[600000] = {600000, 0, "[Name]\u{0020}Lulula\n[B-Day]\u{0020}May\u{0020}19\n[Compatability\u{0020}Rate]\u{0020}87％\n[Height]\u{0020}32m\n[Squad]\u{0020}Soul\u{0020}Destroyers\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}PVP\u{0020}games.", "0", "0", "0", "0", 10000, "dialog_s-1", "dialog_s-1", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}露露啦\n[B-Day]\u{1000}5月19日\n[幻化核心适格率]\u{1000}87％\n[Height]\u{1000}32m\n[部队]\u{1000}魂灭\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}以人为对手的竞技游戏"},
[600001] = {600001, 100, "\u{0020}\u{0020}Captain\u{0020}of\u{0020}\"Soul\u{0020}Destroyers\"\u{0020}and,\u{0020}despite\u{0020}her\u{0020}young\u{0020}age,\u{0020}is\u{0020}surprisingly\u{0020}good\u{0020}at\u{0020}taking\u{0020}care\u{0020}of\u{0020}people.\n\nCompared\u{0020}to\u{0020}other\u{0020}squadmates,\u{0020}she\u{0020}doesn't\u{0020}have\u{0020}much\u{0020}amazing\u{0020}skills,\u{0020}but\u{0020}it's\u{0020}because\u{0020}of\u{0020}her\u{0020}extraordinary\u{0020}patience\u{0020}and\u{0020}empathy\u{0020}that\u{0020}the\u{0020}\"Soul\u{0020}Destroyers\"\u{0020}was\u{0020}formed.\u{0020}Whether\u{0020}it's\u{0020}the\u{0020}gifted\u{0020}Odora\u{0020}or\u{0020}the\u{0020}Kinkura,\u{0020}it's\u{0020}because\u{0020}of\u{0020}her\u{0020}that\u{0020}they're\u{0020}all\u{0020}together.\n\nThe\u{0020}unreliability\u{0020}of\u{0020}her\u{0020}teammates\u{0020}has\u{0020}forced\u{0020}Lulula\u{0020}to\u{0020}take\u{0020}on\u{0020}more\u{0020}in\u{0020}her\u{0020}life\u{0020}taking\u{0020}care\u{0020}of\u{0020}Odora\u{0020}and\u{0020}Kinkura,\u{0020}who\u{0020}are\u{0020}terrible\u{0020}with\u{0020}their\u{0020}own\u{0020}life.\u{0020}Because\u{0020}of\u{0020}her\u{0020}fantastic\u{0020}Kyushu\u{0020}cuisine,\u{0020}she's\u{0020}not\u{0020}only\u{0020}loved\u{0020}by\u{0020}her\u{0020}squadmates,\u{0020}but\u{0020}members\u{0020}from\u{0020}other\u{0020}Kyushu\u{0020}squads\u{0020}also\u{0020}would\u{0020}like\u{0020}to\u{0020}have\u{0020}her.\u{0020}In\u{0020}fact,\u{0020}\"be\u{0020}friends\u{0020}with\u{0020}everyone\"\u{0020}is\u{0020}just\u{0020}what\u{0020}she\u{0020}wants.\n\nShe\u{0020}plays\u{0020}PVP\u{0020}games\u{0020}with\u{0020}her\u{0020}squadmates\u{0020}during\u{0020}their\u{0020}spare\u{0020}time,\u{0020}and\u{0020}she\u{0020}calls\u{0020}herself\u{0020}a\u{0020}master\u{0020}in\u{0020}PVP\u{0020}games.\u{0020}She\u{0020}can\u{0020}win\u{0020}easily\u{0020}no\u{0020}matter\u{0020}what\u{0020}the\u{0020}game\u{0020}is.", "0", "0", "0", "0", 10000, "dialog_s-1", "dialog_s-1", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"魂灭\"的队长，虽然年纪不大却意外地会照顾人。\n\u{1000}\u{1000}相较于另外两位友人，她没有什么惊人的特长，但正因为她那像母亲一样的耐心和同情心，魂灭小队才得以成立。无论是天赋异禀的欧朵啦，亦或是商人出身的金库啦，都是因为她才会聚集在一起。\n\u{1000}\u{1000}在生活上不靠谱的队友让露露啦不得不承担更多的责任，去照顾不能独立生活的欧朵啦与金库啦。能够轻易做出传统九州美食的她，不仅深受欧朵啦、金库啦的喜爱，同时也是九州总部其他队员想要尽可能拉拢的对象。\n\u{1000}\u{1000}\"想和全世界的人成为朋友\"是她的理想，但渐渐地，她走偏到\"成为大家的妈妈\"这个方向上了。\n\u{1000}\u{1000}平常闲暇的时候会和队员打电子游戏，自称是竞技对战游戏的高手，无论是什么类型的对战游戏她都能轻易取胜。"},
[600002] = {600002, 500, "\u{0020}\u{0020}Lulula\u{0020}was\u{0020}raised\u{0020}in\u{0020}the\u{0020}countryside.\u{0020}Although\u{0020}she\u{0020}has\u{0020}a\u{0020}rich\u{0020}family\u{0020}to\u{0020}give\u{0020}her\u{0020}good\u{0020}education,\u{0020}her\u{0020}life\u{0020}was\u{0020}lonely\u{0020}as\u{0020}she\u{0020}grew\u{0020}up;\u{0020}she\u{0020}wants\u{0020}a\u{0020}true\u{0020}friend\u{0020}that\u{0020}she\u{0020}can\u{0020}share\u{0020}her\u{0020}secrets\u{0020}with.\n\nWhen\u{0020}Azure\u{0020}Academy\u{0020}was\u{0020}enrolling,\u{0020}since\u{0020}she\u{0020}wanted\u{0020}to\u{0020}see\u{0020}the\u{0020}world\u{0020}and\u{0020}have\u{0020}more\u{0020}friends,\u{0020}she\u{0020}got\u{0020}permission\u{0020}from\u{0020}her\u{0020}parents\u{0020}to\u{0020}attend\u{0020}the\u{0020}compatability\u{0020}rate\u{0020}test\u{0020}for\u{0020}drivers\u{0020}hosted\u{0020}by\u{0020}Aegis.\u{0020}She\u{0020}was\u{0020}admitted\u{0020}to\u{0020}Azure\u{0020}Academy\u{0020}with\u{0020}a\u{0020}great\u{0020}compatability\u{0020}rate.\n\nLulus\u{0020}treats\u{0020}others\u{0020}with\u{0020}sincerity\u{0020}and\u{0020}innocence,\u{0020}which\u{0020}brings\u{0020}her\u{0020}extremely\u{0020}high\u{0020}popularity:\u{0020}no\u{0020}one\u{0020}would\u{0020}dislike\u{0020}such\u{0020}a\u{0020}girl\u{0020}with\u{0020}enthusiasm\u{0020}and\u{0020}good\u{0020}at\u{0020}cooking.\u{0020}During\u{0020}her\u{0020}school\u{0020}life,\u{0020}she\u{0020}met\u{0020}her\u{0020}good\u{0020}friend:\u{0020}Odora.\u{0020}She\u{0020}invited\u{0020}Odora\u{0020}and\u{0020}Kinkura\u{0020}to\u{0020}start\u{0020}her\u{0020}squad.\n\nThe\u{0020}squad\u{0020}led\u{0020}by\u{0020}Lulula\u{0020}won\u{0020}the\u{0020}tactical\u{0020}competition\u{0020}in\u{0020}Azure\u{0020}Academy\u{0020}3\u{0020}times\u{0020}in\u{0020}a\u{0020}row.\u{0020}This\u{0020}is\u{0020}the\u{0020}proof\u{0020}that\u{0020}her\u{0020}squad\u{0020}is\u{0020}very\u{0020}combat\u{0020}capable\u{0020}under\u{0020}her\u{0020}leadership.\n\nAlthough\u{0020}she\u{0020}led\u{0020}her\u{0020}squad\u{0020}to\u{0020}get\u{0020}such\u{0020}an\u{0020}achievement,\u{0020}she\u{0020}doesn't\u{0020}have\u{0020}any\u{0020}stunning\u{0020}expertise\u{0020}unlike\u{0020}her\u{0020}squadmates.\n\nIf\u{0020}we\u{0020}really\u{0020}have\u{0020}to\u{0020}tell\u{0020}her\u{0020}skills,\u{0020}maybe\u{0020}her\u{0020}100%\u{0020}grade\u{0020}on\u{0020}housekeeping\u{0020}and\u{0020}6\u{0020}times\u{0020}championship\u{0020}in\u{0020}intramural\u{0020}PVP\u{0020}game\u{0020}competition\u{0020}count\u{0020}as\u{0020}that.", "0", "0", "0", "0", 10000, "dialog_s-1", "dialog_s-1", "Lulula's\u{1000}personal\u{1000}story\u{1000}1.", "yd_1", 1, 3, "0", "0", "\u{1000}\u{1000}露露啦是在偏僻的郊外长大的孩子。尽管富裕的家庭让她从小接受了优良的教育，但孤僻的成长环境使她的内心渴望着一个能够与她倾诉心底秘密的朋友。\n\u{1000}\u{1000}在苍穹学院对外招生时，她征求了父母的同意，凭借优异的适格率通过了测试，进入苍穹学院。\n\u{1000}\u{1000}之后为了前往更加广阔的世界，结交更多的朋友，她报名参加了艾吉斯驾驶员适格测试。最终，露露啦凭借优异的适格率通过了测试进入了苍穹学院。\n\u{1000}\u{1000}露露啦天真烂漫真心待人的相处方式使她在学院里有着极高的人气，几乎没有人会讨厌这么一个热情亲切，还擅长料理的女孩。她也在学院生活中结交到了自己新的挚友，欧朵啦。她邀请欧朵啦与金库啦，建立了新的小队。\n\u{1000}\u{1000}围绕着露露啦而成立的三人小队，在苍穹学院的举办的团体战术比赛中取得了三连冠的史诗成绩，这证明了在露露啦的领导下，这支小队拥有着强大的团队战斗力。\n\u{1000}\u{1000}虽说露露啦领导着自己的小队取得了优异的成绩，但她本人并没有特别突出的长处，与她的两名队友比起来，在才能上露露啦要逊色不少。\n\u{1000}\u{1000}如果非要说她有什么才能的话，那么在家政课上取得满分成绩，以及在校内竞技对战游戏个人赛中获得六连冠或许能算作她的才能？\n\u{1000}\u{1000}\"这孩子在战斗上没有过人之处——但是人们总会不自觉成为她的拥趸。\""},
[600003] = {600003, 1000, "\u{0020}\u{0020}\"Soul\u{0020}Destroyer\"\u{0020}led\u{0020}by\u{0020}Lulula\u{0020}has\u{0020}a\u{0020}good\u{0020}performance\u{0020}among\u{0020}other\u{0020}Kyushu\u{0020}squads,\u{0020}which\u{0020}gives\u{0020}their\u{0020}commanders\u{0020}a\u{0020}good\u{0020}impression.\u{0020}They\u{0020}were\u{0020}then\u{0020}appointed\u{0020}to\u{0020}hot\u{0020}spots\u{0020}in\u{0020}different\u{0020}war\u{0020}zones.\n\nOnce\u{0020}in\u{0020}a\u{0020}mission,\u{0020}because\u{0020}of\u{0020}her\u{0020}wrong\u{0020}judgment,\u{0020}the\u{0020}squad\u{0020}went\u{0020}into\u{0020}a\u{0020}critical\u{0020}circumstance.\u{0020}After\u{0020}the\u{0020}incident,\u{0020}Lulula\u{0020}changed\u{0020}her\u{0020}mind\u{0020}on\u{0020}her\u{0020}way\u{0020}of\u{0020}commanding:\u{0020}now\u{0020}she\u{0020}put\u{0020}her\u{0020}squadmates'\u{0020}lives\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\u{0020}This\u{0020}caused\u{0020}a\u{0020}decline\u{0020}in\u{0020}her\u{0020}rating\u{0020}from\u{0020}her\u{0020}commanders,\u{0020}which\u{0020}however,\u{0020}she\u{0020}doesn't\u{0020}care\u{0020}much.\n\nThere\u{0020}is\u{0020}a\u{0020}rumor\u{0020}that\u{0020}she\u{0020}has\u{0020}a\u{0020}good\u{0020}relationship\u{0020}with\u{0020}the\u{0020}captain\u{0020}of\u{0020}Fuurinkazan,\u{0020}Suzuki.\u{0020}But\u{0020}some\u{0020}also\u{0020}saw\u{0020}they\u{0020}were\u{0020}fighting\u{0020}over\u{0020}another\u{0020}member\u{0020}of\u{0020}Fuurinkazan,\u{0020}Shiranui.\u{0020}That\u{0020}was\u{0020}a\u{0020}rare\u{0020}scene\u{0020}in\u{0020}which\u{0020}both\u{0020}of\u{0020}them\u{0020}were\u{0020}angry,\u{0020}which\u{0020}left\u{0020}a\u{0020}deep\u{0020}impression\u{0020}on\u{0020}witnesseses.\n\nSo\u{0020}what\u{0020}happened\u{0020}then?\u{0020}Neither\u{0020}Lulula\u{0020}herself\u{0020}nor\u{0020}other\u{0020}participants\u{0020}want\u{0020}to\u{0020}talk\u{0020}about\u{0020}it.", "0", "0", "0", "0", 10000, "dialog_s-1", "dialog_s-1", "Lulula's\u{1000}personal\u{1000}story\u{1000}2.", "yd_1", 1, 4, "0", "0", "\u{1000}\u{1000}由露露啦作为队长的魂灭小队在艾吉斯九州总部中表现出色，在极短时间内得到了艾吉斯上层的认可，作为一线部队而活跃在各个战区。\n\u{1000}\u{1000}然而，在一次任务中，因为露露啦错误的决断而导致队伍险些陷入绝境，在那之后，露露啦便修改了自己的决策方针，将队员的生命安全作为第一准则。这一做法导致她在上层心中的评价降低不少，但她本人并不介意这一事。\n\u{1000}\u{1000}另外，据传她与\"风林火山\"的队长铃木清风有着不错的私交，但曾经有人目睹过两人因为风林火山的队员\"不知火\"而争吵过。那是两人罕见的同时发怒的场景，因此给在场的人留下了深刻的印象。\n\u{1000}\u{1000}至于当时到底发生了什么事……不管是露露啦，还是其他参与者，似乎都不愿多提的样子。"},
[600004] = {600004, 2000, "\u{0020}\u{0020}Stars\u{0020}are\u{0020}gleaming\u{0020}in\u{0020}the\u{0020}sky.\n\nThe\u{0020}girl\u{0020}stretches\u{0020}her\u{0020}arms\u{0020}towards\u{0020}the\u{0020}sky,\u{0020}it\u{0020}seems\u{0020}like\u{0020}she's\u{0020}so\u{0020}close\u{0020}to\u{0020}the\u{0020}stars.\n\n\"Navigator,\u{0020}I\u{0020}wanna\u{0020}travel\u{0020}around\u{0020}the\u{0020}world\u{0020}with\u{0020}you.\"\n\nShe\u{0020}knows\u{0020}what\u{0020}she\u{0020}wants\u{0020}to\u{0020}do,\u{0020}with\u{0020}her\u{0020}navigator.\n\n\"My\u{0020}dream\u{0020}is\u{0020}to\u{0020}be\u{0020}friends\u{0020}with\u{0020}everyone\u{0020}in\u{0020}this\u{0020}world\",\u{0020}she\u{0020}said,\u{0020}\"Been\u{0020}long\u{0020}since\u{0020}I\u{0020}said\u{0020}that.\"\n\nNostalgia\u{0020}appears\u{0020}on\u{0020}her\u{0020}face,\u{0020}as\u{0020}well\u{0020}as\u{0020}some\u{0020}nervousness.\n\n\"To\u{0020}achieve\u{0020}it,\u{0020}I\u{0020}need\u{0020}Navigator's\u{0020}companion.\"\n\nThis\u{0020}is\u{0020}her\u{0020}confession,\u{0020}her\u{0020}most\u{0020}romantic\u{0020}confession.", "0", "0", "0", "0", 10000, "dialog_s-1", "dialog_s-1", "Lulula's\u{1000}personal\u{1000}story\u{1000}3.", "yd_1", 1, 5, "0", "0", "\u{1000}\u{1000}繁星点缀着夜空，\n\u{1000}\u{1000}女孩在星空下伸开了双手，现在的她离星空幕布仿佛只有那么一丁点距离。\n\u{1000}\u{1000}\"领航，我想和你一起周游世界。\"\n\u{1000}\u{1000}她有想做的事情，\n\u{1000}\u{1000}想和领航一起做的事情，\n\u{1000}\u{1000}\"我的梦想是和世界上的所有人成为朋友——好久没说这句话了。\"\n\u{1000}\u{1000}她的表情有些怀念，还有些忐忑。\n\u{1000}\u{1000}\"为了实现这个目标，我需要领航的陪伴。\"\n\u{1000}\u{1000}这是属于她的，最浪漫的告白。"},
[600100] = {600100, 0, "[Name]\u{0020}Julius\u{0020}Von\u{0020}Nietzsche\n[B-Day]\u{0020}Oct\u{0020}27\n[Compatability\u{0020}Rate]\u{0020}<color=#FF6100>100％</color>\n[Height]\u{0020}38m\n[Squad]\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force\n[Affiliation]\u{0020}Stephanie/Danube\u{0020}Branch\n[Interest]\u{0020}Taking\u{0020}a\u{0020}bath\u{0020}in\u{0020}43°C\u{0020}water", "0", "0", "0", "0", 10001, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}朱利乌斯•冯•尼采\n[B-Day]\u{1000}10月27日\n[幻化核心适格率]\u{1000}<color=#FF6100>100％</color>\n[Height]\u{1000}38m\n[部队]\u{1000}多瑙特别联合部队\u{1000}\u{1000}[隶属]\u{1000}Stephanie/Danube\u{1000}Branch\n[Interest]\u{1000}喜欢在水温43℃的热水中浸泡身体"},
[600101] = {600101, 100, "\u{0020}\u{0020}She\u{0020}is\u{0020}a\u{0020}chivalrous\u{0020}heroine\u{0020}who\u{0020}deems\u{0020}honor\u{0020}as\u{0020}important\u{0020}as\u{0020}her\u{0020}life.\u{0020}No\u{0020}matter\u{0020}in\u{0020}the\u{0020}daily\u{0020}life\u{0020}or\u{0020}in\u{0020}battles,\u{0020}she's\u{0020}the\u{0020}prestigious\u{0020}senior.\n\nUsually,\u{0020}people\u{0020}like\u{0020}her\u{0020}will\u{0020}bring\u{0020}others\u{0020}a\u{0020}sense\u{0020}of\u{0020}distance.\u{0020}That's\u{0020}not\u{0020}true\u{0020}for\u{0020}her:\u{0020}she\u{0020}always\u{0020}uses\u{0020}her\u{0020}warm\u{0020}smile\u{0020}and\u{0020}gentle\u{0020}posture\u{0020}to\u{0020}make\u{0020}people\u{0020}feel\u{0020}relaxed.\n\nOf\u{0020}course,\u{0020}this\u{0020}is\u{0020}not\u{0020}always\u{0020}the\u{0020}case.\u{0020}She\u{0020}can't\u{0020}stand\u{0020}Charlissa,\u{0020}her\u{0020}squadmate,\u{0020}because\u{0020}of\u{0020}the\u{0020}latter's\u{0020}undisciplined\u{0020}nature.\u{0020}Knowing\u{0020}Charlissa\u{0020}is\u{0020}a\u{0020}descendant\u{0020}of\u{0020}a\u{0020}noble\u{0020}just\u{0020}like\u{0020}her,\u{0020}it\u{0020}only\u{0020}deepens\u{0020}her\u{0020}frustration;\u{0020}she\u{0020}simply\u{0020}can't\u{0020}accept\u{0020}such\u{0020}a\u{0020}squadmate.\u{0020}However,\u{0020}she\u{0020}doesn't\u{0020}hate\u{0020}Charlissa,\u{0020}instead\u{0020}she\u{0020}considers\u{0020}Charlissa\u{0020}as\u{0020}her\u{0020}adolescent\u{0020}sister\u{0020}in\u{0020}a\u{0020}rebellious\u{0020}period.\n\nIn\u{0020}her\u{0020}daily\u{0020}life,\u{0020}it's\u{0020}hard\u{0020}to\u{0020}tell\u{0020}her\u{0020}interest\u{0020}other\u{0020}than\u{0020}training.\u{0020}If\u{0020}we\u{0020}really\u{0020}think\u{0020}about\u{0020}it,\u{0020}the\u{0020}only\u{0020}one\u{0020}that\u{0020}counts\u{0020}is\u{0020}\"love\u{0020}to\u{0020}help\u{0020}people\":\u{0020}no\u{0020}matter\u{0020}the\u{0020}training\u{0020}requests\u{0020}from\u{0020}her\u{0020}juniors\u{0020}or\u{0020}help\u{0020}needed\u{0020}by\u{0020}the\u{0020}elderly,\u{0020}she\u{0020}won't\u{0020}reject\u{0020}them.", "0", "0", "0", "0", 10001, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}将荣耀视作生命，秉持着绅士风度的英气少女。无论是在战斗还是在生活中都是令人憧憬的前辈。\n\u{1000}\u{1000}按理来说这样的人都会让人产生距离感，但是恰相反，朱利乌斯总是会用她亲切的笑容和温柔的动作让她身边的人感到毫无压力。\n\u{1000}\u{1000}当然，也有例外，比如和她同属多瑙特别联合部队的查丽莎，朱利乌斯实在无法忍受她那过于随性的言行，特别是得知对方也是贵族后裔后，她更是无法接受自己居然要与这样的家伙为伍。不过她也没有因此而记恨查丽莎，在她眼里查丽莎只不过是自己正处于叛逆期的妹妹罢了。\n\u{1000}\u{1000}平日里似乎很难看出她有什么除了训练之外其他的兴趣爱好。如果非要说的话那大概就只有\"乐于助人\"了吧，无论是来自于后辈的陪练请求还是来自于老人家的搀扶请求，朱利乌斯都不会拒绝。"},
[600102] = {600102, 500, "\u{0020}\u{0020}This\u{0020}is\u{0020}her\u{0020}own\u{0020}decision,\u{0020}not\u{0020}a\u{0020}decision\u{0020}imposed\u{0020}by\u{0020}her\u{0020}family.\n\nJulius's\u{0020}family\u{0020}is\u{0020}a\u{0020}well-known\u{0020}noble\u{0020}in\u{0020}Danube,\u{0020}and\u{0020}also\u{0020}military\u{0020}affiliated\u{0020}in\u{0020}generations.\u{0020}Her\u{0020}parents\u{0020}are\u{0020}excellent\u{0020}commanders\u{0020}and\u{0020}soldiers.\u{0020}As\u{0020}a\u{0020}commonsense,\u{0020}Julius,\u{0020}the\u{0020}first\u{0020}daughter\u{0020}in\u{0020}her\u{0020}family,\u{0020}should\u{0020}be\u{0020}raised\u{0020}like\u{0020}a\u{0020}servicewoman.\n\nHowever,\u{0020}her\u{0020}parents\u{0020}respect\u{0020}their\u{0020}daughter's\u{0020}choices.\u{0020}They\u{0020}don't\u{0020}really\u{0020}care\u{0020}about\u{0020}the\u{0020}honor\u{0020}of\u{0020}a\u{0020}noble,\u{0020}or\u{0020}the\u{0020}honor\u{0020}of\u{0020}a\u{0020}military\u{0020}personnel,\u{0020}but\u{0020}rather\u{0020}the\u{0020}honor\u{0020}of\u{0020}being\u{0020}a\u{0020}gentleman.\n\nBeing\u{0020}raised\u{0020}in\u{0020}such\u{0020}an\u{0020}environment,\u{0020}although\u{0020}her\u{0020}parents\u{0020}never\u{0020}led\u{0020}her,\u{0020}maybe\u{0020}because\u{0020}of\u{0020}the\u{0020}heredity,\u{0020}she\u{0020}was\u{0020}interested\u{0020}in\u{0020}swordsmanship.\u{0020}Her\u{0020}mom\u{0020}was\u{0020}happy\u{0020}about\u{0020}this,\u{0020}and\u{0020}she\u{0020}instructed\u{0020}Julius\u{0020}on\u{0020}swordsmanship\u{0020}by\u{0020}herself.\u{0020}Back\u{0020}then,\u{0020}Julius\u{0020}was\u{0020}simply\u{0020}interested\u{0020}in\u{0020}swordsmanship,\u{0020}she\u{0020}didn't\u{0020}know\u{0020}how\u{0020}she\u{0020}would\u{0020}employ\u{0020}it\u{0020}in\u{0020}the\u{0020}future.\n\n\"My\u{0020}dear\u{0020}daughter,\u{0020}why\u{0020}do\u{0020}you\u{0020}pick\u{0020}up\u{0020}the\u{0020}sword?\u{0020}What\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}be?\"\u{0020}Her\u{0020}father\u{0020}asked\u{0020}her\u{0020}as\u{0020}well.\n\nThe\u{0020}incident\u{0020}that\u{0020}made\u{0020}her\u{0020}decide\u{0020}to\u{0020}take\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}and\u{0020}become\u{0020}an\u{0020}Aegis\u{0020}driver\u{0020}is\u{0020}that\u{0020}her\u{0020}father,\u{0020}that\u{0020}gentle\u{0020}and\u{0020}open-minded\u{0020}man,\u{0020}was\u{0020}killed\u{0020}in\u{0020}action.\u{0020}In\u{0020}many\u{0020}people's\u{0020}common\u{0020}sense:\u{0020}as\u{0020}a\u{0020}serviceman,\u{0020}isn't\u{0020}unable\u{0020}to\u{0020}return\u{0020}from\u{0020}wars\u{0020}acceptable?\u{0020}Isn't\u{0020}that\u{0020}understandable?\n\n\n\n...\n\nNo,\u{0020}she\u{0020}couldn't\u{0020}understand,\u{0020}and\u{0020}she\u{0020}couldn't\u{0020}accept\u{0020}it.\u{0020}She\u{0020}abandoned\u{0020}the\u{0020}courteous\u{0020}behaviors,\u{0020}and\u{0020}neglected\u{0020}other's\u{0020}opposition,\u{0020}went\u{0020}to\u{0020}see\u{0020}her\u{0020}dad\u{0020}as\u{0020}fast\u{0020}as\u{0020}she\u{0020}could.\n\n\"He\u{0020}wasn't\u{0020}killed\u{0020}by\u{0020}Sins,\u{0020}he\u{0020}was\u{0020}hit\u{0020}by\u{0020}a\u{0020}crossbeam\u{0020}when\u{0020}he\u{0020}was\u{0020}saving\u{0020}the\u{0020}civilians.\u{0020}He\u{0020}was\u{0020}successful:\u{0020}those\u{0020}civilians\u{0020}survived.\"\n\nThe\u{0020}man\u{0020}died\u{0020}with\u{0020}the\u{0020}honor\u{0020}of\u{0020}a\u{0020}human\u{0020}and\u{0020}a\u{0020}gentleman.\u{0020}Although\u{0020}Jiulus\u{0020}wasn't\u{0020}there,\u{0020}she\u{0020}heard\u{0020}his\u{0020}voice\u{0020}in\u{0020}her\u{0020}mind.\n\n\"My\u{0020}dear\u{0020}daughter,\u{0020}why\u{0020}do\u{0020}you\u{0020}pick\u{0020}up\u{0020}the\u{0020}sword?\u{0020}What\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}be?\"\n\n...\n\n——\"I\u{0020}want\u{0020}to\u{0020}be\u{0020}like\u{0020}you,\u{0020}to\u{0020}serve\u{0020}and\u{0020}to\u{0020}protect\u{0020}people.\"\n\nShe\u{0020}answered\u{0020}at\u{0020}her\u{0020}dad's\u{0020}funeral.\n\nAfter\u{0020}that,\u{0020}a\u{0020}girl\u{0020}with\u{0020}a\u{0020}claymore\u{0020}joined\u{0020}Danube.", "0", "0", "0", "0", 10001, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}这是她自己决定的，绝非家族强加的意识。\n\u{1000}\u{1000}朱利乌斯的家族是多瑙有名的贵族，同时他们也是多瑙为数不多的军人世家。朱利乌斯的父母都是出色的军官与战士。按照常理来说，在这样的家庭作为长女诞生的朱利乌斯一定会被当做是军人或是战士培养长大。\n\u{1000}\u{1000}朱利乌斯的家族是多瑙有名的贵族，同时他们也是多瑙为数不多的军人世家。朱利乌斯的父母都是出色的军官与战士。按照常理来说，在这样的家庭作为长女诞生的朱利乌斯一定会被当做是军人或是战士培养长大。\n\u{1000}\u{1000}正因此，朱利乌斯的父母一直都非常尊重女儿的选择。他们想要维护的既不是贵族的荣耀，也不是军人的荣耀，而是身为绅士的荣耀。\n\u{1000}\u{1000}就这样，年幼的朱利乌斯便在这样优良的环境中慢慢地成长了起来，虽说父母并没有刻意引导她，但是大概是因为血脉的缘故吧，少女早早就对剑术产生了兴趣，她的母亲也因此非常高兴，开始亲自指导起朱利乌斯的剑术训练。不过那时的她只是将其当做兴趣，至于未来到底要做什么她还不清楚。\n\u{1000}\u{1000}\"我的女儿啊，你为什么会拿起剑，你究竟想成为什么样的人？\"\n\u{1000}\u{1000}——她的父亲也曾这样问过。\n\u{1000}\u{1000}而让她最终决定接受适格测试，成为一名艾吉斯驾驶员的还是因为那件事。\n\u{1000}\u{1000}那位一向温柔明朗的父亲战死了，这是在平常不过的事情了，或者说在常人眼中作为军人，不能从战场上回到家人身边是理所应当的吧，是再合理不过的吧？\n\u{1000}\u{1000}……\n\u{1000}\u{1000}这绝对是不合理的，是无法被朱利乌斯接受的。她选择了遵从自己的内心，选择放声哭泣，选择放弃那些流于表面的矜持，选择不顾他人阻拦，连夜前往父亲身边。\n\u{1000}\u{1000}\"他并不是死于原罪之手，而是为了救助平民而被倒下的房梁砸死的。但是，从某种角度来说他成功了，那户被救助的平民活了下来。\"\n\u{1000}\u{1000}就这样，男人在贯彻了自己作为人类的，作为绅士的荣耀后离开了，虽然没能见到父亲最后一面，但是少女却在那时好像听见了父亲的声音。\n\u{1000}\u{1000}\"朱利乌斯啊，你为什么会拿起剑，你究竟想成为什么样的人？\"\n\u{1000}\u{1000}……\n\u{1000}\u{1000}——\"想要成为像您一样，能为他人提供庇护的人。\"\n\u{1000}\u{1000}在父亲的葬礼上，女孩这样回答道。\n\u{1000}\u{1000}之后，Danube\u{1000}Branch便多了一名挥舞着大剑的少女。"},
[600103] = {600103, 1000, "\u{0020}\u{0020}\"Julius\u{0020}is\u{0020}a\u{0020}little\u{0020}bit\u{0020}stubborn,\u{0020}you\u{0020}should\u{0020}watch\u{0020}her,\u{0020}she\u{0020}can\u{0020}be\u{0020}unreasonably\u{0020}strict\u{0020}about\u{0020}something.\"\u{0020}Before\u{0020}the\u{0020}start\u{0020}of\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force,\u{0020}Stephanie\u{0020}told\u{0020}Navigator.\n\nIndeed,\u{0020}after\u{0020}that\u{0020}incident,\u{0020}it\u{0020}looks\u{0020}like\u{0020}Julius\u{0020}is\u{0020}controlled\u{0020}by\u{0020}something.\u{0020}Perhaps\u{0020}she\u{0020}just\u{0020}wants\u{0020}to\u{0020}keep\u{0020}the\u{0020}honor\u{0020}she\u{0020}inherited\u{0020}from\u{0020}her\u{0020}father.\u{0020}We\u{0020}don't\u{0020}know\u{0020}since\u{0020}which\u{0020}moment,\u{0020}she\u{0020}no\u{0020}longer\u{0020}follow\u{0020}her\u{0020}heart.\u{0020}The\u{0020}reason\u{0020}that\u{0020}made\u{0020}her\u{0020}pick\u{0020}up\u{0020}the\u{0020}sword\u{0020}was\u{0020}forgotten,\u{0020}or\u{0020}abandoned\u{0020}by\u{0020}herself.", "0", "0", "0", "0", 10001, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"朱利乌斯是个稍微有些死脑筋的女孩，你要稍微看着点她，她非常容易钻牛角尖。\"在多瑙特别联合部队成立之前，史蒂芬妮曾经这么嘱托过领航。\n\u{1000}\u{1000}\u{1000}确实如此，在经历了那件事之后，朱利乌斯似乎就被某种东西给束缚住了。她想要维护住的荣耀也许只是从父辈那继承下来的而已，不知从何时起，她已经无法做到听从自己的内心了。而她最初让她举起剑的原因早就被她自己忘记，或者说抛弃了。"},
[600104] = {600104, 2000, "\u{0020}\u{0020}Her\u{0020}body\u{0020}is\u{0020}so\u{0020}giant\u{0020}already.\n\nHer\u{0020}power\u{0020}is\u{0020}unimaginable\u{0020}because\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core.\n\nNow\u{0020}she\u{0020}can\u{0020}raise\u{0020}a\u{0020}building,\u{0020}not\u{0020}to\u{0020}mention\u{0020}a\u{0020}crossbeam.\n\nBut,\u{0020}if\u{0020}that\u{0020}man\u{0020}disappears\u{0020}from\u{0020}her\u{0020}sight,\n\nshe\u{0020}feels\u{0020}restless,\u{0020}still.\n\n\"Why\u{0020}do\u{0020}you\u{0020}pick\u{0020}up\u{0020}the\u{0020}sword?\"\n\nFather's\u{0020}words\u{0020}appear\u{0020}again\u{0020}in\u{0020}her\u{0020}mind.\n\n\"It's\u{0020}because…\"\n\nThe\u{0020}girl\u{0020}looks\u{0020}at\u{0020}her\u{0020}squadmates\u{0020}and\u{0020}that\u{0020}man,\u{0020}replies——\n\n\"I\u{0020}don't\u{0020}have\u{0020}a\u{0020}reason,\u{0020}I'm\u{0020}just\u{0020}following\u{0020}my\u{0020}heart.\"", "0", "0", "0", "0", 10001, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}身体已经变得如此巨大了。\n\u{1000}\u{1000}力气也因为幻化核心的缘故，提升到难以想象的地步。\n\u{1000}\u{1000}现在的她不说是房梁，甚至连高楼都能轻易举起了吧。\n\u{1000}\u{1000}但是，只要那个人从她的视野中消失后，\n\u{1000}\u{1000}少女依然会感到不安……\n\u{1000}\u{1000}\"或者说，你为什么会拿起剑？\"\n\u{1000}\u{1000}父亲的声音再次响起。\n\u{1000}\u{1000}\"我是为了……\"\n\u{1000}\u{1000}看着身后的同伴以及那个人的身影，少女回答道——\n\u{1000}\u{1000}\"我遵从了自己的内心，并没有什么特殊的理由。\""},
[600200] = {600200, 0, "[Name]\u{0020}Hank\n[B-Day]\u{0020}June\u{0020}18\n[Compatability\u{0020}Rate]\u{0020}78％\n[Height]\u{0020}41m\n[Squad]\u{0020}Cavalier\n[Affiliation]\u{0020}Maya\u{0020}Branch\n[Interest]\u{0020}Cigarettes;\u{0020}alcohol;\u{0020}driver", "0", "0", "0", "0", 10002, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}汉克\n[B-Day]\u{1000}6月18日\n[幻化核心适格率]\u{1000}78％\n[Height]\u{1000}41m\n[部队]\u{1000}猎骑\n[隶属]\u{1000}Maya\u{1000}Branch\n[Interest]\u{1000}烟\u{1000}酒\u{1000}驾驶员"},
[600201] = {600201, 100, "\u{0020}\u{0020}She\u{0020}will\u{0020}unexpectedly\u{0020}blurt\u{0020}out\u{0020}vulgar\u{0020}jokes\u{0020}that\u{0020}make\u{0020}people\u{0020}blush.\u{0020}Her\u{0020}single\u{0020}dormitory\u{0020}is\u{0020}piled\u{0020}with\u{0020}empty\u{0020}wine\u{0020}bottles\u{0020}and\u{0020}cigarette\u{0020}butts.\u{0020}People\u{0020}can\u{0020}often\u{0020}see\u{0020}her\u{0020}hammered.\n\n——And,\u{0020}for\u{0020}some\u{0020}reason,\u{0020}she\u{0020}has\u{0020}a\u{0020}blind\u{0020}eye.\n\nIt's\u{0020}hard\u{0020}to\u{0020}imagine\u{0020}that\u{0020}these\u{0020}things\u{0020}happen\u{0020}to\u{0020}a\u{0020}active\u{0020}driver.\u{0020}She\u{0020}is\u{0020}such\u{0020}unique.\n\nIf\u{0020}one\u{0020}can\u{0020}accept\u{0020}some\u{0020}of\u{0020}her\u{0020}bad\u{0020}habits,\u{0020}one\u{0020}will\u{0020}find\u{0020}that\u{0020}she\u{0020}is\u{0020}actually\u{0020}a\u{0020}quite\u{0020}easy-going\u{0020}companion.\u{0020}She\u{0020}is\u{0020}not\u{0020}bound\u{0020}by\u{0020}petty\u{0020}formalities\u{0020}and\u{0020}can\u{0020}have\u{0020}a\u{0020}conversation\u{0020}over\u{0020}any\u{0020}topic.\u{0020}There\u{0020}is\u{0020}always\u{0020}a\u{0020}big\u{0020}smile\u{0020}on\u{0020}her\u{0020}face,\u{0020}making\u{0020}people\u{0020}feel\u{0020}close\u{0020}to\u{0020}her.\n\nAbout\u{0020}her,\u{0020}there\u{0020}is\u{0020}another\u{0020}thing\u{0020}that\u{0020}is\u{0020}concerning.\u{0020}There\u{0020}are\u{0020}some\u{0020}strange\u{0020}gunshot\u{0020}wounds\u{0020}and\u{0020}knife\u{0020}wounds\u{0020}on\u{0020}her\u{0020}back.\u{0020}This\u{0020}is\u{0020}weird\u{0020}for\u{0020}a\u{0020}driver\u{0020}who\u{0020}\"fights\u{0020}with\u{0020}transformation\u{0020}body.\"\n\nObviously,\u{0020}she\u{0020}is\u{0020}not\u{0020}just\u{0020}a\u{0020}driver.", "0", "0", "0", "0", 10002, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}说话时冷不防地会蹦出让人脸红的下流段子；单人宿舍里堆积着空了的酒瓶与燃尽了的烟蒂；人们常常能看见她一身散发着酒气的样子。\n\u{1000}\u{1000}——以及，不知为何瞎了一只的眼睛。\n\u{1000}\u{1000}很难想象这些事情出现在一名正在服役的正规驾驶员身上，但事实的确如此，她便是一个如此奇特的人。\n\u{1000}\u{1000}如果能够容忍并接受她的一些陋习，就会发现她实际上是一位相当好相处的同伴。她不拘小节，能够讨论任何尺度的话题，她的脸上总是挂着豪迈的笑容，让与她相处的人感受不到距离感的存在。\n\u{1000}\u{1000}关于她，还有一点令人在意的地方。她的背上有一些奇怪的枪伤和刀伤，这点对于\"以幻化的巨大躯体作战\"的驾驶员来说是一件奇怪的事。\n\u{1000}\u{1000}显而易见，她的身份不只是驾驶员。"},
[600202] = {600202, 500, "\u{0020}\u{0020}Although\u{0020}Hank's\u{0020}goals\u{0020}have\u{0020}indeed\u{0020}changed,\u{0020}her\u{0020}unrestrained\u{0020}and\u{0020}rather\u{0020}sloppy\u{0020}personality\u{0020}has\u{0020}long\u{0020}been\u{0020}formed\u{0020}and\u{0020}has\u{0020}been\u{0020}carried\u{0020}through\u{0020}to\u{0020}this\u{0020}day.\n\nDue\u{0020}to\u{0020}her\u{0020}outstanding\u{0020}combat\u{0020}and\u{0020}analysis\u{0020}abilities,\u{0020}Hank\u{0020}was\u{0020}once\u{0020}employed\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}Security\u{0020}Department\u{0020}and\u{0020}was\u{0020}active\u{0020}in\u{0020}the\u{0020}shadows\u{0020}as\u{0020}a\u{0020}special\u{0020}operator.\u{0020}With\u{0020}her\u{0020}strength,\u{0020}she\u{0020}easily\u{0020}took\u{0020}out\u{0020}many\u{0020}targets.\u{0020}However,\u{0020}due\u{0020}to\u{0020}her\u{0020}personality,\u{0020}things\u{0020}always\u{0020}ended\u{0020}not\u{0020}neatly\u{0020}enough.\u{0020}She\u{0020}often\u{0020}left\u{0020}a\u{0020}mess\u{0020}for\u{0020}her\u{0020}sister\u{0020}who\u{0020}was\u{0020}also\u{0020}serving\u{0020}in\u{0020}the\u{0020}security\u{0020}department\u{0020}and\u{0020}was\u{0020}her\u{0020}superior.\u{0020}This\u{0020}undoubtedly\u{0020}made\u{0020}the\u{0020}relationship\u{0020}between\u{0020}the\u{0020}two,\u{0020}who\u{0020}had\u{0020}never\u{0020}been\u{0020}very\u{0020}harmonious\u{0020}since\u{0020}childhood,\u{0020}even\u{0020}worse.\n\nJust\u{0020}as\u{0020}her\u{0020}elder\u{0020}sister\u{0020}has\u{0020}always\u{0020}been\u{0020}denying\u{0020}Hank's\u{0020}way\u{0020}of\u{0020}doing\u{0020}things,\u{0020}Hank\u{0020}also\u{0020}doesn't\u{0020}like\u{0020}her\u{0020}bureaucratic\u{0020}jargon\u{0020}that\u{0020}beats\u{0020}around\u{0020}the\u{0020}bush,\u{0020}and\u{0020}secretly\u{0020}guides\u{0020}the\u{0020}situation\u{0020}to\u{0020}a\u{0020}favorable\u{0020}side.\u{0020}When\u{0020}Hank\u{0020}gradually\u{0020}got\u{0020}tired\u{0020}of\u{0020}killing\u{0020}and\u{0020}got\u{0020}tired\u{0020}of\u{0020}doing\u{0020}the\u{0020}dirty\u{0020}work\u{0020}of\u{0020}eliminating\u{0020}dissidents\u{0020}for\u{0020}AEGIS,\u{0020}she\u{0020}naturally\u{0020}got\u{0020}rid\u{0020}of\u{0020}all\u{0020}this.\u{0020}From\u{0020}then\u{0020}on,\u{0020}she\u{0020}parted\u{0020}ways\u{0020}with\u{0020}that\u{0020}sister\u{0020}and\u{0020}never\u{0020}saw\u{0020}each\u{0020}other\u{0020}again.\n\nShe\u{0020}chose\u{0020}a\u{0020}path\u{0020}more\u{0020}suitable\u{0020}for\u{0020}herself\u{0020}-\u{0020}as\u{0020}a\u{0020}freelance\u{0020}mercenary,\u{0020}only\u{0020}taking\u{0020}on\u{0020}commissions\u{0020}that\u{0020}satisfy\u{0020}her\u{0020}and\u{0020}only\u{0020}living\u{0020}the\u{0020}life\u{0020}she\u{0020}wants.\u{0020}Compared\u{0020}to\u{0020}killing,\u{0020}she\u{0020}now\u{0020}prefers\u{0020}protecting\u{0020}things.\u{0020}Anyway,\u{0020}with\u{0020}her\u{0020}outstanding\u{0020}ability,\u{0020}she\u{0020}can\u{0020}also\u{0020}get\u{0020}by\u{0020}well\u{0020}just\u{0020}by\u{0020}taking\u{0020}on\u{0020}high-level\u{0020}security\u{0020}and\u{0020}escort\u{0020}tasks.\n\n——Then,\u{0020}this\u{0020}time,\u{0020}she\u{0020}received\u{0020}a\u{0020}commission\u{0020}from\u{0020}the\u{0020}Cretia\u{0020}family.\n\n\"Our\u{0020}family's\u{0020}children,\u{0020}I\u{0020}entrust\u{0020}them\u{0020}to\u{0020}you.\"", "0", "0", "0", "0", 10002, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}尽管汉克的目标的确有过转变，但她不拘小节甚至可谓散漫的性格早已形成，且贯彻至今。\n\u{1000}\u{1000}由于卓越的作战及分析能力，汉克曾受雇于艾吉斯安全部，作为一名特别行动人员在暗处活跃。她凭借自身实力轻松解决掉不少目标，但碍于那放荡不羁的性格，事情总是结束得不够利落，时常给同在安全部任职、身为其上司的姐姐留下一堆烂摊子，这无疑使得自幼便不太融洽的两人关系更加恶化。\n\u{1000}\u{1000}正如姐姐一直否定着汉克的行事作风，汉克也同样不喜欢她拐弯抹角、闪烁其词，且暗中将情形引向有利一面的官僚话术。当汉克逐渐厌倦杀戮、厌倦了为艾吉斯排除异己的脏活，她便顺理成章摆脱掉了这一切，从此与那位姐姐分道扬镳，再未相见。\n\u{1000}\u{1000}她选择了更加适合自己的道路——作为一名自由佣兵，只接满意的委托，只过自己想过的生活。比起动辄杀戮，她现在更倾向于守护某些事物，反正能力出众的她仅靠接取高级别安保与护送任务也能混得不错。\n\u{1000}\u{1000}然后，这一次，她接到了来自克雷蒂亚家族的委托——\n\u{1000}\u{1000}\"我们家族的孩子，就拜托你了。\""},
[600203] = {600203, 1000, "\u{0020}\u{0020}Having\u{0020}accepted\u{0020}the\u{0020}commission\u{0020}from\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}and\u{0020}passed\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test,\u{0020}Hank,\u{0020}under\u{0020}the\u{0020}arrangement\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Cavalier.\u{0020}Fighting\u{0020}with\u{0020}an\u{0020}gigantified\u{0020}body\u{0020}is\u{0020}a\u{0020}brand-new\u{0020}experience\u{0020}for\u{0020}Hank,\u{0020}and\u{0020}she\u{0020}seems\u{0020}to\u{0020}enjoy\u{0020}the\u{0020}pleasure\u{0020}brought\u{0020}by\u{0020}new\u{0020}things.\n\nWhile\u{0020}indulging\u{0020}in\u{0020}it,\u{0020}she\u{0020}has\u{0020}not\u{0020}forgotten\u{0020}her\u{0020}duty.\u{0020}Concealing\u{0020}her\u{0020}identity,\u{0020}she\u{0020}has\u{0020}always\u{0020}regarded\u{0020}protecting\u{0020}the\u{0020}safety\u{0020}of\u{0020}Alice\u{0020}Cretia\u{0020}and\u{0020}Gin\u{0020}Cretia\u{0020}as\u{0020}her\u{0020}top\u{0020}priority\u{0020}when\u{0020}carrying\u{0020}out\u{0020}the\u{0020}tasks\u{0020}assigned\u{0020}by\u{0020}Aegis.\u{0020}However,\u{0020}during\u{0020}the\u{0020}job,\u{0020}the\u{0020}way\u{0020}the\u{0020}sisters\u{0020}got\u{0020}along\u{0020}touched\u{0020}Hank's\u{0020}memory,\u{0020}which\u{0020}gave\u{0020}Hank\u{0020}reasons\u{0020}other\u{0020}than\u{0020}the\u{0020}task\u{0020}to\u{0020}protect\u{0020}them.\n\nAnother\u{0020}person\u{0020}who\u{0020}caught\u{0020}Hank's\u{0020}attention\u{0020}was\u{0020}Tina\u{0020}Eisen,\u{0020}the\u{0020}maid\u{0020}in\u{0020}the\u{0020}team.\u{0020}Tina's\u{0020}straightforward,\u{0020}strict\u{0020}but\u{0020}fair\u{0020}and\u{0020}impartial\u{0020}way\u{0020}of\u{0020}doing\u{0020}things\u{0020}won\u{0020}Hank's\u{0020}favor,\u{0020}perhaps\u{0020}reminding\u{0020}her\u{0020}of\u{0020}something\u{0020}in\u{0020}the\u{0020}past.", "0", "0", "0", "0", 10002, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}接受了来自克雷蒂亚家族的委托，通过了幻化核心适格率测试的汉克在克雷蒂亚家族的安排下，成为了猎骑小队的一员。以巨大化的身体去战斗，对于汉克来说是一种全新的体验，而她似乎也乐在其中，享受着新事物带来的乐趣。\n\u{1000}\u{1000}她在沉迷之余也没有忘记自己本来的任务，隐瞒自己身份的她在执行艾吉斯下达的任务时一直以保护爱丽丝·克雷蒂亚、静·克雷蒂亚的安全为首任。不过，在保护两姐妹的过程中，两姐妹的相处方式触动了汉克的记忆，这使得汉克有了任务以外的原因去保护她们。\n\u{1000}\u{1000}还有一个人引起了汉克的注意——那便是同队的女仆蒂娜·爱森。蒂娜直率严厉却不失公平公正的行事风格取得了汉克的好感，也许这让她想起了以前的事情。"},
[600204] = {600204, 2000, "\u{0020}\u{0020}Years\u{0020}of\u{0020}wandering\u{0020}as\u{0020}a\u{0020}mercenary\u{0020}have\u{0020}made\u{0020}Hank\u{0020}many\u{0020}friends,\u{0020}or\u{0020}at\u{0020}least\u{0020}people\u{0020}who\u{0020}can\u{0020}call\u{0020}each\u{0020}other\u{0020}friends.\n\nAmong\u{0020}them,\u{0020}there\u{0020}sure\u{0020}are\u{0020}serious\u{0020}people\u{0020}like\u{0020}Tina.\u{0020}The\u{0020}young\u{0020}man\u{0020}in\u{0020}front\u{0020}is\u{0020}no\u{0020}exception.\n\n\"Drink\u{0020}less.\u{0020}I\u{0020}know\u{0020}you\u{0020}won't\u{0020}get\u{0020}drunk\u{0020}and\u{0020}mess\u{0020}up\u{0020}the\u{0020}operation,\u{0020}but\u{0020}excessive\u{0020}drinking\u{0020}is\u{0020}still\u{0020}bad\u{0020}for\u{0020}your\u{0020}health.\"\n\nUnlike\u{0020}other\u{0020}serious\u{0020}and\u{0020}stern\u{0020}people\u{0020}encountered\u{0020}in\u{0020}life,\u{0020}even\u{0020}his\u{0020}preaching\u{0020}words\u{0020}are\u{0020}full\u{0020}of\u{0020}tenderness.\n\n\"--\u{0020}So,\u{0020}will\u{0020}you\u{0020}accompany\u{0020}me\u{0020}to\u{0020}finish\u{0020}this\u{0020}last\u{0020}half\u{0020}bottle?\"\n\nTherefore,\u{0020}just\u{0020}like\u{0020}being\u{0020}intoxicated\u{0020}with\u{0020}alcohol,\u{0020}Hank\u{0020}always\u{0020}greedily\u{0020}craves\u{0020}more\u{0020}from\u{0020}him.\n\n\"Well...\u{0020}Okay.\n\nThe\u{0020}young\u{0020}man\u{0020}nodded.\n\nThus,\u{0020}another\u{0020}feast\u{0020}that\u{0020}doesn't\u{0020}end\u{0020}until\u{0020}everyone\u{0020}is\u{0020}drunk\u{0020}is\u{0020}about\u{0020}to\u{0020}come\u{0020}to\u{0020}a\u{0020}close.", "0", "0", "0", "0", 10002, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}多年浪迹天涯的佣兵生活，让汉克结识了不少朋友，或者至少是能互相称作朋友的人。\n\u{1000}\u{1000}其中自然不乏像蒂娜、姐姐那样一板一眼的家伙，面前的少年亦是如此。\n\u{1000}\u{1000}\"还是少喝点吧，我相信你不会醉酒而搞砸作战，但过量还是会对身体不好。\"\n\u{1000}\u{1000}与生命中遇到的其他正经而严厉之人不同，他的话语即使是说教，其中也饱含温柔。\n\u{1000}\u{1000}\"——那么，你来陪我把最后这半瓶干了？\"\n\u{1000}\u{1000}因此，如同沉醉于酒精一般，汉克总是贪得无厌地向他渴求更多。\n\u{1000}\u{1000}\"唔……没问题。\"\n\u{1000}\u{1000}少年点了点头。\n\u{1000}\u{1000}就这样，又一场不醉不休的宴席即将落下帷幕。"},
[600300] = {600300, 0, "[Name]\u{0020}Morimura\u{0020}Kinosuke\n[B-Day]\u{0020}March\u{0020}11\n[Compatability\u{0020}Rate]\u{0020}85％\n[Height]\u{0020}36m\n[Squad]\u{0020}Fuurinkazan\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}None", "0", "0", "0", "0", 10003, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}森村鬼之介\n[B-Day]\u{1000}3月11日\n[幻化核心适格率]\u{1000}85％\n[Height]\u{1000}36m\n[部队]\u{1000}风林火山\n\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}无"},
[600301] = {600301, 100, "\u{0020}\u{0020}Morimura\u{0020}Kinosuke\u{0020}is\u{0020}the\u{0020}strongest\u{0020}member\u{0020}in\u{0020}solo\u{0020}combat\u{0020}in\u{0020}\"Fuurinkazan\",\u{0020}so\u{0020}she\u{0020}holds\u{0020}the\u{0020}position\u{0020}of\u{0020}fragger\u{0020}and\u{0020}is\u{0020}known\u{0020}as\u{0020}the\u{0020}top\u{0020}one\u{0020}fragger\u{0020}in\u{0020}Kyushu.\n\nBut\u{0020}compared\u{0020}to\u{0020}cooperating\u{0020}with\u{0020}everyone\u{0020}in\u{0020}the\u{0020}team,\u{0020}she\u{0020}still\u{0020}prefers\u{0020}to\u{0020}act\u{0020}alone.\u{0020}On\u{0020}the\u{0020}one\u{0020}hand,\u{0020}it\u{0020}is\u{0020}because\u{0020}her\u{0020}combat\u{0020}style\u{0020}is\u{0020}more\u{0020}suitable\u{0020}for\u{0020}being\u{0020}a\u{0020}roamer\u{0020}in\u{0020}the\u{0020}team.\u{0020}On\u{0020}the\u{0020}other\u{0020}hand,\u{0020}it\u{0020}seems\u{0020}that\u{0020}she\u{0020}is\u{0020}intentionally\u{0020}keeping\u{0020}a\u{0020}distance\u{0020}from\u{0020}the\u{0020}team\u{0020}\"Fuurinkazan\".\u{0020}The\u{0020}reason\u{0020}is\u{0020}that\u{0020}she\u{0020}is\u{0020}originally\u{0020}a\u{0020}\"transfer\u{0020}student\"\u{0020}of\u{0020}Fuurinkazan.\n\nThe\u{0020}\"K46\"\u{0020}team\u{0020}to\u{0020}which\u{0020}Morimura\u{0020}Kinosuke\u{0020}originally\u{0020}belonged\u{0020}was\u{0020}forced\u{0020}to\u{0020}disband\u{0020}due\u{0020}to\u{0020}an\u{0020}accident,\u{0020}and\u{0020}she\u{0020}has\u{0020}been\u{0020}brooding\u{0020}over\u{0020}this\u{0020}matter\u{0020}ever\u{0020}since.\n\n\"Maybe\u{0020}I\u{0020}should\u{0020}not\u{0020}have\u{0020}appeared\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}again\u{0020}at\u{0020}all.\"", "0", "0", "0", "0", 10003, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}森村鬼之介是\"风林火山\"中，单兵作战最强的成员，因此担任了队伍突破手的位置，有着九州第一突破手之称。\n\u{1000}\u{1000}但比起和队伍中的大家配合，她还是更倾向于脱离团体单独行动。一方面是因为她的作战方式更加适合做队伍中的自由人，另一方面则是她本人似乎在有意和\"风林火山\"这支队伍保持距离。而造成这样的原因则是因为她本就是风林火山的\"插班生\"。\n\u{1000}\u{1000}森村鬼之介原本隶属的\"K46\"小队因为一场事故而被迫解散，之后她一直对此事耿耿于怀。\n\u{1000}\u{1000}\"我也许根本就不应该再次出现在战场上。\""},
[600302] = {600302, 500, "\u{0020}\u{0020}Morimura\u{0020}Kinosuke's\u{0020}experience\u{0020}before\u{0020}joining\u{0020}AEGIS\u{0020}was\u{0020}unremarkable.\u{0020}It\u{0020}seems\u{0020}that\u{0020}no\u{0020}one\u{0020}knows\u{0020}why\u{0020}she\u{0020}joined\u{0020}AEGIS.\u{0020}This\u{0020}is\u{0020}not\u{0020}because\u{0020}it\u{0020}is\u{0020}mysterious,\u{0020}but\u{0020}because\u{0020}it's\u{0020}an\u{0020}overly\u{0020}ordinary\u{0020}life\u{0020}that\u{0020}no\u{0020}one's\u{0020}interested.\n\nDuring\u{0020}her\u{0020}academy\u{0020}years,\u{0020}she\u{0020}demonstrated\u{0020}outstanding\u{0020}talent\u{0020}in\u{0020}physical\u{0020}skills\u{0020}and\u{0020}achieved\u{0020}excellent\u{0020}results\u{0020}in\u{0020}simulated\u{0020}battles.\u{0020}After\u{0020}completing\u{0020}her\u{0020}studies,\u{0020}Morimura\u{0020}Kinosuke\u{0020}was\u{0020}assigned\u{0020}to\u{0020}the\u{0020}special\u{0020}operations\u{0020}team\u{0020}\"K46\".\n\nBecause\u{0020}of\u{0020}her\u{0020}outstanding\u{0020}performance\u{0020}during\u{0020}the\u{0020}academy\u{0020}period,\u{0020}Morimura\u{0020}Kinosuke\u{0020}became\u{0020}the\u{0020}captain\u{0020}of\u{0020}\"K46\"\u{0020}and\u{0020}was\u{0020}trusted\u{0020}by\u{0020}her\u{0020}team\u{0020}members.\u{0020}Her\u{0020}status\u{0020}in\u{0020}the\u{0020}hearts\u{0020}of\u{0020}\"K46\"\u{0020}rose\u{0020}along\u{0020}with\u{0020}the\u{0020}increasing\u{0020}number\u{0020}of\u{0020}completed\u{0020}tasks\u{0020}of\u{0020}\"K46\".\n\nHowever,\u{0020}the\u{0020}hidden\u{0020}danger\u{0020}was\u{0020}also\u{0020}planted\u{0020}at\u{0020}this\u{0020}time.\u{0020}If\u{0020}a\u{0020}team\u{0020}only\u{0020}listens\u{0020}to\u{0020}one\u{0020}person's\u{0020}judgment\u{0020}and\u{0020}blindly\u{0020}follows\u{0020}one\u{0020}person,\u{0020}then\u{0020}this\u{0020}team\u{0020}is\u{0020}doomed\u{0020}not\u{0020}to\u{0020}go\u{0020}far.\u{0020}Therefore,\u{0020}looking\u{0020}back\u{0020}now,\u{0020}the\u{0020}downfall\u{0020}of\u{0020}\"K46\"\u{0020}seems\u{0020}inevitable.\n\nDuring\u{0020}an\u{0020}emergency\u{0020}rescue\u{0020}mission,\u{0020}Kyushu\u{0020}Headquarters\u{0020}misestimated\u{0020}the\u{0020}number\u{0020}and\u{0020}intensity\u{0020}of\u{0020}local\u{0020}Sins\u{0020}and\u{0020}only\u{0020}sent\u{0020}several\u{0020}troops\u{0020}for\u{0020}rescue,\u{0020}among\u{0020}which\u{0020}was\u{0020}\"K46\".\u{0020}When\u{0020}arriving\u{0020}at\u{0020}the\u{0020}location,\u{0020}the\u{0020}members\u{0020}of\u{0020}\"K46\"\u{0020}immediately\u{0020}knew\u{0020}that\u{0020}AEGIS\u{0020}had\u{0020}made\u{0020}a\u{0020}mistake.\u{0020}At\u{0020}that\u{0020}time,\u{0020}delaying\u{0020}and\u{0020}waiting\u{0020}for\u{0020}follow-up\u{0020}support\u{0020}was\u{0020}the\u{0020}most\u{0020}conservative\u{0020}approach.\u{0020}However,\u{0020}Morimura\u{0020}Kinosuke\u{0020}thought\u{0020}that\u{0020}\"K46\"\u{0020}alone\u{0020}could\u{0020}solve\u{0020}this\u{0020}crisis.\u{0020}Under\u{0020}Morimura\u{0020}Kinosuke's\u{0020}command,\u{0020}\"K46\"\u{0020}adopted\u{0020}the\u{0020}aggressive\u{0020}tactic\u{0020}of\u{0020}\"subduing\u{0020}Major\u{0020}Sin\u{0020}in\u{0020}Haze\".\n\nHowever,\u{0020}when\u{0020}\"K46\"\u{0020}broke\u{0020}into\u{0020}the\u{0020}center\u{0020}of\u{0020}the\u{0020}mist,\u{0020}the\u{0020}Major\u{0020}Sin\u{0020}they\u{0020}encountered\u{0020}was\u{0020}much\u{0020}stronger\u{0020}than\u{0020}they\u{0020}expected.\u{0020}\"K46\"\u{0020}was\u{0020}almost\u{0020}defeated\u{0020}at\u{0020}the\u{0020}first\u{0020}touch,\u{0020}and\u{0020}only\u{0020}Morimura\u{0020}Kinosuke\u{0020}had\u{0020}a\u{0020}little\u{0020}resistance\u{0020}ability.\u{0020}Eventually,\u{0020}this\u{0020}unfair\u{0020}battle\u{0020}ended\u{0020}with\u{0020}the\u{0020}destruction\u{0020}of\u{0020}\"K46\".\n\nAfter\u{0020}the\u{0020}battle,\u{0020}Morimura\u{0020}Kinosuke,\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}few\u{0020}survivors,\u{0020}survived.\n\nAfter\u{0020}a\u{0020}long\u{0020}convalescence,\u{0020}Morimura\u{0020}Kinosuke\u{0020}returned\u{0020}to\u{0020}AEGIS.\u{0020}At\u{0020}this\u{0020}time,\u{0020}among\u{0020}the\u{0020}original\u{0020}members\u{0020}of\u{0020}\"K46\",\u{0020}only\u{0020}she\u{0020}was\u{0020}able\u{0020}to\u{0020}continue\u{0020}fighting.\u{0020}As\u{0020}a\u{0020}result,\u{0020}the\u{0020}\"K46\"\u{0020}team\u{0020}was\u{0020}disbanded,\u{0020}and\u{0020}Morimura\u{0020}Kinosuke\u{0020}was\u{0020}transferred\u{0020}to\u{0020}the\u{0020}powerful\u{0020}new\u{0020}team\u{0020}\"Fuurinkazan\".", "0", "0", "0", "0", 10003, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}森村鬼之介在加入艾吉斯之前的经历平平无奇，似乎也没什么人知道她是因为什么才加入艾吉斯的——这并非因为神秘，而是太过于普通、正常的人生让人没有探求的欲望。\n\u{1000}\u{1000}她在学院时期展现出优秀的体术天赋，在模拟作战中取得了优秀的成绩。在完成学业后，森村鬼之介被编入执行特种作战的小队\"K46\"中。\n\u{1000}\u{1000}因为学院时期的优异表现，森村鬼之介成为\"K46\"队长的同时，备受同队战友们的信任。她在\"K46\"众人心中的地位，随着\"K46\"不断增加的已完成任务数量水涨船高。\n\u{1000}\u{1000}但，隐患也是在这时候埋下的。一支团队如果只听从一个人的判断，只盲目地追随着一个人，那这支队伍是注定走不远的。所以，\"K46\"的覆灭，现在回过头看，似乎是必然的。\n\u{1000}\u{1000}在一次紧急救援任务时，九州总部错误估计了当地原罪的数量及强度，仅派出了数支部队进行救援，其中就有\"K46\"。当赶到任务地点，\"K46\"的成员们立即便知道艾吉斯犯下了错误。在当时，拖延时间，等待后续支援是最保守的方针，但森村鬼之介却认为光凭\"K46\"就能解决这次的危机。在森村鬼之介的命令下，\"K46\"采取了激进的\"讨伐苍雾中的准罪级原罪\"的战术。\n\u{1000}\u{1000}然而，当\"K46\"闯入苍雾的正中心时，遭遇的准罪级原罪却远比她们料想得要强得多。\"K46\"几乎一触即溃，只有森村鬼之介有些许反抗能力。最终，这场敌我实力悬殊的战斗以\"K46\"的覆灭告终。\n\u{1000}\u{1000}战斗结束后，森村鬼之介作为少数的幸存者之一，活了下来。\n\u{1000}\u{1000}在经过漫长的疗养后，鬼之介重新回到了艾吉斯。此时的原\"K46\"成员仅有她一人能够继续作战，\"K46\"小队因此解散，森村鬼之介被调到了战斗力强大的新人小队\"风林火山\"。"},
[600303] = {600303, 1000, "\u{0020}\u{0020}Morimura\u{0020}Kinosuke\u{0020}has\u{0020}always\u{0020}felt\u{0020}guilty\u{0020}towards\u{0020}the\u{0020}members\u{0020}of\u{0020}\"K46\".\u{0020}She\u{0020}believes\u{0020}that\u{0020}it\u{0020}was\u{0020}precisely\u{0020}her\u{0020}headstrong\u{0020}actions\u{0020}that\u{0020}led\u{0020}the\u{0020}team\u{0020}to\u{0020}destruction.\n\nThis\u{0020}sense\u{0020}of\u{0020}guilt\u{0020}not\u{0020}only\u{0020}makes\u{0020}her\u{0020}hostile\u{0020}to\u{0020}Sins,\u{0020}but\u{0020}also\u{0020}makes\u{0020}it\u{0020}impossible\u{0020}for\u{0020}her\u{0020}to\u{0020}fit\u{0020}in\u{0020}the\u{0020}team.\u{0020}She\u{0020}is\u{0020}afraid\u{0020}of\u{0020}something\u{0020}like\u{0020}last\u{0020}time\u{0020}happening\u{0020}again,\u{0020}so\u{0020}she\u{0020}completely\u{0020}separates\u{0020}herself\u{0020}from\u{0020}the\u{0020}group\u{0020}and\u{0020}becomes\u{0020}a\u{0020}roamer\u{0020}outside\u{0020}the\u{0020}team.\n\nHowever,\u{0020}the\u{0020}kindness\u{0020}from\u{0020}Suzuki\u{0020}Seifung\u{0020}makes\u{0020}her\u{0020}at\u{0020}a\u{0020}loss.\u{0020}Suzuki\u{0020}Seifung\u{0020}thinks\u{0020}that\u{0020}Morimura\u{0020}Kinosuke\u{0020}is\u{0020}a\u{0020}child\u{0020}who\u{0020}can't\u{0020}hide\u{0020}her\u{0020}thoughts\u{0020}-\u{0020}obviously\u{0020}in\u{0020}terms\u{0020}of\u{0020}age,\u{0020}the\u{0020}latter\u{0020}is\u{0020}more\u{0020}like\u{0020}a\u{0020}child.\n\nNot\u{0020}only\u{0020}Suzuki\u{0020}Seifung,\u{0020}but\u{0020}the\u{0020}rest\u{0020}of\u{0020}the\u{0020}people\u{0020}in\u{0020}Fuurinkazan\u{0020}seem\u{0020}to\u{0020}be\u{0020}trying\u{0020}to\u{0020}accept\u{0020}her.\u{0020}This\u{0020}\"kindness\"\u{0020}freaks\u{0020}Morimura\u{0020}Kinosuke\u{0020}out.\n\n\"It\u{0020}would\u{0020}be\u{0020}fine\u{0020}if\u{0020}you\u{0020}just\u{0020}leave\u{0020}me\u{0020}alone.\u{0020}That\u{0020}way,\u{0020}that\u{0020}kind\u{0020}of\u{0020}tragedy\u{0020}won't\u{0020}happen\u{0020}again.\"", "0", "0", "0", "0", 10003, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}森村鬼之介的心中，一直有着对\"K46\"成员的愧疚。她认为正是因为当时自己的一意孤行让队伍走向了毁灭。\n\u{1000}\u{1000}这样的愧疚感不仅让她仇视原罪，更加让她变得无法融入到集体中。她恐惧着像上次那样的事情出现，于是将自己彻底与集体划分开，成为了一个游离在队伍之外的自由人。\n\u{1000}\u{1000}然而，来自铃木清风的善意让她无所适从。铃木清风认为，森村鬼之介是一个藏不住心思的小孩子——明明从年龄上说，后者才更像个孩子。\n\u{1000}\u{1000}不只是铃木清风，风林火山的其余人似乎都在试图将她接纳进来，这种\"善意\"让森村鬼之介感到恐惧。\n\u{1000}\u{1000}\"明明不用管我就好了——让我一个人就好了，这样一来，就不会再发生那种悲剧了。\""},
[600304] = {600304, 2000, "\u{0020}\u{0020}Time\u{0020}always\u{0020}moves\u{0020}forward.\n\nThe\u{0020}death\u{0020}is\u{0020}inevitable，\n\nBut\u{0020}——\n\n\"They\u{0020}shouldn't\u{0020}have\u{0020}died\u{0020}like\u{0020}that.\"\n\n\"They\u{0020}should\u{0020}have\u{0020}ended\u{0020}better.\"\n\nThe\u{0020}Shura\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}Morimura\u{0020}Kinosuke\u{0020}whispered\u{0020}like\u{0020}an\u{0020}ordinary\u{0020}girl\u{0020},\n\npouring\u{0020}out\u{0020}her\u{0020}heart\u{0020}to\u{0020}Navigator\u{0020}held\u{0020}in\u{0020}her\u{0020}palm.\n\n\"Navigator,\u{0020}I'm\u{0020}scared.\u{0020}I'm\u{0020}afraid\u{0020}Captain\u{0020}Suzuki\u{0020}will\u{0020}also\u{0020}meet\u{0020}her\u{0020}doom\u{0020}like\u{0020}them.\"\n\n\"Navigator,\u{0020}please\u{0020}protect\u{0020}Suzuki\u{0020}and\u{0020}others...\u{0020}Please...\u{0020}\"", "0", "0", "0", "0", 10003, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}时间总会向前推移，\n\u{1000}\u{1000}人的死亡无可避免，\n\u{1000}\u{1000}但是——\n\u{1000}\u{1000}\"她们，不应该那样死去的。\"\n\u{1000}\u{1000}\"她们，明明应该有更好的结局才对。\"\n\u{1000}\u{1000}战场上的修罗，森村鬼之介像个普通的女孩般低语着，\n\u{1000}\u{1000}向着被她捧在手心里，和她的体型比起来微不足道的领航倾诉着。\n\u{1000}\u{1000}\"领航，我很害怕，我害怕铃木队长也会像她们一样走向破灭。\"\n\u{1000}\u{1000}\"领航，请保护铃木她们……拜托你了……\""},
[600400] = {600400, 0, "[Name]\u{0020}D-b2\n[Birthday]\u{0020}10/13\n[Transformation\u{0020}Core\u{0020}Compatibility\u{0020}Rate]\u{0020}92%\n[Gigantification\u{0020}Height]\u{0020}50m\n[Unit]\u{0020}Specter\n[Branch]\u{0020}Maya\u{0020}Branch\n[Likes]\u{0020}Social\u{0020}interaction", "0", "0", "0", "0", 10004, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[600401] = {600401, 100, "Record\u{0020}I\n\n\"So\u{0020}there's\u{0020}really\u{0020}no\u{0020}Driver\u{0020}inside...?\"\u{0020}is\u{0020}most\u{0020}people's\u{0020}reaction\u{0020}upon\u{0020}first\u{0020}seeing\u{0020}D-b2.\n\nIndeed,\u{0020}there\u{0020}is\u{0020}no\u{0020}driver\u{0020}inside\u{0020}at\u{0020}all.\u{0020}Few\u{0020}humans\u{0020}are\u{0020}capable\u{0020}of\u{0020}manually\u{0020}controlling\u{0020}such\u{0020}a\u{0020}machine;\u{0020}only\u{0020}you,\u{0020}as\u{0020}a\u{0020}Synesthete.\u{0020}Usually\u{0020}she'll\u{0020}use\u{0020}preset\u{0020}programs,\u{0020}or\u{0020}just\u{0020}move\u{0020}with\u{0020}the\u{0020}power\u{0020}of\u{0020}her\u{0020}will.\n\nHer\u{0020}rather\u{0020}mechanical-sounding\u{0020}name\u{0020}is\u{0020}due\u{0020}to\u{0020}the\u{0020}fact\u{0020}she's\u{0020}a\u{0020}mass-production\u{0020}model.\u{0020}That's\u{0020}not\u{0020}to\u{0020}say\u{0020}it's\u{0020}a\u{0020}name\u{0020}entirely\u{0020}without\u{0020}meaning,\u{0020}however.\u{0020}Records\u{0020}indicate\u{0020}that\u{0020}\"D\"\u{0020}is\u{0020}the\u{0020}initial\u{0020}of\u{0020}the\u{0020}one\u{0020}who\u{0020}gave\u{0020}D-b2\u{0020}her\u{0020}personality.\u{0020}Regretfully,\u{0020}however,\u{0020}she\u{0020}died\u{0020}from\u{0020}an\u{0020}illness\u{0020}long\u{0020}before\u{0020}D-b2's\u{0020}conception...", "0", "0", "0", "0", 10004, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[600402] = {600402, 500, "Record\u{0020}II\n\n\"Let's\u{0020}give\u{0020}Simulant\u{0020}Persona\u{0020}a\u{0020}try.\"\n\nIt\u{0020}was\u{0020}an\u{0020}ordinary\u{0020}afternoon,\u{0020}like\u{0020}any\u{0020}other.\u{0020}As\u{0020}usual,\u{0020}the\u{0020}Doctor\u{0020}intended\u{0020}to\u{0020}impart\u{0020}upon\u{0020}me\u{0020}some\u{0020}more\u{0020}knowledge\u{0020}of\u{0020}the\u{0020}world\u{0020}around\u{0020}us.\n\n\"...You\u{0020}forgot\u{0020}your\u{0020}notes,\u{0020}again?\"\n\n\"It's\u{0020}alright,\u{0020}I've\u{0020}kept\u{0020}mental\u{0020}notes.\"\n\n\"Right...\u{0020}You\u{0020}haven't\u{0020}changed\u{0020}a\u{0020}bit,\u{0020}have\u{0020}you.\"\n\nDoctor\u{0020}could\u{0020}only\u{0020}let\u{0020}out\u{0020}a\u{0020}laugh.\n\n\"Well,\u{0020}note\u{0020}this\u{0020}down\u{0020}in\u{0020}whatever\u{0020}way\u{0020}works\u{0020}best\u{0020}for\u{0020}you.\u{0020}In\u{0020}time,\u{0020}you\u{0020}may\u{0020}well\u{0020}cross\u{0020}paths\u{0020}with\u{0020}some\u{0020}of\u{0020}the\u{0020}figures\u{0020}I'll\u{0020}tell\u{0020}you\u{0020}of\u{0020}today...\"\n\nSimulant\u{0020}Persona:\u{0020}a\u{0020}technology\u{0020}devised\u{0020}to\u{0020}copy\u{0020}the\u{0020}personality\u{0020}of\u{0020}a\u{0020}living\u{0020}subject\u{0020}into\u{0020}code\u{0020}form.\u{0020}With\u{0020}this\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}scientists\u{0020}created\u{0020}chips\u{0020}that\u{0020}could\u{0020}operate\u{0020}Transformation\u{0020}Cores\u{0020}in\u{0020}place\u{0020}of\u{0020}a\u{0020}Driver.\u{0020}Models\u{0020}in\u{0020}a\u{0020}line\u{0020}tend\u{0020}to\u{0020}use\u{0020}the\u{0020}same\u{0020}chip,\u{0020}and\u{0020}so\u{0020}these\u{0020}chips\u{0020}were\u{0020}designed\u{0020}from\u{0020}the\u{0020}same\u{0020}parent.\n\nA\u{0020}living\u{0020}subject\u{0020}whose\u{0020}personality\u{0020}would\u{0020}be\u{0020}copied\u{0020}into\u{0020}the\u{0020}chips,\u{0020}the\u{0020}machines.\u{0020}However,\u{0020}only\u{0020}their\u{0020}persona\u{0020}and\u{0020}cognition—not\u{0020}their\u{0020}memories—are\u{0020}copied\u{0020}over.\u{0020}This\u{0020}meant\u{0020}that\u{0020}Simulant\u{0020}Persona-chip\u{0020}machines\u{0020}could\u{0020}not\u{0020}be\u{0020}considered\u{0020}human,\u{0020}and\u{0020}hence\u{0020}could\u{0020}be\u{0020}sent\u{0020}into\u{0020}battle\u{0020}without\u{0020}any\u{0020}legal\u{0020}or\u{0020}ethical\u{0020}issues.\n\nHowever,\u{0020}what\u{0020}the\u{0020}Transformation\u{0020}Cores\u{0020}yearned\u{0020}for,\u{0020}what\u{0020}Nimbus\u{0020}needed,\u{0020}was\u{0020}more\u{0020}than\u{0020}a\u{0020}mere\u{0020}persona.\u{0020}They\u{0020}needed\u{0020}a\u{0020}compatible,\u{0020}complete,\u{0020}human\u{0020}spirit.\u{0020}While\u{0020}the\u{0020}D\u{0020}line\u{0020}models\u{0020}possessed\u{0020}great\u{0020}firepower,\u{0020}they\u{0020}failed\u{0020}to\u{0020}fully\u{0020}utilize\u{0020}their\u{0020}Transformation\u{0020}Cores'\u{0020}potential\u{0020}and\u{0020}were\u{0020}also\u{0020}at\u{0020}risk\u{0020}of\u{0020}system\u{0020}crashes.\n\nThis,\u{0020}and\u{0020}their\u{0020}substantial\u{0020}production\u{0020}costs,\u{0020}meant\u{0020}the\u{0020}project\u{0020}was\u{0020}soon\u{0020}abandoned\u{0020}by\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}and\u{0020}Kyushu\u{0020}Headquarters\u{0020}entirely.\u{0020}Yet\u{0020}they\u{0020}kept\u{0020}the\u{0020}Simulant\u{0020}Persona\u{0020}chips.\u{0020}It\u{0020}wasn't\u{0020}long\u{0020}before\u{0020}Mayan\u{0020}researchers\u{0020}built\u{0020}upon\u{0020}Simulant\u{0020}Persona\u{0020}technology,\u{0020}working\u{0020}to\u{0020}make\u{0020}them\u{0020}a\u{0020}complete\u{0020}\"soul\"\u{0020}with\u{0020}one\u{0020}final\u{0020}piece\u{0020}of\u{0020}the\u{0020}puzzle:\u{0020}memories.\u{0020}And\u{0020}so,\u{0020}a\u{0020}new\u{0020}kind\u{0020}of\u{0020}chip\u{0020}was\u{0020}created—the\u{0020}Secondary\u{0020}Persona.", "0", "0", "0", "0", 10004, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[600403] = {600403, 1000, "Record\u{0020}III\n\nThe\u{0020}Specter\u{0020}incident...\u{0020}A\u{0020}terrible\u{0020}accident,\u{0020}or\u{0020}a\u{0020}premeditated\u{0020}attack?\u{0020}Machines\u{0020}equipped\u{0020}with\u{0020}Secondary\u{0020}Persona\u{0020}chips\u{0020}were\u{0020}revealed\u{0020}at\u{0020}a\u{0020}conference,\u{0020}deemed\u{0020}the\u{0020}next\u{0020}step\u{0020}after\u{0020}Simulant\u{0020}Persona.\u{0020}But\u{0020}they\u{0020}ran\u{0020}amok,\u{0020}taking\u{0020}over\u{0020}a\u{0020}thousand\u{0020}lives.\n\nTo\u{0020}this\u{0020}day,\u{0020}exactly\u{0020}what\u{0020}happened\u{0020}is\u{0020}still\u{0020}not\u{0020}known;\u{0020}but\u{0020}it\u{0020}left\u{0020}a\u{0020}lasting\u{0020}impact.\u{0020}All\u{0020}machines\u{0020}with\u{0020}Secondary\u{0020}Persona\u{0020}chips\u{0020}were\u{0020}to\u{0020}be\u{0020}decommissioned\u{0020}and\u{0020}destroyed.\u{0020}Even\u{0020}those\u{0020}with\u{0020}Simulant\u{0020}Persona\u{0020}chips\u{0020}were\u{0020}also\u{0020}caught\u{0020}in\u{0020}the\u{0020}sweeping\u{0020}order\u{0020}from\u{0020}headquarters,\u{0020}despite\u{0020}not\u{0020}having\u{0020}shown\u{0020}any\u{0020}issues.\n\nThey\u{0020}were\u{0020}left\u{0020}to\u{0020}sit\u{0020}in\u{0020}the\u{0020}freezing\u{0020}warehouses,\u{0020}sharing\u{0020}the\u{0020}blame\u{0020}in\u{0020}a\u{0020}heavy\u{0020}silence.\u{0020}For\u{0020}they\u{0020}were\u{0020}designed\u{0020}with\u{0020}emotions,\u{0020}and\u{0020}even\u{0020}the\u{0020}basis\u{0020}of\u{0020}what\u{0020}we\u{0020}would\u{0020}call\u{0020}memory.\u{0020}This\u{0020}blame\u{0020}and\u{0020}guilt\u{0020}only\u{0020}weighed\u{0020}heavier\u{0020}upon\u{0020}them\u{0020}as\u{0020}years\u{0020}passed.\u{0020}More\u{0020}and\u{0020}more\u{0020}D\u{0020}models\u{0020}took\u{0020}their\u{0020}own\u{0020}lives,\u{0020}in\u{0020}a\u{0020}way:\u{0020}formatting\u{0020}their\u{0020}own\u{0020}chips.\n\nTo\u{0020}ensure\u{0020}the\u{0020}matter\u{0020}would\u{0020}never\u{0020}be\u{0020}truly\u{0020}forgotten,\u{0020}they\u{0020}had\u{0020}left\u{0020}behind\u{0020}a\u{0020}special\u{0020}machine\u{0020}to\u{0020}act\u{0020}as\u{0020}a\u{0020}vector,\u{0020}possessing\u{0020}data\u{0020}on\u{0020}the\u{0020}incident.\u{0020}That\u{0020}vector\u{0020}is\u{0020}D-b2...\n\nGiven\u{0020}your\u{0020}powers\u{0020}of\u{0020}Synesthesia,\u{0020}I'm\u{0020}certain\u{0020}you're\u{0020}capable\u{0020}of\u{0020}wielding\u{0020}their\u{0020}power\u{0020}and\u{0020}preventing\u{0020}such\u{0020}a\u{0020}tragic\u{0020}chapter\u{0020}of\u{0020}history\u{0020}from\u{0020}repeating\u{0020}itself.\n\nRegardless\u{0020}of\u{0020}whether\u{0020}you\u{0020}still\u{0020}recall\u{0020}what\u{0020}she's\u{0020}been\u{0020}through...\u{0020}You\u{0020}must\u{0020}face\u{0020}the\u{0020}reality\u{0020}that\u{0020}D-b2,\u{0020}as\u{0020}she\u{0020}stands\u{0020}before\u{0020}us\u{0020}now,\u{0020}is\u{0020}nothing\u{0020}more\u{0020}than\u{0020}those\u{0020}machines'\u{0020}hopes\u{0020}and\u{0020}wishes\u{0020}in\u{0020}physical\u{0020}form.\u{0020}The\u{0020}last\u{0020}warmth\u{0020}they\u{0020}had\u{0020}in\u{0020}those\u{0020}cold,\u{0020}silent\u{0020}warehouses.", "0", "0", "0", "0", 10004, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[600404] = {600404, 2000, "\u{0020}\u{0020}Lichen\u{0020}and\u{0020}moss\u{0020}covered\u{0020}her\u{0020}body.\n\nSmall\u{0020}pools\u{0020}of\u{0020}water\u{0020}left\u{0020}by\u{0020}the\u{0020}rain\u{0020}had\u{0020}become\u{0020}a\u{0020}haven\u{0020}for\u{0020}small\u{0020}animals\u{0020}and\u{0020}local\u{0020}wildlife.\n\nShe\u{0020}was\u{0020}now\u{0020}little\u{0020}more\u{0020}than\u{0020}an\u{0020}empty\u{0020}shell,\n\nthe\u{0020}remnants\u{0020}of\u{0020}her\u{0020}soul\u{0020}all\u{0020}but\u{0020}faded\u{0020}away.\n\nYet\u{0020}those\u{0020}she\u{0020}had\u{0020}spent\u{0020}her\u{0020}life\u{0020}protecting\n\nhad\u{0020}vowed\u{0020}to\u{0020}never\u{0020}let\u{0020}her,\u{0020}a\u{0020}hero\u{0020}to\u{0020}them\u{0020}all,\u{0020}rest\u{0020}here\u{0020}alone.\n\nShe\u{0020}hoped\u{0020}that\u{0020}the\u{0020}day\u{0020}would\u{0020}come\n\nthat\u{0020}the\u{0020}flowers\u{0020}laid\u{0020}down\u{0020}beside\u{0020}her\u{0020}would\u{0020}bloom\u{0020}alongside\u{0020}her\u{0020}soul,\u{0020}brightly\u{0020}and\u{0020}full\u{0020}of\u{0020}life.", "0", "0", "0", "0", 10004, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[600500] = {600500, 0, "[Name]\u{0020}Hualian\n[B-Day]\u{0020}Feb\u{0020}14\n[Compatability\u{0020}Rate]\u{0020}76％\n[Height]\u{0020}33m\n[Squad]\u{0020}Tianhua\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Martial\u{0020}arts\u{0020}novels;\u{0020}Role-playing\u{0020}", "0", "0", "0", "0", 10005, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}华恋\n[B-Day]\u{1000}2月14日\n[幻化核心适格率]\u{1000}76％\n[Height]\u{1000}29m\n[部队]\u{1000}天华阁\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}武侠小说\u{1000}角色扮演"},
[600501] = {600501, 100, "\u{0020}\u{0020}The\u{0020}vigorous\u{0020}and\u{0020}lively\u{0020}martial\u{0020}arts\u{0020}girl.\n\nCompared\u{0020}with\u{0020}her\u{0020}sister\u{0020}Huameng\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}martial\u{0020}arts\u{0020}practice,\u{0020}her\u{0020}personality\u{0020}is\u{0020}more\u{0020}extroverted.\u{0020}Whether\u{0020}it\u{0020}is\u{0020}the\u{0020}communication\u{0020}within\u{0020}the\u{0020}team\u{0020}or\u{0020}between\u{0020}Tianhua\u{0020}Pavilion\u{0020}and\u{0020}the\u{0020}outside\u{0020}world,\u{0020}she\u{0020}plays\u{0020}an\u{0020}important\u{0020}hub\u{0020}role.\u{0020}Apart\u{0020}from\u{0020}personality\u{0020}reasons,\u{0020}it\u{0020}is\u{0020}also\u{0020}related\u{0020}to\u{0020}her\u{0020}sister's\u{0020}constant\u{0020}addiction\u{0020}to\u{0020}practice\u{0020}and\u{0020}her\u{0020}captain's\u{0020}poor\u{0020}communication\u{0020}skills.\n\nHowever,\u{0020}this\u{0020}doesn't\u{0020}mean\u{0020}she\u{0020}is\u{0020}a\u{0020}normal\u{0020}person.\u{0020}Although\u{0020}she\u{0020}is\u{0020}not\u{0020}a\u{0020}complete\u{0020}martial\u{0020}arts\u{0020}enthusiast\u{0020}like\u{0020}her\u{0020}sister,\u{0020}her\u{0020}understanding\u{0020}of\u{0020}\"how\u{0020}to\u{0020}share\u{0020}emotions\u{0020}with\u{0020}others\"\u{0020}also\u{0020}deviates\u{0020}from\u{0020}that\u{0020}of\u{0020}ordinary\u{0020}people.\u{0020}She\u{0020}often\u{0020}uses\u{0020}the\u{0020}excuses\u{0020}of\u{0020}\"communicating\u{0020}with\u{0020}combat\"\u{0020}to\u{0020}have\u{0020}spars\u{0020}with\u{0020}people\u{0020}everywhere\u{0020}in\u{0020}Kyushu\u{0020}Headquarters,\u{0020}causing\u{0020}trouble\u{0020}among\u{0020}some\u{0020}people.\n\nThe\u{0020}reason\u{0020}why\u{0020}she\u{0020}acts\u{0020}like\u{0020}this\u{0020}is\u{0020}related\u{0020}to\u{0020}her\u{0020}childhood\u{0020}experiences.\u{0020}She\u{0020}seems\u{0020}to\u{0020}have\u{0020}been\u{0020}influenced\u{0020}by\u{0020}some\u{0020}novels\u{0020}and\u{0020}believes\u{0020}that\u{0020}communicating\u{0020}with\u{0020}combat\u{0020}is\u{0020}the\u{0020}most\u{0020}romantic\u{0020}behavior.\n\nWhen\u{0020}she\u{0020}was\u{0020}still\u{0020}young,\u{0020}she\u{0020}was\u{0020}looking\u{0020}forward\u{0020}to\u{0020}meeting\u{0020}the\u{0020}predestined\u{0020}one\u{0020}-\u{0020}\"If\u{0020}it's\u{0020}my\u{0020}'destined\u{0020}one',\u{0020}they\u{0020}will\u{0020}surely\u{0020}be\u{0020}able\u{0020}to\u{0020}withstand\u{0020}my\u{0020}full\u{0020}kick.\"\u{0020}", "0", "0", "0", "0", 10005, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}以\"小生\"自称，元气活泼的武术少女。\n\u{1000}\u{1000}比起沉迷在武术修行中的姐姐华梦，她的性格要更加外向一些。无论是队内的内部交涉，亦或是天华阁与外界的交流，她都扮演着重要的枢纽角色。除去性格原因，这与她的姐姐一直沉迷修行，她的队长不善交流也有直接的关系。\n\u{1000}\u{1000}……尽管如此，也不能说她是一个正常人。虽然她并不像姐姐那样是一个彻头彻尾的武术脑，但她对于\"如何与人交流情感\"的理解也与常人有所偏差。她常常会用\"以拳交心\"的理由，在九州总部四处与人进行切磋，引起一部分人的不满。\n\u{1000}\u{1000}她的认知方式之所以如此奇特，与她的童年经历有关。她似乎受到了一些娱乐读物的影响，认为以拳交心是最浪漫的行为。\n\u{1000}\u{1000}在她还小的时候，她就盼望着能与命定之人相遇——\"是小生的‘命运之人’的话，就一定能接下小生的全力一脚吧。\""},
[600502] = {600502, 500, "\u{0020}\u{0020}Before\u{0020}going\u{0020}to\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters,\u{0020}Hualian\u{0020}and\u{0020}her\u{0020}elder\u{0020}sister\u{0020}Huameng\u{0020}lived\u{0020}a\u{0020}secluded\u{0020}life\u{0020}in\u{0020}the\u{0020}deep\u{0020}mountains.\u{0020}They\u{0020}studied\u{0020}and\u{0020}read\u{0020}during\u{0020}the\u{0020}day\u{0020}and\u{0020}practiced\u{0020}at\u{0020}night.\n\nHualian's\u{0020}only\u{0020}way\u{0020}to\u{0020}communicate\u{0020}with\u{0020}the\u{0020}outside\u{0020}world\u{0020}was\u{0020}through\u{0020}a\u{0020}monthly\u{0020}grocery\u{0020}shopping.\u{0020}Once\u{0020}she\u{0020}stumbled\u{0020}onto\u{0020}a\u{0020}brand\u{0020}new\u{0020}world\u{0020}with\u{0020}a\u{0020}novel.\u{0020}It\u{0020}was\u{0020}a\u{0020}world\u{0020}that\u{0020}was\u{0020}filled\u{0020}with\u{0020}enmity\u{0020}and\u{0020}righteousness.\u{0020}Although\u{0020}it\u{0020}was\u{0020}not\u{0020}the\u{0020}real\u{0020}world,\u{0020}she\u{0020}yearned\u{0020}for\u{0020}the\u{0020}outside\u{0020}nonetheless...\u{0020}Her\u{0020}wrong\u{0020}perception\u{0020}of\u{0020}\"common\u{0020}sense\"\u{0020}was\u{0020}also\u{0020}blamed\u{0020}on\u{0020}these\u{0020}novels.\n\nShe\u{0020}was\u{0020}not\u{0020}as\u{0020}addicted\u{0020}to\u{0020}cultivation\u{0020}as\u{0020}her\u{0020}sister.\u{0020}After\u{0020}being\u{0020}influenced\u{0020}by\u{0020}martial\u{0020}arts\u{0020}novels,\u{0020}she\u{0020}began\u{0020}to\u{0020}be\u{0020}passionate\u{0020}about\u{0020}sparring\u{0020}with\u{0020}others.\u{0020}Unfortunately,\u{0020}in\u{0020}the\u{0020}small\u{0020}village,\u{0020}there\u{0020}were\u{0020}few\u{0020}people\u{0020}who\u{0020}could\u{0020}practice\u{0020}with\u{0020}her,\u{0020}so\u{0020}her\u{0020}only\u{0020}opponent\u{0020}left\u{0020}was\u{0020}her\u{0020}sister\u{0020}who\u{0020}accompanied\u{0020}her\u{0020}in\u{0020}cultivation.\n\nFelt\u{0020}bored\u{0020}with\u{0020}life\u{0020}in\u{0020}the\u{0020}mountains,\u{0020}she\u{0020}once\u{0020}sneaked\u{0020}out\u{0020}alone.\u{0020}After\u{0020}experiencing\u{0020}an\u{0020}unknown\u{0020}adventure,\u{0020}Hualian\u{0020}was\u{0020}finally\u{0020}sent\u{0020}back\u{0020}to\u{0020}the\u{0020}mountains\u{0020}by\u{0020}the\u{0020}officers\u{0020}handling\u{0020}kidnapping\u{0020}cases.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}many\u{0020}parents\u{0020}came\u{0020}to\u{0020}deliver\u{0020}a\u{0020}lot\u{0020}of\u{0020}condolences\u{0020}and\u{0020}banners,\u{0020}and\u{0020}some\u{0020}rich\u{0020}people\u{0020}even\u{0020}allocated\u{0020}funds\u{0020}to\u{0020}build\u{0020}a\u{0020}library\u{0020}in\u{0020}the\u{0020}village\u{0020}and\u{0020}bring\u{0020}books\u{0020}to\u{0020}the\u{0020}village\u{0020}every\u{0020}year.\n\nAfter\u{0020}that,\u{0020}Hualian\u{0020}spent\u{0020}all\u{0020}her\u{0020}days\u{0020}either\u{0020}practicing\u{0020}martial\u{0020}arts\u{0020}or\u{0020}going\u{0020}to\u{0020}the\u{0020}library.\n\nThe\u{0020}colorful\u{0020}stories\u{0020}formed\u{0020}a\u{0020}sharp\u{0020}contrast\u{0020}to\u{0020}her\u{0020}dull\u{0020}life,\u{0020}and\u{0020}her\u{0020}desire\u{0020}to\u{0020}fight\u{0020}with\u{0020}the\u{0020}strong\u{0020}grew\u{0020}increasingly.\u{0020}Finally,\u{0020}one\u{0020}afternoon,\u{0020}under\u{0020}the\u{0020}encouragement\u{0020}of\u{0020}Huameng,\u{0020}Hualian\u{0020}decided\u{0020}to\u{0020}run\u{0020}away\u{0020}from\u{0020}home.\n\nShe\u{0020}took\u{0020}advantage\u{0020}of\u{0020}the\u{0020}lack\u{0020}of\u{0020}manpower\u{0020}in\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}and\u{0020}volunteered\u{0020}herself.\u{0020}After\u{0020}passing\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test,\u{0020}she\u{0020}became\u{0020}an\u{0020}official\u{0020}driver\u{0020}and\u{0020}went\u{0020}to\u{0020}the\u{0020}battlefield.", "0", "0", "0", "0", 10005, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}在前往艾吉斯九州总部之前，华恋与自己的姐姐华梦在深山中过着接近古人的隐世生活。她们白日读书学习，夜晚则在山林里修炼。\n\u{1000}\u{1000}华恋唯一与外面世界沟通的桥梁是每月一次的采购。她通过一次偶然的机会，用一本书接触到了一个崭新的世界。那是一个快意恩仇，行侠仗义的世界。尽管那与真实的外界存在着相当程度的偏差，但正是这份\"偏差\"，使得她对外界产生了向往……她对于\"常识\"产生了错误的认知，也要归咎于这些娱乐书籍。\n\u{1000}\u{1000}原本并未像姐姐那样沉迷于修炼中的她，在受到武侠故事的影响之后，开始热衷于与人切磋。遗憾的是小小的村子中并没有多少人能够与她对练，于是她的对手就只剩下陪伴着自己修炼的姐姐。\n\u{1000}\u{1000}对山中生活感到枯燥的她，曾经一个人悄悄溜到山外。在经历了一段不为人知的大冒险之后，华恋最后被处理人口贩卖事件的刑侦大队送回了山里。据说，有不少家长专程上门送了许多慰问品与锦旗，甚至有富翁专门拨钱在村子里建了一所图书馆，每年为村里运来新书——这一\"现象\"，直到原罪大规模入侵后才消失。\n\u{1000}\u{1000}华恋在这之后终日除了练武便是往图书馆里钻，不管是\"作品首字可以连成两句诗\"的系列作品，还是与前者齐名另一个作者的作品，她都一本不落地看完了。\n\u{1000}\u{1000}丰富多彩的故事与她枯燥的日常形成了强烈的对比，她那与强者交手的渴望日益增长。终于，在某一天的午后，华恋在自己姐姐华梦的怂恿下，决定来一次离家出走。\n\u{1000}\u{1000}她抓准艾吉斯九州总部缺乏人手的时机，毛遂自荐，通过了核心适格率测试后，成为了正式的驾驶员，奔赴战场。"},
[600503] = {600503, 1000, "\u{0020}\u{0020}Tian\u{0020}Hua\u{0020}Pavilion.\n\nThis\u{0020}is\u{0020}the\u{0020}team\u{0020}named\u{0020}by\u{0020}her,\u{0020}but\u{0020}of\u{0020}which\u{0020}she\u{0020}is\u{0020}not\u{0020}the\u{0020}captain.\u{0020}On\u{0020}the\u{0020}first\u{0020}day\u{0020}of\u{0020}the\u{0020}team's\u{0020}formation,\u{0020}on\u{0020}the\u{0020}grounds\u{0020}that\u{0020}\"team\u{0020}members\u{0020}should\u{0020}communicate\u{0020}through\u{0020}the\u{0020}punches\u{0020}they\u{0020}throw\",\u{0020}she\u{0020}challenged\u{0020}Caihua,\u{0020}the\u{0020}team\u{0020}leader.\n\nThe\u{0020}result\u{0020}was\u{0020}naturally\u{0020}a\u{0020}disastrous\u{0020}defeat.\u{0020}Even\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}Hualian's\u{0020}neck\u{0020}couldn't\u{0020}rotate\u{0020}normally\u{0020}and\u{0020}was\u{0020}almost\u{0020}forcibly\u{0020}corrected\u{0020}in\u{0020}posture.\n\nAfter\u{0020}this,\u{0020}Hualian\u{0020}still\u{0020}kept\u{0020}trying\u{0020}to\u{0020}challenge\u{0020}Caihua's\u{0020}authority\u{0020}as\u{0020}the\u{0020}team\u{0020}leader.\u{0020}Despite\u{0020}suffering\u{0020}defeats\u{0020}repeatedly,\u{0020}she\u{0020}persisted\u{0020}and\u{0020}this\u{0020}made\u{0020}Caihua\u{0020}feel\u{0020}troubled.\n\nThe\u{0020}purpose\u{0020}of\u{0020}Hualian's\u{0020}sparring\u{0020}with\u{0020}others\u{0020}is\u{0020}not\u{0020}about\u{0020}winning\u{0020}or\u{0020}losing,\u{0020}but\u{0020}to\u{0020}understand\u{0020}the\u{0020}other\u{0020}person's\u{0020}heart\u{0020}through\u{0020}the\u{0020}collision\u{0020}of\u{0020}fists\u{0020}and\u{0020}feet\u{0020}-\u{0020}this\u{0020}is\u{0020}what\u{0020}she\u{0020}thinks.\u{0020}To\u{0020}practice\u{0020}her\u{0020}theory,\u{0020}she\u{0020}keeps\u{0020}looking\u{0020}for\u{0020}her\u{0020}opponents\u{0020}at\u{0020}Kyushu\u{0020}Headquarters.\n\nIn\u{0020}addition,\u{0020}according\u{0020}to\u{0020}her,\u{0020}her\u{0020}behavior\u{0020}of\u{0020}engaging\u{0020}in\u{0020}communication\u{0020}with\u{0020}others\u{0020}has\u{0020}another\u{0020}purpose.\n\nIntuition\u{0020}tells\u{0020}me\u{0020}that\u{0020}my\u{0020}beloved\u{0020}is\u{0020}in\u{0020}AEGIS.\u{0020}I\u{0020}must\u{0020}find\u{0020}him!\n\nThis\u{0020}might\u{0020}be\u{0020}a\u{0020}romance\u{0020}that\u{0020}belongs\u{0020}to\u{0020}her\u{0020}love.", "0", "0", "0", "0", 10005, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}天华阁。\n\u{1000}\u{1000}这是由她命名，却并不是由她担任队长的小队。她在队伍组建的第一天，以\"队员之间应当通过挥出的拳头交流\"为由，向身为队长的彩华发起挑战。\n\u{1000}\u{1000}其结果自然是惨败，甚至很长一段时间华恋的脖子都无法正常转动，几乎是强迫性地被进行了姿势矫正。\n\u{1000}\u{1000}在此之后，华恋依然在想方设法挑战彩华身为队长的权威性，尽管屡战屡败，但她屡败屡战，让彩华感到苦恼。\n\u{1000}\u{1000}华恋与人切磋的目的并不在于胜负，而是通过肉体的碰撞来理解对方的心——她本人是这么认为的。她为了践行自己的理论，在九州总部不停地寻找自己的对手。\n\u{1000}\u{1000}另外，据她本人所说，她与人切磋的行为还有另一层目的。\n\u{1000}\u{1000}\"直觉告诉小生，小生的意中人就在艾吉斯，我一定要找到他！\"\n\u{1000}\u{1000}这或许是属于华恋的浪漫吧。"},
[600504] = {600504, 2000, "\u{0020}\u{0020}\"I\u{0020}ask,\u{0020}what\u{0020}is\u{0020}love\u{0020}that\u{0020}makes\u{0020}one's\u{0020}life\u{0020}-\u{0020}\"\n\nThe\u{0020}girl's\u{0020}poem\u{0020}was\u{0020}interrupted\u{0020}halfway\u{0020}through,\u{0020}and\u{0020}she\u{0020}blushed\u{0020}and\u{0020}broke\u{0020}it\u{0020}off.\n\n\"--\u{0020}No,\u{0020}don't\u{0020}make\u{0020}fun\u{0020}of\u{0020}me!\"\n\nNo,\u{0020}I\u{0020}did't.\u{0020}Although\u{0020}I\u{0020}wanted\u{0020}to\u{0020}tell\u{0020}her,\u{0020}the\u{0020}girl\u{0020}has\u{0020}already\u{0020}gone\u{0020}berserk.\n\nShe\u{0020}lifted\u{0020}her\u{0020}leg\u{0020}high,\u{0020}covering\u{0020}both\u{0020}the\u{0020}bright\u{0020}moon\u{0020}and\u{0020}the\u{0020}dark\u{0020}clouds.\n\n\"Navigator,\u{0020}take\u{0020}this\u{0020}passionate\u{0020}kick\u{0020}of\u{0020}mine!\u{0020}\"\n\nOh\u{0020}no.", "0", "0", "0", "0", 10005, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"问世间，情为何物，直教人生——\"\n\u{1000}\u{1000}少女的诗念到一半，便被她一脸羞红地打断了，\n\u{1000}\u{1000}\"——不，不许笑话小生！\"\n\u{1000}\u{1000}不，我没有。虽然想这么跟她沟通，但少女已经开始暴走了。\n\u{1000}\u{1000}她高抬起自己的腿，将皎月与乌云一并遮住。\n\u{1000}\u{1000}\"领航，接下小生这炙热的一脚吧！\"\n\u{1000}\u{1000}——完蛋了。"},
[600600] = {600600, 0, "[Name]\u{0020}Celine\u{0020}Welt\n[B-Day]\u{0020}March\u{0020}31\n[Compatability\u{0020}Rate]\u{0020}90％\n[Height]\u{0020}35m\n[Squad]\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Pain", "0", "0", "0", "0", 10006, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}栖琳•瓦尔特\n[B-Day]\u{1000}3月31日\n[幻化核心适格率]\u{1000}90％\n[Height]\u{1000}32m\n[部队]\u{1000}飓风突击队\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}苦难"},
[600601] = {600601, 100, "\u{0020}\u{0020}She\u{0020}longs\u{0020}for\u{0020}punishment\u{0020}and\u{0020}pain.\n\nShe\u{0020}wants\u{0020}to\u{0020}being\u{0020}scolded,\u{0020}criticized\u{0020}and\u{0020}punished.\n\nShe\u{0020}claimed\u{0020}that\u{0020}she\u{0020}could\u{0020}get\u{0020}pleasure\u{0020}from\u{0020}these\u{0020}behaviors\u{0020}and\u{0020}also\u{0020}believed\u{0020}that\u{0020}there\u{0020}must\u{0020}be\u{0020}someone\u{0020}who\u{0020}could\u{0020}understand\u{0020}her.\n\nPerhaps\u{0020}there\u{0020}are\u{0020}soulmates\u{0020}in\u{0020}the\u{0020}world\u{0020}who\u{0020}can\u{0020}reach\u{0020}a\u{0020}consensus\u{0020}with\u{0020}her,\u{0020}but\u{0020}it\u{0020}is\u{0020}certain\u{0020}that\u{0020}such\u{0020}people\u{0020}are\u{0020}in\u{0020}the\u{0020}minority.\n\nHowever,\u{0020}the\u{0020}team\u{0020}she\u{0020}was\u{0020}in\u{0020}seemed\u{0020}to\u{0020}be\u{0020}a\u{0020}shelter\u{0020}for\u{0020}weirdos.\u{0020}Julia\u{0020}Fox\u{0020}is\u{0020}always\u{0020}enjoying\u{0020}the\u{0020}bullying\u{0020}and\u{0020}insults\u{0020}against\u{0020}her.\u{0020}Jenny,\u{0020}who\u{0020}seems\u{0020}normal,\u{0020}is\u{0020}quite\u{0020}interested\u{0020}in\u{0020}the\u{0020}interaction\u{0020}between\u{0020}the\u{0020}two.\u{0020}The\u{0020}three\u{0020}of\u{0020}them\u{0020}form\u{0020}an\u{0020}exquisitely\u{0020}wonderful\u{0020}closed-loop\u{0020}structure\u{0020}in\u{0020}terms\u{0020}of\u{0020}\"weirdness\",\u{0020}which\u{0020}is\u{0020}unique\u{0020}in\u{0020}the\u{0020}entire\u{0020}Danube\u{0020}region.\n\nTherefore,\u{0020}although\u{0020}the\u{0020}\"Hurricane\u{0020}Shock\u{0020}Squad\"\u{0020}has\u{0020}many\u{0020}excellent\u{0020}performances\u{0020}in\u{0020}combat\u{0020}missions,\u{0020}what\u{0020}really\u{0020}makes\u{0020}the\u{0020}squad\u{0020}famous\u{0020}is\u{0020}still\u{0020}the\u{0020}team\u{0020}structure.", "0", "0", "0", "0", 10006, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}她渴望着欺凌与疼痛。\n\u{1000}\u{1000}她盼望着自己被人责骂，被人批评，被人惩罚。\n\u{1000}\u{1000}她声称自己能从这些行为中得到快感，也相信一定有人能够理解她。\n\u{1000}\u{1000}世界上或许存在着能与她达成共识的心灵之友，但可以确定的是那样的人也是少数。\n\u{1000}\u{1000}——本来应该是少数的，但是，她所在的队伍似乎就是一个怪人收容所。茱莉亚•福克斯总是在享受着对她的欺凌与辱骂，而看似正常的燕妮则似乎对前两位的互动颇感兴趣。她们三人在\"怪异上\"构成了巧妙绝伦的闭环结构，在整个多瑙地区独一无二。\n\u{1000}\u{1000}因此，\"飓风突击队\"虽然在作战任务上不乏精彩的表现，但真正让飓风突击队闻名于世的，还是该小队…………千载难逢的团队结构。"},
[600602] = {600602, 500, "\u{0020}\u{0020}Celine\u{0020}Welt,\u{0020}there\u{0020}are\u{0020}unknown\u{0020}peculiar\u{0020}phenomena\u{0020}in\u{0020}her\u{0020}body.\u{0020}Her\u{0020}body\u{0020}converts\u{0020}physical\u{0020}pain\u{0020}into\u{0020}pleasure,\u{0020}and\u{0020}the\u{0020}doctor\u{0020}who\u{0020}diagnosed\u{0020}her\u{0020}body,\u{0020}in\u{0020}order\u{0020}to\u{0020}respect\u{0020}Celine's\u{0020}personal\u{0020}opinion\u{0020}and\u{0020}conduct\u{0020}a\u{0020}practical\u{0020}analysis\u{0020}of\u{0020}her\u{0020}physical\u{0020}condition,\u{0020}believed\u{0020}that\u{0020}Celine\u{0020}could\u{0020}undergo\u{0020}surgery\u{0020}when\u{0020}she\u{0020}reached\u{0020}adulthood\u{0020}to\u{0020}return\u{0020}her\u{0020}body\u{0020}to\u{0020}normal.\u{0020}But\u{0020}Celine\u{0020}doesn't\u{0020}hate\u{0020}her\u{0020}body.\u{0020}Or\u{0020}rather,\u{0020}she\u{0020}enjoys\u{0020}the\u{0020}happiness\u{0020}brought\u{0020}by\u{0020}her\u{0020}special\u{0020}body.\u{0020}And\u{0020}Julia\u{0020}Fox\u{0020}was\u{0020}the\u{0020}first\u{0020}outsider\u{0020}to\u{0020}know\u{0020}the\u{0020}abnormalities\u{0020}on\u{0020}Celine.\u{0020}The\u{0020}reason\u{0020}why\u{0020}Celine\u{0020}joined\u{0020}Aegis\u{0020}and\u{0020}became\u{0020}the\u{0020}driver\u{0020}of\u{0020}Danube\u{0020}Branch\u{0020}is\u{0020}also\u{0020}inextricably\u{0020}linked\u{0020}to\u{0020}Julia.After\u{0020}her\u{0020}secret\u{0020}was\u{0020}revealed,\u{0020}Celine,\u{0020}who\u{0020}yearned\u{0020}for\u{0020}bullying,\u{0020}and\u{0020}the\u{0020}sharp-tongued\u{0020}Julia\u{0020}struck\u{0020}an\u{0020}unlikely\u{0020}alliance,\u{0020}forming\u{0020}a\u{0020}perplexing\u{0020}yet\u{0020}unbreakable\u{0020}friendship.\u{0020}This\u{0020}bond\u{0020}ultimately\u{0020}led\u{0020}Celine\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}and\u{0020}join\u{0020}forces\u{0020}with\u{0020}Julia\u{0020}as\u{0020}part\u{0020}of\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad.\u{0020}On\u{0020}the\u{0020}battlefield,\u{0020}she\u{0020}was\u{0020}still\u{0020}enjoying\u{0020}the\u{0020}thrill\u{0020}of\u{0020}pain,\u{0020}and\u{0020}she\u{0020}would\u{0020}even\u{0020}accumulate\u{0020}injuries\u{0020}and\u{0020}increase\u{0020}her\u{0020}Compatability\u{0020}Rate\u{0020}with\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}an\u{0020}astonishing\u{0020}99%.\u{0020}The\u{0020}Hurricane\u{0020}Shock\u{0020}Squad's\u{0020}alias\u{0020}\"Masochist\u{0020}Club\"\u{0020}was\u{0020}born\u{0020}because\u{0020}of\u{0020}Celine's\u{0020}kink.\u{0020}To\u{0020}be\u{0020}honest,\u{0020}a\u{0020}team\u{0020}like\u{0020}this\u{0020}could\u{0020}become\u{0020}an\u{0020}official\u{0020}force\u{0020}of\u{0020}Aegis\u{0020}Danube\u{0020}Branch\u{0020}is\u{0020}something\u{0020}that\u{0020}puzzles\u{0020}everyone.\u{0020}What's\u{0020}even\u{0020}more\u{0020}puzzling\u{0020}is\u{0020}that\u{0020}a\u{0020}team\u{0020}like\u{0020}this\u{0020}has\u{0020}repeatedly\u{0020}achieved\u{0020}feats\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}Is\u{0020}it\u{0020}true\u{0020}to\u{0020}say\u{0020}that\u{0020}this\u{0020}era\u{0020}belongs\u{0020}to\u{0020}freaks?", "0", "0", "0", "0", 10006, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}栖琳·瓦尔特，她的身体存在着不为人知的奇特现象。\u{1000}\u{1000}她的身体会将物理上的疼痛转化为快感，而为她的身体进行诊断的医生为了尊重栖琳的个人意见，并且就身体状况进行实际分析后，认为在栖琳成年后就可以接受手术，让身体回归正常。\u{1000}\u{1000}但是栖琳却并不讨厌自己的身体，或者说，她享受着自己特殊体质带来的快乐。\u{1000}\u{1000}而茱莉亚·福克斯是第一个知道栖琳身上异常之处的外人。\u{1000}\u{1000}栖琳之所以会加入艾吉斯，成为Danube\u{1000}Branch的驾驶员，也和茱莉亚有着千丝万缕的关系。在自己的秘密暴露后，渴望欺凌的栖琳，与胡作非为的茱莉亚，在利益上达成了一致，成为了令人面红耳热的心灵之友。\u{1000}\u{1000}\u{1000}\u{1000}正是为了能够更好的维持着二者之间的亲密关系，栖琳才会自愿成为驾驶员，并且与茱莉亚成为队友，成为飓风突击队的一员。\u{1000}\u{1000}在战场上，她仍然在享受着由痛苦转换而来的快感，甚至在战斗过程中，逐渐累积伤势的她会与幻化核心的适格率提升至惊人的99%。\u{1000}\u{1000}飓风突击队的别名\"受虐同好会\"，便是因为栖琳这古怪的特殊癖好而诞生的。\u{1000}\u{1000}说实话，像这样的队伍，能够成为艾吉斯Danube\u{1000}Branch的正式部队，是一件令所有人都感到困惑的事，更令人不解的是，像这样的队伍，却屡屡在战场上立下功劳。\u{1000}\u{1000}难道说，这个时代属于怪胎吗？"},
[600603] = {600603, 1000, "\u{0020}\u{0020}A\u{0020}\"rising\u{0020}star\u{0020}of\u{0020}the\u{0020}battlefield\",\u{0020}and\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}\"Masochist\u{0020}Club\".\u{0020}After\u{0020}Celine\u{0020}joined\u{0020}AEGIS,\u{0020}she\u{0020}and\u{0020}her\u{0020}teammate\u{0020}Julia\u{0020}became\u{0020}influential\u{0020}figures\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}\"Hurricane\u{0020}Shock\u{0020}Squad\".\n\nThe\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\u{0020}has\u{0020}always\u{0020}been\u{0020}highly\u{0020}controversial,\u{0020}and\u{0020}public\u{0020}opinion\u{0020}about\u{0020}them\u{0020}always\u{0020}leans\u{0020}against\u{0020}them.\u{0020}But\u{0020}all\u{0020}these\u{0020}don't\u{0020}affect\u{0020}her.\u{0020}Rather,\u{0020}these\u{0020}abuses\u{0020}and\u{0020}accusations\u{0020}make\u{0020}her\u{0020}more\u{0020}excited\u{0020}and\u{0020}her\u{0020}performance\u{0020}in\u{0020}battles\u{0020}even\u{0020}better.\n\nIn\u{0020}the\u{0020}squad,\u{0020}whenever\u{0020}Julia\u{0020}Fox\u{0020}\"instruct\"\u{0020}her,\u{0020}Jenny\u{0020}would\u{0020}enthusiastically\u{0020}film\u{0020}the\u{0020}scene\u{0020}with\u{0020}a\u{0020}camera.\u{0020}If\u{0020}one\u{0020}were\u{0020}to\u{0020}evaluate\u{0020}the\u{0020}atmosphere\u{0020}of\u{0020}the\u{0020}squad\u{0020}by\u{0020}discarding\u{0020}morality,\u{0020}one\u{0020}might\u{0020}give\u{0020}the\u{0020}evaluation\u{0020}of\u{0020}\"harmonious\u{0020}and\u{0020}happy\".", "0", "0", "0", "0", 10006, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}一边是\"战场的明日之星\"，一边是\"受虐同好会\"的重要份子，栖琳·瓦尔特加入艾吉斯之后，就与她的队员茱莉亚·福克斯成为Danube\u{1000}Branch的风云人物，成为了\"飓风突击队\"的一员。\n\u{1000}\u{1000}飓风突击队总是备受着争议，对她们的舆论总是倒向她的对立面。但这些似乎都无法对她本人造成实际的影响，不如说，这些谩骂与指责会让她更加兴奋，在战斗时的表现会更加优秀。\n\u{1000}\u{1000}在小队里，每当茱莉亚·福克斯对她进行\"教导\"时，一旁的燕妮都会兴趣盎然地用摄影机记录画面。如果以舍弃常识与道德的方式去评价小队的氛围，大概会说出\"其乐融融\"的评价吧。"},
[600604] = {600604, 2000, "\u{0020}\u{0020}——I\u{0020}don't\u{0020}know\u{0020}when\u{0020}the\u{0020}support\u{0020}will\u{0020}arrive.\n\n——I\u{0020}don't\u{0020}know\u{0020}how\u{0020}long\u{0020}I\u{0020}can\u{0020}hold\u{0020}on.\n\nShe\u{0020}stood\u{0020}between\u{0020}the\u{0020}corpses\u{0020}of\u{0020}Sin\u{0020}and\u{0020}the\u{0020}barren\u{0020}mountains,\u{0020}with\u{0020}trampled\u{0020}ancient\u{0020}trees\u{0020}beneath\u{0020}her\u{0020}feet.\n\nThe\u{0020}three-hour\u{0020}continuous\u{0020}fierce\u{0020}battle\u{0020}has\u{0020}left\u{0020}her\u{0020}physical\u{0020}strength\u{0020}nearly\u{0020}exhausted,\u{0020}and\u{0020}her\u{0020}unrecovered\u{0020}body\u{0020}is\u{0020}covered\u{0020}with\u{0020}wounds.\n\nThe\u{0020}amount\u{0020}of\u{0020}blood\u{0020}flowing\u{0020}from\u{0020}her\u{0020}body\u{0020}could\u{0020}almost\u{0020}be\u{0020}used\u{0020}for\u{0020}someone\u{0020}to\u{0020}take\u{0020}a\u{0020}shower.\n\nThe\u{0020}sense\u{0020}of\u{0020}despair\u{0020}brought\u{0020}by\u{0020}the\u{0020}endless\u{0020}battle\u{0020}pressed\u{0020}upon\u{0020}her\u{0020}like\u{0020}dark\u{0020}clouds.\n\nFor\u{0020}a\u{0020}normal\u{0020}person,\u{0020}they\u{0020}should\u{0020}have\u{0020}collapsed\u{0020}by\u{0020}now.\n\nBut\u{0020}she\u{0020}won't.\u{0020}Only\u{0020}she\u{0020}won't.\n\nInstead,\u{0020}she\u{0020}was\u{0020}laughing.\n\nHappiness\u{0020}is\u{0020}born\u{0020}from\u{0020}pain,\n\nand\u{0020}hope\u{0020}is\u{0020}born\u{0020}from\u{0020}despair.\n\n\"This\u{0020}is\u{0020}-\u{0020}what\u{0020}I\u{0020}have\u{0020}been\u{0020}looking\u{0020}for.\"\n\nThe\u{0020}shield\u{0020}she\u{0020}held\u{0020}high\u{0020}to\u{0020}protect\u{0020}her\u{0020}teammates\u{0020}seemed\u{0020}to\u{0020}never\u{0020}fall.", "0", "0", "0", "0", 10006, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}——不知道什么时候援军才会抵达。\n\u{1000}\u{1000}——不知道自己还能够坚持多久。\n\u{1000}\u{1000}她伫立在原罪的尸体与荒山之间，脚底下是被践踏了的古树。\n\u{1000}\u{1000}连续三小时的鏖战让她体力接近枯竭，无法得到恢复的身体遍布伤口。\n\u{1000}\u{1000}从她身上流出的血的量，几乎能够供人淋浴。\n\u{1000}\u{1000}无止境地战斗所带来的绝望感如乌云般压在她的身上。\n\u{1000}\u{1000}正常人的话，这时候应该崩溃了吧。\n\u{1000}\u{1000}但是她不会，只有她不会，\n\u{1000}\u{1000}她反而是在笑。\n\u{1000}\u{1000}从痛苦中诞生快乐，\n\u{1000}\u{1000}从绝望中诞生希望。\n\u{1000}\u{1000}\"这就是——我一直在寻找的东西啊。\"\n\u{1000}\u{1000}她高举着的用来守护队友的盾，似乎永远不会倒下。"},
[600700] = {600700, 0, "[Name]\u{0020}Uki\n[B-Day]\u{0020}July\u{0020}16\n[Compatability\u{0020}Rate]\u{0020}72％\n[Height]\u{0020}36m\n[Squad]\u{0020}Whalefall\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Cooking;\u{0020}knitting", "0", "0", "0", "0", 10007, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}海姬\n[B-Day]\u{1000}7月16日\n[幻化核心适格率]\u{1000}72％\n[Height]\u{1000}38m\n[部队]\u{1000}鲸落\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}料理\u{1000}纺织"},
[600701] = {600701, 100, "\u{0020}\u{0020}The\u{0020}captain\u{0020}of\u{0020}Whalefall,\u{0020}an\u{0020}ordinary\u{0020}girl\u{0020}from\u{0020}a\u{0020}seaside\u{0020}fishing\u{0020}village.\u{0020}As\u{0020}the\u{0020}captain\u{0020}of\u{0020}Whalefall,\u{0020}her\u{0020}underwater\u{0020}combat\u{0020}skills\u{0020}are\u{0020}the\u{0020}most\u{0020}proficient\u{0020}in\u{0020}the\u{0020}team.\u{0020}Even\u{0020}facing\u{0020}underwater\u{0020}specialized\u{0020}Sins,\u{0020}she\u{0020}is\u{0020}not\u{0020}inferior\u{0020}at\u{0020}all.\n\nPerhaps\u{0020}it\u{0020}is\u{0020}because\u{0020}of\u{0020}her\u{0020}origin.\u{0020}She\u{0020}has\u{0020}the\u{0020}inclusiveness\u{0020}that\u{0020}reminds\u{0020}people\u{0020}of\u{0020}the\u{0020}sea.\u{0020}Her\u{0020}kind\u{0020}and\u{0020}gentle\u{0020}attitude\u{0020}makes\u{0020}people\u{0020}unable\u{0020}to\u{0020}resist\u{0020}getting\u{0020}close\u{0020}to\u{0020}her.\n\nThe\u{0020}environment\u{0020}of\u{0020}the\u{0020}fishing\u{0020}village\u{0020}allows\u{0020}her\u{0020}to\u{0020}make\u{0020}delicious\u{0020}seafood\u{0020}dishes.\u{0020}When\u{0020}the\u{0020}frontline\u{0020}soldiers\u{0020}return\u{0020}to\u{0020}Kyushu\u{0020}Headquarters,\u{0020}she\u{0020}will\u{0020}prepare\u{0020}a\u{0020}sumptuous\u{0020}seafood\u{0020}feast\u{0020}for\u{0020}them.\n\n\"How\u{0020}should\u{0020}I\u{0020}put\u{0020}it?\u{0020}If\u{0020}Seifung\u{0020}is\u{0020}a\u{0020}mother,\u{0020}then\u{0020}she\u{0020}is\u{0020}more\u{0020}like\u{0020}a\u{0020}wife.\"\n\nA\u{0020}certain\u{0020}member\u{0020}of\u{0020}Fuurinkazan\u{0020}accurately\u{0020}pointed\u{0020}out\u{0020}the\u{0020}special\u{0020}aspect\u{0020}of\u{0020}the\u{0020}captain\u{0020}of\u{0020}Whalefall.", "0", "0", "0", "0", 10007, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}鲸落的队长，来自海边渔村的平凡少女。作为鲸落的队长，她的水下作战技巧是队伍中最娴熟的，即便面对水下特化型的原罪，她也不会逊色半分。\n\u{1000}\u{1000}也许是出身海边的缘故，她有着让人联想到大海的包容力，她亲切温和的待人态度让人忍不住想要亲近。\n\u{1000}\u{1000}渔村的生长环境让她能做出美味的海鲜料理，当前线战士返回九州总部时，她便会为对方准备好丰盛的海鲜大餐。\n\u{1000}\u{1000}\"和铃木清风不一样——怎么说呢，如果说小清风是妈妈，那么她就更像是妻子吧？\"\n\u{1000}\u{1000}风林火山某位队员精准地指出了鲸落队长的特别之处。"},
[600702] = {600702, 500, "\u{0020}\u{0020}In\u{0020}Uki's\u{0020}hometown,\u{0020}a\u{0020}small\u{0020}fishing\u{0020}village\u{0020}by\u{0020}the\u{0020}sea,\u{0020}there\u{0020}has\u{0020}been\u{0020}a\u{0020}legend\u{0020}passed\u{0020}down\u{0020}from\u{0020}thousands\u{0020}of\u{0020}years\u{0020}ago.\n\nIn\u{0020}the\u{0020}sea\u{0020}area\u{0020}near\u{0020}the\u{0020}fishing\u{0020}village,\u{0020}there\u{0020}dwells\u{0020}a\u{0020}deity,\u{0020}whom\u{0020}the\u{0020}locals\u{0020}call\u{0020}the\u{0020}Sea\u{0020}God.\u{0020}Whenever\u{0020}the\u{0020}weather\u{0020}is\u{0020}bad\u{0020}and\u{0020}there\u{0020}are\u{0020}fierce\u{0020}winds\u{0020}and\u{0020}heavy\u{0020}rain,\u{0020}it\u{0020}means\u{0020}that\u{0020}the\u{0020}Sea\u{0020}God\u{0020}is\u{0020}angry.\u{0020}The\u{0020}lonely\u{0020}Sea\u{0020}God\u{0020}longs\u{0020}for\u{0020}a\u{0020}companion\u{0020}to\u{0020}soothe\u{0020}his\u{0020}solitude.\n\nIn\u{0020}order\u{0020}to\u{0020}pacify\u{0020}the\u{0020}wrath\u{0020}of\u{0020}the\u{0020}Sea\u{0020}God\u{0020}and\u{0020}restore\u{0020}the\u{0020}calmness\u{0020}of\u{0020}the\u{0020}sea,\u{0020}fishermen\u{0020}would\u{0020}select\u{0020}young\u{0020}and\u{0020}beautiful\u{0020}women\u{0020}from\u{0020}the\u{0020}village\u{0020}as\u{0020}the\u{0020}bride\u{0020}of\u{0020}the\u{0020}Sea\u{0020}God\u{0020}and\u{0020}offer\u{0020}them\u{0020}to\u{0020}the\u{0020}Sea\u{0020}God\u{0020}every\u{0020}ten\u{0020}years,\u{0020}praying\u{0020}for\u{0020}good\u{0020}weather\u{0020}and\u{0020}favorable\u{0020}conditions.\n\nNowadays,\u{0020}the\u{0020}evil\u{0020}\"living\u{0020}sacrifice\"\u{0020}has\u{0020}naturally\u{0020}been\u{0020}abolished,\u{0020}but\u{0020}the\u{0020}custom\u{0020}of\u{0020}the\u{0020}\"Bride\u{0020}of\u{0020}the\u{0020}Sea\u{0020}God\"\u{0020}has\u{0020}remained\u{0020}-\u{0020}Uki\u{0020}is\u{0020}precisely\u{0020}the\u{0020}\"Bride\u{0020}of\u{0020}the\u{0020}Sea\u{0020}God\"\u{0020}of\u{0020}this\u{0020}generation,\u{0020}carrying\u{0020}the\u{0020}hope\u{0020}of\u{0020}the\u{0020}fishermen\u{0020}for\u{0020}a\u{0020}better\u{0020}life.\n\nA\u{0020}disgusting\u{0020}coincidence\u{0020}occurred.\u{0020}The\u{0020}first\u{0020}invasion\u{0020}of\u{0020}Sin\u{0020}was\u{0020}almost\u{0020}simultaneous\u{0020}with\u{0020}Uki\u{0020}serving\u{0020}as\u{0020}the\u{0020}Bride\u{0020}of\u{0020}the\u{0020}Sea\u{0020}God.\u{0020}Although\u{0020}the\u{0020}villagers\u{0020}did\u{0020}not\u{0020}associate\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin\u{0020}with\u{0020}Uki,\u{0020}there\u{0020}was\u{0020}an\u{0020}unreasonable\u{0020}sense\u{0020}of\u{0020}guilt\u{0020}in\u{0020}Uki's\u{0020}heart.\n\nThe\u{0020}invasion\u{0020}of\u{0020}Sin\u{0020}and\u{0020}the\u{0020}counterattack\u{0020}of\u{0020}mankind.\u{0020}Uki,\u{0020}who\u{0020}is\u{0020}in\u{0020}a\u{0020}remote\u{0020}fishing\u{0020}village,\u{0020}has\u{0020}always\u{0020}been\u{0020}concerned\u{0020}about\u{0020}the\u{0020}front\u{0020}battlefield.\u{0020}She\u{0020}doesn't\u{0020}know\u{0020}why\u{0020}she\u{0020}does\u{0020}this.\n\nWhen\u{0020}the\u{0020}Envy\u{0020}invasion\u{0020}incident\u{0020}ended\u{0020}and\u{0020}saw\u{0020}the\u{0020}devastated\u{0020}City\u{0020}of\u{0020}Saar,\u{0020}Uki's\u{0020}heart\u{0020}couldn't\u{0020}hold\u{0020}back\u{0020}anymore.\u{0020}She\u{0020}could\u{0020}no\u{0020}longer\u{0020}endure\u{0020}this\u{0020}endless\u{0020}waiting\u{0020}and\u{0020}could\u{0020}no\u{0020}longer\u{0020}endure\u{0020}this\u{0020}kind\u{0020}of\u{0020}life\u{0020}where\u{0020}she\u{0020}could\u{0020}only\u{0020}pray\u{0020}for\u{0020}the\u{0020}appearance\u{0020}of\u{0020}heroes\u{0020}in\u{0020}the\u{0020}rear.\n\nShe\u{0020}was\u{0020}deeply\u{0020}afraid\u{0020}that\u{0020}the\u{0020}disaster\u{0020}of\u{0020}City\u{0020}of\u{0020}Saar\u{0020}would\u{0020}befall\u{0020}her\u{0020}family\u{0020}and\u{0020}was\u{0020}afraid\u{0020}of\u{0020}a\u{0020}future\u{0020}where\u{0020}she\u{0020}was\u{0020}powerless\u{0020}when\u{0020}the\u{0020}disaster\u{0020}occurred.\n\nWhen\u{0020}Aegis\u{0020}recruited\u{0020}excellent\u{0020}water-based\u{0020}warriors\u{0020}to\u{0020}prevent\u{0020}the\u{0020}invasion\u{0020}of\u{0020}aquatic\u{0020}Sin\u{0020}in\u{0020}the\u{0020}future,\u{0020}Uki,\u{0020}with\u{0020}the\u{0020}support\u{0020}of\u{0020}her\u{0020}family\u{0020}and\u{0020}fellow\u{0020}villagers,\u{0020}went\u{0020}to\u{0020}Kyushu\u{0020}Headquarters\u{0020}alone\u{0020}and\u{0020}passed\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test.\n\n\"People\u{0020}are\u{0020}looking\u{0020}forward\u{0020}to\u{0020}the\u{0020}appearance\u{0020}of\u{0020}heroes...\u{0020}But\u{0020}if\u{0020}heroes\u{0020}don't\u{0020}appear,\u{0020}they\u{0020}can\u{0020}only\u{0020}try\u{0020}to\u{0020}be\u{0020}heroes\u{0020}themselves,\u{0020}right?\"", "0", "0", "0", "0", 10007, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}在海姬的家乡，一个位于海边的小渔村，流传着一个从千百年前传下来的传说。\n\u{1000}\u{1000}在渔村附近的海域里，寄宿着一位神灵，当地的人将它称为海神。每当气候恶劣，狂风暴雨的时候，便意味着海神发怒了。孤苦伶仃的海神渴望着一个伴侣，来抚慰自己的孤独。\n\u{1000}\u{1000}为了让海神平息怒火，让大海恢复平静，渔民们会每隔十年从村中选择年轻貌美的女子作为海神的新娘而献给海神，祈求风调雨顺。\n\u{1000}\u{1000}近代以后，\"活祭\"这种恶习自然是被废除了，但\"海神新娘\"这一习俗却保留了下来——海姬，正是这一代的\"海神新娘\"，背负着渔村民众对美好生活的希冀。\n\u{1000}\u{1000}令人嫌恶的巧合发生了，原罪的第一次全面入侵与海姬担任海神新娘几乎是同时的事情。尽管朴实的村民没有将原罪的入侵与海姬联系在一起，但海姬心中却存在着一种没有道理的负罪感。\n\u{1000}\u{1000}原罪的入侵与人类的反击，身处偏远渔村的海姬一直关心着前线战场的变化。她不清楚自己为什么要这么做。\n\u{1000}\u{1000}当嫉妒入侵事件结束后，看到千疮百孔的萨尔市，海姬的心终于按捺不住了。她不能再忍受这种漫无止境的等待，无法再忍受这种只能在后方祈祷英雄出现的生活。\n\u{1000}\u{1000}她打从心底里害怕着萨尔市的灾难降临在自己的家人身上，恐惧着灾难发生时自己却又无能为力的未来。\n\u{1000}\u{1000}在艾吉斯为了预防今后再次出现水栖型原罪的入侵而召集水性优秀的战士时，海姬在家人、乡亲的支持下，只身前往九州总部，通过了幻化核心适格率测试。\n\u{1000}\u{1000}\"人们盼望着英雄出现……可英雄不出现的话，就只能自己试着去当英雄了吧？\""},
[600703] = {600703, 1000, "\u{0020}\u{0020}After\u{0020}training,\u{0020}Uki\u{0020}became\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}newly\u{0020}established\u{0020}team\u{0020}\"Whale\u{0020}Fall\"\u{0020}of\u{0020}Kyushu\u{0020}Headquarters.\n\nUki\u{0020}didn't\u{0020}show\u{0020}any\u{0020}extraordinary\u{0020}talent\u{0020}in\u{0020}combat.\u{0020}In\u{0020}various\u{0020}weapon\u{0020}trainings,\u{0020}she\u{0020}was\u{0020}neither\u{0020}clumsy\u{0020}nor\u{0020}outstanding.\u{0020}Considering\u{0020}that\u{0020}Uki's\u{0020}personality\u{0020}lacked\u{0020}aggressiveness,\u{0020}after\u{0020}obtaining\u{0020}her\u{0020}consent,\u{0020}Uki\u{0020}became\u{0020}a\u{0020}\"Guardian\".\n\nCompared\u{0020}to\u{0020}killing\u{0020}Sin,\u{0020}she\u{0020}hoped\u{0020}to\u{0020}protect\u{0020}her\u{0020}companions\u{0020}who\u{0020}fought\u{0020}against\u{0020}Sin.\u{0020}\"I\u{0020}don't\u{0020}want\u{0020}to\u{0020}see\u{0020}anyone\u{0020}die\u{0020}in\u{0020}front\u{0020}of\u{0020}me.\"\u{0020}With\u{0020}such\u{0020}determination,\u{0020}Uki\u{0020}walked\u{0020}onto\u{0020}the\u{0020}battlefield.\n\nSurprisingly,\u{0020}even\u{0020}though\u{0020}she\u{0020}became\u{0020}a\u{0020}warrior,\u{0020}Uki\u{0020}has\u{0020}not\u{0020}forgotten\u{0020}her\u{0020}identity\u{0020}as\u{0020}the\u{0020}\"Bride\u{0020}of\u{0020}the\u{0020}Sea\u{0020}God\".\u{0020}Up\u{0020}to\u{0020}now,\u{0020}she\u{0020}is\u{0020}still\u{0020}undergoing\u{0020}bride\u{0020}training.\u{0020}Perhaps\u{0020}one\u{0020}day\u{0020}in\u{0020}the\u{0020}future,\u{0020}she\u{0020}will\u{0020}express\u{0020}her\u{0020}feelings\u{0020}to\u{0020}someone.", "0", "0", "0", "0", 10007, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}在经过一段时间的训练后，海姬成为了九州总部新成立小队\"鲸落\"的队长。\n\u{1000}\u{1000}海姬在战斗上没有展现任何过人的天赋，在各项武器训练上，不笨拙，也不突出。考虑到海姬的性格缺乏攻击性，在征求她本人的同意之后，海姬成为了一名\"守护者\"。\n\u{1000}\u{1000}比起杀死原罪，她更希望能够守护与原罪战斗的同伴。\"不希望见到任何人在自己面前死去\"，带着这样的决意，海姬走上了战场。\n\u{1000}\u{1000}稍微让人吃惊的是，即便成了一名战士，海姬也没有忘记自己\"海神新娘\"的身份。时至今日，她也在进行着新娘修行。或许将来的某一天，她会向某人表明自己的心意吧。"},
[600704] = {600704, 2000, "\u{0020}\u{0020}The\u{0020}girl\u{0020}emits\u{0020}the\u{0020}smell\u{0020}of\u{0020}the\u{0020}sea.\n\nA\u{0020}huge\u{0020}figure\u{0020}emerged\u{0020}from\u{0020}the\u{0020}sea,\u{0020}and\u{0020}she\u{0020}raised\u{0020}her\u{0020}head\u{0020}and\u{0020}shook\u{0020}her\u{0020}hair.\n\nThe\u{0020}brilliance\u{0020}of\u{0020}the\u{0020}sun\u{0020}fell\u{0020}upon\u{0020}her\u{0020}azure\u{0020}hair,\u{0020}shining\u{0020}brightly.\n\nShe\u{0020}looked\u{0020}at\u{0020}the\u{0020}person\u{0020}waiting\u{0020}for\u{0020}her\u{0020}on\u{0020}the\u{0020}coast.\n\n\"It's\u{0020}been\u{0020}a\u{0020}long\u{0020}time\u{0020}since\u{0020}I\u{0020}swam\u{0020}like\u{0020}this\u{0020}-\u{0020}Thank\u{0020}you,\u{0020}Navigator.\"\n\nIn\u{0020}her\u{0020}crimson\u{0020}pupils,\u{0020}it\u{0020}seemed\u{0020}as\u{0020}if\u{0020}there\u{0020}were\u{0020}flowing\u{0020}lights\u{0020}rotating.\n\nThe\u{0020}figure\u{0020}of\u{0020}that\u{0020}person\u{0020}was\u{0020}engraved\u{0020}in\u{0020}her\u{0020}pupils.\n\n\"Would\u{0020}you\u{0020}like\u{0020}to\u{0020}swim\u{0020}together,\u{0020}Navigator?\u{0020}I'll\u{0020}hold\u{0020}you\u{0020}up.\"\u{0020}", "0", "0", "0", "0", 10007, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}少女的身上散发着大海的气息，\n\u{1000}\u{1000}庞大的身躯从海里浮现，她仰着头甩了甩头发。\n\u{1000}\u{1000}太阳的光辉落在她蔚蓝的头发上，熠熠生辉，\n\u{1000}\u{1000}她看向在海岸上等着自己的那个人，\n\u{1000}\u{1000}\"好久没像这样游过泳了——谢谢您，领航。\"\n\u{1000}\u{1000}她赤红的瞳中仿佛有流光在转动着，\n\u{1000}\u{1000}那个人的身影被刻印在她的瞳里，\n\u{1000}\u{1000}\"要一起来游泳吗，领航？我会托着您的。\""},
[600800] = {600800, 0, "[Name]\u{0020}Dolores\u{0020}Gaviota\n[B-Day]\u{0020}Jan\u{0020}1\n[Compatability\u{0020}Rate]\u{0020}46％\n[Height]\u{0020}34m\n[Squad]\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Arctic\u{0020}terns,\u{0020}seagulls.", "0", "0", "0", "0", 10008, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}多洛莉丝·加维俄塔\n[B-Day]\u{1000}1月1日\n[幻化核心适格率]\u{1000}46％\n[Height]\u{1000}34m\n[部队]\u{1000}Third\u{1000}Research\u{1000}Laboratory防卫班\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}北极燕鸥\u{1000}猜拳"},
[600801] = {600801, 100, "\u{0020}\u{0020}As\u{0020}one\u{0020}of\u{0020}the\u{0020}drivers\u{0020}with\u{0020}the\u{0020}lowest\u{0020}Compatability\u{0020}Rate,\u{0020}she's\u{0020}certainly\u{0020}the\u{0020}least\u{0020}capable\u{0020}member\u{0020}in\u{0020}her\u{0020}unit.\n\nAnd\u{0020}because\u{0020}of\u{0020}this\u{0020}congenital\u{0020}stigma,\u{0020}no\u{0020}matter\u{0020}how\u{0020}much\u{0020}effort\u{0020}she\u{0020}puts\u{0020}in,\u{0020}she\u{0020}can't\u{0020}be\u{0020}as\u{0020}capable\u{0020}as\u{0020}everybody\u{0020}else.\n\nFortunately,\u{0020}her\u{0020}squadmates\u{0020}don't\u{0020}mind.\u{0020}She\u{0020}has\u{0020}her\u{0020}own\u{0020}advantages.\n\nEverybody\u{0020}who\u{0020}gets\u{0020}along\u{0020}with\u{0020}her\u{0020}feels\u{0020}that\u{0020}she\u{0020}really\u{0020}cares\u{0020}about\u{0020}other\u{0020}people.\u{0020}Her\u{0020}personality\u{0020}is\u{0020}so\u{0020}gentle\u{0020}that\u{0020}she\u{0020}becomes\u{0020}the\u{0020}\"listener\"\u{0020}in\u{0020}her\u{0020}unit,\u{0020}and\u{0020}her\u{0020}squadmates\u{0020}will\u{0020}pour\u{0020}out\u{0020}to\u{0020}her\u{0020}when\u{0020}they\u{0020}have\u{0020}troubles.\u{0020}Although\u{0020}she\u{0020}may\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}solve\u{0020}them,\u{0020}she\u{0020}listens\u{0020}silently\u{0020}and\u{0020}tries\u{0020}her\u{0020}best\u{0020}to\u{0020}seek\u{0020}solutions,\u{0020}and\u{0020}that\u{0020}is\u{0020}pretty\u{0020}exhilarating.\n\nBut\u{0020}for\u{0020}herself,\u{0020}perhaps\u{0020}she\u{0020}wants\u{0020}to\u{0020}be\u{0020}more\u{0020}useful\u{0020}in\u{0020}the\u{0020}future.\u{0020}That's\u{0020}because\u{0020}she's\u{0020}also\u{0020}looking\u{0020}forward\u{0020}to\u{0020}fighting\u{0020}side\u{0020}by\u{0020}side\u{0020}with\u{0020}her\u{0020}best\u{0020}friends.", "0", "0", "0", "0", 10008, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}作为适格率最低的一批驾驶员，多洛莉丝毋庸置疑在部队中的实力属于垫底水平。\n\u{1000}\u{1000}也正是因为这先天的短板，无论她怎么努力都无法追上大家。\n\u{1000}\u{1000}不过好在Third\u{1000}Research\u{1000}Laboratory的大家并不会在意这点，毕竟她也有着属于自己的闪光点。\n\u{1000}\u{1000}所有和她相处过的人，都能感受到自己备受其重视。心思细腻的她担当着部队里大家的倾听者，无论谁遇到了困难都会优先去找多洛莉丝倾诉，虽然她可能无法直接帮助大家解决困难，但是她那安静倾听过后再拼尽自己的全力去想办法的模样确实能让人备受鼓舞。\n\u{1000}\u{1000}不过就她本人而言，可能更加希望自己有朝一日能真正派上用场吧。毕竟，她也盼望着，能和最喜欢的伙伴们一同并肩作战。"},
[600802] = {600802, 500, "\u{0020}\u{0020}Dolores\u{0020}was\u{0020}born\u{0020}in\u{0020}Saar,\u{0020}a\u{0020}harbor\u{0020}region\u{0020}in\u{0020}Danube.\u{0020}Like\u{0020}she\u{0020}said,\u{0020}Saar\u{0020}often\u{0020}suffers\u{0020}from\u{0020}disasters\u{0020}since\u{0020}ancient\u{0020}times.\u{0020}Before\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sins,\u{0020}tsunamis\u{0020}were\u{0020}common\u{0020}visitors\u{0020}of\u{0020}this\u{0020}city.\u{0020}Disasters\u{0020}made\u{0020}Saars\u{0020}implacable\u{0020}and\u{0020}altruistic.\u{0020}Today,\u{0020}although\u{0020}Aegis'\u{0020}reconstruction\u{0020}and\u{0020}reformation\u{0020}have\u{0020}kept\u{0020}tsunamis\u{0020}away\u{0020}from\u{0020}Saar,\u{0020}people\u{0020}here\u{0020}still\u{0020}hold\u{0020}these\u{0020}spirits,\u{0020}like\u{0020}genes.\n\nA\u{0020}decade\u{0020}ago,\u{0020}a\u{0020}catastrophe\u{0020}destroyed\u{0020}Saar\u{0020}again,\u{0020}that\u{0020}was\u{0020}the\u{0020}first\u{0020}invasion\u{0020}of\u{0020}the\u{0020}Sins.\u{0020}Little\u{0020}Dolores\u{0020}was\u{0020}stuck\u{0020}in\u{0020}a\u{0020}subway\u{0020}train,\u{0020}with\u{0020}other\u{0020}passengers.\u{0020}As\u{0020}time\u{0020}passed,\u{0020}they\u{0020}were\u{0020}running\u{0020}out\u{0020}of\u{0020}food\u{0020}and\u{0020}water,\u{0020}and\u{0020}adults\u{0020}made\u{0020}a\u{0020}critical\u{0020}decision.\u{0020}To\u{0020}let\u{0020}the\u{0020}children,\u{0020}the\u{0020}hope\u{0020}of\u{0020}Saar's\u{0020}future\u{0020}survive,\u{0020}they\u{0020}left\u{0020}their\u{0020}food\u{0020}and\u{0020}water\u{0020}to\u{0020}children,\u{0020}and\u{0020}gave\u{0020}up\u{0020}their\u{0020}lives.\n\nWhen\u{0020}rescue\u{0020}teams\u{0020}of\u{0020}Aegis\u{0020}arrived,\u{0020}the\u{0020}only\u{0020}survivors\u{0020}were\u{0020}those\u{0020}kids,\u{0020}among\u{0020}them\u{0020}were\u{0020}Dolores\u{0020}and\u{0020}other\u{0020}members\u{0020}of\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad.\u{0020}And\u{0020}since\u{0020}then,\u{0020}they\u{0020}have\u{0020}oathed\u{0020}to\u{0020}protect\u{0020}this\u{0020}city\u{0020}with\u{0020}their\u{0020}\"borrowed\"\u{0020}lives.\n\nAlthough\u{0020}they\u{0020}lost\u{0020}their\u{0020}family\u{0020}members,\u{0020}those\u{0020}girls\u{0020}recovered\u{0020}from\u{0020}grievance\u{0020}shortly;\u{0020}they\u{0020}helped\u{0020}and\u{0020}inspired\u{0020}each\u{0020}other\u{0020}in\u{0020}their\u{0020}lives.\u{0020}Once\u{0020}they\u{0020}became\u{0020}adults,\u{0020}they\u{0020}joined\u{0020}Aegis\u{0020}and\u{0020}started\u{0020}the\u{0020}\"3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\".\u{0020}And\u{0020}Dolores,\u{0020}being\u{0020}the\u{0020}younger\u{0020}and\u{0020}less\u{0020}Compatability\u{0020}Rate\u{0020}member\u{0020}of\u{0020}the\u{0020}team,\u{0020}has\u{0020}been\u{0020}taken\u{0020}good\u{0020}care\u{0020}of.\u{0020}She\u{0020}returned\u{0020}their\u{0020}kindness\u{0020}by\u{0020}doing\u{0020}things\u{0020}that\u{0020}she\u{0020}could\u{0020}do,\u{0020}and\u{0020}she\u{0020}was\u{0020}thanking\u{0020}this\u{0020}city\u{0020}which\u{0020}gave\u{0020}her\u{0020}two\u{0020}lives.\n\nHowever,\u{0020}she\u{0020}kept\u{0020}those\u{0020}horror\u{0020}memories\u{0020}from\u{0020}that\u{0020}catastrophe…\n\nShe\u{0020}was\u{0020}extremely\u{0020}afraid\u{0020}that\u{0020}the\u{0020}same\u{0020}thing\u{0020}might\u{0020}happen\u{0020}again\u{0020}to\u{0020}her,\u{0020}and\u{0020}she\u{0020}may\u{0020}lose\u{0020}her\u{0020}peaceful\u{0020}life\u{0020}as\u{0020}well\u{0020}as\u{0020}a\u{0020}future\u{0020}with\u{0020}her\u{0020}friends.\u{0020}She's\u{0020}afraid\u{0020}of\u{0020}becoming\u{0020}the\u{0020}\"abandoned\u{0020}one\".", "0", "0", "0", "0", 10008, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}多洛莉丝出生于多瑙地区的港口都市萨尔市。正如她自己所说，萨尔是一座自古一来便多灾多难的城市，在原罪还没入侵前便饱受海啸侵扰。这铸成了萨尔人不屈不挠，敢于奉献的优良品格。虽然现如今在艾吉斯对这座城市的改造与扩建下，海啸对于萨尔人来说已经变得陌生了，但是萨尔人们依旧具备着这些刻在基因里的品格。\n\u{1000}\u{1000}十年前，灾难再一次摧毁了萨尔市，名为原罪的生物第一次入侵了这里。年幼的多洛莉丝被困在地铁之中，和她一起被困住的还有地铁上所有的乘客。随着时间一点点流逝，所剩下的食物与水渐渐跟不上供求，于是大人们做了一个重要的决定。为了给被困的孩子们，给这些未来重铸萨尔的希望争取到活下去的机会，他们将食物与水让给了孩子们，而舍弃了自己的生命。\n\u{1000}\u{1000}最后当艾吉斯的搜救部队赶到时存活下来的只有孩子们了，而多洛莉丝和Third\u{1000}Research\u{1000}Laboratory防卫班的成员们也在其中，也就是那个时候，她们约定好了，今后一定要用这条借来的生命守护住这座城市。\n\u{1000}\u{1000}在灾难中失去了亲人，伙伴的女孩们很快就从悲伤中恢复过来，她们在今后的生活中扶持着，鼓励着彼此。最后在成年之际，加入了艾吉斯，并成立了Third\u{1000}Research\u{1000}Laboratory防卫班。而年纪较小适格率又低的多洛莉丝自然一路上受到了大家不少的关照。她也一直以自己能做到的方式回报着大家……回报着养育了她，并给予了她两次生命的这座城市。\n\u{1000}\u{1000}只是，在她心中一直留有那次事件的阴影……\n\u{1000}\u{1000}她非常害怕同样的事情会再次发生在自己身上，非常害怕失去现如今着平和的生活以及有同伴相伴的未来。她害怕再次成为\"被留下来的人\"。"},
[600803] = {600803, 1000, "\u{0020}\u{0020}\"Navigator,\u{0020}have\u{0020}you\u{0020}heard\u{0020}of\u{0020}arctic\u{0020}terns…?\"\u{0020}That's\u{0020}her\u{0020}favorite\u{0020}animal.\u{0020}They\u{0020}fly\u{0020}40k\u{0020}kilometers\u{0020}per\u{0020}year,\u{0020}only\u{0020}to\u{0020}find\u{0020}the\u{0020}summer.\n\nFor\u{0020}the\u{0020}girls,\u{0020}what's\u{0020}the\u{0020}\"summer\"\u{0020}they\u{0020}are\u{0020}looking\u{0020}for?\u{0020}What\u{0020}made\u{0020}them\u{0020}give\u{0020}up\u{0020}their\u{0020}human\u{0020}form,\u{0020}and\u{0020}why\u{0020}do\u{0020}they\u{0020}fight\u{0020}and\u{0020}protect\u{0020}risking\u{0020}their\u{0020}lives?\u{0020}Of\u{0020}course,\u{0020}abstract\u{0020}ideals\u{0020}like\u{0020}\"The\u{0020}future\u{0020}of\u{0020}Saar\"\u{0020}are\u{0020}reasonable;\u{0020}but\u{0020}in\u{0020}a\u{0020}more\u{0020}precise\u{0020}way,\u{0020}they\u{0020}did\u{0020}all\u{0020}of\u{0020}these\u{0020}for\u{0020}their\u{0020}partners,\u{0020}who\u{0020}accompany\u{0020}and\u{0020}encourage\u{0020}themselves.\n\nThe\u{0020}haze\u{0020}will\u{0020}eventually\u{0020}cover\u{0020}every\u{0020}bit\u{0020}of\u{0020}light\u{0020}one\u{0020}day,\u{0020}and\u{0020}the\u{0020}outlier\u{0020}of\u{0020}migrants\u{0020}will\u{0020}open\u{0020}her\u{0020}wings\u{0020}according\u{0020}to\u{0020}her\u{0020}heart.\u{0020}Rip\u{0020}off\u{0020}the\u{0020}pearly\u{0020}tides,\u{0020}and\u{0020}leave\u{0020}the\u{0020}sorrowful\u{0020}singing,\u{0020}crying,\u{0020}behind.\u{0020}Far\u{0020}away,\u{0020}at\u{0020}her\u{0020}destination,\u{0020}a\u{0020}lengthy,\u{0020}splendid\u{0020}summer\u{0020}that\u{0020}belongs\u{0020}to\u{0020}another\u{0020}hemisphere,\u{0020}awaits.\n\nThe\u{0020}story\u{0020}of\u{0020}Dolores\u{0020}and\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}perpetuates\u{0020}forever\u{0020}in\u{0020}Saar.", "0", "0", "0", "0", 10008, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"领航，你听说过北极燕鸥吗……\"那是多洛莉丝最喜欢的动物，一种每年都要跨越4万公里，只为追寻夏日的海鸟。\n\u{1000}\u{1000}对于少女们而言，她们想要追寻的夏日究竟是什么呢？是什么让她们愿意舍弃人类的形态，又是什么让她们拼上性命去战斗去守护？自然，像是\"萨尔的未来\"这种概念化的事物也是合情合理的，但是如果非要具现化一些的话，那估计就是那日夜陪伴着自己…鼓励着自己的同伴们吧。\n\u{1000}\u{1000}有朝一日浓雾终将遮蔽所有的光线，而离群的候鸟也将在内心的指引下再次展开双翼。划开白色的浪花，让苦难的歌声与啸鸣留在身后，在遥远的彼端，等待着她的将是那蛮长的，璀璨的，属于另一个半球的夏季。\n\u{1000}\u{1000}多洛莉丝与Third\u{1000}Research\u{1000}Laboratory防卫班的故事，将在萨尔市永远延续下去。"},
[600804] = {600804, 2000, "\u{0020}\u{0020}The\u{0020}giant\u{0020}girl\u{0020}stands\u{0020}on\u{0020}the\u{0020}beach,\u{0020}with\u{0020}tides\u{0020}gently\u{0020}touching\u{0020}her\u{0020}toes.\n\nShe\u{0020}comes\u{0020}here,\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}in\u{0020}this\u{0020}size.\n\n\"This\u{0020}is…the\u{0020}place\u{0020}that\u{0020}everyone\u{0020}used\u{0020}to\u{0020}visit\u{0020}a\u{0020}lot,\u{0020}right?\"\n\nIf\u{0020}the\u{0020}weather\u{0020}is\u{0020}good,\u{0020}with\u{0020}her\u{0020}current\u{0020}height\u{0020}she\u{0020}can\u{0020}see\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}just\u{0020}right.\n\nBut,\u{0020}that's\u{0020}not\u{0020}the\u{0020}end\u{0020}of\u{0020}her\u{0020}sight.\n\nShe's\u{0020}ready,\n\nto\u{0020}set\u{0020}sail\u{0020}for\u{0020}the\u{0020}furtherer\u{0020}destinations,\u{0020}and\u{0020}to\u{0020}the\u{0020}location\u{0020}of\u{0020}that\u{0020}person.\n\nAll\u{0020}of\u{0020}these\u{0020}are\u{0020}for\u{0020}that\u{0020}promise\u{0020}they\u{0020}made\u{0020}when\u{0020}they\u{0020}left\u{0020}each\u{0020}other.\n\n\"May\u{0020}we\u{0020}meet\u{0020}again,\u{0020}my\u{0020}Navigator.\"", "0", "0", "0", "0", 10008, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}巨大的少女站在海滩上，浪花轻吻着她的脚趾。\n\u{1000}\u{1000}她还是第一次以这种体型来到这里。\n\u{1000}\u{1000}\"这是……大家过去常来的地方吧。\"\n\u{1000}\u{1000}\u{1000}天气晴朗的话，以她现在的高度刚好能看到远处的Third\u{1000}Research\u{1000}Laboratory。\n\u{1000}\u{1000}但是，那已经不是少女视线的尽头了。\n\u{1000}\u{1000}她已经准备好了，\n\u{1000}\u{1000}向着更远，更远的对岸，以及那个人的所在之处起航。\n\u{1000}\u{1000}这一切都是为了履行当初分别时的约定：\n\u{1000}\u{1000}\"总有一天，我们还会再见面的，领航。\""},
[600900] = {600900, 0, "[Name]\u{0020}Morgan\u{0020}Le\u{0020}Fay\n[B-Day]\u{0020}April\u{0020}7\n[Compatability\u{0020}Rate]\u{0020}96％\n[Height]\u{0020}35m\n[Squad]\u{0020}Moon\u{0020}Corona\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Magic\u{0020}show", "0", "0", "0", "0", 10009, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[600901] = {600901, 100, "\u{0020}\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}is\u{0020}respectable,\u{0020}but\u{0020}that's\u{0020}irrelevant\u{0020}to\u{0020}her\u{0020}performance\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}and\u{0020}not\u{0020}because\u{0020}she's\u{0020}a\u{0020}\"potential\u{0020}synesthete\"\u{0020}and\u{0020}the\u{0020}captain\u{0020}of\u{0020}\"Moon\u{0020}Corona\"\u{0020}either.\u{0020}In\u{0020}Aegis,\u{0020}there\u{0020}is\u{0020}never\u{0020}short\u{0020}of\u{0020}people\u{0020}with\u{0020}capabilities\u{0020}and\u{0020}special\u{0020}powers.\n\nShe's\u{0020}respectable\u{0020}because\u{0020}she\u{0020}decided\u{0020}to\u{0020}join\u{0020}Aegis\u{0020}to\u{0020}help\u{0020}more\u{0020}people\u{0020}and\u{0020}her\u{0020}careful,\u{0020}considerate,\u{0020}and\u{0020}altruistic\u{0020}heart.\u{0020}With\u{0020}these\u{0020}personalities,\u{0020}she\u{0020}can\u{0020}make\u{0020}her\u{0020}squadmates,\u{0020}with\u{0020}completely\u{0020}different\u{0020}temperaments,\u{0020}follow\u{0020}her\u{0020}command\u{0020}willingly.\n\n…Most\u{0020}people\u{0020}don't\u{0020}know\u{0020}that\u{0020}Miss\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}is\u{0020}also\u{0020}a\u{0020}magician.\u{0020}In\u{0020}a\u{0020}banquet\u{0020}hosted\u{0020}by\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}of\u{0020}Aegis,\u{0020}she\u{0020}performed\u{0020}amazing\u{0020}magic\u{0020}tricks\u{0020}for\u{0020}the\u{0020}participants.\n\n\"Although\u{0020}I\u{0020}only\u{0020}met\u{0020}her\u{0020}once\u{0020}at\u{0020}an\u{0020}exchange\u{0020}party,\u{0020}I\u{0020}think,\u{0020}there's\u{0020}no\u{0020}one\u{0020}more\u{0020}beautiful\u{0020}than\u{0020}Morgan\u{0020}Le\u{0020}Fay…No,\u{0020}please\u{0020}don't\u{0020}arrest\u{0020}me,\u{0020}I\u{0020}won't\u{0020}do\u{0020}anything.\"\n\nThat's\u{0020}from\u{0020}a\u{0020}formal\u{0020}staff\u{0020}of\u{0020}Kyushu,\u{0020}now\u{0020}the\u{0020}logistic\u{0020}officer\u{0020}of\u{0020}Danube.", "0", "0", "0", "0", 10009, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[600902] = {600902, 500, "\u{0020}\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}joined\u{0020}Aegis\u{0020}7\u{0020}years\u{0020}ago,\u{0020}regarding\u{0020}her\u{0020}past\u{0020}before\u{0020}that,\u{0020}we\u{0020}only\u{0020}need\u{0020}a\u{0020}simple\u{0020}investigation,\u{0020}and\u{0020}that\u{0020}will\u{0020}be\u{0020}clear.\n\nMorgan\u{0020}Le\u{0020}Fay's\u{0020}parents\u{0020}were\u{0020}both\u{0020}magicians.\u{0020}In\u{0020}the\u{0020}peaceful\u{0020}times,\u{0020}her\u{0020}mom\u{0020}and\u{0020}dad\u{0020}were\u{0020}often\u{0020}invited\u{0020}as\u{0020}special\u{0020}guests\u{0020}to\u{0020}major\u{0020}TV\u{0020}programs.\u{0020}The\u{0020}magical\u{0020}tricks\u{0020}that\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}performed,\u{0020}without\u{0020}any\u{0020}doubt,\u{0020}must\u{0020}be\u{0020}taught\u{0020}by\u{0020}her\u{0020}parents.\n\nAs\u{0020}the\u{0020}war\u{0020}raged\u{0020}on,\u{0020}her\u{0020}parents\u{0020}were\u{0020}gradually\u{0020}out\u{0020}of\u{0020}the\u{0020}public\u{0020}eye;\u{0020}they\u{0020}also\u{0020}went\u{0020}on\u{0020}to\u{0020}stray\u{0020}because\u{0020}of\u{0020}Sins.\u{0020}But\u{0020}they\u{0020}never\u{0020}lose\u{0020}their\u{0020}enthusiasm\u{0020}about\u{0020}their\u{0020}lives\u{0020}despite\u{0020}harsh\u{0020}circumstances.\u{0020}During\u{0020}that\u{0020}period,\u{0020}they\u{0020}would\u{0020}perform\u{0020}magical\u{0020}tricks\u{0020}for\u{0020}other\u{0020}refugees\u{0020}and\u{0020}exhilarate\u{0020}them.\u{0020}When\u{0020}they\u{0020}finally\u{0020}settled\u{0020}down,\u{0020}they\u{0020}often\u{0020}helped\u{0020}their\u{0020}neighbors\u{0020}and\u{0020}friends\u{0020}and\u{0020}built\u{0020}their\u{0020}new\u{0020}homes\u{0020}together.\n\nMorgan\u{0020}Le\u{0020}Fay's\u{0020}Angel-like\u{0020}personality\u{0020}was\u{0020}the\u{0020}treasure\u{0020}cultivated\u{0020}by\u{0020}such\u{0020}a\u{0020}family.\n\nBut,\u{0020}there's\u{0020}one\u{0020}thing\u{0020}she\u{0020}cares\u{0020}about\u{0020}a\u{0020}lot.\n\nFor\u{0020}members\u{0020}of\u{0020}Moon\u{0020}Corona,\u{0020}all\u{0020}of\u{0020}them\u{0020}were\u{0020}tagged\u{0020}as\u{0020}\"potential\u{0020}synesthetes\".\n\nSo,\u{0020}since\u{0020}when\u{0020}did\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}acquire\u{0020}the\u{0020}ability\u{0020}of\u{0020}Synesthesia?\n\nWe\u{0020}asked\u{0020}her\u{0020}parents\u{0020}and\u{0020}her\u{0020}schoolmates,\u{0020}but\u{0020}we\u{0020}couldn't\u{0020}get\u{0020}a\u{0020}clear\u{0020}answer.\n\nIn\u{0020}their\u{0020}minds,\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}is\u{0020}no\u{0020}different\u{0020}from\u{0020}any\u{0020}others.\u{0020}As\u{0020}the\u{0020}closest\u{0020}people\u{0020}to\u{0020}her,\u{0020}their\u{0020}words\u{0020}have\u{0020}a\u{0020}certain\u{0020}amount\u{0020}of\u{0020}credibility.\u{0020}So,\u{0020}we\u{0020}concluded\u{0020}that\u{0020}she\u{0020}joined\u{0020}Aegis\u{0020}shortly\u{0020}after\u{0020}she\u{0020}acquired\u{0020}Synesthesia.\n\nMorgan\u{0020}Le\u{0020}Fay\u{0020}joined\u{0020}Aegis\u{0020}7\u{0020}years\u{0020}ago.\u{0020}It\u{0020}looks\u{0020}like,\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}Aegis\u{0020}also\u{0020}took\u{0020}that\u{0020}navigator.\n\nHere's\u{0020}my\u{0020}guess:\n\nThe\u{0020}accident\u{0020}that\u{0020}happened\u{0020}7\u{0020}years\u{0020}ago,\u{0020}let\u{0020}that\u{0020}navigator\u{0020}become\u{0020}a\u{0020}\"Synesthete\",\u{0020}but\u{0020}its\u{0020}effect\u{0020}didn't\u{0020}stop\u{0020}there,\u{0020}it\u{0020}also\u{0020}turned\u{0020}several\u{0020}girls,\u{0020}including\u{0020}Morgan\u{0020}Le\u{0020}Fay,\u{0020}into\u{0020}\"potential\u{0020}synesthetes\".\u{0020}To\u{0020}monitor\u{0020}these\u{0020}\"potential\u{0020}synesthetes\",\u{0020}Aegis\u{0020}took\u{0020}them\u{0020}as\u{0020}well,\u{0020}and\u{0020}established\u{0020}\"Moon\u{0020}Corona\".\n\nHmm…will\u{0020}they\u{0020}delete\u{0020}this\u{0020}part?", "0", "0", "0", "0", 10009, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[600903] = {600903, 1000, "\u{0020}\u{0020}Morgan\u{0020}Le\u{0020}Fay's\u{0020}popularity\u{0020}among\u{0020}Danube\u{0020}is\u{0020}always\u{0020}high.\n\nThat's\u{0020}partly\u{0020}because\u{0020}not\u{0020}much\u{0020}of\u{0020}drivers\u{0020}in\u{0020}Danube\u{0020}are\u{0020}like\u{0020}normal\u{0020}people\u{0020}(in\u{0020}contrast,\u{0020}the\u{0020}situation\u{0020}in\u{0020}Kyushu\u{0020}is\u{0020}much\u{0020}better),\u{0020}on\u{0020}the\u{0020}other\u{0020}hand,\u{0020}she\u{0020}has\u{0020}the\u{0020}potential\u{0020}of\u{0020}becoming\u{0020}an\u{0020}idol.\n\nIn\u{0020}Danube,\u{0020}there\u{0020}are\u{0020}lots\u{0020}of\u{0020}her\u{0020}loyal\u{0020}fans,\u{0020}and\u{0020}in\u{0020}some\u{0020}extreme\u{0020}cases,\u{0020}people\u{0020}transferred\u{0020}from\u{0020}Kyushu\u{0020}to\u{0020}Danube\u{0020}just\u{0020}for\u{0020}her.\n\nBut\u{0020}although\u{0020}she\u{0020}has\u{0020}such\u{0020}an\u{0020}amount\u{0020}of\u{0020}enthusiastic\u{0020}fans,\u{0020}her\u{0020}life\u{0020}is\u{0020}not\u{0020}disrupted.\n\nThat's\u{0020}because\u{0020}normal\u{0020}people\u{0020}can't\u{0020}get\u{0020}close\u{0020}to\u{0020}her.\n\nAccording\u{0020}to\u{0020}people,\u{0020}every\u{0020}time\u{0020}someone\u{0020}tries\u{0020}to\u{0020}talk\u{0020}to\u{0020}her,\u{0020}they\u{0020}sense\u{0020}the\u{0020}atmosphere\u{0020}of\u{0020}an\u{0020}assassin\u{0020}from\u{0020}Lilith.\n\nSo\u{0020}if\u{0020}someone\u{0020}really\u{0020}decides\u{0020}to\u{0020}do\u{0020}something\u{0020}to\u{0020}Morgan\u{0020}Le\u{0020}Fay,\u{0020}they\u{0020}presumably,\u{0020}possibly…no,\u{0020}surely\u{0020}will\u{0020}be\u{0020}killed.", "0", "0", "0", "0", 10009, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[600904] = {600904, 2000, "\u{0020}\u{0020}Magic\u{0020}tricks\u{0020}are\u{0020}not\u{0020}miracles,\u{0020}they\u{0020}can't\u{0020}change\u{0020}reality.\n\nThey\u{0020}are\u{0020}just\u{0020}some\u{0020}tricks,\u{0020}relying\u{0020}on\u{0020}skills\u{0020}and\u{0020}special\u{0020}tools.\n\n\"But,\u{0020}if\u{0020}they\u{0020}can\u{0020}bring\u{0020}happiness\u{0020}to\u{0020}others,\u{0020}it\u{0020}doesn't\u{0020}matter\u{0020}if\u{0020}they\u{0020}are\u{0020}real\u{0020}or\u{0020}not.\u{0020}My\u{0020}parents,\u{0020}and\u{0020}I,\u{0020}we\u{0020}all\u{0020}agree\u{0020}to\u{0020}that.\"\n\nThe\u{0020}meaning\u{0020}of\u{0020}magical\u{0020}tricks\u{0020}is\u{0020}to\u{0020}bring\u{0020}happiness\u{0020}and\u{0020}surprises,\n\nAnd\u{0020}our\u{0020}girl,\u{0020}Morgan\u{0020}Le\u{0020}Fay,\u{0020}considers\u{0020}her\u{0020}meaning\u{0020}of\u{0020}existence\u{0020}is\u{0020}to\u{0020}protect\u{0020}this\u{0020}little\u{0020}bit\u{0020}of\u{0020}happiness\u{0020}for\u{0020}others.\n\nShe\u{0020}flies\u{0020}over\u{0020}the\u{0020}sky\u{0020}of\u{0020}Danube.\n\nFor\u{0020}her,\u{0020}those\u{0020}inhabitants\u{0020}of\u{0020}this\u{0020}land,\u{0020}are\u{0020}all\u{0020}she\u{0020}wants\u{0020}to\u{0020}guard.\n\nBut\u{0020}she\u{0020}knows,\u{0020}she\u{0020}can't\u{0020}do\u{0020}that\u{0020}on\u{0020}her\u{0020}own.\n\nShe\u{0020}looks\u{0020}at\u{0020}Navigator,\u{0020}who's\u{0020}sitting\u{0020}on\u{0020}her\u{0020}palm\u{0020}like\u{0020}a\u{0020}dumb.\n\n\"My\u{0020}Navigator,\u{0020}from\u{0020}now\u{0020}on,\u{0020}please\u{0020}take\u{0020}care\u{0020}of\u{0020}me.\"", "0", "0", "0", "0", 10009, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[601000] = {601000, 0, "[Name]\u{0020}Alaita\n[B-Day]\u{0020}July\u{0020}29\n[Compatability\u{0020}Rate]\u{0020}82％\n[Height]\u{0020}35m\n[Squad]\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Playing\u{0020}opera\u{0020}with\u{0020}rubber\u{0020}toys\u{0020}in\u{0020}her\u{0020}bathroom.", "0", "0", "0", "0", 10010, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}阿莱塔\n[B-Day]\u{1000}7月29日\n[幻化核心适格率]\u{1000}82％\n[Height]\u{1000}39m\n[部队]\u{1000}\u{1000}Third\u{1000}Research\u{1000}Laboratory防卫班\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}在浴室里和橡皮玩具一起演歌剧"},
[601001] = {601001, 100, "\u{0020}\u{0020}The\u{0020}crimson\u{0020}hairs\u{0020}are\u{0020}beautiful\u{0020}and\u{0020}charming,\u{0020}just\u{0020}like\u{0020}they\u{0020}are\u{0020}soaked\u{0020}by\u{0020}blood.\u{0020}The\u{0020}eyes\u{0020}are\u{0020}bright\u{0020}as\u{0020}diamonds,\u{0020}they\u{0020}sparkle\u{0020}like\u{0020}a\u{0020}dew.\u{0020}Miss\u{0020}Alaita\u{0020}is\u{0020}as\u{0020}beautiful\u{0020}as\u{0020}female\u{0020}protagonists\u{0020}in\u{0020}fairy\u{0020}tales,\u{0020}too\u{0020}beautiful\u{0020}that\u{0020}people\u{0020}feel\u{0020}she\u{0020}will\u{0020}never\u{0020}wither\u{0020}away.\n\nWe\u{0020}can't\u{0020}imagine\u{0020}her\u{0020}appearance\u{0020}when\u{0020}she\u{0020}gets\u{0020}old,\u{0020}and\u{0020}picturing\u{0020}her\u{0020}appearance\u{0020}when\u{0020}she\u{0020}was\u{0020}a\u{0020}little\u{0020}kid\u{0020}is\u{0020}even\u{0020}harder.\u{0020}It's\u{0020}almost\u{0020}like\u{0020}she\u{0020}was\u{0020}born\u{0020}like\u{0020}this.\n\nPeople\u{0020}in\u{0020}Saar\u{0020}express\u{0020}their\u{0020}love\u{0020}for\u{0020}Miss\u{0020}Alaita\u{0020}in\u{0020}their\u{0020}words.\u{0020}Their\u{0020}eyes\u{0020}are\u{0020}often\u{0020}attracted\u{0020}by\u{0020}Alaita\u{0020}when\u{0020}she\u{0020}is\u{0020}singing\u{0020}gently\u{0020}on\u{0020}the\u{0020}seashore.\u{0020}Since\u{0020}an\u{0020}unclarified\u{0020}day,\u{0020}\"Siren\"\u{0020}became\u{0020}Miss\u{0020}Alaita's\u{0020}\"nickname\"\u{0020}among\u{0020}her\u{0020}fans\u{0020}in\u{0020}Saar.\n\nShe\u{0020}takes\u{0020}the\u{0020}love\u{0020}and\u{0020}praise\u{0020}from\u{0020}people\u{0020}easily,\u{0020}and\u{0020}she's\u{0020}clearly\u{0020}conscious\u{0020}about\u{0020}her\u{0020}beauty,\u{0020}and\u{0020}she's\u{0020}proud\u{0020}of\u{0020}it.\n\nSurprisingly,\u{0020}Miss\u{0020}Alaita\u{0020}isn't\u{0020}an\u{0020}egoist,\u{0020}she\u{0020}acknowledges\u{0020}her\u{0020}own\u{0020}beauty\u{0020}and\u{0020}is\u{0020}proud\u{0020}of\u{0020}it,\u{0020}but\u{0020}she's\u{0020}not\u{0020}stingy\u{0020}with\u{0020}her\u{0020}praise\u{0020}towards\u{0020}other\u{0020}awesome\u{0020}things.\n\nFor\u{0020}those\u{0020}things\u{0020}(not\u{0020}only\u{0020}facial\u{0020}appearances),\u{0020}without\u{0020}any\u{0020}hesitation,\u{0020}she\u{0020}will\u{0020}express\u{0020}her\u{0020}adornment\u{0020}and\u{0020}enthusiasm\u{0020}in\u{0020}a\u{0020}straightforward\u{0020}way.", "0", "0", "0", "0", 10010, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}像是被鲜血润洗过，美丽而妖艳的红色长发，以及宛如宝石般璀璨明亮的双目，阿莱塔小姐就如童话故事中女主人公般美丽，美丽到让人觉得她绝不会凋零。\n\u{1000}\u{1000}人们无法想象她老去时的模样，更加无法想象她年幼时的相貌，仿佛她生下来就已是如此。\n\u{1000}\u{1000}萨尔市的人们对阿莱塔小姐的喜爱溢于言表。人们的目光总会被在海边轻声低吟曲子的阿莱塔小姐吸引。不知从什么时候开始，\"海妖\"成为了阿莱塔小姐在萨尔当地粉丝间的\"爱称\"。\n\u{1000}\u{1000}对于人们的喜爱与赞美，阿莱塔小姐表现得十分从容，她能够明确地意识到自己的\"美\"，并以自己的美貌为傲。\n\u{1000}\u{1000}难得的是，阿莱塔小姐并不是以自我为中心的人，她承认自己的美，以自己的美为傲，但她也不吝啬自己对其他美好事物的赞颂。\n\u{1000}\u{1000}对于那些美丽的事物（并不仅仅是容貌），她会毫不犹豫地表达自己的喜爱与热情，绝不会遮遮掩掩。"},
[601002] = {601002, 500, "\u{0020}\u{0020}After\u{0020}she\u{0020}learned\u{0020}about\u{0020}TV\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}she\u{0020}dreamt\u{0020}of\u{0020}becoming\u{0020}an\u{0020}actress.\n\n\"I\u{0020}was\u{0020}born\u{0020}to\u{0020}show\u{0020}beauty\u{0020}to\u{0020}the\u{0020}world...\u{0020}being\u{0020}on\u{0020}stage\u{0020}is\u{0020}my\u{0020}dream.\"\n\nUnfortunately,\u{0020}Miss\u{0020}Alaita\u{0020}didn't\u{0020}achieve\u{0020}her\u{0020}dream.\n\n10\u{0020}years\u{0020}ago,\u{0020}Sins\u{0020}invaded\u{0020}Saar,\u{0020}and\u{0020}that\u{0020}changed\u{0020}people's\u{0020}fate\u{0020}in\u{0020}Saar,\u{0020}and\u{0020}Alaita\u{0020}was\u{0020}one\u{0020}of\u{0020}them.\u{0020}During\u{0020}that\u{0020}havoc,\u{0020}she\u{0020}witnessed\u{0020}how\u{0020}Sins\u{0020}destroyed\u{0020}her\u{0020}city,\u{0020}the\u{0020}stage\u{0020}of\u{0020}her\u{0020}dream,\u{0020}and\u{0020}other\u{0020}beautiful\u{0020}things\u{0020}vanished\u{0020}in\u{0020}a\u{0020}blink.\u{0020}It\u{0020}was\u{0020}the\u{0020}first\u{0020}time\u{0020}she\u{0020}knew\u{0020}how\u{0020}fragile\u{0020}her\u{0020}dream\u{0020}were…\u{0020}and\u{0020}she\u{0020}was\u{0020}scared\u{0020}about\u{0020}it.\u{0020}Although\u{0020}now\u{0020}she's\u{0020}no\u{0020}longer\u{0020}there,\u{0020}she\u{0020}would\u{0020}still\u{0020}wake\u{0020}up\u{0020}because\u{0020}of\u{0020}nightmares.\n\nFortunately,\u{0020}she\u{0020}also\u{0020}witnessed\u{0020}the\u{0020}recovery\u{0020}and\u{0020}revival\u{0020}of\u{0020}Saar.\u{0020}With\u{0020}the\u{0020}help\u{0020}of\u{0020}drivers,\u{0020}Saar\u{0020}became\u{0020}vigorous\u{0020}again,\u{0020}and\u{0020}those\u{0020}figures\u{0020}who\u{0020}fought\u{0020}on\u{0020}the\u{0020}frontlines\u{0020}gave\u{0020}her\u{0020}a\u{0020}deep\u{0020}impression\u{0020}in\u{0020}her\u{0020}heart.\n\n\"If\u{0020}you\u{0020}are\u{0020}not\u{0020}powerful\u{0020}enough\u{0020}to\u{0020}guard\u{0020}those\u{0020}uneasy\u{0020}beauties,\u{0020}they\u{0020}will\u{0020}all\u{0020}become\u{0020}meaningless.\"\n\nFive\u{0020}years\u{0020}ago,\u{0020}she\u{0020}made\u{0020}a\u{0020}decision.\n\nShe\u{0020}abandoned\u{0020}her\u{0020}opportunity\u{0020}to\u{0020}become\u{0020}an\u{0020}actress\u{0020}and\u{0020}attended\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}hosted\u{0020}by\u{0020}Aegis.\n\n\"If\u{0020}you\u{0020}didn't\u{0020}pass\u{0020}that\u{0020}test,\u{0020}will\u{0020}you\u{0020}go\u{0020}back\u{0020}and\u{0020}become\u{0020}an\u{0020}actress?\"\n\n\"Of\u{0020}course…\"\u{0020}When\u{0020}the\u{0020}examiners\u{0020}of\u{0020}Aegis\u{0020}asked\u{0020}her\u{0020}that,\u{0020}she\u{0020}gave\u{0020}a\u{0020}clear\u{0020}answer,\u{0020}\"...and\u{0020}even\u{0020}if\u{0020}I\u{0020}pass\u{0020}the\u{0020}test,\u{0020}I\u{0020}will\u{0020}still\u{0020}be\u{0020}active\u{0020}on\u{0020}the\u{0020}stage\u{0020}called\u{0020}battlefield,\u{0020}as\u{0020}the\u{0020}most\u{0020}beautiful\u{0020}driver.\"\n\nAnd\u{0020}her\u{0020}performances\u{0020}in\u{0020}the\u{0020}academy\u{0020}validated\u{0020}what\u{0020}she\u{0020}said,\n\nPeople\u{0020}who\u{0020}witnessed\u{0020}how\u{0020}she\u{0020}fought\u{0020}would\u{0020}always\u{0020}be\u{0020}impressed\u{0020}by\u{0020}her\u{0020}beautiful\u{0020}postures.", "0", "0", "0", "0", 10010, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}当阿莱塔第一次接触电视时，她便梦想成为一名演员。\n\u{1000}\u{1000}\"我生来便是为了向世人展示美丽……登上舞台是我最初的梦想。\"\n\u{1000}\u{1000}遗憾的是，阿莱塔小姐没有实现自己的梦想。\n\u{1000}\u{1000}十年前，原罪入侵萨尔市，这场灾难改变了大多数萨尔人的命运，阿莱塔小姐也是其中一人。在那场灾难中，她目睹了原罪摧毁城市的过程，她所梦想的舞台以及那些其他美丽的事物都在瞬间付之一炬，她第一次意识到自己所追求之物是如此的脆弱……她对此深感恐惧，即便已经远离都市，她也常常从噩梦中被惊醒。\n\u{1000}\u{1000}不过，好在之后她也亲眼见证了萨尔市的重建，在驾驶员帮助下，萨尔市再次恢复了生机，而那些战斗在前线的身影也深深地烙印在她心中。\n\u{1000}\u{1000}\"如果没有力量去守护这份来之不易的美丽的话，那么这一切便毫无意义。\"\n\u{1000}\u{1000}在五年前，她做出了决定。\n\u{1000}\u{1000}在放弃作为演员出道的机会后，她最终选择参加了艾吉斯的驾驶员适格率测试。\n\u{1000}\u{1000}\"如果测试没有通过的话，你还会回去做演员吗？\"\n\u{1000}\u{1000}\"当然——\"当被艾吉斯的测验人员这么提问时，她回答得很干脆，\"——而且就算是通过了测试，我也会继续作为最美的驾驶员活跃在战场这个舞台。\"\n\u{1000}\u{1000}之后阿莱塔小姐在学院中的表现也印证了自己所说的话。\n\u{1000}\u{1000}亲眼观看过其战斗的人无不被她美丽姿态所折服。"},
[601003] = {601003, 1000, "\u{0020}\u{0020}On\u{0020}that\u{0020}day\u{0020}when\u{0020}Miss\u{0020}Alaita\u{0020}graduated,\u{0020}Envy\u{0020}invaded\u{0020}Saar.\u{0020}They\u{0020}happened\u{0020}almost\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}and\u{0020}just\u{0020}like\u{0020}the\u{0020}last\u{0020}time,\u{0020}tragedies\u{0020}happened\u{0020}before\u{0020}she\u{0020}could\u{0020}do\u{0020}anything…\n\nBut\u{0020}this\u{0020}time,\u{0020}she\u{0020}didn't\u{0020}panic.\u{0020}After\u{0020}Sins\u{0020}were\u{0020}driven\u{0020}out,\u{0020}she\u{0020}instantly\u{0020}joined\u{0020}the\u{0020}regrouping\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad.\u{0020}And\u{0020}on\u{0020}the\u{0020}day\u{0020}she\u{0020}joined,\u{0020}she\u{0020}received\u{0020}a\u{0020}special\u{0020}gift.\u{0020}That\u{0020}sword,\u{0020}although\u{0020}it\u{0020}was\u{0020}an\u{0020}old\u{0020}model,\u{0020}Alaita\u{0020}loves\u{0020}it\u{0020}because\u{0020}the\u{0020}same\u{0020}model\u{0020}was\u{0020}used\u{0020}by\u{0020}heroes.\n\n\"Thank\u{0020}you\u{0020}so\u{0020}much,\u{0020}for\u{0020}guarding\u{0020}our\u{0020}excellent\u{0020}Saar.\"", "0", "0", "0", "0", 10010, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}在阿莱塔小姐毕业的当天，名为嫉妒的原罪入侵了萨尔市。两件事近乎发生在同一时间，一切亦如过去那样，她根本来不及做些什么的时候，悲剧就已经发生了……\n\u{1000}\u{1000}不过这次，她并没有再感到恐惧。在原罪被驱散之后，她义无反顾地加入了正在重建中的Third\u{1000}Research\u{1000}Laboratory防卫班。而在她入队的当天，也收到了一份特殊的礼物。那柄剑，虽说款式稍微有些老旧，不过因为是英雄使用过的款式，所以深得阿莱塔的喜爱。\n\u{1000}\u{1000}\"谢谢你们，守护住了美丽的萨尔。\""},
[601004] = {601004, 2000, "\u{0020}\u{0020}\"Navigator,\u{0020}I\u{0020}am\u{0020}an\u{0020}activist.\"\n\nWhen\u{0020}looking\u{0020}at\u{0020}the\u{0020}setting\u{0020}sun\u{0020}on\u{0020}the\u{0020}horizon\u{0020}together,\u{0020}the\u{0020}girl\u{0020}said\u{0020}that\u{0020}suddenly.\n\nThe\u{0020}smell\u{0020}of\u{0020}the\u{0020}sea\u{0020}mixes\u{0020}with\u{0020}the\u{0020}shine.\u{0020}Illuminated\u{0020}by\u{0020}this\u{0020}light\u{0020}from\u{0020}Saar,\u{0020}her\u{0020}face\u{0020}becomes\u{0020}more\u{0020}pretty\u{0020}and\u{0020}charming.\n\nBut\u{0020}what\u{0020}really\u{0020}attracted\u{0020}Navigator,\u{0020}is\u{0020}that\u{0020}old-fashioned\u{0020}weapon\u{0020}in\u{0020}the\u{0020}hand\u{0020}of\u{0020}\"Siren\".\n\n\"I\u{0020}deeply\u{0020}love\u{0020}every\u{0020}beauty\u{0020}in\u{0020}this\u{0020}world,\u{0020}so,\u{0020}I\u{0020}won't\u{0020}wait,\u{0020}I\u{0020}won't\u{0020}hope\u{0020}that\u{0020}others\u{0020}would\u{0020}protect\u{0020}them.\"\n\nThe\u{0020}girl\u{0020}is\u{0020}standing\u{0020}tight\u{0020}on\u{0020}the\u{0020}seashore,\u{0020}when\u{0020}people\u{0020}raise\u{0020}her\u{0020}heads\u{0020}and\u{0020}look\u{0020}at\u{0020}her,\u{0020}they\u{0020}will\u{0020}realize,\u{0020}she's\u{0020}not\u{0020}only\u{0020}a\u{0020}\"Charming\u{0020}Siren\".\n\nBut\u{0020}also\u{0020}a\u{0020}driver\u{0020}with\u{0020}glorious\u{0020}duties.\n\n\"Our\u{0020}time\u{0020}needs\u{0020}us\u{0020}to\u{0020}take\u{0020}on\u{0020}more\u{0020}duties,\u{0020}my\u{0020}Navigator.\"", "0", "0", "0", "0", 10010, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"领航，我是行动派。\"\n\u{1000}\u{1000}一起于海边眺望海平线尽头下沉的夕阳时，少女突然说道。\n\u{1000}\u{1000}海水的气味混在了落日的霞光中，在这道来自萨尔的光映照下，少女的脸庞更加美艳动人。\n\u{1000}\u{1000}可真正吸引着领航视点的，是\"海妖\"手中的那把旧式武器。\n\u{1000}\u{1000}\"我深爱着世间所有美丽的事物，所以，我不会等待，不会祈求着别人来保护它们。\"\n\u{1000}\u{1000}在夕阳下卓立于海岸上的少女，当人们仰望她时，便意识到了，她并不只是\"美丽的海妖\"。\n\u{1000}\u{1000}她还是一名肩负着光荣使命的驾驶员。\n\u{1000}\u{1000}\"这个时代需要我们背负更多的使命，领航。\""},
[601100] = {601100, 0, "[Name]\u{0020}Jacksui\n[B-Day]\u{0020}Dec\u{0020}28\n[Compatability\u{0020}Rate]\u{0020}85%\n[Height]\u{0020}32m\n[Squad]\u{0020}Ninja\u{0020}Group\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}The\u{0020}movie\u{0020}that\u{0020}embodies\u{0020}the\u{0020}efforts\u{0020}and\u{0020}dedication\u{0020}of\u{0020}the\u{0020}crew", "0", "0", "0", "0", 10011, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}弱水\n[B-Day]\u{1000}12月28日\n[幻化核心适格率]\u{1000}85%\n[Height]\u{1000}32m\n[部队]\u{1000}忍心社\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}注入主创团队心血的电影"},
[601101] = {601101, 100, "\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group,\u{0020}like\u{0020}the\u{0020}others,\u{0020}\"Jacksui\"\u{0020}is\u{0020}merely\u{0020}her\u{0020}code\u{0020}name\u{0020}when\u{0020}carrying\u{0020}out\u{0020}tasks,\u{0020}and\u{0020}no\u{0020}one\u{0020}knows\u{0020}her\u{0020}true\u{0020}identity.\n\nThe\u{0020}tasks\u{0020}of\u{0020}Jacksui,\u{0020}or\u{0020}rather\u{0020}those\u{0020}of\u{0020}the\u{0020}\"Ninja\u{0020}Group\",\u{0020}are\u{0020}mostly\u{0020}to\u{0020}investigate\u{0020}the\u{0020}targets,\u{0020}approach\u{0020}them,\u{0020}and,\u{0020}when\u{0020}necessary,\u{0020}kill\u{0020}the\u{0020}targets\u{0020}ruthlessly.\n\nPerhaps,\u{0020}the\u{0020}number\u{0020}of\u{0020}humans\u{0020}who\u{0020}died\u{0020}at\u{0020}their\u{0020}hands\u{0020}is\u{0020}greater\u{0020}than\u{0020}the\u{0020}Sins\u{0020}they\u{0020}have\u{0020}killed.\n\nAccording\u{0020}to\u{0020}the\u{0020}information\u{0020}provided\u{0020}by\u{0020}the\u{0020}same\u{0020}special\u{0020}operations\u{0020}force\u{0020}\"Fuurinkazan\",\u{0020}Jacksui\u{0020}is\u{0020}usually\u{0020}a\u{0020}child\u{0020}with\u{0020}a\u{0020}cheerful\u{0020}and\u{0020}lively\u{0020}personality\u{0020}and\u{0020}a\u{0020}refreshing\u{0020}smile.\n\n.....Really?", "0", "0", "0", "0", 10011, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}忍心社的成员之一，和其他成员一样，\"弱水\"仅仅只是她执行任务时的代号，无人知晓她的真实身份。\n\u{1000}\u{1000}弱水的任务，或者说\"忍心社\"的任务，大多是调查目标，接近目标，并且在必要时，毫不留情地将目标杀死。\n\u{1000}\u{1000}也许，死在她们手上的人类，比她们杀过的原罪还多。\n\u{1000}\u{1000}根据同为特殊作战部队\"风林火山\"提供的信息，弱水平时是一个性格开朗活泼，有着清爽笑容的孩子。"},
[601102] = {601102, 500, "\u{0020}\u{0020}Like\u{0020}other\u{0020}members\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group,\u{0020}we\u{0020}cannot\u{0020}learn\u{0020}about\u{0020}her\u{0020}past\u{0020}by\u{0020}directly\u{0020}communicating\u{0020}with\u{0020}her.\u{0020}However,\u{0020}I\u{0020}think\u{0020}if\u{0020}we\u{0020}recorded\u{0020}Jacksui's\u{0020}information\u{0020}completely,\u{0020}then\u{0020}surely\u{0020}this\u{0020}file\u{0020}would\u{0020}never\u{0020}be\u{0020}kept.\n\nWe\u{0020}might\u{0020}even\u{0020}be\u{0020}killed.\n\nThe\u{0020}Ninja\u{0020}Group\u{0020}is\u{0020}an\u{0020}\"invisible\u{0020}organization\"\u{0020}like\u{0020}so.\n\nTherefore,\u{0020}we\u{0020}can\u{0020}only\u{0020}collect\u{0020}urban\u{0020}legends\u{0020}and\u{0020}rumors\u{0020}to\u{0020}complete\u{0020}Jacksui's\u{0020}personal\u{0020}information\u{0020}file.\n\nFirst,\u{0020}one\u{0020}thing\u{0020}can\u{0020}be\u{0020}affirmed\u{0020}-\u{0020}Jacksui.\u{0020}She\u{0020}has\u{0020}to\u{0020}rely\u{0020}on\u{0020}a\u{0020}special\u{0020}device\u{0020}for\u{0020}her\u{0020}eyes\u{0020}to\u{0020}have\u{0020}normal\u{0020}vision.\u{0020}In\u{0020}other\u{0020}words,\u{0020}she\u{0020}is\u{0020}blind.\n\nRegarding\u{0020}the\u{0020}reason\u{0020}for\u{0020}Jacksui's\u{0020}blindness,\u{0020}some\u{0020}people\u{0020}say\u{0020}that\u{0020}it\u{0020}was\u{0020}a\u{0020}fever\u{0020}in\u{0020}her\u{0020}childhood\u{0020}that\u{0020}damaged\u{0020}her\u{0020}optic\u{0020}nerve\u{0020}and\u{0020}led\u{0020}to\u{0020}her\u{0020}blindness.\n\nThere\u{0020}is\u{0020}also\u{0020}another\u{0020}\"truth\"\u{0020}with\u{0020}a\u{0020}flavor\u{0020}of\u{0020}conspiracy\u{0020}theory\u{0020}-\u{0020}she,\u{0020}who\u{0020}once\u{0020}had\u{0020}a\u{0020}prominent\u{0020}background,\u{0020}was\u{0020}implicated\u{0020}when\u{0020}her\u{0020}father\u{0020}was\u{0020}in\u{0020}a\u{0020}business\u{0020}struggle\u{0020}with\u{0020}his\u{0020}peers,\u{0020}was\u{0020}poisoned\u{0020}by\u{0020}her\u{0020}father's\u{0020}competitors,\u{0020}and\u{0020}eventually\u{0020}lost\u{0020}her\u{0020}eyesight.\n\nThe\u{0020}person\u{0020}who\u{0020}poisoned\u{0020}her\u{0020}seems\u{0020}to\u{0020}be\u{0020}her\u{0020}former\u{0020}close\u{0020}friend...\n\nThe\u{0020}help\u{0020}of\u{0020}AEGIS\u{0020}\"restored\"\u{0020}her\u{0020}eyesight.\u{0020}In\u{0020}exchange,\u{0020}she\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}Aegis.\n\nLater,\u{0020}Jacksui\u{0020}was\u{0020}selected\u{0020}to\u{0020}become\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}\"Ninja\u{0020}Group\".\n\nHowever,\u{0020}no\u{0020}matter\u{0020}which\u{0020}statement\u{0020}it\u{0020}is,\u{0020}they\u{0020}are\u{0020}all\u{0020}just\u{0020}\"rumors\"\u{0020}and\u{0020}cannot\u{0020}be\u{0020}regarded\u{0020}as\u{0020}facts.\n\nBesides,\u{0020}regarding\u{0020}Jacksui's\u{0020}past\u{0020}-\u{0020}whether\u{0020}Jacksui\u{0020}was\u{0020}an\u{0020}ordinary\u{0020}girl\u{0020}of\u{0020}humble\u{0020}origin\u{0020}or\u{0020}really\u{0020}the\u{0020}heir\u{0020}of\u{0020}some\u{0020}noble,\u{0020}it\u{0020}meaningless\u{0020}now.\n\nBecause\u{0020}it's\u{0020}gone,\u{0020}her\u{0020}hometown\u{0020}that\u{0020}carried\u{0020}her\u{0020}past\u{0020}-\u{0020}under\u{0020}the\u{0020}attack\u{0020}of\u{0020}Sin,\u{0020}completely\u{0020}disappeared\u{0020}from\u{0020}the\u{0020}map.\u{0020}Even\u{0020}if\u{0020}one\u{0020}looks\u{0020}for\u{0020}it\u{0020}with\u{0020}the\u{0020}map\u{0020}before\u{0020}the\u{0020}turmoil,\u{0020}one\u{0020}might\u{0020}only\u{0020}find\u{0020}the\u{0020}ruins\u{0020}like\u{0020}a\u{0020}crater.\n\nNow\u{0020}she\u{0020}has\u{0020}no\u{0020}past.\n\nIt\u{0020}is\u{0020}precisely\u{0020}because\u{0020}of\u{0020}this\u{0020}that\u{0020}she\u{0020}can\u{0020}become\u{0020}the\u{0020}sharp\u{0020}blade\u{0020}in\u{0020}the\u{0020}hands\u{0020}of\u{0020}Aegis\u{0020}without\u{0020}distraction.", "0", "0", "0", "0", 10011, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}和其他忍心社的成员一样，我们无法通过与本人直接沟通来获悉她过去的经历。不过，我想如果我们完整地记录了弱水的信息，那么想必这份档案就绝不会被留存下来。\n\u{1000}\u{1000}我们甚至会被杀掉。\n\u{1000}\u{1000}忍心社就是这样的组织，一个\"隐形的组织\"。\n\u{1000}\u{1000}因此，我们只能收集都市传说，流传在人与人之间的传言，以这样的方式，建立弱水的个人情报档案。\n\u{1000}\u{1000}首先可以肯定一件事是——弱水。她必须要依靠眼部的特殊装置才能拥有常人的视力。换句话说，她是一位盲人。\n\u{1000}\u{1000}关于弱水失明的原因，有人说，是童年时的一次高烧，破坏了她的视觉神经，导致了她的失明。\n\u{1000}\u{1000}也有着另一个带着阴谋论气味的\"真相\"——曾经有着显赫出身的她，在父亲与同行的商业斗争时，受到牵连，遭到父亲的竞争对手下毒，最终双目失明。\n\u{1000}\u{1000}对她下毒的人，似乎是她曾经的挚友……\n\u{1000}\u{1000}艾吉斯的帮助让她\"恢复\"了视力，作为恢复视力的交换，她成为了艾吉斯的一员。\n\u{1000}\u{1000}之后，弱水被选中了成为\"忍心社\"的队员。\n\u{1000}\u{1000}不过，不管哪一个说法，都是\"流言蜚语\"罢了，并不能当做事实看待。\n\u{1000}\u{1000}另外，关于弱水以前的事——无论弱水是一名出身平凡的少女，又或者真的是某个贵族的继承人，事到如今都已经没有意义了。\n\u{1000}\u{1000}因为消失了，承载着她过去的，她的故乡——在原罪的袭击下，从地图上彻底消失了。即使捧着动乱前的地图去寻找，恐怕也只能找到宛如陨石坑的遗迹吧。\n\u{1000}\u{1000}现在的她已经没有过去。\n\u{1000}\u{1000}正是因为如此，所有她才会心无旁骛地成为艾吉斯手中的利刃吧。"},
[601103] = {601103, 1000, "\u{0020}\u{0020}\"The\u{0020}'Ninja\u{0020}Group'\u{0020}is\u{0020}not\u{0020}an\u{0020}organization\u{0020}that\u{0020}one\u{0020}can\u{0020}enter\u{0020}casually.\"\n\nWithout\u{0020}a\u{0020}certain\u{0020}level\u{0020}of\u{0020}awareness\u{0020}-\u{0020}the\u{0020}kind\u{0020}that\u{0020}absolutely\u{0020}does\u{0020}not\u{0020}question\u{0020}the\u{0020}correctness\u{0020}of\u{0020}the\u{0020}task,\u{0020}nor\u{0020}doubts\u{0020}whether\u{0020}they\u{0020}do\u{0020}is\u{0020}right\u{0020}or\u{0020}wrong,\u{0020}and\u{0020}regards\u{0020}the\u{0020}execution\u{0020}of\u{0020}the\u{0020}task\u{0020}as\u{0020}the\u{0020}only\u{0020}truth.\u{0020}Without\u{0020}this\u{0020}kind\u{0020}of\u{0020}awareness,\u{0020}it\u{0020}is\u{0020}impossible\u{0020}to\u{0020}become\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group.\n\nJacksui\u{0020}has\u{0020}such\u{0020}awareness.\u{0020}And\u{0020}that's\u{0020}why\u{0020}the\u{0020}strict\u{0020}and\u{0020}demanding\u{0020}captain\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group,\u{0020}who\u{0020}prioritizes\u{0020}completing\u{0020}tasks\u{0020}over\u{0020}life,\u{0020}would\u{0020}agree\u{0020}to\u{0020}let\u{0020}her\u{0020}become\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group.\n\nBut\u{0020}this\u{0020}kind\u{0020}of\u{0020}awareness,\u{0020}if\u{0020}not\u{0020}nurtured\u{0020}by\u{0020}corresponding\u{0020}\"experiences\",\u{0020}I\u{0020}think\u{0020}it\u{0020}is\u{0020}unreasonable.\u{0020}Unfortunately,\u{0020}we\u{0020}really\u{0020}don't\u{0020}know\u{0020}exactly\u{0020}what\u{0020}she\u{0020}has\u{0020}experienced\u{0020}-\u{0020}this\u{0020}statement\u{0020}can\u{0020}apply\u{0020}to\u{0020}every\u{0020}member\u{0020}of\u{0020}the\u{0020}\"Ninja\u{0020}Group\".\n\nAlthough\u{0020}Jacksui\u{0020}looks\u{0020}like\u{0020}a\u{0020}delicate\u{0020}girl,\u{0020}when\u{0020}she\u{0020}really\u{0020}appears\u{0020}in\u{0020}front\u{0020}of\u{0020}people\u{0020}(I\u{0020}was\u{0020}fortunate\u{0020}to\u{0020}witness\u{0020}her\u{0020}once\u{0020}during\u{0020}a\u{0020}mission),\u{0020}I\u{0020}think\u{0020}no\u{0020}one\u{0020}will\u{0020}doubt\u{0020}whether\u{0020}this\u{0020}girl\u{0020}can\u{0020}complete\u{0020}the\u{0020}task.", "0", "0", "0", "0", 10011, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"忍心社\"并不是随随便便就能进入的组织。\n\u{1000}\u{1000}没有一定的觉悟——那种绝对不会质疑任务的正确性，也不会怀疑自己所作所为究竟是否正确，将执行任务奉为唯一真理的觉悟，没有这种程度的觉悟，是无法成为忍心社一员的。\n\u{1000}\u{1000}弱水的确有这样的觉悟。正是因为如此，那位待人严格苛刻，将完成任务置于生命之上的忍心社队长，才会同意她成为忍心社的一员吧。\n\u{1000}\u{1000}但这份觉悟，如果没有与之相符的\"经历\"来孕育，我认为是不合理的。遗憾的是，我们实在不知道她到底经历过什么——这一段话，能适用于每位\"忍心社\"的成员。\n\u{1000}\u{1000}尽管弱水看上去是一名娇弱的少女，但当她真正出现在人们（我有幸目睹过一次执行任务中的她）面前时，我想，没人会去怀疑这名少女能否完成任务。"},
[601104] = {601104, 2000, "\u{0020}\u{0020}A\u{0020}river\u{0020}in\u{0020}which\u{0020}not\u{0020}even\u{0020}a\u{0020}single\u{0020}leaf\u{0020}can\u{0020}float\u{0020}is\u{0020}called\u{0020}weak\u{0020}flow.\n\nAnd\u{0020}that\u{0020}is\u{0020}the\u{0020}meaning\u{0020}behind\u{0020}the\u{0020}code\u{0020}name\u{0020}of\u{0020}that\u{0020}young\u{0020}girl.\n\n\"In\u{0020}the\u{0020}past,\u{0020}walking\u{0020}along\u{0020}this\u{0020}river,\u{0020}one\u{0020}could\u{0020}see\u{0020}my\u{0020}hometown...\u{0020}\"\n\nFrom\u{0020}a\u{0020}distance,\u{0020}her\u{0020}words\u{0020}could\u{0020}be\u{0020}heard.\n\nShe\u{0020}stood\u{0020}in\u{0020}the\u{0020}middle\u{0020}of\u{0020}the\u{0020}two\u{0020}banks,\u{0020}and\u{0020}the\u{0020}turbulent\u{0020}river\u{0020}water\u{0020}reached\u{0020}her\u{0020}knees.\n\n\"However,\u{0020}it\u{0020}has\u{0020}disappeared\u{0020}now.\u{0020}The\u{0020}place\u{0020}that\u{0020}belongs\u{0020}to\u{0020}me\u{0020}-\u{0020}can't\u{0020}be\u{0020}found\u{0020}anywhere\u{0020}anymore.\u{0020}\"\n\nShe\u{0020}turned\u{0020}her\u{0020}head\u{0020}and\u{0020}looked\u{0020}at\u{0020}me,\n\nThe\u{0020}face\u{0020}under\u{0020}the\u{0020}eye\u{0020}mask\u{0020}is\u{0020}smiling.\n\n\"If\u{0020}I\u{0020}could\u{0020}have\u{0020}met\u{0020}Navigator\u{0020}earlier,\u{0020}perhaps\u{0020}my\u{0020}life\u{0020}would\u{0020}be\u{0020}different\u{0020}from\u{0020}now...\u{0020}\"", "0", "0", "0", "0", 10011, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}连一片树叶也无法浮起的河流，人们称之为弱水，\n\u{1000}\u{1000}而这正是那位少女的代号。\n\u{1000}\u{1000}\"以前，顺着这条江走，就能看到我的故乡……\"\n\u{1000}\u{1000}远远地，能听见她说的这段话，\n\u{1000}\u{1000}她站在两岸的中间，汹涌的江水仅没过她的膝盖。\n\u{1000}\u{1000}\"不过，现在已经消失了吧。属于我的地方——已经哪里都找不到了。\"\n\u{1000}\u{1000}她回过头，看向我，\n\u{1000}\u{1000}眼罩下的脸，正在笑。\n\u{1000}\u{1000}\"要是能早一点遇到领航，或许我的人生就会和现在不同吧……\""},
[601200] = {601200, 0, "[Name]\u{0020}Gloria\n[B-Day]\u{0020}Sep\u{0020}6\n[Compatability\u{0020}Rate]\u{0020}84%\n[Height]\u{0020}36m\n[Squad]\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Iridium\u{0020}cap\u{0020}cloud;\u{0020}Aurora", "0", "0", "0", "0", 10012, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}格洛丽亚\n[B-Day]\u{1000}9月6日\n[幻化核心适格率]\u{1000}84%\n[\u{1000}巨大化身高]\u{1000}37m\n[部队]\u{1000}Third\u{1000}Research\u{1000}Laboratory防卫班\n[\u{1000}隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}虹彩幞状云\u{1000}极光"},
[601201] = {601201, 100, "\u{0020}\u{0020}Miss\u{0020}Gloria\u{0020}is\u{0020}a\u{0020}new\u{0020}member\u{0020}of\u{0020}the\u{0020}reorganized\u{0020}\"3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\".\u{0020}After\u{0020}graduating\u{0020}from\u{0020}the\u{0020}driver\u{0020}academy,\u{0020}she\u{0020}was\u{0020}assigned\u{0020}to\u{0020}the\u{0020}\"3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\"\u{0020}which\u{0020}was\u{0020}under\u{0020}reconstruction\u{0020}and\u{0020}worked\u{0020}with\u{0020}the\u{0020}captain,\u{0020}Dolores.\n\nAccording\u{0020}to\u{0020}Miss\u{0020}Gloria's\u{0020}former\u{0020}classmates,\u{0020}Miss\u{0020}Gloria\u{0020}is\u{0020}an\u{0020}indifferent\u{0020}person.\u{0020}In\u{0020}their\u{0020}impression,\u{0020}Miss\u{0020}Gloria\u{0020}has\u{0020}a\u{0020}naturally\u{0020}cold\u{0020}face\u{0020}that\u{0020}makes\u{0020}people\u{0020}dare\u{0020}not\u{0020}approach.\n\nHowever,\u{0020}the\u{0020}Miss\u{0020}Gloria\u{0020}in\u{0020}Dolores's\u{0020}mouth\u{0020}is\u{0020}a\u{0020}gentle\u{0020}girl\u{0020}who\u{0020}is\u{0020}polite,\u{0020}dignified\u{0020}and\u{0020}elegant.\n\nIn\u{0020}Dolores's\u{0020}opinion,\u{0020}Miss\u{0020}Gloria\u{0020}is\u{0020}careful\u{0020}and\u{0020}organized\u{0020}in\u{0020}doing\u{0020}things.\u{0020}When\u{0020}addressing\u{0020}Dolores\u{0020}who\u{0020}is\u{0020}younger\u{0020}than\u{0020}herself,\u{0020}she\u{0020}still\u{0020}respectfully\u{0020}calls\u{0020}Dolores\u{0020}\"senior\".\n\nMiss\u{0020}Gloria\u{0020}shows\u{0020}completely\u{0020}opposite\u{0020}personalities\u{0020}in\u{0020}different\u{0020}people's\u{0020}descriptions.\u{0020}She\u{0020}is\u{0020}like\u{0020}some\u{0020}kind\u{0020}of\u{0020}rare\u{0020}metal\u{0020}that\u{0020}exhibits\u{0020}different\u{0020}properties\u{0020}depending\u{0020}on\u{0020}the\u{0020}environment.\n\nI\u{0020}guess\u{0020}that\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}her\u{0020}reactions\u{0020}perhaps\u{0020}were\u{0020}not\u{0020}based\u{0020}on\u{0020}her\u{0020}true\u{0020}inner\u{0020}thoughts,\n\nBut\u{0020}it\u{0020}was\u{0020}the\u{0020}\"standard\u{0020}answer\"\u{0020}someone\u{0020}told\u{0020}her.", "0", "0", "0", "0", 10012, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}格洛丽亚小姐是重组后的\"Third\u{1000}Research\u{1000}Laboratory防卫班\"的新成员。从驾驶员学院毕业后，她便被分进正在重建中的\"Third\u{1000}Research\u{1000}Laboratory防卫班\"，与队长多洛莉丝共事。\n\u{1000}\u{1000}根据格洛丽亚小姐曾经的同学所描述，格洛丽亚小姐是一个感情淡薄的人，在她们的印象中，格洛丽亚小姐有一张天生的冷漠脸，让人不敢贸然亲近。\n\u{1000}\u{1000}可是，多洛莉丝口中的格洛丽亚小姐，却是一个彬彬有礼、端庄文雅的温柔少女。\n\u{1000}\u{1000}在多洛莉丝看来，格洛丽亚小姐做事细心且有条理。称呼年龄小于自己的多洛莉丝时，依然会尊敬地称呼多洛莉丝为\"前辈\"。\n\u{1000}\u{1000}格洛丽亚小姐在不同人的描述中呈现出截然相反的个性，她就像某种会因环境不同而表现出不同性质的稀有金属。\n\u{1000}\u{1000}我猜，她所做出来的绝大多数反应，或许并不是出于内心的真实想法，\n\u{1000}\u{1000}而是某人告诉她的\"标准答案\"。"},
[601202] = {601202, 500, "\u{0020}\u{0020}Although\u{0020}it\u{0020}has\u{0020}never\u{0020}been\u{0020}stipulated\u{0020}that\u{0020}only\u{0020}people\u{0020}from\u{0020}Saar\u{0020}can\u{0020}join\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}Miss\u{0020}Gloria,\u{0020}like\u{0020}Dolores,\u{0020}is\u{0020}a\u{0020}Saar\u{0020}person\u{0020}who\u{0020}has\u{0020}been\u{0020}bathing\u{0020}in\u{0020}the\u{0020}sea\u{0020}breeze\u{0020}and\u{0020}listening\u{0020}to\u{0020}the\u{0020}sound\u{0020}of\u{0020}the\u{0020}waves\u{0020}since\u{0020}childhood.\n\nMiss\u{0020}Gloria's\u{0020}parents\u{0020}were\u{0020}just\u{0020}commoners,\u{0020}but\u{0020}they\u{0020}have\u{0020}always\u{0020}demanded\u{0020}Miss\u{0020}Gloria\u{0020}by\u{0020}the\u{0020}standards\u{0020}of\u{0020}\"noble\u{0020}elites\".\u{0020}This\u{0020}might\u{0020}be\u{0020}the\u{0020}wish\u{0020}they\u{0020}placed\u{0020}on\u{0020}Miss\u{0020}Gloria.\u{0020}They\u{0020}must\u{0020}have\u{0020}wanted\u{0020}to\u{0020}lead\u{0020}a\u{0020}carefree\u{0020}life\u{0020}by\u{0020}nurturing\u{0020}an\u{0020}outstanding\u{0020}daughter.\n\nThey\u{0020}had\u{0020}placed\u{0020}detailed\u{0020}restrictions\u{0020}on\u{0020}Miss\u{0020}Gloria's\u{0020}words\u{0020}and\u{0020}deeds\u{0020}-\u{0020}\"Say\u{0020}\"Hello\"\u{0020}when\u{0020}meeting\u{0020}people,\u{0020}\"Wash\u{0020}your\u{0020}hands\u{0020}before\u{0020}eating\",\u{0020}\"No\u{0020}more\u{0020}than\u{0020}half\u{0020}an\u{0020}hour\u{0020}of\u{0020}entertainment\u{0020}in\u{0020}a\u{0020}day\",\u{0020}\"Don't\u{0020}ever\u{0020}play\u{0020}with\u{0020}kids\u{0020}whose\u{0020}grades\u{0020}are\u{0020}outside\u{0020}the\u{0020}top\u{0020}ten\u{0020}of\u{0020}the\u{0020}grade\",\u{0020}\"No\u{0020}ranking\u{0020}in\u{0020}each\u{0020}exam\u{0020}shall\u{0020}be\u{0020}lower\u{0020}than\u{0020}the\u{0020}top\u{0020}three\u{0020}of\u{0020}the\u{0020}grade\"...\u{0020}Gloria's\u{0020}parents\u{0020}would\u{0020}never\u{0020}tolerate\u{0020}Miss\u{0020}Gloria's\u{0020}reaction\u{0020}outside\u{0020}the\u{0020}rules.\n\nThis\u{0020}extremely\u{0020}harsh\u{0020}and\u{0020}almost\u{0020}pathological\u{0020}restraint\u{0020}did\u{0020}indeed\u{0020}make\u{0020}Miss\u{0020}Gloria\u{0020}an\u{0020}outstanding\u{0020}student\u{0020}in\u{0020}the\u{0020}class,\u{0020}but\u{0020}because\u{0020}of\u{0020}this,\u{0020}in\u{0020}the\u{0020}class,\u{0020}almost\u{0020}no\u{0020}one\u{0020}was\u{0020}willing\u{0020}to\u{0020}approach\u{0020}her\u{0020}or\u{0020}understand\u{0020}her.\u{0020}What\u{0020}Gloria\u{0020}truly\u{0020}desires\u{0020}has\u{0020}never\u{0020}been\u{0020}known.\n\nIn\u{0020}the\u{0020}eyes\u{0020}of\u{0020}her\u{0020}peers,\u{0020}Miss\u{0020}Gloria\u{0020}is\u{0020}sparing\u{0020}with\u{0020}words\u{0020}and\u{0020}difficult\u{0020}to\u{0020}get\u{0020}along\u{0020}with.\u{0020}But\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}those\u{0020}who\u{0020}actually\u{0020}work\u{0020}with\u{0020}her,\u{0020}she\u{0020}is\u{0020}a\u{0020}person\u{0020}who\u{0020}is\u{0020}polite\u{0020}and\u{0020}careful\u{0020}in\u{0020}doing\u{0020}things.\n\nThese\u{0020}two\u{0020}sides\u{0020}are\u{0020}both\u{0020}Miss\u{0020}Gloria.\n\nIt\u{0020}is\u{0020}a\u{0020}statue\u{0020}named\u{0020}\"Gloria\"\u{0020}carved\u{0020}and\u{0020}shaped\u{0020}by\u{0020}her\u{0020}parents.\n\nWhether\u{0020}Miss\u{0020}Gloria\u{0020}is\u{0020}close\u{0020}to\u{0020}the\u{0020}noble\u{0020}in\u{0020}people's\u{0020}minds,\u{0020}no\u{0020}one\u{0020}knows.\n\nBut\u{0020}she\u{0020}is\u{0020}a\u{0020}person\u{0020}who\u{0020}has\u{0020}been\u{0020}labeled\u{0020}and\u{0020}bound\u{0020}by\u{0020}stereotypes.\n\nFortunately...\u{0020}She\u{0020}entered\u{0020}AEGIS,\u{0020}entering\u{0020}this\u{0020}\"new\u{0020}world\"\u{0020}that\u{0020}is\u{0020}disconnected\u{0020}from\u{0020}the\u{0020}original\u{0020}world.", "0", "0", "0", "0", 10012, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}虽然从未规定过只有萨尔市的人才能加入Third\u{1000}Research\u{1000}Laboratory防卫班，不过格洛丽亚小姐和多洛莉丝一样，是一名从小便沐浴海风、聆听浪声的萨尔人。\n\u{1000}\u{1000}格洛丽亚小姐的双亲只是平民，却一直以\"贵族精英\"的标准去要求格洛丽亚小姐，这也许就是她的双亲寄予在格洛丽亚小姐身上的愿望。他们一定是想通过培育出优秀的女儿，让自己过上衣食无忧的日子吧。\n\u{1000}\u{1000}他们对格洛丽亚小姐进行了巨细无遗的言行约束——\"与人见面时要说\"您好\"。\"、\"吃饭前要记得洗手\"、\"一天的娱乐时间不得超过半小时\"、\"决不允许与成绩在年级前十之外的人玩耍\"、\"每次考试的排名不得低于年级前三\"……格洛丽亚的父母，绝对不能容忍格洛丽亚小姐做出条例之外的反应。\n\u{1000}\u{1000}这种苛刻到近乎病态的束缚，的确让格洛丽亚小姐成为了班级的优等生，但也正因为如此，在班上，几乎没有一个人愿意接近她，理解她。格洛丽亚真正想要的是什么，从未被人知道。\n\u{1000}\u{1000}在同龄学生眼中，格洛丽亚小姐吝啬言语，难以相处。但在实际与她共事的人眼中，却又是一个懂礼数，做事细心的人。\n\u{1000}\u{1000}这两面，都是格洛丽亚小姐，\n\u{1000}\u{1000}是由父母雕刻、塑造的名为\"格洛丽亚\"的雕像。\n\u{1000}\u{1000}格洛丽亚小姐是否接近了人们心目中的贵族，没有人知道。\n\u{1000}\u{1000}但是她一个被贴上标签、被固有印象束缚住的人。n\u{1000}\u{1000}好在…她进入了艾吉斯，进入了这个和原本世界切断联系的\"新天地\"。"},
[601203] = {601203, 1000, "\u{0020}\u{0020}Miss\u{0020}Gloria\u{0020}joined\u{0020}AEGIS\u{0020}when\u{0020}she\u{0020}entered\u{0020}high\u{0020}school\u{0020}because\u{0020}her\u{0020}parents\u{0020}regarded\u{0020}her\u{0020}\"Compatability\u{0020}Rate\"\u{0020}as\u{0020}a\u{0020}springboard\u{0020}for\u{0020}her\u{0020}to\u{0020}leap\u{0020}like\u{0020}a\u{0020}carp\u{0020}over\u{0020}the\u{0020}dragon's\u{0020}gate.\n\nThis\u{0020}is\u{0020}also\u{0020}an\u{0020}opportunity\u{0020}for\u{0020}Miss\u{0020}Gloria\u{0020}to\u{0020}embark\u{0020}on\u{0020}a\u{0020}new\u{0020}life,\u{0020}an\u{0020}unimagined\u{0020}path.\n\nAfter\u{0020}this,\u{0020}Miss\u{0020}Gloria\u{0020}has\u{0020}undergone\u{0020}some\u{0020}changes.\u{0020}She\u{0020}no\u{0020}longer\u{0020}needs\u{0020}to\u{0020}be\u{0020}restrained\u{0020}by\u{0020}others\u{0020}and\u{0020}can\u{0020}communicate\u{0020}with\u{0020}people\u{0020}of\u{0020}her\u{0020}own\u{0020}preferences.\u{0020}Having\u{0020}equal\u{0020}and\u{0020}friendly\u{0020}communication\u{0020}with\u{0020}others\u{0020}and\u{0020}presenting\u{0020}her\u{0020}demands\u{0020}is\u{0020}a\u{0020}brand-new\u{0020}experience\u{0020}for\u{0020}her.\u{0020}The\u{0020}good\u{0020}news\u{0020}is\u{0020}that\u{0020}she\u{0020}is\u{0020}changing\u{0020}for\u{0020}the\u{0020}better.\n\nShe\u{0020}is\u{0020}looking\u{0020}for\u{0020}how\u{0020}to\u{0020}express\u{0020}her\u{0020}true\u{0020}self\u{0020}correctly\u{0020}-\u{0020}after\u{0020}all,\u{0020}in\u{0020}this\u{0020}strange\u{0020}environment,\u{0020}no\u{0020}one\u{0020}has\u{0020}formulated\u{0020}regulations\u{0020}for\u{0020}her\u{0020}on\u{0020}how\u{0020}to\u{0020}respond\u{0020}in\u{0020}various\u{0020}situations.\n\nShe\u{0020}needs\u{0020}to\u{0020}determine\u{0020}her\u{0020}actions\u{0020}through\u{0020}her\u{0020}own\u{0020}choices\u{0020}instead\u{0020}of\u{0020}relying\u{0020}on\u{0020}those\u{0020}lengthy,\u{0020}cumbersome,\u{0020}and\u{0020}meaningless\u{0020}regulations.\n\n...As\u{0020}for\u{0020}the\u{0020}result,\u{0020}she\u{0020}did\u{0020}achieve\u{0020}it...\u{0020}However,\u{0020}she\u{0020}went\u{0020}a\u{0020}bit\u{0020}too\u{0020}far.\n\nRecently,\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch,\u{0020}there\u{0020}are\u{0020}rumors\u{0020}spreading,\u{0020}although\u{0020}they\u{0020}are\u{0020}just\u{0020}rumors\u{0020}and\u{0020}can\u{0020}even\u{0020}be\u{0020}regarded\u{0020}as\u{0020}malicious\u{0020}slander\u{0020}-\u{0020}when\u{0020}Miss\u{0020}Gloria\u{0020}is\u{0020}in\u{0020}private\u{0020}with\u{0020}that\u{0020}navigator,\u{0020}she\u{0020}often\u{0020}says\u{0020}some\u{0020}embarrassing\u{0020}words.\n\nIs\u{0020}this\u{0020}a\u{0020}good\u{0020}thing?", "0", "0", "0", "0", 10012, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}格洛丽亚小姐是在升入高中时加入艾吉斯的，因为格洛丽亚小姐的父母把她的\"幻化核心适格率\"当成了鲤鱼跃龙门的跳板。\n\u{1000}\u{1000}这对于格洛丽亚小姐来说也是一次通往新生活的契机，一条从未设想的道路。\n\u{1000}\u{1000}这之后，格洛丽亚小姐出现了些许的变化。她不用再被人约束，她能以自己的喜好去跟人交流。与人进行平等的，友善的交流，向人提出自己的诉求，对于她来说是一种全新的体验。好消息是，她正在往好的方向转变。\n\u{1000}\u{1000}她正在寻找着如何正确地表达出真实的自己——毕竟，在这个陌生的环境中，并没有人为她制定了面对各种情况应该做出怎样回应的条例。\n\u{1000}\u{1000}她需要通过自己的选择，来决定自己的行动，而不是靠那些冗长繁琐，却又毫无意义的规章制度。\n\u{1000}\u{1000}…就结果而言，她的确做到了…只是，有些做过头了。\n\u{1000}\u{1000}最近，在Danube\u{1000}Branch里传播着尽管只是谣言，甚至可以算得上是恶意中伤的流言蜚语——在私底下与那位通感者领航相处时的格洛丽亚小姐，常常会说出一些让人脸红耳赤的话语。\n\u{1000}\u{1000}这算是好事吗？"},
[601204] = {601204, 2000, "\u{0020}\u{0020}This\u{0020}labeled\u{0020}girl\u{0020}has\u{0020}been\u{0020}isolated\u{0020}all\u{0020}along.\n\nNo\u{0020}one\u{0020}tried\u{0020}to\u{0020}understand\u{0020}the\u{0020}real\u{0020}her,\u{0020}and\u{0020}stubbornly\u{0020}believed\u{0020}that\u{0020}Gloria\u{0020}was\u{0020}the\u{0020}person\u{0020}in\u{0020}their\u{0020}mind.\n\n——Except\u{0020}for\u{0020}that\u{0020}navigator.\n\nOn\u{0020}the\u{0020}battlefield,\u{0020}gunfire\u{0020}was\u{0020}flying,\u{0020}and\u{0020}the\u{0020}roar\u{0020}of\u{0020}Sin\u{0020}was\u{0020}endless,\n\nbut\u{0020}these\u{0020}had\u{0020}nothing\u{0020}to\u{0020}do\u{0020}with\u{0020}the\u{0020}girl.\n\nShe\u{0020}walked\u{0020}towards\u{0020}the\u{0020}figure\u{0020}flying\u{0020}in\u{0020}the\u{0020}air\u{0020}step\u{0020}by\u{0020}step,\u{0020}stretched\u{0020}out\u{0020}her\u{0020}hand,\u{0020}as\u{0020}if\u{0020}to\u{0020}grab\u{0020}the\u{0020}little\u{0020}figure\u{0020}with\u{0020}her\u{0020}hand.\n\nThen,\u{0020}with\u{0020}a\u{0020}voice\u{0020}that\u{0020}was\u{0020}too\u{0020}gentle\u{0020}to\u{0020}be\u{0020}hers,\n\n\"\u{0020}Only\u{0020}you...\u{0020}noticed\u{0020}the\u{0020}real\u{0020}me...\u{0020}You\u{0020}understand\u{0020}me.\"", "0", "0", "0", "0", 10012, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}这名被人贴上标签的少女，一直以来都被孤立着。\n\u{1000}\u{1000}没人试着去了解真正的她，一厢情愿地认为格洛丽亚就是自己心目中那样的人。\n\u{1000}\u{1000}——除了那个领航之外。\n\u{1000}\u{1000}战场上，炮火纷飞，原罪的咆哮声不绝于耳，\n\u{1000}\u{1000}但这些与这名少女毫无关系。\n\u{1000}\u{1000}她一步步地朝着那个飞在空中的人影走去，伸出手，像是要将那小小的身影用手抓住。\n\u{1000}\u{1000}然后，发出温柔得不像是她的声音，\n\u{1000}\u{1000}\"只有你…注意到了真正的我…我的——理解者。\""},
[601300] = {601300, 0, "[Name]\u{0020}Lilith\n[B-Day]\u{0020}Aug\u{0020}13\n[Compatability\u{0020}Rate]\u{0020}98％\n[Height]\u{0020}35m\n[Squad]\u{0020}Moon\u{0020}Corona\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Staying\u{0020}alone,\u{0020}Wearing\u{0020}pretty\u{0020}clothes,\u{0020}Watching\u{0020}sitcoms,\u{0020}Console\u{0020}gaming.", "0", "0", "0", "0", 10013, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}莉莉丝\n[B-Day]\u{1000}8月14日\n[幻化核心适格率]\u{1000}98％\n[Height]\u{1000}35m\n[部队]\u{1000}Moon\u{1000}Corona\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}一个人独处\u{1000}穿好看的衣服\u{1000}看情景喜剧"},
[601301] = {601301, 100, "\u{0020}\u{0020}The\u{0020}ace\u{0020}of\u{0020}Moon\u{0020}Corona,\u{0020}just\u{0020}like\u{0020}other\u{0020}squadmates,\u{0020}she's\u{0020}a\u{0020}\"potential\u{0020}synesthete\",\u{0020}and\u{0020}she\u{0020}has\u{0020}the\u{0020}special\u{0020}ability\u{0020}to\u{0020}feel\u{0020}the\u{0020}mood\u{0020}of\u{0020}other\u{0020}creatures.\n\nHer\u{0020}extremely\u{0020}high\u{0020}level\u{0020}of\u{0020}Compatability\u{0020}Rate\u{0020}allows\u{0020}her\u{0020}to\u{0020}unleash\u{0020}the\u{0020}power\u{0020}of\u{0020}her\u{0020}AVG\u{0020}gears\u{0020}to\u{0020}the\u{0020}greatest\u{0020}extent.\u{0020}She\u{0020}employs\u{0020}her\u{0020}tactics\u{0020}like\u{0020}a\u{0020}machine\u{0020}and\u{0020}is\u{0020}never\u{0020}sloppy.\u{0020}Combined\u{0020}with\u{0020}her\u{0020}excellent\u{0020}talent,\u{0020}she\u{0020}can\u{0020}be\u{0020}invincible\u{0020}on\u{0020}the\u{0020}battlefields\u{0020}filled\u{0020}with\u{0020}Sins.\n\nBut,\u{0020}although\u{0020}Lilith\u{0020}is\u{0020}a\u{0020}trustworthy\u{0020}teammate\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}not\u{0020}everyone\u{0020}can\u{0020}withstand\u{0020}her\u{0020}personality.\u{0020}Even\u{0020}if\u{0020}you\u{0020}talk\u{0020}to\u{0020}her\u{0020}and\u{0020}try\u{0020}to\u{0020}start\u{0020}a\u{0020}conversation,\u{0020}mostly\u{0020}she\u{0020}will\u{0020}ignore\u{0020}you\u{0020}just\u{0020}like\u{0020}you\u{0020}are\u{0020}the\u{0020}air.\u{0020}Currently\u{0020}in\u{0020}Danube,\u{0020}only\u{0020}her\u{0020}squadmates\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}and\u{0020}Skadi\u{0020}can\u{0020}communicate\u{0020}with\u{0020}her\u{0020}in\u{0020}a\u{0020}normal\u{0020}manner.\u{0020}But\u{0020}even\u{0020}towards\u{0020}her\u{0020}dearest\u{0020}squadmates,\u{0020}she\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}express\u{0020}her\u{0020}feelings\u{0020}excessively.", "0", "0", "0", "0", 10013, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}Moon\u{1000}Corona小队的王牌，与小队里的其他人一样，她是一名\"疑似通感者\"，有着能够感知生物情绪的特殊能力。\n\u{1000}\u{1000}她那极高的高适格率，让她能最大限度地发挥自己AVG装甲的威力。宛如机械般的战术执行力，从不拖泥带水的战斗方式，结合她自身的优秀资质，使得她在原罪肆虐的战场上所向披靡，战无不胜。\n\u{1000}\u{1000}然而，虽说在战场上的莉莉丝是令人信赖的队友，但并不是每个人都能忍受得了她的个性。即使你主动和她搭话，也会有很大概率被她当做空气冷落在一旁。目前能够与她正常沟通的人，在Danube\u{1000}Branch里仅仅只有同队的摩根勒菲与斯卡蒂。可即便是在最亲密的队友面前，她也不愿过多表达自己的想法。\n\u{1000}\u{1000}其原因，是不受控制的\"通感\"让她从别人身上得到了不必要的\"痛苦\"……"},
[601302] = {601302, 500, "\u{0020}\u{0020}Lilith's\u{0020}childhood\u{0020}was\u{0020}wholesome.\u{0020}No\u{0020}matter\u{0020}whether\u{0020}it\u{0020}compares\u{0020}with\u{0020}other\u{0020}drivers',\u{0020}or\u{0020}with\u{0020}her\u{0020}life\u{0020}after\u{0020}10\u{0020}years\u{0020}old,\u{0020}we\u{0020}can\u{0020}say:\u{0020}\"Lilith\u{0020}had\u{0020}a\u{0020}complete\u{0020}and\u{0020}happy\u{0020}childhood.\"\n\nAnd\u{0020}because\u{0020}her\u{0020}childhood\u{0020}was\u{0020}so\u{0020}good,\u{0020}her\u{0020}life\u{0020}after\u{0020}10\u{0020}years\u{0020}old\u{0020}is\u{0020}especially\u{0020}letting\u{0020}people\u{0020}be\u{0020}sympathetic.\n\nThe\u{0020}event\u{0020}that\u{0020}let\u{0020}her\u{0020}life\u{0020}fall\u{0020}into\u{0020}the\u{0020}abyss,\u{0020}was\u{0020}7\u{0020}years\u{0020}ago,\u{0020}that\u{0020}event\u{0020}caused\u{0020}the\u{0020}\"ordinary\u{0020}juvenile\"\u{0020}to\u{0020}become\u{0020}a\u{0020}\"Synesthete\".\n\nCoincidentally,\u{0020}that\u{0020}was\u{0020}Lilith's\u{0020}birthday,\u{0020}her\u{0020}last\u{0020}birthday\u{0020}celebrated\u{0020}with\u{0020}others.\u{0020}On\u{0020}that\u{0020}day,\u{0020}Lilith's\u{0020}parents\u{0020}brought\u{0020}her\u{0020}to\u{0020}her\u{0020}favorite\u{0020}restaurant\u{0020}to\u{0020}celebrate\u{0020}her\u{0020}10th\u{0020}birthday.\u{0020}And,\u{0020}a\u{0020}tragedy\u{0020}for\u{0020}Lilith,\u{0020}also\u{0020}a\u{0020}disaster\u{0020}for\u{0020}the\u{0020}society,\u{0020}happened.\n\nThe\u{0020}start\u{0020}and\u{0020}finish\u{0020}of\u{0020}\"That\u{0020}event\",\u{0020}for\u{0020}Lilith\u{0020}who\u{0020}fainted\u{0020}when\u{0020}it\u{0020}began,\u{0020}was\u{0020}like\u{0020}in\u{0020}a\u{0020}blink.\u{0020}In\u{0020}her\u{0020}memory,\u{0020}she\u{0020}was\u{0020}happily\u{0020}with\u{0020}her\u{0020}parents,\u{0020}and\u{0020}the\u{0020}next\u{0020}moment,\u{0020}when\u{0020}she\u{0020}opened\u{0020}her\u{0020}eyes\u{0020}again,\u{0020}her\u{0020}parents\u{0020}were\u{0020}no\u{0020}longer\u{0020}breathing…\u{0020}and\u{0020}her\u{0020}surroundings\u{0020}turned\u{0020}into\u{0020}a\u{0020}choking\u{0020}fire\u{0020}scene\u{0020}from\u{0020}a\u{0020}cozy\u{0020}family\u{0020}restaurant.\n\nFor\u{0020}this\u{0020}event,\u{0020}she\u{0020}recalled:\n\n\"Back\u{0020}then,\u{0020}I\u{0020}lost\u{0020}my\u{0020}conscience.\u{0020}My\u{0020}only\u{0020}impression\u{0020}when\u{0020}'That\u{0020}event'\u{0020}happened,\u{0020}was\u{0020}the\u{0020}engulfing\u{0020}fire…and\u{0020}people's\u{0020}groans.\u{0020}When\u{0020}I\u{0020}woke\u{0020}up,\u{0020}my\u{0020}dad\u{0020}and\u{0020}mom\u{0020}were...\u{0020}and\u{0020}in\u{0020}my\u{0020}surroundings…\u{0020}no\u{0020}more\u{0020}screaming…\u{0020}but,\u{0020}I\u{0020}still\u{0020}heard\u{0020}something.\u{0020}Those\u{0020}voices\u{0020}can\u{0020}only\u{0020}be\u{0020}heard\u{0020}by\u{0020}me…panicking…hatred…and\u{0020}despairing.\u{0020}That\u{0020}was\u{0020}the\u{0020}voice\u{0020}from\u{0020}an\u{0020}almost\u{0020}dumb\u{0020}person\u{0020}covered\u{0020}by\u{0020}the\u{0020}ruins…and\u{0020}that\u{0020}was\u{0020}me,\u{0020}my\u{0020}voice.\"\n\nLilith\u{0020}survived,\u{0020}and\u{0020}became\u{0020}a\u{0020}\"potential\u{0020}synesthete\",\u{0020}obtained\u{0020}a\u{0020}similar\u{0020}ability\u{0020}like\u{0020}\"That\u{0020}Navigator's\"\u{0020}Synesthesia,\u{0020}the\u{0020}ability\u{0020}of\u{0020}\"Pseudo\u{0020}Synesthesia\".\n\nBut\u{0020}compared\u{0020}to\u{0020}her\u{0020}squadmates\u{0020}who\u{0020}also\u{0020}became\u{0020}\"potential\u{0020}synesthetes\"\u{0020}because\u{0020}of\u{0020}that\u{0020}disaster,\u{0020}her\u{0020}\"Synesthesia\"\u{0020}is\u{0020}more\u{0020}\"sensitive\".\u{0020}She\u{0020}can\u{0020}empathize\u{0020}with\u{0020}negative\u{0020}feelings\u{0020}like\u{0020}\"Pain,\u{0020}Despair,\u{0020}Hatred\"\u{0020}from\u{0020}others'\u{0020}moods,\u{0020}and\u{0020}torture\u{0020}her\u{0020}mind.\u{0020}That\u{0020}is\u{0020}why\u{0020}she\u{0020}no\u{0020}longer\u{0020}wants\u{0020}to\u{0020}communicate\u{0020}with\u{0020}others.\n\nBut,\u{0020}the\u{0020}real\u{0020}reason\u{0020}that\u{0020}continuously\u{0020}causes\u{0020}her\u{0020}pain,\u{0020}perhaps\u{0020}is\u{0020}not\u{0020}her\u{0020}identity\u{0020}and\u{0020}ability\u{0020}of\u{0020}a\u{0020}\"potential\u{0020}synesthete\",\u{0020}but\u{0020}her\u{0020}obsession\u{0020}that,\u{0020}7\u{0020}years\u{0020}ago\u{0020}the\u{0020}one\u{0020}asked\u{0020}to\u{0020}\"celebrate\u{0020}her\u{0020}birthday\",\u{0020}was\u{0020}herself.\n\nAnyways,\u{0020}what\u{0020}happened\u{0020}7\u{0020}years\u{0020}ago\u{0020}changed\u{0020}her\u{0020}life\u{0020}completely.\u{0020}It's\u{0020}impossible\u{0020}for\u{0020}her\u{0020}to\u{0020}return\u{0020}to\u{0020}her\u{0020}former\u{0020}life.", "0", "0", "0", "0", 10013, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}莉莉丝的童年是幸福的，不论是与其他驾驶员对比，亦或是和她自己十岁之后的人生对比，都可以这么说：\"莉莉丝有一个完整的，幸福的童年。\"\n\u{1000}\u{1000}也正是因为她的童年过于美好，才让她十岁之后的人生尤为令人同情。\n\u{1000}\u{1000}——让莉莉丝的人生跌落低谷的落点，是七年前，那个令\"平凡的少年\"成为\"通感者\"的事件。\n\u{1000}\u{1000}那一天发生的时间，正好是莉莉丝的生日，是莉莉丝最后一个在别人欢庆中度过的生日。事件发生的当天，莉莉丝的父母为了庆祝孩子值得纪念的十岁生日，带莉莉丝去了她最喜欢的餐厅吃饭。然后，对莉莉丝而言是悲剧，社会评价是\"灾难\"的事件，发生了。\n\u{1000}\u{1000}\"那个事件\"的发生与结束，对于在事件刚开始时便昏迷过去的莉莉丝来说，是一瞬间的。在她的记忆里，上一刻还在与父母欢声笑语，下一刻，自己再次睁开眼的时候，父母已经再也不会呼吸，再也不会眨眼了…周围的环境也从氛围舒适的家庭餐厅变成了焦味弥漫的火海。\n\u{1000}\u{1000}而关于这件事，当事人是如此回忆：\n\u{1000}\u{1000}\"那时，我失去了意识，对‘那件事’发生时的印象，只剩下吞噬周围的火光…以及人们的悲鸣声。当我醒来后，我的爸爸和妈妈已经……周围…也没有人再尖叫…但是，我还是听到了声音。那是只有我才能听见的…恐惧…憎恨…以及，绝望的声音。那是被埋在建筑物下面，已经无力发声的人的声音…也是我，自己的声音。\"\n\u{1000}\u{1000}莉莉丝存活了下来，并且成为了\"疑似通感者\"，觉醒了与\"那位领航\"拥有的\"通感\"能力接近的\"疑似通感\"能力。\n\u{1000}\u{1000}但比起同因为那场灾难而成为\"疑似通感者\"的另外几名队友而言。她的\"通感\"能力要更加\"敏感\"，别人情绪中的\"痛苦、绝望、憎恶\"等负面情绪，会让她感同身受，折磨她的意识。这也成了她后来拒绝与人来往的原因。\n\u{1000}\u{1000}不过，真正让莉莉丝一直陷入痛苦中的，应该不是\"疑似通感者\"的身份与能力，而是她一厢情愿地认为，是十年前提出\"过生日\"这一请求的自己吧。\n\u{1000}\u{1000}无论如何，七年前的事件，彻底改变了莉莉丝的人生，让她没有可能再回到原来的生活。"},
[601303] = {601303, 1000, "\u{0020}\u{0020}Lilith\u{0020}became\u{0020}a\u{0020}\"potential\u{0020}synesthete\"\u{0020}in\u{0020}that\u{0020}incident,\u{0020}and\u{0020}her\u{0020}life\u{0020}after\u{0020}that\u{0020}changed\u{0020}from\u{0020}its\u{0020}original\u{0020}course.\u{0020}Because\u{0020}of\u{0020}Aegis,\u{0020}she\u{0020}lost\u{0020}her\u{0020}freedom\u{0020}and\u{0020}was\u{0020}conscripted\u{0020}into\u{0020}\"Moon\u{0020}Corona\"\u{0020}for\u{0020}training\u{0020}to\u{0020}become\u{0020}a\u{0020}driver.\u{0020}The\u{0020}main\u{0020}goal\u{0020}was\u{0020}for\u{0020}Aegis\u{0020}to\u{0020}monitor\u{0020}\"potential\u{0020}synesthetes\"\u{0020}constantly.\u{0020}In\u{0020}other\u{0020}words,\u{0020}members\u{0020}of\u{0020}\"Moon\u{0020}Corona\"\u{0020}are\u{0020}the\u{0020}replacements\u{0020}of\u{0020}that\u{0020}navigator.\n\nThe\u{0020}death\u{0020}of\u{0020}her\u{0020}parents,\u{0020}and\u{0020}people's\u{0020}groans\u{0020}during\u{0020}that\u{0020}disaster,\u{0020}those\u{0020}scenes\u{0020}have\u{0020}left\u{0020}severe\u{0020}mental\u{0020}wounds.\u{0020}These\u{0020}wounds\u{0020}make\u{0020}her\u{0020}unable\u{0020}to\u{0020}control\u{0020}her\u{0020}\"Synesthesia\",\u{0020}and\u{0020}bring\u{0020}unnecessary\u{0020}pain\u{0020}to\u{0020}herself.\n\n\"Synesthesia\"\u{0020}brings\u{0020}pain\u{0020}to\u{0020}Lilith,\u{0020}and\u{0020}because\u{0020}of\u{0020}that,\u{0020}she\u{0020}hates\u{0020}everything\u{0020}related\u{0020}to\u{0020}\"Synesthesia\",\u{0020}no\u{0020}matter\u{0020}other\u{0020}Synesthetes,\u{0020}or\u{0020}herself.\u{0020}Her\u{0020}personality\u{0020}gradually\u{0020}became\u{0020}depressive\u{0020}and\u{0020}indifferent\u{0020}because\u{0020}of\u{0020}continuous\u{0020}pain.\n\nThe\u{0020}existence\u{0020}of\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}and\u{0020}Skadi,\u{0020}especially\u{0020}Morgan\u{0020}Le\u{0020}Fay,\u{0020}have\u{0020}prevented\u{0020}Lilith\u{0020}from\u{0020}extremism.\u{0020}In\u{0020}\"Moon\u{0020}Corona\"\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}and\u{0020}Skadi\u{0020}became\u{0020}the\u{0020}backbones\u{0020}of\u{0020}her\u{0020}soul.\u{0020}They\u{0020}won\u{0020}her\u{0020}heart\u{0020}by\u{0020}their\u{0020}sincerity,\u{0020}and\u{0020}became\u{0020}two\u{0020}of\u{0020}Lilith's\u{0020}few\u{0020}friends.\n\nBut,\u{0020}to\u{0020}soothe\u{0020}the\u{0020}wounds\u{0020}in\u{0020}Lilith's\u{0020}heart,\u{0020}it\u{0020}needs\u{0020}someone\u{0020}else.\u{0020}\"Trouble\u{0020}must\u{0020}be\u{0020}solved\u{0020}by\u{0020}who\u{0020}caused\u{0020}it\".\u{0020}The\u{0020}one\u{0020}that\u{0020}can\u{0020}really\u{0020}bring\u{0020}peace\u{0020}to\u{0020}her\u{0020}mind,\u{0020}perhaps\u{0020}it's\u{0020}that\u{0020}\"Real\u{0020}Synesthete\".", "0", "0", "0", "0", 10013, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}莉莉丝在那场事件中成为\"疑似通感者\"，这之后的人生也完全偏离了原本的轨道。在艾吉斯的安排下，她失去了自由，强制性地编入了\"Moon\u{1000}Corona\"，接受驾驶员的训练，其目的主要是便于艾吉斯时刻监视\"疑似通感者\"。换句话说，\"Moon\u{1000}Corona\"的成员是那位领航的替代品。\n\u{1000}\u{1000}双亲的死，灾难时人们的悲鸣声，那时的情景给莉莉丝留下了严重的心理创伤。这些创伤让她无法控制自己的\"通感\"，给自己徒增不必要的痛苦。\n\u{1000}\u{1000}\"通感\"给莉莉丝带来了痛苦，她也因此憎恶起一切有关于\"通感\"的事情，无论是别的通感者，亦或是她自己，她的性情在无止境的痛苦中，日渐冷漠。\n\u{1000}\u{1000}摩根勒菲、斯卡蒂的存在让莉莉丝没有走上极端道路。尤其是摩根勒菲，在\"Moon\u{1000}Corona\"中，摩根勒菲与斯卡蒂几乎成了莉莉丝的心灵支柱，她们用真诚相待走进了莉莉丝内心，成为了莉莉丝为数不多的同伴。\n\u{1000}\u{1000}但，想要抚平莉莉丝内心的创伤，需要别的人。\"解铃还须系铃人\"。能让莉莉丝宁静下来的人，恐怕只有那个\"真正的通感者\"了。"},
[601304] = {601304, 2000, "\u{0020}\u{0020}7\u{0020}years\u{0020}have\u{0020}already\u{0020}passed,\u{0020}but\u{0020}that\u{0020}day\u{0020}has\u{0020}become\u{0020}the\u{0020}girl's\u{0020}nightmare,\u{0020}afflicting\u{0020}her\u{0020}every\u{0020}day.\n\nEvery\u{0020}time\u{0020}when\u{0020}she's\u{0020}a\u{0020}little\u{0020}bit\u{0020}relaxed,\u{0020}the\u{0020}sound\u{0020}back\u{0020}then\u{0020}will\u{0020}reappear\u{0020}near\u{0020}her\u{0020}ear.\u{0020}Despair\u{0020}and\u{0020}hatred,\u{0020}despair\u{0020}because\u{0020}no\u{0020}one\u{0020}responded\u{0020}to\u{0020}her\u{0020}cry\u{0020}for\u{0020}help,\u{0020}hatred\u{0020}because\u{0020}of\u{0020}why\u{0020}no\u{0020}one\u{0020}was\u{0020}going\u{0020}to\u{0020}help\u{0020}her.\n\nAnd,\u{0020}remorse,\u{0020}like\u{0020}what\u{0020}happened\u{0020}on\u{0020}that\u{0020}day\u{0020}was\u{0020}her\u{0020}fault.\n\nHas\u{0020}thought\u{0020}about\u{0020}dying\u{0020}to\u{0020}get\u{0020}rid\u{0020}of\u{0020}everything,\u{0020}for\u{0020}eternal\u{0020}peace.\n\n\"But,\u{0020}that's\u{0020}escaping.\"\n\nThe\u{0020}bright\u{0020}and\u{0020}cold\u{0020}moonlight\u{0020}illuminates\u{0020}on\u{0020}the\u{0020}skyscraping\u{0020}giantess,\u{0020}her\u{0020}dragging\u{0020}shadow\u{0020}letting\u{0020}the\u{0020}city\u{0020}fall\u{0020}into\u{0020}a\u{0020}darkness\u{0020}like\u{0020}in\u{0020}her\u{0020}heart.\u{0020}She\u{0020}seems\u{0020}to\u{0020}have\u{0020}noticed\u{0020}that\u{0020}and\u{0020}jumped\u{0020}to\u{0020}the\u{0020}sky.\u{0020}After\u{0020}that,\u{0020}the\u{0020}moonlight\u{0020}brings\u{0020}brightness\u{0020}to\u{0020}the\u{0020}city.\n\n\"Don't\u{0020}escape,\u{0020}don't\u{0020}compromise,\u{0020}face\u{0020}yourself,\u{0020}these\u{0020}are\u{0020}what\u{0020}I\u{0020}learned\u{0020}from\u{0020}you.\u{0020}'Synesthete',\u{0020}please\u{0020}connect\u{0020}your\u{0020}feelings\u{0020}with\u{0020}me,\u{0020}my\u{0020}pain,\u{0020}and\u{0020}your\u{0020}pain,\u{0020}let's\u{0020}undertake\u{0020}them\u{0020}together.\"\n\n\"I...need\u{0020}your\u{0020}help.\"", "0", "0", "0", "0", 10013, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}已经过去七年了，但那一天早已成为少女的梦魇，日复一日地折磨着少女。\n\u{1000}\u{1000}只需要稍稍一松懈，那时的声音便会在耳边响起。绝望与憎恶，对无人回应自己的求救而绝望，对为什么没人救自己而憎恶。\n\u{1000}\u{1000}然后是，自责，仿佛那一天的灾难，是她的过错一样。\n\u{1000}\u{1000}想过一死了之，想过一了百了，想过以死亡来获得永恒的宁静。\n\u{1000}\u{1000}\"但那样的话，就是逃避。\"\n\u{1000}\u{1000}皎洁清寒的月光落在仰天矗立的少女身上，拉长了的影子让城市陷入了如她内心那般的黑暗中。她似乎注意到了这一点，飞跃向空中。随后，洒下的月光让城市迎来光明。\n\u{1000}\u{1000}\"不能逃避，不能妥协，面对自己，这是我从你身上学到的东西。‘通感者’，与我通感吧，我的痛苦，还有你的痛苦，我们一起承担吧。\"\n\u{1000}\u{1000}\"我需要…你的帮助。\""},
[601400] = {601400, 0, "[Name]\u{0020}Korowin\u{0020}K\u{0020}Vella\n[B-Day]\u{0020}July\u{0020}25\n[Compatability\u{0020}Rate]\u{0020}95%\n[Height]\u{0020}36m\n[Squad]\u{0020}Ember\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Junk\u{0020}food;\u{0020}adventure\u{0020}novels", "0", "0", "0", "0", 10014, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}科罗温·卡·薇拉\n[B-Day]\u{1000}7月25日\n[幻化核心适格率]\u{1000}95%\n[Height]\u{1000}36m\n[部队]\u{1000}灰烬\n[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}垃圾食品\u{1000}冒险小说"},
[601401] = {601401, 100, "\u{0020}\u{0020}Korowin\u{0020}K\u{0020}Vella\u{0020}is\u{0020}considered\u{0020}the\u{0020}only\u{0020}normal\u{0020}person\u{0020}in\u{0020}the\u{0020}Ember\u{0020}team\u{0020}and\u{0020}also\u{0020}the\u{0020}only\u{0020}source\u{0020}of\u{0020}funds\u{0020}for\u{0020}the\u{0020}Ember\u{0020}team\u{0020}in\u{0020}the\u{0020}early\u{0020}stage.\u{0020}Korowin\u{0020}comes\u{0020}from\u{0020}a\u{0020}noble\u{0020}family\u{0020}in\u{0020}Katya,\u{0020}but\u{0020}somehow\u{0020}got\u{0020}to\u{0020}know\u{0020}Iliya\u{0020}K\u{0020}Bronchi\u{0020}who\u{0020}is\u{0020}a\u{0020}commoner.\u{0020}Later,\u{0020}she\u{0020}was\u{0020}even\u{0020}moved\u{0020}by\u{0020}Iliya\u{0020}and\u{0020}joined\u{0020}the\u{0020}Ember\u{0020}team\u{0020}founded\u{0020}by\u{0020}Iliya\u{0020}with\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}funds.\n\nAlthough\u{0020}Korowin\u{0020}is\u{0020}of\u{0020}noble\u{0020}birth,\u{0020}she\u{0020}does\u{0020}not\u{0020}rigidly\u{0020}abide\u{0020}by\u{0020}noble\u{0020}etiquette\u{0020}like\u{0020}ordinary\u{0020}nobles\u{0020}and\u{0020}has\u{0020}no\u{0020}airs\u{0020}when\u{0020}communicating\u{0020}with\u{0020}others.\u{0020}If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}her\u{0020}real\u{0020}lack\u{0020}of\u{0020}knowledge\u{0020}about\u{0020}common\u{0020}sense\u{0020}in\u{0020}life,\u{0020}probably\u{0020}no\u{0020}one\u{0020}would\u{0020}associate\u{0020}her\u{0020}with\u{0020}nobles.\n\nIn\u{0020}this\u{0020}view,\u{0020}saying\u{0020}that\u{0020}she\u{0020}is\u{0020}the\u{0020}only\u{0020}normal\u{0020}person\u{0020}in\u{0020}the\u{0020}team\u{0020}is\u{0020}rather\u{0020}unfair.\n\nKorowin\u{0020}was\u{0020}the\u{0020}strongest\u{0020}member\u{0020}of\u{0020}the\u{0020}Ember\u{0020}Squad,\u{0020}after\u{0020}all,\u{0020}Korowin's\u{0020}Compatability\u{0020}Rate\u{0020}was\u{0020}as\u{0020}high\u{0020}as\u{0020}95%.\n\nHowever,\u{0020}her\u{0020}lack\u{0020}of\u{0020}outstanding\u{0020}performance\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}was\u{0020}because\u{0020}the\u{0020}Ember\u{0020}Squad's\u{0020}equipment\u{0020}was\u{0020}too\u{0020}poor\u{0020}to\u{0020}exert\u{0020}Korowin's\u{0020}full\u{0020}strength.", "0", "0", "0", "0", 10014, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}灰烬小队是卡佳地区最为特殊的小队，其成员都是受过心理创伤而精神不太稳定的非正常人，只有一人除外，那就是科罗温。\n\u{1000}\u{1000}科罗温·卡·薇拉，算是灰烬小队中唯一的正常人，也是灰烬小队前期资金的唯一来源。科罗温出身于卡佳的贵族家庭，却不知怎么的认识了身为庶民的伊莉雅·卡·布诺琪。之后更是被伊莉雅所打动，带着大量的资金加入了伊莉雅创立的灰烬小队。\n\u{1000}\u{1000}虽然说科罗温是贵族出身，但是她不像一般的贵族一样刻板地遵守贵族礼节，和人交流也没有架子。要不是对于生活常识实在是缺乏认知，恐怕没人会把她和贵族联想到一起。\n\u{1000}\u{1000}这么看来说她是小队中唯一的正常人倒也有失公允。\n\u{1000}\u{1000}科罗温是灰烬小队实力最强的成员，毕竟科罗温的适格率高达95%。不过，她在战场上缺乏亮眼的表现，实在是灰烬小队的装备太差，发挥不出科罗温的全部实力。\n\u{1000}\u{1000}科罗温对这倒也没有什么怨言，相对于在外战斗，她可能更喜欢躲在房间里吃零食看小说吧。"},
[601402] = {601402, 500, "\u{0020}\u{0020}If\u{0020}there\u{0020}is\u{0020}anything\u{0020}that\u{0020}has\u{0020}always\u{0020}existed\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region,\u{0020}the\u{0020}old\u{0020}Katya\u{0020}people\u{0020}will\u{0020}surely\u{0020}tell\u{0020}you\u{0020}that\u{0020}it\u{0020}is\u{0020}the\u{0020}white\u{0020}snow\u{0020}on\u{0020}the\u{0020}ground\u{0020}and\u{0020}the\u{0020}nobles\u{0020}of\u{0020}Katya\u{0020}-\u{0020}although\u{0020}the\u{0020}nobles\u{0020}nowadays\u{0020}have\u{0020}lost\u{0020}their\u{0020}previous\u{0020}power\u{0020}and\u{0020}influence,\u{0020}they\u{0020}are\u{0020}still\u{0020}nobles.\n\nAs\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Katya\u{0020}nobility,\u{0020}Korowin's\u{0020}review\u{0020}for\u{0020}the\u{0020}nobility\u{0020}is\u{0020}only\u{0020}one\u{0020}words\u{0020}-\u{0020}boring.\n\nTo\u{0020}others,\u{0020}Korowin\u{0020}seems\u{0020}to\u{0020}be\u{0020}unappreciative\u{0020}of\u{0020}her\u{0020}blessings,\u{0020}but\u{0020}only\u{0020}she\u{0020}herself\u{0020}knows\u{0020}how\u{0020}boring\u{0020}it\u{0020}is\u{0020}to\u{0020}be\u{0020}a\u{0020}noble.\u{0020}The\u{0020}elaborate\u{0020}etiquette,\u{0020}the\u{0020}conventional\u{0020}socializing,\u{0020}and\u{0020}the\u{0020}monotonous\u{0020}balls.\u{0020}Even\u{0020}in\u{0020}this\u{0020}era\u{0020}invaded\u{0020}by\u{0020}Sin,\u{0020}the\u{0020}nobles\u{0020}still\u{0020}try\u{0020}every\u{0020}way\u{0020}to\u{0020}maintain\u{0020}their\u{0020}old-fashioned\u{0020}rules\u{0020}of\u{0020}conduct.\n\nSince\u{0020}childhood,\u{0020}Korowin,\u{0020}who\u{0020}has\u{0020}been\u{0020}taught\u{0020}to\u{0020}revive\u{0020}the\u{0020}glory\u{0020}of\u{0020}nobles,\u{0020}does\u{0020}not\u{0020}want\u{0020}to\u{0020}abide\u{0020}by\u{0020}those\u{0020}noble\u{0020}dogmas.\u{0020}Rather\u{0020}than\u{0020}wearing\u{0020}a\u{0020}noble\u{0020}dress\u{0020}with\u{0020}a\u{0020}tightened\u{0020}waist\u{0020}to\u{0020}attend\u{0020}a\u{0020}ball,\u{0020}she\u{0020}is\u{0020}more\u{0020}willing\u{0020}to\u{0020}lie\u{0020}in\u{0020}bed,\u{0020}eat\u{0020}snacks\u{0020}stolen\u{0020}from\u{0020}servants,\u{0020}and\u{0020}read\u{0020}newly\u{0020}otomate\u{0020}novels.\u{0020}In\u{0020}her\u{0020}opinion,\u{0020}the\u{0020}noble\u{0020}social\u{0020}activities\u{0020}that\u{0020}her\u{0020}parents\u{0020}participate\u{0020}in\u{0020}are\u{0020}a\u{0020}waste\u{0020}of\u{0020}time.\u{0020}After\u{0020}all,\u{0020}when\u{0020}the\u{0020}Sin\u{0020}invades,\u{0020}it\u{0020}will\u{0020}not\u{0020}spare\u{0020}you\u{0020}just\u{0020}because\u{0020}you\u{0020}are\u{0020}a\u{0020}noble.\n\nHowever,\u{0020}she\u{0020}had\u{0020}no\u{0020}way\u{0020}to\u{0020}change\u{0020}anything.\u{0020}After\u{0020}all,\u{0020}Korowin\u{0020}had\u{0020}lived\u{0020}in\u{0020}the\u{0020}family's\u{0020}manor\u{0020}since\u{0020}childhood,\u{0020}had\u{0020}no\u{0020}opportunity\u{0020}to\u{0020}contact\u{0020}the\u{0020}outside\u{0020}world,\u{0020}and\u{0020}could\u{0020}only\u{0020}understand\u{0020}an\u{0020}imagined\u{0020}outside\u{0020}world\u{0020}through\u{0020}the\u{0020}content\u{0020}in\u{0020}novels.\u{0020}Korowin's\u{0020}only\u{0020}dream\u{0020}was\u{0020}to\u{0020}travel\u{0020}around\u{0020}the\u{0020}world\u{0020}one\u{0020}day\u{0020}and\u{0020}taste\u{0020}delicacies\u{0020}from\u{0020}all\u{0020}places.\n\nAfter\u{0020}reaching\u{0020}the\u{0020}age\u{0020}of\u{0020}16,\u{0020}Korowin\u{0020}had\u{0020}become\u{0020}a\u{0020}qualified\u{0020}noble,\u{0020}and\u{0020}her\u{0020}father\u{0020}also\u{0020}believed\u{0020}that\u{0020}the\u{0020}glory\u{0020}of\u{0020}the\u{0020}nobility\u{0020}could\u{0020}not\u{0020}just\u{0020}remain\u{0020}at\u{0020}repetitive\u{0020}balls.\u{0020}The\u{0020}battlefield\u{0020}was\u{0020}the\u{0020}occasion\u{0020}to\u{0020}embody\u{0020}the\u{0020}noble\u{0020}spirit.\u{0020}So,\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}shareholders\u{0020}of\u{0020}the\u{0020}\"Siren\"\u{0020}company,\u{0020}he\u{0020}took\u{0020}Korowin\u{0020}to\u{0020}the\u{0020}\"Siren\"\u{0020}Armored\u{0020}Company\u{0020}for\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}of\u{0020}the\u{0020}illusion\u{0020}core,\u{0020}hoping\u{0020}that\u{0020}she\u{0020}could\u{0020}become\u{0020}a\u{0020}driver\u{0020}to\u{0020}bring\u{0020}honor\u{0020}to\u{0020}the\u{0020}family\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}against\u{0020}Sin\u{0020}and\u{0020}restore\u{0020}the\u{0020}glory\u{0020}of\u{0020}the\u{0020}nobility.\n\nHere,\u{0020}Korowin\u{0020}obtained\u{0020}the\u{0020}qualification\u{0020}of\u{0020}a\u{0020}driver\u{0020}with\u{0020}an\u{0020}ultra-high\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}95%,\u{0020}and\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}she\u{0020}met\u{0020}Iliya\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}here.\u{0020}Through\u{0020}a\u{0020}brief\u{0020}exchange,\u{0020}Korowin\u{0020}learned\u{0020}about\u{0020}Iliya's\u{0020}tragic\u{0020}past\u{0020}and,\u{0020}while\u{0020}feeling\u{0020}sad,\u{0020}also\u{0020}greatly\u{0020}admired\u{0020}Iliya's\u{0020}strong\u{0020}character.\n\nWhen\u{0020}Iliya\u{0020}said\u{0020}that\u{0020}she\u{0020}wanted\u{0020}to\u{0020}recruit\u{0020}people\u{0020}to\u{0020}form\u{0020}an\u{0020}AVG\u{0020}team\u{0020}to\u{0020}take\u{0020}revenge\u{0020}on\u{0020}Sin,\u{0020}Korowin,\u{0020}without\u{0020}thinking\u{0020}twice,\u{0020}joined\u{0020}Iliya's\u{0020}Ember\u{0020}team\u{0020}with\u{0020}all\u{0020}her\u{0020}savings\u{0020}and\u{0020}became\u{0020}one\u{0020}of\u{0020}its\u{0020}important\u{0020}members.", "0", "0", "0", "0", 10014, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}如果说卡佳地区有什么是一直存在的，老卡佳人肯定会告诉你是地上的白雪和卡佳的贵族——尽管如今的贵族已经失去了以往的权势，但他们依然是贵族。\n\u{1000}\u{1000}科罗温作为卡佳贵族中的一分子，对于贵族的评价却只有两个字——无趣。\n\u{1000}\u{1000}在别人看来科罗温这是有点身在福中不知福，但只有她自己知道，当一个贵族有多么的无聊。繁缛的礼节，俗套的应酬以及千篇一律的舞会。就算是在这原罪侵袭的时代中，贵族们还是会想尽办法保持着他们那一套陈旧的行事规则。\n\u{1000}\u{1000}从小就被教导着要复兴贵族荣耀的科罗温却并不想着去遵守那些贵族教条。比起穿着腰部被勒紧的贵族礼服去参加舞会，她更愿意躺在床上吃着从仆人那儿偷来的零食看新连载的乙女小说。在她看来，父母亲参加的这些贵族社交都是在浪费时间，毕竟原罪在入侵的时候可不会因为你是贵族就放过你。\n\u{1000}\u{1000}然而她并没有办法改变什么，毕竟科罗温从小就生活在家族的庄园中，没有机会去接触外界，只能通过小说中的内容来了解一个自己想象中的外界。科罗温唯一的梦想就是有一天能周游世界，吃遍各地美食。\n\u{1000}\u{1000}到了16岁以后，科罗温已经成为了个合格的贵族，而她的父亲也认为贵族的荣耀不能止停留于重复的舞会上，战场才是体现贵族精神的场合。于是他作为\"塞伦\"公司的股东之一，带着科罗温到了\"塞伦\"装甲公司进行幻化核心适格率测试，希望她能够成为一名驾驶员在对抗原罪的战场上为家族带来荣耀，重振贵族的荣光。\n\u{1000}\u{1000}在这里，科罗温以95%的超高适格率获得了驾驶员的资格，同时她也在这第一次见到了伊莉雅。通过短暂的交流，科罗温了解到伊莉雅悲惨的过去，在感到悲伤的同时也非常钦佩伊莉雅的坚强性格。\n\u{1000}\u{1000}当伊莉雅说要招募人手组建一个avg小队复仇原罪时，科罗温想都没想就带着自己的全部积蓄加入了伊莉雅的灰烬小队，成为其重要的成员之一。"},
[601403] = {601403, 1000, "\u{0020}\u{0020}The\u{0020}reason\u{0020}why\u{0020}Korowin\u{0020}chose\u{0020}to\u{0020}join\u{0020}Ember\u{0020}without\u{0020}telling\u{0020}her\u{0020}father\u{0020}was\u{0020}probably\u{0020}moved\u{0020}by\u{0020}Iliya's\u{0020}background.\n\nIn\u{0020}Korowin's\u{0020}eyes,\u{0020}Iliya\u{0020}is\u{0020}like\u{0020}the\u{0020}protagonist\u{0020}in\u{0020}a\u{0020}novel\u{0020}with\u{0020}a\u{0020}tragic\u{0020}past.\u{0020}Through\u{0020}unremitting\u{0020}efforts\u{0020}and\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}companions,\u{0020}she\u{0020}can\u{0020}eventually\u{0020}obtain\u{0020}happiness.\u{0020}Korowin\u{0020}is\u{0020}willing\u{0020}to\u{0020}be\u{0020}Iliya's\u{0020}companion\u{0020}to\u{0020}help\u{0020}her\u{0020}fulfill\u{0020}the\u{0020}wish\u{0020}of\u{0020}revenge,\u{0020}and\u{0020}Iliya\u{0020}also\u{0020}welcomes\u{0020}the\u{0020}powerful\u{0020}Korowin\u{0020}to\u{0020}join\u{0020}Ember.\n\nBut\u{0020}when\u{0020}Korowin\u{0020}came\u{0020}to\u{0020}Iliya\u{0020}with\u{0020}three\u{0020}fully\u{0020}loaded\u{0020}transport\u{0020}trucks\u{0020}of\u{0020}snacks.\u{0020}The\u{0020}captain\u{0020}of\u{0020}the\u{0020}Ember\u{0020}team\u{0020}almost\u{0020}lost\u{0020}control\u{0020}and\u{0020}went\u{0020}berserk.\u{0020}It\u{0020}turned\u{0020}out\u{0020}that\u{0020}the\u{0020}inexperienced\u{0020}Korowin\u{0020}lacked\u{0020}the\u{0020}common\u{0020}sense\u{0020}of\u{0020}\"what\u{0020}is\u{0020}the\u{0020}value\u{0020}of\u{0020}money\",\u{0020}and\u{0020}exchanged\u{0020}all\u{0020}the\u{0020}money\u{0020}for\u{0020}what\u{0020}she\u{0020}considered\u{0020}very\u{0020}\"precious\"\u{0020}gifts\u{0020}to\u{0020}give\u{0020}to\u{0020}her\u{0020}companions\u{0020}in\u{0020}the\u{0020}Ember\u{0020}team.\n\nKnowing\u{0020}the\u{0020}whole\u{0020}story,\u{0020}Iliya\u{0020}took\u{0020}three\u{0020}shots\u{0020}of\u{0020}mental\u{0020}suppressant\u{0020}before\u{0020}calming\u{0020}down\u{0020}and\u{0020}not\u{0020}running\u{0020}wild\u{0020}to\u{0020}destroy\u{0020}that\u{0020}snack\u{0020}store.\n\nAfter\u{0020}this\u{0020}incident,\u{0020}Iliya\u{0020}understood\u{0020}that\u{0020}she\u{0020}must\u{0020}never\u{0020}hand\u{0020}the\u{0020}money\u{0020}to\u{0020}this\u{0020}young\u{0020}lady\u{0020}for\u{0020}management\u{0020}and\u{0020}must\u{0020}immediately\u{0020}popularize\u{0020}the\u{0020}basic\u{0020}common\u{0020}sense\u{0020}of\u{0020}human\u{0020}society\u{0020}to\u{0020}Korowin.\n\nFor\u{0020}Korowin,\u{0020}the\u{0020}greatest\u{0020}feeling\u{0020}of\u{0020}joining\u{0020}Ember\u{0020}is\u{0020}freedom.\u{0020}She\u{0020}feels\u{0020}like\u{0020}a\u{0020}canary\u{0020}that\u{0020}has\u{0020}lived\u{0020}in\u{0020}a\u{0020}cage\u{0020}for\u{0020}more\u{0020}than\u{0020}ten\u{0020}years\u{0020}and\u{0020}finally\u{0020}broke\u{0020}through\u{0020}the\u{0020}cage\u{0020}one\u{0020}day\u{0020}and\u{0020}flew\u{0020}freely\u{0020}in\u{0020}the\u{0020}sky.\n\nAnd\u{0020}the\u{0020}other\u{0020}members\u{0020}of\u{0020}the\u{0020}team\u{0020}also\u{0020}very\u{0020}much\u{0020}welcomed\u{0020}this\u{0020}young\u{0020}lady\u{0020}of\u{0020}noble\u{0020}birth\u{0020}without\u{0020}any\u{0020}noble\u{0020}airs.\u{0020}Especially\u{0020}the\u{0020}three\u{0020}trucks\u{0020}of\u{0020}snacks\u{0020}won\u{0020}the\u{0020}favor\u{0020}of\u{0020}the\u{0020}entire\u{0020}team.\u{0020}After\u{0020}all,\u{0020}the\u{0020}Ember\u{0020}drivers\u{0020}were,\u{0020}in\u{0020}the\u{0020}final\u{0020}analysis,\u{0020}just\u{0020}teenage\u{0020}girls.\n\n\"Everyone\u{0020}in\u{0020}the\u{0020}team\u{0020}has\u{0020}a\u{0020}tragic\u{0020}past,\u{0020}but\u{0020}they\u{0020}are\u{0020}all\u{0020}kind\u{0020}children.\u{0020}The\u{0020}only\u{0020}thing\u{0020}I\u{0020}can\u{0020}do\u{0020}is\u{0020}to\u{0020}accompany\u{0020}them\u{0020}to\u{0020}find\u{0020}their\u{0020}own\u{0020}happiness.\"", "0", "0", "0", "0", 10014, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}科罗温选择瞒着父亲加入灰烬的原因，大概是被伊莉雅的身世所打动。\n\u{1000}\u{1000}在科罗温眼中伊莉雅就像小说中拥有悲惨过去的主角，经过坚持不懈的努力和同伴的帮助下最终能够获得幸福。科罗温愿意成为伊莉雅的同伴帮助她实现复仇的愿望，而伊莉雅也欢迎实力强劲的科罗温加入灰烬。\n\u{1000}\u{1000}但是当科罗温带着满满三辆运输卡车的零食来找伊莉雅的时候。这位灰烬小队的队长差点失控暴走。原来不谙世事的科罗温缺乏\"钱的价值是多少\"这种常识，把钱全部换成自认为非常\"珍贵\"的礼物想送给灰烬小队的同伴们。\n\u{1000}\u{1000}知道事情经过的伊莉雅连打了三针精神抑制剂才冷静下来，没有暴走去把那家零食商店人道毁灭。\n\u{1000}\u{1000}经过这件事，伊莉雅明白了千万不能把钱交给这位千金小姐管理以及必须马上给科罗温进行人类社会基本常识的普及。\n\u{1000}\u{1000}而对于科罗温来说，加入灰烬的最大感受就是自由。她感觉自己就像一只在笼中生活了十多年的金丝雀终于有一天突破了牢笼，自由飞翔于天空。\n\u{1000}\u{1000}而小队的其他成员也都非常欢迎这位没有贵族架子的千金小姐。特别是那三车的零食更是俘获了全队的好感，毕竟灰烬驾驶员们说到底都不过是年龄十几岁的少女。\n\u{1000}\u{1000}\"小队的大家都拥有悲惨的过去，但是她们都是善良的孩子，我唯一能做的只有陪伴她们找到各自的幸福。\""},
[601404] = {601404, 2000, "\u{0020}\u{0020}Rainwater\u{0020}flowed\u{0020}along\u{0020}the\u{0020}indentation\u{0020}on\u{0020}the\u{0020}girl's\u{0020}back,\u{0020}cold\u{0020}and\u{0020}piercing,\u{0020}gathering\u{0020}on\u{0020}the\u{0020}ground\u{0020}and\u{0020}flowing\u{0020}to\u{0020}form\u{0020}a\u{0020}runoff.\u{0020}The\u{0020}girl\u{0020}remained\u{0020}motionless.\u{0020}Three\u{0020}lurking\u{0020}\"insects\"\u{0020}were\u{0020}surrounding\u{0020}her\u{0020}from\u{0020}behind,\u{0020}and\u{0020}their\u{0020}sharp\u{0020}forelimbs\u{0020}like\u{0020}blades\u{0020}were\u{0020}about\u{0020}to\u{0020}tear\u{0020}her\u{0020}apart.\u{0020}\"Navigator,\u{0020}have\u{0020}you\u{0020}ever\u{0020}had\u{0020}the\u{0020}cake\u{0020}from\u{0020}Senro's?\"\u{0020}The\u{0020}girl's\u{0020}inquiry\u{0020}broke\u{0020}the\u{0020}tranquility\u{0020}of\u{0020}the\u{0020}rainy\u{0020}day.\u{0020}Then,\u{0020}her\u{0020}weapon\u{0020}cut\u{0020}through\u{0020}the\u{0020}rain\u{0020}curtain,\u{0020}and\u{0020}along\u{0020}with\u{0020}it,\u{0020}the\u{0020}insects\u{0020}that\u{0020}were\u{0020}trying\u{0020}to\u{0020}approach\u{0020}her\u{0020}were\u{0020}also\u{0020}cut\u{0020}off\u{0020}by\u{0020}the\u{0020}axe\u{0020}blade.\u{0020}On\u{0020}the\u{0020}head\u{0020}of\u{0020}the\u{0020}flying\u{0020}insect,\u{0020}the\u{0020}face\u{0020}lost\u{0020}its\u{0020}vitality.\u{0020}When\u{0020}it\u{0020}fell\u{0020}to\u{0020}the\u{0020}ground,\u{0020}it\u{0020}raised\u{0020}sand\u{0020}and\u{0020}formed\u{0020}a\u{0020}dust\u{0020}storm.\u{0020}The\u{0020}girl\u{0020}smiled\u{0020}and\u{0020}continued\u{0020}the\u{0020}conversation,\u{0020}\"Let's\u{0020}go\u{0020}and\u{0020}eat\u{0020}together\u{0020}next\u{0020}time.\u{0020}My\u{0020}treat.\"\u{0020}\"Of\u{0020}course,\u{0020}we'll\u{0020}also\u{0020}bring\u{0020}everyone\u{0020}from\u{0020}the\u{0020}Ember\u{0020}team.\"", "0", "0", "0", "0", 10014, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}雨水顺着少女背部的凹线流下，\u{1000}\u{1000}冰凉而刺骨，\u{1000}\u{1000}汇聚在地上流动，形成了径流。\u{1000}\u{1000}少女一动不动。\u{1000}\u{1000}三只潜行的\"昆虫\"正从少女背后包围，\u{1000}\u{1000}如刀刃般锋利的前肢即将把她撕碎。\u{1000}\u{1000}\"领航，你吃过森罗家的蛋糕吗？\"\u{1000}\u{1000}少女的询问打破了雨天的宁静，\u{1000}\u{1000}然后，她的武器斩断了雨帘，\u{1000}\u{1000}一同被斧刃斩断的，还有那试图接近她的昆虫。\u{1000}\u{1000}高高飞起的昆虫头颅上，面孔失去了生机，坠落在地时，扬起沙土形成了尘暴。\u{1000}\u{1000}少女微笑着将对话进行了下去，\u{1000}\u{1000}\"下次一起去吃吧，我请客。\"\u{1000}\u{1000}\"当然还要带上灰烬小队的大家。\""},
[601500] = {601500, 0, "[Name]\u{0020}Sofia\u{0020}Il\u{0020}Pogolovsky\n[B-Day]\u{0020}Aug\u{0020}8\n[Compatability\u{0020}Rate]\u{0020}86%\n[Height]\u{0020}38m\n[Squad]\u{0020}Cannonbore\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Enjoy\u{0020}the\u{0020}moment\u{0020}when\u{0020}bodies\u{0020}of\u{0020}Sins\u{0020}fall\u{0020}apart.", "0", "0", "0", "0", 10015, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}索菲亚·伊·波戈洛夫斯基\n[B-Day]\u{1000}8月8日\n[幻化核心适格率]\u{1000}86%\n[Height]\u{1000}38m\n[部队]\u{1000}钢轮戈尔\n[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}欣赏原罪躯体支离破碎的那一刻"},
[601501] = {601501, 100, "\u{0020}\u{0020}Zofia\u{0020}Il\u{0020}Pogolovsky\u{0020}is\u{0020}a\u{0020}dangerous\u{0020}person,\u{0020}this\u{0020}is\u{0020}a\u{0020}consensus\u{0020}among\u{0020}members\u{0020}of\u{0020}Katya,\u{0020}only\u{0020}her\u{0020}careless\u{0020}captain\u{0020}doesn't\u{0020}notice\u{0020}that,\u{0020}or\u{0020}rather,\u{0020}doesn't\u{0020}care\u{0020}about\u{0020}how\u{0020}dangerous\u{0020}she\u{0020}is.\n\nAs\u{0020}like\u{0020}acknowledging\u{0020}how\u{0020}dangerous\u{0020}she\u{0020}is,\u{0020}members\u{0020}of\u{0020}Katya\u{0020}also\u{0020}recognized\u{0020}that\u{0020}Zofia\u{0020}is\u{0020}capable\u{0020}enough\u{0020}to\u{0020}be\u{0020}appointed\u{0020}to\u{0020}difficult\u{0020}duties\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}Any\u{0020}Sins\u{0020}approaching\u{0020}her\u{0020}will\u{0020}be\u{0020}torn\u{0020}apart\u{0020}in\u{0020}a\u{0020}blink.\n\nPeople\u{0020}who\u{0020}witness\u{0020}her\u{0020}fighting\u{0020}will\u{0020}have\u{0020}an\u{0020}illusion\u{0020}that\u{0020}she's\u{0020}not\u{0020}a\u{0020}human,\u{0020}but\u{0020}a\u{0020}beast\u{0020}who\u{0020}is\u{0020}guarding\u{0020}her\u{0020}realm\u{0020}against\u{0020}Sins.\n\nThe\u{0020}risk\u{0020}about\u{0020}her\u{0020}is,\u{0020}even\u{0020}when\u{0020}she\u{0020}leaves\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}returns\u{0020}to\u{0020}her\u{0020}normal\u{0020}daily\u{0020}life,\u{0020}she\u{0020}still\u{0020}expresses\u{0020}her\u{0020}wildness\u{0020}that\u{0020}may\u{0020}destroy\u{0020}everything.\n\nAt\u{0020}all\u{0020}times\u{0020}everyone\u{0020}knows\u{0020},\u{0020}behind\u{0020}her\u{0020}smiling\u{0020}face,\u{0020}is\u{0020}a\u{0020}beast\u{0020}locked\u{0020}in\u{0020}a\u{0020}cage.", "0", "0", "0", "0", 10015, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}索菲亚·伊·波戈洛夫斯基是一个危险的人，这一点是Katya\u{1000}Branch全体成员的共识，也就只有她那大大咧咧的队长才没注意到，或者不在意她有多危险了。\n\u{1000}\u{1000}就像承认她的危险性一样，Katya\u{1000}Branch的成员也承认索菲亚在战场上值得被委以重任，任何尝试着接近她领域的原罪都会在眨眼间被撕碎。\n\u{1000}\u{1000}目睹过她战斗场面的人，恍惚间都会产生一种错觉——那并非是人类，而是一只漆黑的野兽在向原罪捍卫自己的领地主权。\n\u{1000}\u{1000}可她的危险在于——即便是离开了战场，回到了日常生活中的索菲亚，依然会在谈话间流露出那种会将所有事物摧毁的野性。\n\u{1000}\u{1000}人们时时刻刻都能注意到，在她笑容之下，是一只被关在牢笼中的野兽。"},
[601502] = {601502, 500, "\u{0020}\u{0020}Zofia\u{0020}Il\u{0020}Pogolovsky's\u{0020}family\u{0020}used\u{0020}to\u{0020}be\u{0020}noble.\u{0020}\"Used\u{0020}to\u{0020}be\"\u{0020}because\u{0020}there\u{0020}are\u{0020}no\u{0020}real\u{0020}nobles\u{0020}in\u{0020}Katya\u{0020}anymore.\u{0020}What's\u{0020}left\u{0020}for\u{0020}those\u{0020}former\u{0020}nobles,\u{0020}is\u{0020}just\u{0020}a\u{0020}little\u{0020}wealth\u{0020}and\u{0020}knotty\u{0020}etiquettes.\n\nFormer\u{0020}nobles\u{0020}in\u{0020}Katya\u{0020}had\u{0020}a\u{0020}different\u{0020}situation\u{0020}from\u{0020}their\u{0020}counterparts\u{0020}in\u{0020}Danube.\u{0020}When\u{0020}Aegis\u{0020}set\u{0020}up\u{0020}their\u{0020}control\u{0020}over\u{0020}Katya,\u{0020}the\u{0020}most\u{0020}resistance\u{0020}came\u{0020}from\u{0020}those\u{0020}former\u{0020}nobles.\u{0020}Contrary\u{0020}to\u{0020}Danubian\u{0020}nobles\u{0020}that\u{0020}had\u{0020}chosen\u{0020}to\u{0020}cede\u{0020}some\u{0020}authority\u{0020}and\u{0020}cooperate\u{0020}peacefully\u{0020}with\u{0020}Aegis,\u{0020}Katyan\u{0020}nobles\u{0020}refused\u{0020}to\u{0020}make\u{0020}or\u{0020}take\u{0020}any\u{0020}compromises,\u{0020}and\u{0020}ended\u{0020}up\u{0020}in\u{0020}a\u{0020}brutal\u{0020}war\u{0020}and\u{0020}lost\u{0020}their\u{0020}regime\u{0020}over\u{0020}Katya.\n\nAegis\u{0020}won,\u{0020}but\u{0020}the\u{0020}possibility\u{0020}of\u{0020}reconciliation\u{0020}between\u{0020}Aegis\u{0020}Katya\u{0020}Branch\u{0020}and\u{0020}local\u{0020}nobles\u{0020}is\u{0020}forever\u{0020}gone.\n\nBecause\u{0020}Zofia\u{0020}is\u{0020}from\u{0020}a\u{0020}former\u{0020}noble\u{0020}family,\u{0020}it's\u{0020}surprising\u{0020}that\u{0020}she\u{0020}chose\u{0020}to\u{0020}become\u{0020}a\u{0020}member\u{0020}of\u{0020}Aegis\u{0020}Katya\u{0020}Branch.\n\nZofia\u{0020}Il\u{0020}Pogolovsky\u{0020}became\u{0020}a\u{0020}driver\u{0020}because\u{0020}she\u{0020}wanted\u{0020}to\u{0020}vent\u{0020}her\u{0020}inherent\u{0020}\"destroying\u{0020}spree\".\n\nShe\u{0020}has\u{0020}an\u{0020}inborn\u{0020}impulse\u{0020}to\u{0020}destroy\u{0020}everything,\u{0020}and\u{0020}this\u{0020}pulse\u{0020}is\u{0020}universal,\u{0020}no\u{0020}matter\u{0020}who's\u{0020}in\u{0020}front\u{0020}of\u{0020}her,\u{0020}she\u{0020}wants\u{0020}to\u{0020}split\u{0020}them\u{0020}up\u{0020}in\u{0020}her\u{0020}heart.\u{0020}A\u{0020}beast\u{0020}is\u{0020}living\u{0020}inside\u{0020}her,\u{0020}she\u{0020}commented\u{0020}on\u{0020}her\u{0020}\"destroying\u{0020}spree\"\u{0020}like\u{0020}this.\n\nPsycho\u{0020}medics\u{0020}of\u{0020}Aegis\u{0020}think\u{0020}that\u{0020}Zofia's\u{0020}\"destroying\u{0020}spree\"\u{0020}is\u{0020}because\u{0020}of\u{0020}her\u{0020}\"fallen\u{0020}apart\"\u{0020}and\u{0020}\"deformed\"\u{0020}family.\u{0020}Her\u{0020}father\u{0020}was\u{0020}immersed\u{0020}in\u{0020}the\u{0020}game\u{0020}of\u{0020}thrones,\u{0020}eager\u{0020}to\u{0020}regain\u{0020}his\u{0020}power.\n\nHer\u{0020}mother\u{0020}couldn't\u{0020}stand\u{0020}a\u{0020}husband\u{0020}like\u{0020}that,\u{0020}she\u{0020}abandoned\u{0020}her\u{0020}husband\u{0020}and\u{0020}children\u{0020}and\u{0020}went\u{0020}away.\u{0020}As\u{0020}a\u{0020}daughter\u{0020}from\u{0020}such\u{0020}unqualified\u{0020}parents,\u{0020}Zofia\u{0020}neither\u{0020}felt\u{0020}\"caring\"\u{0020}from\u{0020}a\u{0020}young\u{0020}age,\u{0020}nor\u{0020}understood\u{0020}what\u{0020}\"love\"\u{0020}is.\u{0020}That\u{0020}beast\u{0020}inside\u{0020}her,\u{0020}was\u{0020}generated\u{0020}because\u{0020}of\u{0020}her\u{0020}will\u{0020}of\u{0020}understanding\u{0020}\"love\"\u{0020}and\u{0020}want\u{0020}to\u{0020}be\u{0020}\"loved\".\u{0020}Zofia\u{0020}forbears\u{0020}her\u{0020}pulse\u{0020}of\u{0020}destruction\u{0020}anytime,\u{0020}and\u{0020}doesn't\u{0020}allow\u{0020}herself\u{0020}to\u{0020}become\u{0020}a\u{0020}monster\u{0020}driven\u{0020}by\u{0020}desires.\n\nBut\u{0020}how\u{0020}long\u{0020}can\u{0020}she\u{0020}keep\u{0020}it?\u{0020}Maybe\u{0020}someday,\u{0020}that\u{0020}balance\u{0020}will\u{0020}be\u{0020}broken\u{0020}and\u{0020}leans\u{0020}to\u{0020}the\u{0020}side.\u{0020}And\u{0020}if\u{0020}that\u{0020}happens,\u{0020}Zofia\u{0020}might\u{0020}no\u{0020}longer\u{0020}be\u{0020}an\u{0020}ally\u{0020}of\u{0020}humanity.\n\n\"I'm…not\u{0020}a\u{0020}Destroyer..\u{0020}The\u{0020}painful\u{0020}expression\u{0020}of\u{0020}enemies,\u{0020}I'm\u{0020}not\u{0020}interested\u{0020}in\u{0020}them…but,\u{0020}the\u{0020}happiness\u{0020}of\u{0020}destroying\u{0020}enemies'\u{0020}bodies\u{0020}and\u{0020}spirits,\u{0020}was\u{0020}so\u{0020}true…I'm,\u{0020}certainly,\u{0020}abnormal.\"", "0", "0", "0", "0", 10015, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}索菲亚·伊·波戈洛夫斯基的家族曾经是贵族。之所以用\"曾经\"来描述，是因为卡佳这片土地上，已经不存在真正意义上的贵族了。留给的旧贵族的，只剩下些许的财富，以及繁缛的礼节。\u{1000}\u{1000}卡佳地区的旧贵族与多瑙地区的旧贵族面临的处境存在着些许区别。艾吉斯在卡佳建立支部的过程中，遭受到的最大的阻力便来自于卡佳地区的旧贵族。与选择和平共处、交出自己部分权力的多瑙贵族不同，卡佳地区的旧贵族不接受任何形式上的让步，最终以惨烈的战争作为政权更替的收尾方式。\u{1000}\u{1000}艾吉斯取得了胜利，但Katya\u{1000}Branch与卡佳当地的旧贵族之间也不会再有和解的可能。\u{1000}\u{1000}以索菲亚旧贵族的出身，她会选择成为艾吉斯Katya\u{1000}Branch的一员，多少会让人感到不可思议。\u{1000}\u{1000}索菲亚·伊·波戈洛夫斯基成为驾驶员的目的是为了发泄她与生俱来的\"破坏欲\"。\u{1000}\u{1000}她天生就有一种想要摧毁一切事物的冲动，她这种冲动是无关乎对象的，无论对方是谁，她打从心底里都渴望着将眼前的人撕碎。有一只野兽寄宿在自己的身体里，她如此评价自己的\"破坏欲\"。\u{1000}\u{1000}艾吉斯的精神科医生认为，索菲亚这种\"破坏欲\"的成因要归咎于她支离破碎了的，已经畸形化的家庭。一个一门心思钻到了权术中，盼望重新掌握权势的父亲，和一个忍受不了这样的丈夫便抛弃丈夫与孩子，离家出走的母亲。作为这对不合格夫妇的女儿，索菲亚从小便感受不到\"关爱\"，也不理解什么是\"爱\"。而她心里的野兽，便是从她想要理解\"爱\"，渴望被\"爱\"的初衷里孕育出来的。\u{1000}\u{1000}索菲亚始终在克制着破坏的冲动，不让自己沦为一只被欲望驱使的野兽。\u{1000}\u{1000}可这种状态又能维持多久呢？也许某一天，平衡就会打破，天平会不可逆转地倒向某一边，也许那时候，索菲亚就不再是人类的伙伴。\u{1000}\u{1000}\"我……不是施虐狂。敌人痛苦时的表情，我是不感兴趣的……但是，在把敌人的肉体、意志摧毁时产生的快乐，却又是货真价实的……我果然，不正常呢。\""},
[601503] = {601503, 1000, "\u{0020}\u{0020}Because\u{0020}of\u{0020}her\u{0020}mental\u{0020}status\u{0020}and\u{0020}inappropriate\u{0020}reason\u{0020}to\u{0020}join\u{0020}Aegis,\u{0020}and\u{0020}the\u{0020}potential\u{0020}danger\u{0020}resulting\u{0020}from\u{0020}her\u{0020}family,\u{0020}although\u{0020}Zofia's\u{0020}Compatability\u{0020}Rate\u{0020}is\u{0020}far\u{0020}above\u{0020}the\u{0020}\"pass\"\u{0020}level\u{0020}of\u{0020}Aegis,\u{0020}Azure\u{0020}Academy\u{0020}in\u{0020}Katya\u{0020}still\u{0020}rejected\u{0020}her\u{0020}application.\n\nWhen\u{0020}Zofia\u{0020}was\u{0020}deciding\u{0020}to\u{0020}give\u{0020}up,\u{0020}a\u{0020}local\u{0020}PMC\u{0020}\"Siren\"\u{0020}sent\u{0020}her\u{0020}an\u{0020}invitation.\n\nIn\u{0020}Katya,\u{0020}\"Cannonbore\"\u{0020}is\u{0020}peculiar,\u{0020}although\u{0020}it's\u{0020}under\u{0020}the\u{0020}command\u{0020}of\u{0020}Aegis\u{0020}Katya\u{0020}Branch,\u{0020}the\u{0020}latter\u{0020}can't\u{0020}interfere\u{0020}its\u{0020}composition.\n\nBecause\u{0020}Cannonbore\u{0020}is\u{0020}a\u{0020}squad\u{0020}of\u{0020}PMC\u{0020}Siren.\n\nSiren\u{0020}gave\u{0020}Zofia\u{0020}an\u{0020}opportunity\u{0020}of\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}because\u{0020}of\u{0020}its\u{0020}own\u{0020}benefit,\u{0020}and\u{0020}apparently,\u{0020}Zofia\u{0020}stood\u{0020}this\u{0020}chance,\u{0020}letting\u{0020}the\u{0020}Sins\u{0020}become\u{0020}the\u{0020}price\u{0020}of\u{0020}her\u{0020}\"destroying\u{0020}spree\".\n\nBut,\u{0020}Zofia\u{0020}is\u{0020}still\u{0020}a\u{0020}timed\u{0020}bomb\u{0020}of\u{0020}Katya…or\u{0020}rather\u{0020}say,\u{0020}\"Cannonbore\",\u{0020}the\u{0020}squad\u{0020}that\u{0020}retrofits\u{0020}drivers'\u{0020}bodies\u{0020}to\u{0020}enhance\u{0020}their\u{0020}combat\u{0020}capabilities,\u{0020}is\u{0020}the\u{0020}biggest\u{0020}potential\u{0020}danger\u{0020}of\u{0020}Katya\u{0020}Branch.", "0", "0", "0", "0", 10015, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}出于对索菲亚精神状态的考量、以及她不正当的申请理由，再加上她复杂家庭背景可能带来的隐患，即使索菲亚的幻化核心适格率已经远远超过艾吉斯定下的合格线，Katya\u{1000}Branch的苍穹学院仍然拒绝了她的入学申请。\u{1000}\u{1000}而在索菲亚打算放弃的时候，向她抛出橄榄枝的人是卡佳当地的民营军火公司\"塞伦\"。\u{1000}\u{1000}在卡佳，\"钢轮戈尔\"是特殊的，尽管它听从Katya\u{1000}Branch的调遣，但Katya\u{1000}Branch却不能干涉\"钢轮戈尔\"的成员构成。\u{1000}\u{1000}因为\"钢轮戈尔\"是属于军火公司\"塞伦\"的驾驶员部队。\u{1000}\u{1000}\"塞伦\"出于自己的考虑，给索菲亚提供了一个成为驾驶员的机会，显然，索菲亚抓住了这次机会，让原罪成为了自己\"破坏欲\"的牺牲品。\u{1000}\u{1000}不过，索菲亚依然是Katya\u{1000}Branch的隐患……或者说，\"钢轮戈尔\"这支对驾驶员的身体进行改造，来增强驾驶员作战能力的部队，是Katya\u{1000}Branch最大的隐患。"},
[601504] = {601504, 2000, "\u{0020}\u{0020}Tornado\u{0020}roars\u{0020}and\u{0020}waves\u{0020}ferociously,\u{0020}raising\u{0020}what's\u{0020}on\u{0020}the\u{0020}ground.\n\nLighting\u{0020}and\u{0020}thunder,\u{0020}fulmination\u{0020}from\u{0020}dark\u{0020}purple\u{0020}clouds\u{0020}lights\u{0020}up\u{0020}the\u{0020}battlefield,\u{0020}At\u{0020}this\u{0020}moment,\u{0020}the\u{0020}beast\u{0020}is\u{0020}raging.\n\nSins,\u{0020}according\u{0020}to\u{0020}humans,\u{0020}are\u{0020}monsters\u{0020}indeed.\n\nBut\u{0020}the\u{0020}gigantified\u{0020}girl,\u{0020}is\u{0020}an\u{0020}atrocious\u{0020}beast\u{0020}that\u{0020}can\u{0020}tear\u{0020}those\u{0020}monsters\u{0020}apart.\u{0020}\"Navigator,\u{0020}I\u{0020}have\u{0020}a\u{0020}strong\u{0020}pulse.\"\n\nCrushed,\u{0020}torn,\u{0020}rammed,\u{0020}smashed,\u{0020}she\u{0020}slaughtered\u{0020}the\u{0020}Sins\u{0020}one\u{0020}by\u{0020}one,and\u{0020}approaches\u{0020}Navigator,\u{0020}step\u{0020}by\u{0020}step.\n\nShe\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}stop,\u{0020}just\u{0020}like\u{0020}she\u{0020}wants\u{0020}to\u{0020}step\u{0020}on\u{0020}that.\n\n\"I\u{0020}want\u{0020}to…obliterate\u{0020}you,\u{0020}but\u{0020}in\u{0020}a\u{0020}different\u{0020}way\u{0020}unlike\u{0020}before.\"\n\n\"I\u{0020}want\u{0020}to\u{0020}destroy\u{0020}you…because\u{0020}I\u{0020}don't\u{0020}want\u{0020}anyone\u{0020}else\u{0020}to\u{0020}have\u{0020}you.\"\n\n\"Yes,\u{0020}I'm\u{0020}not\u{0020}very\u{0020}normal.\"", "0", "0", "0", "0", 10015, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}龙卷狂乱地舞动，将大地卷起，\u{1000}\u{1000}电闪雷鸣，深紫的云闪照亮了战场，\u{1000}\u{1000}此时此刻，野兽正在肆虐。\u{1000}\u{1000}原罪对于人类而言，的确是怪物。\u{1000}\u{1000}但巨大化后的她，却是连怪物也会一并撕烂的，穷凶极恶的野兽。\u{1000}\u{1000}\"领航，我现在有一种冲动。\"\u{1000}\u{1000}碾碎了，撕碎了，撞碎了，敲碎了，把原罪一一屠杀殆尽后的她，\u{1000}\u{1000}一步一步地接近了领航，\u{1000}\u{1000}她没有停下的打算，就像是要这样踩下去似的，\u{1000}\u{1000}\"我想……毁掉你，但是和先前的任何一次都不同。\"\u{1000}\u{1000}\"我想毁掉你……是因为我不想让其他人得到你。\"\u{1000}\u{1000}\"果然，我不太正常呢。"},
[601600] = {601600, 0, "[Name]\u{0020}Anan\n[B-Day]\u{0020}July\u{0020}19\n[Compatability\u{0020}Rate]\u{0020}75%\n[Height]\u{0020}36m\n[Squad]\u{0020}Fledgling\n[Affiliation]\u{0020}Sahara\u{0020}Branch\n[Interest]\u{0020}The\u{0020}hamburger\u{0020}patty\u{0020}made\u{0020}by\u{0020}Tenten", "0", "0", "0", "0", 10016, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}安安\n[B-Day]\u{1000}7月19日\n[幻化核心适格率]\u{1000}75%\n[Height]\u{1000}26m\n[部队]\u{1000}雏鹰\n\u{1000}\u{00A0}[隶属]\u{1000}萨哈拉支部\n[Interest]\u{1000}天天做的汉堡肉"},
[601601] = {601601, 100, "\u{0020}\u{0020}As\u{0020}a\u{0020}driver,\u{0020}Anan\u{0020}is\u{0020}not\u{0020}qualified.\u{0020}Even\u{0020}when\u{0020}she\u{0020}was\u{0020}studying\u{0020}in\u{0020}the\u{0020}academy,\u{0020}she\u{0020}was\u{0020}the\u{0020}one\u{0020}lagging\u{0020}behind.\n\n\"\"The\u{0020}bottom\u{0020}of\u{0020}the\u{0020}academy\",\u{0020}\"The\u{0020}waste\u{0020}material\u{0020}that\u{0020}is\u{0020}hard\u{0020}to\u{0020}encounter\u{0020}in\u{0020}ten\u{0020}years\",\u{0020}\"The\u{0020}super-academy-level\u{0020}fool\",\u{0020}etc...\n\nThese\u{0020}teasing\u{0020}or\u{0020}insulting\u{0020}titles\u{0020}are\u{0020}all\u{0020}labels\u{0020}that\u{0020}people\u{0020}have\u{0020}attached\u{0020}to\u{0020}Anan.\n\nAnan's\u{0020}character\u{0020}is\u{0020}rather\u{0020}weak.\u{0020}Regarding\u{0020}these\u{0020}labels\u{0020}forced\u{0020}upon\u{0020}her\u{0020}by\u{0020}others,\u{0020}she\u{0020}doesn't\u{0020}have\u{0020}the\u{0020}courage\u{0020}to\u{0020}refute.\n\nHowever,\u{0020}what\u{0020}others\u{0020}don't\u{0020}know\u{0020}is\u{0020}that\u{0020}Anan\u{0020}is\u{0020}a\u{0020}very\u{0020}hardworking\u{0020}child.\u{0020}She\u{0020}spends\u{0020}several\u{0020}times\u{0020}more\u{0020}time\u{0020}than\u{0020}others\u{0020}studying\u{0020}and\u{0020}training\u{0020}every\u{0020}day.\u{0020}Although\u{0020}this\u{0020}hasn't\u{0020}brought\u{0020}any\u{0020}changes\u{0020}to\u{0020}Anan,\u{0020}she\u{0020}has\u{0020}always\u{0020}adhered\u{0020}to\u{0020}such\u{0020}a\u{0020}schedule.\n\nThe\u{0020}class\u{0020}monitor,\u{0020}Karen\u{0020}of\u{0020}the\u{0020}same\u{0020}class,\u{0020}was\u{0020}moved\u{0020}by\u{0020}Anan's\u{0020}persistence.\u{0020}When\u{0020}selecting\u{0020}members\u{0020}of\u{0020}the\u{0020}Fledgling\u{0020}team,\u{0020}despite\u{0020}the\u{0020}opposition\u{0020}of\u{0020}others,\u{0020}she\u{0020}forcefully\u{0020}chose\u{0020}Anan\u{0020}as\u{0020}her\u{0020}team\u{0020}member.\n\nIf\u{0020}Anan\u{0020}misses\u{0020}this\u{0020}opportunity,\u{0020}perhaps\u{0020}she\u{0020}will\u{0020}never\u{0020}become\u{0020}a\u{0020}formal\u{0020}driver\u{0020}for\u{0020}her\u{0020}entire\u{0020}life.\n\nAlthough\u{0020}Anan\u{0020}is\u{0020}a\u{0020}fool,\u{0020}she\u{0020}will\u{0020}always\u{0020}keep\u{0020}Karen's\u{0020}kindness\u{0020}in\u{0020}her\u{0020}heart.", "0", "0", "0", "0", 10016, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}作为一个驾驶员来说安安是不够格的，就算是在学院里学习的时候，她也是拖后腿的那个。\n\u{1000}\u{1000}\"学院的吊车尾\"，\"十年难遇的废材\"，\"超学院级的笨蛋\"等等……\n\u{1000}\u{1000}这些或调侃或侮辱性的称号都是人们贴在安安身上的标签。\n\u{1000}\u{1000}安安的性格比较懦弱，对于他人强给她的这些标签，她没有胆量去反驳。\n\u{1000}\u{1000}不过别人不知道的是，安安是个非常努力的孩子。她每天都会花别人几倍的时间去学习和训练。虽然这并没给安安带来任何改变，但是她始终坚持着这样的作息。\n\u{1000}\u{1000}同班的班长卡莲被安安的坚持所打动，在选拔雏鹰小队队员时不顾旁人反对，强行把安安选上作为自己的队员。\n\u{1000}\u{1000}如果错过了这次的机会，安安或许一辈子都成不了正式的驾驶员。\n\u{1000}\u{1000}虽然安安是个笨蛋，但是卡莲的这份恩情她是会永远记在心中。"},
[601602] = {601602, 500, "\u{0020}\u{0020}Azure\u{0020}Academy\u{0020}is\u{0020}different\u{0020}from\u{0020}normal\u{0020}schools\u{0020}and\u{0020}has\u{0020}a\u{0020}special\u{0020}recruitment\u{0020}mechanism.\n\nSimply\u{0020}put,\u{0020}as\u{0020}long\u{0020}as\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}meets\u{0020}the\u{0020}standard,\u{0020}one\u{0020}can\u{0020}enter.\u{0020}This\u{0020}also\u{0020}leads\u{0020}to\u{0020}uneven\u{0020}quality\u{0020}of\u{0020}the\u{0020}admitted\u{0020}students.\n\nIt\u{0020}was\u{0020}a\u{0020}coincidence\u{0020}that\u{0020}Anan\u{0020}was\u{0020}admitted\u{0020}by\u{0020}Azure\u{0020}Academy.\u{0020}Anan's\u{0020}hometown\u{0020}is\u{0020}a\u{0020}very\u{0020}remote\u{0020}village,\u{0020}so\u{0020}remote\u{0020}that\u{0020}even\u{0020}Sin\u{0020}would\u{0020}not\u{0020}invade.\u{0020}The\u{0020}children\u{0020}who\u{0020}stay\u{0020}here\u{0020}have\u{0020}no\u{0020}future.\u{0020}So\u{0020}Anan\u{0020}left\u{0020}her\u{0020}hometown\u{0020}and\u{0020}came\u{0020}to\u{0020}the\u{0020}big\u{0020}city\u{0020}to\u{0020}strive.\u{0020}Just\u{0020}in\u{0020}time,\u{0020}she\u{0020}encountered\u{0020}the\u{0020}recruitment\u{0020}of\u{0020}Azure\u{0020}Academy\u{0020}and\u{0020}passed\u{0020}the\u{0020}test\u{0020}and\u{0020}was\u{0020}admitted\u{0020}into\u{0020}Azure\u{0020}Academy\u{0020}in\u{0020}a\u{0020}muddle-headed\u{0020}way.\n\nThe\u{0020}quality\u{0020}of\u{0020}life\u{0020}of\u{0020}Anan\u{0020}in\u{0020}the\u{0020}academy\u{0020}is\u{0020}guaranteed,\u{0020}and\u{0020}she\u{0020}has\u{0020}a\u{0020}considerable\u{0020}amount\u{0020}of\u{0020}student\u{0020}aid\u{0020}every\u{0020}month.\n\nThis\u{0020}completely\u{0020}conforms\u{0020}to\u{0020}Anan's\u{0020}psychological\u{0020}expectation\u{0020}of\u{0020}urban\u{0020}life.\n\nHowever,\u{0020}when\u{0020}the\u{0020}teaching\u{0020}of\u{0020}the\u{0020}academy\u{0020}officially\u{0020}started,\u{0020}Anan\u{0020}understood\u{0020}what\u{0020}was\u{0020}meant\u{0020}by\u{0020}\"beyond\u{0020}one's\u{0020}ability\".\u{0020}All\u{0020}kinds\u{0020}of\u{0020}courses\u{0020}and\u{0020}arduous\u{0020}daily\u{0020}training\u{0020}have\u{0020}brought\u{0020}endless\u{0020}pressure\u{0020}to\u{0020}this\u{0020}little\u{0020}girl\u{0020}from\u{0020}the\u{0020}village.\u{0020}Before\u{0020}this,\u{0020}Anan\u{0020}had\u{0020}never\u{0020}received\u{0020}cultural\u{0020}education.\u{0020}Even\u{0020}learning\u{0020}to\u{0020}read\u{0020}was\u{0020}taught\u{0020}by\u{0020}her\u{0020}father.\n\nAt\u{0020}the\u{0020}beginning\u{0020}of\u{0020}the\u{0020}course,\u{0020}Anan\u{0020}could\u{0020}still\u{0020}barely\u{0020}keep\u{0020}up\u{0020}with\u{0020}the\u{0020}progress.\u{0020}However,\u{0020}as\u{0020}the\u{0020}course\u{0020}became\u{0020}richer\u{0020}and\u{0020}the\u{0020}content\u{0020}deeper,\u{0020}Anan\u{0020}found\u{0020}that\u{0020}there\u{0020}was\u{0020}so\u{0020}much\u{0020}to\u{0020}learn\u{0020}that\u{0020}she\u{0020}completely\u{0020}couldn't\u{0020}keep\u{0020}up\u{0020}with\u{0020}the\u{0020}teacher's\u{0020}lessons.\u{0020}Gradually,\u{0020}Anan's\u{0020}grades\u{0020}became\u{0020}the\u{0020}lowest\u{0020}in\u{0020}the\u{0020}class,\u{0020}even\u{0020}the\u{0020}lowest\u{0020}in\u{0020}the\u{0020}entire\u{0020}academy.\u{0020}Labels\u{0020}like\u{0020}\"idiot\"\u{0020}and\u{0020}\"good-for-nothing\"\u{0020}gradually\u{0020}increased.\u{0020}Even\u{0020}the\u{0020}teacher\u{0020}gave\u{0020}up\u{0020}on\u{0020}Anan,\u{0020}calling\u{0020}her\u{0020}a\u{0020}\"good-for-nothing\u{0020}once\u{0020}in\u{0020}a\u{0020}decade\".\n\nLayers\u{0020}upon\u{0020}layers\u{0020}of\u{0020}pressure\u{0020}accumulated\u{0020}on\u{0020}Anan,\u{0020}making\u{0020}her\u{0020}unable\u{0020}to\u{0020}catch\u{0020}her\u{0020}breath.\u{0020}Thought\u{0020}of\u{0020}giving\u{0020}up,\u{0020}thought\u{0020}of\u{0020}running\u{0020}away,\u{0020}and\u{0020}also\u{0020}thought\u{0020}of\u{0020}returning\u{0020}to\u{0020}her\u{0020}hometown\u{0020}and\u{0020}living\u{0020}the\u{0020}most\u{0020}familiar\u{0020}and\u{0020}comfortable\u{0020}life\u{0020}-\u{0020}all\u{0020}kinds\u{0020}of\u{0020}cowardly\u{0020}thoughts\u{0020}once\u{0020}occupied\u{0020}Anan's\u{0020}heart.\n\nShe\u{0020}almost\u{0020}couldn't\u{0020}hold\u{0020}on\u{0020}any\u{0020}longer.\n\nFortunately,\u{0020}in\u{0020}the\u{0020}academy,\u{0020}there\u{0020}was\u{0020}one\u{0020}person\u{0020}who\u{0020}did\u{0020}not\u{0020}give\u{0020}up\u{0020}on\u{0020}Anan,\u{0020}and\u{0020}that\u{0020}was\u{0020}Anan's\u{0020}monitor\u{0020}Karen.\n\nKaren\u{0020}saw\u{0020}Anan's\u{0020}efforts\u{0020}and\u{0020}also\u{0020}learned\u{0020}through\u{0020}daily\u{0020}communication\u{0020}that\u{0020}Anan\u{0020}was\u{0020}not\u{0020}stupid.\u{0020}She\u{0020}just\u{0020}had\u{0020}a\u{0020}lower\u{0020}starting\u{0020}point\u{0020}and\u{0020}needed\u{0020}more\u{0020}time\u{0020}to\u{0020}grow.\n\nUnder\u{0020}Karen's\u{0020}persuasion,\u{0020}the\u{0020}teacher\u{0020}kept\u{0020}Anan,\u{0020}and\u{0020}Anan\u{0020}was\u{0020}able\u{0020}to\u{0020}continue\u{0020}her\u{0020}study\u{0020}in\u{0020}the\u{0020}academy.\u{0020}Later,\u{0020}she\u{0020}was\u{0020}taken\u{0020}by\u{0020}Karen\u{0020}to\u{0020}join\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}and\u{0020}became\u{0020}an\u{0020}unofficial\u{0020}driver.\n\nFor\u{0020}Anan,\u{0020}she\u{0020}has\u{0020}always\u{0020}tried\u{0020}her\u{0020}best\u{0020}to\u{0020}achieve\u{0020}everything.\n\nFrom\u{0020}now\u{0020}on,\u{0020}I\u{0020}will\u{0020}strive\u{0020}to\u{0020}complete\u{0020}the\u{0020}tasks\u{0020}and\u{0020}then\u{0020}repay\u{0020}the\u{0020}kindness\u{0020}of\u{0020}Monitor\u{0020}Karen.", "0", "0", "0", "0", 10016, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}苍穹学院与正常的学校不同，拥有一套特殊的招募机制。\u{1000}\u{1000}简单来说就是只要幻化核心适格率达标就能进，这也导致录取的学生质量参差不齐。\u{1000}\u{1000}安安被苍穹学院录取是一个巧合。安安的故乡是个非常偏僻的小村庄，偏僻到连原罪都不会来入侵。留在这里的孩子是没有未来的，所以安安便离开了故乡，来到了大城市打拼，正好遇到了苍穹学院在招生，稀里糊涂地就通过了测试被录取进入苍穹学院。\u{1000}\u{1000}安安在学院里的生活质量是得到了保证的，并且每个月有着一笔可观的助学费。\u{1000}\u{1000}这完全符合安安原本对城市生活的心理预期。\u{1000}\u{1000}然而当学院的教学正式开展后，安安明白了什么叫做\"力不从心\"。五花八门的课程，艰苦的日常训练，都给这个村庄来的小姑娘带来了无穷的压力。在此之前，安安从未接受过文化教育，连识字都是爸爸教的。\u{1000}\u{1000}课程刚开始时，安安还能勉强跟上进度，但是随着课程的丰富和内容的深入，安安发现自己要学的实在太多，完全没法跟上老师讲的课程。渐渐的，安安的成绩成了班里的倒数第一，甚至是全学院最低。\u{1000}\u{1000}\"笨蛋\"\"废材\"之类的称呼也逐渐多了起来。就连老师都放弃了安安，称呼她为\"十年难遇的废材\"。\u{1000}\u{1000}一层又一层的压力积压在安安身上，压得她喘不过气来。想过放弃，想过逃走，还想过回到家乡，过上自己最熟悉的，最舒适的生活——种种怯懦的想法，曾经盘踞在安安的心里。\u{1000}\u{1000}她差点就坚持不下去了。\u{1000}\u{1000}幸好在学院中，有一个人没有放弃安安，那就是安安的班长卡莲。\u{1000}\u{1000}卡莲看到了安安的努力，也通过平时的交流了解到安安并不是笨蛋，她只是起点比别人低，需要更多的时间去成长。\u{1000}\u{1000}在卡莲的劝说下，老师留下了安安，安安也得以继续留在学院进行学习，更是在之后被卡莲带着一起加入了雏鹰小队，成为非正式的驾驶员。\u{1000}\u{1000}而对安安来说，她自始至终都是在尽自己最大的努力去完成每一件事。\u{1000}\u{1000}\"今后，我要努力完成任务，然后报答卡莲班长的恩情。\""},
[601603] = {601603, 1000, "\u{0020}After\u{0020}joining\u{0020}the\u{0020}Fledgeling\u{0020}Eagle,\u{0020}Anan\u{0020}felt\u{0020}even\u{0020}more\u{0020}relaxed\u{0020}than\u{0020}at\u{0020}Azure\u{0020}Academy.\u{0020}Here,\u{0020}there\u{0020}were\u{0020}no\u{0020}dazzling\u{0020}courses\u{0020}and\u{0020}ruthless\u{0020}ridicule\u{0020}from\u{0020}others.\n\nWhether\u{0020}it's\u{0020}Captain\u{0020}Karen\u{0020}or\u{0020}team\u{0020}member\u{0020}Tenten,\u{0020}they\u{0020}both\u{0020}hold\u{0020}a\u{0020}friendly\u{0020}attitude\u{0020}towards\u{0020}Anan\u{0020}and\u{0020}take\u{0020}care\u{0020}of\u{0020}her\u{0020}in\u{0020}all\u{0020}aspects.\n\nSince\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}was\u{0020}formed\u{0020}temporarily,\u{0020}their\u{0020}gigantification\u{0020}equipment\u{0020}was\u{0020}also\u{0020}temporarily\u{0020}allocated.\u{0020}Anan\u{0020}chose\u{0020}a\u{0020}shield\u{0020}as\u{0020}the\u{0020}main\u{0020}equipment\u{0020}under\u{0020}Karen's\u{0020}suggestion.\n\nTo\u{0020}outsiders,\u{0020}this\u{0020}shield\u{0020}seems\u{0020}to\u{0020}be\u{0020}used\u{0020}to\u{0020}protect\u{0020}Anan\u{0020}herself\u{0020}rather\u{0020}than\u{0020}others,\u{0020}and\u{0020}the\u{0020}mechanical\u{0020}prosthetic\u{0020}leg\u{0020}for\u{0020}assisting\u{0020}in\u{0020}marching\u{0020}must\u{0020}also\u{0020}be\u{0020}for\u{0020}giving\u{0020}Anan\u{0020}higher\u{0020}mobility\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}enabling\u{0020}her\u{0020}to\u{0020}escape\u{0020}danger\u{0020}at\u{0020}any\u{0020}time.\n\nWhen\u{0020}carrying\u{0020}out\u{0020}the\u{0020}mission,\u{0020}Anan's\u{0020}performance\u{0020}surprised\u{0020}those\u{0020}outsiders.\u{0020}In\u{0020}the\u{0020}mission\u{0020}of\u{0020}protecting\u{0020}the\u{0020}retreat\u{0020}of\u{0020}civilians,\u{0020}she\u{0020}utilized\u{0020}her\u{0020}high\u{0020}mobility\u{0020}and\u{0020}repeatedly\u{0020}defended\u{0020}against\u{0020}the\u{0020}attacks\u{0020}of\u{0020}the\u{0020}Sin\u{0020}with\u{0020}the\u{0020}shield.\n\nAnan\u{0020}proved\u{0020}with\u{0020}her\u{0020}actual\u{0020}performance\u{0020}that\u{0020}she\u{0020}is\u{0020}not\u{0020}a\u{0020}fool\u{0020}or\u{0020}good-for-nothing.\u{0020}She\u{0020}just\u{0020}needs\u{0020}time\u{0020}to\u{0020}grow.\n\nShe\u{0020}is\u{0020}no\u{0020}longer\u{0020}the\u{0020}despised\u{0020}bottom\u{0020}of\u{0020}the\u{0020}class\u{0020}but\u{0020}has\u{0020}become\u{0020}the\u{0020}\"guardian\u{0020}angel\"\u{0020}in\u{0020}the\u{0020}hearts\u{0020}of\u{0020}civilians.", "0", "0", "0", "0", 10016, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}在加入雏鹰小队后的安安反而比在苍穹学院里更感觉更加轻松。在这里没有让人眼花缭乱的课程，和别人无情的嘲笑。\u{1000}\u{1000}无论是队长卡莲还是队员天天都对安安抱着友善的态度，更是在各方面照顾着安安。\u{1000}\u{1000}由于雏鹰小队是临时组成的，所以她们的巨大化装备也是临时调配。安安在卡莲的建议下选择了一面盾牌作为主要装备。\u{1000}\u{1000}在外人看来，这盾牌与其说是用来保护其他人，不如说是用来保护安安自己，而辅助行军的机械义腿，也一定是为了让安安在战场上有着更高的机动性，让她能够在任何时候脱离险境。\u{1000}\u{1000}当正式执行任务时，安安的表现让那些外人大吃一惊。她在执行保护平民撤退的任务中，利用自己的高机动性，一次又一次地用盾牌抵御了原罪的进攻。\u{1000}\u{1000}安安用实际表现证明了她并不是笨蛋废柴，她只是需要成长的时间。\u{1000}\u{1000}她不再是被人嫌弃的吊车尾，成为了平民心中的\"守护神\"。"},
[601604] = {601604, 2000, "\u{0020}\u{0020}We\u{0020}have\u{0020}walked\u{0020}along\u{0020}the\u{0020}road\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\n\nOne\u{0020}must\u{0020}not\u{0020}let\u{0020}down\u{0020}vigilance.\u{0020}Danger\u{0020}may\u{0020}come\u{0020}at\u{0020}any\u{0020}time.\n\nA\u{0020}violent\u{0020}vibration\u{0020}came\u{0020}from\u{0020}the\u{0020}ground.\u{0020}It\u{0020}was\u{0020}her!\u{0020}That\u{0020}girl\u{0020}as\u{0020}tall\u{0020}as\u{0020}a\u{0020}high-rise\u{0020}building.\n\nPeople\u{0020}are\u{0020}not\u{0020}afraid.\n\nBecause\u{0020}the\u{0020}girl\u{0020}is\u{0020}their\u{0020}\"guardian\u{0020}angel\"\u{0020}.\n\nPeople\u{0020}looked\u{0020}up\u{0020}at\u{0020}the\u{0020}girl,\u{0020}and\u{0020}on\u{0020}the\u{0020}other\u{0020}side\u{0020}of\u{0020}the\u{0020}road,\u{0020}a\u{0020}monster\u{0020}that\u{0020}played\u{0020}the\u{0020}role\u{0020}of\u{0020}the\u{0020}girl's\u{0020}enemy\u{0020}appeared.\n\nIts\u{0020}meteor-like\u{0020}attack\u{0020}hit\u{0020}the\u{0020}girl's\u{0020}shield.\n\nThe\u{0020}girl's\u{0020}feet\u{0020}plowed\u{0020}two\u{0020}deep\u{0020}ditches\u{0020}on\u{0020}the\u{0020}ground.\n\nBut\u{0020}she\u{0020}didn't\u{0020}take\u{0020}a\u{0020}step\u{0020}backward.\n\n\"I\u{0020}cannot\u{0020}retreat.\u{0020}I\u{0020}must\u{0020}protect\u{0020}them\u{0020}well!\u{0020}\"\n\n\"Because\u{0020}this\u{0020}is\u{0020}the\u{0020}only\u{0020}thing\u{0020}I\u{0020}can\u{0020}do,\u{0020}I\u{0020}must\u{0020}do\u{0020}it\u{0020}well!\u{0020}\"\n\nThis\u{0020}is\u{0020}the\u{0020}reason\u{0020}why\u{0020}people\u{0020}trust\u{0020}her.", "0", "0", "0", "0", 10016, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}顺着道路走了很久了，\u{1000}\u{1000}还不能放松警惕，危险随时会降临。\u{1000}\u{1000}地面传来剧烈的震动，是她！那个高楼般的少女。\u{1000}\u{1000}人们并不害怕，\u{1000}\u{1000}因为少女是他们的守护神。\u{1000}\u{1000}人们仰视着少女，道路的另一头，饰演少女敌人一角的怪物出现了。\u{1000}\u{1000}它流星般的攻击打在少女的盾牌上，\u{1000}\u{1000}少女的双脚在地面上犁出两道深深的沟渠。\u{1000}\u{1000}但是她没有后退一步。\u{1000}\u{1000}\"我不能后退，我要保护好他们！\"\u{1000}\u{1000}\"因为这是我唯一能做到的事，我必须做好！\"\u{1000}\u{1000}这就是人们信赖她的原因。"},
[601700] = {601700, 0, "[Name]\u{0020}Rosalind\n[B-Day]\u{0020}April\u{0020}16\n[Compatability\u{0020}Rate]\u{0020}84%\n[Height]\u{0020}35m\n[Squad]\u{0020}Frontier\n[Affiliation]\u{0020}Maya\u{0020}Branch\n[Interest]\u{0020}Trim\u{0020}and\u{0020}maintain\u{0020}nails", "0", "0", "0", "0", 10017, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}罗莎琳德\n[B-Day]\u{1000}4月16日\n[幻化核心适格率]\u{1000}84%\n[\u{1000}巨大化身高]\u{1000}31m\n[部队]\u{1000}前线\n\u{1000}\u{00A0}[\u{1000}隶属]\u{1000}Maya\u{1000}Branch\n[Interest]\u{1000}修剪、养护自己的指甲"},
[601701] = {601701, 100, "\u{0020}\u{0020}Rosalind,\u{0020}Maya\u{0020}Branch\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}members\u{0020}directly\u{0020}under\u{0020}the\u{0020}[Frontier]\u{0020}\u{0020}AVG\u{0020}troops.\u{0020}After\u{0020}graduating\u{0020}from\u{0020}Azure\u{0020}Academy,\u{0020}she\u{0020}directly\u{0020}joined\u{0020}the\u{0020}[Frontier]\u{0020}\u{0020}troops\u{0020}to\u{0020}fill\u{0020}the\u{0020}position\u{0020}of\u{0020}a\u{0020}predecessor\u{0020}who\u{0020}sacrificed\u{0020}in\u{0020}the\u{0020}battle\u{0020}against\u{0020}Sin.\n\nRosalind,\u{0020}who\u{0020}is\u{0020}used\u{0020}to\u{0020}wielding\u{0020}two\u{0020}swords,\u{0020}volunteered\u{0020}to\u{0020}be\u{0020}the\u{0020}vanguard\u{0020}of\u{0020}the\u{0020}team\u{0020}and\u{0020}was\u{0020}responsible\u{0020}for\u{0020}rushing\u{0020}to\u{0020}the\u{0020}front\u{0020}line\u{0020}of\u{0020}the\u{0020}team.As\u{0020}a\u{0020}newcomer,\u{0020}Rosalind's\u{0020}performance\u{0020}can\u{0020}no\u{0020}longer\u{0020}be\u{0020}described\u{0020}merely\u{0020}as\u{0020}excellent.\u{0020}In\u{0020}her\u{0020}first\u{0020}mission,\u{0020}she\u{0020}completely\u{0020}annihilated\u{0020}the\u{0020}Sin\u{0020}within\u{0020}the\u{0020}mission\u{0020}area\u{0020}with\u{0020}a\u{0020}100%\u{0020}completion\u{0020}rate.\u{0020}Although\u{0020}they\u{0020}are\u{0020}only\u{0020}some\u{0020}low-level\u{0020}Sins,\u{0020}but\u{0020}with\u{0020}such\u{0020}a\u{0020}huge\u{0020}number,\u{0020}even\u{0020}veterans\u{0020}who\u{0020}have\u{0020}been\u{0020}through\u{0020}many\u{0020}battles\u{0020}have\u{0020}to\u{0020}exert\u{0020}a\u{0020}lot\u{0020}of\u{0020}effort\u{0020}to\u{0020}deal\u{0020}with\u{0020}them.\n\nHowever,\u{0020}contrary\u{0020}to\u{0020}her\u{0020}reliability\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}Rosalind\u{0020}is\u{0020}not\u{0020}an\u{0020}easy\u{0020}person\u{0020}to\u{0020}get\u{0020}along\u{0020}with\u{0020}in\u{0020}daily\u{0020}life.\u{0020}Rosalind,\u{0020}who\u{0020}comes\u{0020}from\u{0020}an\u{0020}ordinary\u{0020}family,\u{0020}always\u{0020}regards\u{0020}herself\u{0020}as\u{0020}a\u{0020}\"noble\"\u{0020}and\u{0020}likes\u{0020}to\u{0020}compete\u{0020}with\u{0020}others\u{0020}on\u{0020}some\u{0020}strange\u{0020}little\u{0020}things.\n\nIn\u{0020}order\u{0020}to\u{0020}maintain\u{0020}her\u{0020}\"noble\"\u{0020}identity,\u{0020}Rosalind\u{0020}also\u{0020}set\u{0020}up\u{0020}many\u{0020}flawed\u{0020}personas\u{0020}for\u{0020}herself.\u{0020}Once\u{0020}exposed,\u{0020}she\u{0020}would\u{0020}blush\u{0020}and\u{0020}argue.\u{0020}If\u{0020}she\u{0020}couldn't\u{0020}win\u{0020}the\u{0020}argument,\u{0020}she\u{0020}would\u{0020}throw\u{0020}out\u{0020}a\u{0020}sentence,\u{0020}\"Matters\u{0020}of\u{0020}the\u{0020}nobility,\u{0020}you\u{0020}wouldn't\u{0020}understand\u{0020}even\u{0020}if\u{0020}I\u{0020}told\u{0020}you,\"\u{0020}and\u{0020}then\u{0020}sulkily\u{0020}run\u{0020}back\u{0020}to\u{0020}her\u{0020}room.\n\nAccording\u{0020}to\u{0020}other\u{0020}team\u{0020}members,\u{0020}seeing\u{0020}Rosalind's\u{0020}cute\u{0020}expression\u{0020}when\u{0020}exposed\u{0020}is\u{0020}also\u{0020}a\u{0020}kind\u{0020}of\u{0020}enjoyment.", "0", "0", "0", "0", 10017, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}罗莎琳德，Maya\u{1000}Branch直属[前线]\u{1000}avg部队成员之一，在从苍穹学院毕业后直接加入了[前线]\u{1000}部队以填补上一个在与原罪战斗中牺牲的前辈的位子。\n\u{1000}\u{1000}习惯使用双剑的罗莎琳德自告奋勇担任队伍中的先锋，负责冲在队伍第一线。作为一个新人，罗莎琳德的表现已经不能仅仅用优秀来形容。首次任务便以100%的完成度全歼了任务区内的原罪。虽然只是些低等的原罪，但是庞大的数量，就算是久经沙场的老兵也得费很大的力气才能做到。\n\u{1000}\u{1000}然而与战场上的可靠相反，在平时生活中的罗莎琳德不是个容易相处的人。\n\u{1000}\u{1000}普通家庭出身的罗莎琳德总以\"贵族\"自居，喜欢在一些奇怪的小事上与人攀比。\n\u{1000}\u{1000}为了维持自己\"贵族\"身份，罗莎琳德也给自己立了很多漏洞百出的人设，一旦被人戳穿了，便红着脸争辩，辩不过就扔下一句\"贵族的事，说了你们也不懂\"，然后悻悻地跑回自己的房间。\n\u{1000}\u{1000}据其他队员所说，看到罗莎琳德被揭穿时的可爱表情，倒也不妨是一种享受。"},
[601702] = {601702, 500, "\u{0020}\u{0020}According\u{0020}to\u{0020}Rosalind\u{0020}herself,\u{0020}she\u{0020}came\u{0020}from\u{0020}a\u{0020}Mayan\u{0020}noble\u{0020}family\u{0020}and\u{0020}was\u{0020}the\u{0020}eldest\u{0020}daughter\u{0020}in\u{0020}the\u{0020}family.\u{0020}Rosalind\u{0020}received\u{0020}a\u{0020}traditional\u{0020}aristocratic\u{0020}education\u{0020}from\u{0020}a\u{0020}young\u{0020}age,\u{0020}and\u{0020}did\u{0020}not\u{0020}go\u{0020}to\u{0020}school\u{0020}to...\u{0020}experience\u{0020}life.\u{0020}As\u{0020}the\u{0020}sole\u{0020}heir\u{0020}of\u{0020}the\u{0020}family,\u{0020}Rosalind\u{0020}shoulders\u{0020}the\u{0020}burden\u{0020}of\u{0020}revitalizing\u{0020}and\u{0020}inheriting\u{0020}the\u{0020}family's\u{0020}glory...\n\nIn\u{0020}fact,\u{0020}most\u{0020}of\u{0020}this\u{0020}story\u{0020}is\u{0020}relatively\u{0020}reasonable,\u{0020}except\u{0020}for\u{0020}one\u{0020}thing\u{0020}-\u{0020}there\u{0020}were\u{0020}no\u{0020}nobles\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region.\n\nIn\u{0020}fact,\u{0020}when\u{0020}Rosalind\u{0020}was\u{0020}young,\u{0020}reading\u{0020}Danube\u{0020}noble\u{0020}novels\u{0020}was\u{0020}popular\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region.\u{0020}However,\u{0020}the\u{0020}Maya\u{0020}was\u{0020}a\u{0020}place\u{0020}that\u{0020}advocated\u{0020}freedom,\u{0020}and\u{0020}there\u{0020}were\u{0020}no\u{0020}nobles\u{0020}likeDanube\u{0020}or\u{0020}Katya\u{0020}before.\u{0020}However,\u{0020}this\u{0020}does\u{0020}not\u{0020}mean\u{0020}that\u{0020}there\u{0020}was\u{0020}no\u{0020}oppression\u{0020}in\u{0020}Maya.\u{0020}Here,\u{0020}there\u{0020}was\u{0020}another\u{0020}form\u{0020}of\u{0020}contradiction,\u{0020}that\u{0020}is,\u{0020}the\u{0020}rich\u{0020}and\u{0020}the\u{0020}poor.\u{0020}The\u{0020}freedom\u{0020}of\u{0020}Maya\u{0020}largely\u{0020}belonged\u{0020}to\u{0020}the\u{0020}rich.\u{0020}For\u{0020}the\u{0020}poor,\u{0020}there\u{0020}was\u{0020}only\u{0020}suffocating\u{0020}life\u{0020}pressure\u{0020}here.\n\nRosalind's\u{0020}family\u{0020}belonged\u{0020}to\u{0020}the\u{0020}middle-class\u{0020}in\u{0020}Maya.\u{0020}There\u{0020}were\u{0020}three\u{0020}people\u{0020}in\u{0020}the\u{0020}family,\u{0020}Rosalind\u{0020}and\u{0020}her\u{0020}parents.\u{0020}Nominaly,\u{0020}their\u{0020}family\u{0020}was\u{0020}the\u{0020}middle\u{0020}class\u{0020}of\u{0020}society.\u{0020}In\u{0020}fact,\u{0020}they\u{0020}could\u{0020}only\u{0020}manage\u{0020}to\u{0020}have\u{0020}enough\u{0020}to\u{0020}eat\u{0020}and\u{0020}buy\u{0020}a\u{0020}cake\u{0020}every\u{0020}month.\n\nThe\u{0020}only\u{0020}place\u{0020}that\u{0020}can\u{0020}be\u{0020}regarded\u{0020}as\u{0020}equal\u{0020}in\u{0020}the\u{0020}Maya\u{0020}region\u{0020}is\u{0020}only\u{0020}the\u{0020}school.\u{0020}The\u{0020}children\u{0020}of\u{0020}the\u{0020}poor\u{0020}and\u{0020}the\u{0020}rich\u{0020}can\u{0020}attend\u{0020}the\u{0020}same\u{0020}school\u{0020}and\u{0020}receive\u{0020}the\u{0020}same\u{0020}education.\u{0020}But\u{0020}this\u{0020}also\u{0020}leads\u{0020}to\u{0020}another\u{0020}problem.\u{0020}The\u{0020}children\u{0020}of\u{0020}the\u{0020}rich\u{0020}are\u{0020}always\u{0020}the\u{0020}powerful\u{0020}ones\u{0020}in\u{0020}the\u{0020}school,\u{0020}while\u{0020}the\u{0020}children\u{0020}of\u{0020}the\u{0020}poor\u{0020}can\u{0020}only\u{0020}accept\u{0020}their\u{0020}bullying\u{0020}unless\u{0020}they\u{0020}curry\u{0020}favor\u{0020}with\u{0020}those\u{0020}rich\u{0020}people.\n\nRosalind\u{0020}was\u{0020}one\u{0020}of\u{0020}the\u{0020}children\u{0020}who\u{0020}were\u{0020}unwilling\u{0020}to\u{0020}curry\u{0020}favor\u{0020}with\u{0020}the\u{0020}rich\u{0020}and\u{0020}was\u{0020}naturally\u{0020}bullied.\u{0020}In\u{0020}order\u{0020}to\u{0020}protect\u{0020}herself\u{0020}and\u{0020}the\u{0020}children\u{0020}of\u{0020}other\u{0020}poor\u{0020}people,\u{0020}Rosalind\u{0020}packaged\u{0020}herself\u{0020}with\u{0020}the\u{0020}noble\u{0020}image\u{0020}she\u{0020}saw\u{0020}in\u{0020}novels\u{0020}and\u{0020}falsely\u{0020}claimed\u{0020}to\u{0020}be\u{0020}of\u{0020}noble\u{0020}origin,\u{0020}which\u{0020}actually\u{0020}fooled\u{0020}many\u{0020}people.\u{0020}And\u{0020}those\u{0020}children\u{0020}who\u{0020}truly\u{0020}have\u{0020}noble\u{0020}family\u{0020}backgrounds\u{0020}have\u{0020}always\u{0020}been\u{0020}disdainful\u{0020}of\u{0020}getting\u{0020}involved\u{0020}with\u{0020}them,\u{0020}so\u{0020}no\u{0020}one\u{0020}exposed\u{0020}Rosalind.\n\nRosalind\u{0020}became\u{0020}a\u{0020}well-known\u{0020}noble\u{0020}young\u{0020}lady\u{0020}in\u{0020}the\u{0020}school.\n\n\\u{0020}However,\u{0020}as\u{0020}she\u{0020}grew\u{0020}up,\u{0020}Rosalind\u{0020}increasingly\u{0020}felt\u{0020}the\u{0020}huge\u{0020}gap\u{0020}between\u{0020}herself\u{0020}and\u{0020}those\u{0020}true\u{0020}nobles.\n\n\"One\u{0020}must\u{0020}find\u{0020}a\u{0020}way\u{0020}to\u{0020}earn\u{0020}a\u{0020}lot\u{0020}of\u{0020}money\u{0020}and\u{0020}become\u{0020}a\u{0020}true\u{0020}noble\u{0020}to\u{0020}change\u{0020}all\u{0020}this.\u{0020}\"\n\nRosalind\u{0020}has\u{0020}only\u{0020}one\u{0020}thought\u{0020}at\u{0020}the\u{0020}moment:\u{0020}As\u{0020}long\u{0020}as\u{0020}there\u{0020}is\u{0020}money,\u{0020}the\u{0020}current\u{0020}situation\u{0020}can\u{0020}be\u{0020}changed.\u{0020}And\u{0020}coincidentally,\u{0020}at\u{0020}this\u{0020}time\u{0020}she\u{0020}saw\u{0020}the\u{0020}advertisement\u{0020}for\u{0020}driver\u{0020}recruitment.\n\n\"If\u{0020}I\u{0020}become\u{0020}a\u{0020}driver\u{0020}and\u{0020}eliminate\u{0020}the\u{0020}Sin,\u{0020}I\u{0020}can\u{0020}earn\u{0020}a\u{0020}lot\u{0020}of\u{0020}money!\u{0020}Then\u{0020}I\u{0020}can\u{0020}really\u{0020}become\u{0020}a\u{0020}noble,\u{0020}live\u{0020}in\u{0020}a\u{0020}big\u{0020}house\u{0020}with\u{0020}my\u{0020}parents,\u{0020}and\u{0020}also\u{0020}have\u{0020}the\u{0020}ability\u{0020}to\u{0020}help\u{0020}the\u{0020}poor\u{0020}people\u{0020}in\u{0020}Maya\u{0020}live\u{0020}a\u{0020}better\u{0020}life.\"", "0", "0", "0", "0", 10017, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}根据罗莎琳德本人所述，她来自一个玛雅贵族家庭，是家中的长女。从小罗莎琳德接受的都是传统贵族式教育，直到上学的年纪才到学校里…体验生活。而作为家族的唯一继承人，罗莎琳德身上肩负着振兴和传承家族荣耀的重担……\u{1000}\u{1000}其实这个故事大部分还是比较合理的，除了一点——玛雅地区没有贵族。\u{1000}\u{1000}事实上，在罗莎琳德小的时候玛雅地区正流行着看阅读多瑙贵族小说，而玛雅是一个崇尚自由的地方，在这里并没有像多瑙或卡佳之前那样的贵族的存在。但是这并不意味着玛雅就没有压迫，在这里有着另一种形式的矛盾，那就是富人和穷人。玛雅的自由很大程度上是属于富人的，对于穷人来说这里只有窒息般的生活压力。\u{1000}\u{1000}罗莎琳德的家庭在玛雅属于中产阶级家庭，家中一共三口人，罗莎琳德和她的父母。名义上他们家是社会的中间层，实际上也只是在勉强温饱之余能每个月买个蛋糕吃。\u{1000}\u{1000}而玛雅地区唯一能算得上平等的地方只剩学校了。穷人和富人的孩子都能上同样的学校进行相同的教育。但是这也导致另一个问题，富人的孩子永远是学校中的强势，而穷人的孩子除非巴结那些富人不然只能接受他们的霸凌。\u{1000}\u{1000}罗莎琳德就是不愿意巴结富人的孩子中的一个，自然也受到了欺负。为了保护自己以及其他穷人的孩子，罗莎琳德用自己从小说中看到的贵族形象包装自己，谎称自己是贵族出身，倒也唬住了很多人。而那些真正拥有贵族般家庭出身的孩子一向是不屑于与他们掺和在一起，所以也没人揭穿罗莎琳德。\u{1000}\u{1000}罗莎琳德成为了学校中知名的贵族千金。\u{1000}\u{1000}然而随着成长，罗莎琳德愈发感到自己和那些真正的贵族间的差距之大。\u{1000}\u{1000}\"必须想办法赚大钱，成为真正的贵族才能改变这一切。\"\u{1000}\u{1000}罗莎琳德此刻只有一个想法：只要有钱就能改变现状。而恰巧这时她看到了驾驶员招募的广告。\u{1000}\u{1000}\"成为驾驶员，消灭原罪的话，我就能获得很多钱吧！到时候就能真的成为贵族，带着爸爸妈妈住大房子了，也有能力帮助玛雅的穷人们生活得更好。\""},
[601703] = {601703, 1000, "\u{0020}\u{0020}Joining\u{0020}Frontier,\u{0020}Rosalind\u{0020}is\u{0020}constantly\u{0020}growing.\n\nNot\u{0020}only\u{0020}in\u{0020}combat\u{0020}but\u{0020}also\u{0020}in\u{0020}state\u{0020}of\u{0020}mind.\u{0020}If\u{0020}at\u{0020}the\u{0020}beginning\u{0020}she\u{0020}became\u{0020}a\u{0020}driver\u{0020}for\u{0020}money,\u{0020}then\u{0020}in\u{0020}the\u{0020}fierce\u{0020}battles\u{0020}with\u{0020}Sin\u{0020}again\u{0020}and\u{0020}again,\u{0020}after\u{0020}witnessing\u{0020}cities\u{0020}destroyed\u{0020}by\u{0020}Sin\u{0020}one\u{0020}after\u{0020}another,\u{0020}the\u{0020}obsession\u{0020}with\u{0020}money\u{0020}in\u{0020}Rosalind's\u{0020}heart\u{0020}gradually\u{0020}transformed\u{0020}into\u{0020}an\u{0020}emotion\u{0020}mingled\u{0020}with\u{0020}fear\u{0020}and\u{0020}anger.\n\n\"If...\u{0020}If\u{0020}everything\u{0020}has\u{0020}been\u{0020}destroyed\u{0020}by\u{0020}Sin,\u{0020}then\u{0020}what's\u{0020}the\u{0020}use\u{0020}of\u{0020}money?\u{0020}\"\n\nNow\u{0020}Rosalind\u{0020}has\u{0020}finally\u{0020}realized\u{0020}that\u{0020}Sin\u{0020}is\u{0020}the\u{0020}biggest\u{0020}obstacle\u{0020}on\u{0020}her\u{0020}way\u{0020}to\u{0020}achieving\u{0020}her\u{0020}dream.\n\nSo\u{0020}an\u{0020}important\u{0020}item\u{0020}was\u{0020}added\u{0020}to\u{0020}Rosalind's\u{0020}life\u{0020}creed\u{0020}-\u{0020}all\u{0020}Sins\u{0020}must\u{0020}be\u{0020}eliminated.\u{0020}", "0", "0", "0", "0", 10017, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}加入前线的罗莎琳德是在不断成长的。\u{1000}\u{1000}不仅指战斗上更是心境上的成长。如果说一开始是为了钱成为驾驶员，那么在一次次与原罪的惨烈战斗中，在目睹一座座原罪摧毁的城市之后，罗莎琳德的心中对于金钱的执着渐渐转化成了一种恐惧和愤怒所交揉的情感。\u{1000}\u{1000}\"如果…如果说一切都被原罪摧毁了，那要钱又有什么用呢？\"\u{1000}\u{1000}现在罗莎琳德也终于意识到，原罪是她实现梦想路上的最大障碍。\u{1000}\u{1000}于是在罗莎琳德的人生信条上又添加了重要的一条——必须消灭所有原罪。"},
[601704] = {601704, 2000, "\u{0020}The\u{0020}people\u{0020}in\u{0020}the\u{0020}free\u{0020}country\u{0020}might\u{0020}have\u{0020}never\u{0020}been\u{0020}free.\n\nHowever,\u{0020}the\u{0020}land\u{0020}trampled\u{0020}by\u{0020}Sin\u{0020}is\u{0020}filled\u{0020}with\u{0020}Sin.\n\n\"This\u{0020}young\u{0020}lady\u{0020}will\u{0020}take\u{0020}them\u{0020}down.\u{0020}You\u{0020}just\u{0020}give\u{0020}orders\u{0020}at\u{0020}the\u{0020}rear.\"\n\nShe\u{0020}brandished\u{0020}the\u{0020}two\u{0020}blades\u{0020}as\u{0020}if\u{0020}she\u{0020}were\u{0020}a\u{0020}princess\u{0020}dancing\u{0020}at\u{0020}a\u{0020}noble\u{0020}ball.\n\nWhen\u{0020}she\u{0020}stopped\u{0020}dancing,\u{0020}continuous\u{0020}\"applause\"\u{0020}rang\u{0020}out\u{0020}around\u{0020}her.\n\nThat\u{0020}was\u{0020}the\u{0020}sound\u{0020}of\u{0020}the\u{0020}corpse\u{0020}of\u{0020}Sin\u{0020}colliding\u{0020}with\u{0020}the\u{0020}earth.\n\nRosalind\u{0020}slightly\u{0020}bowed\u{0020}and\u{0020}saluted\u{0020}to\u{0020}the\u{0020}only\u{0020}audience\u{0020}present.\n\nThe\u{0020}only\u{0020}remaining\u{0020}building\u{0020}became\u{0020}her\u{0020}platform.\n\n\"It's\u{0020}over.\u{0020}\"\n\nAt\u{0020}this\u{0020}moment,\u{0020}Rosalind\u{0020}was\u{0020}like\u{0020}a\u{0020}true\u{0020}noble.\n\nElegant\u{0020}and\u{0020}haughty.", "0", "0", "0", "0", 10017, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}自由国度上的人民或许从未有过自由，\u{1000}\u{1000}但是原罪践踏过的土地却充斥着原罪。\u{1000}\u{1000}\"本小姐会解决它们的，你就安心在后方指挥吧。\"\u{1000}\u{1000}她舞动着双刀，就像在贵族舞会上起舞的公主。\u{1000}\u{1000}当她停下舞步，周围便响起了连绵的\"掌声\"，\u{1000}\u{1000}那是原罪的尸体与大地碰撞的声响。\u{1000}\u{1000}罗莎琳德略一欠身，向在场唯一的观众行礼。\u{1000}\u{1000}仅存的大楼，成为了她的讲台。\u{1000}\u{1000}\"结束了。\"\u{1000}\u{1000}这一刻的罗莎琳德就像真正的贵族，\u{1000}\u{1000}优雅而高傲。"},
[601800] = {601800, 0, "[Name]\u{0020}Lyfa\n[B-Day]\u{0020}Feb\u{0020}11\n[Compatability\u{0020}Rate]\u{0020}86%\n[Height]\u{0020}36m\n[Squad]\u{0020}Valkyrie\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Prank\u{0020}the\u{0020}people\u{0020}she\u{0020}is\u{0020}fond\u{0020}of,\u{0020}maid\u{0020}practicing.", "0", "0", "0", "0", 10018, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}莉法\n[B-Day]\u{1000}2月11日\n[幻化核心适格率]\u{1000}86%\n[Height]\u{1000}36m\n[部队]\u{1000}瓦尔基里\n\u{1000}[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}女仆活动"},
[601801] = {601801, 100, "\u{0020}\u{0020}Although\u{0020}the\u{0020}members\u{0020}of\u{0020}\"Valkyrie\"\u{0020}give\u{0020}people\u{0020}an\u{0020}impression\u{0020}of\u{0020}being\u{0020}dedicated\u{0020}and\u{0020}serious\u{0020}to\u{0020}their\u{0020}duties,\u{0020}Lyfa\u{0020}is\u{0020}an\u{0020}outlier.\n\nPerhaps\u{0020}because\u{0020}she\u{0020}likes\u{0020}wearing\u{0020}a\u{0020}maid\u{0020}costume\u{0020}to\u{0020}provide\u{0020}services\u{0020}for\u{0020}other\u{0020}workers\u{0020}in\u{0020}her\u{0020}institute,\u{0020}it's\u{0020}hard\u{0020}to\u{0020}connect\u{0020}her\u{0020}with\u{0020}a\u{0020}Valkyrie.\n\nBeing\u{0020}able\u{0020}to\u{0020}join\u{0020}Valkyrie,\u{0020}Lyfa's\u{0020}combat\u{0020}capability\u{0020}is\u{0020}without\u{0020}doubt.\u{0020}In\u{0020}our\u{0020}daily\u{0020}life\u{0020}she's\u{0020}a\u{0020}meticulous\u{0020}master\u{0020}of\u{0020}maid,\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}she's\u{0020}a\u{0020}tough\u{0020}and\u{0020}reliable\u{0020}nightmare\u{0020}for\u{0020}Sins.\n\nStrong\u{0020}and\u{0020}capable\u{0020}in\u{0020}actions,\u{0020}considerate\u{0020}and\u{0020}careful\u{0020}in\u{0020}her\u{0020}daily\u{0020}life,\u{0020}there\u{0020}might\u{0020}be\u{0020}no\u{0020}perfect\u{0020}drivers\u{0020}in\u{0020}this\u{0020}world,\u{0020}but\u{0020}Lyfa\u{0020}is\u{0020}definitely\u{0020}one\u{0020}of\u{0020}the\u{0020}closest\u{0020}to\u{0020}perfection.", "0", "0", "0", "0", 10018, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}虽然瓦尔基里小队的成员给别人的印象都是尽忠职守，严肃认真的形象，但是莉法给人的感觉却完全不一样\n\u{1000}\u{1000}作为瓦尔基里小队元老级的人物，莉法却一直表现得像个刚入队的新人。可能是因为她总喜欢穿着一身女仆装给研究所内的工作人员端茶送水，让人很难把她和在原罪近身肉搏的女武神联系在一起。\n\u{1000}\u{1000}不过莉法的战斗力是毋庸置疑的，通过几次在战场上面对原罪碾压式的表现后，研究室的众人给莉法起了一个响亮的称号——\"战场上的闪电\"。因为莉法总是能像闪电一样劈开原罪的战阵，让其溃不成军。\n\u{1000}\u{1000}战场上强大可靠的莉法，作为女仆来说也是值得信任。自从莉法加入了瓦尔基里，入驻研究室后，研究室内部就再也没有请过保洁人员。平时端茶送水的工作莉法也全包揽了，每天看到最多的就是莉法热情地在每个员工面前询问他们要喝什么饮料。\n\u{1000}\u{1000}对于这点，大家在感到工作舒适的同时又有点承受不住莉法的这股热情。但是她本人对此毫无察觉，依旧一丝不苟地完成自己女仆的工作。"},
[601802] = {601802, 500, "\u{0020}\u{0020}Lyfa\u{0020}grew\u{0020}up\u{0020}with\u{0020}her\u{0020}grandma,\u{0020}her\u{0020}parents\u{0020}were\u{0020}working\u{0020}hard\u{0020}in\u{0020}the\u{0020}citiy\u{0020}and\u{0020}didn't\u{0020}have\u{0020}time\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}Lyfa,\u{0020}they\u{0020}came\u{0020}home\u{0020}only\u{0020}on\u{0020}weekends,\u{0020}with\u{0020}some\u{0020}snacks\u{0020}and\u{0020}toys.\u{0020}So,\u{0020}compared\u{0020}to\u{0020}her\u{0020}parents,\u{0020}Lyfa\u{0020}had\u{0020}a\u{0020}closer\u{0020}relationship\u{0020}with\u{0020}her\u{0020}grandma.\n\n\n\nShe\u{0020}thrived\u{0020}under\u{0020}the\u{0020}care\u{0020}of\u{0020}her\u{0020}grandma,\u{0020}whose\u{0020}condition\u{0020}was\u{0020}worsening.\u{0020}It\u{0020}was\u{0020}her\u{0020}grandma\u{0020}taking\u{0020}care\u{0020}of\u{0020}Lyfa,\u{0020}but\u{0020}at\u{0020}an\u{0020}unclear\u{0020}moment\u{0020}Lyfa\u{0020}started\u{0020}taking\u{0020}care\u{0020}of\u{0020}her\u{0020}grandma's\u{0020}life.\n\nFortunately,\u{0020}Lyfa\u{0020}was\u{0020}a\u{0020}considerate\u{0020}girl,\u{0020}and\u{0020}she\u{0020}learnt\u{0020}a\u{0020}lot\u{0020}of\u{0020}skills\u{0020}from\u{0020}her\u{0020}grandma.\u{0020}Sweeping\u{0020}the\u{0020}floor,\u{0020}cooking,\u{0020}washing\u{0020}clothes,\u{0020}letting\u{0020}her\u{0020}grandma\u{0020}take\u{0020}the\u{0020}life-saving\u{0020}medicine…\u{0020}it's\u{0020}hard\u{0020}to\u{0020}imagine\u{0020}a\u{0020}young\u{0020}child\u{0020}can\u{0020}do\u{0020}so\u{0020}many\u{0020}things.\n\nPerhaps\u{0020}this\u{0020}can\u{0020}be\u{0020}attributed\u{0020}to\u{0020}her\u{0020}grama's\u{0020}instructions,\u{0020}because\u{0020}her\u{0020}grandma\u{0020}was\u{0020}a\u{0020}maid\u{0020}and\u{0020}served\u{0020}to\u{0020}a\u{0020}painter\u{0020}in\u{0020}Katya\u{0020}in\u{0020}her\u{0020}earlier\u{0020}life.\u{0020}This\u{0020}painter\u{0020}was\u{0020}Lyfa's\u{0020}never-met\u{0020}grandpa,\u{0020}he\u{0020}died\u{0020}before\u{0020}Lyfa\u{0020}was\u{0020}born.\u{0020}Every\u{0020}time\u{0020}when\u{0020}talks\u{0020}about\u{0020}the\u{0020}grandpa,\u{0020}she\u{0020}always\u{0020}describes\u{0020}how\u{0020}indispensable\u{0020}she\u{0020}was\u{0020}to\u{0020}him.\u{0020}Without\u{0020}her\u{0020}service\u{0020}he\u{0020}basically\u{0020}couldn't\u{0020}live\u{0020}a\u{0020}proper\u{0020}life.\u{0020}And\u{0020}she\u{0020}was\u{0020}attracted\u{0020}by\u{0020}his\u{0020}not\u{0020}well-known\u{0020}paintings\u{0020}and\u{0020}fell\u{0020}in\u{0020}love\u{0020}with\u{0020}him.\n\nTheir\u{0020}love\u{0020}stories\u{0020}were\u{0020}promising,\u{0020}so\u{0020}Lyfa\u{0020}was\u{0020}also\u{0020}hoping\u{0020}to\u{0020}find\u{0020}someone\u{0020}that\u{0020}needs\u{0020}her,\u{0020}just\u{0020}like\u{0020}her\u{0020}grandma's\u{0020}story.\n\nAfter\u{0020}Lyfa\u{0020}grew\u{0020}up\u{0020}older,\u{0020}her\u{0020}grandma\u{0020}passed\u{0020}away\u{0020}due\u{0020}to\u{0020}illness\u{0020}and\u{0020}went\u{0020}to\u{0020}see\u{0020}that\u{0020}painter,\u{0020}and\u{0020}Lyfa\u{0020}went\u{0020}back\u{0020}to\u{0020}her\u{0020}parents'\u{0020}side,\u{0020}entered\u{0020}an\u{0020}ordinary\u{0020}school\u{0020}in\u{0020}the\u{0020}city\u{0020}for\u{0020}education,\u{0020}and\u{0020}grew\u{0020}up\u{0020}normally\u{0020}like\u{0020}other\u{0020}kids.\u{0020}Then\u{0020}she\u{0020}passed\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}and\u{0020}was\u{0020}recruited\u{0020}by\u{0020}Valkyries,\u{0020}became\u{0020}a\u{0020}driver.\n\nWe\u{0020}asked\u{0020}Lyfa\u{0020}why\u{0020}she\u{0020}chose\u{0020}to\u{0020}become\u{0020}a\u{0020}driver,\u{0020}she\u{0020}said:\u{0020}\"I\u{0020}heard\u{0020}a\u{0020}voice,\u{0020}it\u{0020}might\u{0020}be\u{0020}her\u{0020}grandma,\u{0020}or\u{0020}someone\u{0020}else,\u{0020}it\u{0020}told\u{0020}me…to\u{0020}be\u{0020}there,\u{0020}someone\u{0020}needs\u{0020}you\u{0020}there.\"\n\n\"So,\u{0020}here\u{0020}I\u{0020}come.\"", "0", "0", "0", "0", 10018, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}就和卡佳地区很多家庭的孩子一样，莉法从小就和奶奶生活在一起，而父母则是一直在城市中打拼，只有周末偶尔会回家带给莉法一些玩具和零食。所以比起父母，奶奶和莉法的关系更加亲近。\n\u{1000}\u{1000}\"奶奶常说，过去的天空很蓝，云很白，可以看见鸟儿在云层中上下翻飞。\"\n\u{1000}\u{1000}\"我没看见过蓝色的天空，所以很想看一看！\"\n\u{1000}\u{1000}位于高纬度的卡佳，曾经拥有地球上最清澈的天空。每一个来到这里的旅人都会忍不住赞叹卡佳天空的美丽。那时的卡佳每年还有持续两周的极光。每年都会有成千上万的旅客为了极光来到这里，甚至不少人选择定居下来。\n\u{1000}\u{1000}然而这一切都随着原罪的出现而成为了历史，现在卡佳的天空只存在一团团散溢的苍雾和夹杂着冰雪的极冷空气团。\n\u{1000}\u{1000}作为原罪时代出生的孩子，莉法从未见过那样美丽的天空。\n\u{1000}\u{1000}莉法在奶奶的养育下健康地成长，但是奶奶的身体却越来越差。本来都是奶奶在照顾莉法，不知什么时候起变成了莉法在照顾奶奶的起居。而她的父母因为繁忙的工作，不能回家。\n\u{1000}\u{1000}幸好莉法是个懂事的孩子，之前跟奶奶学了很多生活技能。扫地，做饭，洗衣服，按时喂奶奶吃救命的药丸……虽然很多事做得不是很好，但也算是勉强撑起了与奶奶两个人的生活。\n\u{1000}\u{1000}也许是苦中作乐，莉法逐渐也喜欢上了做家务。年幼的她特别羡慕电视里的女仆，在她心里只要穿上女仆装才是专业的女仆，就可以更好地照顾奶奶了。\n\u{1000}\u{1000}但是最终奶奶没有能等到莉法成为专业女仆，虽然莉法已经竭尽全力，奶奶还是在她成为女仆之前，离开了人世。\n\u{1000}\u{1000}莉法依稀记得那天，陌生的父母终于回到家中。客厅里，老旧电视在播放着无聊的内容，母亲抱着她嘘寒问暖，父亲站在奶奶房间的门口，一根接着一根地吸烟。但是莉法却感觉脑袋空空的，好像失去了思考的能力。她的目光在房间里扫视，她在寻找，但是并不知道该找什么。直到她看到老旧电视里播放的驾驶员招募广告。\n\u{1000}\u{1000}有人曾问过莉法为什么要成为驾驶员，她说：\"奶奶去世的那天，我在电视里看到了招募广告，那是一个驾驶员在空中一闪而过。\"\n\u{1000}\u{1000}\"在那广告的背景里我看到了奶奶曾描述过的蓝天。\""},
[601803] = {601803, 1000, "\u{0020}\u{0020}In\u{0020}the\u{0020}life\u{0020}and\u{0020}training\u{0020}after\u{0020}she\u{0020}joined\u{0020}Valkyrie,\u{0020}she\u{0020}always\u{0020}shows\u{0020}up\u{0020}in\u{0020}a\u{0020}joyful\u{0020}and\u{0020}positive\u{0020}image.\u{0020}But\u{0020}her\u{0020}AVG\u{0020}gear\u{0020}was\u{0020}designed\u{0020}based\u{0020}on\u{0020}a\u{0020}\"maid\u{0020}costume\",\u{0020}and\u{0020}we\u{0020}worry\u{0020}that\u{0020}may\u{0020}cause\u{0020}dissatisfaction\u{0020}of\u{0020}a\u{0020}squad\u{0020}in\u{0020}Danube.\n\nAlthough\u{0020}there\u{0020}are\u{0020}no\u{0020}clear\u{0020}rules\u{0020}in\u{0020}Valkyrie\u{0020}about\u{0020}costumes,\u{0020}the\u{0020}\"maid\u{0020}costume\"\u{0020}was\u{0020}a\u{0020}little\u{0020}bit\u{0020}too\u{0020}special.\u{0020}Someone\u{0020}has\u{0020}asked\u{0020}Alvitr\u{0020}about\u{0020}that,\u{0020}she\u{0020}just\u{0020}passed\u{0020}it\u{0020}with\u{0020}a\u{0020}smile,\u{0020}like\u{0020}she\u{0020}has\u{0020}an\u{0020}unlimited\u{0020}\"allowance\"\u{0020}on\u{0020}Lyfa.\n\n\"Compared\u{0020}with\u{0020}the\u{0020}end\u{0020}of\u{0020}our\u{0020}world,\u{0020}does\u{0020}it\u{0020}matter?\"\n\nIndeed,\u{0020}compared\u{0020}to\u{0020}the\u{0020}jobs\u{0020}of\u{0020}the\u{0020}1st\u{0020}research\u{0020}lab,\u{0020}does\u{0020}it\u{0020}matter?", "0", "0", "0", "0", 10018, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}80%以上的适格率加上远超同龄人的自律，让莉法很轻松地就获得了驾驶员资格。并且通过了瓦尔基里小队的考核，成为其中的一员。\n\u{1000}\u{1000}在加入瓦尔基里后的训练和生活中，莉法总是以一个元气满满的乐观形象示人。特别是莉法喜欢穿着一身女仆装，给周围人端茶送水的热情，让一些面子薄的工作人员都感到难以招架。\n\u{1000}\u{1000}虽然瓦尔基里小队队内对于服装并没有什么明文规定，但是女仆装确实有点过于显眼。有人曾就此事问过瓦尔基里小队的队长，但是队长并没有就此责怪莉法，反而为其解释：\"无妨，这身装扮是她对已逝之人的思念。作为瓦尔基里的盾，这种小事理当被允许。\"\n\u{1000}\u{1000}很多时候，莉法喜欢来到研究所的屋顶眺望远处的天空，希望能找到躲藏的蓝天，但是只能看到乌云和苍雾。莉法在心中暗暗发誓：\n\u{1000}\u{1000}\"奶奶，我一定会把原罪都赶跑，让卡佳再次拥有蓝天。\""},
[601804] = {601804, 2000, "\u{0020}\u{0020}On\u{0020}the\u{0020}slident\u{0020}battlefield,\n\nDebrises\u{0020}of\u{0020}Sins\u{0020}pavs\u{0020}a\u{0020}new\u{0020}ground,\n\nA\u{0020}giant\u{0020}shield\u{0020}stands\u{0020}in\u{0020}the\u{0020}center,\n\nJust\u{0020}like\u{0020}a\u{0020}tombstone\u{0020}for\u{0020}Sins,\u{0020}that's\u{0020}the\u{0020}girl's\u{0020}weapon.\n\nThe\u{0020}giant\u{0020}girl\u{0020}leans\u{0020}next\u{0020}to\u{0020}that\u{0020}shield,\u{0020}crooning\u{0020}ballads\u{0020}from\u{0020}her\u{0020}childhood.\n\nShe\u{0020}looks\u{0020}towards\u{0020}the\u{0020}sky,\u{0020}asking\u{0020}the\u{0020}one\u{0020}standing\u{0020}on\u{0020}her\u{0020}shoulder,\n\n\"My\u{0020}Navigator,\u{0020}have\u{0020}your\u{0020}clothes\u{0020}got\u{0020}a\u{0020}little\u{0020}bit\u{0020}dirty?\"\n\n\"After\u{0020}the\u{0020}battle,\u{0020}I\u{0020}will\u{0020}wash\u{0020}them\u{0020}or\u{0020}you,\u{0020}if\u{0020}you\u{0020}have\u{0020}other\u{0020}dirty\u{0020}clothes\u{0020}I\u{0020}will\u{0020}take\u{0020}them\u{0020}as\u{0020}well!\"", "0", "0", "0", "0", 10018, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}寂静的战场上，\n\u{1000}\u{1000}曾经遨游其中的少女，终于迎来了与之交汇之时。\n\u{1000}\u{1000}在原罪的残骸铺成了新的土地。\n\u{1000}\u{1000}一个巨大的盾牌立在战场中央，\n\u{1000}\u{1000}好似是原罪们的墓碑，那是少女的武器。\n\u{1000}\u{1000}巨大的少女靠在盾牌旁，嘴里哼着儿时的歌谣。\n\u{1000}\u{1000}她眺望着天空，向站在肩膀上的男子询问，\n\u{1000}\u{1000}\"领航，你见过蓝色的天空吗？不是卡佳这样的真正的天空。\"\n\u{1000}\u{1000}\"奶奶告诉我，卡佳过去的天空也是蓝色，点缀着白云，鸟儿可以自由飞翔。\"\n\u{1000}\u{1000}\"所以我的想法很简单，我只想看看奶奶说的蓝天。\"\n\u{1000}\u{1000}\"也想让卡佳的孩子们都能看到不被这苍雾遮蔽的天空。\""},
[601900] = {601900, 0, "【Name】Nozomi\n【B-Day】May\u{0020}5\n【Compatibility\u{0020}Rate】53%\n【Height】37m\n【Squad】None\n【Affiliation】None\n【Interest】Attend\u{0020}concerts,\u{0020}hold\u{0020}concerts,\u{0020}compose\u{0020}music,\u{0020}travel.", "0", "0", "0", "0", 10019, "0", "0", "0", "0", 0, 1, "0", "0", "0"},
[601901] = {601901, 100, "Nozomi\u{0020}was\u{0020}once\u{0020}a\u{0020}musician.\n\nPerhaps\u{0020}the\u{0020}term\u{0020}\"musician\"\u{0020}is\u{0020}not\u{0020}very\u{0020}appropriate,\u{0020}because\u{0020}this\u{0020}young\u{0020}girl\u{0020}has\u{0020}only\u{0020}shown\u{0020}\"talent\"\u{0020}in\u{0020}composition.\n\n【I\u{0020}want\u{0020}to\u{0020}make\u{0020}the\u{0020}audience\u{0020}dance\u{0020}heartily\u{0020}with\u{0020}my\u{0020}performance!\u{0020}】\u{0020}For\u{0020}this\u{0020}goal,\u{0020}she\u{0020}began\u{0020}to\u{0020}form\u{0020}her\u{0020}own\u{0020}band\u{0020}-\u{0020}first\u{0020}on\u{0020}the\u{0020}streets,\u{0020}then\u{0020}in\u{0020}the\u{0020}livehouse,\u{0020}and\u{0020}the\u{0020}band\u{0020}members\u{0020}were\u{0020}added\u{0020}one\u{0020}by\u{0020}one.\n\nIronically,\u{0020}all\u{0020}the\u{0020}people\u{0020}Nozomi\u{0020}met\u{0020}burst\u{0020}out\u{0020}with\u{0020}dazzling\u{0020}talents\u{0020}on\u{0020}the\u{0020}path\u{0020}of\u{0020}music\u{0020}after\u{0020}a\u{0020}period\u{0020}of\u{0020}precipitation,\u{0020}only\u{0020}she\u{0020}remained\u{0020}stagnant.\n\n\"My\u{0020}performance\u{0020}mixed\u{0020}in\u{0020}is\u{0020}【discordant\u{0020}noise】.\u{0020}\"When\u{0020}Nozomi\u{0020}realized\u{0020}this,\u{0020}she\u{0020}resolutely\u{0020}left\u{0020}the\u{0020}band\u{0020}she\u{0020}formed.\n\nHowever,\u{0020}music\u{0020}will\u{0020}not\u{0020}die\u{0020}like\u{0020}this.\u{0020}Despite\u{0020}repeated\u{0020}defeats\u{0020}and\u{0020}repeated\u{0020}battles,\u{0020}throughout\u{0020}Nozomi's\u{0020}life\u{0020}up\u{0020}to\u{0020}now,\u{0020}she\u{0020}has\u{0020}successively\u{0020}formed\u{0020}four\u{0020}bands,\u{0020}from\u{0020}Kyushu\u{0020}to\u{0020}Danube,\u{0020}and\u{0020}then\u{0020}from\u{0020}Danube\u{0020}to\u{0020}Katya.\u{0020}She\u{0020}has\u{0020}seen\u{0020}the\u{0020}most\u{0020}prosperous\u{0020}cities\u{0020}in\u{0020}the\u{0020}world\u{0020}and\u{0020}also\u{0020}the\u{0020}war-torn\u{0020}and\u{0020}poverty-stricken\u{0020}plateaus.\n\nShe\u{0020}has\u{0020}gone\u{0020}beyond\u{0020}the\u{0020}stage\u{0020}of\u{0020}thinking\u{0020}about\u{0020}\"what\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}express\u{0020}with\u{0020}music?\",\u{0020}and\u{0020}the\u{0020}musical\u{0020}concept\u{0020}that\u{0020}belongs\u{0020}to\u{0020}her\u{0020}and\u{0020}runs\u{0020}through\u{0020}her\u{0020}life\u{0020}has\u{0020}been\u{0020}quietly\u{0020}conceived.", "0", "0", "0", "0", 10019, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[601902] = {601902, 500, "It's\u{0020}so\u{0020}great\u{0020}to\u{0020}bring\u{0020}the\u{0020}teammates\u{0020}into\u{0020}contact\u{0020}with\u{0020}music\u{0020}-\u{0020}these\u{0020}people\u{0020}should\u{0020}be\u{0020}in\u{0020}the\u{0020}right\u{0020}place.\u{0020}If\u{0020}they\u{0020}can't\u{0020}stand\u{0020}on\u{0020}the\u{0020}world\u{0020}stage,\u{0020}it\u{0020}will\u{0020}be\u{0020}a\u{0020}loss\u{0020}for\u{0020}the\u{0020}music\u{0020}industry.\n\nThe\u{0020}process\u{0020}of\u{0020}finding\u{0020}teammates\u{0020}was\u{0020}not\u{0020}all\u{0020}smooth\u{0020}sailing.\u{0020}However,\u{0020}in\u{0020}order\u{0020}to\u{0020}allow\u{0020}these\u{0020}teammates\u{0020}to\u{0020}play\u{0020}their\u{0020}own\u{0020}sounds\u{0020}at\u{0020}ease,\u{0020}Nozomi\u{0020}solved\u{0020}all\u{0020}the\u{0020}problems\u{0020}one\u{0020}after\u{0020}another.\n\n樂The\u{0020}bond\u{0020}between\u{0020}the\u{0020}teams\u{0020}has\u{0020}long\u{0020}been\u{0020}beyond\u{0020}description\u{0020}in\u{0020}just\u{0020}a\u{0020}few\u{0020}words.\u{0020}If\u{0020}possible,\u{0020}she\u{0020}truly\u{0020}hopes\u{0020}to\u{0020}accompany\u{0020}everyone\u{0020}to\u{0020}move\u{0020}forward\u{0020}together.\u{0020}However\u{0020}-\u{0020}drummer,\u{0020}lead\u{0020}singer,\u{0020}keyboardist,\u{0020}bassist,\u{0020}saxophonist,\u{0020}trumpeter,\u{0020}guitarist...\u{0020}She\u{0020}has\u{0020}tried\u{0020}various\u{0020}positions.\n\nNo\u{0020}matter\u{0020}how\u{0020}much\u{0020}she\u{0020}practiced,\u{0020}her\u{0020}talent\u{0020}could\u{0020}only\u{0020}support\u{0020}her\u{0020}to\u{0020}reach\u{0020}the\u{0020}mundane\u{0020}level\u{0020}of\u{0020}[making\u{0020}the\u{0020}audience\u{0020}aware\u{0020}that\u{0020}\"this\u{0020}person\u{0020}is\u{0020}playing\"].\n\n\"How\u{0020}to\u{0020}play\u{0020}music\u{0020}that\u{0020}stirs\u{0020}people's\u{0020}thoughts?\u{0020}\"，\"How\u{0020}to\u{0020}convey\u{0020}one's\u{0020}own\u{0020}thoughts?\u{0020}\"，It's\u{0020}only\u{0020}one\u{0020}step\u{0020}away\u{0020}from\u{0020}this\u{0020}realm,\u{0020}but\u{0020}it\u{0020}has\u{0020}been\u{0020}delayed\u{0020}and\u{0020}still\u{0020}not\u{0020}reached.\n\nNo\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}she\u{0020}starts\u{0020}over,\u{0020}no\u{0020}matter\u{0020}how\u{0020}many\u{0020}bands\u{0020}she\u{0020}forms,\u{0020}the\u{0020}result\u{0020}is\u{0020}the\u{0020}same.\u{0020}Every\u{0020}time\u{0020}she\u{0020}makes\u{0020}a\u{0020}phone\u{0020}call,\u{0020}she\u{0020}can\u{0020}receive\u{0020}worried\u{0020}emotions\u{0020}from\u{0020}her\u{0020}parents.\u{0020}In\u{0020}order\u{0020}to\u{0020}avoid\u{0020}bad\u{0020}smells\u{0020}in\u{0020}the\u{0020}basement\u{0020}for\u{0020}practice,\u{0020}she\u{0020}can\u{0020}only\u{0020}have\u{0020}the\u{0020}same\u{0020}simple\u{0020}meal\u{0020}outside\u{0020}every\u{0020}day.\u{0020}The\u{0020}rent\u{0020}is\u{0020}due...\u{0020}Some\u{0020}tiny\u{0020}details\u{0020}pile\u{0020}up\u{0020}together,\u{0020}and\u{0020}unconsciously,\u{0020}the\u{0020}pressure\u{0020}becomes\u{0020}so\u{0020}great.\n\nAfter\u{0020}reaching\u{0020}a\u{0020}certain\u{0020}age,\u{0020}more\u{0020}and\u{0020}more\u{0020}problems\u{0020}come\u{0020}one\u{0020}after\u{0020}another.\u{0020}Why?\n\nNot\u{0020}to\u{0020}mention\u{0020}that\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin\u{0020}hangs\u{0020}over\u{0020}everyone's\u{0020}head\u{0020}like\u{0020}the\u{0020}Sword\u{0020}of\u{0020}Damocles,\u{0020}and\u{0020}people's\u{0020}peaceful\u{0020}life\u{0020}can\u{0020}be\u{0020}destroyed\u{0020}in\u{0020}an\u{0020}instant.\u{0020}After\u{0020}realizing\u{0020}that\u{0020}her\u{0020}enthusiasm\u{0020}for\u{0020}striving\u{0020}was\u{0020}gradually\u{0020}fading,\u{0020}Nozomi\u{0020}decided\u{0020}to\u{0020}end\u{0020}with\u{0020}the\u{0020}fourth\u{0020}band.\n\nAfter\u{0020}a\u{0020}certain\u{0020}concert\u{0020}ended,\u{0020}misfortune\u{0020}befell\u{0020}her\u{0020}-\u{0020}she\u{0020}was\u{0020}knocked\u{0020}flying\u{0020}by\u{0020}an\u{0020}overspeed\u{0020}truck.\n\n……\u{0020}……\u{0020}Is\u{0020}she\u{0020}going\u{0020}to\u{0020}disappear\u{0020}from\u{0020}this\u{0020}world?\n\nWhat\u{0020}should\u{0020}her\u{0020}parents\u{0020}do\u{0020}next?\n\nShe\u{0020}hasn't\u{0020}said\u{0020}goodbye\u{0020}properly\u{0020}to\u{0020}the\u{0020}band.\n\nNot\u{0020}ready\u{0020}to\u{0020}say\u{0020}goodbye\u{0020}to\u{0020}this\u{0020}world\u{0020}yet.\n\nNot\u{0020}yet——\u{0020}Realize\u{0020}your\u{0020}dreams.\u{0020}——\u{0020}\"Miss\u{0020}Nozomi,\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}■■■■■■■？\"\u{0020}Nimbus...\u{0020}What\u{0020}is\u{0020}it?\n\n\"Miss\u{0020}Nozomi,\u{0020}maybe\u{0020}we\u{0020}will\u{0020}conduct\u{0020}an\u{0020}experiment.\"\u{0020}Confront...\n\n\"■■■■■■■————。\"\u{0020}I\u{0020}want...\n\nContinue\u{0020}playing...\n\nI\u{0020}want...\u{0020}Continue...\u{0020}Playing!\n\n…\u{0020}…\u{0020}…", "0", "0", "0", "0", 10019, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[601903] = {601903, 1000, "She\u{0020}seized\u{0020}a\u{0020}ray\u{0020}of\u{0020}light\u{0020}from\u{0020}the\u{0020}verge\u{0020}of\u{0020}death\u{0020}and\u{0020}made\u{0020}a\u{0020}deal\u{0020}with\u{0020}\"The\u{0020}evil\u{0020}spirit\u{0020}of\u{0020}the\u{0020}Science\u{0020}Department\".\u{0020}Thus,\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}replaced\u{0020}Nozomi's\u{0020}rapidly\u{0020}deteriorating\u{0020}organs.\u{0020}The\u{0020}core\u{0020}that\u{0020}should\u{0020}have\u{0020}been\u{0020}the\u{0020}core\u{0020}of\u{0020}the\u{0020}Sin\u{0020}activity\u{0020}integrated\u{0020}into\u{0020}her\u{0020}body,\u{0020}allowing\u{0020}her\u{0020}to\u{0020}survive.\n\nHer\u{0020}ears\u{0020}have\u{0020}been\u{0020}scrapped.\u{0020}Now,\u{0020}she\u{0020}relies\u{0020}entirely\u{0020}on\u{0020}the\u{0020}mechanical\u{0020}cat\u{0020}ears\u{0020}on\u{0020}top\u{0020}of\u{0020}her\u{0020}head\u{0020}to\u{0020}receive\u{0020}sounds.\n\nHalf\u{0020}of\u{0020}her\u{0020}body\u{0020}was\u{0020}completely\u{0020}replaced,\u{0020}and\u{0020}the\u{0020}constantly\u{0020}operating\u{0020}machinery\u{0020}inside\u{0020}could\u{0020}be\u{0020}seen\u{0020}through\u{0020}the\u{0020}transparent\u{0020}shell.\n\nBut\u{0020}her\u{0020}heart,\u{0020}or\u{0020}rather\u{0020}-\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}did\u{0020}not\u{0020}stop\u{0020}beating\u{0020}because\u{0020}of\u{0020}this.\n\nWhen\u{0020}she\u{0020}picked\u{0020}up\u{0020}the\u{0020}guitar,\u{0020}she\u{0020}could\u{0020}still\u{0020}pluck\u{0020}the\u{0020}strings.\u{0020}When\u{0020}she\u{0020}held\u{0020}the\u{0020}saxophone,\u{0020}she\u{0020}could\u{0020}still\u{0020}play\u{0020}the\u{0020}melody.\u{0020}When\u{0020}she\u{0020}sat\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}piano,\u{0020}the\u{0020}black\u{0020}and\u{0020}white\u{0020}keys\u{0020}melted\u{0020}away\u{0020}in\u{0020}her\u{0020}hands.\n\nShe\u{0020}is\u{0020}like\u{0020}a\u{0020}normal\u{0020}person\u{0020}-\u{0020}except\u{0020}that\u{0020}she\u{0020}can\u{0020}transform\u{0020}into\u{0020}a\u{0020}37-meter\u{0020}giant.\n\nNozomi\u{0020}has\u{0020}not\u{0020}given\u{0020}up\u{0020}her\u{0020}music\u{0020}dream\u{0020}until\u{0020}now.\n\n——There\u{0020}are\u{0020}still\u{0020}people\u{0020}waiting\u{0020}for\u{0020}her\u{0020}comeback.\n\n\"Must\u{0020}one\u{0020}rely\u{0020}on\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}survive?\u{0020}But\u{0020}does\u{0020}the\u{0020}operation\u{0020}of\u{0020}maintaining\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}require\u{0020}Nimbus\u{0020}to\u{0020}provide\u{0020}energy?\u{0020}So\u{0020}applying\u{0020}to\u{0020}participate\u{0020}in\u{0020}the\u{0020}battle\u{0020}in\u{0020}advance\u{0020}to\u{0020}accumulate\u{0020}the\u{0020}capital\u{0020}for\u{0020}survival?\u{0020}That's\u{0020}crazy.\u{0020}\"The\u{0020}counselor\u{0020}of\u{0020}the\u{0020}college\u{0020}commented\u{0020}in\u{0020}this\u{0020}way\u{0020}-\u{0020}but\u{0020}in\u{0020}the\u{0020}end,\u{0020}the\u{0020}counselor\u{0020}still\u{0020}stamped\u{0020}the\u{0020}\"review\u{0020}passed\"\u{0020}seal\u{0020}on\u{0020}the\u{0020}application\u{0020}form.\u{0020}。", "0", "0", "0", "0", 10019, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[601904] = {601904, 2000, "I\u{0020}have\u{0020}a\u{0020}song\u{0020}and\u{0020}I\u{0020}want\u{0020}you\u{0020}to\u{0020}listen\u{0020}to\u{0020}it.\n\nAll\u{0020}because\u{0020}of\u{0020}you\n\nEspecially\u{0020}important\u{0020}you\n\nWhen\u{0020}you\u{0020}understand\u{0020}the\u{0020}underlying\u{0020}meaning\u{0020}of\u{0020}this\u{0020}song.\n\nCome\u{0020}and\u{0020}be\u{0020}the\u{0020}male\u{0020}lead\u{0020}of\u{0020}this\u{0020}song.\n\nMake\u{0020}oneself\u{0020}unique\u{0020}with\u{0020}music\u{0020}and\u{0020}attract\u{0020}others\u{0020}with\u{0020}uniqueness.\n\nExpress\u{0020}one's\u{0020}feelings\u{0020}with\u{0020}music\u{0020}and\u{0020}prevent\u{0020}the\u{0020}beloved\u{0020}one\u{0020}from\u{0020}feigning\u{0020}deafness\u{0020}and\u{0020}dumbness.\n\nI\u{0020}have\u{0020}a\u{0020}good\u{0020}method.\n\nLet\u{0020}dead\u{0020}wood\u{0020}blossom\u{0020}and\u{0020}let\u{0020}the\u{0020}mind\u{0020}flow.\n\nAt\u{0020}the\u{0020}time\u{0020}of\u{0020}transformation,\u{0020}at\u{0020}the\u{0020}time\u{0020}of\u{0020}struggle,\n\nAt\u{0020}the\u{0020}time\u{0020}of\u{0020}synesthesia\u{0020}linkage\n\nGive\u{0020}the\u{0020}wooden\u{0020}man\u{0020}a\u{0020}fatal\u{0020}blow.", "0", "0", "0", "0", 10019, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
