[602001] = {602001, 100, "\u{3000}\u{3000}\"I've\u{0020}already\u{0020}been\u{0020}divorced\u{0020}once,\u{0020}so\u{0020}you\u{0020}should\u{0020}treat\u{0020}me\u{0020}like\u{0020}a\u{0020}proper\u{0020}adult.\"\u{0020}Driver\u{0020}Candidate\u{0020}Mirai\u{0020}blocked\u{0020}your\u{0020}usual\u{0020}path\u{0020}home.\u{0020}\"But\u{0020}I'm\u{0020}willing\u{0020}to\u{0020}let\u{0020}it\u{0020}slide\u{0020}and\u{0020}remarry\u{0020}you,\u{0020}Mr.\u{0020}Pervert.\"\n\n\u{3000}\u{3000}What\u{0020}a\u{0020}brat.\u{0020}And\u{0020}it\u{0020}was\u{0020}rude\u{0020}to\u{0020}call\u{0020}someone\u{0020}\"Mr.\u{0020}Pervert\"\u{0020}upon\u{0020}first\u{0020}meeting.\n\n\u{3000}\u{3000}Yet,\u{0020}strangely,\u{0020}I\u{0020}didn't\u{0020}feel\u{0020}the\u{0020}slightest\u{0020}bit\u{0020}offended.\u{0020}It\u{0020}was\u{0020}as\u{0020}if\u{0020}the\u{0020}title\u{0020}fit\u{0020}me\u{0020}naturally.\n\n\u{3000}\u{3000}I\u{0020}was\u{0020}certain\u{0020}I\u{0020}had\u{0020}never\u{0020}met\u{0020}her\u{0020}before,\u{0020}except,\u{0020}perhaps,\u{0020}in\u{0020}a\u{0020}dream.\u{0020}A\u{0020}vivid,\u{0020}dazzling\u{0020}dream\u{0020}where\u{0020}I\u{0020}adventured\u{0020}across\u{0020}the\u{0020}cosmos\u{0020}with\u{0020}a\u{0020}little\u{0020}girl.\u{0020}And\u{0020}now,\u{0020}that\u{0020}girl's\u{0020}face\u{0020}matched\u{0020}perfectly\u{0020}with\u{0020}that\u{0020}of\u{0020}the\u{0020}one\u{0020}before\u{0020}me.\n\n\u{3000}\u{3000}\"Have\u{0020}we...\u{0020}met\u{0020}in\u{0020}a\u{0020}dream\u{0020}before?\"\n\n\u{3000}\u{3000}\"We\u{0020}even\u{0020}got\u{0020}married\u{0020}in\u{0020}one.\"", "0", "0", "0", "0", 10020, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602002] = {602002, 500, "\u{3000}\u{3000}Before\u{0020}her\u{0020}enlistment,\u{0020}Mirai\u{0020}was\u{0020}in\u{0020}a\u{0020}vegetative\u{0020}state.\n\n\u{3000}\u{3000}It\u{0020}was\u{0020}a\u{0020}Sin\u{0020}invasion.\u{0020}When\u{0020}rescuers\u{0020}pulled\u{0020}her\u{0020}from\u{0020}the\u{0020}rubble,\u{0020}when\u{0020}surgeons\u{0020}dragged\u{0020}her\u{0020}back\u{0020}from\u{0020}death's\u{0020}door,\u{0020}what\u{0020}remained\u{0020}was\u{0020}a\u{0020}body\u{0020}stripped\u{0020}of\u{0020}intelligence,\u{0020}thought,\u{0020}will,\u{0020}emotion,\u{0020}and\u{0020}the\u{0020}ability\u{0020}to\u{0020}perform\u{0020}any\u{0020}purposeful\u{0020}action.\n\n\u{3000}\u{3000}Her\u{0020}parents\u{0020}and\u{0020}sister\u{0020}were\u{0020}shattered.\u{0020}To\u{0020}ordinary\u{0020}people,\u{0020}Sin\u{0020}attacks\u{0020}are\u{0020}unpredictable,\u{0020}but\u{0020}her\u{0020}family\u{0020}convinced\u{0020}themselves\u{0020}that\u{0020}their\u{0020}own\u{0020}support\u{0020}had\u{0020}been\u{0020}the\u{0020}true\u{0020}cause\u{0020}of\u{0020}Mirai's\u{0020}suffering.\n\n\u{3000}\u{3000}A\u{0020}twisted\u{0020}logic.\u{0020}A\u{0020}self-imposed\u{0020}curse.\u{0020}The\u{0020}only\u{0020}way\u{0020}to\u{0020}keep\u{0020}living\u{0020}in\u{0020}a\u{0020}future\u{0020}without\u{0020}Mirai.\u{0020}For\u{0020}two\u{0020}years\u{0020}after\u{0020}the\u{0020}incident,\u{0020}her\u{0020}family\u{0020}visited\u{0020}daily,\u{0020}taking\u{0020}turns\u{0020}recounting\u{0020}their\u{0020}lives\u{0020}to\u{0020}her.\u{0020}The\u{0020}doctor\u{0020}called\u{0020}it\u{0020}a\u{0020}stimulus\u{0020}therapy.\u{0020}To\u{0020}them,\u{0020}it\u{0020}was\u{0020}the\u{0020}only\u{0020}thread\u{0020}still\u{0020}tying\u{0020}Mirai\u{0020}to\u{0020}their\u{0020}world;\u{0020}this\u{0020}was\u{0020}how\u{0020}their\u{0020}lives\u{0020}should\u{0020}have\u{0020}been,\u{0020}if\u{0020}not\u{0020}for\u{0020}the\u{0020}tragedy.\n\n\u{3000}\u{3000}Hatred\u{0020}became\u{0020}fuel.\u{0020}Her\u{0020}sister\u{0020}once\u{0020}applied\u{0020}to\u{0020}become\u{0020}a\u{0020}Driver\u{0020}Candidate,\u{0020}only\u{0020}to\u{0020}be\u{0020}rejected\u{0020}for\u{0020}low\u{0020}compatibility\u{0020}rate.\u{0020}Now,\u{0020}she\u{0020}strives\u{0020}to\u{0020}become\u{0020}a\u{0020}researcher\u{0020}instead.\n\n\u{3000}\u{3000}They\u{0020}loved\u{0020}Mirai\u{0020}that\u{0020}much.\u{0020}Had\u{0020}she\u{0020}never\u{0020}woken\u{0020}up,\u{0020}they\u{0020}might\u{0020}have\u{0020}carried\u{0020}that\u{0020}guilt\u{0020}forever.", "0", "0", "0", "0", 10020, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602003] = {602003, 1000, "\u{3000}\u{3000}\"I\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}Driver.\"\u{0020}It\u{0020}was\u{0020}Mirai's\u{0020}first\u{0020}demand\u{0020}after\u{0020}rehabilitation.\u{0020}\"I\u{0020}want\u{0020}to\u{0020}do\u{0020}it.\"\n\n\u{3000}\u{3000}A\u{0020}family\u{0020}conference\u{0020}was\u{0020}summoned.\n\n\u{3000}\u{3000}\"I'm\u{0020}not\u{0020}going\u{0020}to\u{0020}school\u{0020}with\u{0020}kids\u{0020}two\u{0020}years\u{0020}younger!\"\u{0020}Her\u{0020}reasoning\u{0020}was\u{0020}flawless.\u{0020}At\u{0020}least\u{0020}at\u{0020}the\u{0020}Driver\u{0020}academy,\u{0020}she'd\u{0020}be\u{0020}safe.\u{0020}And\u{0020}given\u{0020}her\u{0020}notorious,\u{0020}three-minute\u{0020}passion,\u{0020}she'd\u{0020}likely\u{0020}quit\u{0020}before\u{0020}ever\u{0020}seeing\u{0020}real\u{0020}combat.\n\n\u{3000}\u{3000}\"I'll\u{0020}call\u{0020}every\u{0020}day.\u{0020}I'll\u{0020}visit\u{0020}on\u{0020}weekends.\"\u{0020}After\u{0020}relentless\u{0020}promises,\u{0020}the\u{0020}family\u{0020}relented.", "0", "0", "0", "0", 10020, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602004] = {602004, 2000, "\u{3000}\u{3000}Mirai\u{0020}is\u{0020}the\u{0020}youngest.\n\n\u{3000}\u{3000}A\u{0020}child\u{0020}who\u{0020}craves\u{0020}admiration.\n\n\u{3000}\u{3000}A\u{0020}child\u{0020}who\u{0020}thinks\u{0020}she's\u{0020}mature.\n\n\u{3000}\u{3000}A\u{0020}child\u{0020}whose\u{0020}passions\u{0020}burn\u{0020}bright\u{0020}and\u{0020}brief.\n\n\u{3000}\u{3000}So...\n\n\u{3000}\u{3000}Stay\u{0020}forever\u{0020}curious.\n\n\u{3000}\u{3000}Embrace\u{0020}your\u{0020}vanity\u{0020}and\u{0020}your\u{0020}love\u{0020}for\u{0020}the\u{0020}spotlight.\n\n\u{3000}\u{3000}And\u{0020}with\u{0020}that\u{0020}proud\u{0020}little\u{0020}head\u{0020}of\u{0020}yours,\u{0020}crash\u{0020}full-speed\u{0020}into\u{0020}the\u{0020}one\u{0020}person\u{0020}fate\u{0020}ordained\u{0020}for\u{0020}you.", "0", "0", "0", "0", 10020, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
