[602101] = {602101, 100, "\u{0020}\u{0020}The\u{0020}driver\u{0020}of\u{0020}\"Two\u{0020}as\u{0020}one\",\u{0020}and\u{0020}the\u{0020}girl's\u{0020}name\u{0020}is\u{0020}Cynthia.\u{0020}What\u{0020}makes\u{0020}her\u{0020}unique\u{0020}is\u{0020}that\u{0020}after\u{0020}gigantification,\u{0020}a\u{0020}white-haired\u{0020}girl\u{0020}\"Cynemia\"\u{0020}who\u{0020}looks\u{0020}very\u{0020}similar\u{0020}to\u{0020}her\u{0020}will\u{0020}split\u{0020}out.\n\nCynemia\u{0020}has\u{0020}her\u{0020}own\u{0020}consciousness.\u{0020}The\u{0020}senses\u{0020}of\u{0020}the\u{0020}two\u{0020}are\u{0020}connected.\u{0020}However,\u{0020}once\u{0020}the\u{0020}gigantification\u{0020}is\u{0020}lifted,\u{0020}Cynemia\u{0020}will\u{0020}disappear\u{0020}accordingly,\u{0020}but\u{0020}the\u{0020}memories\u{0020}belonging\u{0020}to\u{0020}Cynemia\u{0020}will\u{0020}not\u{0020}be\u{0020}passed\u{0020}on\u{0020}to\u{0020}Cynthia.\n\nThe\u{0020}reason\u{0020}for\u{0020}this\u{0020}special\u{0020}phenomenon\u{0020}is\u{0020}still\u{0020}unknown.\u{0020}However,\u{0020}it\u{0020}seems\u{0020}to\u{0020}have\u{0020}little\u{0020}impact\u{0020}on\u{0020}Cynthia\u{0020}herself.\u{0020}During\u{0020}battles,\u{0020}the\u{0020}coordination\u{0020}between\u{0020}the\u{0020}two\u{0020}is\u{0020}very\u{0020}tacit.\u{0020}Without\u{0020}any\u{0020}communication,\u{0020}they\u{0020}can\u{0020}understand\u{0020}each\u{0020}other\u{0020}instantly.\u{0020}In\u{0020}daily\u{0020}life,\u{0020}although\u{0020}there\u{0020}is\u{0020}only\u{0020}Cynthia\u{0020}alone,\u{0020}she\u{0020}won't\u{0020}be\u{0020}too\u{0020}lonely.\u{0020}Flora\u{0020}in\u{0020}the\u{0020}team\u{0020}has\u{0020}a\u{0020}very\u{0020}close\u{0020}relationship\u{0020}with\u{0020}her,\u{0020}and\u{0020}the\u{0020}two\u{0020}often\u{0020}go\u{0020}shopping\u{0020}together.", "0", "0", "0", "0", 10021, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602102] = {602102, 500, "\u{0020}\u{0020}\"Please,\u{0020}save\u{0020}me.\u{0020}Even\u{0020}if\u{0020}it's\u{0020}just\u{0020}to\u{0020}live\u{0020}in\u{0020}your\u{0020}shadow...\u{0020}Take\u{0020}me\u{0020}away\u{0020}from\u{0020}this\u{0020}place.\u{0020}\"\n\nCynthia's\u{0020}parents\u{0020}are\u{0020}scientific\u{0020}officers\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Danube\u{0020}Branch.\u{0020}At\u{0020}the\u{0020}same\u{0020}time,\u{0020}they\u{0020}were\u{0020}also\u{0020}the\u{0020}first\u{0020}batch\u{0020}of\u{0020}reformist\u{0020}nobles\u{0020}to\u{0020}settle\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Ark,\u{0020}and\u{0020}Cynthia\u{0020}thus\u{0020}became\u{0020}the\u{0020}first\u{0020}batch\u{0020}of\u{0020}babies\u{0020}born\u{0020}on\u{0020}the\u{0020}Ark.\n\nBecause\u{0020}the\u{0020}project\u{0020}that\u{0020}Cynthia's\u{0020}parents\u{0020}were\u{0020}involved\u{0020}in\u{0020}required\u{0020}absolute\u{0020}confidentiality,\u{0020}she\u{0020}did\u{0020}not\u{0020}leave\u{0020}the\u{0020}Ark\u{0020}of\u{0020}Danube\u{0020}until\u{0020}she\u{0020}graduated\u{0020}from\u{0020}junior\u{0020}high\u{0020}school.\u{0020}The\u{0020}way\u{0020}she\u{0020}learned\u{0020}knowledge\u{0020}was\u{0020}also\u{0020}through\u{0020}one-on-one\u{0020}teaching\u{0020}by\u{0020}AI.\u{0020}This\u{0020}huge\u{0020}mothership\u{0020}was\u{0020}both\u{0020}a\u{0020}warm\u{0020}home\u{0020}and\u{0020}an\u{0020}inescapable\u{0020}cage\u{0020}for\u{0020}her.\n\nThough\u{0020}Cynthia\u{0020}grew\u{0020}up\u{0020}alone,\u{0020}thanks\u{0020}to\u{0020}her\u{0020}rich\u{0020}imagination\u{0020}and\u{0020}the\u{0020}complex\u{0020}structure\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Ark,\u{0020}she\u{0020}could\u{0020}often\u{0020}entertain\u{0020}herself\u{0020}by\u{0020}\"exploring\"\u{0020}on\u{0020}the\u{0020}spaceship.\n\nOne\u{0020}day,\u{0020}she\u{0020}discovered\u{0020}a\u{0020}special\u{0020}room.\u{0020}It\u{0020}was\u{0020}a\u{0020}monitoring\u{0020}room\u{0020}of\u{0020}the\u{0020}science\u{0020}department\u{0020}which\u{0020}was\u{0020}temporarily\u{0020}closed\u{0020}because\u{0020}of\u{0020}the\u{0020}death\u{0020}of\u{0020}the\u{0020}monitored\u{0020}object.\u{0020}Out\u{0020}of\u{0020}curiosity\u{0020}about\u{0020}her\u{0020}parents'\u{0020}work,\u{0020}the\u{0020}girl\u{0020}sneaked\u{0020}in.\n\nIn\u{0020}this\u{0020}empty\u{0020}room,\u{0020}she\u{0020}saw\u{0020}a\u{0020}large\u{0020}culture\u{0020}tank\u{0020}that\u{0020}had\u{0020}already\u{0020}been\u{0020}emptied.\u{0020}That\u{0020}culture\u{0020}tank\u{0020}was\u{0020}just\u{0020}large\u{0020}enough\u{0020}to\u{0020}contain\u{0020}a\u{0020}person,\u{0020}a\u{0020}person\u{0020}about\u{0020}the\u{0020}same\u{0020}size\u{0020}as\u{0020}herself...\u{0020}Later,\u{0020}as\u{0020}if\u{0020}bewitched\u{0020}by\u{0020}something,\u{0020}by\u{0020}some\u{0020}existence\u{0020}that\u{0020}had\u{0020}lost\u{0020}its\u{0020}form,\u{0020}the\u{0020}girl\u{0020}lay\u{0020}down\u{0020}in\u{0020}the\u{0020}culture\u{0020}tank\u{0020}and\u{0020}activated\u{0020}the\u{0020}switch.\u{0020}The\u{0020}culture\u{0020}fluid\u{0020}began\u{0020}to\u{0020}refill,\u{0020}and\u{0020}the\u{0020}accident\u{0020}occurred.\n\nFortunately,\u{0020}adults\u{0020}rescued\u{0020}Cynthia\u{0020}in\u{0020}time,\u{0020}and\u{0020}Cynthia\u{0020}recovered\u{0020}after\u{0020}a\u{0020}period\u{0020}of\u{0020}rest.\n\nAlthough\u{0020}she\u{0020}quickly\u{0020}lost\u{0020}consciousness\u{0020}after\u{0020}being\u{0020}submerged\u{0020}in\u{0020}the\u{0020}culture\u{0020}fluid,\u{0020}before\u{0020}fainting,\u{0020}she\u{0020}clearly\u{0020}remembered\u{0020}seeing\u{0020}the\u{0020}figure\u{0020}of\u{0020}another\u{0020}girl.\u{0020}That\u{0020}girl\u{0020}had\u{0020}long\u{0020}white\u{0020}hair\u{0020}and\u{0020}pale\u{0020}red\u{0020}eyes.\u{0020}That\u{0020}was\u{0020}probably\u{0020}the\u{0020}memory\u{0020}left\u{0020}by\u{0020}a\u{0020}failed\u{0020}product\u{0020}of\u{0020}some\u{0020}experiment,\u{0020}or\u{0020}rather,\u{0020}the\u{0020}\"consciousness\"...\u{0020}The\u{0020}girl\u{0020}with\u{0020}white\u{0020}hair\u{0020}pleaded\u{0020}to\u{0020}the\u{0020}girl\u{0020}in\u{0020}front\u{0020}of\u{0020}her\u{0020}-\n\n\"Please,\u{0020}save\u{0020}me.\u{0020}Even\u{0020}if\u{0020}it's\u{0020}just\u{0020}to\u{0020}live\u{0020}in\u{0020}your\u{0020}shadow...\u{0020}Take\u{0020}me\u{0020}away\u{0020}from\u{0020}this\u{0020}place.\u{0020}\"\n\nThe\u{0020}lonely\u{0020}girl\u{0020}agreed\u{0020}to\u{0020}the\u{0020}girl\u{0020}with\u{0020}white\u{0020}hair\u{0020}and\u{0020}accepted\u{0020}her.\n\nAfter\u{0020}that,\u{0020}Cynthia\u{0020}did\u{0020}not\u{0020}mention\u{0020}anything\u{0020}about\u{0020}the\u{0020}girl\u{0020}with\u{0020}white\u{0020}hair\u{0020}to\u{0020}anyone.", "0", "0", "0", "0", 10021, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602103] = {602103, 1000, "\u{0020}On\u{0020}the\u{0020}day\u{0020}of\u{0020}Cynthia's\u{0020}first\u{0020}gigantification,\u{0020}she\u{0020}saw\u{0020}clearly\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}the\u{0020}white-haired\u{0020}girl\u{0020}from\u{0020}that\u{0020}year.\u{0020}Although\u{0020}there\u{0020}were\u{0020}some\u{0020}differences\u{0020}from\u{0020}the\u{0020}outline\u{0020}in\u{0020}the\u{0020}image,\u{0020}Cynthia\u{0020}was\u{0020}still\u{0020}very\u{0020}certain\u{0020}that\u{0020}this\u{0020}was\u{0020}the\u{0020}girl\u{0020}she\u{0020}had\u{0020}\"saved\"\u{0020}back\u{0020}then,\u{0020}and\u{0020}Cynthia\u{0020}named\u{0020}her\u{0020}\"Cynemia\".\n\nAlthough\u{0020}Cynemia\u{0020}has\u{0020}an\u{0020}independent\u{0020}consciousness,\u{0020}she\u{0020}has\u{0020}no\u{0020}past\u{0020}memories.\u{0020}Every\u{0020}time,\u{0020}a\u{0020}brand-new\u{0020}Cynemia\u{0020}is\u{0020}generated.\u{0020}However,\u{0020}this\u{0020}does\u{0020}not\u{0020}affect\u{0020}the\u{0020}feelings\u{0020}and\u{0020}cooperation\u{0020}between\u{0020}the\u{0020}two.\u{0020}The\u{0020}two\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}cooperate\u{0020}seamlessly\u{0020}like\u{0020}twins\u{0020}who\u{0020}grew\u{0020}up\u{0020}together\u{0020}since\u{0020}childhood.\n\n\"Although\u{0020}I\u{0020}have\u{0020}no\u{0020}memory,\u{0020}I\u{0020}understand\u{0020}that\u{0020}Cynthia\u{0020}is\u{0020}the\u{0020}person\u{0020}I\u{0020}must\u{0020}protect.\u{0020}If\u{0020}you\u{0020}want\u{0020}to\u{0020}approach\u{0020}her,\u{0020}you\u{0020}have\u{0020}to\u{0020}get\u{0020}through\u{0020}me\u{0020}first.\"", "0", "0", "0", "0", 10021, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602104] = {602104, 2000, "\u{0020}\u{0020}In\u{0020}the\u{0020}coffee\u{0020}shop,\u{0020}Cynthia\u{0020}was\u{0020}talking\u{0020}about\u{0020}what\u{0020}had\u{0020}just\u{0020}happened\u{0020}on\u{0020}the\u{0020}battlefield.\n\nThe\u{0020}black\u{0020}giantess\u{0020}fell\u{0020}from\u{0020}the\u{0020}sky,\u{0020}and\u{0020}she\u{0020}was\u{0020}hit\u{0020}by\u{0020}the\u{0020}enemy.\n\nIn\u{0020}a\u{0020}few\u{0020}seconds,\u{0020}her\u{0020}huge\u{0020}body\u{0020}will\u{0020}fall\u{0020}on\u{0020}the\u{0020}city\u{0020}below,\u{0020}turning\u{0020}everything\u{0020}there\u{0020}into\u{0020}ruins.\n\nIt\u{0020}was\u{0020}an\u{0020}inevitable\u{0020}accident,\u{0020}however...\n\n\"That\u{0020}was\u{0020}close!\u{0020}Almost\u{0020}hit\u{0020}the\u{0020}ground.\"\n\nThe\u{0020}white\u{0020}giantess\u{0020}with\u{0020}the\u{0020}same\u{0020}face\u{0020}caught\u{0020}the\u{0020}black\u{0020}giantess.\n\n\"Cynthia,\u{0020}I\u{0020}will\u{0020}never\u{0020}abandon\u{0020}you.\u{0020}\"\n\n…\n\n\"Navigator,\u{0020}Cynemia\u{0020}is\u{0020}just\u{0020}like\u{0020}my\u{0020}own\u{0020}shadow...\"\n\n\"It\u{0020}is\u{0020}the\u{0020}pure\u{0020}white\u{0020}shadow\u{0020}projected\u{0020}by\u{0020}the\u{0020}pitch-black\u{0020}self.\"", "0", "0", "0", "0", 10021, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
