[602201] = {602201, 100, "\u{3000}\u{3000}Fafnir\u{0020}is\u{0020}a\u{0020}girl\u{0020}who\u{0020}commands\u{0020}attention,\u{0020}both\u{0020}in\u{0020}name\u{0020}and\u{0020}presence.\n\u{3000}\u{3000}Her\u{0020}sun-kissed\u{0020}dark\u{0020}skin\u{0020}is\u{0020}marked\u{0020}with\u{0020}claw-like\u{0020}tattoos,\u{0020}their\u{0020}pale\u{0020}tips\u{0020}streaked\u{0020}with\u{0020}an\u{0020}unknown\u{0020}dye\u{0020}in\u{0020}a\u{0020}vivid\u{0020}crimson.\u{0020}Beneath\u{0020}a\u{0020}tousled\u{0020}fringe,\u{0020}her\u{0020}eyes\u{0020}gleam\u{0020}bright\u{0020}and\u{0020}clear\u{0020}like\u{0020}ripe\u{0020}pomegranates.\n\u{3000}\u{3000}Wild\u{0020}and\u{0020}untamed,\u{0020}she\u{0020}seems\u{0020}like\u{0020}a\u{0020}warrior\u{0020}sprung\u{0020}straight\u{0020}from\u{0020}a\u{0020}primal\u{0020}tribe,\u{0020}utterly\u{0020}out\u{0020}of\u{0020}step\u{0020}with\u{0020}modern\u{0020}society.\u{0020}When\u{0020}it\u{0020}comes\u{0020}to\u{0020}fighting\u{0020}the\u{0020}Sins,\u{0020}Fafnir\u{0020}throws\u{0020}herself\u{0020}into\u{0020}the\u{0020}fray\u{0020}with\u{0020}unmatched\u{0020}ferocity.\u{0020}She\u{0020}revels\u{0020}in\u{0020}charging\u{0020}headfirst\u{0020}into\u{0020}battle,\u{0020}using\u{0020}her\u{0020}powerful\u{0020}physique\u{0020}and\u{0020}massive\u{0020}mecha\u{0020}to\u{0020}confront\u{0020}towering\u{0020}foes\u{0020}without\u{0020}hesitation.\u{0020}She's\u{0020}a\u{0020}genuine\u{0020}battle\u{0020}junkie.\n\u{3000}\u{3000}Perhaps\u{0020}it's\u{0020}this\u{0020}fierce\u{0020}nature\u{0020}that\u{0020}keeps\u{0020}most\u{0020}people\u{0020}at\u{0020}a\u{0020}distance.\u{0020}More\u{0020}often\u{0020}than\u{0020}not,\u{0020}she's\u{0020}alone—quietly\u{0020}slipping\u{0020}into\u{0020}the\u{0020}Ark's\u{0020}café,\u{0020}ordering\u{0020}a\u{0020}coffee\u{0020}that\u{0020}somehow\u{0020}clashes\u{0020}with\u{0020}her\u{0020}fiery\u{0020}spirit,\u{0020}then\u{0020}slipping\u{0020}out\u{0020}without\u{0020}lingering.\n\u{3000}\u{3000}\"They\u{0020}say\u{0020}Fafnir\u{0020}loves\u{0020}her\u{0020}coffee\u{0020}loaded\u{0020}with\u{0020}sugar.\"", "0", "0", "0", "0", 10022, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602202] = {602202, 500, "\u{3000}\u{3000}Long\u{0020}ago,\u{0020}a\u{0020}legend\u{0020}spread\u{0020}across\u{0020}the\u{0020}Danube\u{0020}about\u{0020}a\u{0020}band\u{0020}of\u{0020}warriors\u{0020}who\u{0020}tamed\u{0020}fearsome\u{0020}dragons\u{0020}and\u{0020}fought\u{0020}alongside\u{0020}them,\u{0020}turning\u{0020}their\u{0020}enemies'\u{0020}power\u{0020}into\u{0020}their\u{0020}own.\u{0020}These\u{0020}warriors\u{0020}were\u{0020}known\u{0020}as\u{0020}the\u{0020}Dragon\u{0020}Knights.\n\u{3000}\u{3000}Fafnir's\u{0020}family\u{0020}traces\u{0020}its\u{0020}lineage\u{0020}back\u{0020}to\u{0020}one\u{0020}of\u{0020}these\u{0020}legendary\u{0020}Dragon\u{0020}Knights.\u{0020}But\u{0020}unlike\u{0020}the\u{0020}popular\u{0020}tales,\u{0020}their\u{0020}ancestor\u{0020}didn't\u{0020}conquer\u{0020}a\u{0020}dragon\u{0020}by\u{0020}sheer\u{0020}force.\u{0020}Instead,\u{0020}he\u{0020}forged\u{0020}a\u{0020}pact\u{0020}with\u{0020}the\u{0020}beast—a\u{0020}bond\u{0020}sealed\u{0020}not\u{0020}by\u{0020}claw\u{0020}wounds,\u{0020}but\u{0020}by\u{0020}a\u{0020}mark.\u{0020}That\u{0020}mark\u{0020}is\u{0020}the\u{0020}tattoo\u{0020}Fafnir\u{0020}bears\u{0020}today.\n\u{3000}\u{3000}Of\u{0020}course,\u{0020}in\u{0020}reality,\u{0020}there\u{0020}are\u{0020}no\u{0020}such\u{0020}dragons.\u{0020}Both\u{0020}the\u{0020}folk\u{0020}tales\u{0020}and\u{0020}family\u{0020}stories\u{0020}are\u{0020}flights\u{0020}of\u{0020}fancy.\u{0020}Growing\u{0020}up\u{0020}in\u{0020}the\u{0020}modern\u{0020}world,\u{0020}Fafnir\u{0020}knows\u{0020}this\u{0020}well.\u{0020}But\u{0020}like\u{0020}most\u{0020}kids\u{0020}in\u{0020}Danube,\u{0020}she\u{0020}couldn't\u{0020}escape\u{0020}the\u{0020}fate\u{0020}set\u{0020}by\u{0020}her\u{0020}family,\u{0020}and\u{0020}soon\u{0020}found\u{0020}herself\u{0020}an\u{0020}outcast.\n\u{3000}\u{3000}As\u{0020}a\u{0020}child,\u{0020}Fafnir\u{0020}had\u{0020}a\u{0020}sweet\u{0020}tooth\u{0020}like\u{0020}any\u{0020}other\u{0020}kid.\u{0020}After\u{0020}school,\u{0020}she'd\u{0020}stop\u{0020}by\u{0020}the\u{0020}cake\u{0020}shop\u{0020}at\u{0020}the\u{0020}school\u{0020}gates.\u{0020}But\u{0020}her\u{0020}classmates\u{0020}didn't\u{0020}understand\u{0020}her.\u{0020}To\u{0020}them,\u{0020}her\u{0020}dark\u{0020}skin\u{0020}and\u{0020}marked\u{0020}face\u{0020}were\u{0020}out\u{0020}of\u{0020}place.\u{0020}They\u{0020}began\u{0020}to\u{0020}avoid\u{0020}her,\u{0020}mock\u{0020}her,\u{0020}and\u{0020}even\u{0020}hurt\u{0020}her.\n\u{3000}\u{3000}Somewhere\u{0020}along\u{0020}the\u{0020}way,\u{0020}Fafnir\u{0020}started\u{0020}to\u{0020}accept\u{0020}the\u{0020}role\u{0020}others\u{0020}forced\u{0020}on\u{0020}her.\u{0020}She\u{0020}deliberately\u{0020}pushed\u{0020}people\u{0020}away,\u{0020}grew\u{0020}fierce\u{0020}and\u{0020}unruly,\u{0020}and\u{0020}threw\u{0020}herself\u{0020}into\u{0020}learning\u{0020}how\u{0020}to\u{0020}fight.\u{0020}She\u{0020}convinced\u{0020}herself\u{0020}it\u{0020}was\u{0020}just\u{0020}her\u{0020}nature.\u{0020}The\u{0020}only\u{0020}thing\u{0020}that\u{0020}never\u{0020}changed\u{0020}was\u{0020}her\u{0020}sweet\u{0020}tooth.", "0", "0", "0", "0", 10022, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602203] = {602203, 1000, "\u{3000}\u{3000}Not\u{0020}long\u{0020}ago,\u{0020}AEGIS\u{0020}unveiled\u{0020}a\u{0020}new\u{0020}generation\u{0020}of\u{0020}AVG\u{0020}units—mechs\u{0020}capable\u{0020}of\u{0020}drawing\u{0020}the\u{0020}Nimbus\u{0020}energy\u{0020}directly\u{0020}from\u{0020}within\u{0020}the\u{0020}Sins.\u{0020}This\u{0020}breakthrough\u{0020}boosted\u{0020}driver\u{0020}performance\u{0020}and\u{0020}extended\u{0020}the\u{0020}duration\u{0020}of\u{0020}gigantification.\u{0020}But\u{0020}it\u{0020}came\u{0020}at\u{0020}a\u{0020}cost.\u{0020}Tapping\u{0020}into\u{0020}such\u{0020}unstable\u{0020}energy\u{0020}risked\u{0020}disturbing\u{0020}the\u{0020}driver's\u{0020}neural\u{0020}functions,\u{0020}sometimes\u{0020}driving\u{0020}them\u{0020}into\u{0020}a\u{0020}frenzy\u{0020}state—stripped\u{0020}of\u{0020}reason,\u{0020}driven\u{0020}only\u{0020}by\u{0020}a\u{0020}blind\u{0020}urge\u{0020}to\u{0020}destroy.\n\u{3000}\u{3000}History\u{0020}repeated\u{0020}itself.\u{0020}Fafnir\u{0020}was\u{0020}assigned\u{0020}to\u{0020}the\u{0020}experimental\u{0020}squad.\u{0020}And\u{0020}just\u{0020}like\u{0020}her\u{0020}ancestor,\u{0020}she\u{0020}didn't\u{0020}get\u{0020}along\u{0020}well\u{0020}with\u{0020}the\u{0020}other\u{0020}Dragon\u{0020}Knights.\u{0020}In\u{0020}battle,\u{0020}she\u{0020}held\u{0020}nothing\u{0020}back.\u{0020}Time\u{0020}and\u{0020}again,\u{0020}she\u{0020}pushed\u{0020}herself\u{0020}to\u{0020}the\u{0020}edge,\u{0020}letting\u{0020}the\u{0020}frenzy\u{0020}state\u{0020}take\u{0020}over.\u{0020}It\u{0020}made\u{0020}her\u{0020}a\u{0020}constant\u{0020}source\u{0020}of\u{0020}trouble\u{0020}for\u{0020}the\u{0020}team.\n\u{3000}\u{3000}\"Working\u{0020}with\u{0020}Fafnir\u{0020}is\u{0020}almost\u{0020}impossible...\u{0020}I\u{0020}never\u{0020}know\u{0020}how\u{0020}to\u{0020}talk\u{0020}to\u{0020}her,\"\n\u{3000}\u{3000}Mel\u{0020}once\u{0020}muttered\u{0020}to\u{0020}the\u{0020}Navigator.\n\u{3000}\u{3000}\"Maybe\u{0020}start\u{0020}with\u{0020}her\u{0020}favorite\u{0020}cake.,\"\n\u{3000}\u{3000}\"Huh?\u{0020}That's\u{0020}really\u{0020}all\u{0020}it\u{0020}takes?\"", "0", "0", "0", "0", 10022, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602204] = {602204, 2000, "\u{3000}\u{3000}A\u{0020}black\u{0020}dragon\u{0020}loomed\u{0020}over\u{0020}the\u{0020}city\u{0020}skyline.\n\u{3000}\u{3000}Her\u{0020}scarlet\u{0020}mech\u{0020}burned\u{0020}like\u{0020}wildfire,\u{0020}tail\u{0020}sweeping\u{0020}wide, \u{0020}slicing\u{0020}a\u{0020}high-rise\u{0020}clean\u{0020}in\u{0020}two.\n\u{3000}\u{3000}The\u{0020}streets\u{0020}below\u{0020}were\u{0020}lifeless.\u{0020}And\u{0020}at\u{0020}the\u{0020}heart\u{0020}of\u{0020}the\u{0020}chaos\u{0020}stood\u{0020}a\u{0020}towering\u{0020}girl,\u{0020}lost\u{0020}to\u{0020}madness,\u{0020}her\u{0020}mind\u{0020}overtaken\u{0020}by\u{0020}the\u{0020}very\u{0020}power\u{0020}that\u{0020}made\u{0020}her\u{0020}a\u{0020}weapon.\n\u{3000}\u{3000}\"I'll\u{0020}burn\u{0020}it\u{0020}all\u{0020}to\u{0020}the\u{0020}ground...\u{0020}until\u{0020}this\u{0020}cursed\u{0020}strength,\u{0020}and\u{0020}the\u{0020}life\u{0020}it\u{0020}fuels,\u{0020}are\u{0020}finally\u{0020}spent.\"\n\u{3000}\u{3000}But\u{0020}what\u{0020}then?\n\u{3000}\u{3000}Through\u{0020}the\u{0020}smoke,\u{0020}a\u{0020}small\u{0020}figure\u{0020}emerged—fragile\u{0020}enough\u{0020}to\u{0020}be\u{0020}crushed\u{0020}in\u{0020}a\u{0020}single\u{0020}blow.\n\u{3000}\u{3000}He\u{0020}raised\u{0020}a\u{0020}hand\u{0020}toward\u{0020}her.\n\u{3000}\u{3000}\"It's\u{0020}over\u{0020}now.\u{0020}Come\u{0020}on...\u{0020}Let's\u{0020}go\u{0020}back.\u{0020}That\u{0020}cake\u{0020}shop\u{0020}you\u{0020}love\u{0020}is\u{0020}still\u{0020}waiting.\"", "0", "0", "0", "0", 10022, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
