[602301] = {602301, 100, "\u{0020}\u{0020}Mo\u{0020}became\u{0020}the\u{0020}fourth\u{0020}member\u{0020}of\u{0020}Mammalia\u{0020}largely\u{0020}because\u{0020}she\u{0020}had\u{0020}too\u{0020}much\u{0020}time\u{0020}on\u{0020}her\u{0020}hands.\u{0020}But\u{0020}when\u{0020}it\u{0020}comes\u{0020}to\u{0020}battle,\u{0020}she\u{0020}has\u{0020}proven\u{0020}her\u{0020}worth\u{0020}time\u{0020}and\u{0020}time\u{0020}again.\n\n\u{0020}\u{0020}She\u{0020}isn't\u{0020}as\u{0020}sharp\u{0020}and\u{0020}ruthless\u{0020}as\u{0020}Shirogane,\u{0020}as\u{0020}dependable\u{0020}as\u{0020}Mizo,\u{0020}or\u{0020}as\u{0020}timid\u{0020}as\u{0020}Rou.\u{0020}What\u{0020}makes\u{0020}Mo\u{0020}stand\u{0020}out\u{0020}is\u{0020}her\u{0020}ability\u{0020}to\u{0020}see\u{0020}what\u{0020}others\u{0020}cannot.\n\n\u{0020}\u{0020}With\u{0020}her\u{0020}sharp\u{0020}golden\u{0020}eyes,\u{0020}Mo\u{0020}captures\u{0020}even\u{0020}the\u{0020}smallest\u{0020}movements\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}striking\u{0020}with\u{0020}precision\u{0020}that\u{0020}can\u{0020}turn\u{0020}the\u{0020}tide\u{0020}of\u{0020}battle.\u{0020}She\u{0020}excels\u{0020}in\u{0020}exploiting\u{0020}overlooked\u{0020}opportunities,\u{0020}making\u{0020}decisive\u{0020}moves\u{0020}that\u{0020}others\u{0020}fail\u{0020}to\u{0020}notice.\n\n\u{0020}\u{0020}Even\u{0020}her\u{0020}own\u{0020}teammates\u{0020}sometimes\u{0020}feel\u{0020}as\u{0020}though\u{0020}they‘re\u{0020}being\u{0020}subtly\u{0020}guided\u{0020}by\u{0020}her\u{0020}presence—a\u{0020}reflection\u{0020}of\u{0020}her\u{0020}natural\u{0020}role\u{0020}as\u{0020}a\u{0020}\"Shepherd.\"\n\n\u{0020}\u{0020}Around\u{0020}Mo,\u{0020}everyone\u{0020}instinctively\u{0020}follows\u{0020}her\u{0020}lead,\u{0020}as\u{0020}if\u{0020}she's\u{0020}quietly\u{0020}holding\u{0020}the\u{0020}reins.\u{0020}\u{0020}", "0", "0", "0", "0", 10023, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602302] = {602302, 500, "\u{0020}\u{0020}Mo\u{0020}carries\u{0020}the\u{0020}heavy\u{0020}legacy\u{0020}of\u{0020}her\u{0020}people,\u{0020}the\u{0020}Etans.\u{0020}Before\u{0020}the\u{0020}destruction\u{0020}of\u{0020}their\u{0020}homeworld,\u{0020}Mo\u{0020}served\u{0020}as\u{0020}a\u{0020}\"Shepherd\"—a\u{0020}caretaker\u{0020}and\u{0020}educator\u{0020}responsible\u{0020}for\u{0020}raising\u{0020}Etan\u{0020}children\u{0020}under\u{0020}their\u{0020}society's\u{0020}communal\u{0020}system.\u{0020}In\u{0020}a\u{0020}world\u{0020}where\u{0020}parenthood\u{0020}was\u{0020}replaced\u{0020}by\u{0020}collective\u{0020}upbringing,\u{0020}Shepherds\u{0020}filled\u{0020}the\u{0020}roles\u{0020}of\u{0020}both\u{0020}parent\u{0020}and\u{0020}teacher.\n\n\u{0020}\u{0020}However,\u{0020}in\u{0020}the\u{0020}living\u{0020}areas\u{0020}of\u{0020}the\u{0020}Etan\u{0020}people,\u{0020}there\u{0020}are\u{0020}no\u{0020}longer\u{0020}any\u{0020}children\u{0020}in\u{0020}need\u{0020}of\u{0020}such\u{0020}care,\u{0020}nor\u{0020}is\u{0020}there\u{0020}a\u{0020}demand\u{0020}for\u{0020}Shepherds.\n\n\u{0020}\u{0020}The\u{0020}root\u{0020}cause\u{0020}lies\u{0020}in\u{0020}the\u{0020}advanced\u{0020}technology\u{0020}of\u{0020}the\u{0020}Etan\u{0020}people.\u{0020}Their\u{0020}society\u{0020}relied\u{0020}on\u{0020}artificial\u{0020}reproduction,\u{0020}which\u{0020}not\u{0020}only\u{0020}removed\u{0020}the\u{0020}responsibilities\u{0020}of\u{0020}\"parents\"\u{0020}but\u{0020}also\u{0020}dissolved\u{0020}the\u{0020}very\u{0020}concept\u{0020}of\u{0020}parenthood.\u{0020}Most\u{0020}Etan\u{0020}children\u{0020}were\u{0020}developed\u{0020}in\u{0020}artificial\u{0020}incubation\u{0020}pods,\u{0020}with\u{0020}embryos\u{0020}randomly\u{0020}matched\u{0020}from\u{0020}a\u{0020}gene\u{0020}pool.\u{0020}The\u{0020}task\u{0020}of\u{0020}ensuring\u{0020}the\u{0020}survival\u{0020}of\u{0020}their\u{0020}species\u{0020}was\u{0020}fully\u{0020}delegated\u{0020}to\u{0020}birthing\u{0020}factories.\u{0020}However,\u{0020}the\u{0020}spaceship\u{0020}they\u{0020}used\u{0020}to\u{0020}escape\u{0020}to\u{0020}Earth\u{0020}did\u{0020}not\u{0020}carry\u{0020}such\u{0020}facilities.\n\n\u{0020}\u{0020}Moreover,\u{0020}there\u{0020}were\u{0020}very\u{0020}few\u{0020}children\u{0020}among\u{0020}the\u{0020}passengers\u{0020}of\u{0020}the\u{0020}spaceship.\u{0020}Over\u{0020}the\u{0020}decades\u{0020}since\u{0020}settling\u{0020}on\u{0020}Earth,\u{0020}the\u{0020}few\u{0020}remaining\u{0020}\"children\"\u{0020}have\u{0020}grown\u{0020}into\u{0020}adults,\u{0020}leaving\u{0020}no\u{0020}need\u{0020}for\u{0020}Shepherds.\n\n\u{0020}\u{0020}This\u{0020}shift\u{0020}left\u{0020}Mo\u{0020}with\u{0020}no\u{0020}purpose,\u{0020}becoming\u{0020}the\u{0020}most\u{0020}pitiable\u{0020}and\u{0020}tragic\u{0020}\"unemployed\"\u{0020}among\u{0020}her\u{0020}people.\n\n\u{0020}\u{0020}Every\u{0020}time\u{0020}she\u{0020}reflects\u{0020}on\u{0020}this,\u{0020}her\u{0020}thoughts\u{0020}inevitably\u{0020}return\u{0020}to\u{0020}the\u{0020}final\u{0020}sunrise\u{0020}she\u{0020}witnessed\u{0020}on\u{0020}her\u{0020}home\u{0020}planet—a\u{0020}haunting\u{0020}memory\u{0020}of\u{0020}their\u{0020}extinction.\n\n\u{0020}\u{0020}When\u{0020}the\u{0020}apocalypse\u{0020}struck,\u{0020}Mo\u{0020}and\u{0020}her\u{0020}fellow\u{0020}refugees\u{0020}aboard\u{0020}the\u{0020}spaceship\u{0020}saw\u{0020}live\u{0020}footage\u{0020}of\u{0020}their\u{0020}homeland's\u{0020}demise.\n\n\u{0020}\u{0020}Chaos\u{0020}reigned\u{0020}as\u{0020}people\u{0020}scattered,\u{0020}buildings\u{0020}collapsed\u{0020}in\u{0020}the\u{0020}distance,\u{0020}and\u{0020}massive\u{0020}steel\u{0020}monstrosities\u{0020}swept\u{0020}through\u{0020}the\u{0020}lands,\u{0020}ruthlessly\u{0020}hunting\u{0020}her\u{0020}people\u{0020}with\u{0020}mechanical\u{0020}precision.\u{0020}\"Officers\"\u{0020}worked\u{0020}tirelessly\u{0020}to\u{0020}evacuate\u{0020}civilians,\u{0020}\"Doctors\"\u{0020}treated\u{0020}the\u{0020}wounded,\u{0020}\"Soldiers\"\u{0020}sacrificed\u{0020}themselves\u{0020}in\u{0020}vain,\u{0020}and\u{0020}\"Firefighters\"\u{0020}battled\u{0020}unrelenting\u{0020}flames.\u{0020}Every\u{0020}profession\u{0020}stood\u{0020}firm,\u{0020}fulfilling\u{0020}their\u{0020}roles\u{0020}to\u{0020}the\u{0020}bitter\u{0020}end,\u{0020}yet\u{0020}none\u{0020}could\u{0020}avert\u{0020}the\u{0020}inevitable\u{0020}annihilation.\u{0020}The\u{0020}spacecraft,\u{0020}a\u{0020}symbol\u{0020}of\u{0020}hope\u{0020}built\u{0020}by\u{0020}\"Scientists\"\u{0020}and\u{0020}\"Engineers,\"\u{0020}was\u{0020}no\u{0020}savior.\u{0020}Many\u{0020}were\u{0020}destroyed\u{0020}mid-launch\u{0020}by\u{0020}the\u{0020}monstrous\u{0020}invaders,\u{0020}their\u{0020}ruins\u{0020}serving\u{0020}as\u{0020}collective\u{0020}tombs.\n\n\u{0020}\u{0020}Mo\u{0020}knew\u{0020}there\u{0020}was\u{0020}no\u{0020}saving\u{0020}their\u{0020}planet.\u{0020}Aboard\u{0020}her\u{0020}spaceship,\u{0020}a\u{0020}resolute\u{0020}\"Soldier\"\u{0020}also\u{0020}understood\u{0020}this\u{0020}harsh\u{0020}reality.\u{0020}In\u{0020}an\u{0020}act\u{0020}of\u{0020}bravery,\u{0020}she\u{0020}ordered\u{0020}the\u{0020}ship\u{0020}to\u{0020}flee,\u{0020}sacrificing\u{0020}their\u{0020}homeworld\u{0020}to\u{0020}preserve\u{0020}a\u{0020}fragment\u{0020}of\u{0020}their\u{0020}people.\n\n\u{0020}\u{0020}Even\u{0020}so,\u{0020}Mo\u{0020}has\u{0020}come\u{0020}to\u{0020}realize\u{0020}that\u{0020}planting\u{0020}this\u{0020}\"seed\"\u{0020}of\u{0020}survival\u{0020}on\u{0020}Earth\u{0020}has\u{0020}proven\u{0020}far\u{0020}more\u{0020}challenging\u{0020}than\u{0020}they\u{0020}ever\u{0020}anticipated.", "0", "0", "0", "0", 10023, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602303] = {602303, 1000, "\u{0020}\u{0020}Mo\u{0020}joined\u{0020}Mammalia\u{0020}primarily\u{0020}to\u{0020}resolve\u{0020}her\u{0020}\"employment\u{0020}issue,\"\u{0020}as\u{0020}securing\u{0020}a\u{0020}recognized\u{0020}\"social\u{0020}identity\"\u{0020}is\u{0020}crucial\u{0020}for\u{0020}the\u{0020}Etan\u{0020}people.\n\n\u{0020}\u{0020}However,\u{0020}her\u{0020}presence\u{0020}brought\u{0020}more\u{0020}than\u{0020}just\u{0020}resolution\u{0020}to\u{0020}her\u{0020}own\u{0020}predicament—it\u{0020}initiated\u{0020}a\u{0020}ripple\u{0020}of\u{0020}positive\u{0020}changes\u{0020}within\u{0020}the\u{0020}squad.\n\n\u{0020}\u{0020}As\u{0020}a\u{0020}seasoned\u{0020}\"Shepherd,\"\u{0020}Mo\u{0020}has\u{0020}an\u{0020}exceptional\u{0020}talent\u{0020}for\u{0020}reading\u{0020}her\u{0020}teammates'\u{0020}emotions\u{0020}and\u{0020}uncovering\u{0020}the\u{0020}underlying\u{0020}causes\u{0020}of\u{0020}their\u{0020}struggles.\u{0020}Her\u{0020}methods\u{0020}of\u{0020}providing\u{0020}comfort\u{0020}and\u{0020}reassurance,\u{0020}honed\u{0020}over\u{0020}years\u{0020}of\u{0020}working\u{0020}with\u{0020}children,\u{0020}have\u{0020}proven\u{0020}remarkably\u{0020}effective\u{0020}even\u{0020}with\u{0020}\"adults.\"\n\n\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}most\u{0020}remarkable\u{0020}transformations\u{0020}was\u{0020}seen\u{0020}in\u{0020}Rou.\u{0020}After\u{0020}an\u{0020}earnest\u{0020}conversation\u{0020}with\u{0020}Mo,\u{0020}the\u{0020}once-timid\u{0020}and\u{0020}battle-shy\u{0020}Long\u{0020}found\u{0020}the\u{0020}courage\u{0020}to\u{0020}face\u{0020}her\u{0020}fears,\u{0020}standing\u{0020}firm\u{0020}in\u{0020}battle\u{0020}without\u{0020}retreating.\u{0020}This\u{0020}unexpected\u{0020}development\u{0020}left\u{0020}even\u{0020}Shirogane,\u{0020}the\u{0020}squad's\u{0020}typically\u{0020}stoic\u{0020}member,\u{0020}visibly\u{0020}astonished.\u{0020}From\u{0020}that\u{0020}moment,\u{0020}Shirogane's\u{0020}respect\u{0020}for\u{0020}the\u{0020}\"Shepherd\"\u{0020}deepened\u{0020}further,\u{0020}fully\u{0020}acknowledging\u{0020}the\u{0020}invaluable\u{0020}role\u{0020}Mo\u{0020}plays\u{0020}in\u{0020}supporting\u{0020}and\u{0020}uplifting\u{0020}the\u{0020}team.", "0", "0", "0", "0", 10023, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602304] = {602304, 2000, "\u{0020}\u{0020}Those\u{0020}horns\u{0020}were\u{0020}never\u{0020}meant\u{0020}to\u{0020}pierce.\n\n\u{0020}\u{0020}Those\u{0020}eyes\u{0020}were\u{0020}never\u{0020}meant\u{0020}to\u{0020}turn\u{0020}cold.\n\n\u{0020}\u{0020}Those\u{0020}ears\u{0020}were\u{0020}never\u{0020}meant\u{0020}to\u{0020}spy.\n\n\u{0020}\u{0020}Those\u{0020}hooves\u{0020}were\u{0020}never\u{0020}meant\u{0020}to\u{0020}trample.\n\n\u{0020}\u{0020}Those\u{0020}hands\u{0020}were\u{0020}never\u{0020}meant\u{0020}to\u{0020}let\u{0020}go.\n\n\u{0020}\u{0020}This\u{0020}difficult\u{0020}choice\u{0020}was\u{0020}never\u{0020}hers\u{0020}to\u{0020}bear.\u{0020}\n\n\u{0020}\u{0020}The\u{0020}seeds\u{0020}of\u{0020}civilization\u{0020}were\u{0020}planted\u{0020}long\u{0020}ago\u{0020}on\u{0020}alien\u{0020}soil,\n\n\u{0020}\u{0020}but\u{0020}where\u{0020}will\u{0020}those\u{0020}paths\u{0020}ultimately\u{0020}lead?\n\n\u{0020}\u{0020}She\u{0020}doesn't\u{0020}know.\n\n\u{0020}\u{0020}Neither\u{0020}do\u{0020}I.", "0", "0", "0", "0", 10023, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
