[602501] = {602501, 100, "\u{0020}\u{0020}She's\u{0020}as\u{0020}untamed\u{0020}as\u{0020}the\u{0020}sea,\u{0020}her\u{0020}voice\u{0020}carrying\u{0020}for\u{0020}hundreds\u{0020}of\u{0020}meters\u{0020}-\u{0020}even\u{0020}without\u{0020}Gigantification.\u{0020}She\u{0020}never\u{0020}holds\u{0020}back,\u{0020}never\u{0020}suppresses\u{0020}her\u{0020}emotions,\u{0020}and\u{0020}never\u{0020}cares\u{0020}what\u{0020}anyone\u{0020}else\u{0020}thinks.\n\n\u{0020}\u{0020}Maybe\u{0020}that's\u{0020}why\u{0020}she\u{0020}can\u{0020}handle\u{0020}the\u{0020}raw,\u{0020}beast-like\u{0020}power\u{0020}of\u{0020}her\u{0020}AVG\u{0020}with\u{0020}such\u{0020}ease.\u{0020}The\u{0020}Dragon\u{0020}Knights\u{0020}are\u{0020}no\u{0020}different.\u{0020}Each\u{0020}one\u{0020}fights\u{0020}by\u{0020}their\u{0020}own\u{0020}rules,\u{0020}wild\u{0020}and\u{0020}reckless.\u{0020}Cooperation?\u{0020}That\u{0020}only\u{0020}happens\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}Anywhere\u{0020}else,\u{0020}they're\u{0020}nothing\u{0020}more\u{0020}than\u{0020}lone\u{0020}wolves.", "0", "0", "0", "0", 10025, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602502] = {602502, 500, "\u{0020}\u{0020}Before\u{0020}becoming\u{0020}a\u{0020}Driver,\u{0020}Mel\u{0020}was\u{0020}a\u{0020}delinquent,\u{0020}skipping\u{0020}classes\u{0020}and\u{0020}running\u{0020}the\u{0020}streets.\u{0020}Rules\u{0020}suffocated\u{0020}her\u{0020}-\u{0020}not\u{0020}just\u{0020}school\u{0020}regulations,\u{0020}but\u{0020}family\u{0020}expectations\u{0020}too.\u{0020}To\u{0020}her,\u{0020}even\u{0020}home\u{0020}felt\u{0020}like\u{0020}a\u{0020}cage.\u{0020}Her\u{0020}parents\u{0020}had\u{0020}grand\u{0020}plans:\u{0020}they\u{0020}wanted\u{0020}her\u{0020}to\u{0020}become\u{0020}an\u{0020}AEGIS\u{0020}officer,\u{0020}a\u{0020}respectable,\u{0020}disciplined\u{0020}soldier.\u{0020}But\u{0020}to\u{0020}Mel,\u{0020}that\u{0020}was\u{0020}just\u{0020}another\u{0020}set\u{0020}of\u{0020}chains.\u{0020}So,\u{0020}a\u{0020}year\u{0020}before\u{0020}adulthood,\u{0020}she\u{0020}made\u{0020}a\u{0020}choice\u{0020}that\u{0020}would\u{0020}change\u{0020}her\u{0020}life\u{0020}-\u{0020}she\u{0020}dropped\u{0020}out\u{0020}and\u{0020}ran\u{0020}away.\n\n\u{0020}\u{0020}Someone\u{0020}like\u{0020}her\u{0020}should\u{0020}have\u{0020}had\u{0020}no\u{0020}place\u{0020}in\u{0020}an\u{0020}organization\u{0020}as\u{0020}strict\u{0020}as\u{0020}AEGIS.\u{0020}But\u{0020}fate\u{0020}had\u{0020}other\u{0020}plans.\n\n\u{0020}\u{0020}She\u{0020}had\u{0020}intended\u{0020}to\u{0020}sneak\u{0020}onto\u{0020}a\u{0020}ship,\u{0020}to\u{0020}see\u{0020}the\u{0020}world\u{0020}beyond\u{0020}the\u{0020}city.\u{0020}Instead,\u{0020}she\u{0020}was\u{0020}caught\u{0020}without\u{0020}a\u{0020}ticket.\u{0020}Mel\u{0020}expected\u{0020}to\u{0020}be\u{0020}sent\u{0020}home.\u{0020}What\u{0020}she\u{0020}got\u{0020}was\u{0020}far\u{0020}worse.\u{0020}Just\u{0020}days\u{0020}earlier,\u{0020}her\u{0020}entire\u{0020}neighborhood\u{0020}had\u{0020}been\u{0020}wiped\u{0020}out\u{0020}by\u{0020}the\u{0020}Sins.\n\n\u{0020}\u{0020}She\u{0020}had\u{0020}no\u{0020}home\u{0020}to\u{0020}return\u{0020}to.\u{0020}Sent\u{0020}to\u{0020}a\u{0020}shelter,\u{0020}Mel\u{0020}met\u{0020}others\u{0020}like\u{0020}herself\u{0020}-\u{0020}children\u{0020}who\u{0020}had\u{0020}lost\u{0020}everything.\u{0020}For\u{0020}the\u{0020}first\u{0020}time,\u{0020}she\u{0020}felt\u{0020}true\u{0020}grief\u{0020}and\u{0020}helplessness.\u{0020}She\u{0020}had\u{0020}thought\u{0020}running\u{0020}away\u{0020}would\u{0020}make\u{0020}her\u{0020}free.\u{0020}Now,\u{0020}she\u{0020}understood:\u{0020}only\u{0020}strength\u{0020}could\u{0020}grant\u{0020}her\u{0020}true\u{0020}freedom.\u{0020}Only\u{0020}by\u{0020}wiping\u{0020}out\u{0020}the\u{0020}Sins\u{0020}could\u{0020}she\u{0020}take\u{0020}control\u{0020}of\u{0020}her\u{0020}own\u{0020}fate.\n\n\u{0020}\u{0020}From\u{0020}that\u{0020}moment,\u{0020}she\u{0020}dedicated\u{0020}herself\u{0020}to\u{0020}training,\u{0020}to\u{0020}becoming\u{0020}powerful.\n\n\u{0020}\u{0020}But\u{0020}she\u{0020}would\u{0020}never\u{0020}be\u{0020}an\u{0020}AEGIS\u{0020}officer,\u{0020}bound\u{0020}by\u{0020}orders\u{0020}and\u{0020}protocol.\u{0020}Instead,\u{0020}she\u{0020}chose\u{0020}to\u{0020}be\u{0020}a\u{0020}Driver\u{0020}-\u{0020}a\u{0020}warrior\u{0020}who\u{0020}fought\u{0020}on\u{0020}her\u{0020}own\u{0020}terms.\n\n\u{0020}\u{0020}And\u{0020}in\u{0020}doing\u{0020}so,\u{0020}Mel\u{0020}finally\u{0020}found\u{0020}the\u{0020}freedom\u{0020}to\u{0020}protect\u{0020}everything\u{0020}she\u{0020}loved.聽", "0", "0", "0", "0", 10025, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602503] = {602503, 1000, "\u{0020}\u{0020}After\u{0020}passing\u{0020}the\u{0020}AEGIS\u{0020}qualifications\u{0020}and\u{0020}completing\u{0020}Driver\u{0020}training,\u{0020}Mel\u{0020}faced\u{0020}a\u{0020}new\u{0020}challenge.\u{0020}Her\u{0020}combat\u{0020}style\u{0020}was\u{0020}too\u{0020}wild,\u{0020}often\u{0020}causing\u{0020}energy\u{0020}shortages\u{0020}in\u{0020}battles\u{0020}against\u{0020}the\u{0020}Sins.\n\n\u{0020}\u{0020}Fortunately,\u{0020}AEGIS\u{0020}had\u{0020}recently\u{0020}developed\u{0020}a\u{0020}new\u{0020}energy\u{0020}recovery\u{0020}technology.\u{0020}Based\u{0020}on\u{0020}this,\u{0020}they\u{0020}created\u{0020}a\u{0020}new\u{0020}AVG,\u{0020}capable\u{0020}of\u{0020}absorbing\u{0020}Nimbus\u{0020}from\u{0020}Minor\u{0020}Sin\u{0020}cores\u{0020}and\u{0020}converting\u{0020}it\u{0020}into\u{0020}a\u{0020}Driver's\u{0020}power.\u{0020}This\u{0020}technology\u{0020}granted\u{0020}superior\u{0020}endurance\u{0020}in\u{0020}battle.\n\n\u{0020}\u{0020}However,\u{0020}it\u{0020}was\u{0020}still\u{0020}experimental.\u{0020}AEGIS\u{0020}needed\u{0020}a\u{0020}Driver\u{0020}who\u{0020}could\u{0020}fully\u{0020}exploit\u{0020}its\u{0020}potential,\u{0020}and\u{0020}Mel\u{0020}became\u{0020}the\u{0020}top\u{0020}candidate.\u{0020}The\u{0020}rest,\u{0020}as\u{0020}they\u{0020}say,\u{0020}is\u{0020}history.\u{0020}The\u{0020}Dragon\u{0020}Knights\u{0020}were\u{0020}born.", "0", "0", "0", "0", 10025, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602504] = {602504, 2000, "\u{0020}\u{0020}\"To\u{0020}ride\u{0020}a\u{0020}dragon,\u{0020}to\u{0020}fly\u{0020}freely\u{0020}through\u{0020}the\u{0020}sky,\u{0020}the\u{0020}earth,\u{0020}and\u{0020}the\u{0020}seas\u{0020}-\u{0020}that\u{0020}is\u{0020}my\u{0020}dream.\"\n\n\u{0020}\u{0020}Amidst\u{0020}the\u{0020}endless\u{0020}sea\u{0020}and\u{0020}sky,\n\n\u{0020}\u{0020}the\u{0020}girl\u{0020}cut\u{0020}through\u{0020}the\u{0020}waves\u{0020}and\u{0020}clouds,\u{0020}heading\u{0020}toward\u{0020}a\u{0020}burning\u{0020}city\u{0020}in\u{0020}the\u{0020}distance.\n\n\u{0020}\u{0020}The\u{0020}massive\u{0020}shadow\u{0020}of\u{0020}her\u{0020}ship\u{0020}was\u{0020}cast\u{0020}upon\u{0020}the\u{0020}blue\u{0020}sea\u{0020}beneath\u{0020}her.\n\n\u{0020}\u{0020}But\u{0020}now,\u{0020}she\u{0020}knew\u{0020}the\u{0020}truth.\u{0020}\"I\u{0020}am\u{0020}not\u{0020}yet\u{0020}lost\u{0020}in\u{0020}the\u{0020}dream.\"\n\n\u{0020}\u{0020}Freedom,\u{0020}she\u{0020}realized,\u{0020}wasn't\u{0020}free.\n\n\u{0020}\u{0020}It\u{0020}was\u{0020}a\u{0020}prize\u{0020}earned\u{0020}only\u{0020}after\u{0020}countless\u{0020}battles\u{0020}and\u{0020}painful\u{0020}farewells.\n\n\u{0020}\u{0020}Until\u{0020}then,\u{0020}all\u{0020}she\u{0020}could\u{0020}do\u{0020}was\u{0020}fly.", "0", "0", "0", "0", 10025, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
