[602601] = {602601, 100, "\u{0020}\u{0020}No\u{0020}one\u{0020}should\u{0020}mess\u{0020}with\u{0020}Nastya\u{0020}A\u{0020}Elizabeth.\n\nUnlike\u{0020}the\u{0020}dangerous\u{0020}sense\u{0020}brought\u{0020}by\u{0020}the\u{0020}wildness\u{0020}all\u{0020}over\u{0020}Zofia\u{0020}I.\u{0020}Pogolovsky,\u{0020}Nastya's\u{0020}appearance\u{0020}gives\u{0020}a\u{0020}false\u{0020}sense\u{0020}of\u{0020}security.\u{0020}Most\u{0020}of\u{0020}the\u{0020}time,\u{0020}Nastya's\u{0020}performance\u{0020}still\u{0020}conforms\u{0020}to\u{0020}the\u{0020}image\u{0020}of\u{0020}a\u{0020}generous\u{0020}and\u{0020}decent\u{0020}company\u{0020}executive\u{0020}or\u{0020}a\u{0020}dignified\u{0020}young\u{0020}lady.\n\nBut\u{0020}this\u{0020}is\u{0020}merely\u{0020}her\u{0020}exquisite\u{0020}disguise.\u{0020}When\u{0020}she\u{0020}shows\u{0020}that\u{0020}signature\u{0020}smile,\u{0020}her\u{0020}true\u{0020}side\u{0020}will\u{0020}be\u{0020}revealed\u{0020}-\u{0020}a\u{0020}\"tyrant\"\u{0020}who\u{0020}likes\u{0020}to\u{0020}humiliate\u{0020}others\u{0020}with\u{0020}\"pranks\"\u{0020}to\u{0020}satisfy\u{0020}her\u{0020}desire\u{0020}for\u{0020}control.\u{0020}The\u{0020}best\u{0020}choice\u{0020}is\u{0020}to\u{0020}get\u{0020}away\u{0020}from\u{0020}her\u{0020}vision\u{0020}in\u{0020}the\u{0020}most\u{0020}normal\u{0020}posture\u{0020}and\u{0020}at\u{0020}the\u{0020}fastest\u{0020}speed.\n\nBut\u{0020}even\u{0020}if\u{0020}escaped,\u{0020}one\u{0020}cannot\u{0020}let\u{0020}down\u{0020}vigilance\u{0020}-\u{0020}Nastya's\u{0020}\"pranks\"\u{0020}are\u{0020}everywhere.\u{0020}Her\u{0020}favorite\u{0020}thing\u{0020}is\u{0020}to\u{0020}ridicule\u{0020}those\u{0020}Siren\u{0020}employees\u{0020}who\u{0020}are\u{0020}in\u{0020}a\u{0020}sorry\u{0020}plight\u{0020}under\u{0020}her\u{0020}pranks.\u{0020}She\u{0020}is\u{0020}a\u{0020}dictator\u{0020}immersed\u{0020}in\u{0020}the\u{0020}resentment\u{0020}of\u{0020}others,\u{0020}and\u{0020}the\u{0020}expression\u{0020}of\u{0020}anger\u{0020}and\u{0020}helplessness\u{0020}is\u{0020}the\u{0020}source\u{0020}of\u{0020}her\u{0020}happiness.\n\nHowever,\u{0020}\"pranks\"\u{0020}are\u{0020}not\u{0020}her\u{0020}only\u{0020}purpose.\u{0020}These\u{0020}\"pranks\"\u{0020}are\u{0020}precisely\u{0020}the\u{0020}first\u{0020}step\u{0020}for\u{0020}her\u{0020}to\u{0020}\"rule\"\u{0020}Siren.", "0", "0", "0", "0", 10026, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602602] = {602602, 500, "\u{0020}\u{0020}Nastya's\u{0020}identity\u{0020}has\u{0020}been\u{0020}special\u{0020}since\u{0020}the\u{0020}first\u{0020}day\u{0020}she\u{0020}arrived\u{0020}at\u{0020}Siren.\n\nNot\u{0020}to\u{0020}mention\u{0020}the\u{0020}private\u{0020}living\u{0020}room\u{0020}and\u{0020}exclusive\u{0020}transformation\u{0020}facilities\u{0020}specially\u{0020}arranged\u{0020}for\u{0020}Nastya\u{0020}in\u{0020}Siren.\u{0020}Just\u{0020}the\u{0020}scale\u{0020}of\u{0020}the\u{0020}welcoming\u{0020}team\u{0020}when\u{0020}she\u{0020}first\u{0020}arrived\u{0020}was\u{0020}astonishing\u{0020}enough.\u{0020}Even\u{0020}the\u{0020}top\u{0020}management\u{0020}of\u{0020}Siren\u{0020}was\u{0020}all\u{0020}present.\u{0020}At\u{0020}that\u{0020}moment,\u{0020}Nastya\u{0020}A\u{0020}Elizabeth\u{0020}was\u{0020}undoubtedly\u{0020}the\u{0020}\"queen\"\u{0020}of\u{0020}Siren.\n\nIt\u{0020}is\u{0020}well\u{0020}known\u{0020}that\u{0020}the\u{0020}gigantification\u{0020}technology\u{0020}has\u{0020}always\u{0020}been\u{0020}one\u{0020}of\u{0020}the\u{0020}core\u{0020}secrets\u{0020}of\u{0020}AEGIS,\u{0020}which\u{0020}is\u{0020}crucial\u{0020}to\u{0020}whether\u{0020}humans\u{0020}can\u{0020}contend\u{0020}against\u{0020}Sin.\u{0020}But\u{0020}what\u{0020}the\u{0020}public\u{0020}does\u{0020}not\u{0020}know\u{0020}is\u{0020}that\u{0020}this\u{0020}technology\u{0020}is\u{0020}not\u{0020}exclusive\u{0020}to\u{0020}AEGIS.\u{0020}Katya's\u{0020}arms\u{0020}company,\u{0020}Siren,\u{0020}also\u{0020}possesses\u{0020}the\u{0020}magical\u{0020}power\u{0020}to\u{0020}gigantify\u{0020}girls.\n\nOf\u{0020}course,\u{0020}the\u{0020}price\u{0020}to\u{0020}be\u{0020}paid\u{0020}behind\u{0020}this\u{0020}huge\u{0020}power\u{0020}is\u{0020}huge.\u{0020}Apart\u{0020}from\u{0020}the\u{0020}extremely\u{0020}high\u{0020}R&D\u{0020}costs,\u{0020}the\u{0020}negotiation\u{0020}with\u{0020}AEGIS\u{0020}is\u{0020}the\u{0020}most\u{0020}important\u{0020}link.\u{0020}The\u{0020}specific\u{0020}process\u{0020}of\u{0020}the\u{0020}negotiation\u{0020}has\u{0020}been\u{0020}blocked\u{0020}by\u{0020}the\u{0020}intelligence\u{0020}department.\u{0020}We\u{0020}only\u{0020}know\u{0020}that\u{0020}after\u{0020}the\u{0020}negotiation\u{0020}ended,\u{0020}Katya\u{0020}Branch\u{0020}added\u{0020}a\u{0020}driver\u{0020}team\u{0020}nominally\u{0020}belonging\u{0020}to\u{0020}AEGIS\u{0020}but\u{0020}actually\u{0020}controlled\u{0020}by\u{0020}Siren\u{0020}-\u{0020}Cannonbore.\u{0020}Several\u{0020}relatives\u{0020}of\u{0020}important\u{0020}figures\u{0020}in\u{0020}Siren\u{0020}were\u{0020}also\u{0020}sent\u{0020}to\u{0020}the\u{0020}jurisdiction\u{0020}of\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters\u{0020}in\u{0020}the\u{0020}name\u{0020}of\u{0020}\"studying\u{0020}abroad\"\u{0020}but\u{0020}were\u{0020}actually\u{0020}\"prisoned\".\u{0020}Nastya,\u{0020}the\u{0020}daughter\u{0020}of\u{0020}the\u{0020}current\u{0020}president\u{0020}of\u{0020}Siren,\u{0020}is\u{0020}one\u{0020}of\u{0020}these\u{0020}\"students\".\n\nPerhaps\u{0020}it\u{0020}is\u{0020}because\u{0020}of\u{0020}her\u{0020}family\u{0020}education\u{0020}or\u{0020}the\u{0020}high\u{0020}general\u{0020}cognitive\u{0020}level\u{0020}of\u{0020}Katya\u{0020}people,\u{0020}Nastya\u{0020}appears\u{0020}more\u{0020}mature\u{0020}than\u{0020}other\u{0020}kids.\u{0020}She\u{0020}understood\u{0020}the\u{0020}fact\u{0020}that\u{0020}she\u{0020}was\u{0020}a\u{0020}\"hostage\"\u{0020}very\u{0020}early,\u{0020}but\u{0020}she\u{0020}did\u{0020}not\u{0020}endure\u{0020}this\u{0020}humiliating\u{0020}life.\u{0020}Instead,\u{0020}she\u{0020}is\u{0020}more\u{0020}aloof\u{0020}and\u{0020}wayward\u{0020}than\u{0020}her\u{0020}peers.\n\nOn\u{0020}the\u{0020}surface,\u{0020}Nastya\u{0020}still\u{0020}played\u{0020}the\u{0020}role\u{0020}of\u{0020}\"an\u{0020}exchange\u{0020}student\u{0020}from\u{0020}afar\u{0020}in\u{0020}Katya\",\u{0020}but\u{0020}secretly\u{0020}she\u{0020}bullied\u{0020}almost\u{0020}all\u{0020}the\u{0020}classmates\u{0020}around\u{0020}her,\u{0020}and\u{0020}even\u{0020}the\u{0020}teachers\u{0020}couldn't\u{0020}escape\u{0020}her\u{0020}\"pranks\".\n\nNastya's\u{0020}\"pranks\"\u{0020}are\u{0020}not\u{0020}simple\u{0020}school\u{0020}bullying.\u{0020}Every\u{0020}one\u{0020}of\u{0020}her\u{0020}pranks\u{0020}aims\u{0020}directly\u{0020}at\u{0020}the\u{0020}vital\u{0020}points\u{0020}of\u{0020}others.\u{0020}She\u{0020}simply\u{0020}verbally\u{0020}humiliates\u{0020}those\u{0020}with\u{0020}weak\u{0020}characters\u{0020}and\u{0020}designs\u{0020}traps\u{0020}to\u{0020}make\u{0020}those\u{0020}with\u{0020}strong\u{0020}self-esteem\u{0020}look\u{0020}bad\u{0020}in\u{0020}public.\u{0020}Nastya\u{0020}is\u{0020}like\u{0020}a\u{0020}snake\u{0020}awakening\u{0020}from\u{0020}hibernation,\u{0020}baring\u{0020}its\u{0020}fangs\u{0020}at\u{0020}all\u{0020}accessible\u{0020}prey\u{0020}around\u{0020}her.\u{0020}She\u{0020}embarrasses\u{0020}everyone,\u{0020}makes\u{0020}everyone\u{0020}hate\u{0020}her\u{0020}to\u{0020}the\u{0020}core,\u{0020}and\u{0020}also\u{0020}makes\u{0020}everyone\u{0020}fear\u{0020}her.\n\nRelying\u{0020}on\u{0020}her\u{0020}special\u{0020}identity,\u{0020}Nastya\u{0020}acted\u{0020}wilfully\u{0020}and\u{0020}unscrupulously\u{0020}on\u{0020}campus\u{0020}and\u{0020}had\u{0020}seemingly\u{0020}become\u{0020}the\u{0020}\"queen\"\u{0020}of\u{0020}the\u{0020}school.\u{0020}\n\n\u{0020}Until\u{0020}one\u{0020}day\u{0020}when\u{0020}Nastya\u{0020}was\u{0020}16\u{0020}years\u{0020}old,\u{0020}people\u{0020}from\u{0020}AEGIS\u{0020}suddenly\u{0020}appeared\u{0020}and\u{0020}took\u{0020}her\u{0020}away.\u{0020}By\u{0020}the\u{0020}early\u{0020}hours\u{0020}of\u{0020}the\u{0020}next\u{0020}day,\u{0020}she\u{0020}was\u{0020}already\u{0020}standing\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}building\u{0020}of\u{0020}Siren\u{0020}Company.\u{0020}\n\n\u{0020}Under\u{0020}the\u{0020}gaze\u{0020}of\u{0020}tens\u{0020}of\u{0020}thousands\u{0020}of\u{0020}people,\u{0020}Nastya\u{0020}walked\u{0020}with\u{0020}her\u{0020}head\u{0020}held\u{0020}high\u{0020}and\u{0020}entered\u{0020}her\u{0020}kingdom\u{0020}in\u{0020}high\u{0020}spirits.", "0", "0", "0", "0", 10026, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602603] = {602603, 1000, "\u{0020}\u{0020}When\u{0020}Nastya\u{0020}returned\u{0020}to\u{0020}Siren,\u{0020}she\u{0020}did\u{0020}not\u{0020}experience\u{0020}the\u{0020}expected\u{0020}acclimatization\u{0020}problems.\u{0020}The\u{0020}years\u{0020}spent\u{0020}in\u{0020}Kyushu\u{0020}did\u{0020}not\u{0020}change\u{0020}the\u{0020}Katya\u{0020}bloodline\u{0020}in\u{0020}her\u{0020}body.\n\nAlthough\u{0020}Nastya\u{0020}is\u{0020}a\u{0020}member\u{0020}of\u{0020}Cannonbore,\u{0020}she\u{0020}has\u{0020}little\u{0020}interaction\u{0020}with\u{0020}other\u{0020}team\u{0020}members.\u{0020}Not\u{0020}to\u{0020}mention\u{0020}that\u{0020}Nastya\u{0020}has\u{0020}a\u{0020}private\u{0020}luxurious\u{0020}living\u{0020}room,\u{0020}even\u{0020}the\u{0020}transformation\u{0020}pool\u{0020}for\u{0020}gigantification\u{0020}has\u{0020}a\u{0020}dedicated\u{0020}one\u{0020}for\u{0020}her.\u{0020}For\u{0020}her,\u{0020}being\u{0020}affiliated\u{0020}with\u{0020}the\u{0020}Cannonbore\u{0020}team\u{0020}is\u{0020}just\u{0020}to\u{0020}increase\u{0020}her\u{0020}future\u{0020}bargaining\u{0020}chips\u{0020}-\u{0020}the\u{0020}bargaining\u{0020}chips\u{0020}for\u{0020}seizing\u{0020}Siren.\n\nThe\u{0020}only\u{0020}chance\u{0020}to\u{0020}gather\u{0020}all\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}Cannonbore\u{0020}team\u{0020}is\u{0020}when\u{0020}they\u{0020}assemble\u{0020}for\u{0020}battle.\n\nNastya's\u{0020}armor\u{0020}is\u{0020}the\u{0020}crystallization\u{0020}of\u{0020}all\u{0020}the\u{0020}technological\u{0020}strength\u{0020}of\u{0020}Siren,\u{0020}but\u{0020}it\u{0020}still\u{0020}cannot\u{0020}solve\u{0020}the\u{0020}defect\u{0020}that\u{0020}causes\u{0020}a\u{0020}huge\u{0020}burden\u{0020}on\u{0020}the\u{0020}user's\u{0020}body.\u{0020}Because\u{0020}of\u{0020}this,\u{0020}the\u{0020}people\u{0020}in\u{0020}Siren's\u{0020}equipment\u{0020}R&D\u{0020}department\u{0020}are\u{0020}often\u{0020}punished\u{0020}or\u{0020}even\u{0020}fired\u{0020}for\u{0020}absurd\u{0020}reasons\u{0020}such\u{0020}as\u{0020}not\u{0020}wearing\u{0020}the\u{0020}company\u{0020}uniform\u{0020}correctly.", "0", "0", "0", "0", 10026, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
