[602701] = {602701, 100, "Alvitr\u{0020}is\u{0020}an\u{0020}incredible\u{0020}woman.\n\nIn\u{0020}Katya\u{0020}Branch\u{0020}and\u{0020}AEGIS,\u{0020}there\u{0020}are\u{0020}only\u{0020}a\u{0020}few\u{0020}people\u{0020}who\u{0020}have\u{0020}two\u{0020}identities\u{0020}-\u{0020}a\u{0020}driver\u{0020}and\u{0020}another\u{0020}one.\u{0020}Among\u{0020}them,\u{0020}Alvitr\u{0020}stands\u{0020}out.\n\nBecause\u{0020}she\u{0020}is\u{0020}not\u{0020}only\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}\"Valkyrie\"\u{0020}team,\u{0020}which\u{0020}symbolizes\u{0020}the\u{0020}absolute\u{0020}power\u{0020}of\u{0020}Katya\u{0020}Branch,\u{0020}but\u{0020}also\u{0020}a\u{0020}core\u{0020}researcher\u{0020}of\u{0020}the\u{0020}\"First\u{0020}Research\u{0020}Laboratory\".\n\nSpecial\u{0020}talents\u{0020}like\u{0020}her\u{0020}who\u{0020}shoulder\u{0020}two\u{0020}important\u{0020}positions\u{0020}at\u{0020}the\u{0020}same\u{0020}time\u{0020}have\u{0020}surpassed\u{0020}the\u{0020}\"minority\"\u{0020}category\u{0020}and\u{0020}become\u{0020}\"alternative\".\n\nPerhaps\u{0020}precisely\u{0020}because\u{0020}she\u{0020}possesses\u{0020}rare\u{0020}talents,\u{0020}she\u{0020}has\u{0020}entered\u{0020}the\u{0020}domain\u{0020}that\u{0020}only\u{0020}a\u{0020}few\u{0020}people\u{0020}step\u{0020}into\u{0020}and\u{0020}has\u{0020}seen\u{0020}the\u{0020}future\u{0020}of\u{0020}humanity\u{0020}-\u{0020}that's\u{0020}why\u{0020}she\u{0020}would\u{0020}say\u{0020}such\u{0020}words:\n\n\"Nowadays,\u{0020}humans\u{0020}need\u{0020}a\u{0020}sage\u{0020}to\u{0020}guide\u{0020}the\u{0020}way,\u{0020}and\u{0020}I\u{0020}am\u{0020}the\u{0020}best\u{0020}candidate.\"\u{0020}\n\nIn\u{0020}the\u{0020}eyes\u{0020}of\u{0020}others,\u{0020}it\u{0020}is\u{0020}arrogance.\u{0020}But\u{0020}in\u{0020}her\u{0020}own\u{0020}view,\u{0020}this\u{0020}is\u{0020}just\u{0020}an\u{0020}objective\u{0020}evaluation\u{0020}of\u{0020}herself.\u{0020}\u{0020}", "0", "0", "0", "0", 10027, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602702] = {602702, 500, "Alvitr\u{0020}is\u{0020}a\u{0020}genius.\u{0020}This\u{0020}is\u{0020}an\u{0020}undoubted\u{0020}fact.\u{0020}The\u{0020}word\u{0020}\"genius\"\u{0020}can\u{0020}be\u{0020}used\u{0020}as\u{0020}her\u{0020}label\u{0020}and\u{0020}written\u{0020}in\u{0020}her\u{0020}personal\u{0020}introduction.\n\nAfter\u{0020}the\u{0020}end\u{0020}of\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}Greed\u{0020}Invasion\u{0020}incident,\u{0020}she\u{0020}joined\u{0020}the\u{0020}First\u{0020}Research\u{0020}Laboratory\u{0020}and\u{0020}quickly\u{0020}became\u{0020}a\u{0020}core\u{0020}member\u{0020}of\u{0020}the\u{0020}laboratory,\u{0020}participating\u{0020}in\u{0020}the\u{0020}research\u{0020}and\u{0020}development\u{0020}work\u{0020}related\u{0020}to\u{0020}\"DOMINATOR\"\u{0020}in\u{0020}the\u{0020}First\u{0020}Research\u{0020}Laboratory.\n\nGenerally\u{0020}speaking,\u{0020}for\u{0020}a\u{0020}front-line\u{0020}researcher\u{0020}like\u{0020}her\u{0020}who\u{0020}is\u{0020}involved\u{0020}in\u{0020}the\u{0020}core\u{0020}project\u{0020}of\u{0020}AEGIS,\u{0020}even\u{0020}if\u{0020}she\u{0020}has\u{0020}the\u{0020}qualifications,\u{0020}AEGIS\u{0020}would\u{0020}not\u{0020}allow\u{0020}her\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}who\u{0020}could\u{0020}be\u{0020}in\u{0020}danger\u{0020}at\u{0020}any\u{0020}time.\n\nBut\u{0020}Alvitr\u{0020}obviously\u{0020}has\u{0020}different\u{0020}privileges.\u{0020}The\u{0020}license\u{0020}for\u{0020}her\u{0020}to\u{0020}apply\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}was\u{0020}issued\u{0020}by\u{0020}Dr.\u{0020}Stephanie\u{0020}from\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters.\n\nThe\u{0020}\"Valkyrie\"\u{0020}team\u{0020}created\u{0020}by\u{0020}her\u{0020}is\u{0020}of\u{0020}great\u{0020}significance\u{0020}to\u{0020}Katya\u{0020}and\u{0020}the\u{0020}entire\u{0020}AEGIS.\u{0020}In\u{0020}Katya\u{0020}Branch,\u{0020}there\u{0020}are\u{0020}driver\u{0020}teams\u{0020}like\u{0020}\"Snow\u{0020}Owl\"\u{0020}that\u{0020}symbolize\u{0020}the\u{0020}official\u{0020}AEGIS.\u{0020}However,\u{0020}\"Valkyrie\"\u{0020}is\u{0020}different\u{0020}from\u{0020}them.\u{0020}It\u{0020}is\u{0020}more\u{0020}like\u{0020}a\u{0020}team\u{0020}stationed\u{0020}in\u{0020}the\u{0020}Katya\u{0020}area\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}headquarters.\n\nIn\u{0020}a\u{0020}more\u{0020}straightforward\u{0020}way\u{0020}-\u{0020}\"Valkyrie\"\u{0020}geographically\u{0020}belongs\u{0020}to\u{0020}Katya\u{0020}Branch,\u{0020}and\u{0020}in\u{0020}terms\u{0020}of\u{0020}the\u{0020}command\u{0020}system,\u{0020}it\u{0020}belongs\u{0020}to\u{0020}Kyushu\u{0020}Headquarters.\n\nThus\u{0020}a\u{0020}series\u{0020}of\u{0020}questions\u{0020}arose.\n\nWhy\u{0020}is\u{0020}Alvitr\u{0020}so\u{0020}trusted\u{0020}by\u{0020}Kyushu\u{0020}Headquarters?\u{0020}Why\u{0020}does\u{0020}she\u{0020}enjoy\u{0020}various\u{0020}privileges?\u{0020}Why\u{0020}does\u{0020}she\u{0020}have\u{0020}a\u{0020}close\u{0020}connection\u{0020}with\u{0020}Dr.\u{0020}Stephanie,\u{0020}who\u{0020}has\u{0020}not\u{0020}shown\u{0020}up\u{0020}at\u{0020}Kyushu\u{0020}Headquarters\u{0020}for\u{0020}a\u{0020}long\u{0020}time?\n\nWho\u{0020}is\u{0020}she?\u{0020}What\u{0020}did\u{0020}she\u{0020}experience\u{0020}before\u{0020}joining\u{0020}AEGIS?\n\nWe\u{0020}have\u{0020}no\u{0020}way\u{0020}of\u{0020}knowing.\n\nAlvitr's\u{0020}extraordinary\u{0020}talent,\u{0020}the\u{0020}privileges\u{0020}she\u{0020}enjoys\u{0020}in\u{0020}AEGIS\u{0020}and\u{0020}her\u{0020}untraceable\u{0020}past\u{0020}have\u{0020}given\u{0020}her\u{0020}a\u{0020}legendary\u{0020}touch.\n\nThere\u{0020}is\u{0020}undoubtedly\u{0020}a\u{0020}secret\u{0020}waiting\u{0020}to\u{0020}be\u{0020}deeply\u{0020}explored\u{0020}in\u{0020}her,\u{0020}but\u{0020}presumably\u{0020}no\u{0020}one\u{0020}would\u{0020}be\u{0020}so\u{0020}reckless\u{0020}as\u{0020}to\u{0020}do\u{0020}such\u{0020}a\u{0020}stupid\u{0020}thing\u{0020}that\u{0020}might\u{0020}lead\u