[602703] = {602703, 1000, "I\u{0020}still\u{0020}couldn't\u{0020}resist\u{0020}investigating.\n\nIt\u{0020}is\u{0020}human\u{0020}nature\u{0020}to\u{0020}do\u{0020}stupid\u{0020}things\u{0020}because\u{0020}one\u{0020}cannot\u{0020}restrain\u{0020}one's\u{0020}curiosity.\u{0020}I\u{0020}am\u{0020}not\u{0020}at\u{0020}all\u{0020}surprised\u{0020}that\u{0020}I\u{0020}did\u{0020}such\u{0020}stupid\u{0020}things.\u{0020}In\u{0020}terms\u{0020}of\u{0020}the\u{0020}result,\u{0020}I\u{0020}think\u{0020}the\u{0020}stupid\u{0020}things\u{0020}I\u{0020}did\u{0020}were\u{0020}worth\u{0020}it.\n\nI\u{0020}think\u{0020}Alvitr\u{0020}is\u{0020}a\u{0020}genius,\u{0020}and\u{0020}the\u{0020}result\u{0020}of\u{0020}the\u{0020}investigation\u{0020}further\u{0020}confirmed\u{0020}that\u{0020}her\u{0020}extraordinary\u{0020}aptitude\u{0020}is\u{0020}not\u{0020}an\u{0020}accidental\u{0020}one\u{0020}in\u{0020}a\u{0020}million,\u{0020}but\u{0020}an\u{0020}inevitability.\n\nShe\u{0020}is\u{0020}different\u{0020}from\u{0020}ordinary\u{0020}humans\u{0020}-\u{0020}she\u{0020}is\u{0020}a\u{0020}product\u{0020}of\u{0020}the\u{0020}laboratory.\n\nMore\u{0020}accurately\u{0020}speaking,\u{0020}she\u{0020}is\u{0020}the\u{0020}crystallization\u{0020}of\u{0020}genetic\u{0020}engineering\u{0020}and\u{0020}the\u{0020}best\u{0020}solution\u{0020}selected\u{0020}from\u{0020}tens\u{0020}of\u{0020}thousands\u{0020}of\u{0020}human\u{0020}genes.\n\nTherefore,\u{0020}her\u{0020}extraordinary\u{0020}talent\u{0020}has\u{0020}become\u{0020}an\u{0020}inevitability.\n\nFrom\u{0020}the\u{0020}very\u{0020}beginning\u{0020}of\u{0020}her\u{0020}birth,\u{0020}she\u{0020}was\u{0020}endowed\u{0020}with\u{0020}the\u{0020}mission\u{0020}of\u{0020}\"saving\u{0020}humanity\".\u{0020}Unfortunately,\u{0020}during\u{0020}her\u{0020}growth\u{0020}process,\u{0020}the\u{0020}people\u{0020}who\u{0020}created\u{0020}her\u{0020}became\u{0020}afraid\u{0020}of\u{0020}her\u{0020}talent,\u{0020}grew\u{0020}wary\u{0020}of\u{0020}her,\u{0020}and\u{0020}tried\u{0020}to\u{0020}restrain\u{0020}her\u{0020}in\u{0020}various\u{0020}ways\u{0020}to\u{0020}make\u{0020}her\u{0020}a\u{0020}tool.\n\nHumans\u{0020}are\u{0020}always\u{0020}like\u{0020}this,\u{0020}being\u{0020}afraid\u{0020}of\u{0020}things\u{0020}they\u{0020}cannot\u{0020}understand.\n\nFinally,\u{0020}she\u{0020}destroyed\u{0020}the\u{0020}place\u{0020}of\u{0020}her\u{0020}birth\u{0020}with\u{0020}her\u{0020}own\u{0020}hands.\n\nShe\u{0020}was\u{0020}supposed\u{0020}to\u{0020}be\u{0020}the\u{0020}enemy\u{0020}of\u{0020}humanity,\u{0020}but\u{0020}judging\u{0020}from\u{0020}her\u{0020}close\u{0020}connection\u{0020}with\u{0020}Dr.\u{0020}Stephanie\u{0020}later,\u{0020}it\u{0020}was\u{0020}Dr.\u{0020}Stephanie\u{0020}who\u{0020}changed\u{0020}her\u{0020}mind\u{0020}and\u{0020}made\u{0020}her\u{0020}join\u{0020}AEGIS.\n\nPerhaps\u{0020}her\u{0020}past\u{0020}has\u{0020}never\u{0020}been\u{0020}a\u{0020}secret\u{0020}that\u{0020}was\u{0020}not\u{0020}allowed\u{0020}to\u{0020}be\u{0020}known.\u{0020}It's\u{0020}just\u{0020}that\u{0020}no\u{0020}one\u{0020}has\u{0020}ever\u{0020}had\u{0020}the\u{0020}idea\u{0020}of\u{0020}asking\u{0020}her\u{0020}in\u{0020}person?", "0", "0", "0", "0", 10027, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602704] = {602704, 2000, "The\u{0020}white\u{0020}and\u{0020}bright\u{0020}phantom\u{0020}hanging\u{0020}in\u{0020}the\u{0020}sky\n\nThe\u{0020}enemy\u{0020}of\u{0020}mankind\u{0020}dwells\u{0020}above.\n\nThe\u{0020}bright\u{0020}white\u{0020}fear\u{0020}comes\u{0020}beneath\u{0020}the\u{0020}clouds\u{0020}and\u{0020}fog.\n\nThe\u{0020}girl\u{0020}in\u{0020}armor\u{0020}stares\u{0020}directly\u{0020}at\u{0020}that\u{0020}cold\u{0020}and\u{0020}clear\u{0020}light.\n\nOn\u{0020}the\u{0020}shoulder\u{0020}is\u{0020}the\u{0020}leader\u{0020}of\u{0020}humanity\u{0020}who\u{0020}stands\u{0020}on\u{0020}the\u{0020}same\u{0020}side\u{0020}as\u{0020}her.\n\n\"I\u{0020}will\u{0020}accompany\u{0020}you\u{0020}to\u{0020}the\u{0020}end\u{0020}of\u{0020}this\u{0020}world.\"\n\n\"Whether\u{0020}it\u{0020}is\u{0020}a\u{0020}blank\u{0020}world\u{0020}where\u{0020}everything\u{0020}is\u{0020}extinct,\u{0020}or\u{0020}a\u{0020}new\u{0020}world\u{0020}where\u{0020}you\u{0020}and\u{0020}I\u{0020}no\u{0020}longer\u{0020}exist.\"\n\n\"I\u{0020}will\u{0020}accompany\u{0020}you.\u{0020}This\u{0020}is\u{0020}my\u{0020}mission.\"", "0", "0", "0", "0", 10027, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
