[602801] = {602801, 100, "Mojun\u{0020}is\u{0020}a\u{0020}serious\u{0020}and\u{0020}dignified\u{0020}teacher.\u{0020}She\u{0020}is\u{0020}not\u{0020}only\u{0020}strict\u{0020}with\u{0020}herself\u{0020}but\u{0020}also\u{0020}quite\u{0020}strict\u{0020}with\u{0020}her\u{0020}students.\u{0020}Because\u{0020}they\u{0020}come\u{0020}from\u{0020}the\u{0020}Kyushu\u{0020}region,\u{0020}some\u{0020}students\u{0020}even\u{0020}jokingly\u{0020}learn\u{0020}the\u{0020}way\u{0020}of\u{0020}speaking\u{0020}in\u{0020}costume\u{0020}dramas\u{0020}and\u{0020}call\u{0020}her\u{0020}\"Master\",\u{0020}for\u{0020}which\u{0020}the\u{0020}reason\u{0020}is\u{0020}that\u{0020}Mojun\u{0020}is\u{0020}not\u{0020}old-fashioned\u{0020}but\u{0020}approachable.\u{0020}Her\u{0020}strictness\u{0020}is\u{0020}only\u{0020}aimed\u{0020}at\u{0020}studies.\n\nOther\u{0020}than\u{0020}educational\u{0020}affairs,\u{0020}Mojun\u{0020}knows\u{0020}how\u{0020}to\u{0020}distinguish\u{0020}between\u{0020}public\u{0020}and\u{0020}private.\u{0020}During\u{0020}breaks,\u{0020}she\u{0020}chats\u{0020}with\u{0020}students\u{0020}about\u{0020}trendy\u{0020}topics.\u{0020}Occasionally,\u{0020}she\u{0020}goes\u{0020}to\u{0020}accessory\u{0020}stores\u{0020}with\u{0020}them\u{0020}after\u{0020}school.\u{0020}She\u{0020}also\u{0020}acts\u{0020}as\u{0020}a\u{0020}confidant\u{0020}senior,\u{0020}listening\u{0020}to\u{0020}the\u{0020}troubles\u{0020}and\u{0020}unease\u{0020}of\u{0020}juniors.\u{0020}She\u{0020}is\u{0020}both\u{0020}a\u{0020}good\u{0020}teacher\u{0020}and\u{0020}a\u{0020}beneficial\u{0020}friend.", "0", "0", "0", "0", 10028, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602802] = {602802, 500, "\u{0020}\u{0020}In\u{0020}the\u{0020}new\u{0020}era\u{0020}of\u{0020}rapid\u{0020}scientific\u{0020}progress,\u{0020}an\u{0020}endless\u{0020}stream\u{0020}of\u{0020}cutting-edge\u{0020}technologies\u{0020}and\u{0020}electronic\u{0020}equipment\u{0020}has\u{0020}enabled\u{0020}people\u{0020}to\u{0020}stride\u{0020}forward\u{0020}towards\u{0020}a\u{0020}better\u{0020}tomorrow.\u{0020}Meanwhile,\u{0020}many\u{0020}techniques\u{0020}that\u{0020}have\u{0020}been\u{0020}passed\u{0020}down\u{0020}for\u{0020}thousands\u{0020}of\u{0020}years\u{0020}will\u{0020}inevitably\u{0020}decline\u{0020}in\u{0020}a\u{0020}short\u{0020}period\u{0020}of\u{0020}time,\u{0020}and\u{0020}even\u{0020}be\u{0020}replaced\u{0020}by\u{0020}new\u{0020}things.\u{0020}In\u{0020}such\u{0020}a\u{0020}trend\u{0020}of\u{0020}the\u{0020}times,\u{0020}a\u{0020}girl\u{0020}named\u{0020}Mojun,\u{0020}who\u{0020}was\u{0020}born\u{0020}in\u{0020}an\u{0020}ancient\u{0020}family\u{0020}in\u{0020}Kyushu,\u{0020}has\u{0020}held\u{0020}an\u{0020}ideal\u{0020}since\u{0020}childhood:\u{0020}to\u{0020}promote\u{0020}the\u{0020}declining\u{0020}family-inherited\u{0020}mechanism\u{0020}art\u{0020}and\u{0020}ensure\u{0020}its\u{0020}continuation\u{0020}and\u{0020}inheritance.\n\nWhen\u{0020}she\u{0020}was\u{0020}still\u{0020}a\u{0020}child,\u{0020}Mojun\u{0020}showed\u{0020}an\u{0020}amazing\u{0020}talent\u{0020}in\u{0020}mechanism\u{0020}skills.\u{0020}With\u{0020}little\u{0020}knowledge\u{0020}and\u{0020}some\u{0020}personal\u{0020}understanding\u{0020}and\u{0020}intuition\u{0020}of\u{0020}mechanical\u{0020}structures,\u{0020}she\u{0020}was\u{0020}able\u{0020}to\u{0020}successfully\u{0020}create\u{0020}complex\u{0020}mechanism\u{0020}devices\u{0020}with\u{0020}various\u{0020}shapes.\u{0020}At\u{0020}that\u{0020}time,\u{0020}Mojun\u{0020}was\u{0020}always\u{0020}surrounded\u{0020}by\u{0020}many\u{0020}playmates,\u{0020}because\u{0020}she\u{0020}could\u{0020}create\u{0020}small\u{0020}mechanism\u{0020}animals\u{0020}with\u{0020}some\u{0020}broken\u{0020}branches\u{0020}that\u{0020}she\u{0020}picked\u{0020}up\u{0020}at\u{0020}random,\u{0020}which\u{0020}was\u{0020}very\u{0020}fun\u{0020}for\u{0020}her\u{0020}peers.However,\u{0020}Mojun\u{0020}is\u{0020}not\u{0020}satisfied\u{0020}with\u{0020}this.\n\nIndeed,\u{0020}Mojun\u{0020}loves\u{0020}all\u{0020}delicate\u{0020}and\u{0020}exquisite\u{0020}things,\u{0020}such\u{0020}as\u{0020}rattan\u{0020}jewelry,\u{0020}glass\u{0020}artworks,\u{0020}mechanical\u{0020}clocks\u{0020}and\u{0020}watches...\u{0020}She\u{0020}is\u{0020}also\u{0020}quite\u{0020}proud\u{0020}of\u{0020}the\u{0020}mechanical\u{0020}devices\u{0020}at\u{0020}home.\u{0020}The\u{0020}only\u{0020}regret\u{0020}is\u{0020}that\u{0020}this\u{0020}skill\u{0020}has\u{0020}now\u{0020}stagnated\u{0020}and\u{0020}perhaps\u{0020}one\u{0020}day\u{0020}it\u{0020}will\u{0020}be\u{0020}left\u{0020}far\u{0020}behind\u{0020}by\u{0020}the\u{0020}times.\n\nWith\u{0020}the\u{0020}idea\u{0020}of\u{0020}reforming\u{0020}the\u{0020}mechanism\u{0020}art,\u{0020}Mojun\u{0020}went\u{0020}to\u{0020}Sahara\u{0020}to\u{0020}study.\u{0020}During\u{0020}her\u{0020}student\u{0020}years,\u{0020}she\u{0020}strived\u{0020}to\u{0020}acquire\u{0020}knowledge,\u{0020}hoping\u{0020}to\u{0020}inject\u{0020}new\u{0020}vitality\u{0020}into\u{0020}the\u{0020}traditional\u{0020}art\u{0020}with\u{0020}advanced\u{0020}technology.\u{0020}She\u{0020}inherited\u{0020}the\u{0020}exquisite\u{0020}and\u{0020}changeable\u{0020}design\u{0020}of\u{0020}the\u{0020}mechanism\u{0020}art,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}decentralized\u{0020}overall\u{0020}structure,\u{0020}and\u{0020}incorporated\u{0020}the\u{0020}intelligent\u{0020}sensing\u{0020}system\u{0020}of\u{0020}the\u{0020}information\u{0020}age\u{0020}into\u{0020}it...\u{0020}She\u{0020}gradually\u{0020}saw\u{0020}the\u{0020}potential\u{0020}of\u{0020}the\u{0020}mechanism\u{0020}art\u{0020}yet\u{0020}to\u{0020}be\u{0020}explored.\n\nIn\u{0020}the\u{0020}year\u{0020}of\u{0020}the\u{0020}invasion\u{0020}of\u{0020}the\u{0020}Sin,\u{0020}Mojun\u{0020}became\u{0020}a\u{0020}driver\u{0020}like\u{0020}some\u{0020}of\u{0020}her\u{0020}peers.\u{0020}She\u{0020}made\u{0020}many\u{0020}contributions\u{0020}to\u{0020}the\u{0020}battle\u{0020}with\u{0020}the\u{0020}ever-changing\u{0020}new\u{0020}mechanism\u{0020}art.\u{0020}Position\u{0020}warfare,\u{0020}urban\u{0020}defense,\u{0020}and\u{0020}urban\u{0020}reconstruction\u{0020}all\u{0020}benefited\u{0020}from\u{0020}the\u{0020}characteristic\u{0020}of\u{0020}the\u{0020}mechanism\u{0020}device\u{0020}that\u{0020}\"it\u{0020}is\u{0020}exquisite\u{0020}when\u{0020}contracted\u{0020}and\u{0020}stable\u{0020}when\u{0020}expanded\",\u{0020}and\u{0020}the\u{0020}process\u{0020}went\u{0020}much\u{0020}more\u{0020}smoothly.\u{0020}The\u{0020}decentralized\u{0020}and\u{0020}modular\u{0020}structure\u{0020}also\u{0020}gave\u{0020}the\u{0020}operation\u{0020}more\u{0020}in-depth\u{0020}and\u{0020}flexible\u{0020}strategic\u{0020}value.\n\nWar\u{0020}undoubtedly\u{0020}gave\u{0020}rise\u{0020}to\u{0020}many\u{0020}technologies,\u{0020}and\u{0020}Mojun's\u{0020}mechanism\u{0020}art\u{0020}was\u{0020}a\u{0020}glimmer\u{0020}among\u{0020}the\u{0020}numerous\u{0020}new\u{0020}technologies.\u{0020}More\u{0020}and\u{0020}more\u{0020}people\u{0020}have\u{0020}realized\u{0020}its\u{0020}potential.\u{0020}After\u{0020}retiring,\u{0020}Mojun\u{0020}founded\u{0020}\"Mechanism\u{0020}Engineering\",\u{0020}chose\u{0020}to\u{0020}stay\u{0020}and\u{0020}teach\u{0020}at\u{0020}Azure\u{0020}Academy,\u{0020}and\u{0020}was\u{0020}committed\u{0020}to\u{0020}continuing\u{0020}to\u{0020}delve\u{0020}into\u{0020}this\u{0020}knowledge\u{0020}to\u{0020}make\u{0020}it\u{0020}timeless.", "0", "0", "0", "0", 10028, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602803] = {602803, 1000, "\u{0020}During\u{0020}her\u{0020}service,\u{0020}Mojun\u{0020}had\u{0020}seen\u{0020}some\u{0020}drivers\u{0020}drivers\u{0020}who\u{0020}were\u{0020}deeply\u{0020}trapped\u{0020}in\u{0020}rage\u{0020}and\u{0020}blinded\u{0020}by\u{0020}hatred.\u{0020}Their\u{0020}combat\u{0020}methods,\u{0020}regardless\u{0020}of\u{0020}the\u{0020}environment\u{0020}and\u{0020}the\u{0020}distinction\u{0020}between\u{0020}enemies\u{0020}and\u{0020}allies,\u{0020}eventually\u{0020}caused\u{0020}damage\u{0020}no\u{0020}less\u{0020}than\u{0020}Sin.\u{0020}Mojun\u{0020}had\u{0020}no\u{0020}intention\u{0020}of\u{0020}blaming\u{0020}those\u{0020}girls\u{0020}who\u{0020}were\u{0020}also\u{0020}victims\u{0020}of\u{0020}the\u{0020}war.\u{0020}After\u{0020}all,\u{0020}the\u{0020}mental\u{0020}burden\u{0020}during\u{0020}gigantification\u{0020}could\u{0020}not\u{0020}be\u{0020}ignored.\u{0020}She\u{0020}only\u{0020}hoped\u{0020}that\u{0020}there\u{0020}would\u{0020}be\u{0020}a\u{0020}way\u{0020}to\u{0020}avoid\u{0020}such\u{0020}accidents.\n\nTherefore,\u{0020}in\u{0020}the\u{0020}classroom,\u{0020}Mojun\u{0020}not\u{0020}only\u{0020}imparts\u{0020}combat\u{0020}experience\u{0020}and\u{0020}engineering\u{0020}knowledge\u{0020}but\u{0020}also\u{0020}often\u{0020}conveys\u{0020}her\u{0020}ideas\u{0020}to\u{0020}the\u{0020}younger\u{0020}generations.\u{0020}She\u{0020}attempts\u{0020}to\u{0020}interpret\u{0020}the\u{0020}Mohist\u{0020}thought\u{0020}of\u{0020}\"universal\u{0020}love\u{0020}and\u{0020}non-aggression\"\u{0020}in\u{0020}a\u{0020}modern\u{0020}context,\u{0020}allowing\u{0020}students\u{0020}to\u{0020}understand\u{0020}more\u{0020}profoundly\u{0020}the\u{0020}significance\u{0020}of\u{0020}launching\u{0020}counterattacks\u{0020}and\u{0020}struggles\u{0020}against\u{0020}Sin.\n\nThis\u{0020}approach\u{0020}sometimes\u{0020}causes\u{0020}the\u{0020}pent-up\u{0020}anger\u{0020}and\u{0020}hatred\u{0020}of\u{0020}the\u{0020}younger\u{0020}generation\u{0020}to\u{0020}be\u{0020}directed\u{0020}at\u{0020}herself,\u{0020}and\u{0020}some\u{0020}conservative\u{0020}mohists\u{0020}also\u{0020}raise\u{0020}objections\u{0020}to\u{0020}her\u{0020}interpretation.\u{0020}However,\u{0020}in\u{0020}Mojun's\u{0020}view,\u{0020}these\u{0020}are\u{0020}insignificant.\u{0020}These\u{0020}feedbacks\u{0020}originally\u{0020}mean\u{0020}that\u{0020}a\u{0020}transformation\u{0020}is\u{0020}taking\u{0020}off,\u{0020}just\u{0020}like\u{0020}a\u{0020}gradually\u{0020}activating\u{0020}mechanism\u{0020}device.", "0", "0", "0", "0", 10028, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602804] = {602804, 2000, "\u{0020}\u{0020}Thought\u{0020}it\u{0020}was\u{0020}another\u{0020}ordinary\u{0020}day\u{0020}and\u{0020}the\u{0020}teacher's\u{0020}class\u{0020}was\u{0020}about\u{0020}to\u{0020}begin,\n\nAmong\u{0020}the\u{0020}schoolyard\u{0020}square\u{0020}shaded\u{0020}by\u{0020}olive\u{0020}leaves,\u{0020}a\u{0020}figure\u{0020}with\u{0020}long\u{0020}black\u{0020}hair\u{0020}fluttering\u{0020}was\u{0020}seen.\n\n\"Today's\u{0020}class\u{0020}will\u{0020}be\u{0020}held\u{0020}here.\u{0020}\"\n\nThe\u{0020}brief\u{0020}words\u{0020}filled\u{0020}the\u{0020}students\u{0020}with\u{0020}confusion.\n\nUntil\u{0020}they\u{0020}couldn't\u{0020}help\u{0020}but\u{0020}notice\u{0020}that\u{0020}the\u{0020}earth\u{0020}was\u{0020}trembling\u{0020}along\u{0020}with\u{0020}the\u{0020}leaves\u{0020}-\n\nThree\u{0020}or\u{0020}five\u{0020}huge\u{0020}boxes\u{0020}rose\u{0020}from\u{0020}the\u{0020}ground,\u{0020}and\u{0020}their\u{0020}outlines\u{0020}and\u{0020}structures\u{0020}kept\u{0020}changing.\n\nThe\u{0020}sound\u{0020}of\u{0020}the\u{0020}mechanical\u{0020}gears\u{0020}turning\u{0020}is\u{0020}like\u{0020}the\u{0020}rhythmic\u{0020}chants\u{0020}of\u{0020}the\u{0020}workers.\n\n\"KKKHAAAKKKHAA...\u{0020}KKHAAKKHAA...\u{0020}\"\n\nWhile\u{0020}in\u{0020}shock,\u{0020}the\u{0020}commotion\u{0020}gradually\u{0020}subsided,\u{0020}and\u{0020}the\u{0020}birds\u{0020}startled\u{0020}from\u{0020}their\u{0020}nests\u{0020}were\u{0020}circling\u{0020}above.\n\nThey\u{0020}no\u{0020}longer\u{0020}knew\u{0020}where\u{0020}to\u{0020}go,\u{0020}and\u{0020}a\u{0020}tall\u{0020}and\u{0020}conspicuous\u{0020}building\u{0020}had\u{0020}been\u{0020}completed.\n\n\"Come\u{0020}on,\u{0020}enter\u{0020}this\u{0020}school.\u{0020}The\u{0020}charm\u{0020}of\u{0020}mechanical\u{0020}artistry\u{0020}lies\u{0020}within.\"", "0", "0", "0", "0", 10028, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
