[602901] = {602901, 100, "\u{0020}\u{0020}Although\u{0020}Lily\u{0020}lived\u{0020}on\u{0020}the\u{0020}ark\u{0020}of\u{0020}Kyushu,\u{0020}few\u{0020}people\u{0020}knew\u{0020}of\u{0020}her\u{0020}existence.\u{0020}Although\u{0020}Dr.Stephanie\u{0020}didn't\u{0020}lock\u{0020}her\u{0020}up,\u{0020}she\u{0020}was\u{0020}reluctant\u{0020}to\u{0020}show\u{0020}up\u{0020}in\u{0020}front\u{0020}of\u{0020}other\u{0020}people.\u{0020}Lily\u{0020}liked\u{0020}observing\u{0020}streets\u{0020}underneath\u{0020}from\u{0020}the\u{0020}ark's\u{0020}windows,\u{0020}because\u{0020}that\u{0020}brings\u{0020}up\u{0020}the\u{0020}memories\u{0020}of\u{0020}her\u{0020}life\u{0020}in\u{0020}Logan.\n\n\"Lily\"\u{0020}is\u{0020}just\u{0020}a\u{0020}callsign,\u{0020}Rebecca\u{0020}was\u{0020}her\u{0020}name.\u{0020}We\u{0020}call\u{0020}her\u{0020}by\u{0020}her\u{0020}callsign\u{0020}to\u{0020}differentiate\u{0020}between\u{0020}her\u{0020}human-self\u{0020}and\u{0020}Sin-self.\n\nThe\u{0020}Hydra\u{0020}squad\u{0020}is\u{0020}special\u{0020}because\u{0020}its\u{0020}members'\u{0020}gigantification\u{0020}is\u{0020}more\u{0020}like\u{0020}\"Sinification\".\u{0020}And\u{0020}without\u{0020}any\u{0020}doubt,\u{0020}Sins\u{0020}are\u{0020}humans'\u{0020}enemies.\n\nRebecca\u{0020}didn't\u{0020}want\u{0020}to\u{0020}become\u{0020}a\u{0020}Sin,\u{0020}and\u{0020}she\u{0020}didn't\u{0020}want\u{0020}to\u{0020}hurt\u{0020}humans.\u{0020}But\u{0020}sometimes,\u{0020}to\u{0020}protect\u{0020}the\u{0020}ones\u{0020}she\u{0020}want\u{0020}to\u{0020}protect,\u{0020}she\u{0020}has\u{0020}to\u{0020}give\u{0020}up\u{0020}her\u{0020}human-form,\u{0020}becomes\u{0020}\"Lily\",\u{0020}a\u{0020}Sin.", "0", "0", "0", "0", 10029, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[602902] = {602902, 500, "\u{0020}\u{0020}\u{0020}Rebecca\u{0020}was\u{0020}born\u{0020}in\u{0020}Logan,\u{0020}a\u{0020}city\u{0020}of\u{0020}Danube.\u{0020}She\u{0020}was\u{0020}abandoned\u{0020}by\u{0020}her\u{0020}parents\u{0020}at\u{0020}a\u{0020}very\u{0020}young\u{0020}age.\u{0020}They\u{0020}sent\u{0020}her\u{0020}to\u{0020}a\u{0020}laboratory\u{0020}of\u{0020}Aegis\u{0020}only\u{0020}to\u{0020}get\u{0020}a\u{0020}little\u{0020}life\u{0020}supplies\u{0020}in\u{0020}exchange.\n\nThere,\u{0020}she\u{0020}met\u{0020}Levi,\u{0020}who\u{0020}had\u{0020}a\u{0020}similar\u{0020}fate.\u{0020}Back\u{0020}then,\u{0020}Rebecca\u{0020}was\u{0020}3,\u{0020}Levi\u{0020}was\u{0020}5.\n\nRebecca\u{0020}and\u{0020}Levi\u{0020}were\u{0020}selected\u{0020}to\u{0020}participate\u{0020}in\u{0020}\"Operation\u{0020}Reborn\".\u{0020}To\u{0020}test\u{0020}the\u{0020}human\u{0020}body's\u{0020}compatibility\u{0020}with\u{0020}Nimbus,\u{0020}they\u{0020}underwent\u{0020}a\u{0020}series\u{0020}of\u{0020}brutal\u{0020}experiments.\u{0020}Lots\u{0020}of\u{0020}test\u{0020}subjects\u{0020}have\u{0020}died\u{0020}in\u{0020}these\u{0020}experiments,\u{0020}and\u{0020}fortunately,\u{0020}or\u{0020}rather\u{0020}say,\u{0020}unfortunately,\u{0020}Rebecca\u{0020}and\u{0020}Levi\u{0020}are\u{0020}the\u{0020}only\u{0020}survivors.\n\nThey\u{0020}were\u{0020}confined\u{0020}in\u{0020}this\u{0020}hellish\u{0020}life\u{0020}for\u{0020}3\u{0020}years,\u{0020}only\u{0020}to\u{0020}be\u{0020}rescued\u{0020}after\u{0020}Aegis\u{0020}stopped\u{0020}these\u{0020}inhumane\u{0020}experiments.\n\n\"Rescued\",\u{0020}what\u{0020}a\u{0020}brilliant\u{0020}word,\u{0020}perfectly\u{0020}fits\u{0020}the\u{0020}\"Savior\"\u{0020}image\u{0020}of\u{0020}Aegis.\n\nBut\u{0020}the\u{0020}truth\u{0020}was,\u{0020}perfunctorily,\u{0020}Rebecca\u{0020}and\u{0020}Levi\u{0020}were\u{0020}sent\u{0020}to\u{0020}a\u{0020}dismissed\u{0020}scientist\u{0020}of\u{0020}Aegis:\u{0020}Josephine\u{0020}Bernatskaya.\u{0020}She\u{0020}was\u{0020}the\u{0020}chief\u{0020}executive\u{0020}of\u{0020}\"Operation\u{0020}Reborn\".\n\nIn\u{0020}the\u{0020}following\u{0020}decade,\u{0020}Rebecca\u{0020}and\u{0020}Levi\u{0020}were\u{0020}raised\u{0020}by\u{0020}Josephine.\u{0020}Together,\u{0020}they\u{0020}managed\u{0020}a\u{0020}pet\u{0020}shop\u{0020}in\u{0020}Logan,\u{0020}and\u{0020}were\u{0020}having\u{0020}a\u{0020}peaceful\u{0020}life.\u{0020}But\u{0020}those\u{0020}experiments\u{0020}changed\u{0020}Rebecca's\u{0020}body\u{0020}permanently,\u{0020}and\u{0020}she\u{0020}often\u{0020}hears\u{0020}the\u{0020}voices\u{0020}of\u{0020}Sin,\u{0020}and\u{0020}was\u{0020}even\u{0020}close\u{0020}to\u{0020}becoming\u{0020}a\u{0020}Sin.\u{0020}Fortunately,\u{0020}the\u{0020}Navigator\u{0020}from\u{0020}Danube\u{0020}went\u{0020}to\u{0020}Logan,\u{0020}with\u{0020}his\u{0020}help,\u{0020}Rebecca\u{0020}restored\u{0020}her\u{0020}true\u{0020}self\u{0020}and\u{0020}humanity.\n\nLong\u{0020}after\u{0020}that,\u{0020}she\u{0020}was\u{0020}informed\u{0020}that\u{0020}\"Operation\u{0020}Reborn\"\u{0020}didn't\u{0020}stop\u{0020}a\u{0020}decade\u{0020}ago.\u{0020}Josephine\u{0020}continued\u{0020}this\u{0020}unethical\u{0020}experiment,\u{0020}she\u{0020}kept\u{0020}injecting\u{0020}medicines\u{0020}with\u{0020}relics\u{0020}from\u{0020}the\u{0020}cores\u{0020}of\u{0020}Major\u{0020}Sins\u{0020}to\u{0020}Rebecca\u{0020}and\u{0020}Levi,\u{0020}under\u{0020}the\u{0020}name\u{0020}of\u{0020}treatment.\n\nRebecca\u{0020}didn't\u{0020}become\u{0020}hysterical\u{0020}by\u{0020}the\u{0020}betrayal\u{0020}and\u{0020}deceptions\u{0020}of\u{0020}the\u{0020}last\u{0020}decade,\u{0020}because\u{0020}she\u{0020}finally\u{0020}had\u{0020}the\u{0020}one\u{0020}she\u{0020}can\u{0020}trust.", "0", "0", "0", "0", 10029, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[602903] = {602903, 1000, "\u{0020}\u{0020}Life\u{0020}aboard\u{0020}the\u{0020}ark\u{0020}is\u{0020}completely\u{0020}different\u{0020}from\u{0020}Logan\u{0020}and\u{0020}the\u{0020}lab,\u{0020}although\u{0020}all\u{0020}of\u{0020}them\u{0020}are\u{0020}under\u{0020}the\u{0020}administration\u{0020}of\u{0020}Aegis.\n\nAfter\u{0020}Dr.Stephanie\u{0020}received\u{0020}Rebecca\u{0020}and\u{0020}Levi,\u{0020}their\u{0020}\"real\"\u{0020}treatment\u{0020}was\u{0020}finally\u{0020}started.\u{0020}Needless\u{0020}to\u{0020}say,\u{0020}Dr.Stephanie\u{0020}is\u{0020}a\u{0020}genuine\u{0020}\"smartest\u{0020}brain\".\u{0020}Only\u{0020}after\u{0020}several\u{0020}months\u{0020}of\u{0020}treatment,\u{0020}mutations\u{0020}in\u{0020}Rebecca's\u{0020}were\u{0020}slowed\u{0020}down.\u{0020}Although\u{0020}it\u{0020}was\u{0020}impossible\u{0020}to\u{0020}de-Sinification,\u{0020}at\u{0020}least\u{0020}her\u{0020}situation\u{0020}won't\u{0020}deteriorate.\n\nMoreover,\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}Synesthesia,\u{0020}she\u{0020}can\u{0020}transform\u{0020}into\u{0020}Lily\u{0020}by\u{0020}her\u{0020}own\u{0020}will.\u{0020}Perhaps\u{0020}this\u{0020}was\u{0020}Stephanie's\u{0020}goal:\u{0020}let\u{0020}their\u{0020}Sinification\u{0020}help\u{0020}that\u{0020}navigator.", "0", "0", "0", "0", 10029, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[602904] = {602904, 2000, "\u{0020}\u{0020}Do\u{0020}you\u{0020}want\u{0020}to\u{0020}be\u{0020}surrounded\u{0020}by\u{0020}kittens?\n\nThe\u{0020}first\u{0020}one\u{0020}is\u{0020}a\u{0020}pinecess,\n\nShe's\u{0020}good\u{0020}at\u{0020}being\u{0020}flighty.\n\nThe\u{0020}second\u{0020}one\u{0020}is\u{0020}a\u{0020}Samurai,\n\nShe's\u{0020}a\u{0020}little\u{0020}bit\u{0020}solemn.\n\nThe\u{0020}third\u{0020}one\u{0020}is\u{0020}a\u{0020}Saint,\n\nShe\u{0020}sways\u{0020}her\u{0020}kindness.\n\nThe\u{0020}forth\u{0020}one\u{0020}is\u{0020}a\u{0020}warrior,\n\nShe\u{0020}is\u{0020}full\u{0020}of\u{0020}valor.\n\n...\n\nThe\u{0020}fifth\u{0020}one\u{0020}is\u{0020}lil…LILY!\n\nShe\u{0020}loves,\u{0020}SHE\u{0020}LOVES!", "0", "0", "0", "0", 10029, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
