[603001] = {603001, 100, "\u{0020}\u{0020}Farnese\u{0020}Lante,\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}\"Astray\u{0020}Blossom\"\u{0020}team,\u{0020}a\u{0020}student\u{0020}of\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}she\u{0020}is\u{0020}also\u{0020}the\u{0020}daughter\u{0020}of\u{0020}a\u{0020}prominent\u{0020}family\u{0020}in\u{0020}the\u{0020}northern\u{0020}Sahara\u{0020}and\u{0020}the\u{0020}Tuscany\u{0020}region.\u{0020}Whether\u{0020}in\u{0020}AEGIS\u{0020}or\u{0020}the\u{0020}academy,\u{0020}Farnese\u{0020}is\u{0020}an\u{0020}exceptional\u{0020}existence.\u{0020}Compared\u{0020}to\u{0020}the\u{0020}general\u{0020}rules\u{0020}in\u{0020}specific\u{0020}institutions\u{0020}or\u{0020}society,\u{0020}she\u{0020}gives\u{0020}priority\u{0020}to\u{0020}abiding\u{0020}by\u{0020}the\u{0020}rules\u{0020}of\u{0020}her\u{0020}own\u{0020}family\u{0020}gang.\u{0020}The\u{0020}conflicts\u{0020}between\u{0020}the\u{0020}rules\u{0020}of\u{0020}different\u{0020}systems\u{0020}have\u{0020}caused\u{0020}her\u{0020}some\u{0020}troubles\u{0020}in\u{0020}the\u{0020}academy\u{0020}she\u{0020}attends.\u{0020}And\u{0020}students\u{0020}like\u{0020}her,\u{0020}who\u{0020}have\u{0020}talents\u{0020}but\u{0020}are\u{0020}difficult\u{0020}to\u{0020}discipline,\u{0020}were\u{0020}integrated\u{0020}and\u{0020}formed\u{0020}into\u{0020}an\u{0020}internship\u{0020}team\u{0020}\"Astray\u{0020}Blossom\".\u{0020}This\u{0020}move\u{0020}is\u{0020}expected\u{0020}that\u{0020}the\u{0020}discipline\u{0020}in\u{0020}the\u{0020}formal\u{0020}driver\u{0020}army\u{0020}can\u{0020}be\u{0020}beneficial\u{0020}to\u{0020}them.\n\nIn\u{0020}this\u{0020}team,\u{0020}among\u{0020}several\u{0020}\"problem\u{0020}students\",\u{0020}there\u{0020}must\u{0020}be\u{0020}someone\u{0020}who\u{0020}can\u{0020}suppress\u{0020}other\u{0020}members\u{0020}as\u{0020}the\u{0020}team\u{0020}leader.\u{0020}Considering\u{0020}all\u{0020}aspects,\u{0020}Farnese\u{0020}is\u{0020}the\u{0020}most\u{0020}competent\u{0020}candidate\u{0020}for\u{0020}this\u{0020}duty.\u{0020}With\u{0020}her\u{0020}straightforward\u{0020}and\u{0020}righteous\u{0020}style\u{0020}of\u{0020}her\u{0020}family\u{0020}and\u{0020}her\u{0020}decisive\u{0020}way\u{0020}of\u{0020}doing\u{0020}things,\u{0020}she\u{0020}has\u{0020}gained\u{0020}a\u{0020}certain\u{0020}degree\u{0020}of\u{0020}trust\u{0020}from\u{0020}her\u{0020}teammates.\u{0020}However,\u{0020}whether\u{0020}her\u{0020}personal\u{0020}values\u{0020}will\u{0020}cause\u{0020}certain\u{0020}problems\u{0020}is\u{0020}a\u{0020}later\u{0020}story.", "0", "0", "0", "0", 10030, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[603002] = {603002, 500, "If\u{0020}judged\u{0020}by\u{0020}the\u{0020}standards\u{0020}of\u{0020}those\u{0020}large\u{0020}and\u{0020}small\u{0020}family\u{0020}gangs\u{0020}in\u{0020}Tuscany,\u{0020}Farnese\u{0020}is\u{0020}undoubtedly\u{0020}an\u{0020}outstanding\u{0020}cadre.\u{0020}She\u{0020}is\u{0020}calm\u{0020}and\u{0020}flexible\u{0020}in\u{0020}battles,\u{0020}decisive\u{0020}and\u{0020}courageous\u{0020}in\u{0020}actions,\u{0020}and\u{0020}even\u{0020}adopts\u{0020}some\u{0020}\"ruthless\u{0020}measures\"\u{0020}for\u{0020}victory.\u{0020}The\u{0020}upbringing\u{0020}environment\u{0020}and\u{0020}the\u{0020}way\u{0020}her\u{0020}family\u{0020}cultivated\u{0020}her\u{0020}are\u{0020}one\u{0020}of\u{0020}the\u{0020}factors\u{0020}causing\u{0020}these\u{0020}characteristics.\u{0020}And\u{0020}for\u{0020}the\u{0020}other\u{0020}reasons,\u{0020}perhaps\u{0020}it\u{0020}has\u{0020}to\u{0020}start\u{0020}from\u{0020}the\u{0020}big\u{0020}fire\u{0020}in\u{0020}the\u{0020}residence\u{0020}when\u{0020}she\u{0020}was\u{0020}still\u{0020}young.\n\nAt\u{0020}that\u{0020}time,\u{0020}although\u{0020}the\u{0020}Lante\u{0020}family\u{0020}had\u{0020}already\u{0020}taken\u{0020}charge\u{0020}of\u{0020}the\u{0020}local\u{0020}construction\u{0020}and\u{0020}landscaping\u{0020}industry,\u{0020}they\u{0020}had\u{0020}not\u{0020}yet\u{0020}reached\u{0020}the\u{0020}current\u{0020}level\u{0020}of\u{0020}influence.\u{0020}One\u{0020}night,\u{0020}a\u{0020}certain\u{0020}family\u{0020}among\u{0020}the\u{0020}main\u{0020}competitors\u{0020}suddenly\u{0020}launched\u{0020}an\u{0020}attack.\u{0020}The\u{0020}unexpected\u{0020}offensive\u{0020}caused\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}Lante\u{0020}family\u{0020}to\u{0020}suffer\u{0020}consecutive\u{0020}losses.\u{0020}Young\u{0020}Farnese\u{0020}was\u{0020}powerless\u{0020}to\u{0020}fight\u{0020}back.\u{0020}At\u{0020}that\u{0020}time,\u{0020}she\u{0020}was\u{0020}still\u{0020}being\u{0020}cultivated\u{0020}as\u{0020}the\u{0020}next\u{0020}advisor\u{0020}and\u{0020}had\u{0020}hardly\u{0020}received\u{0020}much\u{0020}combat\u{0020}training,\u{0020}and\u{0020}could\u{0020}hardly\u{0020}even\u{0020}hold\u{0020}a\u{0020}gun.\n\nHowever,\u{0020}Farnese\u{0020}planned\u{0020}a\u{0020}counterattack\u{0020}extremely\u{0020}calmly.\u{0020}With\u{0020}her\u{0020}rich\u{0020}architectural\u{0020}knowledge,\u{0020}she\u{0020}quietly\u{0020}guided\u{0020}the\u{0020}enemies\u{0020}to\u{0020}continuously\u{0020}attack\u{0020}the\u{0020}weak\u{0020}points\u{0020}of\u{0020}the\u{0020}house.\u{0020}Soon,\u{0020}the\u{0020}walls,\u{0020}ceilings,\u{0020}and\u{0020}marble\u{0020}columns\u{0020}collapsed\u{0020}one\u{0020}after\u{0020}another,\u{0020}blocking\u{0020}the\u{0020}enemies'\u{0020}advance\u{0020}and\u{0020}retreat\u{0020}directions\u{0020}for\u{0020}a\u{0020}while.\u{0020}Farnese\u{0020}knew\u{0020}that\u{0020}this\u{0020}delay\u{0020}was\u{0020}not\u{0020}a\u{0020}long-term\u{0020}solution,\u{0020}so\u{0020}she\u{0020}resolutely\u{0020}set\u{0020}fire\u{0020}to\u{0020}this\u{0020}garden\u{0020}she\u{0020}loved\u{0020}the\u{0020}most\u{0020}around\u{0020}the\u{0020}mansion,\u{0020}burning\u{0020}those\u{0020}delicate\u{0020}flowers,\u{0020}the\u{0020}invading\u{0020}enemies,\u{0020}and\u{0020}the\u{0020}remains\u{0020}of\u{0020}family\u{0020}members\u{0020}to\u{0020}ashes.\n\nThis\u{0020}victory\u{0020}made\u{0020}many\u{0020}people\u{0020}look\u{0020}at\u{0020}this\u{0020}young\u{0020}heiress\u{0020}with\u{0020}new\u{0020}eyes.\u{0020}However,\u{0020}the\u{0020}terrifying\u{0020}aspect\u{0020}behind\u{0020}her\u{0020}actions,\u{0020}the\u{0020}cold\u{0020}talent\u{0020}that\u{0020}could\u{0020}easily\u{0020}go\u{0020}astray\u{0020}with\u{0020}the\u{0020}slightest\u{0020}mistake,\u{0020}made\u{0020}the\u{0020}family\u{0020}leader\u{0020}afraid.\u{0020}She\u{0020}felt\u{0020}that\u{0020}she\u{0020}couldn't\u{0020}control\u{0020}this\u{0020}flame\u{0020}in\u{0020}the\u{0020}garden.\u{0020}There\u{0020}were\u{0020}all\u{0020}kinds\u{0020}of\u{0020}combustibles\u{0020}around.\u{0020}No\u{0020}matter\u{0020}how\u{0020}small\u{0020}the\u{0020}flame\u{0020}was,\u{0020}it\u{0020}could\u{0020}easily\u{0020}expand\u{0020}the\u{0020}fire\u{0020}to\u{0020}an\u{0020}uncontrollable\u{0020}extent.\u{0020}Therefore,\u{0020}the\u{0020}direction\u{0020}of\u{0020}Farnese's\u{0020}cultivation\u{0020}changed\u{0020}after\u{0020}this\u{0020}incident.\u{0020}She\u{0020}was\u{0020}no\u{0020}longer\u{0020}the\u{0020}successor\u{0020}of\u{0020}the\u{0020}advisor\u{0020}position\u{0020}but\u{0020}entered\u{0020}the\u{0020}Azure\u{0020}Academy\u{0020}in\u{0020}the\u{0020}Sahara\u{0020}region\u{0020}as\u{0020}the\u{0020}representative\u{0020}of\u{0020}the\u{0020}family\u{0020}and\u{0020}as\u{0020}a\u{0020}token\u{0020}of\u{0020}cooperation\u{0020}with\u{0020}the\u{0020}AEGIS\u{0020}military.", "0", "0", "0", "0", 10030, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[603003] = {603003, 1000, "\u{0020}\u{0020}In\u{0020}AEGIS,\u{0020}Farnese\u{0020}still\u{0020}likes\u{0020}to\u{0020}adopt\u{0020}sacrificial\u{0020}tactics\u{0020}in\u{0020}battles.\u{0020}For\u{0020}houses\u{0020}where\u{0020}the\u{0020}personnel\u{0020}have\u{0020}been\u{0020}evacuated\u{0020}from,\u{0020}she\u{0020}will\u{0020}not\u{0020}hesitate\u{0020}to\u{0020}use\u{0020}them\u{0020}as\u{0020}props,\u{0020}as\u{0020}straightforward\u{0020}as\u{0020}destroying\u{0020}her\u{0020}own\u{0020}mansion\u{0020}when\u{0020}she\u{0020}was\u{0020}young.\u{0020}This\u{0020}kind\u{0020}of\u{0020}behavior\u{0020}often\u{0020}leads\u{0020}to\u{0020}more\u{0020}facility\u{0020}damages\u{0020}caused\u{0020}by\u{0020}her\u{0020}in\u{0020}battles\u{0020}than\u{0020}the\u{0020}Sin.\u{0020}Fortunately,\u{0020}her\u{0020}family\u{0020}is\u{0020}wealthy\u{0020}enough\u{0020}to\u{0020}compensate\u{0020}for\u{0020}the\u{0020}losses.\n\nSince\u{0020}the\u{0020}Lante\u{0020}family\u{0020}is\u{0020}a\u{0020}construction\u{0020}industry\u{0020}giant,\u{0020}some\u{0020}people\u{0020}would\u{0020}guess\u{0020}that\u{0020}this\u{0020}is\u{0020}for\u{0020}the\u{0020}benefit\u{0020}of\u{0020}the\u{0020}family,\u{0020}while\u{0020}more\u{0020}experts\u{0020}in\u{0020}psychology\u{0020}do\u{0020}not\u{0020}think\u{0020}so.\u{0020}Anyway,\u{0020}Farnese's\u{0020}obvious\u{0020}boldness\u{0020}and\u{0020}extravagance\u{0020}have\u{0020}indeed\u{0020}made\u{0020}the\u{0020}delinquent\u{0020}girls\u{0020}among\u{0020}the\u{0020}team\u{0020}members\u{0020}more\u{0020}willing\u{0020}to\u{0020}follow\u{0020}this\u{0020}captain.\u{0020}Whether\u{0020}AEGIS\u{0020}has\u{0020}a\u{0020}planned\u{0020}indulgence\u{0020}or\u{0020}a\u{0020}pending\u{0020}approval\u{0020}of\u{0020}a\u{0020}restrictive\u{0020}plan\u{0020}for\u{0020}this\u{0020}is\u{0020}unknown.", "0", "0", "0", "0", 10030, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[603004] = {603004, 2000, "\u{0020}Among\u{0020}the\u{0020}well-arranged\u{0020}manors\u{0020}in\u{0020}Tuscany,\u{0020}she\u{0020}did\u{0020}not\u{0020}stint\u{0020}on\u{0020}her\u{0020}art\u{0020}skill,\n\nSow\u{0020}fragrance\u{0020}to\u{0020}every\u{0020}garden\u{0020}and\u{0020}bullets\u{0020}to\u{0020}every\u{0020}enemy;\n\nUnder\u{0020}the\u{0020}olive\u{0020}tree\u{0020}shade\u{0020}of\u{0020}Sahara\u{0020}College,\u{0020}the\u{0020}creed\u{0020}she\u{0020}adhered\u{0020}to\u{0020}has\u{0020}not\u{0020}been\u{0020}concealed.\n\nGain\u{0020}respect\u{0020}through\u{0020}means\u{0020}and\u{0020}strategies,\u{0020}and\u{0020}adhere\u{0020}to\u{0020}one's\u{0020}morality.\n\nAnd\u{0020}in\u{0020}the\u{0020}steel\u{0020}building\u{0020}of\u{0020}AEGIS,\u{0020}the\u{0020}girl's\u{0020}sharpness\u{0020}was\u{0020}somewhat\u{0020}restrained.\n\nShe\u{0020}only\u{0020}awaits\u{0020}to\u{0020}embrace\u{0020}the\u{0020}day\u{0020}of\u{0020}returning\u{0020}to\u{0020}her\u{0020}hometown\u{0020}together\u{0020}with\u{0020}the\u{0020}appreciated\u{0020}navigator.", "0", "0", "0", "0", 10030, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[603100] = {603100, 0, "【Name】Ophelia\n【B-Day】Oct.\u{0020}31\n【Compatability\u{0020}Rate】70％\n【Height】34m\n【Squad】Revelation\u{0020}Spring\n【Affiliation】Danube\u{0020}Branch\n【Interest】Play\u{0020}with\u{0020}small\u{0020}animals", "0", "0", "0", "0", 10031, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[603101] = {603101, 100, "Ophelia\u{0020}is\u{0020}a\u{0020}driver\u{0020}with\u{0020}the\u{0020}temperament\u{0020}of\u{0020}an\u{0020}ordinary\u{0020}peasant\u{0020}girl.\u{0020}Although\u{0020}she\u{0020}also\u{0020}serves\u{0020}as\u{0020}a\u{0020}church\u{0020}knight\u{0020}of\u{0020}the\u{0020}Holy\u{0020}Church.\u{0020}However,\u{0020}on\u{0020}her,\u{0020}it\u{0020}is\u{0020}not\u{0020}easy\u{0020}to\u{0020}see\u{0020}the\u{0020}heroic\u{0020}spirit,\u{0020}solemnity,\u{0020}sacredness\u{0020}and\u{0020}piety\u{0020}of\u{0020}her\u{0020}fellow\u{0020}knights.\u{0020}Her\u{0020}character\u{0020}still\u{0020}retains\u{0020}the\u{0020}simplicity\u{0020}and\u{0020}shyness\u{0020}of\u{0020}a\u{0020}rural\u{0020}girl.\u{0020}In\u{0020}fact,\u{0020}the\u{0020}reason\u{0020}why\u{0020}Ophelia\u{0020}became\u{0020}a\u{0020}church\u{0020}knight\u{0020}was\u{0020}more\u{0020}out\u{0020}of\u{0020}the\u{0020}simple\u{0020}wish\u{0020}to\u{0020}do\u{0020}something\u{0020}for\u{0020}her\u{0020}hometown.\u{0020}\u{0020}\u{0020}Whether\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}or\u{0020}a\u{0020}church\u{0020}knight,\u{0020}it\u{0020}is\u{0020}because\u{0020}Ophelia\u{0020}herself\u{0020}indeed\u{0020}has\u{0020}sufficient\u{0020}qualifications\u{0020}.But\u{0020}her\u{0020}self-perception\u{0020}still\u{0020}remains\u{0020}at\u{0020}\"a\u{0020}rural\u{0020}girl\u{0020}who\u{0020}likes\u{0020}to\u{0020}take\u{0020}walks\u{0020}along\u{0020}the\u{0020}ridges\u{0020}of\u{0020}fields\u{0020}and\u{0020}pick\u{0020}wild\u{0020}fruits\u{0020}in\u{0020}the\u{0020}mountains\u{0020}and\u{0020}forests\",\u{0020}her\u{0020}lack\u{0020}of\u{0020}confidence\u{0020}and\u{0020}inherent\u{0020}timidity\u{0020}make\u{0020}her\u{0020}more\u{0020}inclined\u{0020}to\u{0020}dodge\u{0020}even\u{0020}insignificant\u{0020}attacks\u{0020}during\u{0020}battles,\u{0020}and\u{0020}once\u{0020}pushed\u{0020}too\u{0020}hard,\u{0020}she\u{0020}will\u{0020}frantically\u{0020}counterattack\u{0020}hysterically.\u{0020}To\u{0020}make\u{0020}a\u{0020}metaphor,\u{0020}it\u{0020}is\u{0020}just\u{0020}like\u{0020}a\u{0020}small\u{0020}insecure\u{0020}field\u{0020}animal.", "0", "0", "0", "0", 10031, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[603102] = {603102, 500, "Naturally,\u{0020}such\u{0020}an\u{0020}ordinary\u{0020}girl\u{0020}actually\u{0020}prefers\u{0020}to\u{0020}use\u{0020}handy\u{0020}and\u{0020}conventional\u{0020}weapons\u{0020}like\u{0020}swords\u{0020}and\u{0020}shields.\u{0020}However,\u{0020}Mira,\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Order\u{0020}of\u{0020}the\u{0020}Spring,\u{0020}is\u{0020}a\u{0020}person\u{0020}with\u{0020}a\u{0020}rather\u{0020}flamboyant\u{0020}and\u{0020}aggressive\u{0020}style\u{0020}of\u{0020}doing\u{0020}things.\u{0020}She\u{0020}strongly\u{0020}suggests\u{0020}that\u{0020}Ophelia\u{0020}uses\u{0020}a\u{0020}waterwheel\u{0020}with\u{0020}a\u{0020}more\u{0020}unique\u{0020}shape\u{0020}and\u{0020}good\u{0020}publicity\u{0020}effect\u{0020}as\u{0020}a\u{0020}weapon.\u{0020}Because\u{0020}Ophelia\u{0020}comes\u{0020}from\u{0020}a\u{0020}remote\u{0020}village\u{0020}with\u{0020}many\u{0020}rivers\u{0020}and\u{0020}waterwheels,\u{0020}the\u{0020}waterwheel\u{0020}is\u{0020}the\u{0020}greatest\u{0020}symbol\u{0020}of\u{0020}her\u{0020}hometown,\u{0020}so\u{0020}much\u{0020}so\u{0020}that\u{0020}the\u{0020}village\u{0020}itself\u{0020}is\u{0020}named\u{0020}Waterwheel\u{0020}Village.\u{0020}\u{0020}Ophelia\u{0020}was\u{0020}born\u{0020}and\u{0020}grew\u{0020}up\u{0020}in\u{0020}Waterwheel\u{0020}Village.\u{0020}This\u{0020}rich\u{0020}and\u{0020}simple\u{0020}land\u{0020}in\u{0020}the\u{0020}countryside\u{0020}of\u{0020}Danube\u{0020}provided\u{0020}her\u{0020}with\u{0020}all\u{0020}the\u{0020}nourishment\u{0020}needed\u{0020}to\u{0020}become\u{0020}a\u{0020}kind\u{0020}and\u{0020}honest\u{0020}person.\u{0020}The\u{0020}residents\u{0020}here\u{0020}are\u{0020}modern\u{0020}and\u{0020}open-minded\u{0020}enough\u{0020}in\u{0020}their\u{0020}thinking.\u{0020}However,\u{0020}compared\u{0020}to\u{0020}an\u{0020}overly\u{0020}urbanized\u{0020}environment,\u{0020}they\u{0020}prefer\u{0020}the\u{0020}current\u{0020}original\u{0020}nature.\u{0020}The\u{0020}mountains,\u{0020}rivers\u{0020}and\u{0020}woodlands\u{0020}here\u{0020}undoubtedly\u{0020}enabled\u{0020}Ophelia\u{0020}to\u{0020}have\u{0020}a\u{0020}lively\u{0020}and\u{0020}happy\u{0020}childhood.\u{0020}\u{0020}\u{0020}However,\u{0020}it\u{0020}is\u{0020}indeed\u{0020}a\u{0020}fact\u{0020}that\u{0020}such\u{0020}rather\u{0020}traditional\u{0020}villages\u{0020}are\u{0020}disappearing\u{0020}quietly\u{0020}and\u{0020}unknown\u{0020}to\u{0020}many.\u{0020}Due\u{0020}to\u{0020}insufficient\u{0020}development,\u{0020}Waterwheel\u{0020}Village,\u{0020}like\u{0020}some\u{0020}other\u{0020}equally\u{0020}unknown\u{0020}settlements,\u{0020}has\u{0020}become\u{0020}less\u{0020}able\u{0020}to\u{0020}retain\u{0020}young\u{0020}people.\u{0020}After\u{0020}Ophelia\u{0020}deeply\u{0020}understood\u{0020}this\u{0020}point,\u{0020}she\u{0020}hoped\u{0020}that\u{0020}she\u{0020}could\u{0020}do\u{0020}something\u{0020}for\u{0020}the\u{0020}gradually\u{0020}deserted\u{0020}village\u{0020}to\u{0020}make\u{0020}it\u{0020}more\u{0020}prosperous\u{0020}and\u{0020}lively.\u{0020}\u{0020}\u{0020}The\u{0020}only\u{0020}relatively\u{0020}large\u{0020}institution\u{0020}outside\u{0020}the\u{0020}village\u{0020}of\u{0020}Waterwheel\u{0020}Village\u{0020}is\u{0020}the\u{0020}Holy\u{0020}Church,\u{0020}which\u{0020}is\u{0020}also\u{0020}the\u{0020}place\u{0020}where\u{0020}Ophelia\u{0020}liked\u{0020}to\u{0020}play\u{0020}since\u{0020}childhood\u{0020}and\u{0020}often\u{0020}went\u{0020}to\u{0020}help\u{0020}when\u{0020}she\u{0020}grew\u{0020}up.\u{0020}Just\u{0020}when\u{0020}the\u{0020}church\u{0020}of\u{0020}the\u{0020}Danube\u{0020}diocese\u{0020}planned\u{0020}to\u{0020}cooperate\u{0020}with\u{0020}AEGIS\u{0020}and\u{0020}form\u{0020}a\u{0020}driver\u{0020}team\u{0020}\"Order\u{0020}of\u{0020}the\u{0020}Spring\",\u{0020}Ophelia\u{0020}gathered\u{0020}her\u{0020}courage\u{0020}to\u{0020}try\u{0020}under\u{0020}the\u{0020}suggestion\u{0020}of\u{0020}the\u{0020}local\u{0020}clergy.\u{0020}Then,\u{0020}after\u{0020}numerous\u{0020}screenings,\u{0020}she\u{0020}finally\u{0020}passed\u{0020}the\u{0020}test\u{0020}as\u{0020}she\u{0020}wished\u{0020}and\u{0020}was\u{0020}able\u{0020}to\u{0020}join\u{0020}the\u{0020}\"Order\u{0020}of\u{0020}the\u{0020}Spring\"\u{0020}and\u{0020}become\u{0020}a\u{0020}driver\u{0020}and\u{0020}a\u{0020}church\u{0020}knight.\u{0020}\u{0020}\u{0020}The\u{0020}connection\u{0020}between\u{0020}Ophelia\u{0020}and\u{0020}the\u{0020}Holy\u{0020}Church\u{0020}is\u{0020}actually\u{0020}only\u{0020}to\u{0020}this\u{0020}extent.\u{0020}She\u{0020}was\u{0020}almost\u{0020}an\u{0020}exception\u{0020}to\u{0020}join\u{0020}the\u{0020}church\u{0020}temporarily,\u{0020}so\u{0020}she\u{0020}is\u{0020}very\u{0020}lacking\u{0020}in\u{0020}the\u{0020}stable\u{0020}and\u{0020}generous\u{0020}traits\u{0020}of\u{0020}other\u{0020}clergy.\u{0020}Mira,\u{0020}the\u{0020}bishop\u{0020}of\u{0020}the\u{0020}Danube\u{0020}diocese,\u{0020}highly\u{0020}appreciated\u{0020}Ophelia's\u{0020}character\u{0020}and\u{0020}vision.\u{0020}So,\u{0020}she\u{0020}simply\u{0020}proposed\u{0020}to\u{0020}her\u{0020}the\u{0020}suggestion\u{0020}of\u{0020}using\u{0020}a\u{0020}waterwheel\u{0020}as\u{0020}a\u{0020}weapon.\u{0020}This\u{0020}could\u{0020}not\u{0020}only\u{0020}make\u{0020}the\u{0020}Order\u{0020}of\u{0020}the\u{0020}Spring\u{0020}more\u{0020}noticeable\u{0020}but\u{0020}also\u{0020}be\u{0020}a\u{0020}good\u{0020}publicity\u{0020}for\u{0020}Ophelia's\u{0020}hometown.\u{0020}\u{0020}\u{0020}Although\u{0020}somewhat\u{0020}embarrassed,\u{0020}considering\u{0020}her\u{0020}own\u{0020}heart,\u{0020}considering\u{0020}the\u{0020}villagers,\u{0020}the\u{0020}small\u{0020}animals\u{0020}in\u{0020}the\u{0020}fields,\u{0020}the\u{0020}tree\u{0020}fruits\u{0020}and\u{0020}fresh\u{0020}flowers\u{0020}in\u{0020}the\u{0020}mountains\u{0020}-\u{0020}the\u{0020}beautiful\u{0020}village\u{0020}that\u{0020}accompanied\u{0020}her\u{0020}throughout\u{0020}her\u{0020}entire\u{0020}childhood,\u{0020}Ophelia\u{0020}still\u{0020}chose\u{0020}to\u{0020}pick\u{0020}up\u{0020}the\u{0020}heavy\u{0020}weapon\u{0020}in\u{0020}the\u{0020}shape\u{0020}of\u{0020}a\u{0020}waterwheel.", "0", "0", "0", "0", 10031, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[603103] = {603103, 1000, "Drivers\u{0020}from\u{0020}rural\u{0020}areas\u{0020}are\u{0020}not\u{0020}actually\u{0020}very\u{0020}rare,\u{0020}but\u{0020}at\u{0020}least\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}where\u{0020}there\u{0020}are\u{0020}more\u{0020}nobles,\u{0020}Ophelia\u{0020}always\u{0020}feels\u{0020}some\u{0020}pressure.\u{0020}It\u{0020}is\u{0020}not\u{0020}that\u{0020}others\u{0020}discriminated\u{0020}against\u{0020}or\u{0020}alienated\u{0020}her,\u{0020}but\u{0020}there\u{0020}were\u{0020}certain\u{0020}differences\u{0020}in\u{0020}living\u{0020}habits\u{0020}between\u{0020}them.\u{0020}The\u{0020}most\u{0020}obvious\u{0020}one\u{0020}was\u{0020}that\u{0020}when\u{0020}other\u{0020}driver\u{0020}girls\u{0020}invited\u{0020}Ophelia\u{0020}to\u{0020}watch\u{0020}those\u{0020}rather\u{0020}avant-garde\u{0020}fashion\u{0020}art\u{0020}shows,\u{0020}she\u{0020}would\u{0020}always\u{0020}blush\u{0020}and\u{0020}hurriedly\u{0020}refuse.\u{0020}\u{0020}\u{0020}It\u{0020}is\u{0020}the\u{0020}serene\u{0020}and\u{0020}solemn\u{0020}atmosphere\u{0020}in\u{0020}the\u{0020}church\u{0020}that\u{0020}can\u{0020}make\u{0020}Ophelia\u{0020}feel\u{0020}more\u{0020}relaxed.\u{0020}Perhaps\u{0020}she\u{0020}doesn't\u{0020}understand\u{0020}what\u{0020}is\u{0020}sacred,\u{0020}but\u{0020}here,\u{0020}she\u{0020}can\u{0020}indeed\u{0020}temporarily\u{0020}escape\u{0020}from\u{0020}the\u{0020}busy\u{0020}and\u{0020}noisy\u{0020}urban\u{0020}environment\u{0020}and\u{0020}take\u{0020}a\u{0020}break.\u{0020}Of\u{0020}course,\u{0020}it\u{0020}might\u{0020}be\u{0020}even\u{0020}better\u{0020}for\u{0020}her\u{0020}if\u{0020}the\u{0020}diocesan\u{0020}bishop\u{0020}-\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Order\u{0020}of\u{0020}the\u{0020}Spring,\u{0020}Mira\u{0020}-\u{0020}didn't\u{0020}often\u{0020}pester\u{0020}Ophelia\u{0020}to\u{0020}change\u{0020}her\u{0020}into\u{0020}a\u{0020}more\u{0020}avant-garde\u{0020}and\u{0020}bold\u{0020}nun's\u{0020}attire.", "0", "0", "0", "0", 10031, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
