[603201] = {603201, 100, "Dr.\u{0020}Christina,\u{0020}born\u{0020}in\u{0020}Katya,\u{0020}has\u{0020}been\u{0020}serving\u{0020}in\u{0020}the\u{0020}Katya\u{0020}Branch\u{0020}since\u{0020}adulthood\u{0020}-\u{0020}as\u{0020}a\u{0020}driver.\u{0020}However,\u{0020}due\u{0020}to\u{0020}its\u{0020}overly\u{0020}excellent\u{0020}scientific\u{0020}research\u{0020}ability,\u{0020}it\u{0020}was\u{0020}specially\u{0020}permitted\u{0020}to\u{0020}retire\u{0020}from\u{0020}Frontier\u{0020}and\u{0020}transfer\u{0020}to\u{0020}the\u{0020}Science\u{0020}Department.As\u{0020}an\u{0020}amateur\u{0020}without\u{0020}a\u{0020}scientific\u{0020}background,\u{0020}Christina\u{0020}relearned\u{0020}the\u{0020}basic\u{0020}knowledge\u{0020}system\u{0020}of\u{0020}the\u{0020}existing\u{0020}norms\u{0020}in\u{0020}the\u{0020}Science\u{0020}Department\u{0020}and\u{0020}then\u{0020}studied\u{0020}at\u{0020}various\u{0020}Arks.\n\nBecause\u{0020}of\u{0020}her\u{0020}unusual\u{0020}thirst\u{0020}and\u{0020}efforts\u{0020}for\u{0020}\"knowledge\",\u{0020}even\u{0020}as\u{0020}an\u{0020}amateur,\u{0020}she\u{0020}was\u{0020}quickly\u{0020}accepted\u{0020}by\u{0020}the\u{0020}Science\u{0020}Department\u{0020}and\u{0020}became\u{0020}familiar\u{0020}with\u{0020}her\u{0020}colleagues\u{0020}in\u{0020}the\u{0020}department\u{0020}-\u{0020}as\u{0020}\"strange\u{0020}guys\u{0020}exploring\u{0020}the\u{0020}world\",\u{0020}they\u{0020}seemed\u{0020}to\u{0020}have\u{0020}many\u{0020}common\u{0020}topics.\u{0020}Among\u{0020}them\u{0020}were\u{0020}Dr.\u{0020}Hong,\u{0020}who\u{0020}was\u{0020}later\u{0020}called\u{0020}\"Dr.\u{0020}Kurenai\u{0020}\",\u{0020}and\u{0020}that\u{0020}Dr.\u{0020}Alvitr.\u{0020}\u{0020}", "0", "0", "0", "0", 10032, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[603202] = {603202, 500, "The\u{0020}\"ace\"\u{0020}driver\u{0020}Christina,\u{0020}who\u{0020}was\u{0020}at\u{0020}the\u{0020}peak\u{0020}of\u{0020}her\u{0020}career,\u{0020}retired,\u{0020}which\u{0020}became\u{0020}a\u{0020}regret\u{0020}for\u{0020}many\u{0020}Katya\u{0020}people.\u{0020}The\u{0020}reason\u{0020}she\u{0020}claimed\u{0020}to\u{0020}the\u{0020}outside\u{0020}world\u{0020}was\u{0020}that\u{0020}she\u{0020}suffered\u{0020}from\u{0020}a\u{0020}battlefield-related\u{0020}mental\u{0020}illness.\u{0020}Meanwhile,\u{0020}the\u{0020}science\u{0020}department\u{0020}has\u{0020}an\u{0020}\"intern\"\u{0020}named\u{0020}Christina.\n\nHer\u{0020}retirement,\u{0020}from\u{0020}the\u{0020}current\u{0020}perspective,\u{0020}is\u{0020}definitely\u{0020}the\u{0020}most\u{0020}correct\u{0020}thing.\u{0020}But\u{0020}it's\u{0020}hard\u{0020}to\u{0020}imagine\u{0020}what\u{0020}kind\u{0020}of\u{0020}mood\u{0020}Katya\u{0020}Branch\u{0020}was\u{0020}in\u{0020}at\u{0020}that\u{0020}time\u{0020}and\u{0020}how\u{0020}much\u{0020}confrontation\u{0020}was\u{0020}behind\u{0020}the\u{0020}\"retirement\".\u{0020}This\u{0020}matter\u{0020}was\u{0020}not\u{0020}recorded\u{0020}in\u{0020}the\u{0020}files.\u{0020}Of\u{0020}course,\u{0020}the\u{0020}relevant\u{0020}insiders\u{0020}also\u{0020}remained\u{0020}tight-lipped.\u{0020}Only\u{0020}it\u{0020}is\u{0020}known\u{0020}that\u{0020}there\u{0020}were\u{0020}indeed\u{0020}obstructors\u{0020}in\u{0020}the\u{0020}entire\u{0020}incident,\u{0020}and\u{0020}ultimately\u{0020}Christina\u{0020}was\u{0020}victorious.\u{0020}Judging\u{0020}from\u{0020}the\u{0020}remaining\u{0020}records,\u{0020}perhaps\u{0020}Lonis\u{0020}and\u{0020}Christina\u{0020}became\u{0020}acquainted\u{0020}during\u{0020}that\u{0020}time.\n\nAny\u{0020}doctor\u{0020}is\u{0020}a\u{0020}person\u{0020}of\u{0020}firm\u{0020}will,\u{0020}with\u{0020}a\u{0020}powerful\u{0020}inner\u{0020}drive\u{0020}in\u{0020}their\u{0020}heart.\u{0020}They\u{0020}know\u{0020}why\u{0020}they\u{0020}are\u{0020}striving,\u{0020}understand\u{0020}that\u{0020}every\u{0020}effort\u{0020}they\u{0020}make\u{0020}is\u{0020}a\u{0020}solid\u{0020}step\u{0020}towards\u{0020}the\u{0020}goal,\u{0020}will\u{0020}not\u{0020}be\u{0020}easily\u{0020}defeated\u{0020}by\u{0020}difficulties,\u{0020}and\u{0020}will\u{0020}not\u{0020}easily\u{0020}give\u{0020}up\u{0020}their\u{0020}goal.\u{0020}Unless\u{0020}-\u{0020}there\u{0020}is\u{0020}a\u{0020}fatal\u{0020}temptation.\u{0020}Christina\u{0020}always\u{0020}thought\u{0020}that\u{0020}she\u{0020}would\u{0020}continue\u{0020}to\u{0020}fight\u{0020}for\u{0020}humanity\u{0020}and\u{0020}her\u{0020}own\u{0020}goals\u{0020}in\u{0020}the\u{0020}science\u{0020}department\u{0020}until\u{0020}an\u{0020}\"abnormal\u{0020}driver\",\u{0020}\"superpowered\u{0020}individual\"\u{0020}Tsukumo\u{0020}Tamaki,\u{0020}appeared\u{0020}in\u{0020}her\u{0020}line\u{0020}of\u{0020}sight.\n\nHaving\u{0020}a\u{0020}firm\u{0020}goal\u{0020}also\u{0020}means\u{0020}that\u{0020}doctors\u{0020}are\u{0020}willing\u{0020}to\u{0020}lower\u{0020}their\u{0020}bottom\u{0020}line\u{0020}for\u{0020}their\u{0020}goals\u{0020}-\u{0020}not\u{0020}every\u{0020}doctor\u{0020}has\u{0020}a\u{0020}lofty\u{0020}moral\u{0020}standard.\u{0020}This\u{0020}time,\u{0020}Christina\u{0020}decided\u{0020}to\u{0020}slightly\u{0020}violate\u{0020}the\u{0020}rules\u{0020}of\u{0020}the\u{0020}experimenters\u{0020}for\u{0020}Tsukumo\u{0020}Tamaki.\u{0020}She\u{0020}became\u{0020}a\u{0020}driver\u{0020}again\u{0020}and\u{0020}was\u{0020}prepared\u{0020}to\u{0020}apply\u{0020}to\u{0020}be\u{0020}Tsukumo\u{0020}Tamaki's\u{0020}mentor\u{0020}with\u{0020}an\u{0020}extraordinary\u{0020}resume.\u{0020}The\u{0020}former\u{0020}ace\u{0020}driver,\u{0020}she,\u{0020}was\u{0020}going\u{0020}to\u{0020}guide\u{0020}Tsukumo\u{0020}Tamaki\u{0020}to\u{0020}become\u{0020}a\u{0020}competent\u{0020}navigator\u{0020}-\u{0020}in\u{0020}order\u{0020}to\u{0020}obtain\u{0020}the\u{0020}help\u{0020}and\