[603302] = {603302, 500, "\u{0020}\u{0020}[The\u{0020}following\u{0020}information\u{0020}is\u{0020}supplemented\u{0020}from\u{0020}the\u{0020}investigation\u{0020}department\u{0020}of\u{0020}Inca\u{0020}Branch.]\u{0020}\n\nThe\u{0020}earliest\u{0020}record\u{0020}that\u{0020}could\u{0020}be\u{0020}found\u{0020}was\u{0020}that\u{0020}she\u{0020}was\u{0020}abandoned\u{0020}at\u{0020}the\u{0020}gate\u{0020}of\u{0020}the\u{0020}orphanage\u{0020}when\u{0020}she\u{0020}was\u{0020}seven\u{0020}months\u{0020}old.\u{0020}Her\u{0020}biological\u{0020}parents\u{0020}are\u{0020}unknown,\u{0020}and\u{0020}there\u{0020}is\u{0020}no\u{0020}matching\u{0020}sample\u{0020}in\u{0020}the\u{0020}Inca\u{0020}blood\u{0020}bank.\u{0020}It\u{0020}should\u{0020}be\u{0020}a\u{0020}foreign\u{0020}population.\n\nAfter\u{0020}Sin's\u{0020}large-scale\u{0020}invasion,\u{0020}the\u{0020}capital\u{0020}chain\u{0020}of\u{0020}the\u{0020}Daybreak\u{0020}Love\u{0020}Association\u{0020}broke,\u{0020}so\u{0020}the\u{0020}children\u{0020}accommodated\u{0020}in\u{0020}its\u{0020}subordinate\u{0020}institutions\u{0020}were\u{0020}arranged\u{0020}to\u{0020}participate\u{0020}in\u{0020}the\u{0020}driver\u{0020}test\u{0020}in\u{0020}exchange\u{0020}for\u{0020}financing.\u{0020}[S52]\u{0020}\u{0020}was\u{0020}not\u{0020}among\u{0020}the\u{0020}first\u{0020}batch\u{0020}of\u{0020}exchanges.\u{0020}In\u{0020}the\u{0020}submitted\u{0020}materials\u{0020}at\u{0020}that\u{0020}time,\u{0020}[S52]\u{0020}\u{0020}was\u{0020}noted\u{0020}as\u{0020}\"presumed\u{0020}dead\".\n\nIn\u{0020}the\u{0020}second\u{0020}year\u{0020}of\u{0020}Sin's\u{0020}invasion,\u{0020}a\u{0020}large-scale\u{0020}anti-AEGIS\u{0020}protest\u{0020}march\u{0020}occurred\u{0020}in\u{0020}the\u{0020}territory\u{0020}of\u{0020}Kyushu,\u{0020}causing\u{0020}extremely\u{0020}adverse\u{0020}effects.\u{0020}The\u{0020}headquarters\u{0020}sent\u{0020}people\u{0020}to\u{0020}suppress\u{0020}and\u{0020}investigate.\u{0020}After\u{0020}many\u{0020}discussions,\u{0020}it\u{0020}was\u{0020}finally\u{0020}decided\u{0020}to\u{0020}escort\u{0020}[S52]\u{0020},\u{0020}the\u{0020}organizer,\u{0020}back\u{0020}to\u{0020}Inca\u{0020}for\u{0020}disposal.\u{0020}It\u{0020}has\u{0020}still\u{0020}not\u{0020}been\u{0020}possible\u{0020}to\u{0020}find\u{0020}out\u{0020}how\u{0020}she\u{0020}wandered\u{0020}alone\u{0020}in\u{0020}the\u{0020}past.\n\nPs.\u{0020}He\u{0020}had\u{0020}questioned\u{0020}the\u{0020}parties,\u{0020}but\u{0020}failed\u{0020}to\u{0020}get\u{0020}any\u{0020}effective\u{0020}feedback.\u{0020}On\u{0020}the\u{0020}contrary,\u{0020}several\u{0020}interrogators\u{0020}had\u{0020}the\u{0020}idea\u{0020}of\u{0020}resisting\u{0020}AEGIS\u{0020}under\u{0020}the\u{0020}guidance\u{0020}of\u{0020}[S52]\u{0020}.\u{0020}Fortunately,\u{0020}they\u{0020}all\u{0020}received\u{0020}sufficient\u{0020}psychological\u{0020}treatment\u{0020}in\u{0020}time\u{0020}without\u{0020}serious\u{0020}consequences.\n\nFrom\u{0020}the\u{0020}files\u{0020}submitted\u{0020}and\u{0020}the\u{0020}only\u{0020}ones\u{0020}left\u{0020}after\u{0020}the\u{0020}disaster,\u{0020}it\u{0020}can\u{0020}be\u{0020}inferred\u{0020}that\u{0020}[S52]\u{0020}\u{0020}participated\u{0020}in\u{0020}the\u{0020}human\u{0020}nature\u{0020}experiment\u{0020}project\u{0020}under\u{0020}extreme\u{0020}speech.\n\nThe\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}[S52]\u{0020}\u{0020}is\u{0020}not\u{0020}high.\u{0020}Among\u{0020}all\u{0020}the\u{0020}qualified\u{0020}children\u{0020}provided\u{0020}by\u{0020}Daybreak\u{0020}for\u{0020}the\u{0020}test,\u{0020}it\u{0020}ranks\u{0020}moderately\u{0020}low.\u{0020}However,\u{0020}since\u{0020}most\u{0020}of\u{0020}the\u{0020}test\u{0020}samples\u{0020}have\u{0020}communication\u{0020}disorders\u{0020}and\u{0020}indiscriminate\u{0020}aggressiveness,\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}requirements\u{0020}could\u{0020}only\u{0020}be\u{0020}relaxed\u{0020}eventually,\u{0020}and\u{0020}[S52]\u{0020},\u{0020}which\u{0020}would\u{0020}not\u{0020}exhibit\u{0020}any\u{0020}aggressive\u{0020}behavior\u{0020}after\u{0020}magnification,\u{0020}was\u{0020}selected\u{0020}to\u{0020}join\u{0020}the\u{0020}team.\n\nCourant,\u{0020}this\u{0020}name\u{0020}was\u{0020}given\u{0020}to\u{0020}her\u{0020}by\u{0020}the\u{0020}team\u{0020}leader\u{0020}after\u{0020}she\u{0020}was\u{0020}selected\u{0020}into\u{0020}the\u{0020}Daybreak\u{0020}team.\n\nHowever,\u{0020}compared\u{0020}to\u{0020}this\u{0020}name\u{0020}full\u{0020}of\u{0020}bad\u{0020}taste,\u{0020}she\u{0020}is\u{0020}more\u{0020}familiar\u{0020}with\u{0020}[S52]\u{0020}\u{0020}and\u{0020}is\u{0020}more\u{0020}likely\u{0020}to\u{0020}respond.\u{0020}Therefore,\u{0020}in\u{0020}the\u{0020}research\u{0020}institute,\u{0020}the\u{0020}staff\u{0020}generally\u{0020}call\u{0020}her\u{0020}by\u{0020}the\u{0020}number.\u{0020}", "0", "0", "0", "0", 10033, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
