[603401] = {603401, 100, "\u{0020}\u{0020}Prisoner——As\u{0020}the\u{0020}name\u{0020}suggests,\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}team\u{0020}are\u{0020}all\u{0020}prisoners\u{0020}who\u{0020}have\u{0020}committed\u{0020}major\u{0020}crimes\u{0020}in\u{0020}the\u{0020}past\u{0020}and\u{0020}are\u{0020}now\u{0020}serving\u{0020}as\u{0020}a\u{0020}form\u{0020}of\u{0020}atonement.\n\nLoki\u{0020}is\u{0020}one\u{0020}of\u{0020}them.\n\nUnlike\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}Prisoners,\u{0020}Loki\u{0020}spends\u{0020}most\u{0020}of\u{0020}her\u{0020}time\u{0020}on\u{0020}external\u{0020}tasks\u{0020}-\u{0020}in\u{0020}other\u{0020}words,\u{0020}she\u{0020}has\u{0020}more\u{0020}\"freedom\"\u{0020}compared\u{0020}to\u{0020}others\u{0020}in\u{0020}the\u{0020}same\u{0020}situation.\n\nHowever,\u{0020}this\u{0020}freedom\u{0020}comes\u{0020}at\u{0020}a\u{0020}price.\n\nAs\u{0020}an\u{0020}exchange\u{0020}for\u{0020}not\u{0020}being\u{0020}confined\u{0020}in\u{0020}her\u{0020}room\u{0020}like\u{0020}other\u{0020}Prisoners,\u{0020}she\u{0020}must\u{0020}constantly\u{0020}and\u{0020}at\u{0020}all\u{0020}times\u{0020}provide\u{0020}the\u{0020}information\u{0020}they\u{0020}need\u{0020}for\u{0020}AEGIS\u{0020}-\u{0020}precisely\u{0020}speaking,\u{0020}provide\u{0020}the\u{0020}information\u{0020}Stephanie\u{0020}needs.\n\nAs\u{0020}long\u{0020}as\u{0020}it\u{0020}is\u{0020}Stephanie's\u{0020}order,\u{0020}even\u{0020}if\u{0020}it\u{0020}is\u{0020}on\u{0020}the\u{0020}other\u{0020}side\u{0020}of\u{0020}the\u{0020}earth,\u{0020}even\u{0020}if\u{0020}it\u{0020}is\u{0020}a\u{0020}heinous\u{0020}place,\u{0020}she\u{0020}must\u{0020}rush\u{0020}to\u{0020}the\u{0020}scene\u{0020}and\u{0020}serve\u{0020}Stephanie.\n\nThis\u{0020}is\u{0020}her\u{0020}freedom,\u{0020}the\u{0020}freedom\u{0020}named\u{0020}\"Phantom\".", "0", "0", "0", "0", 10034, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[603402] = {603402, 500, "\u{0020}\u{0020}She\u{0020}might\u{0020}be\u{0020}a\u{0020}genius\u{0020}-\u{0020}this\u{0020}is\u{0020}what\u{0020}people\u{0020}often\u{0020}comment\u{0020}about\u{0020}Loki.\n\nOf\u{0020}course,\u{0020}at\u{0020}that\u{0020}time\u{0020}she\u{0020}wasn't\u{0020}called\u{0020}Loki.\u{0020}She\u{0020}had\u{0020}an\u{0020}ordinary\u{0020}name,\u{0020}but\u{0020}one\u{0020}that\u{0020}was\u{0020}more\u{0020}natural\u{0020}and\u{0020}less\u{0020}awkward\u{0020}than\u{0020}\"Loki\".\n\nPerhaps\u{0020}this\u{0020}kind\u{0020}of\u{0020}praise\u{0020}led\u{0020}her\u{0020}to\u{0020}have\u{0020}a\u{0020}wrong\u{0020}perception:\u{0020}that\u{0020}she\u{0020}was\u{0020}special,\u{0020}had\u{0020}special\u{0020}talents,\u{0020}and\u{0020}thus\u{0020}did\u{0020}not\u{0020}need\u{0020}to\u{0020}live\u{0020}like\u{0020}others.\n\nDon't\u{0020}live\u{0020}like\u{0020}others,\u{0020}following\u{0020}the\u{0020}rules\u{0020}and\u{0020}leading\u{0020}a\u{0020}boring\u{0020}life.\n\nOne\u{0020}can\u{0020}not\u{0020}follow\u{0020}the\u{0020}rules\u{0020}by\u{0020}oneself.\n\nThis\u{0020}wrong\u{0020}perception\u{0020}of\u{0020}self-identity\u{0020}and\u{0020}value\u{0020}is\u{0020}not\u{0020}rare\u{0020}for\u{0020}anyone.\u{0020}After\u{0020}all,\u{0020}when\u{0020}they\u{0020}were\u{0020}young,\u{0020}people\u{0020}always\u{0020}felt\u{0020}that\u{0020}they\u{0020}were\u{0020}special\u{0020}and\u{0020}considered\u{0020}themselves\u{0020}the\u{0020}\"protagonist\",\u{0020}and\u{0020}Loki\u{0020}was\u{0020}just\u{0020}one\u{0020}of\u{0020}them.\n\nIt's\u{0020}just\u{0020}that\u{0020}Loki\u{0020}has\u{0020}talents,\u{0020}but\u{0020}she\u{0020}lacks\u{0020}the\u{0020}ability\u{0020}to\u{0020}control\u{0020}her\u{0020}own\u{0020}talents.\n\nShe\u{0020}can\u{0020}easily\u{0020}do\u{0020}things\u{0020}that\u{0020}others\u{0020}can't\u{0020}-\u{0020}not\u{0020}to\u{0020}mention\u{0020}things\u{0020}related\u{0020}to\u{0020}study.\u{0020}She\u{0020}can\u{0020}also\u{0020}quickly\u{0020}master\u{0020}skills\u{0020}outside\u{0020}of\u{0020}school,\u{0020}such\u{0020}as\u{0020}combat\u{0020}skills,\u{0020}engineering,\u{0020}linguistics,\u{0020}and\u{0020}the\u{0020}network\u{0020}security\u{0020}in\u{0020}the\u{0020}computer\u{0020}field.\u{0020}She\u{0020}has\u{0020}reached\u{0020}the\u{0020}expert\u{0020}level\u{0020}in\u{0020}all\u{0020}these\u{0020}fields.\n\n\"A\u{0020}hundred\u{0020}years\u{0020}ago,\u{0020}she\u{0020}might\u{0020}have\u{0020}been\u{0020}selected\u{0020}by\u{0020}the\u{0020}people\u{0020}of\u{0020}the\u{0020}world's\u{0020}four\u{0020}major\u{0020}intelligence\u{0020}agencies.\u{0020}\"Her\u{0020}friend\u{0020}once\u{0020}said\u{0020}this.\n\nGeniuses\u{0020}are\u{0020}always\u{0020}arrogant.\u{0020}This\u{0020}is\u{0020}a\u{0020}stereotype,\u{0020}but\u{0020}it's\u{0020}not\u{0020}wrong\u{0020}to\u{0020}say\u{0020}that\u{0020}Loki\u{0020}is\u{0020}arrogant.\n\nThe\u{0020}young\u{0020}and\u{0020}talented\u{0020}her\u{0020}decided\u{0020}to\u{0020}challenge\u{0020}AEGIS.\n\nAnd\u{0020}they\u{0020}rank\u{0020}that\u{0020}person\u{0020}next\u{0020}to\u{0020}the\u{0020}head\u{0020}of\u{0020}AEGIS\u{0020}as\u{0020}the\u{0020}greatest\u{0020}mystery—Stephanie\u{0020}Ericson's\u{0020}information\u{0020}was\u{0020}set\u{0020}as\u{0020}her\u{0020}own\u{0020}goal.\n\n\"Great\u{0020}feat.\u{0020}Ninety-nine\u{0020}percent\u{0020}of\u{0020}hackers\u{0020}and\u{0020}spies\u{0020}in\u{0020}this\u{0020}world\u{0020}can't\u{0020}even\u{0020}take\u{0020}the\u{0020}first\u{0020}step.\u{0020}Who\u{0020}let\u{0020}those\u{0020}people\u{0020}call\u{0020}themselves\u{0020}'smart\u{0020}people'.\"\n\nOne\u{0020}day\u{0020}in\u{0020}the\u{0020}future,\u{0020}when\u{0020}Loki\u{0020}makes\u{0020}such\u{0020}an\u{0020}evaluation\u{0020}of\u{0020}a\u{0020}rejected\u{0020}driver,\u{0020}what\u{0020}she\u{0020}must\u{0020}be\u{0020}thinking\u{0020}of\u{0020}is\u{0020}the\u{0020}ignorant\u{0020}and\u{0020}presumptuous\u{0020}self\u{0020}in\u{0020}the\u{0020}past.\n\nLoki\u{0020}succeeded.\u{0020}She\u{0020}broke\u{0020}through\u{0020}the\u{0020}defense\u{0020}system\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}Science\u{0020}Department\u{0020}and\u{0020}found\u{0020}Stephanie's\u{0020}information.\u{0020}However,\u{0020}as\u{0020}the\u{0020}price\u{0020}of\u{0020}success.\u{0020}She\u{0020}became\u{0020}a\u{0020}prisoner\u{0020}sentenced\u{0020}to\u{0020}\"immediate\u{0020}execution\".", "0", "0", "0", "0", 10034, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[603403] = {603403, 1000, "\u{0020}\u{0020}In\u{0020}the\u{0020}countless\u{0020}days\u{0020}and\u{0020}nights\u{0020}after\u{0020}that,\u{0020}Loki\u{0020}would\u{0020}always\u{0020}remember\u{0020}her\u{0020}own\u{0020}past\u{0020}events.\n\nShe\u{0020}suspected\u{0020}that\u{0020}it\u{0020}was\u{0020}a\u{0020}trap,\u{0020}a\u{0020}trap\u{0020}set\u{0020}by\u{0020}Stephanie\u{0020}for\u{0020}someone\u{0020}like\u{0020}herself\u{0020}who\u{0020}had\u{0020}talent\u{0020}but\u{0020}didn't\u{0020}know\u{0020}self-control\u{0020}and\u{0020}was\u{0020}a\u{0020}fool.\n\nBut\u{0020}even\u{0020}if\u{0020}her\u{0020}conjecture\u{0020}was\u{0020}proved\u{0020}correct,\u{0020}it\u{0020}would\u{0020}be\u{0020}meaningless.\n\nShe\u{0020}must\u{0020}pay\u{0020}the\u{0020}price\u{0020}for\u{0020}her\u{0020}recklessness.\n\nShe\u{0020}was\u{0020}sent\u{0020}to\u{0020}various\u{0020}places\u{0020}around\u{0020}the\u{0020}world\u{0020}as\u{0020}a\u{0020}hound\u{0020}of\u{0020}AEGIS\u{0020}to\u{0020}carry\u{0020}out\u{0020}the\u{0020}tasks\u{0020}assigned\u{0020}by\u{0020}Stephanie.\n\nShe\u{0020}gradually\u{0020}forgot\u{0020}her\u{0020}name\u{0020}and\u{0020}gradually\u{0020}forgot\u{0020}how\u{0020}to\u{0020}get\u{0020}along\u{0020}with\u{0020}people\u{0020}normally.\n\nShe\u{0020}has\u{0020}lived\u{0020}a\u{0020}way\u{0020}she\u{0020}never\u{0020}imagined\u{0020}before,\u{0020}but\u{0020}hatred\u{0020}has\u{0020}never\u{0020}been\u{0020}erased\u{0020}from\u{0020}her\u{0020}heart.\n\nShe\u{0020}will\u{0020}surely\u{0020}retaliate\u{0020}against\u{0020}Stephanie.", "0", "0", "0", "0", 10034, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[603404] = {603404, 2000, "\u{0020}\u{0020}Gradually\u{0020}forgot\u{0020}the\u{0020}way\u{0020}to\u{0020}show\u{0020}a\u{0020}smile;\n\nGradually\u{0020}forgot\u{0020}the\u{0020}tone\u{0020}of\u{0020}greeting\u{0020}others;\n\nGradually\u{0020}forgot\u{0020}one's\u{0020}own\u{0020}name;\n\nShe\u{0020}might\u{0020}have\u{0020}had\u{0020}the\u{0020}chance\u{0020}to\u{0020}grasp\u{0020}the\u{0020}happiness\u{0020}of\u{0020}an\u{0020}ordinary\u{0020}person,\u{0020}but\u{0020}she\u{0020}gave\u{0020}it\u{0020}up\u{0020}herself.\n\nShe\u{0020}hates\u{0020}Stephanie,\u{0020}but\u{0020}also\u{0020}knows\u{0020}that\u{0020}it\u{0020}is\u{0020}her\u{0020}own\u{0020}fault.\n\nIf\u{0020}given\u{0020}a\u{0020}chance,\u{0020}she\u{0020}might\u{0020}make\u{0020}a\u{0020}more\u{0020}correct\u{0020}choice.\n\nBut\u{0020}there\u{0020}is\u{0020}no\u{0020}chance\u{0020}to\u{0020}start\u{0020}life\u{0020}over.\u{0020}She\u{0020}must\u{0020}face\u{0020}the\u{0020}reality.\n\nEspecially\u{0020}-\u{0020}the\u{0020}reality\u{0020}of\u{0020}how\u{0020}to\u{0020}get\u{0020}along\u{0020}with\u{0020}the\u{0020}child\u{0020}of\u{0020}one's\u{0020}enemy\u{0020}day\u{0020}and\u{0020}night.", "0", "0", "0", "0", 10034, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
