[603501] = {603501, 100, "\u{0020}\u{0020}Hurley\u{0020}Garcia\u{0020}seemed\u{0020}to\u{0020}have\u{0020}written\u{0020}\"Self-reliance\u{0020}and\u{0020}self-improvement\"\u{0020}on\u{0020}her\u{0020}life\u{0020}motto\u{0020}since\u{0020}childhood.\n\nAlthough\u{0020}she\u{0020}has\u{0020}a\u{0020}face\u{0020}that\u{0020}seems\u{0020}to\u{0020}be\u{0020}asking\u{0020}for\u{0020}help\u{0020}at\u{0020}any\u{0020}time,\u{0020}she\u{0020}herself\u{0020}appears\u{0020}to\u{0020}be\u{0020}very\u{0020}resistant\u{0020}to\u{0020}others'\u{0020}help.\n\nWhen\u{0020}she\u{0020}was\u{0020}at\u{0020}the\u{0020}driver's\u{0020}school,\u{0020}she\u{0020}was\u{0020}also\u{0020}-\u{0020}receiving\u{0020}a\u{0020}lot\u{0020}of\u{0020}scholarships\u{0020}while\u{0020}insisting\u{0020}on\u{0020}working\u{0020}part-time\u{0020}outside\u{0020}the\u{0020}school.\u{0020}In\u{0020}order\u{0020}to\u{0020}balance\u{0020}the\u{0020}courses,\u{0020}training\u{0020}and\u{0020}part-time\u{0020}work,\u{0020}she\u{0020}almost\u{0020}wore\u{0020}herself\u{0020}out\u{0020}several\u{0020}times.\n\nHowever,\u{0020}if\u{0020}someone\u{0020}felt\u{0020}pity\u{0020}upon\u{0020}seeing\u{0020}her\u{0020}pitiful\u{0020}appearance\u{0020}and\u{0020}attempted\u{0020}to\u{0020}offer\u{0020}her\u{0020}a\u{0020}helping\u{0020}hand,\u{0020}they\u{0020}would\u{0020}be\u{0020}driven\u{0020}away\u{0020}by\u{0020}her\u{0020}angrily.\n\nShe\u{0020}seemed\u{0020}to\u{0020}be\u{0020}proving\u{0020}to\u{0020}the\u{0020}world\u{0020}with\u{0020}her\u{0020}fierce\u{0020}eyes\u{0020}and\u{0020}not-so-scary\u{0020}tiger\u{0020}teeth\u{0020}-\u{0020}she,\u{0020}Hurley\u{0020}Garcia,\u{0020}was\u{0020}a\u{0020}ruthless\u{0020}person\u{0020}who\u{0020}would\u{0020}never\u{0020}bow\u{0020}to\u{0020}fate.", "0", "0", "0", "0", 10035, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[603502] = {603502, 500, "\u{0020}\u{0020}Hurley\u{0020}Garcia\u{0020}has\u{0020}a\u{0020}notebook\u{0020}that\u{0020}the\u{0020}content\u{0020}is\u{0020}known\u{0020}only\u{0020}to\u{0020}herself.\n\nThat\u{0020}is,\u{0020}the\u{0020}secret\u{0020}diary.\n\nFor\u{0020}her\u{0020}classmates,\u{0020}this\u{0020}was\u{0020}not\u{0020}a\u{0020}secret\u{0020}because\u{0020}she\u{0020}often\u{0020}took\u{0020}out\u{0020}her\u{0020}notebook\u{0020}on\u{0020}various\u{0020}occasions\u{0020}and\u{0020}wrote\u{0020}vigorously\u{0020}on\u{0020}it.\u{0020}Even\u{0020}when\u{0020}talking\u{0020}with\u{0020}classmates,\u{0020}she\u{0020}might\u{0020}suddenly\u{0020}interrupt\u{0020}the\u{0020}conversation\u{0020}and\u{0020}take\u{0020}out\u{0020}the\u{0020}notebook.\u{0020}Maybe\u{0020}she\u{0020}would\u{0020}do\u{0020}the\u{0020}same\u{0020}when\u{0020}working.\n\nNot\u{0020}that\u{0020}no\u{0020}one\u{0020}was\u{0020}curious\u{0020}about\u{0020}what\u{0020}she\u{0020}wrote\u{0020}in\u{0020}her\u{0020}notebook.\u{0020}However,\u{0020}every\u{0020}time\u{0020}someone\u{0020}couldn't\u{0020}resist\u{0020}their\u{0020}curiosity\u{0020}and\u{0020}asked\u{0020}her,\u{0020}she\u{0020}would\u{0020}always\u{0020}refuse\u{0020}them\u{0020}with\u{0020}a\u{0020}decisive\u{0020}attitude.\u{0020}Over\u{0020}time,\u{0020}no\u{0020}one\u{0020}bothered\u{0020}to\u{0020}ask\u{0020}anymore.\n\nHowever,\u{0020}the\u{0020}content\u{0020}in\u{0020}the\u{0020}notebook\u{0020}did\u{0020}not\u{0020}become\u{0020}an\u{0020}eternal\u{0020}mystery\u{0020}in\u{0020}the\u{0020}hearts\u{0020}of\u{0020}her\u{0020}classmates.\n\nOn\u{0020}the\u{0020}day\u{0020}when\u{0020}she\u{0020}completed\u{0020}her\u{0020}studies,\u{0020}became\u{0020}a\u{0020}\"preparatory\u{0020}driver\"\u{0020}and\u{0020}was\u{0020}assigned\u{0020}to\u{0020}the\u{0020}\"Cradle\",\u{0020}she\u{0020}showed\u{0020}the\u{0020}contents\u{0020}of\u{0020}her\u{0020}notebook\u{0020}to\u{0020}her\u{0020}classmates.\n\nThe\u{0020}content\u{0020}of\u{0020}the\u{0020}first\u{0020}page\u{0020}is:\u{0020}\"I\u{0020}want\u{0020}to\u{0020}become\u{0020}a\u{0020}hero\"\u{0020}，And\u{0020}a\u{0020}straight\u{0020}line\u{0020}drawn\u{0020}in\u{0020}the\u{0020}middle\u{0020}of\u{0020}this\u{0020}sentence\u{0020}-\u{0020}this\u{0020}means\u{0020}she\u{0020}denied\u{0020}this\u{0020}sentence.\n\nEach\u{0020}subsequent\u{0020}page\u{0020}records\u{0020}her\u{0020}insights\u{0020}on\u{0020}how\u{0020}to\u{0020}become\u{0020}a\u{0020}hero.\n\nAccording\u{0020}to\u{0020}her,\u{0020}she\u{0020}completed\u{0020}the\u{0020}content\u{0020}of\u{0020}the\u{0020}first\u{0020}page\u{0020}first\u{0020}and\u{0020}then\u{0020}wrote\u{0020}those\u{0020}subsequent\u{0020}insights.\n\nShe\u{0020}denied\u{0020}the\u{0020}idea\u{0020}of\u{0020}becoming\u{0020}a\u{0020}hero,\u{0020}but\u{0020}was\u{0020}still\u{0020}thinking\u{0020}about\u{0020}how\u{0020}to\u{0020}become\u{0020}one.\n\nFinally,\u{0020}under\u{0020}the\u{0020}gaze\u{0020}of\u{0020}all,\u{0020}she\u{0020}burned\u{0020}this\u{0020}notebook\u{0020}filled\u{0020}with\u{0020}her\u{0020}painstaking\u{0020}efforts\u{0020}to\u{0020}ashes.\n\n\"Thus,\u{0020}I\u{0020}can\u{0020}completely\u{0020}bid\u{0020}farewell\u{0020}to\u{0020}my\u{0020}gambling-addicted\u{0020}father.\"\n\nAlthough\u{0020}it\u{0020}is\u{0020}a\u{0020}bit\u{0020}difficult\u{0020}to\u{0020}understand,\u{0020}it\u{0020}seems\u{0020}that\u{0020}she\u{0020}is\u{0020}proving\u{0020}to\u{0020}her\u{0020}deceased\u{0020}father\u{0020}in\u{0020}this\u{0020}way\u{0020}that\u{0020}she\u{0020}can\u{0020}become\u{0020}a\u{0020}hero.\n\nBut\u{0020}she\u{0020}doesn't\u{0020}agree\u{0020}with\u{0020}this\u{0020}childish\u{0020}idea,\u{0020}so\u{0020}she\u{0020}has\u{0020}to\u{0020}deny\u{0020}it.\n\nShe\u{0020}didn't\u{0020}become\u{0020}a\u{0020}driver\u{0020}to\u{0020}be\u{0020}a\u{0020}hero.\n\nShe\u{0020}became\u{0020}a\u{0020}driver\u{0020}for\u{0020}her\u{0020}own\u{0020}selfish\u{0020}interests\u{0020}-\u{0020}to\u{0020}live\u{0020}a\u{0020}happier\u{0020}life.", "0", "0", "0", "0", 10035, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[603503] = {603503, 1000, "\u{0020}\u{0020}The\u{0020}day\u{0020}before\u{0020}the\u{0020}event\u{0020}of\u{0020}\"The\u{0020}crash\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Ark\",\u{0020}Hurley\u{0020}Garcia\u{0020}became\u{0020}the\u{0020}criminal\u{0020}of\u{0020}\"Murdering\u{0020}the\u{0020}Branch\u{0020}Chief\".\u{0020}And\u{0020}then,\u{0020}although\u{0020}she\u{0020}survived\u{0020}from\u{0020}Chesterton,\u{0020}she\u{0020}still\u{0020}didn't\u{0020}fully\u{0020}regain\u{0020}her\u{0020}innocence;\u{0020}if\u{0020}she\u{0020}was\u{0020}really\u{0020}innocent.\n\nBut\u{0020}at\u{0020}that\u{0020}time,\u{0020}Maya\u{0020}was\u{0020}plunged\u{0020}into\u{0020}an\u{0020}unprecedented\u{0020}crisis.\u{0020}Coupled\u{0020}with\u{0020}the\u{0020}crash\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Ark,\u{0020}there\u{0020}was\u{0020}insufficient\u{0020}evidence\u{0020}to\u{0020}prove\u{0020}that\u{0020}Hurley\u{0020}Garcia\u{0020}murdered\u{0020}the\u{0020}Branch\u{0020}Chief\u{0020}of\u{0020}Maya.\n\nAnd\u{0020}as\u{0020}a\u{0020}survivor\u{0020}who\u{0020}emerged\u{0020}unscathed\u{0020}from\u{0020}a\u{0020}dangerous\u{0020}situation,\u{0020}Hurley\u{0020}Garcia,\u{0020}AEGIS\u{0020}has\u{0020}sufficient\u{0020}reasons\u{0020}to\u{0020}keep\u{0020}her\u{0020}and\u{0020}have\u{0020}her\u{0020}do\u{0020}more\u{0020}for\u{0020}AEGIS.\n\nUltimately,\u{0020}under\u{0020}the\u{0020}urging\u{0020}of\u{0020}Dr.\u{0020}Stephanie,\u{0020}the\u{0020}chief\u{0020}scientist\u{0020}at\u{0020}the\u{0020}Kyushu\u{0020}Headquarters,\u{0020}AEGIS\u{0020}suspended\u{0020}the\u{0020}trial\u{0020}of\u{0020}Hurley\u{0020}Garcia's\u{0020}crime\u{0020}and\u{0020}allowed\u{0020}her\u{0020}to\u{0020}temporarily\u{0020}serve\u{0020}in\u{0020}the\u{0020}Frontline\u{0020}team\u{0020}to\u{0020}support\u{0020}the\u{0020}chaotic\u{0020}Maya\u{0020}regions.", "0", "0", "0", "0", 10035, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[603504] = {603504, 2000, "\u{0020}\u{0020}Duties\u{0020}are\u{0020}provided\u{0020}by\u{0020}identity.\n\nResponsibilities\u{0020}beyond\u{0020}one's\u{0020}identity\u{0020}are\u{0020}not\u{0020}ones\u{0020}that\u{0020}oneself\u{0020}should\u{0020}bear.\u{0020}If\u{0020}there\u{0020}are\u{0020}any,\u{0020}they\u{0020}are\u{0020}imposed\u{0020}on\u{0020}oneself\u{0020}by\u{0020}others\u{0020}under\u{0020}the\u{0020}guise\u{0020}of\u{0020}\"morality\".\n\nHurley\u{0020}Garcia\u{0020}has\u{0020}made\u{0020}up\u{0020}her\u{0020}mind\u{0020}long\u{0020}ago.\u{0020}She\u{0020}wants\u{0020}to\u{0020}live\u{0020}for\u{0020}herself.\n\nWhether\u{0020}humanity\u{0020}will\u{0020}be\u{0020}destroyed\u{0020}later\u{0020}or\u{0020}not,\u{0020}she\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}care.\n\nEven\u{0020}if\u{0020}humanity\u{0020}is\u{0020}going\u{0020}to\u{0020}perish,\u{0020}she\u{0020}just\u{0020}needs\u{0020}to\u{0020}live\u{0020}happily\u{0020}during\u{0020}her\u{0020}lifetime.\n\nThose\u{0020}who\u{0020}hinder\u{0020}her\u{0020}happiness,\u{0020}she\u{0020}will\u{0020}get\u{0020}rid\u{0020}of\u{0020}all\u{0020}of\u{0020}them.\n\nAEGIS\u{0020}or\u{0020}Sin,\u{0020}are\u{0020}all\u{0020}the\u{0020}same.\n\n\"Navigator,\u{0020}don't\u{0020}just\u{0020}laugh.\u{0020}I'm\u{0020}not\u{0020}kidding.\u{0020}I'm\u{0020}telling\u{0020}you,\u{0020}you\u{0020}too!\"\n\nIf\u{0020}Navigator\u{0020}interferes\u{0020}with\u{0020}your\u{0020}happiness,\u{0020}get\u{0020}rid\u{0020}of\u{0020}him.\n\nIf\u{0020}the\u{0020}Navigator\u{0020}is\u{0020}part\u{0020}of\u{0020}your\u{0020}happiness,\u{0020}then\u{0020}take\u{0020}him\u{0020}away.\n\nHurley\u{0020}Garcia\u{0020}will\u{0020}make\u{0020}herself\u{0020}happy\u{0020}with\u{0020}her\u{0020}own\u{0020}hands.", "0", "0", "0", "0", 10035, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[603600] = {603600, 0, "[Name]\u{0020}Charlissa\u{0020}de\u{0020}Rolan\n[B-Day]\u{0020}April\u{0020}1\n[Compatability\u{0020}Rate]\u{0020}<color=#FF6100>100％</color>\n[Height]\u{0020}35m\n[Squad]\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force\n[Affiliation]\u{0020}Stephanie/Danube\u{0020}Branch\n[Interest]\u{0020}Enjoy\u{0020}the\u{0020}admiring\u{0020}glances\u{0020}and\u{0020}addresses\u{0020}from\u{0020}others;\u{0020}like\u{0020}the\u{0020}free\u{0020}and\u{0020}decadent\u{0020}rainy\u{0020}days", "0", "0", "0", "0", 10036, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[603601] = {603601, 100, "\u{0020}\u{0020}While\u{0020}most\u{0020}drivers\u{0020}in\u{0020}Danube\u{0020}are\u{0020}busy\u{0020}preparing\u{0020}for\u{0020}Valentine's\u{0020}Day,\u{0020}Charlissa\u{0020}remains\u{0020}unfazed\u{0020}by\u{0020}the\u{0020}festive\u{0020}decorations,\u{0020}store\u{0020}sales,\u{0020}or\u{0020}the\u{0020}romantic\u{0020}atmosphere\u{0020}in\u{0020}the\u{0020}air.\u{0020}She\u{0020}simply\u{0020}enjoys\u{0020}her\u{0020}holiday,\u{0020}staying\u{0020}comfortably\u{0020}in\u{0020}her\u{0020}room.\n\n\u{0020}\u{0020}\"Today's\u{0020}meal\u{0020}is\u{0020}amazing…\u{0020}I\u{0020}think\u{0020}I'll\u{0020}have\u{0020}one\u{0020}more\u{0020}bowl,\"\u{0020}she\u{0020}muses,\u{0020}gazing\u{0020}at\u{0020}the\u{0020}sunset.\u{0020}Unbeknownst\u{0020}to\u{0020}her,\u{0020}she's\u{0020}on\u{0020}the\u{0020}verge\u{0020}of\u{0020}missing\u{0020}a\u{0020}life-changing\u{0020}moment\u{0020}—\u{0020}one\u{0020}that's\u{0020}quietly\u{0020}slipping\u{0020}away\u{0020}like\u{0020}the\u{0020}sun\u{0020}setting\u{0020}beyond\u{0020}the\u{0020}horizon.\n\n\u{0020}\u{0020}But\u{0020}her\u{0020}teammates\u{0020}have\u{0020}something\u{0020}else\u{0020}in\u{0020}mind.\u{0020}With\u{0020}their\u{0020}\"chocolate\u{0020}wake-up\u{0020}plan\"\u{0020}in\u{0020}action,\u{0020}Charlissa\u{0020}is\u{0020}suddenly\u{0020}pulled\u{0020}out\u{0020}of\u{0020}her\u{0020}reverie.\u{0020}Less\u{0020}than\u{0020}a\u{0020}month\u{0020}from\u{0020}a\u{0020}major\u{0020}turning\u{0020}point,\u{0020}she\u{0020}finds\u{0020}herself\u{0020}sprinting\u{0020}towards\u{0020}something\u{0020}new.", "0", "0", "0", "0", 10036, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[603602] = {603602, 500, "\u{0020}\u{0020}“Recently,\u{0020}Charlissa's\u{0020}been\u{0020}acting\u{0020}a\u{0020}little…\u{0020}strange.”\n\n\u{0020}\u{0020}The\u{0020}first\u{0020}sign\u{0020}was\u{0020}her\u{0020}appearance\u{0020}with\u{0020}odd\u{0020}glasses\u{0020}and\u{0020}a\u{0020}fake\u{0020}mustache.\u{0020}When\u{0020}asked,\u{0020}she\u{0020}denied\u{0020}it,\u{0020}but\u{0020}it\u{0020}was\u{0020}clear\u{0020}something\u{0020}was\u{0020}off.\n\n\u{0020}\u{0020}Left\u{0020}alone,\u{0020}she'd\u{0020}grow\u{0020}restless.\u{0020}After\u{0020}a\u{0020}while,\u{0020}she'd\u{0020}put\u{0020}on\u{0020}the\u{0020}disguise,\u{0020}and\u{0020}—\u{0020}to\u{0020}everyone's\u{0020}surprise\u{0020}—\u{0020}she\u{0020}became\u{0020}more\u{0020}confident\u{0020}and\u{0020}assertive.\u{0020}Soon\u{0020}after,\u{0020}she'd\u{0020}visit\u{0020}a\u{0020}small\u{0020}shop\u{0020}run\u{0020}by\u{0020}a\u{0020}certain\u{0020}doctor.\u{0020}When\u{0020}she\u{0020}came\u{0020}out,\u{0020}she\u{0020}always\u{0020}looked…\u{0020}deflated.\n\n\u{0020}\u{0020}More\u{0020}signs\u{0020}followed.\n\n\u{0020}\u{0020}Charlissa,\u{0020}the\u{0020}pampered\u{0020}daughter\u{0020}of\u{0020}a\u{0020}wealthy\u{0020}family,\u{0020}started\u{0020}obsessing\u{0020}over\u{0020}saving\u{0020}money,\u{0020}analyzing\u{0020}purchases\u{0020}for\u{0020}cost-effectiveness.\u{0020}It\u{0020}made\u{0020}people\u{0020}wonder\u{0020}if\u{0020}something\u{0020}had\u{0020}changed\u{0020}with\u{0020}her\u{0020}family's\u{0020}financial\u{0020}situation.\n\n\u{0020}\u{0020}Even\u{0020}more\u{0020}unusual:\u{0020}Charlissa,\u{0020}usually\u{0020}a\u{0020}homebody,\u{0020}had\u{0020}started\u{0020}appearing\u{0020}at\u{0020}the\u{0020}gym.\u{0020}Her\u{0020}recent\u{0020}health\u{0020}report\u{0020}confirmed\u{0020}a\u{0020}slight\u{0020}weight\u{0020}gain,\u{0020}but\u{0020}it\u{0020}was\u{0020}still\u{0020}within\u{0020}normal\u{0020}range.\u{0020}What\u{0020}was\u{0020}the\u{0020}reason\u{0020}behind\u{0020}her\u{0020}newfound\u{0020}focus\u{0020}on\u{0020}fitness?\n\n\u{0020}\u{0020}And\u{0020}then\u{0020}there's\u{0020}that\u{0020}mischievous\u{0020}smile\u{0020}she\u{0020}flashes\u{0020}now\u{0020}and\u{0020}then\u{0020}—\u{0020}especially\u{0020}when\u{0020}she\u{0020}sees\u{0020}you.\u{0020}If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}her\u{0020}perfect\u{0020}focus\u{0020}in\u{0020}battle,\u{0020}people\u{0020}might\u{0020}suggest\u{0020}a\u{0020}full\u{0020}mental\u{0020}evaluation.\n\n\u{0020}\u{0020}…Could\u{0020}it\u{0020}all\u{0020}be\u{0020}because\u{0020}of\u{0020}Valentine's\u{0020}Day?", "0", "0", "0", "0", 10036, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[603603] = {603603, 1000, "\u{0020}\u{0020}After\u{0020}much\u{0020}trial\u{0020}and\u{0020}error,\u{0020}Charlissa\u{0020}finally\u{0020}learned\u{0020}how\u{0020}to\u{0020}wear\u{0020}her\u{0020}new\u{0020}outfit.\u{0020}There's\u{0020}just\u{0020}one\u{0020}catch:\u{0020}a\u{0020}ribbon\u{0020}in\u{0020}the\u{0020}back,\u{0020}tied\u{0020}so\u{0020}tightly\u{0020}that\u{0020}if\u{0020}it\u{0020}loosens,\u{0020}it\u{0020}could\u{0020}leave\u{0020}her\u{0020}in\u{0020}an\u{0020}embarrassing\u{0020}state.\u{0020}A\u{0020}designer's\u{0020}quirky\u{0020}choice\u{0020}now\u{0020}has\u{0020}Charlissa\u{0020}on\u{0020}edge.\n\n\u{0020}\u{0020}She's\u{0020}only\u{0020}worn\u{0020}this\u{0020}outfit\u{0020}in\u{0020}front\u{0020}of\u{0020}you,\u{0020}and\u{0020}while\u{0020}you've\u{0020}seen\u{0020}her\u{0020}fully\u{0020}exposed\u{0020}before,\u{0020}Charlissa\u{0020}isn't\u{0020}quite\u{0020}ready\u{0020}for\u{0020}you\u{0020}to\u{0020}see\u{0020}her\u{0020}like\u{0020}that…\u{0020}at\u{0020}least,\u{0020}not\u{0020}yet.\n\n\u{0020}\u{0020}Now,\u{0020}freed\u{0020}from\u{0020}her\u{0020}self-imposed\u{0020}constraints,\u{0020}Charlissa\u{0020}has\u{0020}big\u{0020}plans\u{0020}for\u{0020}her\u{0020}future.\u{0020}\"Maybe\u{0020}in\u{0020}two\u{0020}years…\u{0020}No,\u{0020}that's\u{0020}too\u{0020}long.\u{0020}One\u{0020}year…\u{0020}or\u{0020}maybe\u{0020}six\u{0020}months?\"\n\n\u{0020}\u{0020}she\u{0020}dreams\u{0020}aloud.", "0", "0", "0", "0", 10036, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[603604] = {603604, 2000, "\u{0020}\u{0020}How\u{0020}delightful!\n\n\u{0020}\u{0020}A\u{0020}future\u{0020}full\u{0020}of\u{0020}endless\u{0020}possibilities\u{0020}awaits\u{0020}her.\n\n\u{0020}\u{0020}She\u{0020}will\u{0020}reap\u{0020}the\u{0020}rewards\u{0020}of\u{0020}her\u{0020}dreams,\u{0020}alongside\u{0020}the\u{0020}mountains,\u{0020}the\u{0020}winds,\u{0020}and\u{0020}the\u{0020}world\u{0020}around\u{0020}her.\n\n\u{0020}\u{0020}Her\u{0020}path\u{0020}ahead\u{0020}is\u{0020}clear,\u{0020}certain,\u{0020}and\u{0020}full\u{0020}of\u{0020}promise.\n\n\u{0020}\u{0020}With\u{0020}the\u{0020}world,\u{0020}the\u{0020}stars,\u{0020}and\u{0020}you\u{0020}by\u{0020}her\u{0020}side,\u{0020}she'll\u{0020}continue\u{0020}her\u{0020}journey\u{0020}forward.\n\n\u{0020}\u{0020}To\u{0020}the\u{0020}melody\u{0020}of\u{0020}love's\u{0020}song,\n\n\u{0020}\u{0020}let's\u{0020}shape\u{0020}the\u{0020}future\u{0020}together.", "0", "0", "0", "0", 10036, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[603700] = {603700, 0, "Name:\u{0020}Kraz\nDate\u{0020}of\u{0020}Birth:\u{0020}July\u{0020}8\nCompatibility\u{0020}Rate:\u{0020}51%\nHeight\u{0020}after\u{0020}Gigantification:\u{0020}34m\nSquad:\u{0020}Iskanwaya\nAffiliation:\u{0020}Inca\nLikes:\u{0020}Pretending", "0", "0", "0", "0", 10037, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[603701] = {603701, 100, "\u{3000}\u{3000}Kraz\u{0020}was\u{0020}never\u{0020}a\u{0020}good\u{0020}Driver,\u{0020}barely\u{0020}even\u{0020}a\u{0020}passable\u{0020}one.\n\u{3000}\u{3000}Her\u{0020}compatibility\u{0020}rate\u{0020}was\u{0020}extremely\u{0020}low,\u{0020}which\u{0020}isn't\u{0020}the\u{0020}sole\u{0020}measure\u{0020}of\u{0020}a\u{0020}Driver's\u{0020}worth,\u{0020}though,\u{0020}given\u{0020}the\u{0020}fact\u{0020}that\u{0020}many\u{0020}of\u{0020}AEGIS'\u{0020}impressive\u{0020}Drivers\u{0020}operate\u{0020}with\u{0020}less-than-ideal\u{0020}rates.\u{0020}It\u{0020}was\u{0020}obvious,\u{0020}however,\u{0020}that\u{0020}Kraz\u{0020}would\u{0020}never\u{0020}become\u{0020}one\u{0020}of\u{0020}them.\n\u{3000}\u{3000}She\u{0020}is\u{0020}timid.\u{0020}For\u{0020}her,\u{0020}the\u{0020}battlefield\u{0020}was\u{0020}a\u{0020}circle\u{0020}drawn\u{0020}around\u{0020}her\u{0020}shield,\u{0020}with\u{0020}her\u{0020}pistol's\u{0020}effective\u{0020}range\u{0020}as\u{0020}its\u{0020}radius.\u{0020}I\u{0020}simply\u{0020}cannot\u{0020}imagine\u{0020}how\u{0020}she\u{0020}would\u{0020}survive\u{0020}the\u{0020}surging\u{0020}hordes\u{0020}of\u{0020}Sins\u{0020}without\u{0020}the\u{0020}protection\u{0020}of\u{0020}other\u{0020}Drivers.\u{0020}She\u{0020}has\u{0020}long\u{0020}since\u{0020}become\u{0020}a\u{0020}burden\u{0020}on\u{0020}the\u{0020}team.\n\u{3000}\u{3000}She\u{0020}doesn't\u{0020}fit\u{0020}in.\u{0020}Almost\u{0020}no\u{0020}one\u{0020}in\u{0020}the\u{0020}Inca\u{0020}Branch\u{0020}would\u{0020}call\u{0020}her\u{0020}a\u{0020}friend.\u{0020}There\u{0020}was\u{0020}always\u{0020}a\u{0020}strange,\u{0020}invisible\u{0020}distance\u{0020}when\u{0020}dealing\u{0020}with\u{0020}her.\u{0020}You\u{0020}could\u{0020}talk\u{0020}to\u{0020}her\u{0020}just\u{0020}fine,\u{0020}but\u{0020}somehow\u{0020}you\u{0020}would\u{0020}never\u{0020}get\u{0020}close\u{0020}to\u{0020}her\u{0020}heart.\u{0020}Over\u{0020}time,\u{0020}that\u{0020}sort\u{0020}of\u{0020}dynamic\u{0020}inevitably\u{0020}drags\u{0020}down\u{0020}team\u{0020}morale,\u{0020}and\u{0020}in\u{0020}turn,\u{0020}battlefield\u{0020}performance.\n\u{3000}\u{3000}She\u{0020}is\u{0020}ungrateful.\u{0020}She\u{0020}has\u{0020}never\u{0020}once\u{0020}shown\u{0020}appreciation\u{0020}to\u{0020}the\u{0020}Navigator\u{0020}who\u{0020}vouched\u{0020}for\u{0020}her\u{0020}entry\u{0020}into\u{0020}AEGIS.\u{0020}Instead,\u{0020}she\u{0020}only\u{0020}grew\u{0020}bolder.\u{0020}Doing\u{0020}everything\u{0020}she\u{0020}could,\u{0020}seizing\u{0020}every\u{0020}chance\u{0020}possible,\u{0020}to\u{0020}cling\u{0020}to\u{0020}that\u{0020}Navigator.\u{0020}This,\u{0020}above\u{0020}all\u{0020}else,\u{0020}is\u{0020}her\u{0020}most\u{0020}unforgivable\u{0020}offense.\n\u{3000}\u{3000}Given\u{0020}all\u{0020}this,\u{0020}I\u{0020}believe\u{0020}Kraz\u{0020}is\u{0020}not\u{0020}suited\u{0020}to\u{0020}continue\u{0020}in\u{0020}her\u{0020}position\u{0020}as\u{0020}a\u{0020}Driver\u{0020}of\u{0020}the\u{0020}Inca\u{0020}Branch's\u{0020}Iskanwaya\u{0020}Squad.\u{0020}I\u{0020}hereby\u{0020}submit\u{0020}a\u{0020}formal\u{0020}request\u{0020}recommending\u{0020}that\u{0020}the\u{0020}Inca\u{0020}Branch\u{0020}re-evaluate\u{0020}Kraz's\u{0020}qualifications,\u{0020}and\u{0020}reassess\u{0020}her\u{0020}ability\u{0020}and\u{0020}value\u{0020}as\u{0020}a\u{0020}Driver.\n\u{3000}\u{3000}One\u{0020}final\u{0020}suggestion:\u{0020}please\u{0020}have\u{0020}Intelligence\u{0020}look\u{0020}into\u{0020}the\u{0020}connection\u{0020}between\u{0020}S70\u{0020}and\u{0020}Kraz.\n\u{3000}\u{3000}Anonymous,\u{0020}S52.", "0", "0", "0", "0", 10037, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[603702] = {603702, 500, "\u{3000}\u{3000}S70,\u{0020}Vega...\u{0020}former\u{0020}names,\u{0020}codenames,\u{0020}aliases...\u{0020}Kraz\u{0020}was\u{0020}simply\u{0020}one\u{0020}of\u{0020}many.\n\u{3000}\u{3000}Ever\u{0020}since\u{0020}the\u{0020}moment\u{0020}she\u{0020}dragged\u{0020}her\u{0020}frail\u{0020}body\u{0020}free\u{0020}from\u{0020}the\u{0020}crimson\u{0020}pool\u{0020}four\u{0020}years\u{0020}ago,\u{0020}she\u{0020}had\u{0020}drifted\u{0020}from\u{0020}identity\u{0020}to\u{0020}identity,\u{0020}none\u{0020}of\u{0020}them\u{0020}truly\u{0020}connected.\n\u{3000}\u{3000}Refugee,\u{0020}displaced\u{0020}survivor,\u{0020}street\u{0020}child...\u{0020}At\u{0020}first,\u{0020}she\u{0020}used\u{0020}these\u{0020}labels\u{0020}to\u{0020}receive\u{0020}AEGIS\u{0020}aid\u{0020}and\u{0020}scrape\u{0020}by.\u{0020}When\u{0020}the\u{0020}incident\u{0020}that\u{0020}scarred\u{0020}her\u{0020}past\u{0020}finally\u{0020}began\u{0020}to\u{0020}fade,\u{0020}she\u{0020}tried\u{0020}on\u{0020}new\u{0020}identities,\u{0020}like\u{0020}waitress,\u{0020}apprentice,\u{0020}janitor...\u{0020}But\u{0020}she\u{0020}soon\u{0020}found\u{0020}she\u{0020}wasn't\u{0020}meant\u{0020}for\u{0020}any\u{0020}of\u{0020}them.\u{0020}Her\u{0020}victim\u{0020}act\u{0020}didn't\u{0020}work\u{0020}there.\u{0020}The\u{0020}words\u{0020}she\u{0020}heard\u{0020}most\u{0020}often\u{0020}were:\u{0020}\"Get\u{0020}lost\u{0020}if\u{0020}you\u{0020}can't\u{0020}do\u{0020}this.\"\u{0020}So,\u{0020}she\u{0020}abandoned\u{0020}those\u{0020}identities\u{0020}without\u{0020}hesitation,\u{0020}wiping\u{0020}them\u{0020}permanently\u{0020}from\u{0020}her\u{0020}internal\u{0020}roster.\n\u{3000}\u{3000}She\u{0020}returned\u{0020}to\u{0020}wandering\u{0020}as\u{0020}a\u{0020}refugee,\u{0020}a\u{0020}vagrant,\u{0020}and\u{0020}even\u{0020}a\u{0020}beggar.\u{0020}It\u{0020}was\u{0020}then,\u{0020}while\u{0020}begging,\u{0020}that\u{0020}she\u{0020}met\u{0020}a\u{0020}kind\u{0020}couple.\u{0020}They\u{0020}couldn't\u{0020}have\u{0020}children,\u{0020}and\u{0020}had\u{0020}long\u{0020}hoped\u{0020}to\u{0020}adopt.\u{0020}This\u{0020}\"pitiful\"\u{0020}little\u{0020}girl\u{0020}captured\u{0020}their\u{0020}heart\u{0020}and\u{0020}they\u{0020}decided\u{0020}to\u{0020}take\u{0020}her\u{0020}in.\u{0020}As\u{0020}their\u{0020}adopted\u{0020}daughter,\u{0020}she\u{0020}stopped\u{0020}using\u{0020}the\u{0020}name\u{0020}Vega,\u{0020}since\u{0020}it\u{0020}reminded\u{0020}her\u{0020}too\u{0020}much\u{0020}of\u{0020}her\u{0020}previous\u{0020}foster\u{0020}parents.\u{0020}She\u{0020}had\u{0020}once\u{0020}thought\u{0020}about\u{0020}visiting\u{0020}them\u{0020}again,\u{0020}but\u{0020}never\u{0020}followed\u{0020}through.\n\u{3000}\u{3000}Her\u{0020}new\u{0020}foster\u{0020}parents\u{0020}weren't\u{0020}well-off,\u{0020}but\u{0020}they\u{0020}lived\u{0020}comfortably.\u{0020}She\u{0020}had\u{0020}made\u{0020}up\u{0020}her\u{0020}mind\u{0020}to\u{0020}live\u{0020}out\u{0020}the\u{0020}rest\u{0020}of\u{0020}her\u{0020}life\u{0020}with\u{0020}them.\u{0020}But\u{0020}fate\u{0020}was\u{0020}like\u{0020}a\u{0020}ringmaster\u{0020}with\u{0020}a\u{0020}whip\u{0020}who\u{0020}never\u{0020}allowed\u{0020}her\u{0020}a\u{0020}moment's\u{0020}rest.\u{0020}A\u{0020}completely\u{0020}ordinary\u{0020}accident\u{0020}in\u{0020}this\u{0020}cruel\u{0020}world\u{0020}shattered\u{0020}her\u{0020}happiness\u{0020}in\u{0020}an\u{0020}all-too-familiar\u{0020}way:\n\u{3000}\u{3000}A\u{0020}Sin\u{0020}attack.\n\u{3000}\u{3000}Wherever\u{0020}destruction\u{0020}walks,\u{0020}survival\u{0020}follows\u{0020}behind\u{0020}in\u{0020}distorted\u{0020}symmetry.\u{0020}The\u{0020}Sin\u{0020}stole\u{0020}her\u{0020}home,\u{0020}but\u{0020}also\u{0020}delivered\u{0020}a\u{0020}new\u{0020}opportunity.\u{0020}The\u{0020}Inca\u{0020}Branch\u{0020}of\u{0020}AEGIS\u{0020}found\u{0020}her\u{0020}amid\u{0020}the\u{0020}ruins,\u{0020}thinking\u{0020}of\u{0020}her\u{0020}as\u{0020}a\u{0020}\"survivor,\"\u{0020}a\u{0020}\"war\u{0020}orphan.\"\u{0020}They\u{0020}offered\u{0020}her\u{0020}two\u{0020}choices.\u{0020}First:\u{0020}take\u{0020}a\u{0020}sizable\u{0020}compensation\u{0020}payment\u{0020}and\u{0020}start\u{0020}a\u{0020}new\u{0020}life\u{0020}elsewhere.\u{0020}Second:\u{0020}join\u{0020}the\u{0020}training\u{0020}program\u{0020}offered\u{0020}by\u{0020}the\u{0020}branch\u{0020}with\u{0020}the\u{0020}goal\u{0020}of\u{0020}becoming\u{0020}a\u{0020}Driver.\n\u{3000}\u{3000}She\u{0020}used\u{0020}the\u{0020}last\u{0020}of\u{0020}her\u{0020}money\u{0020}to\u{0020}erect\u{0020}a\u{0020}gravestone\u{0020}for\u{0020}her\u{0020}adoptive\u{0020}parents\u{0020}in\u{0020}a\u{0020}quiet\u{0020}place,\u{0020}then\u{0020}mourned\u{0020}briefly\u{0020}before\u{0020}leaving\u{0020}the\u{0020}desolate\u{0020}land\u{0020}without\u{0020}a\u{0020}trace.\n\u{3000}\u{3000}When\u{0020}she\u{0020}resurfaced,\u{0020}she\u{0020}was\u{0020}no\u{0020}longer\u{0020}Vega.\u{0020}She\u{0020}was\u{0020}Kraz.", "0", "0", "0", "0", 10037, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[603703] = {603703, 1000, "\u{3000}\u{3000}\"Inca\u{0020}Branch\u{0020}doesn't\u{0020}keep\u{0020}freeloaders.\"\n\u{3000}\u{3000}A\u{0020}slogan\u{0020}with\u{0020}no\u{0020}bite.\u{0020}In\u{0020}truth,\u{0020}the\u{0020}branch\u{0020}is\u{0020}full\u{0020}of\u{0020}\"freeloaders,\"\u{0020}and\u{0020}that\u{0020}opened\u{0020}a\u{0020}door\u{0020}for\u{0020}Kraz's\u{0020}performance.\n\u{3000}\u{3000}To\u{0020}her,\u{0020}\"joining\u{0020}AEGIS\"\u{0020}meant\u{0020}\"a\u{0020}good\u{0020}life\u{0020}is\u{0020}finally\u{0020}coming,\"\u{0020}a\u{0020}sentiment\u{0020}many\u{0020}Drivers\u{0020}shared.\u{0020}She\u{0020}talked\u{0020}her\u{0020}way\u{0020}into\u{0020}an\u{0020}easy\u{0020}job\u{0020}as\u{0020}a\u{0020}security\u{0020}guard\u{0020}for\u{0020}the\u{0020}research\u{0020}facility.\u{0020}Who\u{0020}would\u{0020}dare\u{0020}cause\u{0020}trouble\u{0020}on\u{0020}AEGIS'\u{0020}turf?\u{0020}As\u{0020}far\u{0020}as\u{0020}she\u{0020}was\u{0020}concerned,\u{0020}being\u{0020}a\u{0020}guard\u{0020}meant\u{0020}she\u{0020}was\u{0020}ahead\u{0020}of\u{0020}regular\u{0020}Drivers\u{0020}by\u{0020}at\u{0020}least\u{0020}four\u{0020}decades.\u{0020}\"Being\u{0020}a\u{0020}Driver\u{0020}someday\"?\u{0020}Hello?\u{0020}Come\u{0020}on.\u{0020}Go\u{0020}to\u{0020}hell.\n\u{3000}\u{3000}This\u{0020}should\u{0020}have\u{0020}been\u{0020}the\u{0020}end\u{0020}of\u{0020}her\u{0020}story.\u{0020}Kraz\u{0020}nearly\u{0020}allowed\u{0020}herself\u{0020}to\u{0020}sink\u{0020}into\u{0020}the\u{0020}simple\u{0020}bliss\u{0020}of\u{0020}a\u{0020}stable,\u{0020}comfortable\u{0020}life.\u{0020}But\u{0020}fate's\u{0020}whip\u{0020}didn't\u{0020}stop.\u{0020}She\u{0020}ran\u{0020}into\u{0020}the\u{0020}one\u{0020}person\u{0020}who'd\u{0020}almost\u{0020}caused\u{0020}her\u{0020}death\u{0020}twice.\u{0020}S52.\u{0020}Real\u{0020}name:\u{0020}Courant.\n\u{3000}\u{3000}From\u{0020}a\u{0020}few\u{0020}minutes\u{0020}before\u{0020}she\u{0020}removed\u{0020}her\u{0020}hat\u{0020}to\u{0020}the\u{0020}few\u{0020}seconds\u{0020}before\u{0020}it\u{0020}left\u{0020}her\u{0020}hands,\u{0020}she\u{0020}had\u{0020}already\u{0020}crafted\u{0020}a\u{0020}revenge\u{0020}plan.\u{0020}One\u{0020}that\u{0020}required\u{0020}no\u{0020}bloodshed,\u{0020}yet\u{0020}would\u{0020}strike\u{0020}deep\u{0020}into\u{0020}S52's\u{0020}heart.\n\u{3000}\u{3000}Kraz\u{0020}decided\u{0020}to\u{0020}use\u{0020}her\u{0020}greatest\u{0020}and\u{0020}best\u{0020}weapon,\u{0020}her\u{0020}\"victim\u{0020}act,\"\u{0020}to\u{0020}steal\u{0020}away\u{0020}everything\u{0020}S52\u{0020}held\u{0020}dear.", "0", "0", "0", "0", 10037, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[603704] = {603704, 2000, "\u{3000}\u{3000}S70,\u{0020}an\u{0020}ignorant\u{0020}kid,\n\u{3000}\u{3000}who\u{0020}chose\u{0020}cowardice\u{0020}the\u{0020}moment\u{0020}freedom\u{0020}appeared\u{0020}before\u{0020}her.\n\u{3000}\u{3000}That\u{0020}was\u{0020}the\u{0020}biggest\u{0020}mistake\u{0020}in\u{0020}her\u{0020}life.\n\u{3000}\u{3000}Vega,\u{0020}a\u{0020}deluded\u{0020}fool,\n\u{3000}\u{3000}who\u{0020}thought\u{0020}she\u{0020}could\u{0020}defeat\u{0020}someone\u{0020}at\u{0020}their\u{0020}own\u{0020}game,\n\u{3000}\u{3000}in\u{0020}a\u{0020}field\u{0020}the\u{0020}other\u{0020}mastered.\n\u{3000}\u{3000}Kraz,\u{0020}a\u{0020}stubborn\u{0020}idiot,\n\u{3000}\u{3000}who\u{0020}was\u{0020}betrayed\u{0020}twice,\u{0020}abandoned\u{0020}twice,\n\u{3000}\u{3000}and\u{0020}still\u{0020}never\u{0020}learned\u{0020}how\u{0020}to\u{0020}\"run\u{0020}away.\"\n\u{3000}\u{3000}......\n\u{3000}\u{3000}...Hopeless,\u{0020}isn't\u{0020}she?\u{0020}Maybe.\n\u{3000}\u{3000}Maybe\u{0020}this\u{0020}is\u{0020}all\u{0020}her\u{0020}life\u{0020}will\u{0020}ever\u{0020}amount\u{0020}to.\n\u{3000}\u{3000}\u{0020}If\u{0020}you\u{0020}leave\u{0020}me\u{0020}again,\u{0020}if\u{0020}you\u{0020}abandon\u{0020}me\u{0020}again,\u{0020}Navigator...\n\u{3000}\u{3000}Goodbye,\u{0020}Navigator.\n\u{3000}\u{3000}But\u{0020}remember\u{0020}this:\n\u{3000}\u{3000}When\u{0020}you\u{0020}look\u{0020}at\u{0020}the\u{0020}sky...\n\u{3000}\u{3000}beyond\u{0020}the\u{0020}eternal\u{0020}darkness...\n\u{3000}\u{3000}Kraz\u{0020}will\u{0020}always\u{0020}shine\u{0020}for\u{0020}you.", "0", "0", "0", "0", 10037, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[603800] = {603800, 0, "[Name]\u{0020}Hlokk\n[B-Day]\u{0020}July\u{0020}20\n[Compatibility\u{0020}Rate]\u{0020}76％\n[Height]\u{0020}36m\n[Squad]\u{0020}Night\u{0020}Watcher\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Fishing,\u{0020}research.", "0", "0", "0", "0", 10038, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】欧朵啦\n【生日】5月2日\n【幻化核心适格率】53％\n【巨大化身高】24m\n【部队】魂灭\n【隶属】九州总部\n【爱好】睡觉\u{3000}露露啦的背"},
[603801] = {603801, 100, "The\u{0020}First\u{0020}Laboratory's\u{0020}Control\u{0020}Division\u{0020}is\u{0020}a\u{0020}mysterious\u{0020}and\u{0020}secretive\u{0020}department.\u{0020}Its\u{0020}exact\u{0020}location\u{0020}is\u{0020}unknown\u{0020}to\u{0020}most,\u{0020}even\u{0020}to\u{0020}the\u{0020}laboratory's\u{0020}own\u{0020}employees,\u{0020}who\u{0020}are\u{0020}aware\u{0020}only\u{0020}of\u{0020}its\u{0020}existence.\n\nOn\u{0020}top\u{0020}of\u{0020}that,\u{0020}even\u{0020}fewer\u{0020}know\u{0020}about\u{0020}the\u{0020}existence\u{0020}of\u{0020}Night\u{0020}Watcher\u{0020}Squad.\u{0020}Hlokk,\u{0020}the\u{0020}first\u{0020}member\u{0020}of\u{0020}Night\u{0020}Watcher\u{0020}Squad,\u{0020}has\u{0020}been\u{0020}a\u{0020}near-phantom\u{0020}figure\u{0020}ever\u{0020}since\u{0020}joining\u{0020}the\u{0020}division.\u{0020}Even\u{0020}her\u{0020}parents\u{0020}rarely\u{0020}got\u{0020}a\u{0020}chance\u{0020}to\u{0020}see\u{0020}her\u{0020}year-round.\u{0020}In\u{0020}the\u{0020}solitude\u{0020}of\u{0020}her\u{0020}work\u{0020}at\u{0020}the\u{0020}Control\u{0020}Division,\u{0020}Hlokk\u{0020}found\u{0020}comfort\u{0020}in\u{0020}fishing\u{0020}on\u{0020}the\u{0020}nearby\u{0020}frozen\u{0020}river,\u{0020}a\u{0020}hobby\u{0020}that\u{0020}became\u{0020}her\u{0020}favorite\u{0020}way\u{0020}to\u{0020}pass\u{0020}the\u{0020}time.\n\nShe\u{0020}has\u{0020}two\u{0020}great\u{0020}passions—scientific\u{0020}research\u{0020}and\u{0020}fishing.\u{0020}According\u{0020}to\u{0020}Hlokk,\u{0020}she\u{0020}loves\u{0020}activities\u{0020}where\u{0020}effort\u{0020}alone\u{0020}does\u{0020}guarantee\u{0020}success,\u{0020}and\u{0020}the\u{0020}outcomes\u{0020}are\u{0020}left\u{0020}to\u{0020}chance.\u{0020}This\u{0020}allure\u{0020}of\u{0020}uncertainty\u{0020}is\u{0020}what\u{0020}captivated\u{0020}her\u{0020}deeply.\n\n\"Catching\u{0020}fish\u{0020}isn't\u{0020}the\u{0020}goal,\"\u{0020}she\u{0020}often\u{0020}says.\u{0020}\"I\u{0020}just\u{0020}enjoy\u{0020}the\u{0020}process.\"\n\nYet,\u{0020}despite\u{0020}her\u{0020}modest\u{0020}expectations,\u{0020}Hlokk\u{0020}always\u{0020}returned\u{0020}with\u{0020}a\u{0020}full\u{0020}catch.", "0", "0", "0", "0", 10038, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂灭”的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{3000}\u{3000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{3000}\u{3000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着“生活障碍症”这一奇怪病症。\n\u{3000}\u{3000}“不……无论怎么看，都只是纯粹的懒惰而已吧……”尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[603802] = {603802, 500, "Hlokk\u{0020}thrived\u{0020}on\u{0020}the\u{0020}unpredictability\u{0020}of\u{0020}life,\u{0020}embracing\u{0020}an\u{0020}attitude\u{0020}of\u{0020}letting\u{0020}things\u{0020}unfold\u{0020}naturally.\n\nThis\u{0020}outlook\u{0020}often\u{0020}brought\u{0020}her\u{0020}unexpected\u{0020}successes,\u{0020}both\u{0020}in\u{0020}her\u{0020}research\u{0020}and\u{0020}her\u{0020}fishing\u{0020}endeavors.\n\nIronically,\u{0020}her\u{0020}fishing\u{0020}skills\u{0020}came\u{0020}from\u{0020}her\u{0020}father,\u{0020}who\u{0020}was\u{0020}far\u{0020}from\u{0020}a\u{0020}master\u{0020}fisherman.\n\nHe\u{0020}often\u{0020}remarked,\n\n\"The\u{0020}fun\u{0020}in\u{0020}fishing\u{0020}is\u{0020}that\u{0020}you\u{0020}can\u{0020}spend\u{0020}the\u{0020}whole\u{0020}day\u{0020}enjoying\u{0020}yourself\u{0020}without\u{0020}catching\u{0020}a\u{0020}single\u{0020}fish.\"\n\nWhile\u{0020}this\u{0020}was\u{0020}mostly\u{0020}his\u{0020}way\u{0020}of\u{0020}masking\u{0020}the\u{0020}disappointment\u{0020}of\u{0020}an\u{0020}empty\u{0020}bucket,\u{0020}the\u{0020}sentiment\u{0020}deeply\u{0020}resonated\u{0020}with\u{0020}Hlokk.\n\nShe\u{0020}adopted\u{0020}his\u{0020}philosophy\u{0020}of\u{0020}living\u{0020}in\u{0020}the\u{0020}moment,\u{0020}casting\u{0020}her\u{0020}line\u{0020}without\u{0020}expectations\u{0020}yet\u{0020}consistently\u{0020}reeling\u{0020}in\u{0020}a\u{0020}catch.\n\nFor\u{0020}her,\u{0020}fishing\u{0020}became\u{0020}a\u{0020}kind\u{0020}of\u{0020}exchange:\u{0020}she\u{0020}offered\u{0020}bait\u{0020}and\u{0020}time\u{0020}and\u{0020}was\u{0020}rewarded\u{0020}with\u{0020}pleasant\u{0020}surprises.\n\nThis\u{0020}almost\u{0020}magical\u{0020}knack\u{0020}extended\u{0020}beyond\u{0020}fishing,\u{0020}making\u{0020}her\u{0020}studies\u{0020}and\u{0020}everyday\u{0020}tasks\u{0020}unexpectedly\u{0020}easy\u{0020}and\u{0020}enjoyable.\u{0020}However,\u{0020}this\u{0020}magic\u{0020}seemed\u{0020}to\u{0020}falter\u{0020}in\u{0020}one\u{0020}area—forming\u{0020}friendships.\u{0020}Her\u{0020}peers\u{0020}kept\u{0020}their\u{0020}distance,\u{0020}and\u{0020}even\u{0020}when\u{0020}she\u{0020}reached\u{0020}out,\u{0020}they\u{0020}would\u{0020}quietly\u{0020}withdraw.\u{0020}At\u{0020}the\u{0020}time,\u{0020}Hlokk\u{0020}didn't\u{0020}understand\u{0020}the\u{0020}concept\u{0020}of\u{0020}jealousy,\u{0020}but\u{0020}she\u{0020}did\u{0020}feel\u{0020}a\u{0020}persistent\u{0020}loneliness.\n\nIn\u{0020}response,\u{0020}she\u{0020}turned\u{0020}inward,\u{0020}devoting\u{0020}more\u{0020}time\u{0020}to\u{0020}herself.\u{0020}During\u{0020}this\u{0020}period,\u{0020}her\u{0020}passion\u{0020}for\u{0020}scientific\u{0020}research\u{0020}began\u{0020}to\u{0020}flourish.\u{0020}What\u{0020}started\u{0020}as\u{0020}a\u{0020}curiosity\u{0020}about\u{0020}crafting\u{0020}better\u{0020}fishing\u{0020}bait\u{0020}evolved\u{0020}into\u{0020}a\u{0020}fascination\u{0020}with\u{0020}the\u{0020}experimental\u{0020}nature\u{0020}of\u{0020}Sin\u{0020}Studies.\n\nThe\u{0020}uncertainty\u{0020}of\u{0020}experiments\u{0020}thrilled\u{0020}her\u{0020}even\u{0020}more\u{0020}than\u{0020}fishing,\u{0020}igniting\u{0020}her\u{0020}imagination\u{0020}and\u{0020}gradually\u{0020}dulling\u{0020}her\u{0020}sense\u{0020}of\u{0020}isolation.", "0", "0", "0", "0", 10038, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{3000}\u{3000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{3000}\u{3000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{3000}\u{3000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了“明日之花”的鼓励性质奖章。\n\u{3000}\u{3000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{3000}\u{3000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{3000}\u{3000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队“魂灭”的雏形，也是从那个时候开始的。\n\u{3000}\u{3000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队“魂灭”的一员。"},
[603803] = {603803, 1000, "Though\u{0020}Hlokk\u{0020}never\u{0020}aspired\u{0020}to\u{0020}be\u{0020}a\u{0020}Driver,\u{0020}she\u{0020}didn't\u{0020}shy\u{0020}away\u{0020}from\u{0020}the\u{0020}possibility\u{0020}either.\u{0020}It\u{0020}was\u{0020}Dr.\u{0020}Alvitr\u{0020}who\u{0020}recognized\u{0020}her\u{0020}potential.\n\nInitially,\u{0020}the\u{0020}doctor\u{0020}hoped\u{0020}to\u{0020}train\u{0020}Hlokk\u{0020}as\u{0020}a\u{0020}successor\u{0020}for\u{0020}the\u{0020}First\u{0020}Laboratory.\u{0020}However,\u{0020}she\u{0020}soon\u{0020}realized\u{0020}that\u{0020}Hlokk's\u{0020}free-spirited\u{0020}nature\u{0020}made\u{0020}her\u{0020}an\u{0020}unsuitable\u{0020}candidate\u{0020}for\u{0020}such\u{0020}responsibility.\u{0020}Entrusting\u{0020}the\u{0020}lab\u{0020}to\u{0020}her\u{0020}would\u{0020}be\u{0020}a\u{0020}catastrophic\u{0020}gamble.\u{0020}Instead,\u{0020}Hlokk's\u{0020}value\u{0020}lay\u{0020}elsewhere.\n\nWhen\u{0020}the\u{0020}Control\u{0020}Division\u{0020}was\u{0020}established\u{0020}to\u{0020}house\u{0020}the\u{0020}dangerous\u{0020}experiment\u{0020}specimens,\u{0020}a\u{0020}skilled\u{0020}researcher\u{0020}was\u{0020}required\u{0020}to\u{0020}oversee\u{0020}its\u{0020}operations,\u{0020}and\u{0020}Hlokk\u{0020}was\u{0020}the\u{0020}perfect\u{0020}choice.\n\nNeither\u{0020}too\u{0020}reckless\u{0020}nor\u{0020}overly\u{0020}cautious,\u{0020}she\u{0020}embodied\u{0020}the\u{0020}curiosity\u{0020}of\u{0020}a\u{0020}true\u{0020}explorer.\u{0020}Titles\u{0020}and\u{0020}positions\u{0020}meant\u{0020}little\u{0020}to\u{0020}her,\u{0020}even\u{0020}when\u{0020}she\u{0020}was\u{0020}dismissed\u{0020}from\u{0020}her\u{0020}role.\u{0020}Her\u{0020}only\u{0020}regret\u{0020}was\u{0020}losing\u{0020}the\u{0020}chance\u{0020}to\u{0020}personally\u{0020}witness\u{0020}the\u{0020}changes\u{0020}happening\u{0020}to\u{0020}the\u{0020}world.", "0", "0", "0", "0", 10038, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{3000}\u{3000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{3000}\u{3000}“魂灭小队中存在着一个幽灵队员——”渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{3000}\u{3000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{3000}\u{3000}“——我可以去睡觉了吗？呜……”\n\u{3000}\u{3000}——是的，她只是懒而已。"},
[603804] = {603804, 2000, "Why\u{0020}do\u{0020}fish\u{0020}bite\u{0020}the\u{0020}hook,\u{0020}you\u{0020}ask?\n\nWho\u{0020}knows?\n\nIt's\u{0020}not\u{0020}really\u{0020}worth\u{0020}overthinking\u{0020}about.\n\nMaybe\u{0020}they\u{0020}just\u{0020}bite\u{0020}it\u{0020}because\u{0020}it's\u{0020}wrapped\u{0020}in\u{0020}food,\n\na\u{0020}free\u{0020}meal\u{0020}delivered\u{0020}to\u{0020}their\u{0020}mouths.\n\nPerhaps\u{0020}it's\u{0020}just\u{0020}instinct.\n\nAs\u{0020}for\u{0020}what\u{0020}happens\u{0020}afterward?\n\nThe\u{0020}fish\u{0020}don't\u{0020}care.\n\nA\u{0020}50%\u{0020}chance\u{0020}to\u{0020}live,\n\na\u{0020}50%\u{0020}chance\u{0020}to\u{0020}die.\n\nThat\u{0020}uncertainty,\u{0020}buried\u{0020}in\u{0020}a\u{0020}fixed\u{0020}probability,\n\nis\u{0020}what\u{0020}truly\u{0020}fascinates\u{0020}me.", "0", "0", "0", "0", 10038, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作战如她所推演的那样进行着，\n\u{3000}\u{3000}原罪的行动早在战争开始前就被她看穿，\n\u{3000}\u{3000}将破局的方法说出之后，\n\u{3000}\u{3000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“领航……”\n\u{3000}\u{3000}“喜欢……”\n\u{3000}\u{3000}“最喜欢了……”"},
[603900] = {603900, 0, "[Name]:Harriet\n[B-day]:May\u{0020}23\n[Compatibility\u{0020}Rate]:88%\n[Height]:40m\n[Squad]:Blackthorn\n[Affiliation]:Maya\u{0020}Branch\n[Interest]:Honing\u{0020}herself\u{0020}through\u{0020}underground\u{0020}boxing\u{0020}matches", "0", "0", "0", "0", 10039, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[603901] = {603901, 100, "\u{3000}\u{3000}Harriet,\u{0020}ID\u{0020}ODY763002.\u{0020}A\u{0020}native\u{0020}of\u{0020}Forenda\u{0020}and\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Blackthorn\u{0020}Squad.\n\u{3000}\u{3000}Harriet\u{0020}is\u{0020}a\u{0020}simple\u{0020}person,\u{0020}her\u{0020}world\u{0020}consists\u{0020}of\u{0020}training\u{0020}and\u{0020}boxing\u{0020}matches.\u{0020}She\u{0020}seems\u{0020}to\u{0020}have\u{0020}her\u{0020}own\u{0020}secret\u{0020}network\u{0020}that\u{0020}keeps\u{0020}her\u{0020}informed\u{0020}of\u{0020}every\u{0020}boxing\u{0020}event\u{0020}happening\u{0020}within\u{0020}Maya,\u{0020}whether\u{0020}official\u{0020}or\u{0020}underground.\u{0020}Ninety\u{0020}percent\u{0020}of\u{0020}those\u{0020}rings\u{0020}report\u{0020}having\u{0020}seen\u{0020}Harriet\u{0020}present\u{0020}-\u{0020}always\u{0020}under\u{0020}her\u{0020}real\u{0020}identity.\n\u{3000}\u{3000}In\u{0020}squad\u{0020}operations,\u{0020}Harriet\u{0020}maintains\u{0020}the\u{0020}same\u{0020}attendance\u{0020}rate\u{0020}she\u{0020}does\u{0020}in\u{0020}boxing.\u{0020}It's\u{0020}hard\u{0020}for\u{0020}ordinary\u{0020}people\u{0020}to\u{0020}imagine\u{0020}how\u{0020}she\u{0020}can\u{0020}walk\u{0020}straight\u{0020}out\u{0020}of\u{0020}an\u{0020}intense\u{0020}free-fight\u{0020}match\u{0020}and\u{0020}still\u{0020}show\u{0020}up\u{0020}for\u{0020}Driver\u{0020}missions\u{0020}at\u{0020}full\u{0020}strength.\u{0020}It's\u{0020}even\u{0020}harder\u{0020}to\u{0020}imagine\u{0020}just\u{0020}how\u{0020}much\u{0020}she\u{0020}loves\u{0020}boxing\u{0020}-\u{0020}enough\u{0020}to\u{0020}step\u{0020}into\u{0020}a\u{0020}dangerous\u{0020}match\u{0020}despite\u{0020}having\u{0020}important\u{0020}duties\u{0020}the\u{0020}very\u{0020}next\u{0020}day.\n\u{3000}\u{3000}Perhaps\u{0020}this\u{0020}is\u{0020}what\u{0020}people\u{0020}call\u{0020}\"discipline\"\u{0020}-\u{0020}a\u{0020}behavioral\u{0020}pattern\u{0020}engraved\u{0020}into\u{0020}her\u{0020}very\u{0020}genes,\u{0020}surpassing\u{0020}habit.\u{0020}To\u{0020}Harriet,\u{0020}boxing\u{0020}matches\u{0020}may\u{0020}simply\u{0020}be\u{0020}her\u{0020}version\u{0020}of\u{0020}\"a\u{0020}glass\u{0020}of\u{0020}milk\u{0020}before\u{0020}bed.\"", "0", "0", "0", "0", 10039, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[603902] = {603902, 500, "\u{3000}\u{3000}Forenda\u{0020}is\u{0020}a\u{0020}remarkable\u{0020}city\u{0020}southeast\u{0020}of\u{0020}Cheston,\u{0020}connected\u{0020}by\u{0020}a\u{0020}major\u{0020}highway\u{0020}that\u{0020}spans\u{0020}the\u{0020}entirety\u{0020}of\u{0020}Maya\u{0020}from\u{0020}east\u{0020}to\u{0020}west.\n\u{3000}\u{3000}What\u{0020}makes\u{0020}Forenda\u{0020}famous\u{0020}in\u{0020}all\u{0020}of\u{0020}Maya\u{0020}is\u{0020}its\u{0020}people.\u{0020}Forenda\u{0020}locals,\u{0020}once\u{0020}they\u{0020}believe\u{0020}in\u{0020}something,\u{0020}exhibit\u{0020}extreme\u{0020}resolve\u{0020}-\u{0020}bordering\u{0020}on\u{0020}stubbornness.\u{0020}They\u{0020}ignore\u{0020}persuasion,\u{0020}charge\u{0020}forward\u{0020}like\u{0020}bulls\u{0020}with\u{0020}their\u{0020}eyes\u{0020}closed,\u{0020}unwilling\u{0020}to\u{0020}yield\u{0020}or\u{0020}argue.\u{0020}They're\u{0020}also\u{0020}notoriously\u{0020}whimsical,\u{0020}acting\u{0020}on\u{0020}sudden\u{0020}impulses\u{0020}that\u{0020}others\u{0020}find\u{0020}incomprehensible,\u{0020}leaving\u{0020}surrounding\u{0020}regions\u{0020}baffled\u{0020}and\u{0020}impressed.\n\u{3000}\u{3000}Harriet\u{0020}and\u{0020}her\u{0020}parents\u{0020}are\u{0020}quintessential\u{0020}Forenda\u{0020}locals—stubborn,\u{0020}amusing,\u{0020}and\u{0020}full\u{0020}of\u{0020}surprises.\n\u{3000}\u{3000}She\u{0020}came\u{0020}from\u{0020}a\u{0020}comfortable\u{0020}household.\u{0020}Her\u{0020}father\u{0020}is\u{0020}a\u{0020}lawyer,\u{0020}her\u{0020}mother\u{0020}a\u{0020}homemaker\u{0020}who\u{0020}crafts\u{0020}handmade\u{0020}items\u{0020}in\u{0020}her\u{0020}spare\u{0020}time.\u{0020}Harriet\u{0020}herself\u{0020}was\u{0020}simply\u{0020}a\u{0020}girl\u{0020}with\u{0020}a\u{0020}bit\u{0020}of\u{0020}personality\u{0020}-\u{0020}nothing\u{0020}more.\n\u{3000}\u{3000}Her\u{0020}life\u{0020}should\u{0020}have\u{0020}remained\u{0020}parallel\u{0020}to\u{0020}boxing\u{0020}forever\u{0020}-\u{0020}until\u{0020}one\u{0020}incident,\u{0020}dismissed\u{0020}by\u{0020}adults\u{0020}as\u{0020}\"kids\u{0020}fighting,\"but\u{0020}in\u{0020}truth\u{0020}a\u{0020}rebellion\u{0020}against\u{0020}bullying.\u{0020}In\u{0020}that\u{0020}moment,\u{0020}something\u{0020}unusual\u{0020}sprouted\u{0020}within\u{0020}Harriet.\u{0020}The\u{0020}intense\u{0020}focus\u{0020}during\u{0020}confrontation,\u{0020}the\u{0020}sting\u{0020}of\u{0020}counterattacking,\u{0020}the\u{0020}surge\u{0020}of\u{0020}adrenaline\u{0020}flooding\u{0020}her\u{0020}senses\u{0020}-\u{0020}it\u{0020}all\u{0020}fascinated\u{0020}her.\u{0020}Even\u{0020}taking\u{0020}a\u{0020}punch\u{0020}herself\u{0020}could\u{0020}not\u{0020}extinguish\u{0020}that\u{0020}electrifying\u{0020}impulse.\n\u{3000}\u{3000}At\u{0020}that\u{0020}moment,\u{0020}Harriet's\u{0020}life\u{0020}veered\u{0020}ninety\u{0020}degrees,\u{0020}intersecting\u{0020}with\u{0020}a\u{0020}new\u{0020}path\u{0020}entirely.\u{0020}She\u{0020}resolved\u{0020}to\u{0020}devote\u{0020}the\u{0020}rest\u{0020}of\u{0020}her\u{0020}life\u{0020}to\u{0020}her\u{0020}fists\u{0020}-\u{0020}and\u{0020}to\u{0020}victory.\n\u{3000}\u{3000}Yet\u{0020}between\u{0020}Harriet\u{0020}and\u{0020}the\u{0020}boxing\u{0020}ring\u{0020}stood\u{0020}a\u{0020}towering\u{0020}wall:\u{0020}her\u{0020}father.\u{0020}No\u{0020}gentle,\u{0020}refined\u{0020}lawyer\u{0020}would\u{0020}ever\u{0020}want\u{0020}to\u{0020}see\u{0020}his\u{0020}sweet\u{0020}daughter\u{0020}tie\u{0020}her\u{0020}hair\u{0020}back,\u{0020}pull\u{0020}on\u{0020}gloves,\u{0020}and\u{0020}trade\u{0020}blows\u{0020}in\u{0020}the\u{0020}ring.\u{0020}But\u{0020}no\u{0020}one\u{0020}expected\u{0020}that\u{0020}the\u{0020}one\u{0020}to\u{0020}knock\u{0020}down\u{0020}that\u{0020}wall\u{0020}would\u{0020}be\u{0020}Harriet’s\u{0020}mother\u{0020}-\u{0020}a\u{0020}gentle,\u{0020}kind-hearted\u{0020}woman.\n\u{3000}\u{3000}It\u{0020}turned\u{0020}out\u{0020}Harriet's\u{0020}mother\u{0020}had\u{0020}been\u{0020}a\u{0020}boxer\u{0020}in\u{0020}her\u{0020}youth,\u{0020}thanks\u{0020}to\u{0020}her\u{0020}own\u{0020}father\u{0020}-\u{0020}Harriet's\u{0020}grandfather\u{0020}-\u{0020}who\u{0020}was\u{0020}also\u{0020}a\u{0020}boxer.\u{0020}Whether\u{0020}his\u{0020}parents\u{0020}had\u{0020}also\u{0020}been\u{0020}boxers\u{0020}is\u{0020}unknown.\n\u{3000}\u{3000}Such\u{0020}is\u{0020}Forenda\u{0020}-\u{0020}an\u{0020}unreasonable\u{0020}place\u{0020}where\u{0020}a\u{0020}lawyer\u{0020}having\u{0020}a\u{0020}boxer\u{0020}for\u{0020}a\u{0020}wife\u{0020}feels\u{0020}strangely\u{0020}natural.\u{0020}No\u{0020}one\u{0020}can\u{0020}guess\u{0020}what\u{0020}kind\u{0020}of\u{0020}miraculous,\u{0020}dramatic\u{0020}love\u{0020}story\u{0020}happened\u{0020}between\u{0020}them\u{0020}-\u{0020}but\u{0020}that\u{0020}is\u{0020}simply\u{0020}Forenda.\n\u{3000}\u{3000}The\u{0020}Forenda\u{0020}spirit\u{0020}manifested\u{0020}clearly\u{0020}here.\u{0020}Under\u{0020}her\u{0020}mother's\u{0020}guidance,\u{0020}Harriet\u{0020}began\u{0020}training\u{0020}in\u{0020}boxing.\u{0020}Her\u{0020}grandfather\u{0020}taught\u{0020}boxing\u{0020}to\u{0020}her\u{0020}mother,\u{0020}and\u{0020}her\u{0020}mother\u{0020}passed\u{0020}that\u{0020}legacy\u{0020}to\u{0020}Harriet.\n\u{3000}\u{3000}From\u{0020}street\u{0020}fights,\u{0020}to\u{0020}underground\u{0020}rings,\u{0020}to\u{0020}official\u{0020}competitions\u{0020}-\u{0020}the\u{0020}name\u{0020}\"Harriet\u{0020}the\u{0020}Boxer\"\u{0020}began\u{0020}spreading\u{0020}throughout\u{0020}southeastern\u{0020}Maya.\n\u{3000}\u{3000}Perhaps\u{0020}she\u{0020}truly\u{0020}would\u{0020}have\u{0020}dedicated\u{0020}her\u{0020}entire\u{0020}life\u{0020}to\u{0020}boxing\u{0020}and\u{0020}victory\u{0020}-\u{0020}had\u{0020}that\u{0020}earthshaking\u{0020}disaster\u{0020}never\u{0020}occurred.", "0", "0", "0", "0", 10039, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[603903] = {603903, 1000, "\u{3000}\u{3000}Forenda\u{0020}lies\u{0020}far\u{0020}from\u{0020}Cheston,\u{0020}even\u{0020}farther\u{0020}than\u{0020}its\u{0020}distance\u{0020}to\u{0020}Danube.\u{0020}Yet\u{0020}even\u{0020}so,\u{0020}the\u{0020}deafening\u{0020}crash\u{0020}of\u{0020}that\u{0020}colossal\u{0020}object\u{0020}striking\u{0020}the\u{0020}ground\u{0020}reached\u{0020}every\u{0020}Forenda\u{0020}ear\u{0020}with\u{0020}chilling\u{0020}clarity.\n\u{3000}\u{3000}Harriet\u{0020}heard\u{0020}it\u{0020}too.\u{0020}That\u{0020}very\u{0020}day,\u{0020}she\u{0020}packed\u{0020}her\u{0020}bags\u{0020}and\u{0020}quietly\u{0020}set\u{0020}off\u{0020}toward\u{0020}Cheston.\u{0020}Maybe\u{0020}she\u{0020}wanted\u{0020}a\u{0020}stronger\u{0020}opponent.\u{0020}Maybe\u{0020}it\u{0020}was\u{0020}just\u{0020}her\u{0020}instinctive\u{0020}kindness\u{0020}-\u{0020}like\u{0020}the\u{0020}day\u{0020}she\u{0020}fought\u{0020}back\u{0020}against\u{0020}bullies\u{0020}for\u{0020}a\u{0020}classmate.\u{0020}Harriet\u{0020}felt\u{0020}she\u{0020}needed\u{0020}to\u{0020}do\u{0020}something\u{0020}during\u{0020}this\u{0020}catastrophe.\u{0020}And\u{0020}so\u{0020}she\u{0020}acted\u{0020}-\u{0020}just\u{0020}as\u{0020}any\u{0020}Forenda\u{0020}local\u{0020}would.\n\u{3000}\u{3000}Of\u{0020}course,\u{0020}her\u{0020}journey\u{0020}failed.\u{0020}The\u{0020}moment\u{0020}Cheston\u{0020}came\u{0020}under\u{0020}attack,\u{0020}the\u{0020}other\u{0020}Maya\u{0020}cities\u{0020}activated\u{0020}emergency\u{0020}protocols,\u{0020}sealing\u{0020}every\u{0020}route\u{0020}to\u{0020}the\u{0020}outside\u{0020}world.\u{0020}Only\u{0020}authorized\u{0020}personnel\u{0020}were\u{0020}allowed\u{0020}through.\n\u{3000}\u{3000}By\u{0020}the\u{0020}time\u{0020}Harriet\u{0020}finally\u{0020}stepped\u{0020}onto\u{0020}Cheston\u{0020}soil,\u{0020}everything\u{0020}had\u{0020}already\u{0020}ended…But\u{0020}the\u{0020}devastated\u{0020}city\u{0020}before\u{0020}her,\u{0020}and\u{0020}the\u{0020}people\u{0020}struggling\u{0020}to\u{0020}rise\u{0020}from\u{0020}the\u{0020}rubble,\u{0020}told\u{0020}her\u{0020}one\u{0020}thing\u{0020}clearly\u{0020}-\u{0020}this\u{0020}was\u{0020}only\u{0020}the\u{0020}beginning.", "0", "0", "0", "0", 10039, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[603904] = {603904, 2000, "\u{3000}\u{3000}The\u{0020}match\u{0020}begins\u{0020}with\u{0020}roaring\u{0020}cries.\n\u{3000}\u{3000}Fists\u{0020}collide\u{0020}against\u{0020}steel.\n\u{3000}\u{3000}The\u{0020}score\u{0020}has\u{0020}long\u{0020}surpassed\u{0020}any\u{0020}record.\n\u{3000}\u{3000}Boxing\u{0020}is\u{0020}not\u{0020}merely\u{0020}a\u{0020}sport.\u{0020}It\u{0020}is\u{0020}the\u{0020}meaning\u{0020}of\u{0020}life.\n\u{3000}\u{3000}Boxing\u{0020}itself\u{0020}is\u{0020}the\u{0020}very\u{0020}reason\u{0020}life\u{0020}exists.\n\u{3000}\u{3000}The\u{0020}ring\u{0020}demands\u{0020}more\u{0020}than\u{0020}sweat\u{0020}and\u{0020}effort.\u{0020}It\u{0020}demands\u{0020}unyielding\u{0020}resolve,\n\u{3000}\u{3000}The\u{0020}courage\u{0020}to\u{0020}throw\u{0020}a\u{0020}punch,\n\u{3000}\u{3000}The\u{0020}tenacity\u{0020}to\u{0020}never\u{0020}yield,\n\u{3000}\u{3000}The\u{0020}determination\u{0020}to\u{0020}die\u{0020}without\u{0020}regret.\n\u{3000}\u{3000}When\u{0020}the\u{0020}final\u{0020}bell\u{0020}rings,\u{0020}When\u{0020}the\u{0020}colossal\u{0020}monster\u{0020}crashes\u{0020}to\u{0020}the\u{0020}ground.\n\u{3000}\u{3000}Stand\u{0020}tall,\u{0020}Boxer.\u{0020}Raise\u{0020}your\u{0020}fists\u{0020}toward\u{0020}the\u{0020}next\u{0020}titan,\n\u{3000}\u{3000}And\u{0020}strike!", "0", "0", "0", "0", 10039, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[604000] = {604000, 0, "[Name]:\u{0020}Mini\u{0020}Julius\u{0020}Unit-01\u{0020}\n[B-day]:\u{0020}Feb.\u{0020}13\u{0020}\n[Transformation\u{0020}Core\u{0020}Proficiency]:\u{0020}100%\u{0020}\n[Height]:\u{0020}41m\u{0020}\n[Squad]:\u{0020}Romance\u{0020}Unconfirmed\u{0020}\n[Affiliation]:\u{0020}Danube\u{0020}Branch\u{0020}\n[Hobbies]:\u{0020}Absorbing\u{0020}human\u{0020}emotions", "0", "0", "0", "0", 10040, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[604001] = {604001, 100, "\u{3000}\u{3000}\"Romance\u{0020}Unconfirmed\"\u{0020}is\u{0020}the\u{0020}name\u{0020}of\u{0020}a\u{0020}special\u{0020}operations\u{0020}squad\u{0020}temporarily\u{0020}formed\u{0020}on\u{0020}Valentine's\u{0020}Day.\n\u{3000}\u{3000}No\u{0020}one\u{0020}in\u{0020}the\u{0020}squad\u{0020}is\u{0020}able\u{0020}to\u{0020}properly\u{0020}recognize\u{0020}their\u{0020}own\u{0020}romantic\u{0020}feelings.\n\u{3000}\u{3000}\"So\u{0020}it\u{0020}should\u{0020}be\u{0020}fine\u{0020}for\u{0020}me\u{0020}to\u{0020}be\u{0020}in\u{0020}this\u{0020}squad\u{0020}too,\u{0020}right?\u{0020}Even\u{0020}though\u{0020}it\u{0020}is\u{0020}already\u{0020}completely\u{0020}different\u{0020}from\u{0020}a\u{0020}standard\u{0020}4-person\u{0020}squad.\"\u{0020}Mini\u{0020}Julius\u{0020}Unit-01\u{0020}said\u{0020}this.\u{0020}No--\u{0020}actually,\u{0020}it\u{0020}was\u{0020}little\u{0020}red\u{0020}inside\u{0020}the\u{0020}giant\u{0020}robot\u{0020}who\u{0020}said\u{0020}it.\u{0020}\"Mini\u{0020}Julius\u{0020}Unit-01\u{0020}was\u{0020}made\u{0020}from\u{0020}Miss\u{0020}Julius's\u{0020}memories,\u{0020}so\u{0020}she\u{0020}can\u{0020}be\u{0020}considered\u{0020}Julius\u{0020}too.\"\n\u{3000}\u{3000}\"If\u{0020}we\u{0020}follow\u{0020}that\u{0020}logic,\u{0020}then\u{0020}as\u{0020}her\u{0020}creator,\u{0020}I\u{0020}would\u{0020}be\u{0020}Julius's\u{0020}father.\"\u{0020}Dr.\u{0020}Red's\u{0020}voice\u{0020}also\u{0020}came\u{0020}from\u{0020}inside\u{0020}the\u{0020}giant\u{0020}robot.\n\u{3000}\u{3000}\"Do\u{0020}not\u{0020}try\u{0020}to\u{0020}claim\u{0020}that\u{0020}kind\u{0020}of\u{0020}relationship\u{0020}with\u{0020}me...\u{0020}You\u{0020}only\u{0020}created\u{0020}Mini\u{0020}Julius\u{0020}because\u{0020}you\u{0020}were\u{0020}driven\u{0020}by\u{0020}your\u{0020}own\u{0020}desires,\u{0020}just\u{0020}like\u{0020}those\u{0020}people\u{0020}who\u{0020}drown\u{0020}in\u{0020}lewd\u{0020}urges\u{0020}and\u{0020}only\u{0020}know\u{0020}how\u{0020}to\u{0020}fire\u{0020}something\u{0020}off.\u{0020}You\u{0020}simply\u{0020}wanted\u{0020}to\u{0020}pilot\u{0020}a\u{0020}robot\u{0020}like\u{0020}Mini\u{0020}Julius\u{0020}yourself.\"\u{0020}little\u{0020}red\u{0020}refuted\u{0020}her\u{0020}with\u{0020}righteous\u{0020}indignation.\n\u{3000}\u{3000}And\u{0020}so,\u{0020}these\u{0020}two-in-one\u{0020}Drivers\u{0020}began\u{0020}their\u{0020}own\u{0020}battle.\n\u{3000}\u{3000}Come\u{0020}to\u{0020}think\u{0020}of\u{0020}it,\u{0020}does\u{0020}AEGIS\u{0020}have\u{0020}a\u{0020}few\u{0020}too\u{0020}many\u{0020}two-in-one\u{0020}Drivers?", "0", "0", "0", "0", 10040, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[604002] = {604002, 500, "\u{3000}\u{3000}An\u{0020}experimental\u{0020}robot\u{0020}with\u{0020}a\u{0020}100%\u{0020}Compatibility\u{0020}Rate,\u{0020}created\u{0020}by\u{0020}Dr.\u{0020}Red\u{0020}after\u{0020}stealing\u{0020}part\u{0020}of\u{0020}Julius's\u{0020}\"age\"\u{0020}and\u{0020}fusing\u{0020}it\u{0020}with\u{0020}the\u{0020}Drivers'\u{0020}\"feelings.\"\u{0020}In\u{0020}other\u{0020}words,\u{0020}it\u{0020}does\u{0020}not\u{0020}actually\u{0020}have\u{0020}consciousness.\u{0020}I\u{0020}am\u{0020}writing\u{0020}this\u{0020}down\u{0020}specifically\u{0020}to\u{0020}remind\u{0020}myself,\u{0020}because\u{0020}this\u{0020}point\u{0020}is\u{0020}extremely\u{0020}important.\u{0020}Whenever\u{0020}Mini\u{0020}Julius\u{0020}Unit-01\u{0020}causes\u{0020}trouble,\u{0020}red,\u{0020}who\u{0020}serves\u{0020}as\u{0020}its\u{0020}Driver,\u{0020}always\u{0020}uses\u{0020}strange\u{0020}excuses\u{0020}to\u{0020}shift\u{0020}the\u{0020}blame,\u{0020}including,\u{0020}but\u{0020}not\u{0020}limited\u{0020}to:\n\u{3000}\u{3000}\"I\u{0020}cannot\u{0020}control\u{0020}it\u{0020}at\u{0020}all.\"\n\u{3000}\u{3000}\"That\u{0020}was\u{0020}not\u{0020}me.\u{0020}My\u{0020}Compatibility\u{0020}Rate\u{0020}with\u{0020}Unit-01\u{0020}is\u{0020}very\u{0020}low,\u{0020}so\u{0020}how\u{0020}could\u{0020}I\u{0020}possibly\u{0020}control\u{0020}it\u{0020}well\u{0020}enough\u{0020}to\u{0020}perform\u{0020}such\u{0020}a\u{0020}difficult\u{0020}move?\"\n\u{3000}\u{3000}\"It\u{0020}has\u{0020}a\u{0020}consciousness\u{0020}of\u{0020}its\u{0020}own.\u{0020}It\u{0020}wants\u{0020}to\u{0020}become\u{0020}a\u{0020}real\u{0020}human\u{0020}too.\"\n\u{3000}\u{3000}\"It\u{0020}is\u{0020}rebelling\u{0020}against\u{0020}me!\u{0020}Help!\"\n\u{3000}\u{3000}But\u{0020}in\u{0020}reality,\u{0020}aside\u{0020}from\u{0020}indiscriminately\u{0020}absorbing\u{0020}the\u{0020}emotions\u{0020}generated\u{0020}around\u{0020}it,\u{0020}Mini\u{0020}Julius\u{0020}Unit-01\u{0020}has\u{0020}almost\u{0020}no\u{0020}flaws.\n\u{3000}\u{3000}This\u{0020}brings\u{0020}me\u{0020}to\u{0020}another\u{0020}point.\u{0020}Since\u{0020}Mini\u{0020}Julius\u{0020}Unit-01\u{0020}absorbs\u{0020}the\u{0020}emotions\u{0020}generated\u{0020}by\u{0020}its\u{0020}Driver,\u{0020}if\u{0020}an\u{0020}ordinary\u{0020}person\u{0020}were\u{0020}to\u{0020}pilot\u{0020}it,\u{0020}they\u{0020}might\u{0020}become\u{0020}emotionless\u{0020}after\u{0020}a\u{0020}few\u{0020}months.\n\u{3000}\u{3000}Joy,\u{0020}anger,\u{0020}sorrow,\u{0020}fear,\u{0020}love,\u{0020}hatred,\u{0020}and\u{0020}desire.\u{0020}Almost\u{0020}every\u{0020}human\u{0020}emotion\u{0020}is\u{0020}its\u{0020}prey.\n\u{3000}\u{3000}Speaking\u{0020}of\u{0020}that,\u{0020}I\u{0020}cannot\u{0020}help\u{0020}thinking\u{0020}of\u{0020}the\u{0020}names\u{0020}Dr.\u{0020}Stephanie\u{0020}gave\u{0020}to\u{0020}the\u{0020}Great\u{0020}Sins:\u{0020}Envy,\u{0020}Gluttony,\u{0020}Lust...\n\u{3000}\u{3000}Could\u{0020}Dr.\u{0020}Red\u{0020}have\u{0020}been\u{0020}trying\u{0020}to\u{0020}use\u{0020}this\u{0020}robot\u{0020}to\u{0020}defeat\u{0020}those\u{0020}Great\u{0020}Sins...?\u{0020}Unfortunately,\u{0020}the\u{0020}Great\u{0020}Sins\u{0020}do\u{0020}not\u{0020}seem\u{0020}to\u{0020}actually\u{0020}be\u{0020}embodiments\u{0020}of\u{0020}the\u{0020}seven\u{0020}deadly\u{0020}sins.\u{0020}They\u{0020}are\u{0020}simply\u{0020}called\u{0020}that...\u{0020}Instead,\u{0020}this\u{0020}machine\u{0020}has\u{0020}ended\u{0020}up\u{0020}as\u{0020}a\u{0020}dedicated\u{0020}human-emotion\u{0020}hunting\u{0020}machine,\u{0020}like\u{0020}an\u{0020}oversized\u{0020}Envy.\n\u{3000}\u{3000}Because\u{0020}of\u{0020}this\u{0020}flaw,\u{0020}Mini\u{0020}Julius\u{0020}is\u{0020}unsuitable\u{0020}for\u{0020}mass\u{0020}production.\u{0020}The\u{0020}one\u{0020}and\u{0020}only\u{0020}Unit-01\u{0020}is\u{0020}now\u{0020}entrusted\u{0020}to\u{0020}red,\u{0020}who\u{0020}is\u{0020}also\u{0020}a\u{0020}robot.\u{0020}According\u{0020}to\u{0020}Dr.\u{0020}Red,\u{0020}this\u{0020}is\u{0020}because\u{0020}Unit-01\u{0020}cannot\u{0020}beat\u{0020}red\u{0020}when\u{0020}it\u{0020}comes\u{0020}to\u{0020}stealing\u{0020}emotions.\n\u{3000}\u{3000}When\u{0020}you\u{0020}think\u{0020}about\u{0020}it\u{0020}that\u{0020}way,\u{0020}red\u{0020}is\u{0020}pretty\u{0020}scary\u{0020}too.", "0", "0", "0", "0", 10040, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[604003] = {604003, 1000, "\u{3000}\u{3000}Mini\u{0020}Julius\u{0020}Unit-01\u{0020}is\u{0020}very\u{0020}popular.\n\u{3000}\u{3000}More\u{0020}accurately,\u{0020}she\u{0020}is\u{0020}very\u{0020}popular\u{0020}among\u{0020}the\u{0020}robots.\n\u{3000}\u{3000}For\u{0020}example,\u{0020}D-b2\u{0020}often\u{0020}helps\u{0020}Mini\u{0020}Julius\u{0020}clean\u{0020}her\u{0020}frame,\u{0020}Type\u{0020}Z\u{0020}sometimes\u{0020}brings\u{0020}energy\u{0020}she\u{0020}thinks\u{0020}tastes\u{0020}good\u{0020}to\u{0020}share\u{0020}with\u{0020}Mini\u{0020}Julius,\u{0020}and\u{0020}Alpha\u{0020}often\u{0020}comes\u{0020}here\u{0020}to\u{0020}sit\u{0020}on\u{0020}Mini\u{0020}Julius,\u{0020}staying\u{0020}there\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\n\u{3000}\u{3000}Out\u{0020}of\u{0020}curiosity,\u{0020}I\u{0020}asked\u{0020}Alpha\u{0020}and\u{0020}the\u{0020}others\u{0020}why\u{0020}they\u{0020}did\u{0020}this.\n\u{3000}\u{3000}\"I\u{0020}recently\u{0020}learned\u{0020}that\u{0020}babies\u{0020}need\u{0020}to\u{0020}be\u{0020}taken\u{0020}care\u{0020}of.\"\n\u{3000}\u{3000}\"Because\u{0020}she\u{0020}is\u{0020}my\u{0020}junior.\u{0020}It\u{0020}is\u{0020}only\u{0020}natural\u{0020}for\u{0020}a\u{0020}senior\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}her\u{0020}junior,\u{0020}right?\u{0020}I\u{0020}used\u{0020}to\u{0020}think\u{0020}I\u{0020}was\u{0020}the\u{0020}youngest\u{0020}one\u{0020}in\u{0020}the\u{0020}family,\u{0020}so\u{0020}I\u{0020}am\u{0020}very\u{0020}happy\u{0020}to\u{0020}have\u{0020}a\u{0020}cute\u{0020}junior\u{0020}now.\"\n\u{3000}\u{3000}\"Alpha\u{0020}does\u{0020}not\u{0020}want\u{0020}her\u{0020}to\u{0020}feel\u{0020}lonely.\u{0020}A\u{0020}childhood\u{0020}without\u{0020}anyone\u{0020}by\u{0020}your\u{0020}side\u{0020}is\u{0020}too\u{0020}sad.\u{0020}You\u{0020}humans\u{0020}do\u{0020}this\u{0020}too,\u{0020}right?\"\n\u{3000}\u{3000}Hmm...?\u{0020}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}Mini\u{0020}Julius...\u{0020}actually\u{0020}has\u{0020}a\u{0020}consciousness\u{0020}of\u{0020}her\u{0020}own?", "0", "0", "0", "0", 10040, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[604004] = {604004, 2000, "\u{3000}\u{3000}A\u{0020}robot\u{0020}that\u{0020}inherited\u{0020}Julius's\u{0020}feelings.\n\u{3000}\u{3000}That\u{0020}is\u{0020}Mini\u{0020}Julius.\n\u{3000}\u{3000}But\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}she\u{0020}also\u{0020}inherited\u{0020}Julius's\u{0020}personality.\n\u{3000}\u{3000}That\u{0020}personality\u{0020}that\u{0020}keeps\u{0020}her\u{0020}own\u{0020}\"affection\"\u{0020}suppressed\u{0020}deep\u{0020}inside.\n\u{3000}\u{3000}So\u{0020}she\u{0020}simply\u{0020}watches\u{0020}and\u{0020}protects\u{0020}in\u{0020}silence.\n\u{3000}\u{3000}No,\u{0020}actually,\u{0020}she\u{0020}is\u{0020}simply\u{0020}thinking.\n\u{3000}\u{3000}\"When\u{0020}would\u{0020}be\u{0020}the\u{0020}best\u{0020}time\u{0020}to\u{0020}start\u{0020}talking?\"\n\u{3000}\u{3000}\"Would\u{0020}speaking\u{0020}all\u{0020}of\u{0020}a\u{0020}sudden\u{0020}scare\u{0020}Navigator?\"\n\u{3000}\u{3000}\"I\u{0020}feel\u{0020}like\u{0020}I\u{0020}missed\u{0020}the\u{0020}best\u{0020}timing\u{0020}to\u{0020}start\u{0020}talking.\"\n\u{3000}\u{3000}And\u{0020}so,\u{0020}today\u{0020}too,\u{0020}she\u{0020}waits.", "0", "0", "0", "0", 10040, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[604100] = {604100, 0, "[Name]\u{0020}Alaita\n\u{0020}[B-day]\u{0020}July\u{0020}29\n\u{0020}[Transformation\u{0020}Core\u{0020}Compatibility]\u{0020}82%\n\u{0020}[Height]\u{0020}37m\n\u{0020}[Unit]\u{0020}Torch\n\u{0020}[Affiliation]\u{0020}New\u{0020}Cheston\n\u{0020}[Hobbies]\u{0020}Alcohol\u{0020}and\u{0020}Tobacco", "0", "0", "0", "0", 10041, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[604101] = {604101, 100, "\u{3000}\u{3000}As\u{0020}the\u{0020}deputy\u{0020}officer\u{0020}of\u{0020}New\u{0020}Cheston,\u{0020}Alaita's\u{0020}work\u{0020}can\u{0020}basically\u{0020}be\u{0020}summed\u{0020}up\u{0020}in\u{0020}one\u{0020}sentence:\u{0020}assist\u{0020}the\u{0020}Administrator\u{0020}of\u{0020}New\u{0020}Cheston,\u{0020}Charlissa\u{0020}de\u{0020}Roland,\u{0020}and\u{0020}make\u{0020}sure\u{0020}her\u{0020}body\u{0020}is\u{0020}not\u{0020}crushed\u{0020}under\u{0020}the\u{0020}weight\u{0020}of\u{0020}her\u{0020}heavy\u{0020}workload.\n\u{3000}\u{3000}Alaita\u{0020}seems\u{0020}to\u{0020}have\u{0020}been\u{0020}good\u{0020}at\u{0020}this\u{0020}kind\u{0020}of\u{0020}work\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\n\u{3000}\u{3000}As\u{0020}a\u{0020}vice\u{0020}class\u{0020}president,\u{0020}as\u{0020}a\u{0020}vice-captain,\u{0020}as\u{0020}the\u{0020}city\u{0020}administrator's\u{0020}assistant--she\u{0020}has\u{0020}always\u{0020}held\u{0020}similar\u{0020}positions,\u{0020}serving\u{0020}as\u{0020}the\u{0020}team's\u{0020}number\u{0020}two\u{0020}and\u{0020}supporting\u{0020}the\u{0020}core\u{0020}figure\u{0020}of\u{0020}the\u{0020}team.\n\u{3000}\u{3000}And\u{0020}then,\u{0020}she\u{0020}witnesses\u{0020}their\u{0020}deaths.\n\u{3000}\u{3000}\"Everyone\u{0020}who\u{0020}wanted\u{0020}to\u{0020}become\u{0020}a\u{0020}Hero\u{0020}is\u{0020}dead.\u{0020}Navigator\u{0020}is\u{0020}dead,\u{0020}and\u{0020}Captain\u{0020}Dolores\u{0020}is\u{0020}dead\u{0020}too.\"\n\u{3000}\u{3000}Those\u{0020}words\u{0020}are\u{0020}undoubtedly\u{0020}what\u{0020}she\u{0020}truly\u{0020}feels.\n\u{3000}\u{3000}As\u{0020}an\u{0020}observer,\u{0020}as\u{0020}a\u{0020}witness,\u{0020}and\u{0020}as\u{0020}a\u{0020}survivor,\u{0020}she\u{0020}has\u{0020}already\u{0020}witnessed\u{0020}more\u{0020}than\u{0020}enough\u{0020}death.\u{0020}The\u{0020}heroes\u{0020}who\u{0020}fell\u{0020}one\u{0020}after\u{0020}another\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}have\u{0020}become\u{0020}scars\u{0020}in\u{0020}her\u{0020}heart\u{0020}that\u{0020}can\u{0020}never\u{0020}be\u{0020}smoothed\u{0020}away.", "0", "0", "0", "0", 10041, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[604102] = {604102, 500, "\u{3000}\u{3000}As\u{0020}someone\u{0020}who\u{0020}only\u{0020}became\u{0020}an\u{0020}official\u{0020}Driver\u{0020}after\u{0020}the\u{0020}\"Saar\u{0020}City\u{0020}Incident,\"\u{0020}Alaita\u{0020}is,\u{0020}in\u{0020}a\u{0020}sense,\u{0020}one\u{0020}of\u{0020}the\u{0020}last\u{0020}Drivers\u{0020}of\u{0020}the\u{0020}\"AEGIS\u{0020}era.\"\n\u{3000}\u{3000}The\u{0020}final\u{0020}generation\u{0020}of\u{0020}Drivers,\u{0020}the\u{0020}last\u{0020}Drivers--even\u{0020}terms\u{0020}like\u{0020}these\u{0020}would\u{0020}not\u{0020}be\u{0020}entirely\u{0020}inappropriate\u{0020}to\u{0020}describe\u{0020}her,\u{0020}though\u{0020}of\u{0020}course,\u{0020}she\u{0020}herself\u{0020}would\u{0020}most\u{0020}likely\u{0020}not\u{0020}be\u{0020}happy\u{0020}to\u{0020}be\u{0020}called\u{0020}that.\n\u{3000}\u{3000}After\u{0020}all,\u{0020}such\u{0020}titles\u{0020}are\u{0020}like\u{0020}reminders\u{0020}telling\u{0020}her\u{0020}that\u{0020}humanity\u{0020}has\u{0020}already\u{0020}failed.\n\u{3000}\u{3000}She\u{0020}witnessed\u{0020}the\u{0020}shattering\u{0020}of\u{0020}AEGIS,\u{0020}the\u{0020}fall\u{0020}of\u{0020}heroes,\u{0020}and\u{0020}the\u{0020}apocalyptic\u{0020}sight\u{0020}of\u{0020}humanity\u{0020}displaced\u{0020}and\u{0020}scattered.\u{0020}Maya,\u{0020}Danube,\u{0020}Katya,\u{0020}Kyushu...\u{0020}She\u{0020}took\u{0020}part\u{0020}in\u{0020}almost\u{0020}every\u{0020}war\u{0020}where\u{0020}a\u{0020}human\u{0020}stronghold\u{0020}fell,\u{0020}witnessing\u{0020}humanity's\u{0020}defeat\u{0020}again\u{0020}and\u{0020}again.\n\u{3000}\u{3000}The\u{0020}wish\u{0020}to\u{0020}protect\u{0020}her\u{0020}hometown,\u{0020}the\u{0020}wish\u{0020}to\u{0020}protect\u{0020}humanity--those\u{0020}noble\u{0020}ideals\u{0020}burst\u{0020}before\u{0020}the\u{0020}ashen\u{0020}reality\u{0020}like\u{0020}soap\u{0020}bubbles\u{0020}rising\u{0020}into\u{0020}the\u{0020}sky.\u{0020}When\u{0020}the\u{0020}Ark\u{0020}of\u{0020}Kyushu\u{0020}fell\u{0020}from\u{0020}the\u{0020}heavens,\u{0020}she\u{0020}realized\u{0020}that\u{0020}humanity\u{0020}had\u{0020}already\u{0020}lost\u{0020}every\u{0020}possibility\u{0020}of\u{0020}turning\u{0020}the\u{0020}situation\u{0020}around.\n\u{3000}\u{3000}From\u{0020}that\u{0020}day\u{0020}on,\u{0020}Alaita's\u{0020}heart\u{0020}had\u{0020}already\u{0020}given\u{0020}up.\n\u{3000}\u{3000}The\u{0020}sword\u{0020}had\u{0020}rusted,\u{0020}and\u{0020}the\u{0020}shield's\u{0020}paint\u{0020}had\u{0020}peeled.\u{0020}Of\u{0020}course,\u{0020}equipment\u{0020}transformed\u{0020}from\u{0020}Nimbus\u{0020}energy\u{0020}could\u{0020}never\u{0020}actually\u{0020}deteriorate\u{0020}in\u{0020}such\u{0020}a\u{0020}way--but\u{0020}whenever\u{0020}she\u{0020}was\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}such\u{0020}thoughts\u{0020}would\u{0020}always\u{0020}come\u{0020}to\u{0020}her.\n\u{3000}\u{3000}Alaita\u{0020}no\u{0020}longer\u{0020}knew\u{0020}what\u{0020}she\u{0020}was\u{0020}fighting\u{0020}for.\n\u{3000}\u{3000}Perhaps\u{0020}giving\u{0020}up\u{0020}like\u{0020}this\u{0020}would\u{0020}be\u{0020}better.\n\u{3000}\u{3000}If\u{0020}the\u{0020}ending\u{0020}was\u{0020}already\u{0020}decided,\u{0020}then\u{0020}rather\u{0020}than\u{0020}struggling\u{0020}so\u{0020}ugly\u{0020}and\u{0020}desperately\u{0020}on\u{0020}the\u{0020}verge\u{0020}of\u{0020}death,\u{0020}choosing\u{0020}a\u{0020}way\u{0020}to\u{0020}die\u{0020}that\u{0020}she\u{0020}herself\u{0020}considered\u{0020}beautiful\u{0020}might\u{0020}better\u{0020}suit\u{0020}Alaita's\u{0020}aesthetics.\n\u{3000}\u{3000}But\u{0020}she\u{0020}could\u{0020}not\u{0020}do\u{0020}it.\n\u{3000}\u{3000}She\u{0020}could\u{0020}not\u{0020}abandon\u{0020}herself.\u{0020}She\u{0020}could\u{0020}not\u{0020}end\u{0020}herself.\n\u{3000}\u{3000}The\u{0020}honor\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}and\u{0020}the\u{0020}responsibility\u{0020}inherited\u{0020}from\u{0020}Captain\u{0020}Dolores,\u{0020}would\u{0020}not\u{0020}allow\u{0020}her\u{0020}to\u{0020}give\u{0020}up\u{0020}on\u{0020}herself.\u{0020}Even\u{0020}if\u{0020}her\u{0020}heart\u{0020}had\u{0020}already\u{0020}given\u{0020}up,\u{0020}her\u{0020}body\u{0020}was\u{0020}still\u{0020}fighting\u{0020}by\u{0020}inertia.\n\u{3000}\u{3000}This\u{0020}is\u{0020}torment.\u{0020}An\u{0020}endless\u{0020}hell\u{0020}with\u{0020}no\u{0020}end\u{0020}in\u{0020}sight.", "0", "0", "0", "0", 10041, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[604103] = {604103, 1000, "\u{3000}\u{3000}The\u{0020}founding\u{0020}of\u{0020}New\u{0020}Cheston\u{0020}is\u{0020}a\u{0020}kind\u{0020}of\u{0020}salvation\u{0020}for\u{0020}Alaita.\n\u{3000}\u{3000}Perhaps\u{0020}Charlissa\u{0020}de\u{0020}Roland\u{0020}only\u{0020}chose\u{0020}Alaita\u{0020}as\u{0020}her\u{0020}deputy\u{0020}officer\u{0020}to\u{0020}assist\u{0020}her\u{0020}because\u{0020}there\u{0020}was\u{0020}no\u{0020}one\u{0020}else\u{0020}available,\u{0020}but\u{0020}Alaita\u{0020}does\u{0020}not\u{0020}mind\u{0020}that.\n\u{3000}\u{3000}She\u{0020}simply\u{0020}hopes\u{0020}to\u{0020}have\u{0020}a\u{0020}place\u{0020}to\u{0020}belong.\n\u{3000}\u{3000}She\u{0020}does\u{0020}not\u{0020}believe\u{0020}New\u{0020}Cheston\u{0020}can\u{0020}become\u{0020}humanity's\u{0020}hope,\u{0020}but\u{0020}she\u{0020}does\u{0020}feel\u{0020}that\u{0020}it\u{0020}is\u{0020}her\u{0020}final\u{0020}place\u{0020}to\u{0020}belong.\n\u{3000}\u{3000}In\u{0020}this\u{0020}way,\u{0020}before\u{0020}her\u{0020}life\u{0020}reaches\u{0020}its\u{0020}end,\u{0020}she\u{0020}has\u{0020}gained\u{0020}a\u{0020}clear\u{0020}goal--to\u{0020}fight\u{0020}in\u{0020}order\u{0020}to\u{0020}protect\u{0020}New\u{0020}Cheston.\n\u{3000}\u{3000}The\u{0020}call\u{0020}to\u{0020}counterattack?\u{0020}Humanity's\u{0020}future?\u{0020}There\u{0020}is\u{0020}no\u{0020}longer\u{0020}any\u{0020}room\u{0020}in\u{0020}her\u{0020}heart\u{0020}for\u{0020}such\u{0020}things.\n\u{3000}\u{3000}Assisting\u{0020}Charlissa\u{0020}de\u{0020}Roland\u{0020}and\u{0020}protecting\u{0020}New\u{0020}Cheston--this\u{0020}is\u{0020}Alaita's\u{0020}final\u{0020}mission\u{0020}as\u{0020}a\u{0020}human,\u{0020}and\u{0020}as\u{0020}a\u{0020}Driver.\u{0020}A\u{0020}mission\u{0020}she\u{0020}absolutely\u{0020}cannot\u{0020}fail\u{0020}before\u{0020}her\u{0020}life\u{0020}comes\u{0020}to\u{0020}an\u{0020}end.", "0", "0", "0", "0", 10041, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[604104] = {604104, 2000, "\u{3000}\u{3000}The\u{0020}cheap\u{0020}canned\u{0020}beer\u{0020}has\u{0020}already\u{0020}run\u{0020}dry,\u{0020}and\u{0020}the\u{0020}headache\u{0020}from\u{0020}her\u{0020}hangover\u{0020}is\u{0020}warning\u{0020}her\u{0020}not\u{0020}to\u{0020}do\u{0020}anything\u{0020}stupid\u{0020}again.\n\u{3000}\u{3000}The\u{0020}water\u{0020}in\u{0020}the\u{0020}bathtub\u{0020}has\u{0020}gone\u{0020}completely\u{0020}cold,\u{0020}clearing\u{0020}her\u{0020}head\u{0020}slightly\u{0020}and\u{0020}reminding\u{0020}her\u{0020}that\u{0020}she\u{0020}still\u{0020}has\u{0020}work\u{0020}to\u{0020}do\u{0020}today.\n\u{3000}\u{3000}When\u{0020}she\u{0020}lowers\u{0020}her\u{0020}head,\u{0020}through\u{0020}the\u{0020}mirror-smooth\u{0020}surface\u{0020}of\u{0020}the\u{0020}water,\u{0020}she\u{0020}sees\u{0020}herself\u{0020}as\u{0020}she\u{0020}is\u{0020}now.\n\u{3000}\u{3000}Her\u{0020}red\u{0020}hair,\u{0020}which\u{0020}once\u{0020}looked\u{0020}as\u{0020}though\u{0020}it\u{0020}had\u{0020}been\u{0020}rinsed\u{0020}in\u{0020}blood,\u{0020}has\u{0020}faded.\u{0020}Now,\u{0020}she\u{0020}is\u{0020}no\u{0020}longer\u{0020}worthy\u{0020}of\u{0020}bearing\u{0020}the\u{0020}name\u{0020}\"Siren.\"\n\u{3000}\u{3000}\"I--\"\u{0020}she\u{0020}murmurs\u{0020}softly.\u{0020}\"Am\u{0020}I...\u{0020}an\u{0020}utter\u{0020}failure?\"\n\u{3000}\u{3000}No\u{0020}one\u{0020}can\u{0020}answer\u{0020}her\u{0020}question.", "0", "0", "0", "0", 10041, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[604200] = {604200, 0, "[Name]\u{0020}Shushu\u{0020}Suruga\n[Compatibility\u{0020}Rate]\u{0020}???\n[Height\u{0020}after\u{0020}Gigantification]\u{0020}37m\n[Squad]\u{0020}Demon\u{0020}Defense\u{0020}Force\n[Affiliation]\u{0020}Others\n[Birthday]\u{0020}November\u{0020}13", "0", "0", "0", "0", 10042, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[604201] = {604201, 100, "Shushu\u{0020}Suruga,\u{0020}a\u{0020}lively,\u{0020}curious\u{0020}member\u{0020}of\u{0020}the\u{0020}7th\u{0020}Squad,\u{0020}with\u{0020}a\u{0020}passion\u{0020}for\u{0020}video\u{0020}games.\n\nAmong\u{0020}the\u{0020}squad,\u{0020}Shushu\u{0020}stands\u{0020}out\u{0020}as\u{0020}a\u{0020}unique\u{0020}case.\u{0020}Born\u{0020}into\u{0020}an\u{0020}ordinary\u{0020}family\u{0020}as\u{0020}the\u{0020}youngest\u{0020}of\u{0020}three\u{0020}sisters,\u{0020}she\u{0020}grew\u{0020}up\u{0020}without\u{0020}the\u{0020}presence\u{0020}of\u{0020}her\u{0020}father.\u{0020}From\u{0020}elementary\u{0020}through\u{0020}high\u{0020}school,\u{0020}she\u{0020}attended\u{0020}all-girls\u{0020}schools.\u{0020}In\u{0020}a\u{0020}way,\u{0020}it\u{0020}is\u{0020}precisely\u{0020}this\u{0020}ordinariness\u{0020}that\u{0020}makes\u{0020}her\u{0020}so\u{0020}special.\n\nWithout\u{0020}an\u{0020}excellent\u{0020}profile,\u{0020}Shushu\u{0020}joined\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}for\u{0020}one\u{0020}simple\u{0020}reason:\u{0020}to\u{0020}chase\u{0020}the\u{0020}thrills\u{0020}and\u{0020}spills.\n\nPeach\u{0020}grants\u{0020}her\u{0020}Paradigm\u{0020}Shift,\u{0020}the\u{0020}ability\u{0020}to\u{0020}change\u{0020}her\u{0020}body\u{0020}size\u{0020}(of\u{0020}course,\u{0020}her\u{0020}clothes\u{0020}accordingly)\u{0020}at\u{0020}will.\u{0020}Once\u{0020}activated,\u{0020}her\u{0020}size\u{0020}could\u{0020}dwarf\u{0020}the\u{0020}7th\u{0020}Squad's\u{0020}dorm,\u{0020}wielding\u{0020}overwhelming\u{0020}raw\u{0020}strength\u{0020}at\u{0020}the\u{0020}cost\u{0020}of\u{0020}tremendous\u{0020}energy\u{0020}consumption.", "0", "0", "0", "0", 10042, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[604202] = {604202, 500, "Shushu\u{0020}Suruga\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}quickest\u{0020}of\u{0020}the\u{0020}six\u{0020}otherworldly\u{0020}warrioresses\u{0020}to\u{0020}take\u{0020}in\u{0020}the\u{0020}entire\u{0020}\"Isekai\"\u{0020}situation,\u{0020}or\u{0020}perhaps\u{0020}it's\u{0020}more\u{0020}accurate\u{0020}to\u{0020}say\u{0020}she's\u{0020}thrilled\u{0020}by\u{0020}it.\u{0020}Maybe\u{0020}it's\u{0020}no\u{0020}surprise:\u{0020}after\u{0020}all,\u{0020}she\u{0020}joined\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}in\u{0020}the\u{0020}first\u{0020}place\u{0020}to\u{0020}chase\u{0020}excitement,\u{0020}and\u{0020}crossing\u{0020}into\u{0020}another\u{0020}world\u{0020}certainly\u{0020}delivers\u{0020}plenty\u{0020}of\u{0020}that.\n\nThat\u{0020}said,\u{0020}Shushu\u{0020}has\u{0020}her\u{0020}gripe:\u{0020}her\u{0020}personal\u{0020}ability,\u{0020}which\u{0020}she\u{0020}takes\u{0020}pride\u{0020}in,\u{0020}couldn't\u{0020}stand\u{0020}out\u{0020}in\u{0020}a\u{0020}world\u{0020}where\u{0020}gigiantification\u{0020}is\u{0020}the\u{0020}main\u{0020}way\u{0020}of\u{0020}how\u{0020}Drivers\u{0020}battle\u{0020}against\u{0020}their\u{0020}opponents.\u{0020}Sure,\u{0020}she\u{0020}can\u{0020}still\u{0020}grow\u{0020}larger\u{0020}than\u{0020}most\u{0020}of\u{0020}them,\u{0020}but\u{0020}deep\u{0020}down,\u{0020}it\u{0020}still\u{0020}nags\u{0020}at\u{0020}her\u{0020}a\u{0020}little.", "0", "0", "0", "0", 10042, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[604203] = {604203, 1000, "When\u{0020}gigantified,\u{0020}Shushu\u{0020}retains\u{0020}full\u{0020}use\u{0020}of\u{0020}her\u{0020}powers.\u{0020}If\u{0020}one\u{0020}has\u{0020}to\u{0020}pinpoint\u{0020}the\u{0020}difference\u{0020}between\u{0020}gigiantification\u{0020}and\u{0020}Paradigm\u{0020}Shift,\u{0020}it\u{0020}would\u{0020}boil\u{0020}down\u{0020}to\u{0020}SAFETY,\u{0020}since\u{0020}most\u{0020}of\u{0020}the\u{0020}damage\u{0020}sustained\u{0020}doesn't\u{0020}directly\u{0020}transfer\u{0020}to\u{0020}the\u{0020}Drivers\u{0020}themselves.\n\nThis\u{0020}protective\u{0020}mechanism\u{0020}only\u{0020}makes\u{0020}Shushu\u{0020}more\u{0020}eager\u{0020}to\u{0020}throw\u{0020}herself\u{0020}into\u{0020}combat;\u{0020}she\u{0020}simply\u{0020}takes\u{0020}it\u{0020}as\u{0020}part\u{0020}of\u{0020}the\u{0020}grand\u{0020}Isekai\u{0020}adventure.\u{0020}Of\u{0020}course,\u{0020}if\u{0020}Commander\u{0020}Lonis\u{0020}ever\u{0020}caught\u{0020}wind\u{0020}of\u{0020}her\u{0020}attitude,\u{0020}she'd\u{0020}probably\u{0020}lose\u{0020}it,\u{0020}shouting\u{0020}something\u{0020}like:\u{0020}\"The\u{0020}battlefield\u{0020}is\u{0020}no\u{0020}playground!\"", "0", "0", "0", "0", 10042, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
