[604301] = {604301, 100, "\u{3000}\u{3000}Cosmic\u{0020}Problem\u{0020}Children\u{0020}stand\u{0020}out\u{0020}even\u{0020}within\u{0020}the\u{0020}Heroine\u{0020}Universe.\u{0020}Their\u{0020}exploits\u{0020}include,\u{0020}but\u{0020}are\u{0020}not\u{0020}limited\u{0020}to,\u{0020}turning\u{0020}90%\u{0020}of\u{0020}the\u{0020}universe's\u{0020}Heroines\u{0020}into\u{0020}puppets\u{0020}and\u{0020}attempting\u{0020}to\u{0020}merge\u{0020}with\u{0020}the\u{0020}cosmos\u{0020}itself\u{0020}to\u{0020}gain\u{0020}control\u{0020}over\u{0020}it.\u{0020}Of\u{0020}course,\u{0020}if\u{0020}we're\u{0020}just\u{0020}talking\u{0020}about\u{0020}their\u{0020}capacity\u{0020}for\u{0020}harm,\u{0020}many\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}could\u{0020}achieve\u{0020}similar\u{0020}levels\u{0020}of\u{0020}devastation\u{0020}if\u{0020}they\u{0020}really\u{0020}tried,\u{0020}but\u{0020}don't\u{0020}let\u{0020}that\u{0020}make\u{0020}you\u{0020}underestimate\u{0020}her.\u{0020}Anyone\u{0020}who\u{0020}looks\u{0020}down\u{0020}on\u{0020}a\u{0020}problem\u{0020}child\u{0020}will\u{0020}be\u{0020}punished.\n\u{3000}\u{3000}\u{0020}Most\u{0020}Heroines,\u{0020}though\u{0020}their\u{0020}emotions\u{0020}may\u{0020}be\u{0020}twisted,\u{0020}are\u{0020}adults\u{0020}who\u{0020}can\u{0020}exercise\u{0020}self-restraint,\u{0020}even\u{0020}the\u{0020}younger\u{0020}Drivers\u{0020}eventually\u{0020}grow\u{0020}up\u{0020}after\u{0020}their\u{0020}experiences.\n\u{3000}\u{3000}\u{0020}But\u{0020}the\u{0020}problem\u{0020}child\u{0020}is\u{0020}different.\u{0020}She\u{0020}remained\u{0020}a\u{0020}true\u{0020}child,\u{0020}a\u{0020}being\u{0020}of\u{0020}pure\u{0020}desire\u{0020}who\u{0020}never\u{0020}learned\u{0020}to\u{0020}hold\u{0020}herself\u{0020}back...\u{0020}until\u{0020}one\u{0020}day,\u{0020}after\u{0020}a\u{0020}certain\u{0020}defeat,\u{0020}she\u{0020}finally\u{0020}gave\u{0020}up.", "0", "0", "0", "0", 10043, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[604302] = {604302, 500, "\u{3000}\u{3000}\"Dad!\u{0020}Mama\u{0020}put\u{0020}the\u{0020}vegetables\u{0020}she\u{0020}doesn't\u{0020}like\u{0020}into\u{0020}my\u{0020}bowl\u{0020}again!\"\n\u{3000}\u{3000}\u{0020}[I\u{0020}need\u{0020}to\u{0020}find\u{0020}a\u{0020}way\u{0020}to\u{0020}get\u{0020}Skadi\u{0020}to\u{0020}eat\u{0020}her\u{0020}veggies...\u{0020}maybe\u{0020}hide\u{0020}them\u{0020}inside\u{0020}a\u{0020}piece\u{0020}of\u{0020}meat...\u{0020}You\u{0020}can\u{0020}do\u{0020}it!]\n\u{3000}\u{3000}\u{0020}\"Dad!\u{0020}Mama\u{0020}ate\u{0020}the\u{0020}cake\u{0020}I\u{0020}saved\u{0020}in\u{0020}the\u{0020}fridge\u{0020}again!\"\n\u{3000}\u{3000}\u{0020}[Well,\u{0020}Skadi\u{0020}and\u{0020}I\u{0020}were\u{0020}planning\u{0020}to\u{0020}go\u{0020}to\u{0020}the\u{0020}sweets\u{0020}shop\u{0020}today.\u{0020}Want\u{0020}to\u{0020}come\u{0020}with\u{0020}us?]\n\u{3000}\u{3000}\u{0020}\"Dad!\u{0020}Mama\u{0020}overslept\u{0020}again!\u{0020}She's\u{0020}still\u{0020}in\u{0020}bed!\"\n\u{3000}\u{3000}\u{0020}[She\u{0020}was\u{0020}called\u{0020}for\u{0020}an\u{0020}emergency\u{0020}sortie\u{0020}in\u{0020}the\u{0020}middle\u{0020}of\u{0020}the\u{0020}night.\u{0020}Cut\u{0020}her\u{0020}some\u{0020}slack\u{0020}this\u{0020}time.]\n\u{3000}\u{3000}\u{0020}\"Correction!\u{0020}We\u{0020}must\u{0020}correct\u{0020}Mama's\u{0020}habits!\u{0020}I\u{0020}refuse\u{0020}to\u{0020}have\u{0020}a\u{0020}mama\u{0020}like\u{0020}this!\u{0020}She's\u{0020}just\u{0020}like\u{0020}a\u{0020}child!\"\n\u{3000}\u{3000}\u{0020}And\u{0020}so,\u{0020}Hikari\u{0020}began\u{0020}working\u{0020}with\u{0020}Lilith\u{0020}to\u{0020}correct\u{0020}Skadi's\u{0020}bad\u{0020}habits.\n\u{3000}\u{3000}\u{0020}A\u{0020}daughter\u{0020}teaching\u{0020}her\u{0020}mother\u{0020}a\u{0020}lesson...\u{0020}Those\u{0020}who\u{0020}understood\u{0020}their\u{0020}relationship\u{0020}would\u{0020}always\u{0020}smile\u{0020}wryly\u{0020}at\u{0020}the\u{0020}sight.\n\u{3000}\u{3000}\u{0020}And\u{0020}Skadi,\u{0020}the\u{0020}ultimate\u{0020}victim\u{0020}of\u{0020}this\u{0020}campaign,\u{0020}would\u{0020}say:\u{0020}\"Even\u{0020}so,\u{0020}I\u{0020}have\u{0020}not\u{0020}regretted\u{0020}having\u{0020}you\u{0020}for\u{0020}a\u{0020}single\u{0020}second,\u{0020}Hikari...\u{0020}You\u{0020}are\u{0020}the\u{0020}fruit\u{0020}of\u{0020}Mama\u{0020}and\u{0020}Papa's\u{0020}love...\u{0020}You\u{0020}will\u{0020}understand\u{0020}one\u{0020}day...\u{0020}One\u{0020}day.\"\n\u{3000}\u{3000}\n\u{3000}\u{3000}No\u{0020}matter\u{0020}what\u{0020}Hikari\u{0020}said\u{0020}to\u{0020}her,\u{0020}Skadi\u{0020}would\u{0020}always\u{0020}respond\u{0020}with\u{0020}that\u{0020}gentle\u{0020}gaze...\u{0020}until\u{0020}finally,\u{0020}Hikari\u{0020}couldn't\u{0020}take\u{0020}it\u{0020}anymore\u{0020}and\u{0020}snapped.\u{0020}Then,\u{0020}at\u{0020}the\u{0020}climax\u{0020}of\u{0020}the\u{0020}incident,\u{0020}Hikari\u{0020}hugged\u{0020}Skadi\u{0020}tightly\u{0020}and\u{0020}cried.\n\u{3000}\u{3000}\"I\u{0020}don't\u{0020}have\u{0020}a\u{0020}mama!\u{0020}I\u{0020}don't\u{0020}have\u{0020}a\u{0020}mama!\u{0020}I\u{0020}was\u{0020}born\u{0020}in\u{0020}a\u{0020}chamber!\u{0020}I'm\u{0020}the\u{0020}ultimate\u{0020}weapon!\u{0020}I\u{0020}don't\u{0020}acknowledge\u{0020}you,\u{0020}and\u{0020}I\u{0020}don't\u{0020}need\u{0020}a\u{0020}mama!\u{0020}Only\u{0020}weaklings\u{0020}need\u{0020}mothers!\u{0020}I\u{0020}only\u{0020}need\u{0020}Papa!\u{0020}Stop\u{0020}looking\u{0020}at\u{0020}me\u{0020}like\u{0020}that!\"\n\u{3000}\u{3000}\u{0020}...But\u{0020}really,\u{0020}is\u{0020}it\u{0020}appropriate\u{0020}to\u{0020}say\u{0020}you\u{0020}don't\u{0020}need\u{0020}a\u{0020}mama\u{0020}while\u{0020}you're\u{0020}hugging\u{0020}her\u{0020}and\u{0020}won't\u{0020}let\u{0020}go?", "0", "0", "0", "0", 10043, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[604303] = {604303, 1000, "\u{3000}\u{3000}This\u{0020}story\u{0020}goes\u{0020}back\u{0020}to\u{0020}when\u{0020}I\u{0020}first\u{0020}met\u{0020}Hikari.\u{0020}She\u{0020}asked\u{0020}me\u{0020}a\u{0020}question\u{0020}back\u{0020}then.\n\u{3000}\u{3000}\u{0020}\"Dad...\u{0020}what\u{0020}are\u{0020}you\u{0020}doing?\"\u{0020}Lunch\u{0020}that\u{0020}day\u{0020}was\u{0020}curry.\u{0020}Perhaps\u{0020}drawn\u{0020}by\u{0020}the\u{0020}aroma,\u{0020}Hikari,\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}ever,\u{0020}showed\u{0020}curiosity\u{0020}about\u{0020}human\u{0020}food.\n\u{3000}\u{3000}\u{0020}\"Eating\u{0020}curry.\u{0020}Want\u{0020}some?\"\n\u{3000}\u{3000}\u{0020}\"No.\u{0020}It's\u{0020}inefficient,\"\u{0020}Guang\u{0020}said,\u{0020}swallowing\u{0020}hard.\u{0020}\"When\u{0020}I\u{0020}was\u{0020}an\u{0020}artifical\u{0020}being,\u{0020}and\u{0020}even\u{0020}now,\u{0020}I've\u{0020}always\u{0020}used\u{0020}the\u{0020}most\u{0020}efficient\u{0020}method.\u{0020}That\u{0020}smell\u{0020}is\u{0020}just...\u{0020}distracting.\"\n\u{3000}\u{3000}\u{0020}\n\u{3000}\u{3000}\"The\u{0020}most\u{0020}efficient\u{0020}method?\"\u{0020}\n\u{3000}\u{3000}\"Eating\u{0020}through\u{0020}my\u{0020}back.\"\u{0020}\n\u{3000}\u{3000}\"...What?\"\u{0020}\n\u{3000}\u{3000}\"Eating\u{0020}through\u{0020}my\u{0020}back.\u{0020}You\u{0020}just\u{0020}connect\u{0020}a\u{0020}tube\u{0020}near\u{0020}the\u{0020}base\u{0020}of\u{0020}the\u{0020}spine,\u{0020}around\u{0020}the\u{0020}coccyx,\u{0020}and\u{0020}it\u{0020}provides\u{0020}all\u{0020}the\u{0020}necessary\u{0020}nutrients.\"\u{0020}\"So...\u{0020}you\u{0020}eat\u{0020}through\u{0020}your\u{0020}butt?\"\n\u{3000}\u{3000}\u{0020}\"It's\u{0020}my\u{0020}privilege,\u{0020}Dad.\u{0020}Don't\u{0020}be\u{0020}jealous.\u{0020}Though\u{0020}maybe\u{0020}Red\u{0020}Doctor\u{0020}could\u{0020}install\u{0020}one\u{0020}for\u{0020}you\u{0020}if\u{0020}you\u{0020}asked.\"\n\u{3000}\u{3000}\u{0020}\"I\u{0020}don't\u{0020}want\u{0020}to\u{0020}eat\u{0020}with\u{0020}my\u{0020}butt.\"\n\u{3000}\u{3000}\u{0020}\"Dad...\u{0020}don't\u{0020}say\u{0020}'butt'\u{0020}while\u{0020}we're\u{0020}eating.\u{0020}How\u{0020}can\u{0020}you\u{0020}still\u{0020}have\u{0020}an\u{0020}appetite?\"\n\u{3000}\u{3000}\u{0020}\"I\u{0020}still\u{0020}don't\u{0020}want\u{0020}to\u{0020}eat\u{0020}with\u{0020}my\u{0020}butt.\"\n\u{3000}\u{3000}\u{0020}\"I\u{0020}said\u{0020}it's\u{0020}near\u{0020}the\u{0020}coccyx,\u{0020}closer\u{0020}to\u{0020}the\u{0020}lower\u{0020}back...\u{0020}And\u{0020}you\u{0020}were\u{0020}the\u{0020}one\u{0020}who\u{0020}asked!\u{0020}Besides,\u{0020}it's\u{0020}the\u{0020}most\u{0020}efficient\u{0020}way.\u{0020}Humans\u{0020}have\u{0020}to\u{0020}gather\u{0020}ingredients,\u{0020}then\u{0020}chew\u{0020}and\u{0020}swallow\u{0020}bite\u{0020}by\u{0020}bite.\u{0020}I\u{0020}don't\u{0020}need\u{0020}any\u{0020}of\u{0020}that.\"\n\u{3000}\u{3000}\u{0020}As\u{0020}she\u{0020}said\u{0020}this,\u{0020}she\u{0020}swallowed\u{0020}again.\n\u{3000}\u{3000}\u{0020}\"Why\u{0020}don't\u{0020}you\u{0020}just\u{0020}try\u{0020}it\u{0020}for\u{0020}yourself?\u{0020}Then\u{0020}you'll\u{0020}understand\u{0020}why\u{0020}we\u{0020}eat.\"\u{0020}I\u{0020}said,\u{0020}serving\u{0020}a\u{0020}bowl\u{0020}for\u{0020}her.\u{0020}\"The\u{0020}truth\u{0020}comes\u{0020}from\u{0020}experience.\"\n\u{3000}\u{3000}\u{0020}And\u{0020}so,\u{0020}that\u{0020}was\u{0020}Hikari's\u{0020}first\u{0020}encounter\u{0020}with\u{0020}food.", "0", "0", "0", "0", 10043, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
