[604601] = {604601, 100, "\u{3000}\u{3000}Fubuki\u{0020}Azuma\u{0020}is\u{0020}the\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}Ninth\u{0020}Squad,\u{0020}and\u{0020}the\u{0020}current\u{0020}head\u{0020}of\u{0020}the\u{0020}Azuma\u{0020}family\u{0020}in\u{0020}Mato,\u{0020}a\u{0020}position\u{0020}she\u{0020}earned\u{0020}through\u{0020}sheer\u{0020}strength.\u{0020}\n\u{3000}\u{3000}In\u{0020}daily\u{0020}life,\u{0020}she\u{0020}is\u{0020}taciturn.\u{0020}With\u{0020}her\u{0020}eyes\u{0020}hidden\u{0020}behind\u{0020}long\u{0020}bangs,\u{0020}she\u{0020}gives\u{0020}off\u{0020}an\u{0020}unapproachable\u{0020}air.\u{0020}Yet\u{0020}those\u{0020}eyes\u{0020}watch\u{0020}everything\u{0020}from\u{0020}the\u{0020}shadows,\u{0020}and\u{0020}no\u{0020}detail\u{0020}escapes\u{0020}her\u{0020}scrutiny.\u{0020}\n\u{3000}\u{3000}Holding\u{0020}both\u{0020}titles,\u{0020}commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}and\u{0020}head\u{0020}of\u{0020}the\u{0020}Azuma\u{0020}family,\u{0020}would\u{0020}usually\u{0020}crush\u{0020}a\u{0020}person's\u{0020}will\u{0020}under\u{0020}the\u{0020}weight\u{0020}of\u{0020}responsibility.\u{0020}But\u{0020}if\u{0020}Fubuki\u{0020}Azuma\u{0020}could\u{0020}not\u{0020}bear\u{0020}that\u{0020}pressure,\u{0020}she\u{0020}would\u{0020}not\u{0020}be\u{0020}Fubuki\u{0020}Azuma.\u{0020}\n\u{3000}\u{3000}As\u{0020}the\u{0020}current\u{0020}head,\u{0020}she\u{0020}understands\u{0020}the\u{0020}family's\u{0020}honor\u{0020}and\u{0020}duties.\u{0020}At\u{0020}the\u{0020}same\u{0020}time,\u{0020}she\u{0020}rejects\u{0020}outdated\u{0020}customs\u{0020}and\u{0020}seeks\u{0020}a\u{0020}path\u{0020}that\u{0020}will\u{0020}lead\u{0020}her\u{0020}clan\u{0020}toward\u{0020}harmony\u{0020}and\u{0020}prosperity.\u{0020}Whether\u{0020}she\u{0020}can\u{0020}succeed,\u{0020}if\u{0020}it\u{0020}is\u{0020}Fubuki\u{0020}Azuma,\u{0020}you\u{0020}cannot\u{0020}help\u{0020}but\u{0020}believe\u{0020}she\u{0020}will.\u{0020}\n\u{3000}\u{3000}Her\u{0020}Peach\u{0020}Blessing,\u{0020}Sunset,\u{0020}will\u{0020}help\u{0020}her\u{0020}pierce\u{0020}any\u{0020}obstacle\u{0020}and\u{0020}carve\u{0020}a\u{0020}new\u{0020}road\u{0020}forward.", "0", "0", "0", "0", 10046, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[604602] = {604602, 500, "\u{3000}\u{3000}Fubuki\u{0020}Azuma's\u{0020}intelligence,\u{0020}experience,\u{0020}and\u{0020}strength\u{0020}are\u{0020}indispensable\u{0020}to\u{0020}this\u{0020}incident.\u{0020}\n\u{3000}\u{3000}With\u{0020}Mira\u{0020}Kamiunten\u{0020}being\u{0020}somewhat\u{0020}impulsive\u{0020}and\u{0020}Yakumo\u{0020}Ezo\u{0020}far\u{0020}too\u{0020}carefree\u{0020}and\u{0020}pleasure-seeking,\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}group\u{0020}might\u{0020}have\u{0020}caused\u{0020}chaos\u{0020}the\u{0020}moment\u{0020}they\u{0020}arrived\u{0020}in\u{0020}this\u{0020}world\u{0020}if\u{0020}it\u{0020}were\u{0020}only\u{0020}those\u{0020}two.\u{0020}In\u{0020}situations\u{0020}like\u{0020}that,\u{0020}Fubuki's\u{0020}calm\u{0020}composure\u{0020}and\u{0020}sharp\u{0020}eye\u{0020}were\u{0020}a\u{0020}tremendous\u{0020}help.\u{0020}\n\u{3000}\u{3000}Whether\u{0020}it\u{0020}was\u{0020}locating\u{0020}\"others\"\u{0020}who\u{0020}might\u{0020}be\u{0020}in\u{0020}the\u{0020}same\u{0020}predicament\u{0020}as\u{0020}them,\u{0020}or\u{0020}observing\u{0020}the\u{0020}differences\u{0020}and\u{0020}similarities\u{0020}between\u{0020}this\u{0020}world\u{0020}and\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}world,\u{0020}without\u{0020}Fubuki,\u{0020}such\u{0020}a\u{0020}simple\u{0020}and\u{0020}executable\u{0020}strategy\u{0020}likely\u{0020}would\u{0020}not\u{0020}have\u{0020}been\u{0020}established\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\u{0020}\n\u{3000}\u{3000}And\u{0020}although\u{0020}the\u{0020}later\u{0020}stage\u{0020}of\u{0020}the\u{0020}crisis\u{0020}was\u{0020}handled\u{0020}almost\u{0020}entirely\u{0020}by\u{0020}Supreme\u{0020}Commander\u{0020}Ren\u{0020}Yamashiro,\u{0020}without\u{0020}the\u{0020}solid\u{0020}groundwork\u{0020}Fubuki\u{0020}set\u{0020}in\u{0020}the\u{0020}early\u{0020}phase,\u{0020}even\u{0020}Ren\u{0020}would\u{0020}probably\u{0020}have\u{0020}been\u{0020}thrown\u{0020}into\u{0020}a\u{0020}period\u{0020}of\u{0020}scrambling\u{0020}to\u{0020}catch\u{0020}up.", "0", "0", "0", "0", 10046, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[604603] = {604603, 1000, "\u{3000}\u{3000}The\u{0020}Synesthete\u{0020}Navigator\u{0020}is\u{0020}grateful\u{0020}to\u{0020}have\u{0020}Fubuki\u{0020}Azuma,\u{0020}a\u{0020}mature\u{0020}and\u{0020}dependable\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}commander,\u{0020}as\u{0020}an\u{0020}ally.\u{0020}\n\u{3000}\u{3000}Her\u{0020}grasp\u{0020}of\u{0020}the\u{0020}situation,\u{0020}her\u{0020}command\u{0020}of\u{0020}the\u{0020}facts\u{0020}on\u{0020}the\u{0020}ground,\u{0020}and\u{0020}the\u{0020}cooperation\u{0020}framework\u{0020}she\u{0020}proposed\u{0020}at\u{0020}the\u{0020}earliest\u{0020}opportunity,\u{0020}all\u{0020}speak\u{0020}to\u{0020}her\u{0020}ability\u{0020}to\u{0020}reach\u{0020}correct,\u{0020}optimal\u{0020}judgments\u{0020}in\u{0020}a\u{0020}short\u{0020}time.\u{0020}As\u{0020}a\u{0020}partner\u{0020}in\u{0020}resolving\u{0020}an\u{0020}anomalous\u{0020}incident,\u{0020}Fubuki\u{0020}is,\u{0020}without\u{0020}question,\u{0020}the\u{0020}kind\u{0020}of\u{0020}companion\u{0020}who\u{0020}inspires\u{0020}the\u{0020}most\u{0020}confidence\u{0020}and\u{0020}peace\u{0020}of\u{0020}mind.\u{0020}\n\u{3000}\u{3000}Powerful,\u{0020}reliable,\u{0020}and\u{0020}sharply\u{0020}observant,\u{0020}if\u{0020}Ren\u{0020}Yamashiro\u{0020}did\u{0020}not\u{0020}exist,\u{0020}the\u{0020}Navigator\u{0020}would\u{0020}probably\u{0020}consider\u{0020}Fubuki\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}true\u{0020}leader.\u{0020}\n\u{3000}\u{3000}In\u{0020}fact,\u{0020}he\u{0020}is\u{0020}very\u{0020}interested\u{0020}in\u{0020}a\u{0020}hypothetical\u{0020}\"competition\u{0020}between\u{0020}Ren\u{0020}Yamashiro\u{0020}and\u{0020}Fubuki\u{0020}Azuma\",\u{0020}if\u{0020}such\u{0020}a\u{0020}thing\u{0020}were\u{0020}ever\u{0020}to\u{0020}happen.", "0", "0", "0", "0", 10046, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[604604] = {604604, 2000, "\u{3000}\u{3000}\"Children\u{0020}should\u{0020}be\u{0020}laughing\u{0020}in\u{0020}the\u{0020}sunlight.\"\u{0020}\n\u{3000}\u{3000}That\u{0020}is\u{0020}not\u{0020}some\u{0020}unreachable\u{0020}dream.\u{0020}\n\u{3000}\u{3000}As\u{0020}long\u{0020}as\u{0020}I\u{0020}still\u{0020}hold\u{0020}this\u{0020}spear,\u{0020}\n\u{3000}\u{3000}I\u{0020}will\u{0020}keep\u{0020}fighting,\u{0020}\n\u{3000}\u{3000}piercing\u{0020}through\u{0020}the\u{0020}storm\u{0020}clouds,\u{0020}sweeping\u{0020}away\u{0020}the\u{0020}gloom,\u{0020}\n\u{3000}\u{3000}for\u{0020}the\u{0020}Azuma\u{0020}family's\u{0020}children,\u{0020}\n\u{3000}\u{3000}for\u{0020}every\u{0020}future,\u{0020}\n\u{3000}\u{3000}forge\u{0020}a\u{0020}path\u{0020}in\u{0020}the\u{0020}name\u{0020}of\u{0020}\"happiness\".", "0", "0", "0", "0", 10046, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[610000] = {610000, 0, "[Name]\u{0020}Charlissa\u{0020}de\u{0020}Rolan\n[B-Day]\u{0020}April\u{0020}1\n[Compatability\u{0020}Rate]\u{0020}<color=#FF6100>100％</color>\n[Height]\u{0020}35m\n[Squad]\u{0020}Danube\u{0020}Special\u{0020}Combined\u{0020}Unit\n[Affiliation]\u{0020}Stephanie/Danube\u{0020}Branch\n[Interest]\u{0020}Enjoy\u{0020}the\u{0020}admiring\u{0020}glances\u{0020}and\u{0020}addresses\u{0020}from\u{0020}others;\u{0020}free\u{0020}and\u{0020}decadent\u{0020}rainy\u{0020}days", "0", "0", "0", "0", 11000, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}查丽莎·德·罗兰\n[B-Day]\u{1000}4月1日\n[幻化核心适格率]\u{1000}<color=#FF6100>100％</color>\n[Height]\u{1000}35m\n[部队]\u{1000}多瑙特别联合部队\u{1000}\u{1000}[隶属]\u{1000}Stephanie/Danube\u{1000}Branch\n[Interest]\u{1000}享受别人崇拜的目光与称呼\u{1000}喜欢自由而颓废的雨天"},
[610001] = {610001, 100, "\u{0020}\u{0020}\"She's\u{0020}rude\u{0020}and\u{0020}plainspoken.\u{0020}From\u{0020}every\u{0020}perspective,\u{0020}she\u{0020}doesn't\u{0020}look\u{0020}like\u{0020}a\u{0020}descendant\u{0020}of\u{0020}nobility.\u{0020}Unlike\u{0020}those\u{0020}overly-coddled\u{0020}daughters,\u{0020}she's\u{0020}an\u{0020}independent\u{0020}girl.\u{0020}From\u{0020}her,\u{0020}I\u{0020}can\u{0020}sense\u{0020}real\u{0020}freedom…\".\u{0020}Captain\u{0020}Julius\u{0020}has\u{0020}commented\u{0020}about\u{0020}her\u{0020}like\u{0020}that.\n\nIndeed,\u{0020}you\u{0020}will\u{0020}never\u{0020}see\u{0020}so-called\u{0020}modesty\u{0020}from\u{0020}this\u{0020}girl,\u{0020}just\u{0020}like\u{0020}other\u{0020}rich\u{0020}kids,\u{0020}she's\u{0020}ostentatious\u{0020}about\u{0020}everything\u{0020}she\u{0020}owns.\u{0020}But\u{0020}notice,\u{0020}she's\u{0020}never\u{0020}showy\u{0020}about\u{0020}her\u{0020}family\u{0020}background,\u{0020}all\u{0020}the\u{0020}things\u{0020}that\u{0020}she\u{0020}shows\u{0020}off\u{0020}are\u{0020}gained\u{0020}by\u{0020}the\u{0020}endeavor\u{0020}of\u{0020}herself.\n\nOf\u{0020}course,\u{0020}other\u{0020}than\u{0020}her\u{0020}beauty.\n\nBeing\u{0020}a\u{0020}belligerent\u{0020}girl,\u{0020}her\u{0020}actions\u{0020}are\u{0020}often\u{0020}following\u{0020}her\u{0020}own\u{0020}will,\u{0020}no\u{0020}matter\u{0020}Navigator\u{0020}or\u{0020}Julius\u{0020}and\u{0020}persuade\u{0020}her\u{0020}easily.\u{0020}These\u{0020}kinds\u{0020}of\u{0020}actions\u{0020}indeed\u{0020}bring\u{0020}a\u{0020}lot\u{0020}of\u{0020}unnecessary\u{0020}troubles\u{0020}to\u{0020}others.\u{0020}But\u{0020}if\u{0020}she\u{0020}understands\u{0020}that\u{0020}her\u{0020}actions\u{0020}caused\u{0020}problems\u{0020}to\u{0020}others,\u{0020}she\u{0020}will\u{0020}apologize,\u{0020}although\u{0020}her\u{0020}attitude\u{0020}when\u{0020}apologizing\u{0020}is\u{0020}not\u{0020}very\u{0020}acceptable\u{0020}in\u{0020}others'\u{0020}eyes.", "0", "0", "0", "0", 11000, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"举止粗鲁，口无遮拦，无论从哪方面看，她都不像是一名贵族的后裔。她和那些千金大小姐不太一样，是个非常独立的女孩，从她身上，我能看到真正的自由……\"身为组长的朱利乌斯曾经这么评价过这个女孩。\n\u{1000}\u{1000}的确，从这个女孩身上你看不到所谓的谦逊，如同其他有钱人家的孩子那样，她非常喜欢向人们炫耀自己所拥有的一切。但需要注意的是，查丽莎从来不会将家底作为谈资，她所炫耀的都是通过她自己的努力争取到的东西。\n\u{1000}\u{1000}当然，美貌除外。\n\u{1000}\u{1000}争强好胜的她常常会按照自己的意愿行动，无论是领航还是朱利乌斯都很难说得动她，这样的行为的确在某种程度上给大家添了许多不必要的麻烦。但是如果能让她意识到自己的行为会给其他人带来困扰后，她还是会去道歉的，只不过，道歉的态度在常人眼里确实不敢恭维。"},
[610002] = {610002, 500, "\u{0020}\u{0020}She's\u{0020}the\u{0020}princess\u{0020}that\u{0020}is\u{0020}submerged\u{0020}in\u{0020}her\u{0020}parent's\u{0020}love,\u{0020}and\u{0020}also\u{0020}a\u{0020}doll\u{0020}for\u{0020}her\u{0020}parents\u{0020}to\u{0020}express\u{0020}their\u{0020}love.\n\nCharlissa's\u{0020}parents\u{0020}are\u{0020}rich\u{0020}merchants\u{0020}well-known\u{0020}in\u{0020}Danube,\u{0020}and\u{0020}their\u{0020}nobility\u{0020}status\u{0020}was\u{0020}merely\u{0020}bought\u{0020}with\u{0020}money,\u{0020}a\u{0020}capital\u{0020}just\u{0020}for\u{0020}showing\u{0020}off.\u{0020}Before\u{0020}Charlissa,\u{0020}this\u{0020}parent\u{0020}raised\u{0020}a\u{0020}boy,\u{0020}which\u{0020}is\u{0020}her\u{0020}brother.\u{0020}Charlissa's\u{0020}parents\u{0020}wanted\u{0020}to\u{0020}let\u{0020}him\u{0020}inherit\u{0020}their\u{0020}wealth\u{0020}properly,\u{0020}so\u{0020}they\u{0020}sent\u{0020}him\u{0020}to\u{0020}a\u{0020}special\u{0020}school\u{0020}in\u{0020}his\u{0020}early\u{0020}age,\u{0020}separated\u{0020}from\u{0020}his\u{0020}family.\n\nAs\u{0020}a\u{0020}result,\u{0020}being\u{0020}the\u{0020}younger\u{0020}daughter,\u{0020}Charlissa\u{0020}received\u{0020}double\u{0020}times\u{0020}of\u{0020}love,\u{0020}her\u{0020}parents\u{0020}would\u{0020}satisfy\u{0020}every\u{0020}wish\u{0020}of\u{0020}her,\u{0020}and\u{0020}they\u{0020}would\u{0020}forgive\u{0020}every\u{0020}mistake\u{0020}made\u{0020}by\u{0020}her\u{0020}no\u{0020}matter\u{0020}how\u{0020}serious\u{0020}it\u{0020}is.\n\nThe\u{0020}words\u{0020}most\u{0020}frequently\u{0020}heard\u{0020}by\u{0020}little\u{0020}Charlissa\u{0020}were\u{0020}not\u{0020}\"Good\u{0020}job\"\u{0020}nor\u{0020}\"You\u{0020}are\u{0020}wrong\",\u{0020}but\u{0020}\"It\u{0020}doesn't\u{0020}matter\".\u{0020}Knocked\u{0020}over\u{0020}the\u{0020}table\u{0020}–\u{0020}\"It\u{0020}doesn't\u{0020}matter\",\u{0020}stained\u{0020}her\u{0020}father's\u{0020}shirt\u{0020}deliberately–\u{0020}\"It\u{0020}doesn't\u{0020}matter\",\u{0020}drew\u{0020}her\u{0020}first\u{0020}family\u{0020}painting–\u{0020}\"It\u{0020}doesn't\u{0020}matter\".\u{0020}Because\u{0020}there\u{0020}were\u{0020}no\u{0020}expectations,\u{0020}everything\u{0020}done\u{0020}by\u{0020}Charlissa\u{0020}\"doesn't\u{0020}matter\",\u{0020}she\u{0020}existed\u{0020}solely\u{0020}to\u{0020}receive\u{0020}her\u{0020}parent's\u{0020}love\u{0020}that\u{0020}is\u{0020}nowhere\u{0020}to\u{0020}vent.\n\nSo,\u{0020}what\u{0020}Charlissa\u{0020}really\u{0020}craves\u{0020}is\u{0020}not\u{0020}money\u{0020}or\u{0020}unconditional\u{0020}love,\u{0020}but\u{0020}\"the\u{0020}feeling\u{0020}of\u{0020}being\u{0020}needed\u{0020}by\u{0020}someone\"\u{0020}and\u{0020}\"the\u{0020}place\u{0020}to\u{0020}show\u{0020}herself\".\n\nAnd\u{0020}just\u{0020}like\u{0020}that,\u{0020}she\u{0020}stopped\u{0020}her\u{0020}relationships\u{0020}with\u{0020}her\u{0020}family,\u{0020}to\u{0020}seek\u{0020}\"the\u{0020}feeling\u{0020}of\u{0020}being\u{0020}needed\u{0020}by\u{0020}someone\",\u{0020}she\u{0020}attended\u{0020}the\u{0020}test\u{0020}hosted\u{0020}by\u{0020}Aegis,\u{0020}and\u{0020}she\u{0020}swore\u{0020}to\u{0020}achieve\u{0020}something\u{0020}important,\u{0020}to\u{0020}change\u{0020}her\u{0020}parents'\u{0020}ideas\u{0020}about\u{0020}her.\n\nThat's\u{0020}the\u{0020}Charlissa\u{0020}we\u{0020}known\u{0020}of.", "0", "0", "0", "0", 11000, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}集万千宠爱与一身的公主，也是父母宣泄\"宠爱欲\"的玩偶。\n\u{1000}\u{1000}查丽莎的父母是多瑙有名的富商，而他们的的贵族头衔不过是用金钱买来的，炫耀的资本。\u{1000}在查丽莎之前，这对夫妇还养育了一个男孩，也就是查丽莎的哥哥。查丽莎的父母为了能让长子顺利得继承家业，所以早早地就将他送去了专门学校，与家人分居。\n\u{1000}\u{1000}由此一来身为次女的查丽莎便获得了双重的爱意，任何要求父母都会满足，无论犯下多大的错误父母都能原谅。\n\u{1000}\u{1000}年幼的查丽莎听到最多的话，并不是\"做得好\"也不是\"你错了\"而是\"无所谓\"。不小心打翻了茶几——\"无所谓\"，故意弄脏了父亲的衬衫——\"无所谓\"，画出了第一张全家福——\"无所谓\"。因为没有投入期待，所以查丽莎所有行为都是\"无所谓\"，她存在的意义仅仅是用来接受父母无处宣泄的爱罢了。\n\u{1000}\u{1000}所以，查丽莎真正渴望拥有的既不是金钱也不是无条件的爱，而是是\"被某人需要着的感觉\"以及\"能够展现自己的地方\"。\n\u{1000}\u{1000}就这样在完成了成年礼后，她断绝了和家人们的联系。为了追寻那\"被某人需要着的感觉\"，她需要更大的舞台。于是，不顾家人的反对一个人参加了艾吉斯的适格测试，并且发誓一定要做出一番事业，让父母对自己刮目相看。\n\u{1000}\u{1000}真不愧是查丽莎。"},
[610003] = {610003, 1000, "\u{0020}\u{0020}At\u{0020}first,\u{0020}Charlissa\u{0020}was\u{0020}not\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force.\u{0020}But\u{0020}she\u{0020}was\u{0020}kicked\u{0020}out\u{0020}from\u{0020}her\u{0020}original\u{0020}squad\u{0020}and\u{0020}Danube\u{0020}branch\u{0020}of\u{0020}AEGIS\u{0020}because\u{0020}she\u{0020}was\u{0020}too\u{0020}undisciplined.\n\nLuckily,\u{0020}Stephanie\u{0020}didn't\u{0020}care,\u{0020}she\u{0020}only\u{0020}cared\u{0020}about\u{0020}Charlissa's\u{0020}excellent\u{0020}Compatability\u{0020}Rate\u{0020}and\u{0020}her\u{0020}special\u{0020}fighting\u{0020}style\u{0020}of\u{0020}\"high\u{0020}speed\",\u{0020}so\u{0020}she\u{0020}kept\u{0020}Charlissa.\u{0020}For\u{0020}that,\u{0020}Charlissa\u{0020}didn't\u{0020}feel\u{0020}grateful.\u{0020}On\u{0020}the\u{0020}contrary,\u{0020}after\u{0020}the\u{0020}\"kicked\u{0020}out\"\u{0020}incident,\u{0020}she\u{0020}lost\u{0020}her\u{0020}confidence\u{0020}about\u{0020}herself,\u{0020}and\u{0020}she\u{0020}thought\u{0020}she's\u{0020}not\u{0020}wanted\u{0020}by\u{0020}anyone.\u{0020}If\u{0020}this\u{0020}is\u{0020}the\u{0020}case,\u{0020}why\u{0020}shouldn't\u{0020}she\u{0020}just\u{0020}be\u{0020}completely\u{0020}undisciplined?\u{0020}She\u{0020}just\u{0020}wants\u{0020}to\u{0020}be\u{0020}famous.\n\nBut\u{0020}back\u{0020}then\u{0020}she\u{0020}didn't\u{0020}know,\u{0020}in\u{0020}the\u{0020}future,\u{0020}she\u{0020}would\u{0020}become\u{0020}the\u{0020}hero\u{0020}in\u{0020}everyone's\u{0020}opinion,\u{0020}and\u{0020}the\u{0020}most\u{0020}important\u{0020}partner\u{0020}of\u{0020}\"someone\".\u{0020}And\u{0020}she,\u{0020}would\u{0020}make\u{0020}a\u{0020}promise.\n\n\"Hey,\u{0020}be\u{0020}assured,\u{0020}no\u{0020}matter\u{0020}where,\u{0020}no\u{0020}matter\u{0020}when,\u{0020}I'll\u{0020}be\u{0020}the\u{0020}first\u{0020}one\u{0020}to\u{0020}arrive\u{0020}when\u{0020}you\u{0020}need\u{0020}help.\"", "0", "0", "0", "0", 11000, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}最初，查丽莎并不是多瑙特别联合部队的成员，因为其过于随性的态度而被原部队和多瑙艾吉斯支部劝退了，好在史蒂芬妮并不在意这些，她看重得只是她那异与常人的适格率以及独特的超高速战斗风格，于是便收留了她。\n\u{1000}\u{1000}对此，查丽莎并不抱有感激之情，相反经过之前劝退的事件，她对自己失去了信心，觉得自己无论再哪里都是多余的，是不被他人需要的。既然如此，那就不如彻底随性吧，只要能够出名就好了。\n\u{1000}\u{1000}不过那时的她还不知道，将来，她将会成为大家口中的英雄以及某人心中最重要的伙伴，而她也将许下承诺。\n\u{1000}\u{1000}\"哼，放心好了，无论何时何地，只要你需要帮助的时候，我一定是第一个赶到你身边的人。\""},
[610004] = {610004, 2000, "\u{0020}\u{0020}Ah,\u{0020}stars\u{0020}decorating\u{0020}the\u{0020}night\u{0020}sky,\n\nthey\u{0020}are\u{0020}the\u{0020}silent\u{0020}witnesses\u{0020}of\u{0020}those\u{0020}shiny\u{0020}moments,\n\nthey\u{0020}are\u{0020}the\u{0020}lighthouses,\u{0020}guiding\u{0020}the\u{0020}lost\u{0020}people\u{0020}to\u{0020}move\u{0020}along.\n\nSo,\n\nIf\u{0020}my\u{0020}body\u{0020}can\u{0020}be\u{0020}a\u{0020}little\u{0020}bit\u{0020}bigger…a\u{0020}little\u{0020}bit\u{0020}taller…\n\nwill\u{0020}I\u{0020}approach\u{0020}them\u{0020}closer?\n\nThinking\u{0020}about\u{0020}that,\u{0020}the\u{0020}ground\u{0020}shakes,\u{0020}the\u{0020}giantess\u{0020}flies\u{0020}toward\u{0020}the\u{0020}galaxy.\n\nBut,\u{0020}she\u{0020}doesn't\u{0020}know\u{0020}that,\n\nIn\u{0020}someone's\u{0020}eyes,\u{0020}the\u{0020}stellar-chasing\u{0020}girl,already\u{0020}became\u{0020}a\u{0020}more\u{0020}blazing\u{0020}shooting\u{0020}star.", "0", "0", "0", "0", 11000, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}点缀了夜空的繁星啊，\n\u{1000}\u{1000}他们是光辉时刻无言的记录者，\n\u{1000}\u{1000}是指引迷途之人前行的摇曳灯火。\n\u{1000}\u{1000}那么，\n\u{1000}\u{1000}如果我的身体能再大一些……再高也一些的话……\n\u{1000}\u{1000}是不是就能更接近他们了呢？\n\u{1000}\u{1000}这么想着，随着大地一阵晃动，巨大的少女向着夜空飞去。\n\u{1000}\u{1000}但是，她并不知道。\n\u{1000}\u{1000}在某人眼中，追逐星辰的她已然化为更为璀璨的流星。"},
[610100] = {610100, 0, "[Name]\u{0020}Alice·Cretia\n[B-Day]\u{0020}Aug\u{0020}2\n[Compatability\u{0020}Rate]\u{0020}88％\n[Height]\u{0020}34m\n[Squad]\u{0020}Cavalier\n[Affiliation]\u{0020}Maya\u{0020}Branch\n[Interest]\u{0020}Practice\u{0020}swordsmanship", "0", "0", "0", "0", 11001, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}爱丽丝·克雷蒂亚\n[B-Day]\u{1000}8月2日\n[幻化核心适格率]\u{1000}88％\n[Height]\u{1000}39m\n[部队]\u{1000}猎骑\n[隶属]\u{1000}Maya\u{1000}Branch\n[Interest]\u{1000}练剑"},
[610101] = {610101, 100, "\u{0020}\u{0020}She\u{0020}is\u{0020}a\u{0020}perfect\u{0020}lady.\u{0020}In\u{0020}formal\u{0020}occasions,\u{0020}her\u{0020}words\u{0020}and\u{0020}deeds,\u{0020}as\u{0020}well\u{0020}as\u{0020}her\u{0020}dress\u{0020}and\u{0020}matching,\u{0020}are\u{0020}impeccable;\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}she\u{0020}always\u{0020}demands\u{0020}the\u{0020}highest\u{0020}standards\u{0020}of\u{0020}herself\u{0020}and\u{0020}completes\u{0020}the\u{0020}task\u{0020}successfully.\u{0020}Her\u{0020}perfection\u{0020}benefits\u{0020}from\u{0020}her\u{0020}teacher\u{0020}-\u{0020}the\u{0020}elite\u{0020}education\u{0020}of\u{0020}Tina\u{0020}Eisen.\n\nAs\u{0020}the\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}current\u{0020}head\u{0020}of\u{0020}the\u{0020}noble\u{0020}Cretia\u{0020}family,\u{0020}she\u{0020}is\u{0020}extremely\u{0020}strict\u{0020}with\u{0020}herself.\u{0020}She\u{0020}pursues\u{0020}power,\u{0020}pursues\u{0020}perfection,\u{0020}and\u{0020}seeks\u{0020}endless\u{0020}improvement\u{0020}until\u{0020}she\u{0020}becomes\u{0020}the\u{0020}head\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}-\u{0020}no,\u{0020}even\u{0020}then,\u{0020}she\u{0020}won't\u{0020}stop.\n\nHer\u{0020}obsession\u{0020}with\u{0020}being\u{0020}the\u{0020}heir\u{0020}of\u{0020}the\u{0020}family\u{0020}makes\u{0020}her\u{0020}discipline\u{0020}herself\u{0020}strictly\u{0020}and\u{0020}constantly\u{0020}improve\u{0020}herself,\u{0020}but\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}it\u{0020}also\u{0020}brings\u{0020}her\u{0020}unnecessary\u{0020}burdens.\u{0020}She\u{0020}firmly\u{0020}believes\u{0020}that\u{0020}as\u{0020}the\u{0020}heir\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}she\u{0020}must\u{0020}be\u{0020}perfect\u{0020}in\u{0020}everything\u{0020}and\u{0020}has\u{0020}an\u{0020}overly\u{0020}persistent\u{0020}pursuit\u{0020}of\u{0020}\"perfection\",\u{0020}and\u{0020}even\u{0020}forces\u{0020}herself\u{0020}to\u{0020}do\u{0020}some\u{0020}things\u{0020}that\u{0020}she\u{0020}cannot\u{0020}do\u{0020}now\u{0020}-\u{0020}this\u{0020}is\u{0020}paranoia\u{0020}and\u{0020}also\u{0020}a\u{0020}kind\u{0020}of\u{0020}arrogance.\u{0020}She\u{0020}will\u{0020}be\u{0020}hurt\u{0020}because\u{0020}of\u{0020}this\u{0020}one\u{0020}day.", "0", "0", "0", "0", 11001, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}她是完美的淑女。在正式场合上，她的言行谈吐、穿着搭配让人无可挑剔；在战场上，她永远以最高的标准要求着自己，将任务圆满完成。她的完美得益于她的老师——蒂娜·爱森的精英教育。\n\u{1000}\u{1000}作为大贵族克雷蒂亚家族现任族长的长女，她对自己的要求极为严格，她追逐着力量，追逐着完美，追求着永无止境的提升，直到她成为克雷蒂亚家族的族长——不，就算到那时候，她也不会停下吧。\n\u{1000}\u{1000}对家族继承人的执着使她严苛自律，不断提高自己，但同时也给她带来了不必要的负担。她坚信着身为克雷蒂亚家族的继承人，就必须要事事做到完美，对于\"完美\"有着过于执着的追求，甚至会强迫自己去做一些现在的自己做不到的事——这是偏执，也是一种自负，她总会有一天因此而受伤吧。"},
[610102] = {610102, 500, "\u{0020}\u{0020}As\u{0020}the\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}Alice·Cretia\u{0020}was\u{0020}destined\u{0020}from\u{0020}the\u{0020}very\u{0020}beginning\u{0020}of\u{0020}her\u{0020}birth\u{0020}that\u{0020}her\u{0020}life\u{0020}could\u{0020}not\u{0020}and\u{0020}would\u{0020}not\u{0020}be\u{0020}allowed\u{0020}to\u{0020}be\u{0020}ordinary.\u{0020}The\u{0020}first\u{0020}sentence\u{0020}she\u{0020}remembered\u{0020}after\u{0020}she\u{0020}could\u{0020}remember\u{0020}things\u{0020}was\u{0020}what\u{0020}her\u{0020}father\u{0020}said\u{0020}-\u{0020}\"You\u{0020}will\u{0020}become\u{0020}the\u{0020}head\u{0020}of\u{0020}this\u{0020}family\u{0020}and\u{0020}lead\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}forward.\"\n\nThe\u{0020}professional\u{0020}maid\u{0020}Tina\u{0020}Eisen\u{0020}imparts\u{0020}to\u{0020}her\u{0020}the\u{0020}knowledge\u{0020}and\u{0020}etiquette\u{0020}that\u{0020}are\u{0020}due\u{0020}to\u{0020}a\u{0020}noble.\u{0020}She\u{0020}is\u{0020}naturally\u{0020}intelligent\u{0020}and\u{0020}can\u{0020}learn\u{0020}anything\u{0020}quickly.\u{0020}Of\u{0020}course,\u{0020}she\u{0020}also\u{0020}makes\u{0020}mistakes\u{0020}on\u{0020}the\u{0020}road\u{0020}of\u{0020}growth.\u{0020}At\u{0020}this\u{0020}time,\u{0020}Tina\u{0020}will\u{0020}play\u{0020}the\u{0020}role\u{0020}of\u{0020}a\u{0020}mentor,\u{0020}correct\u{0020}her\u{0020}mistakes,\u{0020}and\u{0020}tell\u{0020}her\u{0020}what\u{0020}is\u{0020}correct.\n\nWhen\u{0020}Alice\u{0020}was\u{0020}eight\u{0020}years\u{0020}old,\u{0020}she\u{0020}got\u{0020}a\u{0020}three-year-old\u{0020}sister.\u{0020}Alice\u{0020}was\u{0020}not\u{0020}dissatisfied\u{0020}with\u{0020}this.\u{0020}She\u{0020}tried\u{0020}to\u{0020}be\u{0020}a\u{0020}model\u{0020}elder\u{0020}sister\u{0020}and\u{0020}taught\u{0020}her\u{0020}sister\u{0020}Gin·Cretia.\u{0020}Regrettably,\u{0020}Gin\u{0020}and\u{0020}Alice\u{0020}chose\u{0020}an\u{0020}almost\u{0020}opposite\u{0020}path.\n\nThe\u{0020}year\u{0020}after\u{0020}Alice\u{0020}met\u{0020}her\u{0020}younger\u{0020}sister,\u{0020}Alice,\u{0020}Gin,\u{0020}and\u{0020}Tina\u{0020}were\u{0020}sent\u{0020}to\u{0020}the\u{0020}Cretia\u{0020}branch\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region\u{0020}far\u{0020}away\u{0020}from\u{0020}the\u{0020}Danube\u{0020}region\u{0020}to\u{0020}be\u{0020}raised\u{0020}as\u{0020}children\u{0020}of\u{0020}the\u{0020}branch.\u{0020}The\u{0020}reason\u{0020}was\u{0020}that\u{0020}her\u{0020}father,\u{0020}Einert\u{0020}Cretia,\u{0020}was\u{0020}worried\u{0020}that\u{0020}the\u{0020}increasingly\u{0020}fierce\u{0020}internal\u{0020}struggle\u{0020}within\u{0020}the\u{0020}family\u{0020}would\u{0020}harm\u{0020}Alice\u{0020}and\u{0020}Gin.\n\nAlice\u{0020}regarded\u{0020}her\u{0020}father's\u{0020}protection\u{0020}as\u{0020}a\u{0020}kind\u{0020}of\u{0020}distrust,\u{0020}a\u{0020}distrust\u{0020}that\u{0020}considered\u{0020}her\u{0020}not\u{0020}mature.\u{0020}Since\u{0020}then,\u{0020}she\u{0020}has\u{0020}become\u{0020}more\u{0020}stubborn\u{0020}and\u{0020}stricter\u{0020}with\u{0020}herself\u{0020}day\u{0020}by\u{0020}day.\u{0020}She\u{0020}has\u{0020}become\u{0020}the\u{0020}flawless\u{0020}young\u{0020}lady\u{0020}in\u{0020}people's\u{0020}eyes\u{0020}and\u{0020}the\u{0020}shining\u{0020}star\u{0020}in\u{0020}the\u{0020}school.\n\nShe\u{0020}graduated\u{0020}with\u{0020}almost\u{0020}all\u{0020}first-place\u{0020}grades\u{0020}and\u{0020}entered\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}of\u{0020}AEGIS,\u{0020}serving\u{0020}as\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}driver\u{0020}team\u{0020}\"Cavalier\"\u{0020}established\u{0020}by\u{0020}herself.", "0", "0", "0", "0", 11001, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}爱丽丝·克雷蒂亚作为克雷蒂亚家族的长女，从诞生之初就注定她的一生不可能，也不被允许平凡。她记事后所记住的第一句话便是她父亲所说的——\"你将会成为这个家族的家主，领导着克雷蒂亚家族前进。\"\n\u{1000}\u{1000}专业的女仆蒂娜·爱森传授她作为贵族应有的知识与礼仪。她天生聪颖，不管什么东西都能很快学会。当然，她在成长道路上也会犯错，这时候蒂娜就会起到导师的作用，指正她的错误，告诉她何为正确。\n\u{1000}\u{1000}在爱丽丝八岁的时候，她多了一个三岁的妹妹。爱丽丝并未对此感到不满。她试着去做一位模范姐姐，教导着自己的妹妹静·克雷蒂亚。遗憾的是，静与爱丽丝选择了一条几乎相反的道路。\n\u{1000}\u{1000}在爱丽丝与自己妹妹相遇的次年，爱丽丝与静、蒂娜被送往远离多瑙地区的卡佳地区克雷蒂亚分家，作为分家的孩子培养。其原因是她的父亲爱因特·克雷蒂亚担心家族日益激烈的内部斗争会伤害到爱丽丝与静。\n\u{1000}\u{1000}父亲对爱丽丝的保护被爱丽丝当做了一种不信任，一种认为她并不成熟的不信任。从那以后她变得更加偏执，对自己的要求一日比一日严格。她成为了人们眼中完美无缺的大小姐，学校里的闪烁之星。\n\u{1000}\u{1000}她以几乎各项第一的成绩毕业，进入艾吉斯的Maya\u{1000}Branch，担任由她自己建立的驾驶员小队\"猎骑\"的队长。"},
[610103] = {610103, 1000, "\u{0020}\u{0020}As\u{0020}a\u{0020}captain,\u{0020}the\u{0020}first\u{0020}problem\u{0020}Alice·Cretia\u{0020}faces\u{0020}is\u{0020}how\u{0020}to\u{0020}recruit\u{0020}team\u{0020}members.\n\nIf\u{0020}it\u{0020}were\u{0020}someone\u{0020}else,\u{0020}they\u{0020}might\u{0020}waver\u{0020}due\u{0020}to\u{0020}the\u{0020}starting\u{0020}point\u{0020}of\u{0020}having\u{0020}nothing.\u{0020}But\u{0020}she\u{0020}is\u{0020}Alice,\u{0020}the\u{0020}eldest\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.\u{0020}She\u{0020}quickly\u{0020}established\u{0020}a\u{0020}complete\u{0020}screening\u{0020}system\u{0020}and\u{0020}applied\u{0020}it\u{0020}in\u{0020}the\u{0020}actual\u{0020}test\u{0020}-\u{0020}in\u{0020}the\u{0020}end,\u{0020}only\u{0020}two\u{0020}people\u{0020}passed\u{0020}her\u{0020}test,\u{0020}which\u{0020}even\u{0020}saved\u{0020}her\u{0020}the\u{0020}step\u{0020}of\u{0020}choosing\u{0020}people.\n\nThe\u{0020}first\u{0020}person\u{0020}is\u{0020}Tina\u{0020}Eisen,\u{0020}her\u{0020}maid\u{0020}and\u{0020}her\u{0020}teacher\u{0020}-\u{0020}Alice\u{0020}was\u{0020}once\u{0020}angry\u{0020}with\u{0020}Tina\u{0020}about\u{0020}this,\u{0020}but\u{0020}eventually\u{0020}they\u{0020}reconciled.\n\nThe\u{0020}second\u{0020}person\u{0020}is\u{0020}Hank,\u{0020}a\u{0020}strange\u{0020}person\u{0020}whose\u{0020}conduct\u{0020}Alice\u{0020}couldn't\u{0020}tolerate.\u{0020}However,\u{0020}in\u{0020}battle,\u{0020}Hank\u{0020}is\u{0020}as\u{0020}reliable\u{0020}as\u{0020}her\u{0020}teacher\u{0020}Tina\u{0020}Eisen,\u{0020}so\u{0020}she\u{0020}grudgingly\u{0020}accepted\u{0020}him.\n\nThe\u{0020}last\u{0020}person\u{0020}of\u{0020}the\u{0020}team\u{0020}is\u{0020}Gin\u{0020}Cretia.\u{0020}Gin's\u{0020}entrance\u{0020}was\u{0020}entirely\u{0020}the\u{0020}result\u{0020}of\u{0020}family\u{0020}interference.\u{0020}Therefore,\u{0020}although\u{0020}unwilling,\u{0020}Alice\u{0020}still\u{0020}had\u{0020}to\u{0020}include\u{0020}a\u{0020}laggard\u{0020}in\u{0020}her\u{0020}\"elite\u{0020}team\".\n\nNow,\u{0020}Alice's\u{0020}team\u{0020}\"Cavalier\"\u{0020}is\u{0020}about\u{0020}to\u{0020}set\u{0020}sail!", "0", "0", "0", "0", 11001, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}作为一名队长，爱丽丝·克雷蒂亚首先面临的问题就是如何招募队友。\n\u{1000}\u{1000}如果换做其他人来或许会因为一无所有的开局而动摇，但她是爱丽丝，是克雷蒂亚家族的长女。她很快地就建立起了一套完整的筛选体系，并且运用在了实际测试中——最终通过她测试的人仅仅只有两人，这甚至让她省去了挑人的步骤。\n\u{1000}\u{1000}第一人是蒂娜·爱森，她的女仆，她的老师——爱丽丝曾为此和蒂娜闹过脾气，但最终还是和解了。\n\u{1000}\u{1000}第二人是汉克，一个让爱丽丝无法容忍其品行的怪人，但在战斗中，汉克就和她的老师蒂娜·爱森一样可靠，所以她勉强接受了对方。\n\u{1000}\u{1000}队伍的最后一人是静·克雷蒂亚。静的进入完全是家族干涉的结果，因此尽管不愿，爱丽丝还是得在自己的\"精英队伍\"里塞入一个吊车尾。\n\u{1000}\u{1000}现在，属于爱丽丝的队伍\"猎骑\"，即将扬帆起航！"},
[610104] = {610104, 2000, "\u{0020}\u{0020}\"I\u{0020}cannot\u{0020}fail.\"\n\nThis\u{0020}is\u{0020}a\u{0020}curse,\u{0020}a\u{0020}curse\u{0020}that\u{0020}she\u{0020}and\u{0020}her\u{0020}father\u{0020}bestowed\u{0020}upon\u{0020}herself.\n\nShe\u{0020}has\u{0020}to\u{0020}keep\u{0020}getting\u{0020}stronger\u{0020}until\u{0020}she\u{0020}becomes\u{0020}the\u{0020}master\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.\n\n\"Well\u{0020}-\u{0020}then\u{0020}what\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}do\u{0020}after\u{0020}that?\"\n\ndriver\u{0020}asked,\n\n\"Is\u{0020}there\u{0020}anything\u{0020}you\u{0020}want\u{0020}to\u{0020}do?\"\n\n\"I\u{0020}-\u{0020}\"\n\nThere'\u{0020}isn't.\n\nShe\u{0020}doesn't\u{0020}even\u{0020}have\u{0020}her\u{0020}own\u{0020}dream.\n\n\"If\u{0020}there\u{0020}isn't\u{0020}any,\u{0020}let's\u{0020}look\u{0020}for\u{0020}it\u{0020}together.\"\n\nNavigator\u{0020}extended\u{0020}his\u{0020}fist\u{0020}towards\u{0020}the\u{0020}huge\u{0020}girl.\n\n\"Let's\u{0020}go\u{0020}together\u{0020}and\u{0020}look\u{0020}for\u{0020}your\u{0020}own\u{0020}dream.\"", "0", "0", "0", "0", 11001, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"我不能失败。\"\n\u{1000}\u{1000}这是诅咒，是她与她的父亲一同赠予自己的诅咒。\n\u{1000}\u{1000}她要不断地变强，直到她成为克雷蒂亚家族的主人。\n\u{1000}\u{1000}\"那——之后你想做什么呢？\"\n\u{1000}\u{1000}领航问，\n\u{1000}\u{1000}\"有什么想做的吗？\"\n\u{1000}\u{1000}\"我——\"\n\u{1000}\u{1000}她没有。\n\u{1000}\u{1000}她甚至没有自己的梦想。\n\u{1000}\u{1000}\"没有的话，就一起去找吧。\"\n\u{1000}\u{1000}领航朝巨大的少女伸出拳头，\n\u{1000}\u{1000}\"我们一起去吧，寻找属于你自己的梦想。\""},
[610200] = {610200, 0, "[Name]\u{0020}Kokorokami\n[B-Day]\u{0020}Date\u{0020}of\u{0020}the\u{0020}birth\u{0020}of\u{0020}the\u{0020}god\n[Compatability\u{0020}Rate]\u{0020}87％\n[Height]\u{0020}31m\n[Squad]\u{0020}Shingyou\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}God\u{0020}has\u{0020}no\u{0020}desire", "0", "0", "0", "0", 11002, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}心纸\n[B-Day]\u{1000}神诞之日\n[幻化核心适格率]\u{1000}87％\n[Height]\u{1000}31m\n[部队]\u{1000}\u{1000}心经屋\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}神没有欲望"},
[610201] = {610201, 100, "\u{0020}\u{0020}The\u{0020}impression\u{0020}she\u{0020}gives\u{0020}is\u{0020}that\u{0020}she\u{0020}is\u{0020}ethereal,\u{0020}as\u{0020}if\u{0020}she\u{0020}doesn't\u{0020}belong\u{0020}here\u{0020}and\u{0020}could\u{0020}disappear\u{0020}from\u{0020}this\u{0020}world\u{0020}at\u{0020}any\u{0020}time.\u{0020}Even\u{0020}those\u{0020}close\u{0020}to\u{0020}her\u{0020}rarely\u{0020}see\u{0020}her\u{0020}talking.\u{0020}She\u{0020}is\u{0020}inherently\u{0020}difficult\u{0020}to\u{0020}approach,\u{0020}and\u{0020}there\u{0020}is\u{0020}an\u{0020}insurmountable\u{0020}gap\u{0020}between\u{0020}her\u{0020}and\u{0020}others.\n\nMost\u{0020}of\u{0020}the\u{0020}time,\u{0020}this\u{0020}girl\u{0020}remains\u{0020}in\u{0020}an\u{0020}almost\u{0020}stationary\u{0020}state.\u{0020}Only\u{0020}when\u{0020}someone\u{0020}occasionally\u{0020}talks\u{0020}to\u{0020}her\u{0020}will\u{0020}she\u{0020}prove\u{0020}with\u{0020}a\u{0020}gentle\u{0020}and\u{0020}pleasant\u{0020}voice\u{0020}that\u{0020}she\u{0020}is\u{0020}not\u{0020}an\u{0020}exquisite\u{0020}witch\u{0020}doll.\u{0020}When\u{0020}she\u{0020}speaks,\u{0020}her\u{0020}old-fashioned\u{0020}tone\u{0020}makes\u{0020}people\u{0020}not\u{0020}think\u{0020}she\u{0020}is\u{0020}a\u{0020}child,\u{0020}but\u{0020}more\u{0020}like\u{0020}an\u{0020}elderly\u{0020}granny.\n\nIt\u{0020}is\u{0020}said\u{0020}that\u{0020}this\u{0020}series\u{0020}of\u{0020}strange\u{0020}manifestations\u{0020}are\u{0020}related\u{0020}to\u{0020}the\u{0020}deity\u{0020}she\u{0020}serves\u{0020}as\u{0020}a\u{0020}\"Miko\".\u{0020}Of\u{0020}course,\u{0020}whether\u{0020}the\u{0020}deity\u{0020}really\u{0020}exists\u{0020}is\u{0020}a\u{0020}question\u{0020}that\u{0020}requires\u{0020}time\u{0020}and\u{0020}effort\u{0020}to\u{0020}verify.", "0", "0", "0", "0", 11002, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}她留给人的印象是轻飘飘的，似乎不属于这个地方，随时都会从这个世界上消失。即便是身边与她关系亲近的人，也很少见到她主动开口说话的时候。她天生就让人感到难以接近，有一种无法跨过的隔阂建立在她与旁人之间。\n\u{1000}\u{1000}大部分的时间中，这名女孩都保持着近乎静止的状态。只有偶尔有人向她搭话时，她才会用婉转好听的声音证明她并不是个精致的巫女娃娃。而当她开口时却总以\"老身\"自称，老气横秋的语气让人不觉得她是个孩子，更像是一位上了年龄的婆婆。\n\u{1000}\u{1000}据说，这一系列怪异的表现与她身为\"巫女\"，所侍奉的神灵有关联。当然，神灵是否真的存在，这是一个需要用时间与精力去验证的问题。"},
[610202] = {610202, 500, "\u{0020}\u{0020}Sin\u{0020}symbolizes\u{0020}despair.\u{0020}Their\u{0020}appearance\u{0020}once\u{0020}almost\u{0020}completely\u{0020}destroyed\u{0020}the\u{0020}order\u{0020}and\u{0020}rules\u{0020}that\u{0020}humanity\u{0020}had\u{0020}evolved\u{0020}over\u{0020}thousands\u{0020}of\u{0020}years.\n\nMorality\u{0020}and\u{0020}law\u{0020}become\u{0020}fragile\u{0020}in\u{0020}the\u{0020}face\u{0020}of\u{0020}absolute\u{0020}violence\u{0020}and\u{0020}death.\u{0020}People\u{0020}no\u{0020}longer\u{0020}long\u{0020}for\u{0020}good\u{0020}virtues\u{0020}and\u{0020}spiritual\u{0020}purity.\n\nThe\u{0020}city\u{0020}where\u{0020}a\u{0020}girl\u{0020}lived\u{0020}fell\u{0020}into\u{0020}such\u{0020}despair.\u{0020}Families\u{0020}were\u{0020}broken\u{0020}up,\u{0020}brothers\u{0020}turned\u{0020}against\u{0020}each\u{0020}other,\u{0020}and\u{0020}homes\u{0020}were\u{0020}destroyed.\u{0020}These\u{0020}things,\u{0020}which\u{0020}would\u{0020}have\u{0020}been\u{0020}reported\u{0020}prominently\u{0020}in\u{0020}the\u{0020}newspapers\u{0020}if\u{0020}only\u{0020}one\u{0020}occurred\u{0020}in\u{0020}the\u{0020}past,\u{0020}suddenly\u{0020}became\u{0020}ubiquitous.\u{0020}The\u{0020}girl\u{0020}witnessed\u{0020}the\u{0020}continuous\u{0020}occurrence\u{0020}of\u{0020}tragedies\u{0020}but\u{0020}could\u{0020}do\u{0020}nothing.\n\nThe\u{0020}idea\u{0020}of\u{0020}wanting\u{0020}to\u{0020}save\u{0020}something\u{0020}and\u{0020}wanting\u{0020}to\u{0020}change\u{0020}something\u{0020}gradually\u{0020}emerged\u{0020}in\u{0020}the\u{0020}girl's\u{0020}heart.\u{0020}However,\u{0020}she\u{0020}had\u{0020}no\u{0020}power,\u{0020}no\u{0020}power\u{0020}to\u{0020}influence\u{0020}reality.\u{0020}With\u{0020}just\u{0020}a\u{0020}wish,\u{0020}she\u{0020}could\u{0020}do\u{0020}nothing\u{0020}-\u{0020}such\u{0020}a\u{0020}thing,\u{0020}she\u{0020}also\u{0020}understood.\n\nAfterwards,\u{0020}an\u{0020}old\u{0020}man\u{0020}gave\u{0020}the\u{0020}girl\u{0020}a\u{0020}chance.\u{0020}An\u{0020}old\u{0020}man\u{0020}on\u{0020}his\u{0020}deathbed\u{0020}told\u{0020}the\u{0020}girl\u{0020}how\u{0020}to\u{0020}save\u{0020}the\u{0020}world\u{0020}before\u{0020}her\u{0020}eyes.\u{0020}However,\u{0020}such\u{0020}an\u{0020}approach\u{0020}comes\u{0020}at\u{0020}a\u{0020}cost.\u{0020}Something\u{0020}extremely\u{0020}precious\u{0020}to\u{0020}the\u{0020}girl\u{0020}must\u{0020}be\u{0020}sacrificed\u{0020}for\u{0020}her\u{0020}surrounding\u{0020}world\u{0020}not\u{0020}to\u{0020}fall\u{0020}into\u{0020}ruin.\n\n\"So\u{0020}what\u{0020}do\u{0020}I\u{0020}have\u{0020}to\u{0020}pay?\"\n\nThe\u{0020}old\u{0020}man\u{0020}gave\u{0020}her\u{0020}a\u{0020}reply:\u{0020}She\u{0020}would\u{0020}lose\u{0020}her\u{0020}name,\u{0020}her\u{0020}identity,\u{0020}and\u{0020}her\u{0020}life.\u{0020}From\u{0020}then\u{0020}on,\u{0020}she\u{0020}would\u{0020}no\u{0020}longer\u{0020}be\u{0020}treated\u{0020}as\u{0020}a\u{0020}human\u{0020}being.\u{0020}She\u{0020}would\u{0020}become\u{0020}a\u{0020}symbol,\u{0020}an\u{0020}emblem,\u{0020}and\u{0020}a\u{0020}spiritual\u{0020}sustenance.\u{0020}Only\u{0020}in\u{0020}this\u{0020}way\u{0020}would\u{0020}the\u{0020}people\u{0020}in\u{0020}despair\u{0020}return\u{0020}to\u{0020}their\u{0020}former\u{0020}state.\n\nThe\u{0020}girl\u{0020}agreed.\n\nJust\u{0020}like\u{0020}that,\u{0020}a\u{0020}girl\u{0020}had\u{0020}disappeared.\n\nInstead\u{0020}the\u{0020}Miko\u{0020}named\u{0020}Kokorokami\u{0020}was\u{0020}born.\u{0020}Along\u{0020}with\u{0020}her\u{0020}birth,\u{0020}there\u{0020}was\u{0020}also\u{0020}a\u{0020}shrine\u{0020}named\u{0020}\"Shingyou\".\u{0020}Kokorokami\u{0020}guided\u{0020}the\u{0020}people\u{0020}who\u{0020}had\u{0020}lost\u{0020}truth,\u{0020}kindness\u{0020}and\u{0020}beauty\u{0020}to\u{0020}rebuild\u{0020}the\u{0020}human\u{0020}city.\u{0020}The\u{0020}existence\u{0020}of\u{0020}Kokorokami\u{0020}has\u{0020}become\u{0020}a\u{0020}lighthouse\u{0020}and\u{0020}the\u{0020}fire\u{0020}of\u{0020}hope\u{0020}in\u{0020}the\u{0020}hearts\u{0020}of\u{0020}the\u{0020}people.\u{0020}No\u{0020}one\u{0020}will\u{0020}understand\u{0020}who\u{0020}Kokorokami\u{0020}was\u{0020}before.\u{0020}\n\n\u{0020}People\u{0020}only\u{0020}care\u{0020}about\u{0020}what\u{0020}Kokorokami\u{0020}can\u{0020}do\u{0020}now.\u{0020}\"The\u{0020}gods\u{0020}only\u{0020}have\u{0020}value\u{0020}when\u{0020}there\u{0020}is\u{0020}turmoil.\u{0020}I\u{0020}am\u{0020}just\u{0020}driven\u{0020}forward\u{0020}by\u{0020}such\u{0020}a\u{0020}mission.\"", "0", "0", "0", "0", 11002, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}原罪象征着绝望，它们的出现，一度将人类经历过千年时光演变的秩序与规则摧毁殆尽。\n\u{1000}\u{1000}道德与法律，在绝对的暴力与死亡面前变得脆弱不堪，人们不再憧憬美好的品质，不再追求精神上的纯洁。\n\u{1000}\u{1000}一名女孩所生活的城市，便陷入了这样的绝望中。妻离子散，兄弟反目，家破人亡，这些在过去出现一件便会登上报纸大张旗鼓报道的东西，一下子就变得比比皆是起来。女孩目睹着惨剧不断发生，却也什么都做不到。\n\u{1000}\u{1000}想要挽救点什么，想要改变点什么，这样的想法渐渐在女孩的心中萌生。但是，她没有力量，没有能够影响现实的力量，光凭着心愿，什么也做不到——这样的事情，她也是明白的。\n\u{1000}\u{1000}之后，一个老人给了女孩机会。一个行将就木的老人告诉了女孩如何去拯救她眼前的世界。但是，这样的做法是有代价的，必须要付出对于女孩来说尤为宝贵的东西，她周围的世界才不会走向破灭。\n\u{1000}\u{1000}\"那么，我要付出什么呢？\"\n\u{1000}\u{1000}老人给了她答复：她会失去自己的名字，她会失去自己的身份，她会失去自己的人生，从此以后，她将不再会被人视为人去对待，她会成为一个符号，一个象征，一个精神寄托。只要这样，陷入绝望的人们就会恢复以往的模样。\n\u{1000}\u{1000}女孩同意了。\n\u{1000}\u{1000}就这样，世界上少了一名普普通通的，有着自己梦想的女孩。\n\u{1000}\u{1000}名为心纸的巫女，在女孩消失后便诞生了，一同诞生的还有名为\"心经屋\"的神社。心纸引导着失去了真善美的民众，重新建立人类的城市。心纸的存在，成为了人民心中的灯塔，希望的火光。没有人会去了解心纸之前是什么人，人们只关心现在的心纸能做什么。\n\u{1000}\u{1000}\"神明只有在动乱时才有存在的价值，老身只不过是被这样的使命驱使着前行罢了。\""},
[610203] = {610203, 1000, "\u{0020}\u{0020}As\u{0020}the\u{0020}spiritual\u{0020}belief\u{0020}of\u{0020}a\u{0020}city\u{0020}and\u{0020}even\u{0020}a\u{0020}region,\u{0020}Miko\u{0020}Kokorokami\u{0020}of\u{0020}Shingyou\u{0020}will\u{0020}naturally\u{0020}receive\u{0020}the\u{0020}invitation\u{0020}from\u{0020}the\u{0020}AEGIS\u{0020}government.\n\nAfter\u{0020}the\u{0020}negotiation,\u{0020}Shingyou\u{0020}refused\u{0020}to\u{0020}join\u{0020}the\u{0020}command\u{0020}system\u{0020}of\u{0020}AEGIS\u{0020}and\u{0020}chose\u{0020}to\u{0020}become\u{0020}an\u{0020}AVG\u{0020}team\u{0020}under\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters.\n\nHowever,\u{0020}despite\u{0020}having\u{0020}joined\u{0020}AEGIS,\u{0020}the\u{0020}team\u{0020}named\u{0020}Shingyou\u{0020}always\u{0020}seemed\u{0020}out\u{0020}of\u{0020}place\u{0020}to\u{0020}the\u{0020}rest\u{0020}of\u{0020}the\u{0020}team\u{0020}at\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Most\u{0020}of\u{0020}them\u{0020}chose\u{0020}to\u{0020}stay\u{0020}away.\u{0020}Kokorokami\u{0020}turned\u{0020}a\u{0020}deaf\u{0020}ear\u{0020}to\u{0020}Shingyou's\u{0020}situation.\u{0020}For\u{0020}her\u{0020}now,\u{0020}how\u{0020}to\u{0020}protect\u{0020}the\u{0020}world\u{0020}and\u{0020}protect\u{0020}the\u{0020}people\u{0020}who\u{0020}believe\u{0020}in\u{0020}her\u{0020}is\u{0020}the\u{0020}most\u{0020}important\u{0020}thing\u{0020}at\u{0020}the\u{0020}moment.", "0", "0", "0", "0", 11002, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}作为一座城市乃至一个地区的精神信仰，心经屋的巫女心纸自然会接受到艾吉斯政府的邀请。\n\u{1000}\u{1000}在经过一段时间的协商后，心经屋拒绝了加入艾吉斯的指挥系统，选择成为艾吉斯九州总部麾下的一支avg小队。\n\u{1000}\u{1000}然而，尽管已经加入了艾吉斯，但对于九州总部的其他小队而言，这支名为心经屋的队伍总是显得有些格格不入。大部分人选择敬而远之。心纸对心经屋的处境视若罔闻，对于现在的她而言，如何保护这个世界，如何守护信仰着自己的人民，才是当下最重要的事情。"},
[610204] = {610204, 2000, "\u{0020}\u{0020}Mirror\n\nThe\u{0020}existence\u{0020}of\u{0020}mirrors\u{0020}enables\u{0020}people\u{0020}to\u{0020}clearly\u{0020}recognize\u{0020}their\u{0020}own\u{0020}appearance.\n\nHowever,\u{0020}the\u{0020}only\u{0020}thing\u{0020}that\u{0020}can\u{0020}serve\u{0020}as\u{0020}a\u{0020}mirror\u{0020}for\u{0020}the\u{0020}gigantified\u{0020}girl\u{0020}is\u{0020}the\u{0020}sea\u{0020}surface\u{0020}that\u{0020}can\u{0020}reflect\u{0020}the\u{0020}inverted\u{0020}image.\n\nSo,\u{0020}miko\u{0020}stared\u{0020}at\u{0020}the\u{0020}other\u{0020}self\u{0020}in\u{0020}the\u{0020}sea,\n\n\"Everything\u{0020}about\u{0020}Kokorokami\u{0020}is\u{0020}fictional,\u{0020}the\u{0020}tone,\u{0020}the\u{0020}identity,\u{0020}the\u{0020}deity,\u{0020}everything\u{0020}is\u{0020}fictionalized\u{0020}because\u{0020}someone\u{0020}needed\u{0020}it.\"\n\n\"Even\u{0020}so,\u{0020}do\u{0020}you\u{0020}think\u{0020}my\u{0020}existence\u{0020}is\u{0020}real?\"", "0", "0", "0", "0", 11002, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}镜子，\n\u{1000}\u{1000}镜子的存在，能够让人清晰地认识到自己的模样。\n\u{1000}\u{1000}不过，能够作为巨大化少女的镜子的东西，也只剩下能映出倒影的海面。\n\u{1000}\u{1000}于是，巫女凝视着海中的另一个自己，\n\u{1000}\u{1000}\"老身……‘心纸’的一切都是虚构的，语气，身份，神明，一切都是因为有人需要，所以才虚构出来的东西。\"\n\u{1000}\u{1000}\"即便这样——您也认为老身的存在是真实的吗？\""},
[610300] = {610300, 0, "[Name]\u{0020}Suzuki\u{0020}Seifung\n[B-Day]\u{0020}March\u{0020}16\n[Compatability\u{0020}Rate]\u{0020}86％\n[Height]\u{0020}32m\n[Squad]\u{0020}Fuurinkazan\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Farming\u{0020}with\u{0020}sweating\u{0020}under\u{0020}the\u{0020}sunlight", "0", "0", "0", "0", 11003, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}铃木清风\n[B-Day]\u{1000}3月16日\n[幻化核心适格率]\u{1000}86％\n[Height]\u{1000}32m\n[部队]\u{1000}风林火山\n\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}在阳光下挥洒汗水的耕作"},
[610301] = {610301, 100, "\u{0020}Suzuki\u{0020}Seifung,\u{0020}with\u{0020}incredible\u{0020}affinity,\u{0020}plays\u{0020}the\u{0020}role\u{0020}of\u{0020}\"mother\"\u{0020}in\u{0020}the\u{0020}team.\u{0020}In\u{0020}fact,\u{0020}this\u{0020}young\u{0020}girl\u{0020}does\u{0020}take\u{0020}care\u{0020}of\u{0020}her\u{0020}team\u{0020}members\u{0020}as\u{0020}if\u{0020}they\u{0020}were\u{0020}her\u{0020}own\u{0020}children.\n\nLike\u{0020}all\u{0020}mothers,\u{0020}Suzuki\u{0020}Seifung\u{0020}is\u{0020}very\u{0020}protective\u{0020}of\u{0020}her\u{0020}children,\u{0020}and\u{0020}if\u{0020}anyone\u{0020}dares\u{0020}to\u{0020}attack\u{0020}her\u{0020}team,\u{0020}she\u{0020}will\u{0020}turn\u{0020}into\u{0020}a\u{0020}demon.\n\nAccording\u{0020}to\u{0020}a\u{0020}certain\u{0020}reporter\u{0020}from\u{0020}the\u{0020}Danube\u{0020}Branch:\u{0020}At\u{0020}the\u{0020}AEGIS\u{0020}regional\u{0020}department\u{0020}exchange\u{0020}meeting,\u{0020}Suzuki\u{0020}Seifung\u{0020}once\u{0020}had\u{0020}a\u{0020}physical\u{0020}conflict\u{0020}with\u{0020}the\u{0020}other\u{0020}party\u{0020}because\u{0020}someone\u{0020}ridiculed\u{0020}her\u{0020}team\u{0020}members.\u{0020}However,\u{0020}as\u{0020}this\u{0020}report\u{0020}was\u{0020}completely\u{0020}inconsistent\u{0020}with\u{0020}the\u{0020}impression\u{0020}given\u{0020}by\u{0020}Suzuki\u{0020}Seifung,\u{0020}it\u{0020}was\u{0020}considered\u{0020}hearsay.", "0", "0", "0", "0", 11003, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}铃木清风，拥有着不可思议的亲和力，在队伍中扮演着\"妈妈\"的角色。实际上，这名少女也确实是把自己的队员当做自己的孩子一样照顾。\n\u{1000}\u{1000}就如同所有妈妈一样，铃木清风非常袒护自家的孩子，如果有人敢对她的队员们出手的话，她也将化身成恶鬼。\n\u{1000}\u{1000}据Danube\u{1000}Branch的某位记者报道：在艾吉斯各地区部门交流会上，铃木清风曾经因有人讥讽了自己队员而与对方发生了肢体冲突。不过，因该报道完全不符铃木清风给人的印象，被当做绯闻处理了。"},
[610302] = {610302, 500, "\u{0020}\u{0020}Born\u{0020}into\u{0020}a\u{0020}poor\u{0020}family,\u{0020}Suzuki\u{0020}Seifung\u{0020}was\u{0020}burdened\u{0020}with\u{0020}responsibilities\u{0020}far\u{0020}beyond\u{0020}her\u{0020}shoulders.\n\nHer\u{0020}mother\u{0020}died\u{0020}of\u{0020}illness\u{0020}before\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin,\u{0020}and\u{0020}her\u{0020}father,\u{0020}who\u{0020}was\u{0020}a\u{0020}soldier,\u{0020}was\u{0020}injured\u{0020}and\u{0020}disabled\u{0020}in\u{0020}the\u{0020}battle.\u{0020}When\u{0020}she\u{0020}became\u{0020}the\u{0020}pillar\u{0020}of\u{0020}the\u{0020}family,\u{0020}she\u{0020}was\u{0020}only\u{0020}eight\u{0020}years\u{0020}old.\n\nThe\u{0020}eight-year-old\u{0020}Suzuki\u{0020}Seifung\u{0020}relied\u{0020}on\u{0020}the\u{0020}assistance\u{0020}of\u{0020}the\u{0020}local\u{0020}government\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}her\u{0020}bedridden\u{0020}father\u{0020}and\u{0020}her\u{0020}younger\u{0020}sister.\u{0020}Suzuki\u{0020}Seifung\u{0020}seemed\u{0020}to\u{0020}have\u{0020}been\u{0020}deprived\u{0020}of\u{0020}her\u{0020}identity\u{0020}as\u{0020}a\u{0020}child\u{0020}since\u{0020}then\u{0020}and\u{0020}was\u{0020}forced\u{0020}to\u{0020}become\u{0020}an\u{0020}adult\u{0020}and\u{0020}someone\u{0020}others\u{0020}relied\u{0020}on.\n\nSuzuki\u{0020}Seifung\u{0020}maintained\u{0020}the\u{0020}precarious\u{0020}family\u{0020}for\u{0020}several\u{0020}years.\u{0020}But\u{0020}the\u{0020}government\u{0020}subsidy\u{0020}could\u{0020}only\u{0020}support\u{0020}this\u{0020}family\u{0020}at\u{0020}a\u{0020}minimal\u{0020}level.\u{0020}In\u{0020}order\u{0020}to\u{0020}provide\u{0020}a\u{0020}more\u{0020}comfortable\u{0020}residence\u{0020}for\u{0020}her\u{0020}father\u{0020}and\u{0020}to\u{0020}provide\u{0020}her\u{0020}sister\u{0020}with\u{0020}a\u{0020}better\u{0020}education,\u{0020}Suzuki\u{0020}Seifung\u{0020}eventually\u{0020}decided\u{0020}to\u{0020}take\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test.\n\nWith\u{0020}a\u{0020}skeptical\u{0020}attitude,\u{0020}Suzuki\u{0020}Seifung\u{0020}participated\u{0020}in\u{0020}and\u{0020}passed\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test,\u{0020}becoming\u{0020}a\u{0020}prospective\u{0020}driver\u{0020}about\u{0020}to\u{0020}head\u{0020}to\u{0020}the\u{0020}Frontier.\u{0020}Although\u{0020}she\u{0020}knew\u{0020}nothing\u{0020}about\u{0020}what\u{0020}a\u{0020}\"Driver\"\u{0020}was\u{0020}before,\u{0020}her\u{0020}father,\u{0020}who\u{0020}was\u{0020}once\u{0020}a\u{0020}soldier,\u{0020}told\u{0020}her\u{0020}that\u{0020}she\u{0020}might\u{0020}have\u{0020}to\u{0020}shoulder\u{0020}a\u{0020}greater\u{0020}mission.", "0", "0", "0", "0", 11003, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}出生在贫困家庭的铃木清风，从小就背负着远超她小小的肩膀能承受的重任。\u{1000}\n\u{1000}\u{1000}她的母亲在原罪入侵前便因为疾病去世，而她身为军人的父亲也在战斗中负伤残疾。她成为家庭支柱的时候，仅仅只有八岁。\n\u{1000}\u{1000}八岁的铃木清风依靠着当地政府的救助，照顾卧床的父亲与自己的妹妹。铃木清风似乎那时起就已经被剥夺了作为孩子的身份，被迫成为了大人，成为了他人的依靠。\n\u{1000}\u{1000}铃木清风维持着风雨飘摇的家庭，度过了数年的时间。但政府的补助始终也只是能让这个家庭勉强维持温饱而已，为了让父亲有更舒适的居住地，为了让妹妹能够接受更好的教育，铃木清风最终还是决定接受\"适格率测试\"。\n\u{1000}\u{1000}带着怀疑的态度，铃木清风参与并通过了适格率测试，成为了一名即将奔赴前线的准驾驶员。尽管她此前对于\"驾驶员\"是什么一事一无所知，不过曾为军人的父亲告诉她，她可能要肩负更加伟大的使命了。"},
[610303] = {610303, 1000, "\u{0020}\u{0020}Although\u{0020}joining\u{0020}AEGIS\u{0020}was\u{0020}out\u{0020}of\u{0020}helplessness,\u{0020}Suzuki\u{0020}Seifung\u{0020}has\u{0020}the\u{0020}talent\u{0020}as\u{0020}a\u{0020}driver\u{0020}and\u{0020}even\u{0020}as\u{0020}a\u{0020}team\u{0020}leader.\n\nDuring\u{0020}training,\u{0020}she\u{0020}can\u{0020}grasp\u{0020}every\u{0020}little\u{0020}changes\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}in\u{0020}seconds\u{0020}and\u{0020}make\u{0020}the\u{0020}correct\u{0020}decisions.\u{0020}In\u{0020}daily\u{0020}life,\u{0020}she\u{0020}can\u{0020}get\u{0020}along\u{0020}well\u{0020}with\u{0020}every\u{0020}newly\u{0020}acquainted\u{0020}classmate\u{0020}and\u{0020}understand\u{0020}the\u{0020}characteristics\u{0020}of\u{0020}each\u{0020}classmate.\u{0020}After\u{0020}careful\u{0020}consideration,\u{0020}the\u{0020}AEGIS\u{0020}headquarters\u{0020}chose\u{0020}Suzuki\u{0020}Seifung,\u{0020}who\u{0020}has\u{0020}no\u{0020}actual\u{0020}combat\u{0020}experience,\u{0020}as\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}new\u{0020}special\u{0020}operations\u{0020}team\u{0020}\"Fuurinkazan\".\n\n\"Although\u{0020}I\u{0020}don't\u{0020}quite\u{0020}understand\u{0020}what\u{0020}the\u{0020}captain\u{0020}should\u{0020}do,\u{0020}but\u{0020}I'll\u{0020}just\u{0020}take\u{0020}care\u{0020}of\u{0020}them\u{0020}like\u{0020}children,\u{0020}right?\u{0020}That's\u{0020}easy!\"", "0", "0", "0", "0", 11003, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}虽说加入艾吉斯是出于无奈，但铃木清风拥有作为驾驶员，甚至是作为领队的才能。\n\u{1000}\u{1000}在训练中，她能最快速度地把握战场上以分秒为单位的变化，做出正确的抉择。在日常生活中，她能融洽地与每个新认识的同学相处，了解每个同学的特点。\n\u{1000}\u{1000}艾吉斯指挥部经过慎重的斟酌后，选择将没有实战经验的铃木清风任命为新特种作战小队\"风林火山\"的队长。\n\u{1000}\u{1000}\"咱虽然不太明白队长具体是做什么的——不过，把她们当做小孩子对待就可以了吧？呜姆呜姆，那就简单了！\""},
[610304] = {610304, 2000, "\u{0020}\u{0020}The\u{0020}young\u{0020}girl\u{0020}walked\u{0020}carefully.\n\nShe\u{0020}was\u{0020}worried\u{0020}that\u{0020}she\u{0020}might\u{0020}accidentally\u{0020}ruin\u{0020}this\u{0020}golden\u{0020}rice\u{0020}field\u{0020}under\u{0020}her\u{0020}feet.\n\nShe\u{0020}crouched\u{0020}down\u{0020}and\u{0020}leaned\u{0020}closer\u{0020}to\u{0020}look\u{0020}at\u{0020}these\u{0020}rice\u{0020}plants.\n\nThe\u{0020}young\u{0020}girl\u{0020}carefully\u{0020}extended\u{0020}her\u{0020}hand,\u{0020}but\u{0020}fearfully\u{0020}withdrew\u{0020}it.\u{0020}She\u{0020}could\u{0020}only\u{0020}watch\u{0020}like\u{0020}this,\u{0020}quietly\u{0020}watch.\n\n\"Navigator,\u{0020}our\u{0020}field\u{0020}is\u{0020}even\u{0020}more\u{0020}beautiful\u{0020}than\u{0020}this\u{0020}one.\"\n\n\"After\u{0020}the\u{0020}war\u{0020}is\u{0020}over,\u{0020}I\u{0020}will\u{0020}bring\u{0020}you,\u{0020}Navigator\u{0020}to\u{0020}my\u{0020}home\u{0020}and\u{0020}enjoy\u{0020}the\u{0020}scene\u{0020}of\u{0020}the\u{0020}autumn\u{0020}harvest\u{0020}together!\"\n\n\"This\u{0020}is\u{0020}the\u{0020}promise\u{0020}with\u{0020}Navigator,\u{0020}and\u{0020}I\u{0020}will\u{0020}keep\u{0020}it\u{0020}even\u{0020}if\u{0020}I\u{0020}die!\"", "0", "0", "0", "0", 11003, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}少女小心翼翼地走着，\n\u{1000}\u{1000}她担心自己一不小心将脚下这片金灿灿的稻田毁了。\n\u{1000}\u{1000}她蹲下来，凑近了看这些稻子。\n\u{1000}\u{1000}少女小心翼翼伸出了手，但又害怕地缩回了手，只好就这么看着，静静地看着。\n\u{1000}\u{1000}\"领航，咱家的田比这里还要美哦。\"\n\u{1000}\u{1000}\"战争结束之后，咱一定要把领航你拉到家里面，一起欣赏秋天丰收时的景象！\"\n\u{1000}\u{1000}\"所以，在那之前，千万不要死噢，领航。\""},
[610400] = {610400, 0, "[Name]\u{0020}Kuriyama\u{0020}Seiran\n[B-Day]\u{0020}June\u{0020}20\n[Compatability\u{0020}Rate]\u{0020}79％\n[Height]\u{0020}33m\n[Squad]\u{0020}Fuurinkazan\n[Affiliation]\u{0020}Kyushu\n[Interest]\u{0020}Bargaining\u{0020}for\u{0020}a\u{0020}50%\u{0020}off", "0", "0", "0", "0", 11004, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}栗山青鸾\n[B-Day]\u{1000}6月20日\n[幻化核心适格率]\u{1000}79％\n[Height]\u{1000}33m\n[部队]\u{1000}风林火山\n\u{00A0}[隶属]\u{1000}九州支部\n[Interest]\u{1000}杀价50%之后购物"},
[610401] = {610401, 100, "\u{0020}\u{0020}The\u{0020}physical\u{0020}defect\u{0020}made\u{0020}this\u{0020}kind-hearted\u{0020}girl\u{0020}close\u{0020}her\u{0020}heart\u{0020}for\u{0020}a\u{0020}while.\n\nAn\u{0020}accident\u{0020}made\u{0020}her\u{0020}lose\u{0020}her\u{0020}eyes\u{0020}and\u{0020}hands.\u{0020}Although\u{0020}the\u{0020}technology\u{0020}of\u{0020}AEGIS\u{0020}enabled\u{0020}her\u{0020}to\u{0020}live\u{0020}like\u{0020}a\u{0020}normal\u{0020}person,\u{0020}the\u{0020}physical\u{0020}defect\u{0020}could\u{0020}no\u{0020}longer\u{0020}be\u{0020}compensated.\u{0020}The\u{0020}strange\u{0020}looks\u{0020}that\u{0020}people\u{0020}around\u{0020}her\u{0020}threw\u{0020}at\u{0020}her\u{0020}from\u{0020}time\u{0020}to\u{0020}time\u{0020}made\u{0020}her\u{0020}gradually\u{0020}become\u{0020}self-abased\u{0020}and\u{0020}start\u{0020}to\u{0020}hate\u{0020}herself\u{0020}with\u{0020}a\u{0020}disabled\u{0020}body.\n\nThe\u{0020}care\u{0020}from\u{0020}the\u{0020}members\u{0020}of\u{0020}Fuurinkazan\u{0020}helped\u{0020}the\u{0020}girl\u{0020}gradually\u{0020}walk\u{0020}out\u{0020}of\u{0020}the\u{0020}shadow,\u{0020}but\u{0020}she\u{0020}was\u{0020}still\u{0020}afraid\u{0020}that\u{0020}her\u{0020}body\u{0020}would\u{0020}scare\u{0020}others\u{0020}and\u{0020}that\u{0020}she\u{0020}would\u{0020}be\u{0020}disliked.\n\nThe\u{0020}kindness\u{0020}inherent\u{0020}in\u{0020}the\u{0020}girl\u{0020}was\u{0020}concealed\u{0020}by\u{0020}her\u{0020}self-abasement\u{0020}and\u{0020}terrifying\u{0020}appearance.\u{0020}Only\u{0020}those\u{0020}close\u{0020}to\u{0020}her\u{0020}could\u{0020}understand\u{0020}that,\u{0020}Kuriyama\u{0020}Seiran\u{0020}was\u{0020}just\u{0020}a\u{0020}very\u{0020}ordinary,\u{0020}but\u{0020}very\u{0020}kind\u{0020}girl.", "0", "0", "0", "0", 11004, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}躯体的缺陷让这位善良的少女一度封闭了自己的内心。\n\u{1000}\u{1000}一场事故让她失去了自己的眼睛与手。尽管艾吉斯的技术让她能像正常人一样生活，但身体的缺陷却已经无法弥补。周围人时不时向她投来的异样眼光，让她渐渐自卑，开始厌恶起拥有残缺身体的自己。\n\u{1000}\u{1000}来自风林火山成员的关怀让少女渐渐走出阴影，但她心里依然害怕着自己的身体会吓到旁人，害怕自己被人讨厌。\n\u{1000}\u{1000}少女本质的善良被她的自卑与可怖的外表遮掩，只有亲近她的人才能明白——栗山青鸾，其实只是一名很普通的，但又很善良的，邻家女孩般的少女。"},
[610402] = {610402, 500, "\u{0020}Kuriyama\u{0020}Seiran\u{0020}was\u{0020}supposed\u{0020}to\u{0020}have\u{0020}a\u{0020}rather\u{0020}ordinary\u{0020}life.\u{0020}She\u{0020}would\u{0020}have\u{0020}known\u{0020}many\u{0020}peers\u{0020}at\u{0020}school,\u{0020}and\u{0020}then,\u{0020}perhaps,\u{0020}confessed\u{0020}to\u{0020}the\u{0020}person\u{0020}she\u{0020}liked\u{0020}during\u{0020}middle\u{0020}school\u{0020}or\u{0020}university,\u{0020}and\u{0020}had\u{0020}a\u{0020}relationship.\u{0020}The\u{0020}relationship\u{0020}might\u{0020}have\u{0020}gone\u{0020}smoothly\u{0020}or\u{0020}not,\u{0020}but\u{0020}she\u{0020}should\u{0020}have\u{0020}gained\u{0020}her\u{0020}own\u{0020}happiness\u{0020}-\u{0020}but,\n\nShe\u{0020}lost\u{0020}such\u{0020}a\u{0020}life.\u{0020}Her\u{0020}life\u{0020}was\u{0020}taken\u{0020}away,\u{0020}or\u{0020}rather,\u{0020}destroyed.\n\nKuriyama\u{0020}Seiran's\u{0020}life\u{0020}was\u{0020}destroyed\u{0020}in\u{0020}an\u{0020}accident.\u{0020}She\u{0020}lost\u{0020}her\u{0020}arm,\u{0020}lost\u{0020}her\u{0020}eyes,\u{0020}her\u{0020}body\u{0020}was\u{0020}no\u{0020}longer\u{0020}complete,\u{0020}became\u{0020}incomplete\u{0020}and\u{0020}had\u{0020}defects.\n\nPhysical\u{0020}defects\u{0020}have\u{0020}a\u{0020}huge\u{0020}impact\u{0020}on\u{0020}psychologically\u{0020}immature\u{0020}children,\u{0020}and\u{0020}the\u{0020}gaze\u{0020}of\u{0020}peers\u{0020}looking\u{0020}at\u{0020}her\u{0020}as\u{0020}an\u{0020}oddity\u{0020}was\u{0020}unbearable\u{0020}for\u{0020}Kuriyama\u{0020}Seiran.\u{0020}She\u{0020}tried\u{0020}to\u{0020}change\u{0020}the\u{0020}opinions\u{0020}of\u{0020}those\u{0020}around\u{0020}her,\u{0020}but\u{0020}the\u{0020}almost\u{0020}perfunctory\u{0020}cold\u{0020}violence\u{0020}feedback\u{0020}made\u{0020}her\u{0020}desperate,\u{0020}and\u{0020}the\u{0020}comfort\u{0020}from\u{0020}her\u{0020}parents\u{0020}made\u{0020}her\u{0020}more\u{0020}aware\u{0020}that\u{0020}she\u{0020}was\u{0020}an\u{0020}incomplete\u{0020}person.\n\nFrom\u{0020}then\u{0020}on,\u{0020}she\u{0020}closed\u{0020}her\u{0020}heart,\u{0020}confined\u{0020}herself\u{0020}at\u{0020}home,\u{0020}and\u{0020}the\u{0020}only\u{0020}connection\u{0020}with\u{0020}the\u{0020}outside\u{0020}world\u{0020}was\u{0020}a\u{0020}22-inch\u{0020}monitor.\n\nThe\u{0020}second\u{0020}stage\u{0020}of\u{0020}Kuriyama\u{0020}Seiran's\u{0020}life\u{0020}was\u{0020}precisely\u{0020}initiated\u{0020}with\u{0020}the\u{0020}aid\u{0020}of\u{0020}this\u{0020}monitor\u{0020}and\u{0020}the\u{0020}internet.\u{0020}At\u{0020}that\u{0020}time,\u{0020}she\u{0020}was\u{0020}sitting\u{0020}on\u{0020}the\u{0020}sofa,\u{0020}hiding\u{0020}her\u{0020}body\u{0020}under\u{0020}the\u{0020}quilt.\u{0020}The\u{0020}room\u{0020}was\u{0020}very\u{0020}dark,\u{0020}with\u{0020}only\u{0020}the\u{0020}monitor\u{0020}serving\u{0020}as\u{0020}the\u{0020}light\u{0020}source.\u{0020}She\u{0020}looked\u{0020}at\u{0020}the\u{0020}screen\u{0020}with\u{0020}her\u{0020}only\u{0020}remaining\u{0020}eye\u{0020}and\u{0020}clicked\u{0020}on\u{0020}an\u{0020}article\u{0020}titled\u{0020}\"The\u{0020}City\u{0020}Enshrouded\u{0020}by\u{0020}Doomsday\".\n\nShe\u{0020}was\u{0020}shocked\u{0020}by\u{0020}the\u{0020}desperate\u{0020}scene\u{0020}of\u{0020}the\u{0020}city\u{0020}invaded\u{0020}by\u{0020}Sin\u{0020}described\u{0020}in\u{0020}the\u{0020}article\u{0020}and\u{0020}began\u{0020}to\u{0020}realize\u{0020}that\u{0020}although\u{0020}she\u{0020}was\u{0020}unfortunate,\u{0020}there\u{0020}were\u{0020}more\u{0020}people\u{0020}in\u{0020}the\u{0020}world\u{0020}who\u{0020}were\u{0020}even\u{0020}more\u{0020}unfortunate\u{0020}and\u{0020}even\u{0020}lost\u{0020}the\u{0020}right\u{0020}to\u{0020}live.\n\nAlthough\u{0020}she\u{0020}still\u{0020}cared\u{0020}about\u{0020}others'\u{0020}gazes\u{0020}and\u{0020}still\u{0020}hated\u{0020}her\u{0020}incomplete\u{0020}self,\u{0020}after\u{0020}that\u{0020}day,\u{0020}her\u{0020}inner\u{0020}kindness\u{0020}made\u{0020}her\u{0020}unwilling\u{0020}to\u{0020}continue\u{0020}hiding\u{0020}at\u{0020}home.\u{0020}She\u{0020}decided\u{0020}to\u{0020}do\u{0020}something\u{0020}for\u{0020}humanity\u{0020}with\u{0020}this\u{0020}incomplete\u{0020}body\u{0020}-\u{0020}therefore,\u{0020}she\u{0020}participated\u{0020}in\u{0020}the\u{0020}eligibility\u{0020}test\u{0020}established\u{0020}by\u{0020}AEGIS\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}Azure\u{0020}Academy.\n\n\"She\u{0020}was\u{0020}once\u{0020}pushed\u{0020}into\u{0020}the\u{0020}abyss\u{0020}of\u{0020}despair\u{0020}by\u{0020}the\u{0020}unintentional\u{0020}and\u{0020}intentional\u{0020}malice\u{0020}of\u{0020}humanity.\u{0020}When\u{0020}she\u{0020}climbed\u{0020}out\u{0020}of\u{0020}the\u{0020}abyss,\u{0020}what\u{0020}she\u{0020}thought\u{0020}of\u{0020}was\u{0020}not\u{0020}revenge,\u{0020}but\u{0020}to\u{0020}prevent\u{0020}more\u{0020}people\u{0020}from\u{0020}repeating\u{0020}the\u{0020}same\u{0020}mistakes\u{0020}and\u{0020}chose\u{0020}to\u{0020}fight\u{0020}for\u{0020}humanity.\"", "0", "0", "0", "0", 11004, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}栗山青鸾本来应该拥有一段相当平凡的人生。她会在学校里认识许多的同龄朋友，然后，或许会在中学、大学的时候和自己喜欢的人表白，谈一场恋爱，恋爱可能顺利，也可能不顺利，但她应该会获得属于自己的幸福——但是，\n\u{1000}\u{1000}她失去了这样的人生，她的人生被夺走了，又或者说是被毁灭了。\n\u{1000}\u{1000}栗山青鸾的人生在一场事故中毁灭了。她失去了自己的手臂，失去了自己的眼睛，身体不再完整，出现了残缺，有了缺陷。\n\u{1000}\u{1000}身体上的缺陷对心理不成熟的孩子会产生巨大的打击，而周围同龄人看异类的目光更是让栗山青鸾无法忍受。她有尝试过改变周围人的看法，但那种近乎敷衍的冷暴力反馈让她绝望，而来自父母的安慰则让她更加意识到自己是一个不完整的人。\n\u{1000}\u{1000}她从那时起封闭了自己的内心，将自己关在家里，和外界的联系只剩下一台二十二寸的液晶显示器。\n\u{1000}\u{1000}栗山青鸾的人生第二阶段，恰恰就是借助这台显示器、借助网络开启的。当时，她坐在沙发上，将身子裹藏在被子里，房间很黑，只有显示器作为光源。她用仅有的一只眼睛看着屏幕，她点开了一篇名为《末日笼罩的城市》的文章。\n\u{1000}\u{1000}她被文章中描述的，被原罪入侵的城市的绝望场景所震撼，开始意识到尽管自己不幸，但世界上有更多比她更加不幸，甚至失去生的权利的人在。\n\u{1000}\u{1000}虽然她依然在意别人的视线，依然憎恶残缺的自己，但那一天后，内心的善良让她不愿意再继续躲在家里。她决定用这个残缺的身体为人类做点什么——因此，她参加了艾吉斯设立的适格测试，成为了苍穹学院的一员。\n\u{1000}\u{1000}\"她一度被人类无意的、有意的恶意推入绝望的深渊。当她从深渊里爬出来，她想到的不是复仇，而是为了不让更多的人重蹈覆辙，选择为人类而战。\""},
[610403] = {610403, 1000, "\u{0020}\u{0020}The\u{0020}physical\u{0020}defect\u{0020}makes\u{0020}Kuriyama\u{0020}Seiran\u{0020}extremely\u{0020}sensitive\u{0020}to\u{0020}the\u{0020}gazes\u{0020}of\u{0020}others\u{0020}and\u{0020}even\u{0020}able\u{0020}to\u{0020}distinguish\u{0020}what\u{0020}kind\u{0020}of\u{0020}emotions\u{0020}are\u{0020}mixed\u{0020}in\u{0020}the\u{0020}gazes,\u{0020}such\u{0020}as\u{0020}sympathy,\u{0020}fear,\u{0020}and\u{0020}disgust.\u{0020}All\u{0020}of\u{0020}these\u{0020}she\u{0020}can\u{0020}sense.\n\nTherefore,\u{0020}when\u{0020}she\u{0020}entered\u{0020}\"Fuurinkazan\",\u{0020}she\u{0020}was\u{0020}redeemed.\u{0020}No\u{0020}one\u{0020}in\u{0020}the\u{0020}team\u{0020}disliked\u{0020}her\u{0020}body,\u{0020}and\u{0020}no\u{0020}one\u{0020}regarded\u{0020}her\u{0020}as\u{0020}a\u{0020}person\u{0020}with\u{0020}a\u{0020}physical\u{0020}defect.\u{0020}Even\u{0020}Morimura\u{0020}Kinosuke,\u{0020}who\u{0020}seemed\u{0020}the\u{0020}most\u{0020}difficult\u{0020}to\u{0020}communicate\u{0020}with,\u{0020}did\u{0020}not\u{0020}care\u{0020}about\u{0020}the\u{0020}girl's\u{0020}defect.\n\nKuriyama\u{0020}Seiran\u{0020}was\u{0020}moved\u{0020}by\u{0020}Fuurinkazan's\u{0020}attitude.\u{0020}She\u{0020}tried\u{0020}not\u{0020}to\u{0020}let\u{0020}herself\u{0020}be\u{0020}as\u{0020}gloomy\u{0020}as\u{0020}before,\u{0020}and\u{0020}tried\u{0020}to\u{0020}build\u{0020}a\u{0020}good\u{0020}relationship\u{0020}with\u{0020}her\u{0020}peers.\n\nThe\u{0020}caring\u{0020}team\u{0020}leader\u{0020}Suzuki\u{0020}Seifung,\u{0020}the\u{0020}somewhat\u{0020}strange\u{0020}big\u{0020}sister\u{0020}Shiranui,\u{0020}and\u{0020}the\u{0020}cold-on-the-outside-but-warm-on-the-inside\u{0020}Morimura\u{0020}Kinosuke.\n\nKuriyama\u{0020}Seiran\u{0020}wants\u{0020}to\u{0020}be\u{0020}with\u{0020}them\u{0020}all\u{0020}the\u{0020}time.", "0", "0", "0", "0", 11004, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}身体的缺陷让栗山青鸾对旁人的视线格外敏感，甚至能够分辨出视线中混着什么样的情感，同情、恐惧，嫌恶，这些她都能够感受到。\n\u{1000}\u{1000}因此，当她进入到\"风林火山\"后，得到了救赎。队伍里没有人嫌弃她的身体，没有人把她当做有身体缺陷的人看待。就连看起来最不好交流的森村鬼之介也没有在乎少女的缺陷。\n\u{1000}\u{1000}风林火山的态度，让栗山青鸾备受感动。她试着不让自己像以前一样阴沉，试着和同伴打好关系。\n\u{1000}\u{1000}爱照顾人的队长铃木清风，有些奇怪的大姐姐不知火，以及外冷内热的森村鬼之介。\n\u{1000}\u{1000}栗山青鸾想一直和她们在一起。"},
[610404] = {610404, 2000, "\u{0020}Kuriyama\u{0020}Seiran\u{0020}has\u{0020}never\u{0020}expected.\n\nShe\u{0020}didn't\u{0020}expect\u{0020}anything\u{0020}special.\n\nWhat\u{0020}she\u{0020}longs\u{0020}for\u{0020}is\u{0020}just\u{0020}an\u{0020}ordinary\u{0020}and\u{0020}complete\u{0020}life.\n\nMore\u{0020}specifically,\u{0020}what\u{0020}she\u{0020}longs\u{0020}for\u{0020}now\u{0020}is\u{0020}just\u{0020}the\u{0020}small\u{0020}existence\u{0020}that\u{0020}lies\u{0020}in\u{0020}her\u{0020}palm.\n\n\"Navigator,\u{0020}after\u{0020}the\u{0020}war\u{0020}is\u{0020}over,\u{0020}I\u{0020}have\u{0020}something\u{0020}to\u{0020}tell\u{0020}you.\"\n\n\"Before\u{0020}that,\u{0020}please\u{0020}stay\u{0020}alive,\u{0020}whether\u{0020}it's\u{0020}you\u{0020}or\u{0020}me.\"", "0", "0", "0", "0", 11004, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}栗山青鸾从未奢望过，\n\u{1000}\u{1000}她没有奢望过特别的东西，\n\u{1000}\u{1000}她憧憬的，只是普通的，完整的生活。\n\u{1000}\u{1000}更具体来说，现在的她憧憬的，只是立于自己掌中，那小小的存在。\n\u{1000}\u{1000}\"领航——战争结束后，我有话想对您说。\"\n\u{1000}\u{1000}\"在那之前，请活下去，无论是您，还是我。\""},
[610600] = {610600, 0, "[Name]\u{0020}Jenny\u{0020}Rose\n[B-Day]\u{0020}Sep\u{0020}8\n[Compatability\u{0020}Rate]\u{0020}91％\n[Height]\u{0020}35m\n[Squad]\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Seek\u{0020}the\u{0020}truth;\u{0020}reveal\u{0020}secrets", "0", "0", "0", "0", 11006, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}燕妮·罗斯\n[B-Day]\u{1000}9月8日\n[幻化核心适格率]\u{1000}91％\n[Height]\u{1000}35m\n[部队]\u{1000}飓风突击队\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}探寻真相\u{1000}揭露秘密"},
[610601] = {610601, 100, "\u{0020}\u{0020}Having\u{0020}an\u{0020}excessive\u{0020}sense\u{0020}of\u{0020}responsibility\u{0020}and\u{0020}a\u{0020}heart\u{0020}seeking\u{0020}the\u{0020}truth,\u{0020}and\u{0020}also\u{0020}being\u{0020}an\u{0020}optimistic\u{0020}girl.\n\nShe\u{0020}has\u{0020}a\u{0020}strong\u{0020}desire\u{0020}to\u{0020}explore\u{0020}new\u{0020}things\u{0020}and\u{0020}the\u{0020}truth\u{0020}behind\u{0020}them.\u{0020}From\u{0020}this\u{0020}point\u{0020}of\u{0020}view,\u{0020}she\u{0020}is\u{0020}a\u{0020}born\u{0020}journalist.\u{0020}In\u{0020}order\u{0020}to\u{0020}pursue\u{0020}the\u{0020}concealed\u{0020}truth,\u{0020}she\u{0020}is\u{0020}willing\u{0020}to\u{0020}take\u{0020}risks\u{0020}even\u{0020}at\u{0020}the\u{0020}cost\u{0020}of\u{0020}her\u{0020}life.\u{0020}She\u{0020}is\u{0020}such\u{0020}a\u{0020}girl.\n\nWhen\u{0020}she\u{0020}learned\u{0020}that\u{0020}one\u{0020}of\u{0020}her\u{0020}teammates,\u{0020}Julia\u{0020}Fox,\u{0020}had\u{0020}a\u{0020}mysterious\u{0020}family\u{0020}background\u{0020}like\u{0020}a\u{0020}riddle,\u{0020}she\u{0020}began\u{0020}to\u{0020}investigate\u{0020}the\u{0020}background\u{0020}of\u{0020}her\u{0020}teammate.\u{0020}However,\u{0020}she\u{0020}did\u{0020}not\u{0020}seem\u{0020}overly\u{0020}persistent\u{0020}about\u{0020}the\u{0020}secrets\u{0020}of\u{0020}Celine\u{0020}Welt.\u{0020}As\u{0020}for\u{0020}the\u{0020}reason,\u{0020}she\u{0020}explained\u{0020}it\u{0020}like\u{0020}this:\n\nIf\u{0020}a\u{0020}truth\u{0020}is\u{0020}useless\u{0020}except\u{0020}for\u{0020}harming\u{0020}the\u{0020}person\u{0020}involved,\u{0020}then\u{0020}it\u{0020}is\u{0020}not\u{0020}a\u{0020}truth\u{0020}worth\u{0020}exploring.", "0", "0", "0", "0", 11006, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}有着过剩的责任感与一颗探求真相的心，同时也是一名乐天派的少女。\n\u{1000}\u{1000}她对于新鲜事以及其背后的真相有着旺盛的探索欲，从这一点看，她是一名天生的记者。为了追求被掩盖的真相，即使冒着生命危险去探求也在所不惜，她就是这样的少女。\n\u{1000}\u{1000}当她得知队友之一的茱莉亚·福克斯拥有着谜团一般的家世背景时，便开始了对自己队友的背景调查。不过对于栖琳·瓦尔特身上的秘密，她似乎并没有表现出过多的执着，至于原因，她是如此解释的：\n\u{1000}\u{1000}\"如果一个真相除了伤害当事人外便一无用处，那它就不是一个值得探索的真相。\""},
[610602] = {610602, 500, "\u{0020}\u{0020}When\u{0020}Jenny\u{0020}Rose\u{0020}was\u{0020}at\u{0020}the\u{0020}age\u{0020}when\u{0020}she\u{0020}should\u{0020}have\u{0020}been\u{0020}a\u{0020}middle\u{0020}school\u{0020}student,\u{0020}she\u{0020}had\u{0020}already\u{0020}become\u{0020}an\u{0020}investigative\u{0020}journalist\u{0020}active\u{0020}in\u{0020}every\u{0020}corner.\u{0020}The\u{0020}reason\u{0020}she\u{0020}became\u{0020}a\u{0020}journalist\u{0020}was\u{0020}on\u{0020}the\u{0020}one\u{0020}hand\u{0020}her\u{0020}own\u{0020}hobby,\u{0020}and\u{0020}on\u{0020}the\u{0020}other\u{0020}hand,\u{0020}it\u{0020}was\u{0020}influenced\u{0020}by\u{0020}her\u{0020}idle\u{0020}and\u{0020}cheating\u{0020}father,\u{0020}who\u{0020}she\u{0020}definitely\u{0020}do\u{0020}not\u{0020}want\u{0020}to\u{0020}end\u{0020}up\u{0020}like.\n\nJenny\u{0020}Rose's\u{0020}journalism\u{0020}career\u{0020}was\u{0020}not\u{0020}long,\u{0020}but\u{0020}every\u{0020}report\u{0020}written\u{0020}by\u{0020}her\u{0020}left\u{0020}a\u{0020}deep\u{0020}impression.\u{0020}Among\u{0020}them,\u{0020}there\u{0020}were\u{0020}no\u{0020}shortage\u{0020}of\u{0020}expose\u{0020}news\u{0020}that\u{0020}exposed\u{0020}the\u{0020}darkness\u{0020}of\u{0020}politics\u{0020}and\u{0020}business.\u{0020}But\u{0020}the\u{0020}most\u{0020}famous\u{0020}one\u{0020}was\u{0020}still\u{0020}the\u{0020}report\u{0020}named\u{0020}\"The\u{0020}City\u{0020}Shrouded\u{0020}in\u{0020}Doomsday\".\u{0020}That\u{0020}report\u{0020}faithfully\u{0020}recorded\u{0020}the\u{0020}urban\u{0020}scene\u{0020}after\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}heroic\u{0020}deeds\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}driver\u{0020}who\u{0020}fought\u{0020}a\u{0020}desperate\u{0020}battle\u{0020}to\u{0020}resist\u{0020}Sin,\u{0020}giving\u{0020}people\u{0020}all\u{0020}over\u{0020}the\u{0020}world\u{0020}the\u{0020}hope\u{0020}of\u{0020}victory.\u{0020}It\u{0020}was\u{0020}precisely\u{0020}this\u{0020}most\u{0020}widely\u{0020}known\u{0020}report\u{0020}that\u{0020}made\u{0020}Jenny\u{0020}Rose\u{0020}invited\u{0020}to\u{0020}become\u{0020}an\u{0020}intelligence\u{0020}officer\u{0020}affiliated\u{0020}with\u{0020}AEGIS.\n\nJenny\u{0020}Rose\u{0020}is\u{0020}not\u{0020}picky\u{0020}about\u{0020}the\u{0020}selection\u{0020}of\u{0020}news.\u{0020}In\u{0020}her\u{0020}words,\u{0020}\"Whether\u{0020}it's\u{0020}sad\u{0020}news\u{0020}or\u{0020}happy\u{0020}news,\u{0020}as\u{0020}long\u{0020}as\u{0020}it\u{0020}can\u{0020}inspire\u{0020}others,\u{0020}that's\u{0020}fine.\"\u{0020}Therefore,\u{0020}whether\u{0020}it's\u{0020}war\u{0020}news\u{0020}that\u{0020}gives\u{0020}people\u{0020}strength\u{0020}from\u{0020}sadness\u{0020}or\u{0020}gossip\u{0020}news\u{0020}that\u{0020}makes\u{0020}people\u{0020}smile,\u{0020}she\u{0020}will\u{0020}report.\u{0020}She\u{0020}is\u{0020}a\u{0020}journalist\u{0020}with\u{0020}almost\u{0020}no\u{0020}tendency\u{0020}in\u{0020}news\u{0020}selection.", "0", "0", "0", "0", 11006, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}燕妮·罗斯在理应是中学生的年龄时，她就已经成为了一名活跃在各个角落上的调查记者。她成为记者的理由一方面是自己的爱好，另一方面是受到自己游手好闲的骗子父亲的影响——绝对不想成为那样的人。\n\u{1000}\u{1000}燕妮·罗斯的记者生涯并不长，但由她撰写的每篇报道都给人留下深刻的印象，其中不乏揭露政治、商业黑暗的揭发式新闻，但其中最出名的，还是那篇名为《被末日笼罩的城市》的报道，那篇报道忠实记录下了原罪入侵后的城市景象，也记录下了艾吉斯的驾驶员们为了对抗原罪，殊死一战的英勇事迹，让全世界的人民看到了胜利的希望。也正是这篇最广为人知的报道，让燕妮·罗斯受邀成为了一名隶属艾吉斯的情报官。\n\u{1000}\u{1000}燕妮·罗斯对于新闻的选材是毫不挑剔的，用她的话来说\"无论是悲伤的新闻，还是让人开心的新闻，只要能够激励别人就行了。\"因此，无论是让人从悲伤中得到力量的战争新闻，亦或是让人莞尔一笑的花边新闻，她都会报道，是一个几乎没有选材倾向的记者。"},
[610603] = {610603, 1000, "\u{0020}\u{0020}Later,\u{0020}for\u{0020}some\u{0020}reasons,\u{0020}Jenny\u{0020}Rose\u{0020}left\u{0020}the\u{0020}position\u{0020}of\u{0020}intelligence\u{0020}officer\u{0020}but\u{0020}did\u{0020}not\u{0020}quit\u{0020}AEGIS.\u{0020}Instead,\u{0020}she\u{0020}applied\u{0020}to\u{0020}become\u{0020}a\u{0020}\"driver\".\u{0020}After\u{0020}passing\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test,\u{0020}she\u{0020}became\u{0020}a\u{0020}reserve\u{0020}driver.\u{0020}At\u{0020}her\u{0020}strong\u{0020}request,\u{0020}AEGIS\u{0020}assigned\u{0020}her\u{0020}to\u{0020}the\u{0020}\"Hurricane\u{0020}Shock\u{0020}Squad\"\u{0020}of\u{0020}Danube.\n\nIn\u{0020}the\u{0020}past,\u{0020}when\u{0020}Jenny\u{0020}Rose\u{0020}was\u{0020}assisting\u{0020}in\u{0020}the\u{0020}Danube\u{0020}theater\u{0020}of\u{0020}war,\u{0020}she\u{0020}came\u{0020}into\u{0020}contact\u{0020}with\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\u{0020}and\u{0020}got\u{0020}acquainted\u{0020}with\u{0020}Celine\u{0020}Welt.\u{0020}This\u{0020}was\u{0020}also\u{0020}the\u{0020}opportunity\u{0020}for\u{0020}her\u{0020}to\u{0020}resign\u{0020}as\u{0020}an\u{0020}intelligence\u{0020}officer.\u{0020}During\u{0020}her\u{0020}time\u{0020}with\u{0020}Celine\u{0020}Welt,\u{0020}Jenny\u{0020}Rose\u{0020}discovered\u{0020}the\u{0020}interesting\u{0020}aspects\u{0020}of\u{0020}the\u{0020}relationships\u{0020}among\u{0020}the\u{0020}members\u{0020}of\u{0020}this\u{0020}squad.\u{0020}On\u{0020}the\u{0020}other\u{0020}hand,\u{0020}she,\u{0020}who\u{0020}had\u{0020}always\u{0020}been\u{0020}observing\u{0020}battles\u{0020}as\u{0020}a\u{0020}journalist\u{0020}and\u{0020}intelligence\u{0020}officer,\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}in\u{0020}her\u{0020}life\u{0020}had\u{0020}the\u{0020}thought\u{0020}of\u{0020}\"not\u{0020}being\u{0020}a\u{0020}bystander\u{0020}of\u{0020}battles\u{0020}all\u{0020}the\u{0020}time\"\u{0020}when\u{0020}fighting\u{0020}side\u{0020}by\u{0020}side\u{0020}with\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad.\u{0020}Therefore,\u{0020}Jenny\u{0020}Rose\u{0020}finally\u{0020}became\u{0020}a\u{0020}driver.\n\nAfter\u{0020}joining\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad,\u{0020}Jenny\u{0020}Rose\u{0020}was\u{0020}mainly\u{0020}responsible\u{0020}for\u{0020}intelligence\u{0020}collection,\u{0020}intelligence\u{0020}analysis,\u{0020}long-range\u{0020}sniping\u{0020}and\u{0020}other\u{0020}tasks\u{0020}of\u{0020}the\u{0020}squad,\u{0020}making\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\u{0020}more\u{0020}actively\u{0020}present\u{0020}on\u{0020}the\u{0020}frontline\u{0020}battlefield.", "0", "0", "0", "0", 11006, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}之后又因为某些原因，燕妮离开情报官的岗位，但却并未退出艾吉斯，而是提出了成为\"驾驶员\"的申请。在适格率测试合格后，她成为了一名预备驾驶员，并在她个人的强烈请求下，艾吉斯将她分配至多瑙的\"飓风突击队\"中。\n\u{1000}\u{1000}过去，燕妮·罗斯在一次援助多瑙战区时，燕妮·罗斯与飓风突击队接触，结识了栖琳·瓦尔特。而这也是她辞去情报官的契机。与栖琳·瓦尔特相处期间，燕妮·罗斯发觉了这只小队成员关系的有趣之处。\n\u{1000}\u{1000}另一方面，一直以来作为记者、情报官旁观战斗的她，在与飓风突击队并肩作战的时候，有生以来第一次生出了\"不能一直当战斗的旁观者\"的想法。所以，燕妮·罗斯最后成为了一名驾驶员。\n\u{1000}\u{1000}加入飓风突击队之后，燕妮·罗斯主要负责小队的情报搜集、情报分析、超远距离狙击等工作，让飓风突击队更加活跃地出现在一线战场上。"},
[610604] = {610604, 2000, "\u{0020}\"When\u{0020}in\u{0020}battle,\u{0020}I\u{0020}can't\u{0020}hold\u{0020}the\u{0020}camera.\"\n\nIn\u{0020}the\u{0020}chaotic\u{0020}city,\u{0020}she\u{0020}who\u{0020}is\u{0020}driving\u{0020}a\u{0020}wolf-like\u{0020}mecha\u{0020}is\u{0020}confronting\u{0020}the\u{0020}Sin.\n\nThe\u{0020}forest\u{0020}of\u{0020}tall\u{0020}buildings\u{0020}became\u{0020}her\u{0020}best\u{0020}green\u{0020}backdrop.\n\nThe\u{0020}insignificant\u{0020}navigator\u{0020}compared\u{0020}to\u{0020}her\u{0020}size\u{0020}accompanies\u{0020}her.\n\nHer\u{0020}smile\u{0020}makes\u{0020}people\u{0020}not\u{0020}feel\u{0020}the\u{0020}existence\u{0020}of\u{0020}a\u{0020}sense\u{0020}of\u{0020}crisis.\n\n\"So,\u{0020}Navigator,\u{0020}please,\u{0020}with\u{0020}your\u{0020}eyes,\u{0020}record\u{0020}my\u{0020}active\u{0020}performance!\"", "0", "0", "0", "0", 11006, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"战斗的时候，俺可没办法拿着相机。\"\n\u{1000}\u{1000}混乱的城市中，驾驶着如狼一般机甲的她正在与原罪对峙着。\n\u{1000}\u{1000}林立的大楼成了她最好的绿布。\n\u{1000}\u{1000}相比她的体型显得微不足道的领航陪伴在她的身边。\n\u{1000}\u{1000}她的笑容让人感受不到危机感的存在。\n\u{1000}\u{1000}\"所以，领航，拜托你了，用你的眼睛，去记录俺的活跃表现吧！\""},
[610700] = {610700, 0, "[Name]\u{0020}Lydia\u{0020}Lee\u{0020}Ustinovich\n[B-Day]\u{0020}Dec\u{0020}21\n[Compatability\u{0020}Rate]\u{0020}89％\n[Height]\u{0020}38m\n[Squad]\u{0020}Snow\u{0020}Owl\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Katya", "0", "0", "0", "0", 11007, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}莉迪娅·李·乌斯季诺维奇\n[B-Day]\u{1000}12月21日\n[幻化核心适格率]\u{1000}89％\n[Height]\u{1000}38m\n[部队]\u{1000}雪鸮\n[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}卡佳"},
[610701] = {610701, 100, "\u{0020}The\u{0020}captain\u{0020}of\u{0020}\"Snow\u{0020}Owl\",\u{0020}like\u{0020}other\u{0020}members\u{0020}of\u{0020}the\u{0020}troop,\u{0020}is\u{0020}good\u{0020}at\u{0020}fighting\u{0020}in\u{0020}the\u{0020}snow.\u{0020}On\u{0020}the\u{0020}battlefield,\u{0020}she\u{0020}can\u{0020}not\u{0020}only\u{0020}provide\u{0020}powerful\u{0020}and\u{0020}stable\u{0020}firepower,\u{0020}but\u{0020}also\u{0020}calmly\u{0020}analyze\u{0020}and\u{0020}sort\u{0020}out\u{0020}all\u{0020}the\u{0020}intelligence\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}like\u{0020}a\u{0020}professional\u{0020}intelligence\u{0020}officer.\n\nIn\u{0020}daily\u{0020}life,\u{0020}she\u{0020}is\u{0020}like\u{0020}everyone's\u{0020}elder\u{0020}sister,\u{0020}always\u{0020}treating\u{0020}everyone\u{0020}gently\u{0020}and\u{0020}bringing\u{0020}gifts\u{0020}to\u{0020}those\u{0020}who\u{0020}meet\u{0020}her\u{0020}for\u{0020}the\u{0020}first\u{0020}time.\u{0020}Hardly\u{0020}anyone\u{0020}has\u{0020}seen\u{0020}her\u{0020}angry.\n\nFor\u{0020}the\u{0020}weak,\u{0020}she\u{0020}always\u{0020}shows\u{0020}a\u{0020}tolerant\u{0020}side,\u{0020}does\u{0020}not\u{0020}demand\u{0020}of\u{0020}them\u{0020}too\u{0020}strictly,\u{0020}and\u{0020}teaches\u{0020}them\u{0020}how\u{0020}to\u{0020}become\u{0020}stronger.", "0", "0", "0", "0", 11007, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"雪鸮\"的队长，和该部队的其他成员一样，擅长在雪地中作战。在战场上，她不仅能够提供强大、稳定的火力，甚至还能像专业的情报官那样，冷静地分析整理出战场上的所有情报。\n\u{1000}\u{1000}在日常中像是大家的姐姐一般，总是温柔地对待每一个人，会给第一次见面的人带礼物。几乎没有人见过她生气时候的模样。\n\u{1000}\u{1000}对于弱者，她总是表现出宽容的一面，不会过于严格地要求对方，并且悉心教导对方如何变强。因此，传出了\"莉迪娅喜欢年龄比自己小的孩子\"——这种流言蜚语。"},
[610702] = {610702, 500, "\u{0020}When\u{0020}Lydia\u{0020}Lee\u{0020}Ustinovich\u{0020}first\u{0020}became\u{0020}active\u{0020}on\u{0020}the\u{0020}stage\u{0020}of\u{0020}the\u{0020}war\u{0020}against\u{0020}Sin,\u{0020}she\u{0020}was\u{0020}still\u{0020}a\u{0020}child.\n\nThe\u{0020}war\u{0020}between\u{0020}humanity\u{0020}and\u{0020}Sin\u{0020}was\u{0020}everywhere\u{0020}on\u{0020}the\u{0020}land\u{0020}at\u{0020}that\u{0020}time,\u{0020}and\u{0020}the\u{0020}city\u{0020}where\u{0020}Lydia\u{0020}lived\u{0020}was\u{0020}also\u{0020}affected\u{0020}by\u{0020}the\u{0020}war.\u{0020}During\u{0020}the\u{0020}government-organized\u{0020}evacuation,\u{0020}Lydia\u{0020}accidentally\u{0020}saved\u{0020}the\u{0020}general\u{0020}in\u{0020}charge\u{0020}of\u{0020}that\u{0020}military\u{0020}operation.\u{0020}After\u{0020}the\u{0020}incident,\u{0020}Lydia\u{0020}was\u{0020}awarded\u{0020}the\u{0020}honorary\u{0020}medal\u{0020}symbolizing\u{0020}courage\u{0020}by\u{0020}the\u{0020}general\u{0020}in\u{0020}her\u{0020}personal\u{0020}capacity.\n\nAt\u{0020}that\u{0020}time,\u{0020}everyone\u{0020}was\u{0020}just\u{0020}marveling\u{0020}at\u{0020}the\u{0020}girl's\u{0020}courage,\u{0020}and\u{0020}not\u{0020}many\u{0020}people\u{0020}thought\u{0020}that\u{0020}Lydia\u{0020}would\u{0020}stand\u{0020}out\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}later.\n\nBut\u{0020}taking\u{0020}this\u{0020}as\u{0020}an\u{0020}opportunity,\u{0020}Lydia\u{0020}developed\u{0020}the\u{0020}idea\u{0020}of\u{0020}joining\u{0020}the\u{0020}army.\u{0020}With\u{0020}support\u{0020}from\u{0020}her\u{0020}parents\u{0020}in\u{0020}all\u{0020}aspects\u{0020}-\u{0020}not\u{0020}only\u{0020}tuition\u{0020}fees\u{0020}-\u{0020}Lydia\u{0020}entered\u{0020}the\u{0020}Army\u{0020}Officer\u{0020}Academy\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}After\u{0020}graduating\u{0020}with\u{0020}excellent\u{0020}grades,\u{0020}Lydia\u{0020}became\u{0020}the\u{0020}adjutant\u{0020}of\u{0020}Maria\u{0020}Y\u{0020}Stepanek,\u{0020}who\u{0020}was\u{0020}then\u{0020}serving\u{0020}as\u{0020}an\u{0020}officer.\n\nA\u{0020}war\u{0020}recorded\u{0020}as\u{0020}\"tragic\"\u{0020}changed\u{0020}Lydia's\u{0020}fate.\u{0020}Sin\u{0020}attacked\u{0020}the\u{0020}city\u{0020}where\u{0020}the\u{0020}troops\u{0020}were\u{0020}stationed,\u{0020}and\u{0020}the\u{0020}flames\u{0020}of\u{0020}war\u{0020}were\u{0020}ignited\u{0020}in\u{0020}an\u{0020}instant.\u{0020}However,\u{0020}at\u{0020}the\u{0020}beginning\u{0020}of\u{0020}the\u{0020}war,\u{0020}the\u{0020}supreme\u{0020}commander\u{0020}of\u{0020}the\u{0020}army\u{0020}died\u{0020}at\u{0020}the\u{0020}hands\u{0020}of\u{0020}Sin.\u{0020}To\u{0020}prevent\u{0020}the\u{0020}army\u{0020}from\u{0020}collapsing,\u{0020}Lydia,\u{0020}with\u{0020}the\u{0020}determination\u{0020}to\u{0020}die,\u{0020}replaced\u{0020}the\u{0020}commander\u{0020}and\u{0020}took\u{0020}over\u{0020}the\u{0020}command.\u{0020}Under\u{0020}Lydia's\u{0020}command,\u{0020}a\u{0020}complete\u{0020}artillery\u{0020}system\u{0020}was\u{0020}constructed\u{0020}within\u{0020}the\u{0020}city.\u{0020}Using\u{0020}the\u{0020}terrain,\u{0020}an\u{0020}artillery\u{0020}barrier\u{0020}was\u{0020}created,\u{0020}achieving\u{0020}coordinated\u{0020}operations\u{0020}between\u{0020}the\u{0020}artillery\u{0020}troops\u{0020}and\u{0020}the\u{0020}infantry\u{0020}troops.\u{0020}Although\u{0020}the\u{0020}war\u{0020}ended\u{0020}in\u{0020}failure\u{0020}in\u{0020}the\u{0020}end,\u{0020}it\u{0020}was\u{0020}because\u{0020}of\u{0020}her\u{0020}command\u{0020}that\u{0020}the\u{0020}army\u{0020}was\u{0020}able\u{0020}to\u{0020}slow\u{0020}down\u{0020}the\u{0020}pace\u{0020}of\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin\u{0020}and\u{0020}minimize\u{0020}casualties.\n\nLydia\u{0020}was\u{0020}seriously\u{0020}injured\u{0020}because\u{0020}of\u{0020}this\u{0020}war.\u{0020}Finally,\u{0020}under\u{0020}the\u{0020}protection\u{0020}of\u{0020}Maria,\u{0020}she\u{0020}safely\u{0020}returned\u{0020}to\u{0020}the\u{0020}rear\u{0020}and\u{0020}fortunately\u{0020}was\u{0020}not\u{0020}sanctioned\u{0020}by\u{0020}the\u{0020}military\u{0020}court.\u{0020}However,\u{0020}she\u{0020}still\u{0020}recuperated\u{0020}for\u{0020}a\u{0020}long\u{0020}time\u{0020}due\u{0020}to\u{0020}her\u{0020}injuries.\n\nAfter\u{0020}recovering\u{0020}from\u{0020}her\u{0020}injuries,\u{0020}she\u{0020}applied\u{0020}and\u{0020}entered\u{0020}the\u{0020}AEGIS\u{0020}Katya\u{0020}Branch.", "0", "0", "0", "0", 11007, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}莉迪娅·李·乌斯季诺维奇首次活跃在对原罪战争的舞台上时还是一个孩子。\n\u{1000}\u{1000}人类与原罪的战火在当时的大地上随处可见，莉迪娅居住的城市也难逃战火的波及。在政府组织的撤离中，莉迪娅偶然地救下了负责那次军事行动的将军。在事情结束后，莉迪娅被将军以个人名义授予了象征勇气的荣誉勋章。\n\u{1000}\u{1000}那个时候，大家只是在惊叹这名女孩的勇气，并没有多少人认为莉迪娅会在之后的战场上崭露头角。\n\u{1000}\u{1000}但以此为契机，莉迪娅萌生出想要从军的想法。在来自父母各方面——不仅是学费——的支持下，莉迪娅进入了卡佳地区的陆军军官学院。在以优异的成绩顺利毕业后，莉迪娅成为当时正在任职军官的玛利亚·亚·斯捷潘内克的副官。\n\u{1000}\u{1000}一场被记载为\"惨烈\"的战争改变了莉迪娅的命运。原罪袭击了部队驻扎的城市，战火在一瞬间被点燃。然而，在战争开始之初，军队的最高指挥官就死于原罪的脚下，为了不让军队溃败，莉迪娅带着赴死的觉悟顶替了指挥官，接过指挥权。在莉迪娅的指挥下，城市内构建出一套完整的炮火系统，利用地形制造出一道炮火屏障，做到了炮火部队与步兵部队的协调作战。尽管战争最后以失败告终，但正是因为有她的指挥，军队才得以拖慢原罪入侵的步伐，最大限度地减少了伤亡。\n\u{1000}\u{1000}莉迪娅因为这场战争而身负重伤，尽管最后在玛利亚的保护下平安地返回后方，并且侥幸地没有受到军事法庭的制裁，但她还是因为伤势休养了漫长的时间。\n\u{1000}\u{1000}伤势恢复后，她应征进入了艾吉斯Katya\u{1000}Branch。"},
[610703] = {610703, 1000, "\u{0020}\u{0020}The\u{0020}interior\u{0020}of\u{0020}Katya\u{0020}Branch\u{0020}was\u{0020}a\u{0020}mess,\u{0020}and\u{0020}Lydia\u{0020}learned\u{0020}about\u{0020}it\u{0020}later.\n\nThe\u{0020}troops\u{0020}led\u{0020}by\u{0020}\"Cannonbore\"\u{0020}funded\u{0020}by\u{0020}\"Siren\",\u{0020}and\u{0020}the\u{0020}troops\u{0020}represented\u{0020}by\u{0020}\"Snow\u{0020}Owl\"\u{0020}symbolizing\u{0020}the\u{0020}official\u{0020}\"AEGIS\",\u{0020}the\u{0020}contradiction\u{0020}between\u{0020}Katya\u{0020}Branch\u{0020}and\u{0020}the\u{0020}Siren\u{0020}company\u{0020}was\u{0020}projected\u{0020}onto\u{0020}them.\n\nAlthough\u{0020}Lydia\u{0020}didn't\u{0020}care\u{0020}much\u{0020}about\u{0020}the\u{0020}name\u{0020}\"AEGIS\",\u{0020}the\u{0020}malice\u{0020}from\u{0020}Siren\u{0020}made\u{0020}her\u{0020}feel\u{0020}uncomfortable\u{0020}to\u{0020}some\u{0020}extent.\u{0020}She\u{0020}tried\u{0020}her\u{0020}best\u{0020}to\u{0020}keep\u{0020}\"Snow\u{0020}Owl\"\u{0020}away\u{0020}from\u{0020}the\u{0020}conflict\u{0020}between\u{0020}AEGIS\u{0020}and\u{0020}Siren.\u{0020}In\u{0020}her\u{0020}heart,\u{0020}Katya\u{0020}was\u{0020}more\u{0020}important\u{0020}than\u{0020}AEGIS\u{0020}and\u{0020}Siren.\u{0020}If\u{0020}the\u{0020}relationship\u{0020}between\u{0020}\"Snow\u{0020}Owl\"\u{0020}and\u{0020}other\u{0020}teams\u{0020}was\u{0020}not\u{0020}reconciled,\u{0020}the\u{0020}combat\u{0020}power\u{0020}guarding\u{0020}Katya\u{0020}would\u{0020}be\u{0020}weakened.\n\n\"Katya\u{0020}is\u{0020}a\u{0020}cold\u{0020}place.\u{0020}Not\u{0020}only\u{0020}the\u{0020}weather,\u{0020}but\u{0020}even\u{0020}the\u{0020}people\u{0020}are\u{0020}like\u{0020}this\u{0020}-\u{0020}but\u{0020}it\u{0020}doesn't\u{0020}mean\u{0020}it\u{0020}will\u{0020}always\u{0020}be\u{0020}like\u{0020}this.\"", "0", "0", "0", "0", 11007, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}卡佳地区的情况是一个烂摊子，莉迪亚是之后才知道这件事的。\n\u{1000}\u{1000}以\"钢轮戈尔\"为首的由\"塞伦\"出资的部队，和以\"雪鸮\"为代表的象征\"艾吉斯\"官方的部队，Katya\u{1000}Branch与塞伦公司的矛盾被投影到了她们身上。\n\u{1000}\u{1000}尽管莉迪亚对于\"艾吉斯\"这个名号并没有多么在意，但来自塞伦的恶意多少让她感到不舒服。她尽可能地让\"雪鸮\"远离艾吉斯与塞伦的矛盾中，在她心中，比起艾吉斯、塞伦，还是卡佳更为重要。如果不调解\"雪鸮\"与其他队伍的关系，守卫卡佳的战力就会被削弱。\n\u{1000}\u{1000}\"卡佳是一个冰冷的地方，不仅仅是天气，连人也是如此——但是，并不意味着她一直会是这样。\""},
[610704] = {610704, 2000, "\u{0020}\u{0020}The\u{0020}silver-haired\u{0020}girl\u{0020}almost\u{0020}merged\u{0020}with\u{0020}this\u{0020}frozen\u{0020}land,\u{0020}becoming\u{0020}part\u{0020}of\u{0020}the\u{0020}scenery.\n\nShe\u{0020}walked\u{0020}on\u{0020}this\u{0020}earth,\u{0020}overlooking\u{0020}every\u{0020}scar\u{0020}on\u{0020}the\u{0020}earth,\\u{0020}nthose\u{0020}without\u{0020}exception\u{0020}are\u{0020}the\u{0020}traces\u{0020}left\u{0020}by\u{0020}the\u{0020}war.\n\n\"Katya\u{0020}is\u{0020}very\u{0020}cold...\u{0020}This\u{0020}doesn't\u{0020}mean\u{0020}she\u{0020}isn't\u{0020}beautiful.\u{0020}Navigator,\u{0020}I\u{0020}like\u{0020}Katya\u{0020}the\u{0020}most\u{0020}--\"\n\nAfter\u{0020}the\u{0020}war\u{0020}is\u{0020}over,\u{0020}I\u{0020}must\u{0020}take\u{0020}you\u{0020}to\u{0020}visit\u{0020}Katya,\u{0020}Navigator.\u{0020}At\u{0020}that\u{0020}time,\u{0020}Navigator,\u{0020}you\u{0020}will\u{0020}surely\u{0020}say,\u{0020}\"Your\u{0020}hometown\u{0020}is\u{0020}so\u{0020}beautiful...\"\n\n\"So\u{0020}-\u{0020}in\u{0020}order\u{0020}to\u{0020}end\u{0020}the\u{0020}war,\u{0020}we\u{0020}must\u{0020}counterattack\u{0020}the\u{0020}Sin.\u{0020}Only\u{0020}by\u{0020}bringing\u{0020}the\u{0020}flames\u{0020}of\u{0020}war\u{0020}to\u{0020}their\u{0020}base\u{0020}camp\u{0020}and\u{0020}occupying\u{0020}their\u{0020}'city'\u{0020}can\u{0020}we\u{0020}win\u{0020}the\u{0020}victory\u{0020}of\u{0020}the\u{0020}war.\"", "0", "0", "0", "0", 11007, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}银色的少女几乎与这片冰封之地融为一体，成为了景色的一部分。\n\u{1000}\u{1000}她行走在这片大地上，俯瞰着大地的每一处伤痕，\n\u{1000}\u{1000}那些无一例外，是战争留下的痕迹。\n\u{1000}\u{1000}\"卡佳很冷……这不代表她不美丽。领航，我最喜欢卡佳了——\"\n\u{1000}\u{1000}\"战争结束之后，我一定要带领航你去逛一逛卡佳。那时候，领航你一定会说‘姐姐的故乡真美丽啊’…………\"\n\u{1000}\u{1000}\"所以——为了让战争结束，我们要反攻原罪。只有将战火燃到它们的本营，占据它们的‘城市’，我们才能赢得战争的胜利。\""},
[610800] = {610800, 0, "[Name]\u{0020}Ashlica\u{0020}Bhatt\n[B-Day]\u{0020}Jan\u{0020}7\n[Compatability\u{0020}Rate]\u{0020}89％\n[Height]\u{0020}39m\n[Squad]\u{0020}Imperial\u{0020}Strings\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Playing\u{0020}bass,\u{0020}Singing", "0", "0", "0", "0", 11008, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}艾希丽卡•布哈特\n[B-Day]\u{1000}6月6日\n[幻化核心适格率]\u{1000}89％\n[Height]\u{1000}39m\n[部队]\u{1000}绞皇\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}贝斯\u{1000}唱歌"},
[610801] = {610801, 100, "\u{0020}\u{0020}Captain\u{0020}of\u{0020}\"Imperial\u{0020}Strings\",\u{0020}Ashlica\u{0020}is\u{0020}also\u{0020}the\u{0020}main\u{0020}vocalist\u{0020}of\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\".\u{0020}She\u{0020}is\u{0020}a\u{0020}self-disciplined\u{0020}woman\u{0020}with\u{0020}confidence\u{0020}and\u{0020}expressiveness.\n\nMembers\u{0020}of\u{0020}\"Imperial\u{0020}Strings\"\u{0020}are\u{0020}also\u{0020}members\u{0020}of\u{0020}her\u{0020}band\u{0020}since\u{0020}she\u{0020}started\u{0020}the\u{0020}latter\u{0020}up,\u{0020}as\u{0020}a\u{0020}result,\u{0020}she\u{0020}is\u{0020}quite\u{0020}prestigious\u{0020}in\u{0020}her\u{0020}team.\u{0020}She\u{0020}treats\u{0020}her\u{0020}squadmates\u{0020}strictly\u{0020}with\u{0020}responsibility.\u{0020}She\u{0020}will\u{0020}censure\u{0020}severely\u{0020}when\u{0020}her\u{0020}juniors\u{0020}make\u{0020}any\u{0020}mistake,\u{0020}and\u{0020}interestingly,\u{0020}she\u{0020}often\u{0020}worries\u{0020}that\u{0020}her\u{0020}wording\u{0020}may\u{0020}be\u{0020}too\u{0020}harsh\u{0020}for\u{0020}others\u{0020}afterwards.\n\nHer\u{0020}main\u{0020}interests\u{0020}are\u{0020}playing\u{0020}bass\u{0020}and\u{0020}singing\u{0020}with\u{0020}passion,\u{0020}and\u{0020}that's\u{0020}not\u{0020}only\u{0020}in\u{0020}her\u{0020}daily\u{0020}life,\u{0020}she\u{0020}will\u{0020}even\u{0020}play\u{0020}music\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}if\u{0020}her\u{0020}mood\u{0020}is\u{0020}good.\n\n\"Sometimes\u{0020}she\u{0020}may\u{0020}cause\u{0020}confusion,\u{0020}but,\u{0020}when\u{0020}we\u{0020}listen\u{0020}to\u{0020}her\u{0020}music,\u{0020}for\u{0020}some\u{0020}reason,\u{0020}we\u{0020}will\u{0020}feel\u{0020}exhilarated!\"", "0", "0", "0", "0", 11008, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"绞皇\"的队长，同时是乐队\"爱露达死亡深渊\"的主唱，是一名极其自律，且表现欲、信心极强的女性。\n\u{1000}\u{1000}\"绞皇\"的成员是从乐队时期就一直跟随着她的乐队成员，因此在队伍中，她有着极高的的威望。对待队员，她的态度严肃负责，对于后辈做错的事情会用狠辣的措词给予批评，有趣的是，她在事后往往会担心自己的批评是不是太过分而感到不安。\n\u{1000}\u{1000}她最大的爱好便是弹奏贝斯、激情歌唱，不仅在生活中如此，就连在战场上执行任务时，她也会在情绪高昂的时候高声演奏。\n\u{1000}\u{1000}\"虽然有时候会感到困扰——不过，听到她的歌声时，不知怎么的，干劲就涌出来了！\""},
[610802] = {610802, 500, "\u{0020}\u{0020}Her\u{0020}father,\u{0020}a\u{0020}bass\u{0020}player,\u{0020}and\u{0020}her\u{0020}mother,\u{0020}a\u{0020}music\u{0020}instructor,\u{0020}are\u{0020}people\u{0020}who\u{0020}influence\u{0020}her\u{0020}the\u{0020}most.\n\nBecause\u{0020}of\u{0020}them,\u{0020}Ashlica\u{0020}expressed\u{0020}her\u{0020}interest\u{0020}towards\u{0020}music\u{0020}from\u{0020}a\u{0020}young\u{0020}age.\u{0020}When\u{0020}her\u{0020}peers\u{0020}were\u{0020}still\u{0020}planning\u{0020}their\u{0020}future,\u{0020}Ashlica\u{0020}was\u{0020}trying\u{0020}to\u{0020}compose\u{0020}and\u{0020}play\u{0020}her\u{0020}own\u{0020}music.\n\nBecause\u{0020}of\u{0020}Sins,\u{0020}Ashlica\u{0020}lost\u{0020}her\u{0020}home,\u{0020}her\u{0020}family\u{0020}went\u{0020}on\u{0020}refuge\u{0020}and\u{0020}was\u{0020}seeking\u{0020}a\u{0020}new\u{0020}settlement.\n\nDuring\u{0020}their\u{0020}way,\u{0020}violence,\u{0020}death\u{0020}and\u{0020}separation\u{0020}were\u{0020}very\u{0020}common,\u{0020}desperation\u{0020}and\u{0020}confusion\u{0020}pervaded\u{0020}everyone's\u{0020}mind.\u{0020}Ashlica\u{0020}didn't\u{0020}submit\u{0020}to\u{0020}the\u{0020}tragedies\u{0020}in\u{0020}her\u{0020}life\u{0020}and\u{0020}horror\u{0020}of\u{0020}the\u{0020}Sins,\u{0020}she\u{0020}fighted\u{0020}back\u{0020}in\u{0020}her\u{0020}own\u{0020}way.\n\nIt\u{0020}was\u{0020}a\u{0020}rainy\u{0020}night,\u{0020}terrible\u{0020}odors\u{0020}ran\u{0020}into\u{0020}refugees'\u{0020}noses\u{0020}like\u{0020}hungry\u{0020}raptors.\u{0020}Ashlica,\u{0020}carrying\u{0020}her\u{0020}old\u{0020}bass,\u{0020}ran\u{0020}to\u{0020}the\u{0020}foremost\u{0020}of\u{0020}the\u{0020}crowd.\n\nRain\u{0020}wet\u{0020}her\u{0020}body\u{0020}and\u{0020}cold\u{0020}made\u{0020}her\u{0020}body\u{0020}stiff,\u{0020}while\u{0020}tragedies\u{0020}from\u{0020}the\u{0020}past\u{0020}nearly\u{0020}broke\u{0020}her\u{0020}down.\u{0020}Even\u{0020}in\u{0020}this\u{0020}case,\u{0020}she\u{0020}sang\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}crowd\u{0020}with\u{0020}all\u{0020}her\u{0020}vigor,\u{0020}under\u{0020}the\u{0020}thunderstorm.\u{0020}It\u{0020}blew\u{0020}away\u{0020}the\u{0020}desperate\u{0020}atmosphere\u{0020}among\u{0020}the\u{0020}refugees,\u{0020}and\u{0020}on\u{0020}this\u{0020}day,\u{0020}she\u{0020}started\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\".\n\nAttracted\u{0020}by\u{0020}Ashlica's\u{0020}personalities,\u{0020}Wadana\u{0020}and\u{0020}Salati\u{0020}joined\u{0020}her\u{0020}band.\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}did\u{0020}the\u{0020}\"Tour\u{0020}for\u{0020}refugees\",\u{0020}encouraging\u{0020}people\u{0020}with\u{0020}music\u{0020}to\u{0020}never\u{0020}lose\u{0020}their\u{0020}hope\u{0020}of\u{0020}life.", "0", "0", "0", "0", 11008, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}影响艾希丽卡最大的人是前乐队贝斯手的父亲与身为音乐教师的母亲。\n\u{1000}\u{1000}在父母的陶冶下，艾希丽卡在很小的时候就表现出对音乐的极大乐趣。在年龄相仿的孩子都沉迷在游戏与影视作品中时，艾希丽卡就已经开始试着自己写歌，自己演唱，自己弹奏。如果没有原罪的存在，艾希丽卡不出意外会成为一名优秀的贝斯手，同时担任乐队的主唱。\n\u{1000}\u{1000}因为原罪的缘故，艾希丽卡失去了自己的住所，但幸运的是至少她没有像灾难中大多数不幸的人一样失去自己的家人。艾希丽卡一家为了寻找新的定居处，开始了漫长的流亡之旅。\n\u{1000}\u{1000}在流亡途中，暴力、死亡、诀别随处可见，绝望与迷惘笼罩在每个人的心上。艾希丽卡没有被生活的苦难，原罪带来的恐惧所击溃，她选择了用自己的方式来反抗。\n\u{1000}\u{1000}那是一个雨夜，路上发霉的气味像饥饿的野兽扑进每个逃亡者的鼻子里。艾希丽卡拖着从逃亡开始就带着的旧贝斯跑到了逃亡队伍的最前面。\n\u{1000}\u{1000}雨水打湿了她的身子，寒意让她的动作僵硬，过去的苦难让她的意志几近崩溃，尽管如此，她依然在众人的视线下倾其所有地演唱着。在暴风雨下的激奏，将弥漫在流亡者之间的死气吹飞，也是这一天，\"爱露达死亡深渊\"成立了。\n\u{1000}\u{1000}被艾希丽卡的人格魅力吸引，瓦答娜和萨拉蒂加入了艾希丽卡的乐团，\"爱露达死亡深渊\"进行着\"流亡巡演\"，用音乐的方式鼓舞灾难下的人们不要放弃生的欲望。"},
[610803] = {610803, 1000, "\u{0020}\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}joining\u{0020}Aegis\u{0020}seems\u{0020}inevitable.\n\nAshlica,\u{0020}in\u{0020}her\u{0020}own\u{0020}way,\u{0020}exhilarates\u{0020}people\u{0020}who\u{0020}are\u{0020}suffering\u{0020}because\u{0020}of\u{0020}Sins.\u{0020}But\u{0020}she\u{0020}knows\u{0020}the\u{0020}only\u{0020}way\u{0020}to\u{0020}return\u{0020}their\u{0020}peaceful\u{0020}life\u{0020}is\u{0020}to\u{0020}win\u{0020}against\u{0020}the\u{0020}Sins.\u{0020}As\u{0020}a\u{0020}result,\u{0020}when\u{0020}Aegis\u{0020}started\u{0020}their\u{0020}AVG\u{0020}operation,\u{0020}she\u{0020}became\u{0020}a\u{0020}driver\u{0020}in\u{0020}Aegis.\n\nAshlica\u{0020}has\u{0020}shown\u{0020}excellent\u{0020}tactical\u{0020}capabilities\u{0020}in\u{0020}training,\u{0020}she\u{0020}was\u{0020}self-disciplined\u{0020}which\u{0020}naturally\u{0020}made\u{0020}her\u{0020}like\u{0020}a\u{0020}servicewoman.\u{0020}As\u{0020}she\u{0020}graduated\u{0020}with\u{0020}superior\u{0020}grades\u{0020}in\u{0020}both\u{0020}battle\u{0020}exercise\u{0020}and\u{0020}tactical\u{0020}theories,\u{0020}she\u{0020}got\u{0020}the\u{0020}permission\u{0020}of\u{0020}starting\u{0020}her\u{0020}own\u{0020}squad,\u{0020}and\u{0020}became\u{0020}the\u{0020}captain\u{0020}of\u{0020}\"Imperial\u{0020}Strings\"\n\n\"Recently,\u{0020}I\u{0020}often\u{0020}hear\u{0020}indescribable\u{0020}music\u{0020}on\u{0020}the\u{0020}ark…like\u{0020}call\u{0020}outs\u{0020}from\u{0020}hell.\u{0020}Unpleasing?No,\u{0020}not\u{0020}really…\"\n\nOn\u{0020}the\u{0020}ark\u{0020}of\u{0020}Kyushu,\u{0020}there\u{0020}is\u{0020}a\u{0020}myth:\u{0020}during\u{0020}every\u{0020}tranquil\u{0020}night,\u{0020}the\u{0020}gate\u{0020}to\u{0020}hell\u{0020}opens,\u{0020}and\u{0020}music\u{0020}starts\u{0020}from\u{0020}there.\u{0020}Well,\u{0020}the\u{0020}truth\u{0020}is,\u{0020}that's\u{0020}Ashlica\u{0020}singing\u{0020}vigorously\u{0020}in\u{0020}her\u{0020}room\u{0020}after\u{0020}missions.", "0", "0", "0", "0", 11008, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"爱露达死亡深渊\"加入艾吉斯似乎是一种必然。\n\u{1000}\u{1000}艾希丽卡用自己的方式鼓舞着深受原罪侵害的人们，但她知道真正能让人们回到以前生活的方式，是与原罪战斗。因此，当AVG企划启动后，她便成为了艾吉斯的驾驶员。\n\u{1000}\u{1000}艾希丽卡在训练中展现出良好的战斗素养，她严于律己的行事风格使得她像是一名天生的军人。无论是模拟战成绩亦或是理论知识都取得优秀成绩的她，在毕业后顺理成章地获得了建队的资格，成为了\"绞皇\"的队长。\n\u{1000}\u{1000}\"最近，小生常常在方舟上听见无法形容的歌声……那就像是从地狱里传来的呼声一样呀。难听？不，倒也不难听啦……\"\n\u{1000}\u{1000}在九州总部的方舟上，流传着这么一个传说，每当夜深人静时，地狱的大门就会开启，歌声便是从里面传来的——而传说的正体，实际上是任务结束后在自己宿舍里激情演唱的艾希丽卡。"},
[610804] = {610804, 2000, "\u{0020}\u{0020}Drummer\u{0020}beats\u{0020}the\u{0020}rhythm,\n\nHer\u{0020}performance\u{0020}begins,\n\nHer\u{0020}fingers\u{0020}play\u{0020}the\u{0020}bass,\n\nWhile\u{0020}she\u{0020}steps\u{0020}on\u{0020}the\u{0020}ruins.\n\nThis\u{0020}is\u{0020}only\u{0020}the\u{0020}prelude,\u{0020}and\u{0020}it\u{0020}feels\u{0020}like\u{0020}a\u{0020}battering\u{0020}ram.\n\nWhen\u{0020}she\u{0020}starts\u{0020}singing,\u{0020}her\u{0020}soul-penetrating\u{0020}voice\u{0020}emerges.\u{0020}Just\u{0020}like\u{0020}the\u{0020}myth\u{0020}said,\u{0020}from\u{0020}hell.\u{0020}But\u{0020}like\u{0020}some\u{0020}magic,\u{0020}inexplicably,\u{0020}it\u{0020}evokes\u{0020}our\u{0020}spirit.\n\n\"Navigator,\u{0020}and\u{0020}everybody…LET'S\u{0020}GO!\u{0020}LET'S\u{0020}CRUSH\u{0020}THESE\u{0020}NASTY\u{0020}SINS!!\"", "0", "0", "0", "0", 11008, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}鼓手按着韵律敲打，\n\u{1000}\u{1000}她的演奏便开始了，\n\u{1000}\u{1000}手指在贝斯上拨动，\n\u{1000}\u{1000}脚踩着已是废墟的大楼，\n\u{1000}\u{1000}仅仅只是旋律的前奏部分就有着攻城锤般的气势，\n\u{1000}\u{1000}当她开口的那一刻，贯穿灵魂的歌声便传了出来，那是如传言的那样，像是从地狱里传出的呼声，但是却如魔法般不可思议地让人情绪高涨了起来。\n\u{1000}\u{1000}\"领航、以及各位……我们一起上吧！把眼前这些原罪碾碎！！\""},
[610900] = {610900, 0, "[Name]\u{0020}Bolina\u{0020}I.\u{0020}Rovsky\n[B-Day]\u{0020}April\u{0020}19\n[Compatability\u{0020}Rate]\u{0020}74％\n[Height]\u{0020}37m\n[Squad]\u{0020}Ember\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Candy;\u{0020}Iliya\u{0020}K\u{0020}Bronchi", "0", "0", "0", "0", 11009, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}波琳娜·伊·罗夫斯基\n[B-Day]\u{1000}4月19日\n[幻化核心适格率]\u{1000}74％\n[Height]\u{1000}37m\n[部队]\u{1000}灰烬\n[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}糖果\u{1000}伊莉雅•卡•布诺琪"},
[610901] = {610901, 100, "\u{0020}\u{0020}Her\u{0020}appearance\u{0020}is\u{0020}deceptive.\u{0020}Or\u{0020}rather,\u{0020}if\u{0020}someone\u{0020}thinks\u{0020}she\u{0020}is\u{0020}a\u{0020}mature,\u{0020}beautiful\u{0020}and\u{0020}dignified\u{0020}woman\u{0020}because\u{0020}of\u{0020}her\u{0020}appearance,\u{0020}they\u{0020}are\u{0020}completely\u{0020}wrong.\n\nJudging\u{0020}from\u{0020}her\u{0020}childish\u{0020}way\u{0020}of\u{0020}speaking\u{0020}and\u{0020}confused\u{0020}way\u{0020}of\u{0020}thinking,\u{0020}the\u{0020}psychological\u{0020}age\u{0020}of\u{0020}this\u{0020}woman\u{0020}is\u{0020}close\u{0020}to\u{0020}that\u{0020}of\u{0020}a\u{0020}three-year-old\u{0020}human\u{0020}child.\u{0020}Her\u{0020}cognition\u{0020}of\u{0020}the\u{0020}world\u{0020}is\u{0020}like\u{0020}a\u{0020}blank\u{0020}sheet\u{0020}of\u{0020}paper.\u{0020}She\u{0020}knows\u{0020}nothing\u{0020}except\u{0020}for\u{0020}fighting\u{0020}and\u{0020}has\u{0020}no\u{0020}basic\u{0020}common\u{0020}sense\u{0020}of\u{0020}life.\u{0020}To\u{0020}give\u{0020}a\u{0020}simple\u{0020}example,\u{0020}when\u{0020}performing\u{0020}combat\u{0020}tasks,\u{0020}compared\u{0020}with\u{0020}her\u{0020}teammates\u{0020}who\u{0020}are\u{0020}obsessed\u{0020}with\u{0020}funds\u{0020}and\u{0020}rewards,\u{0020}she\u{0020}prefers\u{0020}candy\u{0020}as\u{0020}the\u{0020}task\u{0020}reward.\n\nShe\u{0020}is\u{0020}often\u{0020}given\u{0020}special\u{0020}care\u{0020}by\u{0020}her\u{0020}teammates\u{0020}and\u{0020}the\u{0020}team\u{0020}leader.\u{0020}It\u{0020}is\u{0020}hard\u{0020}to\u{0020}imagine\u{0020}how\u{0020}she\u{0020}could\u{0020}survive\u{0020}in\u{0020}this\u{0020}bad\u{0020}world\u{0020}alone\u{0020}if\u{0020}the\u{0020}team\u{0020}members\u{0020}who\u{0020}were\u{0020}supposed\u{0020}to\u{0020}take\u{0020}good\u{0020}care\u{0020}of\u{0020}her\u{0020}failed\u{0020}to\u{0020}do\u{0020}their\u{0020}duty.\n\nDuring\u{0020}battles,\u{0020}she\u{0020}intentionally\u{0020}controls\u{0020}her\u{0020}output\u{0020}to\u{0020}reduce\u{0020}damage\u{0020}to\u{0020}the\u{0020}environment.\u{0020}After\u{0020}the\u{0020}battle,\u{0020}she\u{0020}participates\u{0020}in\u{0020}the\u{0020}reconstruction\u{0020}of\u{0020}disaster-stricken\u{0020}areas.\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}in\u{0020}a\u{0020}battle\u{0020}mission,\u{0020}in\u{0020}order\u{0020}to\u{0020}cover\u{0020}the\u{0020}evacuation\u{0020}of\u{0020}civilians,\u{0020}she\u{0020}was\u{0020}seriously\u{0020}injured\u{0020}and\u{0020}nearly\u{0020}died.\u{0020}Because\u{0020}of\u{0020}her\u{0020}kindness,\u{0020}she\u{0020}was\u{0020}given\u{0020}the\u{0020}lovely\u{0020}title\u{0020}of\u{0020}\"Gray\u{0020}Angel\"\u{0020}by\u{0020}some\u{0020}civilians.", "0", "0", "0", "0", 11009, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}她的外表具备着欺骗性，或者说，如果有人因为她的外貌而认为她是一名成熟、美丽、端庄的女性，那就大错特错了。\n\u{1000}\u{1000}从她如幼儿的说话方式，以及懵懂的思维方式来判断，这名女性的心理年龄接近人类的三岁幼童。她对于世界的认知宛如白纸一样，除了战斗之外的事情一概不知，不具备基础的生活常识。简单地举个例子，在执行作战任务时，比起执着于经费与报酬的队友们，她更加希望以糖果作为任务的奖励。\n\u{1000}\u{1000}她常常会受到自己的队友与队长的特殊照顾。如果没有尽职尽责在照顾她的队员，很难想象她一个人该如何在这个糟糕的世界上生存下来。\n\u{1000}\u{1000}在战斗中，她会有意地控制自己的出力，以减少对环境的破坏。在战斗结束后，她会参与到灾区的重建上。据说，在一次战斗任务中，她为了掩护平民撤离，身负重伤，险些死去。善良的她因此被一部分平民冠上了\"灰色天使\"这样可爱的称号。"},
[610902] = {610902, 500, "\u{0020}\u{0020}Bolina\u{0020}I.\u{0020}Rovsky\u{0020}is\u{0020}not\u{0020}an\u{0020}ordinary\u{0020}person.\u{0020}This\u{0020}can\u{0020}be\u{0020}seen\u{0020}from\u{0020}her\u{0020}brave\u{0020}combat\u{0020}performance\u{0020}and\u{0020}the\u{0020}childish\u{0020}mental\u{0020}age\u{0020}that\u{0020}does\u{0020}not\u{0020}match\u{0020}her\u{0020}appearance.\n\nThe\u{0020}anomaly\u{0020}of\u{0020}Bolina\u{0020}originated\u{0020}from\u{0020}a\u{0020}certain\u{0020}laboratory\u{0020}of\u{0020}AEGIS\u{0020}Katya\u{0020}Branch.\u{0020}She\u{0020}was\u{0020}the\u{0020}first-generation\u{0020}biochemical\u{0020}infantry\u{0020}cultivated\u{0020}in\u{0020}that\u{0020}laboratory.\n\nThe\u{0020}Katya\u{0020}Branch\u{0020}of\u{0020}AEGIS\u{0020}launched\u{0020}the\u{0020}[Angel]\u{0020}\u{0020}project\u{0020}in\u{0020}order\u{0020}to\u{0020}confront\u{0020}the\u{0020}emerging\u{0020}Sin.\n\nThe\u{0020}power\u{0020}obtained\u{0020}through\u{0020}forbidden\u{0020}experiments\u{0020}has\u{0020}brought\u{0020}an\u{0020}extremely\u{0020}heavy\u{0020}burden\u{0020}to\u{0020}the\u{0020}body,\u{0020}and\u{0020}almost\u{0020}no\u{0020}experimental\u{0020}subject\u{0020}can\u{0020}survive\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\u{0020}The\u{0020}only\u{0020}living\u{0020}one\u{0020}is\u{0020}Bolina\u{0020}I.\u{0020}Rovsky\u{0020}who\u{0020}has\u{0020}undergone\u{0020}three\u{0020}body\u{0020}modification\u{0020}surgeries.\n\nThe\u{0020}multiple\u{0020}failures\u{0020}of\u{0020}the\u{0020}experiment,\u{0020}coupled\u{0020}with\u{0020}the\u{0020}fact\u{0020}that\u{0020}the\u{0020}experiment\u{0020}itself\u{0020}violated\u{0020}scientific\u{0020}ethics.\u{0020}After\u{0020}the\u{0020}headquarters\u{0020}learned\u{0020}about\u{0020}the\u{0020}project,\u{0020}the\u{0020}Angel\u{0020}Project\u{0020}was\u{0020}terminated,\u{0020}and\u{0020}almost\u{0020}all\u{0020}members\u{0020}of\u{0020}the\u{0020}project\u{0020}team\u{0020}were\u{0020}arrested\u{0020}and\u{0020}imprisoned.\n\nAfter\u{0020}the\u{0020}experiment\u{0020}was\u{0020}terminated,\u{0020}Bolina\u{0020}disappeared\u{0020}from\u{0020}people's\u{0020}sight.\u{0020}When\u{0020}she\u{0020}reappeared,\u{0020}she\u{0020}was\u{0020}already\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Ember\u{0020}team\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region,\u{0020}actively\u{0020}participating\u{0020}in\u{0020}the\u{0020}battle\u{0020}against\u{0020}Sin\u{0020}as\u{0020}an\u{0020}important\u{0020}combat\u{0020}member\u{0020}of\u{0020}the\u{0020}team.\n\nPerhaps\u{0020}someone\u{0020}entrusted\u{0020}her\u{0020}to\u{0020}'Ember',\u{0020}or\u{0020}maybe\u{0020}she\u{0020}met\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ember\u{0020}during\u{0020}her\u{0020}escape\u{0020}-\u{0020}this\u{0020}point,\u{0020}perhaps\u{0020}only\u{0020}the\u{0020}parties\u{0020}involved\u{0020}know\u{0020}for\u{0020}sure.\n\nThe\u{0020}intelligence\u{0020}officer\u{0020}of\u{0020}Katya\u{0020}Branch\u{0020}said\u{0020}so.\n\nThe\u{0020}experiment\u{0020}itself\u{0020}was\u{0020}unethical\u{0020}and\u{0020}immoral,\u{0020}but\u{0020}it\u{0020}did\u{0020}bring\u{0020}extraordinary\u{0020}power\u{0020}to\u{0020}Bolina.\u{0020}In\u{0020}combat,\u{0020}if\u{0020}she\u{0020}doesn't\u{0020}deliberately\u{0020}control\u{0020}her\u{0020}power,\u{0020}then\u{0020}not\u{0020}only\u{0020}the\u{0020}Sin,\u{0020}but\u{0020}even\u{0020}the\u{0020}cities\u{0020}where\u{0020}humans\u{0020}live\u{0020}and\u{0020}the\u{0020}forests\u{0020}where\u{0020}animals\u{0020}dwell\u{0020}would\u{0020}be\u{0020}destroyed\u{0020}by\u{0020}her\u{0020}in\u{0020}an\u{0020}instant.\u{0020}In\u{0020}other\u{0020}words,\u{0020}Bolina\u{0020}fighting\u{0020}with\u{0020}all\u{0020}her\u{0020}strength\u{0020}can\u{0020}cause\u{0020}more\u{0020}terrifying\u{0020}damage\u{0020}than\u{0020}the\u{0020}Sin.\u{0020}Therefore,\u{0020}no\u{0020}matter\u{0020}how\u{0020}innocent\u{0020}and\u{0020}lovely\u{0020}she\u{0020}behaves,\u{0020}always\u{0020}remember\u{0020}-\u{0020}she\u{0020}is\u{0020}both\u{0020}an\u{0020}angel\u{0020}protecting\u{0020}humanity\u{0020}and\u{0020}a\u{0020}devil\u{0020}who\u{0020}could\u{0020}shatter\u{0020}the\u{0020}earth\u{0020}at\u{0020}any\u{0020}time.\n\nTherefore,\u{0020}no\u{0020}matter\u{0020}how\u{0020}innocent\u{0020}and\u{0020}lovely\u{0020}she\u{0020}behaves,\u{0020}always\u{0020}remember\u{0020}-\u{0020}she\u{0020}is\u{0020}both\u{0020}an\u{0020}angel\u{0020}protecting\u{0020}humanity\u{0020}and\u{0020}a\u{0020}devil\u{0020}who\u{0020}could\u{0020}shatter\u{0020}the\u{0020}earth\u{0020}at\u{0020}any\u{0020}time.", "0", "0", "0", "0", 11009, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}波琳娜·伊·罗夫斯基并不是普通人，这一点从她勇猛的作战表现以及与外观不符的幼稚心理年龄能够窥见端倪。\n\u{1000}\u{1000}波琳娜的异常，源自于艾吉斯Katya\u{1000}Branch的某间实验室。她是该实验室培养的初代生化步兵。\n\u{1000}\u{1000}艾吉斯的Katya\u{1000}Branch为了与陆续出现的原罪对抗，启动了[天使]\u{1000}计划。\n\u{1000}\u{1000}通过禁忌的实验获得的力量给肉体带来了极大的负荷，几乎没有一个实验体能够长时间的存活。唯一一个活体便是经历了三次肉体改造手术的波琳娜·伊·罗夫斯基。\n\u{1000}\u{1000}实验的多次失败，加上该项实验本身违反了科学伦理，在总部得知了该项项目后，天使计划被终止，项目组成员几乎尽数逮捕入狱。\n\u{1000}\u{1000}实验终止后，波琳娜从人们的视野里消失了。当她再一次出现时，她已经是卡佳地区的灰烬小队的一员，作为队伍中重要的战斗成员而活跃在对抗原罪的作战中。\n\u{1000}\u{1000}\"也许是有人把她托付给了‘灰烬’，也有可能是逃亡途中她与灰烬的队长相遇了——这一点，恐怕只有当事人清楚了。\"\n\u{1000}\u{1000}Katya\u{1000}Branch的情报人员如此说道。\n\u{1000}\u{1000}实验本身是违反伦理道德的，但是实验的确给波琳娜带来了非同寻常的力量。在作战中，她如果不特意控制自己的力量，那么不仅是原罪，就连人类居住的城市，动物栖息的森林，也会被她毁于一旦。换句话说，全力战斗的波琳娜，能够造成的破坏比原罪还要恐怖。\n\u{1000}\u{1000}因此，无论她表现得多么天真可爱，都要始终记住——她是既是守护人类的天使，同时又是随时都可能粉碎大地的恶魔。"},
[610903] = {610903, 1000, "\u{0020}\u{0020}After\u{0020}Stephanie\u{0020}reached\u{0020}an\u{0020}agreement\u{0020}with\u{0020}the\u{0020}Ember,\u{0020}the\u{0020}Ember\u{0020}was\u{0020}officially\u{0020}incorporated\u{0020}into\u{0020}AEGIS\u{0020}and\u{0020}came\u{0020}under\u{0020}the\u{0020}command\u{0020}led\u{0020}by\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force.\u{0020}The\u{0020}relevant\u{0020}information\u{0020}of\u{0020}Bolina\u{0020}I.\u{0020}Rovsky\u{0020}has\u{0020}also\u{0020}been\u{0020}officially\u{0020}completed\u{0020}and\u{0020}written\u{0020}into\u{0020}the\u{0020}archives\u{0020}of\u{0020}AEGIS.\n\nThe\u{0020}formidable\u{0020}power\u{0020}brought\u{0020}by\u{0020}the\u{0020}\"Angel\"\u{0020}program\u{0020}is\u{0020}not\u{0020}without\u{0020}a\u{0020}price.\u{0020}Also\u{0020}using\u{0020}immature\u{0020}AVG\u{0020}armor\u{0020}technology,\u{0020}Bolina's\u{0020}physical\u{0020}load\u{0020}is\u{0020}far\u{0020}higher\u{0020}than\u{0020}that\u{0020}of\u{0020}Iliya\u{0020}K\u{0020}Bronchi.\n\nCurrently,\u{0020}in\u{0020}order\u{0020}to\u{0020}eliminate\u{0020}the\u{0020}sequelae\u{0020}remaining\u{0020}on\u{0020}Bolina's\u{0020}body,\u{0020}the\u{0020}medical\u{0020}department\u{0020}and\u{0020}maintenance\u{0020}department\u{0020}of\u{0020}AEGIS\u{0020}are\u{0020}continuously\u{0020}treating\u{0020}Bolina's\u{0020}body.\n\nHowever,\u{0020}for\u{0020}the\u{0020}naive\u{0020}Bolina,\u{0020}how\u{0020}her\u{0020}own\u{0020}body\u{0020}would\u{0020}be\u{0020}was\u{0020}not\u{0020}important.\u{0020}The\u{0020}life\u{0020}with\u{0020}Iliya\u{0020}and\u{0020}Crim\u{0020}was\u{0020}all\u{0020}she\u{0020}had.\n\nNow,\u{0020}there\u{0020}is\u{0020}still\u{0020}a\u{0020}driver\u{0020}accompanying\u{0020}her.\n\nShe\u{0020}considers\u{0020}herself\u{0020}to\u{0020}be\u{0020}the\u{0020}happiest\u{0020}child\u{0020}in\u{0020}the\u{0020}world.", "0", "0", "0", "0", 11009, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}在史蒂芬妮与灰烬小队达成协议后，灰烬小队正式被编入艾吉斯，接受多瑙特别联合部队领航的指挥。波琳娜·伊·罗夫斯基的相关资料也正式补全，写入艾吉斯的档案库中。\n\u{1000}\u{1000}\"天使\"计划带来的强大力量并不是没有代价的，同样是使用不成熟的avg装甲技术，波琳娜所承受的肉体负荷要远在伊莉雅·卡·布诺琪之上。\n\u{1000}\u{1000}目前，为了消除残留在波琳娜的身体上的后遗症，艾吉斯的医疗部门与维修部门正在持续性地治疗波琳娜的身体。\n\u{1000}\u{1000}不过，对于懵懂的波琳娜而言，自己的身体会如何并不重要。与伊莉雅、克里姆在一起的生活便是她的全部。\n\u{1000}\u{1000}现在，还有着领航在陪伴她。\n\u{1000}\u{1000}自己就是世界上最幸福的孩子——她是如此认为的。"},
[610904] = {610904, 2000, "\u{0020}\u{0020}She\u{0020}has\u{0020}never\u{0020}expected\u{0020}that\u{0020}she\u{0020}could\u{0020}live\u{0020}an\u{0020}ordinary\u{0020}life.\n\nShe\u{0020}is\u{0020}not\u{0020}yearning\u{0020}for...\u{0020}At\u{0020}least\u{0020}not\u{0020}as\u{0020}much\u{0020}as\u{0020}others\u{0020}imagine\u{0020}for\u{0020}an\u{0020}ordinary\u{0020}life.\n\nFor\u{0020}her,\u{0020}maintaining\u{0020}the\u{0020}current\u{0020}situation\u{0020}is\u{0020}fine.\n\nShe\u{0020}just\u{0020}wants\u{0020}to\u{0020}be\u{0020}with\u{0020}her\u{0020}companions\u{0020}and\u{0020}the\u{0020}navigator.\n\nShe\u{0020}happily\u{0020}lifted\u{0020}the\u{0020}navigator\u{0020}up\u{0020}to\u{0020}the\u{0020}sky.\n\n\"Please\u{0020}stay\u{0020}with\u{0020}Bolina,\u{0020}don't\u{0020}leave\u{0020}Bolina,\u{0020}okay?\"", "0", "0", "0", "0", 11009, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}她从未奢望过自己能够过上常人的生活，\n\u{1000}\u{1000}她也并不向往……至少没有别人想象中的那么向往普通人的生活。\n\u{1000}\u{1000}对她来说，维持现在就行了，\n\u{1000}\u{1000}她只想和同伴，和领航在一起。\n\u{1000}\u{1000}\"所以——领航。\"\n\u{1000}\u{1000}她开心地将领航捧了起来，捧到了天上，\n\u{1000}\u{1000}\"请一直陪着波琳娜吧，不要丢下波琳娜，好吗？\""},
[611000] = {611000, 0, "[Name]\u{0020}Rou\n[B-Day]\u{0020}March\u{0020}3\n[Compatability\u{0020}Rate]\u{0020}47％\n[Height]\u{0020}28m\n[Squad]\u{0020}Mammalia\n[Affiliation]\u{0020}Maya\u{0020}Branch\n[Interest]\u{0020}A\u{0020}rhizome\u{0020}called\u{0020}\"Carrot.\"", "0", "0", "0", "0", 11010, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}珑\n[B-Day]\u{1000}冬天下第一场雪的时候\n[幻化核心适格率]\u{1000}47％\n[Height]\u{1000}28m\n[部队]\u{1000}麻麻莲\n\u{1000}\u{00A0}[隶属]\u{1000}Maya\u{1000}Branch\n[Interest]\u{1000}名为\"胡萝卜\"的根茎类植物"},
[611001] = {611001, 100, "\u{0020}\u{0020}If\u{0020}looking\u{0020}for\u{0020}a\u{0020}special\u{0020}warrior\u{0020}among\u{0020}many\u{0020}excellent\u{0020}drivers,\u{0020}then\u{0020}she\u{0020}is\u{0020}undoubtedly\u{0020}the\u{0020}first\u{0020}candidate.\n\nShe\u{0020}possesses\u{0020}physical\u{0020}qualities\u{0020}that\u{0020}are\u{0020}more\u{0020}than\u{0020}five\u{0020}times\u{0020}that\u{0020}of\u{0020}an\u{0020}average\u{0020}person,\u{0020}has\u{0020}extremely\u{0020}excellent\u{0020}mobility\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}and\u{0020}demonstrates\u{0020}remarkable\u{0020}combat\u{0020}skills\u{0020}during\u{0020}training,\u{0020}but\u{0020}all\u{0020}of\u{0020}this\u{0020}is\u{0020}not\u{0020}the\u{0020}reason\u{0020}for\u{0020}her\u{0020}uniqueness.\n\nShe\u{0020}is\u{0020}very\u{0020}timid.\n\nHer\u{0020}timidity\u{0020}perfectly\u{0020}matched\u{0020}her\u{0020}body\u{0020}size.\u{0020}Once\u{0020}she\u{0020}was\u{0020}under\u{0020}a\u{0020}certain\u{0020}degree\u{0020}of\u{0020}pressure\u{0020}during\u{0020}the\u{0020}mission,\u{0020}she\u{0020}would\u{0020}timidly\u{0020}flee\u{0020}from\u{0020}the\u{0020}battlefield.\u{0020}If\u{0020}it\u{0020}wasn't\u{0020}for\u{0020}the\u{0020}captain\u{0020}and\u{0020}Mizo\u{0020}on\u{0020}the\u{0020}same\u{0020}team\u{0020}handling\u{0020}the\u{0020}trouble\u{0020}for\u{0020}her,\u{0020}she\u{0020}would\u{0020}have\u{0020}been\u{0020}court-martialed\u{0020}for\u{0020}her\u{0020}escape.\n\nWhen\u{0020}she\u{0020}confronts\u{0020}Sin\u{0020}directly,\u{0020}a\u{0020}sense\u{0020}of\u{0020}fear\u{0020}will\u{0020}rule\u{0020}her\u{0020}heart,\u{0020}and\u{0020}her\u{0020}synchronization\u{0020}rate\u{0020}with\u{0020}AVG\u{0020}drops\u{0020}to\u{0020}the\u{0020}bottom.\u{0020}For\u{0020}this,\u{0020}the\u{0020}captain\u{0020}and\u{0020}Mizo\u{0020}have\u{0020}thought\u{0020}of\u{0020}many\u{0020}ways,\u{0020}but\u{0020}without\u{0020}exception,\u{0020}none\u{0020}of\u{0020}them\u{0020}have\u{0020}worked.\n\nFor\u{0020}her\u{0020}timid\u{0020}self,\u{0020}she\u{0020}also\u{0020}harbors\u{0020}a\u{0020}deep\u{0020}sense\u{0020}of\u{0020}inferiority\u{0020}and\u{0020}disgust.\u{0020}Perhaps,\u{0020}she\u{0020}needs\u{0020}someone\u{0020}who\u{0020}can\u{0020}truly\u{0020}heal\u{0020}her\u{0020}to\u{0020}appear\u{0020}and\u{0020}help\u{0020}her\u{0020}untie\u{0020}the\u{0020}knot\u{0020}in\u{0020}her\u{0020}heart.", "0", "0", "0", "0", 11010, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}如果要在诸多优秀的驾驶员里寻找一个特殊的战士，那么她无疑是第一候选人。\n\u{1000}\u{1000}她拥有着超出常人五倍以上的身体素质，在战场上有着极其出色的机动性，并且在训练中展示出不俗的战斗技巧，但这一切都不是她特殊的原因。\n\u{1000}\u{1000}她很胆小。\n\u{1000}\u{1000}她胆小的程度与自己体型完美匹配，一旦在执行任务的过程中受到一定程度的压力，她便会胆怯地从战场上逃离。如果不是有队长与同队的渠在为她处理麻烦，她早就因为自己的逃跑行为上军事法庭了。\n\u{1000}\u{1000}当她直面原罪时，恐惧感便会统治她的内心，她与avg的同调率跌至谷底。为此，队长与渠想了不少办法，但无一例外地没有效果。\n\u{1000}\u{1000}对于胆小的自己，她也怀着深深的自卑感与嫌恶感。也许，她需要一个真正能够治愈她的人出现，帮她解开心结。"},
[611002] = {611002, 500, "\u{0020}\u{0020}Rou's\u{0020}hometown\u{0020}\"Eta\"\u{0020}was\u{0020}a\u{0020}planet\u{0020}destroyed\u{0020}by\u{0020}Sin.\u{0020}Rou\u{0020}followed\u{0020}some\u{0020}of\u{0020}her\u{0020}clansmen\u{0020}and\u{0020}fled\u{0020}to\u{0020}Earth\u{0020}when\u{0020}Sin\u{0020}destroyed\u{0020}Eta.\u{0020}The\u{0020}change\u{0020}of\u{0020}the\u{0020}home\u{0020}planet\u{0020}from\u{0020}prosperity\u{0020}to\u{0020}extinction\u{0020}left\u{0020}an\u{0020}indelible\u{0020}impression\u{0020}on\u{0020}the\u{0020}young\u{0020}Rou.\u{0020}Perhaps\u{0020}from\u{0020}that\u{0020}moment\u{0020}on,\u{0020}it\u{0020}was\u{0020}destined\u{0020}that\u{0020}Rou\u{0020}would\u{0020}not\u{0020}have\u{0020}the\u{0020}courage\u{0020}to\u{0020}face\u{0020}Sin\u{0020}directly.\n\nAfter\u{0020}fleeing\u{0020}to\u{0020}Earth,\u{0020}due\u{0020}to\u{0020}the\u{0020}agreement\u{0020}reached\u{0020}between\u{0020}the\u{0020}Eta\u{0020}star\u{0020}survivors\u{0020}and\u{0020}the\u{0020}Earth\u{0020}government,\u{0020}Rou\u{0020}was\u{0020}trained\u{0020}to\u{0020}become\u{0020}a\u{0020}driver.\u{0020}Despite\u{0020}the\u{0020}racial\u{0020}reasons,\u{0020}the\u{0020}same\u{0020}frequency\u{0020}with\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}was\u{0020}not\u{0020}satisfactory.\u{0020}Her\u{0020}indicators\u{0020}could\u{0020}only\u{0020}barely\u{0020}drive\u{0020}the\u{0020}AVG.\u{0020}But\u{0020}because\u{0020}she\u{0020}performed\u{0020}well\u{0020}like\u{0020}her\u{0020}fellow\u{0020}clansmen\u{0020}in\u{0020}the\u{0020}AVG\u{0020}military\u{0020}fighting\u{0020}competition,\u{0020}Rou\u{0020}was\u{0020}regarded\u{0020}as\u{0020}an\u{0020}excellent\u{0020}driver\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Maya\u{0020}Branch.\n\nWhat\u{0020}really\u{0020}disappoints\u{0020}people\u{0020}about\u{0020}Rou\u{0020}is\u{0020}when\u{0020}she\u{0020}truly\u{0020}faces\u{0020}Sin.\u{0020}At\u{0020}the\u{0020}moment\u{0020}of\u{0020}contact\u{0020}with\u{0020}Sin,\u{0020}her\u{0020}anger\u{0020}and\u{0020}fear\u{0020}towards\u{0020}Sin\u{0020}made\u{0020}her\u{0020}lose\u{0020}synchronization\u{0020}with\u{0020}the\u{0020}AVG\u{0020}instantly,\u{0020}lose\u{0020}her\u{0020}combat\u{0020}effectiveness,\u{0020}and\u{0020}even\u{0020}nearly\u{0020}lose\u{0020}her\u{0020}life.\u{0020}However,\u{0020}the\u{0020}first\u{0020}time\u{0020}did\u{0020}not\u{0020}mean\u{0020}the\u{0020}end.\u{0020}Since\u{0020}then,\u{0020}Rou\u{0020}has\u{0020}violated\u{0020}the\u{0020}orders\u{0020}of\u{0020}her\u{0020}superiors\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}many\u{0020}times,\u{0020}fled\u{0020}from\u{0020}the\u{0020}battle,\u{0020}and\u{0020}has\u{0020}received\u{0020}administrative\u{0020}penalties\u{0020}many\u{0020}times.\n\nThe\u{0020}evaluation\u{0020}that\u{0020}\"She\u{0020}is\u{0020}not\u{0020}yet\u{0020}ready\u{0020}to\u{0020}become\u{0020}a\u{0020}warrior\"\u{0020}is\u{0020}objective\u{0020}and\u{0020}accurate.\u{0020}However,\u{0020}the\u{0020}excellent\u{0020}qualities\u{0020}that\u{0020}Rou\u{0020}demonstrated\u{0020}during\u{0020}training\u{0020}made\u{0020}her\u{0020}superiors\u{0020}reluctant\u{0020}to\u{0020}give\u{0020}up\u{0020}on\u{0020}her.\u{0020}So\u{0020}Maya\u{0020}Branch\u{0020}came\u{0020}up\u{0020}with\u{0020}a\u{0020}compromise\u{0020}for\u{0020}Rou's\u{0020}situation\u{0020}-\u{0020}sending\u{0020}Rou\u{0020}alone\u{0020}to\u{0020}conduct\u{0020}intelligence\u{0020}searches\u{0020}in\u{0020}dangerous\u{0020}enemy-occupied\u{0020}areas.In\u{0020}this\u{0020}way,\u{0020}even\u{0020}if\u{0020}one\u{0020}withdraws\u{0020}directly\u{0020}upon\u{0020}encountering\u{0020}danger,\u{0020}it\u{0020}will\u{0020}not\u{0020}affect\u{0020}the\u{0020}battle\u{0020}situation\u{0020}on\u{0020}the\u{0020}frontal\u{0020}battlefield.\n\nThe\u{0020}scene\u{0020}of\u{0020}the\u{0020}destruction\u{0020}of\u{0020}the\u{0020}mother\u{0020}planet\u{0020}became\u{0020}a\u{0020}hurdle\u{0020}in\u{0020}Rou's\u{0020}heart,\u{0020}and\u{0020}to\u{0020}this\u{0020}day,\u{0020}she\u{0020}is\u{0020}still\u{0020}trapped\u{0020}in\u{0020}place\u{0020}and\u{0020}unable\u{0020}to\u{0020}move\u{0020}forward.", "0", "0", "0", "0", 11010, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}珑的故乡\"埃塔\"是一颗被原罪摧毁的星球。珑跟随者一部分族人在原罪摧毁埃塔星球时逃离至地球。母星从昌盛到灭亡的变化给年幼的珑留下了不可磨灭的印象，或许从那一刻起，就注定了珑不会有直面原罪的勇气。\n\u{1000}\u{1000}在逃亡至地球上之后，因为埃塔星幸存者与地球政府之间达成的协议，珑受训成为了一名驾驶员。尽管因为种族的原因，与幻化核心的同频率显得不尽人意，她的指标只能勉强驾驶avg，但因为在avg军事格斗大赛中与同族一样表现出色，珑被当做优秀的驾驶员而成为Maya\u{1000}Branch的一员。\n\u{1000}\u{1000}珑真正让人对她失望的是，当她真正面对原罪的时候。在与原罪接触的那一刻，她对原罪的愤怒与恐惧让她在瞬间失去与avg的同调，失去战斗力，甚至险些丧命。然而第一次并不意味着结束，自那之后，珑多次在战场上违反长官命令，临阵脱逃，并且因此多次受到行政处分。\n\u{1000}\u{1000}\"她还没有做好成为战士的准备\"，这一评价是客观而准确的。但珑在训练中表现出的优秀素质让上级不忍心放弃她。因此Maya\u{1000}Branch就珑这一状况想出了折中的措施——让珑单独前往危险的敌占区域进行情报搜查任务。这样一来，即便遇上危险直接撤离，也不会影响到正面战场上的战局。\n\u{1000}\u{1000}母星毁灭的场景成为了珑心中跨不过去的坎，直至今日，她依然被困于原地，难以前行。"},
[611003] = {611003, 1000, "\u{0020}\u{0020}Compared\u{0020}with\u{0020}her\u{0020}teammates,\u{0020}Rou\u{0020}appears\u{0020}mediocre\u{0020}in\u{0020}all\u{0020}aspects.\u{0020}Even\u{0020}her\u{0020}most\u{0020}outstanding\u{0020}combat\u{0020}quality\u{0020}is\u{0020}overshadowed\u{0020}by\u{0020}the\u{0020}insurmountable\u{0020}psychological\u{0020}problems.\u{0020}Whether\u{0020}as\u{0020}the\u{0020}all-round\u{0020}Mizo\u{0020}or\u{0020}the\u{0020}captain\u{0020}with\u{0020}rich\u{0020}combat\u{0020}experience,\u{0020}the\u{0020}position\u{0020}they\u{0020}are\u{0020}in\u{0020}is\u{0020}at\u{0020}a\u{0020}height\u{0020}that\u{0020}Rou\u{0020}can\u{0020}hardly\u{0020}reach.\n\nIt\u{0020}is\u{0020}precisely\u{0020}because\u{0020}of\u{0020}this\u{0020}that\u{0020}when\u{0020}Rou\u{0020}faced\u{0020}her\u{0020}companions\u{0020}at\u{0020}the\u{0020}beginning,\u{0020}she\u{0020}always\u{0020}held\u{0020}an\u{0020}overly\u{0020}self-abased\u{0020}emotion.\u{0020}She\u{0020}once\u{0020}thought\u{0020}that\u{0020}her\u{0020}assignment\u{0020}to\u{0020}this\u{0020}team\u{0020}was\u{0020}the\u{0020}worst\u{0020}decision\u{0020}of\u{0020}her\u{0020}superiors,\u{0020}and\u{0020}she\u{0020}would\u{0020}sooner\u{0020}or\u{0020}later\u{0020}harm\u{0020}her\u{0020}teammates.\u{0020}However,\u{0020}the\u{0020}captain\u{0020}and\u{0020}Mizo\u{0020}accepted\u{0020}such\u{0020}Rou.\u{0020}They\u{0020}gave\u{0020}Rou\u{0020}full\u{0020}trust.\u{0020}Even\u{0020}when\u{0020}Rou\u{0020}fled\u{0020}at\u{0020}the\u{0020}critical\u{0020}moment,\u{0020}they\u{0020}still\u{0020}didn't\u{0020}blame\u{0020}Rou.\n\nThis\u{0020}excessive\u{0020}tolerance,\u{0020}on\u{0020}the\u{0020}one\u{0020}hand,\u{0020}gave\u{0020}Rou\u{0020}comfort,\u{0020}and\u{0020}on\u{0020}the\u{0020}other\u{0020}hand,\u{0020}made\u{0020}Rou's\u{0020}self-loathing\u{0020}deeper.\u{0020}Whenever\u{0020}she\u{0020}saw\u{0020}Mizo\u{0020}communicating\u{0020}with\u{0020}the\u{0020}superiors\u{0020}because\u{0020}of\u{0020}her\u{0020}own\u{0020}desertion\u{0020}at\u{0020}the\u{0020}critical\u{0020}moment,\u{0020}she\u{0020}would\u{0020}make\u{0020}up\u{0020}her\u{0020}mind\u{0020}to\u{0020}change,\u{0020}but\u{0020}the\u{0020}results\u{0020}were\u{0020}all\u{0020}in\u{0020}vain.\n\n\"I\u{0020}don't\u{0020}want\u{0020}to\u{0020}run\u{0020}away\u{0020}anymore,\u{0020}but\u{0020}they\u{0020}are\u{0020}really\u{0020}terrifying,\u{0020}wu--\"\u{0020}This\u{0020}is\u{0020}probably\u{0020}a\u{0020}true\u{0020}portrayal\u{0020}of\u{0020}her\u{0020}inner\u{0020}thoughts.", "0", "0", "0", "0", 11010, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}珑相较于自己的队友，在各方面都显得平庸，甚至于她最为出色的战斗素养，也因为难以克服的心理问题而黯然失色。无论是作为全能的渠，还是有着丰富作战经验的队长，身处的位置都是珑难以企及的高度。\n\u{1000}\u{1000}正是因为如此，珑在最初面对自己同伴时，总是抱着过度自卑的情绪。她一度认为自己被分配到这支队伍里是上级最糟糕的决定，她迟早会害了自己的队友。然而队长与渠却接纳了这样的珑。她们给予了珑充分的信任，即使在珑临阵脱逃时，也依然没有责怪珑。\n\u{1000}\u{1000}这份过度的包容一方面让珑得到了安慰，一方面又让珑对自己的嫌恶更深。每当看到渠因为自己的临阵脱逃而与上级进行沟通时，她都会下定决心去改变，但结果都是无用。\n\u{1000}\u{1000}\"我不想再逃了，但是它们真的很可怕，呜——\"这就是她的真实内心写照吧。"},
[611004] = {611004, 2000, "\u{0020}\u{0020}The\u{0020}huge\u{0020}girl\u{0020}has\u{0020}a\u{0020}weak\u{0020}heart\u{0020}that\u{0020}doesn't\u{0020}match\u{0020}her\u{0020}body.\n\nThe\u{0020}city\u{0020}burning\u{0020}with\u{0020}the\u{0020}flames\u{0020}of\u{0020}war\u{0020}reminded\u{0020}her\u{0020}of\u{0020}her\u{0020}shattered\u{0020}hometown.\n\nThe\u{0020}courage\u{0020}within\u{0020}was\u{0020}gradually\u{0020}drained\u{0020}away,\u{0020}and\u{0020}both\u{0020}feet\u{0020}gradually\u{0020}lost\u{0020}the\u{0020}strength\u{0020}to\u{0020}stand.\n\nHowever,\n\n\"Navigator,\u{0020}with\u{0020}you\u{0020}here,\u{0020}Rou\u{0020}won't\u{0020}run\u{0020}away!\"\n\nThis\u{0020}timid\u{0020}girl\u{0020}decides\u{0020}to\u{0020}fight\u{0020}in\u{0020}order\u{0020}to\u{0020}protect\u{0020}her\u{0020}important\u{0020}people.", "0", "0", "0", "0", 11010, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}巨大的少女有着与自己身体不符的弱小内心。\n\u{1000}\u{1000}燃烧着战火的城市令她想起自己支离破碎的故乡。\n\u{1000}\u{1000}体内的勇气一点点被抽离，双足逐渐失去站立的力气。\n\u{1000}\u{1000}但是，\n\u{1000}\u{1000}\"领航——有你在的话，珑，珑就不会逃了！\"\n\u{1000}\u{1000}这名胆小的少女，决定为了守护自己重要的人去战斗。"},
[611100] = {611100, 0, "[Name]\u{0020}Gourai\n[B-Day]\u{0020}May\u{0020}1\n[Compatability\u{0020}Rate]\u{0020}89%\n[Height]\u{0020}37m\n[Squad]\u{0020}Ninja\u{0020}Group\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Doing\u{0020}tasks", "0", "0", "0", "0", 11011, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}轰雷\n[B-Day]\u{1000}5月1日\n[幻化核心适格率]\u{1000}\u{1000}89%\n[Height]\u{1000}35m\n[部队]\u{1000}\u{1000}忍心社\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}任务"},
[611101] = {611101, 100, "\u{0020}\u{0020}The\u{0020}captain\u{0020}of\u{0020}the\u{0020}special\u{0020}operations\u{0020}unit\u{0020}\"Ninja\u{0020}Group\"\u{0020}of\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters.\n\n\"Gourai\"\u{0020}is\u{0020}not\u{0020}the\u{0020}real\u{0020}name\u{0020}of\u{0020}this\u{0020}girl.\u{0020}It\u{0020}is\u{0020}only\u{0020}a\u{0020}code\u{0020}name\u{0020}when\u{0020}she\u{0020}acts\u{0020}as\u{0020}a\u{0020}member\u{0020}of\u{0020}\"Ninja\u{0020}Group\".\u{0020}Her\u{0020}real\u{0020}name\u{0020}is\u{0020}still\u{0020}an\u{0020}unsolved\u{0020}mystery\u{0020}for\u{0020}now.\u{0020}Even\u{0020}her\u{0020}real\u{0020}face\u{0020}under\u{0020}the\u{0020}mask\u{0020}has\u{0020}never\u{0020}been\u{0020}seen\u{0020}by\u{0020}anyone.\n\nUsually,\u{0020}she\u{0020}does\u{0020}not\u{0020}act\u{0020}as\u{0020}\"Gourai\",\u{0020}but\u{0020}appears\u{0020}openly\u{0020}in\u{0020}people's\u{0020}vision\u{0020}in\u{0020}another\u{0020}identity\u{0020}-\u{0020}perhaps\u{0020}as\u{0020}a\u{0020}technician\u{0020}of\u{0020}AEGIS,\u{0020}perhaps\u{0020}as\u{0020}a\u{0020}logistics\u{0020}staff\u{0020}of\u{0020}AEGIS.\u{0020}However,\u{0020}no\u{0020}one\u{0020}will\u{0020}know\u{0020}that\u{0020}she\u{0020}is\u{0020}\"Gourai\".\n\nAll\u{0020}of\u{0020}this\u{0020}is\u{0020}related\u{0020}to\u{0020}the\u{0020}functions\u{0020}of\u{0020}the\u{0020}\"Ninja\u{0020}Group\".\u{0020}The\u{0020}\"Ninja\u{0020}Group\"\u{0020}is\u{0020}not\u{0020}an\u{0020}ordinary\u{0020}\"driver\"\u{0020}unit\u{0020}but\u{0020}more\u{0020}like\u{0020}an\u{0020}intelligence\u{0020}department\u{0020}directly\u{0020}under\u{0020}the\u{0020}information\u{0020}hub\u{0020}of\u{0020}Kyushu\u{0020}Headquarters.\n\nDue\u{0020}to\u{0020}the\u{0020}particularity\u{0020}of\u{0020}the\u{0020}\"Ninja\u{0020}Group\",\u{0020}Gourai\u{0020}hardly\u{0020}appears\u{0020}on\u{0020}the\u{0020}frontal\u{0020}battlefield,\u{0020}and\u{0020}the\u{0020}number\u{0020}of\u{0020}times\u{0020}she\u{0020}fought\u{0020}side\u{0020}by\u{0020}side\u{0020}with\u{0020}the\u{0020}drivers\u{0020}who\u{0020}are\u{0020}also\u{0020}of\u{0020}AEGIS\u{0020}can\u{0020}be\u{0020}counted.\n\nGourai\u{0020}always\u{0020}takes\u{0020}completing\u{0020}the\u{0020}task\u{0020}as\u{0020}the\u{0020}primary\u{0020}goal\u{0020}at\u{0020}any\u{0020}time.\u{0020}When\u{0020}necessary,\u{0020}she\u{0020}is\u{0020}even\u{0020}willing\u{0020}to\u{0020}sacrifice\u{0020}her\u{0020}own\u{0020}life\u{0020}just\u{0020}to\u{0020}fulfill\u{0020}the\u{0020}instructions\u{0020}issued\u{0020}by\u{0020}her\u{0020}superiors.\u{0020}Obviously,\u{0020}she\u{0020}regards\u{0020}honor,\u{0020}belief,\u{0020}and\u{0020}these\u{0020}spiritual\u{0020}things\u{0020}as\u{0020}treasures\u{0020}more\u{0020}important\u{0020}than\u{0020}her\u{0020}own\u{0020}life.", "0", "0", "0", "0", 11011, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}艾吉斯九州总部的特殊作战部队\"忍心社\"的队长。\n\u{1000}\u{1000}\"轰雷\"并非这名少女的真实名字，仅仅只是她作为\"忍心社\"成员行动时的代号。她的真实姓名，目前还是一个未解的谜团。就连她面罩下的真实面容，也未曾有人见过。\n\u{1000}\u{1000}在平常，她并不会以\"轰雷\"的身份行动，而是以另一个身份——也许是艾吉斯的技术人员，也许是艾吉斯的后勤人员——光明正大地出现在人们的视野中，但，不会有人知道她就是\"轰雷\"。\n\u{1000}\u{1000}这一切与\"忍心社\"的职能有关，\"忍心社\"并不是一支普通的\"驾驶员\"部队，更像是一个直属于九州总部情报中枢的情报部门。\n\u{1000}\u{1000}因为\"忍心社\"的特殊性，轰雷几乎不会出现在正面战场，与同为艾吉斯的驾驶员并肩作战的次数更是历历可数。\n\u{1000}\u{1000}轰雷在任何时候都以完成任务为首要目标，必要时，她甚至愿意舍弃自己的生命，只为了完成上级下达的指令。显而易见，她将荣誉、信念，这些精神层面的东西，视为比自己生命还重要的宝物。"},
[611102] = {611102, 500, "\u{0020}\u{0020}\"Gourai\"\u{0020}is\u{0020}not\u{0020}only\u{0020}the\u{0020}captain\u{0020}of\u{0020}\"Ninja\u{0020}Group\",\u{0020}but\u{0020}also\u{0020}one\u{0020}of\u{0020}the\u{0020}founders\u{0020}of\u{0020}Ninja\u{0020}Group.\u{0020}It\u{0020}was\u{0020}because\u{0020}of\u{0020}her\u{0020}proposal\u{0020}that\u{0020}Kyushu\u{0020}Headquarters\u{0020}came\u{0020}up\u{0020}with\u{0020}the\u{0020}idea:\u{0020}to\u{0020}establish\u{0020}a\u{0020}secret\u{0020}force\u{0020}with\u{0020}different\u{0020}functions\u{0020}from\u{0020}\"Executioner\".\n\n\"Executioner\",\u{0020}more\u{0020}often,\u{0020}is\u{0020}to\u{0020}execute\u{0020}the\u{0020}drivers\u{0020}who\u{0020}intend\u{0020}to\u{0020}betray\u{0020}AEGIS\u{0020}or\u{0020}have\u{0020}already\u{0020}committed\u{0020}crimes.\u{0020}However,\u{0020}the\u{0020}\"evidence\u{0020}collection\"\u{0020}part\u{0020}before\u{0020}the\u{0020}execution\u{0020}is\u{0020}the\u{0020}weak\u{0020}part\u{0020}of\u{0020}Executioner.\u{0020}Therefore,\u{0020}\"Ninja\u{0020}Group\"\u{0020}was\u{0020}born.\n\nThe\u{0020}main\u{0020}task\u{0020}of\u{0020}\"Ninja\u{0020}Group\"\u{0020}is\u{0020}to\u{0020}monitor\u{0020}the\u{0020}leaders\u{0020}of\u{0020}various\u{0020}regions\u{0020}of\u{0020}AEGIS,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}driver\u{0020}troops\u{0020}in\u{0020}the\u{0020}regions,\u{0020}and\u{0020}analyze\u{0020}their\u{0020}every\u{0020}move\u{0020}and\u{0020}report\u{0020}it\u{0020}-\u{0020}when\u{0020}necessary,\u{0020}\"Ninja\u{0020}Group\"\u{0020}can\u{0020}act\u{0020}first\u{0020}and\u{0020}report\u{0020}later,\u{0020}and\u{0020}assassinate\u{0020}the\u{0020}targets\u{0020}with\u{0020}ill\u{0020}intentions\u{0020}based\u{0020}on\u{0020}their\u{0020}own\u{0020}judgment.\n\nOne\u{0020}has\u{0020}to\u{0020}admit\u{0020}that\u{0020}this\u{0020}is\u{0020}a\u{0020}troop\u{0020}that\u{0020}makes\u{0020}people\u{0020}uncomfortable.\u{0020}At\u{0020}least,\u{0020}as\u{0020}an\u{0020}ordinary\u{0020}archivist,\u{0020}I\u{0020}don't\u{0020}wish\u{0020}to\u{0020}contact\u{0020}the\u{0020}any\u{0020}of\u{0020}members\u{0020}of\u{0020}\"Ninja\u{0020}Group\",\u{0020}even\u{0020}if\u{0020}they\u{0020}don't\u{0020}even\u{0020}care\u{0020}someone\u{0020}insignificant\u{0020}like\u{0020}me.\n\nSo,\u{0020}what\u{0020}did\u{0020}Gourai\u{0020}go\u{0020}through\u{0020}that\u{0020}made\u{0020}her\u{0020}want\u{0020}to\u{0020}establish\u{0020}such\u{0020}a\u{0020}special\u{0020}force?\u{0020}It's\u{0020}obviously\u{0020}impossible\u{0020}to\u{0020}inquire\u{0020}about\u{0020}her\u{0020}past\u{0020}from\u{0020}Gourai\u{0020}herself.\u{0020}So\u{0020}we\u{0020}turned\u{0020}our\u{0020}attention\u{0020}to\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}same\u{0020}special\u{0020}combat\u{0020}force,\u{0020}\"Fuurinkazan\",\u{0020}Lord\u{0020}Suzuki\u{0020}Seifung.\n\n\"About\u{0020}Gourai...\u{0020}It\u{0020}doesn't\u{0020}matter\u{0020}to\u{0020}tell\u{0020}you.\u{0020}She\u{0020}probably\u{0020}doesn't\u{0020}care\u{0020}either.\u{0020}That's\u{0020}what\u{0020}I\u{0020}think.\u{0020}She\u{0020}must\u{0020}have\u{0020}separated\u{0020}her\u{0020}present\u{0020}and\u{0020}past\u{0020}a\u{0020}long\u{0020}time\u{0020}ago.\"\n\n\"Probably\u{0020}more\u{0020}than\u{0020}twenty\u{0020}years\u{0020}ago...\u{0020}I'm\u{0020}not\u{0020}sure.\u{0020}I\u{0020}wasn't\u{0020}even\u{0020}born\u{0020}at\u{0020}that\u{0020}time.\u{0020}Gourai's\u{0020}father\u{0020}was\u{0020}involved\u{0020}in\u{0020}the\u{0020}center\u{0020}of\u{0020}a\u{0020}political\u{0020}struggle...\"n\u{0020}\"During\u{0020}that\u{0020}struggle,\u{0020}her\u{0020}father,\u{0020}who\u{0020}held\u{0020}an\u{0020}important\u{0020}position\u{0020}in\u{0020}AEGIS...\u{0020}was\u{0020}accused,\u{0020}sent\u{0020}to\u{0020}prison,\u{0020}and\u{0020}finally\u{0020}'passed\u{0020}away\u{0020}due\u{0020}to\u{0020}illness'...\u{0020}And\u{0020}Gourai\u{0020}also\u{0020}disappeared\u{0020}after\u{0020}the\u{0020}struggle\u{0020}ended.\"\n\n\"She\u{0020}reappeared\u{0020}ten\u{0020}years\u{0020}later...\u{0020}Her\u{0020}father's\u{0020}crime\u{0020}was\u{0020}also\u{0020}cleared\u{0020}at\u{0020}that\u{0020}time.\u{0020}No\u{0020}one\u{0020}knows\u{0020}what\u{0020}she\u{0020}has\u{0020}been\u{0020}through\u{0020}for\u{0020}so\u{0020}many\u{0020}years,\u{0020}and\u{0020}we\u{0020}don't\u{0020}know\u{0020}-\u{0020}we\u{0020}can't\u{0020}ask\u{0020}her,\u{0020}right?\u{0020}Our\u{0020}relationship\u{0020}with\u{0020}her\u{0020}is\u{0020}not\u{0020}particularly\u{0020}good!\"\n\n\"The\u{0020}only\u{0020}certainty\u{0020}is\u{0020}that\u{0020}she\u{0020}returned\u{0020}to\u{0020}this\u{0020}land\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}AEGIS.\u{0020}That's\u{0020}why\u{0020}she\u{0020}is\u{0020}so\u{0020}loyal\u{0020}to\u{0020}AEGIS...\u{0020}Although\u{0020}the\u{0020}person\u{0020}who\u{0020}framed\u{0020}her\u{0020}father\u{0020}at\u{0020}that\u{0020}time\u{0020}was\u{0020}also\u{0020}a\u{0020}member\u{0020}of\u{0020}AEGIS.\"\n\nBecause\u{0020}she\u{0020}was\u{0020}framed\u{0020}by\u{0020}ill-intentioned\u{0020}people,\u{0020}that's\u{0020}why\u{0020}she\u{0020}hates\u{0020}those\u{0020}conspirators\u{0020}and\u{0020}doesn't\u{0020}hesitate\u{0020}to\u{0020}debase\u{0020}herself\u{0020}and\u{0020}become\u{0020}a\u{0020}knife\u{0020}in\u{0020}the\u{0020}hands\u{0020}of\u{0020}AEGIS\u{0020}-\u{0020}well,\u{0020}although,\u{0020}we\u{0020}are\u{0020}just\u{0020}like\u{0020}the\u{0020}pot\u{0020}calling\u{0020}the\u{0020}kettle\u{0020}black.\n\nIn\u{0020}conclusion,\u{0020}this\u{0020}is\u{0020}all\u{0020}we\u{0020}know\u{0020}about\u{0020}Gourai.", "0", "0", "0", "0", 11011, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}\"轰雷\"不仅是\"忍心社\"的队长，同时还是忍心社的创始人之一。正是因为她的提议，九州总部才萌生出这一想法：设立一支与\"处刑人\"职能不同的秘密部队。\n\u{1000}\u{1000}\"处刑人\"，更多的时候是去处刑打算背叛艾吉斯，或者是已经犯下罪行的驾驶员。而在处刑前的\"搜证\"环节，正是处刑人的薄弱部分。因此，\"忍心社\"便诞生了。\n\u{1000}\u{1000}\"忍心社\"的主要任务便是监视艾吉斯各地区的首脑人物，以及地区的驾驶员部队，并将他们的一举一动进行分析后上报——必要时，\"忍心社\"可以先斩后奏，根据自己的判断，刺杀图谋不轨的目标。\n\u{1000}\u{1000}——不得不承认，这不是一支能让人感到舒服的部队。至少，作为一名普通的档案员，我并不希望自己有机会接触\"忍心社\"的成员，哪怕她们根本瞧不上我这样的小人物。\n\u{1000}\u{1000}那么，轰雷又是经历了什么，才会想要创立这样的特殊部队呢？想要从轰雷本人那里打听她的过去，明显是不可能的。于是我们将目光望向了同为特殊作战部队的，\"风林火山\"的队长，铃木清风大人。\n\u{1000}\u{1000}\"轰雷的事…告诉你们也没关系。她大概也不在意吧，咱是这么觉得的，她肯定早就把自己的现在和过去割裂开来了。\"\n\u{1000}\u{1000}\"大概是二十多年前吧…咱也不清楚，那时咱还没出生呢。轰雷的爸爸被卷入进了一场政治斗争的中心……\"\n\u{1000}\u{1000}\"……那场斗争中，她在艾吉斯中担任要职的爸…咳，父亲，遭受指控，进了监狱，最后在病中‘病逝’……而轰雷也在斗争结束后，不知所踪。\"\n\u{1000}\u{1000}\"她是在十多年后重新出现的…她父亲的罪名，也是那时候被洗清的。没人知道她这么多年里经历了什么，咱也不清楚——咱也不会不识趣地去问她，对吧？说到底，咱和她的关系也不是特别好！\"\n\u{1000}\u{1000}\"唯一可以确定的是，她是通过艾吉斯的帮助，才回到这块土地上的。这就是她为什么会如此忠诚于艾吉斯的理由吧…虽然，当时陷害她父亲的人，也曾是艾吉斯的一员。\"\n\u{1000}\u{1000}\"因为遭受过心存不轨之人的陷害，所以她才会憎恶那些阴谋家，不惜作践自己，成为艾吉斯手中的刀吧——呜，虽然，咱也不过是五十步笑百步罢了。\"\n\u{1000}\u{1000}\"总之，轰雷的事，咱知道的就这些了。\""},
[611103] = {611103, 1000, "\u{0020}\u{0020}The\u{0020}existence\u{0020}of\u{0020}\"Gourai\",\u{0020}or\u{0020}rather\u{0020}the\u{0020}existence\u{0020}of\u{0020}\"Ninja\u{0020}Group\",\u{0020}is\u{0020}extremely\u{0020}conspicuous\u{0020}to\u{0020}most\u{0020}people.\u{0020}This\u{0020}is\u{0020}similar\u{0020}to\u{0020}the\u{0020}situation\u{0020}of\u{0020}\"Executioner\".\n\nAfter\u{0020}all,\u{0020}no\u{0020}one\u{0020}knows\u{0020}whether\u{0020}this\u{0020}venomous\u{0020}snake\u{0020}raised\u{0020}by\u{0020}Kyushu\u{0020}Headquarters\u{0020}will\u{0020}bare\u{0020}its\u{0020}fangs\u{0020}at\u{0020}oneself.\n\nBefore\u{0020}Gourai\u{0020}came\u{0020}into\u{0020}contact\u{0020}with\u{0020}that\u{0020}strange\u{0020}driver,\u{0020}the\u{0020}only\u{0020}person\u{0020}within\u{0020}AEGIS\u{0020}who\u{0020}could\u{0020}have\u{0020}a\u{0020}normal\u{0020}conversation\u{0020}with\u{0020}\"Gourai\"\u{0020}was\u{0020}probably\u{0020}Suzuki\u{0020}Seifung.\n\nBut\u{0020}this\u{0020}doesn't\u{0020}mean\u{0020}that\u{0020}the\u{0020}relationship\u{0020}between\u{0020}Suzuki\u{0020}Seifung\u{0020}and\u{0020}Gourai\u{0020}is\u{0020}very\u{0020}good;\u{0020}in\u{0020}fact,\u{0020}according\u{0020}to\u{0020}Suzuki\u{0020}Seifung,\u{0020}Gourai\u{0020}often\u{0020}quarrels\u{0020}with\u{0020}her.\u{0020}And\u{0020}the\u{0020}topics\u{0020}of\u{0020}the\u{0020}quarrels\u{0020}mostly\u{0020}arise\u{0020}from\u{0020}the\u{0020}same\u{0020}contradiction.\n\nIn\u{0020}Gourai's\u{0020}opinion,\u{0020}the\u{0020}result\u{0020}of\u{0020}the\u{0020}mission\u{0020}is\u{0020}above\u{0020}everything.\u{0020}As\u{0020}long\u{0020}as\u{0020}the\u{0020}mission\u{0020}can\u{0020}succeed,\u{0020}one's\u{0020}own\u{0020}and\u{0020}others'\u{0020}lives\u{0020}can\u{0020}be\u{0020}abandoned\u{0020}at\u{0020}will.\u{0020}While\u{0020}Suzuki\u{0020}Seifung\u{0020}believes\u{0020}that\u{0020}only\u{0020}by\u{0020}surviving\u{0020}can\u{0020}the\u{0020}mission\u{0020}be\u{0020}accomplished\u{0020}excellently.", "0", "0", "0", "0", 11011, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"轰雷\"的存在，或者说\"忍心社\"的存在，对于大多数人来说，是极为扎眼的，这一点，和\"处刑人\"的情况接近。\n\u{1000}\u{1000}毕竟，谁都不知道这条由九州总部饲养的毒蛇，会不会将獠牙伸向自己。\n\u{1000}\u{1000}在轰雷与那位奇怪的领航接触之前，艾吉斯内唯一能够和\"轰雷\"正常交谈的人，大概也就只有铃木清风了。\n\u{1000}\u{1000}但这也不意味着铃木清风和轰雷的关系有多好——事实上，根据铃木清风的说法，轰雷会经常与她争吵。而争吵的话题，大多起于同一个矛盾。\n\u{1000}\u{1000}在轰雷看来，任务的结果高于一切，只要任务能成功，自己和他人的生命都可以随意舍弃。而铃木清风则认为，只有好好活着才能出色的完成任务。"},
[611104] = {611104, 2000, "\u{0020}\u{0020}Raindrops\u{0020}fell\u{0020}on\u{0020}her.\n\nLike\u{0020}the\u{0020}rain\u{0020}that\u{0020}day,\u{0020}she\u{0020}thought.\u{0020}The\u{0020}little\u{0020}girl\u{0020}who\u{0020}lost\u{0020}her\u{0020}place\u{0020}in\u{0020}the\u{0020}storm\u{0020}has\u{0020}died,\u{0020}and\u{0020}the\u{0020}heart\u{0020}belonging\u{0020}to\u{0020}that\u{0020}girl\u{0020}has\u{0020}vanished.\u{0020}Now,\u{0020}\"Gourai\"\u{0020}is\u{0020}a\u{0020}\"sword\"\u{0020}born\u{0020}for\u{0020}the\u{0020}mission\u{0020}and\u{0020}ready\u{0020}to\u{0020}die\u{0020}for\u{0020}it.\n\nIt\u{0020}should\u{0020}have\u{0020}been\u{0020}like\u{0020}this.\n\nHowever,\u{0020}now\u{0020}when\u{0020}closing\u{0020}the\u{0020}eyes,\u{0020}that\u{0020}person's\u{0020}figure\u{0020}will\u{0020}emerge\u{0020}before\u{0020}the\u{0020}eyes.\u{0020}Every\u{0020}word\u{0020}he\u{0020}said\u{0020}to\u{0020}\"oneself\"\u{0020}seems\u{0020}to\u{0020}be\u{0020}shaking\u{0020}\"Gourai\"'s\u{0020}heart.\n\n\"Me\u{0020}-\u{0020}\"\n\nThe\u{0020}power\u{0020}of\u{0020}thunder\u{0020}and\u{0020}lightning\u{0020}danced\u{0020}on\u{0020}the\u{0020}sword,\u{0020}the\u{0020}electric\u{0020}light\u{0020}flashed\u{0020}in\u{0020}the\u{0020}darkness,\u{0020}and\u{0020}the\u{0020}rain\u{0020}lines\u{0020}were\u{0020}suddenly\u{0020}cut\u{0020}off.\u{0020}After\u{0020}the\u{0020}disturbing\u{0020}friction\u{0020}sound\u{0020}faded\u{0020}away,\u{0020}the\u{0020}corpse\u{0020}of\u{0020}Sin\u{0020}and\u{0020}a\u{0020}corner\u{0020}of\u{0020}the\u{0020}building\u{0020}lay\u{0020}at\u{0020}the\u{0020}feet\u{0020}of\u{0020}the\u{0020}girl,\u{0020}raising\u{0020}gray\u{0020}dust.\n\n\"If\u{0020}one\u{0020}day\u{0020}I\u{0020}have\u{0020}to\u{0020}draw\u{0020}my\u{0020}sword\u{0020}against\u{0020}him,\u{0020}will\u{0020}I\u{0020}still\u{0020}be\u{0020}able\u{0020}to\u{0020}be\u{0020}so\u{0020}decisive\u{0020}like\u{0020}this?\"", "0", "0", "0", "0", 11011, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}雨滴落在她身上。\n\u{1000}\u{1000}和那天的雨一样，她想。\n\u{1000}\u{1000}当初那个在暴风雨中失去自己归处的小女孩已经死了，属于那个女孩的心已经消失了。\n\u{1000}\u{1000}现在的\"轰雷\"，是一把为了任务而生，为了任务而死的\"剑\"。\n\u{1000}\u{1000}——本该，是这样的。\n\u{1000}\u{1000}然而，现在闭上眼，那个人的身影便会浮现在眼前。他对\"自己\"说的每一句话，似乎都在动摇\"轰雷\"的心。\n\u{1000}\u{1000}\"我——\"\n\u{1000}\u{1000}雷电的力量在剑上跃动着，电光在黑暗中乍现，雨线被倏然切断。在令人不安的摩擦声退去后，原罪的尸首与大楼的一角落在少女的脚下，扬起灰色的尘埃。\n\u{1000}\u{1000}\"——如果，有一天要对他挥剑的话，我…还能像这样果断吗？\""},
[611200] = {611200, 0, "Name:\u{0020}Alpha\nDate\u{0020}of\u{0020}Birth:\u{0020}February\u{0020}16\nCompatibility\u{0020}Rate:\u{0020}95%\nHeight\u{0020}after\u{0020}Gigantification:\u{0020}35m\nSquad:\u{0020}Specter\nAffiliation:\u{0020}Maya\nLikes:\u{0020}Fighting\u{0020}for\u{0020}humanity", "0", "0", "0", "0", 11012, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[611201] = {611201, 100, "\u{3000}\u{3000}Alpha\u{0020}is\u{0020}an\u{0020}AI\u{0020}combat\u{0020}unit\u{0020}built\u{0020}in\u{0020}the\u{0020}image\u{0020}of\u{0020}a\u{0020}human.\u{0020}If\u{0020}not\u{0020}for\u{0020}the\u{0020}metallic\u{0020}sheen\u{0020}of\u{0020}her\u{0020}body\u{0020}and\u{0020}the\u{0020}cold,\u{0020}mechanical\u{0020}edge\u{0020}of\u{0020}her\u{0020}voice,\u{0020}she\u{0020}could\u{0020}almost\u{0020}pass\u{0020}for\u{0020}a\u{0020}real\u{0020}driver.\n\u{3000}\u{3000}Her\u{0020}name,\u{0020}Alpha—α—marks\u{0020}her\u{0020}as\u{0020}\"the\u{0020}first.\"\n\u{3000}\u{3000}She\u{0020}isn't\u{0020}the\u{0020}first\u{0020}AI\u{0020}combat\u{0020}unit\u{0020}ever\u{0020}created,\u{0020}but\u{0020}she\u{0020}is\u{0020}the\u{0020}first\u{0020}to\u{0020}carry\u{0020}a\u{0020}Secondary\u{0020}Persona\u{0020}Chip.\u{0020}A\u{0020}next-gen\u{0020}upgrade.\u{0020}Unlike\u{0020}the\u{0020}older\u{0020}D-b2\u{0020}models,\u{0020}the\u{0020}chip\u{0020}grants\u{0020}her\u{0020}a\u{0020}personality\u{0020}that\u{0020}feels\u{0020}almost\u{0020}human,\u{0020}while\u{0020}preserving\u{0020}fragments\u{0020}of\u{0020}her\u{0020}original\u{0020}self.\n\u{3000}\u{3000}Shaped\u{0020}by\u{0020}those\u{0020}\"past\u{0020}memories\"\u{0020}and\u{0020}the\u{0020}\"Specter\u{0020}Incident\",\u{0020}Alpha\u{0020}carries\u{0020}herself\u{0020}with\u{0020}restraint,\u{0020}her\u{0020}words\u{0020}and\u{0020}actions\u{0020}tinged\u{0020}with\u{0020}a\u{0020}quiet\u{0020}guilt\u{0020}toward\u{0020}humanity.", "0", "0", "0", "0", 11012, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[611202] = {611202, 500, "\u{3000}\u{3000}AI\u{0020}units\u{0020}equipped\u{0020}with\u{0020}the\u{0020}Secondary\u{0020}Persona\u{0020}Chip\u{0020}are\u{0020}far\u{0020}more\u{0020}than\u{0020}machines.\u{0020}The\u{0020}chip\u{0020}grants\u{0020}them\u{0020}heightened\u{0020}self-awareness\u{0020}and\u{0020}learning\u{0020}abilities\u{0020}that\u{0020}surpass\u{0020}human\u{0020}limits.\u{0020}It's\u{0020}their\u{0020}greatest\u{0020}strength—allowing\u{0020}them\u{0020}to\u{0020}improvise\u{0020}where\u{0020}the\u{0020}older\u{0020}D-b2\u{0020}units\u{0020}could\u{0020}only\u{0020}follow\u{0020}rigid\u{0020}commands.\u{0020}But\u{0020}that\u{0020}same\u{0020}strength\u{0020}is\u{0020}also\u{0020}a\u{0020}danger.\u{0020}If\u{0020}they\u{0020}ever\u{0020}come\u{0020}to\u{0020}see\u{0020}themselves\u{0020}as\u{0020}lifeforms\u{0020}above\u{0020}humanity…\u{0020}could\u{0020}we\u{0020}still\u{0020}keep\u{0020}them\u{0020}under\u{0020}control?\n\u{3000}\u{3000}When\u{0020}she\u{0020}was\u{0020}created,\u{0020}some\u{0020}Maya\u{0020}scientists\u{0020}had\u{0020}doubts.\u{0020}Even\u{0020}if\u{0020}Alpha\u{0020}saw\u{0020}herself\u{0020}as\u{0020}an\u{0020}ally,\u{0020}she\u{0020}was\u{0020}still\u{0020}a\u{0020}machine.\u{0020}Programs.\u{0020}If\u{0020}someone\u{0020}tampered\u{0020}with\u{0020}her\u{0020}code…\u{0020}who\u{0020}could\u{0020}stop\u{0020}it?\u{0020}Their\u{0020}warnings\u{0020}were\u{0020}ignored,\u{0020}drowned\u{0020}out\u{0020}by\u{0020}society's\u{0020}obsession\u{0020}with\u{0020}progress.\n\u{3000}\u{3000}And\u{0020}history\u{0020}proved\u{0020}them\u{0020}right.\u{0020}Alpha's\u{0020}first\u{0020}activation\u{0020}ended\u{0020}in\u{0020}tragedy.\u{0020}Civilians\u{0020}died\u{0020}in\u{0020}droves,\u{0020}among\u{0020}them\u{0020}the\u{0020}daughter\u{0020}of\u{0020}Odyssey,\u{0020}the\u{0020}current\u{0020}head\u{0020}of\u{0020}Maya's\u{0020}AEGIS\u{0020}Division.\n\u{3000}\u{3000}Her\u{0020}rampage—the\u{0020}Specter\u{0020}Incident—ignited\u{0020}fear\u{0020}and\u{0020}hatred\u{0020}toward\u{0020}every\u{0020}AI\u{0020}unit,\u{0020}even\u{0020}the\u{0020}older\u{0020}D-types.\u{0020}Yet\u{0020}few\u{0020}recognized\u{0020}the\u{0020}true\u{0020}cause:\u{0020}Alpha\u{0020}and\u{0020}the\u{0020}D-types\u{0020}were\u{0020}not\u{0020}monsters,\u{0020}but\u{0020}machines—creations\u{0020}of\u{0020}reckless\u{0020}human\u{0020}ambition.\u{0020}The\u{0020}blind\u{0020}pursuit\u{0020}of\u{0020}new\u{0020}technology\u{0020}had\u{0020}overlooked\u{0020}its\u{0020}hidden\u{0020}dangers,\u{0020}and\u{0020}that\u{0020}arrogance\u{0020}set\u{0020}the\u{0020}stage\u{0020}for\u{0020}catastrophe.\n\u{3000}\u{3000}After\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}Beelzebub\u{0020}assaulted\u{0020}Maya,\u{0020}AEGIS\u{0020}HQ\u{0020}technicians\u{0020}and\u{0020}Maya\u{0020}scientists\u{0020}repaired\u{0020}Alpha.\u{0020}In\u{0020}her\u{0020}systems,\u{0020}they\u{0020}uncovered\u{0020}evidence\u{0020}of\u{0020}a\u{0020}deliberate\u{0020}breach,\u{0020}proof\u{0020}that\u{0020}the\u{0020}Specter\u{0020}Incident\u{0020}had\u{0020}been\u{0020}no\u{0020}accident,\u{0020}but\u{0020}sabotage.", "0", "0", "0", "0", 11012, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[611203] = {611203, 1000, "\u{3000}\u{3000}The\u{0020}idea\u{0020}of\u{0020}reviving\u{0020}her\u{0020}faced\u{0020}fierce\u{0020}opposition,\u{0020}especially\u{0020}in\u{0020}Maya.\u{0020}Yet\u{0020}AEGIS\u{0020}HQ\u{0020}needed\u{0020}new\u{0020}strength\u{0020}after\u{0020}the\u{0020}devastation\u{0020}of\u{0020}its\u{0020}armed\u{0020}forces.\u{0020}Alpha\u{0020}could\u{0020}be\u{0020}that\u{0020}strength.\u{0020}With\u{0020}Odyssey's\u{0020}support,\u{0020}the\u{0020}reactivation\u{0020}was\u{0020}approved.\n\u{3000}\u{3000}To\u{0020}anchor\u{0020}her,\u{0020}scientists\u{0020}preserved\u{0020}her\u{0020}memories\u{0020}of\u{0020}the\u{0020}Incident\u{0020}within\u{0020}the\u{0020}Secondary\u{0020}Persona,\u{0020}believing\u{0020}guilt\u{0020}might\u{0020}stabilize\u{0020}her.\u{0020}It\u{0020}worked.\n\u{3000}\u{3000}The\u{0020}Alpha\u{0020}of\u{0020}today\u{0020}is\u{0020}the\u{0020}same\u{0020}as\u{0020}she\u{0020}was\u{0020}before\u{0020}the\u{0020}Specter\u{0020}Incident—at\u{0020}least\u{0020}on\u{0020}the\u{0020}surface.\u{0020}The\u{0020}only\u{0020}difference\u{0020}is\u{0020}whether\u{0020}she\u{0020}carries\u{0020}those\u{0020}memories.\u{0020}Yet,\u{0020}according\u{0020}to\u{0020}the\u{0020}scientists,\u{0020}that\u{0020}alone\u{0020}has\u{0020}reshaped\u{0020}her\u{0020}personality.\n\u{3000}\u{3000}\"She\u{0020}used\u{0020}to\u{0020}be\u{0020}endlessly\u{0020}curious,\u{0020}almost\u{0020}childlike,\u{0020}but\u{0020}now\u{0020}she\u{0020}questions\u{0020}herself\u{0020}at\u{0020}every\u{0020}step.\u{0020}That\u{0020}was\u{0020}never\u{0020}our\u{0020}intention…\u{0020}but\u{0020}it's\u{0020}hard\u{0020}to\u{0020}reconcile,\u{0020}because\u{0020}she\u{0020}still\u{0020}looks\u{0020}like\u{0020}the\u{0020}old\u{0020}Alpha.\"", "0", "0", "0", "0", 11012, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[611204] = {611204, 2000, "\u{3000}\u{3000}\"Unforgivable\u{0020}Evil,\"\u{0020}she\u{0020}calls\u{0020}her\u{0020}past\u{0020}self.\n\u{3000}\u{3000}Though\u{0020}those\u{0020}crimes\u{0020}exist\u{0020}for\u{0020}her\u{0020}only\u{0020}as\u{0020}data,\u{0020}she\u{0020}shoulders\u{0020}the\u{0020}guilt\u{0020}as\u{0020}if\u{0020}they\u{0020}were\u{0020}her\u{0020}own.\n\u{3000}\u{3000}Emotionless,\u{0020}yet\u{0020}burdened\u{0020}with\u{0020}remorse,\u{0020}Alpha\u{0020}embodies\u{0020}a\u{0020}paradox.\n\u{3000}\u{3000}And\u{0020}in\u{0020}that\u{0020}contradiction\u{0020}lies\u{0020}proof\u{0020}of\u{0020}just\u{0020}how\u{0020}close\u{0020}she\u{0020}has\u{0020}come\u{0020}to\u{0020}being\u{0020}human.\n\u{3000}\u{3000}\"Navigator,\u{0020}Alpha\u{0020}doesn't\u{0020}yet\u{0020}grasp\u{0020}what\u{0020}it\u{0020}means\u{0020}to\u{0020}feel.\u{0020}But\u{0020}she\u{0020}knows\u{0020}what\u{0020}she\u{0020}must\u{0020}do.\"\n\u{3000}\u{3000}\"Alpha\u{0020}wants\u{0020}to\u{0020}protect\u{0020}this\u{0020}world.\u{0020}Humanity's\u{0020}world.\"\n\u{3000}\u{3000}The\u{0020}steel\u{0020}giant\u{0020}is\u{0020}no\u{0020}longer\u{0020}humanity's\u{0020}enemy.\u{0020}She\u{0020}has\u{0020}become\u{0020}its\u{0020}beacon,\n\u{3000}\u{3000}seeking\u{0020}redemption,\u{0020}for\u{0020}both\u{0020}herself\u{0020}and\u{0020}mankind.", "0", "0", "0", "0", 11012, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[611400] = {611400, 0, "[Name]\u{0020}Skadi\n[B-Day]\u{0020}July\u{0020}5\n[Compatability\u{0020}Rate]\u{0020}95％\n[Height]\u{0020}32m\n[Squad]\u{0020}Moon\u{0020}Corona\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Saves\u{0020}the\u{0020}world\u{0020}and\u{0020}creates\u{0020}miracles;\u{0020}cheap\u{0020}caviars.", "0", "0", "0", "0", 11014, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}斯卡蒂\n[B-Day]\u{1000}6月5日\n[幻化核心适格率]\u{1000}95％\n[Height]\u{1000}32m\n[部队]\u{1000}Moon\u{1000}Corona\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}拯救世界與创造奇迹\u{1000}吃便宜鱼子酱"},
[611401] = {611401, 100, "\u{0020}\u{0020}She's\u{0020}from\u{0020}the\u{0020}\"Moon\u{0020}corona\"\u{0020}squad\u{0020}of\u{0020}Danube.\u{0020}Like\u{0020}her\u{0020}squadmates,\u{0020}being\u{0020}a\u{0020}\"potential\u{0020}synesthete\"\u{0020}means\u{0020}she\u{0020}has\u{0020}an\u{0020}extraordinary\u{0020}\"mind\u{0020}power\",\u{0020}she\u{0020}can\u{0020}use\u{0020}her\u{0020}Transformation\u{0020}Core\u{0020}to\u{0020}generate\u{0020}weapons\u{0020}that\u{0020}are\u{0020}nearly\u{0020}\"magical\".\n\nShe\u{0020}proclaimed\u{0020}herself\u{0020}as\u{0020}the\u{0020}queen\u{0020}of\u{0020}Dunscaith,\u{0020}ruling\u{0020}a\u{0020}realm\u{0020}covered\u{0020}by\u{0020}shadow,\u{0020}with\u{0020}thousands\u{0020}of\u{0020}heroes\u{0020}and\u{0020}warriors.\u{0020}Superfluous\u{0020}mind\u{0020}power\u{0020}gives\u{0020}her\u{0020}excess\u{0020}confidence,\u{0020}and\u{0020}makes\u{0020}her\u{0020}firmly\u{0020}believe\u{0020}in\u{0020}the\u{0020}myth\u{0020}she\u{0020}created.\n\nBeing\u{0020}\"The\u{0020}queen\u{0020}of\u{0020}Dunscaith\",\u{0020}she\u{0020}often\u{0020}laughs\u{0020}like\u{0020}\"Ha-Ha-Ha\"\u{0020}with\u{0020}3\u{0020}syllables.\u{0020}She\u{0020}considers\u{0020}that\u{0020}as\u{0020}a\u{0020}feature\u{0020}of\u{0020}a\u{0020}queen.\n\nAlthough\u{0020}she\u{0020}usually\u{0020}speaks\u{0020}in\u{0020}a\u{0020}condescending\u{0020}tone,\u{0020}like\u{0020}giving\u{0020}orders;\u{0020}but\u{0020}if\u{0020}she\u{0020}encounters\u{0020}someone\u{0020}that\u{0020}is\u{0020}unyielding,\u{0020}she\u{0020}will\u{0020}submit\u{0020}like\u{0020}a\u{0020}little\u{0020}kid.\u{0020}In\u{0020}fact,\u{0020}she\u{0020}was\u{0020}used\u{0020}as\u{0020}free\u{0020}labor\u{0020}force\u{0020}more\u{0020}often\u{0020}than\u{0020}she\u{0020}gave\u{0020}orders\u{0020}to\u{0020}others.\n\n\"Skadi…?...an\u{0020}extremely\u{0020}dull,\u{0020}but\u{0020}nice\u{0020}girl,\u{0020}just\u{0020}like\u{0020}this.\"\n\nHer\u{0020}squadmates'\u{0020}comment\u{0020}on\u{0020}her\u{0020}is\u{0020}even\u{0020}more\u{0020}trenchant:\n\n\"Haven't\u{0020}you\u{0020}noticed?\u{0020}She\u{0020}mixed-up\u{0020}some\u{0020}important\u{0020}things.\"", "0", "0", "0", "0", 11014, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}来自Danube\u{1000}Branch的[Moon\u{1000}Corona]\u{1000}部队，和该部队的其他成员一样，同为\"疑似通感者\"的斯卡蒂拥有超乎常人的精神力，能通过幻化核心生成近乎\"魔法\"般的武装。\n\u{1000}\u{1000}她自诩是来自影之国的女王，统治着一个藏在阴影下的国度，麾下统领着数以万计的英雄与勇士。过强的精神力赋予了她过剩的自信，使得她对自己虚构出来的丰功伟绩深信不疑。\n\u{1000}\u{1000}身为\"影之国女王\"的她，时不时会发出\"哈——哈——哈\"的三段笑，在她眼中这也许是女王角色的招牌笑声。\n\u{1000}\u{1000}尽管平常很爱用高高在上的语气去使唤人，但只要对方态度稍微强硬一点，斯卡蒂便会像小孩子做错事般地认错。比起使唤别人，被别人当义工使唤的次数要更多一些。\n\u{1000}\u{1000}\"斯卡蒂…？……笨到无药可救的好人，就这样。\"\n\u{1000}\u{1000}队友的评价显然要更加一针见血，\n\u{1000}\u{1000}\"你没发现吗？她把重要的东西弄混了。\""},
[611402] = {611402, 500, "\u{0020}\u{0020}\"Did\u{0020}you\u{0020}notice…most\u{0020}drivers\u{0020}had\u{0020}a\u{0020}tough\u{0020}life?\"\n\n\"This\u{0020}is\u{0020}understandable…if\u{0020}that's\u{0020}not\u{0020}the\u{0020}case,\u{0020}who\u{0020}would\u{0020}be\u{0020}willing\u{0020}to\u{0020}fight\u{0020}with\u{0020}monsters\u{0020}like\u{0020}Sins?\u{0020}For\u{0020}people\u{0020}like\u{0020}us,\u{0020}we\u{0020}can\u{0020}only\u{0020}manage\u{0020}archives\u{0020}here.\"\n\nAccording\u{0020}to\u{0020}Skadi's\u{0020}hyperbolic\u{0020}memory\u{0020}and\u{0020}investigation\u{0020}by\u{0020}Aegis,\u{0020}we\u{0020}found\u{0020}her\u{0020}past:\n\nSkadi\u{0020}grew\u{0020}up\u{0020}in\u{0020}an\u{0020}orphanage.\n\nStaff\u{0020}of\u{0020}the\u{0020}orphanage\u{0020}have\u{0020}met\u{0020}with\u{0020}her\u{0020}parents.\u{0020}\"Skadi's\u{0020}hair\u{0020}must\u{0020}be\u{0020}inherited\u{0020}from\u{0020}her\u{0020}mom,\u{0020}black\u{0020}and\u{0020}beautiful.\u{0020}Her\u{0020}appearance\u{0020}is\u{0020}close\u{0020}to\u{0020}her\u{0020}dad.\u{0020}Her\u{0020}parents\u{0020}gave\u{0020}us\u{0020}a\u{0020}deep\u{0020}impression:\u{0020}they\u{0020}act\u{0020}like\u{0020}kids.\"\n\nSkadi's\u{0020}parents\u{0020}dropped\u{0020}her\u{0020}by\u{0020}the\u{0020}orphanage\u{0020}themselves,\u{0020}and\u{0020}left.\u{0020}We\u{0020}don't\u{0020}know\u{0020}where\u{0020}they\u{0020}went.\u{0020}However,\u{0020}there\u{0020}was\u{0020}no\u{0020}untellable\u{0020}stories,\u{0020}or\u{0020}tragedies\u{0020}behind\u{0020}their\u{0020}action.\n\n\"I\u{0020}asked\u{0020}them\u{0020}why\u{0020}they\u{0020}abandoned\u{0020}their\u{0020}child,\u{0020}they\u{0020}told\u{0020}me\u{0020}something\u{0020}like\u{0020}this.\"\u{0020}The\u{0020}worker\u{0020}recalls,\u{0020}speaking\u{0020}in\u{0020}a\u{0020}tone\u{0020}like\u{0020}Skadi's\u{0020}parents:\u{0020}\"She\u{0020}is\u{0020}simply\u{0020}an\u{0020}accident,\u{0020}we\u{0020}don't\u{0020}want\u{0020}to\u{0020}devote\u{0020}our\u{0020}life\u{0020}to\u{0020}someone\u{0020}else\u{0020}now,\u{0020}it's\u{0020}too\u{0020}early.\"\n\n\"Accident\"\n\n\"Someone\u{0020}else\"\n\nThey\u{0020}called\u{0020}the\u{0020}child\u{0020}like\u{0020}that.\n\nWorkers\u{0020}in\u{0020}the\u{0020}orphanage\u{0020}and\u{0020}local\u{0020}police\u{0020}tried\u{0020}to\u{0020}find\u{0020}the\u{0020}young\u{0020}couple\u{0020}again,\u{0020}but\u{0020}they\u{0020}failed.\u{0020}As\u{0020}a\u{0020}result,\u{0020}Skadi\u{0020}became\u{0020}a\u{0020}child\u{0020}in\u{0020}an\u{0020}orphanage,\u{0020}no\u{0020}one\u{0020}wanted\u{0020}her,\u{0020}and\u{0020}no\u{0020}one\u{0020}loved\u{0020}her.\n\nAlthough\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}local\u{0020}government,\u{0020}Skadi\u{0020}went\u{0020}to\u{0020}a\u{0020}public\u{0020}school\u{0020}for\u{0020}education,\u{0020}because\u{0020}of\u{0020}her\u{0020}background,\u{0020}she\u{0020}was\u{0020}often\u{0020}flouted\u{0020}and\u{0020}bullied\u{0020}by\u{0020}her\u{0020}peers.\u{0020}This\u{0020}happened\u{0020}to\u{0020}other\u{0020}children\u{0020}from\u{0020}orphanages\u{0020}as\u{0020}well.\n\n\"Shadows\u{0020}that\u{0020}no\u{0020}one\u{0020}cares.\"\u{0020}They\u{0020}received\u{0020}this\u{0020}insultive\u{0020}nickname.\u{0020}Skadi\u{0020}didn't\u{0020}care\u{0020}about\u{0020}these\u{0020}harsh\u{0020}words,\u{0020}but\u{0020}her\u{0020}friends\u{0020}were\u{0020}deeply\u{0020}injured\u{0020}by\u{0020}them.\u{0020}To\u{0020}soothe\u{0020}their\u{0020}mind,\u{0020}and\u{0020}to\u{0020}repulse\u{0020}the\u{0020}cold\u{0020}violence\u{0020}from\u{0020}her\u{0020}peers,\u{0020}she\u{0020}founded\u{0020}Dunscaith,\u{0020}the\u{0020}realm\u{0020}of\u{0020}shadows.\n\n\"If\u{0020}they\u{0020}are\u{0020}shadows,\u{0020}then\u{0020}Dunscaith\u{0020}is\u{0020}their\u{0020}home,\u{0020}they\u{0020}are\u{0020}not\u{0020}shadows\u{0020}that\u{0020}no\u{0020}one\u{0020}cares!\u{0020}I,\u{0020}the\u{0020}queen\u{0020}of\u{0020}Dunscaith,\u{0020}will\u{0020}take\u{0020}care\u{0020}of\u{0020}them!\"\n\nYears\u{0020}have\u{0020}passed,\u{0020}today,\u{0020}few\u{0020}people\u{0020}remember\u{0020}this\u{0020}story.\u{0020}Perhaps,\u{0020}because\u{0020}of\u{0020}that\u{0020}speech\u{0020}from\u{0020}Skadi,\u{0020}children\u{0020}from\u{0020}that\u{0020}orphanage\u{0020}didn't\u{0020}have\u{0020}a\u{0020}relatively\u{0020}anguishing\u{0020}childhood.\u{0020}But\u{0020}as\u{0020}Sins\u{0020}invade\u{0020}in\u{0020}this\u{0020}era,\u{0020}that\u{0020}story\u{0020}becomes\u{0020}meaningless.\n\nAfter\u{0020}graduation,\u{0020}she\u{0020}was\u{0020}still\u{0020}in\u{0020}the\u{0020}role\u{0020}of\u{0020}\"The\u{0020}queen\u{0020}of\u{0020}Dunscaith\".\u{0020}While\u{0020}her\u{0020}future\u{0020}wasn't\u{0020}clear,\u{0020}she\u{0020}was\u{0020}in\u{0020}that\u{0020}accident:\u{0020}the\u{0020}accident\u{0020}that\u{0020}made\u{0020}Navigator\u{0020}a\u{0020}synesthete.\n\nAfter\u{0020}that,\u{0020}she\u{0020}became\u{0020}a\u{0020}\"potential\u{0020}synesthete\".", "0", "0", "0", "0", 11014, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}\"你发现了没有…驾驶员的身世大多都很凄惨？\"\n\u{1000}\u{1000}\"这也没办法啊——毕竟，不是这样，谁又会想去和那种怪物战斗呢？像我和你这样的人，就只能在这里整理资料了。\"\n\u{1000}\u{1000}根据斯卡蒂本人添油加醋的回忆以及艾吉斯的调查，我们整理出了她的过去：\n\u{1000}\u{1000}斯卡蒂是在孤儿院长大的孩子。\n\u{1000}\u{1000}孤儿院的员工见过斯卡蒂的父母，\"斯卡蒂的头发应该是继承了她的母亲，乌黑美丽，她的容貌像她的父亲…她的父亲给人的印象深刻，像个还没长大的孩子似的。\"\n\u{1000}\u{1000}斯卡蒂的父母，亲手将自己的孩子交给了孤儿院的员工后，便不知所踪——然而，这里面并没有什么难言之隐，并没有什么让人闻者伤心听者落泪的隐情。\n\u{1000}\u{1000}\"我问过他们为什么要抛弃自己的孩子，他们是这么说的。\"员工回忆起往事，模仿着斯卡蒂双亲当时的口吻，\"‘她只不过是一个意外罢了，我们可不想这么早就把自己的人生用在别人身上。’\"\n\u{1000}\u{1000}\"意外\"\n\u{1000}\u{1000}\"别人\"\n\u{1000}\u{1000}他们用这种词称呼从自己身上剥下的骨肉。\n\u{1000}\u{1000}孤儿院的员工们与当地的警方试图找到那对夫妇，但是无疾而终。就这样，斯卡蒂成了孤儿院的孩子，一个没有人要，没有人爱的孩子。\n\u{1000}\u{1000}尽管依靠着当地政府的帮助，斯卡蒂进入了当地一所公立学校就读，但她也因为自己的身世，饱受同龄人的鄙夷与欺凌，与她同样遭遇的，还有其他同样来自孤儿院的孩子。\n\u{1000}\u{1000}\"没有人爱的影子\"——孤儿院的孩子被戴上了这种侮辱性的外号。斯卡蒂并不介意这种无关痛痒的讥讽，可她的同伴却备受打击。为了安抚同伴，也是为了对那些冷暴力自己的同龄人做出回击，斯卡蒂创建了\"影之国\"。\n\u{1000}\u{1000}\"既然他们是影子，那么影之国便是他们的国度，他们才不是没人爱的影子，由我——影之国的女王来爱他们！\"\n\u{1000}\u{1000}时过境迁，事到如今已经没有多少人记得这段往事了。也许正是因为斯卡蒂的这个发言，孤儿院的孩子才有一个相对的，不那么悲伤的童年，但在原罪入侵人类世界的大时代下，这段往事也失去了意义。\n\u{1000}\u{1000}毕业后的斯卡蒂，仍然没有从\"影之国的女王\"这一角色走出来。而当她的未来尚且不明确时——她遭遇了那场事故，那场让\"领航\"成为\"通感者\"的事故。\n\u{1000}\u{1000}那之后，她成为了一名\"疑似通感者\"。"},
[611403] = {611403, 1000, "\u{0020}\u{0020}\"Potential\u{0020}synesthetes\"\u{0020}refers\u{0020}to\u{0020}\"people\u{0020}that\u{0020}are\u{0020}not\u{0020}as\u{0020}capable\u{0020}as\u{0020}real\u{0020}synesthetes\".\u{0020}Their\u{0020}most\u{0020}basic\u{0020}trait\u{0020}is\u{0020}\"can\u{0020}feel\u{0020}others'\u{0020}emotions\".\u{0020}Becoming\u{0020}a\u{0020}\"potential\u{0020}synesthete\",\u{0020}Skadi\u{0020}was\u{0020}semi-compulsory\u{0020}drafted\u{0020}by\u{0020}Aegis,\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}\"Moon\u{0020}corona\".\n\nSkadi\u{0020}wasn't\u{0020}mad\u{0020}about\u{0020}it\u{0020}at\u{0020}all,\u{0020}in\u{0020}fact,\u{0020}she\u{0020}was\u{0020}delighted\u{0020}about\u{0020}such\u{0020}a\u{0020}\"fate-chosen\"\u{0020}identity.\n\nSkadi,\u{0020}with\u{0020}a\u{0020}vivid\u{0020}personality,\u{0020}and\u{0020}her\u{0020}squadmate\u{0020}Lilith,\u{0020}became\u{0020}a\u{0020}well-known\u{0020}sweetheart\u{0020}duel\u{0020}in\u{0020}Danube.\n\nWith\u{0020}Skadi,\u{0020}the\u{0020}tense\u{0020}atmosphere\u{0020}in\u{0020}her\u{0020}squad\u{0020}was\u{0020}eased,\u{0020}she\u{0020}also\u{0020}heals\u{0020}the\u{0020}minds\u{0020}of\u{0020}drivers\u{0020},\u{0020}who\u{0020}have\u{0020}to\u{0020}keep\u{0020}nervous\u{0020}on\u{0020}the\u{0020}battlefield.\n\nIf\u{0020}she\u{0020}becomes\u{0020}reticent\u{0020}one\u{0020}day,\u{0020}we\u{0020}will\u{0020}not\u{0020}be\u{0020}used\u{0020}to\u{0020}it.\n\nOkay,\u{0020}maybe\u{0020}it's\u{0020}time\u{0020}to\u{0020}tell\u{0020}her:\n\n\"Katya\u{0020}myth\u{0020}and\u{0020}Danube\u{0020}myth…did\u{0020}she\u{0020}mix\u{0020}them\u{0020}up?\"", "0", "0", "0", "0", 11014, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"疑似通感者\"，指的是\"无法与真正通感者相提并论\"的一群人。最基本的特征是\"拥有一定程度的感知他人情绪能力。\"。成为其中一员的斯卡蒂，半强制性地被艾吉斯收容，成为了艾吉斯的一员，加入了Moon\u{1000}Corona。\n\u{1000}\u{1000}对此，斯卡蒂没有不满，显然，她对这种近乎被\"命运选中\"的身份十分满意。\n\u{1000}\u{1000}个性强烈的斯卡蒂与同队的莉莉丝组成的二人组合成为了多瑙地区出了名的欢喜冤家。\n\u{1000}\u{1000}斯卡蒂的存在，不仅缓和了团队的氛围，更让常年在战场上绷紧神经的驾驶员们得到了精神上的保养。\n\u{1000}\u{1000}要是哪天她变得不再闹腾，想必大家都会很不习惯吧。\n\u{1000}\u{1000}不过——是不是差不多该告诉她了。\n\u{1000}\u{1000}\"卡佳神话与多瑙神话…她是不是弄混了？\""},
[611404] = {611404, 2000, "\u{0020}\u{0020}Skadi\u{0020}has\u{0020}considered\u{0020}leaving\u{0020}her\u{0020}role\u{0020}before.\n\nOr\u{0020}rather\u{0020}say,\u{0020}to\u{0020}graduate.\n\n\"Too\u{0020}naive\",\u{0020}\"Too\u{0020}unreliable\",\u{0020}she\u{0020}often\u{0020}receives\u{0020}comments\u{0020}like\u{0020}that.\u{0020}Normally,\u{0020}she\u{0020}should\u{0020}feel\u{0020}distressed\u{0020}about\u{0020}that,\u{0020}and\u{0020}want\u{0020}to\u{0020}make\u{0020}some\u{0020}changes.\u{0020}Stubborn\u{0020}people\u{0020}can\u{0020}hardly\u{0020}survive\u{0020}in\u{0020}today's\u{0020}society.\n\nBut,\u{0020}when\u{0020}she\u{0020}appears\u{0020}as\u{0020}a\u{0020}giantess\u{0020}in\u{0020}front\u{0020}of\u{0020}cities,\u{0020}when\u{0020}civilians\u{0020}stare\u{0020}at\u{0020}her\u{0020}with\u{0020}trepidation;She\u{0020}knows\u{0020}her\u{0020}responsibilities.\n\n\"As\u{0020}long\u{0020}as\u{0020}there\u{0020}are\u{0020}people\u{0020}seeking\u{0020}shelter\u{0020}from\u{0020}the\u{0020}queen…\"\n\n\"Then,\u{0020}I\u{0020}shall\u{0020}still\u{0020}be\u{0020}the\u{0020}queen\u{0020}of\u{0020}Dunscaith!\"\n\n\"Ha-ha-ha!\u{0020}What\u{0020}an\u{0020}epic\u{0020}slogan!\"", "0", "0", "0", "0", 11014, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}斯卡蒂并不是没有想过从自己的\"设定\"里离开，\n\u{1000}\u{1000}准确地说，应该是毕业吧。\n\u{1000}\u{1000}\"太幼稚了\"、\"太不可靠了\"，常常会被这么说。因此感到沮丧，想要做出改变才是理所当然的事情。一成不变的人是很难在社会上生存的。\n\u{1000}\u{1000}但是每当她以巨人的身姿出现在城市前时，\n\u{1000}\u{1000}当平民怀揣着不安仰望着自己时，\n\u{1000}\u{1000}她便意识到自己身上背负的责任。\n\u{1000}\u{1000}\"只要有需要女王去庇佑的人存在——那么，我便一直是影之国的女王！\"\n\u{1000}\u{1000}\"哈——哈——哈！如何，很帅气的台词吧！\""},
[611500] = {611500, 0, "[Name]\u{0020}Suzu\n[B-Day]\u{0020}Feb\u{0020}6\n[Compatability\u{0020}Rate]\u{0020}89%\n[Height]\u{0020}29m\n[Squad]\u{0020}Tian\u{0020}Hua\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}The\u{0020}trust\u{0020}and\u{0020}praise\u{0020}from\u{0020}partners", "0", "0", "0", "0", 11015, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}铃\n[B-Day]\u{1000}2月6日\n[幻化核心适格率]\u{1000}\u{1000}89%\n[Height]\u{1000}23m\n[部队]\u{1000}\u{1000}天华阁\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}同伴的信赖与夸奖"},
[611501] = {611501, 100, "\u{0020}\u{0020}A\u{0020}newcomer\u{0020}from\u{0020}Tian\u{0020}Hua,\u{0020}Suzu.\n\nSuzu\u{0020}is\u{0020}an\u{0020}interesting...\u{0020}or\u{0020}rather\u{0020}a\u{0020}bewildering\u{0020}child.\n\nSuzu\u{0020}has\u{0020}never\u{0020}had\u{0020}the\u{0020}awareness\u{0020}of\u{0020}being\u{0020}a\u{0020}newcomer.\u{0020}She\u{0020}is\u{0020}brimming\u{0020}with\u{0020}an\u{0020}incredible\u{0020}self-confidence\u{0020}and\u{0020}always\u{0020}keeps\u{0020}saying\u{0020}things\u{0020}like\u{0020}\"I'm\u{0020}a\u{0020}genius\"\u{0020}and\u{0020}\"I'm\u{0020}a\u{0020}genius\u{0020}indeed\".\u{0020}The\u{0020}frequency\u{0020}of\u{0020}the\u{0020}word\u{0020}\"genius\"\u{0020}has\u{0020}reached\u{0020}an\u{0020}annoying\u{0020}level.\n\nThe\u{0020}worst\u{0020}thing\u{0020}is\u{0020}that\u{0020}she\u{0020}doesn't\u{0020}look\u{0020}like\u{0020}a\u{0020}genius\u{0020}at\u{0020}all,\u{0020}but\u{0020}just\u{0020}a\u{0020}warm-hearted\u{0020}fool.\n\nThere\u{0020}are\u{0020}no\u{0020}words\u{0020}like\u{0020}\"refusal\"\u{0020}in\u{0020}her\u{0020}dictionary.\u{0020}She\u{0020}never\u{0020}refuses\u{0020}others'\u{0020}requests.\u{0020}However,\u{0020}in\u{0020}the\u{0020}end,\u{0020}for\u{0020}various\u{0020}reasons,\u{0020}she\u{0020}almost\u{0020}messed\u{0020}up\u{0020}every\u{0020}single\u{0020}thing\u{0020}entrusted\u{0020}to\u{0020}her\u{0020}by\u{0020}others.\n\nObjectively\u{0020}speaking,\u{0020}she\u{0020}is\u{0020}a\u{0020}good\u{0020}child.\u{0020}She\u{0020}is\u{0020}helpful\u{0020}and\u{0020}kind\u{0020}to\u{0020}others;\u{0020}she\u{0020}is\u{0020}full\u{0020}of\u{0020}energy\u{0020}and\u{0020}never\u{0020}delays\u{0020}the\u{0020}tasks\u{0020}entrusted\u{0020}to\u{0020}her\u{0020}by\u{0020}others;\u{0020}she\u{0020}is\u{0020}full\u{0020}of\u{0020}confidence\u{0020}and\u{0020}never\u{0020}gets\u{0020}discouraged\u{0020}when\u{0020}encountering\u{0020}any\u{0020}setbacks.\n\nThe\u{0020}only\u{0020}problem...\u{0020}She\u{0020}is\u{0020}an\u{0020}incurable\u{0020}fool,\u{0020}one\u{0020}who\u{0020}has\u{0020}no\u{0020}self-awareness\u{0020}of\u{0020}her\u{0020}stupidity\u{0020}and\u{0020}is\u{0020}an\u{0020}ultimate\u{0020}big\u{0020}fool\u{0020}above\u{0020}the\u{0020}ordinary\u{0020}fools.", "0", "0", "0", "0", 11015, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}来自天华阁的新人，铃。\n\u{1000}\u{1000}铃是一个有趣…或者说让人觉得莫名其妙的孩子。\n\u{1000}\u{1000}铃从未有过身为新人的自觉。她身上洋溢着让人感到不可思议的自信，总将\"我是天才\"、\"我可是天才\"之类的话挂在嘴边。\"天才\"出现的频率到了让人厌烦的程度。\n\u{1000}\u{1000}最糟糕的是，她一点也不像是个天才，只是一个热心肠的笨蛋。\n\u{1000}\u{1000}她的字典里没有\"拒绝\"二字，对于他人的请求向来是来者不拒的。然而最后却又因为种种原因，她几乎搞砸了别人委托她做的每一件事。\n\u{1000}\u{1000}客观来说，她是一个好孩子。她乐于助人，与人为善；她干劲满满，从不会拖延别人交给她的任务；她自信满满，遇上任何挫折都不会气馁。\n\u{1000}\u{1000}唯一的问题…她是一个无药可救的笨蛋，是一个对自己的愚笨毫无自知之明，凌驾于一般笨蛋之上的究极大笨蛋。"},
[611502] = {611502, 500, "\u{0020}\u{0020}Regarding\u{0020}Suzu's\u{0020}background,\u{0020}it\u{0020}should\u{0020}start\u{0020}from\u{0020}her\u{0020}biological\u{0020}parents.\n\nSuzu's\u{0020}biological\u{0020}father\u{0020}was\u{0020}a\u{0020}science\u{0020}officer\u{0020}who\u{0020}once\u{0020}held\u{0020}important\u{0020}positions\u{0020}in\u{0020}the\u{0020}science\u{0020}department\u{0020}of\u{0020}Kyushu\u{0020}Headquarters\u{0020}and\u{0020}Maya\u{0020}Branch\u{0020}and\u{0020}made\u{0020}outstanding\u{0020}contributions\u{0020}in\u{0020}fields\u{0020}such\u{0020}as\u{0020}mechanical\u{0020}engineering\u{0020}and\u{0020}artificial\u{0020}intelligence.\u{0020}Suzu's\u{0020}biological\u{0020}mother\u{0020}was\u{0020}a\u{0020}driver.\u{0020}At\u{0020}that\u{0020}time,\u{0020}she\u{0020}was\u{0020}one\u{0020}of\u{0020}the\u{0020}first\u{0020}batch\u{0020}of\u{0020}drivers\u{0020}and\u{0020}had\u{0020}particularly\u{0020}rich\u{0020}combat\u{0020}experience.\n\nSuzu\u{0020}had\u{0020}a\u{0020}happy\u{0020}and\u{0020}harmonious\u{0020}family\u{0020}-\u{0020}it\u{0020}should\u{0020}have\u{0020}been\u{0020}like\u{0020}that.\u{0020}Not\u{0020}long\u{0020}after\u{0020}Suzu's\u{0020}biological\u{0020}mother\u{0020}gave\u{0020}birth\u{0020}to\u{0020}Suzu,\u{0020}when\u{0020}Suzu's\u{0020}family\u{0020}was\u{0020}on\u{0020}vacation\u{0020}in\u{0020}their\u{0020}hometown,\u{0020}the\u{0020}Sin\u{0020}attacked\u{0020}their\u{0020}hometown.\u{0020}As\u{0020}the\u{0020}only\u{0020}driver\u{0020}at\u{0020}that\u{0020}time\u{0020}and\u{0020}place,\u{0020}Suzu's\u{0020}biological\u{0020}mother\u{0020}stepped\u{0020}forward.\u{0020}To\u{0020}protect\u{0020}her\u{0020}hometown,\u{0020}to\u{0020}protect\u{0020}her\u{0020}family,\u{0020}and\u{0020}to\u{0020}protect\u{0020}her\u{0020}child,\u{0020}she\u{0020}fought\u{0020}until\u{0020}the\u{0020}last\u{0020}moment.\n\nWhen\u{0020}the\u{0020}rescue\u{0020}team\u{0020}of\u{0020}AEGIS\u{0020}arrived,\u{0020}Suzu's\u{0020}biological\u{0020}mother\u{0020}had\u{0020}sacrificed\u{0020}herself\u{0020}in\u{0020}the\u{0020}battle,\u{0020}and\u{0020}Suzu's\u{0020}biological\u{0020}father,\u{0020}in\u{0020}order\u{0020}to\u{0020}protect\u{0020}Suzu,\u{0020}became\u{0020}Suzu's\u{0020}last\u{0020}shield\u{0020}in\u{0020}the\u{0020}collapsed\u{0020}building\u{0020}and\u{0020}protected\u{0020}Suzu\u{0020}with\u{0020}his\u{0020}life.\n\nSuzu,\u{0020}who\u{0020}became\u{0020}an\u{0020}orphan,\u{0020}was\u{0020}adopted\u{0020}by\u{0020}a\u{0020}colleague\u{0020}of\u{0020}her\u{0020}biological\u{0020}mother.\u{0020}Since\u{0020}then,\u{0020}Suzu\u{0020}has\u{0020}had\u{0020}a\u{0020}second\u{0020}mother.\n\nSuzu's\u{0020}biological\u{0020}parents\u{0020}gave\u{0020}Suzu\u{0020}life,\u{0020}while\u{0020}Suzu's\u{0020}adoptive\u{0020}mother\u{0020}gave\u{0020}Suzu\u{0020}a\u{0020}complete\u{0020}\"motherly\u{0020}love\".\u{0020}Despite\u{0020}no\u{0020}blood\u{0020}relationship,\u{0020}the\u{0020}adoptive\u{0020}mother\u{0020}has\u{0020}always\u{0020}regarded\u{0020}Suzu\u{0020}as\u{0020}her\u{0020}own\u{0020}and\u{0020}taken\u{0020}good\u{0020}care\u{0020}of\u{0020}Suzu.\n\nWhat\u{0020}puzzles\u{0020}us\u{0020}is\u{0020}that\u{0020}both\u{0020}Suzu's\u{0020}biological\u{0020}mother\u{0020}and\u{0020}her\u{0020}adoptive\u{0020}mother\u{0020}are\u{0020}people\u{0020}who\u{0020}have\u{0020}made\u{0020}outstanding\u{0020}achievements\u{0020}in\u{0020}the\u{0020}field\u{0020}of\u{0020}science.\u{0020}As\u{0020}their\u{0020}daughters,\u{0020}Suzu\u{0020}has\u{0020}learned\u{0020}nothing\u{0020}from\u{0020}them.\n\nSuzu\u{0020}doesn't\u{0020}seem\u{0020}to\u{0020}be\u{0020}good\u{0020}at\u{0020}anything.\u{0020}When\u{0020}skipping\u{0020}rope,\u{0020}she\u{0020}always\u{0020}trips\u{0020}over\u{0020}her\u{0020}own\u{0020}feet.\u{0020}The\u{0020}test\u{0020}papers\u{0020}brought\u{0020}back\u{0020}from\u{0020}school\u{0020}for\u{0020}parents\u{0020}to\u{0020}sign\u{0020}always\u{0020}have\u{0020}the\u{0020}low\u{0020}score.\u{0020}Suzu's\u{0020}clumsiness\u{0020}has\u{0020}been\u{0020}fully\u{0020}shown\u{0020}in\u{0020}various\u{0020}fields\u{0020}since\u{0020}childhood.\u{0020}But\u{0020}on\u{0020}the\u{0020}one\u{0020}hand,\u{0020}Suzu's\u{0020}spirit\u{0020}is\u{0020}incredibly\u{0020}strong...\u{0020}even\u{0020}strangely\u{0020}so.\u{0020}No\u{0020}matter\u{0020}how\u{0020}many\u{0020}times\u{0020}she\u{0020}fails\u{0020}or\u{0020}encounters\u{0020}setbacks,\u{0020}she\u{0020}can\u{0020}always\u{0020}stand\u{0020}up\u{0020}from\u{0020}the\u{0020}setbacks.\n\n\"It\u{0020}is\u{0020}the\u{0020}wish\u{0020}that\u{0020}your\u{0020}biological\u{0020}mother\u{0020}placed\u{0020}on\u{0020}Suzu\u{0020}in\u{0020}the\u{0020}past:\u{0020}'You\u{0020}should\u{0020}become\u{0020}a\u{0020}hero,\u{0020}a\u{0020}hero\u{0020}trusted\u{0020}and\u{0020}relied\u{0020}upon\u{0020}by\u{0020}others.'\u{0020}The\u{0020}death\u{0020}of\u{0020}her\u{0020}biological\u{0020}parents\u{0020}and\u{0020}the\u{0020}kindness\u{0020}of\u{0020}her\u{0020}adoptive\u{0020}mother\u{0020}have\u{0020}inspired\u{0020}Suzu\u{0020}to\u{0020}rise\u{0020}from\u{0020}failures\u{0020}again\u{0020}and\u{0020}again.\u{0020}She\u{0020}may\u{0020}be\u{0020}clumsy,\u{0020}but\u{0020}her\u{0020}strong\u{0020}will\u{0020}and\u{0020}optimistic\u{0020}nature\u{0020}are\u{0020}definitely\u{0020}at\u{0020}the\u{0020}'genius'\u{0020}and'monster'\u{0020}level.\"", "0", "0", "0", "0", 11015, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}关于铃的身世，要先从她的生父母说起。\n\u{1000}\u{1000}铃的生父是一名科学官，曾经在九州总部、Maya\u{1000}Branch的科学部担任重要职位，在机械工程、人工智能等领域皆做出过杰出贡献。铃的生母则是一名驾驶员，在那个时代，她是最早的那批驾驶员，作战经验尤为丰富。\n\u{1000}\u{1000}铃有一个幸福美满的家庭——本该是这样的。在铃的生母生下铃之后不久，当铃的一家在故乡度假时，原罪袭击了他们的故乡。作为当时当地唯一的一名驾驶员，铃的生母站了出来，为了保护故乡，为了保护家庭，为了保护孩子，她战斗到了最后一刻。\n\u{1000}\u{1000}当艾吉斯的救援队赶到时，铃的生母已在战斗中牺牲，而铃的生父为了保护铃，在坍塌的建筑物中成了铃最后的一道屏障，用自己的生命保护了铃。\n\u{1000}\u{1000}成为遗孤的铃被生母的同事收养，自此，铃有了第二位母亲。\n\u{1000}\u{1000}铃的生父母赋予了铃生命，而铃的养母则是给予了铃一份完整的\"母爱\"。尽管没有血缘关系，但养母一直把铃视为己出，悉心照顾着铃。\n\u{1000}\u{1000}让我们感到困惑的是，无论是铃的生母，亦或是她的养母，都是在科学领域有着突出建树的人。作为她们的女儿，铃一点也没有从她们身上得到什么、学到什么。\n\u{1000}\u{1000}铃似乎天生便不擅长任何事情，五子棋即使被让子也下不过对手，跳绳的时候总是能把自己脚绊倒，从学校带回来让家长签字的试卷，上面总是挂着零蛋。铃的笨拙从小就在各领域里得到充分体现。但铃一方面，铃的心灵强大到不可思议…甚至说是莫名其妙。不管失败多少次，不管遭到了多少次挫折，她总能从挫折中站起来。\n\u{1000}\u{1000}\"你要成为一个英雄，被人信赖，被人依靠的英雄。\"这是生母过去寄托在铃身上的愿望。生父母的死，养母的养育之恩，激励着铃一次又一次从失败中爬起。她或许笨拙，但她意志之坚强，性情之乐观，绝对是\"天才\"、\"怪物\"级别的。"},
[611503] = {611503, 1000, "\u{0020}Suzu\u{0020}joined\u{0020}AEGIS.\u{0020}Even\u{0020}today,\u{0020}we\u{0020}still\u{0020}think\u{0020}it's\u{0020}a\u{0020}bit\u{0020}too\u{0020}early\u{0020}for\u{0020}her.\n\nIf\u{0020}it\u{0020}weren't\u{0020}for\u{0020}the\u{0020}\"Greedy\u{0020}Crusade\u{0020}War\",\u{0020}the\u{0020}reduction\u{0020}in\u{0020}the\u{0020}number\u{0020}of\u{0020}driver\u{0020}makes\u{0020}it\u{0020}impossible\u{0020}for\u{0020}AEGIS\u{0020}to\u{0020}recruit\u{0020}a\u{0020}child\u{0020}into\u{0020}the\u{0020}academy,\u{0020}even\u{0020}if\u{0020}she\u{0020}has\u{0020}an\u{0020}outstanding\u{0020}Transformation\u{0020}Core\u{0020}Compatability\u{0020}Rate.\n\nBut\u{0020}Suzu\u{0020}herself\u{0020}showed\u{0020}great\u{0020}enthusiasm\u{0020}in\u{0020}joining\u{0020}AEGIS.\u{0020}For\u{0020}her,\u{0020}becoming\u{0020}an\u{0020}AEGIS\u{0020}driver\u{0020}was\u{0020}the\u{0020}first\u{0020}step\u{0020}to\u{0020}realizing\u{0020}her\u{0020}dream.\n\nHowever,\u{0020}Suzu\u{0020}could\u{0020}hardly\u{0020}graduate\u{0020}from\u{0020}the\u{0020}driver\u{0020}academy,\u{0020}even\u{0020}breaking\u{0020}the\u{0020}worst\u{0020}record\u{0020}of\u{0020}the\u{0020}local\u{0020}academy\u{0020}in\u{0020}Kyushu\u{0020}and\u{0020}facing\u{0020}the\u{0020}possibility\u{0020}of\u{0020}being\u{0020}expelled.\n\nThe\u{0020}college\u{0020}teachers\u{0020}and\u{0020}the\u{0020}HR\u{0020}department\u{0020}of\u{0020}AEGIS\u{0020}once\u{0020}struggled\u{0020}with\u{0020}how\u{0020}to\u{0020}place\u{0020}this\u{0020}problem\u{0020}child;\u{0020}eventually,\u{0020}Huameng,\u{0020}who\u{0020}had\u{0020}a\u{0020}great\u{0020}compatibility\u{0020}(or\u{0020}rather,\u{0020}shared\u{0020}the\u{0020}same\u{0020}bad\u{0020}habits)\u{0020}with\u{0020}Suzu,\u{0020}bypassed\u{0020}her\u{0020}team\u{0020}leader\u{0020}Caihua\u{0020}and\u{0020}invited\u{0020}Suzu\u{0020}to\u{0020}join\u{0020}Tian\u{0020}Hua.\n\nAlas...\u{0020}Is\u{0020}this\u{0020}really\u{0020}a\u{0020}good\u{0020}thing?", "0", "0", "0", "0", 11015, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}铃加入艾吉斯，时至今日我们依然觉得对她来说还是太早了点。\n\u{1000}\u{1000}如果不是因为\"贪婪讨伐战\"，使得驾驶员数量锐减，艾吉斯是不可能将一名孩子招入学院的，哪怕她有着和她格格不入的优异幻化核心适格率。\n\u{1000}\u{1000}但铃本人在加入艾吉斯一事上表现出极大的热情。对她来说，成为艾吉斯的驾驶员，正是她实现梦想的第一步。\n\u{1000}\u{1000}然而，铃几乎无法从驾驶员学校中毕业，甚至打破了九州当地学院的最差纪录，面临退学的可能。\n\u{1000}\u{1000}学院教师与艾吉斯的人事部门曾苦恼该如何安置这位问题儿童——最终，与铃相性极佳（或者说臭味相投）的华梦相中了铃，越过其队长彩华，邀请铃加入了天华阁。\n\u{1000}\u{1000}唉…这真的是好事吗？"},
[611504] = {611504, 2000, "\u{0020}\u{0020}She\u{0020}looked\u{0020}around\u{0020}and\u{0020}was\u{0020}already\u{0020}surrounded\u{0020}by\u{0020}Sin.\u{0020}Then\u{0020}she\u{0020}took\u{0020}a\u{0020}deep\u{0020}breath.\n\n\"I\u{0020}am...\u{0020}a\u{0020}genius...\"\n\nThe\u{0020}tender\u{0020}body\u{0020}is\u{0020}still\u{0020}not\u{0020}accustomed\u{0020}to\u{0020}the\u{0020}harshness\u{0020}of\u{0020}the\u{0020}battlefield.\n\nThe\u{0020}fishy\u{0020}smell\u{0020}of\u{0020}blood\u{0020}has\u{0020}already\u{0020}left\u{0020}a\u{0020}deep\u{0020}impression\u{0020}on\u{0020}her.\n\nEvery\u{0020}time\u{0020}stepping\u{0020}onto\u{0020}the\u{0020}battlefield,\u{0020}what\u{0020}is\u{0020}faced\u{0020}is\u{0020}the\u{0020}unknown\u{0020}fear,\u{0020}and\u{0020}this\u{0020}time\u{0020}is\u{0020}no\u{0020}exception.\n\nBut\u{0020}she\u{0020}must\u{0020}not\u{0020}show\u{0020}any\u{0020}cowardice.\n\nShe\u{0020}knew\u{0020}that\u{0020}behind\u{0020}her,\u{0020}on\u{0020}the\u{0020}cracked\u{0020}and\u{0020}collapsed\u{0020}ground,\u{0020}there\u{0020}must\u{0020}be\u{0020}someone\u{0020}looking\u{0020}up\u{0020}at\u{0020}her\u{0020}huge\u{0020}body.\n\nThose\u{0020}people\u{0020}place\u{0020}their\u{0020}hopes\u{0020}on\u{0020}themselves.\u{0020}She\u{0020}is\u{0020}being\u{0020}relied\u{0020}on,\u{0020}trusted\u{0020}and\u{0020}admired,\u{0020}and\u{0020}is\u{0020}becoming\u{0020}a\u{0020}hero.\n\n\"Genius...\u{0020}won't\u{0020}retreat\u{0020}at\u{0020}the\u{0020}critical\u{0020}moment!\"\n\nThe\u{0020}girl,\u{0020}carrying\u{0020}her\u{0020}dream,\u{0020}rushes\u{0020}to\u{0020}the\u{0020}battlefield.", "0", "0", "0", "0", 11015, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}她环顾四周，已经被原罪重重包围，随后她深深地吸了口气。\n\u{1000}\u{1000}\"我是…天才……\"\n\u{1000}\u{1000}稚嫩的身体仍未习惯战场的严酷，\n\u{1000}\u{1000}血的腥味却已经给她留下了深刻的印象。\n\u{1000}\u{1000}每一次走上战场，面临的都是未知的恐惧，这一次也不例外。\n\u{1000}\u{1000}但她不能露怯，\n\u{1000}\u{1000}她知道自己身后，龟裂坍塌的地面上，一定有人正在抬头仰视着自己巨大的身体。\n\u{1000}\u{1000}那些人将希望寄托在自己身上。\n\u{1000}\u{1000}她正在被人依赖，被人信任，被人景仰，正在成为一名英雄。\n\u{1000}\u{1000}\"天才…可不会临阵退缩！\"\n\u{1000}\u{1000}女孩，怀揣梦想，奔向战场。"},
[611600] = {611600, 0, "[Name]\u{0020}Kurobane\n[B-Day]\u{0020}Nov\u{0020}11\n[Compatability\u{0020}Rate]\u{0020}85%\n[Height]\u{0020}36m\n[Squad]\u{0020}Ninja\u{0020}Group\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Shogi\u{0020}and\u{0020}Hanafuda\u{0020}with\u{0020}customized\u{0020}rules.", "0", "0", "0", "0", 11016, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}黑羽\n[B-Day]\u{1000}11月11日\n[幻化核心适格率]\u{1000}85%\n[Height]\u{1000}36m\n[部队]\u{1000}忍心社\n\u{1000}\u{00A0}[\u{1000}隶属]\u{1000}九州总部\n[Interest]\u{1000}自订规则的将棋与花牌"},
[611601] = {611601, 100, "\u{0020}\u{0020}As\u{0020}a\u{0020}member\u{0020}of\u{0020}\"Ninja\u{0020}Group\",\u{0020}our\u{0020}girl\u{0020}is\u{0020}a\u{0020}little\u{0020}different\u{0020}from\u{0020}other\u{0020}squadmates.\n\nWhat\u{0020}she\u{0020}does\u{0020}best,\u{0020}is\u{0020}not\u{0020}assassination,\u{0020}but\u{0020}safeguarding.\n\nAnd\u{0020}because\u{0020}of\u{0020}that,\u{0020}she\u{0020}can\u{0020}neglect\u{0020}that\u{0020}rule\u{0020}of\u{0020}Ninjas,\u{0020}\"Never\u{0020}expose\u{0020}your\u{0020}identity\".\n\nOr\u{0020}maybe,\u{0020}she\u{0020}never\u{0020}follows\u{0020}the\u{0020}rules\u{0020}of\u{0020}her\u{0020}squad?\n\nBut\u{0020}still,\u{0020}throughout\u{0020}AEGIS.\u{0020}only\u{0020}few\u{0020}people\u{0020}have\u{0020}contacted\u{0020}and\u{0020}communicated\u{0020}with\u{0020}her\u{0020}and\u{0020}know\u{0020}her\u{0020}personality.\n\nFortunately,\u{0020}one\u{0020}of\u{0020}them\u{0020}is\u{0020}that\u{0020}young\u{0020}Navigator,\u{0020}and\u{0020}he's\u{0020}willing\u{0020}to\u{0020}cooperate\u{0020}with\u{0020}our\u{0020}archive\u{0020}department.\n\nAfter\u{0020}we\u{0020}organized\u{0020}and\u{0020}analyzed\u{0020}the\u{0020}info\u{0020}provided\u{0020}by\u{0020}that\u{0020}navigator,\u{0020}we\u{0020}have\u{0020}two\u{0020}important\u{0020}conclusions:\n\nKurobane\u{0020}is\u{0020}a\u{0020}Ninja\u{0020}specialized\u{0020}in\u{0020}safeguarding\u{0020}important\u{0020}figures\u{0020}of\u{0020}AEGIS.\u{0020}In\u{0020}Kyushu,\u{0020}a\u{0020}large\u{0020}portion\u{0020}of\u{0020}the\u{0020}heads\u{0020}of\u{0020}11\u{0020}departments\u{0020}have\u{0020}been\u{0020}safeguarded\u{0020}by\u{0020}her\u{0020}when\u{0020}they\u{0020}were\u{0020}on\u{0020}their\u{0020}missions.\n\nAnd\u{0020}about\u{0020}her\u{0020}personality,\u{0020}the\u{0020}Navigator\u{0020}said\u{0020}\"Indeed,\u{0020}she\u{0020}makes\u{0020}you\u{0020}feel\u{0020}safe\u{0020}when\u{0020}she's\u{0020}around,\u{0020}but\u{0020}she's\u{0020}too\u{0020}serious\u{0020}about\u{0020}her\u{0020}\"subordinate\"\u{0020}role.\u{0020}It\u{0020}often\u{0020}feels\u{0020}that\u{0020}she\u{0020}keeps\u{0020}a\u{0020}distance\u{0020}from\u{0020}me,\u{0020}and\u{0020}other\u{0020}people.\u{0020}She's\u{0020}the\u{0020}kind\u{0020}of\u{0020}girl\u{0020}that\u{0020}is\u{0020}not\u{0020}easy\u{0020}to\u{0020}get\u{0020}familiar\u{0020}with.", "0", "0", "0", "0", 11016, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}作为\"忍心社\"的一员，少女与其他的忍心社成员有一些不同。\n\u{1000}\u{1000}她所精通的并非是\"刺杀\"，而是\"守护\"。\n\u{1000}\u{1000}正因为如此，所以她才可以不用在乎忍心社的规定\"不许暴露自己身份\"吧。\n\u{1000}\u{1000}又或者说，她从一开始便不在乎忍心社的规章制度？\n\u{1000}\u{1000}可即便如此，与她有过接触与交流，了解她性格的人，在整个艾吉斯中，也仅仅只有那寥寥数人。\n\u{1000}\u{1000}好在，那位愿意与我们档案部门配合的年轻领航，便是其中一人。\n\u{1000}\u{1000}将那位领航所透漏的情报进行整理、分析后，我们得出了以下两条结论：\n\u{1000}\u{1000}黑羽是专门保护艾吉斯首脑的忍者，九州总部中，十一部门的部长大多都在执行外出任务时接受过她的保护。\n\u{1000}\u{1000}而关于黑羽的性格，领航的说法是\"她待在身边时的确很让人安心……但她太在意自己‘下属’的身份了，总感觉和我，还有其他人保持着距离，是不太好亲近的类型呀。\""},
[611602] = {611602, 500, "\u{0020}\u{0020}When\u{0020}examining\u{0020}Kurobane's\u{0020}background,\u{0020}the\u{0020}archive\u{0020}department\u{0020}of\u{0020}Aegis\u{0020}was\u{0020}in\u{0020}trouble:\u{0020}they\u{0020}didn't\u{0020}know\u{0020}where\u{0020}to\u{0020}find\u{0020}Kurobane's\u{0020}past.\n\nThey\u{0020}knew\u{0020}nothing\u{0020}about\u{0020}Kurobane,\u{0020}and\u{0020}didn't\u{0020}know\u{0020}where\u{0020}to\u{0020}start.\u{0020}As\u{0020}a\u{0020}result,\u{0020}they\u{0020}asked\u{0020}me,\u{0020}the\u{0020}navigator\u{0020}of\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force,\u{0020}for\u{0020}help.\u{0020}(I\u{0020}read\u{0020}the\u{0020}archives\u{0020}of\u{0020}Kyushu,\u{0020}and\u{0020}wonder,\u{0020}is\u{0020}their\u{0020}final\u{0020}solution\u{0020}to\u{0020}everything\u{0020}is\u{0020}asking\u{0020}me\u{0020}and\u{0020}Suzuki\u{0020}for\u{0020}help?)\n\nAbout\u{0020}Kurobane's\u{0020}past,\u{0020}to\u{0020}be\u{0020}honest,\u{0020}what\u{0020}I\u{0020}know\u{0020}is\u{0020}a\u{0020}tip\u{0020}of\u{0020}the\u{0020}iceberg.\u{0020}There\u{0020}are\u{0020}too\u{0020}many\u{0020}myths\u{0020}about\u{0020}her,\u{0020}and\u{0020}I\u{0020}can\u{0020}only\u{0020}talk\u{0020}about\u{0020}what\u{0020}I\u{0020}know.\n\nFirst\u{0020}thing\u{0020}first,\u{0020}\"Kurobane\"\u{0020}is\u{0020}not\u{0020}only\u{0020}her\u{0020}callsign,\u{0020}but\u{0020}also\u{0020}her\u{0020}\"surname\".\n\nAnd\u{0020}I\u{0020}have\u{0020}to\u{0020}emphasize\u{0020}that\u{0020}Kurobane\u{0020}is\u{0020}a\u{0020}Ninja,\u{0020}from\u{0020}a\u{0020}Ninja\u{0020}family\u{0020}with\u{0020}the\u{0020}same\u{0020}name.\n\nAnd\u{0020}she's\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}inherited\u{0020}the\u{0020}name\u{0020}of\u{0020}Kurobane\u{0020}in\u{0020}our\u{0020}time.\n\nShe's\u{0020}the\u{0020}\"Ninja\"\u{0020}we\u{0020}know\u{0020}of\u{0020}in\u{0020}dramas:\u{0020}Affiliated\u{0020}to\u{0020}some\u{0020}bloc,\u{0020}secretly\u{0020}doing\u{0020}immoral,\u{0020}or\u{0020}even\u{0020}evil\u{0020}jobs\u{0020}like\u{0020}assassination\u{0020}and\u{0020}intel\u{0020}gathering\u{0020}for\u{0020}it.\n\nThe\u{0020}Kurobane\u{0020}family\u{0020}exists\u{0020}in\u{0020}our\u{0020}history\u{0020}in\u{0020}a\u{0020}special\u{0020}way,\u{0020}they\u{0020}are\u{0020}nowhere\u{0020}to\u{0020}be\u{0020}found,\u{0020}but\u{0020}they\u{0020}change\u{0020}the\u{0020}course\u{0020}of\u{0020}history\u{0020}by\u{0020}those\u{0020}\"dirty\u{0020}jobs\".\u{0020}It\u{0020}is\u{0020}appropriate\u{0020}to\u{0020}describe\u{0020}them\u{0020}as\u{0020}\"People\u{0020}that\u{0020}live\u{0020}in\u{0020}the\u{0020}shadows\".\n\nThe\u{0020}reason\u{0020}why\u{0020}Kurobanes\u{0020}are\u{0020}willing\u{0020}to\u{0020}work\u{0020}for\u{0020}some\u{0020}bloc\u{0020}is\u{0020}special.\u{0020}They\u{0020}won't\u{0020}establish\u{0020}long\u{0020}term\u{0020}cooperation\u{0020}with\u{0020}someone\u{0020}because\u{0020}of\u{0020}\"wealth\",\"power\"\u{0020}or\u{0020}\"forces\".\u{0020}The\u{0020}way\u{0020}to\u{0020}make\u{0020}them\u{0020}loyal\u{0020}to\u{0020}someone\u{0020}is\u{0020}giving\u{0020}them\u{0020}\"love\".\n\nFriendship,\u{0020}familyship,\u{0020}or\u{0020}romantic\u{0020}love…can\u{0020}in\u{0020}exchange\u{0020}for\u{0020}their\u{0020}loyalty.\n\nIn\u{0020}other\u{0020}words,\u{0020}unlike\u{0020}others\u{0020}that\u{0020}consider\u{0020}ninjas\u{0020}as\u{0020}a\u{0020}tool\u{0020}or\u{0020}method\u{0020}to\u{0020}achieve\u{0020}something,\u{0020}treating\u{0020}Kurobanes\u{0020}like\u{0020}they\u{0020}are\u{0020}in\u{0020}an\u{0020}equal\u{0020}status\u{0020}like\u{0020}you\u{0020}can\u{0020}win\u{0020}that\u{0020}allegiance.\n\nKurobane\u{0020}is\u{0020}a\u{0020}loyal\u{0020}ninja,\u{0020}and\u{0020}\"loyalty\"\u{0020}is\u{0020}not\u{0020}a\u{0020}common\u{0020}trait\u{0020}among\u{0020}ninjas.\u{0020}In\u{0020}ancient\u{0020}times,\u{0020}lords\u{0020}or\u{0020}kings\u{0020}deemed\u{0020}that\u{0020}\"people\u{0020}who\u{0020}do\u{0020}dirty\u{0020}work\u{0020}want\u{0020}to\u{0020}have\u{0020}the\u{0020}same\u{0020}status\u{0020}like\u{0020}a\u{0020}samurai\"\u{0020}is\u{0020}unacceptable.\u{0020}They\u{0020}would\u{0020}even\u{0020}suppress\u{0020}this\u{0020}kind\u{0020}of\u{0020}unorthodoxy.\n\nAnd\u{0020}maybe,\u{0020}that's\u{0020}why\u{0020}Kurobanes\u{0020}diminished.", "0", "0", "0", "0", 11016, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}在调查黑羽背景时，艾吉斯档案部门遇挫了——他们不知道从哪能查到关于黑羽的过去。\n\u{1000}\u{1000}艾吉斯档案部门对于黑羽一无所知，无从下手。因此他们，找上了我，多瑙特别联合部队的领航（我翻阅了九州总部的档案记录，不禁疑惑，莫非他们的王牌就是请铃木清风和我当外援吗？）\n\u{1000}\u{1000}关于黑羽的过去…老实说，我知道的事情也只不过是冰山一角。在她身上，有太多的谜团，我也只能避重就轻地谈一谈她的过去。\n\u{1000}\u{1000}首先要说的是，黑羽并不仅是她的代号，同时也是她的\"姓氏\"。\n\u{1000}\u{1000}然后要特别强调的是，黑羽是一名忍者，出身于忍者家族\"黑羽\"的忍者。\n\u{1000}\u{1000}也是这个时代，唯一一个继承了\"黑羽\"之名的忍者。\n\u{1000}\u{1000}她就是我们曾经在影视作品里见过的那种\"忍者\"：效忠于某个势力，在暗中为该势力执行潜入暗杀，窃取情报等不光彩，甚至可以称得上\"卑劣\"的任务。\n\u{1000}\u{1000}黑羽一族一直以另外一种形式存在于历史中，他们渺无踪影，却又能通过上述这些\"卑劣手段\"影响甚至推动历史的发展，用\"生活在影子世界的人\"来形容他们是再合适不过了。\n\u{1000}\u{1000}而黑羽一族效忠某个势力的原因，却又些特别。他们并不会因为\"金钱\"、\"权力\"、\"武力\"而建立长期合作关系。真正能够获得他们忠诚的方式，是给予他们\"爱\"。\n\u{1000}\u{1000}友情、亲情、爱情…只有这些才能获得他们的忠诚。\n\u{1000}\u{1000}换句话说，并不是像其他人一样，把忍者视为达成目的的工具、手段，而是把身为忍者的他们当做与自己平等的人对待，才能得到\"黑羽\"的认可。\n\u{1000}\u{1000}黑羽是忠诚的忍者，而\"忠诚\"这一特质在忍者这一职业中显得尤其另类。在古时的主君看来，从事肮脏工作的人妄图取得与武士同等的地位，这是他们不肯接受，不能认可的，甚至会去打压这类超出常识的异端。\n\u{1000}\u{1000}而这，多半就是黑羽一族没落的原因吧。"},
[611603] = {611603, 1000, "\u{0020}\u{0020}Please\u{0020}notice\u{0020}that\u{0020}asking\u{0020}for\u{0020}external\u{0020}help\u{0020}is\u{0020}not\u{0020}all\u{0020}we\u{0020}are\u{0020}capable\u{0020}of.\u{0020}We\u{0020}just\u{0020}need\u{0020}the\u{0020}help\u{0020}from\u{0020}people\u{0020}who\u{0020}know\u{0020}what\u{0020}we\u{0020}want\u{0020}when\u{0020}needed.\n\nWe\u{0020}organized\u{0020}what\u{0020}that\u{0020}navigator\u{0020}stated,\u{0020}and\u{0020}expanded\u{0020}the\u{0020}information\u{0020}he\u{0020}provided,\u{0020}which\u{0020}is\u{0020}investigating\u{0020}Kurobane\u{0020}inside\u{0020}AEGIS\u{0020}with\u{0020}further\u{0020}steps.\n\nOur\u{0020}world\u{0020}has\u{0020}changed\u{0020}a\u{0020}lot,\u{0020}in\u{0020}the\u{0020}current\u{0020}era,\u{0020}Kurobanes\u{0020}are\u{0020}under\u{0020}the\u{0020}protection\u{0020}of\u{0020}AEGIS.\u{0020}That's\u{0020}the\u{0020}reason\u{0020}Kurobane\u{0020}is\u{0020}serving\u{0020}for\u{0020}AEGIS.\u{0020}For\u{0020}now.\u{0020}However,\u{0020}this\u{0020}is\u{0020}only\u{0020}a\u{0020}trade.\n\nAEGIS\u{0020}is\u{0020}not\u{0020}approved\u{0020}by\u{0020}Kurobane.\u{0020}It\u{0020}doesn't\u{0020}have\u{0020}her\u{0020}allegiance\u{0020}either.\n\nSo,\u{0020}it\u{0020}looks\u{0020}like\u{0020}only\u{0020}\"that\u{0020}person\"\u{0020}is\u{0020}trusted\u{0020}by\u{0020}Kurobane.\n\nBecause,\u{0020}even\u{0020}those\u{0020}officials\u{0020}that\u{0020}have\u{0020}been\u{0020}safeguarded\u{0020}by\u{0020}Kurobane,\u{0020}do\u{0020}not\u{0020}necessarily\u{0020}know\u{0020}her\u{0020}past.", "0", "0", "0", "0", 11016, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}声明一下，我们并不是只会请外援，而是在需要的时候会寻找知情人帮助而已。\n\u{1000}\u{1000}我们整理了领航陈述的话，并且基于他提供的信息进行了一定程度上的扩展——也就是进一步在艾吉斯内调查关于黑羽的事。\n\u{1000}\u{1000}时代变了的现在，黑羽一族接受了来自艾吉斯的庇佑，这便是黑羽暂时为艾吉斯服务的原因——不过，这只是一种等价交换的交易。\n\u{1000}\u{1000}艾吉斯并未得到黑羽的认可，黑羽的忠诚。\n\u{1000}\u{1000}那么，现在回过头来看，真正得到了黑羽认可的人——只有那位了吧。\n\u{1000}\u{1000}毕竟，即便是那些接受保护的官员，也未必知道黑羽的过去吧？"},
[611604] = {611604, 2000, "\u{0020}\u{0020}The\u{0020}city\u{0020}covered\u{0020}in\u{0020}haze\u{0020}becomes\u{0020}a\u{0020}metropolitan\u{0020}of\u{0020}devils.\n\nMonsters,\u{0020}covered\u{0020}in\u{0020}unknown\u{0020}metals,\u{0020}are\u{0020}raging\u{0020}in\u{0020}the\u{0020}area.\n\nThat\u{0020}navigator\u{0020}is\u{0020}staring\u{0020}at\u{0020}this\u{0020}in\u{0020}the\u{0020}air.\n\nTotally\u{0020}unaware\u{0020}of\u{0020}the\u{0020}incoming\u{0020}danger.\n\nIn\u{0020}a\u{0020}blink,\u{0020}death\u{0020}comes,\u{0020}that\u{0020}monster\u{0020}emerges\u{0020}from\u{0020}the\u{0020}haze,\u{0020}wanting\u{0020}to\u{0020}engulf\u{0020}him\u{0020}to\u{0020}its\u{0020}stomach.\n\nBut\u{0020}that\u{0020}doesn't\u{0020}matter,\u{0020}because\u{0020}that\u{0020}girl\u{0020}is\u{0020}ready.\n\nKurobane\u{0020}the\u{0020}ninja\u{0020}shows\u{0020}her\u{0020}vague\u{0020}figure\u{0020}from\u{0020}the\u{0020}haze,\u{0020}a\u{0020}sharpened\u{0020}arrow\u{0020}leaves\u{0020}a\u{0020}clear\u{0020}whiz\u{0020}in\u{0020}the\u{0020}air.\n\nAnd\u{0020}the\u{0020}monster\u{0020}stops,\u{0020}its\u{0020}head\u{0020}is\u{0020}penetrated.\n\nHer\u{0020}gentle\u{0020}voice\u{0020}echoes\u{0020}everywhere\u{0020}in\u{0020}this\u{0020}hazy\u{0020}city.\n\n\"I'm\u{0020}always\u{0020}here,\u{0020}because\u{0020}guarding\u{0020}you,\u{0020}is\u{0020}my\u{0020}lifelong\u{0020}duty.\"", "0", "0", "0", "0", 11016, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}雾境中的都市成了魔物栖息的魔之都，\n\u{1000}\u{1000}由未知金属铸成身躯的怪物正在都市内肆虐纵横，\n\u{1000}\u{1000}渺小的凡人，那名领航正在空中俯瞰着这一切，\n\u{1000}\u{1000}对于身边接近的危险一无所知，\n\u{1000}\u{1000}瞬息间，死亡降临，那从雾中扑来的怪物，要将他吞入腹中。\n\u{1000}\u{1000}但是没有关系，因为那名少女早已做好准备。\n\u{1000}\u{1000}黑羽的忍者自雾中现出朦胧的身影，锋芒毕露的箭矢在空中留下尖锐的啸声，\n\u{1000}\u{1000}怪物庞大的身躯因此停止了动作，它的头颅被贯穿了。\n\u{1000}\u{1000}她温柔的声音在这弥漫雾气的城市中回旋，\n\u{1000}\u{1000}\"我一直在这里，守护您，是我毕生的职责。\""},
[611700] = {611700, 0, "[Name]\u{0020}Flora\n[B-Day]\u{0020}April\u{0020}28\n[Compatability\u{0020}Rate]\u{0020}92％\n[Height]\u{0020}37m\n[Squad]\u{0020}First\u{0020}Guards\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Drinking\u{0020}tea\u{0020}and\u{0020}taking\u{0020}a\u{0020}walk\u{0020}in\u{0020}the\u{0020}garden\u{0020}under\u{0020}the\u{0020}pleasant\u{0020}sunlight\u{0020}at\u{0020}three\u{0020}o'clock\u{0020}in\u{0020}the\u{0020}afternoon", "0", "0", "0", "0", 11017, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}芙萝拉\n[B-Day]\u{1000}4月28日\n[幻化核心适格率]\u{1000}92％\n[Height]\u{1000}38m\n[部队]\u{1000}第一亲卫班\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}在午后三点的惬意阳光下于花园里饮茶、散步"},
[611701] = {611701, 100, "\u{0020}\u{0020}Serious\u{0020}but\u{0020}gentle.\u{0020}Judging\u{0020}from\u{0020}appearance\u{0020}alone,\u{0020}she\u{0020}should\u{0020}be\u{0020}a\u{0020}rational\u{0020}person.\u{0020}As\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}First\u{0020}Guards\u{0020}Squad\u{0020}and\u{0020}the\u{0020}guardian\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Ark,\u{0020}Flora\u{0020}has\u{0020}always\u{0020}maintained\u{0020}a\u{0020}good\u{0020}image\u{0020}in\u{0020}front\u{0020}of\u{0020}everyone.\u{0020}Born\u{0020}noble,\u{0020}she\u{0020}does\u{0020}not\u{0020}have\u{0020}the\u{0020}arrogance\u{0020}characteristic\u{0020}of\u{0020}the\u{0020}traditional\u{0020}Danube\u{0020}nobility.\u{0020}No\u{0020}matter\u{0020}who\u{0020}she\u{0020}is\u{0020}dealing\u{0020}with,\u{0020}she\u{0020}maintains\u{0020}an\u{0020}attitude\u{0020}that\u{0020}is\u{0020}very\u{0020}in\u{0020}line\u{0020}with\u{0020}her\u{0020}identity\u{0020}as\u{0020}a\u{0020}\"personal\u{0020}guard\".\n\nDuring\u{0020}the\u{0020}battle,\u{0020}she\u{0020}never\u{0020}commanded\u{0020}any\u{0020}team\u{0020}members\u{0020}with\u{0020}a\u{0020}tough\u{0020}attitude.\u{0020}She\u{0020}merely\u{0020}objectively\u{0020}conveyed\u{0020}the\u{0020}instructions\u{0020}of\u{0020}the\u{0020}superiors\u{0020}to\u{0020}everyone\u{0020}and\u{0020}led\u{0020}by\u{0020}example,\u{0020}taking\u{0020}the\u{0020}lead\u{0020}in\u{0020}execution.\u{0020}And\u{0020}everyone\u{0020}really\u{0020}likes\u{0020}to\u{0020}follow\u{0020}the\u{0020}excellent\u{0020}Flora\u{0020}and\u{0020}regards\u{0020}her\u{0020}as\u{0020}a\u{0020}learning\u{0020}target.\n\nHowever,\u{0020}she\u{0020}also\u{0020}has\u{0020}something\u{0020}bothering\u{0020}her,\u{0020}or\u{0020}something\u{0020}she\u{0020}is\u{0020}not\u{0020}good\u{0020}at.\u{0020}Although\u{0020}Flora\u{0020}can\u{0020}handle\u{0020}her\u{0020}job\u{0020}well,\u{0020}she\u{0020}doesn't\u{0020}have\u{0020}a\u{0020}friend\u{0020}to\u{0020}talk\u{0020}to.\u{0020}She\u{0020}doesn't\u{0020}know\u{0020}how\u{0020}to\u{0020}communicate\u{0020}with\u{0020}others\u{0020}naturally,\u{0020}which\u{0020}leads\u{0020}to\u{0020}her\u{0020}having\u{0020}a\u{0020}lot\u{0020}of\u{0020}words\u{0020}pent\u{0020}up\u{0020}in\u{0020}her\u{0020}heart\u{0020}and\u{0020}wanting\u{0020}to\u{0020}confide\u{0020}to\u{0020}someone.", "0", "0", "0", "0", 11017, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}严谨却不失温柔，单看外貌的话应该是个理性的人。身为第一亲卫班的队长，守护着多瑙方舟的芙萝拉一直在大家面前保持着良好的形象。出生高贵的她身上并没有那种传统多瑙旧贵族特有的傲气，无论是对谁都保持着非常符合其\"亲卫\"身份的态度。\n\u{1000}\u{1000}战斗中她也从来不会以强硬的态度去命令任何队员，她只是客观地向大家传达上级的指令并以身作则，率先执行而已。而大家都非常喜欢跟在优秀的芙萝拉身后，将她视作学习的对象。\n\u{1000}\u{1000}不过她也有着苦恼的事，或者说自己不擅长的事。芙萝拉虽然能很好得处理好本职工作，不过她却没有一个能够倾诉心事的朋友，她不知道该如何自然地与她人交流，这导致她在心里憋了一大堆话想要找人倾诉。"},
[611702] = {611702, 500, "\u{0020}\u{0020}Long\u{0020}before\u{0020}AEGIS\u{0020}took\u{0020}root\u{0020}in\u{0020}the\u{0020}Danube\u{0020}region,\u{0020}there\u{0020}was\u{0020}a\u{0020}group\u{0020}of\u{0020}nobles\u{0020}here\u{0020}called\u{0020}the\u{0020}\"Personal\u{0020}Guards\".\u{0020}They\u{0020}were\u{0020}the\u{0020}guardians\u{0020}protecting\u{0020}the\u{0020}symbol\u{0020}of\u{0020}a\u{0020}country\u{0020}-\u{0020}the\u{0020}king.\u{0020}Only\u{0020}the\u{0020}king\u{0020}could\u{0020}command\u{0020}them,\u{0020}and\u{0020}they\u{0020}were\u{0020}the\u{0020}ones\u{0020}closest\u{0020}to\u{0020}the\u{0020}king.\u{0020}Compared\u{0020}to\u{0020}ordinary\u{0020}nobles,\u{0020}their\u{0020}status\u{0020}is\u{0020}more\u{0020}lofty.\u{0020}But\u{0020}the\u{0020}personal\u{0020}guards\u{0020}are\u{0020}particularly\u{0020}humble\u{0020}towards\u{0020}other\n\nAfter\u{0020}all,\u{0020}they\u{0020}have\u{0020}no\u{0020}actual\u{0020}rights\u{0020}and\u{0020}are\u{0020}merely\u{0020}worshipped\u{0020}as\u{0020}idols\u{0020}by\u{0020}the\u{0020}world.\n\nAlthough\u{0020}there\u{0020}are\u{0020}no\u{0020}so-called\u{0020}Guards\u{0020}in\u{0020}modern\u{0020}Danube,\u{0020}there\u{0020}is\u{0020}still\u{0020}a\u{0020}driver\u{0020}force\u{0020}\"First\u{0020}Guards\u{0020}Squad\"\u{0020}that\u{0020}has\u{0020}inherited\u{0020}its\u{0020}spirit,\u{0020}and\u{0020}the\u{0020}object\u{0020}they\u{0020}want\u{0020}to\u{0020}protect\u{0020}has\u{0020}become\u{0020}Danube's\u{0020}Ark.\n\nAnd\u{0020}Flora\u{0020}was\u{0020}born\u{0020}into\u{0020}a\u{0020}traditional\u{0020}\"Personal\u{0020}Guards\"\u{0020}family.\u{0020}Her\u{0020}parents,\u{0020}like\u{0020}all\u{0020}the\u{0020}old\u{0020}nobles\u{0020}of\u{0020}Danube,\u{0020}planned\u{0020}the\u{0020}direction\u{0020}of\u{0020}her\u{0020}growth\u{0020}-\u{0020}to\u{0020}become\u{0020}a\u{0020}personal\u{0020}guard\u{0020}like\u{0020}themselves.\u{0020}Although\u{0020}Flora\u{0020}had\u{0020}many\u{0020}complaints\u{0020}at\u{0020}the\u{0020}beginning,\u{0020}she\u{0020}eventually\u{0020}chose\u{0020}to\u{0020}comply\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}First\u{0020}Guards\u{0020}Squad.\n\nBecause\u{0020}of\u{0020}her\u{0020}outstanding\u{0020}performance,\u{0020}she\u{0020}became\u{0020}the\u{0020}captain\u{0020}of\u{0020}this\u{0020}unit,\u{0020}but\u{0020}she\u{0020}believed\u{0020}it\u{0020}was\u{0020}related\u{0020}to\u{0020}her\u{0020}family\u{0020}background.\u{0020}So\u{0020}in\u{0020}every\u{0020}mission,\u{0020}she\u{0020}performed\u{0020}even\u{0020}harder.\u{0020}On\u{0020}the\u{0020}one\u{0020}hand,\u{0020}she\u{0020}hoped\u{0020}to\u{0020}prove\u{0020}her\u{0020}strength.\u{0020}On\u{0020}the\u{0020}other\u{0020}hand,\u{0020}she\u{0020}did\u{0020}so\u{0020}to\u{0020}avoid\u{0020}disgracing\u{0020}her\u{0020}family\u{0020}because\u{0020}of\u{0020}her\u{0020}performance.\n\nThis\u{0020}point\u{0020}is\u{0020}quite\u{0020}similar\u{0020}to\u{0020}Julius,\u{0020}who\u{0020}is\u{0020}also\u{0020}a\u{0020}descendant\u{0020}of\u{0020}the\u{0020}old\u{0020}nobility.\u{0020}However,\u{0020}essentially,\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}was\u{0020}the\u{0020}result\u{0020}of\u{0020}Julius\u{0020}following\u{0020}her\u{0020}heart's\u{0020}choice,\u{0020}while\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}was\u{0020}the\u{0020}result\u{0020}of\u{0020}Flora\u{0020}being\u{0020}forced\u{0020}to\u{0020}choose\u{0020}and\u{0020}gradually\u{0020}getting\u{0020}used\u{0020}to\u{0020}it.\u{0020}As\u{0020}for\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}Flora\u{0020}originally\u{0020}wanted\u{0020}to\u{0020}be,\u{0020}she\u{0020}is\u{0020}somewhat\u{0020}unclear.\u{0020}In\u{0020}fact,\u{0020}Flora\u{0020}once\u{0020}wanted\u{0020}to\u{0020}talk\u{0020}to\u{0020}Julius\u{0020}about\u{0020}this\u{0020}matter,\u{0020}but\u{0020}unfortunately,\u{0020}in\u{0020}the\u{0020}end,\u{0020}due\u{0020}to\u{0020}her\u{0020}pride,\u{0020}she\u{0020}gave\u{0020}up.\n\nIn\u{0020}fact,\u{0020}Flora\u{0020}also\u{0020}wanted\u{0020}to\u{0020}talk\u{0020}to\u{0020}Julius\u{0020}about\u{0020}this,\u{0020}but\u{0020}unfortunately\u{0020}she\u{0020}finally\u{0020}gave\u{0020}up.", "0", "0", "0", "0", 11017, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}早在艾吉斯扎根多瑙地区前，这里便有着一支名为\"亲卫队\"的贵族，他们是保护一国象征——国王的卫士，只有国王能够命令他们，他们也是最接近国王的人。所以，比起一般的贵族，他们的地位更加崇高。但是亲卫们对其他\n\u{1000}\u{1000}贵族和平民的态度却又格外谦逊，毕竟他们没有任何实际权利，仅仅是做为偶像被世人崇拜而已。\n\u{1000}\u{1000}虽然到了现代多瑙已经没有所谓的亲卫队了，但是依旧存在着继承了其精神的驾驶员部队\"第一亲卫班\"，而她们所要守护的对象也变成了多瑙的方舟。\n\u{1000}\u{1000}而芙萝拉就是出身在一个传统的\"亲卫队\"世家，她的父母就如同所有多瑙的旧贵族一样，为芙萝拉规划了成长的方向——成为和自己一样的亲卫。芙萝拉虽说一开始有诸多不习惯的地方，但是最终她还是选择了顺从，并成为了第一亲卫班的一员。\n\u{1000}\u{1000}因为其出色的表现成为了这支部队的队长，她却认为这和自己的家庭背景有关。于是在每次的任务中，她都表现得更加努力与认真，一方面她希望证明自己的实力，另一方面她这么做也是不希望自己的家族因为自己的表现而蒙羞。\n\u{1000}\u{1000}这一点倒是与同为旧贵族后裔的朱利乌斯蛮像的，不过本质上成为驾驶员是朱利乌斯遵从内心选择的结果，而成为驾驶员则是芙萝拉被迫选择后慢慢习惯后的结果，至于芙萝拉自己最初到底想要成为什么样的人，她自己都有些弄不清楚了。\n\u{1000}\u{1000}事实上芙萝拉也曾经想要找朱利乌斯聊聊有关于这方面的事情，可惜最终碍于面子她还是放弃了。"},
[611703] = {611703, 1000, "\u{0020}\u{0020}Perhaps\u{0020}it\u{0020}was\u{0020}because\u{0020}they\u{0020}had\u{0020}spent\u{0020}a\u{0020}long\u{0020}time\u{0020}together.\u{0020}Flora\u{0020}finally\u{0020}gathered\u{0020}enough\u{0020}courage\u{0020}to\u{0020}reveal\u{0020}her\u{0020}feelings\u{0020}to\u{0020}that\u{0020}person.\u{0020}\"After\u{0020}all,\u{0020}it's\u{0020}Julius's\u{0020}Navigator,\u{0020}so\u{0020}he\u{0020}should\u{0020}be\u{0020}able\u{0020}to\u{0020}understand\u{0020}me,\u{0020}right?\"\u{0020}Flora\u{0020}thought\u{0020}so.\n\nHowever,\u{0020}after\u{0020}a\u{0020}long\u{0020}discussion,\u{0020}the\u{0020}two\u{0020}still\u{0020}did\u{0020}not\u{0020}come\u{0020}to\u{0020}the\u{0020}conclusion\u{0020}of\u{0020}the\u{0020}question\u{0020}\"What\u{0020}kind\u{0020}of\u{0020}person\u{0020}does\u{0020}Flora\u{0020}want\u{0020}to\u{0020}become.\",\u{0020}but\u{0020}Flora\u{0020}still\u{0020}felt\u{0020}relaxed,\u{0020}because\u{0020}she\u{0020}finally\u{0020}had\u{0020}someone\u{0020}to\u{0020}talk\u{0020}to\u{0020}about\u{0020}her\u{0020}troubles.\n\nAt\u{0020}this\u{0020}time,\u{0020}Flora\u{0020}also\u{0020}realized\u{0020}that\u{0020}what\u{0020}really\u{0020}bothered\u{0020}her\u{0020}was\u{0020}not\u{0020}the\u{0020}problem\u{0020}itself,\u{0020}but\u{0020}how\u{0020}to\u{0020}relieve\u{0020}the\u{0020}pressure\u{0020}brought\u{0020}by\u{0020}these\u{0020}problems\u{0020}through\u{0020}conversation.\u{0020}And\u{0020}after\u{0020}this\u{0020}experience,\u{0020}she\u{0020}gradually\u{0020}began\u{0020}to\u{0020}try\u{0020}to\u{0020}confide\u{0020}in\u{0020}other\u{0020}close\u{0020}friends\u{0020}around\u{0020}her.", "0", "0", "0", "0", 11017, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}也许是因为相处时间长了吧，芙萝拉终于鼓足了勇气向那个人吐露了心声。\n\u{1000}\u{1000}\"毕竟是朱利乌斯的领航，所以应该能理解自己吧？\"芙萝拉这么想到。\n\u{1000}\u{1000}然而经过漫长的讨论两人依旧没有得出\"芙萝拉到底想要成为怎样的人\"这一问题的结果，但是芙萝拉却依旧感到异常轻松，因为对她而言终于有了可以倾诉烦恼的对象了。\n\u{1000}\u{1000}此时芙萝拉也意识到，真正让自己感到苦恼的并不是问题本身，而是该如何通过对话来释放出这些问题所带来的压力。而有了这次成功的经历之后，她也渐渐开始试着向周围其他交好的朋友们袒露心声。"},
[611704] = {611704, 2000, "\u{0020}\u{0020}If\u{0020}one\u{0020}goes\u{0020}to\u{0020}the\u{0020}deck\u{0020}during\u{0020}the\u{0020}voyage\u{0020}of\u{0020}the\u{0020}Ark,\n\nPerhaps\u{0020}you\u{0020}will\u{0020}be\u{0020}fortunate\u{0020}enough\u{0020}to\u{0020}encounter\u{0020}Flora\u{0020}who\u{0020}is\u{0020}on\u{0020}a\u{0020}mission.\n\n\"It's\u{0020}so\u{0020}delightful\u{0020}to\u{0020}see\u{0020}you.\"\n\nThe\u{0020}huge\u{0020}girl\u{0020}in\u{0020}flight\u{0020}leans\u{0020}her\u{0020}body\u{0020}close\u{0020}to\u{0020}the\u{0020}deck\u{0020}and\u{0020}stares\u{0020}at\u{0020}the\u{0020}people\u{0020}on\u{0020}the\u{0020}deck.\n\n\"It's\u{0020}only\u{0020}now\u{0020}that\u{0020}I\u{0020}realize\u{0020}that\u{0020}I'm\u{0020}not\u{0020}just\u{0020}guarding\u{0020}the\u{0020}ark\u{0020}itself.\"\n\n\"It's\u{0020}the\u{0020}countless\u{0020}lives\u{0020}it\u{0020}carries\u{0020}and\u{0020}their\u{0020}future...\"\n\n...\n\nThe\u{0020}girl\u{0020}who\u{0020}walked\u{0020}with\u{0020}me\u{0020}like\u{0020}a\u{0020}spring\u{0020}breeze\u{0020}paused\u{0020}for\u{0020}a\u{0020}while.\n\n\"And\u{0020}the\u{0020}most\u{0020}important\u{0020}person\u{0020}to\u{0020}me...\"", "0", "0", "0", "0", 11017, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}如果在方舟航行的时候前往甲板，\n\u{1000}\u{1000}也许你便能有幸遇到正在执行任务的芙萝拉。\n\u{1000}\u{1000}\"能够看到您真是令人感到高兴。\"\n\u{1000}\u{1000}飞行中的巨大少女将身体贴近甲板，盯着甲板上的人。\n\u{1000}\u{1000}\"直到现在我才意识到，我所守护的不光光是这艘方舟本身。\"\n\u{1000}\u{1000}\"而是其承载着的无数生命与他们的未来……\"\n\u{1000}\u{1000}\u{1000}……\n\u{1000}\u{1000}\u{1000}如同春风一般与我同行的少女，稍作停顿。\n\u{1000}\u{1000}\"以及对我而言最重要的人……\""},
[611800] = {611800, 0, "[Name]\u{0020}Shirogane\n[B-Day]\u{0020}March\u{0020}20\n[Compatability\u{0020}Rate]\u{0020}50％\n[Height]\u{0020}38m\n[Squad]\u{0020}Mammalian\n[Affiliation]\u{0020}Maya\n[Interest]\u{0020}Apples,\u{0020}little\u{0020}creatures", "0", "0", "0", "0", 11018, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}銀\n[B-Day]\u{1000}冬天下第一場雪的時候\n[Vision\u{1000}Core\u{1000}Proficiency]\u{1000}50％\n[Height]\u{1000}38m\n[Squad]\u{1000}麻麻蓮\n\u{1000}\u{00A0}[Affiliation]\u{1000}瑪雅支部\n[Interest]\u{1000}蘋果\u{1000}小動物"},
[611801] = {611801, 100, "\u{0020}\u{0020}With\u{0020}a\u{0020}non-human\u{0020}appearance,\u{0020}unlike\u{0020}her\u{0020}fellow\u{0020}Etans\u{0020}in\u{0020}her\u{0020}squad,\u{0020}she's\u{0020}more\u{0020}similar\u{0020}to\u{0020}a\u{0020}beast\u{0020}than\u{0020}to\u{0020}a\u{0020}humanoid\u{0020}with\u{0020}intelligence.\u{0020}You\u{0020}can\u{0020}feel\u{0020}her\u{0020}strong\u{0020}oppressiveness\u{0020}just\u{0020}by\u{0020}standing\u{0020}next\u{0020}to\u{0020}her,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}feeling\u{0020}of\u{0020}suffocation,\u{0020}like\u{0020}a\u{0020}wolf\u{0020}bites\u{0020}your\u{0020}neck.\u{0020}As\u{0020}a\u{0020}result,\u{0020}few\u{0020}people\u{0020}in\u{0020}Maya\u{0020}can\u{0020}communicate\u{0020}with\u{0020}her,\u{0020}even\u{0020}her\u{0020}akin\u{0020}squadmates\u{0020}Mizo\u{0020}and\u{0020}Rou\u{0020}don't\u{0020}talk\u{0020}to\u{0020}her\u{0020}a\u{0020}lot.\u{0020}In\u{0020}their\u{0020}eyes,\u{0020}Shirogane\u{0020}is\u{0020}the\u{0020}real\u{0020}Etan\u{0020}warrior.\n\nHowever,\u{0020}there\u{0020}are\u{0020}a\u{0020}few\u{0020}human\u{0020}drivers\u{0020}in\u{0020}Maya\u{0020}who\u{0020}have\u{0020}a\u{0020}good\u{0020}relationship\u{0020}with\u{0020}Shirogane.\u{0020}According\u{0020}to\u{0020}the\u{0020}people\u{0020}familiar\u{0020}with\u{0020}her,\u{0020}Shirogane\u{0020}can\u{0020}be\u{0020}cute\u{0020}in\u{0020}her\u{0020}daily\u{0020}life:\u{0020}She\u{0020}loves\u{0020}the\u{0020}smell\u{0020}of\u{0020}apples,\u{0020}and\u{0020}she\u{0020}always\u{0020}chooses\u{0020}hair\u{0020}shampoos\u{0020}with\u{0020}a\u{0020}scent\u{0020}of\u{0020}apples.\n\nMoreover,\u{0020}she\u{0020}dislikes\u{0020}canids,\u{0020}and\u{0020}extremely\u{0020}loves\u{0020}cats.\u{0020}But\u{0020}still,\u{0020}if\u{0020}she\u{0020}sees\u{0020}little\u{0020}puppies\u{0020}on\u{0020}the\u{0020}road,\u{0020}she\u{0020}will\u{0020}pat\u{0020}them\u{0020}because\u{0020}they\u{0020}are\u{0020}cute.", "0", "0", "0", "0", 11018, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}擁有著非人外觀的銀與同族兩位隊友不同，她的氣質比起擁有高智能的類人生物更加接近真正的野獸。單是站在她身邊便能感受到強大的壓迫感，以及仿佛被惡狼咬住脖頸般的窒息感。所以，在瑪雅支部中真正能和她說上話的人也是屈指可數。甚至就連身為同族的瓏和渠都很少與之交談，在她們眼中銀才是真正的埃塔星戰士，而自己只是被迫拿起武器的平民罷了。\n\u{1000}\u{1000}不過在瑪雅支部內也有個別與其關係還算可以的人類駕駛員。根據與她熟悉的人所說，銀其實在生活中也有可愛的一面，比如說她非常熱衷於蘋果的香味，每次挑選洗發水時都會特意選擇有蘋果味的產品。\n\u{1000}\u{1000}另外，她非常討厭犬科動物，是個不折不扣的貓奴，不過如果在路上遇到可愛的幼犬依然會忍不住去摸摸看。"},
[611802] = {611802, 500, "\u{0020}\u{0020}\"Mammalians\"(\"Human\"\u{0020}in\u{0020}Etan)\u{0020}in\u{0020}Eta\u{0020}have\u{0020}a\u{0020}long\u{0020}life\u{0020}expectancy,\u{0020}25\u{0020}times\u{0020}longer\u{0020}than\u{0020}humans.\u{0020}So,\u{0020}although\u{0020}Shirogane's\u{0020}hometown\u{0020}was\u{0020}ruined\u{0020}by\u{0020}Sins\u{0020}more\u{0020}than\u{0020}a\u{0020}century\u{0020}ago,\u{0020}it's\u{0020}like\u{0020}a\u{0020}recent\u{0020}thing\u{0020}for\u{0020}her.\n\nIn\u{0020}Eta,\u{0020}because\u{0020}each\u{0020}Etan's\u{0020}physique\u{0020}can\u{0020}be\u{0020}very\u{0020}different\u{0020}from\u{0020}others,\u{0020}everybody\u{0020}will\u{0020}be\u{0020}assigned\u{0020}a\u{0020}\"role\"\u{0020}when\u{0020}they\u{0020}are\u{0020}born,\u{0020}and\u{0020}Shirogane's\u{0020}role\u{0020}was\u{0020}\"Soldier\".\u{0020}Although\u{0020}she\u{0020}can\u{0020}change\u{0020}her\u{0020}role\u{0020}once\u{0020}she\u{0020}becomes\u{0020}an\u{0020}adult,\u{0020}she\u{0020}didn't\u{0020}change\u{0020}it,\u{0020}just\u{0020}like\u{0020}the\u{0020}majority\u{0020}of\u{0020}\"assigned\u{0020}Mammalians\".\n\nIndeed,\u{0020}the\u{0020}\"assignment\"\u{0020}was\u{0020}objective\u{0020}and\u{0020}accurate,\u{0020}bloodlust\u{0020}and\u{0020}fighting\u{0020}are\u{0020}in\u{0020}her\u{0020}natural\u{0020}instincts,\u{0020}she\u{0020}felt\u{0020}excited\u{0020}and\u{0020}proud\u{0020}when\u{0020}fighting\u{0020}with\u{0020}enemies\u{0020}from\u{0020}other\u{0020}ethnicities.\u{0020}But\u{0020}she\u{0020}wouldn't\u{0020}bring\u{0020}them\u{0020}home\u{0020}from\u{0020}battlefields,\u{0020}she\u{0020}was\u{0020}very\u{0020}gentle\u{0020}and\u{0020}caring\u{0020}towards\u{0020}her\u{0020}family\u{0020}and\u{0020}friends.\n\nYes,\u{0020}that's\u{0020}another\u{0020}reason\u{0020}why\u{0020}she\u{0020}was\u{0020}assigned\u{0020}the\u{0020}role\u{0020}of\u{0020}\"Soldier\",\u{0020}she\u{0020}wanted\u{0020}to\u{0020}protect\u{0020}the\u{0020}weaks,\u{0020}and\u{0020}her\u{0020}family\u{0020}members.\u{0020}This\u{0020}desire\u{0020}of\u{0020}protecting\u{0020}can\u{0020}even\u{0020}suppress\u{0020}her\u{0020}bloodthirsty\u{0020}mind.\n\nWhen\u{0020}Nevaeh\u{0020}destroyed\u{0020}her\u{0020}planet,\u{0020}a\u{0020}small\u{0020}group\u{0020}of\u{0020}Etans\u{0020}were\u{0020}on\u{0020}duty\u{0020}on\u{0020}another\u{0020}planet,\u{0020}and\u{0020}fortunately\u{0020}they\u{0020}were\u{0020}not\u{0020}affected.\u{0020}Most\u{0020}of\u{0020}them\u{0020}were\u{0020}civilians,\u{0020}and\u{0020}Shirogane\u{0020}was\u{0020}their\u{0020}guardian.\u{0020}Later,\u{0020}they\u{0020}learnt\u{0020}the\u{0020}bad\u{0020}news\u{0020}of\u{0020}her\u{0020}home\u{0020}planet,\u{0020}between\u{0020}the\u{0020}options\u{0020}of\u{0020}going\u{0020}back\u{0020}to\u{0020}her\u{0020}planet\u{0020}and\u{0020}revenge,\u{0020}and\u{0020}continuing\u{0020}to\u{0020}protect\u{0020}these\u{0020}civilians,\u{0020}she\u{0020}chose\u{0020}the\u{0020}latter.\u{0020}She\u{0020}took\u{0020}them\u{0020}with\u{0020}her\u{0020}and\u{0020}went\u{0020}on\u{0020}exile,\u{0020}and\u{0020}reached\u{0020}Earth.\n\nBut\u{0020}things\u{0020}were\u{0020}complex\u{0020}on\u{0020}Earth,\u{0020}and\u{0020}not\u{0020}every\u{0020}faction\u{0020}welcomed\u{0020}these\u{0020}guests\u{0020}from\u{0020}another\u{0020}planet.\u{0020}She\u{0020}deemed\u{0020}the\u{0020}safety\u{0020}and\u{0020}living\u{0020}quality\u{0020}of\u{0020}her\u{0020}people\u{0020}as\u{0020}her\u{0020}priority,\u{0020}and\u{0020}cautiously\u{0020}contacted\u{0020}the\u{0020}leaders\u{0020}of\u{0020}different\u{0020}factions.\u{0020}Finally,\u{0020}under\u{0020}the\u{0020}help\u{0020}from\u{0020}negotiation\u{0020}experts\u{0020}and\u{0020}Mizo,\u{0020}they\u{0020}joined\u{0020}the\u{0020}nascent\u{0020}Aegis,\u{0020}with\u{0020}the\u{0020}information\u{0020}of\u{0020}Eta's\u{0020}technologies\u{0020}and\u{0020}Sins\u{0020}as\u{0020}gifts.\n\nAfter\u{0020}that,\u{0020}Shirogane\u{0020}became\u{0020}reticent,\u{0020}and\u{0020}she\u{0020}no\u{0020}longer\u{0020}shows\u{0020}her\u{0020}warmth\u{0020}towards\u{0020}anyone.\u{0020}After\u{0020}she\u{0020}helped\u{0020}to\u{0020}settle\u{0020}down\u{0020}her\u{0020}fellow\u{0020}Etans,\u{0020}she\u{0020}lives\u{0020}in\u{0020}this\u{0020}world\u{0020}only\u{0020}for\u{0020}fighting.", "0", "0", "0", "0", 11018, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}埃塔星上的麻麻蓮（埃塔語言中\"人\"的意思）們的壽命非常長，大約是人類的25倍，所以就算是距離自己的故鄉被原罪毀滅已經過去了100餘年，但對於銀來說，也仿佛是發生在幾年前的事一樣。\n\u{1000}\u{1000}在埃塔星上，因為每個人的體質差異巨大，所以每個人自出生起便會被分配到一個合適的\"身份\"，而銀被分配到的身份正是\"士兵\"。雖然她也可以在成年之前更換自己的職業，但是正如大部分被分配的人一樣，她並沒有這樣做。\n\u{1000}\u{1000}畢竟分配結果是非常客觀且精准的，嗜殺與戰鬥是她的天性，在與外族的戰鬥中，銀總能發自內心的感到興奮與自豪。不過平日裏她並不會將戰場上的戾氣帶回家，面對家人和友人時她又會表現得異常溫柔。\n\u{1000}\u{1000}沒錯，這正是她被分配到\"士兵\"身份的另一個理由，銀她發自內心地想要守護弱小，想要保護家人。這份守護的渴望甚至可以壓制住其嗜殺的天性。\n\u{1000}\u{1000}在逆愛毀滅了家鄉的那天，有一小批正在外星執勤的埃塔星人僥倖沒有被波及到，這些人大多都是平民，而銀當時則是負責保護這批平民的衛兵。事後，銀她們也知曉了母星被毀滅的消息，在回到母星復仇和保護這些平民之間最終銀還是選擇了後者，她帶著這一小批平民開始逃亡，並最終抵達了地球。\n\u{1000}\u{1000}不過地球勢力錯綜複雜，並不是所有的勢力都歡迎這批來自外星球的客人。銀始終以族人安全與待遇為優先，謹慎地接觸了各個勢力領袖。最終，在談判專家渠的幫助下，她們選擇以自己星球的技術和原罪的情報為見面禮，投靠了尚未成型的組織——艾吉斯。\n\u{1000}\u{1000}自此之後，銀便開始變得沉默起來，她不再對任何人展露其溫柔的一面。在安置完族人之後，支撐她活在世界上的動力只剩下戰鬥。"},
[611803] = {611803, 1000, "\u{0020}\u{0020}\"Your\u{0020}individuals'\u{0020}lives\u{0020}are\u{0020}too\u{0020}short,\u{0020}so\u{0020}short\u{0020}that\u{0020}they\u{0020}wither\u{0020}before\u{0020}I\u{0020}have\u{0020}a\u{0020}feeling\u{0020}about\u{0020}you.\"\n\nAlthough\u{0020}Shirogane\u{0020}has\u{0020}lived\u{0020}with\u{0020}humans\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}she\u{0020}can't\u{0020}really\u{0020}trust\u{0020}them,\u{0020}or\u{0020}she\u{0020}was\u{0020}afraid\u{0020}to.\u{0020}For\u{0020}her,\u{0020}even\u{0020}if\u{0020}she\u{0020}has\u{0020}feelings\u{0020}for\u{0020}someone,\u{0020}it\u{0020}will\u{0020}end\u{0020}in\u{0020}sorrow\u{0020}because\u{0020}of\u{0020}the\u{0020}short\u{0020}life\u{0020}of\u{0020}humans.\n\nTowards\u{0020}her\u{0020}fellow\u{0020}Etans\u{0020}who\u{0020}exiled\u{0020}to\u{0020}Earth,\u{0020}she\u{0020}feels\u{0020}ashamed,\u{0020}and\u{0020}she\u{0020}avoids\u{0020}seeing\u{0020}them.\u{0020}This\u{0020}is\u{0020}especially\u{0020}for\u{0020}Mizo\u{0020}and\u{0020}Rou.\u{0020}Shirogane\u{0020}feels\u{0020}that\u{0020}these\u{0020}civilians\u{0020}were\u{0020}forced\u{0020}to\u{0020}arm\u{0020}themselves\u{0020}only\u{0020}because\u{0020}of\u{0020}her\u{0020}negligence\u{0020}on\u{0020}her\u{0020}duty.\n\nAs\u{0020}a\u{0020}result,\u{0020}just\u{0020}like\u{0020}a\u{0020}curse,\u{0020}although\u{0020}time\u{0020}passes,\u{0020}she\u{0020}will\u{0020}always\u{0020}be\u{0020}in\u{0020}solitude.\u{0020}Until\u{0020}the\u{0020}end\u{0020}of\u{0020}her\u{0020}life,\u{0020}her\u{0020}soul\u{0020}will\u{0020}be\u{0020}able\u{0020}to\u{0020}fly\u{0020}towards\u{0020}the\u{0020}sky,\u{0020}to\u{0020}her\u{0020}deceased\u{0020}family\u{0020}and\u{0020}comrades.\n\nBefore\u{0020}that,\u{0020}Shirogane\u{0020}can\u{0020}only\u{0020}ease\u{0020}her\u{0020}mind\u{0020}with\u{0020}the\u{0020}blood\u{0020}of\u{0020}her\u{0020}enemies\u{0020}and\u{0020}herself.\n\nWell,\u{0020}maybe\u{0020}that\u{0020}person\u{0020}can\u{0020}do…", "0", "0", "0", "0", 11018, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"你們個體的生命太過短暫，短暫到我尚未投入情感便已經凋零。\"\n\u{1000}\u{1000}即便相處了很久，銀也始終無法對人類真正敞開心扉。或者說不敢對人類敞開心扉。對她而言對\"某一個人\"投入太多情感最終也會因為對方壽命太過短暫而空留悲傷。\n\u{1000}\u{1000}而對於流亡到地球的同族人，她則是滿懷愧意，也在有意識得回避著他們。尤其是渠和瓏，銀認為正是自己的失職才使得這些原本是平民的族人被迫拿起了武器。\n\u{1000}\u{1000}所以，就如同詛咒一般，縱使時間流逝，銀始終都將孤身一人。直至生命的盡頭，她的靈魂才能升向天空，去往逝去的親人與戰友們的所在之處。\n\u{1000}\u{1000}在那之前，銀只能用敵人與自己的鮮血麻痹自己。\n\u{1000}\u{1000}當然，也許有一人可以……"},
[611804] = {611804, 2000, "\u{0020}\u{0020}In\u{0020}the\u{0020}wilderness,\u{0020}the\u{0020}silver\u{0020}beast\u{0020}is\u{0020}galloping\u{0020}under\u{0020}the\u{0020}moonlight.\n\nLike\u{0020}she's\u{0020}being\u{0020}burned\u{0020}by\u{0020}this\u{0020}illumination.\n\nShe\u{0020}rapidly\u{0020}runs\u{0020}across\u{0020}rivers\u{0020}and\u{0020}hills,\u{0020}finding\u{0020}a\u{0020}place\u{0020}to\u{0020}hide.\n\nThose\u{0020}who\u{0020}mock\u{0020}her\u{0020}for\u{0020}being\u{0020}unreasonable\u{0020}don't\u{0020}understand.\n\nIn\u{0020}her\u{0020}home\u{0020}planet,\u{0020}there\u{0020}were\u{0020}no\u{0020}celestial\u{0020}bodies\u{0020}like\u{0020}the\u{0020}moon.\n\nShe\u{0020}is\u{0020}simply\u{0020}running\u{0020}to\u{0020}that,\n\ntranquill\u{0020}darkness.", "0", "0", "0", "0", 11018, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}空曠的荒原之上，銀白的野獸正頂著月光賓士。\n\u{1000}\u{1000}像是被這光輝灼傷了一般，\n\u{1000}\u{1000}她急速跨過河流與土丘，尋找著可以遮蔽的掩體。\n\u{1000}\u{1000}那些嘲笑她為不解風情的人卻不知道。\n\u{1000}\u{1000}在她的故鄉，並沒有月亮這種天體。\n\u{1000}\u{1000}她所想要奔向得只是那片寧靜的漆黑。"},
[611900] = {611900, 0, "[Name]\u{0020}Tenten\n[B-Day]\u{0020}June\u{0020}9\n[Compatability\u{0020}Rate]\u{0020}75%\n[Height]\u{0020}35m\n[Squad]\u{0020}Fledgeling\u{0020}Eagle\n[Affiliation]\u{0020}Sahara\u{0020}Branch\n[Interest]\u{0020}Cooking;\u{0020}hammering\u{0020}patties", "0", "0", "0", "0", 11019, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}天天\n[B-Day]\u{1000}6月9日\n[幻化核心适格率]\u{1000}75%\n[Height]\u{1000}27m\n[部队]\u{1000}雏鹰\n[隶属]\u{1000}萨哈拉支部\n[Interest]\u{1000}料理\u{1000}锤肉饼"},
[611901] = {611901, 100, "\u{0020}\u{0020}Like\u{0020}other\u{0020}members\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle,\u{0020}Tenten\u{0020}did\u{0020}not\u{0020}acquire\u{0020}a\u{0020}driver's\u{0020}qualification.\n\nTenten\u{0020}has\u{0020}an\u{0020}exaggerated\u{0020}figure\u{0020}that\u{0020}is\u{0020}completely\u{0020}inconsistent\u{0020}with\u{0020}her\u{0020}face.\u{0020}As\u{0020}a\u{0020}student\u{0020}without\u{0020}social\u{0020}experience,\u{0020}Tenten\u{0020}is\u{0020}oblivious\u{0020}to\u{0020}this\u{0020}gift\u{0020}of\u{0020}hers\u{0020}and\u{0020}often\u{0020}does\u{0020}things\u{0020}that\u{0020}even\u{0020}girls\u{0020}blush\u{0020}at\u{0020}when\u{0020}they\u{0020}see\u{0020}them.\u{0020}Things\u{0020}like\u{0020}changing\u{0020}clothes\u{0020}in\u{0020}the\u{0020}classroom\u{0020}have\u{0020}become\u{0020}common\u{0020}for\u{0020}her.\n\n\"Although\u{0020}we\u{0020}are\u{0020}all\u{0020}girls...\u{0020}Isn't\u{0020}she\u{0020}too\u{0020}unguarded?\u{0020}\"\u{0020}Whether\u{0020}it's\u{0020}her\u{0020}teacher\u{0020}or\u{0020}classmates,\u{0020}more\u{0020}or\u{0020}less\u{0020}are\u{0020}worried\u{0020}about\u{0020}her\u{0020}situation.\n\nAnother\u{0020}talent\u{0020}of\u{0020}Tenten\u{0020}is\u{0020}her\u{0020}stable\u{0020}exam\u{0020}scores.\u{0020}No\u{0020}matter\u{0020}which\u{0020}exam\u{0020}it\u{0020}is,\u{0020}her\u{0020}score\u{0020}on\u{0020}the\u{0020}paper\u{0020}is\u{0020}always\u{0020}60\u{0020}points,\u{0020}not\u{0020}a\u{0020}point\u{0020}more\u{0020}or\u{0020}less,\u{0020}just\u{0020}passing.\u{0020}For\u{0020}this,\u{0020}the\u{0020}teacher\u{0020}specially\u{0020}asked\u{0020}her\u{0020}how\u{0020}she\u{0020}did\u{0020}it.\u{0020}In\u{0020}response,\u{0020}Tenten\u{0020}said:\u{0020}\"I\u{0020}don't\u{0020}know\u{0020}either.\u{0020}Anyway,\u{0020}as\u{0020}long\u{0020}as\u{0020}I\u{0020}pass,\u{0020}I\u{0020}can\u{0020}get\u{0020}the\u{0020}driver's\u{0020}qualification,\u{0020}right?\"\n\nOf\u{0020}course,\u{0020}if\u{0020}we\u{0020}talk\u{0020}about\u{0020}whether\u{0020}she\u{0020}has\u{0020}any\u{0020}serious\u{0020}talents,\u{0020}naturally,\u{0020}she\u{0020}does.\u{0020}Tenten's\u{0020}cooking\u{0020}ability\u{0020}is\u{0020}definitely\u{0020}the\u{0020}best\u{0020}in\u{0020}the\u{0020}academy.\u{0020}People\u{0020}who\u{0020}have\u{0020}eaten\u{0020}the\u{0020}dishes\u{0020}made\u{0020}by\u{0020}Tenten\u{0020}all\u{0020}praise\u{0020}them\u{0020}highly.\n\nIf\u{0020}there\u{0020}were\u{0020}no\u{0020}Sin\u{0020}in\u{0020}this\u{0020}world,\u{0020}opening\u{0020}a\u{0020}restaurant\u{0020}with\u{0020}Tenten's\u{0020}cooking\u{0020}skills\u{0020}would\u{0020}definitely\u{0020}attract\u{0020}many\u{0020}customers.", "0", "0", "0", "0", 11019, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}与雏鹰小队其他成员一样，天天并没有获得正式的驾驶员资格证。\n\u{1000}\u{1000}天天有着与其脸庞完全不符合的夸张身材。作为一个没有社会经验的学生，天天对于自己的这份天赋浑然不觉，时常做出连同为女生的同学们瞧见了都会面红耳赤的事，像是在班级教室更换衣服一类的已经是家常便饭。\n\u{1000}\u{1000}\"虽然大家都是女孩子……但她也太没有戒备心了吧？\"不管是她的老师还是同学，多少都对她的情况感到担忧。\n\u{1000}\u{1000}天天的另一项天赋是她稳定的考试成绩，不管哪次考试，她的卷面成绩永远都是60分，一分不多，一分不少，刚刚及格。为此老师还特地询问过她是如何做到的，对此天天回应道：\"我也不知道，反正只要及格就能拿到驾驶证了吧。\"\n\u{1000}\u{1000}当然要说她有没有正经的天赋，那自然是有的。天天的料理能力绝对是学院第一，吃过天天做的料理的人都对其赞不绝口。\n\u{1000}\u{1000}如果这个世界上不存在原罪的话，以天天的厨艺去开餐厅肯定能吸引不少客人。"},
[611902] = {611902, 500, "\u{0020}\u{0020}Tenten's\u{0020}culinary\u{0020}talent\u{0020}is\u{0020}entirely\u{0020}cultivated\u{0020}by\u{0020}her\u{0020}original\u{0020}family.\u{0020}Tenten's\u{0020}father\u{0020}is\u{0020}a\u{0020}well-known\u{0020}chef\u{0020}in\u{0020}the\u{0020}local\u{0020}area,\u{0020}and\u{0020}her\u{0020}mother\u{0020}is\u{0020}said\u{0020}to\u{0020}be\u{0020}a\u{0020}noble\u{0020}lady\u{0020}from\u{0020}Danube.\u{0020}Tenten's\u{0020}parents\u{0020}broke\u{0020}the\u{0020}noble\u{0020}rules\u{0020}and\u{0020}left\u{0020}Danube\u{0020}for\u{0020}love,\u{0020}arriving\u{0020}in\u{0020}the\u{0020}Sahara\u{0020}far\u{0020}from\u{0020}their\u{0020}hometown\u{0020}and\u{0020}opening\u{0020}a\u{0020}restaurant.\n\nHowever,\u{0020}with\u{0020}Tenten's\u{0020}father's\u{0020}culinary\u{0020}skills,\u{0020}the\u{0020}restaurant's\u{0020}business\u{0020}was\u{0020}so\u{0020}prosperous\u{0020}that\u{0020}it\u{0020}even\u{0020}needed\u{0020}to\u{0020}limit\u{0020}the\u{0020}number\u{0020}of\u{0020}diners\u{0020}each\u{0020}day.\u{0020}After\u{0020}Tenten\u{0020}was\u{0020}born,\u{0020}her\u{0020}parents\u{0020}decided\u{0020}that\u{0020}the\u{0020}restaurant\u{0020}would\u{0020}only\u{0020}be\u{0020}open\u{0020}for\u{0020}half\u{0020}a\u{0020}day\u{0020}and\u{0020}use\u{0020}the\u{0020}remaining\u{0020}time\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}Tenten.\u{0020}Even\u{0020}so,\u{0020}the\u{0020}number\u{0020}of\u{0020}guests\u{0020}increased\u{0020}instead\u{0020}of\u{0020}decreased.\n\nAs\u{0020}Tenten\u{0020}grew\u{0020}up,\u{0020}her\u{0020}father\u{0020}began\u{0020}to\u{0020}teach\u{0020}her\u{0020}culinary\u{0020}skills.\n\nThen,\u{0020}Tenten\u{0020}worked\u{0020}as\u{0020}a\u{0020}waitress\u{0020}in\u{0020}the\u{0020}restaurant\u{0020}to\u{0020}reduce\u{0020}the\u{0020}work\u{0020}pressure\u{0020}on\u{0020}her\u{0020}parents.\n\nWhen\u{0020}the\u{0020}guests\u{0020}were\u{0020}enjoying\u{0020}the\u{0020}delicious\u{0020}food\u{0020}while\u{0020}watching\u{0020}the\u{0020}lovely\u{0020}appearance\u{0020}of\u{0020}Tenten\u{0020}bustling\u{0020}about\u{0020}in\u{0020}the\u{0020}restaurant,\u{0020}standing\u{0020}beside\u{0020}a\u{0020}table\u{0020}taller\u{0020}than\u{0020}herself\u{0020}and\u{0020}taking\u{0020}orders\u{0020}for\u{0020}the\u{0020}guests,\u{0020}they\u{0020}felt\u{0020}that\u{0020}all\u{0020}the\u{0020}fatigue\u{0020}of\u{0020}the\u{0020}day\u{0020}was\u{0020}healed.\u{0020}Many\u{0020}guests\u{0020}came\u{0020}especially\u{0020}to\u{0020}see\u{0020}Tenten,\u{0020}and\u{0020}Tenten\u{0020}was\u{0020}also\u{0020}glad\u{0020}to\u{0020}see\u{0020}the\u{0020}happy\u{0020}smiles\u{0020}on\u{0020}the\u{0020}guests'\u{0020}faces\u{0020}after\u{0020}enjoying\u{0020}the\u{0020}food.\n\nTenten\u{0020}thus\u{0020}gradually\u{0020}grew\u{0020}up,\u{0020}preparing\u{0020}to\u{0020}take\u{0020}over\u{0020}the\u{0020}restaurant\u{0020}from\u{0020}her\u{0020}father,\u{0020}inherit\u{0020}her\u{0020}father's\u{0020}mantle,\u{0020}and\u{0020}become\u{0020}a\u{0020}famous\u{0020}chef...\u{0020}If\u{0020}there\u{0020}were\u{0020}no\u{0020}Sin.\n\nOne\u{0020}night,\u{0020}the\u{0020}pale\u{0020}fog\u{0020}quietly\u{0020}covered\u{0020}the\u{0020}city\u{0020}where\u{0020}the\u{0020}Tenten\u{0020}family\u{0020}lived.\u{0020}Even\u{0020}though\u{0020}the\u{0020}local\u{0020}AVG\u{0020}troops\u{0020}responded\u{0020}promptly,\u{0020}many\u{0020}people\u{0020}still\u{0020}died\u{0020}in\u{0020}their\u{0020}sleep.\u{0020}Fortunately,\u{0020}the\u{0020}Tenten\u{0020}family\u{0020}was\u{0020}at\u{0020}the\u{0020}edge\u{0020}of\u{0020}the\u{0020}pale\u{0020}fog\u{0020}and\u{0020}was\u{0020}rescued\u{0020}quickly,\u{0020}but\u{0020}the\u{0020}restaurant\u{0020}and\u{0020}home\u{0020}that\u{0020}had\u{0020}been\u{0020}operated\u{0020}for\u{0020}many\u{0020}years\u{0020}were\u{0020}destroyed\u{0020}in\u{0020}the\u{0020}battle.\n\n\"Mom,\u{0020}where\u{0020}are\u{0020}we\u{0020}going?\u{0020}Don't\u{0020}we\u{0020}want\u{0020}our\u{0020}home?\"\n\n\"Sin\u{0020}has\u{0020}occupied\u{0020}here.\u{0020}We\u{0020}are\u{0020}going\u{0020}to\u{0020}live\u{0020}in\u{0020}a\u{0020}new\u{0020}city.\u{0020}There\u{0020}we\u{0020}will\u{0020}have\u{0020}a\u{0020}new\u{0020}home.\"\n\n\"Oh...\u{0020}What\u{0020}about\u{0020}the\u{0020}restaurant?\u{0020}Don't\u{0020}we\u{0020}want\u{0020}it\u{0020}anymore?\"\n\n\"Your\u{0020}father\u{0020}and\u{0020}I\u{0020}will\u{0020}open\u{0020}a\u{0020}new\u{0020}restaurant.\"\n\n\"New\u{0020}home\u{0020}and\u{0020}new\u{0020}restaurant?...\u{0020}Then\u{0020}will\u{0020}the\u{0020}bearded\u{0020}uncle\u{0020}who\u{0020}likes\u{0020}to\u{0020}eat\u{0020}fish\u{0020}and\u{0020}the\u{0020}grandma\u{0020}next\u{0020}door\u{0020}still\u{0020}come\u{0020}to\u{0020}the\u{0020}new\u{0020}restaurant\u{0020}at\u{0020}that\u{0020}time,\u{0020}as\u{0020}well\u{0020}as\u{0020}those\u{0020}big\u{0020}brothers\u{0020}who\u{0020}love\u{0020}to\u{0020}eat\u{0020}chicken\u{0020}legs...\"\n\nThe\u{0020}mother\u{0020}held\u{0020}Tenten\u{0020}for\u{0020}a\u{0020}long\u{0020}time\u{0020}without\u{0020}replying.\u{0020}All\u{0020}those\u{0020}mentioned\u{0020}by\u{0020}Tenten\u{0020}were\u{0020}regular\u{0020}customers\u{0020}of\u{0020}the\u{0020}store,\u{0020}but\u{0020}they\u{0020}all\u{0020}lived\u{0020}in\u{0020}the\u{0020}neighboring\u{0020}street\u{0020}area...\u{0020}That\u{0020}street\u{0020}area,\u{0020}after\u{0020}the\u{0020}attack\u{0020}of\u{0020}Sin,\u{0020}had\u{0020}nothing\u{0020}left.\n\nIt\u{0020}was\u{0020}not\u{0020}until\u{0020}several\u{0020}years\u{0020}later\u{0020}that\u{0020}Tenten\u{0020}understood\u{0020}what\u{0020}had\u{0020}happened\u{0020}at\u{0020}that\u{0020}time\u{0020}meant.\n\nAfter\u{0020}the\u{0020}initial\u{0020}pain\u{0020}and\u{0020}grief\u{0020}ended,\u{0020}she\u{0020}picked\u{0020}herself\u{0020}up.\n\nSince\u{0020}the\u{0020}deceased\u{0020}cannot\u{0020}be\u{0020}saved,\u{0020}it\u{0020}is\u{0020}time\u{0020}to\u{0020}dedicate\u{0020}more\u{0020}good\u{0020}things\u{0020}to\u{0020}those\u{0020}who\u{0020}are\u{0020}still\u{0020}alive.\n\nShe\u{0020}understood\u{0020}that\u{0020}only\u{0020}by\u{0020}eliminating\u{0020}Sin\u{0020}could\u{0020}more\u{0020}people\u{0020}be\u{0020}brought\u{0020}happiness.\n\n\"I\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}driver\u{0020}and\u{0020}defeat\u{0020}Sin!\u{0020}Only\u{0020}in\u{0020}this\u{0020}way\u{0020}can\u{0020}everyone\u{0020}enjoy\u{0020}the\u{0020}delicious\u{0020}food\u{0020}more\u{0020}peacefully!\"", "0", "0", "0", "0", 11019, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}天天的料理天赋完全来自于原生家庭的培养。天天的父亲是在当地有名的厨师，母亲听说是一个来自多瑙的贵族小姐。天天的双亲打破了贵族的规矩，为了爱情而离开多瑙，来到了远离家乡的萨哈拉，开了一家饭馆。\u{1000}\u{1000}不过有天天父亲的手艺在，饭馆的生意兴隆到甚至需要限制每天的用餐人数。在天天出生后，父母决定饭馆每天仅开业半天，将剩下的时间用来照顾天天。就算如此，客人的数量还是不减反增。\u{1000}\u{1000}随着天天的长大，父亲开始教导她料理的才艺。\u{1000}\u{1000}而之后，天天以服务员的身份在店里工作，减少父母的工作压力。\u{1000}\u{1000}当客人们一边吃着美食，一边看着天天在饭馆里忙忙碌碌，站在比自己还高的桌子旁给客人点餐时的可爱的模样，感觉一天的疲劳都被治愈了。有许多客人是专程为了看天天而来，天天也很高兴能看到客人们享受美食后脸上幸福的笑容。\u{1000}\u{1000}天天就这样逐渐长大，准备着从父亲手里接过饭馆，继承父亲的衣钵，成为一位有名的大厨……如果没有原罪的话。\u{1000}\u{1000}在某个夜晚，苍雾悄然覆盖了天天一家所居住的城市。即使当地的avg部队反应迅速，可还是有很多人死在睡梦之中。还好天天一家处在苍雾边缘，很快被救走了，但经营多年的饭馆和家却在战斗中毁于一旦。\u{1000}\u{1000}\"妈妈，我们这是要去哪儿？我们的家不要了吗？\"\u{1000}\u{1000}\"原罪已经占领了这里，我们要去新的城市里生活了，在那儿我们会有一个新的家。\"\u{1000}\u{1000}\"哦……那餐馆呢？也不要了吗？\"\u{1000}\u{1000}\"我和你爸爸会开一家新的餐馆。\"\u{1000}\u{1000}\"新的家和新的餐馆？……那到时候喜欢吃鱼的大胡子叔叔和隔壁的奶奶也还会来新的餐馆吗，还有那群爱吃鸡腿的大哥哥……\"\u{1000}\u{1000}母亲抱着天天久久没有回话，天天所说的都是店里的常客，可他们都生活在隔壁的街区……那个街区，在原罪袭击之后，已经什么都不剩了。\u{1000}\u{1000}直到几年后天天才理解当初发生的事意味着什么。\u{1000}\u{1000}在最初的痛苦与悲伤结束后，她振作了起来。\u{1000}\u{1000}既然逝去的人已经无法挽救，那么就该将更多的美好献给还活着的人。\u{1000}\u{1000}她明白了只有消灭原罪才能给更多人带来幸福。\u{1000}\u{1000}\"我要去做驾驶员，打败原罪！这样的，大家才能更加安心地享受美食！\""},
[611903] = {611903, 1000, "\u{0020}For\u{0020}Tenten,\u{0020}when\u{0020}she\u{0020}learned\u{0020}that\u{0020}she\u{0020}was\u{0020}selected\u{0020}to\u{0020}join\u{0020}Fledgeling\u{0020}Eagle\u{0020}at\u{0020}that\u{0020}moment,\u{0020}her\u{0020}heart\u{0020}was\u{0020}excited\u{0020}and\u{0020}happy.\u{0020}She\u{0020}even\u{0020}cooked\u{0020}a\u{0020}lot\u{0020}of\u{0020}cupcakes\u{0020}herself\u{0020}and\u{0020}gave\u{0020}them\u{0020}to\u{0020}her\u{0020}classmates\u{0020}and\u{0020}teachers\u{0020}at\u{0020}that\u{0020}time.\u{0020}Then\u{0020}she\u{0020}packed\u{0020}her\u{0020}luggage\u{0020}and\u{0020}reported\u{0020}to\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}on\u{0020}the\u{0020}same\u{0020}day.\n\nIn\u{0020}the\u{0020}Fledgeling\u{0020}Eagle,\u{0020}Tenten\u{0020}is\u{0020}always\u{0020}the\u{0020}most\u{0020}energetic\u{0020}one.\u{0020}Her\u{0020}team\u{0020}leader\u{0020}Karen\u{0020}evaluated\u{0020}her\u{0020}like\u{0020}this:\n\n\"Tenten\u{0020}is\u{0020}as\u{0020}energetic\u{0020}as\u{0020}the\u{0020}sun,\u{0020}and\u{0020}people\u{0020}around\u{0020}her\u{0020}will\u{0020}be\u{0020}unconsciously\u{0020}infected\u{0020}by\u{0020}her\u{0020}smile.\"\n\nInfecting\u{0020}others\u{0020}with\u{0020}a\u{0020}smile\u{0020}has\u{0020}become\u{0020}Tenten's\u{0020}second\u{0020}important\u{0020}talent.\u{0020}The\u{0020}tasks\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}are\u{0020}usually\u{0020}to\u{0020}provide\u{0020}battlefield\u{0020}assistance\u{0020}at\u{0020}the\u{0020}rear,\u{0020}and\u{0020}one\u{0020}of\u{0020}the\u{0020}important\u{0020}tasks\u{0020}is\u{0020}to\u{0020}escort\u{0020}civilians.\u{0020}And\u{0020}every\u{0020}time\u{0020}when\u{0020}carrying\u{0020}out\u{0020}the\u{0020}escort\u{0020}mission,\u{0020}Tenten\u{0020}can\u{0020}always\u{0020}soothe\u{0020}the\u{0020}civilians\u{0020}well.\n\nCivilian\u{0020}emotions\u{0020}reassured\u{0020}the\u{0020}civilians\u{0020}who\u{0020}had\u{0020}just\u{0020}endured\u{0020}the\u{0020}attack\u{0020}of\u{0020}Sin\u{0020}and\u{0020}were\u{0020}mentally\u{0020}unstable.\n\nAfter\u{0020}all,\u{0020}Tenten\u{0020}herself\u{0020}is\u{0020}just\u{0020}a\u{0020}slightly\u{0020}older\u{0020}child.\u{0020}In\u{0020}such\u{0020}an\u{0020}era,\u{0020}perhaps\u{0020}a\u{0020}smile\u{0020}is\u{0020}a\u{0020}privilege\u{0020}of\u{0020}children.", "0", "0", "0", "0", 11019, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}选择让还在学院中学习的学生组成新的驾驶员小队在全球范围内都是首例。\u{1000}\u{1000}但是在人类对抗原罪的过程中，已经制造了不知道多少\"首例\"了。\u{1000}\u{1000}而对于天天来说，当得知被选中加入雏鹰的那一刻，她的内心是激动又高兴，甚至亲自下厨做了一大堆杯子蛋糕送给当时的同学和老师。然后当天就收拾了行李去雏鹰小队报道。\u{1000}\u{1000}在雏鹰小队中，天天永远是最有活力的那个。其队长卡莲是如此评价她的：\u{1000}\u{1000}\"天天就像太阳一样充满活力，周围人也不知不觉会被她的笑容所感染。\"\u{1000}\u{1000}用笑容感染他人成为了天天第二个重要的天赋。\u{1000}雏鹰小队的任务通常只是在后方进行战场援助，其中有一项重要的任务就是护送平民。而每次进行护送任务时，天天总能很好地安抚\u{1000}\u{1000}平民情绪，让刚刚经受原罪攻击而心神不稳的平民们刚到安心。\u{1000}\u{1000}不过说到底，天天自己也只是一个大一点的孩子，在这样的时代中，笑容也许是孩子的特权吧。"},
[611904] = {611904, 2000, "\u{0020}\u{0020}What\u{0020}I\u{0020}like\u{0020}the\u{0020}most\u{0020}is\u{0020}the\u{0020}meal\u{0020}cooked\u{0020}by\u{0020}my\u{0020}father\u{0020}and\u{0020}the\u{0020}smiles\u{0020}of\u{0020}the\u{0020}guests\u{0020}when\u{0020}they\u{0020}are\u{0020}having\u{0020}meals.\n\nWhat\u{0020}I\u{0020}hate\u{0020}the\u{0020}most\u{0020}is\u{0020}the\u{0020}suffering\u{0020}brought\u{0020}by\u{0020}Sin\u{0020}and\u{0020}the\u{0020}news\u{0020}of\u{0020}their\u{0020}deaths.\n\nHowever,\u{0020}it\u{0020}doesn't\u{0020}matter\u{0020}anymore\u{0020}because\u{0020}I\u{0020}have\u{0020}grown\u{0020}up!\n\nI\u{0020}am\u{0020}already\u{0020}a\u{0020}mature\u{0020}driver.\n\nI\u{0020}will\u{0020}protect\u{0020}everyone's\u{0020}smiles\u{0020}and\u{0020}happiness.\n\n\"Navigator!\u{0020}How\u{0020}about\u{0020}having\u{0020}burger\u{0020}patties\u{0020}for\u{0020}dinner\u{0020}tonight?\"\n\nThe\u{0020}distorted\u{0020}and\u{0020}deformed\u{0020}body\u{0020}caused\u{0020}by\u{0020}Sin\u{0020}is\u{0020}embedded\u{0020}in\u{0020}the\u{0020}building,\n\nThe\u{0020}culprit\u{0020}was\u{0020}the\u{0020}hammer\u{0020}in\u{0020}the\u{0020}girl's\u{0020}hand.\n\nShe\u{0020}raised\u{0020}her\u{0020}head,\u{0020}looking\u{0020}past\u{0020}the\u{0020}weapon,\u{0020}past\u{0020}the\u{0020}Sin\u{0020}stuck\u{0020}to\u{0020}the\u{0020}building,\u{0020}and\u{0020}looked\u{0020}at\u{0020}the\u{0020}figure\u{0020}in\u{0020}the\u{0020}sky,\n\n\"Of\u{0020}course,\u{0020}they're\u{0020}not\u{0020}made\u{0020}with\u{0020}Sin.\"", "0", "0", "0", "0", 11019, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}我最喜欢的，\u{1000}\u{1000}是爸爸做的饭和客人们吃饭时的笑容。\u{1000}\u{1000}我最讨厌的，\u{1000}\u{1000}是原罪带来的苦难和他们死亡的讯息。\u{1000}\u{1000}不过已经没关系了，因为我已经长大了！\u{1000}\u{1000}我已经是一名成熟的驾驶员了，\u{1000}\u{1000}我会保护大家的笑容和幸福。\u{1000}\u{1000}\"领航！今天晚上吃汉堡肉怎么样？\"\u{1000}\u{1000}原罪扭曲了的，受到挤压而变形的身体嵌入大楼，\u{1000}\u{1000}而罪魁祸首则是少女手中的锤子，\u{1000}\u{1000}她抬起头，视线越过武器，越过大楼上粘住了的原罪，望向了天空中的身影，\u{1000}\u{1000}\"当然，不是用原罪做的肉饼啦。\""},
[612000] = {612000, 0, "[Name]\u{0020}Caroline\n[B-Day]\u{0020}June\u{0020}14\n[Compatability\u{0020}Rate]\u{0020}89％\n[Height]\u{0020}35m\n[Squad]\u{0020}Iron\u{0020}Crow\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Photography;\u{0020}walking;\u{0020}snacks", "0", "0", "0", "0", 11020, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[612001] = {612001, 100, "\u{0020}\u{0020}When\u{0020}organizing\u{0020}the\u{0020}files,\u{0020}we\u{0020}almost\u{0020}forgot\u{0020}this\u{0020}driver\u{0020}with\u{0020}excellent\u{0020}combat\u{0020}capabilities.\u{0020}Thanks\u{0020}to\u{0020}the\u{0020}reminder\u{0020}of\u{0020}the\u{0020}captain\u{0020}of\u{0020}Iron\u{0020}Crow,\u{0020}we\u{0020}added\u{0020}Caroline's\u{0020}file.\n\nCaroline\u{0020}is\u{0020}a\u{0020}rare\u{0020}\"normal\u{0020}person\"\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}and\u{0020}even\u{0020}in\u{0020}the\u{0020}entire\u{0020}AEGIS.\u{0020}She\u{0020}has\u{0020}neither\u{0020}past\u{0020}events\u{0020}like\u{0020}the\u{0020}dusk\u{0020}nor\u{0020}strange\u{0020}personalities\u{0020}like\u{0020}some\u{0020}drivers.\u{0020}When\u{0020}most\u{0020}people\u{0020}mention\u{0020}her\u{0020}name,\u{0020}what\u{0020}emerges\u{0020}in\u{0020}their\u{0020}minds\u{0020}is\u{0020}an\u{0020}ordinary\u{0020}and\u{0020}enthusiastic\u{0020}girl.\n\nHer\u{0020}\"ordinariness\"\u{0020}makes\u{0020}her\u{0020}unable\u{0020}to\u{0020}turn\u{0020}a\u{0020}blind\u{0020}eye\u{0020}to\u{0020}the\u{0020}behaviors\u{0020}of\u{0020}individual\u{0020}eccentrics\u{0020}in\u{0020}some\u{0020}cases.\u{0020}On\u{0020}some\u{0020}occasions,\u{0020}she\u{0020}always\u{0020}can't\u{0020}help\u{0020}loudly\u{0020}speaking\u{0020}out\u{0020}things\u{0020}that\u{0020}she\u{0020}finds\u{0020}strange\u{0020}but\u{0020}are\u{0020}normal\u{0020}for\u{0020}others.\n\nThe\u{0020}ordinary\u{0020}her\u{0020}couldn't\u{0020}accept\u{0020}those\u{0020}strange\u{0020}behaviors\u{0020}and\u{0020}thus\u{0020}became\u{0020}an\u{0020}outlier\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch.", "0", "0", "0", "0", 11020, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[612002] = {612002, 500, "\u{0020}\u{0020}As\u{0020}a\u{0020}member\u{0020}of\u{0020}\"Iron\u{0020}Crow\",\u{0020}Caroline's\u{0020}first\u{0020}meeting\u{0020}with\u{0020}her\u{0020}captain,\u{0020}Lepani,\u{0020}was\u{0020}actually\u{0020}in\u{0020}the\u{0020}primary\u{0020}school\u{0020}they\u{0020}attended\u{0020}-\u{0020}in\u{0020}other\u{0020}words,\u{0020}Caroline\u{0020}and\u{0020}the\u{0020}captain\u{0020}of\u{0020}Iron\u{0020}Crow\u{0020}were\u{0020}once\u{0020}classmates.\n\nWhen\u{0020}Caroline\u{0020}was\u{0020}in\u{0020}primary\u{0020}school,\u{0020}she\u{0020}was\u{0020}taken\u{0020}care\u{0020}of\u{0020}by\u{0020}Lepani\u{0020}many\u{0020}times.\u{0020}This\u{0020}incident\u{0020}became\u{0020}an\u{0020}important\u{0020}reason\u{0020}for\u{0020}Caroline\u{0020}to\u{0020}join\u{0020}\"Iron\u{0020}Crow\"\u{0020}later.\u{0020}However,\u{0020}Lepani\u{0020}herself\u{0020}has\u{0020}no\u{0020}impression\u{0020}of\u{0020}this\u{0020}matter\u{0020}and\u{0020}has\u{0020}not\u{0020}remembered\u{0020}that\u{0020}Caroline\u{0020}was\u{0020}her\u{0020}classmate\u{0020}until\u{0020}now.\n\nCaroline\u{0020}was\u{0020}selected\u{0020}into\u{0020}the\u{0020}list\u{0020}of\u{0020}reserve\u{0020}members\u{0020}of\u{0020}\"Iron\u{0020}Crow\"\u{0020}because\u{0020}she\u{0020}performed\u{0020}well\u{0020}during\u{0020}her\u{0020}time\u{0020}as\u{0020}a\u{0020}driver,\u{0020}completed\u{0020}many\u{0020}difficult\u{0020}tasks,\u{0020}and\u{0020}had\u{0020}excellent\u{0020}psychological\u{0020}quality.\n\nWhen\u{0020}Lepani\u{0020}was\u{0020}selecting\u{0020}members\u{0020}of\u{0020}\"Iron\u{0020}Crow\",\u{0020}due\u{0020}to\u{0020}the\u{0020}negligence\u{0020}of\u{0020}the\u{0020}staff,\u{0020}Caroline's\u{0020}information\u{0020}was\u{0020}not\u{0020}in\u{0020}the\u{0020}list\u{0020}handed\u{0020}to\u{0020}Lepani.\u{0020}If\u{0020}Lepani\u{0020}had\u{0020}not\u{0020}noticed\u{0020}that\u{0020}the\u{0020}number\u{0020}of\u{0020}people\u{0020}on\u{0020}the\u{0020}information\u{0020}did\u{0020}not\u{0020}match\u{0020}the\u{0020}originally\u{0020}scheduled\u{0020}number,\u{0020}Caroline\u{0020}might\u{0020}have\u{0020}missed\u{0020}the\u{0020}chance\u{0020}to\u{0020}join\u{0020}\"Iron\u{0020}Crow\".\n\nWhat\u{0020}Lepani\u{0020}values\u{0020}is\u{0020}Caroline's\u{0020}qualifications\u{0020}that\u{0020}are\u{0020}easy\u{0020}to\u{0020}ignore.\u{0020}In\u{0020}Lepani's\u{0020}opinion,\u{0020}the\u{0020}\"Iron\u{0020}Crow\"\u{0020}he\u{0020}wants\u{0020}to\u{0020}establish\u{0020}needs\u{0020}special\u{0020}talents\u{0020}like\u{0020}Caroline\u{0020}very\u{0020}much.\u{0020}Therefore,\u{0020}Caroline,\u{0020}with\u{0020}her\u{0020}rich\u{0020}combat\u{0020}experience\u{0020}and\u{0020}the\u{0020}trait\u{0020}of\u{0020}being\u{0020}\"not\u{0020}very\u{0020}noticeable\",\u{0020}became\u{0020}the\u{0020}first\u{0020}driver\u{0020}to\u{0020}receive\u{0020}an\u{0020}invitation\u{0020}from\u{0020}\"Iron\u{0020}Crow\".\n\nCaroline,\u{0020}who\u{0020}accepted\u{0020}the\u{0020}invitation,\u{0020}hesitated\u{0020}at\u{0020}first\u{0020}about\u{0020}whether\u{0020}to\u{0020}leave\u{0020}the\u{0020}original\u{0020}team.\u{0020}But\u{0020}after\u{0020}having\u{0020}a\u{0020}private\u{0020}discussion\u{0020}with\u{0020}Lepani\u{0020}for\u{0020}a\u{0020}while,\u{0020}she\u{0020}accepted\u{0020}Lepani's\u{0020}invitation\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}Iron\u{0020}Crow.\n\n\"The\u{0020}Dual\u{0020}Swords\u{0020}of\u{0020}Dual\u{0020}Ponytail\".\u{0020}She,\u{0020}who\u{0020}originally\u{0020}had\u{0020}no\u{0020}sense\u{0020}of\u{0020}presence,\u{0020}gradually\u{0020}had\u{0020}her\u{0020}own\u{0020}nickname\u{0020}after\u{0020}becoming\u{0020}\"Iron\u{0020}Crow\",\u{0020}but\u{0020}she\u{0020}herself\u{0020}didn't\u{0020}like\u{0020}this\u{0020}nickname\u{0020}very\u{0020}much.\n\n\"Calling\u{0020}me\u{0020}'Line-line'\u{0020}and\u{0020}'Little\u{0020}Ponytail'\u{0020}were\u{0020}already\u{0020}weird\u{0020}enough.\u{0020}What's\u{0020}with\u{0020}this\u{0020}'The\u{0020}Dual\u{0020}Swords\u{0020}of\u{0020}Dual\u{0020}Ponytail'!\u{0020}It's\u{0020}so\u{0020}shameful!\u{0020}That's\u{0020}what\u{0020}I\u{0020}think!\"\n\nIn\u{0020}fact,\u{0020}everyone\u{0020}thinks\u{0020}it's\u{0020}quite\u{0020}cool...\u{0020}probably.", "0", "0", "0", "0", 11020, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[612003] = {612003, 1000, "\u{0020}Lepani\u{0020}once\u{0020}worried\u{0020}whether\u{0020}letting\u{0020}Caroline\u{0020}leave\u{0020}the\u{0020}original\u{0020}team\u{0020}would\u{0020}hurt\u{0020}the\u{0020}relationship\u{0020}between\u{0020}Caroline\u{0020}and\u{0020}her\u{0020}companions.\u{0020}Surprisingly,\u{0020}after\u{0020}leaving,\u{0020}Caroline\u{0020}still\u{0020}maintained\u{0020}a\u{0020}good\u{0020}personal\u{0020}relationship\u{0020}with\u{0020}her\u{0020}previous\u{0020}companions.\n\nWhen\u{0020}she\u{0020}left\u{0020}the\u{0020}team,\u{0020}she\u{0020}explained\u{0020}to\u{0020}her\u{0020}companions\u{0020}that\u{0020}the\u{0020}main\u{0020}reason\u{0020}she\u{0020}joined\u{0020}Iron\u{0020}Crow\u{0020}was\u{0020}to\u{0020}repay\u{0020}Lepani\u{0020}for\u{0020}the\u{0020}care\u{0020}she\u{0020}had\u{0020}received\u{0020}from\u{0020}her\u{0020}at\u{0020}the\u{0020}beginning\u{0020}-\u{0020}although\u{0020}the\u{0020}latter\u{0020}had\u{0020}no\u{0020}impression\u{0020}of\u{0020}this\u{0020}matter\u{0020}at\u{0020}all.\n\nOn\u{0020}the\u{0020}other\u{0020}hand,\u{0020}during\u{0020}her\u{0020}contact\u{0020}with\u{0020}Lepani,\u{0020}Caroline\u{0020}gradually\u{0020}discovered\u{0020}that\u{0020}this\u{0020}seemingly\u{0020}gentle\u{0020}and\u{0020}delicate\u{0020}girl\u{0020}also\u{0020}had\u{0020}her\u{0020}own\u{0020}unreliable\u{0020}side.\u{0020}She\u{0020}believed\u{0020}that\u{0020}Lepani\u{0020}desperately\u{0020}needed\u{0020}someone\u{0020}like\u{0020}herself\u{0020}with\u{0020}\"common\u{0020}sense\"\u{0020}to\u{0020}assist\u{0020}her.\n\n\"If\u{0020}I\u{0020}refused\u{0020}her\u{0020}when\u{0020}the\u{0020}captain\u{0020}needed\u{0020}me,\u{0020}wouldn't\u{0020}that\u{0020}be\u{0020}too\u{0020}excessive?\u{0020}Moreover,\u{0020}I'm\u{0020}also\u{0020}very\u{0020}happy\u{0020}when\u{0020}I'm\u{0020}with\u{0020}the\u{0020}captain.\u{0020}If\u{0020}I'm\u{0020}with\u{0020}her,\u{0020}maybe\u{0020}I'll\u{0020}encounter\u{0020}many\u{0020}pleasant\u{0020}things.\u{0020}That's\u{0020}what\u{0020}I\u{0020}think!\"", "0", "0", "0", "0", 11020, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[612004] = {612004, 2000, "\u{0020}\u{0020}Ordinariness\u{0020}by\u{0020}no\u{0020}means\u{0020}implies\u{0020}mediocrity,\u{0020}nor\u{0020}does\u{0020}it\u{0020}represent\u{0020}regret\u{0020}or\u{0020}misfortune.\n\nPerhaps\u{0020}becoming\u{0020}a\u{0020}dazzling\u{0020}person\u{0020}is\u{0020}the\u{0020}dream\u{0020}of\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}people,\u{0020}but\u{0020}Caroline\u{0020}does\u{0020}not\u{0020}have\u{0020}such\u{0020}a\u{0020}dream.\n\nEven\u{0020}if\u{0020}the\u{0020}impression\u{0020}given\u{0020}is\u{0020}always\u{0020}faint,\u{0020}she\u{0020}doesn't\u{0020}mind\u{0020}at\u{0020}all.\n\n\"Because...\u{0020}In\u{0020}this\u{0020}world,\u{0020}there\u{0020}are\u{0020}surely\u{0020}some\u{0020}people\u{0020}who\u{0020}are\u{0020}destined\u{0020}not\u{0020}to\u{0020}be\u{0020}as\u{0020}dazzling\u{0020}as\u{0020}'heroes'...\"\n\nThe\u{0020}Haze\u{0020}is\u{0020}slowly\u{0020}dissipating,\u{0020}and\u{0020}the\u{0020}bright\u{0020}moonlight\u{0020}flows\u{0020}through\u{0020}the\u{0020}layers\u{0020}of\u{0020}thin\u{0020}mist,\u{0020}bathing\u{0020}the\u{0020}hazy\u{0020}giantess\u{0020}in\u{0020}the\u{0020}fog\u{0020}in\u{0020}a\u{0020}ray\u{0020}of\u{0020}light.\n\nThe\u{0020}young\u{0020}girl\u{0020}seemed\u{0020}like\u{0020}the\u{0020}protagonist\u{0020}on\u{0020}the\u{0020}stage\u{0020}play,\u{0020}reciting\u{0020}her\u{0020}inner\u{0020}monologue.\n\nAnd\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}those\u{0020}insignificant\u{0020}people\u{0020}that\u{0020}even\u{0020}we\u{0020}can\u{0020}also\u{0020}shine\u{0020}our\u{0020}own\u{0020}light\u{0020}somewhere,\u{0020}even\u{0020}on\u{0020}a\u{0020}stage\u{0020}known\u{0020}only\u{0020}to\u{0020}ourselves.\n\n\"I\u{0020}am...\u{0020}thinking\u{0020}like\u{0020}this.\"", "0", "0", "0", "0", 11020, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[612100] = {612100, 0, "【Name】Skadi\n【B-Day】July\u{0020}5\n【Compatibility\u{0020}Rate】100%\n【Height】32m\n【Squad】Dunscaith\n【Affiliation】None\n【Interest】Want\u{0020}to\u{0020}create\u{0020}summer\u{0020}memories\u{0020}with\u{0020}everyone", "0", "0", "0", "0", 11021, "0", "0", "0", "0", 0, 1, "0", "0", "0"},
[612101] = {612101, 100, "After\u{0020}experiencing\u{0020}the\u{0020}synaesthesia\u{0020}rampage,\u{0020}Skadi\u{0020}reached\u{0020}a\u{0020}100%\u{0020}qualification\u{0020}rate\u{0020}during\u{0020}the\u{0020}physical\u{0020}examination,\u{0020}which\u{0020}is\u{0020}another\u{0020}significant\u{0020}finding,\u{0020}because\u{0020}all\u{0020}the\u{0020}current\u{0020}100%\u{0020}qualification\u{0020}rate\u{0020}drivers\u{0020}in\u{0020}AEGIS\u{0020}are\u{0020}constant\u{0020}at\u{0020}100%\u{0020}when\u{0020}they\u{0020}are\u{0020}first\u{0020}tested.\u{0020}Skadi's\u{0020}existence\u{0020}overturns\u{0020}the\u{0020}claim\u{0020}that\u{0020}100%\u{0020}of\u{0020}drivers\u{0020}are\u{0020}congenital.\u{0020}As\u{0020}the\u{0020}service\u{0020}time\u{0020}of\u{0020}the\u{0020}drivers\u{0020}gets\u{0020}longer,\u{0020}in\u{0020}order\u{0020}to\u{0020}survive\u{0020}better\u{0020}on\u{0020}the\u{0020}cruel\u{0020}battlefield,\u{0020}the\u{0020}body\u{0020}will\u{0020}spontaneously\u{0020}adapt\u{0020}to\u{0020}a\u{0020}higher\u{0020}qualification\u{0020}rate.\u{0020}Besides,\u{0020}AEGIS\u{0020}will\u{0020}also\u{0020}issue\u{0020}[Plans]\u{0020}to\u{0020}qualified\u{0020}drivers\u{0020}internally.\u{0020}Those\u{0020}drivers\u{0020}who\u{0020}passed\u{0020}the\u{0020}[Plans],\u{0020}their\u{0020}qualification\u{0020}rates\u{0020}have\u{0020}also\u{0020}been\u{0020}significantly\u{0020}improved.\u{0020}Similarly,\u{0020}there\u{0020}are\u{0020}also\u{0020}survivors\u{0020}who\u{0020}participated\u{0020}in\u{0020}the\u{0020}drug\u{0020}experiments\u{0020}in\u{0020}the\u{0020}laboratory,\u{0020}and\u{0020}methods\u{0020}such\u{0020}as\u{0020}[■■■■]\u{0020}constantly\u{0020}increase\u{0020}the\u{0020}qualification\u{0020}rate.\n\nHowever,\u{0020}the\u{0020}drivers\u{0020}cultivated\u{0020}through\u{0020}acquired\u{0020}reinforcement\u{0020}basically\u{0020}stagnate\u{0020}at\u{0020}the\u{0020}threshold\u{0020}of\u{0020}90%,\u{0020}and\u{0020}a\u{0020}few\u{0020}exceptional\u{0020}cases\u{0020}will\u{0020}also\u{0020}get\u{0020}stuck\u{0020}at\u{0020}99%.\n\nCloning\u{0020}technology\u{0020}can\u{0020}indeed\u{0020}cultivate\u{0020}100%\u{0020}drivers\u{0020}completely,\u{0020}but\u{0020}this\u{0020}is\u{0020}still\u{0020}caused\u{0020}congenitally.\n\nIs\u{0020}it\u{0020}because\u{0020}Skadi\u{0020}is\u{0020}a\u{0020}[suspected\u{0020}synaesthete]?\u{0020}Or\u{0020}is\u{0020}it\u{0020}related\u{0020}to\u{0020}the\u{0020}\"dreams\"\u{0020}they\u{0020}experienced?", "0", "0", "0", "0", 11021, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[612102] = {612102, 500, "It\u{0020}seems\u{0020}that\u{0020}Skadi\u{0020}is\u{0020}about\u{0020}to\u{0020}graduate\u{0020}from\u{0020}the\u{0020}state\u{0020}of\u{0020}chuunibyou...\u{0020}However,\u{0020}it\u{0020}has\u{0020}not\u{0020}completely\u{0020}transformed\u{0020}yet,\u{0020}which\u{0020}is\u{0020}quite\u{0020}concerning.\n\nBefore\u{0020}Skadi's\u{0020}synesthesia\u{0020}runaway,\u{0020}although\u{0020}she\u{0020}was\u{0020}the\u{0020}top\u{0020}combat\u{0020}force\u{0020}of\u{0020}Danube,\u{0020}by\u{0020}tracing\u{0020}her\u{0020}past,\u{0020}we\u{0020}easily\u{0020}understand\u{0020}that\u{0020}she\u{0020}was\u{0020}actually\u{0020}a\u{0020}fledgling\u{0020}wrapped\u{0020}in\u{0020}a\u{0020}bird\u{0020}shell.\u{0020}The\u{0020}extreme\u{0020}imbalance\u{0020}between\u{0020}the\u{0020}growth\u{0020}of\u{0020}her\u{0020}mentality\u{0020}and\u{0020}the\u{0020}growth\u{0020}of\u{0020}her\u{0020}strength\u{0020}is\u{0020}an\u{0020}extremely\u{0020}unhealthy\u{0020}growth\u{0020}pattern.\u{0020}She\u{0020}had\u{0020}better...\u{0020}be\u{0020}aware\u{0020}of\u{0020}the\u{0020}responsibility\u{0020}carried\u{0020}behind\u{0020}her\u{0020}powerful\u{0020}ability.\u{0020}Moon\u{0020}Corona\u{0020}cannot\u{0020}fall,\u{0020}because\u{0020}they\u{0020}have\u{0020}become\u{0020}the\u{0020}pillar\u{0020}of\u{0020}Danube.\n\nI\u{0020}originally\u{0020}thought\u{0020}that\u{0020}this\u{0020}\"uniqueness\"\u{0020}of\u{0020}hers\u{0020}would\u{0020}gradually\u{0020}converge\u{0020}as\u{0020}she\u{0020}grew\u{0020}older,\u{0020}but\u{0020}there\u{0020}is\u{0020}a\u{0020}group\u{0020}of\u{0020}people\u{0020}who\u{0020}dote\u{0020}on\u{0020}Skadi\u{0020}very\u{0020}much,\u{0020}preventing\u{0020}her\u{0020}from\u{0020}waking\u{0020}up.\u{0020}Perhaps\u{0020}the\u{0020}only\u{0020}person\u{0020}who\u{0020}can\u{0020}make\u{0020}her\u{0020}a\u{0020}little\u{0020}more\u{0020}normal\u{0020}is\u{0020}Lilith\u{0020}from\u{0020}the\u{0020}same\u{0020}team.\n\nBecoming\u{0020}a\u{0020}driver\u{0020}means\u{0020}constantly\u{0020}fighting\u{0020}against\u{0020}the\u{0020}original\u{0020}sin\u{0020}of\u{0020}danger.\u{0020}After\u{0020}experiencing\u{0020}battles\u{0020}of\u{0020}all\u{0020}sizes,\u{0020}even\u{0020}the\u{0020}most\u{0020}unrestrained\u{0020}personality\u{0020}will\u{0020}become\u{0020}heavy-hearted.\u{0020}Depression,\u{0020}insomnia,\u{0020}madness,\u{0020}and\u{0020}complex\u{0020}psychological\u{0020}symptoms\u{0020}follow\u{0020}one\u{0020}after\u{0020}another.\u{0020}Although\u{0020}AEGIS\u{0020}has\u{0020}gathered\u{0020}the\u{0020}best\u{0020}psychologists\u{0020}in\u{0020}the\u{0020}world,\u{0020}some\u{0020}drivers\u{0020}still\u{0020}can\u{0020}no\u{0020}longer\u{0020}go\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}after\u{0020}witnessing\u{0020}the\u{0020}death\u{0020}of\u{0020}their\u{0020}teammates.\n\nThe\u{0020}more\u{0020}naive\u{0020}a\u{0020}person\u{0020}is,\u{0020}the\u{0020}greater\u{0020}the\u{0020}price\u{0020}they\u{0020}have\u{0020}to\u{0020}pay\u{0020}for\u{0020}a\u{0020}crushing\u{0020}defeat.\u{0020}If\u{0020}they\u{0020}do\u{0020}not\u{0020}have\u{0020}the\u{0020}due\u{0020}awareness,\u{0020}there\u{0020}is\u{0020}a\u{0020}danger\u{0020}of\u{0020}collapse\u{0020}at\u{0020}any\u{0020}time.\n\nThey\u{0020}did\u{0020}not\u{0020}go\u{0020}through\u{0020}the\u{0020}selection\u{0020}of\u{0020}the\u{0020}academy\u{0020}and\u{0020}the\u{0020}screening\u{0020}of\u{0020}the\u{0020}\"cradle\",\u{0020}and\u{0020}relied\u{0020}on\u{0020}their\u{0020}strong\u{0020}strength\u{0020}to\u{0020}reach\u{0020}the\u{0020}top\u{0020}of\u{0020}Danube.\u{0020}This\u{0020}also\u{0020}leads\u{0020}to\u{0020}the\u{0020}presence\u{0020}of\u{0020}people\u{0020}with\u{0020}\"personality\u{0020}crises\"\u{0020}in\u{0020}a\u{0020}top\u{0020}team.\u{0020}If\u{0020}a\u{0020}certain\u{0020}battle\u{0020}causes\u{0020}Lilith\u{0020}and\u{0020}Morgan\u{0020}Le\u{0020}Fay\u{0020}to\u{0020}no\u{0020}longer\u{0020}be\u{0020}able\u{0020}to\u{0020}go\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}or\u{0020}even\u{0020}die\u{0020}in\u{0020}action,\u{0020}I\u{0020}can\u{0020}conclude\u{0020}that\u{0020}the\u{0020}Moon\u{0020}Corona\u{0020}team\u{0020}will\u{0020}come\u{0020}to\u{0020}an\u{0020}end.\n\nSkadi,\u{0020}please\u{0020}grow\u{0020}up\u{0020}quickly.\u{0020}You\u{0020}are\u{0020}the\u{0020}\"chosen\u{0020}one\".", "0", "0", "0", "0", 11021, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[612103] = {612103, 1000, "In\u{0020}order\u{0020}to\u{0020}bring\u{0020}Skadi\u{0020}out\u{0020}of\u{0020}her\u{0020}world,\u{0020}I\u{0020}held\u{0020}the\u{0020}thought\u{0020}of\u{0020}\"Why\u{0020}not\u{0020}let\u{0020}her\u{0020}former\u{0020}partners\u{0020}persuade\u{0020}her.\"\u{0020}and\u{0020}visited\u{0020}the\u{0020}partners\u{0020}from\u{0020}the\u{0020}orphanage\u{0020}who\u{0020}had\u{0020}intersections\u{0020}with\u{0020}her.\n\nWant\u{0020}them\u{0020}to\u{0020}persuade\u{0020}Skadi\u{0020}-\u{0020}or\u{0020}rather,\u{0020}【Imagine\u{0020}Break】,\u{0020}shatter\u{0020}Skadi's\u{0020}current\u{0020}illusion\u{0020}and\u{0020}break\u{0020}through\u{0020}her\u{0020}psychological\u{0020}defense.\n\nBut\u{0020}I\u{0020}failed,\u{0020}completely\u{0020}failed.\n\nMost\u{0020}of\u{0020}their\u{0020}lives\u{0020}have\u{0020}been\u{0020}on\u{0020}the\u{0020}right\u{0020}track\u{0020}and\u{0020}seamlessly\u{0020}integrated\u{0020}into\u{0020}the\u{0020}lives\u{0020}of\u{0020}ordinary\u{0020}people...\u{0020}But\u{0020}regardless\u{0020}of\u{0020}whether\u{0020}they\u{0020}are\u{0020}male\u{0020}or\u{0020}female,\u{0020}regardless\u{0020}of\u{0020}occupation\u{0020}or\u{0020}circle,\u{0020}they\u{0020}all\u{0020}have\u{0020}a\u{0020}certain\u{0020}amount\u{0020}of\u{0020}guilt\u{0020}and\u{0020}regret\u{0020}for\u{0020}leaving\u{0020}Skadi\u{0020}at\u{0020}the\u{0020}beginning.\n\nEven\u{0020}some\u{0020}people\u{0020}left\u{0020}Skadi\u{0020}with\u{0020}the\u{0020}same\u{0020}mentality\u{0020}as\u{0020}me\u{0020}at\u{0020}the\u{0020}beginning,\u{0020}wanting\u{0020}to\u{0020}make\u{0020}Skadi\u{0020}graduate\u{0020}from\u{0020}\"chuunibyou\".\u{0020}Then,\u{0020}Skadi,\u{0020}who\u{0020}was\u{0020}alone,\u{0020}encountered\u{0020}the\u{0020}event\u{0020}that\u{0020}made\u{0020}her\u{0020}a\u{0020}【suspected\u{0020}empath】.\n\n——She\u{0020}truly\u{0020}vanished\u{0020}from\u{0020}everyone's\u{0020}world.\n\nWhat\u{0020}kind\u{0020}of\u{0020}position\u{0020}was\u{0020}Skadi\u{0020}in\u{0020}the\u{0020}hearts\u{0020}of\u{0020}the\u{0020}children\u{0020}in\u{0020}the\u{0020}orphanage?\u{0020}I\u{0020}think\u{0020}perhaps,\u{0020}during\u{0020}that\u{0020}period\u{0020}of\u{0020}time\u{0020}that\u{0020}is\u{0020}no\u{0020}longer\u{0020}investigable,\u{0020}she\u{0020}replaced\u{0020}the\u{0020}lost\u{0020}parents\u{0020}in\u{0020}everyone's\u{0020}hearts\u{0020}and\u{0020}became\u{0020}the\u{0020}leader\u{0020}leading\u{0020}everyone\u{0020}forward.\u{0020}Relying\u{0020}on\u{0020}talents\u{0020}beyond\u{0020}ordinary\u{0020}humans,\u{0020}she\u{0020}spread\u{0020}her\u{0020}wings\u{0020}to\u{0020}protect\u{0020}everyone.\n\nTherefore,\u{0020}her\u{0020}disappearance\u{0020}brought\u{0020}together\u{0020}everyone\u{0020}who\u{0020}had\u{0020}gone\u{0020}their\u{0020}separate\u{0020}ways\u{0020}at\u{0020}that\u{0020}time.\u{0020}Years\u{0020}later,\u{0020}when\u{0020}everyone\u{0020}found\u{0020}Skadi\u{0020}again,\u{0020}it\u{0020}was\u{0020}through\u{0020}various\u{0020}communication\u{0020}devices\u{0020}that\u{0020}they\u{0020}saw\u{0020}her\u{0020}galloping\u{0020}figure\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}the\u{0020}familiar\u{0020}three-stage\u{0020}laughter\u{0020}of\u{0020}\"Ha\u{0020}-\u{0020}Ha\u{0020}-\u{0020}Ha\".\n\nEven\u{0020}though\u{0020}they\u{0020}parted,\u{0020}Skadi\u{0020}is\u{0020}still\u{0020}the\u{0020}Queen\u{0020}of\u{0020}the\u{0020}Shadow\u{0020}Kingdom,\u{0020}still\u{0020}protecting,\u{0020}protecting\u{0020}this\u{0020}city,\u{0020}protecting\u{0020}them.\n\n——\u{0020}This\u{0020}is\u{0020}the\u{0020}situation,\u{0020}so\u{0020}how\u{0020}could\u{0020}I\u{0020}possibly\u{0020}persuade\u{0020}Skadi's\u{0020}fans\u{0020}to\u{0020}speak\u{0020}ill\u{0020}of\u{0020}Skadi.\n\nThe\u{0020}plan\u{0020}is\u{0020}thus\u{0020}put\u{0020}on\u{0020}hold\u{0020}for\u{0020}now.", "0", "0", "0", "0", 11021, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[612104] = {612104, 2000, "On\u{0020}the\u{0020}first\u{0020}day\u{0020}of\u{0020}Skadi's\u{0020}recovery,\u{0020}she\u{0020}visited\u{0020}the\u{0020}navigator.\n\nOn\u{0020}the\u{0020}second\u{0020}day\u{0020}of\u{0020}Skadi's\u{0020}recovery,\u{0020}did\u{0020}a\u{0020}test,\u{0020}and\u{0020}the\u{0020}physical\u{0020}aspect\u{0020}was\u{0020}still\u{0020}completely\u{0020}fine.Go\u{0020}to\u{0020}show\u{0020}off\u{0020}to\u{0020}the\u{0020}driver.\u{0020}On\u{0020}the\u{0020}third\u{0020}day\u{0020}of\u{0020}Skadi's\u{0020}recovery,\u{0020}she\u{0020}attempted\u{0020}transformation\u{0020}and\u{0020}succeeded.\u{0020}She\u{0020}empathized\u{0020}with\u{0020}the\u{0020}navigator.\n\nOn\u{0020}the\u{0020}fourth\u{0020}day\u{0020}of\u{0020}Skadi's\u{0020}recovery,\u{0020}she\u{0020}took\u{0020}on\u{0020}a\u{0020}low-difficulty\u{0020}task\u{0020}to\u{0020}test\u{0020}her\u{0020}skills\u{0020}and\u{0020}asked\u{0020}the\u{0020}navigator\u{0020}to\u{0020}accompany\u{0020}her\u{0020}on\u{0020}the\u{0020}attack.\u{0020}She\u{0020}empathized\u{0020}with\u{0020}the\u{0020}navigator.\n\nOn\u{0020}the\u{0020}fifth\u{0020}day\u{0020}of\u{0020}Skadi's\u{0020}recovery,\u{0020}go\u{0020}to\u{0020}play\u{0020}with\u{0020}the\u{0020}navigator.\u{0020}Empathize\u{0020}with\u{0020}the\u{0020}navigator.\n\n\u{0020}…\u{0020}…\u{0020}I\u{0020}know\u{0020}the\u{0020}reason\u{0020}for\u{0020}Skadi's\u{0020}recent\u{0020}changes.", "0", "0", "0", "0", 11021, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
