[612201] = {612201, 100, "\u{3000}\u{3000}The\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}a\u{0020}realm\u{0020}where\u{0020}heroines\u{0020}gather\u{0020}and\u{0020}among\u{0020}them,\n\n\u{3000}\u{3000}Her\u{0020}Majesty\u{0020}stands\u{0020}as\u{0020}an\u{0020}anomaly\u{0020}among\u{0020}anomalies.\u{0020}After\u{0020}all,\u{0020}she\u{0020}isn't\u{0020}really\u{0020}a\u{0020}Heroine.\u{0020}With\u{0020}a\u{0020}genuine\u{0020}Skadi\u{0020}already\u{0020}existing\u{0020}in\u{0020}this\u{0020}universe,\u{0020}this\u{0020}\"counterfeit\"\u{0020}should've\u{0020}slunk\u{0020}away\u{0020}in\u{0020}shame;\u{0020}that's\u{0020}how\u{0020}it\u{0020}ought\u{0020}to\u{0020}be.\n\n\u{3000}\u{3000}But\u{0020}what\u{0020}she\u{0020}can't\u{0020}tolerate\u{0020}is\u{0020}the\u{0020}fact\u{0020}that\u{0020}the\u{0020}real\u{0020}Skadi,\u{0020}though\u{0020}technically\u{0020}the\u{0020}same\u{0020}age\u{0020}now,\u{0020}perished\u{0020}before\u{0020}her\u{0020}mind\u{0020}or\u{0020}body\u{0020}could\u{0020}fully\u{0020}mature.\u{0020}This\u{0020}is\u{0020}indisputable.\u{0020}Skadi\u{0020}herself\u{0020}admitted\u{0020}she's\u{0020}already\u{0020}witnessed\u{0020}the\u{0020}end.\n\n\u{3000}\u{3000}Unforgivable.\u{0020}On\u{0020}her\u{0020}way\u{0020}home,\u{0020}Her\u{0020}Majesty\u{0020}stewed.\u{0020}That\u{0020}Navigator\u{0020}promised\u{0020}to\u{0020}protect\u{0020}Skadi,\u{0020}yet\u{0020}the\u{0020}world\u{0020}still\u{0020}met\u{0020}ruin.\n\n\u{3000}\u{3000}[...Maybe\u{0020}I\u{0020}should\u{0020}help\u{0020}him?]\u{0020}The\u{0020}thought\u{0020}crossed\u{0020}her\u{0020}mind.", "0", "0", "0", "0", 11022, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[612202] = {612202, 500, "\u{3000}\u{3000}As\u{0020}one\u{0020}of\u{0020}Skadi's\u{0020}potential\u{0020}futures,\u{0020}Her\u{0020}Majesty\u{0020}has\u{0020}reached\u{0020}the\u{0020}pinnacle\u{0020}of\u{0020}unshackled\u{0020}liberty\u{0020}among\u{0020}all\u{0020}Skadi\u{0020}variants,\u{0020}paired\u{0020}with\u{0020}a\u{0020}mind\u{0020}that\u{0020}operates\u{0020}on\u{0020}pure\u{0020}whimsy.\u{0020}She's\u{0020}the\u{0020}type\u{0020}to\u{0020}sprint\u{0020}headlong\u{0020}toward\u{0020}the\u{0020}next\u{0020}goal\u{0020}without\u{0020}hesitation.\n\n\u{3000}\u{3000}For\u{0020}example,\u{0020}if\u{0020}she\u{0020}decides\u{0020}to\u{0020}aid\u{0020}you\u{0020}(still\u{0020}trapped\u{0020}in\u{0020}your\u{0020}time-looping\u{0020}dilemma),\u{0020}she'll\u{0020}manifest\u{0020}somehow.\n\n\u{3000}\u{3000}\"So,\u{0020}long\u{0020}story\u{0020}short,\u{0020}after\u{0020}all\u{0020}sorts\u{0020}of\u{0020}nonsense,\u{0020}here\u{0020}I\u{0020}am!\"\u{0020}She\u{0020}clapped\u{0020}me\u{0020}on\u{0020}the\u{0020}shoulder.\n\n\u{3000}\u{3000}\"You\u{0020}expect\u{0020}me\u{0020}to\u{0020}believe\u{0020}you're\u{0020}a\u{0020}character\u{0020}from\u{0020}Skadi's\u{0020}novel\u{0020}Dunscaith\u{0020}Chronicles,\u{0020}who\u{0020}crossed\u{0020}into\u{0020}reality\u{0020}thanks\u{0020}to\u{0020}your\u{0020}superpowers?\"\u{0020}Meeting\u{0020}a\u{0020}weirdo\u{0020}who\u{0020}claimed\u{0020}herself\u{0020}as\u{0020}a\u{0020}\"future\u{0020}Skadi\"\u{0020}first\u{0020}thing\u{0020}in\u{0020}the\u{0020}morning\u{0020}left\u{0020}me...\u{0020}conflicted.\n\n\u{3000}\u{3000}\"How\u{0020}cruel!\u{0020}Even\u{0020}if\u{0020}you\u{0020}forgot\u{0020}the\u{0020}details,\u{0020}I\u{0020}must've\u{0020}appeared\u{0020}in\u{0020}your\u{0020}dreams,\u{0020}right?\"\u{0020}She\u{0020}staggered\u{0020}back,\u{0020}feigning\u{0020}devastation.\u{0020}\"Wait,\u{0020}if\u{0020}you've\u{0020}forgotten\u{0020}that\u{0020}much,\u{0020}then\u{0020}you've\u{0020}also\u{0020}forgotten\u{0020}your\u{0020}promise\u{0020}to\u{0020}'protect\u{0020}Skadi\u{0020}no\u{0020}matter\u{0020}what,'\u{0020}haven't\u{0020}you?\u{0020}No\u{0020}wonder\u{0020}things\u{0020}turned\u{0020}out\u{0020}like\u{0020}this!\"\n\n\u{3000}\u{3000}\"...Sure,\u{0020}let's\u{0020}go\u{0020}with\u{0020}that.\u{0020}So\u{0020}why\u{0020}are\u{0020}you\u{0020}here?\"\u{0020}I\u{0020}sighed.\u{0020}Probably\u{0020}just\u{0020}another\u{0020}of\u{0020}Skadi's\u{0020}like-minded\u{0020}friends.\u{0020}What\u{0020}was\u{0020}going\u{0020}on\u{0020}now?\u{0020}Was\u{0020}this\u{0020}some\u{0020}prank\u{0020}scripted\u{0020}by\u{0020}her?\n\n\u{3000}\u{3000}\"Get\u{0020}me\u{0020}a\u{0020}real\u{0020}ID\u{0020}from\u{0020}that\u{0020}Dr.\u{0020}Stephanie.\"\n\n\u{3000}\u{3000}\"...\"\n\n\u{3000}\u{3000}Later,\u{0020}after\u{0020}verification,\u{0020}Dr.\u{0020}Stephanie\u{0020}confirmed\u{0020}it.\u{0020}The\u{0020}girl\u{0020}calling\u{0020}herself\u{0020}\"Skadi:\u{0020}Her\u{0020}Majesty\u{0020}Mode\"\u{0020}has\u{0020}no\u{0020}records.\u{0020}No\u{0020}past.\u{0020}As\u{0020}if\u{0020}she\u{0020}materialized\u{0020}from\u{0020}thin\u{0020}air.", "0", "0", "0", "0", 11022, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[612203] = {612203, 1000, "\u{3000}\u{3000}\"Seems\u{0020}I\u{0020}came\u{0020}at\u{0020}a\u{0020}bad\u{0020}time.\u{0020}Nothing\u{0020}but\u{0020}small\u{0020}fry\u{0020}here.\u{0020}Where's\u{0020}the\u{0020}final\u{0020}boss?\u{0020}Not\u{0020}even\u{0020}a\u{0020}mid-tier\u{0020}villain\u{0020}in\u{0020}sight.\"\n\n\u{3000}\u{3000}\"Final\u{0020}boss...?\"\u{0020}That\u{0020}unsettled\u{0020}me.\n\n\u{3000}\u{3000}\"Oh?\u{0020}Curious?\"\u{0020}Her\u{0020}grin\u{0020}turned\u{0020}sly;\u{0020}clearly,\u{0020}she\u{0020}baited\u{0020}me\u{0020}on\u{0020}purpose.\u{0020}\"But\u{0020}I\u{0020}can't\u{0020}say\u{0020}more.\u{0020}It\u{0020}concerned\u{0020}the\u{0020}[Star\u{0020}Monarch]'s\u{0020}plans.\"\u{0020}\"I\u{0020}should\u{0020}head\u{0020}back\u{0020}now.\u{0020}Next\u{0020}time,\u{0020}I'll\u{0020}bring\u{0020}souvenirs.\"\n\n\u{3000}\u{3000}With\u{0020}that,\u{0020}she\u{0020}dissolved\u{0020}into\u{0020}light\u{0020}dots\u{0020}before\u{0020}my\u{0020}eyes.\n\n\u{3000}\u{3000}...Next\u{0020}time\u{0020}we\u{0020}meet,\u{0020}it\u{0020}would\u{0020}likely\u{0020}be\u{0020}that\u{0020}\"final\u{0020}boss\"\u{0020}battle.\n\n\u{3000}\u{3000}And\u{0020}just\u{0020}like\u{0020}that,\u{0020}my\u{0020}life\u{0020}returned\u{0020}to\u{0020}normal.", "0", "0", "0", "0", 11022, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
