[612301] = {612301, 100, "\u{0020}\u{0020}From\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nKyushu\u{0020}Ping\u{0020}Xin's\u{0020}active\u{0020}driver,\u{0020}Xiaomeng,\u{0020}is\u{0020}agile\u{0020}and\u{0020}proficient\u{0020}in\u{0020}various\u{0020}weapons\u{0020}and\u{0020}martial\u{0020}arts,\u{0020}especially\u{0020}good\u{0020}at\u{0020}fist\u{0020}and\u{0020}kick\u{0020}skills.\u{0020}Because\u{0020}of\u{0020}her\u{0020}amazing\u{0020}potential,\u{0020}she\u{0020}was\u{0020}given\u{0020}the\u{0020}title\u{0020}\"Martialist\",\u{0020}but\u{0020}why\u{0020}did\u{0020}she\u{0020}refuse\u{0020}to\u{0020}think?\n\nIn\u{0020}the\u{0020}\"Academy\",\u{0020}martial\u{0020}arts\u{0020}practitioners\u{0020}tend\u{0020}to\u{0020}be\u{0020}stubborn\u{0020}and\u{0020}not\u{0020}good\u{0020}at\u{0020}thinking\u{0020}is\u{0020}the\u{0020}norm.\u{0020}However,\u{0020}only\u{0020}Xiaomeng,\u{0020}and\u{0020}only\u{0020}Xiaomeng,\u{0020}achieved\u{0020}selective\u{0020}refusal\u{0020}to\u{0020}think.\n\nShe\u{0020}voluntarily\u{0020}entrusted\u{0020}herself\u{0020}completely\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}to\u{0020}her\u{0020}companions,\u{0020}and\u{0020}transformed\u{0020}herself\u{0020}into\u{0020}a\u{0020}weapon,\u{0020}rushing\u{0020}towards\u{0020}her\u{0020}enemies\u{0020}without\u{0020}hesitation.\n\nAlthough\u{0020}being\u{0020}trusted\u{0020}by\u{0020}her\u{0020}like\u{0020}this\u{0020}is\u{0020}a\u{0020}good\u{0020}thing,\u{0020}it\u{0020}also\u{0020}makes\u{0020}one\u{0020}feel\u{0020}the\u{0020}weight\u{0020}of\u{0020}trust...", "0", "0", "0", "0", 11023, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[612302] = {612302, 500, "\u{0020}\u{0020}From\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nI\u{0020}completely\u{0020}misjudged\u{0020}Xiaomeng.\n\nAt\u{0020}first,\u{0020}I\u{0020}thought\u{0020}that\u{0020}Xiaomeng's\u{0020}refusal\u{0020}to\u{0020}think\u{0020}was\u{0020}simply\u{0020}due\u{0020}to\u{0020}her\u{0020}inability\u{0020}to\u{0020}use\u{0020}her\u{0020}brain.\u{0020}She\u{0020}was\u{0020}aware\u{0020}of\u{0020}her\u{0020}weaknesses\u{0020}and\u{0020}thus\u{0020}relied\u{0020}on\u{0020}her\u{0020}companions.\u{0020}That\u{0020}was\u{0020}not\u{0020}a\u{0020}bad\u{0020}approach.\n\nRecently,\u{0020}based\u{0020}on\u{0020}my\u{0020}observation,\u{0020}I\u{0020}found\u{0020}that\u{0020}she\u{0020}simply\u{0020}enjoys\u{0020}being\u{0020}\"relied\u{0020}upon\"\u{0020}by\u{0020}others...\u{0020}No,\u{0020}her\u{0020}symptom\u{0020}is\u{0020}more\u{0020}serious\u{0020}than\u{0020}this:\u{0020}she\u{0020}has\u{0020}obtained\u{0020}something\u{0020}from\u{0020}this\u{0020}behavior\u{0020}of\u{0020}\"being\u{0020}relied\u{0020}upon\"\u{0020}that\u{0020}supports\u{0020}her\u{0020}to\u{0020}live\u{0020}on,\u{0020}is\u{0020}it\u{0020}a\u{0020}sense\u{0020}of\u{0020}satisfaction?\u{0020}Pleasure?...\u{0020}Or\u{0020}is\u{0020}it\u{0020}the\u{0020}sense\u{0020}of\u{0020}existence\u{0020}value?\n\nI\u{0020}finally\u{0020}understood\u{0020}why\u{0020}Xiaomeng's\u{0020}mother\u{0020}asked\u{0020}me\u{0020}to\u{0020}be\u{0020}careful\u{0020}of\u{0020}her\u{0020}before\u{0020}the\u{0020}trip,\u{0020}and\u{0020}also\u{0020}understood\u{0020}what\u{0020}Xiaomeng\u{0020}was\u{0020}lacking:\n\n\"moral\u{0020}character\"\n\nA\u{0020}strong\u{0020}person\u{0020}needs\u{0020}to\u{0020}have\u{0020}a\u{0020}strong\u{0020}soul.\u{0020}That\u{0020}soul\u{0020}is\u{0020}warm,\u{0020}the\u{0020}will\u{0020}is\u{0020}dazzling,\u{0020}and\u{0020}it\u{0020}can\u{0020}enable\u{0020}people\u{0020}to\u{0020}see\u{0020}beautiful\u{0020}things\u{0020}and\u{0020}pursue\u{0020}them.\n\nBut\u{0020}what\u{0020}drives\u{0020}Xiaomeng's\u{0020}actions\u{0020}has\u{0020}never\u{0020}been\u{0020}any\u{0020}\"will\",\u{0020}but\u{0020}\"commands\",\u{0020}so\u{0020}I\u{0020}cannot\u{0020}feel\u{0020}the\u{0020}nobility\u{0020}of\u{0020}power\u{0020}in\u{0020}her.\n\nI\u{0020}want\u{0020}to\u{0020}help\u{0020}Xiaomeng\u{0020}correct\u{0020}this\u{0020}thought,\u{0020}but\u{0020}before\u{0020}I\u{0020}think\u{0020}of\u{0020}a\u{0020}way\u{0020}to\u{0020}correct\u{0020}her\u{0020}habits,\u{0020}I\u{0020}have\u{0020}to\u{0020}protect\u{0020}her\u{0020}first.\u{0020}Those\u{0020}who\u{0020}don't\u{0020}know\u{0020}how\u{0020}to\u{0020}protect\u{0020}themselves\u{0020}will\u{0020}be\u{0020}hurt\u{0020}by\u{0020}themselves\u{0020}sooner\u{0020}or\u{0020}later.\n\nBut\u{0020}to\u{0020}correct\u{0020}her\u{0020}thinking,\u{0020}me\u{0020}alone\u{0020}is\u{0020}not\u{0020}enough.\u{0020}I\u{0020}still\u{0020}need\u{0020}another\u{0020}person\u{0020}trusted\u{0020}by\u{0020}her\u{0020}to\u{0020}help...\u{0020}The\u{0020}help\u{0020}of\u{0020}that\u{0020}navigator.", "0", "0", "0", "0", 11023, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[612303] = {612303, 1000, "\u{0020}\u{0020}A\u{0020}little\u{0020}uncomfortable,\u{0020}but\u{0020}only\u{0020}a\u{0020}little.\n\nXiaomeng\u{0020}didn't\u{0020}notice\u{0020}at\u{0020}all\u{0020}that\u{0020}Navigator\u{0020}and\u{0020}Chenglian\u{0020}were\u{0020}using\u{0020}a\u{0020}gentle\u{0020}way\u{0020}to\u{0020}make\u{0020}her\u{0020}start\u{0020}thinking\u{0020}slowly.\n\n\"\u{0020}What\u{0020}would\u{0020}you\u{0020}like\u{0020}for\u{0020}dinner?\"\u{0020}Starting\u{0020}from\u{0020}such\u{0020}a\u{0020}trivial\u{0020}question,\u{0020}her\u{0020}companion\u{0020}did\u{0020}not\u{0020}choose\u{0020}to\u{0020}directly\u{0020}point\u{0020}out\u{0020}Xiaomeng's\u{0020}shortcomings.\u{0020}Instead,\u{0020}they\u{0020}wanted\u{0020}to\u{0020}gradually\u{0020}change\u{0020}Xiaomeng's\u{0020}habits\u{0020}in\u{0020}life.\u{0020}For\u{0020}every\u{0020}reaction\u{0020}Xiaomeng\u{0020}made,\u{0020}they\u{0020}would\u{0020}give\u{0020}praise\u{0020}and\u{0020}encouragement.\u{0020}To\u{0020}describe\u{0020}it\u{0020}with\u{0020}an\u{0020}appropriate\u{0020}word,\u{0020}it's\u{0020}like\u{0020}boiling\u{0020}a\u{0020}frog\u{0020}in\u{0020}warm\u{0020}water.\u{0020}Xiaomeng\u{0020}has\u{0020}unconsciously\u{0020}fallen\u{0020}into\u{0020}a\u{0020}desperate\u{0020}situation\u{0020}and\u{0020}has\u{0020}reached\u{0020}a\u{0020}dead\u{0020}end.", "0", "0", "0", "0", 11023, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[612304] = {612304, 2000, "\n\nCome\u{0020}and\u{0020}tell\u{0020}me\u{0020}what\u{0020}to\u{0020}do?\n\nWhat\u{0020}are\u{0020}we\u{0020}going\u{0020}to\u{0020}do\u{0020}next?\n\nUnderstand\u{0020}rationally\u{0020}but\u{0020}still\u{0020}keep\u{0020}craving\u{0020}again\u{0020}and\u{0020}again.\n\nThe\u{0020}puppet\u{0020}is\u{0020}enduring\u{0020}the\u{0020}loneliness\u{0020}that\u{0020}cannot\u{0020}be\u{0020}understood.\n\nThe\u{0020}puppet\u{0020}is\u{0020}craving\u{0020}for\u{0020}the\u{0020}incomprehensible\u{0020}love.\n\nFirstly,\u{0020}\"Master\",\n\nShe\u{0020}gave\u{0020}Xiaomeng\u{0020}the\u{0020}power\u{0020}to\u{0020}protect\u{0020}herself\u{0020}and\u{0020}others.\n\nSecondly,\u{0020}\"Mother\"\n\nShe\u{0020}gave\u{0020}Xiaomeng\u{0020}affirmation,\u{0020}encouragement\u{0020}and\u{0020}a\u{0020}warm\u{0020}home.\n\nSo\u{0020}this\u{0020}is\u{0020}love.\n\nSo\u{0020}Xiaomeng\u{0020}started\u{0020}to\u{0020}run.\n\nWant\u{0020}to\u{0020}share\u{0020}this\u{0020}impulse,\n\nShare\u{0020}it\u{0020}with\u{0020}the\u{0020}third\u{0020}one,\u{0020}\"Navigator\".", "0", "0", "0", "0", 11023, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
