[612401] = {612401, 100, "\u{0020}\u{0020}Among\u{0020}the\u{0020}specialized\u{0020}water\u{0020}warfare\u{0020}unit\u{0020}Whalefall,\u{0020}Yanyanlo\u{0020}is\u{0020}the\u{0020}latest\u{0020}member\u{0020}to\u{0020}join.\u{0020}Although\u{0020}her\u{0020}petite\u{0020}appearance\u{0020}can\u{0020}give\u{0020}people\u{0020}a\u{0020}sense\u{0020}of\u{0020}closeness,\u{0020}her\u{0020}quirky\u{0020}behavior\u{0020}and\u{0020}style\u{0020}often\u{0020}ruin\u{0020}this\u{0020}first\u{0020}impression.\u{0020}The\u{0020}author\u{0020}also\u{0020}had\u{0020}a\u{0020}deep\u{0020}experience\u{0020}of\u{0020}this\u{0020}during\u{0020}the\u{0020}investigation\u{0020}for\u{0020}writing\u{0020}the\u{0020}file.\n\nAccording\u{0020}to\u{0020}the\u{0020}statements\u{0020}of\u{0020}the\u{0020}team\u{0020}members,\u{0020}Yanyanlo\u{0020}is\u{0020}not\u{0020}bad-natured.\u{0020}She\u{0020}sometimes\u{0020}exaggeratedly\u{0020}gets\u{0020}close\u{0020}to\u{0020}oneself,\u{0020}and\u{0020}sometimes\u{0020}teases\u{0020}without\u{0020}malice\u{0020}with\u{0020}a\u{0020}mocking\u{0020}expression.\u{0020}How\u{0020}much\u{0020}sincerity\u{0020}and\u{0020}insincerity\u{0020}are\u{0020}hidden\u{0020}beneath\u{0020}her\u{0020}frivolous\u{0020}words\u{0020}and\u{0020}deeds?\u{0020}Regarding\u{0020}this\u{0020}point,\u{0020}perhaps\u{0020}only\u{0020}the\u{0020}most\u{0020}experienced\u{0020}Samghrma\u{0020}in\u{0020}the\u{0020}team\u{0020}can\u{0020}vaguely\u{0020}distinguish.\n\nIn\u{0020}fact,\u{0020}when\u{0020}Yanyanlo\u{0020}just\u{0020}entered\u{0020}AEGIS\u{0020}and\u{0020}faced\u{0020}the\u{0020}issue\u{0020}of\u{0020}qualification\u{0020}review,\u{0020}she\u{0020}astonishingly\u{0020}stated\u{0020}that\u{0020}the\u{0020}main\u{0020}reason\u{0020}she\u{0020}wanted\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}was\u{0020}to\u{0020}challenge\u{0020}deeper\u{0020}diving\u{0020}with\u{0020}an\u{0020}gigantified\u{0020}body.\u{0020}This\u{0020}approach,\u{0020}which\u{0020}is\u{0020}hard\u{0020}to\u{0020}be\u{0020}called\u{0020}either\u{0020}outspoken\u{0020}or\u{0020}impolite,\u{0020}might\u{0020}have\u{0020}been\u{0020}quietly\u{0020}destined\u{0020}at\u{0020}that\u{0020}time:\u{0020}in\u{0020}the\u{0020}future,\u{0020}she\u{0020}would\u{0020}join\u{0020}the\u{0020}unusual\u{0020}team\u{0020}Whalefall.", "0", "0", "0", "0", 11024, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[612402] = {612402, 500, "\u{0020}Unlike\u{0020}other\u{0020}drivers\u{0020}of\u{0020}Whalefall,\u{0020}Yanyanlo\u{0020}is\u{0020}the\u{0020}only\u{0020}member\u{0020}who\u{0020}is\u{0020}not\u{0020}from\u{0020}the\u{0020}seaside.\u{0020}For\u{0020}such\u{0020}a\u{0020}special\u{0020}force,\u{0020}\"being\u{0020}familiar\u{0020}with\u{0020}water\"\u{0020}and\u{0020}\"adapting\u{0020}to\u{0020}the\u{0020}ocean\"\u{0020}are\u{0020}the\u{0020}most\u{0020}prioritized\u{0020}and\u{0020}fundamental\u{0020}requirements.\u{0020}However,\u{0020}Yanyanlo,\u{0020}who\u{0020}was\u{0020}born\u{0020}and\u{0020}grew\u{0020}up\u{0020}in\u{0020}an\u{0020}inland\u{0020}environment,\u{0020}could\u{0020}be\u{0020}selected\u{0020}as\u{0020}a\u{0020}member.\u{0020}Apparently,\u{0020}there\u{0020}are\u{0020}reasons\u{0020}for\u{0020}that.\n\nAlthough\u{0020}Yanyanlo's\u{0020}ability\u{0020}to\u{0020}be\u{0020}mysterious\u{0020}is\u{0020}remarkable,\u{0020}her\u{0020}family\u{0020}members\u{0020}are\u{0020}reasonable\u{0020}and\u{0020}pragmatic.\u{0020}After\u{0020}contacting\u{0020}and\u{0020}communicating\u{0020}with\u{0020}them,\u{0020}we\u{0020}finally\u{0020}succeeded\u{0020}in\u{0020}learning\u{0020}how\u{0020}Yanyanlo\u{0020}initially\u{0020}formed\u{0020}an\u{0020}inseparable\u{0020}bond\u{0020}with\u{0020}the\u{0020}ocean.\n\nIt\u{0020}was\u{0020}during\u{0020}a\u{0020}trip\u{0020}seven\u{0020}years\u{0020}ago\u{0020}that\u{0020}the\u{0020}young\u{0020}Yanyanlo\u{0020}was\u{0020}on\u{0020}a\u{0020}cruise\u{0020}ship\u{0020}with\u{0020}her\u{0020}parents,\u{0020}enjoying\u{0020}the\u{0020}sea\u{0020}breeze\u{0020}and\u{0020}the\u{0020}view\u{0020}on\u{0020}the\u{0020}deck.\u{0020}The\u{0020}sky\u{0020}was\u{0020}clear\u{0020}and\u{0020}sunny\u{0020}that\u{0020}day,\u{0020}and\u{0020}everything\u{0020}within\u{0020}sight\u{0020}seemed\u{0020}to\u{0020}be\u{0020}permeated\u{0020}with\u{0020}blue.\u{0020}The\u{0020}boundless\u{0020}ocean\u{0020}was\u{0020}calm\u{0020}without\u{0020}a\u{0020}ripple,\u{0020}making\u{0020}the\u{0020}cruise\u{0020}ship's\u{0020}voyage\u{0020}extremely\u{0020}stable,\u{0020}as\u{0020}if\u{0020}sliding\u{0020}on\u{0020}ice.\n\nBecause\u{0020}of\u{0020}the\u{0020}good\u{0020}weather,\u{0020}this\u{0020}trip\u{0020}was\u{0020}undoubtedly\u{0020}extremely\u{0020}pleasant.\u{0020}The\u{0020}adults\u{0020}were\u{0020}peacefully\u{0020}enjoying\u{0020}the\u{0020}rare\u{0020}holiday\u{0020}leisure.\u{0020}However,\u{0020}compared\u{0020}to\u{0020}them,\u{0020}as\u{0020}a\u{0020}child,\u{0020}Yanyanlo\u{0020}soon\u{0020}began\u{0020}to\u{0020}feel\u{0020}bored.\u{0020}She\u{0020}didn't\u{0020}understand\u{0020}what\u{0020}pleasure\u{0020}there\u{0020}was\u{0020}in\u{0020}such\u{0020}a\u{0020}long\u{0020}and\u{0020}slow\u{0020}journey.\u{0020}Even\u{0020}the\u{0020}scenery\u{0020}she\u{0020}saw\u{0020}when\u{0020}looking\u{0020}around\u{0020}was\u{0020}always\u{0020}the\u{0020}same.\u{0020}It\u{0020}was\u{0020}like\u{0020}being\u{0020}imprisoned\u{0020}in\u{0020}a\u{0020}vast\u{0020}expanse\u{0020}of\u{0020}deep\u{0020}blue.\u{0020}She\u{0020}couldn't\u{0020}feel\u{0020}the\u{0020}passage\u{0020}of\u{0020}time\u{0020}or\u{0020}whether\u{0020}the\u{0020}ship\u{0020}was\u{0020}really\u{0020}moving.\n\nBored\u{0020}to\u{0020}death,\u{0020}Yanyanlo\u{0020}said\u{0020}nothing\u{0020}at\u{0020}all.\u{0020}Fortunately,\u{0020}her\u{0020}parents\u{0020}soon\u{0020}noticed\u{0020}the\u{0020}anomaly.\u{0020}After\u{0020}some\u{0020}discussion,\u{0020}they\u{0020}took\u{0020}out\u{0020}a\u{0020}string\u{0020}of\u{0020}shell\u{0020}necklaces\u{0020}from\u{0020}the\u{0020}jewelry\u{0020}box,\u{0020}which\u{0020}was\u{0020}bought\u{0020}not\u{0020}long\u{0020}ago,\u{0020}in\u{0020}advance.\u{0020}The\u{0020}colorful\u{0020}patterns\u{0020}on\u{0020}the\u{0020}surface\u{0020}of\u{0020}the\u{0020}shells\u{0020}instantly\u{0020}caught\u{0020}Yanyanlo's\u{0020}attention.\n\nHowever,\u{0020}those\u{0020}who\u{0020}have\u{0020}not\u{0020}lived\u{0020}by\u{0020}the\u{0020}sea\u{0020}for\u{0020}a\u{0020}long\u{0020}time\u{0020}do\u{0020}not\u{0020}understand\u{0020}how\u{0020}capricious\u{0020}and\u{0020}unpredictable\u{0020}the\u{0020}nature\u{0020}of\u{0020}the\u{0020}sea\u{0020}is.\u{0020}Even\u{0020}if\u{0020}it\u{0020}is\u{0020}clear\u{0020}and\u{0020}sunny\u{0020}one\u{0020}second,\u{0020}the\u{0020}undercurrents\u{0020}and\u{0020}atmosphere\u{0020}can\u{0020}still\u{0020}make\u{0020}the\u{0020}ocean\u{0020}change\u{0020}in\u{0020}an\u{0020}instant.\u{0020}Thus,\u{0020}with\u{0020}just\u{0020}one\u{0020}jolt\u{0020}and\u{0020}one\u{0020}sway,\u{0020}Yanyanlo's\u{0020}fate\u{0020}took\u{0020}a\u{0020}turn\u{0020}from\u{0020}then\u{0020}on.\n\nThe\u{0020}cruise\u{0020}ship\u{0020}suddenly\u{0020}trembled\u{0020}with\u{0020}the\u{0020}waves,\u{0020}and\u{0020}the\u{0020}necklace\u{0020}thus\u{0020}slipped\u{0020}from\u{0020}her\u{0020}fingers\u{0020}and\u{0020}dropped\u{0020}straight\u{0020}into\u{0020}the\u{0020}sea.\u{0020}The\u{0020}adults\u{0020}were\u{0020}stunned\u{0020}immediately,\u{0020}and\u{0020}their\u{0020}thoughts\u{0020}had\u{0020}already\u{0020}been\u{0020}disturbed\u{0020}by\u{0020}this\u{0020}wave,\u{0020}turning\u{0020}into\u{0020}a\u{0020}puddle\u{0020}of\u{0020}muddy\u{0020}water.\n\nBut\u{0020}compared\u{0020}to\u{0020}this\u{0020}sudden\u{0020}storm,\u{0020}what\u{0020}shocked\u{0020}everyone\u{0020}even\u{0020}more\u{0020}was\u{0020}the\u{0020}fact\u{0020}that\u{0020}Yanyanlo\u{0020}jumped\u{0020}off\u{0020}the\u{0020}cruise\u{0020}ship\u{0020}in\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye.\u{0020}Maybe\u{0020}it\u{0020}was\u{0020}because\u{0020}of\u{0020}the\u{0020}stubbornness\u{0020}in\u{0020}her\u{0020}bones,\u{0020}or\u{0020}maybe\u{0020}it\u{0020}was\u{0020}because\u{0020}of\u{0020}her\u{0020}nature's\u{0020}longing\u{0020}for\u{0020}the\u{0020}extraordinary.\u{0020}The\u{0020}girl,\u{0020}who\u{0020}did\u{0020}not\u{0020}yet\u{0020}know\u{0020}what\u{0020}fear\u{0020}was,\u{0020}just\u{0020}stared\u{0020}closely\u{0020}at\u{0020}that\u{0020}string\u{0020}of\u{0020}necklaces\u{0020}and\u{0020}jumped\u{0020}into\u{0020}the\u{0020}sea\u{0020}like\u{0020}following\u{0020}a\u{0020}brilliant\u{0020}meteor.\n\nIt\u{0020}was\u{0020}because\u{0020}of\u{0020}this\u{0020}accident\u{0020}and\u{0020}recklessness\u{0020}that\u{0020}she\u{0020}was\u{0020}able\u{0020}to\u{0020}discover\u{0020}the\u{0020}fresh\u{0020}world\u{0020}hidden\u{0020}under\u{0020}the\u{0020}blue\u{0020}curtain,\u{0020}as\u{0020}well\u{0020}as\u{0020}her\u{0020}talent\u{0020}for\u{0020}diving.\u{0020}For\u{0020}the\u{0020}necklace,\u{0020}Yanyanlo\u{0020}pushed\u{0020}away\u{0020}the\u{0020}sea\u{0020}anemones\u{0020}and\u{0020}coral\u{0020}bushes,\u{0020}and\u{0020}searched\u{0020}for\u{0020}more\u{0020}than\u{0020}ten\u{0020}minutes\u{0020}surrounded\u{0020}by\u{0020}tropical\u{0020}fish,\u{0020}until\u{0020}she\u{0020}was\u{0020}brought\u{0020}back\u{0020}to\u{0020}the\u{0020}boat\u{0020}by\u{0020}the\u{0020}rescuers,\u{0020}she\u{0020}was\u{0020}still\u{0020}safe\u{0020}and\u{0020}sound.\n\nYanyanlo\u{0020}was\u{0020}never\u{0020}able\u{0020}to\u{0020}retrieve\u{0020}the\u{0020}necklace\u{0020}her\u{0020}parents\u{0020}gave\u{0020}her,\u{0020}but\u{0020}the\u{0020}experience\u{0020}gave\u{0020}her\u{0020}another\u{0020}treasure.\u{0020}She\u{0020}no\u{0020}longer\u{0020}considered\u{0020}the\u{0020}ocean\u{0020}travel\u{0020}boring,\u{0020}because\u{0020}she\u{0020}knew\u{0020}that\u{0020}the\u{0020}truly\u{0020}colorful\u{0020}and\u{0020}interesting\u{0020}things\u{0020}were\u{0020}actually\u{0020}lurking\u{0020}under\u{0020}the\u{0020}sea,\u{0020}under\u{0020}the\u{0020}skin\u{0020}of\u{0020}the\u{0020}world.", "0", "0", "0", "0", 11024, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[612403] = {612403, 1000, "\u{0020}\u{0020}At\u{0020}first,\u{0020}Yanyanlo's\u{0020}motivation\u{0020}and\u{0020}personality\u{0020}worried\u{0020}AEGIS\u{0020}that\u{0020}she\u{0020}might\u{0020}not\u{0020}be\u{0020}up\u{0020}to\u{0020}the\u{0020}job,\u{0020}but\u{0020}soon\u{0020}after\u{0020}she\u{0020}joined\u{0020}Whalefall,\u{0020}the\u{0020}original\u{0020}unnatural\u{0020}atmosphere\u{0020}in\u{0020}the\u{0020}team\u{0020}changed\u{0020}slightly\u{0020}in\u{0020}a\u{0020}positive\u{0020}direction.\n\nCompared\u{0020}with\u{0020}several\u{0020}members\u{0020}who\u{0020}have\u{0020}been\u{0020}accompanied\u{0020}by\u{0020}the\u{0020}ocean\u{0020}for\u{0020}a\u{0020}long\u{0020}time,\u{0020}Yanyanlo's\u{0020}attitude\u{0020}towards\u{0020}the\u{0020}sea\u{0020}is\u{0020}more\u{0020}casual\u{0020}and\u{0020}natural.\u{0020}She\u{0020}can\u{0020}communicate\u{0020}with\u{0020}people\u{0020}without\u{0020}scruples.\u{0020}Although\u{0020}her\u{0020}words\u{0020}are\u{0020}sometimes\u{0020}sharp,\u{0020}this\u{0020}straightforwardness\u{0020}is\u{0020}the\u{0020}key\u{0020}to\u{0020}breaking\u{0020}through\u{0020}the\u{0020}estrangement.\u{0020}Moreover,\u{0020}Yanyanlo\u{0020}only\u{0020}seems\u{0020}harsh.\u{0020}She\u{0020}knows\u{0020}to\u{0020}keep\u{0020}silent\u{0020}about\u{0020}inappropriate\u{0020}jokes\u{0020}and\u{0020}is\u{0020}also\u{0020}good\u{0020}at\u{0020}using\u{0020}humorous\u{0020}words\u{0020}to\u{0020}dispel\u{0020}anxiety\u{0020}and\u{0020}depression.\n\nHowever,\u{0020}precisely\u{0020}because\u{0020}Yanyanlo\u{0020}was\u{0020}influenced\u{0020}by\u{0020}that\u{0020}\"a\u{0020}blessing\u{0020}in\u{0020}disguise\"\u{0020}experience,\u{0020}she\u{0020}has\u{0020}since\u{0020}become\u{0020}passionate\u{0020}about\u{0020}adventurous\u{0020}behaviors.\u{0020}The\u{0020}driving\u{0020}force\u{0020}she\u{0020}provides\u{0020}for\u{0020}the\u{0020}team\u{0020}may\u{0020}not\u{0020}always\u{0020}be\u{0020}in\u{0020}a\u{0020}good\u{0020}direction.\u{0020}When\u{0020}an\u{0020}insurmountable\u{0020}chasm\u{0020}lies\u{0020}before\u{0020}them,\u{0020}if\u{0020}there\u{0020}is\u{0020}no\u{0020}outstanding\u{0020}leader\u{0020}to\u{0020}remind\u{0020}everyone\u{0020}to\u{0020}stop\u{0020}before\u{0020}it's\u{0020}too\u{0020}late,\u{0020}they\u{0020}will\u{0020}surely\u{0020}face\u{0020}the\u{0020}abyss\u{0020}and\u{0020}then\u{0020}dive\u{0020}into\u{0020}it.", "0", "0", "0", "0", 11024, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[612404] = {612404, 2000, "\u{0020}\u{0020}In\u{0020}the\u{0020}unfathomable\u{0020}darkness,\u{0020}a\u{0020}glimmer\u{0020}of\u{0020}light\u{0020}flickers\u{0020}faintly.\n\nIt\u{0020}is\u{0020}difficult\u{0020}to\u{0020}restrain\u{0020}the\u{0020}nature\u{0020}of\u{0020}being\u{0020}attracted\u{0020}to\u{0020}light.\u{0020}Navigator\u{0020}swam\u{0020}towards\u{0020}that\u{0020}light.\n\nThough\u{0020}the\u{0020}light\u{0020}in\u{0020}the\u{0020}deep\u{0020}sea\u{0020}is\u{0020}alluring,\u{0020}it\u{0020}conceals\u{0020}dangers.\n\nThe\u{0020}voice\u{0020}was\u{0020}distorted\u{0020}by\u{0020}the\u{0020}ocean\u{0020}current,\u{0020}one\u{0020}could\u{0020}still\u{0020}faintly\u{0020}discern\u{0020}that\u{0020}it\u{0020}came\u{0020}from\u{0020}a\u{0020}girl.\n\nSo,\u{0020}keep\u{0020}diving\u{0020}with\u{0020}me.\n\nIn\u{0020}the\u{0020}profound\u{0020}and\u{0020}dark\u{0020}world,\u{0020}no\u{0020}figure\u{0020}can\u{0020}be\u{0020}seen.\u{0020}Only\u{0020}the\u{0020}genuine\u{0020}touch\u{0020}envelopes\u{0020}oneself.\n\n\"I\u{0020}will\u{0020}take\u{0020}Navigator\u{0020}with\u{0020}me\u{0020}into\u{0020}the\u{0020}darkness.\"\u{0020}She\u{0020}deliberately\u{0020}chose\u{0020}disturbing\u{0020}words.\u{0020}\"Then,\u{0020}let's\u{0020}indulge\u{0020}in\u{0020}another\u{0020}world\u{0020}at\u{0020}the\u{0020}bottom\u{0020}of\u{0020}the\u{0020}sea~\"\u{0020}", "0", "0", "0", "0", 11024, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[612700] = {612700, 0, "[Name]:\u{0020}Ima\u{0020}Nanami\u{0020}\n[B-day]:\u{0020}Nov.\u{0020}6\u{0020}\n[Transformation\u{0020}Core\u{0020}Proficiency]:\u{0020}82%\u{0020}\n[Height]:\u{0020}38m\u{0020}\n[Squad]:\u{0020}Prisoners\u{0020}\n[Affiliation]:\u{0020}Kyushu\u{0020}\n[Hobbies]:\u{0020}Incitement\u{0020}and\u{0020}manipulation", "0", "0", "0", "0", 11027, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[612701] = {612701, 100, "\u{3000}\u{3000}If\u{0020}she\u{0020}wished\u{0020}to\u{0020}disguise\u{0020}herself,\u{0020}perhaps\u{0020}no\u{0020}one\u{0020}would\u{0020}ever\u{0020}uncover\u{0020}her\u{0020}true\u{0020}face.\n\u{3000}\u{3000}By\u{0020}the\u{0020}time\u{0020}you\u{0020}realize\u{0020}she\u{0020}is\u{0020}a\u{0020}dangerous\u{0020}person,\u{0020}it\u{0020}means\u{0020}you\u{0020}have\u{0020}already\u{0020}become\u{0020}one\u{0020}of\u{0020}her\u{0020}victims.\n\u{3000}\u{3000}Ima\u{0020}Nanami\u{0020}is\u{0020}like\u{0020}a\u{0020}grim\u{0020}reaper.\u{0020}When\u{0020}her\u{0020}victims\u{0020}are\u{0020}disheartened,\u{0020}defeated,\u{0020}and\u{0020}ashamed\u{0020}of\u{0020}themselves,\u{0020}she\u{0020}appears\u{0020}at\u{0020}their\u{0020}side\u{0020}with\u{0020}a\u{0020}warm\u{0020}smile,\u{0020}offering\u{0020}her\u{0020}own\u{0020}kind\u{0020}of\u{0020}guidance.\n\u{3000}\u{3000}Guidance\u{0020}in\u{0020}the\u{0020}most\u{0020}literal\u{0020}sense,although\u{0020}she\u{0020}claims\u{0020}that\u{0020}\"I'm\u{0020}always\u{0020}happy\u{0020}to\u{0020}give\u{0020}someone\u{0020}a\u{0020}push\u{0020}when\u{0020}they're\u{0020}standing\u{0020}at\u{0020}the\u{0020}edge\u{0020}of\u{0020}a\u{0020}cliff,\"\u{0020}she\u{0020}does\u{0020}not\u{0020}actually\u{0020}lead\u{0020}her\u{0020}victims\u{0020}onto\u{0020}the\u{0020}path\u{0020}of\u{0020}self-destruction,\u{0020}at\u{0020}least\u{0020}not\u{0020}in\u{0020}the\u{0020}physical\u{0020}sense.\n\u{3000}\u{3000}Those\u{0020}bewitched\u{0020}by\u{0020}her\u{0020}words\u{0020}do\u{0020}not\u{0020}choose\u{0020}to\u{0020}end\u{0020}their\u{0020}own\u{0020}lives.\u{0020}No\u{0020}matter\u{0020}how\u{0020}despairing\u{0020}they\u{0020}may\u{0020}be,\u{0020}once\u{0020}they\u{0020}have\u{0020}heard\u{0020}her\u{0020}speak,\u{0020}they\u{0020}can\u{0020}no\u{0020}longer\u{0020}choose\u{0020}the\u{0020}path\u{0020}of\u{0020}suicide.\n\u{3000}\u{3000}Instead,\u{0020}they\u{0020}deny\u{0020}their\u{0020}former\u{0020}selves.\n\u{3000}\u{3000}The\u{0020}noble\u{0020}become\u{0020}petty,\u{0020}the\u{0020}diligent\u{0020}become\u{0020}lazy,\u{0020}and\u{0020}the\u{0020}law-abiding\u{0020}walk\u{0020}down\u{0020}paths\u{0020}of\u{0020}transgression.\n\u{3000}\u{3000}Ima\u{0020}Nanami,her\u{0020}very\u{0020}existence\u{0020}reverses\u{0020}positive\u{0020}and\u{0020}negative,\u{0020}turning\u{0020}the\u{0020}inner\u{0020}and\u{0020}outer\u{0020}self\u{0020}upside\u{0020}down.\n\u{3000}\u{3000}\"I\u{0020}didn't\u{0020}do\u{0020}anything.\u{0020}You\u{0020}did\u{0020}it\u{0020}yourself.\"", "0", "0", "0", "0", 11027, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[612702] = {612702, 500, "\u{3000}\u{3000}What\u{0020}kind\u{0020}of\u{0020}squad\u{0020}the\u{0020}Prisoners\u{0020}are,\u{0020}and\u{0020}who\u{0020}exactly\u{0020}its\u{0020}members\u{0020}are,\u{0020}is\u{0020}not\u{0020}something\u{0020}the\u{0020}general\u{0020}public\u{0020}can\u{0020}know.\u{0020}But\u{0020}one\u{0020}thing\u{0020}seems\u{0020}to\u{0020}be\u{0020}tacitly\u{0020}understood,that\u{0020}every\u{0020}member\u{0020}of\u{0020}the\u{0020}squad\u{0020}has\u{0020}personally\u{0020}committed\u{0020}some\u{0020}grave\u{0020}crime.\n\u{3000}\u{3000}Yet\u{0020}there\u{0020}are\u{0020}always\u{0020}exceptions,\u{0020}and\u{0020}Ima\u{0020}Nanami\u{0020}is\u{0020}the\u{0020}exception\u{0020}among\u{0020}the\u{0020}Prisoners.\n\u{3000}\u{3000},She\u{0020}has\u{0020}never\u{0020}directly\u{0020}committed\u{0020}a\u{0020}crime\u{0020}herself.\n\u{3000}\u{3000}Even\u{0020}calling\u{0020}it\u{0020}\"incitement\"\u{0020}would\u{0020}be\u{0020}a\u{0020}stretch.\n\u{3000}\u{3000}Before\u{0020}joining\u{0020}the\u{0020}Prisoners,\u{0020}the\u{0020}closest\u{0020}she\u{0020}ever\u{0020}came\u{0020}to\u{0020}a\u{0020}crime\u{0020}was\u{0020}nearly\u{0020}turning\u{0020}a\u{0020}salaried\u{0020}office\u{0020}worker\u{0020}into\u{0020}a\u{0020}murderer.\u{0020}Ima\u{0020}Nanami\u{0020}claimed\u{0020}that\u{0020}she\u{0020}had\u{0020}merely\u{0020}guided\u{0020}the\u{0020}person\u{0020}into\u{0020}doing\u{0020}something\u{0020}they\u{0020}had\u{0020}always\u{0020}wanted\u{0020}to\u{0020}do\u{0020}but\u{0020}had\u{0020}never\u{0020}dared\u{0020}to\u{0020}do,\u{0020}and\u{0020}that\u{0020}she\u{0020}had\u{0020}never\u{0020}encouraged\u{0020}them\u{0020}to\u{0020}commit\u{0020}a\u{0020}crime.\n\u{3000}\u{3000}As\u{0020}for\u{0020}turning\u{0020}the\u{0020}noble\u{0020}into\u{0020}the\u{0020}petty\u{0020}and\u{0020}the\u{0020}diligent\u{0020}into\u{0020}the\u{0020}lazy...\u{0020}obviously,\u{0020}none\u{0020}of\u{0020}that\u{0020}can\u{0020}really\u{0020}be\u{0020}called\u{0020}a\u{0020}crime.\n\u{3000}\u{3000}So\u{0020}why\u{0020}did\u{0020}she\u{0020}end\u{0020}up\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}Prisoners?\n\u{3000}\u{3000}\"A\u{0020}miscalculation\u{0020}on\u{0020}my\u{0020}part,who\u{0020}would've\u{0020}known\u{0020}that\u{0020}little\u{0020}girl\u{0020}was\u{0020}the\u{0020}child\u{0020}of\u{0020}an\u{0020}Aegis\u{0020}executive?\u{0020}I\u{0020}really\u{0020}picked\u{0020}the\u{0020}wrong\u{0020}person\u{0020}to\u{0020}mess\u{0020}with.\"\n\u{3000}\u{3000}People\u{0020}had\u{0020}no\u{0020}legal\u{0020}way\u{0020}to\u{0020}Prisoner\u{0020}Ima\u{0020}Nanami,\u{0020}but\u{0020}in\u{0020}the\u{0020}end,\u{0020}she\u{0020}still\u{0020}paid\u{0020}the\u{0020}price\u{0020}for\u{0020}her\u{0020}wickedness,for\u{0020}actions\u{0020}born\u{0020}of\u{0020}her\u{0020}twisted\u{0020}amusement.\n\u{3000}\u{3000}She\u{0020}lured\u{0020}people\u{0020}into\u{0020}falling,\u{0020}and\u{0020}took\u{0020}pleasure\u{0020}in\u{0020}the\u{0020}expressions\u{0020}they\u{0020}showed\u{0020}when\u{0020}they\u{0020}realized\u{0020}they\u{0020}could\u{0020}never\u{0020}become\u{0020}the\u{0020}kind\u{0020}of\u{0020}person\u{0020}they\u{0020}had\u{0020}wanted\u{0020}to\u{0020}be.\u{0020}In\u{0020}the\u{0020}end,\u{0020}she\u{0020}herself\u{0020}fell\u{0020}into\u{0020}the\u{0020}abyss,\u{0020}beyond\u{0020}redemption.\n\u{3000}\u{3000}\"That\u{0020}said,\u{0020}the\u{0020}very\u{0020}instant\u{0020}I\u{0020}realized\u{0020}my\u{0020}life\u{0020}was\u{0020}over,I\u{0020}felt\u{0020}a\u{0020}kind\u{0020}of\u{0020}joy\u{0020}like\u{0020}never\u{0020}before.\"\n\u{3000}\u{3000}As\u{0020}for\u{0020}how\u{0020}she\u{0020}developed\u{0020}such\u{0020}a\u{0020}vile\u{0020}personality,\u{0020}if\u{0020}you\u{0020}were\u{0020}to\u{0020}ask\u{0020}her\u{0020}directly,\u{0020}Ima\u{0020}Nanami\u{0020}would\u{0020}surely\u{0020}tell\u{0020}you\u{0020}a\u{0020}story\u{0020}tragic\u{0020}enough\u{0020}to\u{0020}make\u{0020}you\u{0020}weep.\u{0020}Perhaps\u{0020}it\u{0020}would\u{0020}be\u{0020}about\u{0020}the\u{0020}misfortune\u{0020}of\u{0020}her\u{0020}family,\u{0020}the\u{0020}suffering\u{0020}caused\u{0020}by\u{0020}social\u{0020}oppression,\u{0020}or\u{0020}the\u{0020}despair\u{0020}of\u{0020}shattered\u{0020}dreams.\u{0020}Each\u{0020}time\u{0020}you\u{0020}asked,\u{0020}you\u{0020}would\u{0020}receive\u{0020}a\u{0020}different\u{0020}answer,\u{0020}and\u{0020}eventually\u{0020}you\u{0020}would\u{0020}realize\u{0020}one\u{0020}thing,the\u{0020}truth.\n\u{3000}\u{3000}Ima\u{0020}Nanami\u{0020}was\u{0020}simply\u{0020}born\u{0020}this\u{0020}way.", "0", "0", "0", "0", 11027, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[612703] = {612703, 1000, "\u{3000}\u{3000}No\u{0020}matter\u{0020}how\u{0020}despicable\u{0020}or\u{0020}vile\u{0020}a\u{0020}person\u{0020}may\u{0020}be,\u{0020}as\u{0020}long\u{0020}as\u{0020}they\u{0020}are\u{0020}useful,\u{0020}Stephanie\u{0020}Eriksson\u{0020}will\u{0020}treat\u{0020}them\u{0020}as\u{0020}a\u{0020}piece\u{0020}on\u{0020}the\u{0020}board,\u{0020}even\u{0020}if\u{0020}it\u{0020}means\u{0020}bearing\u{0020}the\u{0020}blame\u{0020}for\u{0020}it.\n\u{3000}\u{3000}And\u{0020}so\u{0020}Stephanie\u{0020}had\u{0020}a\u{0020}brief\u{0020}conversation\u{0020}with\u{0020}Ima\u{0020}Nanami.\u{0020}That\u{0020}conversation\u{0020}indirectly\u{0020}(or\u{0020}perhaps\u{0020}directly)\u{0020}changed\u{0020}Ima\u{0020}Nanami's\u{0020}life,\u{0020}allowing\u{0020}her\u{0020}to\u{0020}return\u{0020}to\u{0020}society\u{0020}under\u{0020}the\u{0020}identity\u{0020}of\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Prisoners.\u{0020}(By\u{0020}comparison,\u{0020}the\u{0020}other\u{0020}Prisoner\u{0020}is\u{0020}a\u{0020}little\u{0020}pitiful.)\n\u{3000}\u{3000}Stephanie\u{0020}placed\u{0020}almost\u{0020}no\u{0020}restrictions\u{0020}on\u{0020}Ima\u{0020}Nanami.\u{0020}Other\u{0020}than\u{0020}assigning\u{0020}her\u{0020}certain\u{0020}tasks,\u{0020}she\u{0020}granted\u{0020}her\u{0020}nearly\u{0020}the\u{0020}highest\u{0020}level\u{0020}of\u{0020}freedom\u{0020}possible.\u{0020}Of\u{0020}course,\u{0020}having\u{0020}once\u{0020}suffered\u{0020}greatly\u{0020}because\u{0020}of\u{0020}her\u{0020}own\u{0020}vile\u{0020}nature,\u{0020}Ima\u{0020}Nanami\u{0020}has\u{0020}now\u{0020}grown\u{0020}a\u{0020}little\u{0020}as\u{0020}well,\u{0020}and\u{0020}understands\u{0020}how\u{0020}to\u{0020}rein\u{0020}in\u{0020}her\u{0020}claws.\n\u{3000}\u{3000}Then,\u{0020}among\u{0020}the\u{0020}very\u{0020}few\u{0020}restrictions\u{0020}Stephanie\u{0020}did\u{0020}impose,\u{0020}the\u{0020}foremost\u{0020}was\u{0020}this:\n\u{3000}\u{3000}\"If\u{0020}one\u{0020}day\u{0020}my\u{0020}child\u{0020}needs\u{0020}help,\u{0020}then\u{0020}no\u{0020}matter\u{0020}how\u{0020}troublesome\u{0020}or\u{0020}unreasonable\u{0020}the\u{0020}request\u{0020}may\u{0020}be,\u{0020}you\u{0020}must\u{0020}help\u{0020}him.\"", "0", "0", "0", "0", 11027, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[612704] = {612704, 2000, "\u{3000}\u{3000}The\u{0020}difference\u{0020}between\u{0020}a\u{0020}good\u{0020}person\u{0020}and\u{0020}an\u{0020}evil\u{0020}one\u{0020}is\u{0020}but\u{0020}a\u{0020}single\u{0020}thought,\n\u{3000}\u{3000}Human\u{0020}nature\u{0020}is\u{0020}nothing\u{0020}more\u{0020}than\u{0020}a\u{0020}blank\u{0020}canvas\u{0020}for\u{0020}others\u{0020}to\u{0020}write\u{0020}upon,\n\u{3000}\u{3000}What\u{0020}is\u{0020}written\u{0020}onto\u{0020}it\u{0020}is\u{0020}mistaken\u{0020}for\u{0020}one's\u{0020}own\u{0020}conviction,\n\u{3000}\u{3000}And\u{0020}the\u{0020}will\u{0020}one\u{0020}carries\u{0020}through\u{0020}is\u{0020}something\u{0020}bestowed\u{0020}by\u{0020}someone\u{0020}else,\n\u{3000}\u{3000}To\u{0020}her,\u{0020}human\u{0020}beings,including\u{0020}herself,were\u{0020}all\u{0020}equally\u{0020}beyond\u{0020}saving,\n\u{3000}\u{3000}Until,\u{0020}until,\n\u{3000}\u{3000},until\u{0020}he\u{0020}appeared,\u{0020}a\u{0020}man\u{0020}who\u{0020}acted\u{0020}according\u{0020}to\u{0020}his\u{0020}own\u{0020}feelings.", "0", "0", "0", "0", 11027, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
