[612801] = {612801, 100, "\u{0020}\u{0020}Geiro\u{0020}is\u{0020}not\u{0020}an\u{0020}easy-going\u{0020}person.\u{0020}She\u{0020}resists\u{0020}others\u{0020}approaching\u{0020}or\u{0020}touching\u{0020}her\u{0020}casually,\u{0020}as\u{0020}if\u{0020}something\u{0020}unpleasant\u{0020}would\u{0020}happen\u{0020}if\u{0020}one\u{0020}gets\u{0020}too\u{0020}close\u{0020}to\u{0020}her.\n\nWhen\u{0020}cooperating\u{0020}with\u{0020}colleagues\u{0020}on\u{0020}necessary\u{0020}work,\u{0020}she\u{0020}often\u{0020}shows\u{0020}an\u{0020}arrogant\u{0020}attitude\u{0020}and\u{0020}dictates\u{0020}others'\u{0020}work.\n\nThere\u{0020}are\u{0020}seldom\u{0020}people\u{0020}as\u{0020}unsociable\u{0020}as\u{0020}her.\n\nBut\u{0020}if\u{0020}one\u{0020}were\u{0020}to\u{0020}evaluate\u{0020}Geiro's\u{0020}character,\u{0020}she\u{0020}would\u{0020}probably\u{0020}be\u{0020}classified\u{0020}as\u{0020}an\u{0020}innocent\u{0020}good\u{0020}person...\u{0020}Or\u{0020}perhaps\u{0020}a\u{0020}naive\u{0020}good\u{0020}person\u{0020}would\u{0020}be\u{0020}more\u{0020}appropriate?\n\nShe\u{0020}attributed\u{0020}all\u{0020}the\u{0020}misfortunes\u{0020}suffered\u{0020}by\u{0020}humanity,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}conspiracies\u{0020}and\u{0020}struggles\u{0020}bred\u{0020}in\u{0020}this\u{0020}era,\u{0020}to\u{0020}the\u{0020}enemy\u{0020}of\u{0020}humanity,\u{0020}\"Sin\".\n\nShe\u{0020}is\u{0020}also\u{0020}the\u{0020}most\u{0020}prominent\u{0020}AEGIS\u{0020}supporter\u{0020}in\u{0020}Katya\u{0020}Branch.\u{0020}She\u{0020}has\u{0020}stated\u{0020}many\u{0020}times\u{0020}that\u{0020}\"The\u{0020}importance\u{0020}of\u{0020}AEGIS\u{0020}is\u{0020}irreplaceable\".\u{0020}In\u{0020}the\u{0020}Katya\u{0020}Branch\u{0020}where\u{0020}the\u{0020}forces\u{0020}of\u{0020}light\u{0020}and\u{0020}darkness\u{0020}are\u{0020}intricately\u{0020}intertwined\u{0020}and\u{0020}almost\u{0020}every\u{0020}team\u{0020}has\u{0020}its\u{0020}own\u{0020}stance,\u{0020}someone\u{0020}with\u{0020}a\u{0020}firm\u{0020}stance\u{0020}like\u{0020}her\u{0020}might\u{0020}become\u{0020}a\u{0020}thorn\u{0020}in\u{0020}the\u{0020}side\u{0020}of\u{0020}some\u{0020}people.\n\nAlthough\u{0020}she\u{0020}seems\u{0020}never\u{0020}to\u{0020}have\u{0020}considered\u{0020}these,\u{0020}perhaps\u{0020}she\u{0020}didn't\u{0020}think\u{0020}of\u{0020}them.\n\nOf\u{0020}course,\u{0020}it\u{0020}could\u{0020}also\u{0020}be\u{0020}that\u{0020}she\u{0020}doesn't\u{0020}care\u{0020}at\u{0020}all,\u{0020}because\u{0020}she\u{0020}is\u{0020}the\u{0020}strongest\u{0020}driver\u{0020}of\u{0020}Katya\u{0020}Branch.", "0", "0", "0", "0", 11028, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[612802] = {612802, 500, "\u{0020}\u{0020}\"Geiro\u{0020}was\u{0020}born\u{0020}in\u{0020}2020\u{0020}and\u{0020}died\u{0020}in\u{0020}2033.\"\n\nYes,\u{0020}as\u{0020}you\u{0020}can\u{0020}see,\u{0020}Geiro\u{0020}is\u{0020}a\u{0020}person\u{0020}who\u{0020}should\u{0020}have\u{0020}been\u{0020}dead.\u{0020}Her\u{0020}death\u{0020}certificate\u{0020}was\u{0020}issued\u{0020}by\u{0020}Genia\u{0020}Lee\u{0020}Zaytsev,\u{0020}the\u{0020}current\u{0020}member\u{0020}of\u{0020}the\u{0020}driver\u{0020}team\u{0020}\"Snow\u{0020}Owl\".\n\nIt\u{0020}is\u{0020}well\u{0020}known\u{0020}that\u{0020}Geiro\u{0020}not\u{0020}only\u{0020}did\u{0020}not\u{0020}die\u{0020}but\u{0020}also\u{0020}became\u{0020}the\u{0020}ace\u{0020}driver\u{0020}of\u{0020}Katya\u{0020}Branch.\n\nAs\u{0020}a\u{0020}doctor\u{0020}who\u{0020}was\u{0020}already\u{0020}well-known\u{0020}and\u{0020}highly\u{0020}reputed\u{0020}long\u{0020}before\u{0020}becoming\u{0020}a\u{0020}driver,\u{0020}Genia\u{0020}admitted\u{0020}that\u{0020}the\u{0020}death\u{0020}certificate\u{0020}of\u{0020}Geiro\u{0020}was\u{0020}her\u{0020}momentary\u{0020}negligence.\n\nLet's\u{0020}start\u{0020}from\u{0020}the\u{0020}beginning\u{0020}to\u{0020}introduce\u{0020}this\u{0020}\"resurrected\"\u{0020}driver.\n\nGeiro\u{0020}was\u{0020}born\u{0020}in\u{0020}a\u{0020}small\u{0020}village\u{0020}near\u{0020}Fillinges\u{0020}in\u{0020}the\u{0020}eastern\u{0020}region\u{0020}of\u{0020}Katya,\u{0020}with\u{0020}an\u{0020}ordinary\u{0020}and\u{0020}unremarkable\u{0020}family\u{0020}background\u{0020}(although\u{0020}often\u{0020}dealing\u{0020}with\u{0020}hunger\u{0020}and\u{0020}cold,\u{0020}but\u{0020}this\u{0020}was\u{0020}the\u{0020}norm\u{0020}for\u{0020}people\u{0020}in\u{0020}Katya).\u{0020}The\u{0020}simple\u{0020}and\u{0020}honest\u{0020}rural\u{0020}atmosphere\u{0020}has\u{0020}enabled\u{0020}Geiro\u{0020}to\u{0020}maintain\u{0020}a\u{0020}simplicity\u{0020}of\u{0020}having\u{0020}good\u{0020}wishes\u{0020}for\u{0020}the\u{0020}world\u{0020}since\u{0020}childhood\u{0020}and\u{0020}has\u{0020}persisted\u{0020}until\u{0020}today.\n\nIt\u{0020}is\u{0020}believed\u{0020}that\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}humans\u{0020}are\u{0020}kind,\u{0020}and\u{0020}the\u{0020}reason\u{0020}why\u{0020}there\u{0020}are\u{0020}malicious\u{0020}people\u{0020}among\u{0020}humans\u{0020}is\u{0020}also\u{0020}caused\u{0020}by\u{0020}the\u{0020}natural\u{0020}disaster\u{0020}of\u{0020}Sin.\u{0020}This\u{0020}cognition\u{0020}was\u{0020}mostly\u{0020}instilled\u{0020}by\u{0020}her\u{0020}parents\u{0020}and\u{0020}villagers.\n\nThis\u{0020}kind\u{0020}of\u{0020}cognition\u{0020}divorced\u{0020}from\u{0020}reality\u{0020}makes\u{0020}her\u{0020}look\u{0020}naive,\u{0020}beautiful\u{0020}and\u{0020}fragile.\n\nFour\u{0020}years\u{0020}ago,\u{0020}the\u{0020}first\u{0020}Great\u{0020}Sin\u{0020}known\u{0020}to\u{0020}humans,\u{0020}\"Greed\",\u{0020}emerged\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region,\u{0020}and\u{0020}the\u{0020}landing\u{0020}place\u{0020}of\u{0020}Greed\u{0020}was\u{0020}\"Fillinges\".\u{0020}As\u{0020}the\u{0020}first\u{0020}scene,\u{0020}the\u{0020}outcome\u{0020}of\u{0020}Fillinges\u{0020}City\u{0020}can\u{0020}be\u{0020}imagined,\u{0020}and\u{0020}the\u{0020}neighboring\u{0020}villages\u{0020}were\u{0020}also\u{0020}dealt\u{0020}a\u{0020}devastating\u{0020}blow.\n\nAnd\u{0020}according\u{0020}to\u{0020}the\u{0020}records\u{0020}on\u{0020}the\u{0020}list\u{0020}of\u{0020}victims,\u{0020}Geiro\u{0020}died\u{0020}in\u{0020}that\u{0020}disaster,\u{0020}just\u{0020}like\u{0020}her\u{0020}parents\u{0020}and\u{0020}fellow\u{0020}villagers.\n\nGeiro\u{0020}was\u{0020}a\u{0020}wounded\u{0020}person\u{0020}found\u{0020}in\u{0020}the\u{0020}ruins\u{0020}not\u{0020}far\u{0020}from\u{0020}the\u{0020}place\u{0020}where\u{0020}Greed\u{0020}died\u{0020}after\u{0020}the\u{0020}end\u{0020}of\u{0020}the\u{0020}Greed\u{0020}Crusade.\u{0020}She\u{0020}was\u{0020}confirmed\u{0020}dead\u{0020}during\u{0020}the\u{0020}process\u{0020}of\u{0020}being\u{0020}sent\u{0020}to\u{0020}the\u{0020}rear\u{0020}for\u{0020}treatment.\u{0020}Before\u{0020}Geiro\u{0020}was\u{0020}confirmed\u{0020}dead,\u{0020}the\u{0020}last\u{0020}person\u{0020}who\u{0020}had\u{0020}contact\u{0020}with\u{0020}her\u{0020}was\u{0020}Genia,\u{0020}who\u{0020}was\u{0020}the\u{0020}medical\u{0020}officer\u{0020}of\u{0020}the\u{0020}Frontier\u{0020}team\u{0020}at\u{0020}that\u{0020}time.\u{0020}But\u{0020}the\u{0020}fact\u{0020}is\u{0020}that\u{0020}she\u{0020}didn't\u{0020}die.\u{0020}It's\u{0020}simply\u{0020}a\u{0020}fairy\u{0020}tale\u{0020}that\u{0020}Genia,\u{0020}who\u{0020}has\u{0020}pulled\u{0020}many\u{0020}people\u{0020}back\u{0020}from\u{0020}the\u{0020}verge\u{0020}of\u{0020}death\u{0020}countless\u{0020}times,\u{0020}could\u{0020}mistake\u{0020}the\u{0020}life\u{0020}and\u{0020}death\u{0020}of\u{0020}a\u{0020}wounded\u{0020}person.\u{0020}Genia's\u{0020}silent\u{0020}attitude\u{0020}towards\u{0020}Geiro's\u{0020}\"resurrection\"\u{0020}is\u{0020}also\u{0020}suspicious.\u{0020}What\u{0020}happened\u{0020}to\u{0020}Geiro\u{0020}is\u{0020}probably\u{0020}only\u{0020}clear\u{0020}to\u{0020}her\u{0020}and\u{0020}Genia,\u{0020}who\u{0020}were\u{0020}the\u{0020}parties\u{0020}involved.\n\nBut\u{0020}the\u{0020}fact\u{0020}is\u{0020}that\u{0020}she\u{0020}didn't\u{0020}die.\n\nIt's\u{0020}simply\u{0020}a\u{0020}fairy\u{0020}tale\u{0020}that\u{0020}Genia,\u{0020}who\u{0020}has\u{0020}pulled\u{0020}many\u{0020}people\u{0020}back\u{0020}from\u{0020}the\u{0020}verge\u{0020}of\u{0020}death\u{0020}countless\u{0020}times,\u{0020}could\u{0020}mistake\u{0020}the\u{0020}life\u{0020}and\u{0020}death\u{0020}of\u{0020}a\u{0020}wounded\u{0020}person.\u{0020}Genia's\u{0020}silent\u{0020}attitude\u{0020}towards\u{0020}Geiro's\u{0020}\"resurrection\"\u{0020}is\u{0020}also\u{0020}suspicious.\u{0020}What\u{0020}happened\u{0020}to\u{0020}Geiro\u{0020}is\u{0020}probably\u{0020}only\u{0020}clear\u{0020}to\u{0020}her\u{0020}and\u{0020}Genia,\u{0020}who\u{0020}were\u{0020}the\u{0020}parties\u{0020}involved.\n\nWhat\u{0020}happened\u{0020}to\u{0020}Geiro\u{0020}is\u{0020}probably\u{0020}only\u{0020}clear\u{0020}to\u{0020}her\u{0020}and\u{0020}Genia,\u{0020}who\u{0020}were\u{0020}the\u{0020}parties\u{0020}involved.", "0", "0", "0", "0", 11028, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[612803] = {612803, 1000, "\u{0020}\u{0020}Two\u{0020}years\u{0020}after\u{0020}being\u{0020}confirmed\u{0020}dead,\u{0020}the\u{0020}resurrected\u{0020}Geiro\u{0020}visited\u{0020}Genia\u{0020}Lee\u{0020}Zaytsev,\u{0020}who\u{0020}was\u{0020}already\u{0020}a\u{0020}driver.\u{0020}The\u{0020}two\u{0020}held\u{0020}a\u{0020}meeting\u{0020}whose\u{0020}conversation\u{0020}content\u{0020}was\u{0020}known\u{0020}only\u{0020}to\u{0020}the\u{0020}two\u{0020}parties.\u{0020}After\u{0020}that,\u{0020}Geiro\u{0020}joined\u{0020}AEGIS.\n\nShe\u{0020}who\u{0020}was\u{0020}qualified\u{0020}became\u{0020}a\u{0020}formal\u{0020}driver\u{0020}in\u{0020}just\u{0020}one\u{0020}year\u{0020}and\u{0020}belonged\u{0020}to\u{0020}the\u{0020}Valkyrie\u{0020}team.\n\nApart\u{0020}from\u{0020}being\u{0020}overly\u{0020}excellent,\u{0020}she\u{0020}didn't\u{0020}show\u{0020}anything\u{0020}different\u{0020}from\u{0020}ordinary\u{0020}people,\u{0020}as\u{0020}if\u{0020}her\u{0020}resurrection\u{0020}was\u{0020}really\u{0020}just\u{0020}an\u{0020}accident\u{0020}caused\u{0020}by\u{0020}negligence.\n\nThe\u{0020}only\u{0020}problem\u{0020}is\u{0020}that\u{0020}she\u{0020}is\u{0020}too\u{0020}excellent.\u{0020}Now,\u{0020}Geiro\u{0020}is\u{0020}the\u{0020}strongest\u{0020}driver\u{0020}of\u{0020}Katya\u{0020}Branch\u{0020}and\u{0020}perhaps\u{0020}even\u{0020}the\u{0020}strongest\u{0020}driver\u{0020}of\u{0020}AEGIS.\n\nA\u{0020}girl\u{0020}who\u{0020}had\u{0020}not\u{0020}received\u{0020}any\u{0020}military\u{0020}training\u{0020}two\u{0020}years\u{0020}ago\u{0020}became\u{0020}the\u{0020}leading\u{0020}driver\u{0020}in\u{0020}less\u{0020}than\u{0020}two\u{0020}years.\u{0020}Before\u{0020}that,\u{0020}she\u{0020}was\u{0020}even\u{0020}regarded\u{0020}as\u{0020}a\u{0020}\"dead\u{0020}person\".\n\nIf\u{0020}nothing\u{0020}bizarre\u{0020}happened\u{0020}to\u{0020}her,\u{0020}no\u{0020}one\u{0020}would\u{0020}believe\u{0020}it.", "0", "0", "0", "0", 11028, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[612804] = {612804, 2000, "\u{0020}\u{0020}She\u{0020}indulged\u{0020}in\u{0020}the\u{0020}wine-like\u{0020}deep\u{0020}darkness\u{0020}and\u{0020}could\u{0020}hear\u{0020}the\u{0020}whispers\u{0020}of\u{0020}Death\u{0020}by\u{0020}her\u{0020}ears.\n\nThe\u{0020}angel\u{0020}in\u{0020}white\u{0020}placed\u{0020}her\u{0020}hand\u{0020}on\u{0020}the\u{0020}girl's\u{0020}chest,\u{0020}making\u{0020}her\u{0020}heart\u{0020}beat\u{0020}again.\n\n\"Now\u{0020}you\u{0020}have\u{0020}unparalleled\u{0020}talent.\u{0020}But\u{0020}you\u{0020}don't\u{0020}have\u{0020}to\u{0020}bear\u{0020}the\u{0020}same\u{0020}weight\u{0020}of\u{0020}responsibility.\"\n\nThe\u{0020}angel\u{0020}asked\u{0020}her\u{0020}to\u{0020}choose\u{0020}her\u{0020}own\u{0020}path.\n\nSo\u{0020}her\u{0020}eyes\u{0020}saw\u{0020}the\u{0020}bumpy\u{0020}land\u{0020}and\u{0020}bloody\u{0020}tears,\n\nFinally\u{0020}she\u{0020}chose\u{0020}to\u{0020}become\u{0020}an\u{0020}ignorant\u{0020}supporter\u{0020}in\u{0020}order\u{0020}to\u{0020}eliminate\u{0020}the\u{0020}unclean\u{0020}things.\n\n\"I\u{0020}have\u{0020}talent.\u{0020}If\u{0020}I\u{0020}choose\u{0020}to\u{0020}stand\u{0020}by\u{0020}when\u{0020}a\u{0020}disaster\u{0020}occurs,\u{0020}then...\u{0020}I\u{0020}am\u{0020}also\u{0020}a\u{0020}perpetrator\u{0020}of\u{0020}humanity.\"\n\nThe\u{0020}huge\u{0020}girl\u{0020}standing\u{0020}with\u{0020}her\u{0020}back\u{0020}to\u{0020}the\u{0020}light,\u{0020}carrying\u{0020}a\u{0020}gun\u{0020}and\u{0020}walking\u{0020}on\u{0020}the\u{0020}road\u{0020}paved\u{0020}with\u{0020}ice,\u{0020}earth\u{0020}and\u{0020}stones,\u{0020}brings\u{0020}the\u{0020}light\u{0020}to\u{0020}a\u{0020}farther\u{0020}place.", "0", "0", "0", "0", 11028, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
