[612901] = {612901, 100, "\u{0020}\u{0020}Senhaku,\u{0020}the\u{0020}current\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council\u{0020}of\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}is\u{0020}an\u{0020}outstanding\u{0020}student\u{0020}from\u{0020}Kyushu.\u{0020}She\u{0020}was\u{0020}admitted\u{0020}with\u{0020}the\u{0020}top\u{0020}score\u{0020}in\u{0020}the\u{0020}theoretical\u{0020}knowledge\u{0020}examination\u{0020}and\u{0020}has\u{0020}an\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}80%,\u{0020}which\u{0020}is\u{0020}an\u{0020}excellent\u{0020}level.\u{0020}In\u{0020}the\u{0020}election\u{0020}of\u{0020}the\u{0020}student\u{0020}council\u{0020}president,\u{0020}she\u{0020}won\u{0020}the\u{0020}support\u{0020}of\u{0020}most\u{0020}students\u{0020}with\u{0020}her\u{0020}articulate\u{0020}speech\u{0020}and\u{0020}practical\u{0020}propositions.\n\nSenhaku's\u{0020}proposition\u{0020}is\u{0020}very\u{0020}simple,\u{0020}\"rule\u{0020}of\u{0020}law\".\n\nAfter\u{0020}becoming\u{0020}the\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council,\u{0020}Senhaku\u{0020}set\u{0020}three\u{0020}rules\u{0020}for\u{0020}managing\u{0020}the\u{0020}college.\n\nFirst:\u{0020}Students\u{0020}should\u{0020}help\u{0020}each\u{0020}other\u{0020}and\u{0020}there\u{0020}should\u{0020}be\u{0020}no\u{0020}bullying\u{0020}behavior\u{0020}among\u{0020}them.\n\nSecond:\u{0020}Grades\u{0020}are\u{0020}the\u{0020}privacy\u{0020}of\u{0020}students\u{0020}and\u{0020}cannot\u{0020}be\u{0020}disclosed\u{0020}at\u{0020}will.\n\nThird:\u{0020}If\u{0020}there\u{0020}are\u{0020}truly\u{0020}irreconcilable\u{0020}conflicts\u{0020}among\u{0020}students,\u{0020}they\u{0020}can\u{0020}be\u{0020}resolved\u{0020}in\u{0020}the\u{0020}training\u{0020}ground\u{0020}by\u{0020}means\u{0020}of\u{0020}\"duels\"\u{0020}under\u{0020}the\u{0020}supervision\u{0020}of\u{0020}the\u{0020}student\u{0020}council.", "0", "0", "0", "0", 11029, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[612902] = {612902, 500, "\u{0020}The\u{0020}data\u{0020}of\u{0020}Senhaku\u{0020}is\u{0020}\"flawless\".\u{0020}The\u{0020}reason\u{0020}for\u{0020}using\u{0020}\"flawless\"\u{0020}to\u{0020}describe\u{0020}it\u{0020}is\u{0020}that\u{0020}this\u{0020}data\u{0020}is\u{0020}truly\u{0020}impeccable.\n\nFrom\u{0020}the\u{0020}the\u{0020}hospital\u{0020}where\u{0020}Senhaku\u{0020}was\u{0020}born,\u{0020}to\u{0020}the\u{0020}time\u{0020}when\u{0020}she\u{0020}first\u{0020}learned\u{0020}to\u{0020}ride\u{0020}a\u{0020}bicycle,\u{0020}and\u{0020}then\u{0020}to\u{0020}the\u{0020}names\u{0020}of\u{0020}the\u{0020}kindergartens,\u{0020}primary\u{0020}schools,\u{0020}and\u{0020}middle\u{0020}schools\u{0020}she\u{0020}attended...\u{0020}Her\u{0020}life\u{0020}so\u{0020}far\u{0020}is\u{0020}spread\u{0020}out\u{0020}in\u{0020}detail\u{0020}before\u{0020}our\u{0020}eyes,\u{0020}without\u{0020}the\u{0020}slightest\u{0020}concealment\u{0020}or\u{0020}flaw.\n\nSuch\u{0020}a\u{0020}clean\u{0020}resume\u{0020}instead\u{0020}makes\u{0020}people\u{0020}suspect\u{0020}whether\u{0020}there\u{0020}are\u{0020}terrifying\u{0020}secrets\u{0020}hidden.\u{0020}However,\u{0020}secrets\u{0020}are\u{0020}not\u{0020}a\u{0020}crime\u{0020}here.\u{0020}Qualification\u{0020}and\u{0020}strength\u{0020}are\u{0020}the\u{0020}thresholds\u{0020}for\u{0020}drivers.\n\nBefore\u{0020}enrolling\u{0020}in\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}Senhaku\u{0020}studied\u{0020}at\u{0020}a\u{0020}certain\u{0020}middle\u{0020}school\u{0020}in\u{0020}Kyushu\u{0020}and\u{0020}was\u{0020}also\u{0020}the\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council\u{0020}of\u{0020}that\u{0020}school.\u{0020}According\u{0020}to\u{0020}the\u{0020}students\u{0020}of\u{0020}that\u{0020}school,\u{0020}President\u{0020}Senhaku\u{0020}was\u{0020}a\u{0020}person\u{0020}who\u{0020}attached\u{0020}great\u{0020}importance\u{0020}to\u{0020}\"rules\".\n\nIn\u{0020}that\u{0020}middle\u{0020}school,\u{0020}the\u{0020}student\u{0020}council\u{0020}was\u{0020}not\u{0020}an\u{0020}organization\u{0020}with\u{0020}much\u{0020}power.\u{0020}It\u{0020}was\u{0020}only\u{0020}equivalent\u{0020}to\u{0020}a\u{0020}special\u{0020}student\u{0020}club.\u{0020}It\u{0020}might\u{0020}be\u{0020}more\u{0020}appropriate\u{0020}to\u{0020}call\u{0020}it\u{0020}the\u{0020}\"Cleaning\u{0020}Management\u{0020}Club\".\u{0020}Even\u{0020}so,\u{0020}Senhaku\u{0020}still\u{0020}persuaded\u{0020}the\u{0020}teacher\u{0020}to\u{0020}formulate\u{0020}a\u{0020}series\u{0020}of\u{0020}harsh\u{0020}regulations\u{0020}within\u{0020}her\u{0020}ability\u{0020}to\u{0020}manage\u{0020}the\u{0020}students.\n\nFor\u{0020}the\u{0020}generally\u{0020}undisciplined\u{0020}students\u{0020}of\u{0020}that\u{0020}school,\u{0020}Senhaku\u{0020}is\u{0020}like\u{0020}an\u{0020}eagle\u{0020}hovering\u{0020}high\u{0020}in\u{0020}the\u{0020}sky.\u{0020}When\u{0020}they\u{0020}violate\u{0020}the\u{0020}school\u{0020}discipline,\u{0020}she\u{0020}will\u{0020}swoop\u{0020}down\u{0020}from\u{0020}the\u{0020}sky\u{0020}and\u{0020}firmly\u{0020}grip\u{0020}their\u{0020}necks\u{0020}with\u{0020}the\u{0020}sharp\u{0020}claws\u{0020}named\u{0020}\"school\u{0020}regulations\".\n\nAfter\u{0020}coming\u{0020}to\u{0020}Sahara,\u{0020}Senhaku\u{0020}seemed\u{0020}to\u{0020}have\u{0020}lost\u{0020}the\u{0020}\"killing\u{0020}intent\"\u{0020}like\u{0020}that\u{0020}of\u{0020}an\u{0020}eagle.\u{0020}After\u{0020}becoming\u{0020}the\u{0020}student\u{0020}council\u{0020}president\u{0020}of\u{0020}Azure\u{0020}Academy,\u{0020}she\u{0020}did\u{0020}not\u{0020}formulate\u{0020}some\u{0020}extremely\u{0020}harsh\u{0020}rules\u{0020}as\u{0020}before.\u{0020}With\u{0020}only\u{0020}three\u{0020}new\u{0020}rules\u{0020}added\u{0020}to\u{0020}the\u{0020}original\u{0020}school\u{0020}regulations,\u{0020}the\u{0020}atmosphere\u{0020}of\u{0020}the\u{0020}entire\u{0020}academy\u{0020}has\u{0020}achieved\u{0020}a\u{0020}qualitative\u{0020}leap.\n\nDuring\u{0020}the\u{0020}regular\u{0020}interview\u{0020}process\u{0020}for\u{0020}driver\u{0020}registration,\u{0020}the\u{0020}registrar\u{0020}asked\u{0020}Senhaku\u{0020}about\u{0020}the\u{0020}\"three\u{0020}rules\"\u{0020}she\u{0020}established.\u{0020}The\u{0020}response\u{0020}was...\n\nRules\u{0020}once\u{0020}established\u{0020}should\u{0020}be\u{0020}followed,\u{0020}but\u{0020}it\u{0020}doesn't\u{0020}mean\u{0020}that\u{0020}the\u{0020}existing\u{0020}rules\u{0020}are\u{0020}necessarily\u{0020}correct.\n\n\"The\u{0020}world\u{0020}is\u{0020}constantly\u{0020}changing,\u{0020}and\u{0020}our\u{0020}rules\u{0020}should\u{0020}also\u{0020}change\u{0020}accordingly.\u{0020}Just\u{0020}like\u{0020}before\u{0020}Sin\u{0020}appeared,\u{0020}allowing\u{0020}minors\u{0020}to\u{0020}go\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}was\u{0020}a\u{0020}serious\u{0020}crime\u{0020}that\u{0020}would\u{0020}be\u{0020}tried\u{0020}in\u{0020}a\u{0020}military\u{0020}court,\u{0020}but\u{0020}now...\"\n\n\u{0020}So\u{0020}the\u{0020}rules\u{0020}I\u{0020}set\u{0020}are\u{0020}not\u{0020}to\u{0020}control\u{0020}anyone.\u{0020}I\u{0020}just\u{0020}hope\u{0020}that\u{0020}students\u{0020}can\u{0020}focus\u{0020}more\u{0020}energy\u{0020}on\u{0020}study\u{0020}and\u{0020}training\u{0020}during\u{0020}these\u{0020}three\u{0020}years\u{0020}to\u{0020}avoid\u{0020}losing\u{0020}their\u{0020}lives\u{0020}due\u{0020}to\u{0020}current\u{0020}negligence\u{0020}in\u{0020}possible\u{0020}future\u{0020}battles.", "0", "0", "0", "0", 11029, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[612903] = {612903, 1000, "\u{0020}The\u{0020}implementation\u{0020}of\u{0020}the\u{0020}Fledgling\u{0020}Project\u{0020}was\u{0020}not\u{0020}smooth\u{0020}in\u{0020}the\u{0020}early\u{0020}stage.\u{0020}The\u{0020}biggest\u{0020}barrier\u{0020}came\u{0020}from\u{0020}Senhaku,\u{0020}the\u{0020}current\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}at\u{0020}Sahara\u{0020}Azure\u{0020}Academy.\n\nWhen\u{0020}Senhaku\u{0020}learned\u{0020}about\u{0020}the\u{0020}Fledgling\u{0020}Project,\u{0020}she\u{0020}led\u{0020}a\u{0020}group\u{0020}of\u{0020}students\u{0020}from\u{0020}the\u{0020}student\u{0020}union\u{0020}to\u{0020}put\u{0020}pressure\u{0020}on\u{0020}the\u{0020}college's\u{0020}senior\u{0020}management,\u{0020}hoping\u{0020}that\u{0020}the\u{0020}college\u{0020}would\u{0020}cancel\u{0020}this\u{0020}cruel\u{0020}project\u{0020}that\u{0020}disregarded\u{0020}students'\u{0020}lives.\u{0020}Senhaku\u{0020}even\u{0020}used\u{0020}some\u{0020}means\u{0020}to\u{0020}bring\u{0020}this\u{0020}matter\u{0020}to\u{0020}the\u{0020}senior\u{0020}management\u{0020}of\u{0020}AEGIS\u{0020}and\u{0020}asked\u{0020}them\u{0020}to\u{0020}send\u{0020}someone\u{0020}to\u{0020}mediate.\n\nThe\u{0020}final\u{0020}mediation\u{0020}result\u{0020}was\u{0020}that\u{0020}the\u{0020}Fledgling\u{0020}Project\u{0020}proceeded\u{0020}as\u{0020}scheduled,\u{0020}but\u{0020}the\u{0020}selection\u{0020}method\u{0020}for\u{0020}the\u{0020}drivers\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle\u{0020}changed\u{0020}from\u{0020}a\u{0020}lottery\u{0020}system\u{0020}to\u{0020}being\u{0020}designated\u{0020}by\u{0020}the\u{0020}student\u{0020}union.\n\nAfter\u{0020}comparing\u{0020}the\u{0020}files\u{0020}of\u{0020}nearly\u{0020}a\u{0020}thousand\u{0020}people\u{0020}in\u{0020}the\u{0020}college,\u{0020}Senhaku\u{0020}only\u{0020}selected\u{0020}two\u{0020}people\u{0020}to\u{0020}become\u{0020}drivers.\u{0020}One\u{0020}was\u{0020}Karen,\u{0020}a\u{0020}student\u{0020}from\u{0020}Katya,\u{0020}and\u{0020}the\u{0020}other\u{0020}was\u{0020}Senhaku\u{0020}herself.\u{0020}Since\u{0020}the\u{0020}number\u{0020}of\u{0020}drivers\u{0020}required\u{0020}for\u{0020}the\u{0020}Fledgling\u{0020}Project\u{0020}was\u{0020}four,\u{0020}Senhaku\u{0020}delegated\u{0020}the\u{0020}authority\u{0020}to\u{0020}Karen\u{0020}to\u{0020}select\u{0020}two\u{0020}suitable\u{0020}classmates\u{0020}to\u{0020}join\u{0020}the\u{0020}team.\n\nAfter\u{0020}the\u{0020}establishment\u{0020}of\u{0020}the\u{0020}Fledgeling\u{0020}Eagle,\u{0020}Senhaku\u{0020}even\u{0020}entrusted\u{0020}the\u{0020}position\u{0020}of\u{0020}team\u{0020}leader\u{0020}to\u{0020}inexperienced\u{0020}Karen.\n\nThe\u{0020}reason\u{0020}given\u{0020}by\u{0020}Senhaku\u{0020}for\u{0020}this\u{0020}is\u{0020}-\n\nAs\u{0020}the\u{0020}president\u{0020}of\u{0020}the\u{0020}student\u{0020}council,\u{0020}I\u{0020}need\u{0020}to\u{0020}be\u{0020}responsible\u{0020}for\u{0020}all\u{0020}the\u{0020}students\u{0020}of\u{0020}the\u{0020}school\u{0020}first.", "0", "0", "0", "0", 11029, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[612904] = {612904, 2000, "\u{0020}\u{0020}On\u{0020}the\u{0020}yellow\u{0020}sand,\u{0020}one\u{0020}person,\u{0020}one\u{0020}eagle\u{0020}and\u{0020}one\u{0020}gun.\n\nIn\u{0020}the\u{0020}distance,\u{0020}the\u{0020}smoke\u{0020}and\u{0020}dust\u{0020}are\u{0020}like\u{0020}waves,\u{0020}and\u{0020}the\u{0020}charging\u{0020}beasts\u{0020}form\u{0020}a\u{0020}tsunami.\n\nSenhaku's\u{0020}eyes\u{0020}showed\u{0020}no\u{0020}trace\u{0020}of\u{0020}panic,\u{0020}and\u{0020}her\u{0020}huge\u{0020}body\u{0020}was\u{0020}like\u{0020}a\u{0020}tough\u{0020}wave-breaking\u{0020}stone.\n\nThe\u{0020}law\u{0020}of\u{0020}the\u{0020}jungle,\u{0020}survival\u{0020}of\u{0020}the\u{0020}fittest...\n\nThis\u{0020}is\u{0020}the\u{0020}law\u{0020}of\u{0020}survival,\u{0020}but\u{0020}not\u{0020}the\u{0020}law\u{0020}of\u{0020}social\u{0020}development.\n\nA\u{0020}huge\u{0020}shadow\u{0020}came\u{0020}from\u{0020}behind\u{0020}him,\u{0020}one\u{0020}after\u{0020}another\u{0020}wave-breaking\u{0020}stones.\n\nCentering\u{0020}on\u{0020}Senhaku,\u{0020}they\u{0020}lined\u{0020}up\u{0020}in\u{0020}a\u{0020}row,\u{0020}and\u{0020}their\u{0020}bodies\u{0020}built\u{0020}a\u{0020}magnificent\u{0020}dam.\n\n\"Students,\u{0020}let\u{0020}Sin\u{0020}experience...\u{0020}the\u{0020}rules\u{0020}of\u{0020}mankind.\"", "0", "0", "0", "0", 11029, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
