[613001] = {613001, 100, "\u{0020}\u{0020}From\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nIt\u{0020}seems\u{0020}that\u{0020}my\u{0020}team\u{0020}members\u{0020}are\u{0020}a\u{0020}bit\u{0020}strange,\u{0020}but\u{0020}it\u{0020}doesn't\u{0020}matter.\u{0020}We\u{0020}will\u{0020}definitely\u{0020}make\u{0020}it.\u{0020}Everyone\u{0020}is\u{0020}a\u{0020}chosen\u{0020}talent.\u{0020}No\u{0020}difficulty\u{0020}can\u{0020}defeat\u{0020}us.\u{0020}I\u{0020}believe\u{0020}in\u{0020}everyone...\u{0020}Should\u{0020}be\u{0020}no\u{0020}problem,\u{0020}right?\n\nWhen\u{0020}going\u{0020}on\u{0020}a\u{0020}trip,\u{0020}I\u{0020}was\u{0020}entrusted\u{0020}by\u{0020}Xiaomeng's\u{0020}mother\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}Xiaomeng.\u{0020}This\u{0020}is\u{0020}\"Martialist\"\u{0020}Xiaomeng.\u{0020}Do\u{0020}I\u{0020}still\u{0020}need\u{0020}to\u{0020}worry?\u{0020}Why\u{0020}is\u{0020}it\u{0020}so\u{0020}solemn\u{0020}and\u{0020}serious...\u{0020}It\u{0020}should\u{0020}be\u{0020}fine...\n\nThose\u{0020}who\u{0020}were\u{0020}helped\u{0020}by\u{0020}Zhaowu\u{0020}also\u{0020}came\u{0020}to\u{0020}ask\u{0020}me\u{0020}to\u{0020}take\u{0020}good\u{0020}care\u{0020}of\u{0020}Zhaowu.\u{0020}Truly,\u{0020}Zhaowu\u{0020}is\u{0020}a\u{0020}master.\u{0020}So\u{0020}many\u{0020}people\u{0020}have\u{0020}come.\u{0020}Although\u{0020}she\u{0020}seems\u{0020}a\u{0020}little\u{0020}shy\u{0020}and\u{0020}dares\u{0020}not\u{0020}look\u{0020}me\u{0020}in\u{0020}the\u{0020}eye,\u{0020}it\u{0020}will\u{0020}definitely\u{0020}be\u{0020}fine.\n\nAnd\u{0020}Shaoyin...\u{0020}is\u{0020}respected\u{0020}by\u{0020}many\u{0020}people,\u{0020}and\u{0020}her\u{0020}family\u{0020}members\u{0020}also\u{0020}came\u{0020}to\u{0020}ask\u{0020}me...\u{0020}How\u{0020}does\u{0020}it\u{0020}feel\u{0020}a\u{0020}bit\u{0020}strange...\u{0020}Will\u{0020}there\u{0020}be\u{0020}no\u{0020}problem.\n\nBut\u{0020}I'm\u{0020}the\u{0020}captain\u{0020}after\u{0020}all,\u{0020}so\u{0020}I'll\u{0020}agree\u{0020}first.", "0", "0", "0", "0", 11030, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613002] = {613002, 500, "\u{0020}\u{0020}From\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nBeen\u{0020}deceived.\n\nAs\u{0020}a\u{0020}\"Historican\",\u{0020}I\u{0020}unexpectedly\u{0020}fell\u{0020}for\u{0020}such\u{0020}a\u{0020}trick...\u{0020}I\u{0020}have\u{0020}no\u{0020}dissatisfaction\u{0020}with\u{0020}my\u{0020}friends,\u{0020}but\u{0020}I\u{0020}feel\u{0020}helpless\u{0020}towards\u{0020}their\u{0020}families,\u{0020}teachers,\u{0020}and\u{0020}friends.\u{0020}These\u{0020}people\u{0020}who\u{0020}speak\u{0020}half\u{0020}and\u{0020}run\u{0020}away,\u{0020}making\u{0020}people\u{0020}uneasy\u{0020}and\u{0020}causing\u{0020}random\u{0020}thoughts.\n\nAlthough\u{0020}the\u{0020}gentle,\u{0020}powerful\u{0020}and\u{0020}wise\u{0020}character\u{0020}image\u{0020}I\u{0020}imagined\u{0020}in\u{0020}my\u{0020}heart\u{0020}has\u{0020}collapsed,\u{0020}aren't\u{0020}everyone\u{0020}quite\u{0020}normal?\u{0020}Isn't\u{0020}it\u{0020}natural\u{0020}to\u{0020}have\u{0020}some\u{0020}flaws?\u{0020}Rather,\u{0020}they\u{0020}are\u{0020}still\u{0020}gentle,\u{0020}powerful\u{0020}and\u{0020}wise\u{0020}now.\n\nFrom\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nSo\u{0020}it\u{0020}is\u{0020}like\u{0020}this.\u{0020}I\u{0020}understand.\n\nSo\u{0020}even\u{0020}if\u{0020}you\u{0020}blame\u{0020}me\u{0020}afterwards,\u{0020}Xiaomeng,\u{0020}I'm\u{0020}going\u{0020}to\u{0020}make\u{0020}a\u{0020}move\u{0020}on\u{0020}you.\n\nFrom\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nI\u{0020}want\u{0020}to\u{0020}tell\u{0020}Zhaowu\u{0020}that\u{0020}there\u{0020}aren't\u{0020}so\u{0020}many\u{0020}sins\u{0020}in\u{0020}this\u{0020}world\u{0020}for\u{0020}you\u{0020}to\u{0020}bear.\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}her\u{0020}that\u{0020}you\u{0020}are\u{0020}already\u{0020}great.\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}her\u{0020}that\u{0020}it\u{0020}has\u{0020}been\u{0020}hard\u{0020}for\u{0020}you\u{0020}to\u{0020}persist\u{0020}until\u{0020}now.\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}her\u{0020}that\u{0020}it's\u{0020}okay\u{0020}not\u{0020}to\u{0020}work.\u{0020}I\u{0020}want\u{0020}her\u{0020}to\u{0020}have\u{0020}less\u{0020}stress\u{0020}-\n\nThis\u{0020}is\u{0020}not\u{0020}because\u{0020}of\u{0020}being\u{0020}asked,\u{0020}nor\u{0020}because\u{0020}of\u{0020}my\u{0020}\"responsibility\",\u{0020}but...\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}you.\n\nFrom\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nI\u{0020}will\u{0020}be\u{0020}moved\u{0020}by\u{0020}those\u{0020}who\u{0020}have\u{0020}devoted\u{0020}themselves\u{0020}to\u{0020}martial\u{0020}arts\u{0020}for\u{0020}many\u{0020}years\u{0020}and\u{0020}reached\u{0020}the\u{0020}peak.\u{0020}But\u{0020}if\u{0020}such\u{0020}a\u{0020}person\u{0020}fails\u{0020}to\u{0020}restrain\u{0020}themselves\u{0020}and,\u{0020}relying\u{0020}on\u{0020}their\u{0020}own\u{0020}strength,\u{0020}disrupts\u{0020}everyone's\u{0020}peace\u{0020}and\u{0020}does\u{0020}things\u{0020}that\u{0020}make\u{0020}everyone\u{0020}cry,\u{0020}it's\u{0020}too\u{0020}heartbreaking.\u{0020}I\u{0020}don't\u{0020}want\u{0020}Xiaomeng\u{0020}to\u{0020}become\u{0020}such\u{0020}a\u{0020}person,\u{0020}but\u{0020}I\u{0020}also\u{0020}don't\u{0020}want\u{0020}to\u{0020}blame\u{0020}Xiaomeng.\u{0020}After\u{0020}all,\u{0020}she\u{0020}hasn't\u{0020}done\u{0020}anything\u{0020}wrong.\n\nFrom\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nOccasionally,\u{0020}you\u{0020}can\u{0020}act\u{0020}spoiled\u{0020}to\u{0020}me,\u{0020}Shaoyin.", "0", "0", "0", "0", 11030, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613003] = {613003, 1000, "\u{0020}\u{0020}From\u{0020}the\u{0020}captain\u{0020}of\u{0020}Ping\u{0020}Xin,\u{0020}Chenglian's\u{0020}diary:\n\nAEGIS\u{0020}is\u{0020}really\u{0020}a\u{0020}peculiar\u{0020}place.\n\nAlthough\u{0020}humanity\u{0020}is\u{0020}facing\u{0020}a\u{0020}major\u{0020}enemy\u{0020}at\u{0020}present,\u{0020}this\u{0020}place\u{0020}is\u{0020}full\u{0020}of\u{0020}interesting\u{0020}and\u{0020}distinctive\u{0020}people,\u{0020}as\u{0020}if\u{0020}only\u{0020}by\u{0020}being\u{0020}interesting\u{0020}can\u{0020}one\u{0020}have\u{0020}the\u{0020}Compatability\u{0020}Rate.\n\nNavigator\u{0020}is\u{0020}also\u{0020}a\u{0020}wonderful\u{0020}person.\u{0020}I\u{0020}have\u{0020}never\u{0020}seen\u{0020}such\u{0020}a\u{0020}pure\u{0020}person,\u{0020}the\u{0020}only\u{0020}synesthete.\u{0020}I\u{0020}don't\u{0020}know\u{0020}what\u{0020}kind\u{0020}of\u{0020}story\u{0020}he\u{0020}has\u{0020}and\u{0020}what\u{0020}drives\u{0020}his\u{0020}actions?\u{0020}Let\u{0020}me\u{0020}listen\u{0020}slowly.\u{0020}There\u{0020}are\u{0020}still\u{0020}many\u{0020}people...\n\nAnd\u{0020}my\u{0020}task\u{0020}is\u{0020}to\u{0020}record\u{0020}these\u{0020}events\u{0020}and\u{0020}these\u{0020}people,\u{0020}write\u{0020}them\u{0020}into\u{0020}a\u{0020}history,\u{0020}leave\u{0020}this\u{0020}history\u{0020}that\u{0020}emerged\u{0020}suddenly\u{0020}like\u{0020}a\u{0020}fantasy\u{0020}story,\u{0020}this\u{0020}history\u{0020}of\u{0020}human\u{0020}survival\u{0020}and\u{0020}struggle,\u{0020}to\u{0020}future\u{0020}generations\u{0020}without\u{0020}reservation,\u{0020}to\u{0020}prove\u{0020}that\u{0020}some\u{0020}people\u{0020}existed\u{0020}and\u{0020}saved\u{0020}the\u{0020}world,\u{0020}and\u{0020}bring\u{0020}this\u{0020}hope\u{0020}to\u{0020}future\u{0020}generations.\n\nSo\u{0020}we\u{0020}will\u{0020}surely\u{0020}succeed.", "0", "0", "0", "0", 11030, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[613004] = {613004, 2000, "\u{0020}\u{0020}Don't\u{0020}give\u{0020}up\u{0020}easily.\n\nI\u{0020}made\u{0020}such\u{0020}a\u{0020}wish.\n\nI\u{0020}want\u{0020}to\u{0020}celebrate\u{0020}for\u{0020}you\u{0020}on\u{0020}a\u{0020}certain\u{0020}day\u{0020}in\u{0020}the\u{0020}future.\n\nI\u{0020}will\u{0020}witness\u{0020}you\u{0020}proudly\u{0020}and\u{0020}cheer\u{0020}for\u{0020}you.\n\nEven\u{0020}though\u{0020}the\u{0020}world\u{0020}is\u{0020}still\u{0020}noisy\u{0020}today,\n\nBut\u{0020}you\u{0020}will\u{0020}be\u{0020}like\u{0020}the\u{0020}hero\u{0020}in\u{0020}the\u{0020}story\n\nMy\u{0020}hero.", "0", "0", "0", "0", 11030, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
