[613101] = {613101, 100, "\u{0020}\u{0020}Levi\u{0020}always\u{0020}shows\u{0020}strong\u{0020}hostility\u{0020}when\u{0020}seeing\u{0020}strangers\u{0020}and\u{0020}is\u{0020}extremely\u{0020}sensitive\u{0020}to\u{0020}the\u{0020}changes\u{0020}around\u{0020}her,\u{0020}just\u{0020}like\u{0020}a\u{0020}mother\u{0020}beast\u{0020}guarding\u{0020}her\u{0020}cubs,\u{0020}always\u{0020}paying\u{0020}attention\u{0020}to\u{0020}the\u{0020}slightest\u{0020}movement\u{0020}around.\u{0020}But\u{0020}you\u{0020}don't\u{0020}have\u{0020}to\u{0020}worry\u{0020}that\u{0020}she\u{0020}will\u{0020}take\u{0020}excessive\u{0020}actions\u{0020}as\u{0020}long\u{0020}as\u{0020}you\u{0020}don't\u{0020}make\u{0020}threatening\u{0020}moves\u{0020}first.\n\nJust\u{0020}as\u{0020}mentioned\u{0020}above,\u{0020}Levi's\u{0020}hostility\u{0020}is\u{0020}to\u{0020}protect\u{0020}herself\u{0020}and\u{0020}also\u{0020}to\u{0020}protect\u{0020}her\u{0020}sister\u{0020}-\u{0020}Rebecca.\u{0020}This\u{0020}might\u{0020}be\u{0020}a\u{0020}character\u{0020}trait\u{0020}developed\u{0020}since\u{0020}the\u{0020}two\u{0020}of\u{0020}them\u{0020}were\u{0020}sold\u{0020}to\u{0020}the\u{0020}laboratory.\u{0020}After\u{0020}all,\u{0020}at\u{0020}that\u{0020}time\u{0020}Levi\u{0020}was\u{0020}5\u{0020}years\u{0020}old\u{0020}and\u{0020}Rebecca\u{0020}was\u{0020}only\u{0020}3\u{0020}years\u{0020}old.\u{0020}As\u{0020}the\u{0020}\"elder\u{0020}sister\",\u{0020}Levi\u{0020}had\u{0020}to\u{0020}undertake\u{0020}more.\n\nPerhaps\u{0020}Levi\u{0020}was\u{0020}influenced\u{0020}by\u{0020}the\u{0020}non-human\u{0020}part\u{0020}within\u{0020}her\u{0020}body.\n\nThe\u{0020}gigantification\u{0020}of\u{0020}the\u{0020}two\u{0020}members\u{0020}of\u{0020}the\u{0020}Hydra\u{0020}team\u{0020}is\u{0020}completely\u{0020}different\u{0020}from\u{0020}that\u{0020}of\u{0020}other\u{0020}teams\u{0020}and\u{0020}should\u{0020}be\u{0020}called\u{0020}\"Sinification\".\u{0020}Like\u{0020}Rebecca,\u{0020}\"Lailaps\"\u{0020}is\u{0020}Levi's\u{0020}code\u{0020}name\u{0020}to\u{0020}distinguish\u{0020}her\u{0020}from\u{0020}Sin.\u{0020}But\u{0020}unlike\u{0020}Rebecca,\u{0020}\"Lily\"\u{0020}wants\u{0020}to\u{0020}protect\u{0020}more\u{0020}people,\u{0020}while\u{0020}\"Lailaps\"\u{0020}only\u{0020}wants\u{0020}to\u{0020}protect\u{0020}Rebecca.", "0", "0", "0", "0", 11031, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613102] = {613102, 500, "\u{0020}\u{0020}Because\u{0020}Levi\u{0020}was\u{0020}two\u{0020}years\u{0020}older\u{0020}than\u{0020}Rebecca,\u{0020}she\u{0020}remembered\u{0020}more\u{0020}clearly\u{0020}the\u{0020}brilliant\u{0020}and\u{0020}distorted\u{0020}smiles\u{0020}on\u{0020}their\u{0020}parents'\u{0020}faces\u{0020}when\u{0020}they\u{0020}received\u{0020}the\u{0020}food\u{0020}exchanged\u{0020}for\u{0020}their\u{0020}own\u{0020}daughter.\n\nAll\u{0020}the\u{0020}children\u{0020}sent\u{0020}to\u{0020}the\u{0020}\"Regeneration\u{0020}Project\"\u{0020}laboratory,\u{0020}including\u{0020}Rebecca,\u{0020}were\u{0020}immersed\u{0020}in\u{0020}crying\u{0020}loudly\u{0020}due\u{0020}to\u{0020}the\u{0020}unease\u{0020}and\u{0020}helplessness\u{0020}of\u{0020}leaving\u{0020}their\u{0020}parents.\u{0020}Only\u{0020}Levi's\u{0020}heart\u{0020}was\u{0020}occupied\u{0020}by\u{0020}anger.\n\nWhy\u{0020}give\u{0020}birth\u{0020}to\u{0020}her?\u{0020}Why\u{0020}raise\u{0020}her?\u{0020}Why\u{0020}abandon\u{0020}her?\n\nBut\u{0020}anger\u{0020}was\u{0020}of\u{0020}no\u{0020}use\u{0020}to\u{0020}a\u{0020}five-year-old\u{0020}child,\u{0020}so\u{0020}Levi's\u{0020}situation\u{0020}was\u{0020}no\u{0020}different\u{0020}from\u{0020}other\u{0020}children.\u{0020}The\u{0020}only\u{0020}difference\u{0020}was\u{0020}that\u{0020}Levi\u{0020}survived\u{0020}the\u{0020}inhumane\u{0020}human\u{0020}experiments\u{0020}one\u{0020}after\u{0020}another,\u{0020}while\u{0020}most\u{0020}children\u{0020}died\u{0020}in\u{0020}the\u{0020}process.\n\nThe\u{0020}three-year-long\u{0020}hellish\u{0020}experiments.\u{0020}At\u{0020}the\u{0020}beginning,\u{0020}there\u{0020}were\u{0020}dozens\u{0020}of\u{0020}healthy\u{0020}children,\u{0020}and\u{0020}in\u{0020}the\u{0020}end,\u{0020}only\u{0020}Levi\u{0020}and\u{0020}Rebecca\u{0020}remained.\u{0020}In\u{0020}this\u{0020}inescapable\u{0020}hell,\u{0020}the\u{0020}two\u{0020}of\u{0020}them\u{0020}were\u{0020}the\u{0020}only\u{0020}reliance\u{0020}for\u{0020}each\u{0020}other.\u{0020}Levi\u{0020}took\u{0020}on\u{0020}the\u{0020}responsibility\u{0020}of\u{0020}an\u{0020}elder\u{0020}sister\u{0020}and\u{0020}took\u{0020}care\u{0020}of\u{0020}Rebecca's\u{0020}daily\u{0020}life.\u{0020}The\u{0020}scientific\u{0020}officers\u{0020}of\u{0020}the\u{0020}laboratory\u{0020}would\u{0020}not\u{0020}care\u{0020}about\u{0020}the\u{0020}lives\u{0020}of\u{0020}the\u{0020}experimental\u{0020}subjects\u{0020}and\u{0020}only\u{0020}provided\u{0020}the\u{0020}most\u{0020}basic\u{0020}living\u{0020}materials.\u{0020}Here,\u{0020}they\u{0020}had\u{0020}no\u{0020}so-called\u{0020}personality.\n\nIt\u{0020}was\u{0020}not\u{0020}until\u{0020}AEGIS\u{0020}shut\u{0020}down\u{0020}the\u{0020}\"Regeneration\u{0020}Project\"\u{0020}that\u{0020}the\u{0020}two\u{0020}sisters\u{0020}were\u{0020}finally\u{0020}liberated.\u{0020}They\u{0020}were\u{0020}assigned\u{0020}to\u{0020}Josephine\u{0020}Bernardskaya\u{0020}-\u{0020}an\u{0020}AEGIS\u{0020}scientific\u{0020}officer\u{0020}and\u{0020}the\u{0020}person\u{0020}in\u{0020}charge\u{0020}of\u{0020}the\u{0020}\"Regeneration\u{0020}Project\"\u{0020}for\u{0020}upbringing.\n\nLevi\u{0020}was\u{0020}originally\u{0020}hostile\u{0020}to\u{0020}Josephine.\u{0020}She\u{0020}did\u{0020}not\u{0020}know\u{0020}Josephine's\u{0020}true\u{0020}identity,\u{0020}but\u{0020}it\u{0020}was\u{0020}just\u{0020}a\u{0020}natural\u{0020}reaction\u{0020}developed\u{0020}in\u{0020}these\u{0020}three\u{0020}years.\u{0020}But\u{0020}as\u{0020}Josephine\u{0020}took\u{0020}them\u{0020}to\u{0020}run\u{0020}a\u{0020}pet\u{0020}store\u{0020}for\u{0020}a\u{0020}period\u{0020}of\u{0020}time,\u{0020}this\u{0020}hostility\u{0020}gradually\u{0020}melted\u{0020}in\u{0020}the\u{0020}sincerity\u{0020}and\u{0020}warmth\u{0020}of\u{0020}the\u{0020}small\u{0020}animals.\n\nThen\u{0020}unconsciously,\u{0020}they\u{0020}spent\u{0020}ten\u{0020}years\u{0020}in\u{0020}the\u{0020}pet\u{0020}store.\u{0020}But\u{0020}the\u{0020}ten\u{0020}years\u{0020}of\u{0020}stable\u{0020}life\u{0020}did\u{0020}not\u{0020}completely\u{0020}erase\u{0020}the\u{0020}influence\u{0020}brought\u{0020}by\u{0020}those\u{0020}three\u{0020}years.\u{0020}Especially\u{0020}when\u{0020}Rebecca\u{0020}said\u{0020}that\u{0020}she\u{0020}heard\u{0020}that\u{0020}voice,\u{0020}Levi\u{0020}knew\u{0020}that\u{0020}everything\u{0020}was\u{0020}not\u{0020}over.\n\n\"I\u{0020}want\u{0020}to\u{0020}protect\u{0020}Rebecca.\u{0020}For\u{0020}this,\u{0020}no\u{0020}matter\u{0020}what\u{0020}I\u{0020}become,\u{0020}I\u{0020}have\u{0020}no\u{0020}complaints.\"", "0", "0", "0", "0", 11031, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613103] = {613103, 1000, "\u{0020}\u{0020}Levi\u{0020}doesn't\u{0020}like\u{0020}Ark,\u{0020}not\u{0020}only\u{0020}because\u{0020}of\u{0020}her\u{0020}dislike\u{0020}for\u{0020}AEGIS.\u{0020}Although\u{0020}life\u{0020}on\u{0020}Ark\u{0020}is\u{0020}easier\u{0020}than\u{0020}running\u{0020}a\u{0020}pet\u{0020}store,\u{0020}the\u{0020}cold\u{0020}walls\u{0020}here\u{0020}always\u{0020}remind\u{0020}her\u{0020}of\u{0020}the\u{0020}time\u{0020}when\u{0020}she\u{0020}was\u{0020}imprisoned\u{0020}as\u{0020}an\u{0020}experimental\u{0020}subject\u{0020}in\u{0020}the\u{0020}laboratory\u{0020}before.\n\nLevi\u{0020}will\u{0020}stay\u{0020}in\u{0020}Ark,\u{0020}not\u{0020}only\u{0020}because\u{0020}Rebecca\u{0020}is\u{0020}here,\u{0020}but\u{0020}also\u{0020}because\u{0020}she\u{0020}chooses\u{0020}to\u{0020}trust\u{0020}the\u{0020}navigator\u{0020}who\u{0020}has\u{0020}helped\u{0020}her.\u{0020}She\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}be\u{0020}someone\u{0020}like\u{0020}Josephine,\u{0020}trusting\u{0020}nothing\u{0020}and\u{0020}getting\u{0020}nothing.\n\nWith\u{0020}Stephanie's\u{0020}treatment,\u{0020}Levi\u{0020}and\u{0020}Rebecca\u{0020}were\u{0020}able\u{0020}to\u{0020}control\u{0020}the\u{0020}mutations\u{0020}in\u{0020}their\u{0020}bodies,\u{0020}and\u{0020}they\u{0020}could\u{0020}even\u{0020}transform\u{0020}into\u{0020}Sin\u{0020}while\u{0020}maintaining\u{0020}a\u{0020}rational\u{0020}state\u{0020}for\u{0020}combat\u{0020}training.\u{0020}Levi's\u{0020}favorite\u{0020}time\u{0020}was\u{0020}during\u{0020}simulated\u{0020}combat\u{0020}training,\u{0020}where\u{0020}she\u{0020}could\u{0020}vent\u{0020}all\u{0020}her\u{0020}anger.\n\nBut\u{0020}in\u{0020}addition\u{0020}to\u{0020}venting,\u{0020}she\u{0020}can't\u{0020}help\u{0020}but\u{0020}think,\u{0020}if\u{0020}one\u{0020}day\u{0020}she\u{0020}and\u{0020}Rebecca\u{0020}return\u{0020}to\u{0020}normal,\u{0020}what\u{0020}will\u{0020}they\u{0020}do\u{0020}then?", "0", "0", "0", "0", 11031, "0", "0", "0", "