[613201] = {613201, 100, "\u{0020}\u{0020}Her\u{0020}name,\u{0020}Chiaki,\u{0020}is\u{0020}a\u{0020}forbidden\u{0020}word\u{0020}in\u{0020}AEGIS.\u{0020}That's\u{0020}not\u{0020}because\u{0020}someone\u{0020}is\u{0020}trying\u{0020}to\u{0020}censor\u{0020}her\u{0020}information.\u{0020}The\u{0020}reason\u{0020}is,\u{0020}staff\u{0020}of\u{0020}AEGIS\u{0020}worry\u{0020}that\u{0020}calling\u{0020}her\u{0020}name\u{0020}directly\u{0020}may\u{0020}cost\u{0020}their\u{0020}lives.\n\nAs\u{0020}a\u{0020}serial\u{0020}killer\u{0020}who\u{0020}conducted\u{0020}lots\u{0020}of\u{0020}felonies,\u{0020}because\u{0020}of\u{0020}her\u{0020}skills\u{0020}of\u{0020}murdering,\u{0020}she\u{0020}was\u{0020}chosen\u{0020}by\u{0020}AEGIS.\u{0020}She\u{0020}was\u{0020}sentenced\u{0020}to\u{0020}join\u{0020}\"Prisoner\"\u{0020}squad\u{0020}by\u{0020}the\u{0020}court.\n\nOn\u{0020}the\u{0020}ark,\u{0020}she\u{0020}is\u{0020}only\u{0020}allowed\u{0020}to\u{0020}stay\u{0020}in\u{0020}her\u{0020}room.\u{0020}Although\u{0020}it's\u{0020}a\u{0020}room,\u{0020}it's\u{0020}more\u{0020}like\u{0020}a\u{0020}cell.\u{0020}Inside,\u{0020}there\u{0020}are\u{0020}only\u{0020}some\u{0020}simple\u{0020}furnitures,\u{0020}like\u{0020}a\u{0020}metal\u{0020}bed,\u{0020}a\u{0020}clothes\u{0020}stand,\u{0020}and\u{0020}a\u{0020}small\u{0020}wooden\u{0020}table.\n\nThe\u{0020}entrance\u{0020}of\u{0020}that\u{0020}room\u{0020}isn't\u{0020}locked.\u{0020}However,\u{0020}if\u{0020}she\u{0020}takes\u{0020}a\u{0020}single\u{0020}step\u{0020}outside,\u{0020}she\u{0020}will\u{0020}trigger\u{0020}the\u{0020}alarm\u{0020}and\u{0020}will\u{0020}be\u{0020}\"asked\"\u{0020}to\u{0020}go\u{0020}back\u{0020}in\u{0020}a\u{0020}strong\u{0020}manner\u{0020}by\u{0020}the\u{0020}security\u{0020}forces.\n\nChiaki\u{0020}has\u{0020}thought\u{0020}about\u{0020}\"killing\u{0020}everyone\u{0020}on\u{0020}the\u{0020}ark\"\u{0020}multiple\u{0020}times,\u{0020}she\u{0020}knows\u{0020}she's\u{0020}capable\u{0020}of\u{0020}that.\u{0020}But\u{0020}to\u{0020}get\u{0020}the\u{0020}real\u{0020}freedom,\u{0020}by\u{0020}meeting\u{0020}the\u{0020}\"finish\u{0020}100\u{0020}missions\"\u{0020}condition\u{0020}set\u{0020}by\u{0020}Stephanie,\u{0020}she\u{0020}decides\u{0020}to\u{0020}spare\u{0020}their\u{0020}lives,\u{0020}for\u{0020}now.", "0", "0", "0", "0", 11032, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613202] = {613202, 500, "\u{0020}\u{0020}Before\u{0020}we\u{0020}start\u{0020}stating\u{0020}Ckiaki's\u{0020}past,\u{0020}you\u{0020}have\u{0020}to\u{0020}know\u{0020}one\u{0020}thing:\u{0020}she\u{0020}hasn't\u{0020}been\u{0020}chosen\u{0020}by\u{0020}anyone\u{0020}yet.\n\nAnd\u{0020}her\u{0020}life\u{0020}wasn't\u{0020}started\u{0020}in\u{0020}a\u{0020}wrong\u{0020}way.\n\nBefore\u{0020}her\u{0020}\"story\"\u{0020}began,\u{0020}she\u{0020}never\u{0020}considered\u{0020}herself\u{0020}as\u{0020}peculiar.\n\nOf\u{0020}course,\u{0020}she\u{0020}also\u{0020}didn't\u{0020}feel\u{0020}her\u{0020}excitement\u{0020}towards\u{0020}blood\u{0020}is\u{0020}normal.\u{0020}But\u{0020}that\u{0020}was\u{0020}only\u{0020}\"special\",\u{0020}not\u{0020}a\u{0020}\"heresy\".\n\nAlthough\u{0020}she\u{0020}had\u{0020}some\u{0020}mindsets\u{0020}that\u{0020}were\u{0020}not\u{0020}generally\u{0020}accepted\u{0020}by\u{0020}others,\u{0020}no\u{0020}one\u{0020}said\u{0020}that\u{0020}people\u{0020}like\u{0020}her\u{0020}would\u{0020}never\u{0020}have\u{0020}a\u{0020}joyful\u{0020}life.\u{0020}Even\u{0020}if\u{0020}she\u{0020}couldn't\u{0020}have\u{0020}happiness,\u{0020}her\u{0020}\"normal\"\u{0020}life\u{0020}shouldn't\u{0020}be\u{0020}taken\u{0020}away.\n\nSo,\u{0020}what\u{0020}went\u{0020}wrong?\n\nShe\u{0020}stays\u{0020}in\u{0020}her\u{0020}cell,\u{0020}touches\u{0020}those\u{0020}scissors\u{0020}which\u{0020}used\u{0020}to\u{0020}be\u{0020}covered\u{0020}with\u{0020}blood,\u{0020}maybe\u{0020}thought\u{0020}about\u{0020}that\u{0020}more\u{0020}than\u{0020}once.\n\nAt\u{0020}least\u{0020}in\u{0020}her\u{0020}opinion,\u{0020}or\u{0020}even\u{0020}in\u{0020}the\u{0020}public\u{0020}opinion,\u{0020}that\u{0020}event\u{0020}happened\u{0020}to\u{0020}her\u{0020}is\u{0020}a\u{0020}mere\u{0020}\"accident\".\u{0020}She's\u{0020}more\u{0020}a\u{0020}\"victim\"\u{0020}rather\u{0020}than\u{0020}a\u{0020}participant.\n\nActually,\u{0020}in\u{0020}that\u{0020}incident,\u{0020}she's\u{0020}a\u{0020}\"victim\",\u{0020}but\u{0020}also\u{0020}a\u{0020}\"collaborator\".\n\nLet's\u{0020}go\u{0020}back\u{0020}to\u{0020}the\u{0020}moment\u{0020}when\u{0020}it\u{0020}happened.\n\nThat\u{0020}should've\u{0020}been\u{0020}a\u{0020}normal\u{0020}afternoon,\u{0020}just\u{0020}like\u{0020}other\u{0020}days.If\u{0020}we\u{0020}try\u{0020}to\u{0020}find\u{0020}the\u{0020}difference\u{0020}scrutinizingly,\u{0020}it\u{0020}was\u{0020}more\u{0020}humid\u{0020}than\u{0020}normal.\n\nBecause\u{0020}it\u{0020}was\u{0020}a\u{0020}weekend,\u{0020}Chiaki\u{0020}took\u{0020}a\u{0020}nap.\u{0020}She\u{0020}woke\u{0020}up,\u{0020}felt\u{0020}a\u{0020}little\u{0020}dizzy,\u{0020}perhaps\u{0020}that's\u{0020}because\u{0020}of\u{0020}that\u{0020}fan\u{0020}which\u{0020}was\u{0020}blowing\u{0020}air\u{0020}towards\u{0020}her\u{0020}continuously.\n\nShe\u{0020}put\u{0020}on\u{0020}her\u{0020}sandals,\u{0020}walked\u{0020}from\u{0020}2F\u{0020}of\u{0020}her\u{0020}home\u{0020}towards\u{0020}the\u{0020}living\u{0020}room\u{0020}downstairs.\u{0020}She\u{0020}heard\u{0020}the\u{0020}quarrel,\u{0020}but\u{0020}not\u{0020}her\u{0020}parents'\u{0020}voices.\u{0020}She\u{0020}wasn't\u{0020}agitated\u{0020}or\u{0020}nervous:\u{0020}that\u{0020}sounded\u{0020}like\u{0020}her\u{0020}neighbor\u{0020}was\u{0020}arguing\u{0020}with\u{0020}someone\u{0020}else.\n\nWhen\u{0020}she\u{0020}arrived\u{0020}at\u{0020}the\u{0020}living\u{0020}room,\u{0020}she\u{0020}finally\u{0020}sensed\u{0020}something\u{0020}wrong.\n\nThe\u{0020}air\u{0020}was\u{0020}a\u{0020}little\u{0020}bit\u{0020}humid,\u{0020}an\u{0020}unfamiliar\u{0020}odor\u{0020}mixed\u{0020}with\u{0020}the\u{0020}air.\u{0020}In\u{0020}the\u{0020}living\u{0020}room,\u{0020}she\u{0020}didn't\u{0020}see\u{0020}her\u{0020}parents.\u{0020}Usually\u{0020}around\u{0020}this\u{0020}time,\u{0020}they\u{0020}should\u{0020}be\u{0020}watching\u{0020}TV\u{0020}there.\n\nShe\u{0020}walked\u{0020}towards\u{0020}the\u{0020}front\u{0020}door.\n\nIt\u{0020}wasn't\u{0020}completely\u{0020}closed,\u{0020}voices\u{0020}of\u{0020}quarreling\u{0020}can\u{0020}be\u{0020}heard\u{0020}from\u{0020}the\u{0020}gap.\u{0020}The\u{0020}door\u{0020}opened\u{0020}slowly\u{0020}when\u{0020}she\u{0020}pushed\u{0020}it,\u{0020}and\u{0020}it\u{0020}got\u{0020}stuck.\u{0020}She\u{0020}managed\u{0020}to\u{0020}open\u{0020}it\u{0020}up\u{0020}with\u{0020}some\u{0020}forces.\n\nJust\u{0020}as\u{0020}she\u{0020}had\u{0020}thought,\u{0020}her\u{0020}neighbor\u{0020}was\u{0020}augmenting\u{0020}with\u{0020}someone.\u{0020}But\u{0020}she\u{0020}didn't\u{0020}expect\u{0020}that,\u{0020}her\u{0020}neighbor's\u{0020}child\u{0020}was\u{0020}being\u{0020}taken\u{0020}away.\n\nWho\u{0020}was\u{0020}that,\u{0020}she\u{0020}didn't\u{0020}know,\u{0020}she\u{0020}also\u{0020}didn't\u{0020}care\u{0020}about\u{0020}that\u{0020}child's\u{0020}safety.\n\nBut\u{0020}she\u{0020}found\u{0020}the\u{0020}reason\u{0020}why\u{0020}the\u{0020}door\u{0020}was\u{0020}stuck\u{0020}when\u{0020}she\u{0020}tried\u{0020}to\u{0020}open\u{0020}it\u{0020}up.\n\nHer\u{0020}parents\u{0020}were\u{0020}right\u{0020}next\u{0020}to\u{0020}it.\n\nThey\u{0020}were\u{0020}laying\u{0020}silently\u{0020}out\u{0020}of\u{0020}the\u{0020}door,\u{0020}silently,\u{0020}with\u{0020}their\u{0020}eyes\u{0020}closed.\n\nParents,\u{0020}died.\u{0020}The\u{0020}fatal\u{0020}injury\u{0020}should\u{0020}be\u{0020}the\u{0020}bullets\u{0020}in\u{0020}their\u{0020}chest,\u{0020}there\u{0020}was\u{0020}not\u{0020}much\u{0020}blood,\u{0020}but\u{0020}that\u{0020}was\u{0020}more\u{0020}than\u{0020}enough\u{0020}to\u{0020}take\u{0020}the\u{0020}lives\u{0020}away\u{0020}from\u{0020}two\u{0020}adults.\u{0020}Blood\u{0020}flew\u{0020}because\u{0020}of\u{0020}gravity,\u{0020}with\u{0020}trails\u{0020}that\u{0020}are\u{0020}a\u{0020}little\u{0020}messy,\u{0020}perhaps\u{0020}caused\u{0020}by\u{0020}Chiaki\u{0020}pushing\u{0020}the\u{0020}bodies.\n\n\"...she's\u{0020}peculiar.\"\n\nWhy\u{0020}the\u{0020}neighbor\u{0020}was\u{0020}arguing\u{0020}with\u{0020}someone,\u{0020}Chiaki\u{0020}didn't\u{0020}understand.\u{0020}Why\u{0020}the\u{0020}stranger\u{0020}said\u{0020}that\u{0020}to\u{0020}the\u{0020}neighbor's\u{0020}child,\u{0020}she\u{0020}didn't\u{0020}understand\u{0020}either.\n\nThe\u{0020}only\u{0020}thing\u{0020}she\u{0020}did\u{0020}was\u{0020}walk\u{0020}back\u{0020}to\u{0020}the\u{0020}living\u{0020}room.\u{0020}After\u{0020}ruling\u{0020}out\u{0020}sharp\u{0020}items\u{0020}like\u{0020}nail\u{0020}clippers,\u{0020}cleavers,\u{0020}knives\u{0020}and\u{0020}meat\u{0020}cutters,\u{0020}she\u{0020}chose\u{0020}a\u{0020}paper\u{0020}cutter\u{0020}and\u{0020}a\u{0020}pair\u{0020}of\u{0020}scissors,\u{0020}which\u{0020}she\u{0020}used\u{0020}in\u{0020}her\u{0020}handwork\u{0020}classes.\n\nWhat\u{0020}happened\u{0020}next,\u{0020}even\u{0020}without\u{0020}a\u{0020}detailed\u{0020}description,\u{0020}we\u{0020}can\u{0020}guess\u{0020}that.\n\nChiaki's\u{0020}neighbor,\u{0020}and\u{0020}that\u{0020}stranger\u{0020}who\u{0020}took\u{0020}that\u{0020}child\u{0020}away…were\u{0020}all\u{0020}dead.\n\nThat\u{0020}\"chosen\"\u{0020}child,\u{0020}and\u{0020}Chiaki,\u{0020}survived.\n\nMaybe\u{0020}they\u{0020}were\u{0020}killed\u{0020}by\u{0020}Chiaki,\u{0020}maybe\u{0020}not.\n\nChiaki\u{0020}was\u{0020}the\u{0020}only\u{0020}survivor\u{0020}who\u{0020}possessed\u{0020}weapons,\u{0020}so\u{0020}the\u{0020}role\u{0020}of\u{0020}\"criminal\"\u{0020}can\u{0020}only\u{0020}be\u{0020}hers.\n\nThat's\u{0020}the\u{0020}past\u{0020}of\u{0020}\"Killer\u{0020}Ghost\"\u{0020}Chiaki.", "0", "0", "0", "0", 11032, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613203] = {613203, 1000, "\u{0020}\u{0020}Stephanie\u{0020}is\u{0020}a\u{0020}legend\u{0020}in\u{0020}AEGIS.\u{0020}only\u{0020}she\u{0020}dares\u{0020}to\u{0020}negotiate\u{0020}harsh\u{0020}proposals\u{0020}like\u{0020}her\u{0020}\"100\u{0020}missions\"\u{0020}proposal,\u{0020}with\u{0020}a\u{0020}\"murderer\".\n\n\"If\u{0020}you\u{0020}finish\u{0020}the\u{0020}100\u{0020}missions\u{0020}I\u{0020}ordered,\u{0020}and\u{0020}follow\u{0020}my\u{0020}command.\"\n\n\"And\u{0020}you\u{0020}will\u{0020}have\u{0020}your\u{0020}freedom,\u{0020}your\u{0020}record\u{0020}will\u{0020}be\u{0020}purged.\"\n\nFor\u{0020}freedom,\u{0020}Chiaki\u{0020}forbears\u{0020}her\u{0020}hatred\u{0020}and\u{0020}killing\u{0020}spree\u{0020}towards\u{0020}AEGIS.\u{0020}became\u{0020}an\u{0020}assassin\u{0020}under\u{0020}AEGIS.\n\nBut\u{0020}no\u{0020}one\u{0020}would\u{0020}expect\u{0020}that,\u{0020}one\u{0020}day,\u{0020}she\u{0020}becomes\u{0020}a\u{0020}driver,\u{0020}and\u{0020}under\u{0020}the\u{0020}command\u{0020}of\u{0020}that\u{0020}navigator.\u{0020}Just\u{0020}like\u{0020}that\u{0020}dictum:\n\n\"Like\u{0020}mother,\u{0020}like\u{0020}son.\"", "0", "0", "0", "0", 11032, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
