[613301] = {613301, 100, "\u{0020}\u{0020}Luck\u{0020}is\u{0020}never\u{0020}a\u{0020}standard\u{0020}to\u{0020}estimate\u{0020}one's\u{0020}capabilities,\u{0020}but\u{0020}indeed,\u{0020}there\u{0020}are\u{0020}people\u{0020}who\u{0020}achieve\u{0020}their\u{0020}wishes\u{0020}just\u{0020}by\u{0020}their\u{0020}luck.\n\nThe\u{0020}good\u{0020}luck\u{0020}of\u{0020}Starry\u{0020}is\u{0020}despairing,\u{0020}especially\u{0020}for\u{0020}her\u{0020}enemies.\u{0020}Being\u{0020}antagonized\u{0020}with\u{0020}Starry\u{0020}will\u{0020}bring\u{0020}a\u{0020}fear\u{0020}of\u{0020}being\u{0020}the\u{0020}enemy\u{0020}of\u{0020}the\u{0020}whole\u{0020}world.\u{0020}You'll\u{0020}never\u{0020}know\u{0020}which\u{0020}will\u{0020}come\u{0020}first:\u{0020}an\u{0020}accident\u{0020}or\u{0020}the\u{0020}bullet\u{0020}from\u{0020}Starry's\u{0020}gun.\u{0020}And\u{0020}of\u{0020}course,\u{0020}in\u{0020}most\u{0020}cases\u{0020}they\u{0020}come\u{0020}simultaneously.\n\nBut\u{0020}her\u{0020}good\u{0020}luck\u{0020}is\u{0020}only\u{0020}for\u{0020}herself,\u{0020}which\u{0020}means\u{0020}it\u{0020}often\u{0020}hurts\u{0020}people\u{0020}around\u{0020}her.\u{0020}That's\u{0020}why\u{0020}she\u{0020}can\u{0020}be\u{0020}friends\u{0020}with\u{0020}strangers\u{0020}in\u{0020}a\u{0020}short\u{0020}time\u{0020}while\u{0020}keeping\u{0020}a\u{0020}certain\u{0020}distance\u{0020}with\u{0020}them.\n\nShe\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}see\u{0020}others\u{0020}getting\u{0020}hurt\u{0020}because\u{0020}of\u{0020}her\u{0020}good\u{0020}luck\u{0020}again.\n\n\"Perhaps\u{0020}my\u{0020}good\u{0020}luck\u{0020}is\u{0020}just\u{0020}passing\u{0020}bad\u{0020}luck\u{0020}to\u{0020}people\u{0020}around\u{0020}me…\"\n\n\"But\u{0020}that's\u{0020}fine,\u{0020}I'm\u{0020}good\u{0020}with\u{0020}operations\u{0020}on\u{0020}my\u{0020}own,\u{0020}without\u{0020}constraints\u{0020}and\u{0020}conflicts.\"", "0", "0", "0", "0", 11033, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613302] = {613302, 500, "\u{0020}\u{0020}\"She\u{0020}was\u{0020}an\u{0020}accident.\"\n\nThat\u{0020}was\u{0020}concluded\u{0020}by\u{0020}the\u{0020}chief\u{0020}science\u{0020}officer\u{0020}of\u{0020}Aegis,\u{0020}Stephanie,\u{0020}after\u{0020}learning\u{0020}about\u{0020}Starry's\u{0020}life\u{0020}and\u{0020}serious\u{0020}considerations.\n\nAlthough\u{0020}using\u{0020}\"accident\"\u{0020}to\u{0020}describe\u{0020}one's\u{0020}birth\u{0020}is\u{0020}like\u{0020}what\u{0020}scientists\u{0020}will\u{0020}do,\u{0020}apparently\u{0020}Dr.Stephanie\u{0020}didn't\u{0020}say\u{0020}that\u{0020}because\u{0020}of\u{0020}this.\n\n\"Starry\u{0020}shouldn't\u{0020}exist.\"\n\nShe\u{0020}added\u{0020}that\u{0020}as\u{0020}a\u{0020}complementary\u{0020}conclusion.\n\nBut\u{0020}unfortunately,\u{0020}even\u{0020}though\u{0020}she\u{0020}made\u{0020}that\u{0020}amendment,\u{0020}not\u{0020}everyone\u{0020}can\u{0020}understand\u{0020}how\u{0020}Starry\u{0020}became\u{0020}existing.\n\nEven\u{0020}if\u{0020}we\u{0020}try\u{0020}our\u{0020}best\u{0020}to\u{0020}track\u{0020}her\u{0020}past,\u{0020}we\u{0020}only\u{0020}know\u{0020}that\u{0020}she\u{0020}was\u{0020}hurt\u{0020}by\u{0020}Sins\u{0020}in\u{0020}Logan:\u{0020}like\u{0020}most\u{0020}people,\u{0020}she\u{0020}lost\u{0020}her\u{0020}family\u{0020}in\u{0020}that\u{0020}tragedy.\n\nUnfortunately,\u{0020}there\u{0020}are\u{0020}tons\u{0020}of\u{0020}people\u{0020}in\u{0020}AEGIS\u{0020}who\u{0020}have\u{0020}a\u{0020}similar\u{0020}fate.\n\nThose\u{0020}who\u{0020}joined\u{0020}Aegis,\u{0020}especially\u{0020}drivers,\u{0020}can't\u{0020}\"mutually\u{0020}exist\"\u{0020}with\u{0020}Sins\u{0020}in\u{0020}this\u{0020}world\u{0020}because\u{0020}of\u{0020}furious\u{0020}hate.\n\nSo,\u{0020}what's\u{0020}so\u{0020}special\u{0020}about\u{0020}Starry?\u{0020}Is\u{0020}it\u{0020}her\u{0020}luck?\n\nBut\u{0020}if\u{0020}she\u{0020}only\u{0020}has\u{0020}good\u{0020}luck,\u{0020}that\u{0020}doesn't\u{0020}mean\u{0020}she\u{0020}\"shouldn't\u{0020}exist\".\n\nIf\u{0020}Stephaine\u{0020}didn't\u{0020}have\u{0020}rhetorics\u{0020}like\u{0020}hyperbole\u{0020}and\u{0020}metaphor\u{0020}that\u{0020}will\u{0020}cause\u{0020}misunderstanding,\u{0020}should\u{0020}that\u{0020}be\u{0020}explained\u{0020}as:\u{0020}\"In\u{0020}our\u{0020}original\u{0020}history,\u{0020}people\u{0020}like\u{0020}Starry\u{0020}shouldn't\u{0020}have\u{0020}appeared\"?\n\nPerhaps\u{0020}in\u{0020}the\u{0020}world\u{0020}of\u{0020}Stephanie's\u{0020}mind,\u{0020}Starry\u{0020}shouldn't\u{0020}appear\u{0020}in\u{0020}front\u{0020}of\u{0020}her,\u{0020}just\u{0020}like\u{0020}those\u{0020}people\u{0020}who\u{0020}vanished\u{0020}because\u{0020}of\u{0020}Sins.\u{0020}But,\u{0020}maybe\u{0020}the\u{0020}course\u{0020}of\u{0020}history\u{0020}changed:\u{0020}An\u{0020}accident\u{0020}called\u{0020}\"Starry\"\u{0020}happened.", "0", "0", "0", "0", 11033, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613303] = {613303, 1000, "\u{0020}\u{0020}Starry\u{0020}attended\u{0020}the\u{0020}Azure\u{0020}Academy.\u{0020}Her\u{0020}nickname\u{0020}\"Azure\u{0020}Fortunate\u{0020}Daughter\"\u{0020}was\u{0020}given\u{0020}by\u{0020}her\u{0020}schoolmates.\n\nBut\u{0020}she\u{0020}didn't\u{0020}finish\u{0020}her\u{0020}studies\u{0020}to\u{0020}become\u{0020}a\u{0020}driver,\u{0020}unlike\u{0020}other\u{0020}students.\u{0020}She\u{0020}left\u{0020}in\u{0020}the\u{0020}middle\u{0020}of\u{0020}her\u{0020}study.\n\nAfter\u{0020}she\u{0020}left\u{0020}the\u{0020}Azure\u{0020}Academy,\u{0020}she\u{0020}went\u{0020}to\u{0020}the\u{0020}1st\u{0020}research\u{0020}institute\u{0020}in\u{0020}Katya.\n\nIf\u{0020}that's\u{0020}because\u{0020}of\u{0020}luck,\u{0020}it's\u{0020}too\u{0020}incredible:\u{0020}that\u{0020}institute\u{0020}is\u{0020}directly\u{0020}affiliated\u{0020}to\u{0020}Kyushu,\u{0020}the\u{0020}center\u{0020}of\u{0020}AEGIS.\u{0020}If\u{0020}they\u{0020}neglected\u{0020}the\u{0020}requirement\u{0020}and\u{0020}hired\u{0020}a\u{0020}non-graduate\u{0020}student,\u{0020}there\u{0020}must\u{0020}be\u{0020}some\u{0020}reasons\u{0020}other\u{0020}than\u{0020}luck.\n\n\"Shouldn't\u{0020}exist.\"\n\nPerhaps\u{0020}because\u{0020}of\u{0020}this\u{0020}comment,\u{0020}she\u{0020}was\u{0020}chosen\u{0020}to\u{0020}join\u{0020}the\u{0020}1st\u{0020}research\u{0020}institute.\u{0020}But\u{0020}being\u{0020}a\u{0020}girl\u{0020}with\u{0020}good\u{0020}luck,\u{0020}what\u{0020}missions\u{0020}will\u{0020}she\u{0020}receive,\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}will\u{0020}she\u{0020}become?\n\nThere\u{0020}are\u{0020}no\u{0020}answers\u{0020}for\u{0020}that\u{0020}even\u{0020}today.\n\nWhat's\u{0020}her\u{0020}future?\u{0020}Also\u{0020}no\u{0020}one\u{0020}knows.\n\nUntil\u{0020}she\u{0020}went\u{0020}back\u{0020}to\u{0020}Logan,\u{0020}the\u{0020}place\u{0020}that\u{0020}may\u{0020}have\u{0020}changed\u{0020}her\u{0020}life,\u{0020}the\u{0020}\"start\"\u{0020}button\u{0020}of\u{0020}her\u{0020}\"paused\"\u{0020}story\u{0020}was\u{0020}pressed\u{0020}again.", "0", "0", "0", "0", 11033, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[613304] = {613304, 2000, "\u{0020}\u{0020}She\u{0020}walks\u{0020}on\u{0020}the\u{0020}wasteland.\n\nShrapnels,\u{0020}boulders\u{0020}fly\u{0020}past\u{0020}her\u{0020}body.\n\nBut\u{0020}none\u{0020}of\u{0020}them\u{0020}hit\u{0020}it.\n\nThe\u{0020}enormous\u{0020}steel\u{0020}monster\u{0020}finds\u{0020}that\u{0020}fragile\u{0020}ant\u{0020}under\u{0020}its\u{0020}feet,\n\nAnd\u{0020}disdainfully,\u{0020}it\u{0020}raises\u{0020}its\u{0020}foreleg,\u{0020}going\u{0020}to\u{0020}crush\u{0020}that\u{0020}ant.\n\nAt\u{0020}this\u{0020}moment,\u{0020}a\u{0020}shooting\u{0020}star,\u{0020}a\u{0020}meteorite,\u{0020}with\u{0020}a\u{0020}huge\u{0020}amount\u{0020}of\u{0020}heat\u{0020}and\u{0020}kinetic\u{0020}energy,\n\nThat\u{0020}hanging\u{0020}silver\u{0020}blade\u{0020}is\u{0020}its\u{0020}target.\n\nBecomes\u{0020}a\u{0020}corpse\u{0020}only\u{0020}in\u{0020}a\u{0020}blink,\u{0020}not\u{0020}the\u{0020}girl,\u{0020}but\u{0020}the\u{0020}monster.\n\n\"How\u{0020}lucky,\u{0020}I\u{0020}don't\u{0020}need\u{0020}to\u{0020}fight.\"\n\n\"Grrrgghh!!!\"\n\n\"Oh\u{0020}no,\u{0020}I\u{0020}still\u{0020}have\u{0020}to\u{0020}deal\u{0020}with\u{0020}them,\u{0020}hope\u{0020}I\u{0020}won't\u{0020}be\u{0020}late\u{0020}for\u{0020}the\u{0020}date\u{0020}with\u{0020}him…\"\n\n...\n\n\"STARRY!\u{0020}GIGANTIFY!\"", "0", "0", "0", "0", 11033, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
