[613401] = {613401, 100, "\u{0020}\u{0020}There\u{0020}was\u{0020}no\u{0020}shadow\u{0020}of\u{0020}a\u{0020}doubt\u{0020}about\u{0020}it.\u{0020}The\u{0020}one\u{0020}who\u{0020}had\u{0020}brought\u{0020}such\u{0020}life\u{0020}and\u{0020}vigor\u{0020}to\u{0020}the\u{0020}reformed\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}was\u{0020}none\u{0020}other\u{0020}than\u{0020}Rodnia\u{0020}herself.\n\nFew\u{0020}could\u{0020}match\u{0020}her\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch;\u{0020}even\u{0020}Skadi\u{0020}paled\u{0020}in\u{0020}comparison\u{0020}to\u{0020}Rodnia's\u{0020}boisterousness.\u{0020}Nobody\u{0020}could\u{0020}cause\u{0020}a\u{0020}scene\u{0020}quite\u{0020}like\u{0020}her.\n\nRodnia\u{0020}had\u{0020}always\u{0020}spoken\u{0020}her\u{0020}mind,\u{0020}and\u{0020}backed\u{0020}up\u{0020}her\u{0020}words\u{0020}without\u{0020}hesitation.\u{0020}It's\u{0020}what\u{0020}she\u{0020}became\u{0020}known\u{0020}for.\u{0020}Any\u{0020}time\u{0020}she\u{0020}started\u{0020}a\u{0020}sentence\u{0020}with\u{0020}\"You\u{0020}know,\u{0020}I'd\u{0020}like\u{0020}to...\",\u{0020}you\u{0020}just\u{0020}knew\u{0020}that\u{0020}she'd\u{0020}have\u{0020}made\u{0020}it\u{0020}reality\u{0020}within\u{0020}a\u{0020}day\u{0020}or\u{0020}two.\n\nShe'd\u{0020}caught\u{0020}wind\u{0020}of\u{0020}the\u{0020}Sin\u{0020}invasion\u{0020}in\u{0020}Saar\u{0020}in\u{0020}the\u{0020}days\u{0020}before\u{0020}her\u{0020}graduation,\u{0020}and\u{0020}sneaked\u{0020}off\u{0020}to\u{0020}join\u{0020}the\u{0020}battlefield.\u{0020}To\u{0020}her\u{0020}regret,\u{0020}though,\u{0020}the\u{0020}battle\u{0020}was\u{0020}over\u{0020}by\u{0020}the\u{0020}time\u{0020}she\u{0020}arrived.\u{0020}Such\u{0020}is\u{0020}but\u{0020}the\u{0020}tip\u{0020}of\u{0020}the\u{0020}Rodnia\u{0020}iceberg,\u{0020}however.\n\n\"Remember:\u{0020}she\u{0020}may\u{0020}sound\u{0020}like\u{0020}she's\u{0020}joking,\u{0020}but\u{0020}you'd\u{0020}best\u{0020}believe\u{0020}she's\u{0020}not.\"\n\nRodnia\u{0020}had\u{0020}always\u{0020}thought\u{0020}herself\u{0020}a\u{0020}born\u{0020}leader.\u{0020}She\u{0020}certainly\u{0020}exhibited\u{0020}the\u{0020}decision-making\u{0020}skills\u{0020}and\u{0020}capabilities\u{0020}of\u{0020}one.\u{0020}Her\u{0020}decisiveness\u{0020}and\u{0020}daring\u{0020}were\u{0020}what\u{0020}led\u{0020}her\u{0020}to\u{0020}such\u{0020}success\u{0020}having\u{0020}taken\u{0020}to\u{0020}the\u{0020}battlefield.\u{0020}Yet\u{0020}the\u{0020}\"born\u{0020}leader\"\u{0020}was\u{0020}want\u{0020}to\u{0020}take\u{0020}great\u{0020}risks,\u{0020}and\u{0020}act\u{0020}rashly,\u{0020}as\u{0020}was\u{0020}her\u{0020}personality.", "0", "0", "0", "0", 11034, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613402] = {613402, 500, "\u{0020}\u{0020}Rodnia\u{0020}is\u{0020}a\u{0020}war\u{0020}orphan.\u{0020}One\u{0020}of\u{0020}far\u{0020}too\u{0020}many\u{0020}in\u{0020}this\u{0020}era.\n\nUnlike\u{0020}the\u{0020}others,\u{0020}however,\u{0020}she\u{0020}was\u{0020}not\u{0020}taken\u{0020}in\u{0020}by\u{0020}a\u{0020}family\u{0020}that\u{0020}had\u{0020}lost\u{0020}their\u{0020}child,\u{0020}nor\u{0020}by\u{0020}an\u{0020}orphanage.\u{0020}Instead,\u{0020}she\u{0020}was\u{0020}adopted\u{0020}by\u{0020}a\u{0020}serving\u{0020}Driver.\u{0020}Perhaps\u{0020}due\u{0020}to\u{0020}their\u{0020}slim\u{0020}age\u{0020}difference,\u{0020}she\u{0020}and\u{0020}the\u{0020}Driver\u{0020}were\u{0020}more\u{0020}like\u{0020}sisters\u{0020}than\u{0020}parent\u{0020}and\u{0020}child.\u{0020}But\u{0020}if\u{0020}you\u{0020}were\u{0020}to\u{0020}ask\u{0020}Rodnia,\u{0020}she'd\u{0020}likely\u{0020}say\u{0020}her\u{0020}Driver\u{0020}was\u{0020}both\u{0020}a\u{0020}mother\u{0020}and\u{0020}a\u{0020}sister\u{0020}to\u{0020}her.\n\nA\u{0020}compassionate\u{0020}yet\u{0020}mighty\u{0020}figure,\u{0020}one\u{0020}who\u{0020}never\u{0020}backed\u{0020}down\u{0020}no\u{0020}matter\u{0020}the\u{0020}challenges\u{0020}battle\u{0020}posed.\u{0020}Someone\u{0020}who\u{0020}never\u{0020}hesitated\u{0020}in\u{0020}saving\u{0020}those\u{0020}in\u{0020}danger.\u{0020}Rodnia's\u{0020}dream\u{0020}was\u{0020}always\u{0020}to\u{0020}become\u{0020}an\u{0020}outstanding\u{0020}Driver\u{0020}just\u{0020}like\u{0020}her.\n\nWith\u{0020}her\u{0020}aid,\u{0020}Rodnia\u{0020}passed\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}Compatibility\u{0020}Rate\u{0020}tests\u{0020}to\u{0020}gain\u{0020}entry\u{0020}to\u{0020}the\u{0020}Driver\u{0020}academy,\u{0020}and\u{0020}prepared\u{0020}to\u{0020}study\u{0020}how\u{0020}to\u{0020}become\u{0020}a\u{0020}capable\u{0020}Driver\u{0020}herself.\n\nYet\u{0020}her\u{0020}adoptive\u{0020}sister,\u{0020}her\u{0020}mother,\u{0020}would\u{0020}never\u{0020}get\u{0020}to\u{0020}see\u{0020}Rodnia\u{0020}start\u{0020}her\u{0020}studies.\n\nShe\u{0020}perished\u{0020}upon\u{0020}the\u{0020}battlefield.\n\nHer\u{0020}funeral\u{0020}was\u{0020}held\u{0020}with\u{0020}the\u{0020}other\u{0020}Drivers\u{0020}that\u{0020}had\u{0020}died\u{0020}in\u{0020}the\u{0020}line\u{0020}of\u{0020}duty.\u{0020}There,\u{0020}Rodnia\u{0020}played\u{0020}a\u{0020}tune\u{0020}on\u{0020}her\u{0020}bagpipes,\u{0020}one\u{0020}she'd\u{0020}always\u{0020}loved\u{0020}while\u{0020}still\u{0020}alive.\n\nIt\u{0020}was\u{0020}then\u{0020}that\u{0020}she\u{0020}decided\u{0020}once\u{0020}and\u{0020}for\u{0020}all.\n\n\"I'll\u{0020}become\u{0020}just\u{0020}as\u{0020}compassionate,\u{0020}just\u{0020}as\u{0020}powerful,\u{0020}as\u{0020}she\u{0020}was!\u{0020}One\u{0020}kind\u{0020}enough\u{0020}to\u{0020}warm\u{0020}the\u{0020}broken\u{0020}hearts\u{0020}of\u{0020}all\u{0020}those\u{0020}in\u{0020}need,\u{0020}strong\u{0020}enough\u{0020}to\u{0020}protect\u{0020}them\u{0020}from\u{0020}harm!\"\n\nAnd\u{0020}she\u{0020}always\u{0020}stood\u{0020}on\u{0020}her\u{0020}word.\u{0020}Such\u{0020}determination\u{0020}was\u{0020}essential\u{0020}for\u{0020}a\u{0020}leader,\u{0020}for\u{0020}the\u{0020}truly\u{0020}strong...\u{0020}A\u{0020}fine\u{0020}aspiration,\u{0020}but\u{0020}one\u{0020}that\u{0020}went\u{0020}awry.\u{0020}In\u{0020}the\u{0020}academy\u{0020}she\u{0020}strove\u{0020}to\u{0020}be\u{0020}the\u{0020}best,\u{0020}but\u{0020}was\u{0020}considered\u{0020}bottom\u{0020}of\u{0020}the\u{0020}class\u{0020}by\u{0020}her\u{0020}tutors\u{0020}and\u{0020}a\u{0020}troublesome\u{0020}ne'er-do-well\u{0020}by\u{0020}her\u{0020}classmates.\n\nThat\u{0020}said,\u{0020}she\u{0020}developed\u{0020}a\u{0020}quality\u{0020}essential\u{0020}to\u{0020}being\u{0020}a\u{0020}Driver:\u{0020}she\u{0020}knew\u{0020}why\u{0020}she\u{0020}fought,\u{0020}and\u{0020}more,\u{0020}she\u{0020}was\u{0020}willing\u{0020}to\u{0020}sacrifice\u{0020}herself\u{0020}for\u{0020}it.", "0", "0", "0", "0", 11034, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613403] = {613403, 1000, "\u{0020}\u{0020}It\u{0020}was\u{0020}only\u{0020}when\u{0020}Rodnia\u{0020}was\u{0020}dispatched\u{0020}to\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}that\u{0020}she\u{0020}found\u{0020}out\u{0020}she\u{0020}was\u{0020}born\u{0020}in\u{0020}Saar.\n\nAfter\u{0020}spending\u{0020}some\u{0020}time\u{0020}with\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}regrouped\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}Dolores,\u{0020}Rodnia's\u{0020}impression\u{0020}of\u{0020}her\u{0020}changed:\u{0020}she'd\u{0020}considered\u{0020}Dolores\u{0020}little\u{0020}more\u{0020}than\u{0020}a\u{0020}\"weak\u{0020}little\u{0020}girl\",\u{0020}but\u{0020}now\u{0020}saw\u{0020}her\u{0020}a\u{0020}\"reliable,\u{0020}kindhearted\u{0020}and\u{0020}strong\"\u{0020}figure.\u{0020}Rodnia,\u{0020}once\u{0020}a\u{0020}troublemaker\u{0020}of\u{0020}a\u{0020}student,\u{0020}saw\u{0020}a\u{0020}little\u{0020}of\u{0020}her\u{0020}elder\u{0020}sister\u{0020}in\u{0020}Dolores.\n\n\"Captain\u{0020}Dolores\u{0020}is\u{0020}a\u{0020}kind\u{0020}woman,\u{0020}and\u{0020}caring,\u{0020}too.\u{0020}That's\u{0020}why\u{0020}I've\u{0020}much\u{0020}to\u{0020}learn\u{0020}from\u{0020}her!\u{0020}I'll\u{0020}grow\u{0020}to\u{0020}become\u{0020}as\u{0020}gentle\u{0020}and\u{0020}generous\u{0020}as\u{0020}my\u{0020}captain.\u{0020}Just\u{0020}like\u{0020}my\u{0020}sister!\"", "0", "0", "0", "0", 11034, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[613404] = {613404, 2000, "\u{0020}\u{0020}The\u{0020}autumn\u{0020}breeze\u{0020}swept\u{0020}between\u{0020}the\u{0020}city\u{0020}buildings,\u{0020}carrying\u{0020}with\u{0020}it\u{0020}the\u{0020}rank\u{0020}odor\u{0020}of\u{0020}death.\n\nThe\u{0020}plaintive\u{0020}song\u{0020}of\u{0020}bagpipes\u{0020}sounded\u{0020}from\u{0020}the\u{0020}skies,\u{0020}almost\u{0020}seeming\u{0020}to\u{0020}resonate\u{0020}with\u{0020}the\u{0020}buildings\u{0020}below.\n\nThe\u{0020}heavy\u{0020}atmosphere\u{0020}and\u{0020}rustling\u{0020}winds\u{0020}fell\u{0020}still,\u{0020}vanishing\u{0020}as\u{0020}the\u{0020}song\u{0020}rang\u{0020}out.\n\nRodnia\u{0020}stood\u{0020}tall\u{0020}in\u{0020}the\u{0020}city's\u{0020}center,\u{0020}a\u{0020}time-weary\u{0020}sorrow\u{0020}upon\u{0020}her\u{0020}face\u{0020}as\u{0020}she\u{0020}played\u{0020}the\u{0020}bagpipes.\n\nShe\u{0020}laid\u{0020}down\u{0020}the\u{0020}heavy\u{0020}instrument,\u{0020}the\u{0020}lamentful\u{0020}music\u{0020}drawing\u{0020}to\u{0020}a\u{0020}close.\n\nThe\u{0020}rumbling\u{0020}crash\u{0020}that\u{0020}sounded\u{0020}as\u{0020}it\u{0020}hit\u{0020}the\u{0020}floor\u{0020}marked\u{0020}the\u{0020}end\u{0020}of\u{0020}her\u{0020}song.\n\nThen\u{0020}that\u{0020}familiar\u{0020}smile\u{0020}of\u{0020}hers\u{0020}returned\u{0020}once\u{0020}more,\u{0020}and\u{0020}she\u{0020}neared\u{0020}the\u{0020}Navigator\u{0020}stood\u{0020}upon\u{0020}a\u{0020}nearby\u{0020}rooftop.\n\n\"That's\u{0020}the\u{0020}end\u{0020}of\u{0020}my\u{0020}performance.\u{0020}So\u{0020}you\u{0020}can\u{0020}wipe\u{0020}that\u{0020}sorry\u{0020}expression\u{0020}off\u{0020}your\u{0020}face\u{0020}now,\u{0020}Navigator!\"\n\nThe\u{0020}mourning\u{0020}was\u{0020}now\u{0020}over.\u{0020}Eventually,\u{0020}we\u{0020}must\u{0020}all\u{0020}cast\u{0020}our\u{0020}minds\u{0020}back\u{0020}to\u{0020}the\u{0020}world\u{0020}of\u{0020}the\u{0020}living.\n\n\"Let's\u{0020}head\u{0020}back!\u{0020}I\u{0020}know\u{0020}I'm\u{0020}starving,\u{0020}alright!\"", "0", "0", "0", "0", 11034, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
