[613501] = {613501, 100, "\u{0020}\"Human\u{0020}experimental\u{0020}weapon\",\u{0020}\"Solomon's\u{0020}demon\",\u{0020}\"The\u{0020}monarch\u{0020}from\u{0020}hell\".\n\nThese\u{0020}exaggerated\u{0020}words,\u{0020}are\u{0020}exactly\u{0020}the\u{0020}aliases\u{0020}of\u{0020}the\u{0020}girl\u{0020}who\u{0020}has\u{0020}the\u{0020}same\u{0020}name\u{0020}as\u{0020}the\u{0020}Solomon's\u{0020}demon\u{0020}\"Zepar\"\u{0020}in\u{0020}the\u{0020}Danube\u{0020}Branch.\n\nNo\u{0020}one\u{0020}believes\u{0020}that\u{0020}this\u{0020}girl\u{0020}who\u{0020}always\u{0020}acts\u{0020}cute\u{0020}in\u{0020}front\u{0020}of\u{0020}others\u{0020}has\u{0020}such\u{0020}titles.\n\n\"People\u{0020}who\u{0020}have\u{0020}this\u{0020}kind\u{0020}of\u{0020}thought\u{0020}like\u{0020}'Is\u{0020}this\u{0020}just\u{0020}bluffing?'\u{0020}are\u{0020}everywhere.\"\n\nAmong\u{0020}the\u{0020}new-generation\u{0020}drivers\u{0020}who\u{0020}have\u{0020}emerged\u{0020}within\u{0020}the\u{0020}past\u{0020}four\u{0020}years,\u{0020}just\u{0020}by\u{0020}hearing\u{0020}these\u{0020}nicknames,\u{0020}one\u{0020}would\u{0020}never\u{0020}expect\u{0020}that\u{0020}the\u{0020}root\u{0020}cause\u{0020}of\u{0020}their\u{0020}creation\u{0020}was\u{0020}Zepar's\u{0020}repeated\u{0020}heroic\u{0020}performances\u{0020}on\u{0020}the\u{0020}battlefield.\n\nAfter\u{0020}all,\u{0020}that\u{0020}was\u{0020}ten\u{0020}or\u{0020}even\u{0020}twenty\u{0020}years\u{0020}ago.\u{0020}How\u{0020}many\u{0020}of\u{0020}those\u{0020}drivers\u{0020}who\u{0020}witnessed\u{0020}the\u{0020}battle\u{0020}between\u{0020}Zepar\u{0020}and\u{0020}Sin\u{0020}are\u{0020}still\u{0020}alive\u{0020}today?\u{0020}Or\u{0020}rather,\u{0020}is\u{0020}there\u{0020}really\u{0020}any\u{0020}driver\u{0020}who\u{0020}can\u{0020}leave\u{0020}the\u{0020}battlefield\u{0020}in\u{0020}an\u{0020}\"intact\"\u{0020}state?\n\nSorry,\u{0020}the\u{0020}content\u{0020}has\u{0020}strayed\u{0020}a\u{0020}bit.\u{0020}Let's\u{0020}bring\u{0020}our\u{0020}focus\u{0020}back\u{0020}to\u{0020}Zepar.\n\nPresumably\u{0020}seeing\u{0020}this,\u{0020}you\u{0020}who\u{0020}are\u{0020}reading\u{0020}the\u{0020}file\u{0020}now\u{0020}can\u{0020}understand,\u{0020}right?\n\nYes,\u{0020}this\u{0020}girl\u{0020}who\u{0020}looks\u{0020}as\u{0020}if\u{0020}she\u{0020}just\u{0020}graduated\u{0020}from\u{0020}Azure\u{0020}Academy\u{0020}to\u{0020}become\u{0020}a\u{0020}driver,\n\nIn\u{0020}fact,\u{0020}they\u{0020}were\u{0020}the\u{0020}first\u{0020}batch\u{0020}of\u{0020}drivers\u{0020}after\u{0020}the\u{0020}emergence\u{0020}of\u{0020}the\u{0020}gigantification\u{0020}technology.", "0", "0", "0", "0", 11035, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613502] = {613502, 500, "\u{0020}\u{0020}\"Humanity\u{0020}was\u{0020}completely\u{0020}defeated.\"\n\nJust\u{0020}like\u{0020}the\u{0020}nickname\u{0020}used\u{0020}for\u{0020}Zepar,\u{0020}this\u{0020}sentence\u{0020}appeared\u{0020}in\u{0020}the\u{0020}battle\u{0020}record\u{0020}of\u{0020}humanity\u{0020}against\u{0020}Sin,\u{0020}and\u{0020}it\u{0020}is\u{0020}not\u{0020}exaggerated\u{0020}at\u{0020}all.\u{0020}And\u{0020}the\u{0020}time\u{0020}when\u{0020}most\u{0020}of\u{0020}the\u{0020}defeats\u{0020}occurred\u{0020}was\u{0020}before\u{0020}a\u{0020}certain\u{0020}time\u{0020}point\u{0020}-\u{0020}that\u{0020}is,\u{0020}before\u{0020}the\u{0020}\"giant\u{0020}girl\u{0020}was\u{0020}officially\u{0020}put\u{0020}into\u{0020}actual\u{0020}combat\".\n\nThe\u{0020}horn\u{0020}of\u{0020}humanity's\u{0020}counterattack\u{0020}was\u{0020}sounded\u{0020}after\u{0020}the\u{0020}drivers\u{0020}officially\u{0020}entered\u{0020}the\u{0020}battlefield.\n\nThe\u{0020}drivers\u{0020}carry\u{0020}the\u{0020}hope\u{0020}of\u{0020}humanity\u{0020}and\u{0020}are\u{0020}the\u{0020}crystallization\u{0020}of\u{0020}human\u{0020}courage\u{0020}and\u{0020}wisdom.\u{0020}The\u{0020}initial\u{0020}drivers'\u{0020}performance\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}did\u{0020}not\u{0020}disappoint\u{0020}humanity\u{0020}either.\u{0020}They\u{0020}rushed\u{0020}to\u{0020}all\u{0020}parts\u{0020}of\u{0020}the\u{0020}world\u{0020}day\u{0020}and\u{0020}night\u{0020}to\u{0020}repel\u{0020}Sin\u{0020}that\u{0020}trampled\u{0020}on\u{0020}human\u{0020}homeland.\u{0020}They\u{0020}won\u{0020}glory\u{0020}with\u{0020}their\u{0020}performance,\u{0020}although\u{0020}behind\u{0020}the\u{0020}glory\u{0020}were\u{0020}scarred\u{0020}bodies\u{0020}and\u{0020}exhausted\u{0020}souls.\n\nAnd\u{0020}Zepar\u{0020}was\u{0020}precisely\u{0020}the\u{0020}driver\u{0020}who\u{0020}stood\u{0020}out\u{0020}from\u{0020}this\u{0020}group,\u{0020}the\u{0020}one\u{0020}who\u{0020}almost\u{0020}became\u{0020}a\u{0020}\"human\u{0020}hero\".\n\nDuring\u{0020}her\u{0020}active\u{0020}five\u{0020}years,\u{0020}Zepar\u{0020}carried\u{0020}out\u{0020}a\u{0020}total\u{0020}of\u{0020}427\u{0020}offensive\u{0020}missions,\u{0020}214\u{0020}defensive\u{0020}missions,\u{0020}and\u{0020}73\u{0020}rescue\u{0020}operations.\u{0020}In\u{0020}other\u{0020}words,\u{0020}even\u{0020}without\u{0020}counting\u{0020}those\u{0020}missions\u{0020}not\u{0020}recorded\u{0020}in\u{0020}the\u{0020}files,\u{0020}Zepar\u{0020}almost\u{0020}completed\u{0020}a\u{0020}formal\u{0020}mission\u{0020}every\u{0020}three\u{0020}days.\n\nConsidering\u{0020}the\u{0020}shortage\u{0020}of\u{0020}drivers\u{0020}at\u{0020}that\u{0020}time,\u{0020}I'm\u{0020}afraid\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}time\u{0020}permitted,\u{0020}then\u{0020}if\u{0020}Sin\u{0020}appeared\u{0020}on\u{0020}human\u{0020}territory,\u{0020}AEGIS\u{0020}would\u{0020}definitely\u{0020}order\u{0020}Zepar\u{0020}to\u{0020}the\u{0020}battlefield.\u{0020}So\u{0020}within\u{0020}five\u{0020}years,\u{0020}remarkable\u{0020}military\u{0020}achievements\u{0020}were\u{0020}made.\n\nSo\u{0020}it\u{0020}became\u{0020}a\u{0020}legend\u{0020}within\u{0020}five\u{0020}years.\n\nSo\u{0020}-\u{0020}her\u{0020}service\u{0020}time\u{0020}was\u{0020}only\u{0020}five\u{0020}years.\n\nAfter\u{0020}spending\u{0020}the\u{0020}most\u{0020}glorious\u{0020}five\u{0020}years\u{0020}as\u{0020}a\u{0020}human,\u{0020}Zepar\u{0020}received\u{0020}many\u{0020}honors\u{0020}and\u{0020}even\u{0020}got\u{0020}such\u{0020}a\u{0020}good\u{0020}name\u{0020}as\u{0020}\"the\u{0020}demon\u{0020}god\u{0020}of\u{0020}Solomon\".\u{0020}Then,\u{0020}before\u{0020}AEGIS\u{0020}was\u{0020}ready\u{0020}to\u{0020}confer\u{0020}her\u{0020}the\u{0020}title\u{0020}of\u{0020}\"the\u{0020}hero\u{0020}of\u{0020}humanity\",\n\nShe\u{0020}disappeared\u{0020}from\u{0020}the\u{0020}public's\u{0020}view.\n\nThe\u{0020}sudden\u{0020}disappearance\u{0020}of\u{0020}Zepar\u{0020}caused\u{0020}an\u{0020}uproar\u{0020}in\u{0020}the\u{0020}society\u{0020}at\u{0020}that\u{0020}time,\u{0020}and\u{0020}the\u{0020}reason\u{0020}for\u{0020}her\u{0020}disappearance\u{0020}was\u{0020}also\u{0020}a\u{0020}controversy.\u{0020}Some\u{0020}people\u{0020}believed\u{0020}that\u{0020}she\u{0020}died\u{0020}in\u{0020}a\u{0020}battle,\u{0020}while\u{0020}others\u{0020}believed\u{0020}that\u{0020}she\u{0020}was\u{0020}overwhelmed\u{0020}and\u{0020}chose\u{0020}to\u{0020}retire,\u{0020}but\u{0020}in\u{0020}any\u{0020}case,\u{0020}AEGIS\u{0020}never\u{0020}submitted\u{0020}her\u{0020}explanation\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}public.\n\nAnd\u{0020}Zepar\u{0020}didn't\u{0020}go\u{0020}anywhere.\n\nFor\u{0020}the\u{0020}past\u{0020}twenty\u{0020}years,\u{0020}Zepar\u{0020}has\u{0020}been\u{0020}on\u{0020}the\u{0020}Ark\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}headquarters,\u{0020}in\u{0020}artificial\u{0020}hibernation,\u{0020}undergoing\u{0020}a\u{0020}long\u{0020}and\u{0020}endless\u{0020}slumber.\n\n—Until\u{0020}Dr.\u{0020}Stephanie\u{0020}woke\u{0020}her\u{0020}up.", "0", "0", "0", "0", 11035, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613503] = {613503, 1000, "\u{0020}\u{0020}The\u{0020}human\u{0020}transformation\u{0020}technology\u{0020}of\u{0020}AEGIS\u{0020}has\u{0020}been\u{0020}continuously\u{0020}maturing\u{0020}over\u{0020}time.\n\nFrom\u{0020}another\u{0020}perspective,\u{0020}this\u{0020}statement\u{0020}is\u{0020}a\u{0020}disguised\u{0020}admission\u{0020}that\u{0020}the\u{0020}first-generation\u{0020}human\u{0020}transformation\u{0020}technology\u{0020}had\u{0020}flaws.\u{0020}And\u{0020}the\u{0020}initial\u{0020}navigators\u{0020}were\u{0020}precisely\u{0020}the\u{0020}\"victims\"\u{0020}of\u{0020}the\u{0020}gigantification\u{0020}technology.\n\nIn\u{0020}order\u{0020}to\u{0020}complete\u{0020}the\u{0020}still\u{0020}immature\u{0020}human\u{0020}transformation\u{0020}technology,\u{0020}the\u{0020}scientific\u{0020}officers\u{0020}of\u{0020}AEGIS\u{0020}performed\u{0020}human\u{0020}adaptation\u{0020}surgeries\u{0020}on\u{0020}the\u{0020}first\u{0020}batch\u{0020}of\u{0020}navigators\u{0020}(which\u{0020}was\u{0020}merely\u{0020}a\u{0020}more\u{0020}pleasant-sounding\u{0020}\"human\u{0020}modification\u{0020}surgery\"),\u{0020}with\u{0020}the\u{0020}aim\u{0020}of\u{0020}enabling\u{0020}them\u{0020}to\u{0020}successfully\u{0020}achieve\u{0020}\"gigantification\".\n\nZepar\u{0020}did\u{0020}not\u{0020}die\u{0020}at\u{0020}the\u{0020}hands\u{0020}of\u{0020}Sin,\u{0020}but\u{0020}almost\u{0020}died\u{0020}due\u{0020}to\u{0020}the\u{0020}\"excessive\u{0020}use\"\u{0020}of\u{0020}AEGIS.\u{0020}During\u{0020}her\u{0020}five\u{0020}years\u{0020}of\u{0020}service,\u{0020}she\u{0020}almost\u{0020}had\u{0020}no\u{0020}concept\u{0020}of\u{0020}\"rest\".\u{0020}She\u{0020}was\u{0020}either\u{0020}on\u{0020}the\u{0020}way\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}or\u{0020}fighting\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}When\u{0020}she\u{0020}left\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}deactivated\u{0020}the\u{0020}gigantification\u{0020}at\u{0020}that\u{0020}moment\u{0020}-\u{0020}her\u{0020}body\u{0020}presented\u{0020}multiple\u{0020}organ\u{0020}failure\u{0020}phenomena,\u{0020}and\u{0020}in\u{0020}the\u{0020}subsequent\u{0020}shock,\u{0020}lots\u{0020}of\u{0020}brain\u{0020}cells\u{0020}died.\n\nAEGIS\u{0020}concealed\u{0020}Zepar's\u{0020}condition\u{0020}from\u{0020}the\u{0020}outside\u{0020}world\u{0020}and\u{0020}wrote\u{0020}\"missing\"\u{0020}into\u{0020}the\u{0020}file\u{0020}of\u{0020}this\u{0020}navigator\u{0020}who\u{0020}was\u{0020}about\u{0020}to\u{0020}become\u{0020}a\u{0020}human\u{0020}hero.\u{0020}The\u{0020}scientific\u{0020}officers\u{0020}led\u{0020}by\u{0020}Dr.\u{0020}Stephanie\u{0020}froze\u{0020}Zepar's\u{0020}body,\u{0020}hoping\u{0020}to\u{0020}bring\u{0020}this\u{0020}hero\u{0020}\"back\u{0020}to\u{0020}life\"\u{0020}one\u{0020}day\u{0020}in\u{0020}the\u{0020}future.\n\nFour\u{0020}years\u{0020}ago,\u{0020}this\u{0020}one-time\u{0020}hero\u{0020}was\u{0020}successfully\u{0020}revived\u{0020}under\u{0020}the\u{0020}treatment\u{0020}of\u{0020}Dr.\u{0020}Stephanie\n\nNowadays,\u{0020}after\u{0020}undergoing\u{0020}rehabilitation\u{0020}for\u{0020}as\u{0020}long\u{0020}as\u{0020}four\u{0020}years\u{0020}and\u{0020}at\u{0020}the\u{0020}request\u{0020}of\u{0020}Captain\u{0020}Lepani\u{0020}of\u{0020}the\u{0020}Iron\u{0020}Crow,\u{0020}she\u{0020}once\u{0020}again\u{0020}throws\u{0020}herself\u{0020}into\u{0020}this\u{0020}battlefield\u{0020}that\u{0020}once\u{0020}sent\u{0020}her\u{0020}to\u{0020}death.\n\nUnlike\u{0020}the\u{0020}past,\u{0020}she\u{0020}who\u{0020}has\u{0020}experienced\u{0020}death\u{0020}once\u{0020}has\u{0020}undergone\u{0020}some\u{0020}-\u{0020}or\u{0020}rather,\u{0020}\"drastic\"\u{0020}-\u{0020}changes\u{0020}in\u{0020}her\u{0020}temperament.\n\n\"Well,\u{0020}I've\u{0020}already\u{0020}died\u{0020}once.\u{0020}Isn't\u{0020}it\u{0020}okay\u{0020}for\u{0020}me\u{0020}to\u{0020}be\u{0020}a\u{0020}little\u{0020}lazy\u{0020}now?\"\n\n\"Besides,\u{0020}you\u{0020}surely\u{0020}don't\u{0020}want\u{0020}such\u{0020}a\u{0020}lovely\u{0020}girl\u{0020}like\u{0020}me\u{0020}to\u{0020}get\u{0020}hurt\u{0020}again,\u{0020}do\u{0020}you?\"\n\n...In\u{0020}this\u{0020}way,\u{0020}that\u{0020}strange\u{0020}value\u{0020}also\u{0020}got\u{0020}a\u{0020}reasonable\u{0020}explanation.", "0", "0", "0", "0", 11035, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[613504] = {613504, 2000, "\u{0020}\u{0020}\"The\u{0020}monarch\u{0020}from\u{0020}hell\",\u{0020}may\u{0020}not\u{0020}be\u{0020}appropriate,\n\nbut\u{0020}the\u{0020}whole\u{0020}\"coming\u{0020}back\u{0020}from\u{0020}hell\"\u{0020}thing\u{0020}is\u{0020}not\u{0020}fictional.\n\nThe\u{0020}pain\u{0020}of\u{0020}organ\u{0020}failure\u{0020}and\u{0020}the\u{0020}sense\u{0020}of\u{0020}despair\u{0020}of\u{0020}realizing\u{0020}one's\u{0020}impending\u{0020}death\u{0020}before\u{0020}shock.\n\nEven\u{0020}to\u{0020}this\u{0020}day,\u{0020}she\u{0020}still\u{0020}remembers.\n\nShe\u{0020}still\u{0020}loves\u{0020}people\u{0020}and\u{0020}is\u{0020}willing\u{0020}to\u{0020}fight\u{0020}for\u{0020}them.\n\nJust,\u{0020}a\u{0020}little\u{0020}bit\u{0020}scared.\n\nAfraid\u{0020}of\u{0020}returning\u{0020}once\u{0020}again\u{0020}to\u{0020}that\u{0020}darkness\u{0020}where\u{0020}one\u{0020}can\u{0020}neither\u{0020}hear\u{0020}nor\u{0020}see,\u{0020}nor\u{0020}even\u{0020}make\u{0020}a\u{0020}sound.\n\n\"Navigator,\u{0020}I'm\u{0020}not\u{0020}some\u{0020}evil\u{0020}spirit,\u{0020}just\u{0020}a\u{0020}coward\u{0020}who's\u{0020}afraid\u{0020}of\u{0020}death.\"\n\nShe\u{0020}was\u{0020}acting\u{0020}coquettishly\u{0020}before\u{0020}the\u{0020}navigator,\u{0020}although\u{0020}the\u{0020}way\u{0020}her\u{0020}huge\u{0020}body\u{0020}was\u{0020}twisting\u{0020}made\u{0020}people\u{0020}worry\u{0020}that\u{0020}she\u{0020}could\u{0020}step\u{0020}on\u{0020}the\u{0020}navigator\n\n\"So,\u{0020}you\u{0020}must\u{0020}keep\u{0020}a\u{0020}good\u{0020}eye\u{0020}on\u{0020}me\u{0020}from\u{0020}behind!\"", "0", "0", "0", "0", 11035, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
