[613601] = {613601, 100, "\u{0020}Precio\u{0020}is\u{0020}a\u{0020}scholar\u{0020}specializing\u{0020}in\u{0020}\"Sin\u{0020}Behavioral\u{0020}Science\",\u{0020}and\u{0020}she\u{0020}teaches\u{0020}at\u{0020}Sahara\u{0020}Azure\u{0020}Academy.\u{0020}However,\u{0020}compared\u{0020}to\u{0020}the\u{0020}trivial\u{0020}educational\u{0020}affairs,\u{0020}she\u{0020}devotes\u{0020}more\u{0020}energy\u{0020}to\u{0020}the\u{0020}most\u{0020}cutting-edge\u{0020}research.\n\nPerhaps\u{0020}due\u{0020}to\u{0020}professional\u{0020}habits,\u{0020}Precio\u{0020}pays\u{0020}considerable\u{0020}attention\u{0020}to\u{0020}practicality.\u{0020}This\u{0020}is\u{0020}usually\u{0020}manifested\u{0020}in\u{0020}that\u{0020}she\u{0020}likes\u{0020}to\u{0020}incorporate\u{0020}some\u{0020}data\u{0020}into\u{0020}her\u{0020}words\u{0020}when\u{0020}communicating.\u{0020}Outside\u{0020}of\u{0020}serious\u{0020}matters,\u{0020}she\u{0020}shows\u{0020}a\u{0020}rather\u{0020}indifferent\u{0020}attitude\u{0020}towards\u{0020}many\u{0020}things.\u{0020}For\u{0020}example,\u{0020}she\u{0020}doesn't\u{0020}pay\u{0020}much\u{0020}attention\u{0020}to\u{0020}the\u{0020}sense\u{0020}of\u{0020}distance\u{0020}with\u{0020}people\u{0020}and\u{0020}seems\u{0020}to\u{0020}lack\u{0020}etiquette.\u{0020}However,\u{0020}because\u{0020}of\u{0020}her\u{0020}straightforward\u{0020}personality,\u{0020}she\u{0020}doesn't\u{0020}make\u{0020}people\u{0020}dislike\u{0020}her.\u{0020}In\u{0020}fact,\u{0020}she\u{0020}is\u{0020}just\u{0020}too\u{0020}lazy\u{0020}to\u{0020}waste\u{0020}her\u{0020}meticulous\u{0020}thoughts\u{0020}on\u{0020}unprofitable\u{0020}interpersonal\u{0020}communication.\n\nUnless,\u{0020}of\u{0020}course,\u{0020}you\u{0020}can\u{0020}generate\u{0020}enough\u{0020}attraction\u{0020}for\u{0020}her,\u{0020}as\u{0020}a\u{0020}good\u{0020}research\u{0020}sample\u{0020}would.", "0", "0", "0", "0", 11036, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613602] = {613602, 500, "\u{0020}\u{0020}The\u{0020}world\u{0020}always\u{0020}fulfills\u{0020}the\u{0020}wishes\u{0020}of\u{0020}some\u{0020}people\u{0020}while\u{0020}going\u{0020}against\u{0020}the\u{0020}wishes\u{0020}of\u{0020}others.\u{0020}No\u{0020}matter\u{0020}how\u{0020}heterogeneous\u{0020}the\u{0020}reality\u{0020}is,\u{0020}it\u{0020}will\u{0020}never\u{0020}disappoint\u{0020}everyone.\u{0020}In\u{0020}this\u{0020}world,\u{0020}some\u{0020}people\u{0020}loathe\u{0020}Sin,\u{0020}some\u{0020}people\u{0020}hate\u{0020}Sin,\u{0020}then,\u{0020}equally,\u{0020}there\u{0020}will\u{0020}be\u{0020}someone\u{0020}who\u{0020}\"likes\"\u{0020}Sin.\n\nPrecio,\u{0020}known\u{0020}as\u{0020}the\u{0020}\"Sin\u{0020}Scholar\",\u{0020}is\u{0020}such\u{0020}an\u{0020}unconventional\u{0020}presence.\u{0020}Since\u{0020}childhood,\u{0020}she\u{0020}has\u{0020}been\u{0020}interested\u{0020}in\u{0020}\"unsolved\u{0020}mysteries\"\u{0020}and\u{0020}\"mysterious\u{0020}things\".\u{0020}After\u{0020}gradually\u{0020}realizing\u{0020}that\u{0020}most\u{0020}of\u{0020}the\u{0020}above-mentioned\u{0020}things\u{0020}were\u{0020}fabricated,\u{0020}she\u{0020}finally\u{0020}turned\u{0020}her\u{0020}attention\u{0020}to\u{0020}Sin\u{0020}-\u{0020}such\u{0020}an\u{0020}extremely\u{0020}real\u{0020}and\u{0020}enigmatic\u{0020}silicon-based\u{0020}life\u{0020}form.\n\nThe\u{0020}appearance\u{0020}of\u{0020}Sin\u{0020}in\u{0020}human\u{0020}history\u{0020}was\u{0020}completely\u{0020}unexpected.\u{0020}Their\u{0020}existence\u{0020}does\u{0020}not\u{0020}conform\u{0020}to\u{0020}any\u{0020}mainstream\u{0020}evolutionary\u{0020}theory.\u{0020}There\u{0020}is\u{0020}no\u{0020}evidence\u{0020}of\u{0020}their\u{0020}activities\u{0020}on\u{0020}Earth,\u{0020}not\u{0020}even\u{0020}a\u{0020}trace\u{0020}can\u{0020}be\u{0020}found\u{0020}in\u{0020}myths\u{0020}and\u{0020}legends\u{0020}of\u{0020}various\u{0020}regions.\u{0020}Although\u{0020}Precio\u{0020}is\u{0020}young\u{0020}and\u{0020}not\u{0020}among\u{0020}the\u{0020}first\u{0020}witnesses\u{0020}of\u{0020}the\u{0020}Sin,\u{0020}she\u{0020}undoubtedly\u{0020}grew\u{0020}up\u{0020}in\u{0020}an\u{0020}environment\u{0020}where\u{0020}the\u{0020}existence\u{0020}of\u{0020}Sin\u{0020}was\u{0020}already\u{0020}public,\u{0020}but\u{0020}she\u{0020}did\u{0020}not\u{0020}take\u{0020}it\u{0020}for\u{0020}granted.\u{0020}Like\u{0020}a\u{0020}child\u{0020}passionate\u{0020}about\u{0020}dissecting\u{0020}insects,\u{0020}she\u{0020}is\u{0020}passionate\u{0020}about\u{0020}revealing\u{0020}the\u{0020}mystery\u{0020}of\u{0020}Sin.\n\nPrecio\u{0020}was\u{0020}admitted\u{0020}to\u{0020}Azure\u{0020}Academy\u{0020}as\u{0020}a\u{0020}young\u{0020}freshman.\u{0020}She\u{0020}knew\u{0020}that\u{0020}if\u{0020}she\u{0020}wanted\u{0020}to\u{0020}study\u{0020}Sin\u{0020}in\u{0020}the\u{0020}cutting-edge\u{0020}field,\u{0020}she\u{0020}had\u{0020}to\u{0020}fight\u{0020}on\u{0020}the\u{0020}front\u{0020}lines\u{0020}as\u{0020}a\u{0020}driver.She\u{0020}kept\u{0020}climbing\u{0020}with\u{0020}excellent\u{0020}performance\u{0020}and\u{0020}contributed\u{0020}many\u{0020}theoretical\u{0020}hypotheses\u{0020}about\u{0020}the\u{0020}behavioral\u{0020}science\u{0020}and\u{0020}morphological\u{0020}origin\u{0020}of\u{0020}Sin\u{0020}to\u{0020}the\u{0020}academy.\u{0020}However,\u{0020}when\u{0020}she\u{0020}truly\u{0020}started\u{0020}her\u{0020}bold\u{0020}and\u{0020}avant-garde\u{0020}project,\u{0020}many\u{0020}conservatives\u{0020}refused\u{0020}to\u{0020}offer\u{0020}help.\u{0020}Therefore,\u{0020}Precio\u{0020}became\u{0020}more\u{0020}determined\u{0020}to\u{0020}do\u{0020}it\u{0020}herself.\n\nShe\u{0020}managed\u{0020}to\u{0020}capture\u{0020}some\u{0020}living\u{0020}specimens\u{0020}and\u{0020}identified\u{0020}the\u{0020}characteristics\u{0020}of\u{0020}some\u{0020}categories\u{0020}in\u{0020}the\u{0020}research,\u{0020}such\u{0020}as\u{0020}Sin\u{0020}that\u{0020}adapts\u{0020}its\u{0020}body\u{0020}size\u{0020}with\u{