[613603] = {613603, 1000, "\u{0020}Precio\u{0020}likes\u{0020}Sin,\u{0020}but\u{0020}it's\u{0020}just\u{0020}the\u{0020}kind\u{0020}of\u{0020}like\u{0020}that\u{0020}physicists\u{0020}have\u{0020}for\u{0020}physical\u{0020}phenomena\u{0020}and\u{0020}mathematicians\u{0020}have\u{0020}for\u{0020}mathematical\u{0020}problems.\u{0020}She\u{0020}is\u{0020}well\u{0020}aware\u{0020}that\u{0020}she\u{0020}only\u{0020}regards\u{0020}the\u{0020}Sin\u{0020}bees\u{0020}around\u{0020}her\u{0020}as\u{0020}tools,\u{0020}but\u{0020}outsiders\u{0020}won't\u{0020}all\u{0020}think\u{0020}so\u{0020}simply.\u{0020}The\u{0020}conservatives'\u{0020}rejection\u{0020}of\u{0020}Precio\u{0020}has\u{0020}already\u{0020}demonstrated\u{0020}this\u{0020}point.\u{0020}Not\u{0020}to\u{0020}mention\u{0020}the\u{0020}attitude\u{0020}of\u{0020}those\u{0020}who\u{0020}have\u{0020}been\u{0020}harmed\u{0020}by\u{0020}Sin.\n\nThe\u{0020}Honeymakers\u{0020}was\u{0020}formed\u{0020}precisely\u{0020}under\u{0020}such\u{0020}circumstances.\u{0020}Mojun's\u{0020}modern\u{0020}interpretation\u{0020}of\u{0020}\"universal\u{0020}love\u{0020}and\u{0020}non-aggression\"\u{0020}has\u{0020}been\u{0020}of\u{0020}great\u{0020}help\u{0020}to\u{0020}Precio.\u{0020}Maybel's\u{0020}position\u{0020}among\u{0020}the\u{0020}\"Seven\u{0020}Sages\"\u{0020}can\u{0020}also\u{0020}be\u{0020}regarded\u{0020}as\u{0020}a\u{0020}guarantee\u{0020}for\u{0020}her.Precio\u{0020}extended\u{0020}a\u{0020}helping\u{0020}hand\u{0020}to\u{0020}Stella.\u{0020}On\u{0020}the\u{0020}one\u{0020}hand,\u{0020}it\u{0020}was\u{0020}because\u{0020}of\u{0020}her\u{0020}precise\u{0020}sniping\u{0020}ability.\u{0020}On\u{0020}the\u{0020}other\u{0020}hand,\u{0020}whether\u{0020}it\u{0020}was\u{0020}due\u{0020}to\u{0020}the\u{0020}influence\u{0020}of\u{0020}her\u{0020}companions\u{0020}and\u{0020}became\u{0020}more\u{0020}humane\u{0020}than\u{0020}before?\u{0020}Regarding\u{0020}this\u{0020}point,\u{0020}perhaps\u{0020}only\u{0020}Precio\u{0020}herself\u{0020}knows.", "0", "0", "0", "0", 11036, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[613604] = {613604, 2000, "\u{0020}\u{0020}She\u{0020}is\u{0020}the\u{0020}queen\u{0020}of\u{0020}the\u{0020}swarm,\u{0020}even\u{0020}though\u{0020}she\u{0020}wears\u{0020}a\u{0020}false\u{0020}crown.\n\nCollect\u{0020}all\u{0020}the\u{0020}pollen\u{0020}of\u{0020}unknown\u{0020}and\u{0020}brew\u{0020}it\u{0020}into\u{0020}the\u{0020}honey\u{0020}named\u{0020}knowledge.\n\nDay\u{0020}after\u{0020}day,\u{0020}until\u{0020}one\u{0020}day,\u{0020}she\u{0020}discovered\u{0020}a\u{0020}new\u{0020}goal.\n\nIt\u{0020}is\u{0020}the\u{0020}navigator\u{0020}of\u{0020}the\u{0020}Danube\u{0020}and\u{0020}the\u{0020}most\u{0020}peculiar\u{0020}flower\u{0020}among\u{0020}the\u{0020}crowd.\n\nA\u{0020}born\u{0020}seeker\u{0020}of\u{0020}knowledge\u{0020}would\u{0020}naturally\u{0020}not\u{0020}let\u{0020}go\u{0020}of\u{0020}such\u{0020}an\u{0020}opportunity.\n\nShe\u{0020}greedily\u{0020}sucks\u{0020}the\u{0020}nectar,\u{0020}as\u{0020}hungry\u{0020}and\u{0020}thirsty\u{0020}as\u{0020}if\u{0020}intoxicated.", "0", "0", "0", "0", 11036, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
