[613701] = {613701, 100, "\u{0020}\u{0020}During\u{0020}the\u{0020}process\u{0020}of\u{0020}documenting\u{0020}and\u{0020}organizing\u{0020}this\u{0020}file,\u{0020}the\u{0020}driver\u{0020}herself\u{0020}requested\u{0020}to\u{0020}be\u{0020}involved\u{0020}on\u{0020}multiple\u{0020}occasions.\u{0020}However,\u{0020}this\u{0020}does\u{0020}not\u{0020}mean\u{0020}that\u{0020}the\u{0020}content\u{0020}of\u{0020}the\u{0020}file\u{0020}would\u{0020}lose\u{0020}objectivity.\u{0020}On\u{0020}the\u{0020}contrary,\u{0020}according\u{0020}to\u{0020}her\u{0020}statement,\u{0020}this\u{0020}action\u{0020}was\u{0020}to\u{0020}ensure\u{0020}the\u{0020}authenticity\u{0020}of\u{0020}the\u{0020}file,\u{0020}and\u{0020}this\u{0020}claim\u{0020}was\u{0020}obviously\u{0020}multiply\u{0020}confirmed\u{0020}in\u{0020}the\u{0020}data\u{0020}collected\u{0020}by\u{0020}AEGIS\u{0020}and\u{0020}in\u{0020}the\u{0020}communication\u{0020}with\u{0020}her.\n\nCelesia\u{0020}belongs\u{0020}to\u{0020}the\u{0020}\"Iron\u{0020}Crow\"\u{0020}and\u{0020}comes\u{0020}from\u{0020}the\u{0020}\"Holy\u{0020}Church\"\u{0020}in\u{0020}the\u{0020}Danube\u{0020}region.\u{0020}She\u{0020}serves\u{0020}as\u{0020}a\u{0020}clergy\u{0020}member\u{0020}in\u{0020}a\u{0020}church.\u{0020}Since\u{0020}she\u{0020}was\u{0020}adopted\u{0020}by\u{0020}the\u{0020}church\u{0020}when\u{0020}she\u{0020}was\u{0020}young\u{0020}and\u{0020}was\u{0020}influenced\u{0020}by\u{0020}the\u{0020}doctrine\u{0020}of\u{0020}\"ablution\u{0020}and\u{0020}purification\",\u{0020}she\u{0020}has\u{0020}become\u{0020}more\u{0020}pursuit\u{0020}of\u{0020}holiness\u{0020}than\u{0020}ordinary\u{0020}people\u{0020}and\u{0020}ordinary\u{0020}clergy.\u{0020}Whether\u{0020}it\u{0020}is\u{0020}for\u{0020}herself\u{0020}or\u{0020}others,\u{0020}for\u{0020}the\u{0020}body\u{0020}or\u{0020}the\u{0020}soul,\u{0020}and\u{0020}even\u{0020}for\u{0020}the\u{0020}file\u{0020}materials,\u{0020}Celesia\u{0020}will,\u{0020}with\u{0020}a\u{0020}solemn\u{0020}attitude,\u{0020}make\u{0020}requirements\u{0020}for\u{0020}purity\u{0020}that\u{0020}far\u{0020}exceed\u{0020}the\u{0020}usual\u{0020}standards.\n\nIf\u{0020}evaluated\u{0020}from\u{0020}a\u{0020}secular\u{0020}perspective,\u{0020}this\u{0020}has\u{0020}reached\u{0020}a\u{0020}degree\u{0020}that\u{0020}can\u{0020}be\u{0020}called\u{0020}\"obsessive\u{0020}cleanliness\".", "0", "0", "0", "0", 11037, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[613702] = {613702, 500, "\u{0020}\u{0020}If\u{0020}the\u{0020}more\u{0020}serious\u{0020}one's\u{0020}attitude\u{0020}towards\u{0020}life\u{0020}is,\u{0020}the\u{0020}more\u{0020}tired\u{0020}one\u{0020}becomes,\u{0020}then\u{0020}Celesia's\u{0020}lifestyle\u{0020}can\u{0020}indeed\u{0020}be\u{0020}regarded\u{0020}as\u{0020}a\u{0020}kind\u{0020}of\u{0020}\"asceticism\".\u{0020}According\u{0020}to\u{0020}the\u{0020}official\u{0020}statistics\u{0020}of\u{0020}the\u{0020}church,\u{0020}Celesia\u{0020}sweeps\u{0020}the\u{0020}church\u{0020}floor\u{0020}seven\u{0020}times\u{0020}a\u{0020}day\u{0020}on\u{0020}average,\u{0020}wipes\u{0020}the\u{0020}pilasters\u{0020}twice,\u{0020}cleans\u{0020}the\u{0020}stained-glass\u{0020}windows\u{0020}once,\u{0020}and\u{0020}even\u{0020}washes\u{0020}her\u{0020}hands\u{0020}with\u{0020}salt\u{0020}water\u{0020}every\u{0020}time.\u{0020}The\u{0020}result\u{0020}of\u{0020}doing\u{0020}so\u{0020}is\u{0020}that\u{0020}the\u{0020}clergy\u{0020}and\u{0020}the\u{0020}believers\u{0020}who\u{0020}participated\u{0020}in\u{0020}the\u{0020}Communion\u{0020}ceremony\u{0020}have\u{0020}never\u{0020}shown\u{0020}symptoms\u{0020}such\u{0020}as\u{0020}food\u{0020}poisoning,\u{0020}and\u{0020}it\u{0020}is\u{0020}also\u{0020}very\u{0020}rare\u{0020}for\u{0020}people\u{0020}to\u{0020}see\u{0020}the\u{0020}traces\u{0020}of\u{0020}cockroaches\u{0020}or\u{0020}mice\u{0020}in\u{0020}the\u{0020}church\u{0020}-\u{0020}the\u{0020}chance\u{0020}of\u{0020}seeing\u{0020}Sin\u{0020}here\u{0020}might\u{0020}be\u{0020}even\u{0020}greater.\n\nApart\u{0020}from\u{0020}the\u{0020}physical\u{0020}aspect,\u{0020}Celesia\u{0020}is\u{0020}equally\u{0020}persistent\u{0020}in\u{0020}spiritual\u{0020}purity.\u{0020}Her\u{0020}personal\u{0020}hobbies\u{0020}are\u{0020}extremely\u{0020}limited,\u{0020}and\u{0020}she\u{0020}has\u{0020}almost\u{0020}never\u{0020}shown\u{0020}the\u{0020}pursuit\u{0020}of\u{0020}material\u{0020}desires.\u{0020}Prayer\u{0020}and\u{0020}meditation\u{0020}seem\u{0020}to\u{0020}be\u{0020}all\u{0020}she\u{0020}has.\u{0020}Perhaps\u{0020}it\u{0020}is\u{0020}precisely\u{0020}such\u{0020}an\u{0020}extremely\u{0020}simple\u{0020}lifestyle\u{0020}that\u{0020}enables\u{0020}her\u{0020}to\u{0020}be\u{0020}energetic\u{0020}enough\u{0020}to\u{0020}conduct\u{0020}a\u{0020}major\u{0020}cleaning\u{0020}of\u{0020}the\u{0020}church\u{0020}every\u{0020}day.\n\nAdmittedly,\u{0020}this\u{0020}lifestyle\u{0020}is\u{0020}vigorously\u{0020}advocated\u{0020}by\u{0020}the\u{0020}Holy\u{0020}Church\u{0020}and\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}reasons\u{0020}why\u{0020}the\u{0020}church\u{0020}flourished\u{0020}before\u{0020}the\u{0020}modern\u{0020}era\u{0020}with\u{0020}a\u{0020}relatively\u{0020}poor\u{0020}public\u{0020}health\u{0020}level.\u{0020}However,\u{0020}Celesia's\u{0020}practice\u{0020}actually\u{0020}far\u{0020}exceeds\u{0020}the\u{0020}standards\u{0020}set\u{0020}by\u{0020}the\u{0020}church\u{0020}itself.\u{0020}Like\u{0020}other\u{0020}clergy\u{0020}members,\u{0020}Celesia\u{0020}was\u{0020}an\u{0020}orphan\u{0020}adopted\u{0020}by\u{0020}the\u{0020}church.\u{0020}Therefore,\u{0020}it\u{0020}is\u{0020}hard\u{0020}to\u{0020}know\u{0020}whether\u{0020}her\u{0020}personality\u{0020}was\u{0020}influenced\u{0020}by\u{0020}past\u{0020}experiences.\n\nCelesia's\u{0020}pursuit\u{0020}of\u{0020}purity\u{0020}turned\u{0020}into\u{0020}an\u{0020}obsession,\u{0020}enabling\u{0020}her\u{0020}to\u{0020}develop\u{0020}excellent\u{0020}insight.\u{0020}She\u{0020}couldn't\u{0020}tolerate\u{0020}even\u{0020}the\u{0020}slightest\u{0020}filth\u{0020}and\u{0020}could\u{0020}always\u{0020}spot\u{0020}the\u{0020}inconspicuous\u{0020}dust\u{0020}on\u{0020}the\u{0020}smooth\u{0020}marble\u{0020}floor\u{0020}tiles\u{0020}at\u{0020}a\u{0020}glance.\u{0020}The\u{0020}space\u{0020}she\u{0020}was\u{0020}in\u{0020}was\u{0020}always\u{0020}kept\u{0020}spotlessly\u{0020}clean,\u{0020}and\u{0020}this\u{0020}delicate\u{0020}and\u{0020}sharp\u{0020}eyesight\u{0020}was\u{0020}precisely\u{0020}what\u{0020}the\u{0020}reconnaissance\u{0020}team\u{0020}\"Iron\u{0020}Crow\"\u{0020}needed.\u{0020}Therefore,\u{0020}the\u{0020}captain\u{0020}of\u{0020}Iron\u{0020}Crow,\u{0020}Lepani,\u{0020}found\u{0020}her.", "0", "0", "0", "0", 11037, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[613703] = {613703, 1000, "\u{0020}\u{0020}Joining\u{0020}AEGIS\u{0020}and\u{0020}completing\u{0020}the\u{0020}tasks\u{0020}outstandingly\u{0020}in\u{0020}the\u{0020}Iron\u{0020}Crow\u{0020}team,\u{0020}Celesia\u{0020}initially\u{0020}regarded\u{0020}this\u{0020}only\u{0020}as\u{0020}a\u{0020}mission\u{0020}given\u{0020}by\u{0020}the\u{0020}church.\u{0020}She\u{0020}had\u{0020}no\u{0020}intention\u{0020}of\u{0020}establishing\u{0020}friendships\u{0020}with\u{0020}other\u{0020}members.\u{0020}After\u{0020}all,\u{0020}such\u{0020}a\u{0020}desire,\u{0020}like\u{0020}impurities,\u{0020}had\u{0020}never\u{0020}emerged\u{0020}in\u{0020}her\u{0020}pool\u{0020}of\u{0020}calm.\u{0020}Even\u{0020}in\u{0020}the\u{0020}church,\u{0020}people\u{0020}with\u{0020}close\u{0020}relationships\u{0020}were\u{0020}more\u{0020}like\u{0020}her\u{0020}family\u{0020}rather\u{0020}than\u{0020}friends.\n\nHowever,\u{0020}the\u{0020}long\u{0020}dormitory\u{0020}life,\u{0020}dangerous\u{0020}battles,\u{0020}the\u{0020}captain\u{0020}who\u{0020}always\u{0020}gets\u{0020}lost,\u{0020}and\u{0020}the\u{0020}teammates\u{0020}who\u{0020}cannot\u{0020}be\u{0020}left\u{0020}alone\u{0020}gradually,\u{0020}like\u{0020}complex\u{0020}organic\u{0020}substances,\u{0020}made\u{0020}Celesia's\u{0020}heart\u{0020}prone\u{0020}to\u{0020}ripples.\u{0020}Some\u{0020}trivial\u{0020}but\u{0020}vital\u{0020}emotions\u{0020}like\u{0020}algae\u{0020}or\u{0020}small\u{0020}fish\u{0020}stirred\u{0020}this\u{0020}pool\u{0020}of\u{0020}calm\u{0020}and\u{0020}made\u{0020}it\u{0020}lively.\u{0020}Although\u{0020}Celesia\u{0020}herself\u{0020}did\u{0020}not\u{0020}want\u{0020}such\u{0020}poetic\u{0020}descriptions\u{0020}to\u{0020}appear\u{0020}in\u{0020}the\u{0020}formal\u{0020}driver's\u{0020}file,\u{0020}she\u{0020}eventually\u{0020}still\u{0020}allowed\u{0020}this\u{0020}passage\u{0020}to\u{0020}be\u{0020}recorded,\u{0020}which\u{0020}was\u{0020}probably\u{0020}also\u{0020}a\u{0020}kind\u{0020}of\u{0020}proof.", "0", "0", "0", "0", 11037, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[613704] = {613704, 2000, "\u{0020}\u{0020}In\u{0020}the\u{0020}filth\u{0020}of\u{0020}this\u{0020}world,\u{0020}not\u{0020}stained\u{0020}by\u{0020}the\u{0020}slightest\u{0020}dust,\u{0020}not\u{0020}touched\u{0020}by\u{0020}confusion.\n\nLike\u{0020}crystal,\u{0020}like\u{0020}snowflake,\u{0020}like\u{0020}the\u{0020}sky,\u{0020}like\u{0020}a\u{0020}wisp\u{0020}of\u{0020}clear\u{0020}spring.\n\nHowever,\u{0020}the\u{0020}toxins\u{0020}of\u{0020}emotions\u{0020}accumulate\u{0020}within\u{0020}each\u{0020}person.\n\nWill\u{0020}it\u{0020}one\u{0020}day\u{0020}also\u{0020}erode\u{0020}her\u{0020}bones\u{0020}and\u{0020}stain\u{0020}her\u{0020}heart?\n\nAll\u{0020}kinds\u{0020}of\u{0020}doubts\u{0020}are\u{0020}as\u{0020}numerous\u{0020}as\u{0020}smoke\u{0020}and\u{0020}dust,\u{0020}covering\u{0020}the\u{0020}girl's\u{0020}eyes.\n\nAnd\u{0020}the\u{0020}appearance\u{0020}of\u{0020}that\u{0020}leader\u{0020}wiped\u{0020}away\u{0020}the\u{0020}dust\u{0020}and\u{0020}clarified\u{0020}the\u{0020}eyes.\n\nShe\u{0020}was\u{0020}able\u{0020}to\u{0020}see\u{0020}her\u{0020}heart\u{0020}clearly\u{0020}and\u{0020}seemed\u{0020}no\u{0020}longer\u{0020}confused.\n\nBecause\u{0020}of\u{0020}oneself,\u{0020}undoubtedly\u{0020}has\u{0020}contracted\u{0020}the\u{0020}illness\u{0020}named\u{0020}\"dependence\".", "0", "0", "0", "0", 11037, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
