[613802] = {613802, 500, "\u{0020}\u{0020}In\u{0020}Azure\u{0020}Academy,\u{0020}many\u{0020}driver\u{0020}students\u{0020}joined\u{0020}voluntarily\u{0020}with\u{0020}a\u{0020}passion\u{0020}for\u{0020}defending\u{0020}their\u{0020}homeland;\u{0020}some\u{0020}enrolled\u{0020}half-reluctantly\u{0020}due\u{0020}to\u{0020}being\u{0020}homeless\u{0020}and\u{0020}eager\u{0020}for\u{0020}revenge;\u{0020}and\u{0020}others\u{0020}simply\u{0020}acted\u{0020}according\u{0020}to\u{0020}the\u{0020}wishes\u{0020}of\u{0020}their\u{0020}elders\u{0020}and\u{0020}had\u{0020}little\u{0020}choice.\u{0020}Among\u{0020}the\u{0020}third\u{0020}type,\u{0020}it\u{0020}can\u{0020}be\u{0020}further\u{0020}divided\u{0020}into\u{0020}the\u{0020}heirs\u{0020}of\u{0020}noble\u{0020}military\u{0020}officer\u{0020}families\u{0020}and\u{0020}those\u{0020}from\u{0020}civilian\u{0020}families.\u{0020}Kafka\u{0020}is\u{0020}undoubtedly\u{0020}the\u{0020}latter.\u{0020}Her\u{0020}father\u{0020}unilaterally\u{0020}sent\u{0020}her\u{0020}to\u{0020}take\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}and\u{0020}then\u{0020}arranged\u{0020}for\u{0020}her\u{0020}to\u{0020}enter\u{0020}Azure\u{0020}Academy,\u{0020}completely\u{0020}disregarding\u{0020}her\u{0020}own\u{0020}will.\u{0020}The\u{0020}result\u{0020}of\u{0020}this\u{0020}arbitrary\u{0020}practice\u{0020}was\u{0020}that\u{0020}although\u{0020}Kafka\u{0020}chose\u{0020}to\u{0020}enroll\u{0020}in\u{0020}a\u{0020}fit\u{0020}of\u{0020}pique\u{0020}because\u{0020}she\u{0020}didn't\u{0020}want\u{0020}to\u{0020}go\u{0020}home,\u{0020}she\u{0020}decided\u{0020}to\u{0020}be\u{0020}a\u{0020}complete\u{0020}\"bad\u{0020}student\"\u{0020}as\u{0020}her\u{0020}rebellion.\n\nIf\u{0020}one\u{0020}could\u{0020}see\u{0020}the\u{0020}photo\u{0020}on\u{0020}Kafka's\u{0020}school\u{0020}admission\u{0020}file,\u{0020}most\u{0020}people\u{0020}should\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}associate\u{0020}it\u{0020}with\u{0020}the\u{0020}current\u{0020}problem\u{0020}student.\u{0020}She\u{0020}was\u{0020}originally\u{0020}an\u{0020}insignificant\u{0020}and\u{0020}ordinary\u{0020}girl.\u{0020}Probably\u{0020}because\u{0020}she\u{0020}was\u{0020}more\u{0020}sensible,\u{0020}elders\u{0020}could\u{0020}easily\u{0020}control\u{0020}her\u{0020}life.\u{0020}But\u{0020}after\u{0020}Kafka\u{0020}decided\u{0020}to\u{0020}take\u{0020}the\u{0020}rebellious\u{0020}path,\u{0020}the\u{0020}seriousness\u{0020}she\u{0020}devoted\u{0020}to\u{0020}this\u{0020}transformation\u{0020}should\u{0020}not\u{0020}be\u{0020}underestimated.\u{0020}She\u{0020}replicated\u{0020}the\u{0020}image\u{0020}of\u{0020}a\u{0020}delinquent\u{0020}girl\u{0020}she\u{0020}saw\u{0020}in\u{0020}comics\u{0020}and\u{0020}games\u{0020}almost\u{0020}completely\u{0020}on\u{0020}herself,\u{0020}with\u{0020}messy\u{0020}and\u{0020}dyed\u{0020}hair,\u{0020}wearing\u{0020}studded\u{0020}leather\u{0020}jackets\u{0020}and\u{0020}straps...\u{0020}Although\u{0020}it\u{0020}was\u{0020}only\u{0020}a\u{0020}bad\u{0020}appearance\u{0020}in\u{0020}disguise,\u{0020}she\u{0020}had\u{0020}already\u{0020}begun\u{0020}to\u{0020}leave\u{0020}an\u{0020}impression\u{0020}in\u{0020}people's\u{0020}hearts.\n\nSome\u{0020}truly\u{0020}disrespectful\u{0020}and\u{0020}clique-forming\u{0020}delinquent\u{0020}girls\u{0020}regarded\u{0020}Kafka's\u{0020}existence\u{0020}as\u{0020}a\u{0020}challenge.\u{0020}According\u{0020}to\u{0020}their\u{0020}unwritten\u{0020}rules,\u{0020}a\u{0020}duel\u{0020}to\u{0020}determine\u{0020}each\u{0020}other's\u{0020}status\u{0020}was\u{0020}inevitable.\u{0020}However,\u{0020}according\u{0020}to\u{0020}Kafka's\u{0020}later\u{0020}account,\u{0020}she\u{0020}actually\u{0020}didn't\u{0020}care\u{0020}about\u{0020}the\u{0020}so-called\u{0020}status.\u{0020}The\u{0020}reason\u{0020}she\u{0020}accepted\u{0020}that\u{0020}duel\u{0020}was\u{0020}actually\u{0020}just\u{0020}to\u{0020}stick\u{0020}to\u{0020}the\u{0020}\"persona\"\u{0020}she\u{0020}had\u{0020}worked\u{0020}hard\u{0020}to\u{0020}shape.\u{0020}After\u{0020}all,\u{0020}if\u{0020}she\u{0020}gave\u{0020}up\u{0020}and\u{0020}evaded\u{0020}at\u{0020}this\u{0020}stage,\u{0020}her\u{0020}father\u{0020}would\u{0020}only\u{0020}take\u{0020}her\u{0020}opinions\u{0020}even\u{0020}less\u{0020}seriously\u{0020}and\u{0020}regard\u{0020}this\u{0020}rebellion\u{0020}as\u{0020}the\u{0020}playfulness\u{0020}of\u{0020}an\u{0020}ignorant\u{0020}girl...\u{0020}Thus,\u{0020}Kafka\u{0020}engaged\u{0020}in\u{0020}the\u{0020}battle.\u{0020}And\u{0020}after\u{0020}her\u{0020}first\u{0020}victory,\u{0020}she\u{0020}became\u{0020}famous,\u{0020}and\u{0020}more\u{0020}and\u{0020}more\u{0020}strange\u{0020}problem\u{0020}students\u{0020}came\u{0020}to\u{0020}challenge\u{0020}her\u{0020}upon\u{0020}hearing\u{0020}the\u{0020}news.\u{0020}Kafka's\u{0020}fate\u{0020}thus\u{0020}went\u{0020}astray\u{0020}by\u{0020}accident,\u{0020}and\u{0020}she\u{0020}gradually\u{0020}became\u{0020}a\u{0020}de\u{0020}facto\u{0020}delinquent\u{0020}girl\u{0020}in\u{0020}many\u{0020}violent\u{0020}incidents.", "0", "0", "0", "0", 11038, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
