[614001] = {614001, 100, "After\u{0020}\"Envy\",\u{0020}the\u{0020}former\u{0020}member\u{0020}of\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}-\u{0020}Dolores·Gavieta\u{0020}reorganized\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad.\u{0020}However,\u{0020}the\u{0020}experimental\u{0020}equipment\u{0020}of\u{0020}the\u{0020}Third\u{0020}Research\u{0020}Laboratory\u{0020}was\u{0020}largely\u{0020}damaged.\u{0020}Everyone\u{0020}in\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}could\u{0020}only\u{0020}temporarily\u{0020}become\u{0020}a\u{0020}team\u{0020}outside\u{0020}the\u{0020}system\u{0020}and\u{0020}was\u{0020}constantly\u{0020}traveling\u{0020}everywhere.\n\nWhen\u{0020}Dolores\u{0020}became\u{0020}the\u{0020}captain\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}she\u{0020}clearly\u{0020}knew\u{0020}what\u{0020}she\u{0020}was\u{0020}acting\u{0020}for.\u{0020}Similarly,\u{0020}for\u{0020}her\u{0020}who\u{0020}faced\u{0020}and\u{0020}solved\u{0020}Major\u{0020}Sin\u{0020}and\u{0020}Great\u{0020}Sin\u{0020}directly,\u{0020}even\u{0020}though\u{0020}her\u{0020}eligibility\u{0020}rate\u{0020}was\u{0020}at\u{0020}the\u{0020}bottom\u{0020}among\u{0020}the\u{0020}navigators,\u{0020}her\u{0020}adaptability\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}judgment\u{0020}were\u{0020}much\u{0020}stronger\u{0020}than\u{0020}the\u{0020}average\u{0020}navigator.\u{0020}She\u{0020}could\u{0020}always\u{0020}calmly\u{0020}give\u{0020}suggestions\u{0020}and\u{0020}make\u{0020}the\u{0020}most\u{0020}correct\u{0020}decisions\u{0020}in\u{0020}the\u{0020}face\u{0020}of\u{0020}any\u{0020}crisis.\u{0020}Coupled\u{0020}with\u{0020}her\u{0020}personality,\u{0020}she\u{0020}quickly\u{0020}established\u{0020}a\u{0020}trusting\u{0020}relationship\u{0020}with\u{0020}her\u{0020}new\u{0020}teammates.\n\nThe\u{0020}reestablished\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}has\u{0020}been\u{0020}recognized\u{0020}by\u{0020}other\u{0020}squads\u{0020}with\u{0020}its\u{0020}own\u{0020}strength\u{0020}in\u{0020}one\u{0020}special\u{0020}assistance\u{0020}mission\u{0020}after\u{0020}another.", "0", "0", "0", "0", 11040, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614002] = {614002, 500, "Because\u{0020}the\u{0020}laboratory\u{0020}was\u{0020}destroyed,\u{0020}the\u{0020}\"Greed\u{0020}Core\"\u{0020}and\u{0020}the\u{0020}\"Envy\u{0020}Core\"\u{0020}lost\u{0020}their\u{0020}containment\u{0020}sites,\u{0020}resulting\u{0020}in\u{0020}frequent\u{0020}Danube\u{0020}Sin\u{0020}invasions.\u{0020}In\u{0020}order\u{0020}to\u{0020}maintain\u{0020}stability,\u{0020}Danube\u{0020}is\u{0020}unable\u{0020}to\u{0020}mobilize\u{0020}large-scale\u{0020}troops\u{0020}to\u{0020}transport\u{0020}the\u{0020}core,\u{0020}and\u{0020}if\u{0020}this\u{0020}continues,\u{0020}Danube's\u{0020}situation\u{0020}will\u{0020}become\u{0020}precarious\u{0020}as\u{0020}drivers\u{0020}continue\u{0020}to\u{0020}be\u{0020}damaged.At\u{0020}the\u{0020}same\u{0020}time,\u{0020}after\u{0020}the\u{0020}appearance\u{0020}of\u{0020}Great\u{0020}Sin\u{0020}\"Envy\",\u{0020}the\u{0020}frequency\u{0020}of\u{0020}Haze\u{0020}occurrences\u{0020}in\u{0020}various\u{0020}places\u{0020}has\u{0020}also\u{0020}increased\u{0020}accordingly.\u{0020}Therefore,\u{0020}major\u{0020}branches\u{0020}have\u{0020}raised\u{0020}their\u{0020}security\u{0020}levels,\u{0020}and\u{0020}drivers\u{0020}in\u{0020}various\u{0020}places\u{0020}have\u{0020}entered\u{0020}a\u{0020}wartime\u{0020}stage\u{0020}of\u{0020}being\u{0020}on\u{0020}standby\u{0020}at\u{0020}any\u{0020}time.\n\nAfter\u{0020}a\u{0020}long\u{0020}wait,\u{0020}the\u{0020}solution\u{0020}for\u{0020}the\u{0020}Third\u{0020}Research\u{0020}Laboratory\u{0020}has\u{0020}finally\u{0020}been\u{0020}reached.\n\nThe\u{0020}Third\u{0020}Research\u{0020}Laboratory\u{0020}will\u{0020}be\u{0020}reconstructed.\u{0020}Before\u{0020}that,\u{0020}the\u{0020}experimental\u{0020}projects\u{0020}will\u{0020}be\u{0020}fully\u{0020}taken\u{0020}over\u{0020}by\u{0020}Dr.\u{0020}Alvitr.\u{0020}The\u{0020}experiments\u{0020}related\u{0020}to\u{0020}the\u{0020}\"Greed\u{0020}Core\"\u{0020}must\u{0020}not\u{0020}be\u{0020}delayed.\u{0020}Relevant\u{0020}personnel\u{0020}will\u{0020}be\u{0020}transferred\u{0020}to\u{0020}the\u{0020}First\u{0020}Research\u{0020}Laboratory\u{0020}located\u{0020}in\u{0020}Katya,\u{0020}which\u{0020}of\u{0020}course\u{0020}also\u{0020}includes\u{0020}the\u{0020}mandatory\u{0020}scheduling\u{0020}of\u{0020}the\u{0020}Third\u{0020}Research\u{0020}Laboratory.\n\nSaar\u{0020}is\u{0020}a\u{0020}place\u{0020}of\u{0020}great\u{0020}significance\u{0020}to\u{0020}Dolores.\u{0020}It\u{0020}is\u{0020}not\u{0020}only\u{0020}where\u{0020}she\u{0020}was\u{0020}born\u{0020}but\u{0020}also\u{0020}where\u{0020}she\u{0020}was\u{0020}endowed\u{0020}with\u{0020}fine\u{0020}qualities\u{0020}and\u{0020}where\u{0020}her\u{0020}hometown\u{0020}was\u{0020}saved.\u{0020}Considering\u{0020}the\u{0020}situation\u{0020}of\u{0020}the\u{0020}new\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}and\u{0020}Dolores,\u{0020}this\u{0020}tough\u{0020}dispatch\u{0020}order\u{0020}was\u{0020}timely\u{0020}stopped\u{0020}by\u{0020}a\u{0020}certain\u{0020}leader.\u{0020}However,\u{0020}on\u{0020}a\u{0020}voluntary\u{0020}basis,\u{0020}the\u{0020}relevant\u{0020}documents\u{0020}were\u{0020}still\u{0020}delivered\u{0020}to\u{0020}Dolores.\n\nShe\u{0020}did\u{0020}not\u{0020}refuse\u{0020}immediately.\u{0020}Instead,\u{0020}she\u{0020}asked\u{0020}her\u{0020}teammates\u{0020}for\u{0020}their\u{0020}opinions,\u{0020}and\u{0020}the\u{0020}answer\u{0020}she\u{0020}got\u{0020}was\u{0020}-\u{0020}no\u{0020}matter\u{0020}where\u{0020}Dolores\u{0020}would\u{0020}go,\u{0020}they\u{0020}all\u{0020}hoped\u{0020}to\u{0020}continue\u{0020}following\u{0020}her.\n\nDolores\u{0020}finally\u{0020}chose\u{0020}to\u{0020}go\u{0020}to\u{0020}Katya.\u{0020}She\u{0020}believes\u{0020}that\u{0020}in\u{0020}the\u{0020}near\u{0020}future,\u{0020}she\u{0020}will\u{0020}return\u{0020}to\u{0020}Saar\u{0020}with\u{0020}the\u{0020}completion\u{0020}of\u{0020}the\u{0020}Third\u{0020}Research\u{0020}Laboratory.\u{0020}Before\u{0020}that,\u{0020}she\u{0020}wants\u{0020}to\u{0020}make\u{0020}her\u{0020}own\u{0020}contribution\u{0020}to\u{0020}the\u{0020}smooth\u{0020}progress\u{0020}of\u{0020}this\u{0020}matter.\n\nThen\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}began\u{0020}the\u{0020}first\u{0020}mission\u{0020}related\u{0020}to\u{0020}the\u{0020}Third\u{0020}Research\u{0020}Laboratory\u{0020}after\u{0020}the\u{0020}reconstruction.\u{0020}If\u{0020}the\u{0020}future\u{0020}remains\u{0020}unchanged,\u{0020}this\u{0020}will\u{0020}also\u{0020}be\u{0020}their\u{0020}last\u{0020}mission.", "0", "0", "0", "0", 11040, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614003] = {614003, 1000, "The\u{0020}predetermined\u{0020}death\u{0020}was\u{0020}changed\u{0020}by\u{0020}everyone\u{0020}together.\n\nDolores\u{0020}has\u{0020}become\u{0020}the\u{0020}most\u{0020}obvious\u{0020}beneficiary\u{0020}of\u{0020}this\u{0020}event\u{0020}and\u{0020}has\u{0020}become\u{0020}a\u{0020}\"ACE\".\u{0020}However,\u{0020}behind\u{0020}this\u{0020}miracle\u{0020}lies\u{0020}a\u{0020}huge\u{0020}responsibility.\u{0020}Firstly,\u{0020}it\u{0020}is\u{0020}inevitable\u{0020}that\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}will\u{0020}need\u{0020}to\u{0020}participate\u{0020}in\u{0020}more\u{0020}high-risk\u{0020}battles\u{0020}afterwards;\u{0020}then\u{0020}it\u{0020}is\u{0020}necessary\u{0020}to\u{0020}cooperate\u{0020}with\u{0020}the\u{0020}research\u{0020}laboratory\u{0020}for\u{0020}regular\u{0020}experiments;\u{0020}the\u{0020}aftereffects\u{0020}of\u{0020}using\u{0020}the\u{0020}Sin\u{0020}Annihilation\u{0020}Cannon,\u{0020}etc...\u{0020}Such\u{0020}restrictive\u{0020}conditions\u{0020}have\u{0020}been\u{0020}imposed\u{0020}on\u{0020}Dolores\u{0020}and\u{0020}the\u{0020}people\u{0020}around\u{0020}her,\u{0020}and\u{0020}these\u{0020}are\u{0020}still\u{0020}within\u{0020}an\u{0020}acceptable\u{0020}range.\n\nThe\u{0020}only\u{0020}thing\u{0020}that\u{0020}Dolores\u{0020}doesn't\u{0020}understand\u{0020}is\u{0020}the\u{0020}request\u{0020}made\u{0020}to\u{0020}her\u{0020}by\u{0020}Dr.\u{0020}Kurenai\u{0020}-\n\nAren't\u{0020}you\u{0020}afraid\u{0020}of\u{0020}being\u{0020}forgotten\u{0020}by\u{0020}others?\u{0020}Then\u{0020}become\u{0020}a\u{0020}dazzling\u{0020}presence\u{0020}that\u{0020}everyone\u{0020}remembers\u{0020}deeply.\u{0020}That\u{0020}is\u{0020}an\u{0020}\"idol\"\u{0020}-\u{0020}a\u{0020}charming\u{0020}and\u{0020}active\u{0020}person\u{0020}who\u{0020}shares\u{0020}the\u{0020}growth\u{0020}process\u{0020}with\u{0020}fans.\u{0020}Go\u{0020}find\u{0020}and\u{0020}consult\u{0020}the\u{0020}predecessors\u{0020}among\u{0020}the\u{0020}drivers,\u{0020}and\u{0020}then\u{0020}become\u{0020}the\u{0020}one\u{0020}who\u{0020}can\u{0020}carry\u{0020}everyone's\u{0020}\"expectations\"\u{0020}and\u{0020}\"hopes\".\u{0020}If\u{0020}you\u{0020}can't\u{0020}do\u{0020}it,\u{0020}return\u{0020}the\u{0020}\"performance\u{0020}costume\"\u{0020}to\u{0020}me.\n\nDolores\u{0020}certainly\u{0020}has\u{0020}the\u{0020}determination\u{0020}to\u{0020}continue\u{0020}this\u{0020}hope,\u{0020}but\u{0020}this\u{0020}requirement\u{0020}is\u{0020}really\u{0020}too\u{0020}strange.", "0", "0", "0", "0", 11040, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614004] = {614004, 2000, "After\u{0020}the\u{0020}rainstorm,\u{0020}pick\u{0020}up\u{0020}the\u{0020}shield\u{0020}of\u{0020}protection\u{0020}in\u{0020}your\u{0020}hand.\n\nFace\u{0020}the\u{0020}future\u{0020}before\u{0020}the\u{0020}correct\u{0020}answer\u{0020}of\u{0020}\"escape\".\n\nThere\u{0020}are\u{0020}many\u{0020}reasons\u{0020}why\u{0020}Dolores\u{0020}is\u{0020}not\u{0020}afraid.\n\nAfter\u{0020}the\u{0020}vow,\u{0020}carry\u{0020}the\u{0020}past\u{0020}and\u{0020}transcend\u{0020}death.\n\nLet\u{0020}sadness\u{0020}be\u{0020}far\u{0020}away\u{0020}and\u{0020}let\u{0020}hope\u{0020}be\u{0020}passed\u{0020}on.\n\nThe\u{0020}promise\u{0020}made\u{0020}with\u{0020}you.\n\nThere\u{0020}are\u{0020}many\u{0020}reasons\u{0020}why\u{0020}Dolores\u{0020}is\u{0020}looking\u{0020}forward\u{0020}to\u{0020}tomorrow.", "0", "0", "0", "0", 11040, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
