[614101] = {614101, 100, "\u{0020}\u{0020}Suana·Yeli·Alessa·Y·Paz·Gispe,The\u{0020}deputy\u{0020}chief\u{0020}of\u{0020}the\u{0020}security\u{0020}section\u{0020}of\u{0020}the\u{0020}Social\u{0020}Rehabilitation\u{0020}Department\u{0020}of\u{0020}the\u{0020}Inca\u{0020}Branch\u{0020}has\u{0020}stayed\u{0020}this\u{0020}time\u{0020}to\u{0020}retrieve\u{0020}a\u{0020}piece\u{0020}of\u{0020}goods\u{0020}that\u{0020}was\u{0020}wrongly\u{0020}sent\u{0020}to\u{0020}the\u{0020}Danube\u{0020}Branch.\u{0020}However,\u{0020}according\u{0020}to\u{0020}the\u{0020}investigation\u{0020}of\u{0020}the\u{0020}Materials\u{0020}Department,\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}did\u{0020}not\u{0020}receive\u{0020}the\u{0020}goods.\u{0020}The\u{0020}specific\u{0020}situation\u{0020}is\u{0020}still\u{0020}under\u{0020}investigation...\n\nWhile\u{0020}waiting\u{0020}for\u{0020}the\u{0020}investigation\u{0020}results,\u{0020}she\u{0020}exchanged\u{0020}contact\u{0020}information\u{0020}with\u{0020}the\u{0020}navigator\u{0020}and\u{0020}participated\u{0020}in\u{0020}many\u{0020}operations\u{0020}as\u{0020}an\u{0020}expatriate\u{0020}driver,\u{0020}including\u{0020}but\u{0020}not\u{0020}limited\u{0020}to\u{0020}patrols,\u{0020}repelling\u{0020}Sin,\u{0020}and\u{0020}escorting\u{0020}the\u{0020}evacuation\u{0020}of\u{0020}the\u{0020}public.\u{0020}However,\u{0020}the\u{0020}enemy-engaging\u{0020}concept\u{0020}of\u{0020}this\u{0020}deputy\u{0020}section\u{0020}chief\u{0020}is\u{0020}very\u{0020}different\u{0020}from\u{0020}that\u{0020}of\u{0020}other\u{0020}drivers\u{0020}she\u{0020}has\u{0020}worked\u{0020}with\u{0020}According\u{0020}to\u{0020}what\u{0020}she\u{0020}said\u{0020}herself,\u{0020}the\u{0020}combat\u{0020}mission\u{0020}assigned\u{0020}by\u{0020}the\u{0020}Inca\u{0020}Branch\u{0020}to\u{0020}the\u{0020}Iskanwaya\u{0020}team\u{0020}is\u{0020}only\u{0020}and\u{0020}merely\u{0020}\"contain\u{0020}Sin\".\u{0020}Only\u{0020}containment.\u{0020}Actions\u{0020}such\u{0020}as\u{0020}pursuit\u{0020}and\u{0020}annihilation\u{0020}that\u{0020}would\u{0020}leave\u{0020}the\u{0020}current\u{0020}coordinates\u{0020}are\u{0020}strictly\u{0020}prohibited.\n\n\"Fortunately,\u{0020}Deputy\u{0020}Section\u{0020}Chief\u{0020}Suana\u{0020}is\u{0020}willing\u{0020}to\u{0020}try\u{0020}new\u{0020}combat\u{0020}plans\u{0020}and\u{0020}is\u{0020}not\u{0020}stubborn...\u{0020}Well,\u{0020}okay,\u{0020}actually\u{0020}she\u{0020}is\u{0020}quite\u{0020}stubborn\u{0020}in\u{0020}insisting\u{0020}that\u{0020}we\u{0020}change\u{0020}our\u{0020}way\u{0020}of\u{0020}addressing\u{0020}and\u{0020}use\u{0020}'Vega'.\"", "0", "0", "0", "0", 11041, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614102] = {614102, 500, "\u{0020}\u{0020}In\u{0020}the\u{0020}Inca,\u{0020}there\u{0020}were\u{0020}some\u{0020}rather\u{0020}special\u{0020}squads,\u{0020}which\u{0020}were\u{0020}not\u{0020}entirely\u{0020}subordinate\u{0020}to\u{0020}the\u{0020}Strategic\u{0020}Department,\u{0020}but\u{0020}were\u{0020}scattered\u{0020}among\u{0020}the\u{0020}other\u{0020}ten\u{0020}departments\u{0020}outside\u{0020}the\u{0020}Strategic\u{0020}Department.\u{0020}Vega's\u{0020}team,\u{0020}Iskanwaya,\u{0020}in\u{0020}addition\u{0020}to\u{0020}the\u{0020}work\u{0020}related\u{0020}to\u{0020}Sin,\u{0020}will\u{0020}also\u{0020}be\u{0020}assigned\u{0020}a\u{0020}lot\u{0020}of\u{0020}paperwork.\n\nIt's\u{0020}only\u{0020}because\u{0020}their\u{0020}Compatability\u{0020}Rates\u{0020}are\u{0020}indeed\u{0020}too\u{0020}low,\u{0020}and\u{0020}the\u{0020}training\u{0020}time\u{0020}for\u{0020}the\u{0020}drivers\u{0020}is\u{0020}extremely\u{0020}short.\u{0020}They\u{0020}don't\u{0020}have\u{0020}the\u{0020}ability\u{0020}to\u{0020}compete\u{0020}with\u{0020}Sin.\u{0020}Compared\u{0020}with\u{0020}those\u{0020}drivers\u{0020}belonging\u{0020}to\u{0020}the\u{0020}Strategic\u{0020}Department,\u{0020}it's\u{0020}like\u{0020}genuine\u{0020}products\u{0020}and\u{0020}counterfeits.\n\nHowever,\u{0020}no\u{0020}one\u{0020}expected\u{0020}them\u{0020}to\u{0020}become\u{0020}remarkable\u{0020}warriors.\n\nThese\u{0020}drivers\u{0020}only\u{0020}need\u{0020}to\u{0020}be\u{0020}able\u{0020}to\u{0020}successfully\u{0020}gigantify\u{0020}themselves.\n\nIn\u{0020}the\u{0020}Inca\u{0020}Branch,\u{0020}the\u{0020}Sin-related\u{0020}task\u{0020}they\u{0020}were\u{0020}most\u{0020}exposed\u{0020}to\u{0020}was\u{0020}to\u{0020}contain\u{0020}Sin\u{0020}at\u{0020}the\u{0020}forefront\u{0020}of\u{0020}the\u{0020}battlefield,\u{0020}buying\u{0020}more\u{0020}time\u{0020}for\u{0020}the\u{0020}personnel\u{0020}at\u{0020}the\u{0020}rear\u{0020}to\u{0020}transfer\u{0020}cultural\u{0020}relics\u{0020}and\u{0020}materials\u{0020}of\u{0020}various\u{0020}values.\u{0020}The\u{0020}paperwork\u{0020}arranged\u{0020}on\u{0020}weekdays\u{0020}was\u{0020}also\u{0020}to\u{0020}enable\u{0020}them\u{0020}to\u{0020}understand\u{0020}each\u{0020}link\u{0020}of\u{0020}the\u{0020}evacuation\u{0020}and\u{0020}know\u{0020}how\u{0020}to\u{0020}contain\u{0020}Sin\u{0020}to\u{0020}avoid\u{0020}losses\u{0020}with\u{0020}the\u{0020}greatest\u{0020}probability.\n\nTherefore,\u{0020}compared\u{0020}to\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}and\u{0020}combat\u{0020}experience,\u{0020}whether\u{0020}they\u{0020}have\u{0020}the\u{0020}determination\u{0020}to\u{0020}die\u{0020}for\u{0020}defending\u{0020}the\u{0020}defense\u{0020}line\u{0020}is\u{0020}even\u{0020}more\u{0020}important.\n\n\"Just\u{0020}by\u{0020}using\u{0020}a\u{0020}few,\u{0020}dozens,\u{0020}or\u{0020}hundreds\u{0020}of\u{0020}drivers\u{0020}with\u{0020}a\u{0020}low\u{0020}Compatability\u{0020}Rate,\u{0020}you\u{0020}can\u{0020}exchange\u{0020}for\u{0020}invaluable\u{0020}relics\u{0020}and\u{0020}cultural\u{0020}artifacts.\u{0020}It's\u{0020}an\u{0020}absolute\u{0020}windfall.\"\n\nAlthough\u{0020}this\u{0020}was\u{0020}said,\u{0020}judging\u{0020}from\u{0020}Vega's\u{0020}expression\u{0020}and\u{0020}tone\u{0020}at\u{0020}that\u{0020}time,\u{0020}she\u{0020}seemed\u{0020}to\u{0020}strongly\u{0020}disagree\u{0020}with\u{0020}this\u{0020}concept.\n\nIf\u{0020}not\u{0020}for\u{0020}repaying\u{0020}the\u{0020}life-saving\u{0020}grace\u{0020}four\u{0020}years\u{0020}ago,\u{0020}perhaps\u{0020}she\u{0020}wouldn't\u{0020}have\u{0020}had\u{0020}any\u{0020}intersection\u{0020}with\u{0020}AEGIS\u{0020}until\u{0020}now,\u{0020}and\u{0020}it's\u{0020}even\u{0020}more\u{0020}impossible\u{0020}for\u{0020}her\u{0020}to\u{0020}become\u{0020}a\u{0020}driver.\u{0020}As\u{0020}for\u{0020}exactly\u{0020}what\u{0020}happened\u{0020}at\u{0020}that\u{0020}time?\u{0020}Why\u{0020}did\u{0020}she\u{0020}end\u{0020}up\u{0020}in\u{0020}a\u{0020}life-threatening\u{0020}situation?\u{0020}Vega\u{0020}is\u{0020}unwilling\u{0020}to\u{0020}talk\u{0020}about\u{0020}it.\u{0020}And\u{0020}the\u{0020}file\u{0020}related\u{0020}to\u{0020}her\u{0020}provided\u{0020}by\u{0020}the\u{0020}Intelligence\u{0020}Department\u{0020}of\u{0020}the\u{0020}Inca\u{0020}Branch\u{0020}starts\u{0020}from\u{0020}a\u{0020}blood\u{0020}test\u{0020}report\u{0020}issued\u{0020}by\u{0020}the\u{0020}Medical\u{0020}Department\u{0020}four\u{0020}years\u{0020}ago,\u{0020}titled\u{0020}\"Abnormal\u{0020}Cell\u{0020}and\u{0020}Organ\u{0020}Functions\u{0020}Caused\u{0020}by\u{0020}Excessive\u{0020}Injection\u{0020}of\u{0020}Prohibited\u{0020}Drugs\".", "0", "0", "0", "0", 11041, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614103] = {614103, 1000, "\u{0020}\u{0020}Archaeology\u{0020}is\u{0020}not\u{0020}so\u{0020}much\u{0020}her\u{0020}hobby\u{0020}as\u{0020}a\u{0020}deep-seated\u{0020}mark.\u{0020}Although\u{0020}she\u{0020}has\u{0020}long\u{0020}cut\u{0020}off\u{0020}contact\u{0020}with\u{0020}her\u{0020}parents,\u{0020}the\u{0020}habits\u{0020}cultivated\u{0020}since\u{0020}childhood\u{0020}have\u{0020}always\u{0020}followed\u{0020}her,\u{0020}reminding\u{0020}her\u{0020}of\u{0020}the\u{0020}disgusting\u{0020}blood\u{0020}flowing\u{0020}in\u{0020}her\u{0020}body.\n\n\"Is\u{0020}it\u{0020}in\u{0020}your\u{0020}opinion\u{0020}that\u{0020}for\u{0020}the\u{0020}so-called\u{0020}cultural\u{0020}relics,\u{0020}anything\u{0020}can\u{0020}be\u{0020}given\u{0020}up?\u{0020}Even\u{0020}a\u{0020}living\u{0020}person?\"\n\n...Even\u{0020}if\u{0020}it\u{0020}were\u{0020}me?\n\nSuyana\u{0020}remembered\u{0020}that\u{0020}for\u{0020}her\u{0020}questioning,\u{0020}her\u{0020}parents\u{0020}were\u{0020}just\u{0020}silent.\u{0020}But\u{0020}those\u{0020}two\u{0020}pairs\u{0020}of\u{0020}unwavering\u{0020}and\u{0020}determined\u{0020}eyes\u{0020}said\u{0020}it\u{0020}all.\u{0020}So\u{0020}she\u{0020}left\u{0020}home,\u{0020}joined\u{0020}a\u{0020}civilian\u{0020}rescue\u{0020}organization,\u{0020}and\u{0020}did\u{0020}her\u{0020}best\u{0020}to\u{0020}help\u{0020}all\u{0020}those\u{0020}who\u{0020}refused\u{0020}AEGIS\u{0020}assistance.\u{0020}Did\u{0020}her\u{0020}best\u{0020}to\u{0020}deny\u{0020}her\u{0020}parents'\u{0020}ridiculous\u{0020}insistence.\n\nBut\u{0020}fate\u{0020}sent\u{0020}Suana\u{0020}back\u{0020}to\u{0020}her\u{0020}parents\u{0020}again.\n\nNowadays,\u{0020}she,\u{0020}code-named\u{0020}Vega,\u{0020}as\u{0020}a\u{0020}driver,\u{0020}has\u{0020}engaged\u{0020}in\u{0020}battles\u{0020}with\u{0020}Sin\u{0020}many\u{0020}times,\u{0020}striving\u{0020}to\u{0020}gain\u{0020}retreat\u{0020}time\u{0020}for\u{0020}her\u{0020}parents\u{0020}and\u{0020}other\u{0020}archaeologists\u{0020}who\u{0020}are\u{0020}still\u{0020}obsessed\u{0020}with\u{0020}the\u{0020}relics.\u{0020}However,\u{0020}even\u{0020}though\u{0020}she\u{0020}had\u{0020}had\u{0020}multiple\u{0020}voice\u{0020}communications\u{0020}with\u{0020}the\u{0020}couple\u{0020}during\u{0020}the\u{0020}evacuation\u{0020}operation,\u{0020}they\u{0020}did\u{0020}not\u{0020}recognize\u{0020}her\u{0020}voice.\n\nIn\u{0020}disappointment\u{0020}after\u{0020}disappointment,\u{0020}she\u{0020}gradually\u{0020}let\u{0020}go\u{0020}and\u{0020}felt\u{0020}that\u{0020}the\u{0020}so-called\u{0020}family\u{0020}was\u{0020}just\u{0020}such\u{0020}a\u{0020}dispensable\u{0020}relationship.\n\nUntil\u{0020}meeting\u{0020}that\u{0020}navigator\u{0020}in\u{0020}the\u{0020}Danube.\n\nHe\u{0020}has\u{0020}no\u{0020}blood\u{0020}relationship\u{0020}with\u{0020}his\u{0020}sister\u{0020}who\u{0020}serves\u{0020}as\u{0020}an\u{0020}intelligence\u{0020}officer,\u{0020}but\u{0020}they\u{0020}have\u{0020}a\u{0020}bond\u{0020}stronger\u{0020}than\u{0020}that\u{0020}of\u{0020}any\u{0020}family.\n\nThe\u{0020}former\u{0020}relief\u{0020}turned\u{0020}into\u{0020}confusion,\u{0020}prompting\u{0020}her\u{0020}to\u{0020}approach\u{0020}the\u{0020}two\u{0020}step\u{0020}by\u{0020}step\u{0020}to\u{0020}observe\u{0020}and\u{0020}study\u{0020}their\u{0020}every\u{0020}detail.", "0", "0", "0", "0", 11041, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614104] = {614104, 2000, "\u{0020}\u{0020}Navigator.\n\nI\u{0020}have\u{0020}imagined\u{0020}many\u{0020}times\u{0020}that\u{0020}if\u{0020}one\u{0020}day,\u{0020}I\u{0020}sacrifice\u{0020}on\u{0020}the\u{0020}battlefield...\n\nThe\u{0020}department\u{0020}will\u{0020}have\u{0020}a\u{0020}new\u{0020}deputy\u{0020}section\u{0020}chief,\u{0020}and\u{0020}the\u{0020}14th\u{0020}team\u{0020}will\u{0020}also\u{0020}have\u{0020}a\u{0020}new\u{0020}driver.\u{0020}As\u{0020}for\u{0020}that\u{0020}couple...\u{0020}Well,\u{0020}they\u{0020}probably\u{0020}wouldn't\u{0020}care\u{0020}even\u{0020}if\u{0020}they\u{0020}knew.\u{0020}My\u{0020}death\u{0020}won't\u{0020}cause\u{0020}them\u{0020}any\u{0020}confusion.\n\nBut\u{0020}perhaps\u{0020}you\u{0020}will\u{0020}remember\u{0020}me?\u{0020}No,\u{0020}you\u{0020}will\u{0020}surely\u{0020}remember\u{0020}me.\n\nAfter\u{0020}all,\u{0020}you\u{0020}are\u{0020}such\u{0020}a\u{0020}person.\n\nSo\u{0020}it\u{0020}seems\u{0020}that\u{0020}the\u{0020}greatest\u{0020}gain\u{0020}for\u{0020}me\u{0020}coming\u{0020}to\u{0020}Danube\u{0020}should\u{0020}be\u{0020}meeting\u{0020}you.\u{0020}Thank\u{0020}you.\n\nSuana", "0", "0", "0", "0", 11041, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
