[614201] = {614201, 100, "\u{0020}\u{0020}Kyla,\u{0020}originally\u{0020}named\u{0020}Kyla·Triaviemzum,\u{0020}usually\u{0020}doesn't\u{0020}introduce\u{0020}herself\u{0020}like\u{0020}this\u{0020}to\u{0020}others\u{0020}because\u{0020}she\u{0020}can't\u{0020}remember\u{0020}her\u{0020}full\u{0020}name.\u{0020}She\u{0020}only\u{0020}allows\u{0020}people\u{0020}to\u{0020}call\u{0020}her\u{0020}\"Kyla\".\u{0020}Even\u{0020}if\u{0020}you\u{0020}call\u{0020}her\u{0020}\"Miss\u{0020}Kyla\",\u{0020}she\u{0020}will\u{0020}think\u{0020}you\u{0020}are\u{0020}calling\u{0020}someone\u{0020}else.\n\nHer\u{0020}poor\u{0020}memory\u{0020}has\u{0020}caused\u{0020}many\u{0020}inconveniences\u{0020}in\u{0020}her\u{0020}life,\u{0020}the\u{0020}most\u{0020}obvious\u{0020}of\u{0020}which\u{0020}is\u{0020}that\u{0020}she\u{0020}could\u{0020}barely\u{0020}graduate\u{0020}from\u{0020}school.\u{0020}On\u{0020}the\u{0020}one\u{0020}hand,\u{0020}learning\u{0020}ability\u{0020}is\u{0020}the\u{0020}reason,\u{0020}and\u{0020}on\u{0020}the\u{0020}other\u{0020}hand,\u{0020}she\u{0020}misses\u{0020}the\u{0020}exam\u{0020}every\u{0020}time.\n\nIf\u{0020}it\u{0020}weren't\u{0020}for\u{0020}her\u{0020}excellent\u{0020}performance\u{0020}in\u{0020}the\u{0020}simulation\u{0020}battles\u{0020}and\u{0020}the\u{0020}fact\u{0020}that\u{0020}\"Frontier\"\u{0020}is\u{0020}a\u{0020}team\u{0020}that\u{0020}needs\u{0020}to\u{0020}quickly\u{0020}replenish\u{0020}new\u{0020}forces,\u{0020}without\u{0020}such\u{0020}a\u{0020}strong\u{0020}family\u{0020}background\u{0020}to\u{0020}support\u{0020}her\u{0020}like\u{0020}some\u{0020}drivers\u{0020}have,\u{0020}she\u{0020}probably\u{0020}wouldn't\u{0020}have\u{0020}become\u{0020}a\u{0020}driver\u{0020}in\u{0020}her\u{0020}entire\u{0020}life.\n\nFortunately,\u{0020}poor\u{0020}memory\u{0020}doesn't\u{0020}only\u{0020}bring\u{0020}her\u{0020}disadvantages\u{0020}-\u{0020}just\u{0020}as\u{0020}she\u{0020}said,\u{0020}\"Bad\u{0020}things\u{0020}will\u{0020}also\u{0020}be\u{0020}forgotten,\u{0020}and\u{0020}the\u{0020}mood\u{0020}will\u{0020}become\u{0020}cheerful.\"\n\nShe\u{0020}should\u{0020}be\u{0020}a\u{0020}good\u{0020}child\u{0020}who\u{0020}can\u{0020}always\u{0020}face\u{0020}every\u{0020}day\u{0020}in\u{0020}the\u{0020}future\u{0020}with\u{0020}an\u{0020}optimistic\u{0020}mood.", "0", "0", "0", "0", 11042, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614202] = {614202, 500, "\u{0020}\u{0020}Most\u{0020}people\u{0020}remember\u{0020}Kyla\u{0020}as\u{0020}always\u{0020}being\u{0020}out\u{0020}in\u{0020}the\u{0020}sun.\n\nIt's\u{0020}not\u{0020}that\u{0020}she\u{0020}has\u{0020}any\u{0020}special\u{0020}ability\u{0020}to\u{0020}summon\u{0020}sunny\u{0020}days.\u{0020}It's\u{0020}just\u{0020}because\u{0020}she\u{0020}likes\u{0020}the\u{0020}sunlight.\n\nBathing\u{0020}in\u{0020}the\u{0020}warm\u{0020}sunlight,\u{0020}then\u{0020}running\u{0020}involuntarily\u{0020}with\u{0020}both\u{0020}feet,\u{0020}and\u{0020}when\u{0020}she\u{0020}came\u{0020}to\u{0020}her\u{0020}senses,\u{0020}a\u{0020}whole\u{0020}day\u{0020}had\u{0020}passed.\u{0020}This\u{0020}is\u{0020}what\u{0020}Kyla\u{0020}does\u{0020}most\u{0020}often.\n\nOf\u{0020}course,\u{0020}because\u{0020}she\u{0020}misjudged\u{0020}the\u{0020}influence\u{0020}of\u{0020}the\u{0020}sun\u{0020}on\u{0020}the\u{0020}temperature,\u{0020}thus\u{0020}exhausting\u{0020}her\u{0020}physical\u{0020}strength\u{0020}too\u{0020}early,\u{0020}even\u{0020}suffering\u{0020}from\u{0020}heatstroke\u{0020}and\u{0020}fainting,\u{0020}and\u{0020}being\u{0020}sent\u{0020}to\u{0020}the\u{0020}school\u{0020}infirmary,\u{0020}such\u{0020}things\u{0020}have\u{0020}happened\u{0020}quite\u{0020}often.\n\nAfter\u{0020}all,\u{0020}she\u{0020}is\u{0020}just\u{0020}an\u{0020}optimistic\u{0020}and\u{0020}sporty\u{0020}person\u{0020}with\u{0020}a\u{0020}poor\u{0020}memory,\u{0020}not\u{0020}a\u{0020}superman\u{0020}with\u{0020}unlimited\u{0020}energy\u{0020}just\u{0020}because\u{0020}of\u{0020}the\u{0020}sun.\n\nAlthough\u{0020}there\u{0020}won't\u{0020}be\u{0020}unlimited\u{0020}energy\u{0020}even\u{0020}with\u{0020}the\u{0020}sun,\u{0020}without\u{0020}it,\u{0020}she\u{0020}would\u{0020}indeed\u{0020}be\u{0020}like\u{0020}a\u{0020}robot\u{0020}with\u{0020}insufficient\u{0020}power.\n\nFew\u{0020}people\u{0020}see\u{0020}Kyla\u{0020}on\u{0020}rainy\u{0020}days\u{0020}because\u{0020}at\u{0020}this\u{0020}time\u{0020}she\u{0020}usually\u{0020}rests\u{0020}in\u{0020}her\u{0020}room.\n\nThe\u{0020}rest\u{0020}for\u{0020}killing\u{0020}time\u{0020}-\u{0020}doing\u{0020}nothing.\u{0020}Maybe\u{0020}on\u{0020}sunny\u{0020}days\u{0020}when\u{0020}she\u{0020}doesn't\u{0020}choose\u{0020}to\u{0020}go\u{0020}out,\u{0020}she\u{0020}might\u{0020}play\u{0020}some\u{0020}nerve-stimulating\u{0020}video\u{0020}games\u{0020}in\u{0020}her\u{0020}room.\u{0020}But\u{0020}once\u{0020}it\u{0020}rains,\u{0020}she\u{0020}will\u{0020}only\u{0020}daze\u{0020}or\u{0020}sleep\u{0020}in\u{0020}her\u{0020}room,\u{0020}ending\u{0020}this\u{0020}rainy\u{0020}day\u{0020}in\u{0020}the\u{0020}fastest\u{0020}way.\n\nThis\u{0020}aversion\u{0020}to\u{0020}rainy\u{0020}days,\u{0020}traced\u{0020}back,\u{0020}can\u{0020}only\u{0020}stem\u{0020}from\u{0020}her\u{0020}childhood.\n\nIt\u{0020}is\u{0020}not\u{0020}something\u{0020}worth\u{0020}mentioning.\u{0020}Talking\u{0020}about\u{0020}it\u{0020}will\u{0020}only\u{0020}make\u{0020}people\u{0020}feel\u{0020}bored.\n\nRain,\u{0020}Sin,\u{0020}Disaster.\n\nHer\u{0020}life\u{0020}is\u{0020}happier\u{0020}compared\u{0020}to\u{0020}other\u{0020}drivers.\u{0020}At\u{0020}least\u{0020}she\u{0020}has\u{0020}never\u{0020}experienced\u{0020}the\u{0020}pain\u{0020}of\u{0020}losing\u{0020}family\u{0020}members.\n\nBut\u{0020}that\u{0020}disaster\u{0020}that\u{0020}occurred\u{0020}on\u{0020}a\u{0020}rainy\u{0020}day\u{0020}probably\u{0020}left\u{0020}an\u{0020}indelible\u{0020}psychological\u{0020}shadow\u{0020}in\u{0020}her\u{0020}heart.\u{0020}Maybe\u{0020}she\u{0020}has\u{0020}forgotten\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}things,\u{0020}but\u{0020}that\u{0020}mood\u{0020}remained.\n\nShe\u{0020}will\u{0020}forget\u{0020}many\u{0020}things,\u{0020}but\u{0020}will\u{0020}never\u{0020}forget\u{0020}her\u{0020}sad\u{0020}mood.\n\nTo\u{0020}drive\u{0020}away\u{0020}the\u{0020}rainy\u{0020}days\u{0020}in\u{0020}her\u{0020}heart,\u{0020}Kyla\u{0020}will\u{0020}have\u{0020}a\u{0020}seesaw\u{0020}battle\u{0020}with\u{0020}Sin,\u{0020}with\u{0020}the\u{0020}survival\u{0020}of\u{0020}both\u{0020}races\u{0020}as\u{0020}the\u{0020}spoils,\u{0020}lasting\u{0020}throughout\u{0020}the\u{0020}entire\u{0020}life\u{0020}cycle.", "0", "0", "0", "0", 11042, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614203] = {614203, 1000, "\u{0020}\u{0020}Kyla's\u{0020}enlightenment\u{0020}is\u{0020}a\u{0020}little\u{0020}strange.\n\nAlthough\u{0020}she\u{0020}was\u{0020}not\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}realized\u{0020}at\u{0020}graduation\u{0020}that\u{0020}the\u{0020}war\u{0020}against\u{0020}Sin\u{0020}was\u{0020}an\u{0020}extermination\u{0020}war\u{0020}that\u{0020}would\u{0020}not\u{0020}cease\u{0020}until\u{0020}the\u{0020}opponent\u{0020}was\u{0020}completely\u{0020}eradicated,\u{0020}among\u{0020}the\u{0020}active\u{0020}navigators\u{0020}of\u{0020}AEGIS,\u{0020}those\u{0020}like\u{0020}her\u{0020}-\u{0020}who\u{0020}could\u{0020}have\u{0020}this\u{0020}awareness\u{0020}without\u{0020}ever\u{0020}experiencing\u{0020}the\u{0020}pain\u{0020}of\u{0020}loss\u{0020}-\u{0020}were\u{0020}in\u{0020}the\u{0020}minority.\n\nNot\u{0020}for\u{0020}the\u{0020}dream,\u{0020}not\u{0020}for\u{0020}saving\u{0020}the\u{0020}weak,\u{0020}not\u{0020}for\u{0020}making\u{0020}everyone\u{0020}happy,\u{0020}and\u{0020}even\u{0020}less\u{0020}for\u{0020}solving\u{0020}one's\u{0020}own\u{0020}troubles\u{0020}or\u{0020}seeking\u{0020}personal\u{0020}gain.\n\nJust\u{0020}by\u{0020}realizing\u{0020}\"This\u{0020}is\u{0020}a\u{0020}long-lasting\u{0020}war\u{0020}that\u{0020}determines\u{0020}whether\u{0020}it\u{0020}is\u{0020}humans\u{0020}or\u{0020}Sin\u{0020}that\u{0020}can\u{0020}survive\",\u{0020}she\u{0020}rushed\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}without\u{0020}hesitation.\n\nVery\u{0020}incredible.\n\nPerhaps\u{0020}there\u{0020}are\u{0020}really\u{0020}people\u{0020}in\u{0020}the\u{0020}world\u{0020}who\u{0020}are\u{0020}born\u{0020}suitable\u{0020}to\u{0020}be\u{0020}a\u{0020}warrior?", "0", "0", "0", "0", 11042, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614204] = {614204, 2000, "\u{0020}\u{0020}The\u{0020}morning\u{0020}sun\u{0020}is\u{0020}so\u{0020}dazzling.\n\nThat\u{0020}dazzling\u{0020}light\u{0020}has\u{0020}remained\u{0020}in\u{0020}the\u{0020}heart\u{0020}since\u{0020}the\u{0020}gaze.\n\nTherefore,\u{0020}when\u{0020}in\u{0020}darkness,\u{0020}closing\u{0020}eyes\u{0020}recalls\u{0020}the\u{0020}beauty\u{0020}of\u{0020}that\u{0020}light.\n\nJust\u{0020}by\u{0020}remembering\u{0020}the\u{0020}beauty\u{0020}of\u{0020}the\u{0020}sun,\u{0020}she\u{0020}could\u{0020}fight\u{0020}endlessly.\n\n\"Navigator,\u{0020}we\u{0020}will\u{0020}win,\u{0020}right?\"\n\nOn\u{0020}this\u{0020}vast\u{0020}battlefield\u{0020}where\u{0020}perhaps\u{0020}countless\u{0020}people\u{0020}have\u{0020}placed\u{0020}their\u{0020}bets,\u{0020}she\u{0020}might\u{0020}be\u{0020}unable\u{0020}to\u{0020}change\u{0020}anything.\n\nBut\u{0020}she\u{0020}wants\u{0020}to\u{0020}convey\u{0020}this\u{0020}unwavering\u{0020}fighting\u{0020}spirit\u{0020}to\u{0020}that\u{0020}synesthete.\n\nTo\u{0020}tell\u{0020}him\u{0020}not\u{0020}to\u{0020}give\u{0020}up.\u{0020}To\u{0020}tell\u{0020}him\u{0020}that\u{0020}the\u{0020}most\u{0020}beautiful\u{0020}sunshine\u{0020}always\u{0020}appears\u{0020}after\u{0020}the\u{0020}thickest\u{0020}dark\u{0020}clouds.\n\nThis\u{0020}is\u{0020}what\u{0020}Kyla\u{0020}can\u{0020}do.", "0", "0", "0", "0", 11042, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
