[614303] = {614303, 1000, "\u{0020}\u{0020}Due\u{0020}to\u{0020}her\u{0020}church\u{0020}duties,\u{0020}Mira\u{0020}is\u{0020}rarely\u{0020}seen\u{0020}at\u{0020}the\u{0020}AEGIS\u{0020}base.\u{0020}Most\u{0020}administrative\u{0020}work\u{0020}is\u{0020}handled\u{0020}by\u{0020}the\u{0020}priests\u{0020}of\u{0020}the\u{0020}Revelation\u{0020}Spring,\u{0020}while\u{0020}the\u{0020}simpler\u{0020}tasks\u{0020}are\u{0020}left\u{0020}to\u{0020}the\u{0020}two\u{0020}knights\u{0020}in\u{0020}her\u{0020}squad.\n\n\u{0020}\u{0020}However,\u{0020}Mira's\u{0020}role\u{0020}within\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}is\u{0020}no\u{0020}secret.\u{0020}As\u{0020}the\u{0020}bishop\u{0020}of\u{0020}the\u{0020}Danube\u{0020}diocese,\u{0020}she's\u{0020}interacted\u{0020}with\u{0020}everyone\u{0020}from\u{0020}nobles\u{0020}to\u{0020}commoners.\u{0020}Interestingly,\u{0020}one\u{0020}might\u{0020}notice\u{0020}that\u{0020}the\u{0020}money\u{0020}donated\u{0020}by\u{0020}the\u{0020}nobles\u{0020}to\u{0020}the\u{0020}church\u{0020}is\u{0020}often\u{0020}redirected\u{0020}by\u{0020}Mira\u{0020}toward\u{0020}charitable\u{0020}efforts\u{0020}that\u{0020}benefit\u{0020}the\u{0020}less\u{0020}fortunate.", "0", "0", "0", "0", 11043, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614304] = {614304, 2000, "\u{0020}\u{0020}We\u{0020}surrender\u{0020}our\u{0020}words\u{0020}to\u{0020}the\u{0020}holy\u{0020}music,\u{0020}we\u{0020}surrender\u{0020}our\u{0020}bodies\u{0020}to\u{0020}the\u{0020}dance.\n\n\u{0020}\n\n\u{0020}We\u{0020}surrender\u{0020}our\u{0020}desires\u{0020}to\u{0020}faith,\u{0020}we\u{0020}surrender\u{0020}our\u{0020}pain\u{0020}to\u{0020}the\u{0020}fight.\n\n\u{0020}\u{0020}O\u{0020}navigator\u{0020}of\u{0020}Danube,\u{0020}bow\u{0020}your\u{0020}head\u{0020}to\u{0020}my\u{0020}chest,\n\n\u{0020}\u{0020}Can\u{0020}you\u{0020}hear\u{0020}the\u{0020}pulse,\u{0020}the\u{0020}river\u{0020}of\u{0020}life\u{0020}within\u{0020}me,\u{0020}the\u{0020}drum\u{0020}of\u{0020}my\u{0020}heart?\n\n\u{0020}\u{0020}Each\u{0020}of\u{0020}us\u{0020}is\u{0020}a\u{0020}timeless\u{0020}instrument,\u{0020}each\u{0020}creating\u{0020}our\u{0020}own\u{0020}melody.\n\n\u{0020}\u{0020}Let\u{0020}us\u{0020}wait\u{0020}as\u{0020}the\u{0020}streams\u{0020}converge,\n\n\u{0020}\u{0020}Until\u{0020}you\u{0020}and\u{0020}I\u{0020}unite\u{0020}in\u{0020}symphony.", "0", "0", "0", "0", 11043, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
