[614401] = {614401, 100, "\u{3000}\u{3000}Heine,\u{0020}the\u{0020}driver\u{0020}of\u{0020}the\u{0020}Architect\u{0020}Team,\u{0020}is\u{0020}employed\u{0020}at\u{0020}the\u{0020}Poynred\u{0020}AVG\u{0020}Institute.\u{0020}She\u{0020}was\u{0020}suspected\u{0020}of\u{0020}violating\u{0020}multiple\u{0020}laws\u{0020}and\u{0020}regulations\u{0020}in\u{0020}the\u{0020}****\u{0020}invasion\u{0020}incident.\u{0020}According\u{0020}to\u{0020}the\u{0020}usual\u{0020}process,\u{0020}she\u{0020}should\u{0020}have\u{0020}been\u{0020}assigned\u{0020}to\u{0020}the\u{0020}Prisoner\u{0020}Team.\u{0020}However,\u{0020}after\u{0020}the\u{0020}judge's\u{0020}discretionary\u{0020}consideration\u{0020}and\u{0020}the\u{0020}insistence\u{0020}of\u{0020}the\u{0020}leader,\u{0020}who\u{0020}was\u{0020}a\u{0020}party\u{0020}involved\u{0020}in\u{0020}the\u{0020}relevant\u{0020}incident,\u{0020}AEGIS\u{0020}finally\u{0020}decided\u{0020}to\u{0020}mitigate\u{0020}her\u{0020}crime,\u{0020}restore\u{0020}her\u{0020}researcher\u{0020}status,\u{0020}and\u{0020}arrange\u{0020}her\u{0020}to\u{0020}the\u{0020}Architect\u{0020}Team.\u{0020}\n\u{3000}\u{3000}Because\u{0020}the\u{0020}situation\u{0020}of\u{0020}Heine\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}was\u{0020}rather\u{0020}special,\u{0020}health\u{0020}checks,\u{0020}psychological\u{0020}consultations\u{0020}and\u{0020}various\u{0020}training\u{0020}and\u{0020}assessment\u{0020}requirements\u{0020}for\u{0020}her\u{0020}were\u{0020}implemented\u{0020}one\u{0020}after\u{0020}another\u{0020}in\u{0020}a\u{0020}short\u{0020}period.\u{0020}After\u{0020}the\u{0020}above\u{0020}series\u{0020}of\u{0020}processes\u{0020}ended,\u{0020}based\u{0020}on\u{0020}data\u{0020}analysis\u{0020}and\u{0020}judgment,\u{0020}Heine's\u{0020}ability\u{0020}and\u{0020}qualifications\u{0020}did\u{0020}not\u{0020}meet\u{0020}the\u{0020}requirements\u{0020}of\u{0020}an\u{0020}attack-type\u{0020}driver.\u{0020}With\u{0020}her\u{0020}physical\u{0020}ability\u{0020}and\u{0020}combat\u{0020}skills,\u{0020}perhaps\u{0020}it\u{0020}would\u{0020}be\u{0020}a\u{0020}more\u{0020}correct\u{0020}choice\u{0020}to\u{0020}transfer\u{0020}her\u{0020}to\u{0020}a\u{0020}support-type\u{0020}driver.\u{0020}However,\u{0020}considering\u{0020}her\u{0020}own\u{0020}will\u{0020}and\u{0020}the\u{0020}fact\u{0020}that\u{0020}she\u{0020}has\u{0020}not\u{0020}been\u{0020}a\u{0020}driver\u{0020}for\u{0020}long,\u{0020}ther\u{0020}adjustment\u{0020}still\u{0020}needs\u{0020}further\u{0020}consideration.", "0", "0", "0", "0", 11044, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614402] = {614402, 500, "\u{3000}\u{3000}Unbeknownst\u{0020}to\u{0020}many\u{0020}of\u{0020}her\u{0020}colleagues\u{0020}at\u{0020}the\u{0020}institute,\u{0020}Heine,\u{0020}who\u{0020}was\u{0020}born\u{0020}in\u{0020}Poynred\u{0020}West\u{0020}and\u{0020}was\u{0020}a\u{0020}child\u{0020}of\u{0020}the\u{0020}Holy\u{0020}Church,\u{0020}kept\u{0020}her\u{0020}past\u{0020}a\u{0020}secret\u{0020}but\u{0020}did\u{0020}not\u{0020}lie.\u{0020}She\u{0020}simply\u{0020}kept\u{0020}quiet\u{0020}when\u{0020}asked,\u{0020}giving\u{0020}the\u{0020}impression\u{0020}of\u{0020}a\u{0020}socially\u{0020}awkward\u{0020}teenage\u{0020}girl.\u{0020}\n\u{3000}\u{3000}What\u{0020}is\u{0020}even\u{0020}more\u{0020}unbelievable\u{0020}to\u{0020}many\u{0020}outside\u{0020}the\u{0020}institute\u{0020}is\u{0020}that\u{0020}Heine\u{0020}designed\u{0020}and\u{0020}manufactured\u{0020}****\u{0020}alone.\u{0020}That\u{0020}was\u{0020}obviously\u{0020}impossible\u{0020}to\u{0020}achieve\u{0020}with\u{0020}the\u{0020}meager\u{0020}salary\u{0020}of\u{0020}an\u{0020}AVG\u{0020}researcher\u{0020}at\u{0020}the\u{0020}middle-class\u{0020}level.\u{0020}After\u{0020}all,\u{0020}in\u{0020}fact,\u{0020}Heine\u{0020}earned\u{0020}enough\u{0020}funds\u{0020}from\u{0020}the\u{0020}wealthy\u{0020}in\u{0020}the\u{0020}east\u{0020}district\u{0020}by\u{0020}anonymously\u{0020}selling\u{0020}her\u{0020}paintings.\u{0020}\n\u{3000}\u{3000}Why\u{0020}would\u{0020}rich\u{0020}people\u{0020}who\u{0020}have\u{0020}no\u{0020}aesthetic\u{0020}vision\u{0020}and\u{0020}only\u{0020}know\u{0020}that\u{0020}the\u{0020}works\u{0020}of\u{0020}famous\u{0020}painters\u{0020}are\u{0020}collected\u{0020}as\u{0020}gold-plated\u{0020}business\u{0020}cards\u{0020}buy\u{0020}such\u{0020}obscure\u{0020}paintings\u{0020}at\u{0020}high\u{0020}prices?\u{0020}Even\u{0020}Heine\u{0020}herself\u{0020}was\u{0020}a\u{0020}little\u{0020}surprised.\u{0020}In\u{0020}fact,\u{0020}it\u{0020}was\u{0020}the\u{0020}mysterious\u{0020}nature\u{0020}of\u{0020}her\u{0020}anonymity\u{0020}that\u{0020}led\u{0020}many\u{0020}insiders\u{0020}to\u{0020}start\u{0020}analyzing,\u{0020}guessing\u{0020}which\u{0020}painter's\u{0020}experimental\u{0020}work\u{0020}or\u{0020}which\u{0020}artist\u{0020}was\u{0020}using\u{0020}a\u{0020}second\u{0020}identity\u{0020}for\u{0020}performance\u{0020}art.\u{0020}The\u{0020}ensuing\u{0020}discussions\u{0020}brought\u{0020}heat\u{0020}to\u{0020}the\u{0020}analysts\u{0020}themselves,\u{0020}and\u{0020}gradually\u{0020}hyped\u{0020}Heine's\u{0020}works\u{0020}to\u{0020}sky-high\u{0020}prices.\u{0020}The\u{0020}wealthy\u{0020}are\u{0020}beginning\u{0020}to\u{0020}take\u{0020}a\u{0020}keen\u{0020}interest\u{0020}in\u{0020}the\u{0020}anonymous\u{0020}artist's\u{0020}work,\u{0020}not\u{0020}because\u{0020}they\u{0020}appreciate\u{0020}the\u{0020}paintings\u{0020}themselves,\u{0020}but\u{0020}because\u{0020}they\u{0020}hope\u{0020}that\u{0020}when\u{0020}the\u{0020}author\u{0020}shows\u{0020}up,\u{0020}the\u{0020}value\u{0020}of\u{0020}her\u{0020}works\u{0020}will\u{0020}rise\u{0020}again\u{0020}or\u{0020}become\u{0020}worthless\u{0020}-\u{0020}in\u{0020}other\u{0020}words,\u{0020}that\u{0020}is\u{0020}just\u{0020}an\u{0020}exciting\u{0020}high-stakes\u{0020}game.\u{0020}\n\u{3000}\u{3000}Although\u{0020}Heine\u{0020}earned\u{0020}enough\u{0020}money\u{0020}through\u{0020}the\u{0020}market\u{0020}to\u{0020}achieve\u{0020}her\u{0020}goals,\u{0020}she\u{0020}became\u{0020}even\u{0020}more\u{0020}resentful\u{0020}of\u{0020}ther\u{0020}vulgar\u{0020}social\u{0020}atmosphere\u{0020}that\u{0020}lingered.\u{0020}So,\u{0020}except\u{0020}for\u{0020}the\u{0020}necessary\u{0020}funds,\u{0020}she\u{0020}donated\u{0020}all\u{0020}the\u{0020}profits\u{0020}she\u{0020}earned\u{0020}to\u{0020}welfare\u{0020}institutions\u{0020}and\u{0020}suddenly\u{0020}stopped\u{0020}selling\u{0020}paintings\u{0020}one\u{0020}day.\u{0020}Those\u{0020}donation\u{0020}certificates\u{0020}of\u{0020}Heine\u{0020}undoubtedly\u{0020}had\u{0020}a\u{0020}positive\u{0020}effect\u{0020}on\u{0020}the\u{0020}verdict\u{0020}in\u{0020}the\u{0020}military\u{0020}court.", "0", "0", "0", "0", 11044, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614403] = {614403, 1000, "\u{3000}\u{3000}For\u{0020}stability\u{0020}considerations,\u{0020}the\u{0020}specific\u{0020}circumstances\u{0020}of\u{0020}Heine\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}were\u{0020}classified\u{0020}as\u{0020}confidential\u{0020}matters.\u{0020}Therefore,\u{0020}for\u{0020}those\u{0020}ordinary\u{0020}drivers,\u{0020}Heine,\u{0020}whom\u{0020}no\u{0020}one\u{0020}had\u{0020}seen\u{0020}during\u{0020}the\u{0020}Azure\u{0020}Academy\u{0020}period,\u{0020}was\u{0020}just\u{0020}like\u{0020}a\u{0020}\"mysterious\u{0020}transfer\u{0020}student\".\u{0020}She\u{0020}suddenly\u{0020}became\u{0020}a\u{0020}hot\u{0020}topic\u{0020}among\u{0020}the\u{0020}crowd.\u{0020}Those\u{0020}gossipy\u{0020}drivers\u{0020}kept\u{0020}asking\u{0020}questions\u{0020}about\u{0020}it,\u{0020}while\u{0020}Heine\u{0020}still\u{0020}maintained\u{0020}the\u{0020}habit\u{0020}she\u{0020}had\u{0020}developed\u{0020}in\u{0020}the\u{0020}research\u{0020}institute\u{0020}-\u{0020}being\u{0020}taciturn.\u{0020}Ther\u{0020}taciturnity\u{0020}naturally\u{0020}gave\u{0020}rise\u{0020}to\u{0020}stronger\u{0020}curiosity,\u{0020}making\u{0020}Heine\u{0020}increasingly\u{0020}nervous,\u{0020}fearing\u{0020}that\u{0020}her\u{0020}secret\u{0020}would\u{0020}be\u{0020}investigated\u{0020}by\u{0020}some\u{0020}busybody.", "0", "0", "0", "0", 11044, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614404] = {614404, 2000, "\u{3000}\u{3000}Sketching\u{0020}the\u{0020}lines\u{0020}carefully,\u{0020}\n\u{3000}\u{3000}Depict\u{0020}the\u{0020}unforgettable\u{0020}outline.\u{0020}\n\u{3000}\u{3000}The\u{0020}figure\u{0020}that\u{0020}intruded\u{0020}into\u{0020}the\u{0020}heart\u{0020}without\u{0020}permission.\u{0020}\n\u{3000}\u{3000}Which\u{0020}kind\u{0020}of\u{0020}pigment\u{0020}should\u{0020}be\u{0020}used\u{0020}for\u{0020}coloring?\u{0020}\n\u{3000}\u{3000}Red\u{0020}as\u{0020}warm\u{0020}as\u{0020}a\u{0020}campfire,\u{0020}blue\u{0020}as\u{0020}quiet\u{0020}as\u{0020}the\u{0020}sea,\u{0020}\n\u{3000}\u{3000}None\u{0020}of\u{0020}them\u{0020}can\u{0020}replace\u{0020}her\u{0020}color.\u{0020}\n\u{3000}\u{3000}What\u{0020}on\u{0020}earth\u{0020}should\u{0020}be\u{0020}your\u{0020}impression\u{0020}color?\u{0020}\n\u{3000}\u{3000}Although\u{0020}it\u{0020}is\u{0020}an\u{0020}unfinished\u{0020}work,\u{0020}\n\u{3000}\u{3000}But\u{0020}couldn't\u{0020}wait\u{0020}to\u{0020}share\u{0020}it\u{0020}with\u{0020}her.\u{0020}\n\u{3000}\u{3000}Ther\u{0020}is\u{0020}not\u{0020}a\u{0020}scenery\u{0020}exclusively\u{0020}belonging\u{0020}to\u{0020}oneself.\u{0020}\n\u{3000}\u{3000}But\u{0020}it\u{0020}is\u{0020}the\u{0020}common\u{0020}memory\u{0020}of\u{0020}two\u{0020}people.", "0", "0", "0", "0", 11044, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
