[614501] = {614501, 100, "\u{3000}\u{3000}[Data\u{0020}retrieved\u{0020}from:\u{0020}Daybreak\u{0020}Charity\u{0020}Association\u{0020}Database]\n\u{3000}\u{3000}Group:\u{0020}B\n\u{3000}\u{3000}ID:\u{0020}17\n\u{3000}\u{3000}Registration\u{0020}Date:\u{0020}**25.1*\n\u{3000}\u{3000}Biological\u{0020}Age:\u{0020}2\u{0020}years\u{0020}old\n\u{3000}\u{3000}Social\u{0020}Background:\u{0020}One\u{0020}of\u{0020}the\u{0020}victims\u{0020}of\u{0020}the\u{0020}****\u{0020}incident.\u{0020}Origins\u{0020}unknown.\u{0020}Taken\u{0020}in\u{0020}by\u{0020}the\u{0020}Daybreak.\n\u{3000}\u{3000}\u{0020}Related\u{0020}Projects:\u{0020}B-*51,\u{0020}B-S31,\u{0020}*-D*7\n\u{3000}\u{3000}Evaluation\u{0020}(Updated\u{0020}**30.01.1*):\n\u{3000}\u{3000}Unable\u{0020}to\u{0020}communicate.\u{0020}Currently\u{0020}responds\u{0020}only\u{0020}to\u{0020}physical\u{0020}impact.\u{0020}Counterattacks\u{0020}in\u{0020}proportion\u{0020}to\u{0020}the\u{0020}force\u{0020}of\u{0020}the\u{0020}hit.\n\u{3000}\u{3000}Perceives\u{0020}touch\u{0020}as\u{0020}a\u{0020}form\u{0020}of\u{0020}violence.\n\u{3000}\u{3000}Brainwave\u{0020}frequency\u{0020}remains\u{0020}below\u{0020}8\u{0020}Hz\u{0020}during\u{0020}normal\u{0020}conditions,\u{0020}but\u{0020}spikes\u{0020}above\u{0020}50\u{0020}Hz\u{0020}when\u{0020}retaliating,\u{0020}then\u{0020}***\u{0020}drops\u{0020}to\u{0020}the\u{0020}**未-band\u{0020}once\u{0020}the\u{0020}source\u{0020}of\u{0020}violence\u{0020}is\u{0020}neutralized.\n\u{3000}\u{3000}...(Data\u{0020}corrupted\u{0020}beyond\u{0020}recognition.)\n\u{3000}\u{3000}\u{0020}Deemed\u{0020}a\u{0020}failed\u{0020}***,\u{0020}l**ed\u{0020}for\u{0020}disposal.\n\u{3000}\u{3000}\u{0020}\"Verir\u{0020}suffers\u{0020}from\u{0020}severe\u{0020}psychological\u{0020}disorders.\u{0020}For\u{0020}daily\u{0020}transport,\u{0020}it's\u{0020}recommended\u{0020}she\u{0020}be\u{0020}wrapped\u{0020}in\u{0020}blankets,\u{0020}placed\u{0020}inside\u{0020}a\u{0020}padded\u{0020}crate,\u{0020}and\u{0020}shipped\u{0020}via\u{0020}logistics\u{0020}freight.\u{0020}Absolutely,\u{0020}under\u{0020}no\u{0020}circumstances,\u{0020}should\u{0020}anyone\u{0020}make\u{0020}physical\u{0020}contact\u{0020}with\u{0020}her.\"\n\u{3000}\u{3000}\u{0020}Note\u{0020}appended\u{0020}to\u{0020}an\u{0020}old\u{0020}document\u{0020}from\u{0020}the\u{0020}Daybreak\u{0020}Charity\u{0020}Association\u{0020}archives.", "0", "0", "0", "0", 11045, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614502] = {614502, 500, "\u{3000}\u{3000}[Additional\u{0020}Information\u{0020}from:\u{0020}Inca\u{0020}Branch,\u{0020}Investigation\u{0020}Department]\n\u{3000}\u{3000}Investigation\u{0020}confirms\u{0020}she\u{0020}is\u{0020}from\u{0020}the\u{0020}Danube.\u{0020}At\u{0020}age\u{0020}two,\u{0020}while\u{0020}shopping\u{0020}with\u{0020}her\u{0020}parents,\u{0020}she\u{0020}was\u{0020}abducted\u{0020}by\u{0020}human\u{0020}traffickers\u{0020}and\u{0020}taken\u{0020}to\u{0020}the\u{0020}Inca\u{0020}border.\u{0020}Before\u{0020}the\u{0020}buyer\u{0020}was\u{0020}found,\u{0020}local\u{0020}police\u{0020}intervened\u{0020}and\u{0020}rescued\u{0020}her,\u{0020}later\u{0020}sending\u{0020}her\u{0020}to\u{0020}a\u{0020}well-known\u{0020}charity\u{0020}institution\u{0020}under\u{0020}the\u{0020}management\u{0020}of\u{0020}the\u{0020}Daybreak\u{0020}Charity\u{0020}Association.\n\u{3000}\u{3000}\u{0020}[B17]'s\u{0020}biological\u{0020}parents\u{0020}and\u{0020}relatives\u{0020}all\u{0020}went\u{0020}missing\u{0020}seven\u{0020}years\u{0020}ago\u{0020}during\u{0020}the\u{0020}large-scale\u{0020}Sin\u{0020}invasion\u{0020}and\u{0020}remain\u{0020}unaccounted\u{0020}for.\u{0020}By\u{0020}law,\u{0020}they\u{0020}were\u{0020}declared\u{0020}deceased\u{0020}five\u{0020}years\u{0020}ago.\u{0020}Since\u{0020}no\u{0020}heirs\u{0020}were\u{0020}found,\u{0020}all\u{0020}assets\u{0020}were\u{0020}given\u{0020}to\u{0020}the\u{0020}AEGIS\u{0020}Danube\u{0020}Branch.\n\u{3000}\u{3000}\u{0020}From\u{0020}the\u{0020}few\u{0020}disaster-surviving\u{0020}documents\u{0020}submitted\u{0020}after\u{0020}the\u{0020}event,\u{0020}it\u{0020}can\u{0020}be\u{0020}inferred\u{0020}that\u{0020}[B17]\u{0020}was\u{0020}involved\u{0020}in\u{0020}an\u{0020}**\u{0020}experimental\u{0020}project\u{0020}related\u{0020}to\u{0020}**.\u{0020}As\u{0020}one\u{0020}of\u{0020}the\u{0020}project's\u{0020}***,\u{0020}[B17]\u{0020}had\u{0020}already\u{0020}received\u{0020}a\u{0020}***\u{0020}notice.\u{0020}However,\u{0020}before\u{0020}the\u{0020}order\u{0020}could\u{0020}be\u{0020}carried\u{0020}out,\u{0020}or\u{0020}to\u{0020}put\u{0020}it\u{0020}accurately,\u{0020}seven\u{0020}years\u{0020}ago,\u{0020}a\u{0020}massive\u{0020}Sin\u{0020}invasion\u{0020}struck\u{0020}cities,\u{0020}forcing\u{0020}the\u{0020}project\u{0020}to\u{0020}shut\u{0020}down.\u{0020}As\u{0020}a\u{0020}result,\u{0020}all\u{0020}***\u{0020}related\u{0020}to\u{0020}her\u{0020}were\u{0020}indefinitely\u{0020}delayed.\n\u{3000}\u{3000}\u{0020}As\u{0020}one\u{0020}of\u{0020}the\u{0020}first\u{0020}****\u{0020}arranged\u{0020}by\u{0020}the\u{0020}Daybreak\u{0020}Charity\u{0020}Association,\u{0020}[B17]\u{0020}ranked\u{0020}among\u{0020}the\u{0020}highest\u{0020}in\u{0020}compatibility\u{0020}rate\u{0020}tests.\u{0020}Still,\u{0020}given\u{0020}her\u{0020}condition,\u{0020}testers\u{0020}believed\u{0020}that\u{0020}even\u{0020}if\u{0020}she\u{0020}were\u{0020}gigantified,\u{0020}she\u{0020}would\u{0020}exhibit\u{0020}no\u{0020}consciousness\u{0020}beyond\u{0020}blank\u{0020}staring\u{0020}and\u{0020}retaliation.\u{0020}Thus,\u{0020}she\u{0020}was\u{0020}excluded\u{0020}from\u{0020}the\u{0020}first\u{0020}round.\n\u{3000}\u{3000}\u{0020}But\u{0020}since\u{0020}only\u{0020}one\u{0020}candidate\u{0020}passed\u{0020}the\u{0020}initial\u{0020}combat\u{0020}test,\u{0020}a\u{0020}second\u{0020}round\u{0020}was\u{0020}held\u{0020}after\u{0020}thorough\u{0020}discussion,\u{0020}including\u{0020}the\u{0020}previously\u{0020}rejected\u{0020}individuals\u{0020}like\u{0020}[B17].\n\u{3000}\u{3000}\u{0020}During\u{0020}those\u{0020}trials,\u{0020}many\u{0020}children\u{0020}who\u{0020}were\u{0020}usually\u{0020}communicative\u{0020}became\u{0020}mentally\u{0020}unstable\u{0020}or\u{0020}unresponsive\u{0020}after\u{0020}gigantification,\u{0020}whereas\u{0020}[B17]'s\u{0020}performance\u{0020}exceeded\u{0020}expectations.\u{0020}Her\u{0020}brainwave\u{0020}frequency\u{0020}stabilized\u{0020}around\u{0020}8\u{0020}Hz,\u{0020}which\u{0020}was\u{0020}likely\u{0020}a\u{0020}repair\u{0020}effect\u{0020}from\u{0020}Nimbus.\u{0020}Her\u{0020}cognitive\u{0020}ability\u{0020}also\u{0020}matched\u{0020}her\u{0020}physical\u{0020}age,\u{0020}contrary\u{0020}to\u{0020}earlier\u{0020}assessments.\n\u{3000}\u{3000}\u{0020}Hence,\u{0020}after\u{0020}[D34],\u{0020}the\u{0020}Daybreak\u{0020}Squad\u{0020}confirmed\u{0020}its\u{0020}second\u{0020}member.\n\u{3000}\u{3000}\u{0020}Due\u{0020}to\u{0020}long-term\u{0020}isolation\u{0020}and\u{0020}lack\u{0020}of\u{0020}social\u{0020}interaction,\u{0020}her\u{0020}response\u{0020}to\u{0020}commands\u{0020}was\u{0020}delayed\u{0020}and\u{0020}her\u{0020}speech\u{0020}peculiar,\u{0020}issues\u{0020}later\u{0020}corrected\u{0020}through\u{0020}short-term\u{0020}training.\u{0020}However,\u{0020}once\u{0020}she\u{0020}reverted\u{0020}from\u{0020}gigantified\u{0020}form,\u{0020}she\u{0020}would\u{0020}return\u{0020}to\u{0020}a\u{0020}near-vegetative\u{0020}state,\u{0020}unable\u{0020}to\u{0020}engage\u{0020}in\u{0020}any\u{0020}meaningful\u{0020}communication.\u{0020}Even\u{0020}the\u{0020}institute's\u{0020}psychologists\u{0020}found\u{0020}no\u{0020}solution.\n\u{3000}\u{3000}\u{0020}The\u{0020}name\u{0020}Verir\u{0020}was\u{0020}assigned\u{0020}to\u{0020}her\u{0020}after\u{0020}she\u{0020}was\u{0020}classified\u{0020}as\u{0020}a\u{0020}failed\u{0020}product.\u{0020}She\u{0020}grew\u{0020}used\u{0020}to\u{0020}it,\u{0020}so\u{0020}the\u{0020}alias\u{0020}was\u{0020}retained\u{0020}in\u{0020}her\u{0020}Driver\u{0020}profile\u{0020}and\u{0020}research\u{0020}files.", "0", "0", "0", "0", 11045, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614503] = {614503, 1000, "\u{3000}\u{3000}To\u{0020}the\u{0020}Navigator:\n\u{3000}\u{3000}Apologies\u{0020}for\u{0020}the\u{0020}repeated\u{0020}trouble.\n\u{3000}\u{3000}\u{0020}Regarding\u{0020}the\u{0020}Verir\u{0020}misdelivery\u{0020}to\u{0020}the\u{0020}Danube\u{0020}branch,\u{0020}the\u{0020}research\u{0020}institute\u{0020}has\u{0020}coordinated\u{0020}with\u{0020}the\u{0020}Inca\u{0020}Branch\u{0020}to\u{0020}investigate\u{0020}and\u{0020}has\u{0020}confirmed\u{0020}that\u{0020}the\u{0020}responsibility\u{0020}lies\u{0020}with\u{0020}the\u{0020}third-party\u{0020}logistics\u{0020}contractor.\u{0020}Once\u{0020}legal\u{0020}negotiations\u{0020}conclude,\u{0020}full\u{0020}compensation\u{0020}will\u{0020}be\u{0020}transferred\u{0020}to\u{0020}the\u{0020}Danube\u{0020}branch.\u{0020}Meanwhile,\u{0020}we\u{0020}greatly\u{0020}appreciate\u{0020}your\u{0020}continued\u{0020}care\u{0020}for\u{0020}Verir\u{0020}and\u{0020}the\u{0020}ongoing\u{0020}Synesthesia\u{0020}therapy\u{0020}sessions\u{0020}between\u{0020}her\u{0020}and\u{0020}Courant.\u{0020}Our\u{0020}representatives\u{0020}will\u{0020}visit\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}soon\u{0020}to\u{0020}meet\u{0020}with\u{0020}you\u{0020}and\u{0020}your\u{0020}intelligence\u{0020}officer\u{0020}for\u{0020}further\u{0020}discussion\u{0020}and\u{0020}fee\u{0020}settlement.\n\u{3000}\u{3000}\u{0020}As\u{0020}for\u{0020}your\u{0020}previous\u{0020}report\u{0020}noting\u{0020}that\u{0020}\"Verir\u{0020}can\u{0020}now\u{0020}engage\u{0020}in\u{0020}basic\u{0020}conversation\u{0020}while\u{0020}in\u{0020}non-gigantified\u{0020}form,\"\u{0020}our\u{0020}staff\u{0020}cannot\u{0020}draw\u{0020}conclusions\u{0020}based\u{0020}solely\u{0020}on\u{0020}your\u{0020}data,\u{0020}since\u{0020}she\u{0020}insists\u{0020}on\u{0020}remaining\u{0020}at\u{0020}the\u{0020}Danube\u{0020}facility.\u{0020}Judging\u{0020}by\u{0020}the\u{0020}behavioral\u{0020}changes\u{0020}seen\u{0020}in\u{0020}Courant\u{0020}after\u{0020}her\u{0020}return\u{0020}from\u{0020}the\u{0020}Danube,\u{0020}perhaps\u{0020}this\u{0020}side\u{0020}of\u{0020}Verir\u{0020}can\u{0020}only\u{0020}be\u{0020}found\u{0020}in\u{0020}your\u{0020}presence?\n\u{3000}\u{3000}\u{0020}Of\u{0020}course,\u{0020}that's\u{0020}purely\u{0020}speculative\u{0020}and\u{0020}carries\u{0020}no\u{0020}clinical\u{0020}weight.\n\u{3000}\u{3000}\u{0020}Still,\u{0020}please\u{0020}note:\u{0020}Verir\u{0020}has\u{0020}shown\u{0020}an\u{0020}unusually\u{0020}strong\u{0020}attachment\u{0020}to\u{0020}you.\u{0020}It's\u{0020}still\u{0020}hard\u{0020}to\u{0020}tell\u{0020}if\u{0020}that's\u{0020}a\u{0020}good\u{0020}or\u{0020}bad\u{0020}sign.\u{0020}To\u{0020}be\u{0020}safe,\u{0020}the\u{0020}Daybreak\u{0020}research\u{0020}team\u{0020}has\u{0020}compiled\u{0020}a\u{0020}complete\u{0020}response\u{0020}protocol,\u{0020}which\u{0020}has\u{0020}been\u{0020}sent\u{0020}to\u{0020}your\u{0020}registered\u{0020}email.\u{0020}Please\u{0020}read\u{0020}it\u{0020}carefully.\n\u{3000}\u{3000}\u{0020}Drivers\u{0020}are\u{0020}substitutable.\u{0020}But\u{0020}you\u{0020}are\u{0020}our\u{0020}only\u{0020}existing\u{0020}Synesthete.\n\u{3000}\u{3000}\u{0020}May\u{0020}fortune\u{0020}and\u{0020}health\u{0020}watch\u{0020}over\u{0020}you.", "0", "0", "0", "0", 11045, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614504] = {614504, 2000, "\u{3000}\u{3000}The\u{0020}world\u{0020}is\u{0020}a\u{0020}box,\u{0020}small,\u{0020}with\u{0020}too\u{0020}many\u{0020}thorns.\n\u{3000}\u{3000}\u{0020}It\u{0020}hurts.\n\u{3000}\u{3000}\u{0020}But\u{0020}I\u{0020}can't\u{0020}escape\u{0020}it.\n\u{3000}\u{3000}\u{0020}I\u{0020}hate\u{0020}this\u{0020}box.\n\u{3000}\u{3000}\u{0020}...The\u{0020}annoying\u{0020}one\u{0020}came\u{0020}back.\n\u{3000}\u{3000}\u{0020}She's\u{0020}changed\u{0020}a\u{0020}lot.\n\u{3000}\u{3000}\u{0020}She\u{0020}smiled\u{0020}and\u{0020}bragged\u{0020}that\u{0020}she's\u{0020}found\u{0020}someone\u{0020}who\u{0020}can\u{0020}save\u{0020}her.\n\u{3000}\u{3000}\u{0020}But\u{0020}she\u{0020}won't\u{0020}tell\u{0020}me\u{0020}who\u{0020}that\u{0020}person\u{0020}is.\n\u{3000}\u{3000}\u{0020}It's\u{0020}easy,\u{0020}really.\n\u{3000}\u{3000}\u{0020}I'll\u{0020}make\u{0020}her\u{0020}talk.\n\u{3000}\u{3000}\u{0020}Then\u{0020}ask\u{0020}to\u{0020}be\u{0020}sent\u{0020}to\u{0020}him,\u{0020}too.", "0", "0", "0", "0", 11045, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
