[614601] = {614601, 100, "\u{3000}\u{3000}You\u{0020}need\u{0020}a\u{0020}role\u{0020}model.\u{0020}\n\u{3000}\u{3000}At\u{0020}some\u{0020}point,\u{0020}she\u{0020}couldn't\u{0020}tell\u{0020}when\u{0020}it\u{0020}started,\u{0020}whether\u{0020}it\u{0020}was\u{0020}her\u{0020}parents\u{0020}or\u{0020}her\u{0020}teachers,\u{0020}but\u{0020}the\u{0020}same\u{0020}words\u{0020}kept\u{0020}being\u{0020}repeated\u{0020}in\u{0020}her\u{0020}ear.\u{0020}\n\u{3000}\u{3000}Because\u{0020}she\u{0020}was\u{0020}a\u{0020}student,\u{0020}she\u{0020}needed\u{0020}a\u{0020}role\u{0020}model\u{0020}capable\u{0020}of\u{0020}guiding\u{0020}her\u{0020}forward.\u{0020}That\u{0020}kind\u{0020}of\u{0020}reasoning,\u{0020}Peppetta\u{0020}might\u{0020}be\u{0020}foolish,\u{0020}but\u{0020}she\u{0020}could\u{0020}still\u{0020}understand\u{0020}the\u{0020}intention\u{0020}behind\u{0020}it,\u{0020}at\u{0020}least\u{0020}a\u{0020}little.\n\u{3000}\u{3000}But\u{0020}if\u{0020}all\u{0020}that\u{0020}was\u{0020}needed\u{0020}was\u{0020}a\u{0020}role\u{0020}model,\u{0020}then\u{0020}casually\u{0020}appointing\u{0020}someone\u{0020}mediocre\u{0020}to\u{0020}that\u{0020}position\u{0020}was\u{0020}simply\u{0020}laughable.\u{0020}\n\u{3000}\u{3000}Peppetta\u{0020}could\u{0020}not\u{0020}bring\u{0020}herself\u{0020}to\u{0020}regard\u{0020}her\u{0020}classmates,\u{0020}or\u{0020}even\u{0020}the\u{0020}outstanding\u{0020}students\u{0020}at\u{0020}her\u{0020}school,\u{0020}as\u{0020}her\u{0020}role\u{0020}models.\u{0020}In\u{0020}her\u{0020}eyes,\u{0020}there\u{0020}wasn't\u{0020}that\u{0020}much\u{0020}difference\u{0020}between\u{0020}herself\u{0020}and\u{0020}them.\u{0020}\n\u{3000}\u{3000}There\u{0020}was\u{0020}a\u{0020}gap,\u{0020}but\u{0020}no\u{0020}true\u{0020}distinction.\u{0020}\n\u{3000}\u{3000}Choosing\u{0020}them\u{0020}as\u{0020}role\u{0020}models\u{0020}would\u{0020}be\u{0020}thinking\u{0020}far\u{0020}too\u{0020}small.\u{0020}\n\u{3000}\u{3000}It\u{0020}was\u{0020}while\u{0020}holding\u{0020}such\u{0020}thoughts,\u{0020}at\u{0020}a\u{0020}time\u{0020}when\u{0020}she\u{0020}wasn’t\u{0020}even\u{0020}qualified\u{0020}to\u{0020}be\u{0020}a\u{0020}trainee\u{0020}Driver\u{0020}that\u{0020}she\u{0020}happened\u{0020}to\u{0020}see\u{0020}a\u{0020}program,\u{0020}an\u{0020}interview\u{0020}boldly\u{0020}titled\u{0020}\"The\u{0020}Savior\u{0020}of\u{0020}Saar\u{0020}City.\"\u{0020}\n\u{3000}\u{3000}It\u{0020}was\u{0020}a\u{0020}decisive\u{0020}moment.\u{0020}\n\u{3000}\u{3000}In\u{0020}that\u{0020}instant,\u{0020}Peppetta\u{0020}decided\u{0020}to\u{0020}take\u{0020}that\u{0020}Navigator\u{0020}as\u{0020}her\u{0020}role\u{0020}model,\u{0020}the\u{0020}goal\u{0020}she\u{0020}would\u{0020}chase\u{0020}for\u{0020}her\u{0020}entire\u{0020}life.\u{0020}\n\u{3000}\u{3000}No,\u{0020}not\u{0020}just\u{0020}a\u{0020}goal.\u{0020}\n\u{3000}\u{3000}But\u{0020}a\u{0020}goal\u{0020}of\u{0020}\"love.\"", "0", "0", "0", "0", 11046, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614602] = {614602, 500, "\u{3000}\u{3000}After\u{0020}setting\u{0020}her\u{0020}goal,\u{0020}there\u{0020}was\u{0020}only\u{0020}one\u{0020}problem\u{0020}left\u{0020}before\u{0020}Peppetta.\u{0020}\n\u{3000}\u{3000}That\u{0020}was\u{0020}how\u{0020}to\u{0020}become\u{0020}a\u{0020}Driver\u{0020}and\u{0020}make\u{0020}her\u{0020}way\u{0020}to\u{0020}the\u{0020}Navigator's\u{0020}side,\u{0020}if\u{0020}she\u{0020}followed\u{0020}the\u{0020}proper\u{0020}path,\u{0020}studied\u{0020}diligently,\u{0020}trained\u{0020}hard,\u{0020}and\u{0020}waited\u{0020}for\u{0020}the\u{0020}right\u{0020}moment,\u{0020}she\u{0020}could\u{0020}become\u{0020}a\u{0020}certified\u{0020}Driver\u{0020}and\u{0020}gradually\u{0020}draw\u{0020}closer\u{0020}to\u{0020}the\u{0020}Navigator.\u{0020}\n\u{3000}\u{3000}But\u{0020}that\u{0020}wouldn't\u{0020}work.\u{0020}\n\u{3000}\u{3000}She\u{0020}didn't\u{0020}have\u{0020}time.\u{0020}\n\u{3000}\u{3000}She\u{0020}knew\u{0020}it,\u{0020}during\u{0020}those\u{0020}TV\u{0020}interviews,\u{0020}there\u{0020}was\u{0020}always\u{0020}a\u{0020}certain\u{0020}Driver\u{0020}openly\u{0020}flirting\u{0020}with\u{0020}the\u{0020}Navigator.\u{0020}Charlissa,\u{0020}or\u{0020}something\u{0020}like\u{0020}that.\u{0020}Peppetta\u{0020}could\u{0020}tell\u{0020}at\u{0020}a\u{0020}glance:\u{0020}a\u{0020}fool\u{0020}who\u{0020}would\u{0020}be\u{0020}easily\u{0020}swept\u{0020}away\u{0020}by\u{0020}romance\u{0020}and\u{0020}incapable\u{0020}of\u{0020}clear\u{0020}thinking.\u{0020}\n\u{3000}\u{3000}If\u{0020}someone\u{0020}like\u{0020}that\u{0020}stayed\u{0020}by\u{0020}the\u{0020}Navigator's\u{0020}side,\u{0020}it\u{0020}wouldn't\u{0020}be\u{0020}long\u{0020}before\u{0020}the\u{0020}Navigator\u{0020}was\u{0020}taken!\u{0020}\n\u{3000}\u{3000}That\u{0020}was\u{0020}absolutely\u{0020}unacceptable.\u{0020}Just\u{0020}imagining\u{0020}the\u{0020}Navigator\u{0020}walking\u{0020}down\u{0020}the\u{0020}aisle\u{0020}with\u{0020}that\u{0020}blonde\u{0020}idiot\u{0020}was\u{0020}enough\u{0020}to\u{0020}make\u{0020}Peppetta's\u{0020}heart\u{0020}stop.\u{0020}\n\u{3000}\u{3000}She\u{0020}believed\u{0020}she\u{0020}surpassed\u{0020}that\u{0020}blonde\u{0020}fool\u{0020}in\u{0020}every\u{0020}respect.\u{0020}The\u{0020}only\u{0020}real\u{0020}difference\u{0020}between\u{0020}them\u{0020}was\u{0020}this:\u{0020}she\u{0020}was\u{0020}still\u{0020}a\u{0020}student,\u{0020}while\u{0020}the\u{0020}other\u{0020}was\u{0020}already\u{0020}a\u{0020}certified\u{0020}Driver.\u{0020}\n\u{3000}\u{3000}She\u{0020}had\u{0020}to\u{0020}become\u{0020}a\u{0020}Driver\u{0020}as\u{0020}soon\u{0020}as\u{0020}possible.\u{0020}And\u{0020}upon\u{0020}learning\u{0020}that\u{0020}the\u{0020}\"Fledgling\"\u{0020}squad\u{0020}was\u{0020}already\u{0020}full,\u{0020}she\u{0020}shifted\u{0020}her\u{0020}sights\u{0020}to…\u{0020}\n\u{3000}\u{3000}The\u{0020}team\u{0020}known\u{0020}for\u{0020}gathering\u{0020}problem\u{0020}children:\u{0020}Astray\u{0020}Blossom.", "0", "0", "0", "0", 11046, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614603] = {614603, 1000, "\u{3000}\u{3000}Wanting\u{0020}to\u{0020}join\u{0020}Astray\u{0020}Blossom\u{0020}was\u{0020}also\u{0020}no\u{0020}easy\u{0020}matter.\u{0020}\n\u{3000}\u{3000}After\u{0020}all,\u{0020}Peppetta\u{0020}considered\u{0020}herself\u{0020}someone\u{0020}with\u{0020}poor\u{0020}grades,\u{0020}late\u{0020}arrivals,\u{0020}early\u{0020}departures,\u{0020}missing\u{0020}homework...\u{0020}but\u{0020}if\u{0020}she\u{0020}were\u{0020}to\u{0020}become\u{0020}a\u{0020}true\u{0020}problem\u{0020}child\u{0020}in\u{0020}the\u{0020}strict\u{0020}sense\u{0020}of\u{0020}the\u{0020}term,\u{0020}there\u{0020}was\u{0020}still\u{0020}a\u{0020}great\u{0020}deal\u{0020}she\u{0020}lacked.\u{0020}\n\u{3000}\u{3000}In\u{0020}order\u{0020}to\u{0020}become\u{0020}a\u{0020}genuinely\u{0020}bad\u{0020}student,\u{0020}be\u{0020}assigned\u{0020}to\u{0020}\"Astray\u{0020}Blossom\",\u{0020}and\u{0020}receive\u{0020}professional\u{0020}Driver\u{0020}training,\u{0020}she\u{0020}began\u{0020}trying\u{0020}to\u{0020}act\u{0020}like\u{0020}one.\u{0020}\n\u{3000}\u{3000}Being\u{0020}compared\u{0020}to\u{0020}delinquent\u{0020}girls\u{0020}or\u{0020}underworld\u{0020}heiresses\u{0020}was\u{0020}hardly\u{0020}pleasant\u{0020}(most\u{0020}importantly,\u{0020}she\u{0020}usually\u{0020}ended\u{0020}up\u{0020}ranked\u{0020}third\u{0020}among\u{0020}them),\u{0020}but\u{0020}as\u{0020}long\u{0020}as\u{0020}the\u{0020}outcome\u{0020}was\u{0020}what\u{0020}she\u{0020}wanted,\u{0020}she\u{0020}could\u{0020}accept\u{0020}it.\u{0020}\n\u{3000}\u{3000}\"So,\u{0020}this\u{0020}is\u{0020}why\u{0020}you\u{0020}secretly\u{0020}snuck\u{0020}into\u{0020}the\u{0020}Danube\u{0020}Branch?\"\u{0020}\n\u{3000}\u{3000}Even\u{0020}the\u{0020}synesthete\u{0020}Navigator\u{0020}found\u{0020}himself\u{0020}at\u{0020}a\u{0020}loss\u{0020}when\u{0020}faced\u{0020}with\u{0020}a\u{0020}girl\u{0020}who\u{0020}charged\u{0020}toward\u{0020}love\u{0020}like\u{0020}an\u{0020}unstoppable\u{0020}war\u{0020}chariot.", "0", "0", "0", "0", 11046, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614604] = {614604, 2000, "\u{3000}\u{3000}Charge,\u{0020}charge,\u{0020}charge,\u{0020}the\u{0020}chariot\u{0020}of\u{0020}love\u{0020}charges\u{0020}forward.\u{0020}\n\u{3000}\u{3000}I\u{0020}won't\u{0020}lose\u{0020}to\u{0020}anyone,\u{0020}won't\u{0020}lose\u{0020}to\u{0020}idiots,\u{0020}won't\u{0020}lose\u{0020}to\u{0020}knights,\u{0020}won't\u{0020}lose\u{0020}to\u{0020}underclassmen.\u{0020}\n\u{3000}\u{3000}Charge,\u{0020}charge,\u{0020}charge,\u{0020}the\u{0020}chariot\u{0020}of\u{0020}love\u{0020}charges\u{0020}forward,\u{0020}\n\u{3000}\u{3000}No\u{0020}one\u{0020}can\u{0020}stop\u{0020}my\u{0020}love\u{0020}chariot.\u{0020}\n\u{3000}\u{3000}Raise\u{0020}the\u{0020}cannon\u{0020}high,\u{0020}fire\u{0020}at\u{0020}the\u{0020}target!\u{0020}\n\u{3000}\u{3000}Capture\u{0020}the\u{0020}Navigator's\u{0020}heart!\u{0020}\n\u{3000}\u{3000}(Wait…\u{0020}is\u{0020}\"heart\"\u{0020}really\u{0020}the\u{0020}right\u{0020}word\u{0020}to\u{0020}use\u{0020}here?)", "0", "0", "0", "0", 11046, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
