[614701] = {614701, 100, "\u{3000}\u{3000}TeleRabbit\u{0020}is\u{0020}a\u{0020}girl\u{0020}with\u{0020}a\u{0020}pleasant\u{0020}singing\u{0020}voice\u{0020}and\u{0020}some\u{0020}knowledge\u{0020}of\u{0020}composition.\u{0020}Although\u{0020}she\u{0020}is\u{0020}still\u{0020}attending\u{0020}school,\u{0020}she\u{0020}is\u{0020}already\u{0020}striving\u{0020}toward\u{0020}the\u{0020}goal\u{0020}of\u{0020}becoming\u{0020}a\u{0020}world-class\u{0020}idol.\u{0020}Her\u{0020}personality\u{0020}is\u{0020}lively\u{0020}and\u{0020}playful,\u{0020}yet\u{0020}she\u{0020}is\u{0020}earnest\u{0020}at\u{0020}heart.\u{0020}Once\u{0020}she\u{0020}sets\u{0020}her\u{0020}mind\u{0020}on\u{0020}something,\u{0020}she\u{0020}gives\u{0020}it\u{0020}her\u{0020}all.\u{0020}Even\u{0020}when\u{0020}her\u{0020}efforts\u{0020}do\u{0020}not\u{0020}yield\u{0020}results,\u{0020}she\u{0020}does\u{0020}not\u{0020}sink\u{0020}into\u{0020}excessive\u{0020}gloom\u{0020}-\u{0020}after\u{0020}waking\u{0020}to\u{0020}the\u{0020}morning\u{0020}sun\u{0020}the\u{0020}next\u{0020}day,\u{0020}her\u{0020}energy\u{0020}will\u{0020}be\u{0020}fully\u{0020}restored.\u{0020}\n\u{3000}\u{3000}[The\u{0020}above\u{0020}content\u{0020}is\u{0020}taken\u{0020}from\u{0020}the\u{0020}channel\u{0020}description\u{0020}of\u{0020}TeleRabbit's\u{0020}own\u{0020}account.]\u{0020}\n\u{3000}\u{3000}At\u{0020}the\u{0020}request\u{0020}of\u{0020}the\u{0020}Chief\u{0020}of\u{0020}the\u{0020}Seven\u{0020}Sages\u{0020}of\u{0020}the\u{0020}Sahara\u{0020}Azure\u{0020}Academy,\u{0020}this\u{0020}Driver\u{0020}profile\u{0020}will\u{0020}not\u{0020}address\u{0020}the\u{0020}existence\u{0020}behind\u{0020}the\u{0020}virtual\u{0020}identity\u{0020}\"TeleRabbit\".\u{0020}Although\u{0020}Aegis\u{0020}will\u{0020}continue\u{0020}to\u{0020}investigate\u{0020}her\u{0020}true\u{0020}identity,\u{0020}any\u{0020}findings\u{0020}will\u{0020}be\u{0020}recorded\u{0020}only\u{0020}in\u{0020}databases\u{0020}with\u{0020}a\u{0020}higher\u{0020}level\u{0020}of\u{0020}confidentiality.", "0", "0", "0", "0", 11047, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614702] = {614702, 500, "\u{3000}\u{3000}Only\u{0020}one\u{0020}month\u{0020}after\u{0020}her\u{0020}debut,\u{0020}TeleRabbit's\u{0020}account\u{0020}had\u{0020}already\u{0020}amassed\u{0020}millions\u{0020}of\u{0020}followers.\u{0020}Discussions\u{0020}about\u{0020}her\u{0020}flooded\u{0020}every\u{0020}major\u{0020}online\u{0020}community,\u{0020}and\u{0020}media\u{0020}coverage\u{0020}came\u{0020}in\u{0020}an\u{0020}overwhelming\u{0020}wave.\u{0020}Yet\u{0020}despite\u{0020}the\u{0020}rise\u{0020}of\u{0020}such\u{0020}a\u{0020}phenomenon-level\u{0020}idol,\u{0020}there\u{0020}were\u{0020}surprisingly\u{0020}few\u{0020}who\u{0020}tried\u{0020}to\u{0020}ride\u{0020}the\u{0020}trend\u{0020}by\u{0020}imitation\u{0020}-\u{0020}because\u{0020}at\u{0020}her\u{0020}core,\u{0020}TeleRabbit\u{0020}is\u{0020}not\u{0020}an\u{0020}idol,\u{0020}but\u{0020}a\u{0020}hacker\u{0020}who\u{0020}operates\u{0020}under\u{0020}the\u{0020}guise\u{0020}of\u{0020}one.\u{0020}\n\u{3000}\u{3000}TeleRabbit's\u{0020}first\u{0020}public\u{0020}appearance\u{0020}took\u{0020}place\u{0020}during\u{0020}the\u{0020}**\u{0020}Academy\u{0020}**\u{0020}Incident,\u{0020}but\u{0020}at\u{0020}that\u{0020}time\u{0020}she\u{0020}had\u{0020}not\u{0020}yet\u{0020}officially\u{0020}debuted\u{0020}as\u{0020}an\u{0020}idol.\u{0020}As\u{0020}a\u{0020}result,\u{0020}her\u{0020}first\u{0020}program\u{0020}following\u{0020}a\u{0020}public\u{0020}appearance\u{0020}was,\u{0020}in\u{0020}fact,\u{0020}an\u{0020}Aegis-hosted\u{0020}press\u{0020}conference.\u{0020}By\u{0020}unknown\u{0020}means,\u{0020}TeleRabbit\u{0020}breached\u{0020}the\u{0020}official\u{0020}system\u{0020}and\u{0020}hijacked\u{0020}the\u{0020}electronic\u{0020}equipment\u{0020}at\u{0020}the\u{0020}venue,\u{0020}instantly\u{0020}transforming\u{0020}what\u{0020}was\u{0020}meant\u{0020}to\u{0020}be\u{0020}a\u{0020}solemn\u{0020}press\u{0020}briefing\u{0020}into\u{0020}her\u{0020}own\u{0020}personal\u{0020}concert\u{0020}-\u{0020}one\u{0020}that\u{0020}could\u{0020}not\u{0020}even\u{0020}be\u{0020}taken\u{0020}off\u{0020}the\u{0020}air.\u{0020}The\u{0020}viewership\u{0020}numbers\u{0020}soared\u{0020}to\u{0020}unprecedented\u{0020}heights,\u{0020}and\u{0020}the\u{0020}incident\u{0020}dominated\u{0020}online\u{0020}trending\u{0020}charts\u{0020}for\u{0020}an\u{0020}entire\u{0020}week.\u{0020}Such\u{0020}an\u{0020}illegal\u{0020}act\u{0020}that\u{0020}openly\u{0020}challenged\u{0020}Aegis's\u{0020}authority\u{0020}was,\u{0020}naturally,\u{0020}something\u{0020}no\u{0020}one\u{0020}else\u{0020}could\u{0020}replicate\u{0020}-\u{0020}even\u{0020}those\u{0020}bold\u{0020}enough\u{0020}to\u{0020}try\u{0020}usually\u{0020}lacked\u{0020}her\u{0020}almost\u{0020}supernatural\u{0020}hacking\u{0020}skills.\u{0020}\n\u{3000}\u{3000}In\u{0020}fact,\u{0020}the\u{0020}policy\u{0020}set\u{0020}to\u{0020}be\u{0020}announced\u{0020}at\u{0020}that\u{0020}press\u{0020}conference\u{0020}had\u{0020}already\u{0020}faced\u{0020}significant\u{0020}opposition,\u{0020}and\u{0020}controversy\u{0020}persisted\u{0020}throughout\u{0020}its\u{0020}trial\u{0020}period.\u{0020}As\u{0020}such,\u{0020}TeleRabbit's\u{0020}actions\u{0020}were\u{0020}widely\u{0020}regarded\u{0020}as\u{0020}a\u{0020}form\u{0020}of\u{0020}rebellion\u{0020}that\u{0020}lay\u{0020}somewhere\u{0020}between\u{0020}radical\u{0020}and\u{0020}restrained.\u{0020}Whether\u{0020}people\u{0020}were\u{0020}merely\u{0020}seeking\u{0020}entertainment\u{0020}or\u{0020}looking\u{0020}for\u{0020}a\u{0020}figure\u{0020}to\u{0020}emulate,\u{0020}they\u{0020}all\u{0020}found\u{0020}something\u{0020}they\u{0020}desired\u{0020}in\u{0020}her\u{0020}idol\u{0020}activities.\u{0020}TeleRabbit\u{0020}thus\u{0020}continues\u{0020}to\u{0020}carry\u{0020}out\u{0020}her\u{0020}distinctive\u{0020}\"performances\"\u{0020}from\u{0020}time\u{0020}to\u{0020}time\u{0020}-\u{0020}appearances\u{0020}with\u{0020}no\u{0020}prior\u{0020}notice,\u{0020}occurring\u{0020}in\u{0020}places\u{0020}no\u{0020}one\u{0020}could\u{0020}predict,\u{0020}emerging\u{0020}suddenly\u{0020}like\u{0020}flash\u{0020}art,\u{0020}only\u{0020}to\u{0020}vanish\u{0020}again\u{0020}in\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye.", "0", "0", "0", "0", 11047, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614703] = {614703, 1000, "\u{3000}\u{3000}TeleRabbit\u{0020}will\u{0020}not\u{0020}appear\u{0020}within\u{0020}the\u{0020}Aegis\u{0020}base\u{0020}under\u{0020}her\u{0020}real\u{0020}identity...\u{0020}or\u{0020}perhaps\u{0020}she\u{0020}already\u{0020}has,\u{0020}only\u{0020}without\u{0020}being\u{0020}discovered.\u{0020}At\u{0020}first,\u{0020}the\u{0020}Logistics\u{0020}Division\u{0020}continued\u{0020}to\u{0020}reserve\u{0020}a\u{0020}dormitory\u{0020}bed\u{0020}for\u{0020}her,\u{0020}with\u{0020}all\u{0020}other\u{0020}accommodations\u{0020}provided\u{0020}according\u{0020}to\u{0020}standard\u{0020}regulations.\u{0020}As\u{0020}a\u{0020}result,\u{0020}this\u{0020}practice\u{0020}of\u{0020}\"preparing\u{0020}meals\u{0020}for\u{0020}an\u{0020}unoccupied\u{0020}bed\"\u{0020}led\u{0020}some\u{0020}uninformed\u{0020}personnel\u{0020}to\u{0020}draw\u{0020}rather\u{0020}strange\u{0020}conclusions.\u{0020}\n\u{3000}\u{3000}Some\u{0020}believed\u{0020}that\u{0020}the\u{0020}owner\u{0020}of\u{0020}the\u{0020}bed\u{0020}must\u{0020}have\u{0020}been\u{0020}a\u{0020}highly\u{0020}decorated\u{0020}Driver\u{0020}in\u{0020}life,\u{0020}deserving\u{0020}of\u{0020}such\u{0020}respect;\u{0020}others\u{0020}thought\u{0020}it\u{0020}was\u{0020}the\u{0020}work\u{0020}of\u{0020}an\u{0020}unfortunate\u{0020}spirit\u{0020}that\u{0020}required\u{0020}appeasement\u{0020}in\u{0020}order\u{0020}to\u{0020}rest\u{0020}in\u{0020}peace.\u{0020}When\u{0020}TeleRabbit\u{0020}learned\u{0020}of\u{0020}these\u{0020}rumors\u{0020}and\u{0020}subsequently\u{0020}hacked\u{0020}into\u{0020}the\u{0020}Ark\u{0020}system\u{0020}to\u{0020}create\u{0020}a\u{0020}holographic\u{0020}projection\u{0020}to\u{0020}clarify\u{0020}the\u{0020}situation,\u{0020}some\u{0020}staff\u{0020}members\u{0020}genuinely\u{0020}believed\u{0020}they\u{0020}were\u{0020}seeing\u{0020}a\u{0020}ghost,\u{0020}and\u{0020}promptly\u{0020}fainted\u{0020}on\u{0020}the\u{0020}spot\u{0020}from\u{0020}fright.", "0", "0", "0", "0", 11047, "0