[614801] = {614801, 100, "\u{3000}\u{3000}The\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}a\u{0020}realm\u{0020}where\u{0020}heroines\u{0020}gather\u{0020}and\u{0020}among\u{0020}them,\n\n\u{3000}\u{3000}Lilith\u{0020}stands\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}most\u{0020}troublesome,\u{0020}the\u{0020}most\u{0020}dangerous\u{0020}to\u{0020}underestimate.\n\n\u{3000}\u{3000}In\u{0020}raw\u{0020}power,\u{0020}she\u{0020}isn't\u{0020}the\u{0020}absolute\u{0020}strongest,\u{0020}yet\u{0020}she\u{0020}resides\u{0020}within\u{0020}the\u{0020}cosmos'\u{0020}first\u{0020}tier.\u{0020}In\u{0020}influence,\u{0020}she\u{0020}has\u{0020}Skadi,\u{0020}the\u{0020}[Star\u{0020}Monarch],\u{0020}as\u{0020}her\u{0020}unwavering\u{0020}backer.\u{0020}In\u{0020}reputation,\u{0020}her\u{0020}record\u{0020}is\u{0020}spotless.\u{0020}No\u{0020}history\u{0020}of\u{0020}disrupting\u{0020}universal\u{0020}harmony.\u{0020}And\u{0020}that\u{0020}is\u{0020}precisely\u{0020}what\u{0020}makes\u{0020}her\u{0020}so\u{0020}perilous.\u{0020}These\u{0020}privileges\u{0020}form\u{0020}an\u{0020}impenetrable\u{0020}shield\u{0020}around\u{0020}her.\u{0020}Even\u{0020}when\u{0020}others\u{0020}sense\u{0020}something\u{0020}off\u{0020}about\u{0020}Lilith,\u{0020}they\u{0020}can't\u{0020}do\u{0020}anything\u{0020}about\u{0020}it.\n\n\u{3000}\u{3000}Because\u{0020}the\u{0020}truth\u{0020}is,\u{0020}their\u{0020}nature\u{0020}only\u{0020}began\u{0020}to\u{0020}shift\u{0020}after\u{0020}arriving\u{0020}here.\u{0020}The\u{0020}tangled\u{0020}mess\u{0020}of\u{0020}her\u{0020}heart\u{0020}only\u{0020}unraveled\u{0020}in\u{0020}death,\u{0020}revealing\u{0020}her\u{0020}true\u{0020}self\u{0020}too\u{0020}late.", "0", "0", "0", "0", 11048, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614802] = {614802, 500, "\u{3000}\u{3000}\"If\u{0020}only\u{0020}I'd\u{0020}understood\u{0020}what\u{0020}I\u{0020}wanted\u{0020}sooner.\"\n\n\u{3000}\u{3000}\"If\u{0020}only\u{0020}I'd\u{0020}honestly\u{0020}shared\u{0020}my\u{0020}struggles\u{0020}with\u{0020}Navigator.\"\n\n\u{3000}\u{3000}\"If\u{0020}only\u{0020}I'd\u{0020}just\u{0020}spoken\u{0020}truthfully.\"\n\n\u{3000}\u{3000}These\u{0020}\"if\u{0020}onlys\"\u{0020}haunted\u{0020}her,\u{0020}echoing\u{0020}through\u{0020}endless\u{0020}nights.\u{0020}The\u{0020}most\u{0020}bitter\u{0020}tear\u{0020}escaped\u{0020}from\u{0020}her\u{0020}eye,\u{0020}kissed\u{0020}by\u{0020}parched\u{0020}lips\u{0020}before\u{0020}falling\u{0020}onto\u{0020}a\u{0020}greedy\u{0020}tongue.\u{0020}She\u{0020}wished\u{0020}it\u{0020}were\u{0020}the\u{0020}world's\u{0020}most\u{0020}excruciating\u{0020}poison\u{0020}or\u{0020}anything\u{0020}to\u{0020}spare\u{0020}her\u{0020}this\u{0020}relentless,\u{0020}heart-pounding\u{0020}remorse.\u{0020}Let\u{0020}the\u{0020}bedsheets\u{0020}swallow\u{0020}her\u{0020}whole.\u{0020}Let\u{0020}the\u{0020}world\u{0020}forget\u{0020}her.\n\n\u{3000}\u{3000}But\u{0020}no\u{0020}such\u{0020}\"if\u{0020}onlys\"\u{0020}exist.\u{0020}She\u{0020}must\u{0020}keep\u{0020}living.\u{0020}The\u{0020}living\u{0020}bear\u{0020}curses,\u{0020}fantasizing\u{0020}that\u{0020}a\u{0020}different\u{0020}self,\u{0020}who\u{0020}had\u{0020}embraced\u{0020}these\u{0020}emotions\u{0020}early,\u{0020}had\u{0020}never\u{0020}missed\u{0020}a\u{0020}single\u{0020}chance\u{0020}to\u{0020}hold\u{0020}him.\n\n\u{3000}\u{3000}This\u{0020}change\u{0020}has\u{0020}cost\u{0020}Lilith\u{0020}the\u{0020}person\u{0020}she\u{0020}once\u{0020}knew.\n\n\u{3000}\u{3000}[I\u{0020}will\u{0020}see\u{0020}him\u{0020}again.\u{0020}I'll\u{0020}win\u{0020}his\u{0020}favor,\u{0020}no\u{0020}matter\u{0020}what\u{0020}it\u{0020}takes.]\u{0020}This\u{0020}is\u{0020}the\u{0020}purpose\u{0020}she's\u{0020}set\u{0020}for\u{0020}herself.\n\n\u{3000}\