[614901] = {614901, 100, "\u{3000}\u{3000}Althea\u{0020}Weiss\u{0020}was\u{0020}assigned\u{0020}to\u{0020}the\u{0020}special\u{0020}squad\u{0020}\"Hydra\"\u{0020}as\u{0020}a\u{0020}new\u{0020}member\u{0020}only\u{0020}one\u{0020}week\u{0020}before\u{0020}Maya\u{0020}was\u{0020}attacked\u{0020}by\u{0020}the\u{0020}Great\u{0020}Sin,\u{0020}Gluttony.\u{0020}In\u{0020}fact,\u{0020}her\u{0020}first\u{0020}formal\u{0020}meeting\u{0020}with\u{0020}her\u{0020}teammates\u{0020}did\u{0020}not\u{0020}even\u{0020}take\u{0020}place\u{0020}until\u{0020}the\u{0020}assembly\u{0020}for\u{0020}their\u{0020}very\u{0020}first\u{0020}mission.\n\u{3000}\u{3000}Judging\u{0020}from\u{0020}her\u{0020}past\u{0020}qualifications,\u{0020}she\u{0020}should\u{0020}not\u{0020}have\u{0020}been\u{0020}eligible\u{0020}to\u{0020}become\u{0020}a\u{0020}driver.\n\u{3000}\u{3000}She\u{0020}lacked\u{0020}the\u{0020}essential\u{0020}combat\u{0020}training\u{0020}and\u{0020}did\u{0020}not\u{0020}possess\u{0020}the\u{0020}mental\u{0020}preparedness\u{0020}expected\u{0020}of\u{0020}a\u{0020}mature\u{0020}driver.\u{0020}Under\u{0020}such\u{0020}circumstances,\u{0020}the\u{0020}fact\u{0020}that\u{0020}Althea\u{0020}was\u{0020}still\u{0020}able\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}can\u{0020}only\u{0020}make\u{0020}one\u{0020}suspect\u{0020}that\u{0020}some\u{0020}unknown\u{0020}secret\u{0020}lies\u{0020}behind\u{0020}it.\n\u{3000}\u{3000}Unexpectedly,\u{0020}however,\u{0020}in\u{0020}the\u{0020}one\u{0020}and\u{0020}only\u{0020}gigantification\u{0020}test\u{0020}she\u{0020}underwent,\u{0020}Althea\u{0020}Weiss\u{0020}displayed\u{0020}extraordinary\u{0020}potential.\u{0020}Yes,\u{0020}her\u{0020}combat\u{0020}techniques\u{0020}could\u{0020}be\u{0020}described\u{0020}as\u{0020}a\u{0020}complete\u{0020}mess,\u{0020}but\u{0020}her\u{0020}adaptability\u{0020}to\u{0020}gigantified\u{0020}combat,\u{0020}along\u{0020}with\u{0020}the\u{0020}exceptional\u{0020}physical\u{0020}abilities\u{0020}she\u{0020}demonstrated\u{0020}in\u{0020}that\u{0020}state,\u{0020}was\u{0020}enough\u{0020}to\u{0020}win\u{0020}over\u{0020}everyone\u{0020}who\u{0020}had\u{0020}doubted\u{0020}her.\n\u{3000}\u{3000}It\u{0020}seems\u{0020}that\u{0020}everyone\u{0020}who\u{0020}can\u{0020}join\u{0020}a\u{0020}special\u{0020}squad\u{0020}has\u{0020}something\u{0020}exceptional\u{0020}about\u{0020}them.", "0", "0", "0", "0", 11049, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[614902] = {614902, 500, "\u{3000}\u{3000}The\u{0020}name\u{0020}Althea\u{0020}Weiss\u{0020}did\u{0020}not\u{0020}originally\u{0020}belong\u{0020}to\u{0020}the\u{0020}Althea\u{0020}Weiss\u{0020}of\u{0020}Hydra.\n\u{3000}\u{3000}It\u{0020}was\u{0020}a\u{0020}name\u{0020}she\u{0020}inherited\u{0020}from\u{0020}elsewhere.\u{0020}Counting\u{0020}her,\u{0020}there\u{0020}have\u{0020}once\u{0020}been\u{0020}three\u{0020}\"Althea\u{0020}Weiss\"\u{0020}in\u{0020}this\u{0020}world.\u{0020}Of\u{0020}course,\u{0020}that\u{0020}refers\u{0020}to\u{0020}three\u{0020}girls\u{0020}directly\u{0020}connected\u{0020}to\u{0020}one\u{0020}another.\u{0020}If\u{0020}we\u{0020}were\u{0020}merely\u{0020}talking\u{0020}about\u{0020}unrelated\u{0020}people\u{0020}who\u{0020}happened\u{0020}to\u{0020}share\u{0020}the\u{0020}same\u{0020}name,\u{0020}that\u{0020}would\u{0020}be\u{0020}another\u{0020}matter\u{0020}entirely.\n\u{3000}\u{3000}The\u{0020}first\u{0020}Althea\u{0020}Weiss\u{0020}did\u{0020}not\u{0020}know\u{0020}the\u{0020}latter\u{0020}two.\u{0020}She\u{0020}died\u{0020}in\u{0020}a\u{0020}disaster\u{0020}that\u{0020}remains\u{0020}an\u{0020}unsolved\u{0020}mystery\u{0020}to\u{0020}this\u{0020}day.\u{0020}No\u{0020}one\u{0020}cared\u{0020}about\u{0020}her\u{0020}life,\u{0020}no\u{0020}trace\u{0020}of\u{0020}her\u{0020}remained,\u{0020}and\u{0020}the\u{0020}last\u{0020}thing\u{0020}she\u{0020}left\u{0020}to\u{0020}this\u{0020}world\u{0020}was\u{0020}her\u{0020}utterly\u{0020}ordinary\u{0020}name.\u{0020}The\u{0020}second\u{0020}Althea\u{0020}Weiss\u{0020}is\u{0020}the\u{0020}one\u{0020}most\u{0020}familiar\u{0020}to\u{0020}people\u{0020}-\u{0020}though\u{0020}only\u{0020}in\u{0020}the\u{0020}sense\u{0020}of\u{0020}what\u{0020}\"ordinary\u{0020}people\"\u{0020}know.\u{0020}She\u{0020}was,\u{0020}without\u{0020}question,\u{0020}an\u{0020}outstanding\u{0020}student,\u{0020}a\u{0020}high\u{0020}school\u{0020}girl\u{0020}somewhat\u{0020}prone\u{0020}to\u{0020}getting\u{0020}stuck\u{0020}on\u{0020}details\u{0020}and\u{0020}unwilling\u{0020}to\u{0020}compromise\u{0020}with\u{0020}ambiguity\u{0020}or\u{0020}vagueness.\u{0020}And\u{0020}after\u{0020}certain\u{0020}truths\u{0020}came\u{0020}to\u{0020}light,\u{0020}she\u{0020}too\u{0020}became\u{0020}a\u{0020}phantom\u{0020}scattered\u{0020}into\u{0020}the\u{0020}air.\n\u{3000}\u{3000}The\u{0020}\"Althea\u{0020}Weiss\"\u{0020}who\u{0020}now\u{0020}remains\u{0020}in\u{0020}this\u{0020}world\u{0020}-\u{0020}though\u{0020}that\u{0020}phrasing\u{0020}may\u{0020}sound\u{0020}a\u{0020}bit\u{0020}dramatic\u{0020}-\u{0020}is\u{0020}the\u{0020}Althea\u{0020}Weiss\u{0020}who\u{0020}inherited\u{0020}that\u{0020}name\u{0020}from\u{0020}the\u{0020}two\u{0020}girls\u{0020}above\u{0020}and\u{0020}joined\u{0020}Aegis's\u{0020}special\u{0020}squad,\u{0020}Hydra.\n\u{3000}\u{3000}She\u{0020}may\u{0020}be\u{0020}the\u{0020}most\u{0020}unusual\u{0020}Althea\u{0020}Weiss,\u{0020}because\u{0020}she\u{0020}possesses\u{0020}the\u{0020}\"empathic\u{0020}resonance\"\u{0020}ability\u{0020}that\u{0020}has\u{0020}caused\u{0020}the\u{0020}greatest\u{0020}interference\u{0020}with\u{0020}the\u{0020}real\u{0020}world\u{0020}to\u{0020}date.\u{0020}Yet\u{0020}she\u{0020}may\u{0020}also\u{0020}be\u{0020}the\u{0020}most\u{0020}ordinary\u{0020}Althea\u{0020}Weiss,\u{0020}because\u{0020}she\u{0020}lacks\u{0020}a\u{0020}lofty\u{0020}character\u{0020}or\u{0020}a\u{0020}tear-jerking\u{0020}past.\u{0020}Before\u{0020}joining\u{0020}Aegis,\u{0020}she\u{0020}had\u{0020}never\u{0020}even\u{0020}thought\u{0020}about\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}she\u{0020}wanted\u{0020}to\u{0020}become.\u{0020}Spiritually\u{0020}speaking,\u{0020}she\u{0020}is\u{0020}ordinary\u{0020}to\u{0020}an\u{0020}almost\u{0020}surprising\u{0020}degree.\n\u{3000}\u{3000}It\u{0020}is\u{0020}only\u{0020}after\u{0020}inheriting\u{0020}the\u{0020}name\u{0020}\"Althea\u{0020}Weiss\"\u{0020}that\u{0020}she\u{0020}experienced\u{0020}some\u{0020}measure\u{0020}of\u{0020}growth.\n\u{3000}\u{3000}\"I\u{0020}owe\u{0020}a\u{0020}great\u{0020}many\u{0020}people,\u{0020}and\u{0020}I\u{0020}have\u{0020}hurt\u{0020}a\u{0020}great\u{0020}many\u{0020}people\u{0020}too.\u{0020}I\u{0020}have\u{0020}to\u{0020}take\u{0020}responsibility\u{0020}for\u{0020}the\u{0020}mistakes\u{0020}I've\u{0020}made.\"\n\u{3000}\u{3000}In\u{0020}the\u{0020}past,\u{0020}she\u{0020}likely\u{0020}would\u{0020}never\u{0020}have\u{0020}said\u{0020}something\u{0020}like\u{0020}that.\u{0020}Only\u{0020}after\u{0020}going\u{0020}through\u{0020}what\u{0020}happened\u{0020}in\u{0020}Plait\u{0020}City,\u{0020}and\u{0020}fully\u{0020}accepting\u{0020}the\u{0020}other\u{0020}side\u{0020}of\u{0020}herself,\u{0020}did\u{0020}she\u{0020}begin\u{0020}to\u{0020}show\u{0020}that\u{0020}serious,\u{0020}uncompromising\u{0020}side\u{0020}to\u{0020}the\u{0020}outside\u{0020}world.\n\u{3000}\u{3000}Perhaps\u{0020}not\u{0020}all\u{0020}of\u{0020}her\u{0020}victims\u{0020}even\u{0020}realize\u{0020}that\u{0020}their\u{0020}rights\u{0020}and\u{0020}interests\u{0020}have\u{0020}been\u{0020}harmed,\u{0020}but\u{0020}she\u{0020}herself\u{0020}does\u{0020}not\u{0020}see\u{0020}it\u{0020}that\u{0020}way.\u{0020}She\u{0020}does\u{0020}not\u{0020}accept\u{0020}ambiguity,\u{0020}nor\u{0020}does\u{0020}she\u{0020}accept\u{0020}vagueness.\u{0020}Now,\u{0020}too,\u{0020}she\u{0020}bears\u{0020}the\u{0020}shadow\u{0020}of\u{0020}\"Althea\u{0020}Weiss.\"\n\u{3000}\u{3000}But\u{0020}as\u{0020}for\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}she\u{0020}is\u{0020}to\u{0020}become,\u{0020}and\u{0020}what\u{0020}kind\u{0020}of\u{0020}path\u{0020}she\u{0020}is\u{0020}to\u{0020}walk,\u{0020}that\u{0020}is\u{0020}something\u{0020}she\u{0020}must\u{0020}choose\u{0020}for\u{0020}herself\u{0020}-\u{0020}and\u{0020}can\u{0020}only\u{0020}choose\u{0020}for\u{0020}herself.", "0", "0", "0", "0", 11049, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[614903] = {614903, 1000, "\u{3000}\u{3000}Thanks\u{0020}to\u{0020}the\u{0020}seven-year\u{0020}beautiful\u{0020}dream\u{0020}in\u{0020}Plait\u{0020}City,\u{0020}Althea\u{0020}Weiss\u{0020}has\u{0020}gained\u{0020}considerable\u{0020}mastery\u{0020}over\u{0020}her\u{0020}\"empathic\u{0020}resonance.\"\u{0020}During\u{0020}the\u{0020}time\u{0020}since\u{0020}she\u{0020}joined\u{0020}Aegis,\u{0020}she\u{0020}has\u{0020}shown\u{0020}not\u{0020}the\u{0020}slightest\u{0020}sign\u{0020}of\u{0020}losing\u{0020}control,\u{0020}nor\u{0020}has\u{0020}she\u{0020}needed\u{0020}medication\u{0020}to\u{0020}stabilize\u{0020}her\u{0020}emotions.\n\u{3000}\u{3000}Unfortunately,\u{0020}because\u{0020}of\u{0020}this\u{0020}exceptionally\u{0020}outstanding\u{0020}talent,\u{0020}she\u{0020}became\u{0020}the\u{0020}next\u{0020}target\u{0020}of\u{0020}a\u{0020}certain\u{0020}notoriously\u{0020}infamous\u{0020}science\u{0020}officer\u{0020}within\u{0020}Aegis.\u{0020}Fortunately,\u{0020}however,\u{0020}Hydra\u{0020}is\u{0020}under\u{0020}the\u{0020}protection\u{0020}of\u{0020}Dr.\u{0020}Stephanie,\u{0020}which\u{0020}allowed\u{0020}her\u{0020}to\u{0020}escape\u{0020}unscathed.\n\u{3000}\u{3000}And\u{0020}if\u{0020}she\u{0020}wishes\u{0020}to\u{0020}become\u{0020}a\u{0020}qualified\u{0020}driver,\u{0020}what\u{0020}she\u{0020}needs\u{0020}is\u{0020}not\u{0020}only\u{0020}great\u{0020}power,\u{0020}but\u{0020}also\u{0020}the\u{0020}spirit\u{0020}to\u{0020}match\u{0020}it.\u{0020}The\u{0020}road\u{0020}Althea\u{0020}Weiss\u{0020}still\u{0020}has\u{0020}to\u{0020}walk\u{0020}is\u{0020}a\u{0020}long\u{0020}one.\n\u{3000}\u{3000}Even\u{0020}so,\u{0020}she\u{0020}is\u{0020}quite\u{0020}optimistic\u{0020}about\u{0020}her\u{0020}future,\u{0020}and\u{0020}she\u{0020}has\u{0020}never\u{0020}once\u{0020}doubted\u{0020}that\u{0020}she\u{0020}can\u{0020}keep\u{0020}going.\u{0020}A\u{0020}certain\u{0020}conviction\u{0020}has\u{0020}become\u{0020}the\u{0020}pillar\u{0020}supporting\u{0020}her\u{0020}heart.\n\u{3000}\u{3000}\"I\u{0020}owe\u{0020}that\u{0020}person\u{0020}an\u{0020}enormous\u{0020}debt\u{0020}of\u{0020}gratitude.\u{0020}If\u{0020}I\u{0020}want\u{0020}to\u{0020}repay\u{0020}it,\u{0020}then\u{0020}I\u{0020}have\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}who\u{0020}can\u{0020}fight\u{0020}by\u{0020}his\u{0020}side.\"", "0", "0", "0", "0", 11049, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[614904] = {614904, 2000, "\u{3000}\u{3000}Late\u{0020}at\u{0020}night,\u{0020}in\u{0020}the\u{0020}stillness\u{0020}of\u{0020}silence,\u{0020}she\u{0020}finds\u{0020}herself\u{0020}missing\u{0020}a\u{0020}past\u{0020}so\u{0020}hazy\u{0020}and\u{0020}dreamlike\u{0020}it\u{0020}almost\u{0020}feels\u{0020}unreal.\n\u{3000}\u{3000}In\u{0020}that\u{0020}cherished\u{0020}past,\u{0020}she\u{0020}once\u{0020}had\u{0020}a\u{0020}friend\u{0020}with\u{0020}whom\u{0020}she\u{0020}could\u{0020}share\u{0020}anything.\n\u{3000}\u{3000}But\u{0020}when\u{0020}her\u{0020}memories\u{0020}reach\u{0020}the\u{0020}end,\u{0020}she\u{0020}remembers\u{0020}that\u{0020}the\u{0020}friend\u{0020}was\u{0020}only\u{0020}a\u{0020}mirror.\n\u{3000}\u{3000}And\u{0020}the\u{0020}only\u{0020}person\u{0020}reflected\u{0020}in\u{0020}that\u{0020}mirror\u{0020}was\u{0020}herself.\n\u{3000}\u{3000}When\u{0020}she\u{0020}was\u{0020}drowned\u{0020}by\u{0020}that\u{0020}loneliness\u{0020}surging\u{0020}over\u{0020}her\u{0020}like\u{0020}a\u{0020}tide,\u{0020}someone\u{0020}reached\u{0020}out\u{0020}a\u{0020}hand\u{0020}to\u{0020}her.\n\u{3000}\u{3000}She\u{0020}knows\u{0020}that\u{0020}to\u{0020}the\u{0020}other\u{0020}person,\u{0020}it\u{0020}may\u{0020}not\u{0020}have\u{0020}seemed\u{0020}like\u{0020}such\u{0020}an\u{0020}important\u{0020}thing.\n\u{3000}\u{3000}But\u{0020}to\u{0020}her,\u{0020}a\u{0020}hand\u{0020}extended\u{0020}at\u{0020}that\u{0020}moment\u{0020}meant\u{0020}everything.\n\u{3000}\u{3000}To\u{0020}keep\u{0020}holding\u{0020}on\u{0020}to\u{0020}that\u{0020}hand\u{0020}forever,\u{0020}she\u{0020}would\u{0020}be\u{0020}willing\u{0020}to\u{0020}do\u{0020}anything.\n\u{3000}\u{3000}Without\u{0020}ever\u{0020}regretting\u{0020}it.", "0", "0", "0", "0", 11049, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
