[615001] = {615001, 100, "Bolina's\u{0020}newfound\u{0020}power\u{0020}brought\u{0020}her\u{0020}an\u{0020}increase\u{0020}in\u{0020}strength,\u{0020}but\u{0020}did\u{0020}not\u{0020}return\u{0020}her\u{0020}maturity.\u{0020}Even\u{0020}after\u{0020}becoming\u{0020}an\u{0020}\"angel,\"\u{0020}her\u{0020}mind\u{0020}remained\u{0020}childlike—innocent\u{0020}and\u{0020}pure.This\u{0020}wasn't\u{0020}necessarily\u{0020}a\u{0020}bad\u{0020}thing,\u{0020}as\u{0020}it\u{0020}allowed\u{0020}those\u{0020}around\u{0020}her\u{0020}to\u{0020}continue\u{0020}interacting\u{0020}with\u{0020}her\u{0020}as\u{0020}they\u{0020}always\u{0020}had.\n\nYet,\u{0020}there\u{0020}is\u{0020}no\u{0020}denying\u{0020}Bolina's\u{0020}new\u{0020}extraordinary\u{0020}potential.\u{0020}With\u{0020}a\u{0020}Compatibility\u{0020}Rate\u{0020}approaching\u{0020}100%—a\u{0020}threshold\u{0020}that\u{0020}pushes\u{0020}even\u{0020}the\u{0020}boundaries\u{0020}of\u{0020}human\u{0020}science\u{0020}and\u{0020}ethics,\u{0020}She\u{0020}is\u{0020}destined\u{0020}to\u{0020}become\u{0020}an\u{0020}ace\u{0020}Driver\u{0020}for\u{0020}both\u{0020}Ember\u{0020}Squad\u{0020}and\u{0020}Katya.\n\nThe\u{0020}\"Super-Gigantification\"\u{0020}that\u{0020}occurred\u{0020}during\u{0020}her\u{0020}first\u{0020}transformation\u{0020}after\u{0020}receiving\u{0020}the\u{0020}\"Paradise\u{0020}Serum,\"\u{0020}did\u{0020}not\u{0020}appear\u{0020}in\u{0020}subsequent\u{0020}transformations.\u{0020}It\u{0020}is\u{0020}suspected\u{0020}to\u{0020}be\u{0020}either\u{0020}a\u{0020}side\u{0020}effect\u{0020}of\u{0020}the\u{0020}initial\u{0020}injection\u{0020}or\u{0020}a\u{0020}one-time\u{0020}miracle.\n\nPerhaps\u{0020}that's\u{0020}the\u{0020}best\u{0020}phrase\u{0020}that\u{0020}can\u{0020}be\u{0020}used\u{0020}to\u{0020}describe\u{0020}Bolina\u{0020}right\u{0020}now,\u{0020}a\u{0020}living,\u{0020}walking\u{0020}miracle.", "0", "0", "0", "0", 11050, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615002] = {615002, 500, "No\u{0020}one\u{0020}could\u{0020}have\u{0020}foreseen\u{0020}the\u{0020}Angel\u{0020}Project\u{0020}succeeding\u{0020}under\u{0020}such\u{0020}circumstances.\n\nIf\u{0020}the\u{0020}researchers\u{0020}who\u{0020}originally\u{0020}spearheaded\u{0020}the\u{0020}project\u{0020}could\u{0020}rise\u{0020}from\u{0020}their\u{0020}graves,\u{0020}they\u{0020}might\u{0020}triumphantly\u{0020}wave\u{0020}their\u{0020}decayed\u{0020}fingers\u{0020}and\u{0020}exclaim:\n\n\"See?\u{0020}We\u{0020}were\u{0020}right!!!\"\n\nOf\u{0020}course,\u{0020}they\u{0020}would\u{0020}never\u{0020}acknowledge\u{0020}the\u{0020}children\u{0020}who\u{0020}died\u{0020}during\u{0020}the\u{0020}transformation\u{0020}surgeries—the\u{0020}\"true\u{0020}angels\"\u{0020}sacrificed\u{0020}to\u{0020}create\u{0020}one\u{0020}\"real\u{0020}angel,\"\u{0020}the\u{0020}reason\u{0020}those\u{0020}researchers\u{0020}lie\u{0020}in\u{0020}their\u{0020}graves\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\n\nAfter\u{0020}all,\u{0020}the\u{0020}\"paradise\"\u{0020}humanity\u{0020}sought\u{0020}can\u{0020}never\u{0020}be\u{0020}built\u{0020}on\u{0020}the\u{0020}suffering\u{0020}of\u{0020}others.\n\nBolina\u{0020}remained\u{0020}oblivious\u{0020}to\u{0020}these\u{0020}grim\u{0020}truths,\u{0020}her\u{0020}pure\u{0020}heart\u{0020}still\u{0020}as\u{0020}untouched\u{0020}as\u{0020}a\u{0020}white\u{0020}cloud\u{0020}in\u{0020}a\u{0020}clear\u{0020}sky—clean,\u{0020}simple,\u{0020}and\u{0020}untainted.\n\nWhether\u{0020}a\u{0020}congenital\u{0020}trait\u{0020}or\u{0020}a\u{0020}side\u{0020}effect\u{0020}of\u{0020}the\u{0020}transformation,\u{0020}one\u{0020}thing\u{0020}is\u{0020}for\u{0020}sure,\u{0020}her\u{0020}heart\u{0020}of\u{0020}gold\u{0020}is\u{0020}truly\u{0020}a\u{0020}blessing\u{0020}upon\u{0020}this\u{0020}world.\u{0020}Perhaps\u{0020}that\u{0020}is\u{0020}also\u{0020}the\u{0020}secret\u{0020}to\u{0020}becoming\u{0020}an\u{0020}angel\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\n\nAfter\u{0020}comparing\u{0020}Bolina's\u{0020}complete\u{0020}data\u{0020}with\u{0020}the\u{0020}archived\u{0020}results\u{0020}of\u{0020}the\u{0020}Angel\u{0020}Project,\u{0020}the\u{0020}First\u{0020}Laboratory\u{0020}concluded\u{0020}that\u{0020}the\u{0020}\"success\"\u{0020}of\u{0020}the\u{0020}Angel\u{0020}Project\u{0020}could\u{0020}not\u{0020}be\u{0020}replicated\u{0020}again.\u{0020}Furthermore,\u{0020}humanity\u{0020}ill\u{0020}needs\u{0020}such\u{0020}cruel\u{0020}methods\u{0020}to\u{0020}create\u{0020}weapons\u{0020}against\u{0020}the\u{0020}Sins.\n\n\u{0020}\u{0020}Bolina\u{0020}will\u{0020}always\u{0020}be\u{0020}the\u{0020}first\u{0020}and\u{0020}last\u{0020}\"real\u{0020}angel.\"", "0", "0", "0", "0", 11050, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615003] = {615003, 1000, "The\u{0020}greatest\u{0020}mystery\u{0020}surrounding\u{0020}Bolina\u{0020}remains\u{0020}the\u{0020}\"Super-Gigantification\"\u{0020}that\u{0020}occurred\u{0020}after\u{0020}her\u{0020}first\u{0020}injection\u{0020}of\u{0020}the\u{0020}Paradise\u{0020}Serum.\n\nHer\u{0020}size\u{0020}increased\u{0020}to\u{0020}three\u{0020}times\u{0020}that\u{0020}of\u{0020}a\u{0020}normal\u{0020}Driver,\u{0020}far\u{0020}exceeding\u{0020}the\u{0020}intended\u{0020}limits\u{0020}of\u{0020}the\u{0020}Gigantification\u{0020}technology.\u{0020}Whether\u{0020}this\u{0020}immense\u{0020}size\u{0020}translated\u{0020}to\u{0020}greater\u{0020}combat\u{0020}power\u{0020}remained\u{0020}unclear,\u{0020}but\u{0020}at\u{0020}least\u{0020}continued\u{0020}observations\u{0020}confirmed\u{0020}that\u{0020}her\u{0020}body\u{0020}did\u{0020}not\u{0020}suffer\u{0020}any\u{0020}adverse\u{0020}side\u{0020}effects.\n\nIn\u{0020}subsequent\u{0020}transformations,\u{0020}Bolina\u{0020}never\u{0020}experienced\u{0020}\"Super-Gigantification\"\u{0020}again.\u{0020}Analysis\u{0020}of\u{0020}the\u{0020}Paradise\u{0020}Serum\u{0020}uncovered\u{0020}no\u{0020}specific\u{0020}component\u{0020}that\u{0020}could\u{0020}logically\u{0020}explain\u{0020}the\u{0020}phenomenon.\n\nResearch\u{0020}into\u{0020}the\u{0020}matter\u{0020}was\u{0020}discontinued\u{0020}after\u{0020}only\u{0020}a\u{0020}few\u{0020}months,\u{0020}with\u{0020}most\u{0020}scientists\u{0020}at\u{0020}the\u{0020}First\u{0020}Laboratory\u{0020}regarding\u{0020}the\u{0020}event\u{0020}as\u{0020}a\u{0020}one-time\u{0020}miracle.\n\nIt\u{0020}is\u{0020}rumored\u{0020}that\u{0020}some\u{0020}misguided\u{0020}scientists\u{0020}went\u{0020}so\u{0020}far\u{0020}as\u{0020}to\u{0020}privately\u{0020}worship\u{0020}Bolina's\u{0020}\"Super-Gigantification\"\u{0020}as\u{0020}a\u{0020}divine\u{0020}omen.", "0", "0", "0", "0", 11050, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615004] = {615004, 2000, "With\u{0020}six\u{0020}pairs\u{0020}of\u{0020}graceful\u{0020}wings,\n\nthe\u{0020}blade\u{0020}and\u{0020}gun\u{0020}glowed\u{0020}with\u{0020}heavenly\u{0020}light\u{0020}in\u{0020}her\u{0020}hands.\n\nMoving\u{0020}seamlessly\u{0020}between\u{0020}the\u{0020}heavens\u{0020}and\u{0020}the\u{0020}earth,\n\nshe\u{0020}cuts\u{0020}through\u{0020}her\u{0020}enemy's\u{0020}menacing\u{0020}claws\n\nand\u{0020}pierces\u{0020}through\u{0020}their\u{0020}armor\u{0020}with\u{0020}unwavering\u{0020}precision.\n\nLike\u{0020}a\u{0020}celestial\u{0020}being,\n\nshe\u{0020}delivers\u{0020}the\u{0020}gospel\u{0020}of\u{0020}victory\u{0020}to\u{0020}all.\n\nAs\u{0020}she\u{0020}gently\u{0020}lands\u{0020}beside\u{0020}you,\n\nher\u{0020}face\u{0020}lights\u{0020}up\u{0020}with\u{0020}a\u{0020}childlike\u{0020}smile,\n\nand\u{0020}she\u{0020}softly\u{0020}asks,\n\n\"Navigator,\u{0020}when\u{0020}can\u{0020}I\u{0020}have\u{0020}some\u{0020}candy?\"", "0", "0", "0", "0", 11050, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[615100] = {615100, 0, "[Name]:\u{0020}Julius\u{0020}von\u{0020}Nietzsche\u{0020}\n[B-day]:\u{0020}October\u{0020}27\u{0020}\n[Core\u{0020}Compatibility]:\u{0020}<color=#FF6100>100%</color>\u{0020}\n[Height]:\u{0020}29m\u{0020}\n[Squad]:\u{0020}Romance\u{0020}Unconfirmed\u{0020}\n[Affiliation]:\u{0020}Stephanie\u{0020}/\u{0020}Danube\u{0020}Branch\u{0020}\n[Interest]:\u{0020}Enjoys\u{0020}soaking\u{0020}in\u{0020}hot\u{0020}water\u{0020}at\u{0020}43°C.", "0", "0", "0", "0", 11051, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[615101] = {615101, 100, "\u{3000}\u{3000}A\u{0020}gallant\u{0020}young\u{0020}lady\u{0020}who\u{0020}treats\u{0020}honor\u{0020}as\u{0020}her\u{0020}very\u{0020}life\u{0020}and\u{0020}upholds\u{0020}the\u{0020}dignity\u{0020}of\u{0020}a\u{0020}true\u{0020}gentleman.\u{0020}Whether\u{0020}in\u{0020}battle\u{0020}or\u{0020}in\u{0020}daily\u{0020}life,\u{0020}she\u{0020}was\u{0020}once\u{0020}an\u{0020}admirable\u{0020}senior\u{0020}figure.\n\u{3000}\u{3000}However,\u{0020}all\u{0020}of\u{0020}that\u{0020}is\u{0020}already\u{0020}in\u{0020}the\u{0020}past.\u{0020}Now\u{0020}there\u{0020}is\u{0020}a\u{0020}mysterious\u{0020}girl\u{0020}who\u{0020}suddenly\u{0020}appeared\u{0020}under\u{0020}the\u{0020}alias\u{0020}Arthur\u{0020}Pendragon\u{0020}and\u{0020}remains\u{0020}constantly\u{0020}by\u{0020}the\u{0020}Navigator's\u{0020}side.\n\u{3000}\u{3000}And\u{0020}furthermore,\u{0020}she\u{0020}shares\u{0020}an\u{0020}extremely\u{0020}close\u{0020}relationship\u{0020}with\u{0020}the\u{0020}Navigator.\u{0020}In\u{0020}the\u{0020}eyes\u{0020}of\u{0020}others,\u{0020}she\u{0020}is\u{0020}nothing\u{0020}short\u{0020}of\u{0020}a\u{0020}classic\u{0020}heaven-sent\u{0020}beauty.\u{0020}And\u{0020}judging\u{0020}by\u{0020}how\u{0020}familiar\u{0020}the\u{0020}Navigator\u{0020}seems\u{0020}with\u{0020}Arthur,\u{0020}she\u{0020}might\u{0020}even\u{0020}belong\u{0020}to\u{0020}the\u{0020}rarer\u{0020}category\u{0020}of\u{0020}a\u{0020}heaven-sent\u{0020}childhood-friend\u{0020}type.\n\u{3000}\u{3000}And\u{0020}furthermore,\u{0020}and\u{0020}furthermore,\u{0020}for\u{0020}some\u{0020}reason,\u{0020}Arthur\u{0020}Pendragon\u{0020}is\u{0020}always\u{0020}wearing\u{0020}a\u{0020}wedding\u{0020}dress,\u{0020}which,\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}the\u{0020}other\u{0020}Drivers,\u{0020}is\u{0020}practically\u{0020}a\u{0020}declaration\u{0020}of\u{0020}ownership\u{0020}over\u{0020}the\u{0020}Navigator\u{0020}to\u{0020}everyone\u{0020}else.", "0", "0", "0", "0", 11051, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615102] = {615102, 500, "\u{3000}\u{3000}Whether\u{0020}in\u{0020}terms\u{0020}of\u{0020}her\u{0020}actual\u{0020}position\u{0020}in\u{0020}reality\u{0020}or\u{0020}her\u{0020}status,\u{0020}she\u{0020}has\u{0020}never\u{0020}been\u{0020}this\u{0020}close\u{0020}to\u{0020}the\u{0020}Navigator\u{0020}before.\u{0020}The\u{0020}girl\u{0020}named\u{0020}Julius\u{0020}had\u{0020}never\u{0020}stood\u{0020}in\u{0020}such\u{0020}a\u{0020}place.\n\u{3000}\u{3000}Or\u{0020}rather,\u{0020}in\u{0020}order\u{0020}to\u{0020}return\u{0020}to\u{0020}her\u{0020}original\u{0020}self,\u{0020}she\u{0020}has\u{0020}already\u{0020}experienced\u{0020}many\u{0020}things\u{0020}she\u{0020}never\u{0020}had\u{0020}before,\u{0020}such\u{0020}as—nestling\u{0020}in\u{0020}the\u{0020}Navigator's\u{0020}arms.\n\u{3000}\u{3000}The\u{0020}Navigator\u{0020}is\u{0020}extremely\u{0020}popular\u{0020}among\u{0020}the\u{0020}Drivers,\u{0020}especially\u{0020}with\u{0020}children.\u{0020}This\u{0020}can\u{0020}be\u{0020}seen\u{0020}from\u{0020}how\u{0020}there\u{0020}are\u{0020}often\u{0020}kids\u{0020}coming\u{0020}to\u{0020}sit\u{0020}in\u{0020}his\u{0020}arms\u{0020}to\u{0020}play\u{0020}with\u{0020}him\u{0020}(such\u{0020}as\u{0020}Skadi,\u{0020}Suzu,\u{0020}Mirai,\u{0020}Odora...\u{0020}and\u{0020}so\u{0020}on).\u{0020}The\u{0020}children\u{0020}shout\u{0020}embarrassing\u{0020}things\u{0020}like\u{0020}\"bride\",\u{0020}\"marriage\",\u{0020}\"I\u{0020}like\u{0020}the\u{0020}Navigator\",\u{0020}\"the\u{0020}whole\u{0020}life\",\u{0020}and\u{0020}no\u{0020}matter\u{0020}what\u{0020}the\u{0020}Navigator\u{0020}is\u{0020}doing,\u{0020}they\u{0020}can\u{0020}naturally\u{0020}settle\u{0020}into\u{0020}his\u{0020}arms,\u{0020}as\u{0020}if\u{0020}becoming\u{0020}one\u{0020}with\u{0020}him.\n\u{3000}\u{3000}Every\u{0020}time\u{0020}she\u{0020}sees\u{0020}such\u{0020}scenes,\u{0020}and\u{0020}then\u{0020}watches\u{0020}the\u{0020}Navigator,\u{0020}unable\u{0020}to\u{0020}handle\u{0020}the\u{0020}children's\u{0020}antics,\u{0020}turn\u{0020}to\u{0020}her\u{0020}for\u{0020}help,\u{0020}Julius\u{0020}shows\u{0020}a\u{0020}relieved\u{0020}smile.\u{0020}She\u{0020}turns\u{0020}these\u{0020}moments\u{0020}of\u{0020}warmth\u{0020}into\u{0020}her\u{0020}own\u{0020}motivation,\u{0020}urging\u{0020}herself\u{0020}forward.\n\u{3000}\u{3000}And\u{0020}so,\u{0020}she\u{0020}never\u{0020}imagined\u{0020}that\u{0020}one\u{0020}day\u{0020}she\u{0020}herself\u{0020}would\u{0020}sit\u{0020}in\u{0020}the\u{0020}Navigator's\u{0020}arms\u{0020}like\u{0020}a\u{0020}child.\u{0020}All\u{0020}of\u{0020}this\u{0020}is\u{0020}for\u{0020}treating\u{0020}her\u{0020}condition,\u{0020}absolutely\u{0020}not...\u{0020}because\u{0020}she\u{0020}is\u{0020}very\u{0020}happy.\n\u{3000}\u{3000}\"My\u{0020}arm,\u{0020}my\u{0020}arm\u{0020}keeps\u{0020}brushing\u{0020}against\u{0020}the\u{0020}edge\u{0020}of\u{0020}his\u{0020}chest...\u{0020}the\u{0020}Navigator\u{0020}doesn't\u{0020}seem\u{0020}to\u{0020}notice...\u{0020}sh-should\u{0020}I\u{0020}remind\u{0020}him?\u{0020}But\u{0020}would\u{0020}it\u{0020}be\u{0020}inappropriate\u{0020}to\u{0020}bring\u{0020}it\u{0020}up?\u{0020}The\u{0020}Navigator\u{0020}is\u{0020}already\u{0020}cooperating\u{0020}with\u{0020}my\u{0020}treatment...\u{0020}would\u{0020}saying\u{0020}this\u{0020}make\u{0020}it\u{0020}seem\u{0020}like\u{0020}I\u{0020}am\u{0020}unwilling?\u{0020}No...\u{0020}this\u{0020}is\u{0020}definitely\u{0020}not\u{0020}right...\u{0020}but\u{0020}the\u{0020}Navigator\u{0020}probably\u{0020}isn't\u{0020}doing\u{0020}it\u{0020}on\u{0020}purpose...\"\n\u{3000}\u{3000}Blushing\u{0020}and\u{0020}flustered\u{0020}reactions\u{0020}are\u{0020}only\u{0020}natural.\u{0020}This\u{0020}scene\u{0020}was\u{0020}witnessed\u{0020}by\u{0020}many\u{0020}Drivers\u{0020}who\u{0020}came\u{0020}to\u{0020}the\u{0020}command\u{0020}room,\u{0020}becoming\u{0020}irrefutable\u{0020}evidence\u{0020}fueling\u{0020}the\u{0020}rumor\u{0020}that\u{0020}\"the\u{0020}Navigator\u{0020}is\u{0020}going\u{0020}to\u{0020}marry\u{0020}his\u{0020}heaven-sent\u{0020}childhood\u{0020}friend.\"", "0", "0", "0", "0", 11051, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615103] = {615103, 1000, "\u{3000}\u{3000}Julius\u{0020}cannot\u{0020}figure\u{0020}it\u{0020}out.\n\u{3000}\u{3000}Why\u{0020}the\u{0020}Drivers\u{0020}keep\u{0020}probing\u{0020}her,\u{0020}openly\u{0020}yet\u{0020}subtly.\u{0020}Why\u{0020}everyone\u{0020}stops\u{0020}talking\u{0020}the\u{0020}moment\u{0020}they\u{0020}see\u{0020}her.\u{0020}Why.\u{0020}Has\u{0020}she\u{0020}become\u{0020}strange?\u{0020}Or\u{0020}is\u{0020}this\u{0020}outfit\u{0020}simply\u{0020}too\u{0020}eye-catching?\n\u{3000}\u{3000}Interacting\u{0020}with\u{0020}everyone\u{0020}under\u{0020}a\u{0020}brand-new\u{0020}identity\u{0020}is\u{0020}a\u{0020}novel\u{0020}experience,\u{0020}but\u{0020}Julius\u{0020}does\u{0020}not\u{0020}hold\u{0020}herself\u{0020}back.\u{0020}She\u{0020}lifts\u{0020}her\u{0020}wedding\u{0020}dress\u{0020}and\u{0020}openly\u{0020}greets\u{0020}the\u{0020}Drivers\u{0020}who\u{0020}are\u{0020}whispering\u{0020}among\u{0020}themselves,\u{0020}then\u{0020}seamlessly\u{0020}blends\u{0020}in\u{0020}with\u{0020}them.\n\u{3000}\u{3000}Surely,\u{0020}after\u{0020}spending\u{0020}some\u{0020}time\u{0020}interacting\u{0020}with\u{0020}her,\u{0020}everyone\u{0020}will\u{0020}be\u{0020}able\u{0020}to\u{0020}guess\u{0020}that\u{0020}the\u{0020}\"Arthur\u{0020}Pendragon\"\u{0020}before\u{0020}them\u{0020}is\u{0020}in\u{0020}fact\u{0020}the\u{0020}long-absent\u{0020}\"Julius\u{0020}von\u{0020}Nietzsche\".\u{0020}When\u{0020}that\u{0020}happens,\u{0020}the\u{0020}so-called\u{0020}rumors\u{0020}should\u{0020}collapse\u{0020}on\u{0020}their\u{0020}own.\n\u{3000}\u{3000}But\u{0020}rumors\u{0020}are\u{0020}rumors.\u{0020}There\u{0020}is\u{0020}something\u{0020}else\u{0020}Julius\u{0020}cannot\u{0020}make\u{0020}sense\u{0020}of.\n\u{3000}\u{3000}Today,\u{0020}just\u{0020}like\u{0020}always,\u{0020}she\u{0020}pushes\u{0020}open\u{0020}that\u{0020}door\u{0020}and\u{0020}steps\u{0020}into\u{0020}that\u{0020}room,\u{0020}where\u{0020}the\u{0020}person\u{0020}she\u{0020}longs\u{0020}to\u{0020}see\u{0020}awaits.\u{0020}When\u{0020}it\u{0020}comes\u{0020}to\u{0020}these\u{0020}feelings,\u{0020}is\u{0020}it\u{0020}that\u{0020}she\u{0020}cannot\u{0020}understand\u{0020}them,\u{0020}or\u{0020}that\u{0020}she\u{0020}refuses\u{0020}to\u{0020}understand\u{0020}them?\u{0020}The\u{0020}answer,\u{0020}and\u{0020}the\u{0020}taste\u{0020}of\u{0020}it,\u{0020}is\u{0020}something\u{0020}only\u{0020}she\u{0020}herself\u{0020}can\u{0020}know.", "0", "0", "0", "0", 11051, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615104] = {615104, 2000, "\u{3000}\u{3000}One\u{0020}day,\n\u{3000}\u{3000}perhaps\u{0020}tomorrow,\u{0020}perhaps\u{0020}on\u{0020}some\u{0020}distant\u{0020}day\u{0020}far\u{0020}in\u{0020}the\u{0020}future,\n\u{3000}\u{3000}I\u{0020}will\u{0020}reclaim\u{0020}my\u{0020}original\u{0020}form.\n\u{3000}\u{3000}When\u{0020}that\u{0020}moment\u{0020}finally\u{0020}arrives,\n\u{3000}\u{3000}what\u{0020}expression\u{0020}should\u{0020}I\u{0020}wear\u{0020}when\u{0020}facing\u{0020}you,\u{0020}and\u{0020}myself?\n\u{3000}\u{3000}But\u{0020}for\u{0020}now,\n\u{3000}\u{3000}please\u{0020}allow\u{0020}me,\u{0020}like\u{0020}Cinderella,\n\u{3000}\u{3000}before\u{0020}the\u{0020}clock\u{0020}strikes\u{0020}twelve\u{0020}at\u{0020}midnight,\n\u{3000}\u{3000}to\u{0020}stay\u{0020}by\u{0020}my\u{0020}prince's\u{0020}side\u{0020}just\u{0020}a\u{0020}little\u{0020}longer.", "0", "0", "0", "0", 11051, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
