[615201] = {615201, 100, "\u{3000}\u{3000}No\u{0020}one\u{0020}knows\u{0020}where\u{0020}Spes\u{0020}came\u{0020}from.\n\u{3000}\u{3000}She\u{0020}is\u{0020}like\u{0020}a\u{0020}ghost\u{0020}with\u{0020}no\u{0020}source,\u{0020}no\u{0020}history,\u{0020}and\u{0020}no\u{0020}origin,\u{0020}wandering\u{0020}across\u{0020}this\u{0020}dying\u{0020}land.\n\u{3000}\u{3000}Her\u{0020}overly\u{0020}sharp\u{0020}gaze\u{0020}is\u{0020}filled\u{0020}with\u{0020}the\u{0020}aggression\u{0020}of\u{0020}a\u{0020}wild\u{0020}animal.\u{0020}To\u{0020}give\u{0020}a\u{0020}fitting\u{0020}example,\u{0020}she\u{0020}is\u{0020}like\u{0020}a\u{0020}lone\u{0020}wolf\u{0020}abandoned\u{0020}by\u{0020}its\u{0020}pack.\u{0020}Her\u{0020}personality,\u{0020}so\u{0020}arrogant\u{0020}that\u{0020}it\u{0020}could\u{0020}almost\u{0020}be\u{0020}described\u{0020}as\u{0020}\"self-supreme,\"\u{0020}only\u{0020}strengthens\u{0020}that\u{0020}impression.\n\u{3000}\u{3000}Spes\u{0020}does\u{0020}not\u{0020}like\u{0020}working\u{0020}with\u{0020}others,\u{0020}nor\u{0020}is\u{0020}she\u{0020}good\u{0020}at\u{0020}it.\u{0020}In\u{0020}her\u{0020}own\u{0020}words,\u{0020}\"Only\u{0020}strength\u{0020}that\u{0020}does\u{0020}not\u{0020}rely\u{0020}on\u{0020}others\u{0020}is\u{0020}true\u{0020}strength.\"\n\u{3000}\u{3000}For\u{0020}someone\u{0020}whose\u{0020}goal\u{0020}is\u{0020}to\u{0020}save\u{0020}the\u{0020}world,\u{0020}such\u{0020}a\u{0020}solitary\u{0020}personality\u{0020}can\u{0020}hardly\u{0020}be\u{0020}called\u{0020}an\u{0020}advantage--\u{0020}but\u{0020}Spes\u{0020}herself\u{0020}does\u{0020}not\u{0020}mind.\n\u{3000}\u{3000}Saving\u{0020}the\u{0020}world\u{0020}is\u{0020}something\u{0020}I\u{0020}can\u{0020}do\u{0020}alone.\u{0020}That\u{0020}is\u{0020}probably\u{0020}what\u{0020}she\u{0020}would\u{0020}say.\u{0020}However,\u{0020}why\u{0020}she\u{0020}chose\u{0020}saving\u{0020}the\u{0020}world,\u{0020}especially\u{0020}in\u{0020}this\u{0020}era\u{0020}where\u{0020}hope\u{0020}is\u{0020}almost\u{0020}impossible,\u{0020}as\u{0020}her\u{0020}goal\u{0020}remains\u{0020}an\u{0020}unsolved\u{0020}mystery.\n\u{3000}\u{3000}Even\u{0020}if\u{0020}one\u{0020}were\u{0020}to\u{0020}ask\u{0020}her\u{0020}directly,\u{0020}it\u{0020}would\u{0020}probably\u{0020}be\u{0020}impossible\u{0020}to\u{0020}get\u{0020}a\u{0020}satisfying\u{0020}answer.\u{0020}Simply\u{0020}surviving\u{0020}her\u{0020}blunt\u{0020}personality\u{0020}without\u{0020}choking\u{0020}on\u{0020}it\u{0020}would\u{0020}already\u{0020}be\u{0020}a\u{0020}stroke\u{0020}of\u{0020}luck.", "0", "0", "0", "0", 11052, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615202] = {615202, 500, "\u{3000}\u{3000}Pandora\u{0020}Engine.\n\u{3000}\u{3000}In\u{0020}Spes's\u{0020}own\u{0020}words,\u{0020}it\u{0020}is\u{0020}a\u{0020}piece\u{0020}of\u{0020}equipment\u{0020}that\u{0020}has\u{0020}been\u{0020}by\u{0020}her\u{0020}side\u{0020}ever\u{0020}since\u{0020}she\u{0020}was\u{0020}born.\n\u{3000}\u{3000}Considering\u{0020}her\u{0020}special\u{0020}constitution,\u{0020}perhaps\u{0020}that\u{0020}is\u{0020}not\u{0020}a\u{0020}lie.\n\u{3000}\u{3000}More\u{0020}than\u{0020}half\u{0020}of\u{0020}Spes's\u{0020}body\u{0020}is\u{0020}composed\u{0020}of\u{0020}pure\u{0020}Nimbus\u{0020}energy.\u{0020}In\u{0020}other\u{0020}words,\u{0020}compared\u{0020}to\u{0020}a\u{0020}human,\u{0020}she\u{0020}is\u{0020}closer\u{0020}to\u{0020}a\u{0020}Sin.\n\u{3000}\u{3000}And\u{0020}that\u{0020}item,\u{0020}whose\u{0020}appearance\u{0020}resembles\u{0020}\"StarChange,\"\u{0020}does\u{0020}not\u{0020}function\u{0020}by\u{0020}injecting\u{0020}Nimbus\u{0020}energy\u{0020}like\u{0020}Astral\u{0020}Shift\u{0020}does.\u{0020}Instead,\u{0020}it\u{0020}activates\u{0020}the\u{0020}Nimbus\u{0020}energy\u{0020}that\u{0020}makes\u{0020}up\u{0020}Spes's\u{0020}body.\n\u{3000}\u{3000}In\u{0020}other\u{0020}words,\u{0020}Spes's\u{0020}existence\u{0020}is\u{0020}closer\u{0020}to\u{0020}that\u{0020}of\u{0020}the\u{0020}Midyr\u{0020}people\u{0020}from\u{0020}twenty\u{0020}years\u{0020}ago.\u{0020}Her\u{0020}giant\u{0020}form\u{0020}is\u{0020}merely\u{0020}another\u{0020}life-form\u{0020}of\u{0020}Spes.\n\u{3000}\u{3000}That\u{0020}is\u{0020}also\u{0020}why\u{0020}she\u{0020}never\u{0020}considers\u{0020}how\u{0020}long\u{0020}she\u{0020}can\u{0020}maintain\u{0020}her\u{0020}giant\u{0020}form.\n\u{3000}\u{3000}As\u{0020}long\u{0020}as\u{0020}she\u{0020}lives\u{0020}in\u{0020}this\u{0020}world\u{0020}that\u{0020}has\u{0020}already\u{0020}been\u{0020}occupied\u{0020}by\u{0020}Sins,\u{0020}the\u{0020}Nimbus\u{0020}energy\u{0020}that\u{0020}makes\u{0020}up\u{0020}her\u{0020}body\u{0020}can\u{0020}continuously\u{0020}replenish\u{0020}her.\n\u{3000}\u{3000}In\u{0020}a\u{0020}sense,\u{0020}she\u{0020}is\u{0020}truly\u{0020}immortal.\u{0020}In\u{0020}exchange,\u{0020}however,\u{0020}the\u{0020}wounds\u{0020}that\u{0020}appear\u{0020}while\u{0020}she\u{0020}is\u{0020}giant\u{0020}will\u{0020}not\u{0020}completely\u{0020}disappear\u{0020}even\u{0020}when\u{0020}she\u{0020}returns\u{0020}to\u{0020}normal\u{0020}human\u{0020}size.\n\u{3000}\u{3000}As\u{0020}for\u{0020}why\u{0020}she\u{0020}possesses\u{0020}such\u{0020}a\u{0020}constitution,\u{0020}it\u{0020}is\u{0020}naturally\u{0020}closely\u{0020}connected\u{0020}to\u{0020}her\u{0020}birth.\u{0020}Once\u{0020}the\u{0020}secret\u{0020}of\u{0020}her\u{0020}birth\u{0020}is\u{0020}known,\u{0020}it\u{0020}becomes\u{0020}possible\u{0020}to\u{0020}understand\u{0020}why\u{0020}she\u{0020}has\u{0020}a\u{0020}constitution\u{0020}so\u{0020}perfectly\u{0020}adapted\u{0020}to\u{0020}this\u{0020}era.\n\u{3000}\u{3000}Only\u{0020}someone\u{0020}with\u{0020}such\u{0020}a\u{0020}constitution\u{0020}is\u{0020}qualified\u{0020}to\u{0020}travel,\u{0020}wander,\u{0020}and\u{0020}live\u{0020}without\u{0020}a\u{0020}fixed\u{0020}home\u{0020}in\u{0020}this\u{0020}world.\n\u{3000}\u{3000}Only\u{0020}she\u{0020}has\u{0020}the\u{0020}ability\u{0020}to\u{0020}witness\u{0020}this\u{0020}world\u{0020}as\u{0020}it\u{0020}enters\u{0020}the\u{0020}countdown\u{0020}to\u{0020}destruction,\u{0020}and\u{0020}to\u{0020}witness\u{0020}how\u{0020}all\u{0020}the\u{0020}beautiful\u{0020}things\u{0020}this\u{0020}world\u{0020}once\u{0020}possessed\u{0020}have\u{0020}become\u{0020}ugly,\u{0020}inferior,\u{0020}and\u{0020}unbearable\u{0020}to\u{0020}look\u{0020}at.\n\u{3000}\u{3000}She\u{0020}is\u{0020}a\u{0020}traveling\u{0020}recorder,\u{0020}using\u{0020}her\u{0020}own\u{0020}eyes\u{0020}to\u{0020}record\u{0020}this\u{0020}world\u{0020}that\u{0020}once\u{0020}belonged\u{0020}to\u{0020}humanity.\n\u{3000}\u{3000}However,\n\u{3000}\u{3000}if\u{0020}Spes\u{0020}is\u{0020}perfectly\u{0020}adapted\u{0020}to\u{0020}this\u{0020}era,\u{0020}does\u{0020}that\u{0020}also\u{0020}mean\u{0020}that\u{0020}once\u{0020}the\u{0020}world\u{0020}returns\u{0020}to\u{0020}the\u{0020}way\u{0020}it\u{0020}originally\u{0020}was,\u{0020}a\u{0020}\"creature\"\u{0020}like\u{0020}her,\u{0020}who\u{0020}completely\u{0020}defies\u{0020}the\u{0020}laws\u{0020}of\u{0020}nature,\u{0020}will\u{0020}no\u{0020}longer\u{0020}be\u{0020}able\u{0020}to\u{0020}survive?\n\u{3000}\u{3000}She\u{0020}has\u{0020}probably\u{0020}never\u{0020}thought\u{0020}about\u{0020}that\u{0020}question.", "0", "0", "0", "0", 11052, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615203] = {615203, 1000, "\u{3000}\u{3000}As\u{0020}for\u{0020}why\u{0020}Spes\u{0020}wants\u{0020}to\u{0020}save\u{0020}the\u{0020}world.\n\u{3000}\u{3000}Because\u{0020}it\u{0020}was\u{0020}Mother's\u{0020}wish--\u{0020}that\u{0020}was\u{0020}her\u{0020}answer.\n\u{3000}\u{3000}Although\u{0020}her\u{0020}mother\u{0020}did\u{0020}not\u{0020}hope\u{0020}that\u{0020}Spes\u{0020}would\u{0020}personally\u{0020}save\u{0020}the\u{0020}world,\u{0020}but\u{0020}rather\u{0020}that\u{0020}Spes\u{0020}would\u{0020}willingly\u{0020}become\u{0020}part\u{0020}of\u{0020}saving\u{0020}the\u{0020}world,\u{0020}or\u{0020}in\u{0020}other\u{0020}words,\u{0020}one\u{0020}of\u{0020}the\u{0020}pieces\u{0020}in\u{0020}the\u{0020}plan\u{0020}to\u{0020}save\u{0020}it.\n\u{3000}\u{3000}But\u{0020}Spes\u{0020}was\u{0020}clearly\u{0020}not\u{0020}satisfied\u{0020}with\u{0020}that\u{0020}arrangement.\n\u{3000}\u{3000}She\u{0020}did\u{0020}not\u{0020}want\u{0020}to\u{0020}be\u{0020}merely\u{0020}a\u{0020}piece,\u{0020}even\u{0020}if\u{0020}she\u{0020}might\u{0020}be\u{0020}an\u{0020}indispensable\u{0020}part\u{0020}of\u{0020}the\u{0020}salvation\u{0020}plan.\n\u{3000}\u{3000}So\u{0020}she\u{0020}refused\u{0020}to\u{0020}carry\u{0020}out\u{0020}Mother's\u{0020}plan.\n\u{3000}\u{3000}She\u{0020}wanted\u{0020}to\u{0020}save\u{0020}this\u{0020}world\u{0020}in\u{0020}her\u{0020}own\u{0020}way.\u{0020}To\u{0020}find\u{0020}that\u{0020}way,\u{0020}and\u{0020}to\u{0020}find\u{0020}the\u{0020}ultimate\u{0020}meaning\u{0020}of\u{0020}why\u{0020}she\u{0020}was\u{0020}born\u{0020}into\u{0020}this\u{0020}world,\u{0020}namely\u{0020}what\u{0020}she\u{0020}was\u{0020}born\u{0020}for\u{0020}and\u{0020}what\u{0020}she\u{0020}would\u{0020}die\u{0020}for,\u{0020}she\u{0020}began\u{0020}her\u{0020}journey.\n\u{3000}\u{3000}At\u{0020}the\u{0020}end\u{0020}of\u{0020}that\u{0020}journey\u{0020}lies\u{0020}the\u{0020}destruction\u{0020}of\u{0020}the\u{0020}world,\u{0020}or\u{0020}the\u{0020}end\u{0020}of\u{0020}life,\u{0020}or\u{0020}perhaps\u{0020}the\u{0020}birth\u{0020}of\u{0020}new\u{0020}hope.\n\u{3000}\u{3000}When\u{0020}she\u{0020}saw\u{0020}that\u{0020}person\u{0020}appear\u{0020}just\u{0020}as\u{0020}the\u{0020}prophecy\u{0020}foretold,\u{0020}she\u{0020}knew\u{0020}the\u{0020}answer.\n\u{3000}\u{3000}And\u{0020}at\u{0020}that\u{0020}moment,\u{0020}she\u{0020}knew\u{0020}that\u{0020}her\u{0020}journey\u{0020}would\u{0020}come\u{0020}to\u{0020}an\u{0020}end.", "0", "0", "0", "0", 11052, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615204] = {615204, 2000, "\u{3000}\u{3000}To\u{0020}her,\u{0020}death\u{0020}seems\u{0020}to\u{0020}be\u{0020}an\u{0020}unavoidable\u{0020}question.\n\u{3000}\u{3000}When\u{0020}she\u{0020}chose\u{0020}this\u{0020}path\u{0020}of\u{0020}the\u{0020}hero,\u{0020}only\u{0020}death\u{0020}remained\u{0020}at\u{0020}the\u{0020}end\u{0020}of\u{0020}the\u{0020}road.\n\u{3000}\u{3000}In\u{0020}this\u{0020}world\u{0020}covered\u{0020}in\u{0020}death,\u{0020}she\u{0020}came\u{0020}to\u{0020}understand\u{0020}what\u{0020}it\u{0020}means\u{0020}to\u{0020}\"live\u{0020}toward\u{0020}death\"\u{0020}far\u{0020}earlier\u{0020}than\u{0020}most\u{0020}people.\n\u{3000}\u{3000}From\u{0020}the\u{0020}moment\u{0020}she\u{0020}was\u{0020}born,\u{0020}she\u{0020}has\u{0020}been\u{0020}walking\u{0020}step\u{0020}by\u{0020}step\u{0020}toward\u{0020}death.\n\u{3000}\u{3000}Spes\u{0020}has\u{0020}been\u{0020}afraid,\u{0020}has\u{0020}been\u{0020}timid,\u{0020}and\u{0020}has\u{0020}hesitated,\u{0020}but\u{0020}she\u{0020}has\u{0020}never\u{0020}regretted\u{0020}it.\n\u{3000}\u{3000}She\u{0020}knows\u{0020}this\u{0020}is\u{0020}the\u{0020}only\u{0020}correct\u{0020}choice.\u{0020}It\u{0020}is\u{0020}both\u{0020}the\u{0020}only\u{0020}path\u{0020}left\u{0020}to\u{0020}her,\u{0020}and\u{0020}the\u{0020}one\u{0020}and\u{0020}only\u{0020}optimal\u{0020}answer.\n\u{3000}\u{3000}She\u{0020}will\u{0020}walk\u{0020}this\u{0020}road\u{0020}to\u{0020}death.\n\u{3000}\u{3000}She\u{0020}will\u{0020}save\u{0020}the\u{0020}world.\n\u{3000}\u{3000}And\u{0020}then,\u{0020}after\u{0020}saving\u{0020}the\u{0020}world,\u{0020}she\u{0020}hopes\u{0020}her\u{0020}tiny\u{0020}wish\u{0020}can\u{0020}be\u{0020}granted.\n\u{3000}\u{3000}\"After\u{0020}I\u{0020}save\u{0020}the\u{0020}world,\u{0020}the\u{0020}surviving\u{0020}humans\u{0020}will\u{0020}have\u{0020}to\u{0020}build\u{0020}me\u{0020}a\u{0020}30-meter-tall\u{0020}statue,\"\u{0020}she\u{0020}says.\u{0020}\"Praise\u{0020}me,\u{0020}worship\u{0020}me,\u{0020}and\u{0020}pass\u{0020}down\u{0020}my\u{0020}story\u{0020}forever.\"", "0", "0", "0", "0", 11052, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
