[615301] = {615301, 100, "Aoba\u{0020}Wakura,\u{0020}a\u{0020}white-haired\u{0020}girl\u{0020}who\u{0020}fought\u{0020}alongside\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}in\u{0020}the\u{0020}battle\u{0020}against\u{0020}Behemoth.\u{0020}She's\u{0020}not\u{0020}the\u{0020}most\u{0020}difficult\u{0020}type\u{0020}to\u{0020}deal\u{0020}with...\u{0020}but\u{0020}she's\u{0020}far\u{0020}from\u{0020}easy.\n\nA\u{0020}self-directed\u{0020}streak\u{0020}isn't\u{0020}uncommon\u{0020}among\u{0020}Drivers,\u{0020}but\u{0020}few\u{0020}pack\u{0020}the\u{0020}same\u{0020}raw\u{0020}destructive\u{0020}potential\u{0020}as\u{0020}Aoba.\u{0020}Her\u{0020}elastic\u{0020}hair\u{0020}is\u{0020}deadlier\u{0020}than\u{0020}any\u{0020}blade\u{0020}or\u{0020}gun\u{0020}and\u{0020}utterly\u{0020}uncontrollable.\n\nFortunately,\u{0020}she\u{0020}doesn't\u{0020}harbor\u{0020}the\u{0020}same\u{0020}bloodlust\u{0020}toward\u{0020}people\u{0020}as\u{0020}she\u{0020}does\u{0020}toward\u{0020}the\u{0020}Sins.\n\nHonestly,\u{0020}she\u{0020}and\u{0020}Zofia\u{0020}might\u{0020}actually\u{0020}get\u{0020}along\u{0020}surprisingly\u{0020}well.", "0", "0", "0", "0", 11053, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615302] = {615302, 500, "One\u{0020}can\u{0020}easily\u{0020}tell\u{0020}the\u{0020}relationship\u{0020}between\u{0020}Aoba\u{0020}and\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}is\u{0020}strained\u{0020}from\u{0020}their\u{0020}daily\u{0020}conversations,\u{0020}yet\u{0020}their\u{0020}battlefield\u{0020}synergy\u{0020}is\u{0020}strangely\u{0020}seamless.\n\nJudging\u{0020}by\u{0020}their\u{0020}different\u{0020}uniforms\u{0020}and\u{0020}appearances,\u{0020}Aoba\u{0020}isn't\u{0020}one\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force.\n\nFrom\u{0020}what\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}have\u{0020}gathered,\u{0020}Aoba\u{0020}Wakura\u{0020}was\u{0020}once\u{0020}an\u{0020}ordinary\u{0020}human\u{0020}who\u{0020}was\u{0020}transformed\u{0020}into\u{0020}what\u{0020}she\u{0020}is\u{0020}now\u{0020}after\u{0020}eating\u{0020}a\u{0020}Peach\u{0020}to\u{0020}survive\u{0020}the\u{0020}Mato\u{0020}Mishap.\n\nAoba\u{0020}carries\u{0020}several\u{0020}of\u{0020}these\u{0020}so-called\u{0020}Peaches\u{0020}with\u{0020}her,\u{0020}which\u{0020}appear\u{0020}to\u{0020}be\u{0020}the\u{0020}source\u{0020}of\u{0020}her\u{0020}power.\u{0020}However,\u{0020}due\u{0020}to\u{0020}their\u{0020}scarcity,\u{0020}and\u{0020}the\u{0020}fact\u{0020}that\u{0020}they\u{0020}can't\u{0020}be\u{0020}replenished\u{0020}in\u{0020}our\u{0020}world,\u{0020}she\u{0020}refuses\u{0020}to\u{0020}surrender\u{0020}even\u{0020}one\u{0020}for\u{0020}research.\n\nAoba's\u{0020}hostility\u{0020}to\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}isn't\u{0020}personal;\u{0020}it\u{0020}is\u{0020}aimed\u{0020}at\u{0020}Yin\u{0020}Yang\u{0020}Dorm,\u{0020}an\u{0020}AEGIS\u{0020}counterpart\u{0020}behind\u{0020}the\u{0020}force,\u{0020}for\u{0020}the\u{0020}sufferings\u{0020}that\u{0020}the\u{0020}authority\u{0020}has\u{0020}inflicted\u{0020}on\u{0020}her.\u{0020}To\u{0020}exact\u{0020}her\u{0020}revenge,\u{0020}she\u{0020}was\u{0020}deep\u{0020}in\u{0020}grueling\u{0020}training\u{0020}before\u{0020}arriving\u{0020}in\u{0020}our\u{0020}world.\n\nBut,\u{0020}honestly,\u{0020}based\u{0020}on\u{0020}our\u{0020}power\u{0020}assessment\u{0020}of\u{0020}her\u{0020}and\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force...\u{0020}she's\u{0020}still\u{0020}ages\u{0020}away\u{0020}from\u{0020}achieving\u{0020}that\u{0020}goal.", "0", "0", "0", "0", 11053, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615303] = {615303, 1000, "Once\u{0020}you\u{0020}get\u{0020}to\u{0020}know\u{0020}Aoba\u{0020}better,\u{0020}you'll\u{0020}notice\u{0020}that\u{0020}at\u{0020}times,\u{0020}she\u{0020}almost\u{0020}feels\u{0020}like\u{0020}an\u{0020}older\u{0020}sister.\n\nShe'll\u{0020}suddenly\u{0020}hug\u{0020}you\u{0020}from\u{0020}behind\u{0020}to\u{0020}give\u{0020}you\u{0020}a\u{0020}scare.\u{0020}Or\u{0020}she'll\u{0020}ruffle\u{0020}your\u{0020}hair\u{0020}into\u{0020}a\u{0020}mess\u{0020}without\u{0020}warning,\u{0020}then\u{0020}seriously\u{0020}start\u{0020}fixing\u{0020}it\u{0020}using\u{0020}a\u{0020}comb\u{0020}that\u{0020}she\u{0020}put\u{0020}out\u{0020}from\u{0020}nowhere,\u{0020}as\u{0020}if\u{0020}it\u{0020}were\u{0020}the\u{0020}most\u{0020}natural\u{0020}thing\u{0020}in\u{0020}the\u{0020}world.\u{0020}At\u{0020}meals,\u{0020}she\u{0020}might\u{0020}casually\u{0020}toss\u{0020}the\u{0020}food\u{0020}she\u{0020}doesn't\u{0020}like\u{0020}into\u{0020}your\u{0020}bowl,\u{0020}pretending\u{0020}to\u{0020}look\u{0020}the\u{0020}other\u{0020}way\u{0020}as\u{0020}if\u{0020}nothing\u{0020}happened.\n\nAs\u{0020}much\u{0020}as\u{0020}she\u{0020}tends\u{0020}to\u{0020}go\u{0020}her\u{0020}own\u{0020}way,\u{0020}having\u{0020}her\u{0020}around\u{0020}will\u{0020}never\u{0020}be\u{0020}annoying.", "0", "0", "0", "0", 11053, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
