[615401] = {615401, 100, "The\u{0020}Commander\u{0020}of\u{0020}the\u{0020}6th\u{0020}Squad\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force,\u{0020}Tenka\u{0020}Izumo\u{0020}is\u{0020}a\u{0020}striking\u{0020}short-haired\u{0020}woman\u{0020}who\u{0020}exudes\u{0020}both\u{0020}authority\u{0020}and\u{0020}charisma.\n\nAn\u{0020}all-time\u{0020}straight-A\u{0020}student,\u{0020}she\u{0020}boasts\u{0020}leadership\u{0020}that\u{0020}stands\u{0020}out\u{0020}even\u{0020}among\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force,\u{0020}combined\u{0020}with\u{0020}a\u{0020}calm,\u{0020}analytical\u{0020}mind.\n\nHer\u{0020}Peach\u{0020}Blessing,\u{0020}Ame-no-Mitori,\u{0020}allows\u{0020}her\u{0020}not\u{0020}only\u{0020}to\u{0020}teleport\u{0020}one\u{0020}across\u{0020}distances,\u{0020}but\u{0020}also\u{0020}to\u{0020}distort\u{0020}space\u{0020}itself\u{0020}to\u{0020}counter\u{0020}attacks\u{0020}or\u{0020}tear\u{0020}through\u{0020}defense.\u{0020}Her\u{0020}naturally\u{0020}wide\u{0020}attack\u{0020}radius\u{0020}makes\u{0020}it\u{0020}easier\u{0020}for\u{0020}her\u{0020}to\u{0020}handle\u{0020}groups\u{0020}of\u{0020}enemies.\u{0020}But\u{0020}don't\u{0020}be\u{0020}fooled:\u{0020}she's\u{0020}just\u{0020}as\u{0020}formidable\u{0020}in\u{0020}one-on-one\u{0020}combat,\u{0020}living\u{0020}up\u{0020}to\u{0020}her\u{0020}title\u{0020}of\u{0020}Commander.", "0", "0", "0", "0", 11054, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615402] = {615402, 500, "That\u{0020}said,\u{0020}her\u{0020}ability\u{0020}isn't\u{0020}strong\u{0020}enough\u{0020}to\u{0020}open\u{0020}a\u{0020}portal\u{0020}between\u{0020}two\u{0020}different\u{0020}worlds.\n\nLike\u{0020}the\u{0020}7th\u{0020}Squad,\u{0020}she's\u{0020}a\u{0020}victim\u{0020}of\u{0020}this\u{0020}world-crossing\u{0020}incident.\n\nUnlike\u{0020}the\u{0020}7th\u{0020}Squad,\u{0020}however,\u{0020}where\u{0020}almost\u{0020}the\u{0020}entire\u{0020}team\u{0020}made\u{0020}it\u{0020}through,\u{0020}Tenka\u{0020}is\u{0020}the\u{0020}sole\u{0020}member\u{0020}of\u{0020}the\u{0020}6th\u{0020}Squad\u{0020}transported\u{0020}to\u{0020}this\u{0020}world,\u{0020}which\u{0020}has\u{0020}made\u{0020}her\u{0020}a\u{0020}general\u{0020}without\u{0020}an\u{0020}army.\n\nFortunately,\u{0020}the\u{0020}two\u{0020}squads\u{0020}get\u{0020}along,\u{0020}and\u{0020}after\u{0020}reuniting\u{0020}with\u{0020}Shushu\u{0020}Suruga\u{0020}of\u{0020}the\u{0020}7th,\u{0020}she\u{0020}at\u{0020}least\u{0020}avoids\u{0020}the\u{0020}misery\u{0020}of\u{0020}fighting\u{0020}alone.\n\nThanks\u{0020}to\u{0020}years\u{0020}of\u{0020}experience\u{0020}responding\u{0020}to\u{0020}the\u{0020}Mato\u{0020}Mishap\u{0020}emergencies,\u{0020}Tenka\u{0020}adapted\u{0020}swiftly\u{0020}to\u{0020}the\u{0020}new\u{0020}environment\u{0020}and\u{0020}figured\u{0020}out\u{0020}how\u{0020}to\u{0020}survive\u{0020}here.\n\nEven\u{0020}if\u{0020}she\u{0020}had\u{0020}to\u{0020}go\u{0020}it\u{0020}alone,\u{0020}she'd\u{0020}manage\u{0020}just\u{0020}fine.\n\nAnd\u{0020}with\u{0020}her\u{0020}cheat\u{0020}ability,\u{0020}passing\u{0020}the\u{0020}Driver\u{0020}qualification\u{0020}test\u{0020}and\u{0020}snagging\u{0020}a\u{0020}captaincy\u{0020}would\u{0020}be\u{0020}all\u{0020}but\u{0020}guaranteed.", "0", "0", "0", "0", 11054, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615403] = {615403, 1000, "Upon\u{0020}her\u{0020}arrival\u{0020}at\u{0020}AEGIS,\u{0020}the\u{0020}one\u{0020}who\u{0020}drew\u{0020}the\u{0020}most\u{0020}attention\u{0020}among\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}was\u{0020}none\u{0020}other\u{0020}than\u{0020}Tenka.\n\nIt\u{0020}was\u{0020}more\u{0020}than\u{0020}her\u{0020}gentle,\u{0020}gracious\u{0020}smile\u{0020}that\u{0020}captivated\u{0020}people;\u{0020}it\u{0020}was\u{0020}the\u{0020}curiosity\u{0020}about\u{0020}her\u{0020}Peach\u{0020}Blessing.\n\nThe\u{0020}power\u{0020}of\u{0020}teleportation\u{0020}naturally\u{0020}is\u{0020}associated\u{0020}with\u{0020}the\u{0020}Gate\u{0020}commonly\u{0020}seen\u{0020}in\u{0020}this\u{0020}world.\u{0020}However,\u{0020}after\u{0020}a\u{0020}series\u{0020}of\u{0020}careful,\u{0020}thorough\u{0020}inspections,\u{0020}no\u{0020}breakthroughs\u{0020}were\u{0020}made.\u{0020}The\u{0020}Peach\u{0020}Blessing\u{0020}appears\u{0020}fundamentally\u{0020}incompatible\u{0020}with\u{0020}this\u{0020}world's\u{0020}technology,\u{0020}dashing\u{0020}hopes\u{0020}of\u{0020}fully\u{0020}understanding\u{0020}or\u{0020}controlling\u{0020}the\u{0020}Gate.\n\nUpon\u{0020}learning\u{0020}it,\u{0020}Tenka\u{0020}comforted\u{0020}the\u{0020}distraught\u{0020}research\u{0020}team.\u{0020}Shortly\u{0020}thereafter,\u{0020}a\u{0020}group\u{0020}of\u{0020}self-proclaimed\u{0020}fans\u{0020}popped\u{0020}up\u{0020}within\u{0020}AEGIS,\u{0020}rallying\u{0020}around\u{0020}the\u{0020}sweet\u{0020}girl.", "0", "0", "0", "0", 11054, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
