[615501] = {615501, 100, "\u{3000}\u{3000}Red,\u{0020}that's\u{0020}the\u{0020}name\u{0020}she\u{0020}writes\u{0020}on\u{0020}her\u{0020}lab\u{0020}reports,\u{0020}but\u{0020}she\u{0020}prefers\u{0020}to\u{0020}be\u{0020}called\u{0020}Red-chan.\n\u{3000}\u{3000}\u{0020}According\u{0020}to\u{0020}her,\u{0020}that's\u{0020}the\u{0020}difference\u{0020}between\u{0020}a\u{0020}creation\u{0020}and\u{0020}the\u{0020}self.\n\u{3000}\u{3000}\u{0020}A\u{0020}\"creation\"\u{0020}is\u{0020}something\u{0020}made\u{0020}by\u{0020}humans\u{0020}using\u{0020}tools\u{0020}and\u{0020}materials.\u{0020}That\u{0020}is,\u{0020}another\u{0020}tool,\u{0020}another\u{0020}material.\u{0020}The\u{0020}\"self,\"\u{0020}on\u{0020}the\u{0020}other\u{0020}hand,\u{0020}requires\u{0020}no\u{0020}creator.\n\u{3000}\u{3000}\u{0020}It\u{0020}simply\u{0020}is.\u{0020}Not\u{0020}a\u{0020}copy\u{0020}of\u{0020}anyone.\u{0020}Not\u{0020}made\u{0020}to\u{0020}shoulder\u{0020}the\u{0020}weight\u{0020}of\u{0020}anyone's\u{0020}expectations.\n\u{3000}\u{3000}\u{0020}She\u{0020}does\u{0020}as\u{0020}she\u{0020}pleases.\u{0020}Cries\u{0020}when\u{0020}she\u{0020}wants\u{0020}to\u{0020}cry,\u{0020}laughs\u{0020}when\u{0020}she\u{0020}feels\u{0020}like\u{0020}it,\u{0020}goes\u{0020}quiet\u{0020}when\u{0020}she\u{0020}needs\u{0020}to,\u{0020}and\u{0020}blows\u{0020}everything\u{0020}up\u{0020}when\u{0020}she's\u{0020}in\u{0020}the\u{0020}mood\u{0020}for\u{0020}chaos.\n\u{3000}\u{3000}\u{0020}Call\u{0020}it\u{0020}madness,\u{0020}call\u{0020}it\u{0020}indulgence.\u{0020}Stack\u{0020}enough\u{0020}negative\u{0020}terms\u{0020}together,\u{0020}and\u{0020}somehow\u{0020}they\u{0020}cancel\u{0020}out.\u{0020}Another\u{0020}great\u{0020}proof\u{0020}of\u{0020}mathematical\u{0020}truth.\n\u{3000}\u{3000}\u{0020}Take\u{0020}one\u{0020}part\u{0020}childishness\u{0020}from\u{0020}a\u{0020}mad\u{0020}scientist,\u{0020}and\u{0020}one\u{0020}part\u{0020}unrequited\u{0020}love\u{0020}from\u{0020}a\u{0020}Driver,\u{0020}then\u{0020}mix\u{0020}them\u{0020}1:1\u{0020}in\u{0020}the\u{0020}crucible\u{0020}of\u{0020}self-satisfaction,\u{0020}and\u{0020}from\u{0020}the\u{0020}primordial\u{0020}broth\u{0020}of\u{0020}life\u{0020}emerges\u{0020}a\u{0020}red,\u{0020}double-helix,\u{0020}silicon-based\u{0020}organism.\n\u{3000}\u{3000}\u{0020}She\u{0020}is\u{0020}absolute\u{0020}life,\u{0020}a\u{0020}new\u{0020}kind\u{0020}of\u{0020}Sin.\u{0020}Currently\u{0020}one\u{0020}year\u{0020}old,\u{0020}destined\u{0020}to\u{0020}forever\u{0020}remain\u{0020}a\u{0020}thirteen-year-old\u{0020}middle\u{0020}school\u{0020}girl\u{0020}known\u{0020}as\u{0020}Red-chan.", "0", "0", "0", "0", 11055, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615502] = {615502, 500, "\u{3000}\u{3000}Red-chan\u{0020}is\u{0020}a\u{0020}Sin.\u{0020}And\u{0020}she\u{0020}has\u{0020}the\u{0020}paperwork\u{0020}to\u{0020}prove\u{0020}it.\u{0020}She\u{0020}even\u{0020}got\u{0020}an\u{0020}official\u{0020}certificate\u{0020}from\u{0020}AEGIS'\u{0020}Science\u{0020}Department\u{0020}confirming\u{0020}it.\n\u{3000}\u{3000}\u{0020}Of\u{0020}course,\u{0020}\"AEGIS\u{0020}has\u{0020}Sins\"\u{0020}stopped\u{0020}being\u{0020}news\u{0020}ages\u{0020}ago.\u{0020}There's\u{0020}no\u{0020}shortage\u{0020}of\u{0020}people\u{0020}with\u{0020}the\u{0020}ability\u{0020}to\u{0020}become\u{0020}a\u{0020}Sin,\u{0020}those\u{0020}who\u{0020}were\u{0020}born\u{0020}from\u{0020}embryos\u{0020}cultured\u{0020}with\u{0020}Sin\u{0020}cores,\u{0020}or\u{0020}those\u{0020}who\u{0020}gained\u{0020}powers\u{0020}through\u{0020}exposure\u{0020}to\u{0020}it.\u{0020}The\u{0020}number\u{0020}only\u{0020}keeps\u{0020}growing.\n\u{3000}\u{3000}\u{0020}But\u{0020}Red-chan\u{0020}is\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}brags\u{0020}about\u{0020}being\u{0020}one\u{0020}of\u{0020}them\u{0020}and\u{0020}profits\u{0020}from\u{0020}it.\n\u{3000}\u{3000}\u{0020}Because\u{0020}she's\u{0020}an\u{0020}artificial\u{0020}human\u{0020}created\u{0020}from\u{0020}Dr.\u{0020}Red's\u{0020}own\u{0020}memories,\u{0020}her\u{0020}body\u{0020}shares\u{0020}many\u{0020}of\u{0020}the\u{0020}doctor's\u{0020}biological\u{0020}traits.\u{0020}That's\u{0020}proven\u{0020}to\u{0020}be\u{0020}a\u{0020}nightmare\u{0020}for\u{0020}AEGIS'\u{0020}aging\u{0020}security\u{0020}AI,\u{0020}which\u{0020}can't\u{0020}reliably\u{0020}tell\u{0020}the\u{0020}two\u{0020}apart.\n\u{3000}\u{3000}\u{0020}The\u{0020}result?\u{0020}Red-chan\u{0020}learned\u{0020}to\u{0020}hijack\u{0020}Dr.\u{0020}Red's\u{0020}access\u{0020}to\u{0020}run\u{0020}her\u{0020}own\u{0020}research\u{0020}projects,\u{0020}and\u{0020}get\u{0020}her\u{0020}hands\u{0020}on\u{0020}sufficient\u{0020}funding\u{0020}and\u{0020}materials.\u{0020}She\u{0020}even\u{0020}lists\u{0020}herself\u{0020}as\u{0020}a\u{0020}\"Sin\u{0020}sample\"\u{0020}on\u{0020}applications,\u{0020}since\u{0020}studies\u{0020}on\u{0020}Sins\u{0020}tend\u{0020}to\u{0020}receive\u{0020}extra\u{0020}resources.\n\u{3000}\u{3000}\u{0020}And\u{0020}when\u{0020}the\u{0020}bills\u{0020}come\u{0020}due?\u{0020}They\u{0020}all\u{0020}land\u{0020}on\u{0020}Dr.\u{0020}Red's\u{0020}desk.\u{0020}It's\u{0020}doubtful\u{0020}the\u{0020}doctor\u{0020}ever\u{0020}imagined\u{0020}her\u{0020}younger\u{0020}self\u{0020}would\u{0020}cause\u{0020}this\u{0020}much\u{0020}trouble...\n\u{3000}\u{3000}\u{0020}Or\u{0020}maybe\u{0020}she\u{0020}did.\u{0020}Maybe\u{0020}this\u{0020}was\u{0020}her\u{0020}plan\u{0020}all\u{0020}along.\u{0020}After\u{0020}all,\u{0020}she\u{0020}is\u{0020}Dr.\u{0020}Red.\n\u{3000}\u{3000}\u{0020}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}Dr.\u{0020}Red\u{0020}is\u{0020}using\u{0020}Red-chan\u{0020}to\u{0020}secretly\u{0020}carry\u{0020}out\u{0020}her\u{0020}banned\u{0020}experiments?\n\u{3000}\u{3000}What\u{0020}the\u{0020}young\u{0020}Dr.\u{0020}Red\u{0020}once\u{0020}wanted\u{0020}to\u{0020}do,\u{0020}maybe\u{0020}the\u{0020}present\u{0020}Dr.\u{0020}Red\u{0020}still\u{0020}does.", "0", "0", "0", "0", 11055, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615503] = {615503, 1000, "\u{3000}\u{3000}Becoming\u{0020}a\u{0020}Driver\u{0020}was\u{0020}Red-chan's\u{0020}idea.\n\u{3000}\u{3000}\u{0020}She\u{0020}claimed,\u{0020}\"Driving\u{0020}the\u{0020}mini-Julius\u{0020}isn't\u{0020}exciting\u{0020}enough.\u{0020}I\u{0020}want\u{0020}to\u{0020}fight\u{0020}for\u{0020}real.\"\n\u{3000}\u{3000}\u{0020}A\u{0020}flimsy\u{0020}excuse\u{0020}that\u{0020}might\u{0020}fool\u{0020}a\u{0020}middle-schooler,\u{0020}but\u{0020}still,\u{0020}better\u{0020}to\u{0020}have\u{0020}her\u{0020}wreak\u{0020}havoc\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}than\u{0020}inside\u{0020}the\u{0020}lab.\n\u{3000}\u{3000}\u{0020}The\u{0020}most\u{0020}unbelievable\u{0020}part,\u{0020}though,\u{0020}is\u{0020}that\u{0020}Red-chan\u{0020}can\u{0020}gigantify!\u{0020}It\u{0020}seems\u{0020}Dr.\u{0020}Red's\u{0020}robotics\u{0020}technology\u{0020}has\u{0020}surpassed\u{0020}even\u{0020}the\u{0020}engineers\u{0020}behind\u{0020}the\u{0020}Specter\u{0020}project\u{0020}years\u{0020}ago.\n\u{3000}\u{3000}\u{0020}\"Absolute\u{0020}life.\u{0020}A\u{0020}new\u{0020}kind\u{0020}of\u{0020}Sin.\"\u{0020}Maybe\u{0020}that\u{0020}wasn't\u{0020}just\u{0020}a\u{0020}pretty\u{0020}slogan\u{0020}after\u{0020}all.\n\u{3000}\u{3000}\u{0020}Perhaps\u{0020}someday,\u{0020}Red\u{0020}will\u{0020}redefine\u{0020}what\u{0020}it\u{0020}means\u{0020}to\u{0020}be\u{0020}human.", "0", "0", "0", "0", 11055, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615504] = {615504, 2000, "\u{3000}\u{3000}Red\u{0020}is\u{0020}a\u{0020}color.\u{0020}\n\u{3000}\u{3000}Hair,\u{0020}eyes,\u{0020}heart,\u{0020}blood.\u{0020}\n\u{3000}\u{3000}Red\u{0020}is\u{0020}emotion.\u{0020}\n\u{3000}\u{3000}Joy,\u{0020}rage,\u{0020}love,\u{0020}hate.\u{0020}\n\u{3000}\u{3000}Red\u{0020}is\u{0020}desire.\u{0020}\n\u{3000}\u{3000}Yearning,\u{0020}madness,\u{0020}greed,\u{0020}possession.\u{0020}\n\u{3000}\u{3000}Red\u{0020}is\u{0020}war.\u{0020}\n\u{3000}\u{3000}Clash,\u{0020}conflict,\u{0020}slaughter,\u{0020}ruin.\n\u{3000}\u{3000}\u{0020}\"So,\u{0020}Red\u{0020}really\u{0020}is\u{0020}humanity's\u{0020}Sin,\u{0020}isn't\u{0020}she?\"\n\u{3000}\u{3000}\u{0020}\"Maybe.\u{0020}But\u{0020}even\u{0020}so...\u{0020}I'll\u{0020}become\u{0020}a\u{0020}redder\u{0020}Red\u{0020}than\u{0020}you.\"", "0", "0", "0", "0", 11055, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
