[615601] = {615601, 100, "\u{3000}\u{3000}Making\u{0020}her\u{0020}debut\u{0020}in\u{0020}her\u{0020}prime\u{0020}at\u{0020}age\u{0020}20\u{0020}in\u{0020}Dunscaith\u{0020}Chronicles\u{0020}I,\u{0020}this\u{0020}version\u{0020}of\u{0020}Skadi\u{0020}from\u{0020}another\u{0020}world\u{0020}had\u{0020}graduated\u{0020}from\u{0020}her\u{0020}chuunibyou\u{0020}phase\u{0020}at\u{0020}14.\u{0020}After\u{0020}a\u{0020}year\u{0020}of\u{0020}soul-searching,\u{0020}she\u{0020}decided\u{0020}to\u{0020}bury\u{0020}those\u{0020}fantasies\u{0020}deep\u{0020}within\u{0020}her\u{0020}heart.\u{0020}At\u{0020}16,\u{0020}she\u{0020}was\u{0020}adopted\u{0020}by\u{0020}a\u{0020}family\u{0020}and,\u{0020}in\u{0020}the\u{0020}same\u{0020}year,\u{0020}awakened\u{0020}the\u{0020}superpower\u{0020}to\u{0020}read\u{0020}minds.\u{0020}The\u{0020}embers\u{0020}of\u{0020}her\u{0020}fantasies\u{0020}burst\u{0020}into\u{0020}flame\u{0020}once\u{0020}more\u{0020}from\u{0020}the\u{0020}ashes.\n\u{3000}\u{3000}\u{0020}\n\u{3000}\u{3000}When\u{0020}the\u{0020}belief\u{0020}in\u{0020}\"fantasy\"\u{0020}began\u{0020}to\u{0020}sustain\u{0020}her,\u{0020}the\u{0020}President,\u{0020}now\u{0020}seeing\u{0020}the\u{0020}world\u{0020}with\u{0020}fresh\u{0020}eyes\u{0020}and\u{0020}renewed\u{0020}vitality,\u{0020}found\u{0020}she\u{0020}could\u{0020}handle\u{0020}every\u{0020}task\u{0020}to\u{0020}perfection.\u{0020}If\u{0020}she\u{0020}set\u{0020}her\u{0020}mind\u{0020}to\u{0020}it,\u{0020}she\u{0020}could\u{0020}master\u{0020}any\u{0020}known,\u{0020}observable\u{0020}field\u{0020}of\u{0020}human\u{0020}knowledge\u{0020}in\u{0020}an\u{0020}astonishingly\u{0020}short\u{0020}time.\u{0020}Because\u{0020}of\u{0020}her\u{0020}mind-reading\u{0020}ability,\u{0020}she\u{0020}believed\u{0020}herself\u{0020}highly\u{0020}perceptive\u{0020}of\u{0020}others'\u{0020}feelings\u{0020}and\u{0020}was\u{0020}utterly\u{0020}convinced\u{0020}other\u{0020}superhumans\u{0020}existed\u{0020}in\u{0020}her\u{0020}world.\u{0020}Driven\u{0020}by\u{0020}her\u{0020}mission\u{0020}to\u{0020}\"find\u{0020}other\u{0020}people\u{0020}with\u{0020}superpowers,\"\u{0020}she\u{0020}tested\u{0020}into\u{0020}humanity's\u{0020}highest\u{0020}institute\u{0020}of\u{0020}learning,\u{0020}ready\u{0020}to\u{0020}challenge\u{0020}all\u{0020}the\u{0020}geniuses\u{0020}of\u{0020}the\u{0020}world.", "0", "0", "0", "0", 11056, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615602] = {615602, 500, "\u{3000}\u{3000}The\u{0020}world\u{0020}was\u{0020}constantly\u{0020}producing\u{0020}prodigies,\u{0020}and\u{0020}this\u{0020}academy\u{0020}gathered\u{0020}young\u{0020}people\u{0020}who\u{0020}had\u{0020}displayed\u{0020}talent\u{0020}in\u{0020}every\u{0020}conceivable\u{0020}field,\u{0020}claiming\u{0020}it\u{0020}could\u{0020}make\u{0020}every\u{0020}student's\u{0020}potential\u{0020}blossom.\n\u{3000}\u{3000}\u{0020}Her\u{0020}immense\u{0020}learning\u{0020}ability\u{0020}allowed\u{0020}her\u{0020}to\u{0020}devour\u{0020}vast\u{0020}amounts\u{0020}of\u{0020}knowledge\u{0020}like\u{0020}a\u{0020}whale,\u{0020}but\u{0020}she\u{0020}quickly\u{0020}realized\u{0020}a\u{0020}problem—the\u{0020}pinnacle\u{0020}of\u{0020}human\u{0020}academia\u{0020}had\u{0020}lost\u{0020}its\u{0020}vitality.\u{0020}The\u{0020}school\u{0020}was\u{0020}rigidly\u{0020}hierarchical,\u{0020}rotting\u{0020}from\u{0020}the\u{0020}ground\u{0020}up,\u{0020}stifling\u{0020}the\u{0020}very\u{0020}students\u{0020}it\u{0020}was\u{0020}meant\u{0020}to\u{0020}nurture.\n\u{3000}\u{3000}\u{0020}So,\u{0020}she\u{0020}decided\u{0020}to\u{0020}improve\u{0020}her\u{0020}own\u{0020}environment\u{0020}while\u{0020}continuing\u{0020}her\u{0020}search\u{0020}for\u{0020}superhumans,\u{0020}thus\u{0020}beginning\u{0020}her\u{0020}war\u{0020}as\u{0020}a\u{0020}student.\n\u{3000}\u{3000}\u{0020}She\u{0020}became\u{0020}the\u{0020}Student\u{0020}Council\u{0020}President.\u{0020}The\u{0020}cost?\u{0020}She\u{0020}temporarily\u{0020}removed\u{0020}her\u{0020}own\u{0020}name,\u{0020}[Skadi],\u{0020}in\u{0020}accordance\u{0020}with\u{0020}the\u{0020}Council's\u{0020}rules.\u{0020}The\u{0020}Student\u{0020}Council\u{0020}was\u{0020}great\u{0020}not\u{0020}because\u{0020}of\u{0020}any\u{0020}individual;\u{0020}a\u{0020}name\u{0020}was\u{0020}a\u{0020}person's\u{0020}most\u{0020}unique\u{0020}marker,\u{0020}and\u{0020}this\u{0020}Council\u{0020}belonged\u{0020}only\u{0020}to\u{0020}[the\u{0020}President].\u{0020}The\u{0020}academy\u{0020}was\u{0020}controlled\u{0020}by\u{0020}thirteen\u{0020}individuals\u{0020}whose\u{0020}authority\u{0020}rivaled\u{0020}the\u{0020}[Student\u{0020}Council\u{0020}President's].\u{0020}Skadi\u{0020}had\u{0020}broken\u{0020}out\u{0020}of\u{0020}her\u{0020}cage\u{0020}only\u{0020}to\u{0020}arrive\u{0020}in\u{0020}a\u{0020}new\u{0020}hell.\n\u{3000}\u{3000}\u{0020}She\u{0020}decided\u{0020}to\u{0020}temporarily\u{0020}shelve\u{0020}her\u{0020}search\u{0020}for\u{0020}superhumans,\u{0020}taking\u{0020}a\u{0020}slight\u{0020}detour\u{0020}to\u{0020}wage\u{0020}a\u{0020}new\u{0020}war:\u{0020}to\u{0020}reclaim\u{0020}her\u{0020}name.\n\u{3000}\u{3000}\u{0020}After\u{0020}a\u{0020}series\u{0020}of\u{0020}events...\u{0020}by\u{0020}age\u{0020}19,\u{0020}Skadi\u{0020}had\u{0020}successfully\u{0020}made\u{0020}the\u{0020}word\u{0020}[President]\u{0020}her\u{0020}exclusive\u{0020}title.\u{0020}When\u{0020}people\u{0020}mentioned\u{0020}the\u{0020}[President],\u{0020}her\u{0020}image\u{0020}now\u{0020}overshadowed\u{0020}the\u{0020}knowledge\u{0020}in\u{0020}textbooks\u{0020}and\u{0020}the\u{0020}photos\u{0020}on\u{0020}the\u{0020}alumni\u{0020}wall.\u{0020}From\u{0020}then\u{0020}on,\u{0020}[Skadi]\u{0020}was\u{0020}the\u{0020}only\u{0020}light.\n\u{3000}\u{3000}\u{0020}Although\u{0020}the\u{0020}final\u{0020}outcome\u{0020}slightly\u{0020}deviated\u{0020}from\u{0020}her\u{0020}initial\u{0020}imagination,\u{0020}she\u{0020}could\u{0020}finally\u{0020}focus\u{0020}her\u{0020}mind\u{0020}on\u{0020}finding\u{0020}other\u{0020}superhumans.\n\u{3000}\u{3000}\u{0020}At\u{0020}20,\u{0020}the\u{0020}President\u{0020}arrived\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe.", "0", "0", "0", "0", 11056, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615603] = {615603, 1000, "\u{3000}\u{3000}Initiative\u{0020}is\u{0020}the\u{0020}greatest\u{0020}strength\u{0020}of\u{0020}every\u{0020}Skadi,\u{0020}but\u{0020}the\u{0020}younger\u{0020}Skadi\u{0020}had\u{0020}not\u{0020}yet\u{0020}clarified\u{0020}her\u{0020}goals\u{0020}and\u{0020}had\u{0020}not\u{0020}emerged\u{0020}from\u{0020}her\u{0020}fantasies.\u{0020}Such\u{0020}a\u{0020}Skadi\u{0020}was\u{0020}powerless.\n\u{3000}\u{3000}\u{0020}[The\u{0020}President]\u{0020}explained\u{0020}her\u{0020}perspective,\u{0020}ready\u{0020}to\u{0020}begin\u{0020}correcting\u{0020}this\u{0020}Skadi.\n\u{3000}\u{3000}\u{0020}But\u{0020}whether\u{0020}it\u{0020}was\u{0020}the\u{0020}Skadi\u{0020}from\u{0020}Dunscaith\u{0020}Chronicles\u{0020}I\u{0020}or\u{0020}the\u{0020}Skadi\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe...\u{0020}they\u{0020}both\u{0020}refused\u{0020}her.\n\u{3000}\u{3000}\u{0020}\"Anyone\u{0020}can\u{0020}become\u{0020}anything.\u{0020}Anything\u{0020}can\u{0020}be\u{0020}achieved.\"\u{0020}The\u{0020}younger\u{0020}Skadi\u{0020}uttered\u{0020}these\u{0020}words,\u{0020}still\u{0020}accumulating\u{0020}the\u{0020}power\u{0020}to\u{0020}grow\u{0020}within\u{0020}her\u{0020}cocoon.\u{0020}\"I\u{0020}don't\u{0020}need\u{0020}your\u{0020}help.\u{0020}Perhaps\u{0020}you\u{0020}should\u{0020}go\u{0020}see\u{0020}the\u{0020}universe.\"\n\u{3000}\u{3000}\u{0020}Taking\u{0020}these\u{0020}words\u{0020}as\u{0020}a\u{0020}catalyst,\u{0020}the\u{0020}President\u{0020}began\u{0020}her\u{0020}journey\u{0020}through\u{0020}the\u{0020}cosmos.\n\u{3000}\u{3000}\u{0020}\"Even\u{0020}after\u{0020}death,\u{0020}you\u{0020}still\u{0020}cling\u{0020}to\u{0020}the\u{0020}fantasy\u{0020}of\u{0020}growing\u{0020}up?\"", "0", "0", "0", "0", 11056, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615604] = {615604, 2000, "\u{3000}\u{3000}\"What's\u{0020}the\u{0020}meaning\u{0020}of\u{0020}travel?\u{0020}Why\u{0020}ask\u{0020}such\u{0020}a\u{0020}strange\u{0020}question?\"\n\u{3000}\u{3000}\u{0020}\"Making\u{0020}friends\u{0020}is\u{0020}joy.\"\n\u{3000}\u{3000}\u{0020}\"Seeing\u{0020}flowing\u{0020}water\u{0020}is\u{0020}joy.\"\n\u{3000}\u{3000}\u{0020}\"Seeing\u{0020}lifeless\u{0020}planets\u{0020}is\u{0020}joy.\"\n\u{3000}\u{3000}\u{0020}\"Every\u{0020}day\u{0020}is\u{0020}unpredictable,\u{0020}unimaginable.\"\n\u{3000}\u{3000}\u{0020}\"Traveling\u{0020}with\u{0020}you\u{0020}is\u{0020}joy.\"\n\u{3000}\u{3000}\u{0020}\"Sharing\u{0020}the\u{0020}thrill\u{0020}of\u{0020}exploration\u{0020}with\u{0020}you\u{0020}is\u{0020}joy.\"\n\u{3000}\u{3000}\u{0020}\"I\u{0020}am\u{0020}not\u{0020}alone,\u{0020}and\u{0020}thinking\u{0020}of\u{0020}this\u{0020}also\u{0020}brings\u{0020}joy.\"\n\u{3000}\u{3000}\u{0020}\"Shall\u{0020}we\u{0020}find\u{0020}joy\u{0020}again\u{0020}tomorrow?\"\n\u{3000}\u{3000}", "0", "0", "0", "0", 11056, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[615700] = {615700, 0, "[Name]\u{0020}Skadi\n\u{0020}[B-day]\u{0020}July\u{0020}5\n\u{0020}[Transformation\u{0020}Core\u{0020}Compatibility]\u{0020}95%\n\u{0020}[Height]\u{0020}32m\n\u{0020}[Unit]\u{0020}Moon\u{0020}Corona\n\u{0020}[Affiliation]\u{0020}Danube\u{0020}Branch\n\u{0020}[Hobbies]\u{0020}Saving\u{0020}the\u{0020}world,\u{0020}creating\u{0020}miracles,\u{0020}and\u{0020}developing\u{0020}new\u{0020}types\u{0020}of\u{0020}takoyaki", "0", "0", "0", "0", 11057, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[615701] = {615701, 100, "\u{3000}\u{3000}Then--how\u{0020}exactly\u{0020}was\u{0020}the\u{0020}world\u{0020}returned\u{0020}to\u{0020}its\u{0020}original\u{0020}state?\n\u{3000}\u{3000}\"My\u{0020}familiar,\u{0020}do\u{0020}you\u{0020}know\u{0020}of\u{0020}the\u{0020}takoyaki\u{0020}contest?\"\u{0020}One\u{0020}day,\u{0020}Skadi\u{0020}suddenly\u{0020}appeared\u{0020}before\u{0020}me\u{0020}with\u{0020}an\u{0020}enormous\u{0020}suitcase\u{0020}on\u{0020}her\u{0020}back\u{0020}and\u{0020}said\u{0020}this\u{0020}to\u{0020}me.\n\u{3000}\u{3000}\"A\u{0020}contest\u{0020}like\u{0020}a\u{0020}cooking\u{0020}competition,\u{0020}right?\u{0020}I\u{0020}remember\u{0020}you\u{0020}mentioning\u{0020}it...\u{0020}A\u{0020}contest\u{0020}held\u{0020}by\u{0020}countless\u{0020}chefs\u{0020}to\u{0020}make\u{0020}the\u{0020}most\u{0020}delicious\u{0020}takoyaki?\"\n\u{3000}\u{3000}\"Exactly,\u{0020}exactly.\u{0020}Then\u{0020}let\u{0020}us\u{0020}go.\"\n\u{3000}\u{3000}\"Did\u{0020}you\u{0020}find\u{0020}another\u{0020}clue?\"\n\u{3000}\u{3000}\"We\u{0020}are\u{0020}going\u{0020}to\u{0020}enter\u{0020}the\u{0020}takoyaki\u{0020}contest.\u{0020}This\u{0020}time,\u{0020}with\u{0020}the\u{0020}combined\u{0020}might\u{0020}of\u{0020}Navigator\u{0020}and\u{0020}me...\u{0020}we\u{0020}will\u{0020}definitely,\u{0020}definitely\u{0020}win\u{0020}first\u{0020}place!\"\n\u{3000}\u{3000}And\u{0020}so,\u{0020}Skadi\u{0020}and\u{0020}I\u{0020}drove\u{0020}together\u{0020}toward\u{0020}the\u{0020}contest\u{0020}venue--Kyushu,\u{0020}the\u{0020}sacred\u{0020}land\u{0020}of\u{0020}gourmet\u{0020}food.\n\u{3000}\u{3000}By\u{0020}the\u{0020}way,\u{0020}Skadi's\u{0020}trump\u{0020}card\u{0020}for\u{0020}this\u{0020}takoyaki\u{0020}contest\u{0020}was\u{0020}cuttlefish\u{0020}takoyaki,\u{0020}but\u{0020}takoyaki\u{0020}made\u{0020}this\u{0020}way\u{0020}had\u{0020}already\u{0020}existed\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\u{0020}Before\u{0020}the\u{0020}world\u{0020}underwent\u{0020}its\u{0020}abnormal\u{0020}change,\u{0020}I\u{0020}had\u{0020}seen\u{0020}it\u{0020}in\u{0020}Danube's\u{0020}city\u{0020}center.\u{0020}But\u{0020}when\u{0020}I\u{0020}pointed\u{0020}this\u{0020}out,\u{0020}she\u{0020}said,\u{0020}\"E-Elixirs\u{0020}have\u{0020}nothing\u{0020}to\u{0020}do\u{0020}with\u{0020}takoyaki.\"\n\u{3000}\u{3000}\"Then\u{0020}why\u{0020}are\u{0020}you\u{0020}entering\u{0020}an\u{0020}elixir\u{0020}in\u{0020}a\u{0020}takoyaki\u{0020}contest!?\"", "0", "0", "0", "0", 11057, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615702] = {615702, 500, "\u{3000}\u{3000}The\u{0020}takoyaki\u{0020}contest\u{0020}ended\u{0020}in\u{0020}crushing\u{0020}defeat.\u{0020}We\u{0020}lost\u{0020}completely.\u{0020}Or\u{0020}rather,\u{0020}this\u{0020}result\u{0020}had\u{0020}been\u{0020}expected\u{0020}from\u{0020}the\u{0020}very\u{0020}beginning...\n\u{3000}\u{3000}The\u{0020}winner\u{0020}was\u{0020}takoyaki\u{0020}made\u{0020}with\u{0020}premium\u{0020}ingredients.\u{0020}Apparently,\u{0020}the\u{0020}chef\u{0020}had\u{0020}spent\u{0020}years\u{0020}training\u{0020}the\u{0020}octopuses\u{0020}day\u{0020}after\u{0020}day\u{0020}in\u{0020}order\u{0020}to\u{0020}win\u{0020}the\u{0020}prize.\u{0020}They\u{0020}were\u{0020}real\u{0020}octopuses,\u{0020}by\u{0020}the\u{0020}way.\u{0020}In\u{0020}fact,\u{0020}none\u{0020}of\u{0020}the\u{0020}chefs\u{0020}at\u{0020}the\u{0020}contest\u{0020}venue\u{0020}cut\u{0020}off\u{0020}their\u{0020}own\u{0020}legs\u{0020}to\u{0020}use\u{0020}as\u{0020}ingredients,\u{0020}so\u{0020}it\u{0020}seems\u{0020}the\u{0020}chefs\u{0020}were\u{0020}actually\u{0020}quite\u{0020}hygienic...\u{0020}The\u{0020}only\u{0020}unhygienic\u{0020}one\u{0020}was\u{0020}Skadi!\n\u{3000}\u{3000}Since\u{0020}we\u{0020}had\u{0020}made\u{0020}the\u{0020}rare\u{0020}trip\u{0020}to\u{0020}Kyushu,\u{0020}we\u{0020}also\u{0020}stopped\u{0020}by\u{0020}Kyushu\u{0020}Headquarters.\u{0020}There,\u{0020}we\u{0020}saw\u{0020}the\u{0020}octopusified\u{0020}Stephanie\u{0020}floating\u{0020}inside\u{0020}a\u{0020}water\u{0020}tank...\u{0020}and\u{0020}somehow,\u{0020}it\u{0020}did\u{0020}not\u{0020}feel\u{0020}out\u{0020}of\u{0020}place\u{0020}at\u{0020}all.\n\u{3000}\u{3000}In\u{0020}the\u{0020}trash\u{0020}bin\u{0020}for\u{0020}her\u{0020}work\u{0020}files,\u{0020}we\u{0020}discovered\u{0020}her\u{0020}research\u{0020}report\u{0020}on\u{0020}the\u{0020}phenomenon\u{0020}of\u{0020}global\u{0020}octopusification.\u{0020}Although\u{0020}the\u{0020}further\u{0020}the\u{0020}report\u{0020}went,\u{0020}the\u{0020}more\u{0020}garbled\u{0020}text\u{0020}appeared,\u{0020}we\u{0020}still\u{0020}managed\u{0020}to\u{0020}extract\u{0020}some\u{0020}important\u{0020}information--Stephanie\u{0020}had\u{0020}detected\u{0020}the\u{0020}source\u{0020}of\u{0020}the\u{0020}abnormal\u{0020}change\u{0020}in\u{0020}the\u{0020}ocean,\u{0020}and\u{0020}had\u{0020}even\u{0020}provided\u{0020}the\u{0020}coordinates...\n\u{3000}\u{3000}\"Huh...?\u{0020}What\u{0020}does\u{0020}this\u{0020}mean?\u{0020}Are\u{0020}we\u{0020}supposed\u{0020}to\u{0020}go\u{0020}into\u{0020}the\u{0020}deep\u{0020}sea...\"\u{0020}Skadi\u{0020}furrowed\u{0020}her\u{0020}brows.\n\u{3000}\u{3000}\"Come\u{0020}to\u{0020}think\u{0020}of\u{0020}it...\u{0020}Since\u{0020}we\u{0020}have\u{0020}all\u{0020}turned\u{0020}into\u{0020}octopuses,\u{0020}does\u{0020}that\u{0020}mean\u{0020}we\u{0020}can\u{0020}move\u{0020}around\u{0020}underwater\u{0020}like\u{0020}octopuses...?\"\n\u{3000}\u{3000}\"I\u{0020}have\u{0020}not\u{0020}tried\u{0020}yet...\u{0020}Fine,\u{0020}let\u{0020}us\u{0020}test\u{0020}it!\"\n\u{3000}\u{3000}The\u{0020}final\u{0020}result\u{0020}was...\u{0020}We\u{0020}really\u{0020}could\u{0020}live\u{0020}freely\u{0020}underwater.\u{0020}We\u{0020}also\u{0020}tested\u{0020}it\u{0020}in\u{0020}low-temperature\u{0020}conditions\u{0020}and\u{0020}found\u{0020}that\u{0020}we\u{0020}could\u{0020}still\u{0020}move\u{0020}without\u{0020}issue...\u{0020}With\u{0020}this\u{0020}extra\u{0020}layer\u{0020}of\u{0020}assurance,\u{0020}we\u{0020}began\u{0020}preparing\u{0020}a\u{0020}submarine\u{0020}and\u{0020}getting\u{0020}ready\u{0020}to\u{0020}explore\u{0020}the\u{0020}deep\u{0020}sea.", "0", "0", "0", "0", 11057, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615703] = {615703, 1000, "\u{3000}\u{3000}We\u{0020}passed\u{0020}through\u{0020}the\u{0020}aurora\u{0020}beneath\u{0020}the\u{0020}sea\u{0020}and\u{0020}arrived\u{0020}at\u{0020}a\u{0020}palace.\n\u{3000}\u{3000}What\u{0020}is\u{0020}this\u{0020}place?\u{0020}Why\u{0020}is\u{0020}there\u{0020}an\u{0020}aurora\u{0020}under\u{0020}the\u{0020}sea...\u{0020}A\u{0020}palace\u{0020}beneath\u{0020}the\u{0020}ocean?\u{0020}I\u{0020}could\u{0020}hear\u{0020}something\u{0020}calling\u{0020}to\u{0020}me.\u{0020}I\u{0020}had\u{0020}to\u{0020}go...\n\u{3000}\u{3000}\"Navigator...!\u{0020}You\u{0020}are\u{0020}pulling\u{0020}me\u{0020}too\u{0020}hard,\u{0020}my\u{0020}familiar!\"\u{0020}Skadi's\u{0020}voice\u{0020}snapped\u{0020}me\u{0020}back\u{0020}to\u{0020}my\u{0020}senses.\u{0020}\"What\u{0020}happened\u{0020}just\u{0020}now?\u{0020}All\u{0020}of\u{0020}a\u{0020}sudden,\u{0020}you\u{0020}could\u{0020}not\u{0020}hear\u{0020}me\u{0020}anymore...\"\n\u{3000}\u{3000}\"I\u{0020}know\u{0020}where\u{0020}the\u{0020}source\u{0020}of\u{0020}the\u{0020}cataclysm\u{0020}is\u{0020}now,\u{0020}but\u{0020}I\u{0020}can\u{0020}barely\u{0020}keep\u{0020}myself\u{0020}under\u{0020}control.\u{0020}Skadi,\u{0020}you\u{0020}have\u{0020}to\u{0020}keep\u{0020}waking\u{0020}me\u{0020}up...\"\n\u{3000}\u{3000}The\u{0020}closer\u{0020}we\u{0020}drew\u{0020}to\u{0020}the\u{0020}source,\u{0020}the\u{0020}more\u{0020}lost\u{0020}I\u{0020}became.\u{0020}Skadi\u{0020}held\u{0020}tightly\u{0020}onto\u{0020}me,\u{0020}constantly\u{0020}throwing\u{0020}out\u{0020}new\u{0020}topics\u{0020}to\u{0020}keep\u{0020}my\u{0020}mind\u{0020}focused.\n\u{3000}\u{3000}Then\u{0020}we\u{0020}saw\u{0020}the\u{0020}statue,\u{0020}a\u{0020}bizarre\u{0020}statue\u{0020}standing\u{0020}at\u{0020}the\u{0020}very\u{0020}center\u{0020}of\u{0020}the\u{0020}crystal\u{0020}palace.\n\u{3000}\u{3000}After\u{0020}that,\u{0020}I\u{0020}cannot\u{0020}remember\u{0020}much.\n\u{3000}\u{3000}\"...Ritual...\u{0020}price...\u{0020}return...\u{0020}give\u{0020}up...\u{0020}change...\"\n\u{3000}\u{3000}Skadi\u{0020}seemed\u{0020}to\u{0020}be\u{0020}saying\u{0020}something.\u{0020}Was\u{0020}she\u{0020}making\u{0020}a\u{0020}wish?\u{0020}I\u{0020}could\u{0020}hear\u{0020}something\u{0020}shatter...\n\u{3000}\u{3000}My\u{0020}consciousness\u{0020}sank\u{0020}into\u{0020}endless\u{0020}darkness.\n\u{3000}\u{3000}\"Let\u{0020}us\u{0020}meet\u{0020}again\u{0020}in\u{0020}the\u{0020}past,\u{0020}my\u{0020}familiar.\"", "0", "0", "0", "0", 11057, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615704] = {615704, 2000, "\u{3000}\u{3000}Actually,\u{0020}the\u{0020}moment\u{0020}I\u{0020}saw\u{0020}that\u{0020}palace,\u{0020}I\u{0020}remembered\u{0020}everything...\n\u{3000}\u{3000}The\u{0020}one\u{0020}who\u{0020}completed\u{0020}that\u{0020}ritual\u{0020}with\u{0020}me\u{0020}in\u{0020}the\u{0020}very\u{0020}beginning...\u{0020}was\u{0020}you\u{0020}too,\u{0020}Navigator!\n\u{3000}\u{3000}So\u{0020}this\u{0020}journey\u{0020}is\u{0020}one\u{0020}we\u{0020}began\u{0020}with\u{0020}our\u{0020}own\u{0020}hands.\n\u{3000}\u{3000}It\u{0020}is\u{0020}a\u{0020}story\u{0020}that\u{0020}belongs\u{0020}only\u{0020}to\u{0020}us.\n\u{3000}\u{3000}I\u{0020}truly\u{0020}enjoyed\u{0020}this\u{0020}journey,\u{0020}you\u{0020}know?\n\u{3000}\u{3000}Will\u{0020}we\u{0020}meet\u{0020}again?\n\u{3000}\u{3000}If\u{0020}only\u{0020}this\u{0020}experience,\u{0020}these\u{0020}memories,\u{0020}could\u{0020}remain...\n\u{3000}\u{3000}If\u{0020}only\u{0020}there\u{0020}were\u{0020}a\u{0020}place\u{0020}where\u{0020}our\u{0020}story\u{0020}could\u{0020}be\u{0020}recorded...\n\u{3000}\u{3000}If\u{0020}there\u{0020}is...\u{0020}then\u{0020}let\u{0020}it\u{0020}be\u{0020}called\u{0020}the\u{0020}Dunscaith\u{0020}Chronicles.", "0", "0", "0", "0", 11057, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[615900] = {615900, 0, "[Name]:\u{0020}Mikael\n\u{0020}[B-day]:\u{0020}Aug.\u{0020}15\n\u{0020}[Transformation\u{0020}Core\u{0020}Compatibility]:\u{0020}94%\n\u{0020}[Height]:\u{0020}40m\n\u{0020}[Squad]:\u{0020}Dragon\u{0020}Knights\n\u{0020}[Affiliation]:\u{0020}Danube\u{0020}Branch\n\u{0020}[Hobbies]:\u{0020}Non-competitive\u{0020}games", "0", "0", "0", "0", 11059, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[615901] = {615901, 100, "\u{3000}\u{3000}Mikael\u{0020}has\u{0020}eyes\u{0020}as\u{0020}deep\u{0020}as\u{0020}blue\u{0020}lace\u{0020}agate,\u{0020}and\u{0020}her\u{0020}fluffy\u{0020}blond\u{0020}hair\u{0020}shows\u{0020}her\u{0020}pure\u{0020}Danube\u{0020}lineage.\n\u{3000}\u{3000}Mikael\u{0020}considers\u{0020}herself\u{0020}a\u{0020}natural-born\u{0020}winner.\u{0020}She\u{0020}has\u{0020}an\u{0020}obsession\u{0020}with\u{0020}victory\u{0020}that\u{0020}goes\u{0020}beyond\u{0020}the\u{0020}ordinary.\u{0020}\"Win\"\u{0020}is\u{0020}the\u{0020}only\u{0020}creed\u{0020}she\u{0020}lives\u{0020}by.\u{0020}No\u{0020}matter\u{0020}what\u{0020}it\u{0020}is,\u{0020}she\u{0020}has\u{0020}to\u{0020}beat\u{0020}everyone\u{0020}else.\u{0020}Back\u{0020}at\u{0020}the\u{0020}academy,\u{0020}she\u{0020}was\u{0020}always\u{0020}the\u{0020}first\u{0020}person\u{0020}to\u{0020}arrive\u{0020}in\u{0020}the\u{0020}classroom.\u{0020}Her\u{0020}competitive\u{0020}spirit\u{0020}makes\u{0020}her\u{0020}secretly\u{0020}compete\u{0020}with\u{0020}others\u{0020}in\u{0020}even\u{0020}the\u{0020}smallest\u{0020}parts\u{0020}of\u{0020}daily\u{0020}life.\u{0020}You\u{0020}never\u{0020}know\u{0020}when\u{0020}Mikael\u{0020}might\u{0020}decide\u{0020}that\u{0020}you\u{0020}are\u{0020}her\u{0020}rival.\n\u{3000}\u{3000}For\u{0020}the\u{0020}sake\u{0020}of\u{0020}victory,\u{0020}Mikael\u{0020}will\u{0020}do\u{0020}whatever\u{0020}it\u{0020}takes\u{0020}to\u{0020}improve\u{0020}herself.\u{0020}That\u{0020}is\u{0020}also\u{0020}why\u{0020}she\u{0020}chose\u{0020}to\u{0020}join\u{0020}the\u{0020}Dragon\u{0020}Knights.\u{0020}The\u{0020}armor\u{0020}used\u{0020}by\u{0020}the\u{0020}Dragon\u{0020}Knights\u{0020}can\u{0020}absorb\u{0020}Haze\u{0020}and\u{0020}convert\u{0020}it\u{0020}into\u{0020}energy.\u{0020}This\u{0020}means\u{0020}they\u{0020}can\u{0020}fight\u{0020}longer\u{0020}than\u{0020}other\u{0020}Drivers,\u{0020}and\u{0020}it\u{0020}also\u{0020}means\u{0020}Mikael\u{0020}can\u{0020}earn\u{0020}more\u{0020}military\u{0020}achievements\u{0020}than\u{0020}anyone\u{0020}else.\n\u{3000}\u{3000}Even\u{0020}so,\u{0020}Mikael\u{0020}has\u{0020}not\u{0020}achieved\u{0020}total\u{0020}victory.\u{0020}Her\u{0020}teammate\u{0020}Fafnir\u{0020}is\u{0020}every\u{0020}bit\u{0020}her\u{0020}equal\u{0020}when\u{0020}it\u{0020}comes\u{0020}to\u{0020}madness\u{0020}in\u{0020}battle,\u{0020}and\u{0020}may\u{0020}even\u{0020}surpass\u{0020}her.", "0", "0", "0", "0", 11059, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[615902] = {615902, 500, "\u{3000}\u{3000}Open\u{0020}any\u{0020}Danube\u{0020}history\u{0020}textbook,\u{0020}and\u{0020}you\u{0020}will\u{0020}find\u{0020}that\u{0020}over\u{0020}the\u{0020}past\u{0020}several\u{0020}centuries,\u{0020}many\u{0020}respected\u{0020}celebrities\u{0020}and\u{0020}scholars\u{0020}were\u{0020}born\u{0020}on\u{0020}this\u{0020}fractured\u{0020}land\u{0020}of\u{0020}Danube,\u{0020}but\u{0020}there\u{0020}were\u{0020}even\u{0020}more\u{0020}cruel\u{0020}and\u{0020}tyrannical\u{0020}kings\u{0020}and\u{0020}generals.\n\u{3000}\u{3000}The\u{0020}most\u{0020}terrifying\u{0020}among\u{0020}them\u{0020}was\u{0020}Emperor\u{0020}Claudius,\u{0020}known\u{0020}to\u{0020}scholars\u{0020}as\u{0020}the\u{0020}\"Iron\u{0020}Tyrant.\"\u{0020}The\u{0020}\"iron\"\u{0020}referred\u{0020}to\u{0020}his\u{0020}cold\u{0020}cruelty.\u{0020}Not\u{0020}toward\u{0020}civilians,\u{0020}nor\u{0020}toward\u{0020}his\u{0020}enemies,\u{0020}but\u{0020}toward\u{0020}his\u{0020}own\u{0020}descendants.\u{0020}Emperor\u{0020}Claudius\u{0020}had\u{0020}many\u{0020}children,\u{0020}but\u{0020}only\u{0020}one\u{0020}lived\u{0020}past\u{0020}the\u{0020}coming-of-age\u{0020}ceremony.\u{0020}He\u{0020}gave\u{0020}each\u{0020}child\u{0020}a\u{0020}sword\u{0020}when\u{0020}they\u{0020}turned\u{0020}16,\u{0020}then\u{0020}made\u{0020}them\u{0020}kill\u{0020}one\u{0020}another.\n\u{3000}\u{3000}Mikael's\u{0020}mother,\u{0020}however,\u{0020}shared\u{0020}the\u{0020}same\u{0020}child-rearing\u{0020}philosophy\u{0020}as\u{0020}Emperor\u{0020}Claudius.\u{0020}Although\u{0020}she\u{0020}did\u{0020}not\u{0020}have\u{0020}that\u{0020}many\u{0020}children,\u{0020}five\u{0020}in\u{0020}total\u{0020}including\u{0020}Mikael,\u{0020}and\u{0020}she\u{0020}was\u{0020}not\u{0020}so\u{0020}cruel\u{0020}as\u{0020}to\u{0020}make\u{0020}them\u{0020}kill\u{0020}one\u{0020}another.\u{0020}Even\u{0020}so,\u{0020}Mikael\u{0020}and\u{0020}the\u{0020}others\u{0020}were\u{0020}instilled\u{0020}from\u{0020}childhood\u{0020}with\u{0020}the\u{0020}obsessive\u{0020}belief\u{0020}that\u{0020}\"the\u{0020}winner\u{0020}takes\u{0020}all.\"\u{0020}Studies,\u{0020}physical\u{0020}ability,\u{0020}practical\u{0020}skills...\u{0020}Every\u{0020}comparable\u{0020}ability\u{0020}was\u{0020}recorded\u{0020}and\u{0020}tallied\u{0020}together.\u{0020}Only\u{0020}the\u{0020}single\u{0020}winner\u{0020}could\u{0020}receive\u{0020}\"motherly\u{0020}love\"\u{0020}and\u{0020}truly\u{0020}live\u{0020}in\u{0020}this\u{0020}home\u{0020}without\u{0020}warmth,\u{0020}while\u{0020}the\u{0020}losers\u{0020}could\u{0020}only\u{0020}barely\u{0020}survive.\n\u{3000}\u{3000}To\u{0020}outsiders,\u{0020}Mikael,\u{0020}who\u{0020}successfully\u{0020}graduated\u{0020}from\u{0020}Azure\u{0020}Academy\u{0020}and\u{0020}joined\u{0020}the\u{0020}Dragon\u{0020}Knights,\u{0020}was\u{0020}naturally\u{0020}the\u{0020}winner\u{0020}of\u{0020}the\u{0020}family.\u{0020}But\u{0020}Mikael\u{0020}herself\u{0020}rarely\u{0020}talks\u{0020}about\u{0020}it,\u{0020}and\u{0020}even\u{0020}seems\u{0020}to\u{0020}avoid\u{0020}the\u{0020}topic.\n\u{3000}\u{3000}Mikael\u{0020}knows\u{0020}that\u{0020}she\u{0020}has\u{0020}always\u{0020}been\u{0020}the\u{0020}winner,\u{0020}monopolizing\u{0020}\"motherly\u{0020}love\"\u{0020}and\u{0020}everything\u{0020}in\u{0020}the\u{0020}family.\u{0020}She\u{0020}has\u{0020}never\u{0020}lost\u{0020}to\u{0020}her\u{0020}siblings,\u{0020}not\u{0020}even\u{0020}once.\u{0020}But\u{0020}whenever\u{0020}she\u{0020}sees\u{0020}those\u{0020}gaunt,\u{0020}starving\u{0020}faces\u{0020}that\u{0020}resemble\u{0020}her\u{0020}own,\u{0020}Mikael\u{0020}cannot\u{0020}help\u{0020}wondering\u{0020}whether\u{0020}this\u{0020}is\u{0020}truly\u{0020}right.\u{0020}Splitting\u{0020}a\u{0020}family\u{0020}into\u{0020}winners\u{0020}and\u{0020}losers,\u{0020}letting\u{0020}the\u{0020}winner\u{0020}possess\u{0020}everything\u{0020}while\u{0020}the\u{0020}losers\u{0020}have\u{0020}nothing\u{0020}at\u{0020}all.\u{0020}Is\u{0020}a\u{0020}family\u{0020}relationship\u{0020}like\u{0020}that\u{0020}really\u{0020}normal?\n\u{3000}\u{3000}\"I\u{0020}learned\u{0020}a\u{0020}word\u{0020}from\u{0020}a\u{0020}textbook\u{0020}called\u{0020}'sharing,'\u{0020}but\u{0020}Mother\u{0020}said\u{0020}that\u{0020}was\u{0020}a\u{0020}lie\u{0020}told\u{0020}by\u{0020}losers.\"\n\u{3000}\u{3000}Mikael\u{0020}fears\u{0020}failure,\u{0020}and\u{0020}fears\u{0020}even\u{0020}more\u{0020}the\u{0020}thought\u{0020}of\u{0020}falling\u{0020}into\u{0020}the\u{0020}same\u{0020}state\u{0020}as\u{0020}her\u{0020}siblings.\u{0020}That\u{0020}is\u{0020}why\u{0020}she\u{0020}must\u{0020}abandon\u{0020}the\u{0020}empathy\u{0020}that\u{0020}only\u{0020}losers\u{0020}would\u{0020}possess.\n\u{3000}\u{3000}Only\u{0020}by\u{0020}numbing\u{0020}herself\u{0020}with\u{0020}victory\u{0020}after\u{0020}victory\u{0020}can\u{0020}she\u{0020}overcome\u{0020}the\u{0020}conscience\u{0020}lurking\u{0020}within\u{0020}her\u{0020}body.", "0", "0", "0", "0", 11059, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[615903] = {615903, 1000, "\u{3000}\u{3000}The\u{0020}first\u{0020}time\u{0020}Mikael\u{0020}put\u{0020}on\u{0020}Dragon\u{0020}Knights\u{0020}armor\u{0020}and\u{0020}fought\u{0020}a\u{0020}Sin,\u{0020}she\u{0020}became\u{0020}completely\u{0020}immersed\u{0020}in\u{0020}the\u{0020}thrill\u{0020}of\u{0020}victory\u{0020}in\u{0020}battle.\u{0020}As\u{0020}the\u{0020}number\u{0020}of\u{0020}Sins\u{0020}she\u{0020}killed\u{0020}continued\u{0020}to\u{0020}rise,\u{0020}her\u{0020}behavior\u{0020}became\u{0020}more\u{0020}and\u{0020}more\u{0020}uncontrollable.\u{0020}After\u{0020}wiping\u{0020}out\u{0020}all\u{0020}the\u{0020}Sins\u{0020}around\u{0020}her,\u{0020}Mikael\u{0020}turned\u{0020}her\u{0020}sights\u{0020}toward\u{0020}every\u{0020}object\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}that\u{0020}rose\u{0020}above\u{0020}a\u{0020}certain\u{0020}height\u{0020}from\u{0020}the\u{0020}ground.\n\u{3000}\u{3000}That\u{0020}battle\u{0020}eventually\u{0020}turned\u{0020}into\u{0020}a\u{0020}scene\u{0020}of\u{0020}an\u{0020}evil\u{0020}dragon\u{0020}ravaging\u{0020}the\u{0020}scorched\u{0020}earth\u{0020}beneath\u{0020}its\u{0020}feet\u{0020}over\u{0020}and\u{0020}over\u{0020}again.\u{0020}Even\u{0020}now,\u{0020}if\u{0020}you\u{0020}go\u{0020}to\u{0020}that\u{0020}place,\u{0020}you\u{0020}can\u{0020}still\u{0020}smell\u{0020}the\u{0020}scorched\u{0020}scent\u{0020}of\u{0020}the\u{0020}soil.\u{0020}The\u{0020}young\u{0020}girl's\u{0020}roar\u{0020}echoed\u{0020}through\u{0020}the\u{0020}sky,\u{0020}and\u{0020}you\u{0020}could\u{0020}feel\u{0020}the\u{0020}madness\u{0020}overflowing\u{0020}from\u{0020}every\u{0020}pore\u{0020}of\u{0020}Mikael's\u{0020}body.\u{0020}Then\u{0020}Fafnir,\u{0020}who\u{0020}had\u{0020}likewise\u{0020}fallen\u{0020}into\u{0020}a\u{0020}berserk\u{0020}state,\u{0020}clashed\u{0020}with\u{0020}Mikael,\u{0020}and\u{0020}only\u{0020}when\u{0020}the\u{0020}two\u{0020}were\u{0020}about\u{0020}to\u{0020}exhaust\u{0020}their\u{0020}last\u{0020}bit\u{0020}of\u{0020}energy\u{0020}did\u{0020}the\u{0020}other\u{0020}squad\u{0020}members,\u{0020}who\u{0020}had\u{0020}been\u{0020}standing\u{0020}by\u{0020}on\u{0020}guard,\u{0020}dare\u{0020}to\u{0020}step\u{0020}forward\u{0020}and\u{0020}separate\u{0020}them,\u{0020}release\u{0020}their\u{0020}armor,\u{0020}and\u{0020}retrieve\u{0020}them.\n\u{3000}\u{3000}Afterward,\u{0020}Mikael\u{0020}seemed\u{0020}to\u{0020}have\u{0020}lost\u{0020}her\u{0020}memory\u{0020}of\u{0020}what\u{0020}happened\u{0020}while\u{0020}she\u{0020}was\u{0020}berserk.\u{0020}But\u{0020}compared\u{0020}to\u{0020}things\u{0020}like\u{0020}how\u{0020}to\u{0020}suppress\u{0020}that\u{0020}berserk\u{0020}state\u{0020}in\u{0020}battle,\u{0020}what\u{0020}she\u{0020}cared\u{0020}about\u{0020}more\u{0020}was\u{0020}this:\u{0020}who\u{0020}exactly\u{0020}had\u{0020}been\u{0020}the\u{0020}victor\u{0020}in\u{0020}that\u{0020}battle?", "0", "0", "0", "0", 11059, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[615904] = {615904, 2000, "\u{3000}\u{3000}The\u{0020}ground\u{0020}trembles.\n\u{3000}\u{3000}Buildings\u{0020}collapse.\n\u{3000}\u{3000}People\u{0020}flee.\n\u{3000}\u{3000}This\u{0020}is\u{0020}a\u{0020}war,\u{0020}a\u{0020}war\u{0020}between\u{0020}giants.\n\u{3000}\u{3000}But\u{0020}the\u{0020}giant\u{0020}that\u{0020}belongs\u{0020}to\u{0020}humanity\u{0020}has\u{0020}already\u{0020}fallen,\u{0020}and\u{0020}the\u{0020}outcome\u{0020}seems\u{0020}all\u{0020}but\u{0020}decided.\n\u{3000}\u{3000}Just\u{0020}then,\u{0020}a\u{0020}dragon's\u{0020}roar\u{0020}rings\u{0020}out\u{0020}from\u{0020}the\u{0020}sky.\n\u{3000}\u{3000}A\u{0020}magnificent\u{0020}lance\u{0020}tears\u{0020}through\u{0020}the\u{0020}heavens\u{0020}and\u{0020}pierces\u{0020}the\u{0020}metallic\u{0020}body\u{0020}of\u{0020}the\u{0020}giant\u{0020}before\u{0020}them.\n\u{3000}\u{3000}The\u{0020}fleeing\u{0020}crowds\u{0020}stop\u{0020}one\u{0020}after\u{0020}another\u{0020}and\u{0020}look\u{0020}up\u{0020}into\u{0020}the\u{0020}sky.\n\u{3000}\u{3000}An\u{0020}angel?\u{0020}A\u{0020}dragon?\n\u{3000}\u{3000}That\u{0020}does\u{0020}not\u{0020}matter.\n\u{3000}\u{3000}What\u{0020}matters\u{0020}is\u{0020}that\u{0020}victory\u{0020}has\u{0020}already\u{0020}begun\u{0020}to\u{0020}tilt\u{0020}toward\u{0020}humanity.", "0", "0", "0", "0", 11059, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
