[616101] = {616101, 100, "\u{3000}\u{3000}Mira\u{0020}Kamiunten\u{0020}may\u{0020}look\u{0020}like\u{0020}a\u{0020}delinquent\u{0020}(and\u{0020}perhaps\u{0020}she\u{0020}once\u{0020}was),\u{0020}but\u{0020}she\u{0020}is\u{0020}in\u{0020}fact\u{0020}the\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}Second\u{0020}Squad.\u{0020}\n\u{3000}\u{3000}She\u{0020}is\u{0020}widely\u{0020}recognized\u{0020}within\u{0020}the\u{0020}Force\u{0020}as\u{0020}a\u{0020}\"delinquent\u{0020}girl\".\u{0020}She\u{0020}is\u{0020}always\u{0020}draped\u{0020}in\u{0020}a\u{0020}tokko-fuku,\u{0020}speaks\u{0020}roughly,\u{0020}and\u{0020}is\u{0020}quick\u{0020}to\u{0020}threaten\u{0020}to\u{0020}beat\u{0020}someone\u{0020}up.\u{0020}\n\u{3000}\u{3000}But\u{0020}if\u{0020}you\u{0020}keep\u{0020}your\u{0020}distance\u{0020}because\u{0020}of\u{0020}that\u{0020}fierce\u{0020}exterior,\u{0020}you\u{0020}will\u{0020}miss\u{0020}what\u{0020}she\u{0020}really\u{0020}is:\u{0020}a\u{0020}kindhearted,\u{0020}good\u{0020}girl.\u{0020}Beneath\u{0020}the\u{0020}violent\u{0020}words\u{0020}and\u{0020}actions\u{0020}is\u{0020}a\u{0020}heart\u{0020}more\u{0020}delicate\u{0020}than\u{0020}anyone's,\u{0020}one\u{0020}that\u{0020}knows\u{0020}how\u{0020}to\u{0020}think\u{0020}for\u{0020}others.\u{0020}\n\u{3000}\u{3000}She\u{0020}has\u{0020}an\u{0020}instinctive\u{0020}urge\u{0020}to\u{0020}protect\u{0020}the\u{0020}weak.\u{0020}She\u{0020}might\u{0020}spit\u{0020}out\u{0020}\"useless\u{0020}brat\",\u{0020}but\u{0020}her\u{0020}body\u{0020}will\u{0020}honestly\u{0020}move\u{0020}to\u{0020}stand\u{0020}in\u{0020}front\u{0020}of\u{0020}them.\u{0020}To\u{0020}comrades\u{0020}she\u{0020}acknowledges,\u{0020}she\u{0020}shows\u{0020}absolute\u{0020}loyalty,\u{0020}a\u{0020}dependable\u{0020}big\u{0020}sister\u{0020}who\u{0020}would\u{0020}shoulder\u{0020}the\u{0020}burden\u{0020}with\u{0020}you\u{0020}even\u{0020}if\u{0020}the\u{0020}world\u{0020}were\u{0020}ending.\u{0020}\n\u{3000}\u{3000}Her\u{0020}Peach\u{0020}Blessing\u{0020}is\u{0020}All-Killing.\u{0020}It\u{0020}can\u{0020}create\u{0020}dozens,\u{0020}even\u{0020}hundreds,\u{0020}of\u{0020}clones\u{0020}identical\u{0020}to\u{0020}her\u{0020}in\u{0020}both\u{0020}capability\u{0020}and\u{0020}physical\u{0020}ability,\u{0020}a\u{0020}powerful\u{0020}ability\u{0020}that\u{0020}lets\u{0020}her\u{0020}form\u{0020}an\u{0020}army\u{0020}all\u{0020}by\u{0020}herself.", "0", "0", "0", "0", 11061, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[616102] = {616102, 500, "\u{3000}\u{3000}Although\u{0020}this\u{0020}is\u{0020}not\u{0020}her\u{0020}own\u{0020}world,\u{0020}and\u{0020}those\u{0020}here\u{0020}are\u{0020}not\u{0020}people\u{0020}who\u{0020}require\u{0020}the\u{0020}protection\u{0020}of\u{0020}the\u{0020}\"Demon\u{0020}Defense\u{0020}Force\".\u{0020}\n\u{3000}\u{3000}As\u{0020}the\u{0020}leader\u{0020}of\u{0020}the\u{0020}Second\u{0020}Squad,\u{0020}Mira\u{0020}Kamiunten\u{0020}continues\u{0020}to\u{0020}fulfill\u{0020}her\u{0020}duty\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}strong\u{0020}and\u{0020}as\u{0020}a\u{0020}captain,\u{0020}even\u{0020}in\u{0020}this\u{0020}unfamiliar\u{0020}other\u{0020}world.\u{0020}She\u{0020}protects\u{0020}innocent\u{0020}civilians\u{0020}and\u{0020}shields\u{0020}them\u{0020}from\u{0020}the\u{0020}threat\u{0020}of\u{0020}monsters.\u{0020}\n\u{3000}\u{3000}This\u{0020}instinct\u{0020}to\u{0020}act\u{0020}before\u{0020}thinking\u{0020}may\u{0020}well\u{0020}be\u{0020}the\u{0020}very\u{0020}reason\u{0020}she\u{0020}was\u{0020}able\u{0020}to\u{0020}become\u{0020}the\u{0020}commander\u{0020}of\u{0020}the\u{0020}Second\u{0020}Squad\u{0020}in\u{0020}the\u{0020}first\u{0020}place.\u{0020}\n\u{3000}\u{3000}For\u{0020}her,\u{0020}protecting\u{0020}innocent\u{0020}civilians\u{0020}and\u{0020}protecting\u{0020}the\u{0020}gentle\u{0020}and\u{0020}vulnerable\u{0020}Angelica\u{0020}may\u{0020}very\u{0020}well\u{0020}take\u{0020}precedence\u{0020}over\u{0020}her\u{0020}own\u{0020}life.\u{0020}Of\u{0020}course,\u{0020}she\u{0020}likely\u{0020}has\u{0020}never\u{0020}rationally\u{0020}weighed\u{0020}whether\u{0020}the\u{0020}life\u{0020}of\u{0020}a\u{0020}squad\u{0020}commander\u{0020}is\u{0020}more\u{0020}important\u{0020}than\u{0020}that\u{0020}of\u{0020}an\u{0020}ordinary\u{0020}person.\u{0020}\n\u{3000}\u{3000}To\u{0020}place\u{0020}lives\u{0020}upon\u{0020}a\u{0020}scale\u{0020}and\u{0020}measure\u{0020}their\u{0020}worth\u{0020}would,\u{0020}to\u{0020}her,\u{0020}be\u{0020}an\u{0020}act\u{0020}of\u{0020}sacrilege\u{0020}in\u{0020}itself.\u{0020}\n\u{3000}\u{3000}Perhaps\u{0020}it\u{0020}is\u{0020}precisely\u{0020}because\u{0020}she\u{0020}possesses\u{0020}such\u{0020}a\u{0020}pure\u{0020}and\u{0020}untainted\u{0020}heart\u{0020}that,\u{0020}in\u{0020}that\u{0020}moment,\u{0020}she\u{0020}stepped\u{0020}forward\u{0020}and\u{0020}stood\u{0020}in\u{0020}front\u{0020}of\u{0020}Ren\u{0020}Yamashiro.\u{0020}Knowing\u{0020}full\u{0020}well\u{0020}the\u{0020}overwhelming\u{0020}strength\u{0020}of\u{0020}the\u{0020}Supreme\u{0020}Commander,\u{0020}she\u{0020}could\u{0020}not\u{0020}have\u{0020}been\u{0020}unaware\u{0020}that\u{0020}such\u{0020}an\u{0020}act\u{0020}was\u{0020}meaningless.\u{0020}\n\u{3000}\u{3000}And\u{0020}yet,\u{0020}even\u{0020}if\u{0020}it\u{0020}was\u{0020}meaningless,\u{0020}even\u{0020}if\u{0020}there\u{0020}was\u{0020}no\u{0020}chance\u{0020}of\u{0020}success,\u{0020}she\u{0020}would\u{0020}still\u{0020}act.\u{0020}She\u{0020}would\u{0020}still\u{0020}move\u{0020}to\u{0020}save\u{0020}those\u{0020}who\u{0020}ought\u{0020}to\u{0020}be\u{0020}saved.\u{0020}\n\u{3000}\u{3000}That\u{0020}is\u{0020}Mira\u{0020}Kamiunten,\u{0020}the\u{0020}commander\u{0020}of\u{0020}the\u{0020}Second\u{0020}Squad.", "0", "0", "0", "0", 11061, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[616103] = {616103, 1000, "\u{3000}\u{3000}Thank\u{0020}you\u{0020}for\u{0020}everything\u{0020}you've\u{0020}done\u{0020}for\u{0020}me.\u{0020}\n\u{3000}\u{3000}Although\u{0020}Angelica\u{0020}was\u{0020}frightened\u{0020}at\u{0020}first\u{0020}by\u{0020}Mira\u{0020}Kamiunten's\u{0020}fierce\u{0020}and\u{0020}intimidating\u{0020}demeanor,\u{0020}if\u{0020}the\u{0020}opportunity\u{0020}ever\u{0020}arises,\u{0020}she\u{0020}would\u{0020}like\u{0020}to\u{0020}properly,\u{0020}and\u{0020}more\u{0020}politely,\u{0020}express\u{0020}her\u{0020}gratitude\u{0020}to\u{0020}her.\u{0020}\n\u{3000}\u{3000}Even\u{0020}though\u{0020}they\u{0020}spent\u{0020}less\u{0020}than\u{0020}three\u{0020}short\u{0020}days\u{0020}together,\u{0020}Angelica\u{0020}was\u{0020}still\u{0020}able\u{0020}to\u{0020}feel\u{0020}it:\u{0020}that\u{0020}warmth\u{0020}of\u{0020}Mira's,\u{0020}whether\u{0020}one\u{0020}might\u{0020}call\u{0020}it\u{0020}clumsy\u{0020}or\u{0020}simply\u{0020}straightforward.\u{0020}\n\u{3000}\u{3000}Despite\u{0020}the\u{0020}fact\u{0020}that\u{0020}Mira\u{0020}herself\u{0020}was\u{0020}the\u{0020}one\u{0020}truly\u{0020}at\u{0020}a\u{0020}loss,\u{0020}an\u{0020}otherworldly\u{0020}drifter\u{0020}cast\u{0020}into\u{0020}an\u{0020}unfamiliar\u{0020}land,\u{0020}it\u{0020}was\u{0020}Mira\u{0020}who\u{0020}tried\u{0020}to\u{0020}comfort\u{0020}her,\u{0020}who\u{0020}tried\u{0020}to\u{0020}protect\u{0020}her\u{0020}as\u{0020}the\u{0020}\"weaker\"\u{0020}one.\u{0020}\n\u{3000}\u{3000}There\u{0020}has\u{0020}never\u{0020}been\u{0020}any\u{0020}rule\u{0020}in\u{0020}this\u{0020}world\u{0020}that\u{0020}demands\u{0020}the\u{0020}strong\u{0020}must\u{0020}protect\u{0020}the\u{0020}weak.\u{0020}And\u{0020}yet,\u{0020}Mira\u{0020}Kamiunten\u{0020}chose\u{0020}to\u{0020}do\u{0020}so\u{0020}anyway.\u{0020}\n\u{3000}\u{3000}Thank\u{0020}you\u{0020}for\u{0020}taking\u{0020}care\u{0020}of\u{0020}me,\u{0020}if\u{0020}there\u{0020}is\u{0020}ever\u{0020}another\u{0020}chance...\u{0020}though\u{0020}there\u{0020}most\u{0020}likely\u{0020}won't\u{0020}be\u{0020}one.\u{0020}No\u{0020}matter\u{0020}what,\u{0020}Angelica\u{0020}still\u{0020}hopes\u{0020}to\u{0020}convey\u{0020}these\u{0020}feelings\u{0020}of\u{0020}gratitude\u{0020}to\u{0020}her.\u{0020}\n\u{3000}\u{3000}Thank\u{0020}you.", "0", "0", "0", "0", 11061, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[616104] = {616104, 2000, "\u{3000}\u{3000}\"Leave\u{0020}your\u{0020}back\u{0020}to\u{0020}me\".\u{0020}\n\u{3000}\u{3000}That's\u{0020}not\u{0020}something\u{0020}I\u{0020}say\u{0020}on\u{0020}a\u{0020}whim.\u{0020}\n\u{3000}\u{3000}As\u{0020}long\u{0020}as\u{0020}you're\u{0020}standing\u{0020}behind\u{0020}me,\u{0020}\n\u{3000}\u{3000}I\u{0020}will\u{0020}never\u{0020}go\u{0020}down.\u{0020}\n\u{3000}\u{3000}No\u{0020}matter\u{0020}how\u{0020}powerful\u{0020}the\u{0020}enemy\u{0020}is,\u{0020}\n\u{3000}\u{3000}no\u{0020}matter\u{0020}how\u{0020}many\u{0020}stand\u{0020}in\u{0020}our\u{0020}way,\u{0020}\n\u{3000}\u{3000}I'll\u{0020}punch\u{0020}a\u{0020}path\u{0020}straight\u{0020}through\u{0020}them.\u{0020}\n\u{3000}\u{3000}So\u{0020}don't\u{0020}give\u{0020}me\u{0020}that\u{0020}worried\u{0020}look.\u{0020}\n\u{3000}\u{3000}Just\u{0020}stay\u{0020}close\u{0020}and\u{0020}follow\u{0020}my\u{0020}lead.", "0", "0", "0", "0", 11061, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[620000] = {620000, 0, "[Name]\u{0020}Kinkura\n[B-Day]\u{0020}Dec\u{0020}2\n[Compatability\u{0020}Rate]\u{0020}76％\n[Height]\u{0020}27m\n[Squad]\u{0020}Soul\u{0020}Destroyers\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Lucrative\u{0020}things", "0", "0", "0", "0", 12000, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}金库啦\n[B-Day]\u{1000}12月2日\n[幻化核心适格率]\u{1000}76％\n[Height]\u{1000}27m\n[部队]\u{1000}魂灭\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}一本万利的事"},
[620001] = {620001, 100, "\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}\"Soul\u{0020}Destroyer\",\u{0020}responsible\u{0020}for\u{0020}the\u{0020}daily\u{0020}expenses\u{0020}of\u{0020}the\u{0020}Soul\u{0020}Destroyer.\u{0020}Unreliable\u{0020}gossip\u{0020}claims\u{0020}that\u{0020}she\u{0020}is\u{0020}also\u{0020}one\u{0020}of\u{0020}the\u{0020}sponsors\u{0020}of\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters.\n\nThe\u{0020}way\u{0020}she\u{0020}measures\u{0020}the\u{0020}value\u{0020}of\u{0020}things\u{0020}will\u{0020}cause\u{0020}dissatisfaction\u{0020}among\u{0020}some\u{0020}people.\u{0020}She\u{0020}believes\u{0020}that\u{0020}most\u{0020}things\u{0020}in\u{0020}the\u{0020}world\u{0020}can\u{0020}be\u{0020}solved\u{0020}by\u{0020}money.\u{0020}Equipment\u{0020}can\u{0020}be\u{0020}bought\u{0020}with\u{0020}money,\u{0020}talents\u{0020}can\u{0020}be\u{0020}recruited\u{0020}with\u{0020}money,\u{0020}and\u{0020}even\u{0020}major\u{0020}crises\u{0020}can\u{0020}be\u{0020}solved\u{0020}with\u{0020}money.\u{0020}To\u{0020}put\u{0020}it\u{0020}bluntly,\u{0020}she\u{0020}holds\u{0020}the\u{0020}idea\u{0020}that\u{0020}money\u{0020}can\u{0020}solve\u{0020}all\u{0020}problems.\n\nBesides\u{0020}this,\u{0020}she\u{0020}doesn't\u{0020}hide\u{0020}her\u{0020}ambition\u{0020}at\u{0020}all.\u{0020}She\u{0020}once\u{0020}said\u{0020}in\u{0020}public\u{0020}that\u{0020}she\u{0020}wanted\u{0020}to\u{0020}build\u{0020}her\u{0020}own\u{0020}business\u{0020}empire,\u{0020}and\u{0020}AEGIS\u{0020}would\u{0020}also\u{0020}become\u{0020}a\u{0020}part\u{0020}of\u{0020}her\u{0020}enterprise\u{0020}in\u{0020}the\u{0020}near\u{0020}future.\u{0020}To\u{0020}achieve\u{0020}her\u{0020}ambition,\u{0020}she\u{0020}is\u{0020}now\u{0020}actively\u{0020}drawing\u{0020}in\u{0020}available\u{0020}talents.\n\nHowever,\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}most\u{0020}people,\u{0020}this\u{0020}is\u{0020}just\u{0020}a\u{0020}not-yet-grown-up\u{0020}child\u{0020}making\u{0020}trouble.", "0", "0", "0", "0", 12000, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"魂灭\"的成员之一，负责魂灭小队的日常开支。有不可靠的小道消息称，她同时还是艾吉斯九州总部的赞助商之一。\n\u{1000}\u{1000}她衡量事物价值的方式会引起一部分人的不满。她认为世界上大部分的事情都可以依靠金钱来解决，没有装备可以用钱买，缺乏人才可以用金钱挖，即便是大危机也可以依靠金钱来解决问题。说白了，她抱着用钱就可以摆平一切问题的想法。\n\u{1000}\u{1000}在此之外，她丝毫不掩饰自己的野心，她曾经在公开场合说要建立自己的商业帝国，而艾吉斯在不久的未来也会成为她企业的一部分。\n\u{1000}\u{1000}为了实现自己的野心，现在她正在积极地拉拢着可以利用的人才。\n\u{1000}\u{1000}不过，在大部分人眼中，这也不过是个还没长大的孩子在胡闹罢了。"},
[620002] = {620002, 500, "\u{0020}\u{0020}The\u{0020}academy\u{0020}of\u{0020}AEGIS\u{0020}is\u{0020}responsible\u{0020}for\u{0020}cultivating\u{0020}and\u{0020}sending\u{0020}outstanding\u{0020}navigators\u{0020}to\u{0020}AEGIS\u{0020}to\u{0020}resist\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Sin.\u{0020}And\u{0020}Kinkura's\u{0020}grandfather\u{0020}was\u{0020}one\u{0020}of\u{0020}the\u{0020}earliest\u{0020}merchants\u{0020}who\u{0020}sponsored\u{0020}the\u{0020}construction\u{0020}of\u{0020}the\u{0020}academy\u{0020}for\u{0020}the\u{0020}AEGIS\u{0020}government.\u{0020}He\u{0020}was\u{0020}renowned\u{0020}in\u{0020}the\u{0020}business\u{0020}world\u{0020}for\u{0020}his\u{0020}excellent\u{0020}business\u{0020}acumen\u{0020}and\u{0020}decisiveness.\u{0020}Moreover,\u{0020}during\u{0020}the\u{0020}period\u{0020}when\u{0020}the\u{0020}AEGIS\u{0020}government\u{0020}took\u{0020}over\u{0020}Kyushu,\u{0020}he\u{0020}became\u{0020}one\u{0020}of\u{0020}the\u{0020}few\u{0020}merchants\u{0020}whose\u{0020}property\u{0020}not\u{0020}only\u{0020}remained\u{0020}intact\u{0020}but\u{0020}increased.\n\nKinkura\u{0020}inherited\u{0020}her\u{0020}grandfather's\u{0020}outstanding\u{0020}merchant\u{0020}mind\u{0020}and\u{0020}had\u{0020}adult-like\u{0020}thinking\u{0020}and\u{0020}handling\u{0020}abilities\u{0020}when\u{0020}she\u{0020}was\u{0020}still\u{0020}young.\u{0020}Relying\u{0020}on\u{0020}her\u{0020}grandfather's\u{0020}connections,\u{0020}she\u{0020}built\u{0020}her\u{0020}own\u{0020}business\u{0020}company\u{0020}and\u{0020}became\u{0020}a\u{0020}newcomer\u{0020}on\u{0020}the\u{0020}capital's\u{0020}rich\u{0020}list\u{0020}after\u{0020}operating\u{0020}the\u{0020}company\u{0020}for\u{0020}several\u{0020}years.\n\nAfter\u{0020}the\u{0020}initial\u{0020}success\u{0020}of\u{0020}her\u{0020}career,\u{0020}Kinkura\u{0020}turned\u{0020}her\u{0020}attention\u{0020}to\u{0020}her\u{0020}next\u{0020}target,\u{0020}the\u{0020}driver's\u{0020}academy,\u{0020}a\u{0020}facility\u{0020}her\u{0020}grandfather\u{0020}had\u{0020}funded.\n\nWhether\u{0020}it\u{0020}is\u{0020}reaching\u{0020}into\u{0020}the\u{0020}AEGIS\u{0020}headquarters\u{0020}by\u{0020}taking\u{0020}the\u{0020}academy\u{0020}as\u{0020}an\u{0020}opportunity,\u{0020}or\u{0020}signing\u{0020}a\u{0020}lifetime\u{0020}endorsement\u{0020}contract\u{0020}with\u{0020}a\u{0020}driver\u{0020}who\u{0020}seems\u{0020}to\u{0020}have\u{0020}star\u{0020}potential,\u{0020}it\u{0020}is\u{0020}a\u{0020}good\u{0020}opportunity\u{0020}for\u{0020}Kinkura,\u{0020}who\u{0020}is\u{0020}still\u{0020}developing\u{0020}her\u{0020}own\u{0020}influence.\n\nAfter\u{0020}convincing\u{0020}herself\u{0020}with\u{0020}the\u{0020}above\u{0020}reasons,\u{0020}Kinkura\u{0020}accepted\u{0020}the\u{0020}sincere\u{0020}invitation\u{0020}of\u{0020}her\u{0020}friend\u{0020}Lulula\u{0020}and\u{0020}became\u{0020}a\u{0020}student\u{0020}of\u{0020}the\u{0020}driver's\u{0020}Academy.\n\nDuring\u{0020}her\u{0020}time\u{0020}at\u{0020}the\u{0020}academy,\u{0020}Kinkura\u{0020}attempted\u{0020}to\u{0020}establish\u{0020}monetary\u{0020}contract\u{0020}relationships\u{0020}with\u{0020}the\u{0020}reserve\u{0020}drivers\u{0020}in\u{0020}the\u{0020}academy\u{0020}in\u{0020}various\u{0020}ways.\n\nHer\u{0020}behavior\u{0020}was\u{0020}detected\u{0020}by\u{0020}the\u{0020}senior\u{0020}management\u{0020}of\u{0020}AEGIS.\u{0020}After\u{0020}a\u{0020}series\u{0020}of\u{0020}investigations,\u{0020}AEGIS\u{0020}issued\u{0020}an\u{0020}official\u{0020}announcement:\u{0020}drivers\u{0020}are\u{0020}prohibited\u{0020}from\u{0020}conducting\u{0020}business\u{0020}activities\u{0020}during\u{0020}their\u{0020}time\u{0020}at\u{0020}the\u{0020}academy.\u{0020}Apparently,\u{0020}Kinkura's\u{0020}wishful\u{0020}thinking\u{0020}was\u{0020}thwarted\u{0020}by\u{0020}AEGIS.\n\n\"The\u{0020}bunch\u{0020}of\u{0020}brutes\u{0020}from\u{0020}AEGIS\u{0020}simply\u{0020}don't\u{0020}understand\u{0020}my\u{0020}thoughts.\u{0020}They\u{0020}are\u{0020}squandering\u{0020}precious\u{0020}resources\u{0020}and\u{0020}will\u{0020}be\u{0020}punished\u{0020}by\u{0020}heaven!\"\u{0020}-\u{0020}Even\u{0020}to\u{0020}this\u{0020}day,\u{0020}she\u{0020}still\u{0020}harbors\u{0020}resentment\u{0020}over\u{0020}this,\u{0020}believing\u{0020}that\u{0020}AEGIS's\u{0020}actions\u{0020}have\u{0020}caused\u{0020}her\u{0020}to\u{0020}lose\u{0020}countless\u{0020}benefits\u{0020}for\u{0020}no\u{0020}reason.\n\nKinkura's\u{0020}obsession\u{0020}with\u{0020}money\u{0020}is\u{0020}also\u{0020}curious.\u{0020}After\u{0020}all,\u{0020}with\u{0020}her\u{0020}outstanding\u{0020}business\u{0020}mind,\u{0020}she\u{0020}is\u{0020}bound\u{0020}to\u{0020}inherit\u{0020}her\u{0020}grandfather's\u{0020}consortium\u{0020}and\u{0020}become\u{0020}the\u{0020}richest\u{0020}person\u{0020}in\u{0020}Kyushu.\u{0020}She\u{0020}could\u{0020}simply\u{0020}enjoy\u{0020}the\u{0020}fruits\u{0020}of\u{0020}her\u{0020}inheritance\u{0020}without\u{0020}being\u{0020}so\u{0020}obsessed\u{0020}with\u{0020}building\u{0020}her\u{0020}own\u{0020}business.\n\nThe\u{0020}media\u{0020}believe\u{0020}that\u{0020}she\u{0020}is\u{0020}merely\u{0020}addicted\u{0020}to\u{0020}this\u{0020}behavior\u{0020}of\u{0020}accumulating\u{0020}capital\u{0020}and\u{0020}enjoys\u{0020}the\u{0020}thrill\u{0020}of\u{0020}her\u{0020}wealth\u{0020}growth.\u{0020}But\u{0020}the\u{0020}drivers\u{0020}who\u{0020}are\u{0020}with\u{0020}her\u{0020}day\u{0020}and\u{0020}night\u{0020}defend\u{0020}her\u{0020}like\u{0020}this:\u{0020}Kinkura's\u{0020}wealth\u{0020}can\u{0020}help\u{0020}those\u{0020}in\u{0020}need\u{0020}in\u{0020}a\u{0020}region\u{0020}or\u{0020}a\u{0020}country,\u{0020}but\u{0020}it\u{0020}is\u{0020}far\u{0020}from\u{0020}enough\u{0020}for\u{0020}the\u{0020}scope\u{0020}of\u{0020}\"the\u{0020}whole\u{0020}world\",\u{0020}and\u{0020}this\u{0020}is\u{0020}the\u{0020}reason\u{0020}why\u{0020}she\u{0020}is\u{0020}persistent\u{0020}in\u{0020}amassing\u{0020}wealth.", "0", "0", "0", "0", 12000, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}艾吉斯的学院肩负着培育、向艾吉斯输送优秀驾驶员，来抵抗原罪入侵的职责。而金库啦的祖父，正是最早赞助艾吉斯政府建设学院的商人之一，以优秀的商业眼光与决断在商界闻名，并且在艾吉斯政府接管九州期间，成为了为数不多财产不仅没有受损，反而增多的商人。\n\u{1000}\u{1000}金库啦继承了祖父优秀的商人头脑，在她年龄尚幼的时候就具备了大人般的思维能力和处事能力。她依靠着自己祖父的人脉，打造着自己的商业公司，并且在经营公司数年后成为了首都富豪榜上的新贵。\n\u{1000}\u{1000}在自己的事业初步有成果后，金库啦的目光望向了自己下一个目标，自己祖父投资赞助的设施——驾驶员学院。\n\u{1000}\u{1000}无论是以学院为契机将手伸入艾吉斯总部、亦或是接触到看上去有明星资质的驾驶员签下终身代言合同，对于仍在发展自身势力的金库啦来说都是一个不错的机会。\n\u{1000}\u{1000}——用上述理由说服了自己之后，金库啦接受了好友露露啦真挚的邀请，成为了驾驶员学院的一名学生。\n\u{1000}\u{1000}在学院期间，金库啦试图用各种方式与学院中的预备驾驶员建立金钱契约关系。\n\u{1000}\u{1000}她这一行为被艾吉斯高层察觉，在经过一系列调查后，艾吉斯推出官方公告：驾驶员在校期间禁止进行商业活动。显然，金库啦的如意算盘在艾吉斯的制止下被打翻了。\n\u{1000}\u{1000}\"艾吉斯的那帮莽夫根本不懂得本小姐的想法。他们这是在暴遣天物，是要遭天谴的！\"——时至今日，她对此依然耿耿于怀，认为艾吉斯的行为让她平白损失了数不清的利益。\n\u{1000}\u{1000}金库啦对金钱的执着也引人好奇。毕竟，拥有出众商业头脑的她，必然会继承祖父的财团，成为九州最富有的人。她完全可以坐享其成，不必如此执着于建立自己的事业。\n\u{1000}\u{1000}媒体们认为她只是沉迷这种积累资本的行为，享受自己财富增长的快感。但与她朝夕相处的驾驶员们是这么为她辩解的：金库啦的财富能让一个地区、一个国家里需要帮助的人得到帮助，但对\"全世界\"这个范围来说是远远不够的，这才是她执着于敛财的原因。"},
[620003] = {620003, 1000, "\u{0020}\u{0020}Kinkura\u{0020}is\u{0020}blind\u{0020}to\u{0020}money.\u{0020}She\u{0020}believes\u{0020}that\u{0020}money\u{0020}is\u{0020}omnipotent.\u{0020}In\u{0020}the\u{0020}past,\u{0020}she\u{0020}thought\u{0020}that\u{0020}all\u{0020}the\u{0020}misfortunes\u{0020}people\u{0020}encountered\u{0020}were\u{0020}ultimately\u{0020}due\u{0020}to\u{0020}\"poverty\".\n\nHer\u{0020}grandfather\u{0020}had\u{0020}once\u{0020}warned\u{0020}her,\u{0020}as\u{0020}a\u{0020}veteran,\u{0020}that\u{0020}money\u{0020}can\u{0020}indeed\u{0020}solve\u{0020}almost\u{0020}all\u{0020}problems,\u{0020}but\u{0020}not\u{0020}the\u{0020}value\u{0020}of\u{0020}everything\u{0020}can\u{0020}be\u{0020}measured\u{0020}in\u{0020}money.\n\nIn\u{0020}the\u{0020}past,\u{0020}Kinkura\u{0020}did\u{0020}not\u{0020}understand\u{0020}this\u{0020}statement\u{0020}and\u{0020}only\u{0020}gradually\u{0020}changed\u{0020}her\u{0020}opinion\u{0020}recently.\n\nFriendship,\u{0020}kinship\u{0020}and\u{0020}love,\u{0020}she\u{0020}realized\u{0020}that\u{0020}these\u{0020}things\u{0020}cannot\u{0020}be\u{0020}evaluated\u{0020}in\u{0020}terms\u{0020}of\u{0020}money.\u{0020}And\u{0020}the\u{0020}opportunity\u{0020}that\u{0020}led\u{0020}to\u{0020}such\u{0020}a\u{0020}change\u{0020}in\u{0020}her\u{0020}was\u{0020}precisely\u{0020}the\u{0020}teammates\u{0020}who\u{0020}fought\u{0020}with\u{0020}her,\u{0020}as\u{0020}well\u{0020}as\u{0020}that\u{0020}young\u{0020}navigator.", "0", "0", "0", "0", 12000, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\u{1000}\u{1000}金库啦对于金钱是盲信的，她认为金钱是无所不能的。在过去，她认为人们遭遇的所有不幸，归根结底都是因为\"贫穷\"。\n\u{1000}\u{1000}她的祖父曾以过来人的身份告诫过她，金钱的确能解决几乎所有的问题，但并不是所有事物的价值都可以用金钱去衡量。\n\u{1000}\u{1000}过去的金库啦并不理解这段话，直到最近才渐渐改变了自己的看法。\n\u{1000}\u{1000}友情、亲情、爱情，她认可了这些事物并不是可以用金钱评估价值的。而让她出现如此转变的契机，正是与她一同战斗的队友，以及那位年轻的领航。"},
[620004] = {620004, 2000, "\u{0020}\"It's\u{0020}so\u{0020}stupid;\u{0020}someone\u{0020}actually\u{0020}believes\u{0020}there\u{0020}are\u{0020}things\u{0020}in\u{0020}the\u{0020}world\u{0020}that\u{0020}money\u{0020}can't\u{0020}buy.\"\n\nShe\u{0020}overlooked\u{0020}the\u{0020}city\u{0020}beneath\u{0020}her\u{0020}feet,\u{0020}and\u{0020}her\u{0020}voice\u{0020}gradually\u{0020}carried\u{0020}dissatisfaction.\n\nFood,\u{0020}accommodation,\u{0020}and\u{0020}clothes\u{0020}all\u{0020}cannot\u{0020}be\u{0020}separated\u{0020}from\u{0020}money.\u{0020}Without\u{0020}money,\u{0020}people\u{0020}cannot\u{0020}survive\u{0020}in\u{0020}the\u{0020}world...\u{0020}It\u{0020}is\u{0020}clearly\u{0020}like\u{0020}this.\n\n\"However,\u{0020}I\u{0020}wavered.\u{0020}Kinship,\u{0020}friendship,\u{0020}and...\u{0020}love.\u{0020}Maybe\u{0020}money\u{0020}really\u{0020}can't\u{0020}measure\u{0020}their\u{0020}value...\"\n\n\"It's\u{0020}all\u{0020}your\u{0020}fault!\u{0020}You\u{0020}made\u{0020}me\u{0020}weird.\u{0020}You\u{0020}are\u{0020}responsible\u{0020}for\u{0020}this!\"", "0", "0", "0", "0", 12000, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"真是愚蠢——居然有人认为世界上存在金钱无法衡量的东西。\"\n\u{1000}\u{1000}她俯瞰着脚下的城市，声音渐渐带上不满，\n\u{1000}\u{1000}\"食物、住宿、衣服，都离不开钱。没有钱，人就无法在世界上生存……明明是这样才对。\"\n\u{1000}\u{1000}\"——可是，我动摇了。亲情，友情，还有……爱情，也许钱真的不能衡量它们的价值……\"\n\u{1000}\u{1000}\"都是你的错！你让本小姐不正常了，要负起责任！\""},
[620100] = {620100, 0, "[Name]\u{0020}Gin·Cretia\n[B-Day]\u{0020}Feb\u{0020}29\n[Compatability\u{0020}Rate]\u{0020}80％\n[Height]\u{0020}30m\n[Squad]\u{0020}Cavalier\n[Affiliation]\u{0020}Maya\u{0020}Branch\n[Interest]\u{0020}Video\u{0020}games,\u{0020}junk\u{0020}food", "0", "0", "0", "0", 12001, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[620101] = {620101, 100, "\u{0020}\u{0020}This\u{0020}little\u{0020}girl\u{0020}who\u{0020}is\u{0020}self-indulgent\u{0020}and\u{0020}addicted\u{0020}to\u{0020}junk\u{0020}food\u{0020}is\u{0020}the\u{0020}second\u{0020}daughter\u{0020}of\u{0020}the\u{0020}noble\u{0020}Cretia\u{0020}family.\u{0020}This\u{0020}is\u{0020}indeed\u{0020}a\u{0020}highly\u{0020}confusing\u{0020}objective\u{0020}fact.\n\nShe\u{0020}has\u{0020}repeatedly\u{0020}refreshed\u{0020}people's\u{0020}perception\u{0020}of\u{0020}\"idiot\",\u{0020}proving\u{0020}her\u{0020}extraordinariness\u{0020}with\u{0020}her\u{0020}record-breaking\u{0020}low\u{0020}scores,\u{0020}and\u{0020}her\u{0020}attitude\u{0020}of\u{0020}not\u{0020}being\u{0020}ashamed\u{0020}but\u{0020}even\u{0020}being\u{0020}proud\u{0020}makes\u{0020}people\u{0020}feel\u{0020}hopeless.\n\nShe,\u{0020}who\u{0020}is\u{0020}addicted\u{0020}to\u{0020}games\u{0020}and\u{0020}fond\u{0020}of\u{0020}junk\u{0020}food,\u{0020}often\u{0020}stays\u{0020}in\u{0020}her\u{0020}room\u{0020}and\u{0020}is\u{0020}reluctant\u{0020}to\u{0020}go\u{0020}out.\u{0020}She\u{0020}will\u{0020}never\u{0020}go\u{0020}out\u{0020}if\u{0020}things\u{0020}can\u{0020}be\u{0020}solved\u{0020}in\u{0020}the\u{0020}room,\u{0020}and\u{0020}she\u{0020}will\u{0020}never\u{0020}do\u{0020}things\u{0020}herself\u{0020}if\u{0020}she\u{0020}can\u{0020}make\u{0020}others\u{0020}do\u{0020}them\u{0020}for\u{0020}her.\u{0020}She\u{0020}almost\u{0020}lives\u{0020}a\u{0020}decadent\u{0020}life\u{0020}of\u{0020}having\u{0020}food\u{0020}and\u{0020}clothes\u{0020}handed\u{0020}to\u{0020}her\u{0020}on\u{0020}a\u{0020}plate.\n\nLiving\u{0020}such\u{0020}a\u{0020}decadent\u{0020}life,\u{0020}it\u{0020}is\u{0020}reasonable\u{0020}that\u{0020}her\u{0020}weight\u{0020}keeps\u{0020}increasing.\u{0020}However,\u{0020}she\u{0020}is\u{0020}extremely\u{0020}concerned\u{0020}about\u{0020}it.\u{0020}She\u{0020}weighs\u{0020}herself\u{0020}almost\u{0020}every\u{0020}once\u{0020}in\u{0020}a\u{0020}while\u{0020}and\u{0020}often\u{0020}walks\u{0020}off\u{0020}the\u{0020}scale\u{0020}with\u{0020}a\u{0020}dull\u{0020}expression,\u{0020}murmuring\u{0020}\"Forget\u{0020}it...\"\u{0020}at\u{0020}the\u{0020}end.\n\nShe\u{0020}almost\u{0020}makes\u{0020}people\u{0020}unable\u{0020}to\u{0020}have\u{0020}expectations.\u{0020}She\u{0020}herself\u{0020}has\u{0020}no\u{0020}motivation\u{0020}to\u{0020}move\u{0020}forward.\u{0020}Fortunately,\u{0020}she\u{0020}is\u{0020}an\u{0020}optimist\u{0020}and\u{0020}doesn't\u{0020}have\u{0020}such\u{0020}troubles\u{0020}as\u{0020}\"what\u{0020}to\u{0020}do\u{0020}about\u{0020}her\u{0020}own\u{0020}future\".", "0", "0", "0", "0", 12002, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[620102] = {620102, 500, "\u{0020}\u{0020}The\u{0020}fact\u{0020}that\u{0020}Gin\u{0020}Cretia\u{0020}is\u{0020}not\u{0020}the\u{0020}biological\u{0020}daughter\u{0020}of\u{0020}the\u{0020}current\u{0020}patriarch\u{0020}of\u{0020}Cretia\u{0020}is\u{0020}little\u{0020}known,\u{0020}previously\u{0020}known\u{0020}only\u{0020}to\u{0020}members\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.\n\nThe\u{0020}original\u{0020}name\u{0020}of\u{0020}Gin·Cretia\u{0020}has\u{0020}no\u{0020}way\u{0020}to\u{0020}be\u{0020}traced.\n\nWhen\u{0020}she\u{0020}was\u{0020}still\u{0020}an\u{0020}infant,\u{0020}her\u{0020}parents\u{0020}died\u{0020}in\u{0020}an\u{0020}accident.\u{0020}Just\u{0020}born\u{0020}Gin\u{0020}was\u{0020}about\u{0020}to\u{0020}face\u{0020}the\u{0020}fate\u{0020}of\u{0020}being\u{0020}publicly\u{0020}funded\u{0020}and\u{0020}raised\u{0020}by\u{0020}relevant\u{0020}institutions.\u{0020}But\u{0020}before\u{0020}that,\u{0020}Gin's\u{0020}friend\u{0020}of\u{0020}her\u{0020}biological\u{0020}parents,\u{0020}the\u{0020}head\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}Einte\u{0020}Cretia,\u{0020}adopted\u{0020}Gin\u{0020}and\u{0020}gave\u{0020}her\u{0020}the\u{0020}name\u{0020}Gin\u{0020}Cretia.\n\nUnder\u{0020}the\u{0020}arrangement\u{0020}of\u{0020}their\u{0020}parents,\u{0020}Gin·Cretia\u{0020}and\u{0020}Alice·Cretia\u{0020}were\u{0020}placed\u{0020}in\u{0020}the\u{0020}Ninja\u{0020}Group\u{0020}area\u{0020}far\u{0020}away\u{0020}from\u{0020}the\u{0020}Danube\u{0020}main\u{0020}family.\n\nAs\u{0020}the\u{0020}second\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}Gin\u{0020}was\u{0020}initially\u{0020}expected\u{0020}as\u{0020}much\u{0020}as\u{0020}the\u{0020}eldest\u{0020}daughter,\u{0020}Alice·Cretia.\u{0020}As\u{0020}time\u{0020}went\u{0020}by,\u{0020}Gin·Cretia,\u{0020}who\u{0020}grew\u{0020}up\u{0020}a\u{0020}little,\u{0020}destroyed\u{0020}everyone's\u{0020}expectations\u{0020}of\u{0020}her\u{0020}with\u{0020}her\u{0020}\"impeccable\"\u{0020}performance\u{0020}-\u{0020}that\u{0020}is,\u{0020}she\u{0020}destroyed\u{0020}all\u{0020}expectations.\u{0020}Gin\u{0020}Cretia,\u{0020}who\u{0020}was\u{0020}lazy,\u{0020}playful,\u{0020}and\u{0020}evasive\u{0020}in\u{0020}her\u{0020}studies,\u{0020}made\u{0020}Tina\u{0020}Eisen,\u{0020}who\u{0020}had\u{0020}been\u{0020}the\u{0020}exclusive\u{0020}maid\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}for\u{0020}generations,\u{0020}helpless,\u{0020}and\u{0020}finally\u{0020}had\u{0020}to\u{0020}adopt\u{0020}a\u{0020}loose\u{0020}generation\u{0020}education\u{0020}method.\n\nAlthough\u{0020}Gin·Cretia\u{0020}was\u{0020}once\u{0020}criticized\u{0020}-\u{0020}or\u{0020}even\u{0020}abused\u{0020}-\u{0020}by\u{0020}her\u{0020}elder\u{0020}sister\u{0020}Alice·Cretia\u{0020}with\u{0020}sharp\u{0020}and\u{0020}radical\u{0020}words,\u{0020}she\u{0020}still\u{0020}relies\u{0020}on\u{0020}and\u{0020}trusts\u{0020}her\u{0020}sister.\u{0020}As\u{0020}the\u{0020}second\u{0020}daughter,\u{0020}she\u{0020}knows\u{0020}how\u{0020}much\u{0020}pressure\u{0020}her\u{0020}sister\u{0020}bears\u{0020}on\u{0020}her\u{0020}small\u{0020}shoulders.\u{0020}She\u{0020}believes\u{0020}that\u{0020}the\u{0020}reason\u{0020}why\u{0020}she\u{0020}can\u{0020}live\u{0020}so\u{0020}freely\u{0020}is\u{0020}entirely\u{0020}because\u{0020}of\u{0020}her\u{0020}sister's\u{0020}existence.\n\nUnfortunately,\u{0020}no\u{0020}matter\u{0020}how\u{0020}excellent\u{0020}her\u{0020}sister\u{0020}performed,\u{0020}due\u{0020}to\u{0020}the\u{0020}responsibility\u{0020}and\u{0020}obligation\u{0020}of\u{0020}the\u{0020}nobility,\u{0020}she,\u{0020}who\u{0020}passed\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test,\u{0020}still\u{0020}had\u{0020}to\u{0020}enter\u{0020}the\u{0020}academy\u{0020}and\u{0020}become\u{0020}a\u{0020}candidate\u{0020}for\u{0020}the\u{0020}driver.\u{0020}This\u{0020}made\u{0020}her,\u{0020}who\u{0020}wanted\u{0020}to\u{0020}stay\u{0020}at\u{0020}home\u{0020}for\u{0020}a\u{0020}lifetime,\u{0020}feel\u{0020}quite\u{0020}desperate.", "0", "0", "0", "0", 12003, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[620103] = {620103, 1000, "\u{0020}\u{0020}During\u{0020}the\u{0020}college\u{0020}period,\u{0020}Gin·Cretia\u{0020}became\u{0020}a\u{0020}legend\u{0020}in\u{0020}the\u{0020}college\u{0020}with\u{0020}the\u{0020}achievement\u{0020}of\u{0020}being\u{0020}the\u{0020}bottom\u{0020}one\u{0020}in\u{0020}the\u{0020}grade\u{0020}for\u{0020}five\u{0020}consecutive\u{0020}years.\n\nThe\u{0020}cooking\u{0020}course\u{0020}she\u{0020}chose.\u{0020}Every\u{0020}time\u{0020}she\u{0020}finished\u{0020}the\u{0020}cooking,\u{0020}the\u{0020}teacher\u{0020}responsible\u{0020}for\u{0020}tasting\u{0020}would\u{0020}lose\u{0020}their\u{0020}sense\u{0020}of\u{0020}taste\u{0020}for\u{0020}three\u{0020}days.\u{0020}In\u{0020}a\u{0020}sense,\u{0020}perhaps\u{0020}there\u{0020}is\u{0020}a\u{0020}great\u{0020}possibility\u{0020}that\u{0020}she\u{0020}is\u{0020}making\u{0020}poison.\n\nDuring\u{0020}her\u{0020}college\u{0020}years,\u{0020}her\u{0020}various\u{0020}performances\u{0020}that\u{0020}were\u{0020}beyond\u{0020}reach\u{0020}made\u{0020}no\u{0020}team\u{0020}dare\u{0020}to\u{0020}choose\u{0020}her\u{0020}as\u{0020}a\u{0020}member\u{0020}when\u{0020}she\u{0020}was\u{0020}about\u{0020}to\u{0020}graduate.\u{0020}A\u{0020}team\u{0020}without\u{0020}affiliation\u{0020}cannot\u{0020}carry\u{0020}out\u{0020}tasks.\u{0020}She,\u{0020}who\u{0020}was\u{0020}complacent\u{0020}about\u{0020}this,\u{0020}seemed\u{0020}to\u{0020}envision\u{0020}a\u{0020}future\u{0020}where\u{0020}she\u{0020}could\u{0020}stay\u{0020}at\u{0020}home\u{0020}after\u{0020}graduation.\n\nDue\u{0020}to\u{0020}the\u{0020}pressure\u{0020}from\u{0020}the\u{0020}family,\u{0020}the\u{0020}eldest\u{0020}daughter,\u{0020}Alice·Cretia,\u{0020}had\u{0020}to\u{0020}bring\u{0020}Gin·Cretia\u{0020}into\u{0020}her\u{0020}team.\u{0020}Gin·Cretia\u{0020}still\u{0020}had\u{0020}to\u{0020}leave\u{0020}school\u{0020}and\u{0020}home\u{0020}and\u{0020}head\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}as\u{0020}a\u{0020}driver.", "0", "0", "0", "0", 12004, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[620104] = {620104, 2000, "\u{0020}\"Th-this\u{0020}is\u{0020}just\u{0020}baby\u{0020}fat.\"\n\nPerhaps\u{0020}it\u{0020}became\u{0020}more\u{0020}obvious\u{0020}after\u{0020}gigantification.\u{0020}She\u{0020}tried\u{0020}to\u{0020}cover\u{0020}it\u{0020}up\u{0020}by\u{0020}pinching\u{0020}her\u{0020}stomach.\n\n\"Don't\u{0020}believe\u{0020}it?\u{0020}Touch\u{0020}it.\u{0020}It's\u{0020}very\u{0020}comfortable.\u{0020}That\u{0020}is\u{0020}the\u{0020}charm\u{0020}of\u{0020}'baby\u{0020}fat'!\"\n\nNo,\u{0020}anyway,\u{0020}that's\u{0020}not\u{0020}a\u{0020}place\u{0020}where\u{0020}others\u{0020}can\u{0020}touch\u{0020}at\u{0020}will.\n\n\"What\u{0020}does\u{0020}it\u{0020}matter?\u{0020}Anyway,\u{0020}it's\u{0020}just\u{0020}you\u{0020}and\u{0020}me\u{0020}now,\u{0020}although\u{0020}the\u{0020}figure\u{0020}is\u{0020}quite\u{0020}conspicuous.\"\n\nShe\u{0020}grinned\u{0020}and\u{0020}smiled\u{0020}like\u{0020}a\u{0020}little\u{0020}animal.\n\nDo\u{0020}you\u{0020}want\u{0020}to\u{0020}touch\u{0020}it,\u{0020}Navigator?", "0", "0", "0", "0", 12005, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[620200] = {620200, 0, "[Name]\u{0020}Shiranui\n[B-Day]\u{0020}Nov\u{0020}26\n[Compatability\u{0020}Rate]\u{0020}87％\n[Height]\u{0020}40m\n[Squad]\u{0020}Fuurinkazan\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Small,\u{0020}soft\u{0020}and\u{0020}lovely\u{0020}things", "0", "0", "0", "0", 12002, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}不知火\n[B-Day]\u{1000}11月26日\n[幻化核心适格率]\u{1000}87％\n[Height]\u{1000}40m\n[部队]\u{1000}风林火山\n\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}小小的、软软的、可爱的东西"},
[620201] = {620201, 100, "\u{0020}\u{0020}Although\u{0020}she\u{0020}is\u{0020}a\u{0020}mature\u{0020}older\u{0020}sister,\u{0020}she\u{0020}unexpectedly\u{0020}likes\u{0020}cute\u{0020}things.\u{0020}However,\u{0020}when\u{0020}cute\u{0020}things\u{0020}are\u{0020}not\u{0020}limited\u{0020}to\u{0020}small\u{0020}animals\u{0020}or\u{0020}objects,\u{0020}it\u{0020}is\u{0020}more\u{0020}or\u{0020}less\u{0020}terrifying.\n\nIn\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}of\u{0020}AEGIS,\u{0020}almost\u{0020}every\u{0020}younger\u{0020}one,\u{0020}or\u{0020}even\u{0020}those\u{0020}who\u{0020}seemed\u{0020}younger\u{0020}(yes,\u{0020}including\u{0020}Dr.\u{0020}Stephanie),\u{0020}was\u{0020}harassed\u{0020}by\u{0020}her.\n\nIn\u{0020}a\u{0020}certain\u{0020}sense,\u{0020}Shiranui\u{0020}is\u{0020}the\u{0020}biggest\u{0020}beneficiary\u{0020}of\u{0020}the\u{0020}abolition\u{0020}of\u{0020}the\u{0020}convention\u{0020}on\u{0020}service\u{0020}age.\n\nHer\u{0020}morbid\u{0020}preference\u{0020}made\u{0020}those\u{0020}younger\u{0020}than\u{0020}her\u{0020}in\u{0020}the\u{0020}team,\u{0020}especially\u{0020}the\u{0020}captain\u{0020}Suzuki\u{0020}Seifung,\u{0020}particularly\u{0020}uncomfortable.\n\nAnyway,\u{0020}it\u{0020}is\u{0020}certain\u{0020}that\u{0020}this\u{0020}woman\u{0020}will\u{0020}burst\u{0020}out\u{0020}with\u{0020}unimaginable\u{0020}power\u{0020}in\u{0020}order\u{0020}to\u{0020}protect\u{0020}the\u{0020}weak\u{0020}and\u{0020}lovely\u{0020}children.", "0", "0", "0", "0", 12002, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}尽管是一个成熟的大姐姐，但她却意外地喜欢可爱的东西——但是，当可爱的东西不局限于小动物或者物件时，就或多或少有些可怕了。\n\u{1000}\u{1000}在艾吉斯的九州总部里，几乎每一个年龄较小的，或者哪怕是看起来年龄较小的（是的，包括史蒂芬妮博士在内）都遭到过她的骚扰。\n\u{1000}\u{1000}某种意义上来说，不知火是撤除服役年龄公约的最大受益者。\n\u{1000}\u{1000}她这份病态的偏爱让队伍里年纪比她小的——尤其是队长铃木清风尤其难受。\n\u{1000}\u{1000}只是——不管如何，可以肯定的是：这个女人，会为了守护弱小的、可爱的孩子，爆发出难以想象的力量。"},
[620202] = {620202, 500, "\u{0020}\u{0020}Although\u{0020}it\u{0020}is\u{0020}hard\u{0020}to\u{0020}imagine,\u{0020}Shiranui\u{0020}was\u{0020}once\u{0020}a\u{0020}student.\u{0020}No.\u{0020}Rather,\u{0020}it\u{0020}would\u{0020}be\u{0020}strange\u{0020}if\u{0020}she\u{0020}didn't\u{0020}have\u{0020}a\u{0020}student\u{0020}period.\u{0020}After\u{0020}all,\u{0020}she\u{0020}is\u{0020}a\u{0020}child\u{0020}from\u{0020}a\u{0020}family\u{0020}of\u{0020}teachers.\u{0020}Her\u{0020}mother,\u{0020}father,\u{0020}as\u{0020}well\u{0020}as\u{0020}her\u{0020}grandparents\u{0020}and\u{0020}other\u{0020}relatives\u{0020}further\u{0020}up\u{0020}the\u{0020}family\u{0020}tree,\u{0020}almost\u{0020}all\u{0020}are\u{0020}teachers.\u{0020}It\u{0020}is\u{0020}more\u{0020}difficult\u{0020}to\u{0020}pick\u{0020}out\u{0020}someone\u{0020}who\u{0020}is\u{0020}not\u{0020}a\u{0020}teacher\u{0020}from\u{0020}Shiranui's\u{0020}family\u{0020}than\u{0020}to\u{0020}find\u{0020}a\u{0020}driver\u{0020}with\u{0020}a\u{0020}100%\u{0020}Compatability\u{0020}Rate.\n\nWhen\u{0020}Shiranui\u{0020}was\u{0020}still\u{0020}a\u{0020}student,\u{0020}education\u{0020}was\u{0020}still\u{0020}the\u{0020}mainstream\u{0020}of\u{0020}the\u{0020}era,\u{0020}and\u{0020}she\u{0020}also\u{0020}aimed\u{0020}to\u{0020}become\u{0020}an\u{0020}excellent\u{0020}teacher\u{0020}like\u{0020}her\u{0020}parents.\u{0020}However,\u{0020}she\u{0020}failed\u{0020}to\u{0020}become\u{0020}a\u{0020}teacher\u{0020}in\u{0020}the\u{0020}end.\n\nIt\u{0020}is\u{0020}neither\u{0020}a\u{0020}matter\u{0020}of\u{0020}ability\u{0020}nor\u{0020}the\u{0020}influence\u{0020}of\u{0020}family\u{0020}changes,\u{0020}wars\u{0020}and\u{0020}the\u{0020}like.\n\nPerhaps\u{0020}it's\u{0020}just\u{0020}her\u{0020}personality.\n\nWhen\u{0020}she\u{0020}went\u{0020}to\u{0020}the\u{0020}middle\u{0020}school\u{0020}as\u{0020}a\u{0020}trainee\u{0020}teacher\u{0020}as\u{0020}an\u{0020}outstanding\u{0020}student,\u{0020}her\u{0020}city\u{0020}was\u{0020}very\u{0020}unlucky\u{0020}to\u{0020}encounter\u{0020}a\u{0020}small-scale\u{0020}Sin.\u{0020}Fortunately,\u{0020}the\u{0020}scale\u{0020}of\u{0020}Sin\u{0020}is\u{0020}not\u{0020}large,\u{0020}and\u{0020}the\u{0020}driver\u{0020}who\u{0020}is\u{0020}on\u{0020}patrol\u{0020}nearby\u{0020}also\u{0020}arrived\u{0020}in\u{0020}time.\u{0020}It\u{0020}is\u{0020}the\u{0020}best\u{0020}description\u{0020}of\u{0020}this\u{0020}incident.\n\nBut\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}parties\u{0020}involved\u{0020}in\u{0020}the\u{0020}incident,\u{0020}Shiranui\u{0020}had\u{0020}a\u{0020}slight\u{0020}change\u{0020}in\u{0020}her\u{0020}concept\u{0020}-\u{0020}as\u{0020}a\u{0020}teacher,\u{0020}even\u{0020}with\u{0020}both\u{0020}hands,\u{0020}she\u{0020}could\u{0020}only\u{0020}protect\u{0020}two\u{0020}students.\n\nThe\u{0020}weak\u{0020}are\u{0020}unable\u{0020}to\u{0020}protect\u{0020}the\u{0020}weak.\n\nSo\u{0020}instead\u{0020}of\u{0020}becoming\u{0020}a\u{0020}teacher,\u{0020}she\u{0020}became\u{0020}a\u{0020}driver.", "0", "0", "0", "0", 12002, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}虽然很难想象，但不知火曾经也是一名学生。不，倒不如说如果她没有学生时期，才显得有些怪异，毕竟她可是教师家庭的孩子。她的母亲、父亲，以及再往上数的祖父母与其他亲戚，几乎都是教师。想从不知火的家族里挑出一位不是教师的人，比找到一位100%适格率的驾驶员还要困难。\n\u{1000}\u{1000}不知火仍是一名学生的时候，升学仍然是那个时代的主流，她也以成为像父母那样的优秀教师为目标而努力着。\n\u{1000}\u{1000}不过，她最后也没能当上教师。\n\u{1000}\u{1000}并不是能力问题，也并非是家庭变故、战祸之类的影响。\n\u{1000}\u{1000}也许只是性格问题。\n\u{1000}\u{1000}在以优秀学生的身份前往中学担任实习教师时，她所在的城市十分不走运地遇到了小规模原罪入。好在原罪规模并不大，正在附近执行巡逻任务的驾驶员也及时赶到，有惊无险是这次事件的最恰当描述。\n\u{1000}\u{1000}但作为事件的当事人之一，不知火产生了一点观念上的变化——作为教师的她，即使用上两只手也只能保护两名学生。\n\u{1000}\u{1000}弱者是无法保护弱者的。\n\u{1000}\u{1000}所以她最后没能成为教师，而是成为了驾驶员。"},
[620203] = {620203, 1000, "People\u{0020}like\u{0020}Shiranui\u{0020}who\u{0020}have\u{0020}been\u{0020}active\u{0020}as\u{0020}a\u{0020}formal\u{0020}driver\u{0020}on\u{0020}the\u{0020}Frontier\u{0020}battlefield\u{0020}for\u{0020}a\u{0020}full\u{0020}five\u{0020}years\u{0020}are\u{0020}extremely\u{0020}rare\u{0020}in\u{0020}the\u{0020}entire\u{0020}AEGIS.\u{0020}So\u{0020}when\u{0020}the\u{0020}\"Fuurinkazan\"\u{0020}was\u{0020}established\u{0020}and\u{0020}the\u{0020}AEGIS\u{0020}Strategy\u{0020}Department\u{0020}announced\u{0020}that\u{0020}the\u{0020}team\u{0020}leader\u{0020}was\u{0020}Suzuki\u{0020}Seifung,\u{0020}who\u{0020}no\u{0020}one\u{0020}had\u{0020}ever\u{0020}heard\u{0020}of,\u{0020}it\u{0020}caused\u{0020}a\u{0020}great\u{0020}stir\u{0020}among\u{0020}the\u{0020}navigators.\n\nBut\u{0020}Shiranui\u{0020}had\u{0020}no\u{0020}objection\u{0020}to\u{0020}the\u{0020}arrangement\u{0020}of\u{0020}the\u{0020}Strategy\u{0020}Department.\n\nShe\u{0020}made\u{0020}this\u{0020}decision\u{0020}based\u{0020}on\u{0020}her\u{0020}own\u{0020}judgment.\n\nBefore\u{0020}being\u{0020}officially\u{0020}incorporated\u{0020}into\u{0020}\"Fuurinkazan\",\u{0020}Shiranui\u{0020}had\u{0020}a\u{0020}general\u{0020}understanding\u{0020}of\u{0020}the\u{0020}future\u{0020}members\u{0020}of\u{0020}this\u{0020}team.\n\nKuriyama\u{0020}Seiran\u{0020}who\u{0020}is\u{0020}self-abased\u{0020}due\u{0020}to\u{0020}physical\u{0020}defects;\u{0020}Morimura\u{0020}Kinosuke\u{0020}who\u{0020}is\u{0020}unable\u{0020}to\u{0020}move\u{0020}forward\u{0020}because\u{0020}of\u{0020}dwelling\u{0020}on\u{0020}the\u{0020}past,\u{0020}and\u{0020}Suzuki\u{0020}Seifung\u{0020}who\u{0020}has\u{0020}excellent\u{0020}leadership\u{0020}ability\u{0020}but\u{0020}is\u{0020}too\u{0020}young.\n\nShiranui\u{0020}judged\u{0020}based\u{0020}on\u{0020}experience\u{0020}that\u{0020}this\u{0020}would\u{0020}be\u{0020}a\u{0020}very\u{0020}powerful\u{0020}team,\u{0020}but\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}it\u{0020}could\u{0020}collapse\u{0020}because\u{0020}of\u{0020}trivial\u{0020}matters.\u{0020}Therefore,\u{0020}as\u{0020}the\u{0020}elder\u{0020}in\u{0020}the\u{0020}team\u{0020}and\u{0020}the\u{0020}member\u{0020}with\u{0020}the\u{0020}richest\u{0020}combat\u{0020}experience\u{0020}against\u{0020}Sin,\u{0020}she\u{0020}had\u{0020}to\u{0020}do\u{0020}something.\n\nShe\u{0020}did\u{0020}not\u{0020}become\u{0020}the\u{0020}core\u{0020}of\u{0020}the\u{0020}team\u{0020}in\u{0020}a\u{0020}presumptuous\u{0020}way\u{0020}but\u{0020}assisted\u{0020}Suzuki\u{0020}Seifung\u{0020}in\u{0020}the\u{0020}form\u{0020}of\u{0020}an\u{0020}advisor,\u{0020}helping\u{0020}her\u{0020}sort\u{0020}out\u{0020}the\u{0020}internal\u{0020}relationships\u{0020}within\u{0020}the\u{0020}team.\u{0020}Shiranui\u{0020}cared\u{0020}for\u{0020}everyone\u{0020}in\u{0020}the\u{0020}team\u{0020}meticulously\u{0020}in\u{0020}her\u{0020}own\u{0020}way,\u{0020}which\u{0020}was\u{0020}precisely\u{0020}her\u{0020}advantage\u{0020}as\u{0020}an\u{0020}elder.", "0", "0", "0", "0", 12002, "0", "0", "0", "0", 1, 4, "0", "0", "\n\u{1000}\u{1000}像不知火这样以正式驾驶员的身份活跃在前线战场足足五年的人，在整个艾吉斯中也是极少数。于是在\"风林火山\"成立时，艾吉斯战略部公布队长人选是从来没人听说过的铃木清风时，在驾驶员之间引起了一阵轩然大波。\n\u{1000}\u{1000}但不知火对战略部的安排并没有异议。\n\u{1000}\u{1000}她是基于自己的判断做出这一决定的。\n\u{1000}\u{1000}\u{1000}\u{1000}在被正式编入\"风林火山\"之前，不知火就对这支小队的未来成员有了大概的认识。\n\u{1000}\u{1000}因为身体缺陷而自卑的栗山青鸾；介怀过去而无法前进的森村鬼之介，以及有着卓越的领袖能力，却年龄过小的铃木清风。\n\u{1000}\u{1000}不知火根据经验判断出这会是一个很强大，但同时也会因为细枝末节的小事而崩塌的队伍。因此，作为队伍中的年长者、与原罪战斗经验最为丰富的成员，她必须做点什么。\n\u{1000}\u{1000}她并未喧宾夺主地成为队伍的核心，而是以幕僚的形式辅助着铃木清风，帮助她梳理队伍内部的关系。不知火以自己的方式无微不至地关心着队伍里的每一个人，这正是她作为年长者的优势。"},
[620204] = {620204, 2000, "\u{0020}\"Nowadays,\u{0020}the\u{0020}world\u{0020}is\u{0020}very\u{0020}tolerant\u{0020}to\u{0020}the\u{0020}strong,\u{0020}while\u{0020}very\u{0020}\u{0020}cruel\u{0020}to\u{0020}the\u{0020}weak.\"\n\n\"Because\u{0020}the\u{0020}strong\u{0020}can\u{0020}sustain\u{0020}the\u{0020}existence\u{0020}of\u{0020}the\u{0020}world,\u{0020}and\u{0020}the\u{0020}weak\u{0020}can\u{0020}only\u{0020}survive\u{0020}by\u{0020}relying\u{0020}on\u{0020}the\u{0020}strong.\"\n\nShiranui\u{0020}was\u{0020}not\u{0020}as\u{0020}frivolous\u{0020}as\u{0020}usual.\n\nOr\u{0020}rather,\u{0020}this\u{0020}is\u{0020}her\u{0020}true\u{0020}appearance.\n\n\"Navigator,\u{0020}such\u{0020}a\u{0020}world\u{0020}is\u{0020}wrong.\"\n\nThe\u{0020}huge\u{0020}body\u{0020}can\u{0020}support\u{0020}the\u{0020}heaven\u{0020}and\u{0020}earth,\u{0020}just\u{0020}like\u{0020}her\u{0020}now.\n\nThe\u{0020}insignificant\u{0020}people\u{0020}can\u{0020}only\u{0020}survive\u{0020}under\u{0020}protection,\u{0020}just\u{0020}like\u{0020}the\u{0020}civilians\u{0020}hiding\u{0020}behind\u{0020}her.\n\n\"The\u{0020}relationship\u{0020}between\u{0020}the\u{0020}strong\u{0020}and\u{0020}the\u{0020}weak,\u{0020}it\u{0020}can't\u{0020}be\u{0020}just\u{0020}like\u{0020}that,\u{0020}and\u{0020}it\u{0020}shouldn't\u{0020}be\u{0020}just\u{0020}like\u{0020}that.\"", "0", "0", "0", "0", 12002, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"现在的世界，对强者很宽容，对弱者很残忍。\"\n\u{1000}\u{1000}\"因为强者能够支撑起世界的存续，弱者只能依附强者才能生存。\"\n\u{1000}\u{1000}不知火并未像往常那样的轻浮，\n\u{1000}\u{1000}或者说，这才是她真正的面貌，\n\u{1000}\u{1000}\"领航，这样的世界是错误的。\"\n\u{1000}\u{1000}庞大的身躯能够支撑起天地，就像现在的她一样。\n\u{1000}\u{1000}渺小的人则只能在庇佑下生存，就像躲在她后方的平民一样。\n\u{1000}\u{1000}\"强者与弱者的关系——不能只是这样，也不该只是这样的。\""},
[620300] = {620300, 0, "[Name]\u{0020}Efgenia·Hen·Veselov\n[B-Day]\u{0020}April\u{0020}21\n[Compatability\u{0020}Rate]\u{0020}93％\n[Height]\u{0020}38m\n[Squad]\u{0020}Cannonbore\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Exercise\u{0020}one's\u{0020}core\u{0020}strength\u{0020}day\u{0020}and\u{0020}night", "0", "0", "0", "0", 12003, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}叶芙根尼娅•亨•韦谢洛夫\n[B-Day]\u{1000}4月21日\n[幻化核心适格率]\u{1000}93％\n[Height]\u{1000}41m\n[部队]\u{1000}钢轮戈尔\n\u{00A0}[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}夜以继日地锻炼自己的核心力量"},
[620301] = {620301, 100, "\u{0020}The\u{0020}captain\u{0020}of\u{0020}\"Cannonbore\"\u{0020}is\u{0020}extremely\u{0020}proficient\u{0020}in\u{0020}positional\u{0020}offensive\u{0020}battles.\u{0020}She\u{0020}can\u{0020}carry\u{0020}out\u{0020}carpet\u{0020}bombing\u{0020}on\u{0020}Sin\u{0020}with\u{0020}the\u{0020}extremely\u{0020}powerful\u{0020}firepower\u{0020}that\u{0020}ordinary\u{0020}drivers\u{0020}cannot\u{0020}control,\u{0020}annihilating\u{0020}the\u{0020}Sin\u{0020}group.\u{0020}However,\u{0020}due\u{0020}to\u{0020}her\u{0020}extremely\u{0020}high\u{0020}destructive\u{0020}power\u{0020}that\u{0020}would\u{0020}bring\u{0020}secondary\u{0020}damage\u{0020}to\u{0020}the\u{0020}city,\u{0020}she\u{0020}rarely\u{0020}has\u{0020}the\u{0020}opportunity\u{0020}to\u{0020}strike.\n\nThe\u{0020}only\u{0020}hobby\u{0020}in\u{0020}ordinary\u{0020}days\u{0020}is\u{0020}exercising.\u{0020}She\u{0020}would\u{0020}voluntarily\u{0020}conduct\u{0020}oppressive\u{0020}training\u{0020}on\u{0020}her\u{0020}body\u{0020}in\u{0020}the\u{0020}absence\u{0020}of\u{0020}training\u{0020}tasks.\u{0020}\"Only\u{0020}by\u{0020}pushing\u{0020}the\u{0020}body\u{0020}to\u{0020}the\u{0020}limit\u{0020}can\u{0020}unprecedented\u{0020}power\u{0020}be\u{0020}elicited.\"\u{0020}For\u{0020}the\u{0020}time\u{0020}being,\u{0020}she\u{0020}thinks\u{0020}so.", "0", "0", "0", "0", 12003, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"钢轮戈尔\"的队长，极为擅长阵地攻坚战，能凭借着寻常驾驶员无法驾驭的强大火力，对原罪实行地毯式轰炸，将原罪群歼灭。但因为其极高的破坏力会给城市带来二次创伤，所以她很少有登场的机会。\n\u{1000}\u{1000}平日里唯一的爱好是锻炼身体，她会主动在没有训练任务的情况下对自己的肉体进行压迫式训练。\"只有将肉体逼至极限，才能牵引出前所未有的力量。\"姑且，她是这么认为的。\n\u{1000}\u{1000}然而，尽管她在不断地锤炼自己的身体——应该说是\"仅有的身体\"——依然无法改变她的手臂与腿脚皆是高科技义肢的事实。\n\u{1000}\u{1000}而这件事的原因，与她的过去有着密切的联系。"},
[620302] = {620302, 500, "\u{0020}\u{0020}Efgenia\u{0020}Hen\u{0020}Veselov,\u{0020}most\u{0020}people\u{0020}know\u{0020}that\u{0020}the\u{0020}name\u{0020}means\u{0020}the\u{0020}ace\u{0020}driver\u{0020}of\u{0020}the\u{0020}Katya\u{0020}region,\u{0020}but\u{0020}before\u{0020}that\u{0020}the\u{0020}owner\u{0020}of\u{0020}the\u{0020}name\u{0020}was\u{0020}a\u{0020}glorified\u{0020}Katya\u{0020}region\u{0020}border\u{0020}guard\u{0020}officer.\n\nShe\u{0020}graduated\u{0020}from\u{0020}the\u{0020}Armored\u{0020}Military\u{0020}Academy\u{0020}and\u{0020}held\u{0020}the\u{0020}position\u{0020}of\u{0020}a\u{0020}tank\u{0020}unit\u{0020}commander,\u{0020}fighting\u{0020}against\u{0020}Sin\u{0020}time\u{0020}and\u{0020}time\u{0020}again.\u{0020}Under\u{0020}the\u{0020}overall\u{0020}situation\u{0020}of\u{0020}the\u{0020}human\u{0020}army's\u{0020}successive\u{0020}defeats,\u{0020}the\u{0020}team\u{0020}she\u{0020}was\u{0020}in\u{0020}still\u{0020}maintained\u{0020}the\u{0020}final\u{0020}glory.\n\nHowever,\u{0020}this\u{0020}glory\u{0020}was\u{0020}destroyed\u{0020}in\u{0020}a\u{0020}military\u{0020}operation.\n\nSin\u{0020}attacked\u{0020}the\u{0020}city\u{0020}where\u{0020}she\u{0020}was.\u{0020}To\u{0020}save\u{0020}the\u{0020}children\u{0020}in\u{0020}the\u{0020}ruins,\u{0020}a\u{0020}boulder\u{0020}falling\u{0020}from\u{0020}a\u{0020}height\u{0020}hit\u{0020}her\u{0020}body\u{0020}directly,\u{0020}crushing\u{0020}her\u{0020}flesh\u{0020}and\u{0020}bones\u{0020}in\u{0020}an\u{0020}instant.\u{0020}Efgenia\u{0020}has\u{0020}since\u{0020}bid\u{0020}farewell\u{0020}to\u{0020}the\u{0020}battlefield.\u{0020}For\u{0020}the\u{0020}rest\u{0020}of\u{0020}her\u{0020}life,\u{0020}without\u{0020}unexpected\u{0020}circumstances,\u{0020}she\u{0020}will\u{0020}spend\u{0020}it\u{0020}in\u{0020}bed\u{0020}and\u{0020}on\u{0020}a\u{0020}wheelchair.\u{0020}However,\u{0020}she\u{0020}has\u{0020}not\u{0020}shown\u{0020}attitudes\u{0020}such\u{0020}as\u{0020}regret\u{0020}or\u{0020}annoyance\u{0020}about\u{0020}this,\u{0020}which\u{0020}proves\u{0020}the\u{0020}strength\u{0020}of\u{0020}her\u{0020}spirit.\n\nDuring\u{0020}Efgenia's\u{0020}convalescence,\u{0020}the\u{0020}local\u{0020}private\u{0020}arms\u{0020}company\u{0020}\"Siren\"\u{0020}in\u{0020}Katya\u{0020}approached\u{0020}her.\u{0020}Under\u{0020}the\u{0020}proposal\u{0020}of\u{0020}Siren,\u{0020}Efgenia\u{0020}underwent\u{0020}the\u{0020}modification\u{0020}surgery\u{0020}of\u{0020}Siren\u{0020}and\u{0020}regained\u{0020}her\u{0020}mobility.\n\nBut\u{0020}she\u{0020}did\u{0020}not\u{0020}choose\u{0020}to\u{0020}return\u{0020}to\u{0020}the\u{0020}army.\u{0020}Instead,\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}Siren,\u{0020}she\u{0020}established\u{0020}an\u{0020}unofficial\u{0020}driver\u{0020}team\u{0020}\"Cannonbore\"\u{0020}belonging\u{0020}to\u{0020}the\u{0020}Katya\u{0020}region.\n\n\"Relying\u{0020}solely\u{0020}on\u{0020}conventional\u{0020}weapons\u{0020}is\u{0020}impossible\u{0020}to\u{0020}defeat\u{0020}them\u{0020}-\u{0020}if\u{0020}one\u{0020}doesn't\u{0020}become\u{0020}a\u{0020}monster,\u{0020}it's\u{0020}impossible\u{0020}to\u{0020}defend\u{0020}the\u{0020}homeland!\"\u{0020}", "0", "0", "0", "0", 12003, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}叶芙根尼娅·亨·韦谢洛夫，大部分人都知道这个名字意味着卡佳地区的王牌驾驶员，但在此之前这个名字的主人曾经是一名荣耀的卡佳地区边防军军官。\n\u{1000}\u{1000}毕业于装甲兵军事学院的她，担任着坦克部队指挥官的职责，一次又一次与原罪战斗着。在人类军队节节败退的大局下，她所在的队伍依然保持着最后的荣光。\n\u{1000}\u{1000}然而，这份荣光毁于一次军事作战中。\n\u{1000}\u{1000}原罪袭击了她所在的城市。为了拯救废墟里的孩子，失去了自己的双腿——从高处落下的巨石，在一瞬间便将她的肉与骨粉碎了。叶芙根尼娅从此告别了战场，她的余生不出意外将会在床上与轮椅上度过，而她本人对此并未表露出类似后悔、懊恼的态度，这证明了她精神的强大。\n\u{1000}\u{1000}在叶芙根尼娅养伤期间，卡佳当地的民营军火公司\"塞伦\"找上了她。在塞伦的提议下，叶芙根尼娅接受了塞伦的改造手术，重新获得了行动能力。\n\u{1000}\u{1000}但她没有选择返回军队，而是通过塞伦的帮助，建立了一支属于卡佳地区的非官方驾驶员小队\"钢轮戈尔\"。\n\u{1000}\u{1000}\"仅仅依靠常规武器是无法击败它们的——如果不成为怪物，就无法守卫家园！\""},
[620303] = {620303, 1000, "\u{0020}\u{0020}The\u{0020}complete\u{0020}equipment\u{0020}of\u{0020}\"Cannonbore\"\u{0020}is\u{0020}led\u{0020}and\u{0020}designed\u{0020}by\u{0020}the\u{0020}\"Siren\"\u{0020}company.\u{0020}The\u{0020}Siren\u{0020}company\u{0020}refused\u{0020}the\u{0020}assistance\u{0020}from\u{0020}AEGIS\u{0020}in\u{0020}order\u{0020}to\u{0020}ensure\u{0020}the\u{0020}independence\u{0020}of\u{0020}Cannonbore.\n\nAfter\u{0020}mutual\u{0020}negotiation,\u{0020}\"Cannonbore\"\u{0020}must\u{0020}operate\u{0020}under\u{0020}the\u{0020}name\u{0020}of\u{0020}AEGIS\u{0020}Katya\u{0020}Branch,\u{0020}follow\u{0020}the\u{0020}deployment\u{0020}of\u{0020}AEGIS\u{0020}to\u{0020}fight\u{0020}against\u{0020}Sin.\u{0020}However,\u{0020}except\u{0020}for\u{0020}this,\u{0020}AEGIS\u{0020}shall\u{0020}not\u{0020}interfere\u{0020}with\u{0020}any\u{0020}internal\u{0020}members\u{0020}of\u{0020}Cannonbore,\u{0020}and\u{0020}AEGIS\u{0020}does\u{0020}not\u{0020}need\u{0020}to\u{0020}provide\u{0020}any\u{0020}technical\u{0020}or\u{0020}material\u{0020}support\u{0020}to\u{0020}Cannonbore.\n\nEfgenia\u{0020}did\u{0020}not\u{0020}care\u{0020}about\u{0020}the\u{0020}complex\u{0020}and\u{0020}obscure\u{0020}negotiations\u{0020}behind\u{0020}Cannonbore.\u{0020}Relying\u{0020}on\u{0020}the\u{0020}powerful\u{0020}firepower\u{0020}provided\u{0020}by\u{0020}the\u{0020}armor,\u{0020}she\u{0020}maintained\u{0020}a\u{0020}100%\u{0020}mission\u{0020}success\u{0020}rate.\n\nShe\u{0020}clearly\u{0020}knows\u{0020}that\u{0020}the\u{0020}armor\u{0020}designed\u{0020}by\u{0020}\"Siren\"\u{0020}provides\u{0020}firepower\u{0020}that\u{0020}conventional\u{0020}armors\u{0020}do\u{0020}not\u{0020}have,\u{0020}but\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}it\u{0020}will\u{0020}bring\u{0020}a\u{0020}heavy\u{0020}burden\u{0020}to\u{0020}the\u{0020}driver\u{0020}and\u{0020}put\u{0020}them\u{0020}at\u{0020}risk\u{0020}of\u{0020}physical\u{0020}collapse\u{0020}at\u{0020}any\u{0020}time.\u{0020}But\u{0020}as\u{0020}a\u{0020}former\u{0020}non-commissioned\u{0020}officer\u{0020}and\u{0020}an\u{0020}active\u{0020}soldier,\u{0020}she\u{0020}has\u{0020}long\u{0020}been\u{0020}ready\u{0020}to\u{0020}die\u{0020}at\u{0020}any\u{0020}time.\n\n\"If\u{0020}you\u{0020}want\u{0020}to\u{0020}protect\u{0020}the\u{0020}human\u{0020}world\u{0020}from\u{0020}Sin,\u{0020}you\u{0020}can't\u{0020}do\u{0020}it\u{0020}without\u{0020}being\u{0020}mentally\u{0020}prepared\u{0020}to\u{0020}die\u{0020}at\u{0020}any\u{0020}time!\u{0020}Right,\u{0020}Navigator?\"", "0", "0", "0", "0", 12003, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"钢轮戈尔\"的全套装备由\"塞伦\"公司主导设计。塞伦公司拒绝了来自艾吉斯的援助，目的是保证钢轮戈尔的独立性。\n\u{1000}\u{1000}在经过双方协商后，\"钢轮戈尔\"必须以艾吉斯Katya\u{1000}Branch的名义进行活动，听从艾吉斯的调遣与原罪战斗，但除此之外艾吉斯不得对钢轮戈尔内部成员进行任何干涉，而艾吉斯也无须向钢轮戈尔提供任何技术、物资上的支持。\n\u{1000}\u{1000}叶芙根尼娅并未在意钢轮戈尔背后复杂阴晦的谈判，她依靠着装甲提供的强大火力，维持着100%的任务成功率。\n\u{1000}\u{1000}她清楚地知道由\"塞伦\"设计的装甲在提供了常规装甲不具备的火力的同时，也会给驾驶员带来沉重的负荷，随时处于肉体崩溃的险境。但她作为一名前任士官，一名现役战士，她早就做好了随时赴死的准备。\n\u{1000}\u{1000}\"想要从原罪手上守护人类的世界，不做好随时去死的心理准备可不行啊！对吧，领航！\""},
[620304] = {620304, 2000, "\u{0020}\u{0020}To\u{0020}save\u{0020}people,\u{0020}she\u{0020}lost\u{0020}her\u{0020}honor.\n\nIn\u{0020}order\u{0020}to\u{0020}return\u{0020}to\u{0020}the\u{0020}battlefield,\u{0020}she\u{0020}lost\u{0020}her\u{0020}human\u{0020}body.\n\nShe\u{0020}persisted\u{0020}in\u{0020}exercising,\u{0020}and\u{0020}a\u{0020}part\u{0020}of\u{0020}her\u{0020}body\u{0020}was\u{0020}no\u{0020}longer\u{0020}human.\n\n\"Regret?\u{0020}Well...\u{0020}I\u{0020}once\u{0020}longed\u{0020}for\u{0020}that\u{0020}kind\u{0020}of\u{0020}ordinary\u{0020}life.\"\n\nThe\u{0020}crimson\u{0020}artillery\u{0020}fire\u{0020}was\u{0020}blooming\u{0020}beside\u{0020}her,\u{0020}and\u{0020}the\u{0020}ground\u{0020}trembled\u{0020}as\u{0020}a\u{0020}result.\n\nShe\u{0020}looked\u{0020}at\u{0020}the\u{0020}Sin\u{0020}in\u{0020}the\u{0020}distance,\u{0020}smiling\u{0020}contentedly.\n\nIf\u{0020}there\u{0020}is\u{0020}no\u{0020}battle,\u{0020}it\u{0020}will\u{0020}be\u{0020}impossible\u{0020}to\u{0020}protect\u{0020}everyone.\u{0020}That\u{0020}would\u{0020}be\u{0020}terrible.", "0", "0", "0", "0", 12003, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}为了救人，她失去了双腿，\n\u{1000}\u{1000}为了重返战场，她失去了双手。\n\u{1000}\u{1000}她持之以恒地锻炼身体，身体的一部分早已不是人类。\n\u{1000}\u{1000}\"后悔？嗯……我憧憬过那种普通的的生活噢。\"\n\u{1000}\u{1000}赤红的炮火在她身边绽放着，地面也因此而战栗，\n\u{1000}\u{1000}她望着远方的原罪，惬意地笑着，\n\u{1000}\u{1000}\"可不战斗，就无法保护大家了。那可不好，不好。\""},
[620400] = {620400, 0, "[Name]\u{0020}Hanakotoba\n[B-Day]\u{0020}Aug\u{0020}17\n[Compatability\u{0020}Rate]\u{0020}81％\n[Height]\u{0020}35m\n[Squad]\u{0020}Shingyou\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Stalking\u{0020}a\u{0020}particular\u{0020}navigator", "0", "0", "0", "0", 12004, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}花语\n[B-Day]\u{1000}8月17日\n[幻化核心适格率]\u{1000}81％\n[Height]\u{1000}35m\n[部队]\u{1000}心经屋\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}跟踪某位特别的领航"},
[620401] = {620401, 100, "\u{0020}\u{0020}\"Feels\u{0020}like\u{0020}a\u{0020}very\u{0020}cute\u{0020}child,\u{0020}but\u{0020}just\u{0020}a\u{0020}little...\"\n\n\"We\u{0020}think\u{0020}the\u{0020}child\u{0020}is\u{0020}very\u{0020}well-behaved\u{0020}-\u{0020}However,\u{0020}sometimes\u{0020}we\u{0020}are\u{0020}also\u{0020}afraid\u{0020}of\u{0020}her,\u{0020}which\u{0020}is\u{0020}really\u{0020}strange.\"\n\nAfter\u{0020}summarizing\u{0020}everyone's\u{0020}first\u{0020}impression\u{0020}of\u{0020}her\u{0020}in\u{0020}Kyushu\u{0020}Headquarters,\u{0020}we\u{0020}can\u{0020}come\u{0020}to\u{0020}a\u{0020}conclusion:\u{0020}She\u{0020}is\u{0020}a\u{0020}well-behaved\u{0020}child,\u{0020}one\u{0020}who\u{0020}is\u{0020}very\u{0020}polite\u{0020}to\u{0020}the\u{0020}people\u{0020}around\u{0020}her\u{0020}and\u{0020}uses\u{0020}honorific\u{0020}language\u{0020}to\u{0020}the\u{0020}navigators\u{0020}and\u{0020}seniors.\u{0020}She\u{0020}has\u{0020}preferences\u{0020}like\u{0020}a\u{0020}child,\u{0020}and\u{0020}likes\u{0020}fluffy\u{0020}animals\u{0020}and\u{0020}toys.\n\nHowever\u{0020}-\u{0020}beneath\u{0020}such\u{0020}a\u{0020}cute\u{0020}and\u{0020}lovely\u{0020}appearance,\u{0020}she\u{0020}occasionally\u{0020}reveals\u{0020}a\u{0020}terrifying\u{0020}side.\u{0020}She\u{0020}has\u{0020}a\u{0020}paranoid\u{0020}demand\u{0020}for\u{0020}the\u{0020}purity\u{0020}of\u{0020}love\u{0020}and\u{0020}an\u{0020}overly\u{0020}strong\u{0020}desire\u{0020}to\u{0020}control\u{0020}her\u{0020}own\u{0020}things.\u{0020}However,\u{0020}being\u{0020}naturally\u{0020}innocent,\u{0020}she\u{0020}is\u{0020}completely\u{0020}unaware\u{0020}of\u{0020}her\u{0020}own\u{0020}abnormalities.\n\nIf\u{0020}someone\u{0020}takes\u{0020}advantage\u{0020}of\u{0020}this\u{0020}Miko's\u{0020}innocence\u{0020}to\u{0020}deceive\u{0020}her,\u{0020}it\u{0020}is\u{0020}estimated\u{0020}that\u{0020}the\u{0020}outcome\u{0020}will\u{0020}be\u{0020}very\u{0020}bad...", "0", "0", "0", "0", 12004, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"感觉上是一个很可爱的孩子，不过就是有点……\"\n\u{1000}\u{1000}\"咱觉得那孩子超乖的——不过，咱偶尔也会有害怕她的时候，真奇怪呢。\"\n\u{1000}\u{1000}简单地将九州总部里每个人对她的第一印象汇总之后，我们能得到一个结论：她是一名乖巧的孩子，是一个会对身边的人非常礼貌，对领航与前辈会使用敬语的乖孩子。她有着像小孩子一样的喜好，喜欢着毛茸茸的动物与玩具。\n\u{1000}\u{1000}然而——在这般乖巧可爱的外表下，她偶尔也会流露出让人不寒而栗的一面。她对于爱的纯洁性有着偏执的要求，对于自己的东西有着过强的控制欲，然而，生性天真的她对于自己的异常一无所知。\n\u{1000}\u{1000}如果有人利用这名巫女的天真无暇欺骗了她，估计下场会很惨吧……"},
[620402] = {620402, 500, "\u{0020}\u{0020}Unlike\u{0020}others\u{0020}in\u{0020}Shingyou,\u{0020}Hanakotoba\u{0020}grew\u{0020}up\u{0020}in\u{0020}the\u{0020}shrine\u{0020}since\u{0020}childhood.\n\nHanakotoba\u{0020}believes\u{0020}in\u{0020}the\u{0020}existence\u{0020}of\u{0020}gods\u{0020}from\u{0020}the\u{0020}bottom\u{0020}of\u{0020}her\u{0020}heart.\u{0020}She\u{0020}believes\u{0020}that\u{0020}gods\u{0020}will\u{0020}surely\u{0020}come\u{0020}to\u{0020}the\u{0020}world\u{0020}when\u{0020}people\u{0020}need\u{0020}them\u{0020}most\u{0020}and\u{0020}guide\u{0020}people\u{0020}forward.\n\nWhen\u{0020}Hanakotoba\u{0020}just\u{0020}learned\u{0020}to\u{0020}read,\u{0020}she\u{0020}began\u{0020}to\u{0020}learn\u{0020}how\u{0020}to\u{0020}become\u{0020}a\u{0020}qualified\u{0020}Miko\u{0020}under\u{0020}the\u{0020}guidance\u{0020}of\u{0020}her\u{0020}grandfather.\u{0020}Unfortunately,\u{0020}before\u{0020}she\u{0020}could\u{0020}grow\u{0020}up\u{0020}and\u{0020}become\u{0020}a\u{0020}formal\u{0020}Miko\u{0020}to\u{0020}inherit\u{0020}the\u{0020}belief\u{0020}culture,\u{0020}Sin,\u{0020}which\u{0020}invaded\u{0020}the\u{0020}world,\u{0020}changed\u{0020}the\u{0020}way\u{0020}humans\u{0020}lived.\n\nDespair\u{0020}and\u{0020}fear\u{0020}made\u{0020}people\u{0020}lose\u{0020}their\u{0020}morality\u{0020}and\u{0020}humanity.\u{0020}Hanakotoba's\u{0020}grandfather,\u{0020}in\u{0020}order\u{0020}to\u{0020}protect\u{0020}the\u{0020}young\u{0020}Hanakotoba\u{0020}in\u{0020}the\u{0020}chaotic\u{0020}crowd,\u{0020}locked\u{0020}her\u{0020}in\u{0020}the\u{0020}deepest\u{0020}room\u{0020}of\u{0020}the\u{0020}shrine\u{0020}and\u{0020}cut\u{0020}off\u{0020}Hanakotoba's\u{0020}connection\u{0020}with\u{0020}the\u{0020}outside\u{0020}world.\u{0020}This\u{0020}extreme\u{0020}approach\u{0020}allowed\u{0020}Hanakotoba\u{0020}to\u{0020}safely\u{0020}pass\u{0020}through\u{0020}the\u{0020}most\u{0020}chaotic\u{0020}period,\u{0020}but\u{0020}it\u{0020}also\u{0020}left\u{0020}an\u{0020}indelible\u{0020}psychological\u{0020}shadow\u{0020}in\u{0020}the\u{0020}young\u{0020}Hanakotoba's\u{0020}heart.\n\nThe\u{0020}pitch-black\u{0020}room\u{0020}made\u{0020}the\u{0020}passage\u{0020}of\u{0020}time\u{0020}meaningless.\u{0020}She\u{0020}couldn't\u{0020}even\u{0020}determine\u{0020}whether\u{0020}she\u{0020}still\u{0020}existed\u{0020}-\u{0020}this\u{0020}sense\u{0020}of\u{0020}nothingness\u{0020}close\u{0020}to\u{0020}death\u{0020}distorted\u{0020}Hanakotoba's\u{0020}mind.\u{0020}If\u{0020}it\u{0020}weren't\u{0020}for\u{0020}the\u{0020}doll\u{0020}sewn\u{0020}by\u{0020}her\u{0020}grandfather\u{0020}accompanying\u{0020}her,\u{0020}Hanakotoba\u{0020}might\u{0020}have\u{0020}suffered\u{0020}even\u{0020}greater\u{0020}distortion.\n\nAfter\u{0020}the\u{0020}chaos\u{0020}ended,\u{0020}Hanakotoba\u{0020}returned\u{0020}to\u{0020}the\u{0020}outside\u{0020}world.\u{0020}Two\u{0020}changes\u{0020}occurred\u{0020}beside\u{0020}her.\u{0020}First,\u{0020}her\u{0020}grandfather\u{0020}became\u{0020}older.\u{0020}Second,\u{0020}she\u{0020}had\u{0020}two\u{0020}more\u{0020}companions:\u{0020}Kokorokami\u{0020}and\u{0020}Hotarugusa.\n\nThe\u{0020}grandfather\u{0020}taught\u{0020}Hanakotoba\u{0020}how\u{0020}to\u{0020}become\u{0020}a\u{0020}Miko\u{0020}who\u{0020}could\u{0020}save\u{0020}the\u{0020}world\u{0020}and\u{0020}redeem\u{0020}people's\u{0020}hearts.\u{0020}He\u{0020}was\u{0020}strict,\u{0020}stern,\u{0020}and\u{0020}ruthless,\u{0020}but\u{0020}he\u{0020}indeed\u{0020}saw\u{0020}through\u{0020}what\u{0020}this\u{0020}turbulent\u{0020}world\u{0020}needed\u{0020}most\u{0020}-\u{0020}it\u{0020}was\u{0020}faith.\u{0020}Under\u{0020}the\u{0020}guidance\u{0020}of\u{0020}this\u{0020}old\u{0020}man\u{0020}-\u{0020}the\u{0020}old\u{0020}shrine\u{0020}priest,\u{0020}a\u{0020}Miko\u{0020}who\u{0020}could\u{0020}become\u{0020}the\u{0020}spiritual\u{0020}pillar\u{0020}of\u{0020}the\u{0020}people\u{0020}was\u{0020}born.\n\nUnder\u{0020}the\u{0020}guidance\u{0020}of\u{0020}this\u{0020}old\u{0020}man\u{0020}-\u{0020}the\u{0020}old\u{0020}shrine\u{0020}priest,\u{0020}a\u{0020}Miko\u{0020}who\u{0020}could\u{0020}become\u{0020}the\u{0020}spiritual\u{0020}pillar\u{0020}of\u{0020}the\u{0020}people\u{0020}was\u{0020}born.", "0", "0", "0", "0", 12004, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}与心经屋的其他人不一样，花语从小便在神社里长大。\n\u{1000}\u{1000}花语打从心底里相信神明是存在的。她相信神灵一定会在人们最需要的时候降临于世，引导人们前进。\n\u{1000}\u{1000}在花语刚学会识字的时候，她便在祖父的教导下学习如何成为一名合格的巫女。遗憾的是，她还没来得及长大，作为一名正式的巫女来传承信仰文化，入侵人类生态圈的原罪便改变了人类的生存方式。\n\u{1000}\u{1000}绝望与恐惧让人们丧失了应有的道德与人性。花语的祖父为了在动乱的人群中将年幼花语保护起来，将她关到了神社最深处的屋子，阻断了花语与外界的联系。这一极端的做法让花语平安地度过了最动乱的时期，但也在年幼的花语心中留下了不可磨灭的心理阴影。\n\u{1000}\u{1000}漆黑的屋子，让时间的流逝失去了意义，伸手看不见五指，连自己是否还存在一事也无法通过客观事物来确定——这种接近死亡的虚无感，让花语的心灵出现了扭曲。如果不是因为有着祖父缝制的玩偶陪伴着她，花语或许会产生更大的扭曲。\n\u{1000}\u{1000}在最初的混乱结束后，花语重新回到了外边的世界。她的身边有两个地方发生了变化，第一，她祖父的脸庞更苍老了，第二，她多了两个同伴：心纸与莹草。\n\u{1000}\u{1000}祖父教导着花语如何成为一名能够拯救世界，救赎人心的巫女。他严苛，他严厉，他不讲情面，但他的确看透了这个动荡的世界最需要的是什么——是信仰。\n\u{1000}\u{1000}在这名老人——老神官的教导下，能够成为民众精神支柱的巫女诞生了。"},
[620403] = {620403, 1000, "\u{0020}\u{0020}Hanakotoba\u{0020}is\u{0020}without\u{0020}a\u{0020}doubt\u{0020}the\u{0020}most\u{0020}caring\u{0020}child\u{0020}in\u{0020}Shingyou,\u{0020}and\u{0020}her\u{0020}childlike\u{0020}personality\u{0020}inspires\u{0020}motherhood.\n\nTherefore,\u{0020}Hanakotoba\u{0020}is\u{0020}always\u{0020}taken\u{0020}care\u{0020}of\u{0020}by\u{0020}others\u{0020}in\u{0020}Kyushu\u{0020}Headquarters.\u{0020}Even\u{0020}teams\u{0020}that\u{0020}have\u{0020}not\u{0020}collaborated\u{0020}with\u{0020}Shingyou\u{0020}will\u{0020}take\u{0020}special\u{0020}care\u{0020}of\u{0020}Hanakotoba.\n\nHanakotoba\u{0020}seems\u{0020}to\u{0020}be\u{0020}aware\u{0020}of\u{0020}this,\u{0020}so\u{0020}this\u{0020}young\u{0020}girl\u{0020}is\u{0020}always\u{0020}annoyed\u{0020}with\u{0020}her\u{0020}own\u{0020}behavior\u{0020}after\u{0020}being\u{0020}childish.\u{0020}\"I\u{0020}should\u{0020}be\u{0020}more\u{0020}mature!\"\u{0020}She\u{0020}demands\u{0020}of\u{0020}herself\u{0020}like\u{0020}this.\n\nThen,\u{0020}recently,\u{0020}Hanakotoba\u{0020}seems\u{0020}to\u{0020}have\u{0020}undergone\u{0020}some\u{0020}changes.\n\nShe\u{0020}spends\u{0020}more\u{0020}time\u{0020}looking\u{0020}in\u{0020}the\u{0020}mirror,\u{0020}starts\u{0020}giggling\u{0020}alone\u{0020}from\u{0020}time\u{0020}to\u{0020}time,\u{0020}and\u{0020}begins\u{0020}to\u{0020}follow\u{0020}someone\u{0020}intentionally\u{0020}or\u{0020}unintentionally...\n\nAnyway,\n\nNavigator,\u{0020}please\u{0020}behave\u{0020}yourself.", "0", "0", "0", "0", 12004, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}花语毫无疑问的是心经屋中最需要人关怀的孩子，她孩子般的性格会激起人心中的母性。\n\u{1000}\u{1000}因而，花语在九州总部中总是被其他人照顾的，即使是和心经屋没有合作过的队伍，也会有人特意在生活上照顾花语。\n\u{1000}\u{1000}花语对此似乎也有自觉，所以这名少女总是在做出孩子气的行为后，为自己的行为感到懊恼。\"我应该更加成熟一点！\"她是如此要求自己的。\n\u{1000}\u{1000}然后，在最近的时间里——花语似乎有了一些变化。\n\u{1000}\u{1000}她照镜子的时间变长了，开始时不时会一个人傻笑，她开始有意无意地跟踪着某个人……\n\u{1000}\u{1000}不管怎么说，\n\u{1000}\u{1000}领航，请好自为之。"},
[620404] = {620404, 2000, "\u{0020}\u{0020}\"Navigator,\u{0020}will\u{0020}be\u{0020}guarded\u{0020}by\u{0020}me.\u{0020}I\u{0020}won't\u{0020}let\u{0020}anyone\u{0020}hurt\u{0020}Navigator.\"\n\nThis\u{0020}indicates\u{0020}the\u{0020}determination\u{0020}of\u{0020}the\u{0020}young\u{0020}girl\u{0020}and\u{0020}is\u{0020}also\u{0020}the\u{0020}lines\u{0020}by\u{0020}which\u{0020}she\u{0020}claims\u{0020}sovereignty.\n\nDraw\u{0020}the\u{0020}bow\u{0020}and\u{0020}nock\u{0020}the\u{0020}arrow,\u{0020}and\u{0020}shoot\u{0020}all\u{0020}the\u{0020}Sins\u{0020}without\u{0020}leaving\u{0020}any.\n\nBodies\u{0020}are\u{0020}everywhere,\u{0020}and\u{0020}the\u{0020}young\u{0020}girl\u{0020}is\u{0020}bathed\u{0020}in\u{0020}blood.\n\n\"Because\u{0020}Navigator\u{0020}belongs\u{0020}to\u{0020}me.\u{0020}I\u{0020}will\u{0020}definitely\u{0020}not\u{0020}give\u{0020}him\u{0020}to\u{0020}anyone\u{0020}else.\"\n\nIn\u{0020}her\u{0020}somewhat\u{0020}reddened\u{0020}pupils\u{0020}was\u{0020}reflected\u{0020}the\u{0020}small\u{0020}figure\u{0020}of\u{0020}the\u{0020}navigator.\n\n\"Navigator,\u{0020}you\u{0020}must\u{0020}want\u{0020}to\u{0020}be\u{0020}with\u{0020}me\u{0020}forever,\u{0020}right?\"\n\nThis\u{0020}is\u{0020}a\u{0020}fatal\u{0020}question.", "0", "0", "0", "0", 12004, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"领航——就由我来守护。我，不会让任何人伤到领航的。\"\n\u{1000}\u{1000}这是表明了少女的决心，也是少女宣誓主权的台词。\n\u{1000}\u{1000}张弓搭箭，将原罪一个不留地射杀，\n\u{1000}\u{1000}尸体遍布，少女沐浴着鲜血，\n\u{1000}\u{1000}\"因为——领航，是属于我的。绝对，绝对，绝对，我绝对不会把他让给别人的哦。\"\n\u{1000}\u{1000}她有些发红的眼瞳里映着领航小小的身影。\n\u{1000}\u{1000}\"领航，你也一定想要和我一直在一起吧，是吧？\"\n\u{1000}\u{1000}这是一道送命的题目。"},
[620500] = {620500, 0, "[Name]\u{0020}Iliya\u{0020}K\u{0020}Bronchi\n[B-Day]\u{0020}Aug\u{0020}14\n[Compatability\u{0020}Rate]\u{0020}92％\n[Height]\u{0020}36m\n[Squad]\u{0020}Ember\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Ice\u{0020}cream;\u{0020}Crush\u{0020}the\u{0020}core\u{0020}of\u{0020}Sin", "0", "0", "0", "0", 12005, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}伊莉雅·卡·布诺琪\n[B-Day]\u{1000}8月14日\n[幻化核心适格率]\u{1000}92％\n[Height]\u{1000}36m\n[部队]\u{1000}灰烬\n[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}冰激凌\u{1000}捏碎原罪的核心"},
[620501] = {620501, 100, "\u{0020}\u{0020}Iliya\u{0020}K\u{0020}Bronchi,\u{0020}an\u{0020}Avenger.\n\nShe\u{0020}hates,\u{0020}loathes\u{0020}and\u{0020}detests\u{0020}Sin.\u{0020}When\u{0020}facing\u{0020}Sin,\u{0020}her\u{0020}anger\u{0020}will\u{0020}make\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}her\u{0020}Transformation\u{0020}Core\u{0020}exceed\u{0020}the\u{0020}original\u{0020}value\u{0020}and\u{0020}burst\u{0020}out\u{0020}astonishing\u{0020}combat\u{0020}effectiveness.\n\nExcessive\u{0020}anger\u{0020}sometimes\u{0020}devours\u{0020}her\u{0020}reason,\u{0020}causing\u{0020}her\u{0020}to\u{0020}be\u{0020}extremely\u{0020}prone\u{0020}to\u{0020}losing\u{0020}control\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}She\u{0020}stabilizes\u{0020}her\u{0020}spirit\u{0020}by\u{0020}taking\u{0020}a\u{0020}drug\u{0020}called\u{0020}\"K93-type\u{0020}Psychotropic\u{0020}Suppressant\"\u{0020}to\u{0020}keep\u{0020}herself\u{0020}in\u{0020}a\u{0020}state\u{0020}of\u{0020}\"calm\u{0020}anger\".\n\nIliya's\u{0020}body\u{0020}has\u{0020}traces\u{0020}of\u{0020}multiple\u{0020}modifications,\u{0020}among\u{0020}which\u{0020}the\u{0020}most\u{0020}notable\u{0020}is\u{0020}her\u{0020}left\u{0020}arm\u{0020}-\u{0020}an\u{0020}arm\u{0020}that\u{0020}has\u{0020}been\u{0020}completely\u{0020}replaced\u{0020}with\u{0020}mechanical\u{0020}parts.\u{0020}Long\u{0020}before\u{0020}entering\u{0020}AEGIS,\u{0020}her\u{0020}body\u{0020}was\u{0020}already\u{0020}like\u{0020}this.\n\nAccording\u{0020}to\u{0020}herself,\u{0020}she\u{0020}voluntarily\u{0020}underwent\u{0020}physical\u{0020}modification\u{0020}in\u{0020}order\u{0020}to\u{0020}obtain\u{0020}stronger\u{0020}power\u{0020}to\u{0020}eliminate\u{0020}Sin.\n\nIn\u{0020}non-combat\u{0020}situations,\u{0020}Iliya's\u{0020}mental\u{0020}state\u{0020}is\u{0020}mostly\u{0020}stable\u{0020}most\u{0020}of\u{0020}the\u{0020}time.\n\nTherefore,\u{0020}it\u{0020}can\u{0020}be\u{0020}concluded\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}Sin\u{0020}is\u{0020}not\u{0020}mentioned,\u{0020}Iliya\u{0020}K\u{0020}Bronchi\u{0020}will\u{0020}not\u{0020}go\u{0020}berserk.", "0", "0", "0", "0", 12005, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}伊莉雅·卡·布诺琪，一名复仇者。\n\u{1000}\u{1000}她仇视、憎恶、痛恨着原罪，面对原罪时，怒火会让她的幻化核心适格率突破原有数值，爆发出惊人的战斗力。\n\u{1000}\u{1000}过度的愤怒有时会吞噬她的理智，导致她极易在战场上失控。她通过服用一种名为\"K93型精神抑制剂\"的药物来安定自己的精神，让自己保持\"平静的愤怒\"。\n\u{1000}\u{1000}伊莉雅的身体有多次改造的痕迹，其中最为显著的是她的左臂——一只完全被替换为机械零件的手臂。早在进入艾吉斯之前，她的身体就已经是这副模样了。\n\u{1000}\u{1000}据本人所说，她是自愿接受身体改造的，目的是能够获得更强的力量，来消灭原罪。\n\u{1000}\u{1000}战斗之外的场合，伊莉雅的精神大多时候都处于稳定状态。\n\u{1000}\u{1000}因此可以断定，只要不提及原罪，伊莉雅·卡·布诺琪便不会暴走。"},
[620502] = {620502, 500, "\u{0020}\"I\u{0020}am\u{0020}willing\u{0020}to\u{0020}transform\u{0020}into\u{0020}flames\u{0020}and\u{0020}burn\u{0020}Sins\u{0020}to\u{0020}ashes.\"\n\nIliya\u{0020}K\u{0020}Bronchi,\u{0020}an\u{0020}avenger\u{0020}destined\u{0020}to\u{0020}spend\u{0020}her\u{0020}entire\u{0020}life\u{0020}destroying\u{0020}Sin.\u{0020}Every\u{0020}drop\u{0020}of\u{0020}blood\u{0020}she\u{0020}sheds\u{0020}and\u{0020}every\u{0020}part\u{0020}of\u{0020}her\u{0020}body\u{0020}she\u{0020}loses\u{0020}will\u{0020}become\u{0020}nails\u{0020}that\u{0020}lock\u{0020}Sin\u{0020}in\u{0020}the\u{0020}coffin.\n\nSin\u{0020}took\u{0020}away\u{0020}her\u{0020}parents\u{0020}when\u{0020}she\u{0020}was\u{0020}twelve.\u{0020}After\u{0020}her\u{0020}parents'\u{0020}death,\u{0020}Iliya\u{0020}once\u{0020}wanted\u{0020}to\u{0020}join\u{0020}AEGIS\u{0020}to\u{0020}take\u{0020}revenge\u{0020}on\u{0020}Sin,\u{0020}but\u{0020}was\u{0020}rejected\u{0020}due\u{0020}to\u{0020}low\u{0020}Compatability\u{0020}Rate\u{0020}and\u{0020}potential\u{0020}mental\u{0020}health\u{0020}problems.\n\nAfterward,\u{0020}Iliya\u{0020}decided\u{0020}to\u{0020}join\u{0020}the\u{0020}company\u{0020}\"Siren\"\u{0020}where\u{0020}her\u{0020}parents\u{0020}used\u{0020}to\u{0020}work\u{0020}and\u{0020}participated\u{0020}in\u{0020}an\u{0020}experimental\u{0020}project\u{0020}\"Iron\u{0020}Man\u{0020}Project\"\u{0020}that\u{0020}her\u{0020}parents\u{0020}were\u{0020}once\u{0020}in\u{0020}charge\u{0020}of\u{0020}as\u{0020}the\u{0020}first\u{0020}volunteer\u{0020}experimental\u{0020}subject.\u{0020}The\u{0020}main\u{0020}purpose\u{0020}of\u{0020}this\u{0020}project\u{0020}is\u{0020}to\u{0020}replace\u{0020}human\u{0020}organs\u{0020}with\u{0020}mechanical\u{0020}parts\u{0020}for\u{0020}operation,\u{0020}so\u{0020}that\u{0020}it\u{0020}can\u{0020}better\u{0020}adapt\u{0020}to\u{0020}the\u{0020}\"test\u{0020}armor\u{0020}-\u{0020}Magicsteel\".\n\nThe\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}14-year-old\u{0020}Iliya\u{0020}with\u{0020}the\u{0020}armor\u{0020}and\u{0020}its\u{0020}Transformation\u{0020}Core\u{0020}reached\u{0020}an\u{0020}astonishing\u{0020}89%.\u{0020}However,\u{0020}due\u{0020}to\u{0020}the\u{0020}inhumane\u{0020}transformation\u{0020}experiments\u{0020}on\u{0020}the\u{0020}drivers\u{0020}for\u{0020}this\u{0020}technology,\u{0020}the\u{0020}armor\u{0020}has\u{0020}not\u{0020}been\u{0020}officially\u{0020}put\u{0020}into\u{0020}use\u{0020}by\u{0020}the\u{0020}military.\n\nIliya,\u{0020}who\u{0020}is\u{0020}eager\u{0020}to\u{0020}take\u{0020}revenge\u{0020}on\u{0020}Sin,\u{0020}reaches\u{0020}an\u{0020}agreement\u{0020}with\u{0020}Siren\u{0020}to\u{0020}exchange\u{0020}continuous\u{0020}maintenance\u{0020}materials\u{0020}by\u{0020}selling\u{0020}the\u{0020}core\u{0020}data\u{0020}of\u{0020}the\u{0020}armor\u{0020}and\u{0020}providing\u{0020}the\u{0020}experimental\u{0020}data\u{0020}of\u{0020}the\u{0020}armor\u{0020}regularly\u{0020}to\u{0020}Siren.\n\nAt\u{0020}this\u{0020}point,\u{0020}a\u{0020}mysterious\u{0020}team\u{0020}emerged\u{0020}on\u{0020}the\u{0020}snowfield.\u{0020}Whenever\u{0020}Sin\u{0020}invaded,\u{0020}they\u{0020}always\u{0020}charged\u{0020}at\u{0020}the\u{0020}frontier\u{0020}of\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}eliminated\u{0020}Sin\u{0020}with\u{0020}the\u{0020}most\u{0020}fierce\u{0020}means.", "0", "0", "0", "0", 12005, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}\"——我愿化身火焰，将原罪燃烧成灰。\"\n\u{1000}\u{1000}伊莉雅·卡·布诺琪，一个注定要用自己的一生去毁灭原罪的复仇者。她流出的每一滴血，失去的每一部分身体，都会成为将原罪关进棺材里的一根根钉子。\n\u{1000}\u{1000}原罪在她十二岁时夺走了她的父母。在双亲死后，伊莉雅一度想要加入艾吉斯，向原罪复仇，但因为适格率过低，以及精神状态的隐患等原因被拒之门外。\n\u{1000}\u{1000}之后，伊莉雅决定加入父母曾任职的公司\"塞伦\"，并以首位志愿者实验体的身份参与了父母曾经负责的一项实验计划\"铁人计划\"。该计划主要目的是，以少部分机械零件来代替人体器官进行工作，使其可以更好的适应\"试用型装甲-Magicsteel\"。\n\u{1000}\u{1000}十四岁的伊莉雅与该装甲及其幻化核心的适格率达到惊人的的89%。但因为该项技术对机师非人道的改造试验，因此该装甲一直没有被军方正式投入使用。\n\u{1000}\u{1000}急于向原罪复仇的伊莉雅，与塞伦达成协议，通过向塞伦出售装甲核心数据以及定期提供装甲的实验数据来换取持续的维修材料。\n\u{1000}\u{1000}至此，雪原上出现了一个神秘的队伍，每当原罪入侵的时候，她们总是冲击在战场的前线，用最狠戾的手段将原罪消灭。"},
[620503] = {620503, 1000, "\u{0020}\u{0020}The\u{0020}\"Ember\"\u{0020}team,\u{0020}led\u{0020}by\u{0020}Iliya,\u{0020}has\u{0020}always\u{0020}been\u{0020}in\u{0020}an\u{0020}awkward\u{0020}\"political\u{0020}position\"\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}She\u{0020}is\u{0020}neither\u{0020}a\u{0020}direct\u{0020}agency\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}government\u{0020}like\u{0020}\"Snow\u{0020}Owl\",\u{0020}nor\u{0020}is\u{0020}she\u{0020}like\u{0020}\"Cannonbore\",\u{0020}who\u{0020}can\u{0020}request\u{0020}any\u{0020}supplies\u{0020}from\u{0020}Siren\u{0020}to\u{0020}support\u{0020}the\u{0020}expenses\u{0020}of\u{0020}the\u{0020}troops.\n\n\"Ember\"\u{0020}is\u{0020}free,\u{0020}but\u{0020}the\u{0020}price\u{0020}of\u{0020}freedom\u{0020}is\u{0020}that\u{0020}few\u{0020}people\u{0020}reach\u{0020}out\u{0020}to\u{0020}them,\u{0020}and\u{0020}they\u{0020}have\u{0020}been\u{0020}living\u{0020}a\u{0020}life\u{0020}of\u{0020}poverty.\n\nThe\u{0020}original\u{0020}intention\u{0020}of\u{0020}Iliya\u{0020}in\u{0020}establishing\u{0020}\"Ember\"\u{0020}was\u{0020}to\u{0020}take\u{0020}revenge\u{0020}on\u{0020}Sin,\u{0020}rather\u{0020}than\u{0020}to\u{0020}protect\u{0020}the\u{0020}people\u{0020}of\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}She\u{0020}knew\u{0020}that\u{0020}once\u{0020}she\u{0020}joined\u{0020}AEGIS\u{0020}or\u{0020}obeyed\u{0020}the\u{0020}instructions\u{0020}of\u{0020}Siren\u{0020}like\u{0020}\"Cannonbore\",\u{0020}she\u{0020}would\u{0020}surely\u{0020}be\u{0020}restricted.\u{0020}Therefore,\u{0020}she\u{0020}has\u{0020}always\u{0020}rejected\u{0020}being\u{0020}incorporated\u{0020}by\u{0020}the\u{0020}government\u{0020}or\u{0020}companies.\n\nIt's\u{0020}a\u{0020}pity\u{0020}that\u{0020}reality\u{0020}is\u{0020}cruel.\u{0020}As\u{0020}the\u{0020}captain,\u{0020}she\u{0020}has\u{0020}to\u{0020}consider\u{0020}the\u{0020}normal\u{0020}operation\u{0020}of\u{0020}the\u{0020}team\u{0020}and\u{0020}the\u{0020}living\u{0020}problems\u{0020}of\u{0020}the\u{0020}team\u{0020}members.\u{0020}Therefore,\u{0020}taking\u{0020}the\u{0020}opportunity\u{0020}of\u{0020}contacting\u{0020}the\u{0020}leader\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Team,\u{0020}Iliya\u{0020}got\u{0020}the\u{0020}chance\u{0020}to\u{0020}join\u{0020}AEGIS.\n\nHowever,\u{0020}when\u{0020}she\u{0020}joined\u{0020}AEGIS,\u{0020}she\u{0020}put\u{0020}forward\u{0020}a\u{0020}requirement,\u{0020}which\u{0020}was:\u{0020}\"We\u{0020}only\u{0020}obey\u{0020}the\u{0020}command\u{0020}of\u{0020}the\u{0020}boss.\u{0020}If\u{0020}he\u{0020}leaves\u{0020}AEGIS,\u{0020}we\u{0020}will\u{0020}also\u{0020}leave.\"\n\nUndoubtedly,\u{0020}this\u{0020}girl\u{0020}who\u{0020}once\u{0020}only\u{0020}thought\u{0020}of\u{0020}\"revenge\",\u{0020}influenced\u{0020}by\u{0020}that\u{0020}leader,\u{0020}has\u{0020}begun\u{0020}to\u{0020}change.", "0", "0", "0", "0", 12005, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\u{1000}\u{1000}由伊莉雅领导的\"灰烬\"小队，在卡佳地区一直处于一个尴尬的\"政治位置\"。她既不像\"雪鸮\"一样，是艾吉斯政府的直属机构，也不像\"钢轮戈尔\"一样，可以向塞伦任意索取物资来维持部队的开销。\n\u{1000}\u{1000}\"灰烬\"是自由的，但自由的代价是鲜有人向她们伸出援手，一直以来过着拮据的生活。\n\u{1000}\u{1000}伊莉雅成立\"灰烬\"的初衷是向原罪复仇，而非保护卡佳地区的人民。她知道自己一旦加入艾吉斯，或者像\"钢轮戈尔\"那样服从塞伦的指令，势必会束手束脚，因此她一直以来排斥被政府、公司收编。\n\u{1000}\u{1000}只可惜现实是残酷的，身为队长，她必须要考虑到队伍的正常运转及队员的生活问题，所以，以接触多瑙特别联合队的领航为契机，伊莉雅得到了加入艾吉斯的机会。\n\u{1000}\u{1000}不过，她在加入艾吉斯时提出了一个要求，就是：\"我们仅听从老板…领航一个人的指挥，如果他离开了艾吉斯，我们也会离开。\"\n\u{1000}\u{1000}毋庸置疑，这位曾经只想着\"复仇\"的少女，受那名领航的影响，已经开始改变了。"},
[620504] = {620504, 2000, "\u{0020}\u{0020}The\u{0020}belated\u{0020}rainstorm\u{0020}attempts\u{0020}to\u{0020}extinguish\u{0020}the\u{0020}flames\u{0020}of\u{0020}war\u{0020}in\u{0020}this\u{0020}city.\n\nBetween\u{0020}the\u{0020}buildings,\u{0020}a\u{0020}huge\u{0020}girl\u{0020}is\u{0020}looking\u{0020}up\u{0020}at\u{0020}the\u{0020}cloudy\u{0020}sky.\n\nThe\u{0020}rainwater\u{0020}hit\u{0020}her\u{0020}cheek\u{0020}and\u{0020}slid\u{0020}to\u{0020}the\u{0020}ground\u{0020}after\u{0020}a\u{0020}long\u{0020}journey.\n\n\"Navigator...\u{0020}Well,\u{0020}I'm\u{0020}starting\u{0020}to\u{0020}get\u{0020}used\u{0020}to\u{0020}this\u{0020}title.\"\n\nShe\u{0020}said,\n\n\"If\u{0020}Sin\u{0020}disappears\u{0020}completely\u{0020}from\u{0020}this\u{0020}land,\u{0020}Iliya's\u{0020}life\u{0020}will\u{0020}also\u{0020}come\u{0020}to\u{0020}an\u{0020}end.\"\n\nIf\u{0020}only\u{0020}the\u{0020}hatred\u{0020}in\u{0020}the\u{0020}girl's\u{0020}heart\u{0020}could\u{0020}be\u{0020}extinguished\u{0020}like\u{0020}the\u{0020}burning\u{0020}fire\u{0020}in\u{0020}this\u{0020}city.\n\n\"After\u{0020}that,\u{0020}can\u{0020}you\u{0020}accompany\u{0020}me\u{0020}to\u{0020}start\u{0020}a\u{0020}new\u{0020}life,\u{0020}Navigator?\"", "0", "0", "0", "0", 12005, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}姗姗来迟的暴雨试图扑灭这座城市的战火，\n\u{1000}\u{1000}楼宇之间，巨大的少女正在仰头看着乌云密布的天空，\n\u{1000}\u{1000}雨水打在她的脸颊上，经过漫长的旅途后才滑落至地。\n\u{1000}\u{1000}\"老板……领航，啧，我果然还是不习惯这个称呼。\"\n\u{1000}\u{1000}她说，\n\u{1000}\u{1000}\"如果，原罪从这片大地上彻底消失了，‘伊莉雅’的人生也就结束了。\"\n\u{1000}\u{1000}如果，少女内心的仇恨能像这座城市里燃着的火一样被熄灭的话——\n\u{1000}\u{1000}\"——那之后，你能陪我开始新的人生吗，领航？\""},
[620700] = {620700, 0, "[Name]\u{0020}Huameng\n[B-Day]\u{0020}Jan\u{0020}13\n[Compatability\u{0020}Rate]\u{0020}76％\n[Height]\u{0020}33m\n[Squad]\u{0020}Tian\u{0020}Hua\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Buffet\u{0020}during\u{0020}and\u{0020}after\u{0020}spiritual\u{0020}practice", "0", "0", "0", "0", 12007, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}华梦\n[B-Day]\u{1000}1月13日\n[幻化核心适格率]\u{1000}76％\n[Height]\u{1000}29m\n[部队]\u{1000}天华阁\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}修行与修行之后的自助餐"},
[620701] = {620701, 100, "\u{0020}\u{0020}A\u{0020}stubborn\u{0020}and\u{0020}addicted\u{0020}vitality\u{0020}girl\u{0020}in\u{0020}cultivation,\u{0020}Tian\u{0020}Hua,\u{0020}and\u{0020}even\u{0020}the\u{0020}most\u{0020}gullible\u{0020}person\u{0020}in\u{0020}Kyushu\u{0020}Headquarters.\n\nIn\u{0020}her\u{0020}life\u{0020}so\u{0020}far,\u{0020}the\u{0020}act\u{0020}of\u{0020}\"cultivation\"\u{0020}has\u{0020}occupied\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}the\u{0020}space.\u{0020}In\u{0020}other\u{0020}words,\u{0020}she\u{0020}has\u{0020}no\u{0020}interest\u{0020}in\u{0020}anything\u{0020}other\u{0020}than\u{0020}cultivation\u{0020}and\u{0020}is\u{0020}obsessed\u{0020}with\u{0020}it\u{0020}to\u{0020}an\u{0020}outrageous\u{0020}degree.\u{0020}She\u{0020}has\u{0020}devoted\u{0020}her\u{0020}seemingly\u{0020}inexhaustible\u{0020}energy\u{0020}to\u{0020}cultivation.\n\nShe\u{0020}who\u{0020}spends\u{0020}most\u{0020}of\u{0020}her\u{0020}life\u{0020}on\u{0020}cultivation\u{0020}can\u{0020}be\u{0020}said\u{0020}to\u{0020}be\u{0020}as\u{0020}pure\u{0020}as\u{0020}a\u{0020}blank\u{0020}sheet\u{0020}in\u{0020}dealing\u{0020}with\u{0020}people\u{0020}and\u{0020}the\u{0020}world.\u{0020}When\u{0020}she\u{0020}talks\u{0020}with\u{0020}people,\u{0020}she\u{0020}always\u{0020}speaks\u{0020}directly\u{0020}and\u{0020}never\u{0020}beats\u{0020}around\u{0020}the\u{0020}bush\u{0020}-\u{0020}this\u{0020}also\u{0020}leads\u{0020}to\u{0020}sometimes\u{0020}making\u{0020}people\u{0020}feel\u{0020}that\u{0020}she\u{0020}doesn't\u{0020}know\u{0020}how\u{0020}to\u{0020}speak\u{0020}according\u{0020}to\u{0020}the\u{0020}occasion,\u{0020}which\u{0020}is\u{0020}somewhat\u{0020}similar\u{0020}to\u{0020}the\u{0020}situation\u{0020}of\u{0020}Captain\u{0020}of\u{0020}Tian\u{0020}Hua.\n\nDuring\u{0020}the\u{0020}time\u{0020}outside\u{0020}of\u{0020}cultivation,\u{0020}she\u{0020}often\u{0020}sneaks\u{0020}into\u{0020}the\u{0020}perilous\u{0020}mountains\u{0020}alone,\u{0020}fighting\u{0020}with\u{0020}wild\u{0020}animals\u{0020}and\u{0020}climbing\u{0020}to\u{0020}the\u{0020}top\u{0020}of\u{0020}cliffs.\u{0020}This\u{0020}is\u{0020}both\u{0020}a\u{0020}relaxation\u{0020}and\u{0020}a\u{0020}form\u{0020}of\u{0020}cultivation\u{0020}for\u{0020}her.", "0", "0", "0", "0", 12007, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}一根筋地沉迷在修行中的元气少女，天华阁，乃至九州总部最好骗的人。\n\u{1000}\u{1000}她迄今为止的人生中，\"修行\"这一行为占据着绝大部分的篇幅。换句话说，她对修行以外的事情毫无兴趣，痴迷修行到了一种令人发指的地步。她将自己似乎永远也用不完的精力用在了修行上。\n\u{1000}\u{1000}人生大半时间用在修行上的她可以说在为人处世上如同白纸一般纯净，她与人对话时素来有话直说，从来不拐弯抹角——这也导致有时候会让人觉得她不懂得看场合说话，这与天华阁队长的情况有些相似。\n\u{1000}\u{1000}在修行外的时间，她常常会一个人溜进危机四伏的大山中，与野生动物搏杀、攀爬绝壁登顶，这对她来说既是一种放松也是一种修行。\n\u{1000}\u{1000}\"偶尔有时候会觉得这孩子像个野兽呢，战斗的时候、平常的时候，都给我这样的感觉。\"——来自一位不肯透漏姓名的九州总部驾驶员的评价。"},
[620702] = {620702, 500, "\u{0020}\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}her\u{0020}hometown\u{0020}is\u{0020}a\u{0020}village\u{0020}with\u{0020}simple\u{0020}folkways\u{0020}located\u{0020}among\u{0020}the\u{0020}Ten-Thousand-Mountain\u{0020}Ranges.\n\nHuameng\u{0020}and\u{0020}Hualian\u{0020}are\u{0020}the\u{0020}only\u{0020}literate\u{0020}people\u{0020}in\u{0020}the\u{0020}village\u{0020}-\u{0020}and\u{0020}also\u{0020}the\u{0020}daughters\u{0020}of\u{0020}the\u{0020}village\u{0020}chief.\u{0020}Therefore,\u{0020}they\u{0020}know\u{0020}more\u{0020}about\u{0020}the\u{0020}outside\u{0020}world\u{0020}than\u{0020}ordinary\u{0020}children.\u{0020}Different\u{0020}from\u{0020}her\u{0020}sister\u{0020}Hualian,\u{0020}who\u{0020}has\u{0020}longing\u{0020}for\u{0020}the\u{0020}outside\u{0020}world,\u{0020}Huameng\u{0020}is\u{0020}devoted\u{0020}to\u{0020}her\u{0020}ancestral\u{0020}skill\u{0020}-\u{0020}martial\u{0020}arts.\n\nAccording\u{0020}to\u{0020}their\u{0020}father,\u{0020}the\u{0020}village\u{0020}chief,\u{0020}the\u{0020}martial\u{0020}arts\u{0020}passed\u{0020}down\u{0020}in\u{0020}their\u{0020}family\u{0020}was\u{0020}taught\u{0020}by\u{0020}a\u{0020}martial\u{0020}arts\u{0020}grandmaster\u{0020}who\u{0020}ran\u{0020}a\u{0020}medical\u{0020}hall\u{0020}a\u{0020}hundred\u{0020}years\u{0020}ago.\u{0020}That\u{0020}grandmaster\u{0020}was\u{0020}renowned\u{0020}in\u{0020}Kyushu,\u{0020}and\u{0020}even\u{0020}today,\u{0020}many\u{0020}people\u{0020}still\u{0020}remember\u{0020}his\u{0020}name\u{0020}and\u{0020}story.\n\nIn\u{0020}order\u{0020}to\u{0020}pursue\u{0020}the\u{0020}grandmaster\u{0020}in\u{0020}the\u{0020}story,\u{0020}Huameng\u{0020}was\u{0020}addicted\u{0020}to\u{0020}cultivation.\u{0020}Eventually\u{0020}-\u{0020}she\u{0020}forgot\u{0020}why\u{0020}she\u{0020}started\u{0020}practicing\u{0020}in\u{0020}the\u{0020}first\u{0020}place\u{0020}and\u{0020}became\u{0020}a\u{0020}strange\u{0020}person\u{0020}who\u{0020}practiced\u{0020}just\u{0020}for\u{0020}the\u{0020}sake\u{0020}of\u{0020}practicing.\u{0020}This\u{0020}is\u{0020}also\u{0020}different\u{0020}from\u{0020}Hualian,\u{0020}who\u{0020}accompanied\u{0020}her\u{0020}in\u{0020}cultivation\u{0020}with\u{0020}a\u{0020}strong\u{0020}purpose.\n\nThe\u{0020}reason\u{0020}why\u{0020}Huameng's\u{0020}nearly\u{0020}stable\u{0020}life\u{0020}like\u{0020}a\u{0020}mountain\u{0020}changed\u{0020}later\u{0020}originated\u{0020}from\u{0020}her\u{0020}accidental\u{0020}discovery\u{0020}of\u{0020}the\u{0020}existence\u{0020}of\u{0020}Sin.\u{0020}She,\u{0020}who\u{0020}had\u{0020}always\u{0020}lived\u{0020}in\u{0020}the\u{0020}\"different\u{0020}world\"\u{0020}of\u{0020}the\u{0020}Ten-Thousand-Mountain\u{0020}Ranges,\u{0020}knew\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}that\u{0020}there\u{0020}was\u{0020}a\u{0020}creature\u{0020}called\u{0020}\"Sin\"\u{0020}in\u{0020}the\u{0020}world.\u{0020}Encountering\u{0020}a\u{0020}bottleneck\u{0020}in\u{0020}her\u{0020}cultivation,\u{0020}she\u{0020}encouraged\u{0020}her\u{0020}sister\u{0020}Hualian\u{0020}to\u{0020}leave\u{0020}the\u{0020}village\u{0020}and\u{0020}head\u{0020}for\u{0020}the\u{0020}main\u{0020}battlefield\u{0020}in\u{0020}the\u{0020}Kyushu\u{0020}region.", "0", "0", "0", "0", 12007, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}据说她的家乡是位于十万大山之间的一个民风淳朴的村子。\n\u{1000}\u{1000}华梦与华恋是村子里唯一一个读书人——也同时是村长的女儿，因此比起一般的孩子要更加了解外面的世界。不同于妹妹华恋对外面的世界怀有憧憬，华梦一心醉心于自己祖传的技艺——武术上。\n\u{1000}\u{1000}按照她们的父亲，即村子的村长所说，她们祖传的武术是一位百年前经营医馆的武术宗师传下的。那位宗师在九州享有盛名，时至今日依然有很多人记着他的名字与故事。\n\u{1000}\u{1000}为了追逐那位故事中的宗师，华梦沉迷于修炼之中，最后——她反而忘了自己最初是因为什么而开始修行了，变成了为修行而修行的怪人。这一点也与抱着强烈目的性而陪伴她修炼的华恋也不太一样。\n\u{1000}\u{1000}华梦近乎大山般平稳的人生之所以会在后来出现变化，起源是她偶然间了解到了原罪的存在。一直生活在十万大山这个\"异世界\"中的她第一次知道世界上有种叫\"原罪\"的生物。在修行上遇到瓶颈的她，鼓动自己的妹妹华恋离开了村子，前往九州地区的主战场。"},
[620703] = {620703, 1000, "\u{0020}\u{0020}According\u{0020}to\u{0020}the\u{0020}normal\u{0020}procedure,\u{0020}Huameng\u{0020}needs\u{0020}to\u{0020}spend\u{0020}at\u{0020}least\u{0020}a\u{0020}year\u{0020}learning\u{0020}relevant\u{0020}knowledge\u{0020}to\u{0020}become\u{0020}an\u{0020}official\u{0020}driver.\u{0020}At\u{0020}that\u{0020}time,\u{0020}the\u{0020}battle\u{0020}situation\u{0020}at\u{0020}Kyushu\u{0020}Headquarters\u{0020}was\u{0020}intense.\u{0020}Coupled\u{0020}with\u{0020}Huameng's\u{0020}exaggerated\u{0020}experience,\u{0020}an\u{0020}exception\u{0020}was\u{0020}made\u{0020}to\u{0020}allow\u{0020}them\u{0020}to\u{0020}go\u{0020}to\u{0020}the\u{0020}battlefield\u{0020}in\u{0020}advance.\n\nBecause\u{0020}of\u{0020}the\u{0020}outstanding\u{0020}performance\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}although\u{0020}the\u{0020}relevant\u{0020}senior\u{0020}management\u{0020}accepted\u{0020}the\u{0020}punishment\u{0020}from\u{0020}the\u{0020}headquarters,\u{0020}Huameng\u{0020}still\u{0020}became\u{0020}the\u{0020}official\u{0020}driver\u{0020}of\u{0020}Kyushu\u{0020}Headquarters.\n\nEven\u{0020}after\u{0020}entering\u{0020}AEGIS,\u{0020}Huameng\u{0020}has\u{0020}not\u{0020}undergone\u{0020}any\u{0020}transformation.\u{0020}She\u{0020}is\u{0020}still\u{0020}on\u{0020}the\u{0020}endless\u{0020}path\u{0020}of\u{0020}cultivation,\u{0020}chasing\u{0020}the\u{0020}shadows\u{0020}of\u{0020}her\u{0020}predecessors.\n\nPerhaps\u{0020}one\u{0020}day,\u{0020}she\u{0020}will\u{0020}reach\u{0020}the\u{0020}end\u{0020}of\u{0020}it.\u{0020}She\u{0020}believes\u{0020}that\u{0020}there\u{0020}must\u{0020}be\u{0020}a\u{0020}more\u{0020}beautiful\u{0020}scenery\u{0020}than\u{0020}the\u{0020}mountains\u{0020}waiting\u{0020}for\u{0020}her.", "0", "0", "0", "0", 12007, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}按照正常的手续流程，华梦至少要花一年以上的时间学习相关知识才能成为正式的驾驶员。当时九州总部前线战况吃紧，再加上华梦夸张的经历，因此破例允许她们提前奔赴战场。\n\u{1000}\u{1000}因为战场上的出色表现，虽说相关高层接受了总部的处分，但华梦还是成为了九州总部的正式驾驶员。\n\u{1000}\u{1000}即使进入了艾吉斯，华梦也没有发生任何转变，她依然在走在没有尽头的修行之路上，追逐着前人的背影。\n\u{1000}\u{1000}也许有一天，她会抵达道路的终点。她相信，一定有比大山还要美丽的景色在那等着她。"},
[620704] = {620704, 2000, "\u{0020}\u{0020}Huameng\u{0020}once\u{0020}hoped\u{0020}to\u{0020}use\u{0020}waterfalls\u{0020}for\u{0020}practice.\n\nIt's\u{0020}just\u{0020}that\u{0020}for\u{0020}Huameng\u{0020}today,\u{0020}waterfalls\u{0020}practice\u{0020}is\u{0020}not\u{0020}that\u{0020}important.\n\n\"Navigator.\"\n\nShe\u{0020}held\u{0020}the\u{0020}Navigator\u{0020}and\u{0020}leaned\u{0020}against\u{0020}her\u{0020}favorite\u{0020}mountain.\n\nHuameng\u{0020}gazed\u{0020}at\u{0020}the\u{0020}waterfall\u{0020}and\u{0020}saw\u{0020}her\u{0020}own\u{0020}figure\u{0020}through\u{0020}it.\n\n\"I-\"\n\nThe\u{0020}young\u{0020}girl\u{0020}stopped.\n\n\"...I\u{0020}like\u{0020}this\u{0020}scenery,\u{0020}Navigator.\"\n\nEven\u{0020}for\u{0020}the\u{0020}straightforward\u{0020}her,\u{0020}it\u{0020}might\u{0020}still\u{0020}take\u{0020}some\u{0020}time\u{0020}to\u{0020}say\u{0020}that\u{0020}sentence.", "0", "0", "0", "0", 12007, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}华梦曾经盼望着用瀑布来进行修行。\n\u{1000}\u{1000}只是对于如今的华梦而言，瀑布——修行并不是那么重要了。\n\u{1000}\u{1000}\"领航。\"\n\u{1000}\u{1000}她捧着领航，靠在了自己最喜欢的大山上。\n\u{1000}\u{1000}华梦注视着瀑布，透过瀑布看到了自己的身影，\n\u{1000}\u{1000}\"小生——\"\n\u{1000}\u{1000}少女停下了。\n\u{1000}\u{1000}\"——小生喜欢这片风景，领航。\"\n\u{1000}\u{1000}即使是直率的她，想要说出那句话，或许还需要一段时间。"},
[620800] = {620800, 0, "[Name]\u{0020}Baili\u{0020}Momo\n[B-Day]\u{0020}Jan\u{0020}23\n[Compatability\u{0020}Rate]\u{0020}83％\n[Height]\u{0020}33m\n[Squad]\u{0020}Whale\u{0020}Fall\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Taking\u{0020}baths;\u{0020}blow-drying\u{0020}hair", "0", "0", "0", "0", 12008, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}百里默默\n[B-Day]\u{1000}1月23日\n[幻化核心适格率]\u{1000}83％\n[Height]\u{1000}33m\n[部队]\u{1000}鲸落\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}泡澡\u{1000}吹风"},
[620801] = {620801, 100, "\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}Whale\u{0020}Fall,\u{0020}she\u{0020}is\u{0020}also\u{0020}the\u{0020}youngest\u{0020}among\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}team,\u{0020}and\u{0020}is\u{0020}looked\u{0020}after\u{0020}by\u{0020}the\u{0020}captain\u{0020}of\u{0020}Whale\u{0020}Fall\u{0020}who\u{0020}treats\u{0020}her\u{0020}as\u{0020}her\u{0020}younger\u{0020}sister.\u{0020}Because\u{0020}she\u{0020}is\u{0020}the\u{0020}same\u{0020}age\u{0020}as\u{0020}the\u{0020}Whale\u{0020}Fall\u{0020}captain,\u{0020}she\u{0020}seems\u{0020}to\u{0020}be\u{0020}pleased\u{0020}to\u{0020}see\u{0020}the\u{0020}captain\u{0020}as\u{0020}an\u{0020}older\u{0020}sibling,\u{0020}and\u{0020}has\u{0020}a\u{0020}very\u{0020}close\u{0020}relationship\u{0020}with\u{0020}her.\n\nGenerally\u{0020}speaking,\u{0020}she's\u{0020}a\u{0020}good\u{0020}kid\u{0020}with\u{0020}a\u{0020}lively\u{0020}personality,\u{0020}but\u{0020}she's\u{0020}often\u{0020}seen\u{0020}talking\u{0020}to\u{0020}herself\u{0020}as\u{0020}if\u{0020}she's\u{0020}having\u{0020}a\u{0020}rational\u{0020}conversation\u{0020}with\u{0020}a\u{0020}imaginary\u{0020}friend.\n\nShe\u{0020}often\u{0020}expresses\u{0020}different\u{0020}opinions\u{0020}on\u{0020}the\u{0020}same\u{0020}matter,\u{0020}which\u{0020}she\u{0020}explains\u{0020}as\u{0020}being\u{0020}a\u{0020}way\u{0020}of\u{0020}communicating\u{0020}her\u{0020}own\u{0020}separate\u{0020}views\u{0020}from\u{0020}those\u{0020}of\u{0020}her\u{0020}deceased\u{0020}sisters.\u{0020}At\u{0020}present,\u{0020}some\u{0020}of\u{0020}the\u{0020}people\u{0020}in\u{0020}the\u{0020}Headquarters\u{0020}of\u{0020}Kyushu\u{0020}speculate\u{0020}that\u{0020}she\u{0020}suffers\u{0020}from\u{0020}dissociative\u{0020}identity\u{0020}disorder,\u{0020}while\u{0020}others\u{0020}consider\u{0020}her\u{0020}to\u{0020}be\u{0020}delusional,\u{0020}with\u{0020}only\u{0020}a\u{0020}few\u{0020}believing\u{0020}that\u{0020}her\u{0020}sisters'\u{0020}spirits\u{0020}really\u{0020}reside\u{0020}in\u{0020}her\u{0020}little\u{0020}head.", "0", "0", "0", "0", 12008, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}鲸落的成员之一，同时也是队伍里年龄最小的孩子，被鲸落的队长当做妹妹照顾。因为与鲸落队长同期的缘故，她本人似乎也很乐意把队长看做是自己的姐姐，与队长的关系十分亲昵。\n\u{1000}\u{1000}大体上，她是一个活泼的好孩子，但常常会有人目睹到她自言自语的场景，像是在和\"别人看不见的空气朋友\"进行着逻辑通顺的对话。\n\u{1000}\u{1000}经常会对同一件事情表达出不同的看法，她的解释是她是在分别传达自己与死去的姐姐的意见。目前，九州总部的一部分人猜测她患有多重人格障碍，另一部分人则认为她只是在妄想，只有极少数人才相信她小小的脑袋里真的寄宿着她姐姐的灵魂。"},
[620802] = {620802, 500, "\u{0020}\u{0020}Like\u{0020}the\u{0020}other\u{0020}two\u{0020}members\u{0020}of\u{0020}Whale\u{0020}Fall,\u{0020}Bairi\u{0020}Momo\u{0020}was\u{0020}raised\u{0020}by\u{0020}the\u{0020}sea.\n\nMomo's\u{0020}family\u{0020}has\u{0020}an\u{0020}age-old\u{0020}family\u{0020}tradition:\u{0020}burial\u{0020}at\u{0020}sea,\u{0020}in\u{0020}which,\u{0020}upon\u{0020}the\u{0020}death\u{0020}of\u{0020}a\u{0020}family\u{0020}member,\u{0020}the\u{0020}urn\u{0020}containing\u{0020}the\u{0020}deceased's\u{0020}ashes\u{0020}is\u{0020}sunk\u{0020}into\u{0020}the\u{0020}sea,\u{0020}believing\u{0020}that\u{0020}the\u{0020}final\u{0020}destination\u{0020}of\u{0020}the\u{0020}human\u{0020}soul\u{0020}is\u{0020}the\u{0020}sea,\u{0020}and\u{0020}that\u{0020}in\u{0020}the\u{0020}sea,\u{0020}the\u{0020}deceased\u{0020}will\u{0020}find\u{0020}eternal\u{0020}rest.\n\nBecause\u{0020}of\u{0020}this\u{0020}superstitious\u{0020}tradition,\u{0020}Momo's\u{0020}birth\u{0020}was\u{0020}seen\u{0020}as\u{0020}a\u{0020}gift\u{0020}from\u{0020}the\u{0020}sea\u{0020}by\u{0020}her\u{0020}mother,\u{0020}who\u{0020}had\u{0020}suffered\u{0020}several\u{0020}miscarriages\u{0020}due\u{0020}to\u{0020}her\u{0020}health,\u{0020}as\u{0020}well\u{0020}as\u{0020}by\u{0020}the\u{0020}rest\u{0020}of\u{0020}the\u{0020}family,\u{0020}and\u{0020}Momo's\u{0020}safe\u{0020}birth\u{0020}was\u{0020}a\u{0020}reward\u{0020}from\u{0020}the\u{0020}sea\u{0020}for\u{0020}the\u{0020}Momo\u{0020}family's\u{0020}unwavering\u{0020}faith,\u{0020}or\u{0020}so\u{0020}they\u{0020}believe.\n\nMomo\u{0020}showed\u{0020}no\u{0020}signs\u{0020}of\u{0020}abnormality\u{0020}until\u{0020}she\u{0020}was\u{0020}five\u{0020}years\u{0020}old,\u{0020}exhibiting\u{0020}all\u{0020}the\u{0020}activity\u{0020}expected\u{0020}of\u{0020}a\u{0020}child\u{0020}of\u{0020}her\u{0020}age,\u{0020}until\u{0020}one\u{0020}night,\u{0020}she\u{0020}suddenly\u{0020}ran\u{0020}to\u{0020}her\u{0020}mother\u{0020}and\u{0020}told\u{0020}her\u{0020}that\u{0020}she\u{0020}was\u{0020}hearing\u{0020}voices\u{0020}in\u{0020}her\u{0020}head.\n\nMomo's\u{0020}abnormality\u{0020}was\u{0020}beyond\u{0020}the\u{0020}family's\u{0020}imagination,\u{0020}and\u{0020}from\u{0020}that\u{0020}day\u{0020}on,\u{0020}Bairi\u{0020}Momo's\u{0020}family\u{0020}believed\u{0020}that\u{0020}Momo\u{0020}possessed\u{0020}the\u{0020}ability\u{0020}to\u{0020}talk\u{0020}to\u{0020}her\u{0020}deceased\u{0020}sisters.\n\nAfter\u{0020}the\u{0020}Danube\u{0020}incident,\u{0020}Bairi\u{0020}Momo\u{0020}was\u{0020}angered\u{0020}by\u{0020}the\u{0020}behavior\u{0020}of\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}\"Envy\",\u{0020}which\u{0020}she\u{0020}perceived\u{0020}as\u{0020}desecration\u{0020}of\u{0020}the\u{0020}sea,\u{0020}leaving\u{0020}her\u{0020}furious.\u{0020}When\u{0020}the\u{0020}AEGIS\u{0020}interviewer\u{0020}asked\u{0020}Bairi\u{0020}Momo\u{0020}why\u{0020}she\u{0020}had\u{0020}traveled\u{0020}so\u{0020}far\u{0020}to\u{0020}apply\u{0020}for\u{0020}the\u{0020}position,\u{0020}Bairi\u{0020}Momo\u{0020}replied\u{0020}in\u{0020}a\u{0020}voice\u{0020}that\u{0020}was\u{0020}distinctively\u{0020}sharp\u{0020}for\u{0020}her\u{0020}age:\n\n\"Momo's\u{0020}sisters\u{0020}are\u{0020}all\u{0020}sleeping\u{0020}in\u{0020}the\u{0020}sea,\u{0020}and\u{0020}Momo\u{0020}will\u{0020}not\u{0020}let\u{0020}those\u{0020}nasty\u{0020}Sins\u{0020}disturb\u{0020}them!", "0", "0", "0", "0", 12008, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}与鲸落另外两名成员一样，百里默默是在海边长大的孩子。\n\u{1000}\u{1000}默默的家族有古老的传统——海葬，在家人死后，会将装着家人骨灰的骨灰盒沉入大海，他们深信人类灵魂的最终归宿是大海，在大海里，亡者将得到永恒的安息。\n\u{1000}\u{1000}因为这一迷信的传统，默默的诞生被因身体原因而经历了数次流产的母亲，以及其他的家人视为来自大海的馈赠。默默之所以能平安降生，是大海对默默家族一直以来不曾动摇的信仰的回报，他们是如此认为的。\n\u{1000}\u{1000}默默一直到五岁为止都没有表现出任何的异常之处，她有着这个年龄的孩子该有的活泼好动。直到某个夜晚，她忽然跑到自己的母亲面前，对自己的母亲说自己脑袋里有其他的声音。\n\u{1000}\u{1000}默默的异常让家里人感到不可思议，也就是那天开始，百里默默的家人相信默默拥有着能与已故的姐姐们交谈的能力。\n\u{1000}\u{1000}多瑙事件结束后，高等原罪\"嫉妒\"的行为惹恼了百里默默。她认为原罪的行为是在亵渎大海，她对此感到愤怒。\n\u{1000}\u{1000}当艾吉斯的测试人员询问百里默默为何会千里迢迢赶来应征时，百里默默用她这个年龄特有的尖锐声音如此回答：\n\u{1000}\u{1000}\"茜茜姐、苑苑姐、伶伶姐——默默的姐姐们都在海里安眠，默默绝对不能让那些讨人厌的原罪打扰她们！\""},
[620803] = {620803, 1000, "\u{0020}\u{0020}Bairi\u{0020}Momo's\u{0020}somewhat\u{0020}neurotic\u{0020}way\u{0020}of\u{0020}talking\u{0020}and\u{0020}unpredictable\u{0020}train\u{0020}of\u{0020}thought\u{0020}have\u{0020}left\u{0020}those\u{0020}around\u{0020}her\u{0020}unsure\u{0020}of\u{0020}how\u{0020}to\u{0020}interact\u{0020}with\u{0020}her.\u{0020}Currently,\u{0020}only\u{0020}her\u{0020}teammates\u{0020}can\u{0020}understand\u{0020}her\u{0020}unusual\u{0020}way\u{0020}of\u{0020}communication.\n\nAccording\u{0020}to\u{0020}information\u{0020}provided\u{0020}by\u{0020}some\u{0020}private\u{0020}sources.\u{0020}In\u{0020}the\u{0020}dead\u{0020}of\u{0020}night,\u{0020}Bairi\u{0020}Momo\u{0020}will\u{0020}appear\u{0020}alone\u{0020}in\u{0020}a\u{0020}corner\u{0020}of\u{0020}the\u{0020}ark,\u{0020}looking\u{0020}up\u{0020}at\u{0020}the\u{0020}night\u{0020}sky,\u{0020}occasionally\u{0020}looking\u{0020}out\u{0020}to\u{0020}sea,\u{0020}where\u{0020}she\u{0020}will\u{0020}engage\u{0020}in\u{0020}her\u{0020}usual\u{0020}conversation\u{0020}with\u{0020}herself.\n\nAt\u{0020}this\u{0020}time,\u{0020}Bairi\u{0020}Momo\u{0020}exudes\u{0020}a\u{0020}sense\u{0020}of\u{0020}detachment\u{0020}that\u{0020}is\u{0020}hard\u{0020}to\u{0020}describe,\u{0020}even\u{0020}if\u{0020}someone\u{0020}witnesses\u{0020}the\u{0020}scene,\u{0020}they\u{0020}would\u{0020}not\u{0020}attempt\u{0020}to\u{0020}go\u{0020}up\u{0020}and\u{0020}speak\u{0020}to\u{0020}her.\n\nWhether\u{0020}Bairi\u{0020}Momo\u{0020}is\u{0020}a\u{0020}psychic\u{0020}who\u{0020}can\u{0020}communicate\u{0020}with\u{0020}the\u{0020}dead,\u{0020}a\u{0020}pure\u{0020}delusional\u{0020}individual,\u{0020}or\u{0020}a\u{0020}patient\u{0020}with\u{0020}dissociative\u{0020}identity\u{0020}disorder,\u{0020}there\u{0020}is\u{0020}still\u{0020}no\u{0020}definite\u{0020}proof\u{0020}of\u{0020}her\u{0020}identity.", "0", "0", "0", "0", 12008, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}百里默默有些神经质的说话方式以及让人捉摸不透的思考方式，让她周围的人不知道该如何与她相处。目前，只有与她同队的队友才能理解她那异于常人的沟通方式。\n\u{1000}\u{1000}据一部分人私下里提供的消息。每当夜深人静的时候，百里默默便会独自一人出现在方舟内的某个角落里，仰望着夜空，有时则是眺望大海，然后在那里进行着一如既往的自言自语。\n\u{1000}\u{1000}这个时候的百里默默，身上散发着一种难以名状的距离感，因此，即便有人目睹到了这一场景，也不会试图上去和她搭话。\n\u{1000}\u{1000}百里默默，究竟是能够与死者交流的超能力者，还是一个纯粹的妄想狂、又或者是一个多重人格障碍的患者，这件事至今没能得到一个确切的结论。"},
[620804] = {620804, 2000, "\u{0020}\u{0020}Bairi\u{0020}Momo\u{0020}was\u{0020}in\u{0020}the\u{0020}depths\u{0020}of\u{0020}the\u{0020}sea,\u{0020}her\u{0020}eyes\u{0020}wide\u{0020}open\u{0020}as\u{0020}if\u{0020}she\u{0020}was\u{0020}trying\u{0020}to\u{0020}peer\u{0020}through\u{0020}the\u{0020}trail\u{0020}of\u{0020}the\u{0020}flowing\u{0020}waves.\n\n\"Glub,\u{0020}glub.\"\u{0020}opening\u{0020}her\u{0020}mouth,\u{0020}she\u{0020}could\u{0020}only\u{0020}make\u{0020}such\u{0020}incomprehensible\u{0020}sounds.\n\nA\u{0020}school\u{0020}of\u{0020}fish\u{0020}took\u{0020}her\u{0020}mouth\u{0020}as\u{0020}a\u{0020}natural\u{0020}cavern\u{0020}in\u{0020}the\u{0020}deep\u{0020}sea,\u{0020}waiting\u{0020}for\u{0020}an\u{0020}opportunity\u{0020}to\u{0020}enter.\n\nBubbles\u{0020}of\u{0020}air\u{0020}drifted\u{0020}past\u{0020}her\u{0020}golden\u{0020}pupils,\u{0020}yet\u{0020}she\u{0020}continued\u{0020}to\u{0020}gaze\u{0020}into\u{0020}the\u{0020}silence\u{0020}of\u{0020}the\u{0020}sea.\n\nAfter\u{0020}some\u{0020}time,\u{0020}she\u{0020}emerged\u{0020}from\u{0020}the\u{0020}sea\u{0020}and\u{0020}looked\u{0020}at\u{0020}Navigator,\n\n\"Momo\u{0020}would\u{0020}still\u{0020}return\u{0020}to\u{0020}the\u{0020}sea,\u{0020}back\u{0020}to\u{0020}the\u{0020}side\u{0020}of\u{0020}my\u{0020}sisters.\"\n\n\"...Until\u{0020}then,\u{0020}Navigator,\u{0020}will\u{0020}you\u{0020}keep\u{0020}Momo\u{0020}company?", "0", "0", "0", "0", 12008, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}百里默默正在水中，\n\u{1000}\u{1000}她睁大着眼睛，像是要把流水的痕迹都看透一般。\n\u{1000}\u{1000}\"咕咕咕——\"\n\u{1000}\u{1000}张开嘴也只能发出意味不明的声音。\n\u{1000}\u{1000}有一群海鱼把她的嘴当做深海中的天然岩洞，想要伺机而入。\n\u{1000}\u{1000}气泡从她金色的眼瞳前飘过，她依然在凝视着寂静的深海。\n\u{1000}\u{1000}良久，她从海中浮出，看向领航，\n\u{1000}\u{1000}\"——默默还是会回归大海的，回到姐姐们的身边。\"\n\u{1000}\u{1000}\"……在那之前，领航，你能一直陪着默默吗？\""},
[620900] = {620900, 0, "[Name]\u{0020}Maria\u{0020}Y\u{0020}Stepanek\n[B-Day]\u{0020}March\u{0020}1\n[Compatability\u{0020}Rate]\u{0020}88％\n[Height]\u{0020}41m\n[Squad]\u{0020}Snow\u{0020}Owl\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Hug\u{0020}people", "0", "0", "0", "0", 12009, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}玛利亚·亚·斯捷潘内克\n[B-Day]\u{1000}3月1日\n[幻化核心适格率]\u{1000}88％\n[Height]\u{1000}41m\n[部队]\u{1000}雪鸮\n[隶属]\u{1000}Katya\u{1000}Branch\n[Interest]\u{1000}和人拥抱"},
[620901] = {620901, 100, "\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}official\u{0020}team\u{0020}\"Snow\u{0020}Owl\"\u{0020}of\u{0020}Katya\u{0020}Branch,\u{0020}like\u{0020}other\u{0020}members\u{0020}from\u{0020}this\u{0020}team,\u{0020}she\u{0020}is\u{0020}very\u{0020}good\u{0020}at\u{0020}fighting\u{0020}in\u{0020}snow,\u{0020}frozen\u{0020}soil\u{0020}and\u{0020}tundra\u{0020}areas.\n\nDuring\u{0020}battles,\u{0020}she\u{0020}usually\u{0020}serves\u{0020}as\u{0020}long-range\u{0020}fire\u{0020}support\u{0020}in\u{0020}land\u{0020}and\u{0020}air\u{0020}battles\u{0020}and\u{0020}is\u{0020}the\u{0020}most\u{0020}reliable\u{0020}backing\u{0020}in\u{0020}the\u{0020}team.\u{0020}\"Only\u{0020}when\u{0020}she\u{0020}is\u{0020}behind\u{0020}us\u{0020}can\u{0020}we\u{0020}fight\u{0020}at\u{0020}ease.\"\u{0020}Her\u{0020}captain\u{0020}Lydia\u{0020}evaluated\u{0020}her\u{0020}in\u{0020}this\u{0020}way.\n\nNot\u{0020}only\u{0020}is\u{0020}her\u{0020}performance\u{0020}reliable\u{0020}and\u{0020}reassuring\u{0020}during\u{0020}battles,\u{0020}but\u{0020}in\u{0020}life,\u{0020}this\u{0020}elder\u{0020}sister\u{0020}is\u{0020}also\u{0020}very\u{0020}popular\u{0020}among\u{0020}the\u{0020}members\u{0020}of\u{0020}Katya\u{0020}Branch.\u{0020}Her\u{0020}natural\u{0020}and\u{0020}simple\u{0020}character\u{0020}makes\u{0020}it\u{0020}very\u{0020}difficult\u{0020}for\u{0020}others\u{0020}not\u{0020}to\u{0020}like\u{0020}her.\u{0020}However,\u{0020}sometimes\u{0020}she\u{0020}always\u{0020}makes\u{0020}many\u{0020}overly\u{0020}intimate\u{0020}moves\u{0020}towards\u{0020}others\u{0020}inadvertently,\u{0020}thereby\u{0020}causing\u{0020}some\u{0020}unnecessary\u{0020}misunderstandings.", "0", "0", "0", "0", 12009, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}Katya\u{1000}Branch官方小队\"雪鸮\"的成员之一，和来自该部队的其他成员一样，她十分擅长在雪地冻土、苔原地带战斗。\n\u{1000}\u{1000}在战斗中，她通常担任着陆地战、空战时的远程火力支援，是队伍中最为可靠的后盾。\"只有她在我们身后，我们才能安心战斗。\"她的队长莉迪娅是如此评价她的。\n\u{1000}\u{1000}她不仅在战斗时的表现令人感到可靠踏实，在生活中，这位大姐姐也十分受Katya\u{1000}Branch成员的欢迎。她那种天然质朴的性格让别人很难不喜欢上她。然而，有的时候她总是会在不经意间对他人做出很多在常人眼里过于亲昵的举动，从而引起一些不必要的误会。"},
[620902] = {620902, 500, "\u{0020}\u{0020}Maria\u{0020}Y\u{0020}Stepanek\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}drivers\u{0020}who\u{0020}have\u{0020}served\u{0020}the\u{0020}longest\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region\u{0020}at\u{0020}present.\n\nBefore\u{0020}becoming\u{0020}a\u{0020}driver,\u{0020}she\u{0020}fought\u{0020}against\u{0020}Sin\u{0020}many\u{0020}times\u{0020}as\u{0020}an\u{0020}officer\u{0020}with\u{0020}the\u{0020}army\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}government\u{0020}and\u{0020}accumulated\u{0020}rich\u{0020}combat\u{0020}experience.\u{0020}Because\u{0020}the\u{0020}activity\u{0020}area\u{0020}borders\u{0020}the\u{0020}Kyushu\u{0020}region,\u{0020}Maria\u{0020}went\u{0020}to\u{0020}the\u{0020}Kyushu\u{0020}region\u{0020}more\u{0020}than\u{0020}once\u{0020}and\u{0020}fought\u{0020}side\u{0020}by\u{0020}side\u{0020}with\u{0020}the\u{0020}troops\u{0020}in\u{0020}the\u{0020}Kyushu\u{0020}region,\u{0020}forming\u{0020}a\u{0020}deep\u{0020}friendship.\n\nThe\u{0020}battle\u{0020}against\u{0020}Sin\u{0020}was\u{0020}almost\u{0020}like\u{0020}walking\u{0020}with\u{0020}death.\u{0020}The\u{0020}closest\u{0020}she\u{0020}had\u{0020}ever\u{0020}been\u{0020}to\u{0020}death\u{0020}was\u{0020}a\u{0020}battle\u{0020}before\u{0020}she\u{0020}became\u{0020}a\u{0020}driver.\u{0020}It\u{0020}was\u{0020}a\u{0020}doomed\u{0020}urban\u{0020}defense\u{0020}battle.\u{0020}Facing\u{0020}the\u{0020}massive\u{0020}attack\u{0020}of\u{0020}Sin,\u{0020}Maria's\u{0020}team\u{0020}had\u{0020}no\u{0020}resistance\u{0020}and\u{0020}could\u{0020}only\u{0020}evacuate\u{0020}from\u{0020}the\u{0020}city.\n\nHowever,\u{0020}the\u{0020}evacuation\u{0020}did\u{0020}not\u{0020}go\u{0020}as\u{0020}smoothly\u{0020}as\u{0020}expected.\u{0020}Her\u{0020}comrade\u{0020}Lydia\u{0020}was\u{0020}injured\u{0020}and\u{0020}had\u{0020}difficulty\u{0020}moving.\u{0020}In\u{0020}order\u{0020}to\u{0020}cover\u{0020}Lydia's\u{0020}retreat,\u{0020}they\u{0020}were\u{0020}disconnected\u{0020}from\u{0020}the\u{0020}main\u{0020}force\u{0020}and\u{0020}missed\u{0020}the\u{0020}best\u{0020}time\u{0020}to\u{0020}evacuate.\n\nSin,\u{0020}which\u{0020}was\u{0020}wantonly\u{0020}destroying\u{0020}the\u{0020}city,\u{0020}blocked\u{0020}Maria's\u{0020}way\u{0020}of\u{0020}escaping\u{0020}from\u{0020}the\u{0020}city,\u{0020}and\u{0020}the\u{0020}temperature\u{0020}of\u{0020}minus\u{0020}twenty\u{0020}degrees\u{0020}Celsius\u{0020}made\u{0020}it\u{0020}extremely\u{0020}difficult\u{0020}for\u{0020}them\u{0020}to\u{0020}move.\u{0020}Their\u{0020}death\u{0020}was\u{0020}only\u{0020}a\u{0020}matter\u{0020}of\u{0020}time.\n\nThe\u{0020}countdown\u{0020}of\u{0020}life\u{0020}is\u{0020}about\u{0020}to\u{0020}end,\u{0020}but\u{0020}neither\u{0020}Maria\u{0020}nor\u{0020}Lydia\u{0020}is\u{0020}the\u{0020}kind\u{0020}of\u{0020}person\u{0020}who\u{0020}would\u{0020}wait\u{0020}passively\u{0020}for\u{0020}death.\u{0020}They\u{0020}attempted\u{0020}to\u{0020}create\u{0020}miracles\u{0020}in\u{0020}their\u{0020}own\u{0020}way\u{0020}-\u{0020}and\u{0020}they\u{0020}indeed\u{0020}did\u{0020}it.\n\n\"Well?\u{0020}How\u{0020}did\u{0020}I\u{0020}do\u{0020}it?\u{0020}Um...\u{0020}Uh...\u{0020}I\u{0020}can't\u{0020}remember\u{0020}the\u{0020}details\u{0020}anymore.\u{0020}The\u{0020}only\u{0020}thing\u{0020}I\u{0020}still\u{0020}remember\u{0020}is\u{0020}-\u{0020}it\u{0020}was\u{0020}very\u{0020}cold,\u{0020}Lydia\u{0020}lay\u{0020}down\u{0020}in\u{0020}the\u{0020}snow,\u{0020}constantly\u{0020}saying\u{0020}that\u{0020}she\u{0020}didn't\u{0020}want\u{0020}to\u{0020}die\u{0020}here.\"\n\n\"\u{0020}'I\u{0020}can't\u{0020}let\u{0020}her\u{0020}die\u{0020}in\u{0020}such\u{0020}a\u{0020}place!',\u{0020}I\u{0020}seemed\u{0020}to\u{0020}think\u{0020}so\u{0020}at\u{0020}that\u{0020}time...\u{0020}Um,\u{0020}that's\u{0020}it!\"", "0", "0", "0", "0", 12009, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}玛利亚·亚·斯捷潘内克是卡佳地区目前服役时间最长的驾驶员之一。\n\u{1000}\u{1000}在成为一名驾驶员之前，她便以军官的身份随着艾吉斯政府的军队多次与原罪作战，积攒下了丰富的作战经验。因为活动区域与九州地区接壤的缘故，玛利亚不止一次地前往九州地区，与九州地区的部队并肩作战，结下了深厚的情谊。\n\u{1000}\u{1000}与原罪的战斗，几乎是与死亡同行，而她经历过离死亡最近的一次战役，则是在她成为驾驶员之前的一场战役。那是一场注定会失败的城市保卫战，面对原罪的大举进攻，玛利亚的队伍毫无抵抗能力，只能从城市中撤离。\n\u{1000}\u{1000}然而，撤离工作并没有想象中那样顺利，她当时的战友莉迪娅因战受伤，行动不便，为了掩护莉迪娅撤退，她们与主力部队脱节，错过了最佳的撤离时间。\n\u{1000}\u{1000}在大肆破坏城市的原罪阻断了玛利亚逃离城市的道路，而零下负二十摄氏度的温度让她们寸步难行，距离死亡，也只是时间问题。\n\u{1000}\u{1000}生命的倒计时即将结束，但无论是玛利亚还是莉迪娅都不是会坐以待毙的人，她们试图用自己的方式去创造奇迹——而她们，的确做到了。\n\u{1000}\u{1000}\"嗯？我是怎么做到的？嗯……呜……已经记不起细节啦。我唯一还记得的就是——天气很冷，莉迪娅躺倒在雪地里，不停地说着不想死在这里。\"\n\u{1000}\u{1000}\"‘不能让她死在这种地方！’，我当时好像就是这么想的……嗯，就是这样啦！\""},
[620903] = {620903, 1000, "\u{0020}\u{0020}Perhaps\u{0020}it\u{0020}was\u{0020}that\u{0020}situation\u{0020}of\u{0020}being\u{0020}in\u{0020}a\u{0020}freezing\u{0020}and\u{0020}helpless\u{0020}environment\u{0020}that\u{0020}left\u{0020}a\u{0020}deep\u{0020}psychological\u{0020}shadow\u{0020}on\u{0020}Maria,\u{0020}which\u{0020}she\u{0020}seemed\u{0020}not\u{0020}to\u{0020}be\u{0020}aware\u{0020}of.\u{0020}After\u{0020}that\u{0020}incident,\u{0020}Maria\u{0020}became\u{0020}extremely\u{0020}fond\u{0020}of\u{0020}intimate\u{0020}contact\u{0020}with\u{0020}people.\u{0020}It\u{0020}has\u{0020}become\u{0020}her\u{0020}habit\u{0020}to\u{0020}keep\u{0020}warm\u{0020}through\u{0020}physical\u{0020}contact.\n\nNot\u{0020}only\u{0020}the\u{0020}\"Cannonbore\"\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region\u{0020}has\u{0020}suffered\u{0020}from\u{0020}her\u{0020}harassment\u{0020}method\u{0020}similar\u{0020}to\u{0020}\"embracing\",\u{0020}even\u{0020}the\u{0020}drivers\u{0020}of\u{0020}the\u{0020}neighboring\u{0020}Kyushu\u{0020}Headquarters\u{0020}were\u{0020}hugged\u{0020}fiercely\u{0020}by\u{0020}her\u{0020}at\u{0020}the\u{0020}exchange\u{0020}meeting.\u{0020}\"In\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}where\u{0020}I\u{0020}am,\u{0020}such\u{0020}strange\u{0020}people\u{0020}are\u{0020}rare\u{0020}-\u{0020}\"\u{0020}This\u{0020}may\u{0020}be\u{0020}the\u{0020}inner\u{0020}thought\u{0020}of\u{0020}most\u{0020}Kyushu\u{0020}Headquarters\u{0020}drivers.\n\nMaria\u{0020}has\u{0020}been\u{0020}committed\u{0020}to\u{0020}reviving\u{0020}the\u{0020}economy\u{0020}of\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}During\u{0020}her\u{0020}spare\u{0020}time\u{0020}from\u{0020}missions,\u{0020}she\u{0020}mostly\u{0020}appears\u{0020}in\u{0020}civilian\u{0020}areas,\u{0020}cares\u{0020}about\u{0020}the\u{0020}lives\u{0020}of\u{0020}civilians,\u{0020}and\u{0020}hopes\u{0020}for\u{0020}the\u{0020}war\u{0020}to\u{0020}end\u{0020}soon.\u{0020}Years\u{0020}of\u{0020}battles\u{0020}have\u{0020}made\u{0020}her\u{0020}long\u{0020}for\u{0020}peace\u{0020}more\u{0020}than\u{0020}the\u{0020}average\u{0020}driver.\u{0020}\"When...\u{0020}will\u{0020}the\u{0020}war\u{0020}end?\"\n\n\"When...\u{0020}will\u{0020}the\u{0020}war\u{0020}end?\"", "0", "0", "0", "0", 12009, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}也许是那段冰天雪地，孤立无援的处境给玛利亚留下了深刻的心理阴影——尽管她本人似乎没有察觉到——那件事之后，玛利亚变得格外喜欢与人亲密接触。通过肢体接触的方式来取暖，这已经成为了她的习惯。\n\u{1000}\u{1000}不只是同为卡佳地区的\"钢轮戈尔\"小队遭受过她类似\"拥抱\"的骚扰方式，就连邻居的九州总部的驾驶员也在交流会上被她恶狠狠地拥抱过。\"在老身所处的九州总部，这样的怪人也不多见——\"这或许是大多数九州总部驾驶员的内心想法。\n\u{1000}\u{1000}玛利亚一直致力于复兴卡佳地区的经济。执行任务外的时间，她大多数出现在平民生活的地方，关心平民的生活，盼望着战争早日结束。常年的征战，让她比起一般的驾驶员更加盼望和平来到。\n\u{1000}\u{1000}\"战争……到底什么时候才会结束呢？\""},
[620904] = {620904, 2000, "\u{0020}\u{0020}A\u{0020}layer\u{0020}of\u{0020}snow\u{0020}covers\u{0020}the\u{0020}barren\u{0020}frozen\u{0020}soil.\n\nEvery\u{0020}step\u{0020}leaves\u{0020}a\u{0020}mark\u{0020}in\u{0020}the\u{0020}snow.\n\nThe\u{0020}snowflakes\u{0020}that\u{0020}were\u{0020}blown\u{0020}down\u{0020}by\u{0020}the\u{0020}strong\u{0020}wind\u{0020}in\u{0020}the\u{0020}air\u{0020}landed\u{0020}on\u{0020}the\u{0020}body.\n\nThe\u{0020}unmelted\u{0020}snow\u{0020}made\u{0020}her\u{0020}look\u{0020}like\u{0020}a\u{0020}moving\u{0020}snow\u{0020}mountain\u{0020}from\u{0020}afar.\n\nShe\u{0020}looked\u{0020}into\u{0020}the\u{0020}distance,\u{0020}looking\u{0020}at\u{0020}her\u{0020}hometown.\n\n\"Navigator...\u{0020}This\u{0020}is\u{0020}my\u{0020}hometown,\u{0020}Katya.\"\n\nHer\u{0020}title\u{0020}has\u{0020}changed\u{0020}several\u{0020}times,\u{0020}but\u{0020}what\u{0020}remains\u{0020}unchanged\u{0020}is\u{0020}this\u{0020}freezing\u{0020}and\u{0020}desolate\u{0020}scene.\n\n\"It\u{0020}was\u{0020}like\u{0020}this\u{0020}in\u{0020}the\u{0020}past,\u{0020}and\u{0020}it\u{0020}is\u{0020}still\u{0020}like\u{0020}this\u{0020}now.\u{0020}If\u{0020}the\u{0020}war\u{0020}does\u{0020}not\u{0020}end,\u{0020}she\u{0020}will\u{0020}always\u{0020}be\u{0020}like\u{0020}this.\"\n\n\"Please\u{0020}end\u{0020}the\u{0020}war,\u{0020}Navigator.\"", "0", "0", "0", "0", 12009, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}寸草不生的冻土上铺上一层积雪，\n\u{1000}\u{1000}每走一步都能在雪地上留下脚印。\n\u{1000}\u{1000}空中伴随着狂风飘下的雪花落在了身上，\n\u{1000}\u{1000}未能消融的雪，让她远远看上去就像一座移动雪山。\n\u{1000}\u{1000}她望着远方，望着自己的家乡。\n\u{1000}\u{1000}\"领航…这里就是我的家乡，卡佳。\"\n\u{1000}\u{1000}\"她的称呼几次更替，但不变的是这天寒地冻的景象。\n\u{1000}\u{1000}过去是这样，现在也是这样。如果战争不结束的话，她永远都会是这样——\"\n\u{1000}\u{1000}\"——请结束战争吧，领航。\""},
[621000] = {621000, 0, "[Name]\u{0020}Meika\n[B-Day]\u{0020}Oct\u{0020}10\n[Compatability\u{0020}Rate]\u{0020}89%\n[Height]\u{0020}34m\n[Squad]\u{0020}Ninja\u{0020}Group\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Coffee\u{0020}milk\u{0020}with\u{0020}a\u{0020}mixing\u{0020}ratio\u{0020}of\u{0020}7\u{0020}to\u{0020}3;\u{0020}cathartic\u{0020}battles", "0", "0", "0", "0", 12010, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}冥火\n[B-Day]\u{1000}10月10日\n[幻化核心适格率]\u{1000}89%\n[Height]\u{1000}34m\n[部队]\u{1000}忍心社\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}混合比例为7比3的咖啡牛奶\u{1000}发泄式的战斗"},
[621001] = {621001, 100, "\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group,\u{0020}like\u{0020}the\u{0020}others,\u{0020}\"Meika\"\u{0020}is\u{0020}not\u{0020}her\u{0020}real\u{0020}name,\u{0020}but\u{0020}only\u{0020}a\u{0020}code\u{0020}name\u{0020}when\u{0020}she\u{0020}is\u{0020}on\u{0020}a\u{0020}mission.\u{0020}Like\u{0020}the\u{0020}others,\u{0020}she\u{0020}hides\u{0020}her\u{0020}true\u{0020}appearance\u{0020}during\u{0020}the\u{0020}operation.\n\nIsn't\u{0020}she\u{0020}acting\u{0020}openly?\u{0020}Surely\u{0020}someone\u{0020}will\u{0020}raise\u{0020}such\u{0020}a\u{0020}question...\u{0020}Although\u{0020}that's\u{0020}indeed\u{0020}the\u{0020}case,\u{0020}it\u{0020}doesn't\u{0020}mean\u{0020}she\u{0020}hasn't\u{0020}\"hidden\u{0020}herself\".\n\nThe\u{0020}Meika\u{0020}we\u{0020}know\u{0020}is\u{0020}a\u{0020}lunatic\u{0020}who\u{0020}always\u{0020}bares\u{0020}her\u{0020}teeth,\u{0020}has\u{0020}a\u{0020}bad\u{0020}temper,\u{0020}and\u{0020}enjoys\u{0020}bombarding\u{0020}wildly\u{0020}during\u{0020}battles\u{0020}-\u{0020}So,\u{0020}is\u{0020}there\u{0020}really\u{0020}such\u{0020}a\u{0020}person\u{0020}in\u{0020}Kyushu\u{0020}Headquarters?\n\nWe\u{0020}have\u{0020}not\u{0020}found\u{0020}any\u{0020}drivers\u{0020}or\u{0020}logistics\u{0020}personnel\u{0020}who\u{0020}match\u{0020}the\u{0020}characteristics\u{0020}of\u{0020}Meika.\u{0020}We\u{0020}do\u{0020}not\u{0020}know\u{0020}what\u{0020}the\u{0020}real\u{0020}\"Meika\"\u{0020}is\u{0020}like.\u{0020}People\u{0020}can\u{0020}know\u{0020}that\u{0020}the\u{0020}huge\u{0020}and\u{0020}hot-tempered\u{0020}girl\u{0020}who\u{0020}appears\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}is\u{0020}Meika,\u{0020}but\u{0020}when\u{0020}she\u{0020}leaves\u{0020}the\u{0020}battlefield,\u{0020}changes\u{0020}her\u{0020}specific\u{0020}clothing\u{0020}and\u{0020}conceals\u{0020}her\u{0020}true\u{0020}personality\u{0020}-\u{0020}how\u{0020}can\u{0020}we\u{0020}know\u{0020}who\u{0020}the\u{0020}\"Meika\"\u{0020}is?\n\nActors\u{0020}who\u{0020}leave\u{0020}a\u{0020}movie,\u{0020}even\u{0020}standing\u{0020}under\u{0020}a\u{0020}character\u{0020}poster,\u{0020}can\u{0020}be\u{0020}ignored\u{0020}by\u{0020}people.", "0", "0", "0", "0", 12010, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}忍心社的成员之一，和其他成员一样，\"冥火\"并非她真实的名字，仅仅只是她执行任务时的代号。和其他成员一样，她会在行动时隐藏自己的真实模样——\n\u{1000}\u{1000}——她不是正大光明地在行动着吗？肯定会有人提出这样的问题吧…虽然的确是这样没错，但这不意味着她没有\"隐藏自己\"。\n\u{1000}\u{1000}我们熟知的冥火是一个总是龇牙咧嘴，脾气暴躁，在战斗时以狂轰乱炸为乐的疯子——那么，九州总部里真的有这样的人吗？\n\u{1000}\u{1000}我们并没有发现符合冥火特征的驾驶员、后勤人员，我们并不知道真实的\"冥火\"是什么样的人。人们可以知道出现在战场上，脾气暴躁的巨大少女是冥火，但离开了战场，换下了特定的服饰，掩盖了真正的个性——我们怎样才能知道谁才是那个\"冥火\"呢？\n\u{1000}\u{1000}从电影中离开的演员，即便是站在角色海报的下面也一样会被人无视。"},
[621002] = {621002, 500, "\u{0020}\u{0020}Meika's\u{0020}past\u{0020}could\u{0020}be\u{0020}surprisingly\u{0020}easily\u{0020}investigated\u{0020}and\u{0020}was\u{0020}not\u{0020}deliberately\u{0020}hidden\u{0020}or\u{0020}erased.\n\nPerhaps\u{0020}it\u{0020}is\u{0020}because\u{0020}-\u{0020}even\u{0020}if\u{0020}one\u{0020}knows\u{0020}her\u{0020}past,\u{0020}one\u{0020}may\u{0020}not\u{0020}necessarily\u{0020}know\u{0020}her\u{0020}true\u{0020}identity.\u{0020}Or\u{0020}rather,\u{0020}this\u{0020}\"past\"\u{0020}itself\u{0020}is\u{0020}false\u{0020}information.\n\nBefore\u{0020}having\u{0020}the\u{0020}code\u{0020}name\u{0020}\"Meika\",\u{0020}this\u{0020}young\u{0020}girl\u{0020}had\u{0020}an\u{0020}ordinary\u{0020}name\u{0020}and\u{0020}an\u{0020}ordinary\u{0020}family.\u{0020}What\u{0020}was\u{0020}extraordinary\u{0020}was\u{0020}her\u{0020}physical\u{0020}condition.\n\nShe\u{0020}has\u{0020}two\u{0020}personalities.\n\nOne\u{0020}personality\u{0020}is\u{0020}the\u{0020}\"Meika\"\u{0020}we\u{0020}are\u{0020}familiar\u{0020}with,\u{0020}who\u{0020}is\u{0020}short-tempered\u{0020}and\u{0020}irritable.\u{0020}In\u{0020}the\u{0020}few\u{0020}combat\u{0020}missions,\u{0020}she\u{0020}often\u{0020}has\u{0020}conflicts\u{0020}with\u{0020}others.\u{0020}And\u{0020}the\u{0020}other\u{0020}personality\u{0020}of\u{0020}Meika\u{0020}is\u{0020}said\u{0020}to\u{0020}be\u{0020}an\u{0020}understanding,\u{0020}gentle\u{0020}and\u{0020}considerate\u{0020}good\u{0020}child\u{0020}who\u{0020}has\u{0020}nothing\u{0020}to\u{0020}do\u{0020}with\u{0020}\"quarrels\".\n\nTheoretically,\u{0020}there\u{0020}is\u{0020}no\u{0020}primary\u{0020}or\u{0020}secondary\u{0020}distinction\u{0020}between\u{0020}the\u{0020}two\u{0020}personalities,\u{0020}and\u{0020}they\u{0020}can\u{0020}switch\u{0020}the\u{0020}dominance\u{0020}of\u{0020}the\u{0020}body\u{0020}at\u{0020}will.\u{0020}However,\u{0020}perhaps\u{0020}because\u{0020}people\u{0020}prefer\u{0020}the\u{0020}gentle\u{0020}and\u{0020}considerate\u{0020}personality\u{0020}and\u{0020}reject\u{0020}the\u{0020}hot-tempered\u{0020}one,\u{0020}in\u{0020}the\u{0020}past\u{0020}days,\u{0020}the\u{0020}irritable\u{0020}one\u{0020}has\u{0020}always\u{0020}been\u{0020}in\u{0020}slumber\u{0020}and\u{0020}unwilling\u{0020}to\u{0020}come\u{0020}out\u{0020}and\u{0020}communicate\u{0020}with\u{0020}people.\n\nBut\u{0020}they\u{0020}have\u{0020}no\u{0020}hostility\u{0020}towards\u{0020}the\u{0020}other\u{0020}\"self\".\u{0020}When\u{0020}the\u{0020}gentle\u{0020}one\u{0020}is\u{0020}bullied,\u{0020}the\u{0020}irritable\u{0020}other\u{0020}personality\u{0020}will\u{0020}appear\u{0020}and\u{0020}drive\u{0020}away\u{0020}those\u{0020}who\u{0020}bully\u{0020}her.\u{0020}The\u{0020}gentle\u{0020}one\u{0020}will\u{0020}also\u{0020}voluntarily\u{0020}hand\u{0020}over\u{0020}the\u{0020}control\u{0020}of\u{0020}the\u{0020}body\u{0020}to\u{0020}the\u{0020}irritable\u{0020}one\u{0020}in\u{0020}a\u{0020}situation\u{0020}where\u{0020}she\u{0020}won't\u{0020}be\u{0020}disturbed.\n\nHowever,\u{0020}although\u{0020}the\u{0020}parties\u{0020}do\u{0020}not\u{0020}mind\u{0020}this\u{0020}strange\u{0020}interdependent\u{0020}relationship,\u{0020}their\u{0020}parents\u{0020}seem\u{0020}unable\u{0020}to\u{0020}accept\u{0020}this\u{0020}situation.\u{0020}When\u{0020}Meika's\u{0020}parents\u{0020}learned\u{0020}that\u{0020}there\u{0020}was\u{0020}a\u{0020}\"psychic\u{0020}force\u{0020}coordination\u{0020}device\"\u{0020}in\u{0020}the\u{0020}AEGIS\u{0020}academy\u{0020}that\u{0020}could\u{0020}stabilize\u{0020}the\u{0020}mind,\u{0020}they\u{0020}let\u{0020}their\u{0020}child\u{0020}take\u{0020}the\u{0020}AEGIS\u{0020}Compatability\u{0020}Rate\u{0020}Test.\u{0020}They\u{0020}hoped\u{0020}that\u{0020}AEGIS\u{0020}could\u{0020}make\u{0020}their\u{0020}daughter\u{0020}a\u{0020}normal\u{0020}person\u{0020}-\u{0020}in\u{0020}their\u{0020}view,\u{0020}the\u{0020}so-called\u{0020}\"normal\"\u{0020}meant\u{0020}the\u{0020}disappearance\u{0020}of\u{0020}the\u{0020}\"irritable\u{0020}Meika\".\n\nWhen\u{0020}taking\u{0020}the\u{0020}AEGIS\u{0020}test,\u{0020}the\u{0020}testers\u{0020}found\u{0020}that\u{0020}when\u{0020}Meika\u{0020}was\u{0020}in\u{0020}the\u{0020}\"irritable\u{0020}personality\",\u{0020}she\u{0020}showed\u{0020}an\u{0020}extremely\u{0020}high\u{0020}Transformation\u{0020}Core\u{0020}Compatability\u{0020}Rate,\u{0020}while\u{0020}when\u{0020}she\u{0020}was\u{0020}in\u{0020}the\u{0020}\"gentle\u{0020}personality\",\u{0020}it\u{0020}would\u{0020}be\u{0020}so\u{0020}low\u{0020}that\u{0020}she\u{0020}couldn't\u{0020}even\u{0020}start\u{0020}the\u{0020}AVG.\n\nAfter\u{0020}passing\u{0020}the\u{0020}test,\u{0020}Meika\u{0020}entered\u{0020}the\u{0020}AEGIS\u{0020}academy\u{0020}for\u{0020}training.\u{0020}At\u{0020}the\u{0020}time\u{0020}of\u{0020}entry,\u{0020}she\u{0020}made\u{0020}her\u{0020}own\u{0020}request\u{0020}to\u{0020}AEGIS:\n\n\"In\u{0020}any\u{0020}case,\u{0020}please\u{0020}don't\u{0020}let\u{0020}'us'\u{0020}disappear.\u{0020}Without\u{0020}either\u{0020}one,\u{0020}I\u{0020}wouldn't\u{0020}be\u{0020}me.\"\n\nIt\u{0020}doesn't\u{0020}matter\u{0020}which\u{0020}personality\u{0020}made\u{0020}it.\u{0020}We\u{0020}-\u{0020}AEGIS\u{0020}believes\u{0020}that\u{0020}no\u{0020}matter\u{0020}which\u{0020}personality,\u{0020}both\u{0020}have\u{0020}the\u{0020}right\u{0020}to\u{0020}\"live\".", "0", "0", "0", "0", 12010, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}冥火的过去意外地很容易就能查到，并没有被刻意地隐藏、消除。\n\u{1000}\u{1000}也许是因为——即便知道她的过去，也未必能知道她的真实身份吧。又或者说，这段\"过去\"本身就是虚假的信息。\n\u{1000}\u{1000}在拥有\"冥火\"这个代号之前，这名少女有一个普通的名字，和一个普通的家庭，而不普通的地方，在于她的身体情况。\n\u{1000}\u{1000}她有着两个人格。\n\u{1000}\u{1000}一个人格是我们熟知的\"冥火\"，脾气暴躁、易怒，在为数不多的作战任务中，常会与人发生摩擦。而另一个人格的冥火，据说是一个善解人意、温柔体贴，与\"争吵\"无缘的好孩子。\n\u{1000}\u{1000}理论上，两个人格之间没有主次之分，她们之间可以任意更换对身体的支配权。不过，也许是人们更加喜欢温柔体贴的人格，排斥性情暴躁的人格的缘故，在过去的日子里，易怒的她总是在沉睡中，不愿出来和人交流。\n\u{1000}\u{1000}但她们对另一个\"自己\"，并没有心存敌意。当温和的她遭受欺负时，暴躁的另一个人格便会出现，把欺负自己的人赶跑。温和的她也会主动在不会被人打扰的情况下，将身体的控制权交给易怒的她。\n\u{1000}\u{1000}不过，尽管当事人并不介意这种奇怪的依存关系，但她们的父母似乎无法接受这种情况。当冥火的双亲知道艾吉斯的驾驶员学院里有着能够让精神稳定下来的\"精神力协调装置\"时，便让孩子参加了艾吉斯的幻化核心适格率测试。他们希望艾吉斯能让他们的女儿变成正常人——在他们看来，所谓的\"正常\"，便是\"易怒的冥火\"消失。\n\u{1000}\u{1000}在接受艾吉斯测试时，测试人员发现，当冥火处于\"易怒人格\"时，表现出极高幻化核心适格率，而处于\"温和人格\"时，便会低到连启动AVG都做不到的程度。\n\u{1000}\u{1000}测试通过后，冥火进入艾吉斯驾驶员学院接受培训。在进入之际，她向艾吉斯提出了自己的请求：\n\u{1000}\u{1000}\"无论如何，请不要让‘我们’消失。少了任何一个，我就不是我了。\"\n\u{1000}\u{1000}是由哪个人格提出来的，其实并不重要。我们——艾吉斯认为，无论是哪一个人格，都有权利\"活着\"。"},
[621003] = {621003, 1000, "\u{0020}\u{0020}\"Meika\"\u{0020}performed\u{0020}quite\u{0020}well\u{0020}in\u{0020}the\u{0020}hospital.\u{0020}She\u{0020}graduated\u{0020}from\u{0020}the\u{0020}driver\u{0020}academy\u{0020}with\u{0020}honors\u{0020}within\u{0020}two\u{0020}years,\u{0020}but\u{0020}after\u{0020}graduation,\u{0020}she\u{0020}did\u{0020}not\u{0020}become\u{0020}a\u{0020}driver\u{0020}immediately,\u{0020}but\u{0020}was\u{0020}active\u{0020}in\u{0020}an\u{0020}unknown\u{0020}corner\u{0020}as\u{0020}a\u{0020}logistics\u{0020}staff\u{0020}responsible\u{0020}for\u{0020}testing\u{0020}equipment.\n\nOn\u{0020}the\u{0020}other\u{0020}hand,\u{0020}she\u{0020}passed\u{0020}the\u{0020}test\u{0020}of\u{0020}the\u{0020}secret\u{0020}force\u{0020}\"Ninja\u{0020}Group\"\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}this\u{0020}special\u{0020}force\u{0020}to\u{0020}carry\u{0020}out\u{0020}special\u{0020}combat\u{0020}tasks.\n\nIn\u{0020}other\u{0020}words,\u{0020}an\u{0020}agreement\u{0020}was\u{0020}reached\u{0020}between\u{0020}Meika's\u{0020}two\u{0020}personalities.\u{0020}When\u{0020}acting\u{0020}as\u{0020}an\u{0020}ordinary\u{0020}person,\u{0020}it\u{0020}is\u{0020}the\u{0020}gentle\u{0020}her,\u{0020}using\u{0020}her\u{0020}original\u{0020}name.\u{0020}Only\u{0020}when\u{0020}appearing\u{0020}as\u{0020}a\u{0020}driver\u{0020}and\u{0020}being\u{0020}active\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}whether\u{0020}bright\u{0020}or\u{0020}dark,\u{0020}the\u{0020}other\u{0020}her,\u{0020}\"Meika\"\u{0020}will\u{0020}emerge.", "0", "0", "0", "0", 12010, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"冥火\"在院中的表现相当出色，她在两年内以优异的成绩从驾驶员学校毕业，但毕业后的她并没有立即成为一名驾驶员，而是作为一名负责调试装备的后勤人员活跃在不为人知的角落。\n\u{1000}\u{1000}另一方面，她又通过了秘密部队\"忍心社\"的考验，成为了这支特殊部队的一员，执行特殊作战任务。\n\u{1000}\u{1000}换句话说，冥火的两个人格之间达成了协议，但以普通人身份行动时，便是温和的她，使用着自己原本的名字。只有以驾驶员身份出现，活跃在或明或暗的战场上时，另一个她——\"冥火\"才会出现。"},
[621004] = {621004, 2000, "\u{0020}Gentle\u{0020}and\u{0020}kind\u{0020}people\u{0020}are\u{0020}always\u{0020}liked.\n\nNot\u{0020}to\u{0020}mention\u{0020}she\u{0020}is\u{0020}always\u{0020}so\u{0020}intelligent\u{0020}and\u{0020}always\u{0020}knows\u{0020}what\u{0020}others\u{0020}are\u{0020}thinking.\n\nThe\u{0020}self\u{0020}who\u{0020}cannot\u{0020}control\u{0020}one's\u{0020}temper\u{0020}and\u{0020}only\u{0020}knows\u{0020}to\u{0020}vent\u{0020}dissatisfaction\u{0020}through\u{0020}violence\n\nIt\u{0020}is\u{0020}okay\u{0020}to\u{0020}be\u{0020}refused\u{0020}by\u{0020}people,\u{0020}not\u{0020}loved\u{0020}by\u{0020}parents,\u{0020}and\u{0020}regarded\u{0020}as\u{0020}\"weird\".\n\nHowever,\n\n\"I\u{0020}-\u{0020}don't\u{0020}want\u{0020}to\u{0020}disappear.\"\n\nShe\u{0020}sat\u{0020}on\u{0020}the\u{0020}edge\u{0020}of\u{0020}the\u{0020}mountain,\u{0020}like\u{0020}an\u{0020}abandoned\u{0020}puppy.\n\nAlthough,\u{0020}as\u{0020}for\u{0020}the\u{0020}\"puppy\",\u{0020}she\u{0020}is\u{0020}indeed\u{0020}a\u{0020}bit\u{0020}too\u{0020}big.\n\n\"...Obviously,\u{0020}I\u{0020}haven't\u{0020}done\u{0020}anything\u{0020}wrong...\u{0020}Why\u{0020}can't\u{0020}everyone\u{0020}accept\u{0020}me?\"\n\n\"I\u{0020}also\u{0020}want...\u{0020}to\u{0020}be\u{0020}like\u{0020}'her',\u{0020}and\u{0020}loved\u{0020}by\u{0020}others.\"\n\nThen,\n\n\"...People\u{0020}love\u{0020}you.\"\u{0020}\"She\"\u{0020}said,\n\n\"Even\u{0020}if\u{0020}everyone\u{0020}wants\u{0020}you\u{0020}to\u{0020}disappear...\u{0020}I,\u{0020}and\u{0020}Navigator,\u{0020}must\u{0020}be\u{0020}loving\u{0020}you.\"", "0", "0", "0", "0", 12010, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}温柔善良的人总是招人喜欢的，\n\u{1000}\u{1000}更何况她还总那么聪敏，总能知道别人在想些什么。\n\u{1000}\u{1000}而控制不住自己脾气的自己，只知道用暴力来发泄不满的自己，\n\u{1000}\u{1000}不被人们接受，不被父母喜爱，被当做\"不正常的人\"看，也没什么奇怪的。\n\u{1000}\u{1000}但是，\n\u{1000}\u{1000}\"我——不想消失。\"\n\u{1000}\u{1000}她坐在山的边上，像一条被人遗弃的小狗似的\n\u{1000}\u{1000}——尽管，就\"小狗\"而言，她着实太大了点。\n\u{1000}\u{1000}\"…明明，我没做错什么……为什么，大家就不能接受我？\"\n\u{1000}\u{1000}\"我也想…像‘她’一样，被人喜欢，被人爱着啊。\"\n\u{1000}\u{1000}然后，\u{1000}\n\u{1000}\u{1000}\"…有人爱着你的。\"\"她\"说，\n\u{1000}\u{1000}\"——就算所有人都希望你消失…我，还有领航，一定是——爱着你的。\""},
[621100] = {621100, 0, "[Name]:\u{0020}Samghrma\n[B-Day]:\u{0020}May\u{0020}7\n[Compatability\u{0020}Rate]:\u{0020}91%\n[Height]:\u{0020}34m\n[Squad]:\u{0020}Whale\u{0020}Fall\n[Affiliation]:\u{0020}Kyushu\u{0020}Headquarters\n[Interest]:\u{0020}Knowledge\u{0020}comes\u{0020}from\u{0020}books\u{0020}and\u{0020}firsthand\u{0020}experience.", "0", "0", "0", "0", 12011, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[621101] = {621101, 100, "\u{3000}\u{3000}This\u{0020}quiet,\u{0020}introspective\u{0020}girl\u{0020}possesses\u{0020}a\u{0020}sensitivity\u{0020}far\u{0020}beyond\u{0020}the\u{0020}ordinary.\u{0020}\n\n\u{3000}\u{3000}After\u{0020}the\u{0020}Saar\u{0020}incident,\u{0020}to\u{0020}prevent\u{0020}such\u{0020}tragedies\u{0020}from\u{0020}recurring,\u{0020}Kyushu\u{0020}Headquarters\u{0020}established\u{0020}a\u{0020}specialized\u{0020}aquatic\u{0020}unit:\u{0020}Whale\u{0020}Fall.\u{0020}Following\u{0020}an\u{0020}exhaustive\u{0020}selection\u{0020}process,\u{0020}Samghrma\u{0020}became\u{0020}one\u{0020}of\u{0020}its\u{0020}members.\u{0020}\n\n\u{3000}\u{3000}Most\u{0020}days,\u{0020}she\u{0020}can\u{0020}be\u{0020}found\u{0020}buried\u{0020}in\u{0020}the\u{0020}archives\u{0020}of\u{0020}AEGIS\u{0020}or\u{0020}among\u{0020}the\u{0020}shelves\u{0020}of\u{0020}the\u{0020}library.\u{0020}Though\u{0020}she\u{0020}appears\u{0020}to\u{0020}get\u{0020}on\u{0020}well\u{0020}with\u{0020}the\u{0020}rest\u{0020}of\u{0020}Whale\u{0020}Fall,\u{0020}she\u{0020}insists\u{0020}she\u{0020}still\u{0020}prefers\u{0020}solitude\u{0020}which\u{0020}stems\u{0020}from\u{0020}over\u{0020}a\u{0020}decade\u{0020}of\u{0020}life\u{0020}at\u{0020}sea.\u{0020}\n\n\u{3000}\u{3000}But\u{0020}don't\u{0020}let\u{0020}her\u{0020}usual\u{0020}calm\u{0020}demeanor\u{0020}fool\u{0020}you.\u{0020}On\u{0020}the\u{0020}battlefield,\u{0020}Samghrma\u{0020}delivers\u{0020}a\u{0020}performance\u{0020}impossible\u{0020}to\u{0020}ignore.\u{0020}Faced\u{0020}with\u{0020}hordes\u{0020}of\u{0020}outnumbering\u{0020}Sins,\u{0020}she\u{0020}and\u{0020}her\u{0020}partner,\u{0020}Whity,\u{0020}dominate\u{0020}the\u{0020}field\u{0020}with\u{0020}ruthless\u{0020}heavy\u{0020}firepower.\u{0020}\n\n\u{3000}\u{3000}\"Who's\u{0020}Whity?\u{0020}It's\u{0020}right\u{0020}in\u{0020}front\u{0020}of\u{0020}you,\u{0020}Navigator.\"", "0", "0", "0", "0", 12011, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[621102] = {621102, 500, "\n\n\u{3000}\u{3000}Samghrma\u{0020}was\u{0020}born\u{0020}and\u{0020}raised\u{0020}on\u{0020}the\u{0020}ocean.\u{0020}Fourteen\u{0020}years\u{0020}ago,\u{0020}a\u{0020}Kyushu\u{0020}cruise\u{0020}ship\u{0020}was\u{0020}attacked\u{0020}by\u{0020}the\u{0020}Sins\u{0020}and\u{0020}lost\u{0020}contact.\u{0020}By\u{0020}the\u{0020}time\u{0020}the\u{0020}search\u{0020}team\u{0020}found\u{0020}it,\u{0020}only\u{0020}wreckage\u{0020}drifting\u{0020}on\u{0020}the\u{0020}waves\u{0020}remained.\u{0020}Near\u{0020}the\u{0020}debris,\u{0020}they\u{0020}discovered\u{0020}the\u{0020}sole\u{0020}survivor.\u{0020}A\u{0020}little\u{0020}girl.\u{0020}\n\n\u{3000}\u{3000}After\u{0020}some\u{0020}deliberation,\u{0020}the\u{0020}rescue\u{0020}team\u{0020}adopted\u{0020}the\u{0020}orphan\u{0020}and\u{0020}named\u{0020}her\u{0020}Samghrma.\u{0020}\n\n\u{3000}\u{3000}According\u{0020}to\u{0020}Samghrma\u{0020}herself,\u{0020}the\u{0020}trauma\u{0020}of\u{0020}her\u{0020}childhood\u{0020}left\u{0020}her\u{0020}terrified\u{0020}of\u{0020}land.\u{0020}\n\n\u{3000}\u{3000}Every\u{0020}time\u{0020}the\u{0020}rescue\u{0020}ship\u{0020}docked,\u{0020}she\u{0020}would\u{0020}refuse\u{0020}to\u{0020}disembark,\u{0020}locking\u{0020}herself\u{0020}in\u{0020}the\u{0020}cabin\u{0020}until\u{0020}they\u{0020}were\u{0020}back\u{0020}for\u{0020}another\u{0020}sail.\u{0020}This\u{0020}habit\u{0020}only\u{0020}deepened\u{0020}her\u{0020}quiet,\u{0020}reserved\u{0020}nature.\u{0020}\n\n\u{3000}\u{3000}The\u{0020}crew\u{0020}knew\u{0020}she\u{0020}couldn't\u{0020}stay\u{0020}on\u{0020}the\u{0020}ship\u{0020}forever\u{0020}(after\u{0020}all,\u{0020}neither\u{0020}could\u{0020}they).\u{0020}Sooner\u{0020}or\u{0020}later,\u{0020}she'd\u{0020}have\u{0020}to\u{0020}step\u{0020}ashore.\u{0020}They\u{0020}decided\u{0020}to\u{0020}bring\u{0020}her\u{0020}a\u{0020}book\u{0020}each\u{0020}time\u{0020}they\u{0020}resupplied,\u{0020}hoping\u{0020}to\u{0020}soften\u{0020}her\u{0020}fear\u{0020}of\u{0020}landing.\u{0020}Stray\u{0020}Birds\u{0020}she\u{0020}always\u{0020}carries\u{0020}is\u{0020}the\u{0020}very\u{0020}first\u{0020}book\u{0020}they\u{0020}gave\u{0020}her.\u{0020}\n\n\u{3000}\u{3000}The\u{0020}world\u{0020}depicted\u{0020}by\u{0020}those\u{0020}books\u{0020}captivated\u{0020}Samghrma,\u{0020}filling\u{0020}her\u{0020}mind\u{0020}with\u{0020}wonder\u{0020}that\u{0020}slowly\u{0020}replaced\u{0020}her\u{0020}fear.\u{0020}Her\u{0020}resistance\u{0020}to\u{0020}land\u{0020}was\u{0020}no\u{0020}longer\u{0020}as\u{0020}fierce\u{0020}as\u{0020}it\u{0020}once\u{0020}had\u{0020}been.\u{0020}\n\n\u{3000}\u{3000}A\u{0020}decade\u{0020}passed,\u{0020}and\u{0020}Samghrma\u{0020}was\u{0020}no\u{0020}longer\u{0020}the\u{0020}innocent\u{0020}little\u{0020}girl.\u{0020}The\u{0020}rescue\u{0020}team,\u{0020}however,\u{0020}had\u{0020}grown\u{0020}old;\u{0020}it\u{0020}was\u{0020}time\u{0020}for\u{0020}them\u{0020}to\u{0020}disband.\u{0020}(Nobody\u{0020}could\u{0020}expect\u{0020}a\u{0020}crew\u{0020}with\u{0020}core\u{0020}members\u{0020}all\u{0020}over\u{0020}fifty\u{0020}to\u{0020}keep\u{0020}working\u{0020}forever.)\u{0020}Before\u{0020}parting\u{0020}ways,\u{0020}they\u{0020}asked\u{0020}Samghrma\u{0020}what\u{0020}she\u{0020}wanted\u{0020}to\u{0020}do\u{0020}next.\u{0020}\n\n\u{3000}\u{3000}Though\u{0020}every\u{0020}one\u{0020}of\u{0020}them\u{0020}was\u{0020}prepared\u{0020}to\u{0020}take\u{0020}her\u{0020}in\u{0020}after\u{0020}retirement,\u{0020}she\u{0020}denied\u{0020}them\u{0020}the\u{0020}chance.\u{0020}The\u{0020}same\u{0020}girl\u{0020}who\u{0020}had\u{0020}never\u{0020}once\u{0020}set\u{0020}foot\u{0020}on\u{0020}land\u{0020}before,\u{0020}announced\u{0020}that\u{0020}she\u{0020}wanted\u{0020}to\u{0020}travel\u{0020}across\u{0020}Kyushu.\u{0020}\n\n\u{3000}\u{3000}They\u{0020}had\u{0020}always\u{0020}known\u{0020}she\u{0020}couldn't\u{0020}stay\u{0020}at\u{0020}sea\u{0020}forever,\u{0020}but\u{0020}her\u{0020}sudden\u{0020}desire\u{0020}for\u{0020}travel\u{0020}still\u{0020}took\u{0020}them\u{0020}by\u{0020}surprise.\u{0020}Then\u{0020}it\u{0020}dawned\u{0020}on\u{0020}them:\u{0020}their\u{0020}plan\u{0020}had\u{0020}worked.\u{0020}She\u{0020}wanted\u{0020}to\u{0020}see\u{0020}the\u{0020}world\u{0020}she\u{0020}had\u{0020}only\u{0020}read\u{0020}about\u{0020}with\u{0020}her\u{0020}own\u{0020}eyes.\u{0020}\n\n\u{3000}\u{3000}They\u{0020}respected\u{0020}her\u{0020}choice,\u{0020}though\u{0020}on\u{0020}one\u{0020}condition.\u{0020}Until\u{0020}she\u{0020}came\u{0020}of\u{0020}age,\u{0020}a\u{0020}few\u{0020}of\u{0020}the\u{0020}crew\u{0020}members\u{0020}who\u{0020}were\u{0020}still\u{0020}in\u{0020}good\u{0020}shape\u{0020}would\u{0020}act\u{0020}as\u{0020}her\u{0020}guardians,\u{0020}accompanying\u{0020}her\u{0020}on\u{0020}her\u{0020}journey.", "0", "0", "0", "0", 12011, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[621103] = {621103, 1000, "\u{3000}\u{3000}Two\u{0020}years\u{0020}into\u{0020}her\u{0020}travels,\u{0020}Samghrma\u{0020}arrived\u{0020}in\u{0020}Kyushu's\u{0020}capital\u{0020}and\u{0020}took\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}Compatibility\u{0020}Rate\u{0020}Test,\u{0020}where\u{0020}she\u{0020}was\u{0020}identified\u{0020}as\u{0020}a\u{0020}rare\u{0020}candidate\u{0020}with\u{0020}great\u{0020}potential.\u{0020}\n\n\u{3000}\u{3000}During\u{0020}her\u{0020}travels,\u{0020}she\u{0020}had\u{0020}learned\u{0020}about\u{0020}Drivers\u{0020}and\u{0020}the\u{0020}particular\u{0020}test,\u{0020}and\u{0020}the\u{0020}idea\u{0020}intrigued\u{0020}her.\u{0020}The\u{0020}rescue\u{0020}team,\u{0020}who\u{0020}had\u{0020}dedicated\u{0020}their\u{0020}lives\u{0020}to\u{0020}saving\u{0020}others,\u{0020}had\u{0020}influenced\u{0020}her\u{0020}through\u{0020}their\u{0020}actions.\u{0020}Now,\u{0020}she\u{0020}wanted\u{0020}to\u{0020}become\u{0020}a\u{0020}Driver\u{0020}herself\u{0020}who\u{0020}could\u{0020}help\u{0020}more\u{0020}victims\u{0020}of\u{0020}the\u{0020}Sins'\u{0020}devastation.\u{0020}\n\n\u{3000}\u{3000}After\u{0020}consulting\u{0020}both\u{0020}her\u{0020}and\u{0020}her\u{0020}guardians,\u{0020}AEGIS\u{0020}had\u{0020}Samghrma\u{0020}enrolled\u{0020}as\u{0020}a\u{0020}trainee\u{0020}Driver.\u{0020}She\u{0020}completed\u{0020}her\u{0020}training\u{0020}and,\u{0020}upon\u{0020}graduation,\u{0020}was\u{0020}assigned\u{0020}to\u{0020}Whale\u{0020}Fall,\u{0020}the\u{0020}unit\u{0020}formed\u{0020}in\u{0020}the\u{0020}aftermath\u{0020}of\u{0020}the\u{0020}Saar\u{0020}incident.\u{0020}\n\n\u{3000}\u{3000}About\u{0020}Whity\n\n\u{3000}\u{3000}Whity\u{0020}appears\u{0020}to\u{0020}have\u{0020}been\u{0020}the\u{0020}name\u{0020}of\u{0020}a\u{0020}sperm\u{0020}whale\u{0020}once\u{0020}rescued\u{0020}by\u{0020}the\u{0020}team.\u{0020}Samghrma\u{0020}had\u{0020}briefly\u{0020}spent\u{0020}time\u{0020}with\u{0020}it.\u{0020}Back\u{0020}then,\u{0020}with\u{0020}no\u{0020}peers\u{0020}around,\u{0020}she\u{0020}likely\u{0020}considered\u{0020}it\u{0020}her\u{0020}only\u{0020}friend.", "0", "0", "0", "0", 12011, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[621104] = {621104, 2000, "\u{3000}\u{3000}\"The\u{0020}fish\u{0020}in\u{0020}the\u{0020}water\u{0020}is\u{0020}silent,\u{0020}the\u{0020}animal\u{0020}on\u{0020}the\u{0020}earth\u{0020}is\u{0020}noisy,\u{0020}the\u{0020}bird\u{0020}in\u{0020}the\u{0020}air\u{0020}is\u{0020}singing.\u{0020}But\u{0020}Man\u{0020}has\u{0020}in\u{0020}him\u{0020}the\u{0020}silence\u{0020}of\u{0020}the\u{0020}sea,\u{0020}the\u{0020}noise\u{0020}of\u{0020}the\u{0020}earth\u{0020}and\u{0020}the\u{0020}music\u{0020}of\u{0020}the\u{0020}air.\"\u{0020}\n\n\u{3000}\u{3000}A\u{0020}seagull\u{0020}perched\u{0020}on\u{0020}the\u{0020}girl's\u{0020}fingertip\u{0020}as\u{0020}Samghrma's\u{0020}amber\u{0020}eyes\u{0020}reflected\u{0020}the\u{0020}boundless\u{0020}blue\u{0020}sea.\n\n\u{3000}\u{3000}The\u{0020}only\u{0020}world\u{0020}she\u{0020}had\u{0020}ever\u{0020}known.\u{0020}\n\n\u{3000}\u{3000}\"Navigator...\u{0020}I\u{0020}used\u{0020}to\u{0020}fear\u{0020}the\u{0020}land.\"\u{0020}\n\n\u{3000}\u{3000}The\u{0020}seagull\u{0020}cried\u{0020}out\u{0020}and\u{0020}flew\u{0020}from\u{0020}her\u{0020}hand,\u{0020}realizing\u{0020}this\u{0020}motionless\u{0020}giant\u{0020}was,\u{0020}in\u{0020}fact,\u{0020}a\u{0020}living\u{0020}being.\u{0020}\n\n\u{3000}\u{3000}\"I\u{0020}had\u{0020}never\u{0020}seen\u{0020}the\u{0020}world\u{0020}beyond\u{0020}the\u{0020}waves.\u{0020}I\u{0020}couldn't\u{0020}imagine\u{0020}living\u{0020}anywhere\u{0020}but\u{0020}on\u{0020}a\u{0020}ship.\"\u{0020}\n\n\u{3000}\u{3000}\"But\u{0020}I\u{0020}knew.\u{0020}You\u{0020}can't\u{0020}stay\u{0020}still.\"\u{0020}\n\n\u{3000}\u{3000}\"Time\u{0020}moves\u{0020}forward.\u{0020}So...\u{0020}I\u{0020}wanted\u{0020}to\u{0020}move\u{0020}forward\u{0020}too.\"\u{0020}\n\n\u{3000}\u{3000}\"I\u{0020}wanted\u{0020}to\u{0020}learn\u{0020}how\u{0020}a\u{0020}human\u{0020}lives.\"\n\n\u{3000}\u{3000}\"That's\u{0020}why,\u{0020}I\u{0020}left\u{0020}the\u{0020}sea.\"", "0", "0", "0", "0", 12011, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[621200] = {621200, 0, "[Name]\u{0020}Julia\u{0020}Fox\n[B-Day]\u{0020}Aug\u{0020}7\n[Compatability\u{0020}Rate]\u{0020}89％\n[Height]\u{0020}32m\n[Squad]\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Painful\u{0020}wailing\u{0020}sounds", "0", "0", "0", "0", 12012, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}茱莉亚·福克斯\n[B-Day]\u{1000}8月7日\n[幻化核心适格率]\u{1000}89％\n[Height]\u{1000}32m\n[部队]\u{1000}飓风突击队\n[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}施虐"},
[621201] = {621201, 100, "\u{0020}\u{0020}Julia\u{0020}Fox,\u{0020}a\u{0020}noble\u{0020}young\u{0020}lady\u{0020}who\u{0020}is\u{0020}willing\u{0020}to\u{0020}spend\u{0020}lavishly\u{0020}for\u{0020}her\u{0020}preferences,\u{0020}and\u{0020}a\u{0020}villain\u{0020}who\u{0020}will\u{0020}not\u{0020}hesitate\u{0020}to\u{0020}boss\u{0020}people\u{0020}around\u{0020}to\u{0020}achieve\u{0020}her\u{0020}goals\u{0020}-\u{0020}these\u{0020}are\u{0020}the\u{0020}labels\u{0020}her\u{0020}enemies\u{0020}have\u{0020}attached\u{0020}to\u{0020}her\u{0020}based\u{0020}on\u{0020}their\u{0020}own\u{0020}judgment.\n\nIn\u{0020}fact,\u{0020}for\u{0020}those\u{0020}who\u{0020}hate\u{0020}her,\u{0020}Julia\u{0020}is\u{0020}indeed\u{0020}such\u{0020}a\u{0020}person.\u{0020}Julia\u{0020}has\u{0020}always\u{0020}been\u{0020}ruthless\u{0020}towards\u{0020}her\u{0020}enemies\u{0020}-\u{0020}those\u{0020}nobles\u{0020}who\u{0020}like\u{0020}to\u{0020}bully\u{0020}civilians\u{0020}with\u{0020}their\u{0020}superior\u{0020}status.\u{0020}She\u{0020}would\u{0020}use\u{0020}words\u{0020}sharper\u{0020}than\u{0020}a\u{0020}steel\u{0020}sword\u{0020}to\u{0020}destroy\u{0020}the\u{0020}dignity\u{0020}of\u{0020}the\u{0020}enemies,\u{0020}make\u{0020}the\u{0020}enemies'\u{0020}struggles\u{0020}futile\u{0020}with\u{0020}money\u{0020}and\u{0020}power,\u{0020}make\u{0020}the\u{0020}enemies\u{0020}feel\u{0020}a\u{0020}deep\u{0020}sense\u{0020}of\u{0020}frustration.\u{0020}Eventually,\u{0020}most\u{0020}of\u{0020}those\u{0020}who\u{0020}oppose\u{0020}her\u{0020}do\u{0020}not\u{0020}have\u{0020}a\u{0020}good\u{0020}ending.\u{0020}It\u{0020}can\u{0020}be\u{0020}said\u{0020}that\u{0020}it\u{0020}is\u{0020}truly\u{0020}learning\u{0020}from\u{0020}the\u{0020}foreigners'\u{0020}advanced\u{0020}skills\u{0020}to\u{0020}resist\u{0020}them.\n\nHowever,\u{0020}Julia's\u{0020}sadistic\u{0020}nature\u{0020}is\u{0020}not\u{0020}only\u{0020}shown\u{0020}to\u{0020}her\u{0020}enemies.\u{0020}Even\u{0020}to\u{0020}the\u{0020}civilians\u{0020}who\u{0020}hold\u{0020}her\u{0020}in\u{0020}awe\u{0020}or\u{0020}the\u{0020}comrades-in-arms\u{0020}who\u{0020}are\u{0020}with\u{0020}her\u{0020}day\u{0020}and\u{0020}night,\u{0020}she\u{0020}will\u{0020}not\u{0020}change\u{0020}her\u{0020}speech\u{0020}habits.\u{0020}The\u{0020}difference\u{0020}is\u{0020}that\u{0020}for\u{0020}these\u{0020}people,\u{0020}Julia\u{0020}will\u{0020}only\u{0020}remain\u{0020}at\u{0020}the\u{0020}verbal\u{0020}stage\u{0020}and\u{0020}rarely\u{0020}takes\u{0020}actual\u{0020}actions.\n\n…Nevertheless,\u{0020}most\u{0020}drivers\u{0020}would\u{0020}keep\u{0020}their\u{0020}distance\u{0020}from\u{0020}her.\u{0020}Perhaps\u{0020}only\u{0020}Celine\u{0020}and\u{0020}Jenny\u{0020}from\u{0020}the\u{0020}same\u{0020}team\u{0020}could\u{0020}accept\u{0020}her.\u{0020}However,\u{0020}she\u{0020}was\u{0020}unexpectedly\u{0020}popular\u{0020}among\u{0020}civilians...\u{0020}Maybe\u{0020}some\u{0020}people\u{0020}really\u{0020}like\u{0020}this\u{0020}kind?\u{0020}", "0", "0", "0", "0", 12012, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}茱莉亚·福克斯，一个愿意为自己喜好一掷千金的贵族大小姐，一个为了达成自己目的，便会毫不犹豫使唤别人的恶角——这是她的敌人仅凭自己的判断给她贴上的标签。\n\u{1000}\u{1000}事实上，对于讨厌她的人来说，茱莉亚的确是这样一个人。茱莉亚对于自己的敌人——那些喜欢以自己高高在上的身份去欺压平民的贵族——向来是不留情面的。她会用比断钢剑还锋锐的言词去摧毁敌人的尊严，用金钱与权力让敌人的挣扎化为徒劳，让敌人感受到深深的挫败感，最终，与她作对的人大多不会有什么好下场，可谓是真正的师夷长技以制夷。\n\u{1000}\u{1000}不过，茱莉亚的嗜虐性并不只对她的敌人表露，即便是对她敬畏有加的平民，亦或是朝夕相处的战友，她也不会改变自己的言辞习惯。不同的是，对于这些人，茱莉亚仅会停留在言语阶段，鲜有做出实际行动的时候。\n\u{1000}\u{1000}…尽管如此，大多数驾驶员也会对她敬而远之，也就只有同队的栖琳与燕妮才能接受她了吧。不过，她在平民中意外得有人气…也许一些人的确喜欢这类？\u{1000}"},
[621202] = {621202, 500, "\u{0020}\u{0020}Even\u{0020}if\u{0020}any\u{0020}means\u{0020}known\u{0020}to\u{0020}humans\u{0020}were\u{0020}used\u{0020}to\u{0020}investigate\u{0020}Julia\u{0020}Fox's\u{0020}background,\u{0020}it\u{0020}would\u{0020}only\u{0020}end\u{0020}in\u{0020}vain.\n\nTherefore,\u{0020}the\u{0020}family\u{0020}behind\u{0020}Julia\u{0020}has\u{0020}always\u{0020}been\u{0020}a\u{0020}mystery,\u{0020}even\u{0020}becoming\u{0020}one\u{0020}of\u{0020}the\u{0020}\"Seven\u{0020}Incredibles\"\u{0020}(Jenny\u{0020}Rose's\u{0020}words)\u{0020}rumored\u{0020}to\u{0020}be\u{0020}in\u{0020}the\u{0020}upper\u{0020}echelons\u{0020}of\u{0020}the\u{0020}Danube\u{0020}area.\n\nJulia's\u{0020}family\u{0020}is\u{0020}a\u{0020}mystery,\u{0020}but\u{0020}her\u{0020}own\u{0020}experience\u{0020}in\u{0020}the\u{0020}public\u{0020}eye\u{0020}is\u{0020}as\u{0020}well-known\u{0020}as\u{0020}an\u{0020}open\u{0020}book.\u{0020}When\u{0020}she\u{0020}was\u{0020}young,\u{0020}she\u{0020}once\u{0020}turned\u{0020}a\u{0020}noble\u{0020}lady\u{0020}who\u{0020}took\u{0020}pleasure\u{0020}in\u{0020}bullying\u{0020}civilians\u{0020}and\u{0020}scolded\u{0020}them\u{0020}with\u{0020}whipping\u{0020}and\u{0020}scolding\u{0020}into\u{0020}a\u{0020}masochist\u{0020}seeking\u{0020}others'\u{0020}scolding.\u{0020}When\u{0020}she\u{0020}entered\u{0020}Azure\u{0020}Academy,\u{0020}she\u{0020}cultivated\u{0020}her\u{0020}die-hard\u{0020}fans\u{0020}like\u{0020}a\u{0020}wildfire\u{0020}and\u{0020}established\u{0020}a\u{0020}student\u{0020}organization\u{0020}centered\u{0020}on\u{0020}herself\u{0020}with\u{0020}absolute\u{0020}power\u{0020}in\u{0020}the\u{0020}academy.\n\nShe\u{0020}has\u{0020}also\u{0020}made\u{0020}many\u{0020}enemies\u{0020}because\u{0020}of\u{0020}her\u{0020}way\u{0020}of\u{0020}doing\u{0020}things\u{0020}as\u{0020}she\u{0020}pleases.\u{0020}During\u{0020}her\u{0020}period\u{0020}from\u{0020}childhood\u{0020}to\u{0020}being\u{0020}a\u{0020}driver,\u{0020}her\u{0020}enemies\u{0020}have\u{0020}been\u{0020}constantly\u{0020}increasing.\n\nJulia\u{0020}seems\u{0020}to\u{0020}be\u{0020}well\u{0020}aware\u{0020}of\u{0020}this\u{0020}situation\u{0020}and\u{0020}takes\u{0020}it\u{0020}for\u{0020}granted.\u{0020}In\u{0020}fact,\u{0020}whenever\u{0020}those\u{0020}who\u{0020}are\u{0020}hostile\u{0020}to\u{0020}her\u{0020}want\u{0020}to\u{0020}take\u{0020}action\u{0020}against\u{0020}her,\u{0020}the\u{0020}result\u{0020}always\u{0020}turns\u{0020}into\u{0020}an\u{0020}anticlimactic\u{0020}farce.\u{0020}Julia\u{0020}is\u{0020}in\u{0020}society\u{0020}like\u{0020}a\u{0020}wild\u{0020}beast\u{0020}without\u{0020}natural\u{0020}enemies\u{0020}releasing\u{0020}her\u{0020}nature\u{0020}in\u{0020}the\u{0020}jungle.\n\nJulia's\u{0020}motivation\u{0020}for\u{0020}becoming\u{0020}a\u{0020}driver\u{0020}is\u{0020}as\u{0020}much\u{0020}a\u{0020}mystery\u{0020}as\u{0020}her\u{0020}background.\u{0020}However,\u{0020}those\u{0020}who\u{0020}know\u{0020}her\u{0020}personality\u{0020}and\u{0020}are\u{0020}her\u{0020}enemies\u{0020}are\u{0020}more\u{0020}willing\u{0020}to\u{0020}believe\u{0020}that\u{0020}this\u{0020}young\u{0020}lady\u{0020}is\u{0020}just\u{0020}tired\u{0020}of\u{0020}the\u{0020}ordinary\u{0020}life\u{0020}and\u{0020}wants\u{0020}to\u{0020}try\u{0020}something\u{0020}different.\u{0020}This\u{0020}view\u{0020}has\u{0020}also\u{0020}become\u{0020}Julia's\u{0020}best\u{0020}shield.\u{0020}Whenever\u{0020}someone\u{0020}questions\u{0020}her\u{0020}motivation\u{0020}for\u{0020}being\u{0020}a\u{0020}driver,\u{0020}she\u{0020}would\u{0020}smile\u{0020}and\u{0020}say,\u{0020}\"Don't\u{0020}you\u{0020}think\u{0020}that\u{0020}being\u{0020}a\u{0020}driver\u{0020}is\u{0020}more\u{0020}interesting\u{0020}than\u{0020}an\u{0020}ordinary\u{0020}person?\"\u{0020}-\u{0020}As\u{0020}for\u{0020}which\u{0020}aspect\u{0020}is\u{0020}interesting\u{0020}compared\u{0020}to\u{0020}ordinary\u{0020}people,\u{0020}whether\u{0020}as\u{0020}an\u{0020}object\u{0020}or\u{0020}a\u{0020}subject,\u{0020}it\u{0020}goes\u{0020}without\u{0020}saying.", "0", "0", "0", "0", 12012, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}即便用上任何人类已知的手段去调查茱莉亚·福克斯的身世背景，最后也只会像九州古代典籍上记载的《桃花源》那样无疾而终。\n\u{1000}\u{1000}因此，茱莉亚背后的家族一直是一个谜团，甚至成为了多瑙地区上层传闻中的\"七大不可思议之一\"（燕妮·罗斯语）。\n\u{1000}\u{1000}茱莉亚的家族是一个谜，但她本人出现在公众视野下的经历却像公开的书本一样被人所知。在她小的时候，就曾经将一名以欺凌平民为乐的贵族用鞭打与责骂的贵族小姐培养成了寻求他人责骂的受虐狂。当她进入苍穹学院时，便以野火燎原之势培养出了自己的死忠粉丝，在学院中组建了以自己为中心，拥有绝对权力的学生组织。\n\u{1000}\u{1000}她也因为自己我行我素的作风而在树敌不少，在她从孩童到驾驶员时期，她的敌人在不停地增加。\n\u{1000}\u{1000}茱莉亚对这一状况似乎也了如指掌，并且理所当然地未放在心上。事实上，那些与她敌对的人每当想对她动手时，其结果都会演变成虎头蛇尾的闹剧。茱莉亚处于社会中，就像一只没有天敌的野兽在丛林中释放自己的天性。\n\u{1000}\u{1000}茱莉亚成为驾驶员的动机与她的身世一样是个谜团，但了解她个性的，与她为敌的人更愿意相信这位大小姐只是玩腻了寻常人的生活，想要尝试与众不同的事物而已。这一看法也成了茱莉亚最好用的盾牌，每当有人质问她当驾驶员的动机时，她都会微笑着说出：\"你不觉得比起一般人，驾驶员要更加有趣吗？\"——至于对比普通人，到底是哪方面有趣，是作为宾语还是主语的有趣，就不言而喻了。"},
[621203] = {621203, 1000, "\u{0020}\u{0020}Julia\u{0020}set\u{0020}her\u{0020}sights\u{0020}on\u{0020}Celine\u{0020}Welt,\u{0020}who\u{0020}has\u{0020}excellent\u{0020}warrior\u{0020}qualifications.\n\nTwo\u{0020}young\u{0020}girls\u{0020}reached\u{0020}a\u{0020}consensus\u{0020}on\u{0020}their\u{0020}hobbies,\u{0020}hit\u{0020}it\u{0020}off\u{0020}immediately,\u{0020}and\u{0020}established\u{0020}the\u{0020}\"Hurricane\u{0020}Shock\u{0020}Squad\".\n\nAfter\u{0020}that,\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\u{0020}established\u{0020}became\u{0020}Julia's\u{0020}backyard,\u{0020}where\u{0020}she\u{0020}could\u{0020}freely\u{0020}release\u{0020}her\u{0020}nature\u{0020}without\u{0020}being\u{0020}blamed\u{0020}by\u{0020}anyone.\u{0020}Her\u{0020}enemies\u{0020}once\u{0020}tried\u{0020}to\u{0020}curb\u{0020}her\u{0020}immoral\u{0020}behavior\u{0020}through\u{0020}military\u{0020}meetings,\u{0020}but\u{0020}measures\u{0020}against\u{0020}her\u{0020}were\u{0020}never\u{0020}implemented.\n\nAlthough\u{0020}the\u{0020}relationship\u{0020}between\u{0020}Julia\u{0020}and\u{0020}Celine\u{0020}is\u{0020}very\u{0020}delicate,\u{0020}the\u{0020}Hurricane\u{0020}Shock\u{0020}Squad\u{0020}cannot\u{0020}be\u{0020}considered\u{0020}an\u{0020}inhumane\u{0020}team.\u{0020}Her\u{0020}team\u{0020}is\u{0020}the\u{0020}only\u{0020}one\u{0020}in\u{0020}Danube\u{0020}that\u{0020}writes\u{0020}\"Never\u{0020}leave\u{0020}any\u{0020}companion\u{0020}behind\"\u{0020}in\u{0020}the\u{0020}team\u{0020}regulations.\u{0020}This\u{0020}is\u{0020}the\u{0020}best\u{0020}evidence\u{0020}that\u{0020}this\u{0020}wayward\u{0020}young\u{0020}lady\u{0020}values\u{0020}the\u{0020}two\u{0020}companions\u{0020}-\u{0020}although\u{0020}she\u{0020}would\u{0020}never\u{0020}admit\u{0020}it.", "0", "0", "0", "0", 12012, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}茱莉亚盯上了有着出色战士资质的栖琳·瓦尔特。\n\u{1000}\u{1000}两名少女在各自的爱好上达成了共识，一拍即合，建立了\"飓风突击队\"。\n\u{1000}\u{1000}此后，由她们成立的飓风突击队成了茱莉亚的后花园，她在这里可以任意地释放自己的天性而不用被任何人责备。她的敌人曾经试图通过军事会议来遏止她有伤风化的行为，但始终未能落实针对她的措施。\n\u{1000}\u{1000}尽管茱莉亚与栖琳的关系十分微妙，但并不能因此认为飓风突击队是一个没有人情味的小队。她的队伍是多瑙唯一一个将\"绝对不丢下任何一个同伴\"写在小队条律的队伍。这是这位肆意妄为的大小姐重视两位同伴的最好证据——虽说她是绝对不会承认的。"},
[621204] = {621204, 2000, "\u{0020}\"Are\u{0020}you\u{0020}very\u{0020}tired?\u{0020}Are\u{0020}you\u{0020}in\u{0020}pain?\u{0020}Are\u{0020}you\u{0020}desperate?\u{0020}But\u{0020}I\u{0020}don't\u{0020}allow\u{0020}you\u{0020}to\u{0020}die.\"\n\nDusk\u{0020}is\u{0020}approaching.\u{0020}The\u{0020}setting\u{0020}sun\u{0020}is\u{0020}shining\u{0020}on\u{0020}her,\u{0020}and\u{0020}her\u{0020}shadow\u{0020}is\u{0020}covering\u{0020}this\u{0020}land.\n\nThis\u{0020}interception\u{0020}battle\u{0020}after\u{0020}a\u{0020}600-kilometer\u{0020}rescue\u{0020}has\u{0020}lasted\u{0020}for\u{0020}three\u{0020}hours.\n\nThere\u{0020}is\u{0020}no\u{0020}dawn\u{0020}of\u{0020}victory\u{0020}in\u{0020}sight,\u{0020}no\u{0020}knowledge\u{0020}of\u{0020}the\u{0020}conditions\u{0020}for\u{0020}victory,\u{0020}and\u{0020}the\u{0020}subsequent\u{0020}support\u{0020}is\u{0020}illusory.\n\nBut\u{0020}she\u{0020}still\u{0020}ordered\u{0020}her\u{0020}teammates\u{0020}not\u{0020}to\u{0020}give\u{0020}up.\n\n\"Feel\u{0020}this\u{0020}pain\u{0020}well\u{0020}and\u{0020}enjoy\u{0020}this\u{0020}happiness.\u{0020}If\u{0020}you\u{0020}die,\u{0020}there\u{0020}will\u{0020}be\u{0020}nothing\u{0020}left.\"\n\nShe\u{0020}trampled\u{0020}on\u{0020}Sin's\u{0020}corpse\u{0020}and\u{0020}shouted\u{0020}loudly.", "0", "0", "0", "0", 12012, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"很累吧？很痛苦？很绝望？但是我不允许你们死。\"\n\u{1000}\u{1000}黄昏将至，夕阳映在她身上，而她的影子则笼罩着这片土地。\n\u{1000}\u{1000}这场驰援六百公里后的阻截战已经持续了三小时。\n\u{1000}\u{1000}看不到胜利的曙光，不知道取胜的条件，后续的支援虚无缥缈。\n\u{1000}\u{1000}但她依然命令队友不能放弃。\n\u{1000}\u{1000}\"好好感受这份痛楚，享受这份快乐吧，死了的话，就什么都没了。\"\n\u{1000}\u{1000}她踩踏在原罪尸首上，大声高喊着。"},
[621300] = {621300, 0, "[Name]\u{0020}Karen\n[B-Day]\u{0020}March\u{0020}13\n[Compatability\u{0020}Rate]\u{0020}86％\n[Height]\u{0020}36m\n[Squad]\u{0020}Fledgling\u{0020}Eagle\n[Affiliation]\u{0020}Sahara\n[Interest]\u{0020}Exotic\u{0020}cultures,\u{0020}White\u{0020}Water-Lily", "0", "0", "0", "0", 12013, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}卡莲\n[B-Day]\u{1000}3月1日\n[幻化核心适格率]\u{1000}86％\n[Height]\u{1000}36m\n[部队]\u{1000}雏鹰\n[隶属]\u{1000}萨哈拉支部\n[Interest]\u{1000}异乡文化\u{1000}白睡莲"},
[621301] = {621301, 100, "\u{0020}\u{0020}Not\u{0020}being\u{0020}impressive,\u{0020}Karen\u{0020}is\u{0020}a\u{0020}white-haired\u{0020}girl\u{0020}and\u{0020}she\u{0020}is\u{0020}mildly\u{0020}facial\u{0020}paralyzed.\u{0020}From\u{0020}her\u{0020}daily\u{0020}dressed\u{0020}school\u{0020}uniform\u{0020}we\u{0020}can\u{0020}conclude\u{0020}that,\u{0020}just\u{0020}like\u{0020}other\u{0020}members\u{0020}of\u{0020}\"Fledgling\u{0020}Eagle\",\u{0020}she's\u{0020}not\u{0020}a\u{0020}real\u{0020}driver,\u{0020}but\u{0020}a\u{0020}student\u{0020}from\u{0020}Sahara's\u{0020}military\u{0020}academy.\u{0020}She\u{0020}joins\u{0020}battles\u{0020}just\u{0020}for\u{0020}conducting\u{0020}her\u{0020}research\u{0020}in\u{0020}a\u{0020}better\u{0020}approach.\n\nAlthough\u{0020}she's\u{0020}not\u{0020}expressive,\u{0020}she\u{0020}is\u{0020}not\u{0020}stolid.\u{0020}According\u{0020}to\u{0020}drivers\u{0020}who\u{0020}have\u{0020}fought\u{0020}together\u{0020}with\u{0020}her,\u{0020}she\u{0020}often\u{0020}started\u{0020}chatting\u{0020}actively\u{0020}with\u{0020}her\u{0020}teammates,\u{0020}and\u{0020}she\u{0020}could\u{0020}learn\u{0020}their\u{0020}personalities\u{0020}and\u{0020}tactical\u{0020}habits\u{0020}in\u{0020}a\u{0020}moment.\u{0020}She\u{0020}can\u{0020}do\u{0020}this\u{0020}even\u{0020}better\u{0020}than\u{0020}most\u{0020}Navigators.\n\nOther\u{0020}than\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}in\u{0020}the\u{0020}rest\u{0020}areas\u{0020}of\u{0020}the\u{0020}ark\u{0020}we\u{0020}may\u{0020}also\u{0020}see\u{0020}Karen,\u{0020}with\u{0020}her\u{0020}notebook,\u{0020}finding\u{0020}her\u{0020}interviewee.\u{0020}If\u{0020}Karen\u{0020}gets\u{0020}eye-contact\u{0020}with\u{0020}you,\u{0020}she\u{0020}will\u{0020}\"Strike\"\u{0020}you\u{0020}again.\u{0020}She\u{0020}will\u{0020}ask\u{0020}you\u{0020}everything\u{0020}about\u{0020}your\u{0020}daily\u{0020}life,\u{0020}and\u{0020}write\u{0020}down\u{0020}your\u{0020}answer\u{0020}carefully\u{0020}in\u{0020}her\u{0020}notebook.\u{0020}When\u{0020}she's\u{0020}finished,\u{0020}she\u{0020}gives\u{0020}you\u{0020}a\u{0020}white\u{0020}paper\u{0020}flower\u{0020}as\u{0020}a\u{0020}compensation\u{0020}for\u{0020}your\u{0020}time.\n\n\"This\u{0020}is\u{0020}the\u{0020}white\u{0020}water-lily\u{0020}from\u{0020}Sahara,\u{0020}it\u{0020}represents\u{0020}my\u{0020}gratitude,\u{0020}so\u{0020}please\u{0020}keep\u{0020}it.\"", "0", "0", "0", "0", 12013, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}不苟言笑，略微有些面瘫脸的白发少女。从她平日穿着的学院制服便不难看出，和雏鹰部队中的其他人一样，实际上她并不是一名正规的驾驶员，而是一名来自萨哈拉地区的军官学院在读生，而她亲自投身于战场的理由则是为了能够更好地完成自己所研究的课题。\n\u{1000}\u{1000}虽说长了一张冰山脸，不过实际上她的性格倒没有多高冷。根据曾与她一同作战的驾驶员所说，卡莲总是会主动与同伴搭话，并很快摸清每一个驾驶员的性格与战斗习惯，这一点甚至比大部分领航都做得要出色。\n\u{1000}\u{1000}除了在战场上，在方舟的休息区内也能撞上拿着笔记本正在寻找采访对象的卡莲。如果和她对上视线，那么她便会再次\"出击\"。她会从衣食住行各个方面向你展开提问，并将你的回答认真记录在随身携带的笔记本上，谈话结束时她会送给你一朵白色的纸花作为占用了你时间的报酬。\n\u{1000}\u{1000}\"这是萨哈拉特产的白睡莲，算是我的一点点心意，还请您笑纳。\""},
[621302] = {621302, 500, "\u{0020}\u{0020}Karen\u{0020}was\u{0020}born\u{0020}in\u{0020}Katya,\u{0020}she\u{0020}has\u{0020}other\u{0020}siblings\u{0020}in\u{0020}her\u{0020}family.\u{0020}Just\u{0020}like\u{0020}most\u{0020}kids\u{0020}in\u{0020}Katya,\u{0020}she\u{0020}grew\u{0020}up\u{0020}while\u{0020}learning\u{0020}the\u{0020}stories\u{0020}of\u{0020}heroes,\u{0020}who\u{0020}paid\u{0020}their\u{0020}lives\u{0020}for\u{0020}their\u{0020}ideals.\n\nLittle\u{0020}Karen,\u{0020}like\u{0020}other\u{0020}kids,\u{0020}was\u{0020}so\u{0020}impressed\u{0020}by\u{0020}these\u{0020}stories,\u{0020}that\u{0020}made\u{0020}her\u{0020}want\u{0020}to\u{0020}be\u{0020}the\u{0020}savior\u{0020}of\u{0020}the\u{0020}world.\u{0020}On\u{0020}the\u{0020}other\u{0020}hand,\u{0020}Karen\u{0020}had\u{0020}her\u{0020}selfish\u{0020}will:\u{0020}she\u{0020}wanted\u{0020}to\u{0020}save\u{0020}those\u{0020}heroes,\u{0020}or\u{0020}rather\u{0020}say,\u{0020}she\u{0020}didn't\u{0020}want\u{0020}them\u{0020}to\u{0020}die.\n\nKaren\u{0020}talked\u{0020}about\u{0020}her\u{0020}opinions\u{0020}with\u{0020}her\u{0020}family,\u{0020}unfortunately,\u{0020}they\u{0020}didn't\u{0020}agree\u{0020}with\u{0020}her.\u{0020}Most\u{0020}Katyans\u{0020}think\u{0020}it's\u{0020}an\u{0020}ultimate\u{0020}honor\u{0020}to\u{0020}die\u{0020}for\u{0020}one's\u{0020}ideals.\u{0020}However,\u{0020}to\u{0020}smoothe\u{0020}Karen's\u{0020}mood,\u{0020}her\u{0020}family\u{0020}told\u{0020}her:\n\nAlthough\u{0020}those\u{0020}heroes\u{0020}are\u{0020}dead,\u{0020}their\u{0020}stories\u{0020}will\u{0020}be\u{0020}passed\u{0020}down\u{0020}to\u{0020}our\u{0020}descendants.\u{0020}By\u{0020}the\u{0020}current\u{0020}state\u{0020}of\u{0020}war,\u{0020}it\u{0020}will\u{0020}surely\u{0020}end\u{0020}in\u{0020}the\u{0020}future…\n\n\n\nHowever,\u{0020}the\u{0020}reality\u{0020}wasn't\u{0020}close\u{0020}to\u{0020}their\u{0020}ideals,\u{0020}because\u{0020}humans\u{0020}never\u{0020}were\u{0020}able\u{0020}to\u{0020}kill\u{0020}Nevaeh,\u{0020}and\u{0020}the\u{0020}war\u{0020}is\u{0020}not\u{0020}ending\u{0020}and\u{0020}people\u{0020}keep\u{0020}dying\u{0020}from\u{0020}it.\u{0020}Later,\u{0020}Karen's\u{0020}older\u{0020}sisters\u{0020}took\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}and\u{0020}became\u{0020}drivers,\u{0020}and\u{0020}went\u{0020}to\u{0020}battlefields\u{0020}with\u{0020}those\u{0020}heroic\u{0020}ideals.\u{0020}While\u{0020}Karen,\u{0020}as\u{0020}she\u{0020}grew\u{0020}up,\u{0020}she\u{0020}questioned\u{0020}what\u{0020}exactly\u{0020}she\u{0020}wanted\u{0020}to\u{0020}save.\n\nBut\u{0020}soon,\u{0020}when\u{0020}she\u{0020}encountered\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Great\u{0020}Sin\u{0020}\"Greed\",\u{0020}when\u{0020}she\u{0020}saw\u{0020}countless\u{0020}drivers,\u{0020}soldiers,\u{0020}even\u{0020}her\u{0020}family\u{0020}members,\u{0020}devoted\u{0020}their\u{0020}lives\u{0020}to\u{0020}defend\u{0020}Katya,\u{0020}she\u{0020}finally\u{0020}made\u{0020}her\u{0020}decision:\u{0020}she\u{0020}wants\u{0020}not\u{0020}only\u{0020}to\u{0020}save\u{0020}the\u{0020}world,\u{0020}but\u{0020}to\u{0020}keep\u{0020}heroes\u{0020}alive.\n\nTo\u{0020}reach\u{0020}her\u{0020}goals,\u{0020}being\u{0020}a\u{0020}driver\u{0020}is\u{0020}simply\u{0020}not\u{0020}enough.\u{0020}Because\u{0020}of\u{0020}that,\u{0020}she\u{0020}didn't\u{0020}take\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test,\u{0020}but\u{0020}attended\u{0020}the\u{0020}officer's\u{0020}recruiting\u{0020}exam\u{0020}hosted\u{0020}by\u{0020}Sahara.\u{0020}Although\u{0020}this\u{0020}was\u{0020}considered\u{0020}as\u{0020}timid\u{0020}by\u{0020}Katyans,\u{0020}she\u{0020}didn't\u{0020}have\u{0020}any\u{0020}qualms.\n\nAfter\u{0020}lots\u{0020}of\u{0020}tests,\u{0020}finally,\u{0020}she\u{0020}left\u{0020}that\u{0020}land\u{0020}covered\u{0020}by\u{0020}ice\u{0020}and\u{0020}snow.\u{0020}She\u{0020}traveled\u{0020}westward,\u{0020}went\u{0020}to\u{0020}another\u{0020}shore\u{0020}of\u{0020}the\u{0020}ocean,\u{0020}the\u{0020}warm\u{0020}island\u{0020}named\u{0020}Sahara.\u{0020}She\u{0020}registered\u{0020}as\u{0020}a\u{0020}\"reserve\u{0020}commander\u{0020}of\u{0020}the\u{0020}strategic\u{0020}department\".\u{0020}From\u{0020}here,\u{0020}Karen's\u{0020}fate\u{0020}changed\u{0020}completely,\u{0020}she\u{0020}has\u{0020}chosen\u{0020}a\u{0020}pathway\u{0020}different\u{0020}from\u{0020}her\u{0020}late\u{0020}relatives.", "0", "0", "0", "0", 12013, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}卡莲出生于卡佳，家里除了自己外，还有着其他的兄弟姐妹，和大部分在卡佳出生的孩子一样，卡莲从小便听着英雄们为了达成理想而献出生命的故事长大。\n\u{1000}\u{1000}一方面就如同其他孩子那样，年幼的卡莲被这些英雄的故事所激励，树立起了要拯救世界的远大理想，但另一方面，卡莲也有了自己的私愿，她希望能够拯救这些英雄，或者说她并不希望这些英雄死去。\n\u{1000}\u{1000}卡莲曾经向家人表述了自己的想法，可惜家人并不能认同卡莲的想法。大部分卡佳人认为为了理想而牺牲是无上光荣的。不过，家里人为了照顾卡莲的情绪于是便安慰她说这些英雄虽然已经死去，但他们的故事依旧会传承下去并激励着下一代不断努力，而按照现在的战事，在不久的将来战争终将结束……\n\u{1000}\u{1000}但是，现实并没有那么美好，因为人类始终无法找出可以消灭始祖原罪逆爱的方法，导致战争并没有如同预想般那样早早结束，依旧有人不断死去。不久之后，卡莲的姐姐们也参加了适格测试成为了一名驾驶员，怀揣着从英雄们那继承下来的救世理想踏上了战场。而渐渐成熟起来的卡莲则再次陷入了思考，自己所想要拯救的到底是什么。\n\u{1000}\u{1000}不过很快，在亲身经历了高等原罪贪婪入侵，见证了包括自己亲人在内的无数驾驶员、士兵为了保卫卡佳而献出自己的生命之后，卡莲最终下定了决心，她不光光要拯救世界，她还要让英雄们能够活下来。\n\u{1000}\u{1000}而想要达成这两个目标，光是成为驾驶员或者领航是远远不够的，所以，她才没有选择去参加适格测试，而是报名参加了萨哈拉支部举办的军官测试，即便这样的行为在卡佳会被误认为软弱的象征，她也丝毫没有犹豫。\n\u{1000}\u{1000}在经历了层层选拔与测试之后，最终，她离开了那个被冰雪所覆盖的国度，一路向西，来到了与主大陆隔海相望的温暖岛屿都市——萨哈拉，并正式注册成为了萨哈拉支部下的一名\"战略部负责人候补生\"。自此，卡莲的命运发生了改变，她选择了和已故的亲人们完全不同的道路。"},
[621303] = {621303, 1000, "\u{0020}\u{0020}In\u{0020}Sahara's\u{0020}academy,\u{0020}other\u{0020}than\u{0020}learning\u{0020}basic\u{0020}stratagem\u{0020}theories\u{0020}and\u{0020}her\u{0020}elective:\u{0020}AVG\u{0020}development,\u{0020}she\u{0020}was\u{0020}also\u{0020}interested\u{0020}in\u{0020}local\u{0020}culture.\n\nWhen\u{0020}she\u{0020}learnt\u{0020}that\u{0020}white\u{0020}water-lily\u{0020}means\u{0020}\"invincible\"\u{0020}in\u{0020}local\u{0020}culture,\u{0020}she\u{0020}picked\u{0020}a\u{0020}lot\u{0020}of\u{0020}white\u{0020}water-lilies\u{0020}before\u{0020}she\u{0020}came\u{0020}to\u{0020}Danube,\u{0020}and\u{0020}she\u{0020}packed\u{0020}them\u{0020}up\u{0020}as\u{0020}gifts\u{0020}for\u{0020}drivers\u{0020}on\u{0020}the\u{0020}frontline.\n\nUnfortunately,\u{0020}most\u{0020}of\u{0020}the\u{0020}flowers\u{0020}have\u{0020}withered\u{0020}before\u{0020}she\u{0020}reached\u{0020}her\u{0020}destination.\u{0020}She\u{0020}correlated\u{0020}the\u{0020}idea\u{0020}\"Although\u{0020}those\u{0020}heroes\u{0020}are\u{0020}dead,\u{0020}their\u{0020}stories\u{0020}will\u{0020}be\u{0020}passed\u{0020}down\u{0020}to\u{0020}our\u{0020}descendants,\u{0020}and\u{0020}inspire\u{0020}them.\"\u{0020}So,\u{0020}she\u{0020}made\u{0020}a\u{0020}lot\u{0020}of\u{0020}white\u{0020}paper\u{0020}flowers\u{0020}as\u{0020}replacements\u{0020}on\u{0020}her\u{0020}own,\u{0020}and\u{0020}hopes\u{0020}the\u{0020}blessing\u{0020}will\u{0020}pass\u{0020}to\u{0020}others.\n\nAmong\u{0020}them,\u{0020}there\u{0020}is\u{0020}one\u{0020}that\u{0020}cost\u{0020}her\u{0020}the\u{0020}most\u{0020}effort,\u{0020}but\u{0020}is\u{0020}not\u{0020}gifted\u{0020}yet.\n\n\"I\u{0020}thought\u{0020}I\u{0020}should\u{0020}send\u{0020}it\u{0020}to\u{0020}him,\u{0020}but\u{0020}nah,\u{0020}forget\u{0020}about\u{0020}it.\"\n\n\"If\u{0020}I\u{0020}have\u{0020}a\u{0020}chance,\u{0020}when\u{0020}everything\u{0020}ends,\u{0020}when\u{0020}he\u{0020}finishes\u{0020}his\u{0020}duty,\u{0020}I\u{0020}should\u{0020}take\u{0020}him\u{0020}to\u{0020}see\u{0020}the\u{0020}real\u{0020}ones.\"\n\n\"After\u{0020}that,\u{0020}I\u{0020}have\u{0020}other\u{0020}things\u{0020}to\u{0020}tell\u{0020}him…\"", "0", "0", "0", "0", 12013, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}在萨哈拉的学院，卡莲除了学习最基础的战略知识和她选修的avg装备研发课题外，她还对当地文化产生了浓厚的兴趣。\n\u{1000}\u{1000}在了解到白色睡莲在当地文化有着\"不灭\"的含义后，她在来Danube\u{1000}Branch前特意采摘了大量白色睡莲，并打算将其包装起来作为礼物送给前线的驾驶员和领航们。\n\u{1000}\u{1000}可惜的是这些睡莲在她还没抵达目的前便都枯萎了，这使她联想到家人曾经提过的\"英雄即便逝去，其经历也会被编纂成故事，激励下一代\"的说法。于是她便亲手制作了大量纸花作为替代品，希望这份祝福也能传承下去。\n\u{1000}\u{1000}而其中，有一束她花费了最多心血的作品，却至今还未送出。\n\u{1000}\u{1000}\"本来是想送给他的，不过最后感觉还是算了。\"\n\u{1000}\u{1000}\"有机会的话，等一切都结束之后…等他完成了自己的使命后，带他去看看实物好了。\"\n\u{1000}\u{1000}\"那时，还有其他想要对他说的话……\""},
[621304] = {621304, 2000, "\u{0020}\u{0020}Looking\u{0020}up\u{0020}into\u{0020}the\u{0020}sky,\u{0020}she\u{0020}still\u{0020}remembers\u{0020}the\u{0020}scene\u{0020}she\u{0020}saw\u{0020}on\u{0020}that\u{0020}day.\n\nA\u{0020}meteor\u{0020}shower…\n\nThose\u{0020}heroic\u{0020}people,\u{0020}the\u{0020}ones\u{0020}she\u{0020}cares\u{0020}the\u{0020}most,\n\nFalling\u{0020}down\u{0020}from\u{0020}the\u{0020}sky,\u{0020}burning,\u{0020}like\u{0020}shooting\u{0020}stars.\n\nIt\u{0020}was\u{0020}not\u{0020}like\u{0020}what\u{0020}written\u{0020}in\u{0020}books,\u{0020}that\u{0020}warriors\u{0020}die\u{0020}with\u{0020}dignity,\n\nInstead,\u{0020}she\u{0020}felt\u{0020}sorrow\u{0020}and\u{0020}anguish,\u{0020}only.\n\nBut…\n\n\"After\u{0020}I'm\u{0020}in\u{0020}your\u{0020}shoes,\u{0020}I\u{0020}can\u{0020}finally\u{0020}understand\u{0020}you…\"\n\nThe\u{0020}giantess\u{0020}turns\u{0020}her\u{0020}body\u{0020}gently,\u{0020}looking\u{0020}at\u{0020}the\u{0020}war-torn\u{0020}city.\n\n\"Perhaps,\u{0020}what\u{0020}you\u{0020}are\u{0020}willing\u{0020}to\u{0020}die\u{0020}for,\u{0020}is\u{0020}not\u{0020}the\u{0020}ideal\u{0020}of\u{0020}becoming\u{0020}heroes…\"\n\n\"But\u{0020}presumably,\u{0020}you\u{0020}died\u{0020}to\u{0020}protect\u{0020}someone\u{0020}you\u{0020}love…\"", "0", "0", "0", "0", 12013, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}仰望着天空，她仍然记得那天所看到的场景。\n\u{1000}\u{1000}流星雨……\n\u{1000}\u{1000}被称为英雄的人们，她最珍视的人们，\n\u{1000}\u{1000}如同流星一般燃烧着从空中陨落。\n\u{1000}\u{1000}和书中描绘出的英雄就义前那令人振奋的氛围不同，\n\u{1000}\u{1000}那时的她所能感受到只有悲伤与痛苦。\n\u{1000}\u{1000}但是……\n\u{1000}\u{1000}\"和你们站在同样的高度后，稍微也能理解一些了……\"\n\u{1000}\u{1000}巨大的少女缓缓侧过身，看向经历过战火洗礼的城市。\n\u{1000}\u{1000}\"也许，让你们甘愿牺牲的并不是成为英雄的理想。\"\n\u{1000}\u{1000}\"你们大概也只是想要守护某些人罢了……\""},
[621400] = {621400, 0, "[Name]\u{0020}Cephalis\n[B-Day]\u{0020}June\u{0020}11\n[Compatability\u{0020}Rate]\u{0020}???\n[Height]\u{0020}28m\n[Squad]\u{0020}Shumia\n[Affiliation]\u{0020}None\n[Interest]\u{0020}Reminiscing", "0", "0", "0", "0", 12014, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[621401] = {621401, 100, "\u{0020}\u{0020}Cephalis\u{0020}of\u{0020}the\u{0020}Shumia\u{0020}Team.\u{0020}People\u{0020}who\u{0020}meet\u{0020}her\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}always\u{0020}mistake\u{0020}her\u{0020}for\u{0020}a\u{0020}lost\u{0020}child\u{0020}from\u{0020}someone's\u{0020}family.\u{0020}But\u{0020}her\u{0020}actual\u{0020}identity\u{0020}is\u{0020}an\u{0020}alien\u{0020}visitor.\n\nWe\u{0020}thought\u{0020}that\u{0020}Cephalis\u{0020}had\u{0020}the\u{0020}common\u{0020}characteristics\u{0020}of\u{0020}Midyr\u{0020}people\u{0020}-\u{0020}having\u{0020}no\u{0020}concept\u{0020}of\u{0020}hometown\u{0020}and\u{0020}relatives\u{0020}and\u{0020}friends.\n\nBut\u{0020}when\u{0020}learning\u{0020}that\u{0020}her\u{0020}home\u{0020}planet\u{0020}seemed\u{0020}to\u{0020}have\u{0020}been\u{0020}destroyed\u{0020}by\u{0020}Sin\u{0020}all\u{0020}at\u{0020}once,\u{0020}Cephalis's\u{0020}slightly\u{0020}depressed\u{0020}mood\u{0020}highlighted\u{0020}her\u{0020}difference.\n\nCephalis\u{0020}is\u{0020}often\u{0020}accompanied\u{0020}by\u{0020}a\u{0020}robot\u{0020}dog,\u{0020}called\u{0020}\"Renie\".\u{0020}The\u{0020}name\u{0020}was\u{0020}given\u{0020}by\u{0020}Cephalis\u{0020}herself,\u{0020}but\u{0020}she\u{0020}did\u{0020}not\u{0020}know\u{0020}the\u{0020}meaning\u{0020}of\u{0020}the\u{0020}name.\n\nRenie\u{0020}is\u{0020}the\u{0020}latest\u{0020}intelligent\u{0020}product\u{0020}of\u{0020}the\u{0020}AEGIS\u{0020}R\u{0020}&\u{0020}D\u{0020}department.\u{0020}She\u{0020}follows\u{0020}Cephalis\u{0020}as\u{0020}a\u{0020}pet\u{0020}at\u{0020}ordinary\u{0020}times.\u{0020}When\u{0020}Cephalis\u{0020}needs\u{0020}to\u{0020}make\u{0020}an\u{0020}attack,\u{0020}Renie's\u{0020}AI\u{0020}consciousness\u{0020}can\u{0020}be\u{0020}uploaded\u{0020}to\u{0020}a\u{0020}larger\u{0020}dog-shaped\u{0020}combat\u{0020}machine,\u{0020}and\u{0020}follow\u{0020}Cephalis\u{0020}in\u{0020}a\u{0020}huge\u{0020}form\u{0020}to\u{0020}fight\u{0020}together.\n\nIn\u{0020}the\u{0020}battle\u{0020}against\u{0020}Sin,\u{0020}Cephalis\u{0020}and\u{0020}Renie\u{0020}were\u{0020}invincible.\u{0020}The\u{0020}tacit\u{0020}understanding\u{0020}cultivated\u{0020}in\u{0020}daily\u{0020}life\u{0020}was\u{0020}their\u{0020}strongest\u{0020}weapon.\u{0020}However,\u{0020}it\u{0020}was\u{0020}obvious\u{0020}that\u{0020}the\u{0020}degree\u{0020}of\u{0020}tacit\u{0020}cooperation\u{0020}between\u{0020}Renie\u{0020}and\u{0020}Cephalis\u{0020}far\u{0020}exceeded\u{0020}that\u{0020}of\u{0020}other\u{0020}drivers\u{0020}and\u{0020}also\u{0020}exceeded\u{0020}the\u{0020}expectations\u{0020}of\u{0020}researchers.\u{0020}Sometimes,\u{0020}even\u{0020}without\u{0020}Cephalis\u{0020}giving\u{0020}orders,\u{0020}Renie\u{0020}would\u{0020}take\u{0020}the\u{0020}most\u{0020}correct\u{0020}action,\u{0020}which\u{0020}completely\u{0020}exceeded\u{0020}the\u{0020}limit\u{0020}of\u{0020}the\u{0020}original\u{0020}design.\n\nPerhaps\u{0020}it\u{0020}is\u{0020}because\u{0020}of\u{0020}the\u{0020}different\u{0020}constitutions\u{0020}between\u{0020}Midyr\u{0020}people\u{0020}and\u{0020}Earth\u{0020}people.\n\nThe\u{0020}R\u{0020}&\u{0020}D\u{0020}department\u{0020}that\u{0020}couldn't\u{0020}find\u{0020}the\u{0020}reason\u{0020}after\u{0020}multiple\u{0020}detections\u{0020}finally\u{0020}gave\u{0020}up\u{0020}exploring\u{0020}the\u{0020}differences.\u{0020}After\u{0020}all,\u{0020}there\u{0020}are\u{0020}more\u{0020}studies\u{0020}that\u{0020}require\u{0020}their\u{0020}energy\u{0020}consumption.\u{0020}It\u{0020}is\u{0020}enough\u{0020}for\u{0020}us\u{0020}to\u{0020}know\u{0020}that\u{0020}there\u{0020}is\u{0020}one\u{0020}more\u{0020}reliable\u{0020}combat\u{0020}force\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}against\u{0020}Sin.", "0", "0", "0", "0", 12014, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[621402] = {621402, 500, "\u{0020}\u{0020}During\u{0020}the\u{0020}communication\u{0020}with\u{0020}the\u{0020}Midyr\u{0020}people,\u{0020}we\u{0020}thought\u{0020}we\u{0020}completely\u{0020}understood\u{0020}their\u{0020}way\u{0020}of\u{0020}life\u{0020}and\u{0020}thinking.\n\nLived\u{0020}a\u{0020}lifetime\u{0020}in\u{0020}interstellar\u{0020}travel,\u{0020}having\u{0020}no\u{0020}concept\u{0020}of\u{0020}hometown\u{0020}or\u{0020}relatives,\u{0020}and\u{0020}like\u{0020}salmon,\u{0020}would\u{0020}return\u{0020}to\u{0020}the\u{0020}home\u{0020}planet\u{0020}for\u{0020}reproduction\u{0020}after\u{0020}reaching\u{0020}adulthood\u{0020}and\u{0020}then\u{0020}die...\n\nThis\u{0020}is\u{0020}the\u{0020}life\u{0020}of\u{0020}Midyr\u{0020}people,\u{0020}as\u{0020}we\u{0020}think...\u{0020}Their\u{0020}life.\n\nBut\u{0020}there\u{0020}are\u{0020}exceptions\u{0020}to\u{0020}everything,\u{0020}like\u{0020}her\u{0020}teammate\u{0020}Aevati.\n\nAnd\u{0020}Cephalis,\u{0020}likewise\u{0020}an\u{0020}exception,\u{0020}is\u{0020}a\u{0020}Midyr\u{0020}person\u{0020}who\u{0020}misses\u{0020}her\u{0020}hometown.\n\nAll\u{0020}the\u{0020}following\u{0020}comes\u{0020}from\u{0020}Cephalis's\u{0020}self-narration.\n\n\"Midyr\u{0020}is\u{0020}a\u{0020}planet\u{0020}as\u{0020}beautiful\u{0020}as\u{0020}the\u{0020}Earth.\u{0020}There\u{0020}are\u{0020}also\u{0020}various\u{0020}forms\u{0020}of\u{0020}animals\u{0020}and\u{0020}plants\u{0020}living\u{0020}on\u{0020}the\u{0020}planet,\u{0020}and\u{0020}there\u{0020}are\u{0020}distinctions\u{0020}between\u{0020}land\u{0020}and\u{0020}sea\u{0020}on\u{0020}the\u{0020}surface.\"\n\n\"The\u{0020}sun\u{0020}on\u{0020}Midyr\u{0020}rises\u{0020}in\u{0020}the\u{0020}south\u{0020}and\u{0020}sets\u{0020}in\u{0020}the\u{0020}north,\u{0020}and\u{0020}the\u{0020}day\u{0020}is\u{0020}a\u{0020}little\u{0020}longer\u{0020}than\u{0020}on\u{0020}Earth.\u{0020}There\u{0020}is\u{0020}very\u{0020}little\u{0020}movement\u{0020}on\u{0020}land,\u{0020}because\u{0020}Midyr\u{0020}people\u{0020}set\u{0020}out\u{0020}on\u{0020}a\u{0020}voyage\u{0020}shortly\u{0020}after\u{0020}birth.\"\n\n\"There\u{0020}are\u{0020}also\u{0020}cities\u{0020}on\u{0020}Midyr,\u{0020}but\u{0020}they\u{0020}have\u{0020}been\u{0020}abandoned\u{0020}and\u{0020}become\u{0020}a\u{0020}steel\u{0020}jungle\u{0020}occupied\u{0020}by\u{0020}trees\u{0020}and\u{0020}vines.\u{0020}That\u{0020}is\u{0020}the\u{0020}relic\u{0020}of\u{0020}the\u{0020}old\u{0020}Midyr\u{0020}civilization...\"\n\nFrom\u{0020}Cephalis's\u{0020}mouth,\u{0020}we\u{0020}gathered\u{0020}more\u{0020}information\u{0020}about\u{0020}Midyr.\u{0020}The\u{0020}vast\u{0020}majority\u{0020}of\u{0020}it\u{0020}contains\u{0020}details\u{0020}that\u{0020}several\u{0020}other\u{0020}Midyr\u{0020}people\u{0020}have\u{0020}never\u{0020}mentioned.\u{0020}So\u{0020}much\u{0020}so\u{0020}that\u{0020}the\u{0020}intelligence\u{0020}department\u{0020}of\u{0020}AEGIS\u{0020}suspected\u{0020}whether\u{0020}Cephalis\u{0020}was\u{0020}not\u{0020}of\u{0020}the\u{0020}same\u{0020}race\u{0020}as\u{0020}the\u{0020}rest.\u{0020}However,\u{0020}in\u{0020}the\u{0020}subsequent\u{0020}investigation,\u{0020}we\u{0020}determined\u{0020}that\u{0020}there\u{0020}is\u{0020}indeed\u{0020}only\u{0020}one\u{0020}race\u{0020}on\u{0020}Midyr.\n\nIn\u{0020}a\u{0020}recent\u{0020}interview,\u{0020}Cephalis\u{0020}mentioned\u{0020}one\u{0020}thing\u{0020}that\u{0020}is\u{0020}particularly\u{0020}concerning.\n\n\"Recently,\u{0020}I\u{0020}always\u{0020}dream\u{0020}that\u{0020}I\u{0020}have\u{0020}returned\u{0020}to\u{0020}Midyr\u{0020}and\u{0020}wake\u{0020}up\u{0020}on\u{0020}the\u{0020}grassland\u{0020}where\u{0020}I\u{0020}used\u{0020}to\u{0020}sleep.\u{0020}Everything\u{0020}around\u{0020}is\u{0020}exactly\u{0020}the\u{0020}same\u{0020}as\u{0020}before.\u{0020}\"\n\n\"In\u{0020}the\u{0020}dream,\u{0020}I\u{0020}spent\u{0020}most\u{0020}of\u{0020}the\u{0020}time\u{0020}enjoying\u{0020}the\u{0020}scenery\u{0020}alone,\u{0020}but\u{0020}I\u{0020}could\u{0020}clearly\u{0020}feel\u{0020}the\u{0020}presence\u{0020}of\u{0020}another\u{0020}person\u{0020}beside\u{0020}me.\u{0020}Every\u{0020}time\u{0020}when\u{0020}I\u{0020}was\u{0020}about\u{0020}to\u{0020}see\u{0020}that\u{0020}person,\u{0020}I\u{0020}woke\u{0020}up\u{0020}and\u{0020}then\u{0020}saw\u{0020}Renie\u{0020}lying\u{0020}beside\u{0020}me...\u{0020}\"\n\nRegarding\u{0020}this\u{0020}dream\u{0020}of\u{0020}Cephalis,\u{0020}the\u{0020}researchers\u{0020}at\u{0020}the\u{0020}headquarters\u{0020}have\u{0020}no\u{0020}clue.\u{0020}After\u{0020}all,\u{0020}they\u{0020}are\u{0020}scientists\u{0020}rather\u{0020}than\u{0020}dream\u{0020}interpreters.\u{0020}All\u{0020}of\u{0020}this\u{0020}can\u{0020}only\u{0020}be\u{0020}attributed\u{0020}to\u{0020}Cephalis\u{0020}missing\u{0020}her\u{0020}home\u{0020}planet\u{0020}too\u{0020}much.\u{0020}As\u{0020}for\u{0020}that\u{0020}\"person\u{0020}in\u{0020}the\u{0020}dream\",\u{0020}it\u{0020}might\u{0020}be\u{0020}her\u{0020}former\u{0020}friend.\u{0020}However,\u{0020}someone\u{0020}proposed\u{0020}a\u{0020}viewpoint\u{0020}at\u{0020}that\u{0020}time.\u{0020}Because\u{0020}it\u{0020}was\u{0020}too\u{0020}shocking,\u{0020}it\u{0020}was\u{0020}not\u{0020}recognized\u{0020}by\u{0020}everyone.\u{0020}Let's\u{0020}record\u{0020}it\u{0020}here\u{0020}for\u{0020}the\u{0020}reference\u{0020}of\u{0020}readers\u{0020}-\u{0020}If\u{0020}Midyr\u{0020}people\u{0020}can\u{0020}be\u{0020}resurrected\u{0020}through\u{0020}the\u{0020}information\u{0020}from\u{0020}60\u{0020}years\u{0020}ago,\u{0020}then\u{0020}will\u{0020}their\u{0020}home\u{0020}planet\u{0020}also\u{0020}exist\u{0020}in\u{0020}the\u{0020}form\u{0020}of\u{0020}information\u{0020}somewhere,\u{0020}waiting\u{0020}for\u{0020}rebirth\u{0020}in\u{0020}the\u{0020}future?\n\nAs\u{0020}for\u{0020}that\u{0020}\"person\u{0020}in\u{0020}the\u{0020}dream\",\u{0020}it\u{0020}might\u{0020}be\u{0020}her\u{0020}former\u{0020}friend.\n\nHowever,\u{0020}someone\u{0020}proposed\u{0020}a\u{0020}viewpoint\u{0020}at\u{0020}that\u{0020}time.\u{0020}Because\u{0020}it\u{0020}was\u{0020}too\u{0020}shocking,\u{0020}it\u{0020}was\u{0020}not\u{0020}recognized\u{0020}by\u{0020}everyone.\u{0020}Let's\u{0020}record\u{0020}it\u{0020}here\u{0020}for\u{0020}the\u{0020}reference\u{0020}of\u{0020}readers\u{0020}-\u{0020}If\u{0020}Midyr\u{0020}people\u{0020}can\u{0020}be\u{0020}resurrected\u{0020}through\u{0020}the\u{0020}information\u{0020}from\u{0020}60\u{0020}years\u{0020}ago,\u{0020}then\u{0020}will\u{0020}their\u{0020}home\u{0020}planet\u{0020}also\u{0020}exist\u{0020}in\u{0020}some\u{0020}form\u{0020}of\u{0020}information\u{0020}somewhere,\u{0020}waiting\u{0020}for\u{0020}rebirth\u{0020}in\u{0020}the\u{0020}future?", "0", "0", "0", "0", 12014, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[621403] = {621403, 1000, "\u{0020}\u{0020}Sixty\u{0020}years\u{0020}is\u{0020}already\u{0020}most\u{0020}of\u{0020}a\u{0020}human's\u{0020}life,\u{0020}but\u{0020}for\u{0020}these\u{0020}several\u{0020}reborn\u{0020}Midyr\u{0020}people,\u{0020}it\u{0020}is\u{0020}just\u{0020}a\u{0020}long\u{0020}sleep.\n\nWhen\u{0020}Cephalis\u{0020}stood\u{0020}up\u{0020}from\u{0020}the\u{0020}pool\u{0020}filled\u{0020}with\u{0020}liquid\u{0020}Nimbus\u{0020}energy,\u{0020}memories\u{0020}of\u{0020}fear\u{0020}and\u{0020}sadness\u{0020}followed.\u{0020}She\u{0020}was\u{0020}the\u{0020}only\u{0020}crying\u{0020}Midyr\u{0020}person,\u{0020}allowing\u{0020}us\u{0020}to\u{0020}understand\u{0020}the\u{0020}physiological\u{0020}commonalities\u{0020}between\u{0020}humans\u{0020}and\u{0020}Midyr\u{0020}people.\n\nFortunately,\u{0020}that\u{0020}special\u{0020}navigator\u{0020}was\u{0020}present\u{0020}at\u{0020}that\u{0020}time.\u{0020}With\u{0020}a\u{0020}few\u{0020}simple\u{0020}words,\u{0020}he\u{0020}soothed\u{0020}Cephalis's\u{0020}emotions\u{0020}and\u{0020}helped\u{0020}her\u{0020}get\u{0020}familiar\u{0020}with\u{0020}her\u{0020}new\u{0020}body\u{0020}and\u{0020}the\u{0020}new\u{0020}environment.\n\nAs\u{0020}a\u{0020}Midyr\u{0020}person\u{0020}who\u{0020}has\u{0020}been\u{0020}traveling\u{0020}everywhere\u{0020}in\u{0020}the\u{0020}universe,\u{0020}Cephalis\u{0020}quickly\u{0020}adapted\u{0020}to\u{0020}life\u{0020}on\u{0020}Earth\u{0020}and\u{0020}made\u{0020}many\u{0020}human\u{0020}friends.\u{0020}She\u{0020}even\u{0020}became\u{0020}an\u{0020}AVG\u{0020}driver\u{0020}and\u{0020}joined\u{0020}the\u{0020}battle\u{0020}against\u{0020}Sin.\u{0020}Earth\u{0020}seems\u{0020}to\u{0020}have\u{0020}become\u{0020}her\u{0020}second\u{0020}home.\n\nIf\u{0020}it\u{0020}weren't\u{0020}for\u{0020}seeing\u{0020}Cephalis\u{0020}looking\u{0020}up\u{0020}at\u{0020}the\u{0020}starry\u{0020}sky\u{0020}on\u{0020}the\u{0020}rooftop\u{0020}every\u{0020}night,\u{0020}perhaps\u{0020}no\u{0020}one\u{0020}would\u{0020}know\u{0020}that\u{0020}the\u{0020}Midyr\u{0020}people\u{0020}also\u{0020}have\u{0020}feelings\u{0020}of\u{0020}homesickness.", "0", "0", "0", "0", 12014, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[621404] = {621404, 2000, "\u{0020}\u{0020}That\u{0020}is\u{0020}the\u{0020}direction\u{0020}where\u{0020}Midyr\u{0020}is.\n\nThe\u{0020}navigator\u{0020}stands\u{0020}on\u{0020}the\u{0020}girl's\u{0020}raised\u{0020}finger\n\nLook\u{0020}towards\u{0020}the\u{0020}starry\u{0020}sky\u{0020}pointed\u{0020}to\n\nSearching\u{0020}for\u{0020}the\u{0020}planet\u{0020}mentioned\u{0020}by\u{0020}the\u{0020}girl\n\nBut\u{0020}only\u{0020}saw\u{0020}total\u{0020}darkness.\n\nHowever,\u{0020}when\u{0020}he\u{0020}turned\u{0020}around\u{0020}to\u{0020}comfort\u{0020}the\u{0020}girl,\n\nHe\u{0020}unexpectedly\u{0020}saw,\n\nIn\u{0020}the\u{0020}depth\u{0020}of\u{0020}the\u{0020}girl's\u{0020}pupil\n\nReflecting\u{0020}a\u{0020}planet\u{0020}as\u{0020}blue\u{0020}as\u{0020}the\u{0020}Earth.\n\nThat\u{0020}is\u{0020}Midyr,\n\nThat\u{0020}is\u{0020}the\u{0020}hometown\u{0020}that\u{0020}Cephalis\u{0020}has\u{0020}been\u{0020}longing\u{0020}for.", "0", "0", "0", "0", 12014, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[621500] = {621500, 0, "[Name]\u{0020}Vesper\n[B-Day]\u{0020}Sep\u{0020}29\n[Compatability\u{0020}Rate]\u{0020}89%\n[Height]\u{0020}37m\n[Squad]\u{0020}First\u{0020}Guards\u{0020}Squad\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Reading\u{0020}legends\u{0020}and\u{0020}epics", "0", "0", "0", "0", 12015, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}薇丝帕尔\n[B-Day]\u{1000}9月29日\n[幻化核心适格率]\u{1000}89%\n[Height]\u{1000}37m\n[部队]\u{1000}第一亲卫班\n\u{1000}\u{00A0}[隶属]\u{1000}Danube\u{1000}Branch\n[Interest]\u{1000}阅读传说与史诗"},
[621501] = {621501, 100, "\u{0020}\u{0020}\"The\u{0020}Princess\u{0020}of\u{0020}Danube\",\u{0020}\"The\u{0020}Flower\u{0020}of\u{0020}Danube\"...\u{0020}People\u{0020}call\u{0020}this\u{0020}girl\u{0020}with\u{0020}rose-colored\u{0020}curly\u{0020}hair\u{0020}in\u{0020}such\u{0020}a\u{0020}way.\u{0020}If\u{0020}one\u{0020}has\u{0020}to\u{0020}choose\u{0020}a\u{0020}girl\u{0020}at\u{0020}the\u{0020}top\u{0020}among\u{0020}many\u{0020}\"young\u{0020}lady\"\u{0020}type\u{0020}drivers,\u{0020}then\u{0020}it\u{0020}must\u{0020}be\u{0020}Vesper.\u{0020}Vesper\u{0020}was\u{0020}born\u{0020}into\u{0020}the\u{0020}largest\u{0020}noble\u{0020}family\u{0020}in\u{0020}Danube\u{0020}at\u{0020}present,\u{0020}and\u{0020}her\u{0020}father\u{0020}is\u{0020}the\u{0020}famous\u{0020}Danube\u{0020}Branch\u{0020}Chief,\u{0020}which\u{0020}is\u{0020}the\u{0020}reason\u{0020}why\u{0020}she\u{0020}is\u{0020}called\u{0020}\"The\u{0020}Princess\u{0020}of\u{0020}Danube\".\n\nIt\u{0020}is\u{0020}a\u{0020}very\u{0020}strange\u{0020}thing\u{0020}for\u{0020}someone\u{0020}of\u{0020}such\u{0020}noble\u{0020}status\u{0020}to\u{0020}appear\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}When\u{0020}Vesper\u{0020}first\u{0020}appeared\u{0020}in\u{0020}public\u{0020}as\u{0020}a\u{0020}driver,\u{0020}it\u{0020}naturally\u{0020}caused\u{0020}quite\u{0020}a\u{0020}stir.\u{0020}The\u{0020}new\u{0020}nobles\u{0020}and\u{0020}commoners\u{0020}worshipped\u{0020}her\u{0020}as\u{0020}a\u{0020}role\u{0020}model,\u{0020}but\u{0020}the\u{0020}old\u{0020}nobles\u{0020}accused\u{0020}her\u{0020}of\u{0020}being\u{0020}just\u{0020}a\u{0020}show-off\u{0020}vase.\n\n\n\nVesper\u{0020}eventually\u{0020}refuted\u{0020}the\u{0020}doubts\u{0020}of\u{0020}the\u{0020}old\u{0020}nobles\u{0020}towards\u{0020}her\u{0020}with\u{0020}her\u{0020}excellent\u{0020}performance\u{0020}in\u{0020}her\u{0020}first\u{0020}battle.\n\nHowever,\u{0020}that\u{0020}night,\u{0020}at\u{0020}the\u{0020}victory\u{0020}celebration\u{0020}dinner\u{0020}held\u{0020}in\u{0020}the\u{0020}capital\u{0020}of\u{0020}Danube,\u{0020}Vesper\u{0020}did\u{0020}not\u{0020}wear\u{0020}a\u{0020}magnificent\u{0020}dress\u{0020}as\u{0020}people\u{0020}imagined\u{0020}and\u{0020}give\u{0020}a\u{0020}speech\u{0020}in\u{0020}the\u{0020}pre-prepared\u{0020}indoor\u{0020}auditorium.\n\nShe\u{0020}was\u{0020}suspended\u{0020}above\u{0020}the\u{0020}auditorium\u{0020}in\u{0020}a\u{0020}gigantic\u{0020}form,\u{0020}introducing\u{0020}herself\u{0020}to\u{0020}people\u{0020}haughtily\u{0020}and\u{0020}gracefully.\n\n\"Vesper·Teresa·Herstal\u{0020}is\u{0020}first\u{0020}and\u{0020}foremost\u{0020}a\u{0020}noble,\u{0020}and\u{0020}only\u{0020}secondly\u{0020}a\u{0020}driver.\"", "0", "0", "0", "0", 12015, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"多瑙的公主\"，\"多瑙之花\"……人们如此这般称呼这位拥有玫瑰色卷发的少女。如果非要在众多\"大小姐\"型驾驶员中选出一名位于顶端的少女的话，那么便非薇丝帕尔莫属。薇丝帕尔出生于多瑙目前最大的贵族世家，她的父亲是赫赫有名的Danube\u{1000}Branch长，这也是她被称为\"多瑙的公主\"的原因了。\n\u{1000}\u{1000}身份如此尊贵的人出现在战场是一件非常奇怪的事情，当薇丝帕尔第一次以驾驶员的姿态出现在公众面前时自然是引起了不小的轰动，新贵族和平民将她视作榜样一般崇拜，但旧贵族却指责她只不过是逢场作秀的花瓶。\n\u{1000}\u{1000}薇丝帕尔最终还是用自己首战优异的表现反驳了旧贵族们对她的质疑。\n\u{1000}\u{1000}只是当夜，在多瑙首都举办的庆功晚宴上，薇丝帕尔并没有像人们想象得那般身着华丽的礼服，在事先准备好的室内礼堂上演讲。\n\u{1000}\u{1000}她以巨大化的姿态悬浮在礼堂的上空，高傲且优雅地向人们介绍起自己。\n\u{1000}\u{1000}\"薇丝帕尔·特蕾莎·赫尔斯塔尔，首先是一名贵族，其次才是驾驶员。\""},
[621502] = {621502, 500, "\u{0020}\u{0020}Vesper\u{0020}is\u{0020}like\u{0020}the\u{0020}\"rich\u{0020}young\u{0020}lady\"\u{0020}in\u{0020}the\u{0020}impression\u{0020}of\u{0020}most\u{0020}people.\u{0020}She\u{0020}was\u{0020}born\u{0020}noble,\u{0020}has\u{0020}a\u{0020}good\u{0020}appearance.\u{0020}She\u{0020}spends\u{0020}money\u{0020}freely\u{0020}but\u{0020}behaves\u{0020}elegantly.\u{0020}She\u{0020}is\u{0020}highly\u{0020}talented\u{0020}but\u{0020}maverick.\u{0020}She\u{0020}has\u{0020}both\u{0020}an\u{0020}angelic\u{0020}side\u{0020}and\u{0020}a\u{0020}demonic\u{0020}side.\n\nBut\u{0020}in\u{0020}fact,\u{0020}her\u{0020}parents\u{0020}did\u{0020}not\u{0020}want\u{0020}their\u{0020}daughter\u{0020}to\u{0020}be\u{0020}so\u{0020}conspicuous,\u{0020}and\u{0020}even\u{0020}opposed\u{0020}Vesper's\u{0020}participation\u{0020}in\u{0020}the\u{0020}driver\u{0020}qualification\u{0020}test,\u{0020}but\u{0020}it\u{0020}was\u{0020}inconvenient\u{0020}for\u{0020}her\u{0020}supporters\u{0020}and\u{0020}political\u{0020}stance\u{0020}to\u{0020}show\u{0020}it.\n\nThe\u{0020}new\u{0020}nobles\u{0020}of\u{0020}Danube,\u{0020}led\u{0020}by\u{0020}the\u{0020}branch\u{0020}chief,\u{0020}are\u{0020}not\u{0020}as\u{0020}obsessed\u{0020}with\u{0020}the\u{0020}so-called\u{0020}glory\u{0020}and\u{0020}destiny\u{0020}as\u{0020}the\u{0020}old\u{0020}nobles.\u{0020}To\u{0020}put\u{0020}it\u{0020}bluntly,\u{0020}they\u{0020}are\u{0020}just\u{0020}opportunists\u{0020}and\u{0020}a\u{0020}small\u{0020}number\u{0020}of\u{0020}patriots\u{0020}who\u{0020}have\u{0020}been\u{0020}given\u{0020}the\u{0020}title\u{0020}of\u{0020}noble.\u{0020}The\u{0020}reason\u{0020}why\u{0020}they\u{0020}call\u{0020}themselves\u{0020}nobles\u{0020}is\u{0020}only\u{0020}due\u{0020}to\u{0020}the\u{0020}cultural\u{0020}tradition\u{0020}of\u{0020}Danube...\u{0020}The\u{0020}people\u{0020}of\u{0020}Danube\u{0020}always\u{0020}hope\u{0020}that\u{0020}those\u{0020}who\u{0020}lead\u{0020}them\u{0020}are\u{0020}always\u{0020}descendants\u{0020}of\u{0020}heroes\u{0020}like\u{0020}in\u{0020}legendary\u{0020}stories.\u{0020}That's\u{0020}why\u{0020}they\u{0020}excitedly\u{0020}promoted\u{0020}Vesper\u{0020}as\u{0020}an\u{0020}idol\u{0020}after\u{0020}she\u{0020}became\u{0020}a\u{0020}driver.\n\nOf\u{0020}course,\u{0020}this\u{0020}does\u{0020}not\u{0020}mean\u{0020}that\u{0020}Vesper\u{0020}was\u{0020}willing\u{0020}to\u{0020}become\u{0020}a\u{0020}driver\u{0020}for\u{0020}the\u{0020}family\u{0020}and\u{0020}the\u{0020}new\u{0020}nobility.\u{0020}After\u{0020}all,\u{0020}her\u{0020}family\u{0020}was\u{0020}already\u{0020}at\u{0020}the\u{0020}top\u{0020}of\u{0020}Danube,\u{0020}and\u{0020}the\u{0020}decline\u{0020}of\u{0020}the\u{0020}old\u{0020}nobility\u{0020}was\u{0020}inevitable.\u{0020}There\u{0020}was\u{0020}no\u{0020}need\u{0020}for\u{0020}Vesper\u{0020}to\u{0020}risk\u{0020}her\u{0020}life\u{0020}to\u{0020}promote\u{0020}it.\n\nOn\u{0020}the\u{0020}contrary,\u{0020}she\u{0020}is\u{0020}the\u{0020}one\u{0020}most\u{0020}\"influenced\"\u{0020}by\u{0020}traditional\u{0020}culture.\u{0020}Vesper\u{0020}was\u{0020}attracted\u{0020}by\u{0020}those\u{0020}fantastic\u{0020}legends\u{0020}that\u{0020}have\u{0020}been\u{0020}passed\u{0020}down\u{0020}in\u{0020}Danube\u{0020}since\u{0020}her\u{0020}childhood.\u{0020}She\u{0020}yearned\u{0020}extremely\u{0020}for\u{0020}those\u{0020}ancestors\u{0020}who\u{0020}carried\u{0020}the\u{0020}destiny\u{0020}and\u{0020}held\u{0020}swords\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}and\u{0020}hoped\u{0020}that\u{0020}one\u{0020}day\u{0020}she\u{0020}could\u{0020}become\u{0020}a\u{0020}new\u{0020}legend.\n\n\"Was\u{0020}she\u{0020}the\u{0020}princess\u{0020}of\u{0020}Danube?\u{0020}Maybe\u{0020}that's\u{0020}not\u{0020}accurate\u{0020}enough.\u{0020}In\u{0020}that\u{0020}era\u{0020}full\u{0020}of\u{0020}legends,\u{0020}she\u{0020}might\u{0020}have\u{0020}been\u{0020}called\u{0020}the\u{0020}knight\u{0020}of\u{0020}Danube,\u{0020}or,\u{0020}the\u{0020}future\u{0020}queen\u{0020}of\u{0020}Danube.\"", "0", "0", "0", "0", 12015, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}薇丝帕尔就像大多数人们印象中的\"千金大小姐\"一样，她出生高贵，外表姣好，她挥金如土却举止优雅，她天资过人却特立独行，她既有如同天使的一面亦有类似恶魔的一面。\u{1000}\u{1000}但事实上，她的父母并不希望自己的女儿如此引人注目，甚至在薇丝帕尔参加驾驶员适格测试这件事上也是持反对态度，但碍于其支持者和政治立场的缘故不方便表露出来。\u{1000}\u{1000}以支部长为首的多瑙的新贵族们并不像是老贵族们那样执着于所谓的荣耀和宿命，说白了他们只是被冠以了贵族头衔的投机者和小部分爱国者罢了，之所以将自己称为贵族只是因为多瑙的文化传统所致……多瑙的人民希望率领她们的永远是如同传奇故事中的英雄后裔。所以他们才会在薇丝帕尔成为驾驶员后兴奋地将她推崇为偶像。\u{1000}\u{1000}当然，这也并不代表着薇丝帕尔是为了家族和新贵族才愿意成为驾驶员的，毕竟她的家族早已位于多瑙的顶点，而旧贵族的衰退也是必然之事，完全不需要薇丝帕尔冒着生命危险去推动。\u{1000}\u{1000}相反，她才是受到传统文化\"影响\"最深的那个，薇丝帕尔在年幼时便被多瑙流传至今的那些天马行空的传奇故事所吸引，她无比憧憬着那些背负天命执剑沙场的祖先，并希望自己有朝一日能够成为新的传奇。\u{1000}\u{1000}\"多瑙的公主吗？也许还不够准确吧，放到那个满是传奇的年代，她也许应该被称为多瑙的骑士，或者，多瑙未来的女王。\""},
[621503] = {621503, 1000, "\u{0020}\u{0020}Guards\u{0020}Squad\u{0020}originally\u{0020}meant\u{0020}\"the\u{0020}king's\u{0020}trusted\u{0020}guard\".\u{0020}But\u{0020}now\u{0020}there\u{0020}is\u{0020}no\u{0020}king\u{0020}in\u{0020}Danube,\u{0020}and\u{0020}the\u{0020}object\u{0020}of\u{0020}the\u{0020}allegiance\u{0020}is\u{0020}no\u{0020}longer\u{0020}humans,\u{0020}but\u{0020}the\u{0020}huge\u{0020}Danube\u{0020}Ark\u{0020}built\u{0020}by\u{0020}AEGIS.\u{0020}At\u{0020}present,\u{0020}Vesper\u{0020}is\u{0020}serving\u{0020}in\u{0020}this\u{0020}legendary\u{0020}army.\n\nHere\u{0020}she\u{0020}met\u{0020}Cynthia,\u{0020}who\u{0020}was\u{0020}born\u{0020}a\u{0020}commoner,\u{0020}and\u{0020}also\u{0020}made\u{0020}acquaintance\u{0020}with\u{0020}Flora,\u{0020}who\u{0020}represented\u{0020}the\u{0020}old\u{0020}noble\u{0020}forces.\u{0020}The\u{0020}three,\u{0020}who\u{0020}should\u{0020}have\u{0020}been\u{0020}opposed\u{0020}to\u{0020}each\u{0020}other,\u{0020}stood\u{0020}together\u{0020}in\u{0020}the\u{0020}face\u{0020}of\u{0020}a\u{0020}common\u{0020}mission.\u{0020}And\u{0020}this\u{0020}was\u{0020}exactly\u{0020}the\u{0020}result\u{0020}Vesper\u{0020}wanted.\u{0020}She\u{0020}hoped\u{0020}more\u{0020}than\u{0020}anyone\u{0020}else\u{0020}to\u{0020}eliminate\u{0020}the\u{0020}barriers\u{0020}among\u{0020}the\u{0020}public\u{0020}in\u{0020}Danube.\u{0020}She\u{0020}hoped\u{0020}more\u{0020}than\u{0020}anyone\u{0020}else\u{0020}that\u{0020}after\u{0020}completely\u{0020}destroying\u{0020}Sin,\u{0020}Danube\u{0020}could\u{0020}still\u{0020}be\u{0020}as\u{0020}united\u{0020}as\u{0020}it\u{0020}is\u{0020}now.\n\nThe\u{0020}reason\u{0020}for\u{0020}giving\u{0020}birth\u{0020}to\u{0020}this\u{0020}ideal\u{0020}is\u{0020}not\u{0020}only\u{0020}the\u{0020}identity\u{0020}of\u{0020}\"the\u{0020}princess\u{0020}of\u{0020}Danube\",\u{0020}but\u{0020}also\u{0020}because\u{0020}she\u{0020}is\u{0020}\"the\u{0020}people\u{0020}born\u{0020}in\u{0020}Danube\".\u{0020}Yes,\u{0020}the\u{0020}girl\u{0020}did\u{0020}not\u{0020}notice\u{0020}that\u{0020}this\u{0020}is\u{0020}not\u{0020}a\u{0020}mission\u{0020}bestowed\u{0020}by\u{0020}God.\u{0020}This\u{0020}is\u{0020}just\u{0020}a\u{0020}dream\u{0020}that\u{0020}every\u{0020}child\u{0020}born\u{0020}in\u{0020}Danube\u{0020}desires\u{0020}to\u{0020}realize.\n\nVesper,\u{0020}she\u{0020}is\u{0020}just\u{0020}an\u{0020}ordinary\u{0020}girl\u{0020}from\u{0020}Danube.", "0", "0", "0", "0", 12015, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}亲卫队，本意是\"国王的亲信卫队\"。但现如今的多瑙已经没有所谓的国王了，亲卫队所效忠的对象也不再是人类，而是艾吉斯所建造的巨大多瑙方舟。当下，薇丝帕尔正效力于这支充满传奇的部队。\u{1000}\u{1000}在这里她认识了平民出生的辛西娅，也结识了代表着旧贵族势力的芙萝拉，本应对立的三人在共同的使命面前站在了一起。而这正是薇丝帕尔想要的结果，她比任何人都希望消去多瑙大众之间的隔阂，她比任何人都希望在彻底歼灭原罪后，多瑙依旧能够像是现在一般团结。\u{1000}\u{1000}孕育出这份理想的不仅仅是\"多瑙的公主\"这个身份，更是因为她是\"出生在多瑙的人民\"。没错，少女并未注意到，这并不是什么上天赐予她的使命，这仅仅是每个出生在多瑙的孩子都会渴望实现的梦想而已。\u{1000}\u{1000}薇丝帕尔，她仅仅是一名普通的多瑙女孩。"},
[621504] = {621504, 2000, "\u{0020}\u{0020}Inside\u{0020}the\u{0020}auditorium,\u{0020}everyone\u{0020}was\u{0020}full\u{0020}of\u{0020}anticipation,\u{0020}waiting\u{0020}for\u{0020}the\u{0020}princess\u{0020}of\u{0020}Danube\u{0020}to\u{0020}come\u{0020}on\u{0020}stage\u{0020}and\u{0020}give\u{0020}a\u{0020}speech.\n\nHowever,\u{0020}when\u{0020}the\u{0020}bell\u{0020}rang,\u{0020}the\u{0020}figure\u{0020}of\u{0020}the\u{0020}young\u{0020}girl\u{0020}did\u{0020}not\u{0020}appear\u{0020}on\u{0020}the\u{0020}stage.\n\nPeople\u{0020}looked\u{0020}at\u{0020}each\u{0020}other\u{0020}in\u{0020}bewilderment.\u{0020}Just\u{0020}then,\u{0020}a\u{0020}cry\u{0020}outside\u{0020}the\u{0020}auditorium\u{0020}broke\u{0020}the\u{0020}awkwardness.\u{0020}People\u{0020}ran\u{0020}out\u{0020}of\u{0020}the\u{0020}auditorium\u{0020}and\u{0020}saw\u{0020}a\u{0020}scene\u{0020}that\u{0020}would\u{0020}be\u{0020}unforgettable\u{0020}for\u{0020}a\u{0020}lifetime.\n\nVesper's\u{0020}huge\u{0020}and\u{0020}white\u{0020}body\u{0020}stood\u{0020}in\u{0020}the\u{0020}auditorium\u{0020}like\u{0020}a\u{0020}Roman\u{0020}pillar.\u{0020}A\u{0020}head\u{0020}of\u{0020}wine-colored\u{0020}long\u{0020}hair\u{0020}poured\u{0020}down\u{0020}like\u{0020}a\u{0020}waterfall\u{0020}from\u{0020}shoulders\u{0020}tens\u{0020}of\u{0020}meters\u{0020}high.\n\nWith\u{0020}the\u{0020}roof\u{0020}of\u{0020}the\u{0020}auditorium\u{0020}as\u{0020}the\u{0020}stage,\u{0020}the\u{0020}girl\u{0020}stretched\u{0020}her\u{0020}toes\u{0020}and\u{0020}saluted\u{0020}the\u{0020}little\u{0020}visitors.\n\n\"Vesper·Teresa·Herstal\u{0020}is\u{0020}first\u{0020}and\u{0020}foremost\u{0020}a\u{0020}noble,\u{0020}and\u{0020}only\u{0020}secondly\u{0020}a\u{0020}driver.\"\u{0020}", "0", "0", "0", "0", 12015, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}礼堂之内，众人满怀期待，等待着多瑙的公主上台演讲。\u{1000}\u{1000}可是，当钟声响起，舞台上并没有出现少女的身影。\u{1000}\u{1000}人们面面相觑，就在这时礼堂外的一声惊呼打破了这份尴尬。\u{1000}\u{1000}人们跑出礼堂，看到了毕生难忘的场面。\u{1000}\u{1000}薇丝帕尔那巨大洁白的躯干如同罗马柱一般立于礼堂之上，\u{1000}\u{1000}一头葡萄酒色的长发宛若瀑布从数十米高的肩膀上倾泻而下。\u{1000}\u{1000}以礼堂的屋顶为舞台，少女绷起足尖，向着小小的来客行礼。\u{1000}\u{1000}\"薇丝帕尔·特蕾莎·赫尔斯塔尔，首先是一名驾驶员，其次才是贵族。\""},
[621600] = {621600, 0, "[Name]\u{0020}Salati\u{0020}Sony\n[B-Day]\u{0020}March\u{0020}26\n[Compatability\u{0020}Rate]\u{0020}86％\n[Height]\u{0020}40m\n[Squad]\u{0020}Imperial\u{0020}Strings\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Listening\u{0020}to\u{0020}old\u{0020}records", "0", "0", "0", "0", 12016, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}萨拉蒂·索尼\n[B-Day]\u{1000}3月26日\n[幻化核心适格率]\u{1000}86％\n[Height]\u{1000}40m\n[部队]\u{1000}绞皇\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}听老旧唱片"},
[621601] = {621601, 100, "\u{0020}Salati\u{0020}Sony,\u{0020}the\u{0020}most\u{0020}famous\u{0020}driver\u{0020}of\u{0020}the\u{0020}Imperial\u{0020}Strings,\u{0020}is\u{0020}also\u{0020}a\u{0020}star\u{0020}member\u{0020}of\u{0020}the\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}band.\u{0020}After\u{0020}only\u{0020}a\u{0020}few\u{0020}small\u{0020}concerts,\u{0020}they\u{0020}gained\u{0020}a\u{0020}large\u{0020}number\u{0020}of\u{0020}fans,\u{0020}and\u{0020}often\u{0020}people\u{0020}disregarded\u{0020}the\u{0020}control\u{0020}of\u{0020}AEGIS\u{0020}and\u{0020}took\u{0020}risks\u{0020}to\u{0020}sneak\u{0020}into\u{0020}the\u{0020}driver's\u{0020}base\u{0020}just\u{0020}to\u{0020}see\u{0020}Salati.\u{0020}And\u{0020}Salati's\u{0020}personality\u{0020}is\u{0020}as\u{0020}warm\u{0020}as\u{0020}her\u{0020}long\u{0020}red\u{0020}hair,\u{0020}and\u{0020}she\u{0020}is\u{0020}very\u{0020}excited\u{0020}to\u{0020}see\u{0020}every\u{0020}fan,\u{0020}which\u{0020}to\u{0020}a\u{0020}certain\u{0020}extent\u{0020}exacerbates\u{0020}the\u{0020}fanaticism\u{0020}of\u{0020}fans.\n\nIf\u{0020}someone\u{0020}asks\u{0020}why\u{0020}those\u{0020}fans\u{0020}are\u{0020}so\u{0020}fanatically\u{0020}fond\u{0020}of\u{0020}Salati,\u{0020}they\u{0020}will\u{0020}mostly\u{0020}reply\u{0020}that\u{0020}it\u{0020}is\u{0020}because\u{0020}they\u{0020}are\u{0020}impressed\u{0020}by\u{0020}Salati's\u{0020}performance.\u{0020}But\u{0020}in\u{0020}fact,\u{0020}everyone\u{0020}knows\u{0020}in\u{0020}their\u{0020}hearts\u{0020}that\u{0020}Salati's\u{0020}outstanding\u{0020}appearance\u{0020}is\u{0020}the\u{0020}main\u{0020}reason.\n\nSuch\u{0020}an\u{0020}outstanding\u{0020}Salati\u{0020}Sony\u{0020}not\u{0020}only\u{0020}fascinates\u{0020}human\u{0020}fans\u{0020}on\u{0020}the\u{0020}stage\u{0020}but\u{0020}also\u{0020}drives\u{0020}the\u{0020}Sins\u{0020}crazy\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}Few\u{0020}Sins\u{0020}can\u{0020}resist\u{0020}her\u{0020}sound\u{0020}waves.\n\nAlthough\u{0020}the\u{0020}Sin\u{0020}was\u{0020}eliminated\u{0020}quickly\u{0020}in\u{0020}the\u{0020}battle\u{0020}with\u{0020}Salati's\u{0020}participation,\u{0020}I\u{0020}feel\u{0020}that\u{0020}if\u{0020}her\u{0020}attack\u{0020}lasted\u{0020}a\u{0020}little\u{0020}longer,\u{0020}perhaps\u{0020}the\u{0020}rest\u{0020}of\u{0020}us,\u{0020}including\u{0020}me,\u{0020}would\u{0020}also\u{0020}be\u{0020}eliminated.", "0", "0", "0", "0", 12016, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}萨拉蒂·索尼，绞皇小队最出名的驾驶员，也是\"爱露达死亡深渊\"乐队的明星成员。仅通过几次小型的演唱会就收获了一大票的粉丝，经常有人不顾艾吉斯的管控，铤而走险潜入驾驶员的基地只为了看萨拉蒂一眼。而萨拉蒂的性格也像她火红的长发一般热烈，对每个粉丝都抱有十分的热情去接待，这在一定程度上加剧了粉丝的狂热。\n\u{1000}\u{1000}如果有人问起那些粉丝为什么如此狂热地喜欢萨拉蒂，他们多半会回答说是因为被萨拉蒂的演奏所折服。但是其实大家心里都明白，萨拉蒂出众的外貌才是最主要的原因。\n\u{1000}\u{1000}如此优秀的萨拉蒂·索尼不但在舞台上让人类粉丝们痴迷，在战场中同样让原罪们感到疯狂，鲜少有原罪能够抵抗她的音浪。\n\u{1000}\u{1000}\"虽然有萨拉蒂参加的战斗，原罪很快就被消灭，但是我感觉如果她的攻击再多持续一会儿，恐怕我在内的其他人也要被消灭了。\""},
[621602] = {621602, 500, "\u{0020}\u{0020}The\u{0020}singing\u{0020}style\u{0020}of\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}is\u{0020}very\u{0020}aggressive.\n\n\"The\u{0020}roar\u{0020}from\u{0020}hell\"\u{0020}is\u{0020}the\u{0020}best\u{0020}summary\u{0020}of\u{0020}its\u{0020}singing\u{0020}style.\u{0020}Many\u{0020}people\u{0020}said\u{0020}they\u{0020}couldn't\u{0020}stand\u{0020}it,\u{0020}but\u{0020}after\u{0020}a\u{0020}period\u{0020}of\u{0020}time\u{0020}without\u{0020}listening,\u{0020}they\u{0020}felt\u{0020}uncomfortable\u{0020}all\u{0020}over.\n\nListening\u{0020}to\u{0020}their\u{0020}music\u{0020}gives\u{0020}an\u{0020}exciting\u{0020}experience\u{0020}when\u{0020}facing\u{0020}death,\u{0020}and\u{0020}one\u{0020}can\u{0020}feel\u{0020}the\u{0020}rush\u{0020}of\u{0020}adrenaline.\n\nOver\u{0020}time,\u{0020}the\u{0020}number\u{0020}of\u{0020}fans\u{0020}has\u{0020}increased.\u{0020}Like\u{0020}ordinary\u{0020}fan\u{0020}groups,\u{0020}they\u{0020}were\u{0020}also\u{0020}curious\u{0020}about\u{0020}the\u{0020}backgrounds\u{0020}of\u{0020}several\u{0020}members\u{0020}of\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\".\u{0020}Especially\u{0020}for\u{0020}Salati's\u{0020}background\u{0020}-\u{0020}with\u{0020}such\u{0020}a\u{0020}lovely\u{0020}appearance\u{0020}and\u{0020}an\u{0020}exceptionally\u{0020}pleasant\u{0020}voice,\u{0020}it's\u{0020}a\u{0020}pity\u{0020}not\u{0020}to\u{0020}be\u{0020}an\u{0020}idol.\n\nBut\u{0020}everyone\u{0020}has\u{0020}their\u{0020}own\u{0020}little\u{0020}secrets,\u{0020}and\u{0020}Salati\u{0020}Sony's\u{0020}secret\u{0020}is\u{0020}that\u{0020}she\u{0020}has\u{0020}the\u{0020}strange\u{0020}disease\u{0020}of\u{0020}being\u{0020}tone-deaf\u{0020}when\u{0020}singing.\n\n\"Incomplete\u{0020}muscular\u{0020}development\u{0020}of\u{0020}the\u{0020}vocal\u{0020}cords\"\u{0020}is\u{0020}a\u{0020}disease\u{0020}that\u{0020}is\u{0020}not\u{0020}uncommon,\u{0020}but\u{0020}has\u{0020}a\u{0020}variety\u{0020}of\u{0020}symptoms.\u{0020}In\u{0020}Salati's\u{0020}body,\u{0020}the\u{0020}symptoms\u{0020}are\u{0020}that\u{0020}although\u{0020}she\u{0020}usually\u{0020}has\u{0020}no\u{0020}problem\u{0020}speaking,\u{0020}and\u{0020}even\u{0020}has\u{0020}a\u{0020}very\u{0020}nice\u{0020}voice,\u{0020}when\u{0020}it\u{0020}comes\u{0020}to\u{0020}singing,\u{0020}she\u{0020}is\u{0020}often\u{0020}out\u{0020}of\u{0020}tune.\u{0020}This\u{0020}was\u{0020}a\u{0020}painful\u{0020}to\u{0020}Salati,\u{0020}and\u{0020}even\u{0020}made\u{0020}her\u{0020}give\u{0020}up\u{0020}her\u{0020}musical\u{0020}dream\u{0020}for\u{0020}a\u{0020}while.\n\nHowever,\u{0020}there\u{0020}is\u{0020}more\u{0020}than\u{0020}one\u{0020}path\u{0020}to\u{0020}a\u{0020}dream,\u{0020}and\u{0020}there\u{0020}is\u{0020}more\u{0020}than\u{0020}one\u{0020}way\u{0020}to\u{0020}play\u{0020}music.\u{0020}On\u{0020}the\u{0020}road\u{0020}of\u{0020}refuge\u{0020}and\u{0020}exile\u{0020}caused\u{0020}by\u{0020}Sin,\u{0020}after\u{0020}seeing\u{0020}her\u{0020}friend\u{0020}Ashlica\u{0020}playing\u{0020}passionately\u{0020}in\u{0020}the\u{0020}heavy\u{0020}rain,\u{0020}the\u{0020}fire\u{0020}of\u{0020}music\u{0020}in\u{0020}Salati's\u{0020}heart\u{0020}was\u{0020}reignited,\u{0020}and\u{0020}she\u{0020}decided\u{0020}to\u{0020}look\u{0020}for\u{0020}another\u{0020}way\u{0020}of\u{0020}playing.\n\nWhen\u{0020}Ashlica\u{0020}said\u{0020}she\u{0020}wanted\u{0020}to\u{0020}form\u{0020}a\u{0020}band\u{0020}and\u{0020}extended\u{0020}an\u{0020}olive\u{0020}branch\u{0020}to\u{0020}Salati,\u{0020}she\u{0020}readily\u{0020}accepted\u{0020}without\u{0020}hesitation\u{0020}or\u{0020}fear.\u{0020}\"I\u{0020}will\u{0020}accept\u{0020}my\u{0020}disease\u{0020}and\u{0020}my\u{0020}dream.\u{0020}Thank\u{0020}you,\u{0020}Ashlica,\u{0020}for\u{0020}letting\u{0020}me\u{0020}understand\u{0020}that\u{0020}the\u{0020}real\u{0020}enemy\u{0020}is\u{0020}not\u{0020}the\u{0020}imperfection\u{0020}of\u{0020}the\u{0020}voice\u{0020}but\u{0020}self-abandonment.\"\u{0020}", "0", "0", "0", "0", 12016, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}\"爱露达死亡深渊\"的演唱风格是十分激进的。\u{1000}\u{1000}\"如同来自地狱的轰鸣\"是对其演唱风格的最好概括，很多人在听了之后纷纷表示接受不了，但是过一段时间不听又感觉浑身难受。\u{1000}\u{1000}\"听她们的音乐有一种面对死亡时的刺激体验，能感受到肾上腺素飙升的感觉。\"\u{1000}\u{1000}久而久之，乐队的粉丝数量就增加了上来。如同一般的粉丝团体一样，他们私下里也对\"爱露达死亡深渊\"的几位成员的身世产生了好奇。特别是对于萨拉蒂的身世——如此可爱的外表，异常动听的声线，不做偶像真是可惜了。\u{1000}\u{1000}但是每个人都有自己的小秘密，而萨拉蒂·索尼的秘密就是她患有唱歌五音不全的怪病。\u{1000}\u{1000}\"声带肌肉发育不完全\"，一种不算罕见，但是存在多种病状的疾病。在萨拉蒂身上就病状表现为虽然平时说话完全没有问题，甚至拥有非常好听的声线，但是一到唱歌的时候就无法正常地发出该发出的音调，经常跑调。这对萨拉蒂来说是沉痛的打击，甚至一度让她放弃了音乐梦。\u{1000}\u{1000}不过通往梦想的路不止一条，演奏音乐的方式也不止一种。在那因原罪导致的逃难流亡的路上，看到好友艾希丽卡在大雨中纵情演奏之后，萨拉蒂内心的音乐之火也被重新点燃，她决定去找寻另一种演奏的方式。\u{1000}\u{1000}当艾希丽卡说要成立乐队并向萨拉蒂抛出橄榄枝时，她欣然接受，没有犹豫也没有惧怕。\u{1000}\u{1000}\"我将接受我的疾病，我的梦想，谢谢艾希丽卡让我明白了真正的敌人不是声音的残缺而是自我的放弃。\""},
[621603] = {621603, 1000, "\u{0020}The\u{0020}original\u{0020}intention\u{0020}of\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}was\u{0020}to\u{0020}inspire\u{0020}the\u{0020}refugees,\u{0020}and\u{0020}its\u{0020}core\u{0020}concept\u{0020}later\u{0020}evolved\u{0020}into\u{0020}protecting\u{0020}ordinary\u{0020}people\u{0020}from\u{0020}Sin.\u{0020}Therefore,\u{0020}it\u{0020}was\u{0020}a\u{0020}natural\u{0020}thing\u{0020}for\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}band\u{0020}to\u{0020}join\u{0020}AEGIS.\n\nAlthough\u{0020}Salati\u{0020}is\u{0020}not\u{0020}good\u{0020}at\u{0020}singing,\u{0020}she\u{0020}has\u{0020}a\u{0020}good\u{0020}sense\u{0020}of\u{0020}music\u{0020}and\u{0020}can\u{0020}control\u{0020}the\u{0020}pitch\u{0020}well\u{0020}enough\u{0020}to\u{0020}convince\u{0020}the\u{0020}most\u{0020}demanding\u{0020}music\u{0020}critics.\u{0020}So\u{0020}in\u{0020}the\u{0020}band,\u{0020}Salati\u{0020}holds\u{0020}a\u{0020}special\u{0020}position\u{0020}-\u{0020}the\u{0020}band\u{0020}DJ,\u{0020}adjusting\u{0020}the\u{0020}sound\u{0020}to\u{0020}make\u{0020}the\u{0020}band's\u{0020}performance\u{0020}better.\n\nIf\u{0020}the\u{0020}entire\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}band\u{0020}is\u{0020}an\u{0020}off-road\u{0020}vehicle\u{0020}traveling\u{0020}through\u{0020}hell,\u{0020}Salati\u{0020}is\u{0020}the\u{0020}one\u{0020}who\u{0020}takes\u{0020}the\u{0020}wheel,\u{0020}smoothly\u{0020}leading\u{0020}the\u{0020}team\u{0020}to\u{0020}its\u{0020}destination\u{0020}after\u{0020}the\u{0020}captain\u{0020}Ashlica\u{0020}determines\u{0020}the\u{0020}direction.\n\nThis\u{0020}heavy\u{0020}off-road\u{0020}vehicle\u{0020}named\u{0020}\"Elda's\u{0020}Abyss\u{0020}of\u{0020}Death\"\u{0020}was\u{0020}galloping\u{0020}in\u{0020}hell\u{0020}while\u{0020}crushing\u{0020}one\u{0020}demon\u{0020}called\u{0020}\"Sin\"\u{0020}after\u{0020}another.\u{0020}It\u{0020}enabled\u{0020}the\u{0020}originally\u{0020}just\u{0020}a\u{0020}somewhat\u{0020}special\u{0020}newcomer\u{0020}team\u{0020}to\u{0020}rapidly\u{0020}rise\u{0020}to\u{0020}become\u{0020}a\u{0020}\"star\u{0020}team\"\u{0020}well-known\u{0020}at\u{0020}the\u{0020}headquarters.\n\nHowever,\u{0020}no\u{0020}matter\u{0020}how\u{0020}highly\u{0020}the\u{0020}outside\u{0020}world\u{0020}praises\u{0020}them,\u{0020}for\u{0020}Salati,\u{0020}the\u{0020}original\u{0020}intention\u{0020}of\u{0020}protecting\u{0020}ordinary\u{0020}people,\u{0020}eliminating\u{0020}Sin,\u{0020}and\u{0020}pursuing\u{0020}music\u{0020}has\u{0020}never\u{0020}changed.", "0", "0", "0", "0", 12016, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}\"爱露达死亡深渊\"成立的初衷是为了鼓舞逃难的人民，其核心的理念随后进化为从原罪手中保护普通人。所以乐队的成员加入艾吉斯也是顺水推舟的事。\u{1000}\u{1000}萨拉蒂虽然不善歌唱，但是她的音感很好，对于音调的把控可以让最苛刻的音乐评判家诚服。所以在乐队中，萨拉蒂担任了一个特殊职位——乐队DJ，通过调音来让乐队的演奏达到更棒的效果。\u{1000}\u{1000}如果说整个\"爱露达死亡深渊\"乐队是一辆在地狱中穿行的越野车，那萨拉蒂就是把控方向盘的人，在队长艾希丽卡确定方向后平稳地带领队伍前往目的地。\u{1000}\u{1000}这辆名为\"爱露达死亡深渊\"的重型越野车在地狱驰骋的同时，还碾碎了一只又一只被称为\"原罪\"的恶魔。让本来只是一支有点特殊的新人队伍迅速攀升成在总部赫赫有名的\"明星小队\"。\u{1000}\u{1000}不过无论外界对她们有多高的赞誉，对于萨拉蒂来说保护普通人，消灭原罪以及追求音乐的初心从来没有改变过。"},
[621604] = {621604, 2000, "\u{0020}\u{0020}The\u{0020}silent\u{0020}night\u{0020}suddenly\u{0020}roared,\n\nSin\u{0020}in\u{0020}the\u{0020}ruins\u{0020}fell\u{0020}in\u{0020}large\u{0020}numbers.\n\nIt\u{0020}turned\u{0020}out\u{0020}to\u{0020}be\u{0020}the\u{0020}Requiem\u{0020}from\u{0020}the\u{0020}Abyss.\n\nPull\u{0020}these\u{0020}murderous\u{0020}evil\u{0020}ghosts\u{0020}into\u{0020}hell.\n\n\"The\u{0020}next\u{0020}song\u{0020}is\u{0020}an\u{0020}unreleased\u{0020}new\u{0020}song,\u{0020}Navigator,\u{0020}enjoy\u{0020}it...\u{0020}Eh?\u{0020}Where's\u{0020}Navigator?\"\n\nSalati\u{0020}didn't\u{0020}realize\u{0020}that\u{0020}the\u{0020}music\u{0020}just\u{0020}now\u{0020}not\u{0020}only\u{0020}pulled\u{0020}Sin\u{0020}into\u{0020}hell,\n\nIt\u{0020}almost\u{0020}sent\u{0020}the\u{0020}navigator\u{0020}to\u{0020}heaven.", "0", "0", "0", "0", 12016, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}寂静的夜晚忽然响起轰鸣，\u{1000}\u{1000}废墟中的原罪成片地倒下。\u{1000}\u{1000}原来那是来自深渊的安魂曲，\u{1000}\u{1000}要将这些杀人的恶鬼拉入地狱。\u{1000}\u{1000}\"下一首是未公开的新歌，领航好好欣赏吧……诶？领航呢？\"\u{1000}\u{1000}萨拉蒂没意识到，刚才的音乐不但把原罪拉入了地狱，\u{1000}\u{1000}还差点把脚边屋顶上的领航送入天堂。"},
[621700] = {621700, 0, "【Name】Suzu\n【B-Day】February\u{0020}6\n【Compatibility\u{0020}Rate】91％\n【Height】29m\n【Squad】Dunscaith\n【Affiliation】None\n【Interest】Companion's\u{0020}trust\u{0020}and\u{0020}praise", "0", "0", "0", "0", 12017, "0", "0", "0", "0", 0, 1, "0", "0", "0"},
[621701] = {621701, 100, "When\u{0020}will\u{0020}the\u{0020}navigator\u{0020}come?\n\nThe\u{0020}closer\u{0020}it\u{0020}gets\u{0020}to\u{0020}summer,\u{0020}such\u{0020}thoughts\u{0020}keep\u{0020}surfacing\u{0020}in\u{0020}consciousness\u{0020}like\u{0020}bubbles\u{0020}in\u{0020}a\u{0020}spring\u{0020}and\u{0020}then\u{0020}burst.\n\nA\u{0020}few\u{0020}days\u{0020}ago,\u{0020}when\u{0020}everyone\u{0020}including\u{0020}Tian\u{0020}Hua\u{0020}went\u{0020}on\u{0020}vacation\u{0020}to\u{0020}the\u{0020}beach\u{0020}together,\u{0020}I\u{0020}was\u{0020}still\u{0020}wearing\u{0020}the\u{0020}kind\u{0020}of\u{0020}one-piece\u{0020}swimsuit\u{0020}for\u{0020}children.\n\nBefore\u{0020}this,\u{0020}before\u{0020}encountering\u{0020}the\u{0020}navigator,\u{0020}Suzu\u{0020}had\u{0020}always\u{0020}been\u{0020}wearing\u{0020}a\u{0020}children's\u{0020}swimsuit\u{0020}and\u{0020}she\u{0020}also\u{0020}felt\u{0020}that\u{0020}there\u{0020}was\u{0020}no\u{0020}problem\u{0020}with\u{0020}it.\n\n\"Well...\u{0020}Choose\u{0020}this\u{0020}one\u{0020}again.\u{0020}Buy\u{0020}both\u{0020}of\u{0020}them\u{0020}together!\"\n\nBut\u{0020}this\u{0020}year,\u{0020}Suzu\u{0020}prepared\u{0020}two\u{0020}swimsuits\u{0020}for\u{0020}this\u{0020}summer.\n\nPerhaps\u{0020}she\u{0020}didn't\u{0020}notice\u{0020}her\u{0020}own\u{0020}intention\u{0020}and\u{0020}straightforwardly,\u{0020}instinctively\u{0020}bought\u{0020}a\u{0020}style\u{0020}of\u{0020}swimsuit\u{0020}completely\u{0020}opposite\u{0020}to\u{0020}the\u{0020}previous\u{0020}one.\u{0020}Moreover,\u{0020}the\u{0020}gap\u{0020}between\u{0020}the\u{0020}two...\u{0020}seemed\u{0020}a\u{0020}bit\u{0020}frightening.\u{0020}Her\u{0020}captain\u{0020}carefully\u{0020}checked\u{0020}it\u{0020}once,\u{0020}repeatedly\u{0020}asked\u{0020}for\u{0020}Suzu's\u{0020}opinion,\u{0020}and\u{0020}then\u{0020}nervously\u{0020}paid\u{0020}the\u{0020}bill.\u{0020}After\u{0020}hesitating\u{0020}and\u{0020}deliberating\u{0020}for\u{0020}a\u{0020}moment,\u{0020}she\u{0020}asked\u{0020}Suzu\u{0020}to\u{0020}pick\u{0020}a\u{0020}sunscreen\u{0020}windbreaker.", "0", "0", "0", "0", 12017, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[621702] = {621702, 500, "The\u{0020}\"desire\u{0020}to\u{0020}express\"\u{0020}in\u{0020}summer\u{0020}seems\u{0020}to\u{0020}have\u{0020}risen\u{0020}to\u{0020}the\u{0020}same\u{0020}level\u{0020}as\u{0020}the\u{0020}wish\u{0020}of\u{0020}\"becoming\u{0020}a\u{0020}scientist\",\u{0020}and\u{0020}the\u{0020}day\u{0020}agreed\u{0020}with\u{0020}navigator\u{0020}is\u{0020}approaching\u{0020}step\u{0020}by\u{0020}step.\n\nAnd\u{0020}that\u{0020}piece\u{0020}of\u{0020}clothing\u{0020}which\u{0020}was\u{0020}evaluated\u{0020}by\u{0020}the\u{0020}team\u{0020}leader\u{0020}as\u{0020}\"reckless\u{0020}and\u{0020}presumptuous\"...\u{0020}Suzu\u{0020}has\u{0020}only\u{0020}worn\u{0020}it\u{0020}at\u{0020}home\u{0020}for\u{0020}herself\u{0020}to\u{0020}see.\n\n———\u{0020}\"Why\u{0020}-\u{0020}Suzu,\u{0020}aren't\u{0020}you\u{0020}wearing\u{0020}that\u{0020}specially\u{0020}bought\u{0020}dress?\"\u{0020}Captain\u{0020}Caihua\u{0020}of\u{0020}Tian\u{0020}Hua\u{0020}was\u{0020}surprised\u{0020}that\u{0020}Suzu\u{0020}wasn't\u{0020}wearing\u{0020}the\u{0020}imagined\u{0020}dress.\n\n\"I\u{0020}want\u{0020}to\u{0020}wear\u{0020}it\u{0020}for\u{0020}navigator!\"\u{0020}At\u{0020}this\u{0020}moment,\u{0020}the\u{0020}ultimate\u{0020}big\u{0020}fool\u{0020}said\u{0020}this\u{0020}sentence\u{0020}loudly\u{0020}without\u{0020}any\u{0020}hesitation\u{0020}or\u{0020}scruple.\n\n\"…\"\u{0020}———\u{0020}A\u{0020}good\u{0020}day\u{0020}is\u{0020}just\u{0020}around\u{0020}the\u{0020}corner,\u{0020}but\u{0020}Suzu\u{0020}has\u{0020}encountered\u{0020}a\u{0020}greater\u{0020}crisis\u{0020}in\u{0020}her\u{0020}life.\n\nBecause\u{0020}she\u{0020}was\u{0020}too\u{0020}addicted\u{0020}to\u{0020}enjoying\u{0020}the\u{0020}summer\u{0020}and\u{0020}the\u{0020}beach\u{0020}with\u{0020}her\u{0020}teammates,\u{0020}the\u{0020}skin\u{0020}exposed\u{0020}outside\u{0020}of\u{0020}her\u{0020}was\u{0020}slightly\u{0020}tanned\u{0020}a\u{0020}little.\n\n\"Oh,\u{0020}there's\u{0020}only\u{0020}a\u{0020}little\u{0020}difference...\u{0020}Can't\u{0020}you\u{0020}tell?\"\n\n\"It\u{0020}doesn't\u{0020}matter.\u{0020}I,\u{0020}the\u{0020}genius,\u{0020}will\u{0020}surely\u{0020}recover.\u{0020}There\u{0020}are\u{0020}still\u{0020}three\u{0020}days...\"\n\nThe\u{0020}answer\u{0020}is\u{0020}impossible.\n\n\"Put\u{0020}it\u{0020}on\u{0020}for\u{0020}a\u{0020}moment\u{0020}and\u{0020}have\u{0020}a\u{0020}look.\"\n\nThis\u{0020}is\u{0020}fine!\u{0020}I'm\u{0020}such\u{0020}a\u{0020}genius!\u{0020}There's\u{0020}no\u{0020}influence\u{0020}at\u{0020}all!\n\nNot\u{0020}knowing\u{0020}what\u{0020}mental\u{0020}journey\u{0020}she\u{0020}has\u{0020}gone\u{0020}through,\u{0020}in\u{0020}any\u{0020}case,\u{0020}Suzu\u{0020}quickly\u{0020}cheered\u{0020}up...\u{0020}As\u{0020}long\u{0020}as\u{0020}the\u{0020}result\u{0020}is\u{0020}good.\n\nThere\u{0020}is\u{0020}still\u{0020}one\u{0020}day\u{0020}until\u{0020}the\u{0020}agreed\u{0020}day.\n\nSuzu\u{0020}was\u{0020}affected\u{0020}by\u{0020}Skadi's\u{0020}[Synesthesia\u{0020}Out\u{0020}of\u{0020}Control]\u{0020}rampage\u{0020}and\u{0020}fell\u{0020}into\u{0020}a\u{0020}coma.\n\nIn\u{0020}Skadi's\u{0020}world,\u{0020}two\u{0020}wishes,\u{0020}\"becoming\u{0020}a\u{0020}scientist\"\u{0020}and\u{0020}\"the\u{0020}desire\u{0020}to\u{0020}express\u{0020}to\u{0020}the\u{0020}navigator\",\u{0020}were\u{0020}fulfilled.\n\n\"Fox\u{0020}ears...\u{0020}are\u{0020}real!\"\u{0020}\"Ah!\u{0020}The\u{0020}tail\u{0020}is\u{0020}also\u{0020}real?!\"\u{0020}\"However...\u{0020}Is\u{0020}Suzu,\u{0020}who\u{0020}becomes\u{0020}a\u{0020}scientist,\u{0020}still\u{0020}the\u{0020}same\u{0020}Suzu?\"", "0", "0", "0", "0", 12017, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[621703] = {621703, 1000, "\"navigator.\"\u{0020}\"Perhaps\u{0020}the\u{0020}me\u{0020}who\u{0020}wrote\u{0020}this\u{0020}has\u{0020}already\u{0020}vanished.\"\n\n\"\u{0020}In\u{0020}reality,\u{0020}that\u{0020}me...\u{0020}I'm\u{0020}afraid\u{0020}I'm\u{0020}still\u{0020}looking\u{0020}forward\u{0020}to\u{0020}the\u{0020}day\u{0020}when\u{0020}I'll\u{0020}wear\u{0020}a\u{0020}swimsuit\u{0020}for\u{0020}you\u{0020}to\u{0020}see.\u{0020}\"\n\n\"Of\u{0020}course,\u{0020}if\u{0020}you\u{0020}find\u{0020}this\u{0020}letter\u{0020}in\u{0020}advance,\u{0020}please\u{0020}pretend\u{0020}you\u{0020}didn't\u{0020}see\u{0020}it.\"\u{0020}\"Even\u{0020}for\u{0020}a\u{0020}super-genius\u{0020}like\u{0020}me...\u{0020}If\u{0020}someone\u{0020}sees\u{0020}something\u{0020}like\u{0020}this\u{0020}suicide\u{0020}note,\u{0020}I\u{0020}would\u{0020}be\u{0020}shy.\"\n\n\"Although\u{0020}I\u{0020}want\u{0020}to\u{0020}explain\u{0020}clearly\u{0020}to\u{0020}you\u{0020}face\u{0020}to\u{0020}face,\u{0020}but\u{0020}only\u{0020}when\u{0020}I'm\u{0020}alone\u{0020}can\u{0020}I\u{0020}slowly\u{0020}and\u{0020}methodically\u{0020}organize\u{0020}my\u{0020}thoughts\u{0020}and\u{0020}tell\u{0020}you\u{0020}clearly.\"\n\n\"You\u{0020}must\u{0020}ask,\u{0020}why\u{0020}do\u{0020}I\u{0020}have\u{0020}to\u{0020}say\u{0020}goodbye\u{0020}to\u{0020}you?\"\u{0020}\"Because\u{0020}when\u{0020}I\u{0020}start\u{0020}[thinking]\u{0020}because\u{0020}of\u{0020}my\u{0020}wish,\u{0020}I'm\u{0020}no\u{0020}longer\u{0020}Suzu.\"\n\n\"......Not\u{0020}that\u{0020}one.\u{0020}In\u{0020}reality,\u{0020}the\u{0020}Suzu\u{0020}you\u{0020}are\u{0020}familiar\u{0020}with\"\n\nWhen\u{0020}this\u{0020}journey\u{0020}ends,\u{0020}my\u{0020}wish\u{0020}will\u{0020}end\u{0020}and\u{0020}I\u{0020}will\u{0020}disappear.\n\n\"I'm\u{0020}glad\u{0020}I\u{0020}met\u{0020}you,\u{0020}navigator.\"\u{0020}\"…\"\u{0020}\"I,\u{0020}apart\u{0020}from\u{0020}becoming\u{0020}a\u{0020}science\u{0020}officer,\u{0020}have\u{0020}thought\u{0020}a\u{0020}lot...\u{0020}For\u{0020}instance,\u{0020}I\u{0020}am\u{0020}Suzu,\u{0020}but\u{0020}not\u{0020}Suzu.\"\n\nFor\u{0020}instance,\u{0020}the\u{0020}meaning\u{0020}of\u{0020}my\u{0020}existence.\u{0020}For\u{0020}instance,\u{0020}should\u{0020}I\u{0020}stay,\u{0020}can\u{0020}I\u{0020}survive,\u{0020}is\u{0020}there\u{0020}anyone\u{0020}who\u{0020}needs\u{0020}me?\u{0020}So\u{0020}when\u{0020}the\u{0020}princess\u{0020}asked\u{0020}me\u{0020}for\u{0020}help,\u{0020}I\u{0020}agreed\u{0020}without\u{0020}hesitation.\u{0020}The\u{0020}last\u{0020}question\u{0020}is,\u{0020}should\u{0020}I\u{0020}seize\u{0020}the\u{0020}happiness\u{0020}that\u{0020}belongs\u{0020}to\u{0020}Suzu?\u{0020}Suzu\u{0020}is\u{0020}so\u{0020}happy.\u{0020}It\u{0020}is\u{0020}because\u{0020}of\u{0020}her\u{0020}parents,\u{0020}the\u{0020}second\u{0020}mother,\u{0020}Tian\u{0020}Hua's\u{0020}companions...\u{0020}It\u{0020}is\u{0020}their\u{0020}kindness\u{0020}that\u{0020}carried\u{0020}Suzu\u{0020}to\u{0020}grow\u{0020}up.\u{0020}If...\u{0020}I\u{0020}replace\u{0020}Suzu,\u{0020}wouldn't\u{0020}that\u{0020}be\u{0020}doing\u{0020}the\u{0020}same\u{0020}thing\u{0020}as\u{0020}that\u{0020}Sin?\u{0020}The\u{0020}wonderful\u{0020}things\u{0020}I\u{0020}inherited\u{0020}from\u{0020}Suzu...\u{0020}...\u{0020}Even\u{0020}the'soul'\u{0020}of\u{0020}a\u{0020}'person'\u{0020}will\u{0020}be\u{0020}destroyed.\u{0020}So\u{0020}-\u{0020}I\u{0020}will\u{0020}give\u{0020}the\u{0020}answer\u{0020}here,\u{0020}the\u{0020}reason\u{0020}why\u{0020}a\u{0020}person\u{0020}is\u{0020}a\u{0020}person.\u{0020}Farewell.\u{0020}...\u{0020}I\u{0020}hope\u{0020}that\u{0020}when\u{0020}we\u{0020}part,\u{0020}I\u{0020}can\u{0020}bid\u{0020}you\u{0020}farewell\u{0020}properly.I\u{0020}only\u{0020}have\u{0020}you\u{0020}now...", "0", "0", "0", "0", 12017, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
