[621801] = {621801, 100, "\u{3000}\u{3000}There\u{0020}are\u{0020}not\u{0020}many\u{0020}people\u{0020}who\u{0020}become\u{0020}drivers\u{0020}with\u{0020}strange\u{0020}purposes,\u{0020}but\u{0020}Sisha\u{0020}is\u{0020}also\u{0020}a\u{0020}particularly\u{0020}impressive\u{0020}one\u{0020}among\u{0020}them.\"To\u{0020}make\u{0020}this\u{0020}huge\u{0020}body\u{0020}a\u{0020}bridge\u{0020}for\u{0020}people\",\u{0020}at\u{0020}first\u{0020}hearing,\u{0020}it\u{0020}really\u{0020}makes\u{0020}people\u{0020}mistakenly\u{0020}think\u{0020}that\u{0020}she\u{0020}means\u{0020}it\u{0020}literally\u{0020}and\u{0020}physically.\u{0020}After\u{0020}all,\u{0020}in\u{0020}the\u{0020}AEGIS\u{0020}interview\u{0020}process,\u{0020}such\u{0020}\"empty\u{0020}talk\"\u{0020}has\u{0020}long\u{0020}been\u{0020}out\u{0020}of\u{0020}fashion.\u{0020}However,\u{0020}Shisha's\u{0020}words\u{0020}contained\u{0020}no\u{0020}falsehood,\u{0020}and\u{0020}the\u{0020}interviewers\u{0020}soon\u{0020}understood\u{0020}this.\u{0020}\n\u{3000}\u{3000}Shisha\u{0020}is\u{0020}an\u{0020}optimist\u{0020}among\u{0020}optimists,\u{0020}with\u{0020}an\u{0020}enthusiastic\u{0020}personality,\u{0020}proactive\u{0020}at\u{0020}work,\u{0020}friendly\u{0020}towards\u{0020}others,\u{0020}and\u{0020}has\u{0020}a\u{0020}considerable\u{0020}eligibility\u{0020}rate\u{0020}for\u{0020}the\u{0020}Transformation\u{0020}Core.\u{0020}AEGIS\u{0020}has\u{0020}no\u{0020}reason\u{0020}to\u{0020}reject\u{0020}such\u{0020}a\u{0020}talent.\u{0020}After\u{0020}officially\u{0020}becoming\u{0020}a\u{0020}driver,\u{0020}the\u{0020}knowledge\u{0020}reserve\u{0020}as\u{0020}a\u{0020}bridge\u{0020}designer\u{0020}also\u{0020}enabled\u{0020}Shisha\u{0020}to\u{0020}contribute\u{0020}to\u{0020}some\u{0020}fortifications.\u{0020}Of\u{0020}course,\u{0020}more\u{0020}importantly,\u{0020}her\u{0020}sunny,\u{0020}upward,\u{0020}and\u{0020}never-give-up\u{0020}personality\u{0020}is\u{0020}quite\u{0020}infectious\u{0020}in\u{0020}the\u{0020}long\u{0020}war\u{0020}against\u{0020}Sin.", "0", "0", "0", "0", 12018, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[621802] = {621802, 500, "\u{3000}\u{3000}If\u{0020}one\u{0020}must\u{0020}find\u{0020}the\u{0020}source\u{0020}of\u{0020}Shisha's\u{0020}love\u{0020}for\u{0020}bridges\u{0020}and\u{0020}her\u{0020}optimism\u{0020}towards\u{0020}life,\u{0020}it\u{0020}can\u{0020}probably\u{0020}be\u{0020}traced\u{0020}back\u{0020}to\u{0020}her\u{0020}father.\u{0020}This\u{0020}family\u{0020}is\u{0020}from\u{0020}the\u{0020}\"City\u{0020}of\u{0020}a\u{0020}Thousand\u{0020}Bridges\",\u{0020}Poynred.\u{0020}Although\u{0020}the\u{0020}father\u{0020}is\u{0020}not\u{0020}very\u{0020}active\u{0020}anymore,\u{0020}he\u{0020}is\u{0020}indeed\u{0020}a\u{0020}highly\u{0020}experienced\u{0020}bridge\u{0020}designer\u{0020}in\u{0020}the\u{0020}industry.\u{0020}He\u{0020}not\u{0020}only\u{0020}contributed\u{0020}many\u{0020}methodologies\u{0020}and\u{0020}design\u{0020}ideas\u{0020}to\u{0020}his\u{0020}peers,\u{0020}but\u{0020}also\u{0020}was\u{0020}highly\u{0020}praised\u{0020}for\u{0020}his\u{0020}dedication\u{0020}to\u{0020}the\u{0020}projects.\u{0020}During\u{0020}the\u{0020}period\u{0020}of\u{0020}his\u{0020}career\u{0020}rise,\u{0020}his\u{0020}talent\u{0020}and\u{0020}vigor\u{0020}were\u{0020}no\u{0020}less\u{0020}than\u{0020}that\u{0020}of\u{0020}Shisha\u{0020}today.\u{0020}The\u{0020}only\u{0020}thing\u{0020}that\u{0020}was\u{0020}criticized\u{0020}was\u{0020}that\u{0020}from\u{0020}a\u{0020}certain\u{0020}period,\u{0020}he\u{0020}would\u{0020}never\u{0020}take\u{0020}a\u{0020}second\u{0020}look\u{0020}at\u{0020}poor\u{0020}projects\u{0020}with\u{0020}tight\u{0020}budgets.\u{0020}\n\u{3000}\u{3000}Shisha\u{0020}certainly\u{0020}understands\u{0020}.The\u{0020}transformation\u{0020}of\u{0020}the\u{0020}father\u{0020}was\u{0020}for\u{0020}what,\u{0020}but\u{0020}she\u{0020}neither\u{0020}blamed\u{0020}the\u{0020}heaven\u{0020}nor\u{0020}held\u{0020}a\u{0020}grudge\u{0020}against\u{0020}anyone.\u{0020}She\u{0020}did\u{0020}not\u{0020}attribute\u{0020}the\u{0020}fault\u{0020}to\u{0020}either\u{0020}side\u{0020}but\u{0020}resolutely\u{0020}chose\u{0020}to\u{0020}follow\u{0020}the\u{0020}path\u{0020}her\u{0020}father\u{0020}had\u{0020}taken\u{0020}and\u{0020}attempted\u{0020}to\u{0020}go\u{0020}further\u{0020}on\u{0020}this\u{0020}basis.\u{0020}She\u{0020}wanted\u{0020}to\u{0020}use\u{0020}herself\u{0020}as\u{0020}an\u{0020}excellent\u{0020}counterexample\u{0020}to\u{0020}refute\u{0020}her\u{0020}father's\u{0020}self-mockery\u{0020}of\u{0020}idealism\u{0020}and\u{0020}then\u{0020}rebuild\u{0020}the\u{0020}dilapidated\u{0020}bridge\u{0020}that\u{0020}isolated\u{0020}people's\u{0020}hearts\u{0020}in\u{0020}her\u{0020}hometown.\u{0020}\n\u{3000}\u{3000}Therefore,\u{0020}Shisha\u{0020}began\u{0020}to\u{0020}study\u{0020}engineering\u{0020}knowledge\u{0020}painstakingly,\u{0020}and\u{0020}passed\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}Proficiency\u{0020}Test,\u{0020}entered\u{0020}Azure\u{0020}Academy,\u{0020}and\u{0020}finally\u{0020}became\u{0020}a\u{0020}driver.\u{0020}The\u{0020}long\u{0020}time\u{0020}can\u{0020}be\u{0020}summarized\u{0020}in\u{0020}just\u{0020}one\u{0020}sentence\u{0020}in\u{0020}the\u{0020}file,\u{0020}but\u{0020}all\u{0020}the\u{0020}setbacks\u{0020}and\u{0020}confusion\u{0020}therein\u{0020}are\u{0020}only\u{0020}clear\u{0020}to\u{0020}herself.\u{0020}No\u{0020}matter\u{0020}the\u{0020}specific\u{0020}situation,\u{0020}she\u{0020}eventually\u{0020}overcame\u{0020}many\u{0020}obstacles,\u{0020}grew\u{0020}into\u{0020}the\u{0020}image\u{0020}she\u{0020}desired,\u{0020}and\u{0020}influenced\u{0020}the\u{0020}people\u{0020}around\u{0020}her\u{0020}with\u{0020}that\u{0020}vitality\u{0020}-\u{0020}in\u{0020}that\u{0020}Azure\u{0020}Academy,\u{0020}the\u{0020}class\u{0020}where\u{0020}Shisha\u{0020}studied\u{0020}broke\u{0020}the\u{0020}record\u{0020}of\u{0020}the\u{0020}highest\u{0020}graduation\u{0020}rate,\u{0020}which\u{0020}undoubtedly\u{0020}was\u{0020}because\u{0020}of\u{0020}the\u{0020}existence\u{0020}of\u{0020}this\u{0020}striving-for-excellence\u{0020}role\u{0020}model.", "0", "0", "0", "0", 12018, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[621803] = {621803, 1000, "\u{3000}\u{3000}Since\u{0020}Shisha\u{0020}chose\u{0020}to\u{0020}stay\u{0020}in\u{0020}her\u{0020}hometown\u{0020}Poynred,\u{0020}this\u{0020}ancient\u{0020}and\u{0020}perilous\u{0020}mountain\u{0020}city,\u{0020}and\u{0020}she\u{0020}did\u{0020}not\u{0020}hold\u{0020}a\u{0020}position\u{0020}in\u{0020}the\u{0020}Holy\u{0020}Church,\u{0020}AEGIS\u{0020}had\u{0020}to\u{0020}set\u{0020}up\u{0020}a\u{0020}new\u{0020}team\u{0020}for\u{0020}her.\u{0020}For\u{0020}a\u{0020}long\u{0020}time,\u{0020}there\u{0020}has\u{0020}been\u{0020}only\u{0020}Shisha\u{0020}in\u{0020}this\u{0020}team.\u{0020}\n\u{3000}\u{3000}Even\u{0020}so,\u{0020}Shisha\u{0020}is\u{0020}not\u{0020}alone\u{0020}in\u{0020}AEGIS.\u{0020}She\u{0020}can\u{0020}often\u{0020}make\u{0020}friends\u{0020}with\u{0020}drivers\u{0020}of\u{0020}similar\u{0020}age.\u{0020}And\u{0020}after\u{0020}the\u{0020}mysterious\u{0020}Heine\u{0020}joined\u{0020}the\u{0020}Architect\u{0020}team\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}people,\u{0020}Shisha\u{0020}was\u{0020}often\u{0020}questioned\u{0020}in\u{0020}a\u{0020}besieging\u{0020}way.\u{0020}Fortunately,\u{0020}she\u{0020}can\u{0020}always\u{0020}rely\u{0020}on\u{0020}her\u{0020}social\u{0020}skills,\u{0020}get\u{0020}through\u{0020}it\u{0020}with\u{0020}a\u{0020}sunny\u{0020}and\u{0020}enthusiastic\u{0020}smile,\u{0020}and\u{0020}sometimes\u{0020}even\u{0020}joke\u{0020}along\u{0020}with\u{0020}others'\u{0020}gossip,\u{0020}making\u{0020}them\u{0020}really\u{0020}think\u{0020}that\u{0020}Heine's\u{0020}true\u{0020}identity\u{0020}is\u{0020}an\u{0020}android.", "0", "0", "0", "0", 12018, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[621804] = {621804, 2000, "\u{3000}\u{3000}The\u{0020}world\u{0020}is\u{0020}crossed\u{0020}by\u{0020}a\u{0020}huge\u{0020}gap,\u{0020}\n\u{3000}\u{3000}It\u{0020}is\u{0020}the\u{0020}scar\u{0020}engraved\u{0020}by\u{0020}subjective\u{0020}consciousness,\u{0020}\n\u{3000}\u{3000}It\u{0020}is\u{0020}like\u{0020}a\u{0020}high\u{0020}wall\u{0020}that\u{0020}cuts\u{0020}off\u{0020}people's\u{0020}communication,\u{0020}\n\u{3000}\u{3000}The\u{0020}bottom\u{0020}of\u{0020}the\u{0020}valley\u{0020}is\u{0020}filled\u{0020}with\u{0020}the\u{0020}corpses\u{0020}of\u{0020}\"misunderstandings\".\u{0020}\n\u{3000}\u{3000}Can\u{0020}the\u{0020}power\u{0020}of\u{0020}the\u{0020}soul\u{0020}fly\u{0020}across\u{0020}the\u{0020}abyss?\u{0020}\n\u{3000}\u{3000}Facing\u{0020}this\u{0020}question\u{0020}with\u{0020}no\u{0020}visible\u{0020}answer,\u{0020}\n\u{3000}\u{3000}Both\u{0020}you\u{0020}and\u{0020}I\u{0020}are\u{0020}people\u{0020}who\u{0020}hesitate\u{0020}and\u{0020}do\u{0020}not\u{0020}move\u{0020}forward.\u{0020}\n\u{3000}\u{3000}\"Therefore,\u{0020}let's\u{0020}shorten\u{0020}our\u{0020}distance\u{0020}a\u{0020}little\u{0020}more.\"\u{0020}\n\u{3000}\u{3000}The\u{0020}smiling\u{0020}girl\u{0020}comes\u{0020}close,\u{0020}\n\u{3000}\u{3000}Like\u{0020}a\u{0020}bridge\u{0020}connecting\u{0020}each\u{0020}other.", "0", "0", "0", "0", 12018, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
