[621901] = {621901, 100, "\u{0020}\u{0020}Designation\u{0020}ODY763001,\u{0020}Caitlin\u{0020}from\u{0020}Chesterton,\u{0020}member\u{0020}of\u{0020}the\u{0020}Blackthorn\u{0020}Squad.\n\n\u{0020}\u{0020}Caitlin\u{0020}may\u{0020}look\u{0020}young,\u{0020}but\u{0020}her\u{0020}marksmanship\u{0020}speaks\u{0020}of\u{0020}years\u{0020}beyond\u{0020}her\u{0020}age.\u{0020}In\u{0020}just\u{0020}two\u{0020}years\u{0020}as\u{0020}a\u{0020}SWAT\u{0020}officer,\u{0020}she\u{0020}became\u{0020}a\u{0020}sniper\u{0020}of\u{0020}near-unmatched\u{0020}precision,\u{0020}capable\u{0020}of\u{0020}hitting\u{0020}her\u{0020}mark\u{0020}in\u{0020}even\u{0020}the\u{0020}most\u{0020}chaotic\u{0020}environments.\n\n\u{0020}\u{0020}The\u{0020}former\u{0020}police\u{0020}commissioner\u{0020}once\u{0020}remarked:\u{0020}\"When\u{0020}Caitlin\u{0020}raises\u{0020}her\u{0020}scope,\u{0020}only\u{0020}two\u{0020}things\u{0020}remain—the\u{0020}target\u{0020}and\u{0020}the\u{0020}rifle\u{0020}in\u{0020}her\u{0020}hands.\"\n\n\u{0020}\u{0020}Calmness\u{0020}is\u{0020}a\u{0020}virtue\u{0020}for\u{0020}any\u{0020}sniper,\u{0020}but\u{0020}Caitlin's\u{0020}is\u{0020}something\u{0020}colder,\u{0020}almost\u{0020}ruthless.\u{0020}It's\u{0020}in\u{0020}her\u{0020}eyes,\u{0020}the\u{0020}kind\u{0020}that\u{0020}offers\u{0020}no\u{0020}escape.\u{0020}A\u{0020}gaze\u{0020}that\u{0020}makes\u{0020}one\u{0020}feel\u{0020}the\u{0020}press\u{0020}of\u{0020}steel\u{0020}against\u{0020}their\u{0020}forehead,\u{0020}the\u{0020}whisper\u{0020}of\u{0020}a\u{0020}trigger\u{0020}waiting\u{0020}to\u{0020}be\u{0020}pulled.\n\n\u{0020}\u{0020}The\u{0020}only\u{0020}saving\u{0020}grace?\u{0020}Caitlin\u{0020}is\u{0020}a\u{0020}cop,\u{0020}not\u{0020}an\u{0020}assassin.", "0", "0", "0", "0", 12019, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[621902] = {621902, 500, "\u{0020}\u{0020}Caitlin\u{0020}remembers\u{0020}that\u{0020}day\u{0020}well.\n\n\u{0020}\u{0020}Perched\u{0020}atop\u{0020}a\u{0020}high-rise,\u{0020}she\u{0020}set\u{0020}up\u{0020}her\u{0020}sniper\u{0020}rifle,\u{0020}her\u{0020}scope\u{0020}trained\u{0020}on\u{0020}the\u{0020}bank\u{0020}a\u{0020}hundred\u{0020}meters\u{0020}away.\u{0020}Below,\u{0020}officers\u{0020}had\u{0020}the\u{0020}building\u{0020}surrounded,\u{0020}their\u{0020}patrol\u{0020}cars\u{0020}forming\u{0020}a\u{0020}barricade.\u{0020}Inside,\u{0020}armed\u{0020}criminals\u{0020}held\u{0020}hostages,\u{0020}just\u{0020}another\u{0020}standoff\u{0020}in\u{0020}Chesterton.\n\n\u{0020}\u{0020}Before\u{0020}becoming\u{0020}a\u{0020}Driver,\u{0020}Caitlin\u{0020}had\u{0020}spent\u{0020}two\u{0020}years\u{0020}as\u{0020}a\u{0020}SWAT\u{0020}sniper.\u{0020}She\u{0020}had\u{0020}long\u{0020}grown\u{0020}numb\u{0020}to\u{0020}this\u{0020}city's\u{0020}rot.\u{0020}Without\u{0020}hesitation,\u{0020}she\u{0020}began\u{0020}her\u{0020}search\u{0020}for\u{0020}the\u{0020}target\u{0020}-\u{0020}a\u{0020}masked\u{0020}man\u{0020}with\u{0020}a\u{0020}bomb.\n\n\u{0020}\u{0020}Chesterton\u{0020}saw\u{0020}these\u{0020}crises\u{0020}all\u{0020}too\u{0020}often,\u{0020}but\u{0020}most\u{0020}ended\u{0020}in\u{0020}success.\u{0020}Each\u{0020}mission\u{0020}refined\u{0020}Caitlin's\u{0020}aim,\u{0020}each\u{0020}shot\u{0020}hardened\u{0020}her\u{0020}heart.\n\n\u{0020}\u{0020}She\u{0020}scanned\u{0020}the\u{0020}bank's\u{0020}windows,\u{0020}sweeping\u{0020}past\u{0020}them\u{0020}until\u{0020}the\u{0020}mask\u{0020}appeared.\u{0020}Target\u{0020}acquired.\n\n\u{0020}\u{0020}She\u{0020}aligned\u{0020}the\u{0020}crosshairs\u{0020}with\u{0020}his\u{0020}movements.\n\n\u{0020}\u{0020}Breathe.\u{0020}Steady.\u{0020}Fire.\u{0020}Two\u{0020}years.\u{0020}Too\u{0020}many\u{0020}bodies.\u{0020}Caitlin\u{0020}no\u{0020}longer\u{0020}kept\u{0020}count.\u{0020}She\u{0020}knew\u{0020}some\u{0020}of\u{0020}them\u{0020}weren't\u{0020}monsters,\u{0020}just\u{0020}desperate.\u{0020}Maybe\u{0020}this\u{0020}one\u{0020}was,\u{0020}too.\u{0020}But\u{0020}hesitation\u{0020}only\u{0020}led\u{0020}to\u{0020}more\u{0020}deaths.\n\n\u{0020}\u{0020}A\u{0020}sniper\u{0020}doesn't\u{0020}see\u{0020}people\u{0020}-\u{0020}only\u{0020}targets.\n\n\u{0020}\u{0020}All\u{0020}she\u{0020}wanted\u{0020}was\u{0020}to\u{0020}protect\u{0020}the\u{0020}city.\n\n\u{0020}\u{0020}The\u{0020}shot\u{0020}rang\u{0020}out.\u{0020}The\u{0020}masked\u{0020}man\u{0020}collapsed.\n\n\u{0020}\u{0020}Mission\u{0020}complete.\u{0020}Another\u{0020}clean\u{0020}execution.\u{0020}She\u{0020}disassembled\u{0020}her\u{0020}rifle,\u{0020}preparing\u{0020}to\u{0020}leave.\u{0020}Then\u{0020}-\u{0020}a\u{0020}deafening\u{0020}roar.\u{0020}An\u{0020}explosion.\n\n\u{0020}\u{0020}Had\u{0020}the\u{0020}bomb\u{0020}gone\u{0020}off?\n\n\u{0020}\u{0020}Had\u{0020}the\u{0020}target\u{0020}survived?\n\n\u{0020}\u{0020}Had\u{0020}the\u{0020}bomb\u{0020}squad\u{0020}failed?\n\n\u{0020}\u{0020}...\n\n\u{0020}\u{0020}No.\u{0020}It\u{0020}wasn't\u{0020}the\u{0020}bank.\u{0020}Caitlin\u{0020}looked\u{0020}up...\u{0020}The\u{0020}Ark,\u{0020}a\u{0020}symbol\u{0020}of\u{0020}eternity,\u{0020}was\u{0020}burning.\n\n\u{0020}\u{0020}She\u{0020}had\u{0020}heard\u{0020}of\u{0020}Drivers.\u{0020}She\u{0020}had\u{0020}heard\u{0020}of\u{0020}the\u{0020}Sin.\u{0020}But\u{0020}back\u{0020}then,\u{0020}they\u{0020}were\u{0020}distant\u{0020}threats,\u{0020}nothing\u{0020}more\u{0020}than\u{0020}headlines\u{0020}and\u{0020}emergency\u{0020}broadcasts.\u{0020}They\u{0020}had\u{0020}never\u{0020}touched\u{0020}her\u{0020}world.\n\n\u{0020}\u{0020}\"It\u{0020}wasn't\u{0020}until\u{0020}the\u{0020}Ark's\u{0020}shadow\u{0020}swallowed\u{0020}me\u{0020}and\u{0020}everyone\u{0020}below\u{0020}that\u{0020}I\u{0020}realized\u{0020}that\u{0020}I\u{0020}had\u{0020}been\u{0020}wrong\u{0020}all\u{0020}along.\"\n\n\u{0020}\u{0020}Against\u{0020}true\