[621903] = {621903, 1000, "\u{0020}\u{0020}Caitlin\u{0020}barely\u{0020}survived\u{0020}the\u{0020}Maya\u{0020}Ark\u{0020}Crash.\u{0020}When\u{0020}she\u{0020}came\u{0020}to,\u{0020}she\u{0020}was\u{0020}already\u{0020}in\u{0020}a\u{0020}shelter,\u{0020}dodging\u{0020}falling\u{0020}debris\u{0020}alongside\u{0020}other\u{0020}survivors.\n\n\u{0020}\u{0020}For\u{0020}now,\u{0020}they\u{0020}could\u{0020}only\u{0020}wait\u{0020}for\u{0020}rescue,\u{0020}but\u{0020}against\u{0020}the\u{0020}towering\u{0020}metal\u{0020}beasts\u{0020}outside,\u{0020}her\u{0020}gun\u{0020}was\u{0020}useless.\u{0020}She\u{0020}had\u{0020}always\u{0020}prided\u{0020}herself\u{0020}on\u{0020}keeping\u{0020}calm\u{0020}under\u{0020}pressure,\u{0020}but\u{0020}calm\u{0020}wasn't\u{0020}enough\u{0020}anymore.\u{0020}She\u{0020}needed\u{0020}more\u{0020}-\u{0020}a\u{0020}larger\u{0020}battlefield,\u{0020}a\u{0020}stronger\u{0020}weapon,\u{0020}a\u{0020}stronger\u{0020}self.\n\n\u{0020}\u{0020}Snipers\u{0020}are\u{0020}defined\u{0020}by\u{0020}their\u{0020}composure,\u{0020}and\u{0020}Caitlin,\u{0020}ever\u{0020}calm,\u{0020}made\u{0020}her\u{0020}decision\u{0020}-\u{0020}she\u{0020}would\u{0020}enlist\u{0020}in\u{0020}the\u{0020}Driver\u{0020}Renaissance\u{0020}Program,\u{0020}spearheaded\u{0020}by\u{0020}Odyssey\u{0020}Heavy\u{0020}Industries.\n\n\u{0020}\u{0020}From\u{0020}now\u{0020}on,\u{0020}she\u{0020}would\u{0020}never\u{0020}have\u{0020}to\u{0020}run\u{0020}from\u{0020}the\u{0020}shadows\u{0020}again.", "0", "0", "0", "0", 12019, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[621904] = {621904, 2000, "\u{0020}\u{0020}I\u{0020}once\u{0020}thought\n\n\u{0020}\u{0020}I\u{0020}was\u{0020}protecting\u{0020}this\u{0020}city...\n\n\u{0020}\u{0020}but\u{0020}in\u{0020}truth,\n\n\u{0020}\u{0020}it\u{0020}was\u{0020}the\u{0020}city\u{0020}that\u{0020}protected\u{0020}me.\n\n\n\n\u{0020}\u{0020}I\u{0020}once\u{0020}took\u{0020}lives\n\n\u{0020}\u{0020}without\u{0020}hesitation,\n\n\u{0020}\u{0020}yet\u{0020}I\u{0020}couldn't\u{0020}save\n\n\u{0020}\u{0020}the\u{0020}terrified\u{0020}innocents.\n\n\n\n\u{0020}\u{0020}I\u{0020}once\u{0020}believed\n\n\u{0020}\u{0020}the\u{0020}Sins\u{0020}were\u{0020}far\u{0020}removed\u{0020}from\u{0020}my\u{0020}world,\n\n\u{0020}\u{0020}but\u{0020}when\u{0020}they\u{0020}finally\u{0020}stood\u{0020}before\u{0020}me,\n\n\u{0020}\u{0020}I\u{0020}was\u{0020}afraid\u{0020}-\u{0020}because\u{0020}I\u{0020}lacked\u{0020}to\u{0020}power\u{0020}to\u{0020}fight\u{0020}them.\n\n\n\n\u{0020}\u{0020}But\u{0020}now...\n\n\u{0020}\u{0020}I\u{0020}fear\u{0020}nothing.\n\n\u{0020}\u{0020}I\u{0020}will\u{0020}never\u{0020}run\u{0020}again.\n\n\u{0020}\u{0020}Because\u{0020}now,\u{0020}I\u{0020}have\u{0020}power.\n\n\u{0020}\u{0020}And\u{0020}I\u{0020}have\u{0020}you.", "0", "0", "0", "0", 12019, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
