[622001] = {622001, 100, "\u{0020}\u{0020}Miss…Flovira\u{0020}is\u{0020}a\u{0020}positive\u{0020}person,\u{0020}she\u{0020}is\u{0020}just\u{0020}like\u{0020}a\u{0020}lot\u{0020}of\u{0020}girls,\u{0020}has\u{0020}some\u{0020}hobbies\u{0020}and\u{0020}an\u{0020}extrovert\u{0020}personality.\u{0020}Only\u{0020}when\u{0020}she\u{0020}talks\u{0020}about\u{0020}interstellar\u{0020}traveling,\u{0020}will\u{0020}she\u{0020}show\u{0020}her\u{0020}\"fierce\"\u{0020}side.\n\n\n\nBut\u{0020}Miss\u{0020}Flovria\u{0020}is\u{0020}a\u{0020}special\u{0020}one.\u{0020}In\u{0020}fact,\u{0020}she's\u{0020}an\u{0020}alien.\n\n\n\nBorn\u{0020}on\u{0020}an\u{0020}alien\u{0020}planet,\u{0020}grew\u{0020}up\u{0020}on\u{0020}an\u{0020}alien\u{0020}planet,\u{0020}she's\u{0020}totally\u{0020}an\u{0020}alien.\n\n\n\nAccording\u{0020}to\u{0020}Miss\u{0020}Flovira,\u{0020}their\u{0020}home\u{0020}planet\u{0020}is\u{0020}\"Midyr\".\n\n\n\nReferring\u{0020}to\u{0020}them\u{0020}as\u{0020}Midyrians\u{0020}should\u{0020}be\u{0020}accurate.\n\n\n\nMidyrians\u{0020}don't\u{0020}have\u{0020}ideas\u{0020}about\u{0020}hometown\u{0020}and\u{0020}family,\u{0020}they\u{0020}do\u{0020}interstellar\u{0020}traveling\u{0020}throughout\u{0020}their\u{0020}life.\u{0020}Flovira\u{0020}is\u{0020}no\u{0020}different\u{0020}from\u{0020}them,\u{0020}she\u{0020}controls\u{0020}a\u{0020}spacecraft\u{0020}called\u{0020}\"Shumia\",\u{0020}doing\u{0020}interstellar\u{0020}adventures\u{0020}with\u{0020}her\u{0020}fellow\u{0020}Midyrians.\n\n\n\nMeets\u{0020}with\u{0020}people,\u{0020}has\u{0020}some\u{0020}communications,\u{0020}and\u{0020}leaves\u{0020}for\u{0020}the\u{0020}next\u{0020}chapter\u{0020}of\u{0020}their\u{0020}journey.\u{0020}They\u{0020}repeat\u{0020}this\u{0020}cycle\u{0020}in\u{0020}their\u{0020}life,\u{0020}and\u{0020}enjoy\u{0020}it.\u{0020}Miss\u{0020}Flovira\u{0020}should\u{0020}always\u{0020}be\u{0020}enjoying\u{0020}her\u{0020}journey\u{0020}with\u{0020}happiness.", "0", "0", "0", "0", 12020, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622002] = {622002, 500, "\u{0020}\u{0020}Miss\u{0020}Flovira's\u{0020}communication\u{0020}with\u{0020}Earth\u{0020}started\u{0020}from\u{0020}thousands\u{0020}of\u{0020}light-years\u{0020}away.\n\n\n\nSignals\u{0020}from\u{0020}\"Shumia\",\u{0020}transmitted\u{0020}by\u{0020}superluminal\u{0020}electromagnetic\u{0020}pulses,\u{0020}was\u{0020}received\u{0020}and\u{0020}decoded\u{0020}by\u{0020}human.\u{0020}After\u{0020}that,\u{0020}we\u{0020}often\u{0020}received\u{0020}superluminal\u{0020}information\u{0020}from\u{0020}\"Shumia\".\u{0020}By\u{0020}continuously\u{0020}decoding\u{0020}their\u{0020}messages,\u{0020}we\u{0020}have\u{0020}a\u{0020}crude\u{0020}understanding\u{0020}about\u{0020}Midyr.\n\n\n\nMidyrians\u{0020}have\u{0020}well-developed\u{0020}technologies,\u{0020}we\u{0020}can\u{0020}have\u{0020}that\u{0020}conclusion\u{0020}by\u{0020}knowing\u{0020}almost\u{0020}every\u{0020}Midyrians\u{0020}can\u{0020}travel\u{0020}across\u{0020}stars.\u{0020}But\u{0020}because\u{0020}of\u{0020}their\u{0020}highly\u{0020}developed\u{0020}technologies,\u{0020}they\u{0020}don't\u{0020}have\u{0020}the\u{0020}same\u{0020}emotions\u{0020}as\u{0020}humans:\u{0020}they\u{0020}don't\u{0020}have\u{0020}the\u{0020}ideas\u{0020}of\u{0020}hometown\u{0020}and\u{0020}relatives,\u{0020}deem\u{0020}gone\u{0020}forever\u{0020}the\u{0020}same\u{0020}as\u{0020}temporary\u{0020}separation,\u{0020}which\u{0020}is\u{0020}unreasonable\u{0020}for\u{0020}us\u{0020}humans.\n\n\n\nWith\u{0020}these\u{0020}differences,\u{0020}humans\u{0020}worried\u{0020}about\u{0020}the\u{0020}coming\u{0020}of\u{0020}Midyrians.\u{0020}Who\u{0020}knows\u{0020}if\u{0020}they\u{0020}are\u{0020}just\u{0020}another\u{0020}batch\u{0020}of\u{0020}Sins?\n\n\n\nBut\u{0020}this\u{0020}was\u{0020}a\u{0020}temporary\u{0020}misunderstanding.\u{0020}At\u{0020}least,\u{0020}no\u{0020}matter\u{0020}how\u{0020}humans\u{0020}think\u{0020}about\u{0020}them,\u{0020}one\u{0020}thing\u{0020}is\u{0020}for\u{0020}sure:\u{0020}Miss\u{0020}Flovira\u{0020}didn't\u{0020}have\u{0020}any\u{0020}ill\u{0020}will.\n\n\n\nOr\u{0020}rather,\u{0020}she\u{0020}didn't\u{0020}have\u{0020}any\u{0020}emotion.\n\n\n\nNo\u{0020}kindness,\u{0020}no\u{0020}malice,\u{0020}she\u{0020}didn't\u{0020}take\u{0020}a\u{0020}side,\u{0020}she\u{0020}didn't\u{0020}have\u{0020}any\u{0020}feelings\u{0020}towards\u{0020}humans.\n\n\n\nShe\u{0020}was\u{0020}simply\u{0020}embracing\u{0020}her\u{0020}journey,\u{0020}and\u{0020}sharing\u{0020}her\u{0020}feelings\u{0020}in\u{0020}her\u{0020}journey.\n\n\n\nShe\u{0020}shared\u{0020}her\u{0020}joy\u{0020}and\u{0020}sadness\u{0020}with\u{0020}us\u{0020}humans,\u{0020}who\u{0020}were\u{0020}lonely\u{0020}in\u{0020}the\u{0020}deserted\u{0020}galaxy.\n\n\n\nThat's\u{0020}all.\n\n\n\nAfter\u{0020}that,\u{0020}60\u{0020}years\u{0020}ago,\u{0020}the\u{0020}communication\u{0020}between\u{0020}Earth\u{0020}and\u{0020}Shumia\u{0020}was\u{0020}stopped.\n\n\n\nMiss\u{0020}Flovira,\u{0020}and\u{0020}Shumia,\u{0020}we\u{0020}guess\u{0020}they\u{0020}encountered\u{0020}some\u{0020}danger,\u{0020}maybe\u{0020}they\u{0020}accidentally\u{0020}went\u{0020}into\u{0020}a\u{0020}wormhole\u{0020}and\u{0020}an\u{0020}unknown\u{0020}trip;\u{0020}or\u{0020}maybe\u{0020}they\u{0020}were\u{0020}unlucky\u{0020}and\u{0020}grabbed\u{0020}by\u{0020}a\u{0020}black\u{0020}hole,\u{0020}straight\u{0020}to\u{0020}hell.\n\n\n\nAfter\u{0020}a\u{0020}long\u{0020}time,\u{0020}we\u{0020}finally\u{0020}decoded\u{0020}her\u{0020}last\u{0020}message:\u{0020}\"Be\u{0020}careful\u{0020}about\u{0020}▇▇\"\n\n\n\nWe\u{0020}deem\u{0020}this\u{0020}message\u{0020}as\u{0020}her\u{0020}death\u{0020}notification,\u{0020}but\u{0020}things\u{0020}didn't\u{0020}end\u{0020}there.\n\n\n\nIf\u{0020}that\u{0020}was\u{0020}the\u{0020}case,\u{0020}we\u{0020}wouldn't\u{0020}have\u{0020}this\u{0020}archive\u{0020}now.", "0", "0", "0", "0", 12020, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622003] = {622003, 1000, "\u{0020}\u{0020}60\u{0020}years\u{0020}ago,\u{0020}people\u{0020}thought\u{0020}their\u{0020}relationship\u{0020}with\u{0020}interstellar\u{0020}travelers\u{0020}came\u{0020}to\u{0020}an\u{0020}end.\u{0020}60\u{0020}years\u{0020}passed,\u{0020}our\u{0020}world\u{0020}has\u{0020}changed\u{0020}a\u{0020}lot,\u{0020}and\u{0020}we\u{0020}reopened\u{0020}this\u{0020}history.\n\n\n\nDr.\u{0020}Stephanie\u{0020}let\u{0020}members\u{0020}of\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force\u{0020}get\u{0020}in\u{0020}contact\u{0020}with\u{0020}those\u{0020}superluminal\u{0020}signals.\n\n\n\nWhat\u{0020}happened\u{0020}next\u{0020}was\u{0020}only\u{0020}from\u{0020}the\u{0020}narration\u{0020}from\u{0020}that\u{0020}navigator.\n\n\n\nHe\u{0020}claimed\u{0020}he\u{0020}met\u{0020}with\u{0020}Miss\u{0020}Flovira,\u{0020}and\u{0020}discovered\u{0020}the\u{0020}fact\u{0020}that\u{0020}Shumia\u{0020}was\u{0020}eliminated\u{0020}by\u{0020}the\u{0020}attack\u{0020}from\u{0020}Great\u{0020}Sins.\u{0020}And,\u{0020}the\u{0020}most\u{0020}unbelievable\u{0020}thing\u{0020}happened.\n\n\n\nMiss\u{0020}Flovira,\u{0020}who\u{0020}was\u{0020}supposed\u{0020}to\u{0020}be\u{0020}dead\u{0020}at\u{0020}least\u{0020}60\u{0020}years\u{0020}ago,\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}the\u{0020}navigator,\u{0020}used\u{0020}the\u{0020}power\u{0020}of\u{0020}Nimbus\u{0020}to\u{0020}construct\u{0020}her\u{0020}body\u{0020}and...revived.\n\n\n\nMidyrians\u{0020}may\u{0020}have\u{0020}the\u{0020}ability\u{0020}to\u{0020}store\u{0020}their\u{0020}consciousness\u{0020}in\u{0020}their\u{0020}messages.\u{0020}So,\u{0020}the\u{0020}last\u{0020}message\u{0020}we\u{0020}received\u{0020}from\u{0020}them\u{0020}is\u{0020}not\u{0020}only\u{0020}a\u{0020}warning\u{0020}from\u{0020}them,\u{0020}but\u{0020}also\u{0020}the\u{0020}way…to\u{0020}save\u{0020}themselves?\n\n\n\nThis\u{0020}is\u{0020}unreasonable—-but\u{0020}very\u{0020}romantic.", "0", "0", "0", "0", 12020, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[622004] = {622004, 2000, "\u{0020}\u{0020}\"Whoa...\u{0020}That's\u{0020}what\u{0020}happened?\"\n\n\n\nThe\u{0020}giantess\u{0020}stays\u{0020}under\u{0020}the\u{0020}starry\u{0020}sky,\u{0020}she\u{0020}stops\u{0020}there.\n\n\n\nShe\u{0020}stretches\u{0020}her\u{0020}hands\u{0020}towards\u{0020}the\u{0020}universe,\u{0020}while\u{0020}her\u{0020}fingertips\u{0020}are\u{0020}turning\u{0020}into\u{0020}gleaming\u{0020}stars.\n\n\n\nTime\u{0020}becomes\u{0020}the\u{0020}limitation\u{0020}of\u{0020}her\u{0020}journey.\n\n\n\n\"I'm\u{0020}dead,\u{0020}it's\u{0020}over…\u{0020}My\u{0020}life\u{0020}and\u{0020}my\u{0020}journey\u{0020}are\u{0020}over.\"\n\n\n\n\"However…\"\n\n\n\nShe\u{0020}stares\u{0020}at\u{0020}this\u{0020}gorgeous\u{0020}planet,\u{0020}and\u{0020}lovely\u{0020}people\u{0020}living\u{0020}there.\n\n\n\n\"...starting\u{0020}a\u{0020}new\u{0020}journey\u{0020}here\u{0020}is\u{0020}not\u{0020}bad,\u{0020}huh?\"\n\n\n\n\"Moreover,\u{0020}there\u{0020}are\u{0020}delicious\u{0020}foods!\"\n\n\n\nFlovira's\u{0020}journey\u{0020}on\u{0020}the\u{0020}Earth,\u{0020}now\u{0020}starts.", "0", "0", "0", "0", 12020, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
