[622102] = {622102, 500, "\u{0020}\u{0020}Taken\u{0020}from\u{0020}the\u{0020}confidential\u{0020}diary\u{0020}of\u{0020}Ping\u{0020}Xin\u{0020}leader,\u{0020}Chenglian:\n\nDamn...\u{0020}Shaoyin,\u{0020}our\u{0020}Lucky\u{0020}Charm...\u{0020}She's\u{0020}too\u{0020}cute.\n\nI'd\u{0020}assumed\u{0020}she'd\u{0020}be\u{0020}aloof,\u{0020}and\u{0020}cold;\u{0020}the\u{0020}quiet\u{0020}type,\u{0020}an\u{0020}outsider.\u{0020}Someone\u{0020}to\u{0020}keep\u{0020}an\u{0020}eye\u{0020}on\u{0020}so\u{0020}she\u{0020}doesn't\u{0020}cause\u{0020}conflict\u{0020}with\u{0020}the\u{0020}others.\u{0020}Yet\u{0020}I\u{0020}found\u{0020}it's\u{0020}just\u{0020}that\u{0020}her\u{0020}expression\u{0020}doesn't\u{0020}change\u{0020}much,\u{0020}she's\u{0020}softly\u{0020}spoken,\u{0020}and\u{0020}hesitates\u{0020}before\u{0020}replying\u{0020}sometimes;\u{0020}that's\u{0020}all.\u{0020}She\u{0020}doesn't\u{0020}rush.\n\nI\u{0020}suppose\u{0020}you\u{0020}could\u{0020}say\u{0020}she\u{0020}takes\u{0020}her\u{0020}time\u{0020}in\u{0020}all\u{0020}she\u{0020}does.\n\nBut\u{0020}it's\u{0020}a\u{0020}considered\u{0020}slowness—when\u{0020}making\u{0020}a\u{0020}decision,\u{0020}or\u{0020}thinking\u{0020}what\u{0020}to\u{0020}say,\u{0020}she\u{0020}thinks\u{0020}several\u{0020}steps\u{0020}ahead\u{0020}by\u{0020}considering\u{0020}the\u{0020}repercussions.\u{0020}Only\u{0020}once\u{0020}she's\u{0020}decided\u{0020}on\u{0020}the\u{0020}perfect\u{0020}move\u{0020}does\u{0020}she\u{0020}take\u{0020}action.\n\nSo\u{0020}she's\u{0020}not\u{0020}cold\u{0020}or\u{0020}aloof,\u{0020}just\u{0020}an\u{0020}over-thinker,\u{0020}meaning\u{0020}she'll\u{0020}often\u{0020}be\u{0020}slow\u{0020}to\u{0020}respond.\u{0020}Give\u{0020}her\u{0020}time,\u{0020}and\u{0020}she'll\u{0020}share\u{0020}her\u{0020}thoughts\u{0020}with\u{0020}you.\u{0020}Most\u{0020}scientists\u{0020}are\u{0020}so\u{0020}self-focused\u{0020}that\u{0020}they\u{0020}won't\u{0020}give\u{0020}her\u{0020}that\u{0020}time,\u{0020}though.\n\nAll\u{0020}good\u{0020}things\u{0020}come\u{0020}with\u{0020}time.\n\nPerhaps\u{0020}that's\u{0020}why\u{0020}such\u{0020}joy\u{0020}shines\u{0020}in\u{0020}her\u{0020}eyes\u{0020}when\u{0020}others\u{0020}look\u{0020}up\u{0020}to\u{0020}her,\u{0020}or\u{0020}seek\u{0020}her\u{0020}help\u{0020}with\u{0020}things,\u{0020}taking\u{0020}her\u{0020}as\u{0020}a\u{0020}teacher.\n\nThose\u{0020}with\u{0020}the\u{0020}loudest\u{0020}voices\u{0020}are\u{0020}heard\u{0020}more\u{0020}than\u{0020}others.\u{0020}Maybe\u{0020}Shaoyin\u{0020}just\u{0020}doesn't\u{0020}realize\u{0020}that.\n\nPlaying\u{0020}the\u{0020}role\u{0020}of\u{0020}teacher,\u{0020}a\u{0020}leader\u{0020}like\u{0020}that,\u{0020}will\u{0020}wear\u{0020}you\u{0020}out\u{0020}eventually,\u{0020}Shaoyin...\u{0020}And\u{0020}you'll\u{0020}only\u{0020}drift\u{0020}ever\u{0020}farther\u{0020}from\u{0020}that\u{0020}you\u{0020}seek...", "0", "0", "0", "0", 12021, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622103] = {622103, 1000, "\u{0020}\u{0020}Shaoyin\u{0020}knew\u{0020}how\u{0020}others\u{0020}described\u{0020}her\u{0020}as\u{0020}having\u{0020}innate\u{0020}knowledge.\n\nSome\u{0020}looked\u{0020}at\u{0020}her\u{0020}with\u{0020}envy,\u{0020}others\u{0020}with\u{0020}admiration,\u{0020}but\u{0020}she\u{0020}could\u{0020}only\u{0020}hesitate\u{0020}in\u{0020}reaction.\u{0020}She\u{0020}kept\u{0020}the\u{0020}pain\u{0020}of\u{0020}her\u{0020}ultra-accurate\u{0020}memory\u{0020}inside,\u{0020}striving\u{0020}to\u{0020}sort\u{0020}through\u{0020}her\u{0020}mind\u{0020}and\u{0020}act\u{0020}with\u{0020}laser\u{0020}precision\u{0020}in\u{0020}all\u{0020}she\u{0020}did.\n\nMaybe\u{0020}it\u{0020}would\u{0020}earn\u{0020}her\u{0020}a\u{0020}few\u{0020}words\u{0020}of\u{0020}their\u{0020}praise.\u{0020}And\u{0020}that\u{0020}was\u{0020}enough\u{0020}for\u{0020}her.\n\nShe\u{0020}had\u{0020}many\u{0020}visitors,\u{0020}but\u{0020}each\u{0020}only\u{0020}shared\u{0020}a\u{0020}few\u{0020}words\u{0020}with\u{0020}her.\n\nShaoyin\u{0020}knew\u{0020}how\u{0020}they\u{0020}considered\u{0020}her\u{0020}a\u{0020}\"lucky\u{0020}charm\",\u{0020}too.\n\nHence\u{0020}some\u{0020}looked\u{0020}at\u{0020}her\u{0020}with\u{0020}hope,\u{0020}others\u{0020}with\u{0020}appreciation,\u{0020}but\u{0020}again\u{0020}all\u{0020}she\u{0020}could\u{0020}do\u{0020}was\u{0020}hesitate.\u{0020}She'd\u{0020}pretend\u{0020}like\u{0020}she\u{0020}knew\u{0020}nothing\u{0020}of\u{0020}it\u{0020}all.\u{0020}Shaoyin\u{0020}would\u{0020}identify\u{0020}what\u{0020}was\u{0020}troubling\u{0020}those\u{0020}who\u{0020}came\u{0020}to\u{0020}her,\u{0020}and\u{0020}with\u{0020}seeming\u{0020}indifference,\u{0020}she'd\u{0020}hint\u{0020}at\u{0020}ways\u{0020}they\u{0020}could\u{0020}solve\u{0020}their\u{0020}problems.\n\nAnd\u{0020}if\u{0020}that\u{0020}was\u{0020}enough\u{0020}to\u{0020}keep\u{0020}more\u{0020}people\u{0020}coming\u{0020}to\u{0020}visit,\u{0020}then\u{0020}that\u{0020}was\u{0020}enough\u{0020}for\u{0020}her.\n\nYet\u{0020}fewer\u{0020}and\u{0020}fewer\u{0020}people\u{0020}came.\n\nThey'd\u{0020}just\u{0020}wish\u{0020}for\u{0020}luck\u{0020}from\u{0020}afar,\u{0020}not\u{0020}wanting\u{0020}to\u{0020}cause\u{0020}offense\u{0020}by\u{0020}coming\u{0020}to\u{0020}her\u{0020}directly.\n\nShe'd\u{0020}reached\u{0020}out\u{0020}twice\u{0020}before,\u{0020}but\u{0020}both\u{0020}times\u{0020}failed.\n\nAnd\u{0020}now...\n\nThe\u{0020}Navigator\u{0020}of\u{0020}the\u{0020}Danube,\u{0020}the\u{0020}sole\u{0020}Synesthete\u{0020}with\u{0020}powers\u{0020}to\u{0020}connect\u{0020}to\u{0020}Drivers\u{0020}and\u{0020}share\u{0020}their\u{0020}very\u{0020}emotions...\n\nA\u{0020}new\u{0020}opportunity\u{0020}had\u{0020}arisen\u{0020}before\u{0020}her.\n\nShaoyin\u{0020}wasn't\u{0020}going\u{0020}to\u{0020}let\u{0020}this\u{0020}chance\u{0020}slip\u{0020}her\u{0020}by.\u{0020}Not\u{0020}this\u{0020}time.", "0", "0", "0", "0", 12021, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
