[622201] = {622201, 100, "\u{0020}\u{0020}The\u{0020}\"Iron\u{0020}Crow\"\u{0020}is\u{0020}a\u{0020}reconnaissance\u{0020}team\u{0020}established\u{0020}by\u{0020}the\u{0020}AEGIS\u{0020}Danube\u{0020}branch\u{0020}after\u{0020}the\u{0020}\"Great\u{0020}Sin\u{0020}Envy\u{0020}Invasion\",\u{0020}whose\u{0020}members\u{0020}are\u{0020}selected\u{0020}from\u{0020}various\u{0020}teams\u{0020}and\u{0020}are\u{0020}experienced\u{0020}drivers.\n\nLepani\u{0020}is\u{0020}the\u{0020}\"captain\"\u{0020}of\u{0020}this\u{0020}team.\n\nAs\u{0020}the\u{0020}team\u{0020}leader,\u{0020}Lepani\u{0020}is\u{0020}as\u{0020}dedicated\u{0020}as\u{0020}most\u{0020}of\u{0020}the\u{0020}drivers\u{0020}who\u{0020}have\u{0020}taken\u{0020}on\u{0020}this\u{0020}responsibility,\u{0020}leading\u{0020}the\u{0020}way\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}and\u{0020}being\u{0020}kind\u{0020}and\u{0020}considerate\u{0020}in\u{0020}life.\u{0020}However,\u{0020}her\u{0020}way\u{0020}of\u{0020}thinking\u{0020}details\u{0020}often\u{0020}be\u{0020}in\u{0020}the\u{0020}details\u{0020}of\u{0020}the\u{0020}lack\u{0020}of\u{0020}consideration,\u{0020}will\u{0020}put\u{0020}the\u{0020}cart\u{0020}before\u{0020}the\u{0020}horse,\u{0020}or\u{0020}is\u{0020}too\u{0020}much\u{0020}behavior.\n\nShe\u{0020}once\u{0020}added\u{0020}an\u{0020}excessive\u{0020}amount\u{0020}of\u{0020}sleeping\u{0020}pills\u{0020}to\u{0020}the\u{0020}midnight\u{0020}snack\u{0020}out\u{0020}of\u{0020}the\u{0020}intention\u{0020}of\u{0020}allowing\u{0020}her\u{0020}teammates\u{0020}to\u{0020}get\u{0020}a\u{0020}good\u{0020}rest,\u{0020}which\u{0020}almost\u{0020}caused\u{0020}them\u{0020}to\u{0020}sleep\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\n\nThe\u{0020}most\u{0020}important\u{0020}thing\u{0020}is\u{0020}that\u{0020}you\u{0020}can't\u{0020}be\u{0020}afraid\u{0020}of\u{0020}what\u{0020}you're\u{0020}doing.\n\n\n\nWhat\u{0020}really\u{0020}makes\u{0020}people\u{0020}feel\u{0020}unbelievable\u{0020}is\u{0020}that,\u{0020}as\u{0020}the\u{0020}leader\u{0020}of\u{0020}the\u{0020}investigation\u{0020}team\u{0020}\"Iron\u{0020}Crow\",\u{0020}Lepani\u{0020}is\u{0020}actually\u{0020}an\u{0020}uncompromising\u{0020}idiot\u{0020}of\u{0020}the\u{0020}road.\u{0020}Leaving\u{0020}the\u{0020}team,\u{0020}she\u{0020}may\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}complete\u{0020}the\u{0020}task\u{0020}alone.\n\nIt\u{0020}is\u{0020}rumored\u{0020}that\u{0020}in\u{0020}order\u{0020}to\u{0020}let\u{0020}her\u{0020}teammates\u{0020}in\u{0020}the\u{0020}implementation\u{0020}of\u{0020}the\u{0020}task\u{0020}not\u{0020}to\u{0020}leave\u{0020}their\u{0020}own,\u{0020}and\u{0020}put\u{0020}themselves\u{0020}and\u{0020}their\u{0020}teammates\u{0020}with\u{0020}a\u{0020}large\u{0020}iron\u{0020}chain\u{0020}together\u{0020}......\u{0020}This\u{0020}may\u{0020}be\u{0020}a\u{0020}rumor,\u{0020}right?", "0", "0", "0", "0", 12022, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622202] = {622202, 500, "\u{0020}\u{0020}It's\u{0020}not\u{0020}uncommon\u{0020}for\u{0020}people\u{0020}to\u{0020}associate\u{0020}Lepani's\u{0020}roadblock\u{0020}problem\u{0020}with\u{0020}her\u{0020}past\u{0020}of\u{0020}being\u{0020}separated\u{0020}from\u{0020}her\u{0020}parents\u{0020}in\u{0020}the\u{0020}battlefield.\n\nAs\u{0020}to\u{0020}whether\u{0020}she\u{0020}became\u{0020}separated\u{0020}from\u{0020}her\u{0020}parents\u{0020}because\u{0020}she\u{0020}was\u{0020}a\u{0020}half-wit\u{0020}or\u{0020}because\u{0020}she\u{0020}became\u{0020}a\u{0020}half-wit\u{0020}after\u{0020}being\u{0020}separated\u{0020}from\u{0020}them,\u{0020}not\u{0020}many\u{0020}people\u{0020}care.\u{0020}She\u{0020}wasn't\u{0020}much\u{0020}of\u{0020}a\u{0020}celebrity\u{0020}in\u{0020}the\u{0020}past.\n\nLepani\u{0020}has\u{0020}a\u{0020}lot\u{0020}of\u{0020}combat\u{0020}experience\u{0020}and\u{0020}was\u{0020}the\u{0020}leader\u{0020}of\u{0020}the\u{0020}previous\u{0020}squad,\u{0020}but\u{0020}she\u{0020}was\u{0020}more\u{0020}or\u{0020}less\u{0020}a\u{0020}\"nobody\"\u{0020}before\u{0020}the\u{0020}formation\u{0020}of\u{0020}the\u{0020}\"Iron\u{0020}Crow\"\u{0020}compared\u{0020}to\u{0020}the\u{0020}other\u{0020}outstanding\u{0020}leaders\u{0020}of\u{0020}the\u{0020}Danube\u{0020}branch.\u{0020}Although\u{0020}in\u{0020}terms\u{0020}of\u{0020}ability,\u{0020}she\u{0020}is\u{0020}not\u{0020}much\u{0020}worse\u{0020}than\u{0020}the\u{0020}excellent\u{0020}driver\u{0020}leader,\u{0020}she\u{0020}really\u{0020}only\u{0020}lacks\u{0020}an\u{0020}opportunity\u{0020}to\u{0020}show\u{0020}herself.\n\nShe\u{0020}doesn't\u{0020}care\u{0020}about\u{0020}it,\u{0020}and\u{0020}no\u{0020}one\u{0020}will\u{0020}care\u{0020}about\u{0020}it\u{0020}-\u{0020}drivers\u{0020}are\u{0020}soldiers,\u{0020}and\u{0020}they\u{0020}don't\u{0020}need\u{0020}to\u{0020}be\u{0020}known\u{0020}and\u{0020}discussed.\n\nIt\u{0020}was\u{0020}only\u{0020}after\u{0020}the\u{0020}\"Major\u{0020}Sin\u{0020}Envy\u{0020}Incident\"\u{0020}was\u{0020}over\u{0020}that\u{0020}she\u{0020}was\u{0020}selected\u{0020}for\u{0020}the\u{0020}special\u{0020}unit\u{0020}\"Iron\u{0020}Crow\",\u{0020}which\u{0020}was\u{0020}created\u{0020}due\u{0020}to\u{0020}the\u{0020}needs\u{0020}of\u{0020}the\u{0020}Danube\u{0020}branch\u{0020}and\u{0020}her\u{0020}experience\u{0020}in\u{0020}combat,\u{0020}that\u{0020}she\u{0020}came\u{0020}to\u{0020}prominence.\n\n\n\nIt's\u{0020}also\u{0020}because\u{0020}of\u{0020}the\u{0020}attention\u{0020}she\u{0020}gets\u{0020}that\u{0020}some\u{0020}of\u{0020}her\u{0020}little\u{0020}problems\u{0020}are\u{0020}discovered.\u{0020}However,\u{0020}those\u{0020}minor\u{0020}problems\u{0020}did\u{0020}not\u{0020}affect\u{0020}her\u{0020}evaluation\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}the\u{0020}Danube\u{0020}hierarchy,\u{0020}and\u{0020}she\u{0020}is\u{0020}still\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Iron\u{0020}Crow\u{0020}who\u{0020}deserves\u{0020}the\u{0020}trust\u{0020}of\u{0020}the\u{0020}Danube\u{0020}branch.\n\nOn\u{0020}the\u{0020}other\u{0020}hand,\u{0020}\"Having\u{0020}no\u{0020}sense\u{0020}of\u{0020}direction\u{0020}but\u{0020}always\u{0020}good\u{0020}at\u{0020}detective\u{0020}work,\u{0020}she's\u{0020}really\u{0020}good!\"\u{0020}This\u{0020}kind\u{0020}of\u{0020}compliment\u{0020}with\u{0020}some\u{0020}malicious\u{0020}words\u{0020}among\u{0020}the\u{0020}ordinary\u{0020}drivers\u{0020}also\u{0020}gradually\u{0020}increased.\n\nEven\u{0020}if\u{0020}this\u{0020}kind\u{0020}of\u{0020}sarcasm\u{0020}and\u{0020}compliments\u{0020}are\u{0020}heard\u{0020}by\u{0020}Lepani,\u{0020}she\u{0020}doesn't\u{0020}care.\u{0020}Her\u{0020}ability\u{0020}to\u{0020}face\u{0020}outsiders\u{0020}with\u{0020}a\u{0020}gentle\u{0020}and\u{0020}generous\u{0020}smile\u{0020}at\u{0020}all\u{0020}times\u{0020}is\u{0020}one\u{0020}of\u{0020}the\u{0020}most\u{0020}admirable\u{0020}things\u{0020}about\u{0020}her.\n\nOf\u{0020}course,\u{0020}it\u{0020}would\u{0020}be\u{0020}more\u{0020}believable\u{0020}if\u{0020}she\u{0020}could\u{0020}cut\u{0020}down\u{0020}on\u{0020}her\u{0020}ludicrous\u{0020}rhetoric\u{0020}and\u{0020}unsettling\u{0020}atrocities.", "0", "0", "0", "0", 12022, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622203] = {622203, 1000, "\u{0020}\u{0020}Lepani's\u{0020}remark\u{0020}leaves\u{0020}people\u{0020}wondering\u{0020}whether\u{0020}she\u{0020}was\u{0020}joking\u{0020}or\u{0020}serious,\u{0020}not\u{0020}to\u{0020}mention\u{0020}some\u{0020}of\u{0020}her\u{0020}actions\u{0020}were\u{0020}a\u{0020}bit\u{0020}over\u{0020}the\u{0020}top\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}others,\u{0020}most\u{0020}of\u{0020}which\u{0020}would\u{0020}be\u{0020}hated\u{0020}by\u{0020}others,\u{0020}but\u{0020}if\u{0020}it's\u{0020}Lepani,\u{0020}it\u{0020}was\u{0020}natural\u{0020}that\u{0020}people\u{0020}couldn't\u{0020}hate\u{0020}her.\n\nThis\u{0020}might\u{0020}have\u{0020}something\u{0020}to\u{0020}do\u{0020}with\u{0020}Lepani's\u{0020}temperament\u{0020}and\u{0020}looks.\u{0020}A\u{0020}girl\u{0020}as\u{0020}angelic\u{0020}as\u{0020}her,\u{0020}no\u{0020}matter\u{0020}what\u{0020}peculiar\u{0020}things\u{0020}she\u{0020}may\u{0020}do,\u{0020}will\u{0020}still\u{0020}be\u{0020}forgiven\u{0020}and\u{0020}loved.\n\nThis\u{0020}charm\u{0020}of\u{0020}hers\u{0020}is\u{0020}what\u{0020}convinced\u{0020}Caroline\u{0020}and\u{0020}Zepar\u{0020}to\u{0020}leave\u{0020}their\u{0020}teams\u{0020}and\u{0020}form\u{0020}the\u{0020}\"Iron\u{0020}Crow\"\u{0020}with\u{0020}her.\n\n\"When\u{0020}I'm\u{0020}with\u{0020}Captain\u{0020}Lepani,\u{0020}I\u{0020}feel\u{0020}happy\u{0020}no\u{0020}matter\u{0020}what\u{0020}I\u{0020}do,\u{0020}at\u{0020}least\u{0020}that's\u{0020}what\u{0020}I\u{0020}think.\"", "0", "0", "0", "0", 12022, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[622204] = {622204, 2000, "\u{0020}\u{0020}The\u{0020}young\u{0020}girl\u{0020}seemed\u{0020}to\u{0020}be\u{0020}out\u{0020}for\u{0020}a\u{0020}stroll,\u{0020}walking\u{0020}on\u{0020}a\u{0020}remote\u{0020}island.\n\nLepani\u{0020}looked\u{0020}as\u{0020}comfortable\u{0020}as\u{0020}if\u{0020}she\u{0020}were\u{0020}in\u{0020}her\u{0020}own\u{0020}backyard.\n\n\"It's\u{0020}true,\u{0020}you\u{0020}don't\u{0020}have\u{0020}to\u{0020}worry\u{0020}about\u{0020}getting\u{0020}lost\u{0020}if\u{0020}you\u{0020}have\u{0020}a\u{0020}navigator\u{0020}around.\"\n\n\"Synaesthesia\u{0020}is\u{0020}such\u{0020}a\u{0020}great\u{0020}ability...\u{0020}if\u{0020}only\u{0020}everyone\u{0020}could\u{0020}have\u{0020}it,\u{0020}then\u{0020}no\u{0020}one\u{0020}would\u{0020}ever\u{0020}get\u{0020}lost.\"\n\nAs\u{0020}she\u{0020}said\u{0020}that,\u{0020}she\u{0020}looked\u{0020}at\u{0020}the\u{0020}small,\u{0020}bound\u{0020}Navigator\u{0020}dangling\u{0020}over\u{0020}her\u{0020}chest.\n\n\"However,\u{0020}if\u{0020}you're\u{0020}tied\u{0020}up\u{0020}like\u{0020}this..then\u{0020}Navigator\u{0020}can't\u{0020}go\u{0020}anywhere,\u{0020}right?\u{0020}That's\u{0020}right,\u{0020}we'll\u{0020}never\u{0020}be\u{0020}separated!\"\n\nAs\u{0020}for\u{0020}Navigator's\u{0020}complaints..presumably,\u{0020}the\u{0020}girl\u{0020}could\u{0020}not\u{0020}hear\u{0020}them\u{0020}at\u{0020}the\u{0020}moment.", "0", "0", "0", "0", 12022, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
