[622301] = {622301, 100, "\u{0020}\u{0020}\"The\u{0020}Academy's\u{0020}Shooting\u{0020}Star\"\u{0020}-\u{0020}that's\u{0020}what\u{0020}some\u{0020}of\u{0020}the\u{0020}students\u{0020}at\u{0020}Sahara's\u{0020}Azure\u{0020}Academy\u{0020}once\u{0020}called\u{0020}Stella,\u{0020}a\u{0020}title\u{0020}with\u{0020}a\u{0020}distinctly\u{0020}mocking\u{0020}and\u{0020}sarcastic\u{0020}connotation,\u{0020}but\u{0020}one\u{0020}that\u{0020}is\u{0020}now\u{0020}almost\u{0020}a\u{0020}thing\u{0020}of\u{0020}the\u{0020}past.\n\nDuring\u{0020}Stella's\u{0020}first\u{0020}years\u{0020}as\u{0020}a\u{0020}teacher,\u{0020}her\u{0020}presence\u{0020}was\u{0020}scarce,\u{0020}her\u{0020}movements\u{0020}unpredictable,\u{0020}like\u{0020}a\u{0020}shooting\u{0020}star,\u{0020}even\u{0020}to\u{0020}the\u{0020}point\u{0020}of\u{0020}repeatedly\u{0020}skipping\u{0020}lectures\u{0020}and\u{0020}leaving\u{0020}students\u{0020}waiting,\u{0020}a\u{0020}behavior\u{0020}unheard\u{0020}of\u{0020}throughout\u{0020}the\u{0020}college.\u{0020}While\u{0020}occasionally\u{0020}missing\u{0020}lectures\u{0020}for\u{0020}inexperienced\u{0020}student\u{0020}drivers\u{0020}is\u{0020}nothing\u{0020}new,\u{0020}Stella's\u{0020}behavior\u{0020}as\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}faculty\u{0020}is\u{0020}anything\u{0020}but.\n\nIt's\u{0020}easy\u{0020}to\u{0020}discern\u{0020}that\u{0020}Stella\u{0020}is\u{0020}not\u{0020}an\u{0020}irrational\u{0020}person,\u{0020}but\u{0020}rather\u{0020}an\u{0020}introverted,\u{0020}repressed\u{0020}individual\u{0020}who\u{0020}apologizes\u{0020}and\u{0020}belittles\u{0020}herself\u{0020}when\u{0020}she's\u{0020}criticized\u{0020}and\u{0020}whose\u{0020}words\u{0020}and\u{0020}actions\u{0020}reveal\u{0020}a\u{0020}sense\u{0020}of\u{0020}weakness\u{0020}and\u{0020}decadence.\u{0020}Based\u{0020}on\u{0020}this\u{0020}attitude,\u{0020}it's\u{0020}obvious\u{0020}that\u{0020}she's\u{0020}aware\u{0020}of\u{0020}her\u{0020}mistakes,\u{0020}yet\u{0020}often\u{0020}repeats\u{0020}them,\u{0020}as\u{0020}if\u{0020}they\u{0020}were\u{0020}caused\u{0020}by\u{0020}some\u{0020}kind\u{0020}of\u{0020}uncontrollable\u{0020}force.\n\nAnd\u{0020}indeed\u{0020}it\u{0020}was;\u{0020}After\u{0020}all,\u{0020}Stella\u{0020}could\u{0020}still\u{0020}be\u{0020}teaching\u{0020}military\u{0020}strategy,\u{0020}principles\u{0020}of\u{0020}communication,\u{0020}camouflage\u{0020}and\u{0020}stealth\u{0020}as\u{0020}normal,\u{0020}and\u{0020}every\u{0020}class\u{0020}she\u{0020}was\u{0020}intentionally\u{0020}avoiding\u{0020}was\u{0020}the\u{0020}one\u{0020}in\u{0020}which\u{0020}she\u{0020}excelled\u{0020}as\u{0020}a\u{0020}sniping\u{0020}instructor.\u{0020}Even\u{0020}her\u{0020}students\u{0020}can\u{0020}easily\u{0020}notice\u{0020}this\u{0020}level\u{0020}of\u{0020}remarkable\u{0020}abnormality.", "0", "0", "0", "0", 12023, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622302] = {622302, 500, "\u{0020}\u{0020}Through\u{0020}study\u{0020}and\u{0020}evaluation,\u{0020}it's\u{0020}clear\u{0020}that\u{0020}Stella's\u{0020}introverted\u{0020}and\u{0020}repressed\u{0020}personality,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}patience\u{0020}and\u{0020}endurance\u{0020}that\u{0020}are\u{0020}the\u{0020}most\u{0020}important\u{0020}qualities\u{0020}of\u{0020}a\u{0020}good\u{0020}sniper,\u{0020}took\u{0020}root\u{0020}in\u{0020}her\u{0020}childhood\u{0020}when\u{0020}her\u{0020}family\u{0020}was\u{0020}struggling\u{0020}to\u{0020}make\u{0020}ends\u{0020}meet.\u{0020}Just\u{0020}as\u{0020}plants\u{0020}look\u{0020}to\u{0020}the\u{0020}sun,\u{0020}people\u{0020}seem\u{0020}to\u{0020}have\u{0020}an\u{0020}instinctive\u{0020}longing\u{0020}for\u{0020}the\u{0020}heavens.\u{0020}Even\u{0020}children\u{0020}who\u{0020}have\u{0020}not\u{0020}been\u{0020}exposed\u{0020}to\u{0020}art\u{0020}or\u{0020}philosophy\u{0020}will\u{0020}naturally\u{0020}develop\u{0020}a\u{0020}simple\u{0020}yet\u{0020}grandiose\u{0020}hobby\u{0020}that\u{0020}seems\u{0020}to\u{0020}be\u{0020}genetically\u{0020}ingrained\u{0020}in\u{0020}their\u{0020}nature:\u{0020}stargazing.\u{0020}Stella\u{0020}has\u{0020}been\u{0020}fascinated\u{0020}by\u{0020}the\u{0020}beauty\u{0020}and\u{0020}mystery\u{0020}of\u{0020}celestial\u{0020}bodies\u{0020}since\u{0020}she\u{0020}was\u{0020}a\u{0020}child,\u{0020}but\u{0020}her\u{0020}family's\u{0020}circumstances\u{0020}prevented\u{0020}her\u{0020}from\u{0020}spreading\u{0020}her\u{0020}wings\u{0020}further.\u{0020}With\u{0020}the\u{0020}exorbitant\u{0020}cost\u{0020}of\u{0020}telescopes\u{0020}and\u{0020}the\u{0020}free\u{0020}observatory\u{0020}viewed\u{0020}by\u{0020}her\u{0020}elders\u{0020}as\u{0020}an\u{0020}alternative\u{0020}amusement\u{0020}park,\u{0020}Stella\u{0020}spent\u{0020}her\u{0020}childhood\u{0020}in\u{0020}a\u{0020}long-term\u{0020}agreement\u{0020}where\u{0020}perfect\u{0020}grades\u{0020}were\u{0020}her\u{0020}price\u{0020}of\u{0020}admission.\n\nA\u{0020}high-stakes\u{0020}mission\u{0020}leads\u{0020}to\u{0020}a\u{0020}radical\u{0020}shift\u{0020}in\u{0020}the\u{0020}way\u{0020}Stella\u{0020}viewed\u{0020}her\u{0020}job.\u{0020}As\u{0020}usual,\u{0020}Stella\u{0020}was\u{0020}positioned\u{0020}on\u{0020}a\u{0020}hill\u{0020}far\u{0020}from\u{0020}the\u{0020}battlefield.\u{0020}She\u{0020}set\u{0020}up\u{0020}her\u{0020}weapon\u{0020}and\u{0020}watched\u{0020}the\u{0020}Haze-covered\u{0020}war\u{0020}zone\u{0020}through\u{0020}her\u{0020}goggles,\u{0020}waiting\u{0020}for\u{0020}the\u{0020}fox-like\u{0020}Major\u{0020}Sin\u{0020}to\u{0020}show\u{0020}up.\u{0020}But,\u{0020}perhaps\u{0020}due\u{0020}to\u{0020}the\u{0020}cunning\u{0020}nature\u{0020}of\u{0020}her\u{0020}prey,\u{0020}Stella\u{0020}and\u{0020}the\u{0020}investigation\u{0020}department\u{0020}were\u{0020}slow\u{0020}to\u{0020}detect\u{0020}it\u{0020}and,\u{0020}since\u{0020}a\u{0020}strategic\u{0020}sniper's\u{0020}job\u{0020}is\u{0020}to\u{0020}wait\u{0020}patiently\u{0020}for\u{0020}the\u{0020}target\u{0020}to\u{0020}show\u{0020}up\u{0020}and\u{0020}then\u{0020}strike,\u{0020}she\u{0020}couldn't\u{0020}afford\u{0020}to\u{0020}shoot\u{0020}ahead\u{0020}of\u{0020}time\u{0020}and\u{0020}surprise\u{0020}the\u{0020}enemy.\u{0020}The\u{0020}longer\u{0020}the\u{0020}battle\u{0020}dragged\u{0020}on,\u{0020}the\u{0020}worse\u{0020}it\u{0020}would\u{0020}be\u{0020}for\u{0020}those\u{0020}in\u{0020}the\u{0020}Haze.\u{0020}Stella's\u{0020}teammates\u{0020}were\u{0020}losing\u{0020}ground\u{0020}yet,\u{0020}at\u{0020}the\u{0020}same\u{0020}time\u{0020},the\u{0020}commander's\u{0020}voice\u{0020}on\u{0020}the\u{0020}communicator\u{0020}kept\u{0020}her\u{0020}waiting.\n\nThrough\u{0020}the\u{0020}narrow\u{0020}barrel\u{0020}of\u{0020}the\u{0020}scope,\u{0020}Stella's\u{0020}gaze\u{0020}travels\u{0020}through\u{0020}distance,\u{0020}tens\u{0020}of\u{0020}kilometers,\u{0020}to\u{0020}her\u{0020}teammates.\u{0020}But,\u{0020}even\u{0020}though\u{0020}they\u{0020}appear\u{0020}to\u{0020}be\u{0020}close,\u{0020}she\u{0020}can\u{0020}only\u{0020}watch\u{0020}as\u{0020}they\u{0020}fall\u{0020}into\u{0020}dangerous\u{0020}situations,\u{0020}unable\u{0020}to\u{0020}fight\u{0020}alongside\u{0020}them.\u{0020}On\u{0020}a\u{0020}mission\u{0020}of\u{0020}waiting\u{0020}and\u{0020}enduring,\u{0020}she\u{0020}pushed\u{0020}down\u{0020}her\u{0020}unbearable\u{0020}restlessness\u{0020}and\u{0020}kept\u{0020}herself\u{0020}calm\u{0020}as\u{0020}a\u{0020}sniper\u{0020}should.\u{0020}At\u{0020}the\u{0020}very\u{0020}least,\u{0020}she\u{0020}can't\u{0020}let\u{0020}her\u{0020}trembling\u{0020}hands\u{0020}ruin\u{0020}the\u{0020}shot\u{0020}her\u{0020}teammates\u{0020}are\u{0020}trying\u{0020}so\u{0020}hard\u{0020}to\u{0020}create\u{0020}for\u{0020}her.\n\nHowever,\u{0020}the\u{0020}mission\u{0020}ended\u{0020}in\u{0020}failure.\u{0020}Their\u{0020}Sin\u{0020}target\u{0020}seemingly\u{0020}sensed\u{0020}the\u{0020}danger\u{0020}and\u{0020}never\u{0020}emerged\u{0020}until\u{0020}the\u{0020}Haze\u{0020}had\u{0020}cleared.\u{0020}Her\u{0020}patience\u{0020}and\u{0020}the\u{0020}wounds\u{0020}of\u{0020}her\u{0020}comrades\u{0020}were\u{0020}in\u{0020}vain\u{0020}and\u{0020}a\u{0020}sense\u{0020}of\u{0020}emptiness\u{0020}and\u{0020}guilt\u{0020}washed\u{0020}over\u{0020}Stella,\u{0020}often\u{0020}regretting\u{0020}what\u{0020}might\u{0020}have\u{0020}been\u{0020}if\u{0020}she\u{0020}had\u{0020}fired\u{0020}her\u{0020}weapon\u{0020}earlier.\u{0020}Whenever\u{0020}she\u{0020}used\u{0020}the\u{0020}scope,\u{0020}Stella\u{0020}would\u{0020}see\u{0020}her\u{0020}teammates\u{0020}falling\u{0020}with\u{0020}grave\u{0020}injuries\u{0020}and\u{0020}her\u{0020}own\u{0020}incompetence.\u{0020}Even\u{0020}her\u{0020}love\u{0020}of\u{0020}stargazing\u{0020}was\u{0020}affected,\u{0020}seeing\u{0020}stars\u{0020}that\u{0020}appear\u{0020}to\u{0020}be\u{0020}within\u{0020}her\u{0020}reach\u{0020}but\u{0020}were\u{0020}actually\u{0020}far\u{0020}away\u{0020}only\u{0020}reinforced\u{0020}her\u{0020}sense\u{0020}of\u{0020}helplessness.\u{0020}It\u{0020}remains\u{0020}to\u{0020}be\u{0020}seen\u{0020}whether\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}team\u{0020}still\u{0020}interacted\u{0020}with\u{0020}one\u{0020}another\u{0020}or\u{0020}whether\u{0020}Stellae's\u{0020}mental\u{0020}disorders\u{0020}had\u{0020}anything\u{0020}to\u{0020}do\u{0020}with\u{0020}it\u{0020}but,\u{0020}after\u{0020}she\u{0020}lost\u{0020}her\u{0020}ability\u{0020}to\u{0020}snipe\u{0020}and\u{0020}quit\u{0020}the\u{0020}team,\u{0020}it\u{0020}was\u{0020}time\u{0020}for\u{0020}the\u{0020}part\u{0020}we\u{0020}know\u{0020}so\u{0020}well\u{0020}-\u{0020}the\u{0020}leader\u{0020}of\u{0020}the\u{0020}Honeymakers,\u{0020}Priscilla\u{0020}was\u{0020}forced\u{0020}to\u{0020}take\u{0020}Stella\u{0020}into\u{0020}her\u{0020}care\u{0020}and\u{0020}then\u{0020}she\u{0020}was\u{0020}transferred\u{0020}to\u{0020}the\u{0020}Sahara\u{0020}Azure\u{0020}Academy\u{0020}as\u{0020}a\u{0020}teacher.", "0", "0", "0", "0", 12023, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
