[622403] = {622403, 1000, "\u{3000}\u{3000}In\u{0020}the\u{0020}real\u{0020}world.\n\n\u{3000}\u{3000}\"Hmm...\u{0020}this\u{0020}is\u{0020}weird...\"\u{0020}Franca\u{0020}paused\u{0020}mid-bite,\u{0020}chopsticks\u{0020}hovering.\n\n\u{3000}\u{3000}\"What?\u{0020}Is\u{0020}my\u{0020}cooking\u{0020}that\u{0020}strange?\"\n\n\u{3000}\u{3000}\"No,\u{0020}no!\u{0020}Not\u{0020}the\u{0020}taste.\u{0020}Just...\u{0020}it\u{0020}feels\u{0020}strange.\"\u{0020}She\u{0020}prodded\u{0020}at\u{0020}the\u{0020}dish,\u{0020}an\u{0020}act\u{0020}that\u{0020}would've\u{0020}been\u{0020}told\u{0020}off\u{0020}if\u{0020}not\u{0020}for\u{0020}the\u{0020}fact\u{0020}that\u{0020}she'd\u{0020}eventually\u{0020}eat\u{0020}it.\u{0020}\"This\u{0020}whole\u{0020}spread\u{0020}looks\u{0020}so\u{0020}ordinary...\u{0020}and\u{0020}yet,\u{0020}every\u{0020}single\u{0020}dish\u{0020}seems\u{0020}to\u{0020}be\u{0020}my\u{0020}favorite.\u{0020}Navigator...\"\n\n\u{3000}\u{3000}The\u{0020}unspoken\u{0020}accusation\u{0020}in\u{0020}her\u{0020}words\u{0020}was\u{0020}clear.\u{0020}\"How\u{0020}would\u{0020}you\u{0020}know\u{0020}what\u{0020}home-cooked\u{0020}meals\u{0020}I\u{0020}love?\"\u{0020}Such\u{0020}knowledge\u{0020}could\u{0020}only\u{0020}come\u{0020}from\u{0020}meticulous\u{0020}research.\n\n\u{3000}\u{3000}\"I've\u{0020}been\u{0020}dreaming\u{0020}about\u{0020}cooking\u{0020}these\u{0020}dishes\u{0020}lately.\"\n\n\u{3000}\u{3000}\"D...\u{0020}dreaming?\"\u{0020}The\u{0020}excuse\u{0020}was\u{0020}lame,\u{0020}but\u{0020}since\u{0020}the\u{0020}food\u{0020}suited\u{0020}her\u{0020}tastes,\u{0020}she\u{0020}let\u{0020}it\u{0020}slide.\n\n\u{3000}\u{3000}Abandoning\u{0020}the\u{0020}dish\u{0020}she'd\u{0020}been\u{0020}poking,\u{0020}she\u{0020}reached\u{0020}for\u{0020}another,\u{0020}though\u{0020}it\u{0020}was\u{0020}too\u{0020}soon\u{0020}to\u{0020}convict\u{0020}her\u{0020}of\u{0020}playing\u{0020}with\u{0020}her\u{0020}food.", "0", "0", "0", "0", 12024, "0", "0", "0", "0", 1, 4, "0"