[622501] = {622501, 100, "\u{3000}\u{3000}There\u{0020}has\u{0020}never\u{0020}been\u{0020}any\u{0020}shortage\u{0020}of\u{0020}geniuses\u{0020}among\u{0020}Aegis's\u{0020}drivers.\u{0020}In\u{0020}an\u{0020}organization\u{0020}where\u{0020}a\u{0020}person's\u{0020}evaluation\u{0020}and\u{0020}standing\u{0020}are\u{0020}determined\u{0020}by\u{0020}their\u{0020}performance\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}such\u{0020}geniuses\u{0020}are\u{0020}destined\u{0020}never\u{0020}to\u{0020}go\u{0020}unnoticed.\u{0020}Like\u{0020}stars\u{0020}gathered\u{0020}beneath\u{0020}the\u{0020}night\u{0020}sky,\u{0020}they\u{0020}will\u{0020}shine\u{0020}forever.\n\u{3000}\u{3000}These\u{0020}geniuses\u{0020}will\u{0020}become\u{0020}humanity's\u{0020}heroes,\u{0020}playing\u{0020}crucial\u{0020}roles\u{0020}in\u{0020}the\u{0020}war\u{0020}between\u{0020}humankind\u{0020}and\u{0020}Sin.\u{0020}By\u{0020}contrast,\u{0020}those\u{0020}unremarkable\u{0020}drivers\u{0020}will\u{0020}only\u{0020}become\u{0020}silent\u{0020}contributors\u{0020}to\u{0020}the\u{0020}war,\u{0020}never\u{0020}noticed\u{0020}by\u{0020}anyone.\n\u{3000}\u{3000},Such\u{0020}thinking\u{0020}is\u{0020}a\u{0020}tremendous\u{0020}fallacy.\n\u{3000}\u{3000}And\u{0020}yet\u{0020}Felin\u{0020}Branny\u{0020}cannot\u{0020}stop\u{0020}herself\u{0020}from\u{0020}thinking\u{0020}this\u{0020}way.\n\u{3000}\u{3000}As\u{0020}an\u{0020}ordinary\u{0020}driver\u{0020}who\u{0020}just\u{0020}so\u{0020}happened\u{0020}to\u{0020}have\u{0020}the\u{0020}qualifications\u{0020}to\u{0020}become\u{0020}one,\u{0020}and\u{0020}thus\u{0020}gained\u{0020}the\u{0020}chance\u{0020}to\u{0020}come\u{0020}into\u{0020}contact\u{0020}with\u{0020}those\u{0020}geniuses,\u{0020}Felin\u{0020}always\u{0020}tells\u{0020}herself\u{0020}that\u{0020}she\u{0020}is\u{0020}no\u{0020}different\u{0020}from\u{0020}them,\u{0020}that\u{0020}all\u{0020}of\u{0020}them\u{0020}are\u{0020}fighting\u{0020}for\u{0020}humanity.\n\u{3000}\u{3000}But\u{0020}she\u{0020}cannot\u{0020}suppress\u{0020}the\u{0020}darkness\u{0020}in\u{0020}her\u{0020}heart,every\u{0020}night,\u{0020}she\u{0020}resents\u{0020}the\u{0020}fact\u{0020}that\u{0020}she\u{0020}is\u{0020}nothing\u{0020}more\u{0020}than\u{0020}an\u{0020}ordinary\u{0020}person.\n\u{3000}\u{3000}It\u{0020}is\u{0020}precisely\u{0020}because\u{0020}she\u{0020}can\u{0020}come\u{0020}into\u{0020}contact\u{0020}with\u{0020}geniuses\u{0020}that\u{0020}she\u{0020}has\u{0020}become\u{0020}aware\u{0020}of\u{0020}her\u{0020}own\u{0020}inadequacy,\u{0020}and\u{0020}thus\u{0020}come\u{0020}to\u{0020}hate\u{0020}her\u{0020}own\u{0020}powerlessness.\n\u{3000}\u{3000}Perhaps\u{0020}Felin\u{0020}Branny\u{0020}is\u{0020}destined\u{0020}never\u{0020}to\u{0020}become\u{0020}a\u{0020}hero.", "0", "0", "0", "0", 12025, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622502] = {622502, 500, "\u{3000}\u{3000}This\u{0020}is\u{0020}a\u{0020}feeling\u{0020}that\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}people\u{0020}have\u{0020}experienced\u{0020}at\u{0020}some\u{0020}point.\n\u{3000}\u{3000}Because\u{0020}they\u{0020}perform\u{0020}above\u{0020}average\u{0020}in\u{0020}some\u{0020}area,\u{0020}they\u{0020}begin\u{0020}to\u{0020}think\u{0020}of\u{0020}themselves\u{0020}as\u{0020}talented,\u{0020}and\u{0020}then\u{0020}as\u{0020}someone\u{0020}special,in\u{0020}other\u{0020}words,\u{0020}they\u{0020}naturally\u{0020}come\u{0020}to\u{0020}assume\u{0020}that\u{0020}they\u{0020}are\u{0020}the\u{0020}protagonist.\n\u{3000}\u{3000}Then,\u{0020}at\u{0020}some\u{0020}point\u{0020}along\u{0020}the\u{0020}road\u{0020}of\u{0020}life,\u{0020}they\u{0020}begin\u{0020}to\u{0020}notice\u{0020}the\u{0020}truth\u{0020}hidden\u{0020}beneath\u{0020}the\u{0020}surface.\n\u{3000}\u{3000}For\u{0020}Felin,\u{0020}that\u{0020}stage\u{0020}likely\u{0020}came\u{0020}after\u{0020}she\u{0020}officially\u{0020}became\u{0020}a\u{0020}driver.\n\u{3000}\u{3000}Coming\u{0020}from\u{0020}a\u{0020}small\u{0020}city,\u{0020}she\u{0020}stood\u{0020}out\u{0020}in\u{0020}the\u{0020}compatibility\u{0020}test\u{0020}thanks\u{0020}to\u{0020}her\u{0020}relatively\u{0020}strong\u{0020}aptitude\u{0020}rate\u{0020}and\u{0020}became\u{0020}a\u{0020}member\u{0020}of\u{0020}Azure\u{0020}Academy.\u{0020}Her\u{0020}solid\u{0020}academic\u{0020}performance,\u{0020}her\u{0020}\"Excellent\"\u{0020}rating\u{0020}in\u{0020}simulated\u{0020}combat,\u{0020}and\u{0020}the\u{0020}ease\u{0020}with\u{0020}which\u{0020}she\u{0020}carried\u{0020}herself\u{0020}all\u{0020}led\u{0020}her\u{0020}to\u{0020}believe\u{0020}that\u{0020}she\u{0020}was\u{0020}a\u{0020}\"genius.\"\n\u{3000}\u{3000}But\u{0020}after\u{0020}becoming\u{0020}a\u{0020}driver,\u{0020}she\u{0020}discovered\u{0020}that\u{0020}the\u{0020}world\u{0020}looked\u{0020}different.\n\u{3000}\u{3000}Combat\u{0020}was\u{0020}nothing\u{0020}like\u{0020}she\u{0020}had\u{0020}imagined,\u{0020}and\u{0020}the\u{0020}enemies\u{0020}she\u{0020}faced\u{0020}were\u{0020}completely\u{0020}different\u{0020}from\u{0020}those\u{0020}in\u{0020}simulation\u{0020}battles.\u{0020}Her\u{0020}self-satisfied\u{0020}mock\u{0020}battle\u{0020}results\u{0020}and\u{0020}decent\u{0020}adaptability\u{0020}were\u{0020}nowhere\u{0020}near\u{0020}enough\u{0020}to\u{0020}let\u{0020}her\u{0020}navigate\u{0020}the\u{0020}battlefield\u{0020}with\u{0020}ease,just\u{0020}forcing\u{0020}herself\u{0020}to\u{0020}stay\u{0020}calm\u{0020}enough\u{0020}to\u{0020}aim\u{0020}and\u{0020}fire\u{0020}already\u{0020}took\u{0020}everything\u{0020}she\u{0020}had.\n\u{3000}\u{3000}At\u{0020}last,\u{0020}she\u{0020}realized\u{0020}that\u{0020}she\u{0020}was\u{0020}only\u{0020}an\u{0020}ordinary\u{0020}person\u{0020}who\u{0020}happened\u{0020}to\u{0020}be\u{0020}fairly\u{0020}capable,\u{0020}someone\u{0020}with\u{0020}just\u{0020}enough\u{0020}talent\u{0020}to\u{0020}stand\u{0020}on\u{0020}this\u{0020}stage,\u{0020}but\u{0020}not\u{0020}enough\u{0020}to\u{0020}become\u{0020}the\u{0020}\"protagonist.\"\n\u{3000}\u{3000}As\u{0020}a\u{0020}warrior\u{0020}fighting\u{0020}for\u{0020}humanity's\u{0020}survival,\u{0020}she\u{0020}knew\u{0020}she\u{0020}should\u{0020}not\u{0020}be\u{0020}so\u{0020}narrow-minded.\u{0020}So\u{0020}she\u{0020}learned\u{0020}to\u{0020}make\u{0020}peace\u{0020}with\u{0020}it,\u{0020}learned\u{0020}to\u{0020}accept\u{0020}her\u{0020}own\u{0020}mediocrity,\u{0020}and\u{0020}learned\u{0020}to\u{0020}play\u{0020}the\u{0020}role\u{0020}of\u{0020}an\u{0020}ordinary\u{0020}member\u{0020}within\u{0020}her\u{0020}squad\u{0020}while\u{0020}getting\u{0020}along\u{0020}well\u{0020}with\u{0020}her\u{0020}comrades.\n\u{3000}\u{3000}This\u{0020}is\u{0020}what\u{0020}growth\u{0020}means,\u{0020}she\u{0020}thought.", "0", "0", "0", "0", 12025, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622503] = {622503, 1000, "\u{3000}\u{3000}After\u{0020}the\u{0020}incident\u{0020}in\u{0020}which\u{0020}Envy\u{0020}invaded\u{0020}Saar\u{0020}City\u{0020}came\u{0020}to\u{0020}an\u{0020}end,\u{0020}Felin\u{0020}Branny,who\u{0020}had\u{0020}been\u{0020}dealing\u{0020}with\u{0020}certain\u{0020}psychological\u{0020}issues\u{0020}ever\u{0020}since\u{0020}becoming\u{0020}a\u{0020}driver,was\u{0020}deemed\u{0020}no\u{0020}longer\u{0020}fit\u{0020}to\u{0020}serve\u{0020}as\u{0020}a\u{0020}driver,\u{0020}and\u{0020}was\u{0020}therefore\u{0020}transferred\u{0020}to\u{0020}the\u{0020}Department\u{0020}of\u{0020}Social\u{0020}Restoration,\u{0020}where\u{0020}she\u{0020}took\u{0020}charge\u{0020}of\u{0020}post-disaster\u{0020}urban\u{0020}reconstruction\u{0020}work.\n\u{3000}\u{3000}About\u{0020}half\u{0020}a\u{0020}year\u{0020}later,\u{0020}upon\u{0020}the\u{0020}recommendation\u{0020}of\u{0020}Valkyrie's\u{0020}captain\u{0020}and\u{0020}her\u{0020}team\u{0020}members,\u{0020}Felin\u{0020}Branny\u{0020}regained\u{0020}her\u{0020}status\u{0020}as\u{0020}a\u{0020}driver\u{0020}and\u{0020}joined\u{0020}the\u{0020}squad\u{0020}\"Atrium.\"\u{0020}The\u{0020}squad's\u{0020}primary\u{0020}duty\u{0020}is\u{0020}to\u{0020}assist\u{0020}the\u{0020}First\u{0020}Research\u{0020}Lab\u{0020}and\u{0020}Valkyrie\u{0020}in\u{0020}carrying\u{0020}out\u{0020}special\u{0020}missions,in\u{0020}other\u{0020}words,\u{0020}it\u{0020}is\u{0020}a\u{0020}special\u{0020}unit\u{0020}whose\u{0020}specific\u{0020}assignments\u{0020}are\u{0020}not\u{0020}made\u{0020}public.\n\u{3000}\u{3000}There\u{0020}was\u{0020}once\u{0020}a\u{0020}driver\u{0020}with\u{0020}little\u{0020}presence\u{0020}who\u{0020}believed\u{0020}that\u{0020}\"although\u{0020}the\u{0020}meanings\u{0020}are\u{0020}similar,\u{0020}ordinary\u{0020}is\u{0020}not\u{0020}the\u{0020}same\u{0020}as\u{0020}mediocre,\"\u{0020}but\u{0020}Felin\u{0020}considers\u{0020}herself\u{0020}the\u{0020}very\u{0020}embodiment\u{0020}of\u{0020}\"mediocrity.\"\n\u{3000}\u{3000}Now,\u{0020}Felin\u{0020}Branny\u{0020}has\u{0020}accepted\u{0020}her\u{0020}own\u{0020}mediocrity,\u{0020}accepted\u{0020}her\u{0020}own\u{0020}weakness,\u{0020}and\u{0020}resolved\u{0020}to\u{0020}face\u{0020}this\u{0020}world\u{0020}as\u{0020}her\u{0020}true\u{0020}self.\n\u{3000}\u{3000}She\u{0020}will\u{0020}keep\u{0020}her\u{0020}feet\u{0020}on\u{0020}the\u{0020}ground\u{0020}and,\u{0020}as\u{0020}one\u{0020}ordinary\u{0020}person,\u{0020}leave\u{0020}behind\u{0020}as\u{0020}much\u{0020}of\u{0020}her\u{0020}own\u{0020}mark\u{0020}on\u{0020}this\u{0020}world\u{0020}as\u{0020}she\u{0020}can.", "0", "0", "0", "0", 12025, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
