[622601] = {622601, 100, "\u{3000}\u{3000}\"Lightning\u{0020}on\u{0020}the\u{0020}Battlefield\"\u{0020}now\u{0020}fights\u{0020}in\u{0020}a\u{0020}different\u{0020}form.\u{0020}No\u{0020}longer\u{0020}clad\u{0020}in\u{0020}the\u{0020}familiar\u{0020}black-and-white\u{0020}maid\u{0020}outfit,\u{0020}she\u{0020}has\u{0020}changed\u{0020}into\u{0020}a\u{0020}dashing\u{0020}riding\u{0020}suit.\n\u{3000}\u{3000}Her\u{0020}personality\u{0020}seems\u{0020}to\u{0020}have\u{0020}been\u{0020}affected\u{0020}by\u{0020}the\u{0020}outfit\u{0020}as\u{0020}well\u{0020}-\u{0020}or\u{0020}perhaps\u{0020}it\u{0020}is\u{0020}simply\u{0020}part\u{0020}of\u{0020}her\u{0020}professional\u{0020}dedication\u{0020}to\u{0020}\"playing\u{0020}the\u{0020}role\"\u{0020}-\u{0020}and\u{0020}compared\u{0020}to\u{0020}before,\u{0020}she\u{0020}seems\u{0020}far\u{0020}more\u{0020}unrestrained.\n\u{3000}\u{3000}Riding\u{0020}a\u{0020}roaring\u{0020}motorcycle\u{0020}down\u{0020}the\u{0020}highways\u{0020}of\u{0020}the\u{0020}wasteland,\u{0020}if\u{0020}she\u{0020}hears\u{0020}someone's\u{0020}cry\u{0020}for\u{0020}help,\u{0020}the\u{0020}battlefield\u{0020}lightning\u{0020}will\u{0020}make\u{0020}her\u{0020}entrance\u{0020}from\u{0020}the\u{0020}sky\u{0020}above\u{0020}(or\u{0020}by\u{0020}crashing\u{0020}through\u{0020}a\u{0020}wall)\u{0020}-\u{0020}Miss\u{0020}Lyfa,\u{0020}today\u{0020}as\u{0020}always,\u{0020}is\u{0020}carrying\u{0020}out\u{0020}Valkyrie's\u{0020}field\u{0020}missions\u{0020}with\u{0020}tireless\u{0020}devotion.\n\u{3000}\u{3000}\"Miss\u{0020}Lyfa\u{0020}is\u{0020}going\u{0020}to\u{0020}leave\u{0020}the\u{0020}mark\u{0020}of\u{0020}the\u{0020}Valkyrie\u{0020}Biker\u{0020}Gang\u{0020}all\u{0020}across\u{0020}the\u{0020}world!\"", "0", "0", "0", "0", 12026, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622602] = {622602, 500, "\u{3000}\u{3000}Valkyrie's\u{0020}duty\u{0020}is\u{0020}to\u{0020}guard\u{0020}the\u{0020}First\u{0020}Research\u{0020}Lab,\u{0020}just\u{0020}like\u{0020}the\u{0020}former\u{0020}Third\u{0020}Research\u{0020}Lab\u{0020}Defense\u{0020}Squad\u{0020}and\u{0020}the\u{0020}First\u{0020}Royal\u{0020}Guard\u{0020}Squad\u{0020}aboard\u{0020}the\u{0020}Danube\u{0020}Ark.\u{0020}In\u{0020}principle,\u{0020}they\u{0020}should\u{0020}be\u{0020}stationed\u{0020}at\u{0020}the\u{0020}First\u{0020}Research\u{0020}Lab\u{0020}at\u{0020}all\u{0020}times.\n\u{3000}\u{3000}But\u{0020}in\u{0020}reality\u{0020}-\u{0020}aside\u{0020}from\u{0020}the\u{0020}most\u{0020}conspicuous\u{0020}member,\u{0020}Valkyrie\u{0020}Captain\u{0020}Alvitr,\u{0020}who\u{0020}is\u{0020}almost\u{0020}always\u{0020}seen\u{0020}around\u{0020}the\u{0020}First\u{0020}Research\u{0020}Lab,\u{0020}the\u{0020}remaining\u{0020}Valkyrie\u{0020}members\u{0020}all\u{0020}tend\u{0020}to\u{0020}disappear\u{0020}for\u{0020}periods\u{0020}of\u{0020}time.\n\u{3000}\u{3000}These\u{0020}are\u{0020}Valkyrie's\u{0020}\"field\u{0020}missions.\"\n\u{3000}\u{3000}For\u{0020}reasons\u{0020}unknown,\u{0020}Captain\u{0020}Alvitr\u{0020}always\u{0020}sends\u{0020}her\u{0020}few\u{0020}subordinates\u{0020}to\u{0020}various\u{0020}parts\u{0020}of\u{0020}the\u{0020}world\u{0020}to\u{0020}carry\u{0020}out\u{0020}\"secret\u{0020}missions\"\u{0020}known\u{0020}only\u{0020}to\u{0020}a\u{0020}select\u{0020}few.\u{0020}In\u{0020}this\u{0020}regard,\u{0020}she\u{0020}is\u{0020}exactly\u{0020}like\u{0020}Dr.\u{0020}Stephanie\u{0020}at\u{0020}Kyushu\u{0020}Headquarters.\n\u{3000}\u{3000}So,\u{0020}in\u{0020}order\u{0020}to\u{0020}truly\u{0020}shine\u{0020}in\u{0020}this\u{0020}secret\u{0020}mission,\u{0020}Miss\u{0020}Lyfa\u{0020}put\u{0020}in\u{0020}a\u{0020}tremendous\u{0020}amount\u{0020}of\u{0020}effort.\n\u{3000}\u{3000}An\u{0020}isolation\u{0020}helmet\u{0020}that\u{0020}could\u{0020}supposedly\u{0020}reduce\u{0020}the\u{0020}effects\u{0020}of\u{0020}empathic\u{0020}resonance\u{0020}to\u{0020}a\u{0020}certain\u{0020}extent\u{0020}-\u{0020}later\u{0020}proven\u{0020}to\u{0020}be\u{0020}largely\u{0020}ineffective\u{0020}-\u{0020}and\u{0020}a\u{0020}motorcycle\u{0020}powered\u{0020}by\u{0020}a\u{0020}Nimbus\u{0020}core\u{0020}with\u{0020}nearly\u{0020}indestructible\u{0020}outer\u{0020}armor;\u{0020}these\u{0020}were\u{0020}all\u{0020}products\u{0020}she\u{0020}helped\u{0020}design,\u{0020}while\u{0020}other\u{0020}researchers\u{0020}were\u{0020}responsible\u{0020}for\u{0020}development\u{0020}(Miss\u{0020}Lyfa\u{0020}admits\u{0020}that\u{0020}she\u{0020}lacks\u{0020}the\u{0020}hands-on\u{0020}ability\u{0020}for\u{0020}actual\u{0020}R&D).\n\u{3000}\u{3000}Unfortunately,\u{0020}things\u{0020}did\u{0020}not\u{0020}go\u{0020}as\u{0020}she\u{0020}had\u{0020}hoped.\u{0020}Miss\u{0020}Lyfa's\u{0020}hard\u{0020}work\u{0020}ended\u{0020}up\u{0020}being\u{0020}almost\u{0020}entirely\u{0020}unnecessary.\u{0020}Even\u{0020}if\u{0020}the\u{0020}helmet\u{0020}and\u{0020}motorcycle\u{0020}had\u{0020}been\u{0020}replaced\u{0020}with\u{0020}civilian\u{0020}versions,\u{0020}the\u{0020}process\u{0020}and\u{0020}outcome\u{0020}of\u{0020}the\u{0020}mission\u{0020}would\u{0020}not\u{0020}have\u{0020}changed\u{0020}much.\n\u{3000}\u{3000}Afterward,\u{0020}when\u{0020}Captain\u{0020}Alvitr\u{0020}learned\u{0020}what\u{0020}Miss\u{0020}Lyfa\u{0020}had\u{0020}done,\u{0020}she\u{0020}ordered\u{0020}Lyfa\u{0020}not\u{0020}to\u{0020}wear\u{0020}her\u{0020}maid\u{0020}outfit\u{0020}for\u{0020}a\u{0020}full\u{0020}month,\u{0020}and\u{0020}allowed\u{0020}her\u{0020}to\u{0020}move\u{0020}about\u{0020}the\u{0020}lab\u{0020}only\u{0020}in\u{0020}a\u{0020}clean\u{0020}suit.", "0", "0", "0", "0", 12026, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622603] = {622603, 1000, "\u{3000}\u{3000}\"The\u{0020}clever\u{0020}and\u{0020}brilliant\u{0020}Miss\u{0020}Lyfa\u{0020}will\u{0020}never\u{0020}submit\u{0020}to\u{0020}the\u{0020}evil\u{0020}Captain\u{0020}Alvitr!\"\n\u{3000}\u{3000}One\u{0020}week\u{0020}after\u{0020}being\u{0020}ordered\u{0020}not\u{0020}to\u{0020}wear\u{0020}her\u{0020}maid\u{0020}outfit,\u{0020}Lyfa\u{0020}ran\u{0020}away\u{0020}from\u{0020}home.\n\u{3000}\u{3000}She\u{0020}rode\u{0020}her\u{0020}motorcycle\u{0020}all\u{0020}the\u{0020}way\u{0020}from\u{0020}Katya\u{0020}to\u{0020}Danube,\u{0020}crossing\u{0020}great\u{0020}distances\u{0020}just\u{0020}to\u{0020}seek\u{0020}the\u{0020}protection\u{0020}of\u{0020}the\u{0020}empathic\u{0020}resonator\u{0020}Navigator.\n\u{3000}\u{3000}When\u{0020}Captain\u{0020}Alvitr\u{0020}learned\u{0020}of\u{0020}this,\u{0020}she\u{0020}flew\u{0020}into\u{0020}a\u{0020}rage\u{0020}and\u{0020}demanded\u{0020}that\u{0020}the\u{0020}Danube\u{0020}Branch\u{0020}hand\u{0020}over\u{0020}Valkyrie's\u{0020}traitor.\n\u{3000}\u{3000}In\u{0020}the\u{0020}end,\u{0020}this\u{0020}farce\u{0020}was\u{0020}settled\u{0020}through\u{0020}the\u{0020}mediation\u{0020}of\u{0020}Dr.\u{0020}Stephanie\u{0020}and\u{0020}the\u{0020}empathic\u{0020}resonator\u{0020}Navigator,\u{0020}with\u{0020}the\u{0020}result\u{0020}being:\u{0020}\"Lyfa's\u{0020}freedom\u{0020}to\u{0020}choose\u{0020}her\u{0020}own\u{0020}clothes\u{0020}will\u{0020}be\u{0020}restored,\u{0020}but\u{0020}such\u{0020}self-willed\u{0020}behavior\u{0020}must\u{0020}never\u{0020}happen\u{0020}again.\"", "0", "0", "0", "0", 12026, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[622604] = {622604, 2000, "\u{3000}\u{3000}A\u{0020}motorcycle\u{0020}racing\u{0020}across\u{0020}the\u{0020}earth,\n\u{3000}\u{3000}An\u{0020}engine\u{0020}roar\u{0020}echoing\u{0020}through\u{0020}the\u{0020}skies,\n\u{3000}\u{3000}As\u{0020}long\u{0020}as\u{0020}she\u{0020}is\u{0020}riding\u{0020}it,\u{0020}no\u{0020}matter\u{0020}where\u{0020}in\u{0020}the\u{0020}world\u{0020}she\u{0020}may\u{0020}be,\u{0020}she\u{0020}can\u{0020}reach\u{0020}your\u{0020}side.\n\u{3000}\u{3000}So\u{0020}believe\u{0020}this:\u{0020}in\u{0020}your\u{0020}darkest\u{0020}hour,\u{0020}the\u{0020}lightning\u{0020}of\u{0020}the\u{0020}battlefield\u{0020}will\u{0020}always\u{0020}strike\u{0020}down\u{0020}beside\u{0020}you,\u{0020}never\u{0020}breaking\u{0020}its\u{0020}promise.", "0", "0", "0", "0", 12026, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
