[622701] = {622701, 100, "Crim\u{0020}loved\u{0020}Christmas,\u{0020}though\u{0020}no\u{0020}more\u{0020}than\u{0020}she\u{0020}loved\u{0020}any\u{0020}holiday\u{0020}that\u{0020}gave\u{0020}her\u{0020}an\u{0020}excuse\u{0020}to\u{0020}indulge\u{0020}in\u{0020}a\u{0020}drunken\u{0020}stupor.\n\nThe\u{0020}one\u{0020}difference\u{0020}was\u{0020}that\u{0020}on\u{0020}Christmas,\u{0020}she\u{0020}always\u{0020}dressed\u{0020}in\u{0020}a\u{0020}ridiculous\u{0020}Santa\u{0020}costume\u{0020}and\u{0020}punctuated\u{0020}her\u{0020}conversations\u{0020}with\u{0020}an\u{0020}exaggerated\u{0020}\"Ho!\u{0020}Ho!\u{0020}Ho!\"\u{0020}She\u{0020}had\u{0020}since\u{0020}fully\u{0020}embraced\u{0020}her\u{0020}role\u{0020}of\u{0020}Santa\u{0020}Claus.\n\nThough\u{0020}no\u{0020}one\u{0020}was\u{0020}quite\u{0020}sure\u{0020}how\u{0020}or\u{0020}why\u{0020}this\u{0020}tradition\u{0020}began.\u{0020}While\u{0020}her\u{0020}antics\u{0020}might\u{0020}be\u{0020}entertaining,\u{0020}they\u{0020}didn't\u{0020}curb\u{0020}her\u{0020}drinking.\n\nIf\u{0020}anything,\u{0020}her\u{0020}holiday\u{0020}cheer\u{0020}seemed\u{0020}to\u{0020}deepen\u{0020}her\u{0020}dependence\u{0020}on\u{0020}alcohol,\u{0020}suggesting\u{0020}that\u{0020}she\u{0020}might\u{0020}be\u{0020}wrestling\u{0020}with\u{0020}unspoken\u{0020}troubles.\n\nBut\u{0020}Crim\u{0020}never\u{0020}talked\u{0020}about\u{0020}her\u{0020}problems,\u{0020}and\u{0020}those\u{0020}around\u{0020}her\u{0020}rarely\u{0020}asked.\u{0020}Instead,\u{0020}she\u{0020}kept\u{0020}up\u{0020}her\u{0020}facade\u{0020}of\u{0020}carefree\u{0020}optimism,\u{0020}believing\u{0020}that\u{0020}as\u{0020}long\u{0020}as\u{0020}there\u{0020}were\u{0020}smiles\u{0020}on\u{0020}Christmas,\u{0020}that\u{0020}was\u{0020}enough.", "0", "0", "0", "0", 12027, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622702] = {622702, 500, "On\u{0020}Crim's\u{0020}first\u{0020}Christmas,\u{0020}she\u{0020}received\u{0020}a\u{0020}single\u{0020}apple\u{0020}from\u{0020}her\u{0020}father\u{0020}as\u{0020}a\u{0020}gift.\n\nHer\u{0020}second\u{0020}Christmas,\u{0020}she\u{0020}took\u{0020}a\u{0020}secret\u{0020}sip\u{0020}of\u{0020}fruit\u{0020}wine\u{0020}and\u{0020}slept\u{0020}through\u{0020}Christmas\u{0020}Eve\u{0020}and\u{0020}most\u{0020}of\u{0020}the\u{0020}next\u{0020}day.\n\nHer\u{0020}third\u{0020}Christmas,\u{0020}she\u{0020}buried\u{0020}a\u{0020}bottle\u{0020}of\u{0020}fruit\u{0020}wine\u{0020}beneath\u{0020}the\u{0020}third\u{0020}apple\u{0020}tree\u{0020}in\u{0020}the\u{0020}orchard,\u{0020}planning\u{0020}to\u{0020}dig\u{0020}it\u{0020}up\u{0020}the\u{0020}following\u{0020}Christmas.\n\nHer\u{0020}fourth\u{0020}Christmas,\u{0020}she\u{0020}wore\u{0020}an\u{0020}oversized\u{0020}Santa\u{0020}suit\u{0020}that\u{0020}swallowed\u{0020}her\u{0020}small\u{0020}frame.\u{0020}She\u{0020}passed\u{0020}out\u{0020}bread\u{0020}and\u{0020}candies\u{0020}to\u{0020}the\u{0020}homeless\u{0020}children,\u{0020}with\u{0020}only\u{0020}her\u{0020}tiny\u{0020}head\u{0020}poking\u{0020}out\u{0020}from\u{0020}the\u{0020}baggy\u{0020}costume.\n\nFrom\u{0020}her\u{0020}fifth\u{0020}Christmas\u{0020}onward,\u{0020}Crim\u{0020}completely\u{0020}embraced\u{0020}the\u{0020}role\u{0020}of\u{0020}Santa\u{0020}Claus.\u{0020}Despite\u{0020}her\u{0020}meager\u{0020}means,\u{0020}she\u{0020}dedicated\u{0020}herself\u{0020}to\u{0020}spreading\u{0020}joy.\n\nThe\u{0020}Santa\u{0020}suit\u{0020}she\u{0020}wore\u{0020}originally\u{0020}belonged\u{0020}to\u{0020}Crim's\u{0020}father.\u{0020}One\u{0020}Christmas,\u{0020}he\u{0020}had\u{0020}planned\u{0020}to\u{0020}dress\u{0020}up\u{0020}and\u{0020}bring\u{0020}holiday\u{0020}cheer\u{0020}to\u{0020}those\u{0020}less\u{0020}fortunate.\u{0020}However,\u{0020}he\u{0020}fell\u{0020}gravely\u{0020}ill\u{0020}that\u{0020}year,\u{0020}too\u{0020}weak\u{0020}to\u{0020}fulfill\u{0020}the\u{0020}role—or\u{0020}even\u{0020}care\u{0020}for\u{0020}himself.\u{0020}Crim\u{0020}took\u{0020}over,\u{0020}cared\u{0020}for\u{0020}her\u{0020}father,\u{0020}and\u{0020}stepped\u{0020}into\u{0020}his\u{0020}Santa\u{0020}boots,\u{0020}quite\u{0020}literally.\n\nThe\u{0020}first\u{0020}time\u{0020}Crim\u{0020}appeared\u{0020}as\u{0020}Santa,\u{0020}bundled\u{0020}up\u{0020}in\u{0020}the\u{0020}oversized\u{0020}costume\u{0020}like\u{0020}a\u{0020}woolen\u{0020}ball,\u{0020}her\u{0020}absurd\u{0020}appearance\u{0020}made\u{0020}everyone\u{0020}laugh.\u{0020}But\u{0020}Crim\u{0020}didn't\u{0020}mind—she\u{0020}reveled\u{0020}in\u{0020}their\u{0020}joy.\u{0020}Even\u{0020}the\u{0020}trace\u{0020}of\u{0020}embarrassment\u{0020}she\u{0020}felt\u{0020}was\u{0020}eased\u{0020}by\u{0020}a\u{0020}sip\u{0020}of\u{0020}fruit\u{0020}wine\u{0020}before\u{0020}heading\u{0020}out.\n\nCrim\u{0020}loved\u{0020}seeing\u{0020}people\u{0020}laugh,\u{0020}especially\u{0020}when\u{0020}she\u{0020}was\u{0020}the\u{0020}cause\u{0020}of\u{0020}their\u{0020}happiness.\u{0020}It\u{0020}made\u{0020}her\u{0020}feel\u{0020}like\u{0020}a\u{0020}hero.\n\nTo\u{0020}Crim,\u{0020}a\u{0020}hero\u{0020}is\u{0020}someone\u{0020}who\u{0020}brings\u{0020}smiles\u{0020}to\u{0020}people\u{0020}in\u{0020}difficult\u{0020}times.\u{0020}Santa\u{0020}Claus\u{0020}was\u{0020}a\u{0020}hero,\u{0020}and\u{0020}by\u{0020}playing\u{0020}Santa,\u{0020}Crim\u{0020}believed\u{0020}she\u{0020}could\u{0020}be\u{0020}one\u{0020}too.", "0", "0", "0", "0", 12027, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622703] = {622703, 1000, "Have\u{0020}you\u{0020}ever\u{0020}seen\u{0020}a\u{0020}Santa\u{0020}who\u{0020}gave\u{0020}alcohol\u{0020}to\u{0020}children\u{0020}as\u{0020}gifts?\n\nTo\u{0020}preserve\u{0020}the\u{0020}reputation\u{0020}of\u{0020}Santa\u{0020}Claus,\u{0020}Iliya\u{0020}usually\u{0020}kept\u{0020}Crim\u{0020}indoors\u{0020}on\u{0020}Christmas\u{0020}Day.\u{0020}Crim,\n\nwho\u{0020}is\u{0020}often\u{0020}an\u{0020}open\u{0020}book\u{0020}when\u{0020}it\u{0020}comes\u{0020}to\u{0020}her\u{0020}love\u{0020}of\u{0020}alcohol,\u{0020}became\u{0020}strangely\u{0020}difficult\u{0020}to\u{0020}read\u{0020}during\u{0020}the\u{0020}holidays.\u{0020}While\u{0020}she\u{0020}spent\u{0020}most\u{0020}of\u{0020}the\u{0020}day\u{0020}playing\u{0020}Santa\u{0020}(usually\u{0020}getting\u{0020}herself\u{0020}into\u{0020}trouble),\u{0020}she\u{0020}can\u{0020}occasionally\u{0020}be\u{0020}found\u{0020}sitting\u{0020}alone,\u{0020}drinking\u{0020}quietly\u{0020}and\u{0020}looking\u{0020}uncharacteristically\u{0020}somber.\n\nLike\u{0020}many\u{0020}who\u{0020}used\u{0020}alcohol\u{0020}to\u{0020}drown\u{0020}their\u{0020}sorrows,\u{0020}Crim\u{0020}never\u{0020}spoke\u{0020}openly\u{0020}about\u{0020}her\u{0020}troubles.\u{0020}Only\u{0020}when\u{0020}she\u{0020}drank\u{0020}herself\u{0020}into\u{0020}oblivion\u{0020}do\u{0020}her\u{0020}inner\u{0020}thoughts\u{0020}slip\u{0020}out,\u{0020}and\u{0020}even\u{0020}then,\u{0020}they're\u{0020}often\u{0020}cryptic.\n\nHer\u{0020}most\u{0020}frequent\u{0020}lament?\u{0020}\"Ugh...\u{0020}That\u{0020}bottle\u{0020}of\u{0020}wine\u{0020}I\u{0020}buried...\u{0020}How\u{0020}could\u{0020}it\u{0020}be\u{0020}gone?!\"", "0", "0", "0", "0", 12027, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
