[622801] = {622801, 100, "\u{3000}\u{3000}\"You\u{0020}smell\u{0020}like\u{0020}another\u{0020}woman.\"\u{0020}With\u{0020}just\u{0020}a\u{0020}single\u{0020}hug,\u{0020}Detective\u{0020}Mirai\u{0020}picked\u{0020}up\u{0020}on\u{0020}the\u{0020}clue\u{0020}of\u{0020}your\u{0020}\"infidelity.\"\u{0020}\"So,\u{0020}Mr.\u{0020}Pervert...\u{0020}is\u{0020}there\u{0020}anything\u{0020}you'd\u{0020}like\u{0020}to\u{0020}say?\"\u{0020}\n\u{3000}\u{3000}\"Is\u{0020}that...\u{0020}so?\"\u{0020}\n\u{3000}\u{3000}\"Of\u{0020}course\u{0020}there\u{0020}is!\u{0020}Don't\u{0020}underestimate\u{0020}the\u{0020}investigative\u{0020}abilities\u{0020}of\u{0020}a\u{0020}Super\u{0020}Love\u{0020}Detective\u{0020}Assistant.\u{0020}What\u{0020}my\u{0020}eyes\u{0020}see,\u{0020}my\u{0020}tongue\u{0020}tastes,\u{0020}my\u{0020}ears\u{0020}hear,\u{0020}my\u{0020}nose\u{0020}smells,\u{0020}and\u{0020}my\u{0020}hands\u{0020}touch...\u{0020}those\u{0020}are\u{0020}all\u{0020}my\u{0020}weapons.\"\u{0020}She\u{0020}said\u{0020}smugly.\u{0020}\"Originally,\u{0020}Mr.\u{0020}Pervert\u{0020}should\u{0020}smell\u{0020}entirely\u{0020}like\u{0020}me...\u{0020}Every\u{0020}day\u{0020}we\u{0020}meet,\u{0020}I\u{0020}make\u{0020}sure\u{0020}to\u{0020}confirm\u{0020}the\u{0020}scent\u{0020}on\u{0020}you\u{0020}and\u{0020}leave\u{0020}a\u{0020}new\u{0020}one\u{0020}behind...\u{0020}But\u{0020}today,\u{0020}I\u{0020}actually\u{0020}smelled\u{0020}something\u{0020}else…!\"\u{0020}\n\u{3000}\u{3000}\"...Are\u{0020}you\u{0020}a\u{0020}dog\u{0020}or\u{0020}something...?\"\u{0020}\n\u{3000}\u{3000}\"What\u{0020}kind\u{0020}of\u{0020}strange\u{0020}thing\u{0020}are\u{0020}you\u{0020}saying,\u{0020}Mr.\u{0020}Pervert…?\u{0020}This\u{0020}is\u{0020}how\u{0020}I\u{0020}prove\u{0020}to\u{0020}others\u{0020}that\u{0020}you\u{0020}belong\u{0020}to\u{0020}me.\u{0020}If\u{0020}other\u{0020}women\u{0020}smell\u{0020}my\u{0020}scent\u{0020}on\u{0020}you,\u{0020}they\u{0020}won't\u{0020}come\u{0020}close\u{0020}and\u{0020}try\u{0020}to\u{0020}flirt\u{0020}with\u{0020}you!\"\u{0020}\n\u{3000}\u{3000}\"That's\u{0020}exactly\u{0020}what\u{0020}a\u{0020}dog\u{0020}does!?\"", "0", "0", "0", "0", 12028, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622802] = {622802, 500, "\u{3000}\u{3000}The\u{0020}Super\u{0020}Love\u{0020}Detective\u{0020}Assistant\u{0020}Mirai...\u{0020}no,\u{0020}perhaps\u{0020}it's\u{0020}more\u{0020}accurate\u{0020}to\u{0020}say\u{0020}Doggy\u{0020}Mirai\u{0020}now...\u{0020}stared\u{0020}at\u{0020}the\u{0020}Navigator\u{0020}with\u{0020}an\u{0020}intensely\u{0020}\"canine\"\u{0020}gaze,\u{0020}all\u{0020}for\u{0020}the\u{0020}answer\u{0020}she\u{0020}cared\u{0020}about\u{0020}more\u{0020}than\u{0020}anything\u{0020}else:\u{0020}\"Hurry\u{0020}up~\u{0020}tell\u{0020}me~\u{0020}who\u{0020}was\u{0020}it~!\"\n\u{3000}\u{3000}They\u{0020}were\u{0020}clearly\u{0020}very\u{0020}aggressive\u{0020}words,\u{0020}yet\u{0020}when\u{0020}she\u{0020}said\u{0020}them,\u{0020}they\u{0020}sounded\u{0020}more\u{0020}like\u{0020}a\u{0020}plea\u{0020}for\u{0020}affection.\n\u{3000}\u{3000}She\u{0020}was\u{0020}obviously\u{0020}just\u{0020}a\u{0020}child\u{0020}who\u{0020}didn't\u{0020}understand\u{0020}anything,\u{0020}and\u{0020}yet\u{0020}she\u{0020}said\u{0020}things\u{0020}like\u{0020}wanting\u{0020}to\u{0020}become\u{0020}your\u{0020}bride.\n\u{3000}\u{3000}\"I\u{0020}don't\u{0020}know\u{0020}either?\"\u{0020}You\u{0020}truly\u{0020}had\u{0020}no\u{0020}clue\u{0020}about\u{0020}the\u{0020}matter.\u{0020}\"I've\u{0020}been\u{0020}coordinating\u{0020}with\u{0020}a\u{0020}lot\u{0020}of\u{0020}Drivers\u{0020}today...\u{0020}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}someone's\u{0020}perfume\u{0020}accidentally\u{0020}rubbed\u{0020}off\u{0020}on\u{0020}me?\"\n\u{3000}\u{3000}\"I~\u{0020}said~\u{0020}that's\u{0020}not\u{0020}it~!\"\u{0020}Mirai\u{0020}looked\u{0020}distressed,\u{0020}her\u{0020}features\u{0020}almost\u{0020}scrunching\u{0020}together.\u{0020}\"The\u{0020}culprit\u{0020}is\u{0020}probably\u{0020}a\u{0020}repeat\u{0020}offender,\u{0020}a\u{0020}shameless\u{0020}cat\u{0020}who\u{0020}left\u{0020}a\u{0020}lot\u{0020}of\u{0020}scent\u{0020}on\u{0020}you…\u{0020}and\u{0020}some\u{0020}of\u{0020}those\u{0020}smells\u{0020}definitely\u{0020}aren't\u{0020}the\u{0020}kind\u{0020}you'd\u{0020}get\u{0020}from\u{0020}normal\u{0020}contact…\"\n\u{3000}\u{3000}\"Ah...\u{0020}like\u{0020}what\u{0020}places,\u{0020}for\u{0020}example?\"\n\u{3000}\u{3000}\"Mr.\u{0020}Pervert's\u{0020}crotch.\"\u{0020}She\u{0020}pointed\u{0020}at\u{0020}the\u{0020}crime\u{0020}scene.\u{0020}\"This\u{0020}is\u{0020}supposed\u{0020}to\u{0020}be\u{0020}my\u{0020}throne,\u{0020}every\u{0020}single\u{0020}day,\u{0020}I'm\u{0020}supposed\u{0020}to\u{0020}sit\u{0020}on\u{0020}your\u{0020}lap,\u{0020}but\u{0020}today\u{0020}the\u{0020}scent\u{0020}is\u{0020}a\u{0020}little\u{0020}off…\u{0020}Let\u{0020}me\u{0020}take\u{0020}a\u{0020}closer\u{0020}sniff…\"\n\u{3000}\u{3000}\"Don't\u{0020}keep\u{0020}shoving\u{0020}your\u{0020}face\u{0020}toward\u{0020}my\u{0020}crotch…\u{0020}that's\u{0020}very\u{0020}rude…\u{0020}no…\u{0020}this\u{0020}is\u{0020}downright\u{0020}indecent…\"\u{0020}You\u{0020}pressed\u{0020}Mirai's\u{0020}head\u{0020}down\u{0020}firmly\u{0020}to\u{0020}stop\u{0020}her\u{0020}criminal\u{0020}behavior.\u{0020}\"People\u{0020}will\u{0020}think\u{0020}I'm\u{0020}some\u{0020}kind\u{0020}of\u{0020}weirdo.\"\n\u{3000}\u{3000}\"This\u{0020}is\u{0020}a\u{0020}necessary\u{0020}sacrifice,\u{0020}Mr.\u{0020}Pervert.\"\n\u{3000}\u{3000}\"What\u{0020}exactly\u{0020}are\u{0020}you\u{0020}planning\u{0020}to\u{0020}sacrifice…\u{0020}me?\u{0020}It's\u{0020}me,\u{0020}right?\u{0020}You're\u{0020}planning\u{0020}to\u{0020}sacrifice\u{0020}me,\u{0020}aren't\u{0020}you!?\"\n\u{3000}\u{3000}\"It's\u{0020}fine…\u{0020}I'll\u{0020}go\u{0020}with\u{0020}you.\u{0020}A\u{0020}heartbroken\u{0020}me\u{0020}will\u{0020}die\u{0020}for\u{0020}love\u{0020}alongside\u{0020}the\u{0020}cheating\u{0020}Mr.\u{0020}Pervert!\"\n\u{3000}\u{3000}\"Don't\u{0020}assume\u{0020}I've\u{0020}already\u{0020}committed\u{0020}a\u{0020}crime!?\u{0020}And\u{0020}don't\u{0020}go\u{0020}for\u{0020}a\u{0020}lovers'\u{0020}double\u{