[622804] = {622804, 2000, "\u{3000}\u{3000}Be\u{0020}utterly\u{0020}captivated\u{0020}by\u{0020}me.\n\u{3000}\u{3000}Make\u{0020}me\u{0020}everything\u{0020}to\u{0020}Mr.\u{0020}Pervert.\n\u{3000}\u{3000}With\u{0020}me\u{0020}around,\u{0020}the\u{0020}future\u{0020}will\u{0020}surely...\u{0020}\n\u{3000}\u{3000}never\u{0020}let\u{0020}Mr.\u{0020}Pervert\u{0020}down!\n\u{3000}\u{3000}We\u{0020}will\u{0020}be\u{0020}happy!\n\u{3000}\u{3000}So\u{0020}please,\u{0020}give\u{0020}me\u{0020}proper\u{0020}consideration!\n\u{3000}\u{3000}I'll\u{0020}use\u{0020}the\u{0020}power\u{0020}of\u{0020}a\u{0020}detective\u{0020}to\u{0020}crush\u{0020}all\u{0020}evil!\n\u{3000}\u{3000}And\u{0020}hide\u{0020}any\u{0020}evidence\u{0020}that\u{0020}could\u{0020}work\u{0020}against\u{0020}us!\n\u{3000}\u{3000}Then\u{0020}let\u{0020}the\u{0020}detective\u{0020}and\u{0020}her\u{0020}assistant\u{0020}live\u{0020}on\u{0020}together!\n\u{3000}\u{3000}Live\u{0020}on,\u{0020}happily!", "0", "0", "0", "0", 12028, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
