[622901] = {622901, 100, "\u{3000}\u{3000}When\u{0020}Fleur's\u{0020}parents\u{0020}died,\u{0020}she\u{0020}was\u{0020}still\u{0020}a\u{0020}child.\n\u{3000}\u{3000}When\u{0020}the\u{0020}members\u{0020}of\u{0020}Moon\u{0020}Corona\u{0020}fell\u{0020}one\u{0020}after\u{0020}another,\u{0020}Fleur\u{0020}was\u{0020}still\u{0020}a\u{0020}child.\n\u{3000}\u{3000}When\u{0020}the\u{0020}world\u{0020}was\u{0020}destroyed\u{0020}and\u{0020}humanity\u{0020}fled\u{0020}in\u{0020}every\u{0020}direction\u{0020}like\u{0020}rats,\u{0020}Fleur\u{0020}still\u{0020}had\u{0020}not\u{0020}truly\u{0020}left\u{0020}the\u{0020}category\u{0020}of\u{0020}a\u{0020}child.\n\u{3000}\u{3000}When\u{0020}did\u{0020}Fleur\u{0020}become\u{0020}an\u{0020}adult?\u{0020}In\u{0020}truth,\u{0020}even\u{0020}she\u{0020}does\u{0020}not\u{0020}know.\u{0020}Perhaps\u{0020}growing\u{0020}up\u{0020}is\u{0020}simply\u{0020}like\u{0020}that--\u{0020}by\u{0020}the\u{0020}time\u{0020}you\u{0020}come\u{0020}back\u{0020}to\u{0020}your\u{0020}senses,\u{0020}you\u{0020}are\u{0020}already\u{0020}an\u{0020}adult.\n\u{3000}\u{3000}But\u{0020}what\u{0020}she\u{0020}needed\u{0020}to\u{0020}do\u{0020}was\u{0020}something\u{0020}Fleur\u{0020}had\u{0020}already\u{0020}understood\u{0020}back\u{0020}when\u{0020}she\u{0020}was\u{0020}still\u{0020}a\u{0020}child.\n\u{3000}\u{3000}It\u{0020}is\u{0020}fine\u{0020}for\u{0020}only\u{0020}her\u{0020}personality\u{0020}to\u{0020}be\u{0020}hazy\u{0020}and\u{0020}absentminded.\u{0020}Her\u{0020}goal\u{0020}cannot\u{0020}be\u{0020}hazy\u{0020}too.\n\u{3000}\u{3000}Hold\u{0020}the\u{0020}line,\u{0020}preserve\u{0020}hope,\u{0020}and\u{0020}in\u{0020}the\u{0020}darkest\u{0020}era,\u{0020}wait\u{0020}for\u{0020}the\u{0020}first\u{0020}ray\u{0020}of\u{0020}hope\u{0020}to\u{0020}break\u{0020}through\u{0020}the\u{0020}clouds.\u{0020}That\u{0020}is\u{0020}what\u{0020}Fleur\u{0020}must\u{0020}do.", "0", "0", "0", "0", 12029, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[622902] = {622902, 500, "\u{3000}\u{3000}No\u{0020}one\u{0020}ever\u{0020}doubted\u{0020}Moon\u{0020}Corona's\u{0020}strength.\u{0020}If\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force\u{0020}was\u{0020}a\u{0020}hidden\u{0020}trump\u{0020}card,\u{0020}then\u{0020}Moon\u{0020}Corona\u{0020}was\u{0020}a\u{0020}trump\u{0020}card\u{0020}placed\u{0020}openly\u{0020}on\u{0020}the\u{0020}table.\n\u{3000}\u{3000}When\u{0020}humanity\u{0020}fell\u{0020}into\u{0020}crisis,\u{0020}if\u{0020}people\u{0020}were\u{0020}asked\u{0020}to\u{0020}choose\u{0020}one\u{0020}squad\u{0020}to\u{0020}save\u{0020}humanity,\u{0020}Moon\u{0020}Corona\u{0020}would\u{0020}probably\u{0020}receive\u{0020}quite\u{0020}a\u{0020}few\u{0020}votes.\n\u{3000}\u{3000}Perhaps\u{0020}it\u{0020}might\u{0020}even\u{0020}pass\u{0020}unanimously,\u{0020}becoming\u{0020}the\u{0020}savior\u{0020}everyone\u{0020}looked\u{0020}to.\u{0020}After\u{0020}that,\u{0020}it\u{0020}would\u{0020}smoothly\u{0020}save\u{0020}the\u{0020}world,\u{0020}reclaim\u{0020}lost\u{0020}territory,\u{0020}and\u{0020}move\u{0020}toward\u{0020}the\u{0020}happy\u{0020}end\u{0020}everyone\u{0020}wanted\u{0020}to\u{0020}see.\n\u{3000}\u{3000}That\u{0020}is\u{0020}why\u{0020}humanity\u{0020}despaired.\n\u{3000}\u{3000}That\u{0020}is\u{0020}why,\u{0020}when\u{0020}Moon\u{0020}Corona\u{0020}was\u{0020}completely\u{0020}wiped\u{0020}out,\u{0020}humanity\u{0020}fell\u{0020}into\u{0020}despair--\u{0020}at\u{0020}least,\u{0020}that\u{0020}was\u{0020}how\u{0020}the\u{0020}people\u{0020}of\u{0020}Danube\u{0020}saw\u{0020}it.\n\u{3000}\u{3000}When\u{0020}Maya\u{0020}fell,\u{0020}when\u{0020}the\u{0020}units\u{0020}sent\u{0020}to\u{0020}support\u{0020}Maya\u{0020}disappeared\u{0020}without\u{0020}a\u{0020}trace,\u{0020}and\u{0020}when\u{0020}Gluttony's\u{0020}virus\u{0020}had\u{0020}already\u{0020}reached\u{0020}into\u{0020}Danube,\u{0020}the\u{0020}heavy\u{0020}responsibility\u{0020}of\u{0020}saving\u{0020}Danube\u{0020}and\u{0020}even\u{0020}AEGIS\u{0020}fell\u{0020}upon\u{0020}Moon\u{0020}Corona.\n\u{3000}\u{3000}Of\u{0020}course,\u{0020}they\u{0020}were\u{0020}not\u{0020}fighting\u{0020}alone.\u{0020}Reinforcements\u{0020}from\u{0020}Kyushu\u{0020}and\u{0020}Katya\u{0020}were\u{0020}also\u{0020}fighting\u{0020}alongside\u{0020}Moon\u{0020}Corona.\n\u{3000}\u{3000}But\u{0020}they\u{0020}failed.\n\u{3000}\u{3000}Utterly\u{0020}and\u{0020}completely.\n\u{3000}\u{3000}No\u{0020}survivors--\u{0020}that\u{0020}phrasing\u{0020}may\u{0020}be\u{0020}somewhat\u{0020}exaggerated,\u{0020}but\u{0020}it\u{0020}does\u{0020}not\u{0020}stray\u{0020}far\u{0020}from\u{0020}the\u{0020}result.\u{0020}Aside\u{0020}from\u{0020}Fleur,\u{0020}not\u{0020}a\u{0020}single\u{0020}person\u{0020}returned\u{0020}alive\u{0020}from\u{0020}that\u{0020}battlefield.\n\u{3000}\u{3000}A\u{0020}battle\u{0020}against\u{0020}a\u{0020}fully\u{0020}evolved\u{0020}Great\u{0020}Sin,\u{0020}or\u{0020}rather,\u{0020}a\u{0020}Great\u{0020}Sin\u{0020}that\u{0020}had\u{0020}already\u{0020}surpassed\u{0020}its\u{0020}fully\u{0020}evolved\u{0020}form,\u{0020}was\u{0020}a\u{0020}war\u{0020}doomed\u{0020}to\u{0020}fail.\u{0020}Nearly\u{0020}all\u{0020}of\u{0020}AEGIS's\u{0020}elites\u{0020}were\u{0020}lost\u{0020}in\u{0020}that\u{0020}war,\u{0020}and\u{0020}the\u{0020}fall\u{0020}of\u{0020}Moon\u{0020}Corona\u{0020}became\u{0020}the\u{0020}first\u{0020}sign\u{0020}of\u{0020}AEGIS's\u{0020}destruction...\u{0020}and\u{0020}humanity's\u{0020}destruction.\n\u{3000}\u{3000}Of\u{0020}course,\u{0020}in\u{0020}Fleur's\u{0020}heart,\u{0020}perhaps\u{0020}the\u{0020}sign\u{0020}of\u{0020}destruction\u{0020}appeared\u{0020}even\u{0020}earlier.\n\u{3000}\u{3000}In\u{0020}any\u{0020}case,\u{0020}the\u{0020}fall\u{0020}of\u{0020}Moon\u{0020}Corona\u{0020}and\u{0020}the\u{0020}collapse\u{0020}of\u{0020}AEGIS\u{0020}turned\u{0020}Fleur\u{0020}into\u{0020}a\u{0020}homeless\u{0020}stray\u{0020}cat.\u{0020}And\u{0020}the\u{0020}one\u{0020}who\u{0020}took\u{0020}in\u{0020}that\u{0020}stray\u{0020}cat\u{0020}afterward\u{0020}was\u{0020}none\u{0020}other\u{0020}than\u{0020}Charlissa\u{0020}de\u{0020}Roland,\u{0020}the\u{0020}future\u{0020}administrator\u{0020}of\u{0020}New\u{0020}Cheston.", "0", "0", "0", "0", 12029, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[622903] = {622903, 1000, "\u{3000}\u{3000}In\u{0020}New\u{0020}Cheston,\u{0020}if\u{0020}a\u{0020}major\u{0020}incident\u{0020}affecting\u{0020}the\u{0020}entire\u{0020}city\u{0020}occurs,\u{0020}such\u{0020}as\u{0020}a\u{0020}Sin\u{0020}disaster,\u{0020}there\u{0020}is\u{0020}a\u{0020}chance\u{0020}of\u{0020}seeing\u{0020}Charlissa\u{0020}de\u{0020}Roland\u{0020}and\u{0020}Alaita.\u{0020}The\u{0020}two\u{0020}of\u{0020}them\u{0020}always\u{0020}appear\u{0020}at\u{0020}critical\u{0020}moments.\n\u{3000}\u{3000}But\u{0020}seeing\u{0020}Fleur,\u{0020}the\u{0020}rumored\u{0020}survivor\u{0020}of\u{0020}Moon\u{0020}Corona,\u{0020}is\u{0020}no\u{0020}simple\u{0020}matter.\n\u{3000}\u{3000}At\u{0020}the\u{0020}very\u{0020}least,\u{0020}most\u{0020}people\u{0020}have\u{0020}never\u{0020}seen\u{0020}Fleur\u{0020}in\u{0020}any\u{0020}formal\u{0020}setting.\u{0020}And\u{0020}in\u{0020}other\u{0020}situations,\u{0020}even\u{0020}if\u{0020}they\u{0020}are\u{0020}lucky\u{0020}enough\u{0020}to\u{0020}catch\u{0020}a\u{0020}glimpse\u{0020}of\u{0020}her,\u{0020}they\u{0020}probably\u{0020}would\u{0020}not\u{0020}recognize\u{0020}that\u{0020}the\u{0020}girl\u{0020}often\u{0020}accompanied\u{0020}by\u{0020}cats\u{0020}is\u{0020}a\u{0020}famous\u{0020}member\u{0020}of\u{0020}Moon\u{0020}Corona.\n\u{3000}\u{3000}In\u{0020}fact,\u{0020}Fleur\u{0020}does\u{0020}not\u{0020}stay\u{0020}in\u{0020}New\u{0020}Cheston\u{0020}most\u{0020}of\u{0020}the\u{0020}time.\u{0020}Even\u{0020}when\u{0020}she\u{0020}has\u{0020}no\u{0020}mission,\u{0020}she\u{0020}leaves\u{0020}New\u{0020}Cheston\u{0020}alone\u{0020}and\u{0020}wanders\u{0020}through\u{0020}the\u{0020}Maya\u{0020}region,\u{0020}which\u{0020}has\u{0020}already\u{0020}become\u{0020}forbidden\u{0020}territory\u{0020}for\u{0020}humanity,\u{0020}as\u{0020}if\u{0020}searching\u{0020}for\u{0020}something.\n\u{3000}\u{3000}Only\u{0020}when\u{0020}the\u{0020}morning\u{0020}sun\u{0020}first\u{0020}rises,\u{0020}and\u{0020}pale\u{0020}golden\u{0020}light\u{0020}scatters\u{0020}its\u{0020}remaining\u{0020}rays\u{0020}through\u{0020}the\u{0020}pitch-black\u{0020}clouds,\u{0020}do\u{0020}the\u{0020}residents\u{0020}of\u{0020}New\u{0020}Cheston\u{0020}have\u{0020}the\u{0020}fortune\u{0020}of\u{0020}seeing\u{0020}Fleur\u{0020}playing\u{0020}with\u{0020}cats\u{0020}on\u{0020}the\u{0020}eastern\u{0020}side\u{0020}of\u{0020}New\u{0020}Cheston.", "0", "0", "0", "0", 12029, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[622904] = {622904, 2000, "\u{3000}\u{3000}People\u{0020}may\u{0020}die\u{0020}with\u{0020}the\u{0020}passage\u{0020}of\u{0020}time,\u{0020}but\u{0020}hope\u{0020}does\u{0020}not.\n\u{3000}\u{3000}As\u{0020}the\u{0020}world\u{0020}gradually\u{0020}moved\u{0020}toward\u{0020}destruction,\u{0020}and\u{0020}people\u{0020}had\u{0020}already\u{0020}lost\u{0020}faith\u{0020}in\u{0020}the\u{0020}future,\n\u{3000}\u{3000}Fleur\u{0020}still\u{0020}firmly\u{0020}believed\u{0020}that\u{0020}the\u{0020}person\u{0020}who\u{0020}had\u{0020}given\u{0020}her\u{0020}a\u{0020}second\u{0020}life\u{0020}and\u{0020}bestowed\u{0020}special\u{0020}abilities\u{0020}upon\u{0020}her,\n\u{3000}\u{3000}that\u{0020}Navigator\u{0020}who\u{0020}symbolized\u{0020}hope,\u{0020}was\u{0020}still\u{0020}alive.\n\u{3000}\u{3000}What\u{0020}she\u{0020}needed\u{0020}to\u{0020}do\u{0020}was\u{0020}wait.\n\u{3000}\u{3000}So\u{0020}that\u{0020}when\u{0020}he\u{0020}returned,\u{0020}there\u{0020}would\u{0020}be\u{0020}a\u{0020}home\u{0020}where\u{0020}he\u{0020}could\u{0020}rest.\n\u{3000}\u{3000}That\u{0020}is\u{0020}what\u{0020}Fleur\u{0020}has\u{0020}been\u{0020}doing.\n\u{3000}\u{3000}When\u{0020}they\u{0020}finally\u{0020}reunite,\u{0020}she\u{0020}will\u{0020}definitely\u{0020}say\u{0020}those\u{0020}words--\n\u{3000}\u{3000}\"--Navigator,\u{0020}long\u{0020}time\u{0020}no\u{0020}see.\u{0020}Fleur\u{0020}is\u{0020}an\u{0020}adult\u{0020}now,\u{0020}meow.\"", "0", "0", "0", "0", 12029, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
