[623001] = {623001, 100, "Himari\u{0020}Azuma,\u{0020}the\u{0020}second-in-command\u{0020}of\u{0020}the\u{0020}7th\u{0020}Squad\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force.\n\nBeautiful,\u{0020}proud,\u{0020}impatient,\u{0020}and\u{0020}quick\u{0020}to\u{0020}anger.\u{0020}Her\u{0020}favorite\u{0020}food\u{0020}is\u{0020}ramen.\u{0020}She\u{0020}holds\u{0020}deep\u{0020}admiration\u{0020}for\u{0020}Kyouka,\u{0020}the\u{0020}commander\u{0020}of\u{0020}her\u{0020}squad.\n\nHer\u{0020}Peach\u{0020}Blessing\u{0020}Lofty\u{0020}Ambitions:\u{0020}Learning\u{0020}allows\u{0020}her\u{0020}to\u{0020}copy\u{0020}the\u{0020}abilities\u{0020}of\u{0020}others,\u{0020}with\u{0020}the\u{0020}strength\u{0020}varying\u{0020}according\u{0020}to\u{0020}her\u{0020}compatibility\u{0020}with\u{0020}them.\u{0020}As\u{0020}a\u{0020}result,\u{0020}if\u{0020}the\u{0020}match\u{0020}is\u{0020}poor,\u{0020}the\u{0020}power\u{0020}will\u{0020}be\u{0020}diluted\u{0020}significantly.\u{0020}To\u{0020}fully\u{0020}master\u{0020}a\u{0020}copied\u{0020}skill,\u{0020}she\u{0020}must\u{0020}undergo\u{0020}relentless\u{0020}training.\u{0020}Currently,\u{0020}her\u{0020}most\u{0020}frequently\u{0020}used\u{0020}abilities\u{0020}are\u{0020}Bang\u{0020}Bang\u{0020}Bang:\u{0020}Armed\u{0020}Belle\u{0020}of\u{0020}Tokoyama,\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}5th\u{0020}Squad\u{0020}and\u{0020}Eternal\u{0020}Chains:\u{0020}Slave\u{0020}of\u{0020}Kyouka.", "0", "0", "0", "0", 12030, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[623002] = {623002, 500, "Hailing\u{0020}from\u{0020}the\u{0020}prestigious\u{0020}Azuma\u{0020}family\u{0020}that\u{0020}boasts\u{0020}a\u{0020}long\u{0020}and\u{0020}celebrated\u{0020}history\u{0020}of\u{0020}service\u{0020}in\u{0020}Mato,\u{0020}Himari\u{0020}grew\u{0020}up\u{0020}bearing\u{0020}the\u{0020}burden\u{0020}of\u{0020}expectations.\n\nUnlike\u{0020}Commander\u{0020}Kyouka\u{0020}Uzen\u{0020}and\u{0020}Nei\u{0020}Okawamura,\u{0020}Himari's\u{0020}decision\u{0020}to\u{0020}join\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}stems\u{0020}from\u{0020}a\u{0020}desperate\u{0020}urge\u{0020}to\u{0020}prove\u{0020}herself.\u{0020}Found\u{0020}lacking,\u{0020}she\u{0020}has\u{0020}become\u{0020}a\u{0020}subject\u{0020}of\u{0020}ridicule\u{0020}to\u{0020}her\u{0020}own\u{0020}sister,\u{0020}Yachiho\u{0020}Azuma.\u{0020}Driven\u{0020}by\u{0020}shame,\u{0020}she\u{0020}pushed\u{0020}herself\u{0020}harder\u{0020}and\u{0020}harder,\u{0020}setting\u{0020}her\u{0020}sights\u{0020}on\u{0020}becoming\u{0020}someone\u{0020}as\u{0020}powerful\u{0020}as\u{0020}Kyouka.\n\nThough\u{0020}her\u{0020}motivation\u{0020}stems\u{0020}from\u{0020}a\u{0020}desire\u{0020}to\u{0020}prove\u{0020}herself,\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}Azuma\u{0020}family,\u{0020}she\u{0020}carries\u{0020}a\u{0020}genuine\u{0020}sense\u{0020}of\u{0020}justice\u{0020}in\u{0020}her\u{0020}heart\u{0020}when\u{0020}fighting\u{0020}for\u{0020}humanity.", "0", "0", "0", "0", 12030, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[623003] = {623003, 1000, "Even\u{0020}after\u{0020}being\u{0020}transported\u{0020}into\u{0020}another\u{0020}world,\u{0020}Himari\u{0020}has\u{0020}never\u{0020}once\u{0020}neglected\u{0020}her\u{0020}daily\u{0020}training.\u{0020}More\u{0020}precisely\u{0020}speaking,\u{0020}she\u{0020}even\u{0020}adapted\u{0020}her\u{0020}regimen\u{0020}to\u{0020}the\u{0020}new\u{0020}world's\u{0020}realities.\u{0020}Such\u{0020}flexibility\u{0020}and\u{0020}focus\u{0020}instill\u{0020}a\u{0020}deep\u{0020}sense\u{0020}of\u{0020}trust.\u{0020}It\u{0020}didn't\u{0020}take\u{0020}long\u{0020}for\u{0020}her\u{0020}to\u{0020}pass\u{0020}the\u{0020}simulated\u{0020}battle\u{0020}with\u{0020}flying\u{0020}colors,\u{0020}showing\u{0020}her\u{0020}excellent\u{0020}understanding\u{0020}of\u{0020}new\u{0020}enemies\u{0020}and\u{0020}battlefields.\n\nTo\u{0020}learn,\u{0020}to\u{0020}adapt,\u{0020}to\u{0020}train,\u{0020}and\u{0020}to\u{0020}become\u{0020}stronger.\u{0020}It's\u{0020}like\u{0020}second\u{0020}nature\u{0020}to\u{0020}her.\u{0020}A\u{0020}girl\u{0020}with\u{0020}relentless\u{0020}drive\u{0020}and\u{0020}a\u{0020}sharp\u{0020}mind.\u{0020}Truly,\u{0020}she's\u{0020}a\u{0020}warrioress\u{0020}worthy\u{0020}of\u{0020}the\u{0020}renowned\u{0020}Azuma\u{0020}name.", "0", "0", "0", "0", 12030, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[623004] = {623004, 2000, "Why\u{0020}keep\u{0020}pushing\u{0020}myself\u{0020}so\u{0020}hard?\n\nTo\u{0020}my\u{0020}family's\u{0020}recognition?\n\nTo\u{0020}never\u{0020}bring\u{0020}shame\u{0020}upon\u{0020}myself?\n\nTo\u{0020}live\u{0020}up\u{0020}to\u{0020}the\u{0020}expectations\u{0020}of\u{0020}those\u{0020}who\u{0020}believe\u{0020}in\u{0020}me?\n\nOr\u{0020}to\u{0020}follow\u{0020}in\u{0020}someone's\u{0020}footsteps?\n\nBurn\u{0020}all\u{0020}of\u{0020}it\u{0020}in\u{0020}the\u{0020}furnace\u{0020}of\u{0020}blood,\u{0020}sweat,\u{0020}and\u{0020}tears.\n\nToday,\u{0020}Himari\u{0020}still\u{0020}fights\u{0020}on.", "0", "0", "0", "0", 12030, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
