[623101] = {623101, 100, "\u{3000}\u{3000}The\u{0020}passage\u{0020}of\u{0020}time\u{0020}brings\u{0020}growth.\n\u{3000}\u{3000}However,\u{0020}that\u{0020}saying\u{0020}does\u{0020}not\u{0020}apply\u{0020}to\u{0020}murderers.\n\u{3000}\u{3000}Chiaki,\u{0020}a\u{0020}Prisoner\u{0020}who\u{0020}spends\u{0020}most\u{0020}of\u{0020}her\u{0020}time\u{0020}inside\u{0020}a\u{0020}cage,\u{0020}has\u{0020}practically\u{0020}no\u{0020}real\u{0020}sense\u{0020}of\u{0020}\"time.\"\n\u{3000}\u{3000}Whether\u{0020}it\u{0020}is\u{0020}a\u{0020}day,\u{0020}a\u{0020}week,\u{0020}or\u{0020}even\u{0020}a\u{0020}year,\u{0020}there\u{0020}is\u{0020}not\u{0020}much\u{0020}difference\u{0020}in\u{0020}how\u{0020}she\u{0020}feels\u{0020}it.\n\u{3000}\u{3000}Without\u{0020}hope,\u{0020}there\u{0020}is\u{0020}no\u{0020}disappointment.\u{0020}Without\u{0020}waiting\u{0020}for\u{0020}tomorrow\u{0020}to\u{0020}come,\u{0020}there\u{0020}is\u{0020}no\u{0020}reason\u{0020}to\u{0020}care\u{0020}about\u{0020}the\u{0020}speed\u{0020}of\u{0020}time.\n\u{3000}\u{3000}\"--Huh?\u{0020}Is\u{0020}there\u{0020}no\u{0020}one\u{0020}you\u{0020}want\u{0020}to\u{0020}see,\u{0020}Senpai?\"\n\u{3000}\u{3000}The\u{0020}unlikable\u{0020}junior,\u{0020}trampling\u{0020}all\u{0020}over\u{0020}the\u{0020}sense\u{0020}of\u{0020}social\u{0020}distance\u{0020}with\u{0020}her\u{0020}question,\u{0020}touches\u{0020}upon\u{0020}a\u{0020}hidden\u{0020}place\u{0020}in\u{0020}the\u{0020}murderer's\u{0020}heart.\n\u{3000}\u{3000}Naturally,\u{0020}at\u{0020}that\u{0020}very\u{0020}moment,\u{0020}the\u{0020}irritating\u{0020}face\u{0020}of\u{0020}a\u{0020}certain\u{0020}Navigator\u{0020}pops\u{0020}up\u{0020}from\u{0020}her\u{0020}hippocampus\u{0020}entirely\u{0020}on\u{0020}its\u{0020}own.\n\u{3000}\u{3000}\"No.\"\n\u{3000}\u{3000}That\u{0020}is\u{0020}how\u{0020}she\u{0020}answers.\n\u{3000}\u{3000}At\u{0020}least,\u{0020}until\u{0020}that\u{0020}guy\u{0020}sends\u{0020}her\u{0020}a\u{0020}text,\u{0020}she\u{0020}will\u{0020}absolutely\u{0020}never\u{0020}admit\u{0020}that\u{0020}she\u{0020}wants\u{0020}to\u{0020}see\u{0020}him.", "0", "0", "0", "0", 12031, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[623102] = {623102, 500, "\u{3000}\u{3000}In\u{0020}the\u{0020}nearly\u{0020}two\u{0020}years\u{0020}after\u{0020}the\u{0020}\"Logan\u{0020}City\u{0020}Incident\"\u{0020}ended,\u{0020}Chiaki\u{0020}has\u{0020}not\u{0020}had\u{0020}the\u{0020}chance\u{0020}to\u{0020}relax.\n\u{3000}\u{3000}Although\u{0020}Stephanie\u{0020}shows\u{0020}her\u{0020}rare\u{0020}traces\u{0020}of\u{0020}humanity\u{0020}on\u{0020}certain\u{0020}occasions--allowing\u{0020}her\u{0020}to\u{0020}meet\u{0020}her\u{0020}handful\u{0020}of\u{0020}friends\u{0020}in\u{0020}her\u{0020}spare\u{0020}time\u{0020}and\u{0020}spend\u{0020}a\u{0020}brief,\u{0020}pleasant\u{0020}while\u{0020}at\u{0020}ease--for\u{0020}the\u{0020}vast\u{0020}majority\u{0020}of\u{0020}her\u{0020}time,\u{0020}she\u{0020}still\u{0020}has\u{0020}to\u{0020}fulfill\u{0020}her\u{0020}duties\u{0020}as\u{0020}a\u{0020}\"Prisoner.\"\n\u{3000}\u{3000}That\u{0020}is\u{0020}to\u{0020}say,\u{0020}as\u{0020}Stephanie's\u{0020}\"hound,\"\u{0020}she\u{0020}kills\u{0020}those\u{0020}who\u{0020}endanger\u{0020}humanity,\u{0020}endanger\u{0020}society,\u{0020}or\u{0020}to\u{0020}put\u{0020}it\u{0020}bluntly--endanger\u{0020}AEGIS's\u{0020}rule.\n\u{3000}\u{3000}Of\u{0020}course,\u{0020}she\u{0020}does\u{0020}not\u{0020}care\u{0020}whether\u{0020}the\u{0020}other\u{0020}party\u{0020}is\u{0020}truly\u{0020}\"evil.\"\n\u{3000}\u{3000}If,\u{0020}during\u{0020}a\u{0020}mission,\u{0020}she\u{0020}were\u{0020}to\u{0020}discover\u{0020}that\u{0020}the\u{0020}target\u{0020}was\u{0020}actually\u{0020}a\u{0020}good\u{0020}person\u{0020}with\u{0020}kind\u{0020}intentions,\u{0020}merely\u{0020}misunderstood\u{0020}for\u{0020}their\u{0020}passionate\u{0020}ideals,\u{0020}she\u{0020}feels\u{0020}that\u{0020}she\u{0020}would\u{0020}probably\u{0020}still\u{0020}bring\u{0020}down\u{0020}her\u{0020}blade\u{0020}without\u{0020}hesitation.\n\u{3000}\u{3000}She\u{0020}would\u{0020}only\u{0020}think\u{0020}this--if\u{0020}that\u{0020}guy\u{0020}found\u{0020}out\u{0020}she\u{0020}had\u{0020}done\u{0020}something\u{0020}like\u{0020}that,\u{0020}he\u{0020}would\u{0020}definitely\u{0020}despise\u{0020}her.\n\u{3000}\u{3000}Fortunately,\u{0020}no\u{0020}such\u{0020}moral\u{0020}dilemma\u{0020}has\u{0020}ever\u{0020}been\u{0020}placed\u{0020}before\u{0020}her.\n\u{3000}\u{3000}Perhaps\u{0020}Stephanie\u{0020}is\u{0020}right.\u{0020}Those\u{0020}written\u{0020}onto\u{0020}her\u{0020}list,\u{0020}even\u{0020}if\u{0020}they\u{0020}are\u{0020}not\u{0020}\"utterly\u{0020}unforgivable,\"\u{0020}are\u{0020}absolutely\u{0020}no\u{0020}saints\u{0020}either.\n\u{3000}\u{3000}Killing\u{0020}those\u{0020}disgusting\u{0020}\"humans\"\u{0020}who\u{0020}are\u{0020}no\u{0020}different\u{0020}from\u{0020}maggots\u{0020}places\u{0020}no\u{0020}psychological\u{0020}burden\u{0020}on\u{0020}Chiaki\u{0020}at\u{0020}all.\n\u{3000}\u{3000}That\u{0020}said,\u{0020}during\u{0020}the\u{0020}brief\u{0020}moments\u{0020}of\u{0020}free\u{0020}time\u{0020}after\u{0020}a\u{0020}mission\u{0020}ends,\u{0020}she\u{0020}sometimes\u{0020}wonders\u{0020}if,\u{0020}had\u{0020}she\u{0020}not\u{0020}walked\u{0020}this\u{0020}path\u{0020}back\u{0020}then,\u{0020}she\u{0020}might\u{0020}have\u{0020}had\u{0020}a\u{0020}completely\u{0020}different\u{0020}life.\n\u{3000}\u{3000}\"Idiot--\"\n\u{3000}\u{3000}She\u{0020}almost\u{0020}feels\u{0020}like\u{0020}using\u{0020}her\u{0020}scissors\u{0020}to\u{0020}cut\u{0020}off\u{0020}her\u{0020}precious\u{0020}fingers.\n\u{3000}\u{3000}\"--Stop\u{0020}indulging\u{0020}in\u{0020}stupid\u{0020}fantasies,\u{0020}you\u{0020}social\u{0020}trash.\"\n\u{3000}\u{3000}That\u{0020}is\u{0020}how\u{0020}Chiaki\u{0020}curses\u{0020}herself.", "0", "0", "0", "0", 12031, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[623103] = {623103, 1000, "\u{3000}\u{3000}\"I\u{0020}need\u{0020}you\u{0020}to\u{0020}go\u{0020}to\u{0020}Maya.\"\n\u{3000}\u{3000}\"Now?\"\n\u{3000}\u{3000}\"Now.\"\n\u{3000}\u{3000}\"Business\u{0020}or\u{0020}personal?\"\n\u{3000}\u{3000}\"Both\u{0020}business\u{0020}and\u{0020}personal.\"\n\u{3000}\u{3000}\"Name?\"\n\u{3000}\u{3000}\"Starry.\"\n\u{3000}\u{3000}\"...\"\n\u{3000}\u{3000}\"You\u{0020}are\u{0020}going\u{0020}to\u{0020}save\u{0020}her,\u{0020}not\u{0020}kill\u{0020}her.\"\n\u{3000}\u{3000}\"I\u{0020}know.\"\n\u{3000}\u{3000}Her\u{0020}conversations\u{0020}with\u{0020}Stephanie\u{0020}always\u{0020}seem\u{0020}to\u{0020}be\u{0020}this\u{0020}concise,\u{0020}as\u{0020}if\u{0020}adding\u{0020}even\u{0020}one\u{0020}more\u{0020}word\u{0020}would\u{0020}rob\u{0020}Chiaki\u{0020}of\u{0020}a\u{0020}portion\u{0020}of\u{0020}her\u{0020}life\u{0020}force.\n\u{3000}\u{3000}Although\u{0020}Chiaki\u{0020}does\u{0020}not\u{0020}know\u{0020}what\u{0020}kind\u{0020}of\u{0020}trouble\u{0020}Starry\u{0020}has\u{0020}gotten\u{0020}herself\u{0020}into,\u{0020}she\u{0020}still\u{0020}heads\u{0020}for\u{0020}that\u{0020}perilous\u{0020}place\u{0020}known\u{0020}as\u{0020}Maya.\u{0020}Before\u{0020}she\u{0020}leaves,\u{0020}Stephanie\u{0020}gives\u{0020}her\u{0020}two\u{0020}things.\n\u{3000}\u{3000}One\u{0020}is\u{0020}a\u{0020}piece\u{0020}of\u{0020}\"equipment\u{0020}specially\u{0020}designed\u{0020}to\u{0020}counter\u{0020}a\u{0020}Great\u{0020}Sin,\"\u{0020}hastily\u{0020}developed\u{0020}in\u{0020}response\u{0020}to\u{0020}the\u{0020}virus\u{0020}of\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}\"Gluttony\"\u{0020}and\u{0020}jointly\u{0020}created\u{0020}by\u{0020}Stephanie\u{0020}and\u{0020}the\u{0020}First\u{0020}Laboratory--something\u{0020}Chiaki\u{0020}swears\u{0020}she\u{0020}would\u{0020}rather\u{0020}die\u{0020}than\u{0020}wear.\n\u{3000}\u{3000}The\u{0020}other\u{0020}is\u{0020}a\u{0020}junior\u{0020}so\u{0020}overly\u{0020}familiar\u{0020}that\u{0020}she\u{0020}gives\u{0020}Chiaki\u{0020}a\u{0020}headache,\u{0020}to\u{0020}the\u{0020}point\u{0020}that\u{0020}Chiaki\u{0020}even\u{0020}considers\u{0020}whether\u{0020}she\u{0020}should\u{0020}find\u{0020}some\u{0020}deserted\u{0020}place\u{0020}to\u{0020}\"dispose\u{0020}of\"\u{0020}her--the\u{0020}\"Prisoner,\"\u{0020}Shigure.", "0", "0", "0", "0", 12031, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[623104] = {623104, 2000, "\u{3000}\u{3000}She\u{0020}is\u{0020}trash.\n\u{3000}\u{3000}She\u{0020}is\u{0020}the\u{0020}dregs\u{0020}of\u{0020}society.\n\u{3000}\u{3000}She\u{0020}is\u{0020}an\u{0020}aberration\u{0020}who\u{0020}cannot\u{0020}blend\u{0020}into\u{0020}any\u{0020}social\u{0020}group.\n\u{3000}\u{3000}She\u{0020}should\u{0020}be\u{0020}grateful\u{0020}simply\u{0020}to\u{0020}be\u{0020}alive.\n\u{3000}\u{3000}She\u{0020}should\u{0020}bow\u{0020}her\u{0020}head\u{0020}in\u{0020}thanks\u{0020}simply\u{0020}for\u{0020}being\u{0020}allowed\u{0020}to\u{0020}breathe.\n\u{3000}\u{3000}She\u{0020}should\u{0020}be\u{0020}satisfied\u{0020}simply\u{0020}to\u{0020}bathe\u{0020}in\u{0020}the\u{0020}sunlight\u{0020}like\u{0020}a\u{0020}normal\u{0020}person.\n\u{3000}\u{3000}But,\n\u{3000}\u{3000}if\u{0020}she\u{0020}could,\n\u{3000}\u{3000}she,\u{0020}too,\u{0020}wants\u{0020}to\u{0020}be\u{0020}like\u{0020}those\u{0020}innocent\u{0020}girls,\n\u{3000}\u{3000}and\u{0020}take\u{0020}his\u{0020}hand.", "0", "0", "0", "0", 12031, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
