[623501] = {623501, 100, "\u{3000}\u{3000}Yakumo\u{0020}Ezo,\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}Fifth\u{0020}Squad,\u{0020}is\u{0020}probably\u{0020}also\u{0020}the\u{0020}person\u{0020}in\u{0020}the\u{0020}Force\u{0020}who\u{0020}most\u{0020}understands\u{0020}how\u{0020}to\u{0020}enjoy\u{0020}life,\u{0020}and\u{0020}the\u{0020}most\u{0020}free-spirited\u{0020}of\u{0020}them\u{0020}all.\u{0020}\n\u{3000}\u{3000}She\u{0020}always\u{0020}wears\u{0020}a\u{0020}frivolous\u{0020}smile,\u{0020}has\u{0020}zero\u{0020}resistance\u{0020}to\u{0020}any\u{0020}cute\u{0020}girl,\u{0020}and\u{0020}dreams\u{0020}of\u{0020}building\u{0020}a\u{0020}harem\u{0020}made\u{0020}entirely\u{0020}of\u{0020}beautiful\u{0020}girls.\u{0020}She\u{0020}often\u{0020}gets\u{0020}teased,\u{0020}and\u{0020}even\u{0020}beaten\u{0020}up,\u{0020}for\u{0020}her\u{0020}sexual\u{0020}harassment\u{0020}antics,\u{0020}but\u{0020}she\u{0020}seems\u{0020}to\u{0020}enjoy\u{0020}it.\u{0020}\n\u{3000}\u{3000}Her\u{0020}Peach\u{0020}Blessing\u{0020}is\u{0020}Night\u{0020}Storm,\u{0020}a\u{0020}power\u{0020}as\u{0020}free\u{0020}and\u{0020}unrestrained\u{0020}as\u{0020}her\u{0020}personality:\u{0020}a\u{0020}formidable\u{0020}ability\u{0020}to\u{0020}command\u{0020}storms\u{0020}at\u{0020}will.", "0", "0", "0", "0", 12035, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[623502] = {623502, 500, "\u{3000}\u{3000}Yakumo\u{0020}Ezo\u{0020}is\u{0020}actually\u{0020}very\u{0020}strong.\u{0020}\n\u{3000}\u{3000}In\u{0020}this\u{0020}incident,\u{0020}the\u{0020}one\u{0020}most\u{0020}constrained\u{0020}may\u{0020}well\u{0020}have\u{0020}been\u{0020}that\u{0020}free-spirited\u{0020}girl\u{0020}herself.\u{0020}\n\u{3000}\u{3000}Compared\u{0020}to\u{0020}Mira\u{0020}Kamiunten\u{0020}and\u{0020}Fubuki\u{0020}Azuma,\u{0020}who\u{0020}can\u{0020}fight\u{0020}by\u{0020}creating\u{0020}clones\u{0020}or\u{0020}by\u{0020}piercing\u{0020}the\u{0020}enemy\u{0020}with\u{0020}a\u{0020}spear,\u{0020}Yakumo,\u{0020}fighting\u{0020}inside\u{0020}a\u{0020}city,\u{0020}cannot\u{0020}fully\u{0020}use\u{0020}her\u{0020}storm-controlling\u{0020}power.\u{0020}\n\u{3000}\u{3000}If\u{0020}she\u{0020}were\u{0020}to\u{0020}go\u{0020}all\u{0020}out...\u{0020}the\u{0020}city,\u{0020}and\u{0020}the\u{0020}people\u{0020}living\u{0020}in\u{0020}it,\u{0020}would\u{0020}probably\u{0020}be\u{0020}blown\u{0020}away\u{0020}in\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye.\u{0020}\n\u{3000}\u{3000}Because\u{0020}of\u{0020}that,\u{0020}she\u{0020}has\u{0020}to\u{0020}keep\u{0020}her\u{0020}ability\u{0020}tightly\u{0020}leashed\u{0020}throughout\u{0020}the\u{0020}fight\u{0020}against\u{0020}Sin.\u{0020}\n\u{3000}\u{3000}So\u{0020}she\u{0020}is\u{0020}not\u{0020}just\u{0020}comic\u{0020}relief.\u{0020}\n\u{3000}\u{3000}She\u{0020}is\u{0020}comic\u{0020}relief\u{0020}with\u{0020}real\u{0020}combat\u{0020}power.\u{0020}\n\u{3000}\u{3000}Though\u{0020}if\u{0020}you\u{0020}put\u{0020}it\u{0020}that\u{0020}way,\u{0020}she\u{0020}would\u{0020}probably\u{0020}get\u{0020}mad.\u{0020}\n\u{3000}\u{3000}Either\u{0020}way,\u{0020}in\u{0020}this\u{0020}incident,\u{0020}Yakumo's\u{0020}power\u{0020}was\u{0020}indispensable.\u{0020}If\u{0020}she\u{0020}had\u{0020}a\u{0020}stage\u{0020}better\u{0020}suited\u{0020}to\u{0020}her,\u{0020}she\u{0020}would\u{0020}surely\u{0020}shine\u{0020}even\u{0020}brighter.", "0", "0", "0", "0", 12035, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[623503] = {623503, 1000, "\u{3000}\u{3000}Being\u{0020}around\u{0020}Yakumo\u{0020}is\u{0020}relaxing,\u{0020}or\u{0020}so\u{0020}the\u{0020}Synesthete\u{0020}Navigator\u{0020}thinks.\u{0020}\n\u{3000}\u{3000}Fubuki\u{0020}Azuma\u{0020}is\u{0020}dependable,\u{0020}but\u{0020}if\u{0020}we're\u{0020}talking\u{0020}about\u{0020}someone\u{0020}who\u{0020}is\u{0020}simply\u{0020}easier\u{0020}to\u{0020}be\u{0020}around,\u{0020}then\u{0020}it\u{0020}has\u{0020}to\u{0020}be\u{0020}Yakumo\u{0020}Ezo.\u{0020}\n\u{3000}\u{3000}Without\u{0020}Yakumo\u{0020}as\u{0020}the\u{0020}social\u{0020}lubricant,\u{0020}even\u{0020}someone\u{0020}as\u{0020}mature\u{0020}and\u{0020}steady\u{0020}as\u{0020}Fubuki\u{0020}could\u{0020}end\u{0020}up\u{0020}letting\u{0020}negotiations\u{0020}turn\u{0020}stiff\u{0020}and\u{0020}tense.\u{0020}Yakumo's\u{0020}presence\u{0020}prevents\u{0020}that,\u{0020}almost\u{0020}effortlessly.\u{0020}\n\u{3000}\u{3000}Anyone\u{0020}around\u{0020}her\u{0020}can\u{0020}smile\u{0020}with\u{0020}ease,\u{0020}and\u{0020}there\u{0020}are\u{0020}likely\u{0020}many\u{0020}in\u{0020}her\u{0020}world\u{0020}who\u{0020}have\u{0020}been\u{0020}“saved”\u{0020}because\u{0020}of\u{0020}that.\u{0020}\n\u{3000}\u{3000}More\u{0020}than\u{0020}her\u{0020}strength\u{0020}as\u{0020}a\u{0020}commander,\u{0020}it\u{0020}is\u{0020}that\u{0020}easygoing,\u{0020}natural\u{0020}attitude\u{0020}that\u{0020}makes\u{0020}Yakumo\u{0020}charming.\u{0020}Of\u{0020}course,\u{0020}the\u{0020}harassment\u{0020}part\u{0020}does\u{0020}not\u{0020}count.", "0", "0", "0", "0", 12035, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[623504] = {623504, 2000, "\u{3000}\u{3000}\"Let's\u{0020}go\u{0020}for\u{0020}a\u{0020}ride\u{0020}together\".\u{0020}\n\u{3000}\u{3000}Not\u{0020}to\u{0020}run\u{0020}away\u{0020}from\u{0020}anything.\u{0020}\n\u{3000}\u{3000}It\u{0020}just\u{0020}feels\u{0020}like\u{0020}the\u{0020}wind\u{0020}is\u{0020}especially\u{0020}nice\u{0020}today,\u{0020}\n\u{3000}\u{3000}and\u{0020}it\u{0020}would\u{0020}be\u{0020}a\u{0020}shame\u{0020}not\u{0020}to\u{0020}enjoy\u{0020}it.\u{0020}\n\u{3000}\u{3000}No\u{0020}matter\u{0020}what\u{0020}kind\u{0020}of\u{0020}hardship\u{0020}lies\u{0020}ahead,\u{0020}\n\u{3000}\u{3000}just\u{0020}face\u{0020}it\u{0020}with\u{0020}a\u{0020}smile.\u{0020}\n\u{3000}\u{3000}Because\u{0020}a\u{0020}smile\u{0020}is\u{0020}the\u{0020}strongest\u{0020}weapon!\u{0020}\n\u{3000}\u{3000}So\u{0020}let's\u{0020}toss\u{0020}all\u{0020}our\u{0020}worries\u{0020}behind\u{0020}us,\u{0020}\n\u{3000}\u{3000}and\u{0020}go\u{0020}find\u{0020}the\u{0020}happiest\u{0020}things\u{0020}in\u{0020}the\u{0020}world!", "0", "0", "0", "0", 12035, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[623700] = {623700, 0, "[Name]\u{0020}Kyla\u{0020}Triaviemzum\n\u{0020}[B-day]\u{0020}July\u{0020}18\n\u{0020}[Transformation\u{0020}Core\u{0020}Compatibility]\u{0020}88%\n\u{0020}[Height]\u{0020}35m\n\u{0020}[Squad]\u{0020}Dunscaith\n\u{0020}[Affiliation]\u{0020}Heroine\u{0020}Universe\n\u{0020}[Hobbies]\u{0020}Sunshine\u{0020}and\u{0020}all\u{0020}kinds\u{0020}of\u{0020}outdoor\u{0020}sports", "0", "0", "0", "0", 12037, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[623701] = {623701, 100, "\u{3000}\u{3000}Among\u{0020}those\u{0020}who\u{0020}came\u{0020}to\u{0020}the\u{0020}Heroine\u{0020}Universe,\u{0020}cases\u{0020}where\u{0020}\"someone\u{0020}shows\u{0020}a\u{0020}completely\u{0020}different\u{0020}side\u{0020}from\u{0020}when\u{0020}they\u{0020}were\u{0020}alive\"\u{0020}are\u{0020}not\u{0020}uncommon.\u{0020}As\u{0020}long\u{0020}as\u{0020}one\u{0020}lives\u{0020}here\u{0020}long\u{0020}enough,\u{0020}there\u{0020}will\u{0020}always\u{0020}be\u{0020}a\u{0020}few\u{0020}times\u{0020}when\u{0020}they\u{0020}find\u{0020}themselves\u{0020}shouting\u{0020}at\u{0020}a\u{0020}once-familiar\u{0020}face,\u{0020}\"Who\u{0020}are\u{0020}you\u{0020}supposed\u{0020}to\u{0020}be!?\"\n\u{3000}\u{3000}And\u{0020}in\u{0020}this\u{0020}environment\u{0020}that\u{0020}could\u{0020}practically\u{0020}be\u{0020}called\u{0020}a\u{0020}giant\u{0020}jack-in-the-box,\u{0020}Kyla\u{0020}can\u{0020}almost\u{0020}be\u{0020}described\u{0020}as\u{0020}completely\u{0020}unchanged--though\u{0020}that\u{0020}fact\u{0020}alone\u{0020}is\u{0020}not\u{0020}especially\u{0020}rare,\u{0020}since\u{0020}there\u{0020}are\u{0020}examples\u{0020}like\u{0020}Ophelia\u{0020}elsewhere\u{0020}as\u{0020}well.\n\u{3000}\u{3000}What\u{0020}truly\u{0020}shocks\u{0020}most\u{0020}people\u{0020}is\u{0020}the\u{0020}reason\u{0020}Kyla\u{0020}has\u{0020}not\u{0020}changed\u{0020}at\u{0020}all:\u{0020}[Heroine's\u{0020}Memory],\u{0020}the\u{0020}recollections\u{0020}almost\u{0020}every\u{0020}heroine\u{0020}treasures,\u{0020}concerning\u{0020}how\u{0020}the\u{0020}story\u{0020}between\u{0020}them\u{0020}and\u{0020}Navigator\u{0020}reached\u{0020}its\u{0020}end,\u{0020}was\u{0020}forgotten\u{0020}by\u{0020}Kyla\u{0020}along\u{0020}with\u{0020}most\u{0020}of\u{0020}her\u{0020}memories\u{0020}of\u{0020}that\u{0020}timeline,\u{0020}leaving\u{0020}nothing\u{0020}behind.\n\u{3000}\u{3000}Moreover,\u{0020}unlike\u{0020}Miss\u{0020}Future,\u{0020}who\u{0020}was\u{0020}once\u{0020}a\u{0020}wanted\u{0020}criminal,\u{0020}even\u{0020}when\u{0020}the\u{0020}\"Memory\u{0020}Dreams\"\u{0020}provided\u{0020}as\u{0020}a\u{0020}default\u{0020}service\u{0020}of\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}visit\u{0020}her\u{0020}at\u{0020}a\u{0020}fairly\u{0020}normal\u{0020}frequency,\u{0020}Kyla\u{0020}can\u{0020}still\u{0020}forget\u{0020}all\u{0020}of\u{0020}those\u{0020}memories\u{0020}again\u{0020}within\u{0020}just\u{0020}a\u{0020}few\u{0020}short\u{0020}hours.\n\u{3000}\u{3000}Miss\u{0020}Kyla\u{0020}[whose\u{0020}full\u{0020}name\u{0020}is\u{0020}too\u{0020}complicated,\u{0020}and\u{0020}she\u{0020}does\u{0020}not\u{0020}care\u{0020}either,\u{0020}so\u{0020}it\u{0020}will\u{0020}not\u{0020}be\u{0020}read\u{0020}out]\u{0020}may\u{0020}be\u{0020}the\u{0020}only\u{0020}heroine\u{0020}most\u{0020}people\u{0020}have\u{0020}ever\u{0020}seen\u{0020}who\u{0020}does\u{0020}not\u{0020}possess\u{0020}[Heroine's\u{0020}Memory].", "0", "0", "0", "0", 12037, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[623702] = {623702, 500, "\u{3000}\u{3000}Obviously,\u{0020}given\u{0020}Kyla's\u{0020}personality,\u{0020}it\u{0020}is\u{0020}difficult\u{0020}for\u{0020}her\u{0020}to\u{0020}understand\u{0020}why\u{0020}some\u{0020}people\u{0020}see\u{0020}her\u{0020}as\u{0020}something\u{0020}like\u{0020}an\u{0020}unidentified\u{0020}life-form.\u{0020}(Assuming\u{0020}she\u{0020}has\u{0020}actually\u{0020}noticed\u{0020}that\u{0020}in\u{0020}the\u{0020}first\u{0020}place.)\u{0020}But\u{0020}in\u{0020}any\u{0020}case,\u{0020}this\u{0020}has\u{0020}not\u{0020}had\u{0020}much\u{0020}effect\u{0020}on\u{0020}her\u{0020}life\u{0020}after\u{0020}rebirth.\n\u{3000}\u{3000}Like\u{0020}most\u{0020}heroines,\u{0020}Kyla\u{0020}wakes\u{0020}up\u{0020}on\u{0020}a\u{0020}comfortable,\u{0020}habitable\u{0020}planet,\u{0020}has\u{0020}normal\u{0020}and\u{0020}friendly\u{0020}contact\u{0020}with\u{0020}the\u{0020}Association\u{0020}personnel\u{0020}sent\u{0020}to\u{0020}receive\u{0020}her,\u{0020}and\u{0020}cooperatively\u{0020}completes\u{0020}the\u{0020}procedures\u{0020}for\u{0020}her\u{0020}universe\u{0020}pass\u{0020}(a\u{0020}special\u{0020}model\u{0020}with\u{0020}fully\u{0020}automatic\u{0020}loss\u{0020}reporting).\u{0020}After\u{0020}that,\u{0020}she\u{0020}throws\u{0020}herself\u{0020}into\u{0020}her\u{0020}second\u{0020}life\u{0020}as\u{0020}if\u{0020}she\u{0020}had\u{0020}been\u{0020}released\u{0020}back\u{0020}into\u{0020}the\u{0020}wild.\u{0020}There\u{0020}are\u{0020}absolutely\u{0020}no\u{0020}signs\u{0020}that\u{0020}she\u{0020}might\u{0020}suddenly\u{0020}transform\u{0020}into\u{0020}some\u{0020}cosmic\u{0020}disaster.\u{0020}She\u{0020}is\u{0020}so\u{0020}stable\u{0020}that\u{0020}it\u{0020}is\u{0020}almost\u{0020}moving.\n\u{3000}\u{3000}According\u{0020}to\u{0020}the\u{0020}records\u{0020}kept\u{0020}by\u{0020}the\u{0020}Association,\u{0020}Kyla\u{0020}remains\u{0020}in\u{0020}a\u{0020}state\u{0020}of\u{0020}irregular\u{0020}free\u{0020}activity\u{0020}for\u{0020}quite\u{0020}a\u{0020}long\u{0020}time:\u{0020}she\u{0020}will\u{0020}suddenly\u{0020}appear\u{0020}on\u{0020}some\u{0020}planet,\u{0020}just\u{0020}as\u{0020}suddenly\u{0020}appear\u{0020}in\u{0020}certain\u{0020}incidents,\u{0020}and\u{0020}then\u{0020}just\u{0020}as\u{0020}suddenly\u{0020}play\u{0020}some\u{0020}kind\u{0020}of\u{0020}role.\u{0020}As\u{0020}a\u{0020}result,\u{0020}she\u{0020}completes\u{0020}a\u{0020}number\u{0020}of\u{0020}public\u{0020}jobs\u{0020}issued\u{0020}by\u{0020}the\u{0020}Association,\u{0020}but\u{0020}since\u{0020}she\u{0020}never\u{0020}once\u{0020}comes\u{0020}to\u{0020}claim\u{0020}the\u{0020}corresponding\u{0020}rewards,\u{0020}these\u{0020}are\u{0020}probably\u{0020}all\u{0020}just\u{0020}pure\u{0020}coincidences.\n\u{3000}\u{3000}No\u{0020}one\u{0020}knows\u{0020}what\u{0020}kind\u{0020}of\u{0020}coincidences\u{0020}allow\u{0020}Kyla\u{0020}to\u{0020}travel\u{0020}between\u{0020}stars\u{0020}with\u{0020}such\u{0020}high\u{0020}frequency.\u{0020}Thanks\u{0020}to\u{0020}her\u{0020}well-known\u{0020}excessive\u{0020}energy,\u{0020}even\u{0020}though\u{0020}her\u{0020}universe\u{0020}pass\u{0020}has\u{0020}long\u{0020}since\u{0020}been\u{0020}equipped\u{0020}with\u{0020}an\u{0020}emergency\u{0020}recall\u{0020}function\u{0020}just\u{0020}in\u{0020}case,\u{0020}many\u{0020}people\u{0020}still\u{0020}worry\u{0020}that\u{0020}Kyla\u{0020}will\u{0020}one\u{0020}day\u{0020}disappear\u{0020}into\u{0020}some\u{0020}unknown\u{0020}corner\u{0020}of\u{0020}the\u{0020}universe.\u{0020}This\u{0020}worry\u{0020}grows\u{0020}day\u{0020}by\u{0020}day\u{0020}as\u{0020}her\u{0020}whereabouts\u{0020}become\u{0020}more\u{0020}and\u{0020}more\u{0020}unexpected,\u{0020}until\u{0020}one\u{0020}Association\u{0020}member\u{0020}responsible\u{0020}for\u{0020}keeping\u{0020}an\u{0020}eye\u{0020}on\u{0020}her\u{0020}finally\u{0020}reaches\u{0020}the\u{0020}limit\u{0020}of\u{0020}her\u{0020}patience.\n\u{3000}\u{3000}\"Whoa!\u{0020}Rosa!\u{0020}Why\u{0020}did\u{0020}you\