[623703] = {623703, 1000, "\u{3000}\u{3000}And\u{0020}so,\u{0020}Kyla's\u{0020}life\u{0020}as\u{0020}a\u{0020}cosmic\u{0020}street\u{0020}wanderer\u{0020}came\u{0020}to\u{0020}an\u{0020}end.\n\u{3000}\u{3000}Since\u{0020}Kyla\u{0020}herself\u{0020}has\u{0020}no\u{0020}particular\u{0020}objection\u{0020}to\u{0020}this,\u{0020}while\u{0020}Rosalind\u{0020}saves\u{0020}a\u{0020}great\u{0020}deal\u{0020}of\u{0020}the\u{0020}time\u{0020}she\u{0020}would\u{0020}otherwise\u{0020}have\u{0020}spent\u{0020}dragging\u{0020}Kyla\u{0020}back\u{0020}from\u{0020}all\u{0020}kinds\u{0020}of\u{0020}dangerous\u{0020}places,\u{0020}this\u{0020}is\u{0020}a\u{0020}very\u{0020}positive\u{0020}change.\n\u{3000}\u{3000}After\u{0020}joining\u{0020}the\u{0020}Heroine\u{0020}Association\u{0020}as\u{0020}Rosalind's\u{0020}subordinate,\u{0020}Kyla\u{0020}takes\u{0020}on\u{0020}the\u{0020}role\u{0020}of\u{0020}field\u{0020}dispatcher\u{0020}in\u{0020}various\u{0020}incidents,\u{0020}sharing\u{0020}Rosalind's\u{0020}workload\u{0020}while\u{0020}creating\u{0020}all\u{0020}kinds\u{0020}of\u{0020}unexpected\u{0020}gains\u{0020}through\u{0020}her\u{0020}own\u{0020}intuition.\u{0020}After\u{0020}all,\u{0020}anyone\u{0020}can\u{0020}question\u{0020}Kyla's\u{0020}memory,\u{0020}but\u{0020}what\u{0020}truly\u{0020}allows\u{0020}her\u{0020}friends\u{0020}to\u{0020}overlook\u{0020}that\u{0020}flaw\u{0020}is\u{0020}precisely\u{0020}her\u{0020}heart,\u{0020}which\u{0020}can\u{0020}face\u{0020}everything\u{0020}with\u{0020}positivity.\n\u{3000}\u{3000}Even\u{0020}Lady\u{0020}Rosalind,\u{0020}who\u{0020}rarely\u{0020}admits\u{0020}defeat,\u{0020}is\u{0020}willing\u{0020}to\u{0020}acknowledge\u{0020}in\u{0020}private\u{0020}that\u{0020}half\u{0020}the\u{0020}credit\u{0020}for\u{0020}the\u{0020}Outstanding\u{0020}Employee\u{0020}Awards\u{0020}she\u{0020}has\u{0020}won\u{0020}for\u{0020}several\u{0020}consecutive\u{0020}terms\u{0020}belongs\u{0020}to\u{0020}Kyla.\u{0020}As\u{0020}for\u{0020}why\u{0020}she\u{0020}only\u{0020}admits\u{0020}it\u{0020}in\u{0020}private,\u{0020}that\u{0020}is\u{0020}to\u{0020}prevent\u{0020}Kyla\u{0020}from\u{0020}getting\u{0020}carried\u{0020}away.\n\u{3000}\u{3000}And\u{0020}so,\u{0020}with\u{0020}her\u{0020}reunion\u{0020}with\u{0020}her\u{0020}old\u{0020}partner,\u{0020}even\u{0020}without\u{0020}the\u{0020}memories\u{0020}that\u{0020}are\u{0020}incomparably\u{0020}precious\u{0020}to\u{0020}most\u{0020}people,\u{0020}Kyla's\u{0020}life\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}continues\u{0020}in\u{0020}an\u{0020}orderly\u{0020}fashion\u{0020}today\u{0020}as\u{0020}well.\n\u{3000}\u{3000}...As\u{0020}for\u{0020}the\u{0020}fact\u{0020}that,\u{0020}while\u{0020}escaping\u{0020}a\u{0020}small\u{0020}black\u{0020}hole,\u{0020}she\u{0020}threw\u{0020}out\u{0020}the\u{0020}part\u{0020}of\u{0020}the\u{0020}ship\u{0020}that\u{0020}happened\u{0020}to\u{0020}contain\u{0020}Rosalind's\u{0020}private\u{0020}treasury,\u{0020}causing\u{0020}the\u{0020}person\u{0020}in\u{0020}question\u{0020}to\u{0020}suddenly\u{0020}become\u{0020}a\u{0020}debtor,\u{0020}and\u{0020}the\u{0020}fact\u{0020}that\u{0020}she\u{0020}was\u{0020}later\u{0020}assigned\u{0020}to\u{0020}serve\u{0020}as\u{0020}an\u{0020}equipment\u{0020}tester\u{0020}for\u{0020}a\u{0020}certain\u{0020}petite\u{0020}craftswoman\u{0020}among\u{0020}the\u{0020}collaborators--those\u{0020}are\u{0020}stories\u{0020}for\u{0020}another\u{0020}time.", "0", "0", "0", "0", 12037, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[623704] = {623704, 2000, "\u{3000}\u{3000}The\u{0020}morning\u{0020}sun\u{0020}is\u{0020}so\u{0020}dazzling.\n\u{3000}\u{3000}Though\u{0020}on\u{0020}closer\u{0020}inspection,\u{0020}that\u{0020}thing\u{0020}on\u{0020}the\u{0020}horizon\u{0020}looks\u{0020}less\u{0020}like\u{0020}the\u{0020}morning\u{0020}sun\u{0020}and\u{0020}more\u{0020}like\u{0020}a\u{0020}sunset\u{0020}with\u{0020}its\u{0020}colors\u{0020}configured\u{0020}incorrectly.\u{0020}Also,\u{0020}it\u{0020}is\u{0020}hard\u{0020}to\u{0020}say\u{0020}whether\u{0020}this\u{0020}dazzling\u{0020}sensation\u{0020}comes\u{0020}from\u{0020}the\u{0020}light\u{0020}itself,\u{0020}or\u{0020}from\u{0020}the\u{0020}physiological\u{0020}reaction\u{0020}caused\u{0020}by\u{0020}being\u{0020}hung\u{0020}upside\u{0020}down\u{0020}for\u{0020}too\u{0020}long.\n\u{3000}\u{3000}\"Hehe...\u{0020}Looks\u{0020}like\u{0020}I\u{0020}messed\u{0020}up\u{0020}again.\"\n\u{3000}\u{3000}Kyla,\u{0020}hanging\u{0020}from\u{0020}another\u{0020}branch\u{0020}nearby,\u{0020}smiles\u{0020}a\u{0020}little\u{0020}awkwardly.\n\u{3000}\u{3000}Although\u{0020}this\u{0020}is\u{0020}already\u{0020}about\u{0020}the\u{0020}third\u{0020}time\u{0020}today\u{0020}they\u{0020}have\u{0020}been\u{0020}hung\u{0020}up\u{0020}somewhere,\u{0020}from\u{0020}the\u{0020}moment\u{0020}Navigator\u{0020}agreed\u{0020}to\u{0020}go\u{0020}exploring\u{0020}with\u{0020}her,\u{0020}something\u{0020}like\u{0020}this\u{0020}had\u{0020}long\u{0020}since\u{0020}been\u{0020}within\u{0020}expectations.\n\u{3000}\u{3000}And\u{0020}so,\u{0020}while\u{0020}they\u{0020}remain\u{0020}hanging\u{0020}upside\u{0020}down\u{0020}and\u{0020}wait\u{0020}for\u{0020}rescue,\u{0020}Kyla\u{0020}keeps\u{0020}excitedly\u{0020}talking\u{0020}about\u{0020}everything\u{0020}that\u{0020}happened\u{0020}throughout\u{0020}the\u{0020}day,\u{0020}as\u{0020}if\u{0020}even\u{0020}the\u{0020}most\u{0020}ordinary\u{0020}things\u{0020}can\u{0020}shine\u{0020}with\u{0020}incredible\u{0020}brilliance\u{0020}in\u{0020}her\u{0020}eyes.\n\u{3000}\u{3000}A\u{0020}lack\u{0020}of\u{0020}common\u{0020}sense,\u{0020}fair\u{0020}weather,\u{0020}no\u{0020}threats\u{0020}from\u{0020}Sins\u{0020}or\u{0020}any\u{0020}other\u{0020}evil\u{0020}aliens,\u{0020}and\u{0020}clear\u{0020}skies\u{0020}for\u{0020}eighty\u{0020}percent\u{0020}of\u{0020}the\u{0020}year.\n\u{3000}\u{3000}There\u{0020}is\u{0020}no\u{0020}place\u{0020}more\u{0020}suited\u{0020}for\u{0020}her\u{0020}to\u{0020}live\u{0020}than\u{0020}this...\u{0020}Hmm,\u{0020}probably\u{0020}not.", "0", "0", "0", "0", 12037, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
