[623801] = {623801, 100, "\u{3000}\u{3000}The\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}a\u{0020}place\u{0020}where\u{0020}heroines\u{0020}gather.\n\u{3000}\u{3000}Among\u{0020}the\u{0020}many\u{0020}kinds\u{0020}of\u{0020}heroines\u{0020}living\u{0020}here,\u{0020}Rosalind\u{0020}could\u{0020}be\u{0020}considered\u{0020}a\u{0020}representative\u{0020}of\u{0020}the\u{0020}\"average\u{0020}case\":\u{0020}her\u{0020}personality\u{0020}has\u{0020}not\u{0020}undergone\u{0020}any\u{0020}exaggerated\u{0020}changes,\u{0020}she\u{0020}has\u{0020}never\u{0020}caused\u{0020}any\u{0020}incidents,\u{0020}and\u{0020}she\u{0020}certainly\u{0020}has\u{0020}not\u{0020}suddenly\u{0020}turned\u{0020}into\u{0020}a\u{0020}Universal\u{0020}Calamity\u{0020}through\u{0020}some\u{0020}inexplicable\u{0020}chain\u{0020}of\u{0020}logic.\u{0020}She\u{0020}simply\u{0020}found\u{0020}a\u{0020}general\u{0020}direction\u{0020}for\u{0020}her\u{0020}new\u{0020}life,\u{0020}joined\u{0020}the\u{0020}Heroine\u{0020}Association\u{0020}thanks\u{0020}to\u{0020}her\u{0020}diligent\u{0020}nature,\u{0020}and\u{0020}was\u{0020}placed\u{0020}on\u{0020}the\u{0020}list\u{0020}of\u{0020}candidates\u{0020}for\u{0020}Outstanding\u{0020}Employee\u{0020}not\u{0020}long\u{0020}after\u{0020}starting\u{0020}the\u{0020}job.\n\u{3000}\u{3000}Judging\u{0020}from\u{0020}that\u{0020}description\u{0020}alone,\u{0020}her\u{0020}life\u{0020}might\u{0020}sound\u{0020}somewhat\u{0020}dull.\u{0020}But\u{0020}in\u{0020}a\u{0020}place\u{0020}this\u{0020}bizarre\u{0020}and\u{0020}fantastical,\u{0020}it\u{0020}is\u{0020}precisely\u{0020}people\u{0020}who\u{0020}are\u{0020}relatively\u{0020}conscientious\u{0020}like\u{0020}her\u{0020}who\u{0020}keep\u{0020}everything\u{0020}running\u{0020}smoothly.\n\u{3000}\u{3000}\"Does\u{0020}throwing\u{0020}all\u{0020}the\u{0020}money\u{0020}you\u{0020}earn\u{0020}into\u{0020}various\u{0020}investment\u{0020}projects\u{0020}count\u{0020}as\u{0020}average\u{0020}behavior\u{0020}too?\"\n\u{3000}\u{3000}\"This\u{0020}is\u{0020}a\u{0020}place\u{0020}with\u{0020}so\u{0020}much\u{0020}excess\u{0020}productivity\u{0020}that\u{0020}no\u{0020}one\u{0020}even\u{0020}knows\u{0020}what\u{0020}to\u{0020}do\u{0020}with\u{0020}it.\u{0020}Surely\u{0020}how\u{0020}this\u{0020}young\u{0020}lady\u{0020}chooses\u{0020}to\u{0020}allocate\u{0020}her\u{0020}assets\u{0020}is\u{0020}none\u{0020}of\u{0020}your\u{0020}business!\"\n\u{3000}\u{3000}As\u{0020}described\u{0020}above,\u{0020}at\u{0020}most,\u{0020}she\u{0020}simply\u{0020}seems\u{0020}a\u{0020}little\u{0020}obsessed\u{0020}with\u{0020}becoming\u{0020}a\u{0020}genuine\u{0020}noble\u{0020}in\u{0020}her\u{0020}second\u{0020}life.", "0", "0", "0", "0", 12038, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[623802] = {623802, 500, "\u{3000}\u{3000}To\u{0020}build\u{0020}herself\u{0020}up\u{0020}from\u{0020}nothing\u{0020}into\u{0020}a\u{0020}true\u{0020}noble,\u{0020}Rosalind\u{0020}has\u{0020}put\u{0020}effort\u{0020}into\u{0020}all\u{0020}sorts\u{0020}of\u{0020}things.\n\u{3000}\u{3000}First,\u{0020}she\u{0020}steadily\u{0020}accumulates\u{0020}funds\u{0020}through\u{0020}her\u{0020}official\u{0020}work\u{0020}at\u{0020}the\u{0020}Association.\u{0020}Then,\u{0020}based\u{0020}on\u{0020}each\u{0020}heroine's\u{0020}personality,\u{0020}she\u{0020}carefully\u{0020}chooses\u{0020}investment\u{0020}projects\u{0020}and\u{0020}business\u{0020}partners,\u{0020}while\u{0020}also\u{0020}avoiding\u{0020}unnecessary\u{0020}spending\u{0020}in\u{0020}her\u{0020}personal\u{0020}life...\u{0020}In\u{0020}theory,\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}hardly\u{0020}the\u{0020}sort\u{0020}of\u{0020}place\u{0020}where\u{0020}living\u{0020}responsibly\u{0020}goes\u{0020}unrewarded,\u{0020}so\u{0020}Rosalind's\u{0020}cautious\u{0020}and\u{0020}reliable\u{0020}approach\u{0020}should\u{0020}have\u{0020}brought\u{0020}her\u{0020}dream\u{0020}within\u{0020}reach\u{0020}long\u{0020}ago.\u{0020}In\u{0020}reality,\u{0020}however,\u{0020}she\u{0020}is\u{0020}still\u{0020}working\u{0020}hard\u{0020}to\u{0020}save\u{0020}up\u{0020}enough\u{0020}money\u{0020}to\u{0020}become\u{0020}the\u{0020}owner\u{0020}of\u{0020}an\u{0020}entire\u{0020}planet,\u{0020}her\u{0020}circumstances\u{0020}remaining\u{0020}every\u{0020}bit\u{0020}as\u{0020}stable\u{0020}as\u{0020}her\u{0020}motivation.\n\u{3000}\u{3000}\"To\u{0020}sum\u{0020}up\u{0020}the\u{0020}reason\u{0020}in\u{0020}the\u{0020}words\u{0020}of\u{0020}her\u{0020}colleagues\u{0020}at\u{0020}the\u{0020}Association:\u{0020}Rosalind\u{0020}is\u{0020}just\u{0020}unbelievably\u{0020}unlucky.\"\n\u{3000}\u{3000}Whether\u{0020}this\u{0020}is\u{0020}simply\u{0020}a\u{0020}trait\u{0020}of\u{0020}the\u{0020}Rosalind\u{0020}who\u{0020}once\u{0020}became\u{0020}a\u{0020}heroine,\u{0020}or\u{0020}whether\u{0020}the\u{0020}universe\u{0020}itself\u{0020}is\u{0020}quietly\u{0020}tampering\u{0020}with\u{0020}things,\u{0020}no\u{0020}one\u{0020}knows.\u{0020}In\u{0020}any\u{0020}case,\u{0020}the\u{0020}Rosalind\u{0020}of\u{0020}today\u{0020}seems\u{0020}to\u{0020}suffer\u{0020}extraordinarily\u{0020}coincidental\u{0020}bouts\u{0020}of\u{0020}\"bad\u{0020}luck\"\u{0020}in\u{0020}all\u{0020}sorts\u{0020}of\u{0020}situations.\u{0020}\"A\u{0020}risk\u{0020}assessed\u{0020}at\u{0020}less\u{0020}than\u{0020}a\u{0020}1%\u{0020}chance\u{0020}of\u{0020}occurring\u{0020}somehow\u{0020}happens\u{0020}specifically\u{0020}to\u{0020}her.\"\u{0020}\"On\u{0020}the\u{0020}way\u{0020}to\u{0020}meet\u{0020}an\u{0020}important\u{0020}business\u{0020}partner,\u{0020}she\u{0020}is\u{0020}suddenly\u{0020}swept\u{0020}away\u{0020}by\u{0020}cosmic\u{0020}turbulence\u{0020}and\u{0020}ends\u{0020}up\u{0020}owing\u{0020}a\u{0020}huge\u{0020}breach-of-contract\u{0020}penalty\u{0020}out\u{0020}of\u{0020}nowhere.\"\u{0020}\"Her\u{0020}private\u{0020}vault,\u{0020}containing\u{0020}nearly\u{0020}all\u{0020}her\u{0020}assets,\u{0020}gets\u{0020}thrown\u{0020}overboard\u{0020}by\u{0020}an\u{0020}uninformed\u{0020}subordinate\u{0020}while\u{0020}escaping\u{0020}a\u{0020}miniature\u{0020}black\u{0020}hole\"...\u{0020}Misfortunes\u{0020}like\u{0020}these\u{0020}keep\u{0020}happening\u{0020}one\u{0020}after\u{0020}another,\u{0020}always\u{0020}with\u{0020}the\u{0020}remarkable\u{0020}professionalism\u{0020}of\u{0020}inconveniencing\u{0020}Rosalind\u{0020}and\u{0020}Rosalind\u{0020}alone\u{0020}without\u{0020}causing\u{0020}any\u{0020}collateral\u{0020}damage.\u{0020}Over\u{0020}time,\u{0020}many\u{0020}people\u{0020}have\u{0020}begun\u{0020}to\u{0020}feel\u{0020}an\u{0020}instinctive\u{0020}sense\u{0020}of\u{0020}sympathy\u{0020}whenever\u{0020}the\u{0020}topic\u{0020}of\u{0020}\"when\u{0020}Rosalind\u{0020}will\u{0020}finally\u{0020}manage\u{0020}to\u{0020}save\u{0020}enough\u{0020}money\"\u{0020}comes\u{0020}up.\n\u{3000}\u{3000}Fortunately,\u{0020}bleak\u{0020}as\u{0020}her\u{0020}current\u{0020}situation\u{0020}may\u{0020}be,\u{0020}Rosalind\u{0020}continues\u{0020}to\u{0020}plan\u{0020}toward\u{0020}achieving\u{0020}her\u{0020}dream\u{0020}with\u{0020}unwavering\u{0020}determination.\u{0020}Whether\u{0020}that\u{0020}comes\u{0020}from\u{0020}Kyla's\u{0020}influence\u{0020}or\u{0020}from\u{0020}a\u{0020}personality\u{0020}that\u{0020}is\u{0020}clearly\u{0020}far\u{0020}more\u{0020}easygoing\u{0020}than\u{0020}everyone\u{0020}once\u{0020}imagined,\u{0020}outsiders\u{0020}can\u{0020}only\u{0020}guess.\n\u{3000}\u{3000}As\u{0020}the\u{0020}saying\u{0020}goes,\u{0020}even\u{0020}if\u{0020}you\u{0020}lose,\u{0020}you\u{0020}must\u{0020}never\u{0020}lose\u{0020}face.\u{0020}Although\u{0020}she\u{0020}normally\u{0020}has\u{0020}plenty\u{0020}of\u{0020}self-control,\u{0020}Rosalind\u{0020}refuses\u{0020}to\u{0020}compromise\u{0020}on\u{0020}anything\u{0020}involving\u{0020}\"making\u{0020}sure\u{0020}people\u{0020}recognize\u{0020}her\u{0020}as\u{0020}a\u{0020}proper\u{0020}noble\u{0020}lady,\"\u{0020}and\u{0020}can\u{0020}easily\u{0020}get\u{0020}carried\u{0020}away\u{0020}and\u{0020}spend\u{0020}money\u{0020}she\u{0020}never\u{0020}intended\u{0020}to.\u{0020}To\u{0020}make\u{0020}up\u{0020}for\u{0020}those\u{0020}unexpected\u{0020}expenses,\u{0020}she\u{0020}occasionally\u{0020}takes\u{0020}part-time\u{0020}jobs\u{0020}at\u{0020}restaurants\u{0020}introduced\u{0020}by\u{0020}acquaintances.", "0", "0", "0", "0", 12038, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[623803] = {623803, 1000, "\u{3000}\u{3000}After\u{0020}the\u{0020}crisis\u{0020}caused\u{0020}by\u{0020}the\u{0020}Universal\u{0020}Calamity\u{0020}was\u{0020}resolved,\u{0020}Rosalind\u{0020}and\u{0020}several\u{0020}other\u{0020}heroines\u{0020}holding\u{0020}important\u{0020}positions\u{0020}in\u{0020}the\u{0020}area\u{0020}immediately\u{0020}threw\u{0020}themselves\u{0020}into\u{0020}rebuilding\u{0020}the\u{0020}\"former\u{0020}Sin\u{0020}Vegas.\"\n\u{3000}\u{3000}--That\u{0020}said,\u{0020}thanks\u{0020}to\u{0020}the\u{0020}unexpectedly\u{0020}smooth\u{0020}resolution\u{0020}of\u{0020}the\u{0020}incident,\u{0020}the\u{0020}city\u{0020}itself\u{0020}remained\u{0020}remarkably\u{0020}intact\u{0020}afterward.\u{0020}The\u{0020}only\u{0020}large-scale\u{0020}work\u{0020}required\u{0020}was\u{0020}replacing\u{0020}every\u{0020}reference\u{0020}to\u{0020}\"Sin\"\u{0020}on\u{0020}signs\u{0020}and\u{0020}promotional\u{0020}materials,\u{0020}which\u{0020}was\u{0020}obviously\u{0020}hardly\u{0020}a\u{0020}difficult\u{0020}task\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe.\n\u{3000}\u{3000}...\n\u{3000}\u{3000}In\u{0020}the\u{0020}end,\u{0020}although\u{0020}she\u{0020}once\u{0020}again\u{0020}entered\u{0020}the\u{0020}situation\u{0020}as\u{0020}a\u{0020}victim,\u{0020}Rosalind\u{0020}did\u{0020}legitimately\u{0020}obtain\u{0020}administrative\u{0020}authority\u{0020}over\u{0020}a\u{0020}coastal\u{0020}tourist\u{0020}district,\u{0020}taking\u{0020}a\u{0020}huge\u{0020}step\u{0020}toward\u{0020}what\u{0020}had\u{0020}once\u{0020}seemed\u{0020}like\u{0020}a\u{0020}hopelessly\u{0020}distant\u{0020}goal.\n\u{3000}\u{3000}\"Now\u{0020}it's\u{0020}time\u{0020}for\u{0020}this\u{0020}young\u{0020}lady\u{0020}to\u{0020}show\u{0020}off\u{0020}her\u{0020}talents!\u{0020}Prepare\u{0020}yourself,\u{0020}Navigator.\u{0020}By\u{0020}the\u{0020}next\u{0020}time\u{0020}you\u{0020}visit,\u{0020}I\u{0020}guarantee\u{0020}I'll\u{0020}turn\u{0020}'Navigator\u{0020}Vegas'\u{0020}into\u{0020}a\u{0020}tourist\u{0020}destination\u{0020}so\u{0020}famous\u{0020}you'll\u{0020}hear\u{0020}advertisements\u{0020}for\u{0020}it\u{0020}from\u{0020}the\u{0020}other\u{0020}side\u{0020}of\u{0020}the\u{0020}galaxy!\"\n\u{3000}\u{3000}\"That's\u{0020}some\u{0020}incredible\u{0020}determination,\u{0020}but\u{0020}didn't\u{0020}we\u{0020}already\u{0020}agree\u{0020}to\u{0020}change\u{0020}that\u{0020}name!?\"", "0", "0", "0", "0", 12038, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[623804] = {623804, 2000, "\u{3000}\u{3000}As\u{0020}expected,\u{0020}today\u{0020}has\u{0020}been\u{0020}another\u{0020}day\u{0020}that\u{0020}left\u{0020}something\u{0020}to\u{0020}be\u{0020}desired.\n\u{3000}\u{3000}Kyla\u{0020}caused\u{0020}trouble\u{0020}again,\u{0020}the\u{0020}financial\u{0020}situation\u{0020}is\u{0020}as\u{0020}poor\u{0020}as\u{0020}ever,\u{0020}and\u{0020}the\u{0020}list\u{0020}of\u{0020}things\u{0020}waiting\u{0020}to\u{0020}be\u{0020}dealt\u{0020}with\u{0020}is\u{0020}piling\u{0020}up\u{0020}like\u{0020}a\u{0020}mountain...\u{0020}But\u{0020}even\u{0020}if\u{0020}you\u{0020}stacked\u{0020}all\u{0020}those\u{0020}problems\u{0020}together\u{0020}and\u{0020}doubled\u{0020}them,\u{0020}they\u{0020}would\u{0020}still\u{0020}be\u{0020}nothing\u{0020}more\u{0020}than\u{0020}fleeting\u{0020}clouds\u{0020}to\u{0020}this\u{0020}young\u{0020}lady.\n\u{3000}\u{3000}--If\u{0020}you\u{0020}simply\u{0020}assumed\u{0020}that\u{0020}this\u{0020}young\u{0020}lady\u{0020}was\u{0020}influenced\u{0020}by\u{0020}a\u{0020}certain\u{0020}subordinate,\u{0020}that\u{0020}would\u{0020}be\u{0020}far\u{0020}too\u{0020}disrespectful.\u{0020}A\u{0020}noble's\u{0020}confidence\u{0020}naturally\u{0020}has\u{0020}reasons\u{0020}of\u{0020}its\u{0020}own.\n\u{3000}\u{3000}Within\u{0020}those\u{0020}memories,\u{0020}filled\u{0020}with\u{0020}both\u{0020}regret\u{0020}and\u{0020}beauty,\u{0020}that\u{0020}I\u{0020}brought\u{0020}with\u{0020}me\u{0020}as\u{0020}my\u{0020}only\u{0020}luggage,\u{0020}lies\u{0020}the\u{0020}reason\u{0020}I\u{0020}can\u{0020}always\u{0020}hold\u{0020}my\u{0020}head\u{0020}high.\n\u{3000}\u{3000}After\u{0020}all,\u{0020}I\u{0020}have\u{0020}already\u{0020}been\u{0020}your\u{0020}[Number\u{0020}One].", "0", "0", "0", "0", 12038, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[630000] = {630000, 0, "[Name]\u{0020}Odora\n[B-Day]\u{0020}May\u{0020}2\n[Compatability\u{0020}Rate]\u{0020}53％\n[Height]\u{0020}27m\n[Squad]\u{0020}Soul\u{0020}Destroyers\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Sleeping;\u{0020}Lulula's\u{0020}back", "0", "0", "0", "0", 13000, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}欧朵啦\n[B-Day]\u{1000}5月2日\n[幻化核心适格率]\u{1000}53％\n[Height]\u{1000}24m\n[部队]\u{1000}魂灭\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}睡觉\u{1000}露露啦的背"},
[630001] = {630001, 100, "\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}\"Soul\u{0020}Destroyer\",\u{0020}a\u{0020}genius\u{0020}girl,\u{0020}it\u{0020}is\u{0020}rumored\u{0020}that\u{0020}she\u{0020}sleeps\u{0020}for\u{0020}twenty\u{0020}hours\u{0020}a\u{0020}day.\n\nIt\u{0020}is\u{0020}said\u{0020}that\u{0020}she\u{0020}has\u{0020}intelligence\u{0020}and\u{0020}knowledge\u{0020}close\u{0020}to\u{0020}that\u{0020}of\u{0020}Dr.\u{0020}Stephanie,\u{0020}the\u{0020}chief\u{0020}scientist\u{0020}of\u{0020}AEGIS.\u{0020}Because\u{0020}she\u{0020}sleeps\u{0020}most\u{0020}of\u{0020}the\u{0020}time,\u{0020}this\u{0020}rumor\u{0020}cannot\u{0020}be\u{0020}confirmed.\n\nShe\u{0020}often\u{0020}appears\u{0020}with\u{0020}Lulula,\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Soul\u{0020}Destroyer.\u{0020}When\u{0020}people\u{0020}see\u{0020}her,\u{0020}Lulula\u{0020}is\u{0020}always\u{0020}by\u{0020}her\u{0020}side.\u{0020}According\u{0020}to\u{0020}insiders'\u{0020}revelations,\u{0020}even\u{0020}now\u{0020}after\u{0020}graduating\u{0020}from\u{0020}Azure\u{0020}Academy,\u{0020}she\u{0020}still\u{0020}cannot\u{0020}live\u{0020}independently\u{0020}and\u{0020}has\u{0020}a\u{0020}strange\u{0020}disorder\u{0020}called\u{0020}\"Life\u{0020}Disability\u{0020}Syndrome\".\n\n\"No\u{0020}matter\u{0020}what,\u{0020}it's\u{0020}just\u{0020}pure\u{0020}laziness...\"\u{0020}The\u{0020}person\u{0020}who\u{0020}tried\u{0020}to\u{0020}make\u{0020}the\u{0020}truth\u{0020}public\u{0020}was\u{0020}jointly\u{0020}and\u{0020}humanely\u{0020}destroyed\u{0020}(?)\u{0020}by\u{0020}Lulula\u{0020}and\u{0020}Kinkura.", "0", "0", "0", "0", 13000, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"魂灭\"的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{1000}\u{1000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{1000}\u{1000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着\"生活障碍症\"这一奇怪病症。\n\u{1000}\u{1000}\"不……无论怎么看，都只是纯粹的懒惰而已吧……\"尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[630002] = {630002, 500, "\u{0020}\u{0020}As\u{0020}a\u{0020}new\u{0020}generation\u{0020}born\u{0020}after\u{0020}Sin's\u{0020}full-scale\u{0020}invasion,\u{0020}Odora\u{0020}showed\u{0020}her\u{0020}talent\u{0020}at\u{0020}a\u{0020}very\u{0020}young\u{0020}age.\u{0020}Those\u{0020}tasks\u{0020}that\u{0020}were\u{0020}even\u{0020}considered\u{0020}difficult\u{0020}for\u{0020}adults,\u{0020}Odora\u{0020}could\u{0020}complete\u{0020}alone\u{0020}relying\u{0020}on\u{0020}the\u{0020}knowledge\u{0020}from\u{0020}books.\n\nThe\u{0020}exceptionally\u{0020}talented\u{0020}Odora\u{0020}was\u{0020}soon\u{0020}noticed\u{0020}by\u{0020}Stephanie,\u{0020}the\u{0020}chief\u{0020}scientist\u{0020}of\u{0020}AEGIS.\u{0020}AEGIS\u{0020}proved\u{0020}through\u{0020}tests\u{0020}that\u{0020}Odora's\u{0020}talent\u{0020}was\u{0020}not\u{0020}the\u{0020}result\u{0020}of\u{0020}media\u{0020}hype\u{0020}but\u{0020}genuine\u{0020}ability.\n\nIn\u{0020}order\u{0020}not\u{0020}to\u{0020}let\u{0020}this\u{0020}talent\u{0020}be\u{0020}buried\u{0020}and\u{0020}to\u{0020}allow\u{0020}this\u{0020}talent\u{0020}to\u{0020}have\u{0020}a\u{0020}more\u{0020}sufficient\u{0020}space\u{0020}to\u{0020}exert\u{0020}itself,\u{0020}AEGIS\u{0020}let\u{0020}Odora\u{0020}enter\u{0020}the\u{0020}Azure\u{0020}Academy\u{0020}for\u{0020}nurturing\u{0020}talents.\n\nAEGIS\u{0020}may\u{0020}be\u{0020}right.\u{0020}Odora\u{0020}absorbs\u{0020}academic\u{0020}knowledge\u{0020}and\u{0020}tactical\u{0020}theory\u{0020}much\u{0020}faster\u{0020}than\u{0020}people\u{0020}imagine.\u{0020}Three\u{0020}months\u{0020}after\u{0020}she\u{0020}joined\u{0020}Azure\u{0020}Academy,\u{0020}her\u{0020}practical\u{0020}application\u{0020}of\u{0020}battlefield\u{0020}judgment\u{0020}and\u{0020}tactics\u{0020}has\u{0020}gone\u{0020}beyond\u{0020}the\u{0020}scope\u{0020}of\u{0020}students.In\u{0020}a\u{0020}simulation\u{0020}battle\u{0020}with\u{0020}graduates,\u{0020}she\u{0020}achieved\u{0020}an\u{0020}overwhelming\u{0020}advantage\u{0020}and\u{0020}was\u{0020}awarded\u{0020}the\u{0020}encouraging\u{0020}medal\u{0020}of\u{0020}\"Flower\u{0020}of\u{0020}Tomorrow\".\n\nUnfortunately,\u{0020}in\u{0020}terms\u{0020}of\u{0020}the\u{0020}Compatability\u{0020}Rate,\u{0020}which\u{0020}is\u{0020}the\u{0020}most\u{0020}important\u{0020}for\u{0020}the\u{0020}driver,\u{0020}Odora's\u{0020}figure\u{0020}is\u{0020}not\u{0020}ideal,\u{0020}which\u{0020}makes\u{0020}her\u{0020}unable\u{0020}to\u{0020}become\u{0020}a\u{0020}front-line\u{0020}warrior.\n\nIn\u{0020}addition,\u{0020}AEGIS's\u{0020}behavior\u{0020}also\u{0020}exposed\u{0020}another\u{0020}weakness\u{0020}for\u{0020}Odora\u{0020}-\u{0020}she\u{0020}couldn't\u{0020}live\u{0020}independently.\u{0020}She\u{0020}didn't\u{0020}know\u{0020}how\u{0020}to\u{0020}eat\u{0020}alone,\u{0020}or\u{0020}even\u{0020}dress.\u{0020}Her\u{0020}daily\u{0020}life\u{0020}was\u{0020}taken\u{0020}care\u{0020}of\u{0020}by\u{0020}her\u{0020}then\u{0020}roommate,\u{0020}Lulula.\n\nHowever,\u{0020}it\u{0020}was\u{0020}precisely\u{0020}because\u{0020}of\u{0020}her\u{0020}weakness\u{0020}that\u{0020}she\u{0020}formed\u{0020}a\u{0020}deep\u{0020}bond\u{0020}with\u{0020}Lulula.\u{0020}The\u{0020}embryonic\u{0020}form\u{0020}of\u{0020}the\u{0020}future\u{0020}elite\u{0020}squad\u{0020}\"Soul\u{0020}Destroyers\"\u{0020}also\u{0020}began\u{0020}at\u{0020}that\u{0020}time.\n\nAfter\u{0020}Lulula\u{0020}graduated,\u{0020}considering\u{0020}Odora's\u{0020}situation,\u{0020}AEGIS\u{0020}made\u{0020}an\u{0020}exception\u{0020}and\u{0020}allowed\u{0020}Odora\u{0020}to\u{0020}leave\u{0020}the\u{0020}academy\u{0020}early\u{0020}to\u{0020}become\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}team\u{0020}\"Soul\u{0020}Destroyers\"\u{0020}belonging\u{0020}to\u{0020}Lulula.", "0", "0", "0", "0", 13000, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{1000}\u{1000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{1000}\u{1000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{1000}\u{1000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了\"明日之花\"的鼓励性质奖章。\n\u{1000}\u{1000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{1000}\u{1000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{1000}\u{1000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队\"魂灭\"的雏形，也是从那个时候开始的。\n\u{1000}\u{1000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队\"魂灭\"的一员。"},
[630003] = {630003, 1000, "\u{0020}Odora's\u{0020}reclusive\u{0020}lifestyle\u{0020}intensified\u{0020}after\u{0020}she\u{0020}entered\u{0020}the\u{0020}AEGIS\u{0020}Kyushu\u{0020}Headquarters.\n\nPerhaps\u{0020}it\u{0020}was\u{0020}the\u{0020}change\u{0020}of\u{0020}environment\u{0020}that\u{0020}made\u{0020}her\u{0020}feel\u{0020}uneasy.\u{0020}After\u{0020}moving\u{0020}into\u{0020}the\u{0020}Kyushu\u{0020}Headquarters,\u{0020}the\u{0020}number\u{0020}of\u{0020}times\u{0020}she\u{0020}went\u{0020}out\u{0020}became\u{0020}even\u{0020}less.\u{0020}Therefore,\u{0020}although\u{0020}the\u{0020}people\u{0020}at\u{0020}the\u{0020}Kyushu\u{0020}Headquarters\u{0020}knew\u{0020}that\u{0020}there\u{0020}was\u{0020}a\u{0020}third\u{0020}person\u{0020}in\u{0020}the\u{0020}Soul\u{0020}Destroyer\u{0020}besides\u{0020}Lulula\u{0020}and\u{0020}Kinkura,\u{0020}few\u{0020}people\u{0020}had\u{0020}seen\u{0020}her\u{0020}in\u{0020}person.\n\n\"There\u{0020}was\u{0020}a\u{0020}ghost\u{0020}member\u{0020}in\u{0020}the\u{0020}'Soul\u{0020}Destroyer'.\"\u{0020}Such\u{0020}a\u{0020}rumor\u{0020}gradually\u{0020}spread\u{0020}among\u{0020}the\u{0020}Kyushu\u{0020}Headquarters.\u{0020}After\u{0020}Lulula's\u{0020}preaching,\u{0020}Odora\u{0020}increased\u{0020}the\u{0020}number\u{0020}of\u{0020}her\u{0020}outings.\n\nNow\u{0020}the\u{0020}truth\u{0020}has\u{0020}finally\u{0020}come\u{0020}to\u{0020}light.\u{0020}The\u{0020}reason\u{0020}for\u{0020}her\u{0020}reclusive\u{0020}lifestyle\u{0020}is\u{0020}not\u{0020}shyness\u{0020}but\u{0020}a\u{0020}more\u{0020}simple\u{0020}one.\n\n\"May\u{0020}I\u{0020}go\u{0020}to\u{0020}sleep?\"\n\nYes,\u{0020}she\u{0020}is\u{0020}just\u{0020}lazy.", "0", "0", "0", "0", 13000, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{1000}\u{1000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{1000}\u{1000}\"魂灭小队中存在着一个幽灵队员——\"渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{1000}\u{1000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{1000}\u{1000}\"——我可以去睡觉了吗？呜……\"\n\u{1000}\u{1000}——是的，她只是懒而已。"},
[630004] = {630004, 2000, "\u{0020}\u{0020}The\u{0020}battle\u{0020}was\u{0020}going\u{0020}on\u{0020}as\u{0020}she\u{0020}had\u{0020}deduced,\n\nSin's\u{0020}actions\u{0020}had\u{0020}been\u{0020}seen\u{0020}through\u{0020}by\u{0020}her\u{0020}long\u{0020}before\u{0020}the\u{0020}war\u{0020}began,\n\nAfter\u{0020}telling\u{0020}the\u{0020}way\u{0020}to\u{0020}solve\u{0020}the\u{0020}problem,\n\nshe\u{0020}lay\u{0020}in\u{0020}the\u{0020}hills,\u{0020}sleeping\u{0020}quietly,\u{0020}talking\u{0020}in\u{0020}a\u{0020}childlike\u{0020}dream,\n\n\"Phew...\u{0020}Phew...\"\n\n\"Lulula...\"\n\n\"Navigator...\"\n\n\"I\u{0020}like\u{0020}Navigator...\"\n\n\"I\u{0020}like\u{0020}Navigator\u{0020}the\u{0020}most...\"", "0", "0", "0", "0", 13000, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}作战如她所推演的那样进行着，\n\u{1000}\u{1000}原罪的行动早在战争开始前就被她看穿，\n\u{1000}\u{1000}将破局的方法说出之后，\n\u{1000}\u{1000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{1000}\u{1000}\"呼……呼……呼……\"\n\u{1000}\u{1000}\"露露啦……\"\n\u{1000}\u{1000}\"领航……\"\n\u{1000}\u{1000}\"喜欢……\"\n\u{1000}\u{1000}\"最喜欢了……\""},
[630100] = {630100, 0, "[Name]\u{0020}Franca\u{0020}Vinci\n[B-Day]\u{0020}May\u{0020}17\n[Compatability\u{0020}Rate]\u{0020}<color=#FF6100>100％</color>\n[Height]\u{0020}35m\n[Squad]\u{0020}Danube\u{0020}Special\u{0020}Combined\u{0020}Unit\n[Affiliation]\u{0020}Stephanie/Danube\u{0020}Branch\n[Interest]\u{0020}Online\u{0020}Mahjong,\u{0020}Chess,\u{0020}Poker,\u{0020}Go", "0", "0", "0", "0", 13001, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}弗兰卡·芬奇\n[B-Day]\u{1000}5月17日\n[幻化核心适格率]\u{1000}<color=#FF6100>100％</color>\n[Height]\u{1000}35m\n[部队]\u{1000}多瑙特别联合部队\u{1000}\u{1000}[隶属]\u{1000}Stephanie/Danube\u{1000}Branch\n[Interest]\u{1000}会一个人打在线进行的麻将、国际象棋、扑克牌、围棋——这样会让她很安心"},
[630101] = {630101, 100, "\u{0020}\u{0020}She's\u{0020}an\u{0020}excellent\u{0020}newcomer\u{0020}with\u{0020}modesty\u{0020}and\u{0020}endeavor.\n\nFor\u{0020}her\u{0020}seniors,\u{0020}Julius\u{0020}and\u{0020}Charlissa,\u{0020}she\u{0020}expresses\u{0020}a\u{0020}great\u{0020}amount\u{0020}of\u{0020}yearning\u{0020}and\u{0020}modesty.\u{0020}She\u{0020}always\u{0020}views\u{0020}becoming\u{0020}them\u{0020}as\u{0020}her\u{0020}goal.\n\nAnd\u{0020}perhaps\u{0020}because\u{0020}of\u{0020}that,\u{0020}when\u{0020}she's\u{0020}present,\u{0020}Julius\u{0020}and\u{0020}Charlissa\u{0020}will\u{0020}avoid\u{0020}quarreling.\n\n\"We\u{0020}can't\u{0020}let\u{0020}the\u{0020}newcomers\u{0020}have\u{0020}a\u{0020}horrible\u{0020}impression,\u{0020}that\u{0020}AEGIS\u{0020}is\u{0020}in\u{0020}fact\u{0020}an\u{0020}organization\u{0020}full\u{0020}of\u{0020}infighting.\"\u{0020}Charlissa,\u{0020}that\u{0020}intractable\u{0020}girl\u{0020}said.\n\nOn\u{0020}her\u{0020}off-duty\u{0020}times,\u{0020}she\u{0020}makes\u{0020}some\u{0020}handcrafts\u{0020}and\u{0020}puts\u{0020}them\u{0020}in\u{0020}her\u{0020}room\u{0020}as\u{0020}decorations.\u{0020}Also,\u{0020}she's\u{0020}good\u{0020}at\u{0020}cooking\u{0020}and\u{0020}gardening.\u{0020}She\u{0020}seeks\u{0020}\"the\u{0020}sense\u{0020}of\u{0020}life\"\u{0020}even\u{0020}in\u{0020}tough\u{0020}conditions.\u{0020}In\u{0020}battles\u{0020}she\u{0020}mainly\u{0020}does\u{0020}supporting\u{0020}jobs,\u{0020}and\u{0020}almost\u{0020}never\u{0020}fights\u{0020}directly\u{0020}with\u{0020}enemies.\n\nBut\u{0020}that\u{0020}doesn't\u{0020}mean\u{0020}she's\u{0020}timid.\u{0020}On\u{0020}the\u{0020}contrary,\u{0020}she\u{0020}is\u{0020}more\u{0020}willing\u{0020}to\u{0020}save\u{0020}her\u{0020}partners,\u{0020}civilians\u{0020}and\u{0020}their\u{0020}peaceful\u{0020}lives\u{0020}compared\u{0020}to\u{0020}her\u{0020}squadmates.\u{0020}She\u{0020}is\u{0020}always\u{0020}the\u{0020}first\u{0020}to\u{0020}go\u{0020}as\u{0020}a\u{0020}rescuer\u{0020}during\u{0020}battles,\u{0020}and\u{0020}she\u{0020}won't\u{0020}flinch\u{0020}even\u{0020}when\u{0020}facing\u{0020}enemies\u{0020}that\u{0020}are\u{0020}much\u{0020}more\u{0020}powerful\u{0020}than\u{0020}herself.", "0", "0", "0", "0", 13001, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}谦虚有礼同时富有进取心的优秀新人。\n\u{1000}\u{1000}面对身为自己前辈的查丽莎与朱利乌斯表现出极大的憧憬与谦逊，总是以她们两为目标而努力。\n\u{1000}\u{1000}也许正是因为这些原因吧，只要有她在的场合，朱利乌斯和查丽莎都会尽量避免发生争吵。\n\u{1000}\u{1000}\"绝对不能给新人留下艾吉斯原来是这种充满内讧的组织的糟糕印象啊。\"那个桀骜不驯的查丽莎曾经这么说过。\n\u{1000}\u{1000}闲暇时光则会抽空做些手工放在宿舍中作为装饰，同时也非常擅长料理与园艺。是一名哪怕在艰苦的环境中也不忘追寻\"生活气息\"的少女。在战斗中则主要负责援助工作，很少参与正面战斗。\n\u{1000}\u{1000}但是这并不意味着她是个胆小的女孩。相反她比另外两位队员更加迫切地想要守护同伴、平民以及属于她们的平和日常。战斗时冲在救援第一线的总是她，甚至在面对比自己强大得多的敌人时也不会退缩。"},
[630102] = {630102, 500, "\u{0020}\u{0020}In\u{0020}a\u{0020}seaside\u{0020}town\u{0020}which\u{0020}was\u{0020}not\u{0020}yet\u{0020}affected\u{0020}by\u{0020}the\u{0020}war,\u{0020}a\u{0020}couple\u{0020}managing\u{0020}a\u{0020}restaurant\u{0020}raised\u{0020}3\u{0020}children.\u{0020}Their\u{0020}eldest\u{0020}daughter\u{0020}was\u{0020}named\u{0020}Franca\u{0020}Finch.\n\nNormally,\u{0020}other\u{0020}than\u{0020}going\u{0020}to\u{0020}school\u{0020}for\u{0020}education,\u{0020}she\u{0020}also\u{0020}had\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}her\u{0020}younger\u{0020}siblings.\u{0020}Her\u{0020}family\u{0020}wasn't\u{0020}rich\u{0020}and\u{0020}was\u{0020}having\u{0020}too\u{0020}many\u{0020}people\u{0020}so\u{0020}she\u{0020}couldn't\u{0020}have\u{0020}a\u{0020}lot\u{0020}of\u{0020}new\u{0020}clothes\u{0020}like\u{0020}her\u{0020}schoolmates.\u{0020}However,\u{0020}she\u{0020}didn't\u{0020}mind,\u{0020}as\u{0020}a\u{0020}girl\u{0020}good\u{0020}at\u{0020}handcrafting,\u{0020}she\u{0020}made\u{0020}pretty\u{0020}and\u{0020}cozy\u{0020}clothes\u{0020}for\u{0020}her\u{0020}family,\u{0020}and\u{0020}her\u{0020}talent\u{0020}in\u{0020}cooking\u{0020}means\u{0020}she\u{0020}could\u{0020}turn\u{0020}simple\u{0020}food\u{0020}into\u{0020}delicious\u{0020}cuisines.\u{0020}She\u{0020}was\u{0020}never\u{0020}ostentatious\u{0020}about\u{0020}her\u{0020}skills,\u{0020}so\u{0020}she\u{0020}had\u{0020}good\u{0020}relationships\u{0020}with\u{0020}her\u{0020}schoolmates.\n\nFor\u{0020}her,\u{0020}living\u{0020}a\u{0020}healthy\u{0020}life\u{0020}together\u{0020}with\u{0020}her\u{0020}family\u{0020}and\u{0020}friends\u{0020}was\u{0020}her\u{0020}utmost\u{0020}happiness,\u{0020}and\u{0020}Sins\u{0020}are\u{0020}things\u{0020}far\u{0020}away\u{0020}from\u{0020}her.\n\nWell,\u{0020}that\u{0020}thought\u{0020}didn't\u{0020}last\u{0020}for\u{0020}long.\u{0020}One\u{0020}day,\u{0020}the\u{0020}girl's\u{0020}best\u{0020}friend\u{0020}didn't\u{0020}go\u{0020}to\u{0020}school,\u{0020}and\u{0020}her\u{0020}teacher\u{0020}didn't\u{0020}say\u{0020}anything\u{0020}about\u{0020}it.\u{0020}So,\u{0020}she\u{0020}was\u{0020}trying\u{0020}to\u{0020}find\u{0020}her\u{0020}friend\u{0020}that\u{0020}didn't\u{0020}come\u{0020}to\u{0020}school.\u{0020}Did\u{0020}she\u{0020}move\u{0020}to\u{0020}another\u{0020}place\u{0020}and\u{0020}go\u{0020}to\u{0020}another\u{0020}school?\u{0020}Or\u{0020}was\u{0020}she\u{0020}hospitalized\u{0020}because\u{0020}of\u{0020}an\u{0020}accident?\u{0020}Or…finally,\u{0020}Franca\u{0020}got\u{0020}the\u{0020}answer.\n\nIt\u{0020}was\u{0020}Sins,\u{0020}that\u{0020}destroyed\u{0020}her\u{0020}friend's\u{0020}hometown.\u{0020}As\u{0020}a\u{0020}result,\u{0020}that\u{0020}friend\u{0020}finished\u{0020}the\u{0020}procedures\u{0020}of\u{0020}quitting\u{0020}school,\u{0020}and\u{0020}joined\u{0020}an\u{0020}organization\u{0020}called\u{0020}Aegis.\n\nAt\u{0020}that\u{0020}moment,\u{0020}Franca\u{0020}felt\u{0020}scared.\u{0020}Everytime\u{0020}when\u{0020}she\u{0020}stood\u{0020}at\u{0020}the\u{0020}dock\u{0020}and\u{0020}looked\u{0020}far\u{0020}away,\u{0020}she\u{0020}couldn't\u{0020}hold\u{0020}her\u{0020}imagination\u{0020}that\u{0020}put\u{0020}herself\u{0020}into\u{0020}that\u{0020}friend's\u{0020}point\u{0020}of\u{0020}view.\u{0020}Maybe\u{0020}in\u{0020}the\u{0020}near\u{0020}future,\u{0020}the\u{0020}war\u{0020}will\u{0020}be\u{0020}here\u{0020}as\u{0020}well…no,\u{0020}if\u{0020}we\u{0020}keep\u{0020}lying\u{0020}around,\u{0020}more\u{0020}and\u{0020}more\u{0020}people\u{0020}will\u{0020}lose\u{0020}their\u{0020}little\u{0020}and\u{0020}simple\u{0020}happiness,\u{0020}forever.\n\nTo\u{0020}prevent\u{0020}that\u{0020}from\u{0020}happening,\u{0020}after\u{0020}she\u{0020}talked\u{0020}with\u{0020}her\u{0020}family,\u{0020}she\u{0020}also\u{0020}participated\u{0020}in\u{0020}the\u{0020}Compatability\u{0020}Rate\u{0020}test\u{0020}hosted\u{0020}by\u{0020}Aegis.\u{0020}After\u{0020}that\u{0020}she\u{0020}was\u{0020}chosen\u{0020}by\u{0020}Stephanie\u{0020}because\u{0020}of\u{0020}her\u{0020}superior\u{0020}Proficiency,\u{0020}and\u{0020}joined\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force.\n\nOthers\u{0020}may\u{0020}think\u{0020}that\u{0020}she\u{0020}wants\u{0020}to\u{0020}improve\u{0020}her\u{0020}family's\u{0020}economic\u{0020}status,\u{0020}or\u{0020}wants\u{0020}revenge\u{0020}for\u{0020}her\u{0020}friend\u{0020}in\u{0020}this\u{0020}way.\u{0020}But\u{0020}actually,\u{0020}she\u{0020}just\u{0020}wants\u{0020}to\u{0020}save\u{0020}our\u{0020}peaceful\u{0020}life\u{0020}for\u{0020}our\u{0020}future.", "0", "0", "0", "0", 13001, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}在尚且没有被战火侵蚀的海边小城中，有一对开餐馆的夫妻养育了3名儿女。其中长女的名字便是弗兰卡·芬奇。\n\u{1000}\u{1000}平日里除了要去学校接受教育外弗兰卡也要帮着父母照顾弟弟妹妹，并不富裕的家庭加上过多的人口让她自然无法像其他同学那样购买很多新衣服。但是这对她而言都不算什么，善于手工的她会为家人们制作漂亮合身的衣服，而料理天赋也使她可以把最便宜的食材化为山珍海味。同时她也从不以此炫耀，所以她在学校的人缘也还算不错。\n\u{1000}\u{1000}对那时的她而言，每天能和家人与朋友们健康地生活在一起就是最幸福的事情了，而原罪只不过是离她很遥远的事物而已。\n\u{1000}\u{1000}当然，这样的想法并没有维持多久。某一天，少女最好的朋友突然没有来学校，而老师也没有多说什么。于是，她开始不停地寻找那位没有来学校的朋友。是搬家转校了吗？是因为意外而住院了吗？还是因为……直到最后，少女得到了答案。\n\u{1000}\u{1000}是原罪，原罪将朋友的故乡化为灰烬，而那位朋友也因此而办理了退学手续，加入了名为艾吉斯的组织。\n\u{1000}\u{1000}那一刻，弗兰卡感到了恐惧。每当伫立在码头看向远方时总会忍不住想象，忍不住将自己代入那位友人的视角。也许在不久之后，战火也会蔓延至此吧……不，如果现在不做些什么的话，终有一日更多的人将会永远地失去这最低规格的，小小的幸福吧。\n\u{1000}\u{1000}所以为了防止这一天的到来，在与家人交流过后，她也报名参加了艾吉斯举行的适格测试。而之后又因为其极高的适格率与优异的表现而被史蒂芬妮选中，加入了多瑙特别联合部队。\n\u{1000}\u{1000}在外人看来，她似乎是想要通过这种方式来改善家境，或者说是为了帮助友人复仇。但是实际上，她只是为了守护住未来平和的日常而已。"},
[630103] = {630103, 1000, "\u{0020}\u{0020}With\u{0020}trepidation\u{0020}about\u{0020}the\u{0020}future\u{0020}and\u{0020}yearning\u{0020}for\u{0020}power,\u{0020}Franca\u{0020}joined\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force.\u{0020}And\u{0020}because\u{0020}of\u{0020}this\u{0020}opportunity,\u{0020}she\u{0020}met\u{0020}the\u{0020}navigator\u{0020}who\u{0020}also\u{0020}wants\u{0020}to\u{0020}protect\u{0020}\"something\",\u{0020}and\u{0020}two\u{0020}excellent\u{0020}seniors.\n\n\"Just\u{0020}because\u{0020}we\u{0020}have\u{0020}people\u{0020}like\u{0020}Franca,\u{0020}who\u{0020}love\u{0020}their\u{0020}lives,\u{0020}we\u{0020}have\u{0020}the\u{0020}reason\u{0020}to\u{0020}continue\u{0020}our\u{0020}fight.\"\u{0020}This\u{0020}is\u{0020}a\u{0020}consensus\u{0020}in\u{0020}the\u{0020}squad.\u{0020}Franca,\u{0020}the\u{0020}seemingly\u{0020}least\u{0020}mature\u{0020}member,\u{0020}already\u{0020}became\u{0020}what\u{0020}they\u{0020}are\u{0020}fighting\u{0020}for.\u{0020}And\u{0020}for\u{0020}Franca\u{0020}herself,\u{0020}consequently,\u{0020}she\u{0020}has\u{0020}one\u{0020}more\u{0020}\"life\"\u{0020}that\u{0020}she\u{0020}wants\u{0020}to\u{0020}save.\n\nPerhaps,\u{0020}in\u{0020}the\u{0020}near\u{0020}future,\u{0020}although\u{0020}the\u{0020}war\u{0020}is\u{0020}not\u{0020}finished\u{0020}yet,\u{0020}when\u{0020}she's\u{0020}mature\u{0020}enough,\u{0020}her\u{0020}trepidation\u{0020}will\u{0020}vanish\u{0020}gradually.\u{0020}Instead,\u{0020}she\u{0020}will\u{0020}have\u{0020}her\u{0020}mind,\u{0020}her\u{0020}feeling\u{0020}and\u{0020}her\u{0020}hope\u{0020}towards\u{0020}\"that\u{0020}person\".", "0", "0", "0", "0", 13001, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}怀揣着对未来的不安与对力量的憧憬，弗兰卡加入了多瑙特别联合部队，正是借此机会她认识了同样想要守护\"某物\"的领航以及两位出色的前辈。\n\u{1000}\u{1000}\"正是因为有弗兰卡这样热爱生活的人存在，所以我们才有继续战斗的必要啊。\"这是团队里的一致看法，看似最不成熟的弗兰卡实际上在不知不觉中已经成为了大家行动目的的缩影。而对于弗兰卡来说自己想要守护的日常也理所应当地多了一份。\n\u{1000}\u{1000}或许在不久的将来，即便是战争尚未结束，但是当她足够成熟的时候那份心中的不安也会慢慢消散。取而代之的，则是对那个人的心意，对那个人的情感，以及对那个人的憧憬。"},
[630104] = {630104, 2000, "\u{0020}\u{0020}On\u{0020}the\u{0020}dock's\u{0020}beach\u{0020}of\u{0020}her\u{0020}hometown.\n\nThe\u{0020}giant\u{0020}girl\u{0020}is\u{0020}holding\u{0020}that\u{0020}little\u{0020}navigator\u{0020}in\u{0020}her\u{0020}palms.\n\nThe\u{0020}girl,\u{0020}who\u{0020}was\u{0020}always\u{0020}afraid\u{0020}of\u{0020}looking\u{0020}into\u{0020}the\u{0020}distance,\n\nis\u{0020}watching\u{0020}that\u{0020}setting\u{0020}sun\u{0020}with\u{0020}a\u{0020}smile.\n\n\"Today,\u{0020}I\u{0020}will\u{0020}no\u{0020}longer\u{0020}be\u{0020}afraid,\u{0020}no\u{0020}matter\u{0020}what\u{0020}appears\u{0020}on\u{0020}the\u{0020}horizon.\"\n\nAnd\u{0020}that's\u{0020}not\u{0020}only\u{0020}because\u{0020}of\u{0020}her\u{0020}giant\u{0020}body,\u{0020}but\u{0020}also…\n\nBecause\u{0020}of\u{0020}that\u{0020}little\u{0020}sense\u{0020}of\u{0020}dependency,\u{0020}holding\u{0020}in\u{0020}her\u{0020}hands.", "0", "0", "0", "0", 13001, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}在故乡的码头沙滩上。\n\u{1000}\u{1000}巨大的少女手捧着小小的领航。\n\u{1000}\u{1000}一直以来都不敢眺望远处的女孩啊，现如今却微笑着看向那缓缓下沉的太阳。\n\u{1000}\u{1000}\"今天，无论海的另一头出现什么我都不会再感到害怕了。\"\n\u{1000}\u{1000}这倒不光光是因为巨大的身型，而是因为……\n\u{1000}\u{1000}那在手心中的，小小的依靠。"},
[630200] = {630200, 0, "[Name]\u{0020}Tina\u{0020}Eisen\n[B-Day]\u{0020}Jan\u{0020}24\n[Compatability\u{0020}Rate]\u{0020}71％\n[Height]\u{0020}37m\n[Squad]\u{0020}Cavalier\n[Affiliation]\u{0020}Cavalier[Interest]\u{0020}Organize\u{0020}and\u{0020}educate\u{0020}people", "0", "0", "0", "0", 13002, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}蒂娜·爱森\n[B-Day]\u{1000}1月24日\n[幻化核心适格率]\u{1000}71％\n[Height]\u{1000}39m\n[部队]\u{1000}猎骑\n[隶属]\u{1000}玛雅\n[Interest]\u{1000}整理与育人"},
[630201] = {630201, 100, "\u{0020}\u{0020}She\u{0020}used\u{0020}her\u{0020}words\u{0020}and\u{0020}deeds\u{0020}to\u{0020}interpret\u{0020}what\u{0020}is\u{0020}a\u{0020}\"perfect\"\u{0020}maid.\n\nTina\u{0020}is\u{0020}fulfilling\u{0020}her\u{0020}duty\u{0020}as\u{0020}a\u{0020}maid\u{0020}all\u{0020}the\u{0020}time\u{0020}-\u{0020}being\u{0020}loyal\u{0020}to\u{0020}the\u{0020}\"Cretia\"\u{0020}family,\u{0020}always\u{0020}staying\u{0020}by\u{0020}the\u{0020}side\u{0020}of\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}and\u{0020}guarding\u{0020}the\u{0020}growth\u{0020}of\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies.\n\nWhile\u{0020}she\u{0020}was\u{0020}responsible\u{0020}for\u{0020}the\u{0020}daily\u{0020}life\u{0020}of\u{0020}Alice\u{0020}Cretia\u{0020}and\u{0020}Gin\u{0020}Cretia,\u{0020}she\u{0020}also\u{0020}shouldered\u{0020}the\u{0020}responsibility\u{0020}of\u{0020}educating\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies.\u{0020}Although\u{0020}sometimes\u{0020}her\u{0020}education\u{0020}was\u{0020}so\u{0020}severe\u{0020}that\u{0020}it\u{0020}made\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}miserable.\n\nHowever,\u{0020}she\u{0020}did\u{0020}not\u{0020}rigidly\u{0020}educate\u{0020}the\u{0020}two\u{0020}ladies\u{0020}in\u{0020}the\u{0020}same\u{0020}way.\u{0020}The\u{0020}maid\u{0020}deliberately\u{0020}separated\u{0020}the\u{0020}two\u{0020}ladies\u{0020}in\u{0020}life\u{0020}and\u{0020}education.\u{0020}For\u{0020}Gin's\u{0020}education,\u{0020}it\u{0020}was\u{0020}more\u{0020}about\u{0020}cognition\u{0020}and\u{0020}trust,\u{0020}and\u{0020}for\u{0020}Alice,\u{0020}it\u{0020}was\u{0020}about\u{0020}the\u{0020}transmission\u{0020}of\u{0020}responsibility\u{0020}and\u{0020}wisdom.\n\nEveryone\u{0020}has\u{0020}different\u{0020}experiences\u{0020}and\u{0020}talents,\u{0020}and\u{0020}this\u{0020}world\u{0020}also\u{0020}needs\u{0020}all\u{0020}kinds\u{0020}of\u{0020}people.\u{0020}That's\u{0020}why\u{0020}I\u{0020}treat\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}differently\u{0020}and\u{0020}lead\u{0020}them\u{0020}to\u{0020}their\u{0020}respective\u{0020}paths.", "0", "0", "0", "0", 13002, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}她用自己的言行举止去诠释了何为\"完美\"的女仆。\n\u{1000}\u{1000}蒂娜时时刻刻都在履行自己身为女仆的职责——忠于\"克雷蒂亚\"家族，始终陪伴在克雷蒂亚家族的两位大小姐身边，守护着两位小姐的成长。\n\u{1000}\u{1000}她在负责照顾爱丽丝·克雷蒂亚与静·克雷蒂亚两位大小姐的起居时，还肩负着教育两位小姐的职责。尽管有些时候她的教育会过于严厉，以至于让两位小姐叫苦不堪。\n\u{1000}\u{1000}不过，她也并不是死板地用同一种方式教育两位小姐。女仆在生活和教育上有意将俩位小姐分开，对于静的教育更多的是认知和信任，对于爱丽丝则是责任和智慧的传输。\n\u{1000}\u{1000}\"每个人都有不同的经历和天赋，而这个世界也需要各种各样的人。所以我才会区别对待两位小姐，将她们引向各自的路。\""},
[630202] = {630202, 500, "\u{0020}\u{0020}The\u{0020}family\u{0020}of\u{0020}Tina\u{0020}Eisen\u{0020}has\u{0020}been\u{0020}professional\u{0020}servants\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}for\u{0020}generations,\u{0020}with\u{0020}a\u{0020}history\u{0020}of\u{0020}nearly\u{0020}two\u{0020}hundred\u{0020}years.\u{0020}Every\u{0020}time\u{0020}on\u{0020}the\u{0020}day\u{0020}when\u{0020}a\u{0020}Cretia\u{0020}successor\u{0020}is\u{0020}born,\u{0020}the\u{0020}Eisen\u{0020}family\u{0020}selects\u{0020}the\u{0020}head\u{0020}maid\u{0020}to\u{0020}train\u{0020}and\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}next-generation\u{0020}successor.\n\nShe\u{0020}had\u{0020}been\u{0020}preparing\u{0020}for\u{0020}this\u{0020}inevitable\u{0020}day\u{0020}for\u{0020}a\u{0020}full\u{0020}nine\u{0020}years.\u{0020}When\u{0020}other\u{0020}peers\u{0020}were\u{0020}still\u{0020}at\u{0020}an\u{0020}age\u{0020}to\u{0020}act\u{0020}spoiled\u{0020}to\u{0020}their\u{0020}parents,\u{0020}she\u{0020}had\u{0020}already\u{0020}become\u{0020}an\u{0020}outstanding\u{0020}servant\u{0020}who\u{0020}mastered\u{0020}all\u{0020}the\u{0020}skills\u{0020}of\u{0020}a\u{0020}maid.\u{0020}Exactly\u{0020}at\u{0020}the\u{0020}age\u{0020}of\u{0020}nine,\u{0020}the\u{0020}first\u{0020}young\u{0020}lady\u{0020}of\u{0020}Cretia,\u{0020}Alice·Cretia,\u{0020}was\u{0020}born.\n\nTina\u{0020}Eisen\u{0020}taught\u{0020}Alice\u{0020}the\u{0020}manners\u{0020}and\u{0020}etiquette\u{0020}that\u{0020}a\u{0020}young\u{0020}lady\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}should\u{0020}have\u{0020}and\u{0020}taught\u{0020}her\u{0020}to\u{0020}distinguish\u{0020}between\u{0020}wrong\u{0020}and\u{0020}right\u{0020}things.\u{0020}For\u{0020}the\u{0020}young\u{0020}lady,\u{0020}Tina\u{0020}was\u{0020}both\u{0020}a\u{0020}teacher\u{0020}who\u{0020}taught\u{0020}her\u{0020}life\u{0020}knowledge\u{0020}and\u{0020}a\u{0020}sister\u{0020}who\u{0020}protected\u{0020}her.\n\nThe\u{0020}second\u{0020}eldest\u{0020}young\u{0020}lady\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}Gin·Cretia,\u{0020}inserted\u{0020}a\u{0020}restless\u{0020}interlude\u{0020}into\u{0020}Tina\u{0020}Eisen's\u{0020}maid\u{0020}career\u{0020}.\u{0020}When\u{0020}Tina\u{0020}was\u{0020}sixteen\u{0020}years\u{0020}old,\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}adopted\u{0020}an\u{0020}orphan\u{0020}from\u{0020}the\u{0020}battlefield\u{0020}as\u{0020}the\u{0020}second\u{0020}daughter\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family.\n\nGin\u{0020}is\u{0020}different\u{0020}from\u{0020}Alice.\n\nDuring\u{0020}the\u{0020}day,\u{0020}Gin\u{0020}is\u{0020}always\u{0020}sleeping.\u{0020}At\u{0020}night,\u{0020}she\u{0020}becomes\u{0020}energetic\u{0020}again,\u{0020}as\u{0020}if\u{0020}she\u{0020}has\u{0020}endless\u{0020}energy.\u{0020}Because\u{0020}her\u{0020}schedule\u{0020}is\u{0020}inconsistent\u{0020}with\u{0020}that\u{0020}of\u{0020}normal\u{0020}people,\u{0020}she\u{0020}is\u{0020}always\u{0020}sleepy\u{0020}in\u{0020}class.\u{0020}Her\u{0020}academic\u{0020}performance\u{0020}has\u{0020}thus\u{0020}declined,\u{0020}and\u{0020}she\u{0020}has\u{0020}gradually\u{0020}lost\u{0020}interest\u{0020}in\u{0020}learning.\u{0020}Compared\u{0020}to\u{0020}the\u{0020}boring\u{0020}study,\u{0020}she\u{0020}prefers\u{0020}to\u{0020}hide\u{0020}in\u{0020}her\u{0020}room\u{0020}to\u{0020}play\u{0020}video\u{0020}games\u{0020}or\u{0020}watch\u{0020}her\u{0020}favorite\u{0020}cartoon\u{0020}and\u{0020}movies.\n\nTina\u{0020}once\u{0020}tried\u{0020}to\u{0020}correct\u{0020}Gin's\u{0020}behavior,\u{0020}but\u{0020}was\u{0020}met\u{0020}with\u{0020}fierce\u{0020}resistance.\u{0020}Soon,\u{0020}Tina\u{0020}realized\u{0020}that\u{0020}the\u{0020}methodology\u{0020}used\u{0020}to\u{0020}teach\u{0020}Alice\u{0020}was\u{0020}not\u{0020}applicable\u{0020}to\u{0020}educating\u{0020}Gin\u{0020}Cretia.\u{0020}Gin\u{0020}should\u{0020}not\u{0020}become\u{0020}the\u{0020}second\u{0020}Alice\u{0020}Cretia,\u{0020}but\u{0020}the\u{0020}unique\u{0020}Gin\u{0020}Cretia.\u{0020}Tina\u{0020}Eisen\u{0020}cheered\u{0020}up,\u{0020}taught\u{0020}students\u{0020}in\u{0020}accordance\u{0020}with\u{0020}their\u{0020}aptitude,\u{0020}and\u{0020}guided\u{0020}Gin\u{0020}onto\u{0020}the\u{0020}path\u{0020}suitable\u{0020}for\u{0020}her\u{0020}with\u{0020}a\u{0020}lenient\u{0020}educational\u{0020}policy.\n\nWhen\u{0020}dealing\u{0020}with\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}with\u{0020}completely\u{0020}different\u{0020}temperaments,\u{0020}Tina\u{0020}formulated\u{0020}different\u{0020}educational\u{0020}policies\u{0020}for\u{0020}them.\u{0020}Especially\u{0020}when\u{0020}there\u{0020}was\u{0020}\"a\u{0020}lady\"\u{0020}like\u{0020}Alice\u{0020}before,\u{0020}Tina\u{0020}did\u{0020}not\u{0020}disappoint\u{0020}Gin·Cretia\u{0020}either,\u{0020}but\u{0020}still\u{0020}guided\u{0020}Gin\u{0020}onto\u{0020}the\u{0020}path\u{0020}suitable\u{0020}for\u{0020}her.\u{0020}Undoubtedly,\u{0020}Tina\u{0020}Eisen\u{0020}is\u{0020}the\u{0020}premier\u{0020}excellent\u{0020}maid\u{0020}in\u{0020}the\u{0020}world.", "0", "0", "0", "0", 13002, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}蒂娜·爱森的家族世世代代都是克雷蒂亚家族的职业仆从，迄今已经有了近两百年的历史。爱森家族每次会在克雷蒂亚继承人诞生的那天，选定出培养和照顾下代继承人的女仆长。\n\u{1000}\u{1000}她为了这迟早要来临的一天，足足准备了九年的时间。当其他同龄人仍然处在向自己的父母撒娇的年龄，她就已经成了一名掌握了所有女仆技能的优秀仆从。正好也是九岁的时候，克雷蒂亚的第一位大小姐爱丽丝·克雷蒂亚出生了。\n\u{1000}\u{1000}蒂娜·爱森教导着爱丽丝作为克雷蒂亚家族大小姐应有的举止仪态，教会了她分辨错误的事情与正确的事情。蒂娜对于大小姐而言，既是教会了她人生知识的老师，又是保护着她的姐姐。\n\u{1000}\u{1000}克雷蒂亚家族的第二位大小姐，静·克雷蒂亚，为蒂娜·爱森的女仆生活插入了一首躁动的插曲。在蒂娜十六岁的时候，克雷蒂亚家族收养了一名战场遗孤作为克雷蒂亚家族的次女。\n\u{1000}\u{1000}静是一个和爱丽丝不同的孩子。\n\u{1000}\u{1000}在白天时，静总是在睡觉，到了晚上，她又变得精神焕发，好像有使不完的劲似的。因为作息与正常人不一致，导致她在上课时总是昏昏欲睡，学习成绩因此下降，对学习也渐渐丧失了兴趣。比起枯燥的学习，她更喜欢躲在自己的房间里畅玩电子游戏，或者是观看自己喜欢的动画、电影。\n\u{1000}\u{1000}蒂娜曾试图矫正静的行为，但因此遭到了激烈的反抗。很快地，蒂娜意识到教导爱丽丝的那套方法论是不适用于教育静·克雷蒂亚的。静不该成为第二个爱丽丝·克雷蒂亚，而是成为独一无二的静·克雷蒂亚，蒂娜·爱森振作起来，因材施教，用宽松的教育方针引导着静走上适合自己的路。\n\u{1000}\u{1000}在对待两位性情截然不同的大小姐，蒂娜为她们制定了不同的教育方针。尤其是有爱丽丝这样的\"珠玉\"在前时，蒂娜也未对静·克雷蒂亚失望，而是仍然将静引向适合她的路。毫无疑问，蒂娜·爱森是世界上首屈一指的优秀女仆。"},
[630203] = {630203, 1000, "\u{0020}\u{0020}Several\u{0020}months\u{0020}after\u{0020}the\u{0020}eldest\u{0020}daughter\u{0020}Alice·Cretia\u{0020}and\u{0020}the\u{0020}second\u{0020}daughter\u{0020}Gin·Cretia\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}successively\u{0020}entered\u{0020}Azure\u{0020}Academy\u{0020}for\u{0020}study,\u{0020}Tina,\u{0020}who\u{0020}was\u{0020}worried\u{0020}and\u{0020}uneasy\u{0020}about\u{0020}this,\u{0020}submitted\u{0020}a\u{0020}request\u{0020}to\u{0020}the\u{0020}head\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family\u{0020}to\u{0020}study\u{0020}at\u{0020}Azure\u{0020}Academy.\n\nUnder\u{0020}the\u{0020}recommendation\u{0020}of\u{0020}the\u{0020}Cretia\u{0020}family,\u{0020}Tina\u{0020}Eisen\u{0020}entered\u{0020}the\u{0020}logistics\u{0020}department\u{0020}of\u{0020}AEGIS\u{0020}Academy\u{0020}to\u{0020}learn\u{0020}skills\u{0020}that\u{0020}are\u{0020}not\u{0020}for\u{0020}maids:\u{0020}battlefield\u{0020}support\u{0020}work.\n\nAs\u{0020}time\u{0020}went\u{0020}by,\u{0020}Tina\u{0020}unsurprisingly\u{0020}entered\u{0020}the\u{0020}same\u{0020}team\u{0020}as\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies.\u{0020}But\u{0020}what\u{0020}gave\u{0020}her\u{0020}a\u{0020}headache\u{0020}was\u{0020}the\u{0020}stranger\u{0020}in\u{0020}the\u{0020}team:\u{0020}Hank.\u{0020}Hank\u{0020}always\u{0020}acted\u{0020}overly\u{0020}familiar\u{0020}and\u{0020}got\u{0020}close\u{0020}to\u{0020}the\u{0020}two\u{0020}young\u{0020}ladies\u{0020}in\u{0020}a\u{0020}familiar\u{0020}way,\u{0020}and\u{0020}always\u{0020}did\u{0020}some\u{0020}impolite\u{0020}things\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}young\u{0020}ladies,\u{0020}which\u{0020}gave\u{0020}Tina\u{0020}a\u{0020}big\u{0020}headache.\u{0020}The\u{0020}incorrigible\u{0020}Hank\u{0020}became\u{0020}a\u{0020}serious\u{0020}problem\u{0020}for\u{0020}Tina,\u{0020}but\u{0020}the\u{0020}former's\u{0020}character\u{0020}of\u{0020}approaching\u{0020}without\u{0020}any\u{0020}explanation\u{0020}also\u{0020}left\u{0020}Tina\u{0020}unable\u{0020}to\u{0020}resist.", "0", "0", "0", "0", 13002, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}在克雷蒂亚家族的长女爱丽丝·克雷蒂亚与次女静·克雷蒂亚相继进入苍穹学院就读几个月后，对此心怀忧虑、惴惴不安的蒂娜向克雷蒂亚的家主提出了就读苍穹学院的请求。\n\u{1000}\u{1000}在克雷蒂亚家族的举荐下，蒂娜·爱森进入了艾吉斯学院的后勤部，学习不属于女仆的技能——战场的支援工作。\n\u{1000}\u{1000}随着时间流逝，蒂娜不出意外地与两位小姐进入了同一只小队，但令她头疼的是队伍里的陌生人——汉克。汉克总是一副自来熟的样子亲近着两位大小姐，并且总是在大小姐面前做出一些无礼之事，这让蒂娜十分头疼。屡教不改的汉克成了蒂娜的心腹大患，但前者不由分说就凑过来的性格也让蒂娜无从招架。"},
[630204] = {630204, 2000, "\u{0020}\u{0020}For\u{0020}her,\u{0020}being\u{0020}a\u{0020}maid,\u{0020}being\u{0020}loyal,\u{0020}and\u{0020}serving\u{0020}someone\u{0020}came\u{0020}naturally.\n\nShe\u{0020}assumed\u{0020}she\u{0020}was\u{0020}simply\u{0020}doing\u{0020}things\u{0020}like\u{0020}walking\u{0020}and\u{0020}breathing.\n\n\"The\u{0020}perfect\u{0020}maid\u{0020}is\u{0020}truly\u{0020}remarkable.\"\n\nDespite\u{0020}this,\u{0020}even\u{0020}the\u{0020}tiniest\u{0020}gesture,\u{0020}allowing\u{0020}him\u{0020}to\u{0020}sit\u{0020}on\u{0020}her\u{0020}back,\u{0020}was\u{0020}greeted\u{0020}with\u{0020}gratitude.\n\nTina\u{0020}Eisen,\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}in\u{0020}twenty-seven\u{0020}years,\u{0020}was\u{0020}at\u{0020}a\u{0020}loss\u{0020}for\u{0020}words\u{0020}in\u{0020}the\u{0020}face\u{0020}of\u{0020}an\u{0020}unfamiliar\u{0020}experience.\n\nAn\u{0020}unexpected,\u{0020}never-before-seen\u{0020}emotion\u{0020}began\u{0020}to\u{0020}emerge.", "0", "0", "0", "0", 13002, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}作为女仆，忠于某个人，为某个人服务，对于她而言是理所当然的事。\n\u{1000}\u{1000}只是在做着如同走路和呼吸的事——她是这么想的。\n\u{1000}\u{1000}\"真是帮大忙了，完美的女仆果然厉害啊。\"\n\u{1000}\u{1000}然而，仅仅只是让他坐在自己背上这点小事，都会得到这样的感谢。\n\u{1000}\u{1000}在这种从未感受过的体验面前，\n\u{1000}\u{1000}蒂娜·爱森，二十七年以来第一次手足无措了。\n\u{1000}\u{1000}一种陌生的，从未有过的情感渐渐发芽了。"},
[630300] = {630300, 0, "[Name]\u{0020}Crim\u{0020}K.Tanov\n[B-Day]\u{0020}Feb\u{0020}18\n[Compatability\u{0020}Rate]\u{0020}68％\n[Height]\u{0020}31m\n[Squad]\u{0020}Ember\n[Affiliation]\u{0020}Katya\n[Interest]\u{0020}Katya\u{0020}liquor;\u{0020}Katya\u{0020}smoked\u{0020}sausage", "0", "0", "0", "0", 13003, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}克里姆·科·塔诺夫\n[B-Day]\u{1000}2月18日\n[幻化核心适格率]\u{1000}68％\n[Height]\u{1000}31m\n[部队]\u{1000}灰烬\n[隶属]\u{1000}卡佳地区\n[Interest]\u{1000}高浓度的卡佳酒\u{1000}卡佳熏肉肠"},
[630301] = {630301, 100, "\u{0020}\u{0020}If\u{0020}she\u{0020}didn't\u{0020}consume\u{0020}any\u{0020}alcohol,\u{0020}she\u{0020}would\u{0020}be\u{0020}a\u{0020}very\u{0020}energetic\u{0020}and\u{0020}good\u{0020}kid.\u{0020}Whenever\u{0020}she's\u{0020}stressful,\u{0020}she\u{0020}would\u{0020}choose\u{0020}to\u{0020}drink\u{0020}to\u{0020}relieve\u{0020}her\u{0020}stress;\u{0020}after\u{0020}that,\u{0020}she\u{0020}can\u{0020}be\u{0020}a\u{0020}little\u{0020}different.\n\nAs\u{0020}a\u{0020}child\u{0020}born\u{0020}in\u{0020}a\u{0020}cold\u{0020}area,\u{0020}it\u{0020}is\u{0020}not\u{0020}strange\u{0020}that\u{0020}she\u{0020}develops\u{0020}the\u{0020}hobby\u{0020}of\u{0020}alcohol\u{0020}addiction.\u{0020}The\u{0020}only\u{0020}thing\u{0020}that\u{0020}is\u{0020}not\u{0020}admirable\u{0020}is\u{0020}that\u{0020}she\u{0020}has\u{0020}the\u{0020}drinking\u{0020}manner\u{0020}like\u{0020}a\u{0020}middle\u{0020}aged\u{0020}person.\u{0020}After\u{0020}getting\u{0020}drunk,\u{0020}she\u{0020}often\u{0020}rushes\u{0020}into\u{0020}the\u{0020}navigator's\u{0020}office\u{0020}and\u{0020}makes\u{0020}a\u{0020}big\u{0020}fuss,\u{0020}being\u{0020}a\u{0020}typical\u{0020}\"troublemaker\u{0020}after\u{0020}drinking\".\n\nBesides\u{0020}drinking\u{0020}by\u{0020}herself,\u{0020}she\u{0020}also\u{0020}likes\u{0020}to\u{0020}brew\u{0020}wine\u{0020}and\u{0020}share\u{0020}it\u{0020}with\u{0020}others.\u{0020}She\u{0020}is\u{0020}also\u{0020}proficient\u{0020}in\u{0020}cooking\u{0020}and\u{0020}often\u{0020}makes\u{0020}some\u{0020}incredible\u{0020}dishes;\u{0020}of\u{0020}course,\u{0020}\"incredible\"\u{0020}is\u{0020}not\u{0020}praising\u{0020}the\u{0020}deliciousness\u{0020}of\u{0020}the\u{0020}dishes,\u{0020}but...\n\nIn\u{0020}short,\u{0020}she\u{0020}served\u{0020}as\u{0020}the\u{0020}logistics\u{0020}officer\u{0020}of\u{0020}the\u{0020}Ember\u{0020}team,\u{0020}responsible\u{0020}for\u{0020}the\u{0020}daily\u{0020}meals\u{0020}of\u{0020}her\u{0020}teammates.\u{0020}For\u{0020}her\u{0020}teammates,\u{0020}the\u{0020}daily\u{0020}\"surprise\"\u{0020}came\u{0020}from\u{0020}her\u{0020}not\u{0020}knowing\u{0020}what\u{0020}kind\u{0020}of\u{0020}meals\u{0020}would\u{0020}be\u{0020}made.\n\n\"If\u{0020}she\u{0020}is\u{0020}willing\u{0020}to\u{0020}make\u{0020}normal\u{0020}meals\u{0020}and\u{0020}fine\u{0020}wines,\u{0020}then\u{0020}she\u{0020}is\u{0020}a\u{0020}well-deserved\u{0020}chef.\u{0020}However\u{0020}-\u{0020}uh...\u{0020}\"\u{0020}This\u{0020}is\u{0020}the\u{0020}navigator's\u{0020}comprehensive\u{0020}evaluation\u{0020}of\u{0020}her\u{0020}cooking\u{0020}and\u{0020}brewing\u{0020}skills.\n\nOnce\u{0020}someone\u{0020}asked\u{0020}her\u{0020}why\u{0020}she\u{0020}did\u{0020}this,\u{0020}and\u{0020}her\u{0020}reply\u{0020}was:\u{0020}\"Under\u{0020}extreme\u{0020}circumstances,\u{0020}there's\u{0020}no\u{0020}guarantee\u{0020}that\u{0020}normal\u{0020}ingredients\u{0020}can\u{0020}be\u{0020}used\u{0020}for\u{0020}cooking!\"", "0", "0", "0", "0", 13003, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}如果不沾酒的话，就是一个活力十足的好孩子。每当她积攒了一定的压力之后，便会选择通过喝酒来释放压力——那之后，就稍微有点不大一样了。\n\u{1000}\u{1000}作为出生在严寒地带的孩子，她会染上嗜酒这个爱好并不算一件奇怪的事。唯一让人不敢恭维的是，她有着大叔般的酒品。醉酒后的她常常会闯入领航的办公室大闹特闹，是典型的\"酒后麻烦人物\"。\n\u{1000}\u{1000}除了喜欢自己喝酒外，她还喜欢酿酒分享给其他人喝，她同时还精通厨艺，常常做一些令人感到不可思议的菜肴——当然，\"不可思议\"并不是在称赞菜肴的美味，而是……\n\u{1000}\u{1000}总之，她担任着灰烬小队里的后勤官，负责队友日常的伙食。对于她的队友而言，每日的\"惊喜\"就是来自于她不知道会做成什么样的三餐。\n\u{1000}\u{1000}\"如果她愿意做正常的饭菜与美酒，那她就是名当之无愧的大厨，然而——呜……\"这便是领航对她厨艺与酿酒技艺的综合评价。\n\u{1000}\u{1000}曾经有人询问过她为什么这么做，她的答复是：\"在极端情况下，可没办法保证能用正常的食材做菜呀！\""},
[630302] = {630302, 500, "\u{0020}\u{0020}Crim\u{0020}K.Tanov\u{0020}was\u{0020}an\u{0020}adopted\u{0020}child.\u{0020}She\u{0020}grew\u{0020}up\u{0020}in\u{0020}a\u{0020}remote\u{0020}village\u{0020}that\u{0020}grew\u{0020}apples\u{0020}and\u{0020}sold\u{0020}fruit\u{0020}wine\u{0020}for\u{0020}a\u{0020}living.\u{0020}The\u{0020}fruit\u{0020}wine\u{0020}produced\u{0020}by\u{0020}the\u{0020}village\u{0020}has\u{0020}always\u{0020}been\u{0020}the\u{0020}best-selling\u{0020}drink\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}Crim\u{0020}learned\u{0020}the\u{0020}brewing\u{0020}skills\u{0020}from\u{0020}the\u{0020}village's\u{0020}master\u{0020}brewer\u{0020}when\u{0020}she\u{0020}was\u{0020}young.\u{0020}Unfortunately,\u{0020}her\u{0020}addiction\u{0020}to\u{0020}alcohol\u{0020}also\u{0020}started\u{0020}from\u{0020}that\u{0020}time.\n\nCrim's\u{0020}opportunity\u{0020}to\u{0020}come\u{0020}into\u{0020}contact\u{0020}with\u{0020}cooking\u{0020}was\u{0020}when\u{0020}her\u{0020}father\u{0020}caught\u{0020}a\u{0020}cold.\u{0020}In\u{0020}order\u{0020}to\u{0020}make\u{0020}her\u{0020}bedridden\u{0020}father\u{0020}recover\u{0020}soon,\u{0020}Crim\u{0020}tried\u{0020}to\u{0020}make\u{0020}some\u{0020}meals\u{0020}to\u{0020}regulate\u{0020}the\u{0020}body.\u{0020}After\u{0020}a\u{0020}period\u{0020}of\u{0020}recuperation,\u{0020}the\u{0020}father\u{0020}recovered\u{0020}his\u{0020}health,\u{0020}and\u{0020}Crim's\u{0020}cooking\u{0020}skills\u{0020}also\u{0020}improved\u{0020}significantly\u{0020}during\u{0020}that\u{0020}time.\n\nIn\u{0020}her\u{0020}spare\u{0020}time,\u{0020}Crim\u{0020}would\u{0020}use\u{0020}her\u{0020}savings\u{0020}to\u{0020}help\u{0020}the\u{0020}homeless.\u{0020}Under\u{0020}her\u{0020}suggestion\u{0020}and\u{0020}led\u{0020}by\u{0020}her\u{0020}father,\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}local\u{0020}relevant\u{0020}institutions,\u{0020}a\u{0020}homeless\u{0020}person\u{0020}mutual\u{0020}assistance\u{0020}association\u{0020}was\u{0020}established,\u{0020}which\u{0020}not\u{0020}only\u{0020}provided\u{0020}a\u{0020}guarantee\u{0020}of\u{0020}life\u{0020}for\u{0020}those\u{0020}homeless\u{0020}people,\u{0020}but\u{0020}also\u{0020}maintained\u{0020}social\u{0020}order\u{0020}to\u{0020}a\u{0020}certain\u{0020}extent.\n\nDuring\u{0020}a\u{0020}long\u{0020}trip\u{0020}with\u{0020}her\u{0020}father,\u{0020}Crim,\u{0020}who\u{0020}came\u{0020}to\u{0020}the\u{0020}\"Soriri\"\u{0020}town,\u{0020}witnessed\u{0020}with\u{0020}her\u{0020}own\u{0020}eyes\u{0020}the\u{0020}scene\u{0020}of\u{0020}Sin\u{0020}attacking\u{0020}the\u{0020}human\u{0020}village\u{0020}and\u{0020}\"Ember\",\u{0020}who\u{0020}arrived\u{0020}at\u{0020}the\u{0020}battlefield\u{0020}in\u{0020}time\u{0020}and\u{0020}appeared\u{0020}like\u{0020}a\u{0020}hero\u{0020}in\u{0020}an\u{0020}epic.\u{0020}After\u{0020}that\u{0020}day,\u{0020}Crim,\u{0020}attracted\u{0020}by\u{0020}the\u{0020}handsomeness\u{0020}and\u{0020}strength\u{0020}of\u{0020}\"Ember\",\u{0020}secretly\u{0020}signed\u{0020}up\u{0020}for\u{0020}this\u{0020}mysterious\u{0020}civilian\u{0020}team\u{0020}without\u{0020}telling\u{0020}her\u{0020}father.\n\nThe\u{0020}reason\u{0020}for\u{0020}joining\u{0020}the\u{0020}Ember\u{0020}team\u{0020}is,\u{0020}on\u{0020}the\u{0020}one\u{0020}hand,\u{0020}attracted\u{0020}by\u{0020}the\u{0020}strength\u{0020}and\u{0020}handsomeness\u{0020}displayed\u{0020}by\u{0020}the\u{0020}Ember\u{0020}team,\u{0020}and\u{0020}on\u{0020}the\u{0020}other\u{0020}hand,\u{0020}she\u{0020}wants\u{0020}to\u{0020}help\u{0020}more\u{0020}people\u{0020}who\u{0020}have\u{0020}been\u{0020}displaced\u{0020}due\u{0020}to\u{0020}Sin's\u{0020}invasion.\u{0020}If\u{0020}possible,\u{0020}she\u{0020}wants\u{0020}to\u{0020}be\u{0020}a\u{0020}hero\u{0020}who\u{0020}ends\u{0020}the\u{0020}war\u{0020}-\u{0020}a\u{0020}hero\u{0020}with\u{0020}a\u{0020}good\u{0020}ending.", "0", "0", "0", "0", 13003, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}克里姆·科·塔诺夫是被人收养的孩子。她成长于一个种植苹果、贩卖果酒为生的偏僻村子。村子生产的果酒一直是卡佳地区最畅销的饮品，克里姆酿酒的技艺便是在小的时候从村子里的酿酒师傅那学来的。不幸染上酒瘾，也是从那个时候开始的。\n\u{1000}\u{1000}克里姆接触厨艺的契机是父亲染上风寒。为了让卧病的父亲早日康复，克里姆试着做了些调理身体的膳食。父亲经过一段时间的调养恢复了健康，而克里姆的厨艺也在那段时间里有了十足的长进。\n\u{1000}\u{1000}在闲暇时间，克里姆还会用自己的储蓄来接济无家可归的人，在她的建议下，由她父亲牵头，通过当地有关机构的帮助，成立了一个流民互助协会，既为那些无家可归的人提供了生活保证，又一定程度上维护了社会秩序。\n\u{1000}\u{1000}在一次与父亲的远行中，来到\"索里里\"镇的克里姆，亲眼目睹了袭击人类村落的原罪与以及及时赶到战场，仿若史诗中的英雄般登场的\"灰烬\"战斗的场面。那一天之后，被\"灰烬\"的帅气与强大所吸引的克里姆，瞒着父亲，偷偷报名了这支神秘的民间小队。\n\u{1000}\u{1000}加入灰烬小队的原因，一方面是被灰烬小队展现出的强大与帅气吸引，另一方面则是她想帮助到更多因为原罪的入侵而流离失所的人。如果可以的话，她想成为一名结束战争的英雄——一个能有好结局的英雄。"},
[630303] = {630303, 1000, "\u{0020}\u{0020}Crim\u{0020}became\u{0020}the\u{0020}logistics\u{0020}officer\u{0020}of\u{0020}the\u{0020}Ember\u{0020}with\u{0020}excellent\u{0020}(only\u{0020}at\u{0020}the\u{0020}technical\u{0020}level)\u{0020}cooking\u{0020}and\u{0020}brewing\u{0020}skills.\u{0020}As\u{0020}a\u{0020}civilian\u{0020}team,\u{0020}the\u{0020}logistics\u{0020}resources\u{0020}of\u{0020}the\u{0020}Ember\u{0020}often\u{0020}faced\u{0020}a\u{0020}deficit\u{0020}crisis,\u{0020}which\u{0020}made\u{0020}her,\u{0020}as\u{0020}the\u{0020}logistics\u{0020}officer,\u{0020}always\u{0020}stressed.\n\nThis\u{0020}situation\u{0020}got\u{0020}better\u{0020}upon\u{0020}the\u{0020}official\u{0020}incorporation\u{0020}of\u{0020}the\u{0020}Ember\u{0020}into\u{0020}AEGIS.\u{0020}Although\u{0020}not\u{0020}much,\u{0020}the\u{0020}stable\u{0020}and\u{0020}guaranteed\u{0020}logistical\u{0020}support\u{0020}can\u{0020}be\u{0020}regarded\u{0020}as\u{0020}\"strong\u{0020}support\"\u{0020}for\u{0020}Crim.\n\nAs\u{0020}the\u{0020}biggest\u{0020}beneficiary\u{0020}of\u{0020}joining\u{0020}AEGIS,\u{0020}Crim,\u{0020}in\u{0020}order\u{0020}to\u{0020}repay\u{0020}the\u{0020}help\u{0020}of\u{0020}the\u{0020}navigator,\u{0020}often\u{0020}makes\u{0020}dishes\u{0020}with\u{0020}novel\u{0020}ideas\u{0020}and\u{0020}unique\u{0020}materials\u{0020}and\u{0020}sends\u{0020}them\u{0020}to\u{0020}the\u{0020}navigator's\u{0020}room,\u{0020}allowing\u{0020}the\u{0020}navigator\u{0020}to\u{0020}be\u{0020}the\u{0020}first\u{0020}taster.", "0", "0", "0", "0", 13003, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}克里姆以出色（仅在技术层面上）的厨艺与酿酒技艺成为了灰烬小队的后勤官。作为一支民间小队，灰烬战队的后勤资源常常面临着赤字危机，这让身为后勤官的她总是背负着压力。\n\u{1000}\u{1000}这一状况得以改善的契机无疑是灰烬小队正式入编艾吉斯。尽管不多，但稳定的、有保障的后勤支援对于克里姆来说已经算得上\"鼎力扶持\"了。\n\u{1000}\u{1000}克里姆作为加入艾吉斯的最大受益人，为了回报领航的帮助，常常会做一些立意新颖，取材独特的菜肴送到领航的房间，让领航作为第一位试吃人。"},
[630304] = {630304, 2000, "\u{0020}I\u{0020}really\u{0020}hope\u{0020}that\u{0020}one\u{0020}day,\u{0020}everyone\u{0020}can\u{0020}live\u{0020}in\u{0020}a\u{0020}warm\u{0020}house.\n\nThis\u{0020}is\u{0020}why\u{0020}the\u{0020}girl\u{0020}fights.\n\nTo\u{0020}save\u{0020}the\u{0020}people\u{0020}suffering\u{0020}from\u{0020}hunger\u{0020}and\u{0020}cold,\u{0020}she\u{0020}became\u{0020}a\u{0020}\"hero\".\u{0020}There\u{0020}were\u{0020}thoughts\u{0020}of\u{0020}giving\u{0020}up\u{0020}along\u{0020}the\u{0020}way,\u{0020}but\u{0020}she\u{0020}persisted\u{0020}until\u{0020}now.\n\nThe\u{0020}giant\u{0020}who\u{0020}stands\u{0020}firm\u{0020}in\u{0020}the\u{0020}fierce\u{0020}blizzard\u{0020}is\u{0020}actually\u{0020}just\u{0020}a\u{0020}young\u{0020}girl.\n\n\"To\u{0020}make\u{0020}everyone\u{0020}can\u{0020}have\u{0020}enough\u{0020}to\u{0020}eat\u{0020}and\u{0020}everyone\u{0020}can\u{0020}live\u{0020}in\u{0020}a\u{0020}big\u{0020}house.\u{0020}That\u{0020}is\u{0020}my\u{0020}dream,\u{0020}Navigator.\"\n\nAlso,\u{0020}I\u{0020}still\u{0020}want\u{0020}endless\u{0020}wine.\u{0020}Hehe!", "0", "0", "0", "0", 13003, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"真希望有一天，大家都能住进温暖的房子里呀。\"\n\u{1000}\u{1000}这正是少女参加战争的理由，\n\u{1000}\u{1000}想要拯救饱受饥寒之难的人民，抱着质朴的愿望成为了人民口中的\"英雄\"，途中也有过想要放弃的想法，但她咬着牙坚持到了现在。\n\u{1000}\u{1000}在凛冽的暴风雪中屹立不倒的巨人，其真身也不过是年纪轻轻的女孩罢了。\n\u{1000}\u{1000}\"人人都能吃饱饭，人人都能在大房子里住，这就是我的梦想喔，领航。\"\n\u{1000}\u{1000}\"还有，我还想要永远喝不完的酒，嘿嘿！\""},
[630400] = {630400, 0, "[Name]\u{0020}Caihua\n[B-Day]\u{0020}Aug\u{0020}26\n[Compatability\u{0020}Rate]\u{0020}81％\n[Height]\u{0020}32m\n[Squad]\u{0020}Tian\u{0020}Hua\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Do\u{0020}one\u{0020}good\u{0020}deed\u{0020}every\u{0020}day", "0", "0", "0", "0", 13004, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}彩华\n[B-Day]\u{1000}8月26日\n[幻化核心适格率]\u{1000}81％\n[Height]\u{1000}32m\n[部队]\u{1000}天华阁\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}日行一善"},
[630401] = {630401, 100, "\u{0020}\u{0020}When\u{0020}it\u{0020}comes\u{0020}to\u{0020}the\u{0020}most\u{0020}conscientious\u{0020}and\u{0020}responsible\u{0020}person\u{0020}in\u{0020}Kyushu\u{0020}Headquarters,\u{0020}she\u{0020}is\u{0020}undoubtedly\u{0020}the\u{0020}first\u{0020}choice\u{0020}by\u{0020}vast\u{0020}majority\u{0020}of\u{0020}people.\n\nHer\u{0020}serious\u{0020}and\u{0020}responsible\u{0020}attitude\u{0020}towards\u{0020}her\u{0020}work\u{0020}often\u{0020}makes\u{0020}colleagues\u{0020}worry\u{0020}that\u{0020}she\u{0020}will\u{0020}impose\u{0020}unnecessary\u{0020}burdens\u{0020}on\u{0020}her.\u{0020}However,\u{0020}she\u{0020}seems\u{0020}to\u{0020}attach\u{0020}great\u{0020}importance\u{0020}to\u{0020}her\u{0020}own\u{0020}body,\u{0020}and\u{0020}the\u{0020}concerns\u{0020}of\u{0020}colleagues\u{0020}are\u{0020}superfluous.\n\nHer\u{0020}conscientiousness\u{0020}and\u{0020}responsibility\u{0020}are\u{0020}not\u{0020}only\u{0020}reflected\u{0020}in\u{0020}her\u{0020}work,\u{0020}but\u{0020}even\u{0020}in\u{0020}conversations\u{0020}with\u{0020}others,\u{0020}one\u{0020}can\u{0020}feel\u{0020}this\u{0020}quality\u{0020}of\u{0020}hers.\u{0020}She\u{0020}would\u{0020}correct\u{0020}others'\u{0020}mistakes\u{0020}regardless\u{0020}of\u{0020}the\u{0020}occasion,\u{0020}and\u{0020}turn\u{0020}a\u{0020}blind\u{0020}eye\u{0020}even\u{0020}if\u{0020}it\u{0020}makes\u{0020}the\u{0020}other\u{0020}party\u{0020}embarrassed.\u{0020}Therefore,\u{0020}although\u{0020}she\u{0020}has\u{0020}no\u{0020}ill\u{0020}intentions,\u{0020}she\u{0020}often\u{0020}becomes\u{0020}the\u{0020}destroyer\u{0020}of\u{0020}the\u{0020}atmosphere\u{0020}and\u{0020}the\u{0020}terminator\u{0020}of\u{0020}the\u{0020}chat.\n\nHowever,\u{0020}although\u{0020}she\u{0020}is\u{0020}not\u{0020}good\u{0020}at\u{0020}getting\u{0020}along\u{0020}with\u{0020}others,\u{0020}people\u{0020}around\u{0020}her\u{0020}don't\u{0020}dislike\u{0020}her.\u{0020}From\u{0020}time\u{0020}to\u{0020}time,\u{0020}there\u{0020}are\u{0020}some\u{0020}colleagues\u{0020}who\u{0020}have\u{0020}received\u{0020}help\u{0020}from\u{0020}her\u{0020}expressing\u{0020}their\u{0020}gratitude\u{0020}-\u{0020}then,\u{0020}they\u{0020}are\u{0020}scared\u{0020}away\u{0020}by\u{0020}the\u{0020}girl\u{0020}who\u{0020}is\u{0020}not\u{0020}good\u{0020}at\u{0020}responding\u{0020}to\u{0020}thanks\u{0020}with\u{0020}a\u{0020}stern\u{0020}face.\u{0020}Such\u{0020}a\u{0020}scene\u{0020}is\u{0020}always\u{0020}repeating,\u{0020}and\u{0020}perhaps\u{0020}people\u{0020}also\u{0020}enjoy\u{0020}it.\n\nSuch\u{0020}a\u{0020}scene\u{0020}is\u{0020}always\u{0020}repeating.\u{0020}Perhaps\u{0020}people\u{0020}also\u{0020}enjoy\u{0020}it.", "0", "0", "0", "0", 13004, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}提及九州总部最认真负责的人，她必然是绝大多数人心中的首选。\n\u{1000}\u{1000}她对于自己的工作过于认真负责的态度，常常让同僚担心她会因为工作而给自己的身体增加不必要的负担。不过，她似乎对自己的身体十分重视，同僚的担心是多余的。\n\u{1000}\u{1000}她的认真负责不仅体现在工作中，就连与人相处的对话也能让人感受到她的这份认真。她会不分场合地指正旁人的错误，即使会让对方陷入尴尬也视若无睹。因此没有恶意的她，却经常成为氛围的毁灭者、聊天的终结者。\n\u{1000}\u{1000}……不过，虽然她不太懂得与人相处，但周围的人并不讨厌她。时不时会有一些从她那得到帮助的同事向她表示感谢——然后，被不擅长回应谢意的少女板着脸吓跑。\n\u{1000}\u{1000}这样的景色总在循环着，或许人们也乐在其中。"},
[630402] = {630402, 500, "\u{0020}\u{0020}The\u{0020}daughter\u{0020}of\u{0020}a\u{0020}wealthy\u{0020}businessman\u{0020}who\u{0020}runs\u{0020}a\u{0020}pharmaceutical\u{0020}company,\u{0020}Caihua\u{0020}is\u{0020}the\u{0020}kind\u{0020}of\u{0020}child\u{0020}born\u{0020}with\u{0020}a\u{0020}silver\u{0020}spoon\u{0020}in\u{0020}her\u{0020}mouth.\u{0020}Her\u{0020}father\u{0020}intends\u{0020}to\u{0020}cultivate\u{0020}Caihua\u{0020}as\u{0020}his\u{0020}successor,\u{0020}but\u{0020}Caihua,\u{0020}who\u{0020}has\u{0020}been\u{0020}exposed\u{0020}to\u{0020}business\u{0020}transactions\u{0020}since\u{0020}childhood,\u{0020}despises\u{0020}doing\u{0020}business\u{0020}and\u{0020}even\u{0020}detests\u{0020}the\u{0020}business\u{0020}world.\u{0020}She\u{0020}believes\u{0020}that\u{0020}there\u{0020}are\u{0020}lies\u{0020}everywhere\u{0020}among\u{0020}businessmen,\u{0020}which\u{0020}she\u{0020}finds\u{0020}unbearable.\n\nBy\u{0020}contrast,\u{0020}she\u{0020}is\u{0020}more\u{0020}interested\u{0020}in\u{0020}the\u{0020}ancestral\u{0020}craft\u{0020}-\u{0020}acupuncture\u{0020}and\u{0020}acupoint\u{0020}pressing\u{0020}-\u{0020}that\u{0020}was\u{0020}abandoned\u{0020}by\u{0020}her\u{0020}father.\u{0020}When\u{0020}her\u{0020}elderly\u{0020}grandfather\u{0020}learned\u{0020}that\u{0020}Caihua\u{0020}was\u{0020}interested\u{0020}in\u{0020}the\u{0020}family\u{0020}craft,\u{0020}he\u{0020}passed\u{0020}on\u{0020}his\u{0020}lifelong\u{0020}medical\u{0020}experience\u{0020}to\u{0020}his\u{0020}little\u{0020}granddaughter.\n\nLearning\u{0020}medicine\u{0020}from\u{0020}her\u{0020}grandfather\u{0020}was\u{0020}the\u{0020}happiest\u{0020}time\u{0020}in\u{0020}Caihua's\u{0020}life\u{0020}and\u{0020}the\u{0020}only\u{0020}memory\u{0020}she\u{0020}has\u{0020}of\u{0020}her\u{0020}childhood.\n\nAfter\u{0020}turning\u{0020}sixteen,\u{0020}Caihua\u{0020}bid\u{0020}farewell\u{0020}to\u{0020}her\u{0020}family\u{0020}and\u{0020}began\u{0020}to\u{0020}travel\u{0020}alone\u{0020}in\u{0020}Kyushu,\u{0020}leaving\u{0020}behind\u{0020}urban\u{0020}legends\u{0020}like\u{0020}\"The\u{0020}girl\u{0020}who\u{0020}can\u{0020}cure\u{0020}all\u{0020}diseases\u{0020}with\u{0020}a\u{0020}needle\",\u{0020}\"The\u{0020}girl\u{0020}with\u{0020}the\u{0020}ability\u{0020}to\u{0020}bring\u{0020}the\u{0020}dead\u{0020}back\u{0020}to\u{0020}life\",\u{0020}and\u{0020}\"The\u{0020}doctoress\u{0020}who\u{0020}leaves\u{0020}patients\u{0020}with\u{0020}unforgettable\u{0020}pain\"\u{0020}-\u{0020}all\u{0020}somewhat\u{0020}exaggerated\u{0020}but\u{0020}also\u{0020}with\u{0020}some\u{0020}truth.\n\nCaihua\u{0020}regarded\u{0020}the\u{0020}world\u{0020}as\u{0020}her\u{0020}home.\u{0020}After\u{0020}wandering\u{0020}for\u{0020}a\u{0020}year\u{0020}and\u{0020}a\u{0020}half,\u{0020}she\u{0020}finally\u{0020}reached\u{0020}the\u{0020}end\u{0020}of\u{0020}her\u{0020}journey.\u{0020}What\u{0020}awaited\u{0020}her\u{0020}was\u{0020}not\u{0020}the\u{0020}magnificent\u{0020}river,\u{0020}not\u{0020}the\u{0020}ancient\u{0020}and\u{0020}towering\u{0020}forests,\u{0020}nor\u{0020}the\u{0020}undulating\u{0020}mountains.\u{0020}Her\u{0020}destination\u{0020}was\u{0020}a\u{0020}dead\u{0020}place.\n\nThe\u{0020}sky\u{0020}was\u{0020}obscured\u{0020}by\u{0020}fog,\u{0020}tall\u{0020}buildings\u{0020}turned\u{0020}into\u{0020}worthless\u{0020}bricks\u{0020}and\u{0020}tiles,\u{0020}and\u{0020}the\u{0020}smiles\u{0020}that\u{0020}once\u{0020}filled\u{0020}people's\u{0020}faces\u{0020}disappeared.\u{0020}Caihua\u{0020}stood\u{0020}in\u{0020}the\u{0020}dusty\u{0020}ruins\u{0020}where\u{0020}no\u{0020}patient\u{0020}was\u{0020}there\u{0020}for\u{0020}her\u{0020}to\u{0020}cure,\u{0020}and\u{0020}no\u{0020}living\u{0020}person\u{0020}at\u{0020}all.\u{0020}Dead,\u{0020}all\u{0020}dead,\u{0020}destroyed,\u{0020}exhausted,\u{0020}vanished.\u{0020}A\u{0020}city\u{0020}disappeared\u{0020}from\u{0020}the\u{0020}map\u{0020}of\u{0020}humanity.\n\nThat\u{0020}day,\u{0020}the\u{0020}traveling\u{0020}doctor\u{0020}Caihua\u{0020}reached\u{0020}the\u{0020}end.", "0", "0", "0", "0", 13004, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}经营着药物公司的富商之女，彩华就是那类含着金钥匙出生的孩子。父亲有意将彩华培养为自己的接班人，而从小对商场交易耳濡目染的彩华轻视从商，甚至厌恶商场。她认为商人之间充斥着谎言，这让她难以忍受。\n\u{1000}\u{1000}相比之下，她对于被父亲放弃了的祖传手艺——针灸点穴——更加感兴趣。年事已高的祖父得知彩华对家传手艺感兴趣，便将自己的毕生行医经验传授给了自己的小孙女。\n\u{1000}\u{1000}跟随着自己祖父学医是彩华人生中最快乐的时光，也是她对于自己童年唯一的记忆。\n\u{1000}\u{1000}在年满十六之后，彩华辞别了家人，开始一人在九州游历四方，在各个城市里留下了如都市传说一般的事迹：\"用一根针便能解决所有疾病的少女\"、\"拥有起死回生之术的女孩\"、\"会给病人留下刻苦铭心之痛的女神医\"——尽是些言过其实，但也有一定真实性的传闻。\n\u{1000}\u{1000}彩华以四海为家，经历了一年半的漂泊后，终于来到了她这趟旅途的终点。等待她的不是波澜壮阔的江流，不是古木参天的森林，更加不是龙翔凤舞的群山。她的终点，是一处死地。\n\u{1000}\u{1000}天空被雾气遮住，高楼大厦沦为一文不值的砖瓦，原本洋溢在人们脸上的笑容也消失了。彩华立足于黄土纷飞的废墟中，没有一个患者需要她去救治，也没有一个活人在她面前走动。死，死了，一个不剩，毁灭，殆尽，消亡，一座城市从人类的地图上消失了。\n\u{1000}\u{1000}那一天，游医彩华抵达了终点。"},
[630403] = {630403, 1000, "\u{0020}\u{0020}After\u{0020}graduating\u{0020}from\u{0020}Azure\u{0020}Academy\u{0020}with\u{0020}outstanding\u{0020}grades,\u{0020}Caihua\u{0020}became\u{0020}a\u{0020}driver\u{0020}candidate\u{0020}of\u{0020}Kyushu\u{0020}Headquarters.\u{0020}When\u{0020}Kyushu\u{0020}Headquarters\u{0020}encountered\u{0020}a\u{0020}crisis,\u{0020}she\u{0020}became\u{0020}the\u{0020}captain\u{0020}of\u{0020}a\u{0020}temporary\u{0020}team\u{0020}and\u{0020}led\u{0020}the\u{0020}team\u{0020}to\u{0020}carry\u{0020}out\u{0020}the\u{0020}support\u{0020}mission\u{0020}for\u{0020}Frontier.\n\nTaking\u{0020}this\u{0020}as\u{0020}an\u{0020}opportunity,\u{0020}she\u{0020}met\u{0020}Huameng,\u{0020}a\u{0020}girl\u{0020}addicted\u{0020}to\u{0020}martial\u{0020}arts\u{0020}practice\u{0020}and\u{0020}unable\u{0020}to\u{0020}extricate\u{0020}herself,\u{0020}and\u{0020}Huameng's\u{0020}sister,\u{0020}Hualian,\u{0020}who\u{0020}wanted\u{0020}to\u{0020}compete\u{0020}in\u{0020}martial\u{0020}arts\u{0020}with\u{0020}others\u{0020}all\u{0020}day.\n\nIf\u{0020}it\u{0020}is\u{0020}said\u{0020}that\u{0020}they\u{0020}did\u{0020}not\u{0020}bring\u{0020}trouble\u{0020}to\u{0020}her\u{0020}life,\u{0020}it\u{0020}is\u{0020}definitely\u{0020}a\u{0020}lie.\u{0020}But\u{0020}if\u{0020}it\u{0020}is\u{0020}said\u{0020}that\u{0020}Caihua\u{0020}does\u{0020}not\u{0020}like\u{0020}her\u{0020}team\u{0020}members,\u{0020}it\u{0020}is\u{0020}also\u{0020}a\u{0020}lie.\u{0020}The\u{0020}outgoing\u{0020}sisters\u{0020}Huameng\u{0020}and\u{0020}Hualian,\u{0020}as\u{0020}well\u{0020}as\u{0020}Suzu,\u{0020}who\u{0020}joined\u{0020}later\u{0020}and\u{0020}always\u{0020}did\u{0020}some\u{0020}stupid\u{0020}things,\u{0020}made\u{0020}Caihua,\u{0020}who\u{0020}had\u{0020}been\u{0020}traveling\u{0020}alone,\u{0020}feel\u{0020}the\u{0020}warmth\u{0020}of\u{0020}family\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\n\nHowever,\u{0020}for\u{0020}the\u{0020}earnest\u{0020}and\u{0020}somewhat\u{0020}clumsy\u{0020}Caihua\u{0020}to\u{0020}express\u{0020}this\u{0020}feeling,\u{0020}it\u{0020}is\u{0020}estimated\u{0020}that\u{0020}a\u{0020}very\u{0020}long\u{0020}journey\u{0020}will\u{0020}be\u{0020}needed.", "0", "0", "0", "0", 13004, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}彩华以杰出的成绩从苍穹学院毕业后，成为九州总部的驾驶员备选名单上的一员。在九州总部遇到危机时，成为了一支临时小队的队长，带领队伍执行支援前线任务。\n\u{1000}\u{1000}以此为契机，她认识了沉迷在武术修行中不可自拔的少女华梦，以及华梦的妹妹，整天想和人切磋武艺的华恋。\n\u{1000}\u{1000}如果说两名少女没给自己的生活带来麻烦，那绝对是谎言。但如果说彩华不喜欢自己的两名队员，同样也是谎言。外向的华梦、华恋姐妹让孤身一人四处游历的彩华久违地感受到了家庭的温暖。\n\u{1000}\u{1000}不过，想让认真、又有点笨拙的彩华将这感情说出来，估计需要一段很长的旅途吧。"},
[630404] = {630404, 2000, "\u{0020}\u{0020}The\u{0020}reason\u{0020}for\u{0020}not\u{0020}continuing\u{0020}to\u{0020}practice\u{0020}medicine?\n\nThe\u{0020}azure\u{0020}mist\u{0020}gradually\u{0020}dissipated,\u{0020}as\u{0020}if\u{0020}the\u{0020}land\u{0020}that\u{0020}had\u{0020}been\u{0020}attacked\u{0020}by\u{0020}meteorite\u{0020}swarms\u{0020}revealed\u{0020}its\u{0020}true\u{0020}appearance.\n\nThe\u{0020}young\u{0020}girl\u{0020}touched\u{0020}her\u{0020}own\u{0020}cheek\u{0020}and\u{0020}looked\u{0020}seriously\u{0020}at\u{0020}the\u{0020}navigator\u{0020}under\u{0020}her\u{0020}feet.\n\n\"I\u{0020}have\u{0020}never\u{0020}given\u{0020}up\u{0020}medical\u{0020}skills,\u{0020}Navigator.\"\n\nBlindly\u{0020}saving\u{0020}people\u{0020}is\u{0020}unable\u{0020}to\u{0020}change\u{0020}the\u{0020}current\u{0020}situation.\n\nIt\u{0020}seemed\u{0020}that\u{0020}there\u{0020}was\u{0020}a\u{0020}burning\u{0020}flame\u{0020}in\u{0020}her\u{0020}pupils.\n\n\"Only\u{0020}by\u{0020}eliminating\u{0020}Sin\u{0020}one\u{0020}by\u{0020}one\u{0020}can\u{0020}humanity\u{0020}recover.\"\u{0020}\"...Do\u{0020}you\u{0020}think\u{0020}so\u{0020}too,\u{0020}Navigator?\"", "0", "0", "0", "0", 13004, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}\"不继续四处行医的理由？\"\n\u{1000}\u{1000}苍蓝的雾气渐渐散去，像是被陨石群袭击过的大地露出了面目。\n\u{1000}\u{1000}少女摸了摸自己的脸颊，认真地看着脚下的领航，\n\u{1000}\u{1000}\"在下从没有放弃过医术，领航。\"\n\u{1000}\u{1000}\"一昧地救人，是无法改变现状的。\"\n\u{1000}\u{1000}她的眼瞳中仿佛有一团炙热的火焰，\n\u{1000}\u{1000}\"只有将原罪一个不剩地消灭，人类才能康复。\"\n\u{1000}\u{1000}\"……你也是这么想的吧，领航？\""},
[630500] = {630500, 0, "[Name]\u{0020}Genia\n[B-Day]\u{0020}June\u{0020}24\n[Compatability\u{0020}Rate]\u{0020}86％\n[Height]\u{0020}38m\n[Squad]\u{0020}Snow\u{0020}Owl\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Piece\u{0020}together\u{0020}mind\u{0020}maps;\u{0020}Draw\u{0020}anatomical\u{0020}diagrams", "0", "0", "0", "0", 13005, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[630501] = {630501, 100, "\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}the\u{0020}official\u{0020}team\u{0020}\"Snow\u{0020}Owl\"\u{0020}of\u{0020}Katya\u{0020}Branch,\u{0020}unlike\u{0020}other\u{0020}members\u{0020}who\u{0020}are\u{0020}good\u{0020}at\u{0020}fighting\u{0020}in\u{0020}the\u{0020}snow,\u{0020}although\u{0020}Genia\u{0020}is\u{0020}very\u{0020}familiar\u{0020}with\u{0020}the\u{0020}snow\u{0020}environment,\u{0020}she\u{0020}is\u{0020}more\u{0020}proficient\u{0020}in\u{0020}providing\u{0020}support\u{0020}at\u{0020}the\u{0020}rear\u{0020}rather\u{0020}than\u{0020}fighting.\n\n\n\nHer\u{0020}capable\u{0020}way\u{0020}of\u{0020}doing\u{0020}things\u{0020}made\u{0020}her\u{0020}trusted\u{0020}by\u{0020}her\u{0020}teammates.\u{0020}It\u{0020}could\u{0020}be\u{0020}said\u{0020}that\u{0020}whether\u{0020}it\u{0020}was\u{0020}the\u{0020}battlefield\u{0020}where\u{0020}the\u{0020}conventional\u{0020}troops\u{0020}were\u{0020}the\u{0020}main\u{0020}troops\u{0020}in\u{0020}the\u{0020}past,\u{0020}or\u{0020}the\u{0020}Sin\u{0020}battlefield\u{0020}where\u{0020}the\u{0020}driver\u{0020}troops\u{0020}were\u{0020}the\u{0020}main\u{0020}combat\u{0020}force,\u{0020}when\u{0020}the\u{0020}soldiers\u{0020}knew\u{0020}that\u{0020}Genia\u{0020}was\u{0020}in\u{0020}charge\u{0020}of\u{0020}support,\u{0020}they\u{0020}would\u{0020}abandon\u{0020}all\u{0020}their\u{0020}worries\u{0020}and\u{0020}do\u{0020}their\u{0020}best\u{0020}to\u{0020}go\u{0020}into\u{0020}battle.\n\n\n\nShe\u{0020}can\u{0020}make\u{0020}the\u{0020}wounded\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}feel\u{0020}at\u{0020}ease,\u{0020}not\u{0020}by\u{0020}gentle\u{0020}words\u{0020}and\u{0020}actions,\u{0020}but\u{0020}by\u{0020}the\u{0020}confidence\u{0020}of\u{0020}\"No\u{0020}matter\u{0020}what\u{0020}kind\u{0020}of\u{0020}injury,\u{0020}I\u{0020}can\u{0020}definitely\u{0020}save\u{0020}you\".\n\n\n\n\"We\u{0020}are\u{0020}fighting\u{0020}against\u{0020}Sin\u{0020}-\u{0020}and\u{0020}Genia,\u{0020}she\u{0020}is\u{0020}constantly\u{0020}engaged\u{0020}in\u{0020}a\u{0020}protracted\u{0020}battle\u{0020}with\u{0020}Death.\"\n\n\n\n-\u{0020}Lydia\u{0020}Lee\u{0020}Ustinovich,\u{0020}Captain\u{0020}Snow\u{0020}Owl.", "0", "0", "0", "0", 13005, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[630502] = {630502, 500, "\u{0020}\u{0020}Genia\u{0020}Lee\u{0020}Zaytsev\u{0020}is\u{0020}a\u{0020}native\u{0020}of\u{0020}Katya.\n\n\n\nBut\u{0020}what\u{0020}makes\u{0020}her\u{0020}different\u{0020}from\u{0020}other\u{0020}Katya\u{0020}people\u{0020}is\u{0020}that\u{0020}she\u{0020}detests\u{0020}Katya,\u{0020}which\u{0020}is\u{0020}covered\u{0020}with\u{0020}snow\u{0020}all\u{0020}year\u{0020}round.\n\n\n\nBecause\u{0020}she\u{0020}understood\u{0020}that\u{0020}Katya\u{0020}was\u{0020}ruthless,\u{0020}its\u{0020}coldness\u{0020}would\u{0020}claim\u{0020}the\u{0020}lives\u{0020}of\u{0020}most\u{0020}people.\u{0020}At\u{0020}least\u{0020}her\u{0020}grandmother\u{0020}died\u{0020}desperately\u{0020}in\u{0020}the\u{0020}severe\u{0020}cold.\u{0020}It\u{0020}was\u{0020}also\u{0020}her\u{0020}grandmother's\u{0020}death\u{0020}that\u{0020}made\u{0020}her\u{0020}aware\u{0020}of\u{0020}how\u{0020}heartless\u{0020}this\u{0020}land\u{0020}was.\n\n\n\nNot\u{0020}only\u{0020}did\u{0020}Genia\u{0020}experience\u{0020}her\u{0020}grandmother's\u{0020}death.\u{0020}People\u{0020}she\u{0020}knew\u{0020}and\u{0020}those\u{0020}she\u{0020}didn't,\u{0020}when\u{0020}she\u{0020}was\u{0020}still\u{0020}young,\u{0020}she\u{0020}had\u{0020}already\u{0020}witnessed\u{0020}enough\u{0020}deaths\u{0020}-\u{0020}Genia\u{0020}knew\u{0020}that\u{0020}people\u{0020}were\u{0020}bound\u{0020}to\u{0020}die,\u{0020}but\u{0020}she\u{0020}believed\u{0020}that\u{0020}people\u{0020}should\u{0020}die\u{0020}in\u{0020}happiness.\u{0020}So\u{0020}she\u{0020}became\u{0020}a\u{0020}doctor,\u{0020}a\u{0020}battlefield\u{0020}doctor\u{0020}who\u{0020}was\u{0020}always\u{0020}accompanied\u{0020}by\u{0020}death.\n\n\n\nGenia\u{0020}became\u{0020}a\u{0020}soldier\u{0020}and\u{0020}served\u{0020}in\u{0020}the\u{0020}army\u{0020}in\u{0020}the\u{0020}Katya\u{0020}region.\u{0020}She\u{0020}didn't\u{0020}care\u{0020}who\u{0020}the\u{0020}army\u{0020}was\u{0020}fighting\u{0020}against\u{0020}or\u{0020}whom\u{0020}she\u{0020}was\u{0020}serving.\u{0020}Her\u{0020}only\u{0020}duty\u{0020}was\u{0020}to\u{0020}save\u{0020}all\u{0020}the\u{0020}wounded\u{0020}and\u{0020}sick\u{0020}patients\u{0020}sent\u{0020}to\u{0020}her.\n\n\n\nShe\u{0020}met\u{0020}her\u{0020}future\u{0020}partner\u{0020}and\u{0020}future\u{0020}captain,\u{0020}namely\u{0020}Lydia\u{0020}Lee\u{0020}Ustinovich,\u{0020}for\u{0020}the\u{0020}first\u{0020}time\u{0020}on\u{0020}the\u{0020}operating\u{0020}table\u{0020}in\u{0020}the\u{0020}emergency\u{0020}room.\u{0020}Excessive\u{0020}blood\u{0020}loss,\u{0020}severe\u{0020}hypothermia,\u{0020}cessation\u{0020}of\u{0020}breathing,\u{0020}weak\u{0020}heartbeats,\u{0020}and\u{0020}dilated\u{0020}pupils.\u{0020}At\u{0020}that\u{0020}time,\u{0020}Lydia\u{0020}was\u{0020}already\u{0020}halfway\u{0020}to\u{0020}a\u{0020}dead\u{0020}person.\n\n\n\nThe\u{0020}fateful\u{0020}Lydia\u{0020}was\u{0020}saved\u{0020}by\u{0020}Genia\u{0020}and\u{0020}retrieved\u{0020}her\u{0020}life\u{0020}from\u{0020}the\u{0020}clutches\u{0020}of\u{0020}death.\u{0020}After\u{0020}the\u{0020}surgery,\u{0020}Genia\u{0020}received\u{0020}an\u{0020}order\u{0020}from\u{0020}her\u{0020}superiors\u{0020}and\u{0020}was\u{0020}responsible\u{0020}for\u{0020}Lydia's\u{0020}rehabilitation\u{0020}treatment.\n\n\n\nDuring\u{0020}the\u{0020}rehabilitation\u{0020}period,\u{0020}Genia\u{0020}accepted\u{0020}Lydia's\u{0020}invitation\u{0020}and\u{0020}joined\u{0020}the\u{0020}AEGIS\u{0020}Katya\u{0020}Branch\u{0020}with\u{0020}her.", "0", "0", "0", "0", 13005, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[630503] = {630503, 1000, "\u{0020}\u{0020}When\u{0020}\"Snow\u{0020}Owl\"\u{0020}was\u{0020}established,\u{0020}some\u{0020}people\u{0020}once\u{0020}worried\u{0020}that\u{0020}there\u{0020}would\u{0020}be\u{0020}fierce\u{0020}contradictions\u{0020}between\u{0020}Genia\u{0020}and\u{0020}Lydia.\n\n\n\nBecause\u{0020}Genia\u{0020}hates\u{0020}Katya\u{0020}so\u{0020}much\u{0020}that\u{0020}she\u{0020}even\u{0020}wishes\u{0020}Katya\u{0020}to\u{0020}disappear.\n\n\n\nThis\u{0020}makes\u{0020}people\u{0020}worry\u{0020}that\u{0020}Genia\u{0020}and\u{0020}Lydia\u{0020}will\u{0020}have\u{0020}differences\u{0020}and\u{0020}quarrels\u{0020}on\u{0020}issues\u{0020}related\u{0020}to\u{0020}Katya.\n\n\n\nMoreover,\u{0020}Genia\u{0020}herself\u{0020}is\u{0020}a\u{0020}person\u{0020}with\u{0020}a\u{0020}tough\u{0020}attitude\u{0020}and\u{0020}a\u{0020}leadership\u{0020}temperament.\u{0020}It\u{0020}is\u{0020}only\u{0020}natural\u{0020}for\u{0020}such\u{0020}a\u{0020}person\u{0020}to\u{0020}argue\u{0020}with\u{0020}others\u{0020}because\u{0020}of\u{0020}insisting\u{0020}on\u{0020}her\u{0020}own\u{0020}opinions.\n\n\n\nHowever,\u{0020}the\u{0020}situation\u{0020}those\u{0020}people\u{0020}worried\u{0020}about\u{0020}did\u{0020}not\u{0020}occur.\u{0020}Genia\u{0020}was\u{0020}competent\u{0020}in\u{0020}the\u{0020}role\u{0020}assigned\u{0020}to\u{0020}her\u{0020}in\u{0020}the\u{0020}team\u{0020}and\u{0020}did\u{0020}not\u{0020}have\u{0020}a\u{0020}conflict\u{0020}with\u{0020}Lydia,\u{0020}who\u{0020}was\u{0020}the\u{0020}team\u{0020}leader.\n\n\n\nObviously,\u{0020}the\u{0020}reason\u{0020}why\u{0020}those\u{0020}people\u{0020}had\u{0020}such\u{0020}meaningless\u{0020}worries\u{0020}was\u{0020}that\u{0020}they\u{0020}had\u{0020}no\u{0020}idea\u{0020}at\u{0020}all\u{0020}what\u{0020}kind\u{0020}of\u{0020}person\u{0020}Genia\u{0020}was.\n\n\n\n\"I\u{0020}have\u{0020}heard\u{0020}of\u{0020}you.\u{0020}To\u{0020}be\u{0020}honest,\u{0020}I\u{0020}don't\u{0020}like\u{0020}you.\u{0020}But\u{0020}don't\u{0020}worry.\u{0020}Anyway,\u{0020}I\u{0020}will\u{0020}never\u{0020}give\u{0020}up\u{0020}on\u{0020}you.\u{0020}Saving\u{0020}patients\u{0020}is\u{0020}a\u{0020}doctor's\u{0020}duty.\"\n\n\n\nShe\u{0020}once\u{0020}said\u{0020}this\u{0020}to\u{0020}the\u{0020}dying\u{0020}Lydia.\n\n\n\nPersonal\u{0020}likes\u{0020}and\u{0020}dislikes\u{0020}are\u{0020}insignificant\u{0020}in\u{0020}front\u{0020}of\u{0020}a\u{0020}doctor.", "0", "0", "0", "0", 13005, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[630504] = {630504, 2000, "\u{0020}\u{0020}\"She\u{0020}said\u{0020}to\u{0020}you,\u{0020}'Katya\u{0020}is\u{0020}a\u{0020}very\u{0020}beautiful\u{0020}place'?\"\n\n\n\nIn\u{0020}the\u{0020}vast\u{0020}white\u{0020}snowstorm,\u{0020}she\u{0020}is\u{0020}strolling.\n\n\n\nWith\u{0020}each\u{0020}of\u{0020}her\u{0020}steps,\u{0020}she\u{0020}left\u{0020}\"heavy\"\u{0020}footprints\u{0020}on\u{0020}the\u{0020}snow.\n\n\n\nAt\u{0020}least,\u{0020}humans\u{0020}of\u{0020}normal\u{0020}size\u{0020}could\u{0020}not\u{0020}leave\u{0020}such\u{0020}obvious\u{0020}traces\u{0020}on\u{0020}this\u{0020}land.\n\n\n\n\"Perhaps\u{0020}what\u{0020}she\u{0020}said\u{0020}is\u{0020}true,\u{0020}but\u{0020}it\u{0020}has\u{0020}nothing\u{0020}to\u{0020}do\u{0020}with\u{0020}me.\"\n\n\n\nThis\u{0020}land\u{0020}has\u{0020}taken\u{0020}away\u{0020}too\u{0020}many\u{0020}lives.\n\n\n\nShe\u{0020}is\u{0020}still\u{0020}loathing\u{0020}this\u{0020}snowfield.\n\n\n\n\"I\u{0020}will\u{0020}not\u{0020}stop\u{0020}fighting\u{0020}until\u{0020}the\u{0020}snow\u{0020}in\u{0020}Katya\u{0020}melts.\"\n\n\n\n\"From\u{0020}the\u{0020}day\u{0020}my\u{0020}grandma\u{0020}passed\u{0020}away,\u{0020}I\u{0020}have\u{0020}decided.\"\n\n\n\n\"Then\u{0020}what\u{0020}about\u{0020}you?\u{0020}Navigator,\u{0020}why\u{0020}do\u{0020}you\u{0020}fight?\"", "0", "0", "0", "0", 13005, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[630600] = {630600, 0, "[Name]\u{0020}Hotarugusa\n[B-Day]\u{0020}Sep\u{0020}19\n[Compatability\u{0020}Rate]\u{0020}85％\n[Height]\u{0020}36m\n[Squad]\u{0020}Shingyou\u{0020}House\n[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n[Interest]\u{0020}Looking\u{0020}at\u{0020}her\u{0020}cats\u{0020}through\u{0020}surveillance\u{0020}cameras.", "0", "0", "0", "0", 13006, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}莹草\n[B-Day]\u{1000}9月19日\n[幻化核心适格率]\u{1000}85％\n[Height]\u{1000}36m\n[部队]\u{1000}心经屋\n\u{1000}\u{00A0}[隶属]\u{1000}九州总部\n[Interest]\u{1000}在监控里看自己养的猫猫"},
[630601] = {630601, 100, "\u{0020}\u{0020}She's\u{0020}the\u{0020}least\u{0020}experienced\u{0020}member\u{0020}in\u{0020}Shingyou\u{0020}House.\n\nUnlike\u{0020}Hanakotoba\u{0020}who\u{0020}grew\u{0020}up\u{0020}in\u{0020}a\u{0020}shrine,\u{0020}and\u{0020}unlike\u{0020}Kokorokami\u{0020}who\u{0020}chose\u{0020}her\u{0020}duty\u{0020}in\u{0020}this\u{0020}turbulent\u{0020}world.\n\nHotarugusa\u{0020}didn't\u{0020}join\u{0020}Shingyou\u{0020}House\u{0020}as\u{0020}a\u{0020}destined\u{0020}fate,\u{0020}it\u{0020}was\u{0020}unexpected.\n\nBut\u{0020}still,\u{0020}although\u{0020}she\u{0020}joined\u{0020}Shingyou\u{0020}House\u{0020}by\u{0020}accident,\u{0020}she\u{0020}is\u{0020}the\u{0020}most\u{0020}reliable\u{0020}member\u{0020}of\u{0020}the\u{0020}squad.\u{0020}Unlike\u{0020}her\u{0020}captain,\u{0020}who\u{0020}often\u{0020}appears\u{0020}in\u{0020}front\u{0020}of\u{0020}the\u{0020}public,\u{0020}Hotarugusa\u{0020}usually\u{0020}supports\u{0020}her\u{0020}squad\u{0020}as\u{0020}an\u{0020}advisor\u{0020}in\u{0020}the\u{0020}background.\n\n\"Because\u{0020}of\u{0020}Hotarugusa,\u{0020}I\u{0020}can\u{0020}do\u{0020}my\u{0020}job\u{0020}without\u{0020}being\u{0020}disturbed.\"\u{0020}This\u{0020}is\u{0020}the\u{0020}proof\u{0020}from\u{0020}her\u{0020}captain.\n\nHowever,\u{0020}\"Big\u{0020}Sis\u{0020}Hotarugusa\"\u{0020}isn't\u{0020}always\u{0020}friendly\u{0020}and\u{0020}kind.\u{0020}When\u{0020}asked\u{0020}about\u{0020}her\u{0020}age,\u{0020}she\u{0020}will\u{0020}become\u{0020}an\u{0020}unreasonable\u{0020}devil.", "0", "0", "0", "0", 13006, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}她是心经屋中，资历最浅的人。\n\u{1000}\u{1000}既不像花语那样，从小在神社长大，也不像心纸那样，在乱世中临危受命。\n\u{1000}\u{1000}她的加入没有前两人那样的必然性，她只是出于偶然才加入心经屋。\n\u{1000}\u{1000}尽管如此，因为一次偶然事件加入心经屋的她，却是心经屋中最可靠的人。她不像心经屋的队长那样常常出现在人前，更多的时候以幕僚的形式，默默支撑着心经屋。\n\u{1000}\u{1000}正是因为有小莹草的存在，老身才能安心地履行自己的职责——心经屋队长的话，便是最好的证明。\n\u{1000}\u{1000}不过，对待他人友善且富有爱心的莹草大姐姐，被人问到关于年龄的话题时，就会化身失去理智的魔鬼。"},
[630602] = {630602, 500, "\u{0020}\u{0020}Although\u{0020}Hotarugusa\u{0020}is\u{0020}the\u{0020}least\u{0020}experienced\u{0020}member\u{0020}in\u{0020}her\u{0020}squad,\u{0020}that\u{0020}doesn't\u{0020}mean\u{0020}she's\u{0020}bad\u{0020}at\u{0020}the\u{0020}job\u{0020}as\u{0020}a\u{0020}miko.\n\nIn\u{0020}fact,\u{0020}she\u{0020}has\u{0020}been\u{0020}working\u{0020}in\u{0020}another\u{0020}shrine\u{0020}as\u{0020}a\u{0020}miko.\u{0020}Regarding\u{0020}the\u{0020}knowledge\u{0020}on\u{0020}traditional\u{0020}mikos,\u{0020}perhaps\u{0020}she\u{0020}is\u{0020}the\u{0020}best\u{0020}among\u{0020}her\u{0020}squadmates.\n\n…So\u{0020}what\u{0020}exactly\u{0020}is\u{0020}her\u{0020}age…no,\u{0020}never\u{0020}mind.\n\nAccording\u{0020}to\u{0020}herself,\u{0020}she\u{0020}met\u{0020}Kokorokami\u{0020}in\u{0020}a\u{0020}rainy\u{0020}night.\u{0020}Back\u{0020}then\u{0020}she\u{0020}was\u{0020}homeless,\u{0020}because\u{0020}Sins\u{0020}destroyed\u{0020}her\u{0020}shrine\u{0020}where\u{0020}she\u{0020}lived\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\u{0020}She\u{0020}fell\u{0020}down\u{0020}by\u{0020}Kokorokami\u{0020}due\u{0020}to\u{0020}fatigue,\u{0020}and\u{0020}when\u{0020}she\u{0020}woke\u{0020}up\u{0020}again,\u{0020}she\u{0020}was\u{0020}in\u{0020}an\u{0020}unknown\u{0020}bed.\u{0020}It\u{0020}was\u{0020}Kokorokami\u{0020}who\u{0020}gave\u{0020}her\u{0020}shelter.\n\nWhen\u{0020}she\u{0020}learnt\u{0020}the\u{0020}difficulties\u{0020}in\u{0020}Shingyou\u{0020}House,\u{0020}she\u{0020}didn't\u{0020}left\u{0020}Kokorokami\u{0020}alone.\u{0020}She\u{0020}stayed\u{0020}and\u{0020}helped\u{0020}Kokorokami\u{0020}to\u{0020}develop\u{0020}\"Shingyou\u{0020}House\''\u{0020}as\u{0020}a\u{0020}brand.\u{0020}You\u{0020}are\u{0020}right,\u{0020}maintaining\u{0020}a\u{0020}shrine\u{0020}is\u{0020}rather\u{0020}a\u{0020}way\u{0020}of\u{0020}income\u{0020}than\u{0020}a\u{0020}belief\u{0020}for\u{0020}her.\n\nHotarugusa\u{0020}has\u{0020}a\u{0020}completely\u{0020}different\u{0020}opinion\u{0020}on\u{0020}gods\u{0020}and\u{0020}beliefs\u{0020}from\u{0020}Kokorokami.\u{0020}Because\u{0020}of\u{0020}that,\u{0020}they\u{0020}are\u{0020}actually\u{0020}complementary\u{0020}to\u{0020}each\u{0020}other.\u{0020}As\u{0020}Kokorokami\u{0020}and\u{0020}\"Shingyou\u{0020}House\"\u{0020}became\u{0020}more\u{0020}and\u{0020}more\u{0020}well\u{0020}known,\u{0020}Hotarugusa\u{0020}did\u{0020}the\u{0020}planning\u{0020}with\u{0020}her\u{0020}efforts.\n\n\"Actually,\u{0020}I\u{0020}wasn't\u{0020}expected\u{0020}to\u{0020}stay\u{0020}here\u{0020}for\u{0020}this\u{0020}long.\u{0020}But\u{0020}that\u{0020}old\u{0020}man\u{0020}asked\u{0020}me\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}the\u{0020}girls,\u{0020}and\u{0020}I\u{0020}accepted\u{0020}and\u{0020}stayed.\u{0020}Well,\u{0020}it\u{0020}ain't\u{0020}bad.\"\n\nMaybe\u{0020}Hotarugusa\u{0020}is\u{0020}not\u{0020}the\u{0020}most\u{0020}professional\u{0020}miko,\u{0020}but\u{0020}surely\u{0020}she\u{0020}is\u{0020}the\u{0020}miko\u{0020}who\u{0020}fits\u{0020}Shingyou\u{0020}House\u{0020}the\u{0020}most.\u{0020}Without\u{0020}her,\u{0020}Kokorokami\u{0020}and\u{0020}Shingyou\u{0020}House\u{0020}would\u{0020}have\u{0020}more\u{0020}difficulties\u{0020}in\u{0020}achieving\u{0020}their\u{0020}ideals.", "0", "0", "0", "0", 13006, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}莹草是心经屋中资历最浅的成员，这并不意味着她不熟悉巫女这项\"职业\"。\n\u{1000}\u{1000}事实上，她曾经在另一家神社里以职业巫女的身份就职过，如果论对传统巫女的了解，她大概是心经屋中最了解\"巫女\"是什么的人了。\n\u{1000}\u{1000}……所以说她的年龄到底…不，还是不提这个了。\n\u{1000}\u{1000}根据莹草本人的描述，她与心纸是在一个雨夜相遇的。那时的她居无定所，一直以来定居的神社在原罪的脚下化为了废墟。精疲力尽的她倒在了心纸身边，醒来的时候，她已经躺在一张陌生的床上了——是心纸收留了无家可归的她。\n\u{1000}\u{1000}在了解了心经屋的处境后，她没有抛下心纸离去，而是选择留下来，协助心纸建设\"心经屋\"这个招牌——是的，比起信仰，她更像是把经营神社看做一个维持生计的手段。\n\u{1000}\u{1000}从对待神灵及信仰的态度上来看，莹草显然是和心纸截然相反的。也正是因为相反，所以两人才能互补。在心纸及心经屋的影响力逐渐扩大的背后，有着不断为此出谋划策的莹草在努力。\n\u{1000}\u{1000}\"其实，我本来不想留在这里这么久的。不过，那位老爷爷拜托我照顾她们，所以我才留下来了——现在想想，到也不坏吧。\"\n\u{1000}\u{1000}莹草或许不是最纯粹的巫女，但她绝对是最适合心经屋的巫女。如果没有她的存在，无论是心经屋，还是心纸，都会在追逐自己理想的道路上走不少弯路吧。"},
[630603] = {630603, 1000, "\u{0020}\u{0020}When\u{0020}people\u{0020}think\u{0020}of\u{0020}\"Shingyou\u{0020}House\",\u{0020}they\u{0020}mostly\u{0020}think\u{0020}about\u{0020}\"Kokorokami\",\u{0020}but\u{0020}the\u{0020}communication\u{0020}between\u{0020}Shingyou\u{0020}House\u{0020}and\u{0020}AEGIS\u{0020}is\u{0020}mostly\u{0020}done\u{0020}by\u{0020}Hotarugusa,\u{0020}who\u{0020}works\u{0020}in\u{0020}the\u{0020}background.\n\nFrom\u{0020}some\u{0020}sources,\u{0020}we\u{0020}learnt\u{0020}a\u{0020}fact:\u{0020}Hotarugusa's\u{0020}negotiation\u{0020}skill\u{0020}is\u{0020}too\u{0020}sophisticated\u{0020}for\u{0020}her\u{0020}age.\u{0020}She\u{0020}uses\u{0020}the\u{0020}popularity\u{0020}of\u{0020}\"Shingyou\u{0020}House\"\u{0020}as\u{0020}an\u{0020}advantage,\u{0020}and\u{0020}holds\u{0020}her\u{0020}initiative\u{0020}firmly\u{0020}in\u{0020}negotiations.\n\nAEGIS\u{0020}made\u{0020}their\u{0020}biggest\u{0020}concession,\u{0020}which\u{0020}let\u{0020}\"Shingyou\u{0020}House\"\u{0020}join\u{0020}AEGIS\u{0020}as\u{0020}administrators.\u{0020}Weirdly,\u{0020}this\u{0020}proposal\u{0020}was\u{0020}rejected\u{0020}by\u{0020}Kokorokami.\n\nAfter\u{0020}that,\u{0020}\"Shingyou\u{0020}House\"\u{0020}was\u{0020}formally\u{0020}established.\n\n\"If\u{0020}that\u{0020}kid\u{0020}likes\u{0020}the\u{0020}idea,\u{0020}just\u{0020}let\u{0020}her\u{0020}do\u{0020}it.\u{0020}As\u{0020}long\u{0020}as\u{0020}she's\u{0020}happy.\"", "0", "0", "0", "0", 13006, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}尽管当人们提起\"心经屋\"的时候，更多的是想起老人口吻的少女心纸，但在与艾吉斯的接触中，负责与艾吉斯沟通的人，实际上是在幕后工作的莹草。\n\u{1000}\u{1000}从旁人的叙述里，我们了解到一个事实：莹草的交涉手段有着超出她年龄的成熟，她牢牢抓住心经屋的影响力这一点作为己方的优势，丝毫不肯在谈判中让出主动权。\n\u{1000}\u{1000}艾吉斯一度做出最大的退步，同意让\"心经屋\"以管理者的身份加入艾吉斯。但奇怪的是，这项提议却被心纸驳回了。\n\u{1000}\u{1000}在这之后，便诞生了被人们熟知的\"心经屋\"部队。\n\u{1000}\u{1000}\"那孩子喜欢这样的话，就按照她喜欢的做吧。只要她开心，大姐姐就无憾啦~\""},
[630604] = {630604, 2000, "\u{0020}\u{0020}Hotarugusa\u{0020}already\u{0020}got\u{0020}used\u{0020}to\u{0020}the\u{0020}feeling\u{0020}of\u{0020}being\u{0020}a\u{0020}dependant\u{0020}of\u{0020}someone,\u{0020}needed\u{0020}by\u{0020}someone.\n\nFor\u{0020}her,\u{0020}taking\u{0020}care\u{0020}of\u{0020}her\u{0020}juniors\u{0020}is\u{0020}almost\u{0020}like\u{0020}an\u{0020}instinct.\n\n\"Well,\u{0020}being\u{0020}taken\u{0020}care\u{0020}of\u{0020}by\u{0020}someone\u{0020}else,\u{0020}also\u{0020}feels\u{0020}great.\"\n\nOn\u{0020}the\u{0020}battlefield,\u{0020}leaning\u{0020}on\u{0020}an\u{0020}unfinished\u{0020}building,\u{0020}she\u{0020}stares\u{0020}at\u{0020}her\u{0020}Navigator\u{0020}far\u{0020}away\u{0020}while\u{0020}having\u{0020}a\u{0020}short\u{0020}break.\n\nShe\u{0020}sees\u{0020}her\u{0020}Navigator\u{0020}is\u{0020}overlooking\u{0020}the\u{0020}battlefield,\u{0020}biting\u{0020}his\u{0020}lip\u{0020}while\u{0020}commanding.\n\n\"So,\u{0020}I\u{0020}have\u{0020}to\u{0020}carry\u{0020}on,\u{0020}to\u{0020}thank\u{0020}him\u{0020}in\u{0020}return.\"\n\nAs\u{0020}she\u{0020}says\u{0020}that,\u{0020}she\u{0020}joins\u{0020}the\u{0020}battle\u{0020}once\u{0020}again.", "0", "0", "0", "0", 13006, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}莹草已经习惯了被某个人依靠，被某个人需要的感觉。\n\u{1000}\u{1000}对她来说，照顾年幼的人已经成了她近乎本能的习惯。\n\u{1000}\u{1000}\"——不过，被人照顾的感觉，其实也不赖嘛。\"\n\u{1000}\u{1000}战场上，倚靠着施工中的大楼，在短暂的喘息时间，她凝视着远方的领航。\n\u{1000}\u{1000}领航俯瞰战场，咬着嘴唇指挥的模样映入她的视网膜，\n\u{1000}\u{1000}\"那么，我也得努力下，好好回报下他才行。\"\n\u{1000}\u{1000}这么说着，她再度投入战斗中。"},
[630700] = {630700, 0, "[Name]:\u{0020}Type\u{0020}T\n[Date\u{0020}of\u{0020}Birth]:\u{0020}May\u{0020}18\n[Compatibility\u{0020}Rate]:\u{0020}93%\n[Height\u{0020}after\u{0020}Gigantification]:\u{0020}38m\n[Squad]:\u{0020}Specter\n[Affiliation]:\u{0020}Maya\u{0020}Branch\n[Likes]:\u{0020}Acquiring\u{0020}everything\u{0020}about\u{0020}humanity", "0", "0", "0", "0", 13007, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[630701] = {630701, 100, "Log\u{0020}1:\n\u{3000}\u{3000}T\u{0020}is\u{0020}the\u{0020}latest\u{0020}prototype\u{0020}unit\u{0020}developed\u{0020}to\u{0020}date.\u{0020}She\u{0020}has\u{0020}not\u{0020}been\u{0020}formally\u{0020}deployed\u{0020}in\u{0020}combat,\u{0020}so\u{0020}no\u{0020}battle\u{0020}records\u{0020}exist\u{0020}in\u{0020}the\u{0020}database.\u{0020}However,\u{0020}it\u{0020}is\u{0020}certain\u{0020}that\u{0020}her\u{0020}performance,\u{0020}powered\u{0020}by\u{0020}cutting-edge\u{0020}technology,\u{0020}far\u{0020}surpasses\u{0020}that\u{0020}of\u{0020}D-b2.\n\u{3000}\u{3000}\u{0020}She\u{0020}is\u{0020}scheduled\u{0020}to\u{0020}be\u{0020}deployed\u{0020}in\u{0020}operations\u{0020}against\u{0020}the\u{0020}Sins.\u{0020}Yet,\u{0020}to\u{0020}prevent\u{0020}another\u{0020}tragedy\u{0020}like\u{0020}the\u{0020}Specter\u{0020}Incident,\u{0020}an\u{0020}AI\u{0020}rebellion,\u{0020}AEGIS\u{0020}has\u{0020}decided\u{0020}not\u{0020}to\u{0020}equip\u{0020}her\u{0020}with\u{0020}any\u{0020}weapon\u{0020}systems\u{0020}until\u{0020}her\u{0020}safety\u{0020}and\u{0020}controllability\u{0020}are\u{0020}fully\u{0020}verified.\n\u{3000}\u{3000}\u{0020}Unlike\u{0020}D-b2,\u{0020}T\u{0020}demonstrates\u{0020}a\u{0020}near-human\u{0020}sense\u{0020}of\u{0020}desire\u{0020}and\u{0020}intelligence,\u{0020}showing\u{0020}a\u{0020}particularly\u{0020}strong\u{0020}interest\u{0020}in\u{0020}learning.", "0", "0", "0", "0", 13007, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[630702] = {630702, 500, "Log\u{0020}2:\n\u{3000}\u{3000}In\u{0020}a\u{0020}sense,\u{0020}T\u{0020}might\u{0020}be\u{0020}considered\u{0020}a\u{0020}\"sister\"\u{0020}to\u{0020}D-b2,\u{0020}though\u{0020}using\u{0020}such\u{0020}a\u{0020}human\u{0020}term\u{0020}may\u{0020}not\u{0020}be\u{0020}entirely\u{0020}appropriate.\u{0020}Still,\u{0020}no\u{0020}better\u{0020}word\u{0020}comes\u{0020}to\u{0020}mind.\u{0020}\"Daughter\"?\u{0020}No,\u{0020}that\u{0020}feels\u{0020}even\u{0020}less\u{0020}fitting.\n\u{3000}\u{3000}\u{0020}The\u{0020}\"Simulant\u{0020}Persona\"\u{0020}is\u{0020}a\u{0020}specialized\u{0020}chip\u{0020}created\u{0020}by\u{0020}digitally\u{0020}copying\u{0020}a\u{0020}human\u{0020}personality\u{0020}into\u{0020}a\u{0020}program.\u{0020}Typically,\u{0020}units\u{0020}of\u{0020}the\u{0020}same\u{0020}model\u{0020}use\u{0020}persona\u{0020}chips\u{0020}derived\u{0020}from\u{0020}the\u{0020}same\u{0020}individual.\n\u{3000}\u{3000}\u{0020}After\u{0020}the\u{0020}Specter\u{0020}Incident,\u{0020}nearly\u{0020}all\u{0020}Simulant\u{0020}Personas\u{0020}initiated\u{0020}self-destruction\u{0020}protocols.\u{0020}The\u{0020}sole\u{0020}survivor\u{0020}was\u{0020}D-b2\u{0020}with\u{0020}awareness\u{0020}you've\u{0020}met,\u{0020}Navigator.\n\u{3000}\u{3000}\u{0020}T's\u{0020}persona\u{0020}chip\u{0020}is\u{0020}an\u{0020}advanced\u{0020}AI\u{0020}built\u{0020}on\u{0020}what\u{0020}we\u{0020}had\u{0020}for\u{0020}D's,\u{0020}designed\u{0020}to\u{0020}better\u{0020}replicate\u{0020}human\u{0020}personality.\u{0020}It\u{0020}remains\u{0020}a\u{0020}Simulant\u{0020}Persona,\u{0020}only\u{0020}improved\u{0020}over\u{0020}time\u{0020}through\u{0020}technical\u{0020}progress.\u{0020}Yet,\u{0020}precisely\u{0020}because\u{0020}it's\u{0020}built\u{0020}upon\u{0020}the\u{0020}previous\u{0020}generation,\u{0020}referring\u{0020}to\u{0020}T\u{0020}as\u{0020}D's\u{0020}\"sister\"\u{0020}feels\u{0020}strangely\u{0020}fitting.\n\u{3000}\u{3000}\u{0020}We\u{0020}once\u{0020}asked\u{0020}the\u{0020}development\u{0020}team\u{0020}in\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}if\u{0020}the\u{0020}new\u{0020}Simulant\u{0020}Persona\u{0020}used\u{0020}data\u{0020}from\u{0020}the\u{0020}same\u{0020}person\u{0020}as\u{0020}D.\n\u{3000}\u{3000}\u{0020}\"No,\"\u{0020}their\u{0020}representative\u{0020}said.\u{0020}\"We\u{0020}didn't\u{0020}use\u{0020}any\u{0020}human\u{0020}personality\u{0020}data\u{0020}at\u{0020}all.\"", "0", "0", "0", "0", 13007, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[630703] = {630703, 1000, "Log\u{0020}3:\n\u{3000}\u{3000}The\u{0020}development\u{0020}of\u{0020}the\u{0020}new\u{0020}Simulant\u{0020}Persona\u{0020}faced\u{0020}numerous\u{0020}obstacles\u{0020}from\u{0020}the\u{0020}start.\u{0020}Yet,\u{0020}with\u{0020}covert\u{0020}support\u{0020}from\u{0020}Mr.\u{0020}Odyssey,\u{0020}the\u{0020}project\u{0020}proceeded,\u{0020}culminating\u{0020}in\u{0020}the\u{0020}birth\u{0020}of\u{0020}T.\n\u{3000}\u{3000}\u{0020}The\u{0020}original\u{0020}Simulant\u{0020}Persona\u{0020}was\u{0020}abandoned\u{0020}due\u{0020}to\u{0020}functional\u{0020}flaws,\u{0020}high\u{0020}costs,\u{0020}and\u{0020}difficulties\u{0020}in\u{0020}mass\u{0020}production.\u{0020}But\u{0020}now,\u{0020}with\u{0020}the\u{0020}abolition\u{0020}of\u{0020}the\u{0020}Secondary\u{0020}Persona\u{0020}system\u{0020}and\u{0020}breakthroughs\u{0020}in\u{0020}manufacturing,\u{0020}a\u{0020}new\u{0020}generation\u{0020}has\u{0020}finally\u{0020}emerged.\n\u{3000}\u{3000}\u{0020}The\u{0020}unusually\u{0020}short\u{0020}development\u{0020}cycle,\u{0020}from\u{0020}project\u{0020}approval\u{0020}to\u{0020}T's\u{0020}completion,\u{0020}makes\u{0020}us\u{0020}suspect\u{0020}that\u{0020}the\u{0020}Maya\u{0020}Branch\u{0020}or\u{0020}Odyssey\u{0020}Heavy\u{0020}Industries\u{0020}had\u{0020}been\u{0020}preparing\u{0020}long\u{0020}in\u{0020}advance.", "0", "0", "0", "0", 13007, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[630704] = {630704, 2000, "\u{3000}\u{3000}She\u{0020}possesses\u{0020}a\u{0020}childlike\u{0020}curiosity,\u{0020}yet\u{0020}she\u{0020}wasn't\u{0020}given\u{0020}human\u{0020}emotions.\n\u{3000}\u{3000}\u{0020}She\u{0020}sits\u{0020}quietly\u{0020}in\u{0020}her\u{0020}cradle,\u{0020}gazing\u{0020}down\u{0020}at\u{0020}the\u{0020}world\u{0020}below,\n\u{3000}\u{3000}\u{0020}pondering\u{0020}her\u{0020}purpose.\n\u{3000}\u{3000}Why\u{0020}was\u{0020}she\u{0020}created?\n\u{3000}\u{3000}\u{0020}To\u{0020}protect\u{0020}humanity?\n\u{3000}\u{3000}\u{0020}Or\u{0020}is\u{0020}there\u{0020}another\u{0020}purpose?\n\u{3000}\u{3000}\u{0020}She\u{0020}doesn't\u{0020}know.\n\u{3000}\u{3000}\u{0020}\"I\u{0020}want\u{0020}to\u{0020}understand...\u{0020}Why\u{0020}was\u{0020}I\u{0020}born?\u{0020}Why\u{0020}have\u{0020}I\u{0020}come\u{0020}into...\u{0020}a\u{0020}world\u{0020}that\u{0020}rejects\u{0020}me?\"", "0", "0", "0", "0", 13007, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[630800] = {630800, 0, "[Name]\u{0020}Isabella\n[B-Day]\u{0020}Jan\u{0020}28\n[Compatability\u{0020}Rate]\u{0020}89%\n[Height]\u{0020}38m\n[Squad]\u{0020}Dragon\u{0020}Knights\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Make\u{0020}a\u{0020}detailed\u{0020}schedule", "0", "0", "0", "0", 13008, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[630801] = {630801, 100, "\u{0020}\"I\u{0020}was\u{0020}chosen\u{0020}by\u{0020}heaven\u{0020}and\u{0020}destined\u{0020}to\u{0020}step\u{0020}onto\u{0020}the\u{0020}battlefield.\"\n\nWhen\u{0020}they\u{0020}first\u{0020}met,\u{0020}Isabella\u{0020}emphasized\u{0020}this.\u{0020}She\u{0020}believes\u{0020}in\u{0020}the\u{0020}so-called\u{0020}fatalism\u{0020}and\u{0020}thinks\u{0020}that\u{0020}she\u{0020}was\u{0020}born\u{0020}to\u{0020}be\u{0020}a\u{0020}driver\u{0020}fighting\u{0020}on\u{0020}the\u{0020}battlefield.\u{0020}She\u{0020}firmly\u{0020}believes\u{0020}that\u{0020}only\u{0020}in\u{0020}this\u{0020}way\u{0020}can\u{0020}she\u{0020}prevent\u{0020}Sin\u{0020}from\u{0020}devouring\u{0020}the\u{0020}entire\u{0020}world.\n\nAlthough\u{0020}such\u{0020}an\u{0020}idea\u{0020}seems\u{0020}somewhat\u{0020}arrogant\u{0020}and\u{0020}foolish,\u{0020}in\u{0020}fact,\u{0020}as\u{0020}long\u{0020}as\u{0020}you\u{0020}get\u{0020}along\u{0020}with\u{0020}her,\u{0020}you\u{0020}will\u{0020}find\u{0020}that\u{0020}she\u{0020}is\u{0020}not\u{0020}as\u{0020}conceited\u{0020}as\u{0020}you\u{0020}imagine.\u{0020}She\u{0020}does\u{0020}have\u{0020}something\u{0020}to\u{0020}be\u{0020}proud\u{0020}of.\n\nIsabella\u{0020}has\u{0020}an\u{0020}almost\u{0020}abnormal\u{0020}ability\u{0020}to\u{0020}plan\u{0020}her\u{0020}time\u{0020}and\u{0020}self-control.\u{0020}First,\u{0020}she\u{0020}spent\u{0020}a\u{0020}lot\u{0020}of\u{0020}energy\u{0020}dividing\u{0020}her\u{0020}schedule\u{0020}down\u{0020}to\u{0020}every\u{0020}minute,\u{0020}and\u{0020}after\u{0020}that,\u{0020}she\u{0020}completed\u{0020}all\u{0020}these\u{0020}\"missions\"\u{0020}planned\u{0020}by\u{0020}herself\u{0020}day\u{0020}after\u{0020}day\u{0020}for\u{0020}ten\u{0020}years.\u{0020}The\u{0020}result\u{0020}forged\u{0020}by\u{0020}this\u{0020}ascetic\u{0020}life\u{0020}is\u{0020}Isabella's\u{0020}strong\u{0020}body\u{0020}and\u{0020}spirit.\u{0020}With\u{0020}these,\u{0020}she\u{0020}became\u{0020}the\u{0020}leading\u{0020}driver\u{0020}in\u{0020}Danube.\n\nMorely,\u{0020}she,\u{0020}who\u{0020}believes\u{0020}in\u{0020}fatalism\u{0020}and\u{0020}has\u{0020}extremely\u{0020}high\u{0020}requirements\u{0020}for\u{0020}herself,\u{0020}never\u{0020}dictates\u{0020}the\u{0020}lifestyle\u{0020}of\u{0020}others,\u{0020}and\u{0020}she\u{0020}will\u{0020}highly\u{0020}praise\u{0020}those\u{0020}who\u{0020}hope\u{0020}to\u{0020}change\u{0020}their\u{0020}destiny\u{0020}through\u{0020}efforts.", "0", "0", "0", "0", 13008, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[630802] = {630802, 500, "\u{0020}It\u{0020}is\u{0020}said\u{0020}that\u{0020}on\u{0020}the\u{0020}night\u{0020}of\u{0020}Isabella's\u{0020}birth,\u{0020}the\u{0020}constellation\u{0020}symbolizing\u{0020}\"destiny\"\u{0020}appeared\u{0020}in\u{0020}the\u{0020}sky.\u{0020}Her\u{0020}poor\u{0020}but\u{0020}devout\u{0020}parents\u{0020}firmly\u{0020}believed\u{0020}that\u{0020}there\u{0020}must\u{0020}be\u{0020}a\u{0020}connection\u{0020}between\u{0020}these\u{0020}two\u{0020}things.\u{0020}Since\u{0020}then,\u{0020}they\u{0020}have\u{0020}raised\u{0020}Isabella\u{0020}as\u{0020}a\u{0020}child\u{0020}of\u{0020}God.\u{0020}Young\u{0020}Isabella\u{0020}was\u{0020}like\u{0020}a\u{0020}blank\u{0020}sheet\u{0020}of\u{0020}paper.\u{0020}Under\u{0020}the\u{0020}influence\u{0020}of\u{0020}her\u{0020}parents.\n\nShe\u{0020}also\u{0020}accepted\u{0020}her\u{0020}own\u{0020}persona\u{0020}of\u{0020}\"the\u{0020}Chosen\u{0020}One\".\n\nHowever,\u{0020}as\u{0020}Isabella\u{0020}grew\u{0020}up,\u{0020}as\u{0020}the\u{0020}amount\u{0020}of\u{0020}information\u{0020}she\u{0020}received\u{0020}gradually\u{0020}became\u{0020}wider\u{0020}and\u{0020}more\u{0020}extensive,\u{0020}especially\u{0020}after\u{0020}going\u{0020}through\u{0020}school\u{0020}education,\u{0020}she\u{0020}also\u{0020}slowly\u{0020}began\u{0020}to\u{0020}think.\n\nPerhaps\u{0020}there\u{0020}are\u{0020}no\u{0020}gods\u{0020}in\u{0020}this\u{0020}world,\u{0020}and\u{0020}perhaps\u{0020}I\u{0020}am\u{0020}not\u{0020}a\u{0020}child\u{0020}of\u{0020}the\u{0020}gods\u{0020}at\u{0020}all...\u{0020}Unless\u{0020}I\u{0020}can\u{0020}witness\u{0020}that\u{0020}miracle\u{0020}(constellation)\u{0020}with\u{0020}my\u{0020}own\u{0020}eyes\u{0020}and\u{0020}find\u{0020}my\u{0020}given\u{0020}mission...\n\nThen,\u{0020}five\u{0020}years\u{0020}ago,\u{0020}miracles\u{0020}and\u{0020}disasters\u{0020}befell\u{0020}Isabella's\u{0020}hometown\u{0020}simultaneously.\n\nSin\u{0020}set\u{0020}everything\u{0020}ablaze.\u{0020}The\u{0020}town\u{0020}where\u{0020}Isabella\u{0020}lived\u{0020}was\u{0020}swallowed\u{0020}by\u{0020}the\u{0020}flames.\u{0020}The\u{0020}thick\u{0020}smoke\u{0020}filled\u{0020}the\u{0020}sky.\u{0020}Even\u{0020}in\u{0020}the\u{0020}early\u{0020}morning,\u{0020}the\u{0020}sky\u{0020}was\u{0020}still\u{0020}shrouded\u{0020}in\u{0020}darkness.\u{0020}On\u{0020}the\u{0020}black\u{0020}street,\u{0020}a\u{0020}girl\u{0020}stained\u{0020}red\u{0020}with\u{0020}blood\u{0020}lay\u{0020}on\u{0020}her\u{0020}back,\u{0020}waiting\u{0020}for\u{0020}death.\n\nIn\u{0020}this\u{0020}world,\u{0020}there\u{0020}are\u{0020}no\u{0020}gods\u{0020}and\u{0020}no\u{0020}so-called\u{0020}destiny.\n\nSelf-mockingly,\u{0020}she\u{0020}reached\u{0020}out\u{0020}her\u{0020}hand\u{0020}towards\u{0020}the\u{0020}sky.\n\n--\u{0020}The\u{0020}story\u{0020}of\u{0020}that\u{0020}star\u{0020}was\u{0020}indeed\u{0020}deceiving\u{0020}me,\u{0020}wasn't\u{0020}it?\n\nBut,\u{0020}the\u{0020}sky\u{0020}responded\u{0020}to\u{0020}the\u{0020}girl.\n\nSoon,\u{0020}one...\u{0020}no,\u{0020}several\u{0020}shining\u{0020}stars\u{0020}streaked\u{0020}across\u{0020}the\u{0020}sky.\u{0020}The\u{0020}drivers\u{0020}from\u{0020}the\u{0020}Danube\u{0020}headquarters\u{0020}dispelled\u{0020}the\u{0020}darkness\u{0020}and\u{0020}saved\u{0020}the\u{0020}girl.\u{0020}Their\u{0020}figures\u{0020}were\u{0020}thus\u{0020}deeply\u{0020}imprinted\u{0020}in\u{0020}the\u{0020}girl's\u{0020}mind.\u{0020}Two\u{0020}years\u{0020}later,\u{0020}Isabella,\u{0020}a\u{0020}survivor\u{0020}of\u{0020}that\u{0020}incident,\u{0020}finally\u{0020}left\u{0020}the\u{0020}rehabilitation\u{0020}hospital\u{0020}and\u{0020}embarked\u{0020}on\u{0020}a\u{0020}new\u{0020}life...\n\nAfter\u{0020}joining\u{0020}AEGIS,\u{0020}Isabella\u{0020}was\u{0020}assigned\u{0020}to\u{0020}the\u{0020}unit\u{0020}named\u{0020}Dragon\u{0020}Knights.\u{0020}Other\u{0020}drivers\u{0020}in\u{0020}this\u{0020}unit\u{0020}would\u{0020}continuously\u{0020}absorb\u{0020}the\u{0020}energy\u{0020}within\u{0020}Sin\u{0020}during\u{0020}battles\u{0020}to\u{0020}enhance\u{0020}their\u{0020}Compatability\u{0020}Rate\u{0020}and\u{0020}combat\u{0020}power.\u{0020}However,\u{0020}the\u{0020}corresponding\u{0020}cost\u{0020}was\u{0020}that\u{0020}if\u{0020}they\u{0020}couldn't\u{0020}vent\u{0020}the\u{0020}excess\u{0020}energy,\u{0020}they\u{0020}might\u{0020}fall\u{0020}into\u{0020}frenzy.\n\nBut\u{0020}as\u{0020}a\u{0020}driver\u{0020}piloting\u{0020}an\u{0020}auxiliary\u{0020}AVG,\u{0020}Isabella\u{0020}was\u{0020}special.\u{0020}Since\u{0020}she\u{0020}couldn't\u{0020}absorb\u{0020}the\u{0020}energy\u{0020}from\u{0020}the\u{0020}enemy\u{0020}through\u{0020}attacks,\u{0020}apart\u{0020}from\u{0020}treating,\u{0020}her\u{0020}most\u{0020}important\u{0020}task\u{0020}was\u{0020}to\u{0020}share\u{0020}the\u{0020}excess\u{0020}energy\u{0020}for\u{0020}her\u{0020}teammates.\u{0020}It\u{0020}could\u{0020}be\u{0020}said\u{0020}that\u{0020}she\u{0020}was\u{0020}the\u{0020}final\u{0020}insurance\u{0020}in\u{0020}this\u{0020}special\u{0020}combat\u{0020}system.", "0", "0", "0", "0", 13008, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[630803] = {630803, 1000, "\u{0020}\u{0020}What\u{0020}has\u{0020}been\u{0020}supporting\u{0020}her\u{0020}in\u{0020}the\u{0020}battle\u{0020}is\u{0020}neither\u{0020}the\u{0020}longing\u{0020}for\u{0020}a\u{0020}better\u{0020}life\u{0020}nor\u{0020}the\u{0020}hatred\u{0020}for\u{0020}Sin,\u{0020}but\u{0020}something\u{0020}like\u{0020}a\u{0020}sense\u{0020}of\u{0020}destiny.\u{0020}Or,\u{0020}just\u{0020}as\u{0020}we\u{0020}need\u{0020}to\u{0020}eat\u{0020}and\u{0020}sleep\u{0020}to\u{0020}survive,\u{0020}Isabella\u{0020}believes\u{0020}that\u{0020}she\u{0020}must\u{0020}fight\u{0020}against\u{0020}Sin\u{0020}as\u{0020}a\u{0020}driver\u{0020}to\u{0020}survive.\n\nIsabella\u{0020}relies\u{0020}on\u{0020}war\u{0020}more\u{0020}than\u{0020}anyone\u{0020}else\u{0020}and\u{0020}desires\u{0020}battle\u{0020}more\u{0020}than\u{0020}any\u{0020}driver...\u{0020}And\u{0020}because\u{0020}of\u{0020}her\u{0020}childhood\u{0020}experiences,\u{0020}this\u{0020}kind\u{0020}of\u{0020}thinking\u{0020}of\u{0020}hers\u{0020}is\u{0020}almost\u{0020}impossible\u{0020}to\u{0020}be\u{0020}shaken.\n\nHowever,\u{0020}your\u{0020}task\u{0020}is\u{0020}to\u{0020}end\u{0020}the\u{0020}war.\u{0020}That\u{0020}is\u{0020}to\u{0020}say,\u{0020}in\u{0020}the\u{0020}end,\u{0020}you\u{0020}will\u{0020}personally\u{0020}\"end\"\u{0020}the\u{0020}fate\u{0020}of\u{0020}this\u{0020}young\u{0020}girl.\u{0020}Then,\u{0020}when\u{0020}that\u{0020}moment\u{0020}comes,\u{0020}will\u{0020}she\u{0020}stand\u{0020}on\u{0020}the\u{0020}opposite\u{0020}side\u{0020}of\u{0020}you?", "0", "0", "0", "0", 13008, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[630804] = {630804, 2000, "\u{0020}\u{0020}In\u{0020}the\u{0020}deep\u{0020}of\u{0020}the\u{0020}night,\u{0020}the\u{0020}meteor\u{0020}above\u{0020}the\u{0020}city\u{0020}is\u{0020}actually\u{0020}a\u{0020}speeding\u{0020}maiden.\n\nEvery\u{0020}night,\u{0020}she\u{0020}would\u{0020}search\u{0020}for\u{0020}something\u{0020}like\u{0020}this\u{0020}in\u{0020}the\u{0020}night\u{0020}sky.\n\n\"...How\u{0020}long\u{0020}has\u{0020}it\u{0020}been\u{0020}since\u{0020}we\u{0020}saw\u{0020}new\u{0020}stars?\"\n\nThe\u{0020}maiden\u{0020}landed\u{0020}by\u{0020}the\u{0020}lake,\u{0020}took\u{0020}off\u{0020}her\u{0020}thick\u{0020}armor,\u{0020}and\u{0020}inserted\u{0020}her\u{0020}fair\u{0020}feet\u{0020}into\u{0020}the\u{0020}cold\u{0020}lake\u{0020}water.\n\nThe\u{0020}spray\u{0020}of\u{0020}waves\u{0020}disturbed\u{0020}the\u{0020}entire\u{0020}lake\u{0020}surface,\u{0020}but\u{0020}the\u{0020}maiden's\u{0020}heart\u{0020}calmed\u{0020}down\u{0020}because\u{0020}of\u{0020}it.\n\nDuring\u{0020}the\u{0020}long\u{0020}battle,\u{0020}her\u{0020}heart\u{0020}had\u{0020}actually\u{0020}wavered.\n\nShe\u{0020}gradually\u{0020}realized\u{0020}that\u{0020}no\u{0020}one\u{0020}was\u{0020}born\u{0020}for\u{0020}war.\n\nHowever,\u{0020}to\u{0020}bring\u{0020}about\u{0020}another\u{0020}transformation,\u{0020}she\u{0020}still\u{0020}needs\u{0020}an\u{0020}opportunity.\n\nOr\u{0020}rather,\u{0020}she\u{0020}needs\u{0020}a\u{0020}star\u{0020}who\u{0020}can\u{0020}light\u{0020}a\u{0020}new\u{0020}path\u{0020}for\u{0020}her.", "0", "0", "0", "0", 13008, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
