[630901] = {630901, 100, "\u{0020}\u{0020}It\u{0020}seems\u{0020}that\u{0020}Aevati\u{0020}is\u{0020}like\u{0020}a\u{0020}fairy\u{0020}princess\u{0020}walking\u{0020}out\u{0020}of\u{0020}a\u{0020}fairy\u{0020}tale.\u{0020}She\u{0020}has\u{0020}a\u{0020}pair\u{0020}of\u{0020}bright\u{0020}eyes\u{0020}like\u{0020}colorful\u{0020}lakes\u{0020}and\u{0020}a\u{0020}pair\u{0020}of\u{0020}slender\u{0020}and\u{0020}agile\u{0020}ears.\u{0020}Everyone\u{0020}who\u{0020}has\u{0020}seen\u{0020}her\u{0020}projection\u{0020}is\u{0020}moved\u{0020}by\u{0020}her\u{0020}beauty\u{0020}and\u{0020}hopes\u{0020}to\u{0020}see\u{0020}her\u{0020}in\u{0020}person.\u{0020}Unfortunately,\u{0020}Aevati\u{0020}is\u{0020}neither\u{0020}human\u{0020}nor\u{0020}on\u{0020}our\u{0020}familiar\u{0020}home\u{0020}planet.\u{0020}She\u{0020}is\u{0020}a\u{0020}space\u{0020}traveler\u{0020}from\u{0020}the\u{0020}planet\u{0020}Midyr\u{0020}and\u{0020}is\u{0020}now\u{0020}traveling\u{0020}interstellar\u{0020}with\u{0020}three\u{0020}of\u{0020}her\u{0020}kind\u{0020}in\u{0020}the\u{0020}\"Shumia\"\u{0020}interstellar\u{0020}spaceship.\n\nLike\u{0020}all\u{0020}Midyr\u{0020}people,\u{0020}Aevati\u{0020}is\u{0020}very\u{0020}friendly\u{0020}to\u{0020}humans.\u{0020}In\u{0020}daily\u{0020}communication,\u{0020}not\u{0020}only\u{0020}does\u{0020}she\u{0020}not\u{0020}put\u{0020}herself\u{0020}in\u{0020}a\u{0020}superior\u{0020}position,\u{0020}but\u{0020}she\u{0020}even\u{0020}uses\u{0020}honorific\u{0020}titles\u{0020}to\u{0020}address\u{0020}the\u{0020}drivers\u{0020}she\u{0020}works\u{0020}with.\u{0020}After\u{0020}learning\u{0020}about\u{0020}the\u{0020}suffering\u{0020}of\u{0020}other\u{0020}species,\u{0020}she\u{0020}also\u{0020}shows\u{0020}genuine\u{0020}sadness\u{0020}and\u{0020}concern.", "0", "0", "0", "0", 13009, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}仿佛是从童话故事中走出的精灵公主一般，艾伊瓦蒂拥有一双如同彩色湖泊般的明亮双眸以及一对纤细灵动的耳朵。凡是见过她投影的人都无不为之美貌所动容，并希望亲眼见上她一面。不过可惜的是，艾伊瓦蒂既不是人类也不在我们熟悉的母星上。她是来自米狄尔星球的一名太空旅者，现在正与同族的三人驾驶着\"修米娅\"号星际飞船进行星际旅行。\n\u{1000}\u{1000}和所有的米狄尔人一样，艾伊瓦蒂对人类非常友善，在日常交流中她非但不会将自己置于上位，甚至还会使用尊称来称呼与自己共事的驾驶员。在了解了其他物种所遭受的苦难后，她也会流露出真切的悲伤与关怀。"},
[630902] = {630902, 500, "\u{0020}\u{0020}Interstellar\u{0020}travel\u{0020}is\u{0020}not\u{0020}only\u{0020}the\u{0020}act\u{0020}of\u{0020}the\u{0020}Midyr\u{0020}people\u{0020}exploring\u{0020}the\u{0020}world,\u{0020}but\u{0020}also\u{0020}their\u{0020}way\u{0020}of\u{0020}survival.\u{0020}People\u{0020}on\u{0020}this\u{0020}planet\u{0020}will\u{0020}be\u{0020}sent\u{0020}on\u{0020}interstellar\u{0020}spacecraft\u{0020}to\u{0020}start\u{0020}their\u{0020}journey\u{0020}since\u{0020}birth\u{0020}and\u{0020}only\u{0020}return\u{0020}to\u{0020}their\u{0020}home\u{0020}planet\u{0020}to\u{0020}reproduce\u{0020}the\u{0020}next\u{0020}generation\u{0020}and\u{0020}meet\u{0020}the\u{0020}end\u{0020}of\u{0020}their\u{0020}lives\u{0020}when\u{0020}they\u{0020}reach\u{0020}adulthood.\u{0020}This\u{0020}cycle\u{0020}repeats\u{0020}itself,\u{0020}just\u{0020}like\u{0020}the\u{0020}migratory\u{0020}salmon,\u{0020}continuing\u{0020}life\u{0020}in\u{0020}the\u{0020}form\u{0020}of\u{0020}separation...\n\nAevati\u{0020}is\u{0020}the\u{0020}youngest\u{0020}crew\u{0020}member\u{0020}on\u{0020}the\u{0020}Shumia,\u{0020}so\u{0020}the\u{0020}job\u{0020}assigned\u{0020}to\u{0020}her\u{0020}is\u{0020}the\u{0020}easiest\u{0020}logistical\u{0020}work.\u{0020}With\u{0020}the\u{0020}help\u{0020}of\u{0020}AI\u{0020}and\u{0020}robots,\u{0020}the\u{0020}work\u{0020}that\u{0020}requires\u{0020}Aevati\u{0020}to\u{0020}do\u{0020}is\u{0020}actually\u{0020}very\u{0020}little,\u{0020}which\u{0020}also\u{0020}gives\u{0020}her\u{0020}time\u{0020}to\u{0020}study\u{0020}the\u{0020}civilizations\u{0020}of\u{0020}other\u{0020}races.\n\nDuring\u{0020}the\u{0020}voyage,\u{0020}if\u{0020}the\u{0020}Midyr\u{0020}people\u{0020}discover\u{0020}other\u{0020}advanced\u{0020}civilizations,\u{0020}they\u{0020}will\u{0020}actively\u{0020}send\u{0020}signals.\u{0020}If\u{0020}the\u{0020}other\u{0020}party\u{0020}can\u{0020}receive\u{0020}and\u{0020}successfully\u{0020}decipher\u{0020}them,\u{0020}the\u{0020}Midyr\u{0020}people\u{0020}will\u{0020}propose\u{0020}a\u{0020}request\u{0020}to\u{0020}maintain\u{0020}long-term\u{0020}contact\u{0020}and\u{0020}exchange\u{0020}information.\u{0020}Thus,\u{0020}during\u{0020}the\u{0020}long\u{0020}journey,\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}civilization\u{0020}information\u{0020}of\u{0020}alien\u{0020}races\u{0020}has\u{0020}been\u{0020}stored\u{0020}on\u{0020}the\u{0020}Shumia.\u{0020}Eventually,\u{0020}during\u{0020}the\u{0020}process\u{0020}of\u{0020}studying\u{0020}these\u{0020}civilizations,\u{0020}Aevati\u{0020}gradually\u{0020}understood\u{0020}the\u{0020}concept\u{0020}of\u{0020}\"life\u{0020}and\u{0020}death,\u{0020}separation\u{0020}and\u{0020}reunion\".\u{0020}Such\u{0020}she\u{0020}cherished\u{0020}the\u{0020}time\u{0020}spent\u{0020}with\u{0020}her\u{0020}companions\u{0020}more\u{0020}and\u{0020}more,\u{0020}and\u{0020}gradually\u{0020}began\u{0020}to\u{0020}dread\u{0020}the\u{0020}arrival\u{0020}of\u{0020}the\u{0020}day\u{0020}of\u{0020}return.\u{0020}Ultimately,\u{0020}during\u{0020}the\u{0020}process\u{0020}of\u{0020}studying\u{0020}these\u{0020}civilizations,\u{0020}Aevati\u{0020}gradually\u{0020}understood\u{0020}the\u{0020}concept\u{0020}of\u{0020}\"life\u{0020}and\u{0020}death,\u{0020}separation\u{0020}and\u{0020}reunion\".\u{0020}Such\u{0020}she\u{0020}cherished\u{0020}the\u{0020}time\u{0020}spent\u{0020}with\u{0020}her\u{0020}companions\u{0020}more\u{0020}and\u{0020}more,\u{0020}and\u{0020}gradually\u{0020}began\u{0020}to\u{0020}dread\u{0020}the\u{0020}arrival\u{0020}of\u{0020}the\u{0020}day\u{0020}of\u{0020}return.\n\nOf\u{0020}course,\u{0020}during\u{0020}the\u{0020}research\u{0020}process,\u{0020}what\u{0020}impressed\u{0020}her\u{0020}the\u{0020}most\u{0020}was\u{0020}humans,\u{0020}because\u{0020}in\u{0020}human\u{0020}mythology,\u{0020}there\u{0020}was\u{0020}the\u{0020}concept\u{0020}of\u{0020}\"heaven\",\u{0020}which\u{0020}was\u{0020}a\u{0020}place\u{0020}where\u{0020}people\u{0020}could\u{0020}be\u{0020}reunited\u{0020}after\u{0020}death.\u{0020}It\u{0020}was\u{0020}the\u{0020}first\u{0020}time\u{0020}Aevati\u{0020}had\u{0020}heard\u{0020}of\u{0020}such\u{0020}a\u{0020}place.\u{0020}Although\u{0020}the\u{0020}so-called\u{0020}heaven\u{0020}only\u{0020}existed\u{0020}in\u{0020}legends,\u{0020}it\u{0020}also\u{0020}calmed\u{0020}her\u{0020}uneasy\u{0020}heart\u{0020}a\u{0020}little.\n\nBut\u{0020}to\u{0020}Aevati's\u{0020}surprise,\u{0020}their\u{0020}journey\u{0020}will\u{0020}also\u{0020}come\u{0020}to\u{0020}an\u{0020}end\u{0020}soon...", "0", "0", "0", "0", 13009, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}星际旅行，并不光光是米狄尔星人探索世界的行为，更是他们的生存方式。这个星球上的人自从出生起便会被送上星际飞船展开旅行，只有成年后才会回到母星繁育下一代并迎来自己生命的终结，周而复始，如同洄游的鲑鱼一般，以别离的形式进行着生命的延续……\u{1000}\u{1000}艾伊瓦蒂是修米娅号上年纪最小的船员，所以交给她的工作也是最为轻松的后勤工作。借由AI和机器人的帮助，需要艾伊瓦蒂亲手完成的工作其实非常少，这也让她有了可以去研究其他种族文明的时间。\u{1000}\u{1000}没错，在航行的过程中如果米狄尔人发现了其他的高等文明便会主动发射电子脉冲信号，如果对方能够接受到并成功破译的话，米狄尔人便会提出长期保持联络并交换信息的请求，就这样在漫长的旅途中修米娅号上储备了大量外星种族的文明信息。最终，在研究这些文明的过程中，艾伊瓦蒂逐渐明白了\"生死离别\"的概念，这样的她愈发珍惜和同伴们共同相处的时光，并渐渐开始畏惧起返航之日的到来。\u{1000}\u{1000}当然，在研究过程中，最让她印象深刻的当属人类，因为在人类的神话中存在着\"天堂\"这一概念，那是人们在死后得以团聚的地方。艾伊瓦蒂还是第一次听说有这种地方，虽然所谓的天堂只存在于传说中，但这也让她一直不安的心稍稍安定了下来。\u{1000}\u{1000}但是出乎艾伊瓦蒂的预料的是，她们的旅途也将在不久之后结束……"},
[630903] = {630903, 1000, "\u{0020}\u{0020}The\u{0020}last\u{0020}contact\u{0020}and\u{0020}information\u{0020}exchange\u{0020}with\u{0020}the\u{0020}Shumia\u{0020}was\u{0020}sixty\u{0020}years\u{0020}ago.\u{0020}Now,\u{0020}there\u{0020}are\u{0020}no\u{0020}space\u{0020}travelers\u{0020}called\u{0020}\"Midyrian\"\u{0020}in\u{0020}the\u{0020}universe\u{0020}anymore.\u{0020}Their\u{0020}home\u{0020}planet\u{0020}for\u{0020}reproduction\u{0020}has\u{0020}also\u{0020}been\u{0020}destroyed\u{0020}by\u{0020}Sin.\u{0020}Aevati\u{0020}has\u{0020}probably\u{0020}disappeared\u{0020}somewhere\u{0020}in\u{0020}the\u{0020}dark\u{0020}universe\u{0020}along\u{0020}with\u{0020}her\u{0020}companions...\n\nOriginally,\u{0020}that\u{0020}was\u{0020}the\u{0020}end,\u{0020}but\u{0020}the\u{0020}appearance\u{0020}of\u{0020}the\u{0020}synesthetes\u{0020}brought\u{0020}a\u{0020}turning\u{0020}point\u{0020}to\u{0020}this\u{0020}event.\n\nThe\u{0020}information\u{0020}left\u{0020}by\u{0020}the\u{0020}Midyrians,\u{0020}or\u{0020}rather,\u{0020}their\u{0020}language\u{0020}contains\u{0020}\"consciousness\u{0020}and\u{0020}past\u{0020}memories\".\u{0020}Through\u{0020}the\u{0020}connection\u{0020}with\u{0020}the\u{0020}Transformation\u{0020}Core\u{0020}by\u{0020}synesthesia\u{0020}ability,\u{0020}their\u{0020}bodies\u{0020}can\u{0020}be\u{0020}constructed\u{0020}out\u{0020}of\u{0020}thin\u{0020}air.\u{0020}Aevati\u{0020}and\u{0020}them\u{0020}were\u{0020}thus\u{0020}\"awakened\"\u{0020}again.\n\nAfter\u{0020}learning\u{0020}about\u{0020}Sin,\u{0020}everyone\u{0020}on\u{0020}the\u{0020}Shumia\u{0020}ultimately\u{0020}chose\u{0020}to\u{0020}temporarily\u{0020}stay\u{0020}on\u{0020}Earth\u{0020}in\u{0020}the\u{0020}form\u{0020}of\u{0020}virtual\u{0020}projections\u{0020}to\u{0020}help\u{0020}humans\u{0020}jointly\u{0020}fight\u{0020}against\u{0020}Sin.", "0", "0", "0", "0", 13009, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}最后一次和修米娅号接触并交换信息已经是六十年前的事了，现在的宇宙中已经没有被称为\"米狄尔人\"的太空旅者了，她们用作繁衍生息的母星也被原罪毁灭了。艾伊瓦蒂，大概已经和同伴们一同消失在黑暗宇宙的某处了………\u{1000}\u{1000}本来，这就是结局了，但是通感者的出现为此次事件带来了转机。\u{1000}\u{1000}米狄尔人留下的信息，或者说她们的语言中包含了\"意识与过去的记忆\"，借由通感能力与幻化核心连结完成后便能凭空构建出她们的身体。艾伊瓦蒂她们就这样被再次\"唤醒\"了。\u{1000}\u{1000}在得知了有关原罪的事情之后，修米娅号的大家最终选择以虚拟投影的形态暂时留在地球，帮助人类共同对抗原罪。"},
[630904] = {630904, 2000, "\u{0020}\u{0020}The\u{0020}sun\u{0020}and\u{0020}the\u{0020}moon\u{0020}rotate,\u{0020}and\u{0020}countless\u{0020}celestial\u{0020}bodies\u{0020}have\u{0020}constantly\u{0020}brushed\u{0020}past\u{0020}the\u{0020}horizon\u{0020}over\u{0020}the\u{0020}decades.\n\nThe\u{0020}girl\u{0020}who\u{0020}once\u{0020}roamed\u{0020}among\u{0020}them\u{0020}has\u{0020}finally\u{0020}reached\u{0020}the\u{0020}moment\u{0020}of\u{0020}intersection\u{0020}with\u{0020}it.\n\nLeaving\u{0020}deep\u{0020}footprints\u{0020}on\u{0020}the\u{0020}soft\u{0020}ground,\u{0020}this\u{0020}moment\u{0020}belongs\u{0020}only\u{0020}to\u{0020}the\u{0020}girl\u{0020}for\u{0020}a\u{0020}while.\n\n\"It's\u{0020}been\u{0020}a\u{0020}long\u{0020}time\u{0020}since\u{0020}I\u{0020}walked\u{0020}so\u{0020}steadily\u{0020}like\u{0020}this.\"\n\nThe\u{0020}girl\u{0020}tilted\u{0020}her\u{0020}head\u{0020}to\u{0020}look\u{0020}at\u{0020}the\u{0020}navigator\u{0020}who\u{0020}accompanied\u{0020}her\u{0020}by\u{0020}her\u{0020}side.\n\n\"Navigator,\u{0020}do\u{0020}you\u{0020}know?\"\n\n\"In\u{0020}our\u{0020}culture,\u{0020}when\u{0020}the\u{0020}Midyr\u{0020}people\u{0020}land,\n\nIt\u{0020}is\u{0020}the\u{0020}time\u{0020}when\u{0020}one\u{0020}encounters\u{0020}the\u{0020}most\u{0020}important\u{0020}person\u{0020}in\u{0020}their\u{0020}life...\"", "0", "0", "0", "0", 13009, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}日月轮转，无数星体在数十年间不断与地平线擦肩而过。\u{1000}\u{1000}曾经遨游其中的少女，终于迎来了与之交汇之时。\u{1000}\u{1000}在松软的土地上留下深深的脚印，此时此刻是只属于少女的片刻时光。\u{1000}\u{1000}\"好久没有像这样脚踏实地地行走了呢。\"\u{1000}\u{1000}少女歪头看向肩头上那位陪伴在她左右的领航。\u{1000}\u{1000}\"领航，你知道吗？\"\u{1000}\u{1000}\"在我们的文化中，当米狄尔人落地之时，\u{1000}\u{1000}便是与其生命中最重要的人邂逅之时……\""},
[631000] = {631000, 0, "[Name]\u{0020}Mizo\n[B-Day]\u{0020}Nov\u{0020}22\n[Compatability\u{0020}Rate]\u{0020}55％\n[Height]\u{0020}36m\n[Squad]\u{0020}Mammalian\n[Affiliation]\u{0020}Maya\n[Interest]\u{0020}Frozen\u{0020}tofu,\u{0020}sophisticated\u{0020}guns.", "0", "0", "0", "0", 13010, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[631001] = {631001, 100, "\u{0020}\u{0020}Mizo\u{0020}is\u{0020}the\u{0020}most\u{0020}affable\u{0020}one\u{0020}in\u{0020}her\u{0020}squad.\u{0020}Compared\u{0020}to\u{0020}introvertive\u{0020}Rou\u{0020}and\u{0020}in\u{0020}imperturbable\u{0020}Shirogane,\u{0020}she\u{0020}cares\u{0020}more\u{0020}about\u{0020}people's\u{0020}attitude\u{0020}towards\u{0020}them.\u{0020}Almost\u{0020}everything\u{0020}related\u{0020}to\u{0020}their\u{0020}squad\u{0020}has\u{0020}to\u{0020}communicate\u{0020}with\u{0020}Mizo,\u{0020}no\u{0020}matter\u{0020}battle\u{0020}orders\u{0020}or\u{0020}supplies.\n\nMizo\u{0020}is\u{0020}also\u{0020}one\u{0020}of\u{0020}the\u{0020}representatives\u{0020}of\u{0020}the\u{0020}Etan\u{0020}people,\u{0020}she\u{0020}never\u{0020}misses\u{0020}a\u{0020}single\u{0020}conference\u{0020}about\u{0020}security\u{0020}and\u{0020}quality\u{0020}of\u{0020}Etans'\u{0020}lives.\u{0020}During\u{0020}the\u{0020}discussions,\u{0020}Miss\u{0020}Mizo\u{0020}can\u{0020}always\u{0020}provide\u{0020}her\u{0020}constructive\u{0020}opinions,\u{0020}and\u{0020}effectively\u{0020}prevents\u{0020}conflicts.\n\nMizo's\u{0020}professionalism\u{0020}as\u{0020}a\u{0020}medic\u{0020}is\u{0020}well-acknowledged\u{0020}by\u{0020}the\u{0020}public,\u{0020}her\u{0020}personality\u{0020}and\u{0020}versatility\u{0020}are\u{0020}also\u{0020}outstanding\u{0020}among\u{0020}AEGIS.\n\nBut\u{0020}from\u{0020}the\u{0020}chemically\u{0020}assay\u{0020}of\u{0020}hair\u{0020}samples\u{0020}found\u{0020}in\u{0020}an\u{0020}archive\u{0020}room\u{0020}which\u{0020}have\u{0020}things\u{0020}stolen,\u{0020}we\u{0020}know\u{0020}that\u{0020}Mizo\u{0020}masters\u{0020}much\u{0020}more\u{0020}skills\u{0020}than\u{0020}we\u{0020}expected.", "0", "0", "0", "0", 13010, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[631002] = {631002, 500, "\u{0020}\u{0020}Because\u{0020}Mizo's\u{0020}hairs\u{0020}were\u{0020}found\u{0020}in\u{0020}that\u{0020}archive\u{0020}room,\u{0020}the\u{0020}department\u{0020}of\u{0020}intelligence\u{0020}detained\u{0020}her\u{0020}for\u{0020}information.\n\nMizo\u{0020}was\u{0020}calm\u{0020}during\u{0020}the\u{0020}process,\u{0020}without\u{0020}attempts\u{0020}to\u{0020}escape\u{0020}and\u{0020}resisting.\u{0020}So,\u{0020}our\u{0020}methods\u{0020}prepared\u{0020}for\u{0020}her\u{0020}were\u{0020}unnecessary.\u{0020}Although\u{0020}she\u{0020}was\u{0020}so\u{0020}obedient,\u{0020}the\u{0020}information\u{0020}she\u{0020}told\u{0020}us\u{0020}was\u{0020}really\u{0020}stunning.\n\nAccording\u{0020}to\u{0020}her,\u{0020}just\u{0020}like\u{0020}other\u{0020}Etans,\u{0020}she\u{0020}was\u{0020}assigned\u{0020}a\u{0020}\"role\",\u{0020}and\u{0020}that\u{0020}was\u{0020}a\u{0020}special\u{0020}one:\u{0020}she's\u{0020}an\u{0020}agent\u{0020}in\u{0020}the\u{0020}department\u{0020}of\u{0020}intelligence.\n\nMizo\u{0020}was\u{0020}taken\u{0020}into\u{0020}Eta's\u{0020}secret\u{0020}services\u{0020}in\u{0020}a\u{0020}young\u{0020}age,\u{0020}where\u{0020}she\u{0020}learnt\u{0020}special\u{0020}skills\u{0020}for\u{0020}agents.\u{0020}Indeed,\u{0020}her\u{0020}talent\u{0020}was\u{0020}excellent.\u{0020}She\u{0020}became\u{0020}a\u{0020}senior\u{0020}agent\u{0020}in\u{0020}her\u{0020}team\u{0020}when\u{0020}she\u{0020}was\u{0020}young.\n\nBut\u{0020}in\u{0020}her\u{0020}missions\u{0020}she\u{0020}learnt\u{0020}a\u{0020}lot\u{0020}of\u{0020}secrets,\u{0020}including\u{0020}some\u{0020}cruel\u{0020}facts,\u{0020}which\u{0020}ordeals\u{0020}her\u{0020}principles.\n\nWhen\u{0020}she\u{0020}knew\u{0020}that\u{0020}Eta's\u{0020}rulers\u{0020}genocided\u{0020}large\u{0020}numbers\u{0020}of\u{0020}civilians\u{0020}with\u{0020}\"Inferior\u{0020}genes\"\u{0020}in\u{0020}order\u{0020}to\u{0020}optimize\u{0020}their\u{0020}population's\u{0020}genes,\u{0020}she\u{0020}couldn't\u{0020}take\u{0020}it\u{0020}any\u{0020}longer.\n\nShe\u{0020}tried\u{0020}to\u{0020}reveal\u{0020}all\u{0020}of\u{0020}these,\u{0020}and\u{0020}save\u{0020}those\u{0020}people\u{0020}who\u{0020}were\u{0020}being\u{0020}persecuted,\u{0020}but\u{0020}she\u{0020}failed\u{0020}every\u{0020}time.\n\nShe\u{0020}felt\u{0020}disappointment,\u{0020}so\u{0020}she\u{0020}absconded\u{0020}from\u{0020}her\u{0020}agency,\u{0020}the\u{0020}place\u{0020}where\u{0020}she\u{0020}was\u{0020}raised.\u{0020}She\u{0020}went\u{0020}to\u{0020}a\u{0020}remote\u{0020}town,\u{0020}concealed\u{0020}her\u{0020}identity\u{0020}and\u{0020}started\u{0020}a\u{0020}new\u{0020}life.\u{0020}But,\u{0020}only\u{0020}after\u{0020}a\u{0020}few\u{0020}years,\u{0020}Sins\u{0020}invaded\u{0020}Eta.\u{0020}There\u{0020}were\u{0020}only\u{0020}a\u{0020}few\u{0020}survivors\u{0020}in\u{0020}the\u{0020}town,\u{0020}and\u{0020}she\u{0020}led\u{0020}them\u{0020}aboard\u{0020}a\u{0020}spacecraft.\u{0020}At\u{0020}last,\u{0020}those\u{0020}survivors\u{0020}came\u{0020}to\u{0020}Earth…\n\nSo\u{0020}called\u{0020}\"Agents\",\u{0020}are\u{0020}just\u{0020}like\u{0020}some\u{0020}ghosts\u{0020}wandering\u{0020}in\u{0020}the\u{0020}dark\u{0020}side\u{0020}of\u{0020}their\u{0020}society.\u{0020}They\u{0020}have\u{0020}to\u{0020}face\u{0020}those\u{0020}evil\u{0020}creatures\u{0020}who\u{0020}live\u{0020}in\u{0020}the\u{0020}darkness,\u{0020}and\u{0020}those\u{0020}monsters\u{0020}that\u{0020}take\u{0020}the\u{0020}kindness\u{0020}in\u{0020}our\u{0020}humanity\u{0020}as\u{0020}their\u{0020}food.\u{0020}The\u{0020}endings\u{0020}of\u{0020}those\u{0020}agents\u{0020}are\u{0020}either\u{0020}being\u{0020}assimilated\u{0020}into\u{0020}those\u{0020}sordid\u{0020}creatures,\u{0020}or\u{0020}escape\u{0020}before\u{0020}being\u{0020}eaten\u{0020}by\u{0020}the\u{0020}darkness.\n\nPerhaps,\u{0020}because\u{0020}they\u{0020}took\u{0020}so\u{0020}much\u{0020}effort\u{0020}to\u{0020}escape\u{0020}from\u{0020}the\u{0020}darkness,\u{0020}they\u{0020}are\u{0020}more\u{0020}frightened\u{0020}to\u{0020}be\u{0020}covered\u{0020}in\u{0020}darkness\u{0020}again\u{0020}compared\u{0020}to\u{0020}others.\n\n\"For\u{0020}investigating\u{0020}the\u{0020}dark\u{0020}side\u{0020}of\u{0020}Aegis\u{0020}to\u{0020}make\u{0020}sure\u{0020}it\u{0020}won't\u{0020}harm\u{0020}Etans.\"\u{0020}She\u{0020}explained\u{0020}what\u{0020}she\u{0020}has\u{0020}done\u{0020}in\u{0020}the\u{0020}archive\u{0020}room.\u{0020}From\u{0020}her\u{0020}words\u{0020}we\u{0020}can\u{0020}feel\u{0020}her\u{0020}incredulousness\u{0020}and\u{0020}bias\u{0020}towards\u{0020}Aegis.\u{0020}Although\u{0020}I\u{0020}can't\u{0020}promise\u{0020}that\u{0020}Aegis\u{0020}doesn't\u{0020}have\u{0020}a\u{0020}dark\u{0020}side,\u{0020}under\u{0020}the\u{0020}threat\u{0020}of\u{0020}Sins'\u{0020}invasion,\u{0020}we\u{0020}have\u{0020}to\u{0020}stick\u{0020}with\u{0020}each\u{0020}other\u{0020}and\u{0020}be\u{0020}united.\n\nThat\u{0020}also\u{0020}shows\u{0020}us\u{0020}another\u{0020}important\u{0020}issue:\n\nHow\u{0020}many\u{0020}Etans\u{0020}are\u{0020}still\u{0020}having\u{0020}their\u{0020}\"Bias\"\u{0020}towards\u{0020}Aegis?", "0", "0", "0", "0", 13010, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[631003] = {631003, 1000, "\u{0020}\u{0020}It\u{0020}seems\u{0020}inevitable\u{0020}to\u{0020}form\u{0020}an\u{0020}AVG\u{0020}squad\u{0020}completely\u{0020}with\u{0020}Etans,\u{0020}not\u{0020}only\u{0020}that\u{0020}solves\u{0020}human\u{0020}resources\u{0020}issues\u{0020}in\u{0020}the\u{0020}war\u{0020}with\u{0020}Sins,\u{0020}but\u{0020}also\u{0020}shows\u{0020}our\u{0020}sincerity\u{0020}to\u{0020}Etans,\u{0020}considering\u{0020}that\u{0020}AVG\u{0020}and\u{0020}gigantification\u{0020}is\u{0020}the\u{0020}core\u{0020}of\u{0020}AEGIS.\n\nThe\u{0020}selection\u{0020}of\u{0020}Mizo\u{0020}was\u{0020}also\u{0020}simple:\u{0020}her\u{0020}Compatability\u{0020}Rate\u{0020}is\u{0020}far\u{0020}superior\u{0020}than\u{0020}the\u{0020}average\u{0020}of\u{0020}Etans,\u{0020}even\u{0020}better\u{0020}than\u{0020}those\u{0020}Etans\u{0020}with\u{0020}a\u{0020}\"warrior\"\u{0020}occupation.\n\nOf\u{0020}course,\u{0020}Compatability\u{0020}Rate\u{0020}doesn't\u{0020}represent\u{0020}fighting\u{0020}capabilities,\u{0020}Etans\u{0020}are\u{0020}good\u{0020}warriors.\u{0020}But\u{0020}that\u{0020}doesn't\u{0020}mean\u{0020}Mizo\u{0020}is\u{0020}weak\u{0020}in\u{0020}battles.\u{0020}On\u{0020}the\u{0020}contrary,\u{0020}she\u{0020}passed\u{0020}all\u{0020}of\u{0020}the\u{0020}training\u{0020}subjects\u{0020}in\u{0020}her\u{0020}first\u{0020}trial.\u{0020}Her\u{0020}grades\u{0020}on\u{0020}close\u{0020}quarter\u{0020}combat\u{0020}and\u{0020}usage\u{0020}of\u{0020}guns\u{0020}are\u{0020}especially\u{0020}impressive.\n\nTo\u{0020}our\u{0020}disappointment,\u{0020}Mizo\u{0020}applied\u{0020}to\u{0020}become\u{0020}qualified\u{0020}as\u{0020}a\u{0020}Supporter.\u{0020}However,\u{0020}we\u{0020}respect\u{0020}her\u{0020}choice.", "0", "0", "0", "0", 13010, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[631004] = {631004, 2000, "\u{0020}\u{0020}The\u{0020}battle\u{0020}rages\u{0020}for\u{0020}days,\u{0020}fighting\u{0020}never\u{0020}stops.\n\nThe\u{0020}furry\u{0020}girl\u{0020}eventually\u{0020}encountered\u{0020}the\u{0020}scenario\u{0020}that\u{0020}she\u{0020}has\u{0020}to\u{0020}face\u{0020}theSins\u{0020}alone,\n\nbut\u{0020}she\u{0020}didn't\u{0020}fluster,\n\nand\u{0020}calmly,\u{0020}packed\u{0020}up\u{0020}her\u{0020}equipments\u{0020}supplied\u{0020}by\u{0020}AEGIS.\n\nShe\u{0020}shows\u{0020}her\u{0020}sharp\u{0020}paws\u{0020}towards\u{0020}the\u{0020}striking\u{0020}monsters.\n\nAs\u{0020}the\u{0020}ashes\u{0020}vanish,\u{0020}the\u{0020}dead\u{0020}Sins\u{0020}fall\u{0020}down,\u{0020}and\u{0020}Mizo\u{0020}stands.\n\nThe\u{0020}difference\u{0020}is,\u{0020}some\u{0020}wounds\u{0020}appear\u{0020}on\u{0020}her\u{0020}arms.\n\n\"Perhaps,\u{0020}I\u{0020}should\u{0020}choose\u{0020}to\u{0020}fight,\n\nbut\u{0020}that\u{0020}reminds\u{0020}me\u{0020}of\u{0020}my\u{0020}past,\u{0020}my\u{0020}service\u{0020}for\u{0020}the\u{0020}darkness.\"", "0", "0", "0", "0", 13010, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[631100] = {631100, 0, "【Name】Meria\n\u{0020}【B-Day】July\u{0020}11\n\u{0020}【Transformation\u{0020}Core\u{0020}Proficiency】50％\n\u{0020}【Height】33m\n\u{0020}【Squad】Revelation\u{0020}Spring\n【Affiliation】Danube\u{0020}Branch\n\u{0020}【Interest】Do\u{0020}good\u{0020}every\u{0020}day", "0", "0", "0", "0", 13011, "0", "0", "0", "0", 0, 1, "0", "0", "0"},
[631101] = {631101, 100, "\u{3000}\u{3000}As\u{0020}the\u{0020}driver\u{0020}of\u{0020}Revelation\u{0020}Spring\u{0020}squad,\u{0020}Meria\u{0020}naturally\u{0020}also\u{0020}has\u{0020}a\u{0020}position\u{0020}in\u{0020}the\u{0020}Holy\u{0020}Church.\u{0020}She\u{0020}has\u{0020}served\u{0020}as\u{0020}a\u{0020}saint\u{0020}in\u{0020}the\u{0020}Diocese\u{0020}of\u{0020}Poynred\u{0020}for\u{0020}several\u{0020}years.\u{0020}Looking\u{0020}at\u{0020}the\u{0020}resume\u{0020}alone,\u{0020}Meria\u{0020}has\u{0020}not\u{0020}been\u{0020}in\u{0020}the\u{0020}church\u{0020}for\u{0020}a\u{0020}long\u{0020}time.\u{0020}Compared\u{0020}with\u{0020}the\u{0020}children\u{0020}who\u{0020}were\u{0020}adopted\u{0020}by\u{0020}the\u{0020}church\u{0020}in\u{0020}their\u{0020}infancy,\u{0020}she\u{0020}can\u{0020}only\u{0020}be\u{0020}regarded\u{0020}as\u{0020}a\u{0020}junior,\u{0020}but\u{0020}her\u{0020}piety\u{0020}is\u{0020}beyond\u{0020}everyone's\u{0020}expectations.\u{0020}Due\u{0020}to\u{0020}her\u{0020}good\u{0020}performance,\u{0020}Meria\u{0020}entered\u{0020}the\u{0020}church\u{0020}soon\u{0020}and\u{0020}became\u{0020}an\u{0020}official\u{0020}priest,\u{0020}and\u{0020}was\u{0020}further\u{0020}canonized\u{0020}as\u{0020}a\u{0020}saint.\u{0020}\n\u{3000}\u{3000}However,\u{0020}in\u{0020}the\u{0020}driver's\u{0020}career,\u{0020}perhaps\u{0020}because\u{0020}the\u{0020}qualification\u{0020}rate\u{0020}is\u{0020}low,\u{0020}perhaps\u{0020}because\u{0020}as\u{0020}a\u{0020}support\u{0020}driver,\u{0020}Meria's\u{0020}performance\u{0020}is\u{0020}not\u{0020}outstanding,\u{0020}the\u{0020}lack\u{0020}of\u{0020}impressive\u{0020}performance,\u{0020}according\u{0020}to\u{0020}his\u{0020}remarks\u{0020}\"silently\u{0020}guarding\u{0020}comrades\u{0020}is\u{0020}their\u{0020}duty\",\u{0020}Meria\u{0020}may\u{0020}indeed\u{0020}conform\u{0020}to\u{0020}the\u{0020}kind\u{0020}of\u{0020}weak\u{0020}and\u{0020}kind\u{0020}traditional\u{0020}clergy\u{0020}image,\u{0020}it\u{0020}can\u{0020}even\u{0020}be\u{0020}said\u{0020}that\u{0020}she\u{0020}is\u{0020}simply\u{0020}carved\u{0020}according\u{0020}to\u{0020}this\u{0020}mold.", "0", "0", "0", "0", 13011, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[631102] = {631102, 500, "\u{3000}\u{3000}In\u{0020}the\u{0020}eyes\u{0020}of\u{0020}the\u{0020}clergy\u{0020}and\u{0020}believers\u{0020}of\u{0020}the\u{0020}church,\u{0020}Meria\u{0020}is\u{0020}a\u{0020}well-deserved\u{0020}saintess,\u{0020}even\u{0020}though\u{0020}she\u{0020}is\u{0020}from\u{0020}the\u{0020}Eastern\u{0020}District\u{0020}of\u{0020}Poynred,\u{0020}or\u{0020}rather,\u{0020}precisely\u{0020}because\u{0020}she\u{0020}is\u{0020}from\u{0020}the\u{0020}Eastern\u{0020}District.\u{0020}\n\u{3000}\u{3000}Seven\u{0020}years\u{0020}ago,\u{0020}when\u{0020}Meria\u{0020}experienced\u{0020}the\u{0020}taste\u{0020}of\u{0020}structural\u{0020}poverty\u{0020}in\u{0020}that\u{0020}area\u{0020}with\u{0020}a\u{0020}significant\u{0020}class\u{0020}disparity,\u{0020}she\u{0020}eventually\u{0020}set\u{0020}off\u{0020}for\u{0020}the\u{0020}Western\u{0020}District\u{0020}despite\u{0020}the\u{0020}cynicism\u{0020}of\u{0020}those\u{0020}around\u{0020}her.\u{0020}This\u{0020}choice\u{0020}undoubtedly\u{0020}astonished\u{0020}her\u{0020}fellow\u{0020}vagrant\u{0020}children\u{0020}who\u{0020}were\u{0020}also\u{0020}from\u{0020}the\u{0020}slums.\u{0020}However,\u{0020}no\u{0020}one\u{0020}could\u{0020}have\u{0020}imagined\u{0020}that\u{0020}Meria's\u{0020}arrival\u{0020}recreated\u{0020}the\u{0020}miracle\u{0020}of\u{0020}Poynred\u{0020}-\u{0020}thousands\u{0020}of\u{0020}years\u{0020}ago,\u{0020}when\u{0020}this\u{0020}place\u{0020}was\u{0020}still\u{0020}a\u{0020}barren\u{0020}mountainous\u{0020}area,\u{0020}it\u{0020}was\u{0020}the\u{0020}church\u{0020}saints\u{0020}who\u{0020}led\u{0020}the\u{0020}people\u{0020}to\u{0020}continuously\u{0020}open\u{0020}up\u{0020}the\u{0020}mountains\u{0020}and\u{0020}cultivate\u{0020}the\u{0020}land,\u{0020}discovering\u{0020}numerous\u{0020}water\u{0020}sources\u{0020}and\u{0020}making\u{0020}Poynred\u{0020}a\u{0020}fertile\u{0020}land\u{0020}flowing\u{0020}with\u{0020}the\u{0020}fountain\u{0020}of\u{0020}life.\u{0020}And\u{0020}as\u{0020}stated\u{0020}by\u{0020}relevant\u{0020}personnel,\u{0020}not\u{0020}long\u{0020}after\u{0020}Meria\u{0020}arrived\u{0020}in\u{0020}the\u{0020}Western\u{0020}District\u{0020}in\u{0020}a\u{0020}state\u{0020}of\u{0020}hunger\u{0020}and\u{0020}cold\u{0020}and\u{0020}was\u{0020}about\u{0020}to\u{0020}pass\u{0020}out\u{0020}due\u{0020}to\u{0020}dehydration,\u{0020}she\u{0020}unexpectedly\u{0020}discovered\u{0020}unrecorded\u{0020}springs\u{0020}again.\u{0020}This\u{0020}discovery\u{0020}might\u{0020}merely\u{0020}be\u{0020}a\u{0020}coincidence,\u{0020}but\u{0020}the\u{0020}symbolic\u{0020}meaning\u{0020}behind\u{0020}it\u{0020}is\u{0020}probably\u{0020}one\u{0020}of\u{0020}the\u{0020}reasons\u{0020}why\u{0020}the\u{0020}church\u{0020}proclaimed\u{0020}her\u{0020}as\u{0020}a\u{0020}saintess.\u{0020}\n\u{3000}\u{3000}However,\u{0020}was\u{0020}that\u{0020}discovery\u{0020}really\u{0020}a\u{0020}miracle?\u{0020}After\u{0020}Meria\u{0020}became\u{0020}a\u{0020}driver,\u{0020}the\u{0020}AEGIS\u{0020}research\u{0020}department\u{0020}conducted\u{0020}a\u{0020}series\u{0020}of\u{0020}studies\u{0020}on\u{0020}this\u{0020}issue,\u{0020}including\u{0020}but\u{0020}not\u{0020}limited\u{0020}to\u{0020}psychological\u{0020}suggestion.\u{0020}The\u{0020}results\u{0020}showed\u{0020}that\u{0020}there\u{0020}might\u{0020}be\u{0020}some\u{0020}special\u{0020}powers\u{0020}in\u{0020}Meria\u{0020}that\u{0020}could\u{0020}affect\u{0020}reality.\u{0020}The\u{0020}specific\u{0020}effect\u{0020}and\u{0020}trigger\u{0020}timing\u{0020}depend\u{0020}on\u{0020}her\u{0020}emotional\u{0020}fluctuations.\u{0020}\n\u{3000}\u{3000}When\u{0020}a\u{0020}certain\u{0020}pure\u{0020}wish\u{0020}is\u{0020}generated,\u{0020}Meria's\u{0020}ability\u{0020}can\u{0020}work\u{0020}miracles\u{0020}and\u{0020}make\u{0020}her\u{0020}dreams\u{0020}come\u{0020}true.\u{0020}The\u{0020}accidental\u{0020}discovery\u{0020}when\u{0020}she\u{0020}was\u{0020}on\u{0020}the\u{0020}verge\u{0020}of\u{0020}coma\u{0020}seven\u{0020}years\u{0020}ago\u{0020}might\u{0020}stem\u{0020}from\u{0020}this\u{0020}ability.\u{0020}In\u{0020}other\u{0020}words,\u{0020}it\u{0020}was\u{0020}the\u{0020}result\u{0020}of\u{0020}her\u{0020}inner\u{0020}prayer.\u{0020}However,\u{0020}as\u{0020}a\u{0020}saintess,\u{0020}Meria\u{0020}should\u{0020}have\u{0020}been\u{0020}praying\u{0020}for\u{0020}the\u{0020}believers\u{0020}every\u{0020}day.\u{0020}Why\u{0020}didn't\u{0020}her\u{0020}ability\u{0020}always\u{0020}take\u{0020}effect?\u{0020}Various\u{0020}speculations\u{0020}about\u{0020}this\u{0020}doubt\u{0020}cannot\u{0020}be\u{0020}elaborated\u{0020}in\u{0020}detail.\u{0020}But\u{0020}according\u{0020}to\u{0020}the\u{0020}author's\u{0020}personal\u{0020}imagination,\u{0020}although\u{0020}Meria's\u{0020}sincere\u{0020}prayer\u{0020}when\u{0020}she\u{0020}was\u{0020}in\u{0020}a\u{0020}trance\u{0020}saved\u{0020}herself,\u{0020}this\u{0020}girl\u{0020}from\u{0020}the\u{0020}slums\u{0020}of\u{0020}the\u{0020}Eastern\u{0020}District\u{0020}might\u{0020}have\u{0020}no\u{0020}longer\u{0020}believed\u{0020}in\u{0020}gods\u{0020}and\u{0020}miracles\u{0020}in\u{0020}her\u{0020}heart\u{0020}from\u{0020}the\u{0020}very\u{0020}beginning.", "0", "0", "0", "0", 13011, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[631103] = {631103, 1000, "\u{3000}\u{3000}Meria's\u{0020}performance\u{0020}in\u{0020}AEGIS\u{0020}is\u{0020}basically\u{0020}no\u{0020}different\u{0020}from\u{0020}that\u{0020}in\u{0020}the\u{0020}church.\u{0020}She\u{0020}still\u{0020}has\u{0020}the\u{0020}appearance\u{0020}of\u{0020}an\u{0020}innocent,\u{0020}pure,\u{0020}gentle\u{0020}and\u{0020}polite\u{0020}saintess.\u{0020}Even\u{0020}though\u{0020}there\u{0020}are\u{0020}many\u{0020}eccentric\u{0020}people\u{0020}in\u{0020}AEGIS,\u{0020}no\u{0020}one\u{0020}will\u{0020}make\u{0020}things\u{0020}difficult\u{0020}for\u{0020}such\u{0020}a\u{0020}well-behaved\u{0020}and\u{0020}sensible\u{0020}girl.\u{0020}However,\u{0020}sometimes,\u{0020}some\u{0020}people\u{0020}claim\u{0020}that\u{0020}they\u{0020}witnessed\u{0020}an\u{0020}abnormal\u{0020}Meria,\u{0020}described\u{0020}as\u{0020}\"like\u{0020}a\u{0020}changed\u{0020}person\",\u{0020}and\u{0020}such\u{0020}sightings\u{0020}usually\u{0020}occur\u{0020}in\u{0020}the\u{0020}dead\u{0020}of\u{0020}night\u{0020}or\u{0020}when\u{0020}Meria\u{0020}is\u{0020}alone.\u{0020}The\u{0020}abnormal\u{0020}state\u{0020}is\u{0020}always\u{0020}fleeting.\u{0020}\n\u{3000}\u{3000}When\u{0020}faced\u{0020}with\u{0020}the\u{0020}investigation\u{0020}and\u{0020}inquiries\u{0020}of\u{0020}the\u{0020}managers,\u{0020}Meria\u{0020}was\u{0020}initially\u{0020}reluctant\u{0020}to\u{0020}answer.\u{0020}Eventually,\u{0020}she\u{0020}claimed\u{0020}that\u{0020}she\u{0020}would\u{0020}occasionally\u{0020}be\u{0020}possessed\u{0020}by\u{0020}a\u{0020}demon.\u{0020}In\u{0020}that\u{0020}state,\u{0020}she\u{0020}would\u{0020}tell\u{0020}lies,\u{0020}lose\u{0020}all\u{0020}virtues,\u{0020}and\u{0020}even\u{0020}be\u{0020}unable\u{0020}to\u{0020}control\u{0020}her\u{0020}instinctive\u{0020}desires\u{0020}properly.\u{0020}However,\u{0020}she\u{0020}immediately\u{0020}said\u{0020}that\u{0020}there\u{0020}was\u{0020}no\u{0020}need\u{0020}to\u{0020}worry\u{0020}if\u{0020}such\u{0020}a\u{0020}situation\u{0020}was\u{0020}witnessed,\u{0020}as\u{0020}she\u{0020}would\u{0020}reseal\u{0020}the\u{0020}demon\u{0020}soon...\u{0020}After\u{0020}this\u{0020}highly\u{0020}suspicious\u{0020}statement\u{0020}spread\u{0020}like\u{0020}wildfire\u{0020}one\u{0020}day,\u{0020}Meria's\u{0020}evaluation\u{0020}within\u{0020}AEGIS\u{0020}actually\u{0020}became\u{0020}higher.", "0", "0", "0", "0", 13011, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[631104] = {631104, 2000, "\u{3000}\u{3000}At\u{0020}the\u{0020}bottom\u{0020}of\u{0020}the\u{0020}cold\u{0020}and\u{0020}dark\u{0020}well.\u{0020}\n\u{3000}\u{3000}In\u{0020}the\u{0020}deep\u{0020}part\u{0020}of\u{0020}the\u{0020}already\u{0020}dried-up\u{0020}soul.\u{0020}\n\u{3000}\u{3000}The\u{0020}young\u{0020}girl\u{0020}sleeps\u{0020}on\u{0020}the\u{0020}bed\u{0020}of\u{0020}blooming\u{0020}flowers\u{0020}and\u{0020}removes\u{0020}all\u{0020}disguises.\u{0020}\n\u{3000}\u{3000}Neither\u{0020}be\u{0020}attached\u{0020}to\u{0020}the\u{0020}wide\u{0020}robes\u{0020}of\u{0020}the\u{0020}saints\u{0020}nor\u{0020}be\u{0020}obsessed\u{0020}with\u{0020}the\u{0020}flashy\u{0020}light.\u{0020}\n\u{3000}\u{3000}What\u{0020}remains\u{0020}after\u{0020}giving\u{0020}up\u{0020}everything\u{0020}is\u{0020}only\u{0020}the\u{0020}desire\u{0020}to\u{0020}adhere\u{0020}to\u{0020}one's\u{0020}own\u{0020}heart.\u{0020}\n\u{3000}\u{3000}\"Navigator,\u{0020}don't\u{0020}look\u{0020}away.\"\u{0020}\n\u{3000}\u{3000}\"There's\u{0020}nothing\u{0020}to\u{0020}be\u{0020}ashamed\u{0020}of,\u{0020}that's\u{0020}all\u{0020}I\u{0020}have.\"\u{0020}\n\u{3000}\u{3000}The\u{0020}young\u{0020}girl\u{0020}indulging\u{0020}in\u{0020}filth\u{0020}casts\u{0020}her\u{0020}gaze\u{0020}towards\u{0020}the\u{0020}wellhead.\u{0020}\n\u{3000}\u{3000}Seeming\u{0020}to\u{0020}catch\u{0020}the\u{0020}last\u{0020}ray\u{0020}of\u{0020}the\u{0020}setting\u{0020}sun.", "0", "0", "0", "0", 13011, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
[631200] = {631200, 0, "【Name】Dorothy·Derrich\n【B-Day】April\u{0020}2nd\n\u{0020}【Compatibility\u{0020}Rate】47％\n【Height】38m\n【Squad】Dunscaith\n【Affiliation】None\n【Interest】Observe\u{0020}the\u{0020}accuracy\u{0020}of\u{0020}the\u{0020}prophecy\u{0020}and\u{0020}disrupt\u{0020}the\u{0020}outcome\u{0020}of\u{0020}the\u{0020}prophecy.", "0", "0", "0", "0", 13012, "0", "0", "0", "0", 0, 1, "0", "0", "0"},
[631201] = {631201, 100, "A\u{0020}mysterious\u{0020}woman\u{0020}longing\u{0020}for\u{0020}the\u{0020}Kyushu\u{0020}culture,\u{0020}a\u{0020}descendant\u{0020}of\u{0020}the\u{0020}remaining\u{0020}witches\u{0020}during\u{0020}the\u{0020}Danube\u{0020}\"Witch\u{0020}Hunt\"\u{0020}period,\u{0020}envying\u{0020}the\u{0020}belief\u{0020}culture\u{0020}of\u{0020}Kyushu\u{0020}because\u{0020}they\u{0020}can\u{0020}stand\u{0020}openly\u{0020}on\u{0020}the\u{0020}\"front\u{0020}of\u{0020}the\u{0020}world\",\u{0020}be\u{0020}accepted\u{0020}by\u{0020}humans\u{0020}and\u{0020}fight\u{0020}for\u{0020}humans.\n\nAffected\u{0020}by\u{0020}Skadi's\u{0020}[Synesthesia]\u{0020}rampage,\u{0020}still\u{0020}doing\u{0020}the\u{0020}job\u{0020}of\u{0020}temple\u{0020}sacrifice\u{0020}in\u{0020}the\u{0020}dream,\u{0020}\"I\u{0020}don't\u{0020}want\u{0020}to\u{0020}work\u{0020}anymore!\"\u{0020}-\u{0020}After\u{0020}having\u{0020}such\u{0020}a\u{0020}thought,\u{0020}was\u{0020}taken\u{0020}away\u{0020}by\u{0020}Skadi\u{0020}with\u{0020}the\u{0020}Gate.\n\nIn\u{0020}the\u{0020}[Skadi\u{0020}Incident],\u{0020}briefly\u{0020}became\u{0020}the\u{0020}\"ideal\u{0020}self\"\u{0020}and\u{0020}peeked\u{0020}at\u{0020}Skadi's\u{0020}early\u{0020}setting\u{0020}collection\u{0020}through\u{0020}the\u{0020}\"divine\u{0020}inspiration\"\u{0020}bestowed\u{0020}by\u{0020}Skadi.\u{0020}Liked\u{0020}the\u{0020}feeling\u{0020}that\u{0020}everyone\u{0020}regarded\u{0020}her\u{0020}as\u{0020}a\u{0020}prophet.\n\nAfter\u{0020}the\u{0020}incident\u{0020}was\u{0020}over,\u{0020}I\u{0020}forgot\u{0020}this\u{0020}memory,\u{0020}planned\u{0020}to\u{0020}take\u{0020}the\u{0020}driver's\u{0020}test,\u{0020}and\u{0020}met\u{0020}an\u{0020}abandoned\u{0020}black\u{0020}cat\u{0020}on\u{0020}the\u{0020}road.", "0", "0", "0", "0", 13012, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[631202] = {631202, 500, "According\u{0020}to\u{0020}herself,\u{0020}Dorothy·Derrich\u{0020}is\u{0020}a\u{0020}great\u{0020}witch\u{0020}born\u{0020}from\u{0020}a\u{0020}famous\u{0020}magic\u{0020}family\u{0020}and\u{0020}also\u{0020}the\u{0020}first\u{0020}[witch]\u{0020}to\u{0020}officially\u{0020}step\u{0020}onto\u{0020}the\u{0020}world\u{0020}stage\u{0020}after\u{0020}the\u{0020}\"Witch\u{0020}Hunt\".\n\nThe\u{0020}so-called\u{0020}\"witch\"\u{0020}is\u{0020}just\u{0020}a\u{0020}pitiful\u{0020}person\u{0020}who\u{0020}possesses\u{0020}knowledge\u{0020}ahead\u{0020}of\u{0020}the\u{0020}times\u{0020}but\u{0020}is\u{0020}not\u{0020}understood\u{0020}by\u{0020}the\u{0020}mundane\u{0020}people.\n\nToday,\u{0020}the\u{0020}legends\u{0020}about\u{0020}witches\u{0020}have\u{0020}been\u{0020}debunked\u{0020}with\u{0020}the\u{0020}progress\u{0020}of\u{0020}science\u{0020}and\u{0020}the\u{0020}change\u{0020}of\u{0020}times.\u{0020}However,\u{0020}the\u{0020}birthplace\u{0020}of\u{0020}the\u{0020}Witch\u{0020}Hunt\u{0020}-\u{0020}Danube\u{0020}-\u{0020}has\u{0020}been\u{0020}filled\u{0020}with\u{0020}discrimination\u{0020}and\u{0020}ridicule\u{0020}against\u{0020}witches\u{0020}from\u{0020}the\u{0020}beginning\u{0020}to\u{0020}the\u{0020}end.\n\nPeople\u{0020}are\u{0020}enthusiastically\u{0020}discussing\u{0020}divination\u{0020}and\u{0020}constellation\u{0020}fortune,\u{0020}but\u{0020}regard\u{0020}witches\u{0020}as\u{0020}words\u{0020}to\u{0020}insult\u{0020}others.\n\nThe\u{0020}witch\u{0020}who\u{0020}does\u{0020}all\u{0020}kinds\u{0020}of\u{0020}evil\u{0020}in\u{0020}nursery\u{0020}rhymes,\u{0020}and\u{0020}the\u{0020}witch\u{0020}who\u{0020}takes\u{0020}away\u{0020}disobedient\u{0020}children\u{0020}at\u{0020}night.\n\nOrphans\u{0020}without\u{0020}support\u{0020}are\u{0020}called\u{0020}children\u{0020}of\u{0020}witches,\u{0020}and\u{0020}even\u{0020}political\u{0020}persecution\u{0020}can\u{0020}still\u{0020}be\u{0020}related\u{0020}to\u{0020}the\u{0020}belief\u{0020}in\u{0020}witches.\n\nWhen\u{0020}a\u{0020}certain\u{0020}belief,\u{0020}a\u{0020}certain\u{0020}misinterpretation\u{0020}becomes\u{0020}common\u{0020}sense,\u{0020}and\u{0020}a\u{0020}certain\u{0020}mistake\u{0020}is\u{0020}integrated\u{0020}into\u{0020}daily\u{0020}life,\u{0020}it\u{0020}becomes\u{0020}the\u{0020}capital\u{0020}of\u{0020}ridicule.\u{0020}The\u{0020}witch\u{0020}is\u{0020}like\u{0020}a\u{0020}crouching\u{0020}rat\u{0020}in\u{0020}a\u{0020}deep\u{0020}ditch,\u{0020}and\u{0020}those\u{0020}survivors\u{0020}who\u{0020}finally\u{0020}survived\u{0020}will\u{0020}feel\u{0020}the\u{0020}ubiquitous\u{0020}environmental\u{0020}pressure.\u{0020}Some\u{0020}witches\u{0020}chose\u{0020}to\u{0020}leave\u{0020}Danube\u{0020}because\u{0020}they\u{0020}couldn't\u{0020}bear\u{0020}this\u{0020}malice.\u{0020}Although\u{0020}Dorothy\u{0020}was\u{0020}a\u{0020}legitimate\u{0020}Danube\u{0020}witch\u{0020}born\u{0020}in\u{0020}such\u{0020}an\u{0020}environment,\u{0020}the\u{0020}perennial\u{0020}malice\u{0020}did\u{0020}not\u{0020}make\u{0020}her\u{0020}yield\u{0020}to\u{0020}the\u{0020}world.\u{0020}She\u{0020}sincerely\u{0020}felt\u{0020}uncomfortable\u{0020}and\u{0020}disgusted\u{0020}with\u{0020}this\u{0020}atmosphere\u{0020}and\u{0020}urgently\u{0020}wanted\u{0020}to\u{0020}change\u{0020}this\u{0020}situation.\u{0020}The\u{0020}great\u{0020}witch\u{0020}listed\u{0020}a\u{0020}detailed\u{0020}plan.\u{0020}This\u{0020}plan\u{0020}was\u{0020}based\u{0020}on\u{0020}the\u{0020}fact\u{0020}that\u{0020}\"Danube\u{0020}attempts\u{0020}to\u{0020}misinterpret\u{0020}mistakes.\"\u{0020}She\u{0020}wanted\u{0020}to\u{0020}promote\u{0020}and\u{0020}glorify\u{0020}the\u{0020}witch's\u{0020}culture\u{0020}in\u{0020}the\u{0020}world\u{0020}to\u{0020}replace\u{0020}the\u{0020}current\u{0020}malice,\u{0020}create\u{0020}a\u{0020}non-existent\u{0020}culture,\u{0020}and\u{0020}annihilate\u{0020}another\u{0020}culture.\u{0020}To\u{0020}gain\u{0020}experience\u{0020}and\u{0020}allies,\u{0020}Dorothy\u{0020}traveled\u{0020}far\u{0020}away.\u{0020}During\u{0020}her\u{0020}journey,\u{0020}she\u{0020}met\u{0020}various\u{0020}people\u{0020}similar\u{0020}to\u{0020}the\u{0020}identity\u{0020}of\u{0020}[witches]\u{0020}in\u{0020}different\u{0020}regions.\u{0020}Some\u{0020}of\u{0020}them\u{0020}retired\u{0020}to\u{0020}the\u{0020}mountains\u{0020}and\u{0020}forests,\u{0020}or\u{0020}lived\u{0020}in\u{0020}seclusion\u{0020}in\u{0020}the\u{0020}city,\u{0020}or\u{0020}were\u{0020}respected\u{0020}in\u{0020}the\u{0020}spotlight\u{0020}of\u{0020}the\u{0020}world.\u{0020}Eventually,\u{0020}she\u{0020}stayed\u{0020}in\u{0020}Kyushu,\u{0020}a\u{0020}place\u{0020}that\u{0020}embraces\u{0020}various\u{0020}beliefs.\u{0020}One\u{0020}day\u{0020}after\u{0020}waking\u{0020}up\u{0020}from\u{0020}a\u{0020}nap,\u{0020}she\u{0020}decided\u{0020}to\u{0020}take\u{0020}the\u{0020}driver's\u{0020}test\u{0020}and\u{0020}met\u{0020}a\u{0020}clingy\u{0020}black\u{0020}cat\u{0020}on\u{0020}the\u{0020}way.", "0", "0", "0", "0", 13012, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[631203] = {631203, 1000, "Kyushu\u{0020}is\u{0020}a\u{0020}city\u{0020}full\u{0020}of\u{0020}a\u{0020}sense\u{0020}of\u{0020}fragmentation.\n\nIts\u{0020}surroundings\u{0020}are\u{0020}mainly\u{0020}dominated\u{0020}by\u{0020}ancient\u{0020}buildings,\u{0020}among\u{0020}which\u{0020}a\u{0020}large\u{0020}amount\u{0020}of\u{0020}Kyushu's\u{0020}traditional\u{0020}culture\u{0020}is\u{0020}retained.\u{0020}The\u{0020}invasion\u{0020}of\u{0020}Sin\u{0020}forced\u{0020}a\u{0020}large\u{0020}number\u{0020}of\u{0020}refugees\u{0020}to\u{0020}come\u{0020}to\u{0020}Kyushu\u{0020}to\u{0020}make\u{0020}a\u{0020}living.\u{0020}So\u{0020}when\u{0020}we\u{0020}walk\u{0020}on\u{0020}the\u{0020}streets\u{0020}of\u{0020}the\u{0020}outer\u{0020}city\u{0020}area\u{0020}of\u{0020}Kyushu,\u{0020}we\u{0020}can\u{0020}see\u{0020}all\u{0020}kinds\u{0020}of\u{0020}people.\u{0020}Similarly,\u{0020}their\u{0020}cultures\u{0020}and\u{0020}beliefs\u{0020}also\u{0020}blend\u{0020}smoothly\u{0020}with\u{0020}Kyushu.\n\nDorothy\u{0020}is\u{0020}in\u{0020}Kyushu,\u{0020}preparing\u{0020}to\u{0020}find\u{0020}a\u{0020}job.\n\n\"Why\u{0020}did\u{0020}Miko's\u{0020}recruitment\u{0020}conditions\u{0020}only\u{0020}require\u{0020}combat\u{0020}ability...?\"", "0", "0", "0", "0", 13012, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[631204] = {631204, 2000, "\"Originally,\u{0020}this\u{0020}is\u{0020}transformation?\u{0020}\"\n\nIt\u{0020}seems\u{0020}there\u{0020}are\u{0020}no\u{0020}more\u{0020}special\u{0020}changes,\u{0020}right?\n\nDorothy·Derrich,\u{0020}the\u{0020}witch.\n\nToday,\u{0020}I\u{0020}got\u{0020}the\u{0020}transformation\u{0020}license\u{0020}for\u{0020}the\u{0020}first\u{0020}time.\n\nHowever,\u{0020}in\u{0020}this\u{0020}case,\u{0020}I'm\u{0020}one\u{0020}step\u{0020}closer\u{0020}to\u{0020}the\u{0020}future\u{0020}predicted.\n\nShe\u{0020}looked\u{0020}up\u{0020}at\u{0020}the\u{0020}starry\u{0020}sky,\u{0020}and\u{0020}what\u{0020}was\u{0020}reflected\u{0020}in\u{0020}her\u{0020}eyes,\n\nIt\u{0020}is\u{0020}the\u{0020}shadow\u{0020}of\u{0020}a\u{0020}certain\u{0020}navigator.\n\n\"When\u{0020}you\u{0020}remember\u{0020}me\u{0020}and\u{0020}that\u{0020}memory.\"\\u{0020}n\u{0020}\"I'm\u{0020}really\u{0020}looking\u{0020}forward\u{0020}to\u{0020}it.\"", "0", "0", "0", "0", 13012, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
[631300] = {631300, 0, "[Name]\u{0020}Fleur\n[B-Day]\u{0020}July\u{0020}12\n[Compatability\u{0020}Rate]\u{0020}100％\n[Height]\u{0020}29m\n[Squad]\u{0020}Moon\u{0020}Corona\n[Affiliation]\u{0020}Danube\u{0020}Branch\n[Interest]\u{0020}Play\u{0020}with\u{0020}cats.", "0", "0", "0", "0", 13013, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[631301] = {631301, 100, "\u{0020}\u{0020}People\u{0020}feel\u{0020}she's\u{0020}a\u{0020}little\u{0020}one\u{0020}that\u{0020}is\u{0020}always\u{0020}confused,\u{0020}and\u{0020}she's\u{0020}sluggish\u{0020}when\u{0020}she\u{0020}talks\u{0020}with\u{0020}people\u{0020}or\u{0020}responds\u{0020}to\u{0020}others,\u{0020}it's\u{0020}almost\u{0020}like\u{0020}she\u{0020}lives\u{0020}in\u{0020}her\u{0020}own\u{0020}time.\u{0020}As\u{0020}a\u{0020}result,\u{0020}she\u{0020}always\u{0020}stays\u{0020}in\u{0020}a\u{0020}corner\u{0020}far\u{0020}away\u{0020}from\u{0020}people,\u{0020}like\u{0020}a\u{0020}stray\u{0020}cat,\u{0020}observing\u{0020}others\u{0020}silently\u{0020}and\u{0020}lonely.\u{0020}If\u{0020}someone\u{0020}chats\u{0020}to\u{0020}her,\u{0020}she\u{0020}will\u{0020}look\u{0020}very\u{0020}happy.\n\nBut,\u{0020}she\u{0020}seems\u{0020}to\u{0020}have\u{0020}a\u{0020}physical\u{0020}condition\u{0020}that\u{0020}attracts\u{0020}kittens.\u{0020}Every\u{0020}cat\u{0020}in\u{0020}the\u{0020}ark\u{0020}has\u{0020}a\u{0020}good\u{0020}relation\u{0020}with\u{0020}Fleur,\u{0020}we\u{0020}often\u{0020}see\u{0020}Fleur\u{0020}play\u{0020}with\u{0020}the\u{0020}cats.\u{0020}And\u{0020}a\u{0020}myth\u{0020}appeared:\u{0020}\"Fleur\u{0020}is\u{0020}actually\u{0020}a\u{0020}cat.\"\n\nBut\u{0020}on\u{0020}the\u{0020}battlefield,\u{0020}Fleur\u{0020}is\u{0020}agile\u{0020}like\u{0020}a\u{0020}cat,\u{0020}very\u{0020}different\u{0020}from\u{0020}her\u{0020}normally\u{0020}sluggish\u{0020}behaviors.\u{0020}No\u{0020}matter\u{0020}how\u{0020}big\u{0020}her\u{0020}body\u{0020}is,\u{0020}she\u{0020}can\u{0020}control\u{0020}her\u{0020}AVG\u{0020}gears\u{0020}and\u{0020}move\u{0020}nimbly\u{0020}between\u{0020}allies\u{0020}and\u{0020}foes\u{0020}to\u{0020}support\u{0020}her\u{0020}comrades.", "0", "0", "0", "0", 13013, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[631302] = {631302, 500, "\u{0020}\u{0020}Before\u{0020}she\u{0020}joined\u{0020}\"Moon\u{0020}Corona\",\u{0020}Fleur\u{0020}was\u{0020}already\u{0020}\"well-known\"\u{0020}in\u{0020}Saar.\n\nAccording\u{0020}to\u{0020}locals,\u{0020}every\u{0020}night\u{0020}people\u{0020}can\u{0020}see\u{0020}a\u{0020}short\u{0020}little\u{0020}girl\u{0020}standing\u{0020}on\u{0020}the\u{0020}beach\u{0020}where\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}can\u{0020}be\u{0020}seen\u{0020}far\u{0020}away.\u{0020}She\u{0020}looks\u{0020}at\u{0020}that\u{0020}giant\u{0020}building\u{0020}across\u{0020}the\u{0020}sea\u{0020}alone,\u{0020}like\u{0020}she's\u{0020}waiting\u{0020}for\u{0020}someone,\u{0020}until\u{0020}the\u{0020}sun\u{0020}rises,\u{0020}when\u{0020}she\u{0020}disappears\u{0020}with\u{0020}the\u{0020}dew.\n\nSo\u{0020}why\u{0020}did\u{0020}she\u{0020}stay\u{0020}on\u{0020}that\u{0020}beach\u{0020}every\u{0020}night?\u{0020}Why\u{0020}did\u{0020}she\u{0020}appear\u{0020}only\u{0020}at\u{0020}nights?\n\nNo\u{0020}one\u{0020}knows.\n\nSometimes\u{0020}there\u{0020}are\u{0020}nice\u{0020}or\u{0020}malicious\u{0020}people\u{0020}who\u{0020}try\u{0020}to\u{0020}track\u{0020}her\u{0020}down\u{0020}to\u{0020}help\u{0020}her,\u{0020}but\u{0020}all\u{0020}of\u{0020}them\u{0020}lose\u{0020}her\u{0020}on\u{0020}the\u{0020}way.\u{0020}According\u{0020}to\u{0020}them,\u{0020}the\u{0020}girl\u{0020}had\u{0020}a\u{0020}stunning\u{0020}speed,\u{0020}and\u{0020}stray\u{0020}cats\u{0020}often\u{0020}disturbed\u{0020}them\u{0020}when\u{0020}they\u{0020}were\u{0020}following\u{0020}her,\u{0020}and\u{0020}as\u{0020}a\u{0020}result\u{0020}she\u{0020}would\u{0020}disappear\u{0020}abruptly\u{0020}in\u{0020}their\u{0020}sight.\n\nNevertheless,\u{0020}in\u{0020}the\u{0020}voice\u{0020}recording\u{0020}a\u{0020}driver\u{0020}left\u{0020}to\u{0020}us,\u{0020}we\u{0020}finally\u{0020}discovered\u{0020}her\u{0020}story.\n\nBack\u{0020}then,\u{0020}a\u{0020}dark-haired\u{0020}driver\u{0020}of\u{0020}3rd\u{0020}Laboratory\u{0020}Defence\u{0020}Squad\u{0020}noticed\u{0020}Fleur\u{0020}when\u{0020}she\u{0020}was\u{0020}shopping\u{0020}for\u{0020}the\u{0020}team.\u{0020}With\u{0020}a\u{0020}big\u{0020}bag\u{0020}of\u{0020}cat\u{0020}food\u{0020}as\u{0020}\"payment\",\u{0020}Fleur\u{0020}made\u{0020}friends\u{0020}with\u{0020}this\u{0020}driver,\u{0020}they\u{0020}became\u{0020}friends.\u{0020}In\u{0020}their\u{0020}following\u{0020}communication,\u{0020}Fleur\u{0020}told\u{0020}the\u{0020}driver\u{0020}her\u{0020}story.\n\nFleur's\u{0020}parents\u{0020}are\u{0020}staff\u{0020}in\u{0020}the\u{0020}lab.\u{0020}Because\u{0020}of\u{0020}their\u{0020}work,\u{0020}they\u{0020}cannot\u{0020}stay\u{0020}with\u{0020}her,\u{0020}so\u{0020}she\u{0020}was\u{0020}raised\u{0020}by\u{0020}her\u{0020}grandma.\n\nBecause\u{0020}her\u{0020}grandma\u{0020}was\u{0020}old\u{0020}and\u{0020}her\u{0020}actions\u{0020}were\u{0020}always\u{0020}sluggish,\u{0020}being\u{0020}a\u{0020}considerate\u{0020}girl\u{0020}Fleur\u{0020}slowed\u{0020}down\u{0020}to\u{0020}follow\u{0020}her\u{0020}grandma's\u{0020}pace,\u{0020}and\u{0020}that\u{0020}made\u{0020}her\u{0020}sluggish.\u{0020}Well,\u{0020}of\u{0020}course\u{0020}this\u{0020}kind\u{0020}of\u{0020}behavior\u{0020}and\u{0020}personality\u{0020}kept\u{0020}her\u{0020}away\u{0020}from\u{0020}socializing\u{0020}with\u{0020}her\u{0020}peers,\u{0020}so\u{0020}she\u{0020}was\u{0020}gradually\u{0020}isolated\u{0020}by\u{0020}her\u{0020}peers\u{0020}in\u{0020}school.\n\nAfter\u{0020}being\u{0020}alienized,\u{0020}Fleur\u{0020}didn't\u{0020}decide\u{0020}to\u{0020}change\u{0020}herself,\u{0020}because\u{0020}she\u{0020}cared\u{0020}more\u{0020}about\u{0020}her\u{0020}grandma\u{0020}than\u{0020}herself\u{0020}and\u{0020}didn't\u{0020}want\u{0020}her\u{0020}grandma\u{0020}to\u{0020}feel\u{0020}lonely.\u{0020}Seeking\u{0020}friendship,\u{0020}she\u{0020}finally\u{0020}chose\u{0020}to\u{0020}make\u{0020}friends\u{0020}with\u{0020}stray\u{0020}cats\u{0020}in\u{0020}the\u{0020}city.\u{0020}With\u{0020}her\u{0020}care\u{0020}and\u{0020}accompanying,\u{0020}nice\u{0020}and\u{0020}gentle\u{0020}Fleur\u{0020}was\u{0020}accepted\u{0020}by\u{0020}those\u{0020}cats.\n\nPerhaps\u{0020}because\u{0020}of\u{0020}her\u{0020}experiences\u{0020}in\u{0020}school,\u{0020}or\u{0020}perhaps\u{0020}she\u{0020}lived\u{0020}with\u{0020}these\u{0020}stray\u{0020}cats\u{0020}for\u{0020}so\u{0020}long,\u{0020}Fleur\u{0020}became\u{0020}shy.\u{0020}She\u{0020}instinctively\u{0020}avoids\u{0020}strangers.\n\nThe\u{0020}reason\u{0020}why\u{0020}she\u{0020}stays\u{0020}on\u{0020}that\u{0020}beach\u{0020}at\u{0020}night\u{0020}is\u{0020}her\u{0020}promise\u{0020}with\u{0020}dad\u{0020}and\u{0020}mom,\u{0020}although\u{0020}they\u{0020}can\u{0020}only\u{0020}come\u{0020}back\u{0020}once\u{0020}a\u{0020}year,\u{0020}but\u{0020}her\u{0020}mom\u{0020}said\u{0020}\"If\u{0020}Fleur\u{0020}stands\u{0020}on\u{0020}that\u{0020}beach,\u{0020}dad\u{0020}and\u{0020}mom\u{0020}can\u{0020}see\u{0020}her\u{0020}through\u{0020}a\u{0020}telescope.\"\n\nYes,\u{0020}that's\u{0020}why\u{0020}she\u{0020}appeared\u{0020}on\u{0020}the\u{0020}beach\u{0020}every\u{0020}night,\u{0020}only\u{0020}to\u{0020}\"let\u{0020}her\u{0020}dad\u{0020}and\u{0020}mom\u{0020}see\u{0020}her\".\n\nUnder\u{0020}that\u{0020}impression\u{0020}of\u{0020}sluggish\u{0020}and\u{0020}lonely,\u{0020}she's\u{0020}actually\u{0020}a\u{0020}girl\u{0020}with\u{0020}a\u{0020}considerate\u{0020}heart\u{0020}for\u{0020}others.", "0", "0", "0", "0", 13013, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[631303] = {631303, 1000, "\u{0020}\u{0020}That\u{0020}was\u{0020}an\u{0020}unusual\u{0020}night,\u{0020}because\u{0020}of\u{0020}the\u{0020}invasion\u{0020}of\u{0020}Envy,\u{0020}the\u{0020}girl\u{0020}who\u{0020}lived\u{0020}near\u{0020}the\u{0020}sea\u{0020}lost\u{0020}all\u{0020}of\u{0020}her\u{0020}relatives,\u{0020}including\u{0020}those\u{0020}stray\u{0020}cats.\u{0020}She\u{0020}was\u{0020}the\u{0020}only\u{0020}survivor…hidden\u{0020}in\u{0020}a\u{0020}corner\u{0020}not\u{0020}discovered\u{0020}by\u{0020}anyone.\u{0020}Until\u{0020}she\u{0020}heard\u{0020}a\u{0020}voice\u{0020}calling\u{0020}for\u{0020}her,\u{0020}she\u{0020}went\u{0020}to\u{0020}the\u{0020}beach\u{0020}again.\n\nLooking\u{0020}at\u{0020}that\u{0020}building\u{0020}across\u{0020}the\u{0020}sea,\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}the\u{0020}girl\u{0020}knew\u{0020}what\u{0020}she\u{0020}wanted.\u{0020}She\u{0020}wanted\u{0020}family's\u{0020}love,\u{0020}she\u{0020}wanted\u{0020}friendships,\u{0020}everything\u{0020}she\u{0020}had\u{0020}done\u{0020}before,\u{0020}was\u{0020}to\u{0020}seek\u{0020}responses.\u{0020}Ain't\u{0020}she\u{0020}wanted\u{0020}to\u{0020}see\u{0020}her\u{0020}parents\u{0020}from\u{0020}this\u{0020}side\u{0020}of\u{0020}the\u{0020}sea?\n\nShe\u{0020}was\u{0020}very\u{0020}close;\u{0020}if\u{0020}she\u{0020}graduated\u{0020}from\u{0020}the\u{0020}driver's\u{0020}Academy\u{0020}of\u{0020}Danube\u{0020}as\u{0020}an\u{0020}ACE,\u{0020}she\u{0020}could\u{0020}join\u{0020}the\u{0020}3rd\u{0020}Laboratory\u{0020}Defence\u{0020}Squad,\u{0020}to\u{0020}meet\u{0020}her\u{0020}parents.\n\nBut\u{0020}now,\u{0020}years\u{0020}of\u{0020}endeavors,\u{0020}goals,\u{0020}all\u{0020}of\u{0020}them\u{0020}become\u{0020}nothing.\n\nSo,\u{0020}our\u{0020}desperate\u{0020}girl\u{0020}chose\u{0020}to\u{0020}walk\u{0020}into\u{0020}the\u{0020}sea…\n\nWhen\u{0020}she\u{0020}woke\u{0020}up\u{0020}again,\u{0020}she\u{0020}found\u{0020}herself\u{0020}rescued\u{0020}by\u{0020}AEGIS's\u{0020}SAR\u{0020}team,\u{0020}and\u{0020}she\u{0020}became\u{0020}a\u{0020}\"potential\u{0020}synesthete\"\u{0020}with\u{0020}no\u{0020}reason,\u{0020}and\u{0020}acquired\u{0020}the\u{0020}ability\u{0020}of\u{0020}reading\u{0020}others'\u{0020}moods.\u{0020}When\u{0020}she\u{0020}felt\u{0020}the\u{0020}\"happiness\"\u{0020}and\u{0020}\"joy\",\u{0020}she\u{0020}finally\u{0020}got\u{0020}driven\u{0020}to\u{0020}continue\u{0020}her\u{0020}life.\n\nAfter\u{0020}that,\u{0020}as\u{0020}she\u{0020}accepted,\u{0020}Fleur\u{0020}was\u{0020}recruited\u{0020}by\u{0020}Moon\u{0020}Corona,\u{0020}and\u{0020}became\u{0020}a\u{0020}\"Support\"\u{0020}driver.\n\nAnd\u{0020}the\u{0020}reason\u{0020}why\u{0020}she\u{0020}became\u{0020}a\u{0020}\"potential\u{0020}synesthete\",\u{0020}seems\u{0020}it\u{0020}was\u{0020}related\u{0020}to\u{0020}that\u{0020}navigator\u{0020}who\u{0020}was\u{0020}on\u{0020}a\u{0020}mission\u{0020}in\u{0020}3rd\u{0020}Laboratory.", "0", "0", "0", "0", 13013, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[631304] = {631304, 2000, "\u{0020}\u{0020}\"Fleur,\u{0020}watch\u{0020}out!\"\n\n\"Oh\u{0020}Nya~…\"\n\nThe\u{0020}girl\u{0020}nimbly\u{0020}evades\u{0020}that\u{0020}laser\u{0020}beam.\n\nAnd\u{0020}turns\u{0020}her\u{0020}head\u{0020}to\u{0020}another\u{0020}side.\n\nWhat's\u{0020}happening\u{0020}on\u{0020}the\u{0020}battlefield\u{0020}seems\u{0020}unrelated\u{0020}to\u{0020}her.\n\nSo\u{0020}what\u{0020}attracted\u{0020}her\u{0020}attention?\n\n\"Of\u{0020}course…\"\n\nWhat's\u{0020}in\u{0020}her\u{0020}eyes\u{0020}was\u{0020}that\u{0020}little\u{0020}black\u{0020}figure.\n\nAfter\u{0020}a\u{0020}long\u{0020}time\u{0020}of\u{0020}getting\u{0020}along\u{0020}and\u{0020}fight\u{0020}together,\u{0020}the\u{0020}girl\u{0020}finally\u{0020}realized:\n\n\"You\u{0020}are\u{0020}the\u{0020}one\u{0020}who\u{0020}gave\u{0020}Fleur\u{0020}power,\u{0020}and\u{0020}a\u{0020}second\u{0020}life…\"\n\n\"The\u{0020}important\u{0020}one,\u{0020}Nya~.\"", "0", "0", "0", "0", 13013, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[631400] = {631400, 0, "[Name]\u{0020}Momoka\n[B-Day]\u{0020}Jan\u{0020}9\n[Compatability\u{0020}Rate]\u{0020}90％\n[Height]\u{0020}35m\n[Squad]\u{0020}Snow\u{0020}Owl\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Stand\u{0020}in\u{0020}the\u{0020}snow\u{0020}and\u{0020}feel\u{0020}the\u{0020}snowflakes\u{0020}falling", "0", "0", "0", "0", 13014, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[631401] = {631401, 100, "\u{0020}\u{0020}One\u{0020}of\u{0020}the\u{0020}members\u{0020}of\u{0020}Katya\u{0020}Branch's\u{0020}official\u{0020}team\u{0020}\"Snow\u{0020}Owl\",\u{0020}Katya\u{0020}Branch\u{0020}is\u{0020}very\u{0020}good\u{0020}at\u{0020}fighting\u{0020}in\u{0020}the\u{0020}snow\u{0020}and\u{0020}is\u{0020}responsible\u{0020}for\u{0020}providing\u{0020}support\u{0020}to\u{0020}the\u{0020}team.\n\nUsually,\u{0020}Momoka\u{0020}is\u{0020}a\u{0020}very\u{0020}self-willed\u{0020}person.\u{0020}When\u{0020}seeing\u{0020}cute\u{0020}things,\u{0020}she\u{0020}always\u{0020}can't\u{0020}resist\u{0020}playing\u{0020}with\u{0020}them.\u{0020}Cute\u{0020}things\u{0020}include\u{0020}but\u{0020}are\u{0020}not\u{0020}limited\u{0020}to\u{0020}plush\u{0020}toys,\u{0020}various\u{0020}small\u{0020}animals,\u{0020}and\u{0020}human\u{0020}children.\u{0020}Therefore,\u{0020}the\u{0020}employees\u{0020}of\u{0020}Katya\u{0020}Branch\u{0020}never\u{0020}let\u{0020}their\u{0020}children\u{0020}appear\u{0020}in\u{0020}front\u{0020}of\u{0020}Momoka.\n\nEven\u{0020}in\u{0020}battles,\u{0020}Momoka\u{0020}would\u{0020}only\u{0020}obey\u{0020}the\u{0020}orders\u{0020}of\u{0020}Captain\u{0020}Lydia.\u{0020}However,\u{0020}when\u{0020}others\u{0020}were\u{0020}in\u{0020}danger,\u{0020}Momoka\u{0020}would\u{0020}never\u{0020}stand\u{0020}idly\u{0020}by.\u{0020}So\u{0020}far,\u{0020}in\u{0020}the\u{0020}battles\u{0020}where\u{0020}Momoka\u{0020}was\u{0020}present,\u{0020}few\u{0020}people\u{0020}died\u{0020}or\u{0020}were\u{0020}seriously\u{0020}injured.\u{0020}Therefore,\u{0020}there\u{0020}is\u{0020}a\u{0020}saying\u{0020}circulating\u{0020}in\u{0020}the\u{0020}Katya\u{0020}Army\u{0020}that\u{0020}\"As\u{0020}long\u{0020}as\u{0020}Momoka\u{0020}is\u{0020}by\u{0020}your\u{0020}side,\u{0020}you\u{0020}can\u{0020}fight\u{0020}without\u{0020}any\u{0020}restraint.\"\n\nHowever,\u{0020}Momoka\u{0020}is\u{0020}always\u{0020}cold\u{0020}when\u{0020}getting\u{0020}along\u{0020}with\u{0020}others.\u{0020}Even\u{0020}when\u{0020}chatting\u{0020}with\u{0020}others\u{0020}occasionally,\u{0020}she\u{0020}often\u{0020}looks\u{0020}into\u{0020}the\u{0020}distance\u{0020}during\u{0020}the\u{0020}conversation\u{0020}and\u{0020}then\u{0020}falls\u{0020}into\u{0020}a\u{0020}long\u{0020}silence,\u{0020}making\u{0020}the\u{0020}conversational\u{0020}partner\u{0020}embarrassed.\n\n\"It's\u{0020}not\u{0020}that\u{0020}she\u{0020}doesn't\u{0020}like\u{0020}to\u{0020}talk,\u{0020}she\u{0020}just\u{0020}doesn't\u{0020}know\u{0020}how\u{0020}to\u{0020}respond\u{0020}to\u{0020}the\u{0020}kindness\u{0020}of\u{0020}others.\"\n\nCaptain\u{0020}Lydia\u{0020}explained\u{0020}Momoka's\u{0020}coldness\u{0020}in\u{0020}this\u{0020}way.", "0", "0", "0", "0", 13014, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[631402] = {631402, 500, "\u{0020}\u{0020}Momoka's\u{0020}identity\u{0020}has\u{0020}always\u{0020}been\u{0020}a\u{0020}mystery.\n\nIt\u{0020}was\u{0020}rumored\u{0020}that\u{0020}she\u{0020}was\u{0020}a\u{0020}spirit\u{0020}of\u{0020}the\u{0020}snowfield\u{0020}and\u{0020}was\u{0020}discovered\u{0020}and\u{0020}brought\u{0020}back\u{0020}by\u{0020}Lydia\u{0020}during\u{0020}a\u{0020}mission.\u{0020}Because\u{0020}Momoka's\u{0020}body\u{0020}was\u{0020}unusually\u{0020}cold,\u{0020}those\u{0020}who\u{0020}had\u{0020}been\u{0020}in\u{0020}close\u{0020}contact\u{0020}with\u{0020}her\u{0020}described\u{0020}her\u{0020}skin\u{0020}as\u{0020}being\u{0020}as\u{0020}icy\u{0020}as\u{0020}snowflakes.\u{0020}Lydia\u{0020}never\u{0020}responded\u{0020}to\u{0020}this\u{0020}claim,\u{0020}which\u{0020}increasingly\u{0020}led\u{0020}others\u{0020}to\u{0020}believe\u{0020}that\u{0020}this\u{0020}was\u{0020}the\u{0020}truth.\n\nHowever,\u{0020}the\u{0020}truth\u{0020}is\u{0020}that\u{0020}Momoka\u{0020}is\u{0020}a\u{0020}genuine\u{0020}human\u{0020}being,\u{0020}but\u{0020}her\u{0020}life\u{0020}story\u{0020}is\u{0020}full\u{0020}of\u{0020}hardships.\n\nAccording\u{0020}to\u{0020}the\u{0020}information,\u{0020}Momoka\u{0020}is\u{0020}an\u{0020}orphan\u{0020}who\u{0020}fled\u{0020}from\u{0020}Katya\u{0020}to\u{0020}Kyushu.\u{0020}Her\u{0020}hometown\u{0020}was\u{0020}destroyed\u{0020}in\u{0020}the\u{0020}war,\u{0020}and\u{0020}her\u{0020}biological\u{0020}parents\u{0020}died\u{0020}of\u{0020}exhaustion\u{0020}after\u{0020}handing\u{0020}over\u{0020}the\u{0020}infant\u{0020}her\u{0020}to\u{0020}her\u{0020}adoptive\u{0020}parents.\u{0020}They\u{0020}only\u{0020}managed\u{0020}to\u{0020}say\u{0020}\"Momoka\",\u{0020}so\u{0020}the\u{0020}adoptive\u{0020}parents\u{0020}named\u{0020}her\u{0020}Momoka\u{0020}as\u{0020}a\u{0020}commemoration\u{0020}of\u{0020}her\u{0020}biological\u{0020}parents.\n\nBecause\u{0020}Momoka\u{0020}has\u{0020}a\u{0020}face\u{0020}like\u{0020}Katya's,\u{0020}her\u{0020}adoptive\u{0020}parents\u{0020}have\u{0020}received\u{0020}a\u{0020}lot\u{0020}of\u{0020}criticism\u{0020}in\u{0020}the\u{0020}village.\u{0020}There\u{0020}are\u{0020}always\u{0020}some\u{0020}decadent\u{0020}and\u{0020}stubborn\u{0020}people\u{0020}who\u{0020}think\u{0020}that\u{0020}Momoka\u{0020}will\u{0020}bring\u{0020}disasters\u{0020}(attacks\u{0020}from\u{0020}Sin).\u{0020}Especially\u{0020}because\u{0020}of\u{0020}her\u{0020}cold\u{0020}body\u{0020}constitution,\u{0020}the\u{0020}children\u{0020}in\u{0020}the\u{0020}village\u{0020}dare\u{0020}not\u{0020}play\u{0020}with\u{0020}her\u{0020}and\u{0020}regard\u{0020}her\u{0020}as\u{0020}ominous.\u{0020}However,\u{0020}the\u{0020}adoptive\u{0020}parents\u{0020}still\u{0020}raised\u{0020}her\u{0020}regardless\u{0020}of\u{0020}everything.\u{0020}Although\u{0020}the\u{0020}family's\u{0020}life\u{0020}was\u{0020}poor,\u{0020}it\u{0020}was\u{0020}still\u{0020}relatively\u{0020}happy.\n\nUntil\u{0020}Sin\u{0020}attacked\u{0020}this\u{0020}small\u{0020}village.\n\nEven\u{0020}though\u{0020}the\u{0020}surrounding\u{0020}patrolling\u{0020}driver\u{0020}arrived\u{0020}in\u{0020}time\u{0020}to\u{0020}kill\u{0020}Sin,\u{0020}the\u{0020}villagers\u{0020}still\u{0020}pointed\u{0020}the\u{0020}finger\u{0020}of\u{0020}this\u{0020}disaster\u{0020}at\u{0020}Momoka.\u{0020}The\u{0020}villagers\u{0020}surrounded\u{0020}Momoka's\u{0020}house\u{0020}and\u{0020}forced\u{0020}her\u{0020}adoptive\u{0020}parents\u{0020}to\u{0020}hand\u{0020}over\u{0020}Momoka,\u{0020}but\u{0020}how\u{0020}could\u{0020}they\u{0020}bear\u{0020}to\u{0020}do\u{0020}so.\u{0020}Just\u{0020}when\u{0020}the\u{0020}adoptive\u{0020}father\u{0020}was\u{0020}about\u{0020}to\u{0020}go\u{0020}out\u{0020}and\u{0020}fight\u{0020}desperately\u{0020}with\u{0020}a\u{0020}pitchfork,\u{0020}the\u{0020}usually\u{0020}introverted\u{0020}Momoka\u{0020}appeared\u{0020}voluntarily\u{0020}and\u{0020}agreed\u{0020}to\u{0020}leave\u{0020}the\u{0020}village,\u{0020}and\u{0020}this\u{0020}farce\u{0020}subsided.\n\nIn\u{0020}order\u{0020}not\u{0020}to\u{0020}cause\u{0020}any\u{0020}more\u{0020}complications,\u{0020}Momoka\u{0020}left\u{0020}the\u{0020}village\u{0020}alone\u{0020}early\u{0020}the\u{0020}next\u{0020}morning\u{0020}and\u{0020}headed\u{0020}to\u{0020}the\u{0020}nearest\u{0020}city\u{0020}hoping\u{0020}to\u{0020}find\u{0020}a\u{0020}way\u{0020}out.\n\nIn\u{0020}the\u{0020}city,\u{0020}Momoka\u{0020}saw\u{0020}the\u{0020}recruitment\u{0020}information\u{0020}of\u{0020}AVG\u{0020}driver.\u{0020}Helpless,\u{0020}she\u{0020}decided\u{0020}to\u{0020}give\u{0020}it\u{0020}a\u{0020}try.\u{0020}Fortunately,\u{0020}Momoka\u{0020}was\u{0020}admitted\u{0020}with\u{0020}a\u{0020}Compatability\u{0020}Rate\u{0020}of\u{0020}up\u{0020}to\u{0020}90%\u{0020}and\u{0020}graduated\u{0020}successfully\u{0020}with\u{0020}excellent\u{0020}grades\u{0020}and\u{0020}joined\u{0020}the\u{0020}local\u{0020}AVG\u{0020}troops.\n\nAfter\u{0020}becoming\u{0020}a\u{0020}driver,\u{0020}Momoka's\u{0020}main\u{0020}task\u{0020}every\u{0020}day\u{0020}is\u{0020}to\u{0020}patrol\u{0020}the\u{0020}border\u{0020}between\u{0020}Katya\u{0020}and\u{0020}Kyushu\u{0020}and\u{0020}often\u{0020}passes\u{0020}by\u{0020}the\u{0020}village\u{0020}of\u{0020}her\u{0020}adoptive\u{0020}parents.\u{0020}But\u{0020}she\u{0020}has\u{0020}never\u{0020}visited\u{0020}them.\u{0020}She\u{0020}is\u{0020}afraid\u{0020}of\u{0020}bringing\u{0020}extra\u{0020}troubles\u{0020}to\u{0020}her\u{0020}adoptive\u{0020}parents.\u{0020}Whenever\u{0020}this\u{0020}happens,\u{0020}Momoka\u{0020}can't\u{0020}help\u{0020}but\u{0020}think\u{0020}of\u{0020}her\u{0020}real\u{0020}hometown,\u{0020}the\u{0020}strange\u{0020}city\u{0020}in\u{0020}the\u{0020}snow\u{0020}in\u{0020}Katya.\n\n\"Perhaps\u{0020}compared\u{0020}to\u{0020}the\u{0020}current\u{0020}home,\u{0020}the\u{0020}hometown\u{0020}far\u{0020}in\u{0020}Katya\u{0020}might\u{0020}be\u{0020}easier\u{0020}to\u{0020}reach.\"\n\nSo,\u{0020}when\u{0020}the\u{0020}Snow\u{0020}Owl\u{0020}team\u{0020}from\u{0020}the\u{0020}Katya\u{0020}region\u{0020}came\u{0020}to\u{0020}the\u{0020}Kyushu\u{0020}region\u{0020}for\u{0020}cross-regional\u{0020}tasks,\u{0020}Momoka\u{0020}submitted\u{0020}an\u{0020}application\u{0020}to\u{0020}her\u{0020}superiors,\u{0020}hoping\u{0020}to\u{0020}transfer\u{0020}to\u{0020}the\u{0020}Snow\u{0020}Owl\u{0020}team.", "0", "0", "0", "0", 13014, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[631403] = {631403, 1000, "\u{0020}\u{0020}Although\u{0020}there\u{0020}had\u{0020}never\u{0020}been\u{0020}a\u{0020}cross-regional\u{0020}transfer\u{0020}before,\u{0020}Kyushu's\u{0020}AEGIS\u{0020}executives\u{0020}made\u{0020}an\u{0020}exception\u{0020}to\u{0020}transfer\u{0020}Momoka\u{0020}to\u{0020}Snow\u{0020}Owl,\u{0020}considering\u{0020}her\u{0020}Katya\u{0020}ancestry.\n\nOf\u{0020}course,\u{0020}this\u{0020}was\u{0020}also\u{0020}approved\u{0020}by\u{0020}the\u{0020}captain\u{0020}of\u{0020}the\u{0020}Snow\u{0020}Owl,\u{0020}Lydia.\n\nJoining\u{0020}Snow\u{0020}Owl,\u{0020}Momoka\u{0020}went\u{0020}to\u{0020}Katya\u{0020}Branch.\u{0020}For\u{0020}Momoka,\u{0020}who\u{0020}lived\u{0020}in\u{0020}Kyushu\u{0020}since\u{0020}childhood,\u{0020}everything\u{0020}in\u{0020}Katya\u{0020}was\u{0020}so\u{0020}strange,\u{0020}strange\u{0020}food,\u{0020}strange\u{0020}rooms,\u{0020}and\u{0020}strange\u{0020}people.\u{0020}She\u{0020}was\u{0020}originally\u{0020}introverted\u{0020}and\u{0020}was\u{0020}even\u{0020}more\u{0020}afraid\u{0020}to\u{0020}communicate\u{0020}with\u{0020}others.\u{0020}Not\u{0020}to\u{0020}mention\u{0020}there\u{0020}was\u{0020}a\u{0020}huge\u{0020}gap\u{0020}between\u{0020}her\u{0020}and\u{0020}the\u{0020}people\u{0020}of\u{0020}Katya\u{0020}-\u{0020}Momoka\u{0020}was\u{0020}not\u{0020}good\u{0020}at\u{0020}the\u{0020}Katya\u{0020}language.\u{0020}Among\u{0020}the\u{0020}Snow\u{0020}Owl,\u{0020}only\u{0020}the\u{0020}captain\u{0020}Lydia\u{0020}had\u{0020}learned\u{0020}a\u{0020}little\u{0020}Kyushu\u{0020}language.\n\nSo\u{0020}in\u{0020}the\u{0020}eyes\u{0020}of\u{0020}outsiders,\u{0020}it\u{0020}seems\u{0020}that\u{0020}Momoka\u{0020}only\u{0020}listens\u{0020}to\u{0020}the\u{0020}captain\u{0020}and\u{0020}ignores\u{0020}everyone\u{0020}else.\u{0020}However,\u{0020}when\u{0020}seeing\u{0020}others\u{0020}in\u{0020}danger,\u{0020}Momoka\u{0020}will\u{0020}not\u{0020}stand\u{0020}by\u{0020}idly\u{0020}and\u{0020}can\u{0020}always\u{0020}provide\u{0020}help\u{0020}in\u{0020}time.\n\nWhen\u{0020}there\u{0020}is\u{0020}no\u{0020}mission\u{0020}at\u{0020}ordinary\u{0020}times,\u{0020}Momoka\u{0020}likes\u{0020}to\u{0020}stand\u{0020}in\u{0020}the\u{0020}snow\u{0020}and\u{0020}meditate,\u{0020}recalling\u{0020}the\u{0020}appearance\u{0020}of\u{0020}her\u{0020}home\u{0020}far\u{0020}away\u{0020}in\u{0020}Kyushu.\n\n\"I\u{0020}don't\u{0020}know\u{0020}where\u{0020}my\u{0020}true\u{0020}hometown\u{0020}is\u{0020}again.\"", "0", "0", "0", "0", 13014, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[631404] = {631404, 2000, "\u{0020}\u{0020}The\u{0020}white\u{0020}snow\u{0020}cannot\u{0020}cover\u{0020}the\u{0020}huge\u{0020}white\u{0020}maiden.\n\nThe\u{0020}maiden\u{0020}left\u{0020}one\u{0020}huge\u{0020}deep\u{0020}pit\u{0020}after\u{0020}another\u{0020}on\u{0020}the\u{0020}snow.\n\nIt\u{0020}seems\u{0020}that\u{0020}she\u{0020}is\u{0020}looking\u{0020}for\u{0020}something.\n\nHer\u{0020}appearance\u{0020}is\u{0020}as\u{0020}cold\u{0020}as\u{0020}snow.\n\nHer\u{0020}heart\u{0020}is\u{0020}as\u{0020}hot\u{0020}as\u{0020}the\u{0020}sun.\n\nShe\u{0020}wants\u{0020}to\u{0020}melt\u{0020}the\u{0020}ice\u{0020}and\u{0020}snow\u{0020}like\u{0020}the\u{0020}sun\u{0020}to\u{0020}find\u{0020}the\u{0020}way\u{0020}to\u{0020}her\u{0020}hometown.\n\n\"I\u{0020}don't\u{0020}know\u{0020}where\u{0020}my\u{0020}home\u{0020}is,\u{0020}but\u{0020}I\u{0020}will\u{0020}keep\u{0020}looking.\"\n\n\"If\u{0020}this\u{0020}place\u{0020}is\u{0020}not\u{0020}my\u{0020}hometown,\u{0020}will\u{0020}you\u{0020}still\u{0020}accompany\u{0020}me\u{0020}to\u{0020}keep\u{0020}looking,\u{0020}Navigator?\"", "0", "0", "0", "0", 13014, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
