[631501] = {631501, 100, "\u{0020}\u{0020}Lina\u{0020}Vuon\u{0020}belongs\u{0020}to\u{0020}the\u{0020}\"Superhero\u{0020}Association\"\u{0020}of\u{0020}the\u{0020}Ninja\u{0020}Group.\u{0020}Behind\u{0020}the\u{0020}scenes,\u{0020}she\u{0020}is\u{0020}actually\u{0020}Masked\u{0020}Ranger\u{0020}1,\u{0020}who\u{0020}is\u{0020}dedicated\u{0020}to\u{0020}fighting\u{0020}criminals\u{0020}and\u{0020}maintaining\u{0020}peace.\u{0020}Because\u{0020}of\u{0020}her\u{0020}unique\u{0020}combat\u{0020}style\u{0020}and\u{0020}enthusiastic\u{0020}personality,\u{0020}she\u{0020}is\u{0020}a\u{0020}well-known\u{0020}figure\u{0020}in\u{0020}Maya\u{0020}Branch.\u{0020}After\u{0020}a\u{0020}long\u{0020}time,\u{0020}it\u{0020}has\u{0020}become\u{0020}an\u{0020}unspoken\u{0020}secret\u{0020}that\u{0020}she\u{0020}is\u{0020}\"Masked\u{0020}Ranger\u{0020}1\".\u{0020}Lina\u{0020}herself\u{0020}has\u{0020}no\u{0020}intention\u{0020}of\u{0020}hiding\u{0020}this\u{0020}identity\u{0020}from\u{0020}everyone:\u{0020}although\u{0020}she\u{0020}calls\u{0020}herself\u{0020}\"Masked\u{0020}Ranger\u{0020}1\",\u{0020}she\u{0020}has\u{0020}never\u{0020}seen\u{0020}wearing\u{0020}a\u{0020}mask\u{0020}when\u{0020}she\u{0020}acts\u{0020}of\u{0020}righteousness.\u{0020}But\u{0020}what\u{0020}makes\u{0020}everyone\u{0020}curious\u{0020}is\u{0020}that\u{0020}Lina\u{0020}obviously\u{0020}calls\u{0020}herself\u{0020}\"1\",\u{0020}but\u{0020}she\u{0020}has\u{0020}a\u{0020}\"06\"\u{0020}mark\u{0020}on\u{0020}she,\u{0020}which\u{0020}is\u{0020}particularly\u{0020}eye-catching.\n\nBecause\u{0020}the\u{0020}\"Superhero\u{0020}Association\"\u{0020}currently\u{0020}has\u{0020}only\u{0020}one\u{0020}\"superhero\"\u{0020}Lina,\u{0020}she\u{0020}always\u{0020}follows\u{0020}the\u{0020}other\u{0020}teams\u{0020}and\u{0020}especially\u{0020}likes\u{0020}to\u{0020}protect\u{0020}the\u{0020}new\u{0020}drivers\u{0020}who\u{0020}have\u{0020}just\u{0020}graduated\u{0020}from\u{0020}the\u{0020}academy.", "0", "0", "0", "0", 13015, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[631502] = {631502, 500, "\u{0020}\u{0020}Lina\u{0020}Vuon\u{0020}was\u{0020}born\u{0020}into\u{0020}an\u{0020}extremely\u{0020}privileged\u{0020}family.\u{0020}Her\u{0020}father\u{0020}and\u{0020}mother\u{0020}were\u{0020}the\u{0020}largest\u{0020}consortium\u{0020}in\u{0020}their\u{0020}city.\u{0020}However,\u{0020}she\u{0020}abandoned\u{0020}her\u{0020}smooth-sailing\u{0020}life\u{0020}and\u{0020}became\u{0020}a\u{0020}driver.\u{0020}What's\u{0020}even\u{0020}more\u{0020}fantastic\u{0020}is\u{0020}that\u{0020}her\u{0020}parents\u{0020}approved\u{0020}of\u{0020}their\u{0020}daughter's\u{0020}wayward\u{0020}behavior\u{0020}and\u{0020}actively\u{0020}taught\u{0020}her\u{0020}combat\u{0020}skills.\n\nThe\u{0020}Vuon\u{0020}couple\u{0020}has\u{0020}only\u{0020}one\u{0020}daughter\u{0020}as\u{0020}the\u{0020}heir.\u{0020}Why\u{0020}were\u{0020}they\u{0020}willing\u{0020}to\u{0020}let\u{0020}their\u{0020}only\u{0020}child\u{0020}go\u{0020}to\u{0020}the\u{0020}dangerous\u{0020}battlefield?\u{0020}When\u{0020}did\u{0020}the\u{0020}big\u{0020}shots\u{0020}of\u{0020}the\u{0020}consortium\u{0020}have\u{0020}such\u{0020}a\u{0020}lofty\u{0020}awareness\u{0020}of\u{0020}\"fighting\u{0020}for\u{0020}humanity\"?\n\nAccording\u{0020}to\u{0020}Lina\u{0020}herself,\u{0020}she\u{0020}did\u{0020}this\u{0020}in\u{0020}order\u{0020}to\u{0020}become\u{0020}like\u{0020}her\u{0020}parents.\n\nIt\u{0020}was\u{0020}a\u{0020}story\u{0020}that\u{0020}happened\u{0020}when\u{0020}she\u{0020}was\u{0020}still\u{0020}young.\u{0020}That\u{0020}day,\u{0020}she\u{0020}just\u{0020}finished\u{0020}watching\u{0020}a\u{0020}movie\u{0020}with\u{0020}her\u{0020}parents,\u{0020}walked\u{0020}through\u{0020}an\u{0020}alley,\u{0020}and\u{0020}then\u{0020}witnessed\u{0020}an\u{0020}event\u{0020}that\u{0020}she\u{0020}would\u{0020}never\u{0020}forget\u{0020}for\u{0020}her\u{0020}entire\u{0020}life,\u{0020}a\u{0020}murder\u{0020}case.\n\nThe\u{0020}gangsters\u{0020}immediately\u{0020}decided\u{0020}to\u{0020}silence\u{0020}the\u{0020}witnesses\u{0020}by\u{0020}killing\u{0020}them.\u{0020}But\u{0020}before\u{0020}they\u{0020}could\u{0020}do\u{0020}anything,\u{0020}it\u{0020}was\u{0020}the\u{0020}Vuon\u{0020}couple\u{0020}-\u{0020}Lina's\u{0020}father\u{0020}and\u{0020}mother\u{0020}-\u{0020}who\u{0020}took\u{0020}the\u{0020}initiative.\u{0020}They\u{0020}fought\u{0020}against\u{0020}the\u{0020}gangsters\u{0020}armed\u{0020}with\u{0020}weapons\u{0020}barehandedly\u{0020}and\u{0020}defeated\u{0020}all\u{0020}the\u{0020}gangsters\u{0020}within\u{0020}2\u{0020}minutes.\n\n\"Mom\u{0020}and\u{0020}Dad\u{0020}used\u{0020}to\u{0020}be\u{0020}superheroes,\"\u{0020}the\u{0020}father\u{0020}and\u{0020}mother\u{0020}explained\u{0020}to\u{0020}the\u{0020}young\u{0020}Lina.\n\n\"That's\u{0020}why\u{0020}I\u{0020}want\u{0020}to\u{0020}be\u{0020}like\u{0020}Mom\u{0020}and\u{0020}Dad\u{0020}when\u{0020}I\u{0020}grow\u{0020}up,\"\u{0020}the\u{0020}young\u{0020}Lina\u{0020}promised\u{0020}her\u{0020}parents.\n\nThen\u{0020}-\u{0020}not\u{0020}long\u{0020}after\u{0020}Lina\u{0020}started\u{0020}her\u{0020}driver\u{0020}activities,\u{0020}her\u{0020}parents\u{0020}died\u{0020}in\u{0020}a\u{0020}criminal\u{0020}activity.", "0", "0", "0", "0", 13015, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[631503] = {631503, 1000, "\u{0020}\u{0020}\"I'm\u{0020}Lina,\u{0020}Lina\u{0020}Vuon.\u{0020}Boy,\u{0020}do\u{0020}you\u{0020}want\u{0020}to\u{0020}be\u{0020}my\u{0020}partner?\"\n\n\"Why\u{0020}did\u{0020}I\u{0020}choose\u{0020}you?\u{0020}Hmph~\u{0020}Because\u{0020}I\u{0020}was\u{0020}just\u{0020}looking\u{0020}for\u{0020}a\u{0020}teammate\u{0020}with\u{0020}'heroic\u{0020}aspirations',\u{0020}and\u{0020}I\u{0020}think\u{0020}you\u{0020}are\u{0020}such\u{0020}a\u{0020}person.\"\n\n\"The\u{0020}'Superhero\u{0020}Association'\u{0020}needs\u{0020}talents\u{0020}like\u{0020}you.\u{0020}Well...\u{0020}It\u{0020}doesn't\u{0020}matter\u{0020}if\u{0020}you\u{0020}are\u{0020}a\u{0020}navigator.\u{0020}I'm\u{0020}a\u{0020}hero,\u{0020}so\u{0020}I\u{0020}will\u{0020}protect\u{0020}you.\u{0020}You\u{0020}can\u{0020}just\u{0020}be\u{0020}our\u{0020}brain!\"\n\n\"Well,\u{0020}from\u{0020}now\u{0020}on,\u{0020}your\u{0020}title\u{0020}will\u{0020}be\u{0020}'Masked\u{0020}Ranger\u{0020}2'.\u{0020}What\u{0020}do\u{0020}you\u{0020}think?\u{0020}Eh...\u{0020}Too\u{0020}tacky?...\u{0020}But\u{0020}I\u{0020}think\u{0020}it's\u{0020}very\u{0020}cool!\"\n\n\"Do\u{0020}you\u{0020}want\u{0020}your\u{0020}own\u{0020}mask?\u{0020}Ah...\u{0020}We\u{0020}don't\u{0020}have\u{0020}it\u{0020}yet,\u{0020}because\u{0020}I\u{0020}haven't\u{0020}decided\u{0020}whether\u{0020}to\u{0020}make\u{0020}standard\u{0020}team\u{0020}uniforms\u{0020}of\u{0020}different\u{0020}colors\u{0020}or\u{0020}customize\u{0020}them\u{0020}according\u{0020}to\u{0020}everyone's\u{0020}preferences...\u{0020}At\u{0020}least\u{0020}I'll\u{0020}consider\u{0020}this\u{0020}matter\u{0020}after\u{0020}finding\u{0020}all\u{0020}the\u{0020}other\u{0020}three\u{0020}members!\"", "0", "0", "0", "0", 13015, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[631504] = {631504, 2000, "\u{0020}\u{0020}Boy~\n\nI\u{0020}become\u{0020}a\u{0020}superhero\u{0020}to\u{0020}protect\u{0020}everyone\n\nAnd\u{0020}you\u{0020}can\u{0020}be\u{0020}my\u{0020}hero.\n\nLet\u{0020}the\u{0020}two\u{0020}of\u{0020}us\u{0020}be\u{0020}like\u{0020}my\u{0020}father\u{0020}and\u{0020}mother.\n\nI\u{0020}have\u{0020}a\u{0020}premonition\u{0020}that\u{0020}our\u{0020}life\u{0020}will\u{0020}definitely\u{0020}be\u{0020}very\u{0020}interesting.\n\nIt\u{0020}must\u{0020}be\u{0020}a\u{0020}story\u{0020}full\u{0020}of\u{0020}happiness\u{0020}and\u{0020}hope\n\nThen,\u{0020}the\u{0020}time\u{0020}we\u{0020}are\u{0020}spending\u{0020}together\u{0020}in\u{0020}the\u{0020}secret\u{0020}base\u{0020}now\n\nIt\u{0020}must\u{0020}be\u{0020}our\u{0020}most\u{0020}wonderful\u{0020}memory.", "0", "0", "0", "0", 13015, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
[631600] = {631600, 0, "[Name]:\u{0020}Dolores\u{0020}Gaviota\n\u{0020}[B-Day]:\u{0020}Jan.1\n\u{0020}\u{0020}[Transformation\u{0020}Core\u{0020}Proficiency]:\u{0020}46%\u{0020}(+13%)\n\u{0020}\u{0020}[Height]:\u{0020}34m\n\u{0020}\u{0020}[Squa]:\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\n\u{0020}\u{0020}[Affiliation]:\u{0020}Danube\u{0020}Branch\n\u{0020}\u{0020}[Interest]:\u{0020}Seagull", "0", "0", "0", "0", 13016, "0", "0", "0", "0", 0, 1, "0", "0", "0"},
[631601] = {631601, 100, "\u{3000}\u{3000}While\u{0020}eating\u{0020}with\u{0020}Dolores,\u{0020}we\u{0020}talked\u{0020}about\u{0020}why\u{0020}she\u{0020}had\u{0020}appeared\u{0020}in\u{0020}the\u{0020}Ark\u{0020}district\u{0020}of\u{0020}Danube.\n\u{3000}\u{3000}\"Actually,\u{0020}3rd\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}sometimes\u{0020}gets\u{0020}sent\u{0020}to\u{0020}help\u{0020}out\u{0020}in\u{0020}other\u{0020}areas\u{0020}now,\"\u{0020}Dolores\u{0020}explained.\u{0020}\"Usually\u{0020}it's\u{0020}to\u{0020}carry\u{0020}out\u{0020}missions\u{0020}in\u{0020}more\u{0020}remote\u{0020}places,\u{0020}so\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}this\u{0020}time\u{0020}to\u{0020}be\u{0020}this\u{0020}close\u{0020}to\u{0020}the\u{0020}Ark.\u{0020}I\u{0020}thought\u{0020}I'd\u{0020}take\u{0020}the\u{0020}chance\u{0020}to\u{0020}come\u{0020}back\u{0020}and\u{0020}see\u{0020}everyone.\"\n\u{3000}\u{3000}\"Take\u{0020}the\u{0020}chance\u{0020}to\u{0020}come\u{0020}back\u{0020}to\u{0020}the\u{0020}Ark...\u{0020}then\u{0020}why\u{0020}didn't\u{0020}you\u{0020}tell\u{0020}me?\"\u{0020}Whether\u{0020}as\u{0020}a\u{0020}former\u{0020}comrade-in-arms\u{0020}or\u{0020}as\u{0020}a\u{0020}friend\u{0020}I\u{0020}hadn't\u{0020}seen\u{0020}in\u{0020}a\u{0020}long\u{0020}time,\u{0020}I\u{0020}knew\u{0020}I\u{0020}would\u{0020}have\u{0020}been\u{0020}happy\u{0020}to\u{0020}see\u{0020}Dolores.\u{0020}Could\u{0020}she\u{0020}have\u{0020}had\u{0020}some\u{0020}reason\u{0020}she\u{0020}couldn't\u{0020}say?\u{0020}\"Was\u{0020}it\u{0020}because\u{0020}you\u{0020}were\u{0020}on\u{0020}a\u{0020}mission\u{0020}and\u{0020}it\u{0020}wasn't\u{0020}convenient\u{0020}to\u{0020}see\u{0020}me?\"\n\u{3000}\u{3000}\"No...\u{0020}actually...\"\u{0020}A\u{0020}rare\u{0020}look\u{0020}of\u{0020}hesitation\u{0020}appeared\u{0020}on\u{0020}Dolores's\u{0020}face.\u{0020}\"I\u{0020}just\u{0020}wasn't\u{0020}ready\u{0020}yet...\"\n\u{3000}\u{3000}\"Ahem...\u{0020}I\u{0020}felt\u{0020}like\u{0020}I\u{0020}should\u{0020}be\u{0020}more\u{0020}mature\u{0020}and\u{0020}composed...\u{0020}but\u{0020}I\u{0020}just\u{0020}couldn't\u{0020}settle\u{0020}my\u{0020}heart.\"\u{0020}She\u{0020}gave\u{0020}me\u{0020}an\u{0020}apologetic\u{0020}smile.", "0", "0", "0", "0", 13016, "0", "0", "0", "0", 0, 2, "0", "0", "0"},
[631602] = {631602, 500, "\u{3000}\u{3000}As\u{0020}for\u{0020}the\u{0020}follow-up\u{0020}investigation\u{0020}into\u{0020}the\u{0020}statue\u{0020}Dolores\u{0020}had.\n\u{3000}\u{3000}During\u{0020}my\u{0020}brief\u{0020}time\u{0020}with\u{0020}Dolores,\u{0020}I\u{0020}was\u{0020}too\u{0020}curious\u{0020}not\u{0020}to\u{0020}ask\u{0020}in\u{0020}the\u{0020}end\u{0020}what\u{0020}exactly\u{0020}the\u{0020}stone\u{0020}she\u{0020}found\u{0020}that\u{0020}day\u{0020}was.\n\u{3000}\u{3000}\"This?\u{0020}Um...\u{0020}supposedly\u{0020}it's\u{0020}a\u{0020}magical\u{0020}girl\u{0020}transformation\u{0020}device\u{0020}that\u{0020}brings\u{0020}miracles...\u{0020}I\u{0020}don't\u{0020}really\u{0020}know\u{0020}either...\u{0020}sorry...\u{0020}that's\u{0020}why\u{0020}I\u{0020}couldn't\u{0020}really\u{0020}tell\u{0020}Navigator\u{0020}what\u{0020}it\u{0020}was\u{0020}back\u{0020}then...\"\u{0020}Dolores\u{0020}herself\u{0020}did\u{0020}not\u{0020}seem\u{0020}very\u{0020}sure.\n\u{3000}\u{3000}\"I\u{0020}see...\u{0020}if\u{0020}it\u{0020}isn't\u{0020}something\u{0020}like\u{0020}a\u{0020}sword\u{0020}or\u{0020}a\u{0020}robot\u{0020}warrior,\u{0020}some\u{0020}kind\u{0020}of\u{0020}stone\u{0020}whose\u{0020}concept\u{0020}or\u{0020}origin\u{0020}I\u{0020}clearly\u{0020}know,\u{0020}then\u{0020}it's\u{0020}really\u{0020}hard\u{0020}to\u{0020}identify...\"\u{0020}I\u{0020}said\u{0020}thoughtfully.\u{0020}\"What\u{0020}exactly\u{0020}is\u{0020}going\u{0020}on\u{0020}with\u{0020}that\u{0020}garden...\u{0020}to\u{0020}think\u{0020}you\u{0020}can\u{0020}pick\u{0020}up\u{0020}such\u{0020}strange\u{0020}stones\u{0020}there.\"\n\u{3000}\u{3000}\"Hm...?\u{0020}This\u{0020}stone\u{0020}wasn't\u{0020}picked\u{0020}up\u{0020}in\u{0020}the\u{0020}garden.\"\n\u{3000}\u{3000}\"Wasn't\u{0020}it\u{0020}picked\u{0020}up\u{0020}in\u{0020}the\u{0020}garden\u{0020}and\u{0020}then\u{0020}given\u{0020}to\u{0020}you?\"\n\u{3000}\u{3000}\"...Captain\u{0020}Angelica\u{0020}said\u{0020}this\u{0020}was\u{0020}a\u{0020}charm\u{0020}given\u{0020}to\u{0020}her\u{0020}by\u{0020}a\u{0020}driver\u{0020}who\u{0020}once\u{0020}saved\u{0020}her\u{0020}when\u{0020}she\u{0020}was\u{0020}still\u{0020}little.\"\u{0020}Dolores\u{0020}took\u{0020}the\u{0020}\"charm\"\u{0020}out\u{0020}of\u{0020}her\u{0020}pocket\u{0020}and\u{0020}gently\u{0020}rubbed\u{0020}it\u{0020}with\u{0020}her\u{0020}fingers.\u{0020}\"Then\u{0020}it\u{0020}passed\u{0020}from\u{0020}Captain\u{0020}Angelica\u{0020}to\u{0020}me.\u{0020}Isn't\u{0020}that\u{0020}amazing?\u{0020}It's\u{0020}like\u{0020}the\u{0020}driver's\u{0020}will\u{0020}is\u{0020}being\u{0020}passed\u{0020}on\u{0020}and\u{0020}carried\u{0020}forward\u{0020}through\u{0020}this\u{0020}stone.\u{0020}At\u{0020}first,\u{0020}I\u{0020}even\u{0020}thought\u{0020}that\u{0020}if\u{0020}I\u{0020}couldn't\u{0020}find\u{0020}it,\u{0020}maybe\u{0020}some\u{0020}next\u{0020}driver\u{0020}would\u{0020}pick\u{0020}up\u{0020}this\u{0020}stone,\u{0020}and\u{0020}then\u{0020}this\u{0020}'baton'\u{0020}would\u{0020}just\u{0020}keep\u{0020}being\u{0020}passed\u{0020}along.\"\n\u{3000}\u{3000}\"Then\u{0020}it's\u{0020}better\u{0020}if\u{0020}you\u{0020}keep\u{0020}carrying\u{0020}it\u{0020}with\u{0020}you.\"\n\u{3000}\u{3000}\"Of\u{0020}course...\u{0020}I\u{0020}won't\u{0020}lose\u{0020}it\u{0020}again.\"", "0", "0", "0", "0", 13016, "0", "0", "0", "0", 0, 3, "0", "0", "0"},
[631603] = {631603, 1000, "\u{3000}\u{3000}\"Navigator...\u{0020}are\u{0020}you\u{0020}free\u{0020}tomorrow?\"\u{0020}Dolores\u{0020}asked\u{0020}at\u{0020}the\u{0020}end\u{0020}of\u{0020}dinner.\n\u{3000}\u{3000}\"Mm...\u{0020}I'm\u{0020}not\u{0020}especially\u{0020}busy\u{0020}lately...\u{0020}and\u{0020}the\u{0020}strange\u{0020}task\u{0020}assigned\u{0020}to\u{0020}me\u{0020}was\u{0020}finished\u{0020}today.\"\u{0020}I\u{0020}thought\u{0020}it\u{0020}over\u{0020}seriously\u{0020}before\u{0020}answering.\n\u{3000}\u{3000}When\u{0020}she\u{0020}heard\u{0020}that,\u{0020}Dolores's\u{0020}eyes\u{0020}seemed\u{0020}to\u{0020}light\u{0020}up\u{0020}noticeably.\u{0020}Perhaps\u{0020}she\u{0020}herself\u{0020}hadn't\u{0020}realized\u{0020}it,\u{0020}but\u{0020}just\u{0020}a\u{0020}moment\u{0020}ago\u{0020}the\u{0020}words\u{0020}\"nervous\u{0020}and\u{0020}uneasy\"\u{0020}had\u{0020}practically\u{0020}been\u{0020}written\u{0020}all\u{0020}over\u{0020}her\u{0020}face.\u{0020}Now,\u{0020}however,\u{0020}her\u{0020}expression\u{0020}had\u{0020}completely\u{0020}changed\u{0020}to\u{0020}\"happy.\"\n\u{3000}\u{3000}\"Then...\u{0020}would\u{0020}you\u{0020}like\u{0020}to\u{0020}walk\u{0020}around\u{0020}downtown\u{0020}Danube\u{0020}with\u{0020}me\u{0020}tomorrow?\"\u{0020}With\u{0020}a\u{0020}lively\u{0020}tone,\u{0020}Dolores\u{0020}waited\u{0020}for\u{0020}my\u{0020}answer.\u{0020}Or\u{0020}perhaps,\u{0020}having\u{0020}realized\u{0020}her\u{0020}feelings\u{0020}were\u{0020}already\u{0020}written\u{0020}plain\u{0020}on\u{0020}her\u{0020}face,\u{0020}she\u{0020}no\u{0020}longer\u{0020}intended\u{0020}to\u{0020}hide\u{0020}them.\u{0020}\"I\u{0020}want\u{0020}to\u{0020}spend\u{0020}the\u{0020}time\u{0020}ahead\u{0020}with\u{0020}Navigator.\"", "0", "0", "0", "0", 13016, "0", "0", "0", "0", 0, 4, "0", "0", "0"},
[631604] = {631604, 2000, "\u{3000}\u{3000}I\u{0020}thought\u{0020}I\u{0020}had\u{0020}already\u{0020}grown\u{0020}up.\n\u{3000}\u{3000}I\u{0020}thought\u{0020}becoming\u{0020}someone\u{0020}everyone\u{0020}could\u{0020}rely\u{0020}on\u{0020}meant\u{0020}I\u{0020}had\u{0020}become\u{0020}mature.\n\u{3000}\u{3000}But...\n\u{3000}\u{3000}when\u{0020}I\u{0020}can't\u{0020}see\u{0020}someone,\u{0020}I\u{0020}still\u{0020}feel\u{0020}a\u{0020}little\u{0020}lonely.\n\u{3000}\u{3000}I\u{0020}thought\u{0020}I\u{0020}was\u{0020}no\u{0020}longer\u{0020}aimless.\n\u{3000}\u{3000}I\u{0020}thought\u{0020}protecting\u{0020}everyone's\u{0020}smiles\u{0020}would\u{0020}be\u{0020}enough\u{0020}to\u{0020}satisfy\u{0020}me.\n\u{3000}\u{3000}But...\n\u{3000}\u{3000}I\u{0020}still\u{0020}find\u{0020}myself\u{0020}imagining\u{0020}that\u{0020}someone\u{0020}might\u{0020}smile\u{0020}at\u{0020}me.\n\u{3000}\u{3000}I\u{0020}don't\u{0020}want\u{0020}to\u{0020}keep\u{0020}waiting\u{0020}anymore.\n\u{3000}\u{3000}Even\u{0020}if\u{0020}the\u{0020}time\u{0020}we\u{0020}spend\u{0020}together\u{0020}is\u{0020}so\u{0020}brief.\n\u{3000}\u{3000}I\u{0020}will\u{0020}still\u{0020}do\u{0020}everything\u{0020}I\u{0020}can\u{0020}to\u{0020}hold\u{0020}on\u{0020}to\u{0020}you...\n\u{3000}\u{3000}my\u{0020}Navigator", "0", "0", "0", "0", 13016, "0", "0", "0", "0", 0, 5, "0", "0", "0"},
