[631701] = {631701, 100, "From\u{0020}the\u{0020}surface\u{0020}data,\u{0020}Tsukumo\u{0020}Tamaki\u{0020}will\u{0020}be\u{0020}listed\u{0020}as\u{0020}one\u{0020}of\u{0020}humanity's\u{0020}hopes\u{0020}to\u{0020}save\u{0020}the\u{0020}world,\u{0020}because\u{0020}she\u{0020}showed\u{0020}her\u{0020}talent\u{0020}at\u{0020}the\u{0020}beginning\u{0020}of\u{0020}school\u{0020}-\u{0020}as\u{0020}a\u{0020}preparatory\u{0020}navigator\u{0020}who\u{0020}has\u{0020}only\u{0020}been\u{0020}exposed\u{0020}to\u{0020}theoretical\u{0020}knowledge,\u{0020}she\u{0020}won\u{0020}the\u{0020}first\u{0020}place\u{0020}in\u{0020}the\u{0020}test\u{0020}that\u{0020}all\u{0020}navigators\u{0020}participate\u{0020}in.\n\nHowever,\u{0020}based\u{0020}on\u{0020}the\u{0020}surface\u{0020}data\u{0020}analysis,\u{0020}Tsukumo\u{0020}Tamaki\u{0020}is\u{0020}likely\u{0020}to\u{0020}be\u{0020}imprisoned\u{0020}because\u{0020}her\u{0020}performance,\u{0020}both\u{0020}in\u{0020}theory\u{0020}and\u{0020}in\u{0020}simulation\u{0020}battles,\u{0020}has\u{0020}reached\u{0020}the\u{0020}theoretical\u{0020}limit.\u{0020}Her\u{0020}achievements\u{0020}point\u{0020}to\u{0020}only\u{0020}two\u{0020}possibilities\u{0020}-\u{0020}either\u{0020}there\u{0020}is\u{0020}a\u{0020}leak\u{0020}within\u{0020}AEGIS,\u{0020}or\u{0020}she\u{0020}is\u{0020}a\u{0020}hacker\u{0020}who\u{0020}has\u{0020}broken\u{0020}through\u{0020}the\u{0020}AEGIS\u{0020}system.\n\nAnyway,\u{0020}it\u{0020}is\u{0020}certain\u{0020}that\u{0020}she\u{0020}did\u{0020}not\u{0020}hide\u{0020}her\u{0020}abnormality.\u{0020}She\u{0020}was\u{0020}trying\u{0020}to\u{0020}attract\u{0020}someone's\u{0020}attention.", "0", "0", "0", "0", 13017, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[631702] = {631702, 500, "Tsukumo\u{0020}Tamaki\u{0020}claims\u{0020}to\u{0020}be\u{0020}a\u{0020}person\u{0020}with\u{0020}the\u{0020}superpower\u{0020}of\u{0020}\"predicting\u{0020}the\u{0020}future\".\u{0020}Along\u{0020}with\u{0020}this\u{0020}statement\u{0020}comes\u{0020}the\u{0020}special\u{0020}deployment\u{0020}of\u{0020}Tsukumo\u{0020}Tamaki\u{0020}and\u{0020}the\u{0020}upgrade\u{0020}of\u{0020}the\u{0020}confidentiality\u{0020}level.\n\nTrace\u{0020}her\u{0020}life.\u{0020}Before\u{0020}coming\u{0020}to\u{0020}AEGIS,\u{0020}Tsukumo\u{0020}Tamaki\u{0020}had\u{0020}an\u{0020}\"ordinary\"\u{0020}life.\u{0020}Her\u{0020}family\u{0020}was\u{0020}originally\u{0020}in\u{0020}a\u{0020}small\u{0020}village\u{0020}in\u{0020}Kyushu\u{0020}and\u{0020}her\u{0020}parents\u{0020}ran\u{0020}a\u{0020}trading\u{0020}company.\u{0020}From\u{0020}the\u{0020}age\u{0020}of\u{0020}eight\u{0020}until\u{0020}adulthood,\u{0020}she\u{0020}moved\u{0020}many\u{0020}times\u{0020}as\u{0020}her\u{0020}parents'\u{0020}company\u{0020}improved.\u{0020}This\u{0020}is\u{0020}why\u{0020}she\u{0020}became\u{0020}a\u{0020}navigator\u{0020}in\u{0020}Danube\u{0020}-\u{0020}within\u{0020}the\u{0020}next\u{0020}two\u{0020}years,\u{0020}her\u{0020}family\u{0020}will\u{0020}expand\u{0020}their\u{0020}business\u{0020}in\u{0020}Danube.\n\nFrom\u{0020}this\u{0020}received\u{0020}report,\u{0020}the\u{0020}resume\u{0020}of\u{0020}Tsukumo\u{0020}Tamaki\u{0020}has\u{0020}no\u{0020}problems\u{0020}at\u{0020}all\u{0020}and\u{0020}is\u{0020}even\u{0020}somewhat\u{0020}ordinary.\n\nHowever,\u{0020}if\u{0020}combined\u{0020}with\u{0020}another\u{0020}piece\u{0020}of\u{0020}information,\u{0020}her\u{0020}anomaly\u{0020}will\u{0020}be\u{0020}discovered.\n\nEvery\u{0020}time,\u{0020}almost\u{0020}every\u{0020}time,\u{0020}with\u{0020}her\u{0020}moving\u{0020}away,\u{0020}the\u{0020}area\u{0020}where\u{0020}she\u{0020}was\u{0020}located\u{0020}would\u{0020}be\u{0020}attacked\u{0020}by\u{0020}Sin.\u{0020}At\u{0020}the\u{0020}same\u{0020}time,\u{0020}AEGIS\u{0020}would\u{0020}receive\u{0020}anonymous\u{0020}reminder\u{0020}letters\u{0020}before\u{0020}Sin's\u{0020}attack.\u{0020}But\u{0020}unfortunately,\u{0020}those\u{0020}letters\u{0020}were\u{0020}not\u{0020}taken\u{0020}seriously\u{0020}until\u{0020}we\u{0020}started\u{0020}to\u{0020}investigate,\u{0020}and\u{0020}then\u{0020}everything\u{0020}became\u{0020}clear.\n\n……\n\nA\u{0020}message\u{0020}from\u{0020}the\u{0020}headquarters\u{0020}has\u{0020}been\u{0020}received.\u{0020}The\u{0020}investigation\u{0020}and\u{0020}file\u{0020}writing\u{0020}of\u{0020}Tsukumo\u{0020}Tamaki\u{0020}will\u{0020}be\u{0020}suspended.\u{0020}But\u{0020}before\u{0020}that,\u{0020}please\u{0020}allow\u{0020}me\u{0020}to\u{0020}add\u{0020}a\u{0020}footnote\u{0020}at\u{0020}the\u{0020}end\u{0020}and\u{0020}leave\u{0020}the\u{0020}editing\u{0020}history\u{0020}record.\n\nSuch\u{0020}a\u{0020}person\u{0020}with\u{0020}special\u{0020}abilities,\u{0020}why\u{0020}did\u{0020}she\u{0020}choose\u{0020}to\u{0020}expose\u{0020}her\u{0020}ability?\u{0020}Why\u{0020}did\u{0020}she\u{0020}hide\u{0020}herself\u{0020}in\u{0020}the\u{0020}form\u{0020}of\u{0020}anonymous\u{0020}letters\u{0020}in\u{0020}her\u{0020}previous\u{0020}life,\u{0020}but\u{0020}change\u{0020}her\u{0020}mind\u{0020}today?\u{0020}Why\u{0020}did\u{0020}she\u{0020}become\u{0020}a\u{0020}navigator?\u{0020}Is\u{0020}she\u{0020}helping\u{0020}us?\u{0020}Is\u{0020}it\u{0020}because\u{0020}we\u{0020}will\u{0020}encounter\u{0020}a\u{0020}situation\u{0020}that\u{0020}requires\u{0020}her\u{0020}power\u{0020}in\u{0020}the\u{0020}future?\n\nOr\u{0020}did\u{0020}she\u{0020}predict\u{0020}the\u{0020}future\u{0020}of\u{0020}mankind?\n\n...\u{0020}What\u{0020}did\u{0020}she\u{0020}see\u{0020}in\u{0020}the\u{0020}future?", "0", "0", "0", "0", 13017, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[631703] = {631703, 1000, "Dr.\u{0020}Stephanie\u{0020}asked\u{0020}me\u{0020}to\u{0020}write\u{0020}my\u{0020}own\u{0020}file...\u{0020}How\u{0020}to\u{0020}write\u{0020}it...\u{0020}I'll\u{0020}write\u{0020}a\u{0020}letter\u{0020}to\u{0020}my\u{0020}dear.\u{0020}I\u{0020}know\u{0020}you\u{0020}will\u{0020}read\u{0020}it.\n\nFirst!\u{0020}My\u{0020}dear,\u{0020}I\u{0020}really,\u{0020}really,\u{0020}really\u{0020}want\u{0020}to\u{0020}meet\u{0020}you\u{0020}soon!\u{0020}So\u{0020}when\u{0020}you\u{0020}see\u{0020}this\u{0020}file,\u{0020}I\u{0020}think\u{0020}I\u{0020}have\u{0020}graduated\u{0020}from\u{0020}Dr.\u{0020}Christina\u{0020}and\u{0020}set\u{0020}off\u{0020}to\u{0020}find\u{0020}you.\n\nIn\u{0020}the\u{0020}past\u{0020}six\u{0020}months,\u{0020}I\u{0020}have\u{0020}received\u{0020}a\u{0020}lot\u{0020}of\u{0020}help\u{0020}from\u{0020}everyone,\u{0020}allowing\u{0020}me\u{0020}to\u{0020}successfully\u{0020}complete\u{0020}all\u{0020}the\u{0020}preparatory\u{0020}courses\u{0020}for\u{0020}the\u{0020}driver\u{0020}within\u{0020}half\u{0020}a\u{0020}year.\u{0020}Of\u{0020}course,\u{0020}it\u{0020}is\u{0020}also\u{0020}related\u{0020}to\u{0020}my\u{0020}own\u{0020}very,\u{0020}very\u{0020}hard\u{0020}work\u{0020}to\u{0020}return\u{0020}to\u{0020}your\u{0020}side.\n\nMy\u{0020}dear\u{0020}must\u{0020}be\u{0020}very\u{0020}strange\u{0020}why\u{0020}it\u{0020}is\u{0020}\"courses\u{0020}for\u{0020}the\u{0020}driver\"?\u{0020}Hehe,\u{0020}now\u{0020}I,\u{0020}Tsukumo\u{0020}Tamaki\u{0020}-\u{0020}have\u{0020}already\u{0020}graduated\u{0020}as\u{0020}a\u{0020}driver.\u{0020}I\u{0020}didn't\u{0020}expect\u{0020}it!\u{0020}At\u{0020}that\u{0020}time,\u{0020}I\u{0020}wasn't\u{0020}joking!\n\nAlso,\u{0020}if\u{0020}you\u{0020}want\u{0020}to\u{0020}go\u{0020}to\u{0020}Katya\u{0020}for\u{0020}fun,\u{0020}you\u{0020}can\u{0020}ask\u{0020}me\u{0020}to\u{0020}show\u{0020}you\u{0020}the\u{0020}way...\u{0020}Well,\u{0020}no,\u{0020}please\u{0020}be\u{0020}sure\u{0020}to\u{0020}ask\u{0020}me\u{0020}to\u{0020}show\u{0020}you\u{0020}the\u{0020}way.\u{0020}After\u{0020}all,\u{0020}Katya\u{0020}has\u{0020}the\u{0020}famous\u{0020}First\u{0020}Research\u{0020}Laboratory.\u{0020}I\u{0020}think\u{0020}you\u{0020}will\u{0020}definitely\u{0020}come\u{0020}over\u{0020}sometime.\n\nAlso,\u{0020}about\u{0020}what\u{0020}I\u{0020}saw\u{0020}before,\u{0020}that\u{0020}I\u{0020}will\u{0020}die\u{0020}in\u{0020}the\u{0020}future,\u{0020}I\u{0020}want\u{0020}to\u{0020}tell\u{0020}you\u{0020}in\u{0020}person.\n\nIn\u{0020}short,\u{0020}that's\u{0020}it.\u{0020}I'm\u{0020}setting\u{0020}off\u{0020}for\u{0020}the\u{0020}position\u{0020}beside\u{0020}my\u{0020}dear!\n\nThe\u{0020}defeated\u{0020}heroine\u{0020}-\u{0020}Tsukumo\u{0020}Tamaki.", "0", "0", "0", "0", 13017, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[631704] = {631704, 2000, "Start\u{0020}with\u{0020}being\u{0020}curious\u{0020}about\u{0020}oneself\n\nCuriosity\u{0020}brings\u{0020}a\u{0020}\"self\"\u{0020}who\u{0020}cares\u{0020}about\u{0020}the\u{0020}future\u{0020}of\u{0020}the\u{0020}world,\n\n\"Self\"\u{0020}brought\u{0020}a\u{0020}him\u{0020}who\u{0020}was\u{0020}entangled\u{0020}with\u{0020}oneself.\n\nHe\u{0020}brought\u{0020}the\u{0020}ultimate\u{0020}answer\u{0020}of\u{0020}the\u{0020}world.\n\nThe\u{0020}answer\u{0020}is\u{0020}defeat.\n\nThe\u{0020}defeat\u{0020}of\u{0020}the\u{0020}defeated\u{0020}heroine.\n\nThe\u{0020}heroine\u{0020}who\u{0020}\"herself\"\u{0020}has\u{0020}been\u{0020}defeated,\u{0020}her\u{0020}story\u{0020}is\u{0020}over.\n\nBut\u{0020}-\u{0020}perhaps\u{0020}the\u{0020}story\u{0020}of\u{0020}Tsukumo\u{0020}Tamaki\u{0020}has\u{0020}just\u{0020}begun\u{0020}now.", "0", "0", "0", "0", 13017, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[631800] = {631800, 0, "[Name]\u{0020}Mittoshiva\n[B-Day]\u{0020}Nov\u{0020}1\n[Compatability\u{0020}Rate]\u{0020}???\n[Height]\u{0020}31m\n[Squad]\u{0020}Shumia\n[Affiliation]\u{0020}None\n[Interest]\u{0020}Ski", "0", "0", "0", "0", 13018, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[631801] = {631801, 100, "\u{0020}\u{0020}Shumia\u{0020}is\u{0020}a\u{0020}squad\u{0020}consisting\u{0020}only\u{0020}of\u{0020}aliens\u{0020}from\u{0020}Midyr,\u{0020}and\u{0020}Mittoshiva\u{0020}is\u{0020}an\u{0020}especially\u{0020}mythical\u{0020}driver\u{0020}in\u{0020}Shumia.\n\nHer\u{0020}voice\u{0020}is\u{0020}a\u{0020}myth,\u{0020}no\u{0020}one\u{0020}have\u{0020}ever\u{0020}heard\u{0020}her\u{0020}voice\u{0020}from\u{0020}her\u{0020}mouth,\n\nShe\u{0020}always\u{0020}takes\u{0020}a\u{0020}radio\u{0020}with\u{0020}her,\u{0020}and\u{0020}that's\u{0020}her\u{0020}\"mouth\".\u{0020}Her\u{0020}communications\u{0020}with\u{0020}others\u{0020}completely\u{0020}rely\u{0020}on\u{0020}the\u{0020}radio\u{0020}playing\u{0020}some\u{0020}recorded\u{0020}and\u{0020}voice-distorted\u{0020}words,\u{0020}even\u{0020}after\u{0020}gigantification\u{0020}she\u{0020}still\u{0020}let\u{0020}the\u{0020}machine\u{0020}do\u{0020}this\u{0020}important\u{0020}job.\u{0020}People\u{0020}around\u{0020}her\u{0020}are\u{0020}far\u{0020}more\u{0020}curious\u{0020}about\u{0020}her\u{0020}\"voice\"\u{0020}than\u{0020}her\u{0020}\"pointy\u{0020}ears\".\n\nWhen\u{0020}the\u{0020}existence\u{0020}of\u{0020}Shumia\u{0020}was\u{0020}publicly\u{0020}announced,\u{0020}we\u{0020}found\u{0020}that\u{0020}compared\u{0020}to\u{0020}Mittoshiva,\u{0020}other\u{0020}Midyrians\u{0020}in\u{0020}that\u{0020}squad\u{0020}are\u{0020}just\u{0020}ordinary.\u{0020}That\u{0020}makes\u{0020}people\u{0020}more\u{0020}curious\u{0020}about\u{0020}the\u{0020}reasons\u{0020}for\u{0020}why\u{0020}this\u{0020}short\u{0020}little\u{0020}blue\u{0020}alien\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}open\u{0020}her\u{0020}mouth.", "0", "0", "0", "0", 13018, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[631802] = {631802, 500, "\u{0020}\u{0020}From\u{0020}the\u{0020}information\u{0020}provided\u{0020}by\u{0020}the\u{0020}members\u{0020}of\u{0020}this\u{0020}squad,\u{0020}\"Shumia\"\u{0020}was\u{0020}a\u{0020}massive\u{0020}spacecraft\u{0020}with\u{0020}a\u{0020}wide\u{0020}range\u{0020}of\u{0020}facilities.\u{0020}To\u{0020}counter\u{0020}every\u{0020}possible\u{0020}scenario\u{0020}during\u{0020}their\u{0020}travel,\u{0020}95%\u{0020}of\u{0020}systems\u{0020}onboard\u{0020}are\u{0020}managed\u{0020}by\u{0020}AI\u{0020}and\u{0020}robots.\n\nAnd\u{0020}the\u{0020}remaining\u{0020}5%\u{0020}seems\u{0020}like\u{0020}deliberately\u{0020}left\u{0020}to\u{0020}crew\u{0020}members\u{0020}just\u{0020}for\u{0020}their\u{0020}amusement.\u{0020}Those\u{0020}were\u{0020}some\u{0020}essential\u{0020}but\u{0020}not\u{0020}tiring\u{0020}jobs.\u{0020}Passengers\u{0020}from\u{0020}Midyr\u{0020}enjoyed\u{0020}their\u{0020}journey\u{0020}most\u{0020}of\u{0020}the\u{0020}time,\u{0020}and\u{0020}finished\u{0020}these\u{0020}\"essential\"\u{0020}jobs\u{0020}in\u{0020}their\u{0020}spare\u{0020}time.\n\nMittoshiva\u{0020}was\u{0020}the\u{0020}\"communicator\"\u{0020}of\u{0020}Shumia,\u{0020}in\u{0020}charge\u{0020}of\u{0020}sending\u{0020}greetings\u{0020}to\u{0020}the\u{0020}boundless\u{0020}universe,\u{0020}and\u{0020}waiting\u{0020}for\u{0020}replies\u{0020}from\u{0020}other\u{0020}civilizations.\n\nFrom\u{0020}Earth's\u{0020}perspective\u{0020}this\u{0020}is\u{0020}an\u{0020}important\u{0020}and\u{0020}divine\u{0020}job,\u{0020}but\u{0020}this\u{0020}is\u{0020}merely\u{0020}humans'\u{0020}own\u{0020}narrow\u{0020}minded\u{0020}opinion.\u{0020}We\u{0020}neglected\u{0020}the\u{0020}fact\u{0020}that\u{0020}Midyrians\u{0020}were\u{0020}an\u{0020}advanced\u{0020}civilization\u{0020}that\u{0020}can\u{0020}travel\u{0020}in\u{0020}universe,\u{0020}for\u{0020}them\u{0020}this\u{0020}is\u{0020}as\u{0020}simple\u{0020}as\u{0020}we\u{0020}saying\u{0020}\"Good\u{0020}morning.\"\u{0020}to\u{0020}our\u{0020}neighbors.\n\nCommunicator's\u{0020}works\u{0020}are\u{0020}as\u{0020}followed:\n\nFirst,\u{0020}broadcast\u{0020}the\u{0020}greeting\u{0020}message\u{0020}in\u{0020}every\u{0020}frequency\u{0020}band.\n\nWhen\u{0020}received\u{0020}replies,\u{0020}set\u{0020}up\u{0020}a\u{0020}semi-permanent\u{0020}communication\u{0020}channel\u{0020}with\u{0020}that\u{0020}civilization,\u{0020}and\u{0020}send\u{0020}the\u{0020}information\u{0020}about\u{0020}Midyr.\n\nContinuously\u{0020}exchange\u{0020}the\u{0020}information\u{0020}of\u{0020}each\u{0020}other\u{0020}with\u{0020}that\u{0020}civilization,\u{0020}negotiate\u{0020}about\u{0020}their\u{0020}landing\u{0020}and\u{0020}traveling\u{0020}on\u{0020}that\u{0020}planet.\n\nAlmost\u{0020}all\u{0020}kinds\u{0020}of\u{0020}information\u{0020}used\u{0020}above\u{0020}for\u{0020}communication\u{0020}are\u{0020}already\u{0020}well-written,\u{0020}in\u{0020}different\u{0020}languages,\u{0020}stored\u{0020}in\u{0020}Shumia's\u{0020}database.\u{0020}We\u{0020}think\u{0020}that\u{0020}this\u{0020}is\u{0020}why\u{0020}Mittoshiva\u{0020}doesn't\u{0020}want\u{0020}to\u{0020}speak,\u{0020}but\u{0020}other\u{0020}members\u{0020}of\u{0020}Shumia\u{0020}told\u{0020}another\u{0020}story…\n\n\"During\u{0020}a\u{0020}trip,\u{0020}we\u{0020}landed\u{0020}on\u{0020}an\u{0020}icy\u{0020}planet\u{0020}for\u{0020}a\u{0020}short\u{0020}period…\"\n\n\"That's\u{0020}the\u{0020}first\u{0020}place\u{0020}Shumia\u{0020}visited,\u{0020}all\u{0020}of\u{0020}us\u{0020}expressed\u{0020}enthusiasm.\"\n\n\"Mittoshiva\u{0020}was\u{0020}the\u{0020}most\u{0020}excited\u{0020}one\u{0020}among\u{0020}us,\u{0020}she\u{0020}ran\u{0020}and\u{0020}played\u{0020}in\u{0020}the\u{0020}snow,\u{0020}shouted\u{0020}toward\u{0020}the\u{0020}white\u{0020}sky\u{0020}but\u{0020}that\u{0020}\"sky\"\u{0020}was\u{0020}actually\u{0020}a\u{0020}big\u{0020}snow\u{0020}layer.\"\n\n\n\n\"That\u{0020}snow\u{0020}layer,\u{0020}kilometers\u{0020}above\u{0020}us,\u{0020}almost\u{0020}buried\u{0020}Shumia\u{0020}completely.\u{0020}We\u{0020}examined\u{0020}this\u{0020}accident\u{0020}and\u{0020}concluded\u{0020}that\u{0020}it\u{0020}was\u{0020}an\u{0020}avalanche\u{0020}caused\u{0020}by\u{0020}the\u{0020}seismic\u{0020}shakes\u{0020}when\u{0020}Shumia\u{0020}landed,\u{0020}but\u{0020}Mittoshiva\u{0020}stubbornly\u{0020}thought\u{0020}that\u{0020}was\u{0020}caused\u{0020}by\u{0020}her\u{0020}shouting.\"\n\n\"From\u{0020}then\u{0020}Mittoshiva\u{0020}thinks\u{0020}her\u{0020}voice\u{0020}is\u{0020}cursed,\u{0020}and\u{0020}unwilling\u{0020}to\u{0020}speak\u{0020}with\u{0020}her\u{0020}mouth,\u{0020}we\u{0020}couldn't\u{0020}help\u{0020}her\u{0020}even\u{0020}with\u{0020}our\u{0020}most\u{0020}advanced\u{0020}psychotherapy\u{0020}system.\"\n\n\"Perhaps,\u{0020}only\u{0020}if\u{0020}someone\u{0020}really\u{0020}enters\u{0020}her\u{0020}heart,\u{0020}can\u{0020}make\u{0020}her\u{0020}vocal\u{0020}cord\u{0020}vibrate\u{0020}again.\"\n\n\u{0020}", "0", "0", "0", "0", 13018, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[631803] = {631803, 1000, "\u{0020}\u{0020}Shortly\u{0020}after\u{0020}formally\u{0020}becoming\u{0020}a\u{0020}driver,\u{0020}Mittoshiva\u{0020}submitted\u{0020}a\u{0020}report.\u{0020}It\u{0020}solved\u{0020}a\u{0020}myth\u{0020}that\u{0020}has\u{0020}confused\u{0020}AEGIS\u{0020}for\u{0020}a\u{0020}long\u{0020}time:\u{0020}What\u{0020}happened\u{0020}on\u{0020}Shumia\u{0020}60\u{0020}years\u{0020}ago?\n\n…That\u{0020}was\u{0020}shortly\u{0020}after\u{0020}the\u{0020}last\u{0020}communication\u{0020}with\u{0020}earth,\u{0020}Shumia\u{0020}received\u{0020}an\u{0020}emergency\u{0020}message\u{0020}from\u{0020}their\u{0020}home\u{0020}planet.\u{0020}This\u{0020}is\u{0020}very\u{0020}strange,\u{0020}Shumia\u{0020}never\u{0020}recorded\u{0020}such\u{0020}kind\u{0020}of\u{0020}urgent\u{0020}and\u{0020}weird\u{0020}messages\u{0020}since\u{0020}she\u{0020}left\u{0020}drydock\u{0020}until\u{0020}now.\n\n\"Don't\u{0020}reply!\u{0020}Don't\u{0020}come\u{0020}back!\"\n\nI\u{0020}remembered\u{0020}that\u{0020}Shumia\u{0020}was\u{0020}stopped\u{0020}on\u{0020}the\u{0020}orbit\u{0020}of\u{0020}a\u{0020}planet.\u{0020}The\u{0020}only\u{0020}planet\u{0020}of\u{0020}that\u{0020}double\u{0020}star\u{0020}system,\u{0020}was\u{0020}about\u{0020}to\u{0020}be\u{0020}torn\u{0020}apart\u{0020}by\u{0020}those\u{0020}2\u{0020}stars,\u{0020}we\u{0020}were\u{0020}about\u{0020}to\u{0020}record\u{0020}this\u{0020}epic\u{0020}moment.\n\nAfter\u{0020}a\u{0020}long\u{0020}discussion\u{0020}we\u{0020}finally\u{0020}decided\u{0020}to\u{0020}reply\u{0020}to\u{0020}that\u{0020}message\u{0020}and\u{0020}what\u{0020}happened.\n\nShortly\u{0020}after\u{0020}the\u{0020}reply\u{0020}was\u{0020}sent,\u{0020}Sins\u{0020}found\u{0020}Shumia\u{0020}first.\n\nShaking,\u{0020}explosions,\u{0020}raspy\u{0020}alerts…darkness\u{0020}and\u{0020}woke\u{0020}up,\u{0020}the\u{0020}Sun\u{0020}entered\u{0020}my\u{0020}view.", "0", "0", "0", "0", 13018, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
