[631904] = {631904, 2000, "\u{0020}\u{0020}You\u{0020}should\u{0020}learn\u{0020}to\u{0020}cherish\u{0020}yourself,\n\nthe\u{0020}very\u{0020}same\u{0020}yourself\u{0020}under\u{0020}those\u{0020}mental\u{0020}\"illnesses\".\n\nBecause\u{0020}you\u{0020}understand,\u{0020}you\u{0020}cure.\n\nBecause\u{0020}you\u{0020}pain,\u{0020}you\u{0020}cure.\n\nA\u{0020}part\u{0020}of\u{0020}curing\u{0020}is\u{0020}a\u{0020}part\u{0020}of\u{0020}self.\n\nSo,\n\nYou\u{0020}don't\u{0020}cure\u{0020}because\u{0020}you\u{0020}are\u{0020}happy.\n\nBut\u{0020}you,\u{0020}being\u{0020}like\u{0020}this,\u{0020}saved\u{0020}lots\u{0020}of\u{0020}people.\n\nSo\u{0020}I\u{0020}want\u{0020}to\u{0020}make\u{0020}you\u{0020}happy.\n\nThis\u{0020}is\u{0020}just\u{0020}a\u{0020}superficial,\u{0020}stupid,\u{0020}fragile\u{0020}and\u{0020}self-centric\u{0020}manifesto.\n\nBut,\u{0020}it\u{0020}may\u{0020}become\u{0020}more\u{0020}wonderful.", "0", "0", "0", "0", 13019, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
