[632201] = {632201, 100, "\u{3000}\u{3000}ID:\u{0020}ODY763003,\u{0020}Monica,\u{0020}from\u{0020}Blackthorn\u{0020}Squad,\u{0020}citizen\u{0020}of\u{0020}Chesterton.\n\u{3000}\u{3000}\u{0020}Monica\u{0020}is\u{0020}a\u{0020}troublemaker\u{0020}within\u{0020}the\u{0020}squad.\u{0020}Anyone\u{0020}can\u{0020}see\u{0020}she's\u{0020}not\u{0020}content\u{0020}with\u{0020}just\u{0020}being\u{0020}a\u{0020}follower,\u{0020}which\u{0020}leads\u{0020}to\u{0020}frequent\u{0020}one-sided\u{0020}arguments\u{0020}with\u{0020}the\u{0020}squad\u{0020}captain,\u{0020}Caitlin.\u{0020}Caitlin\u{0020}just\u{0020}watches\u{0020}while\u{0020}Monica\u{0020}vents.\n\u{3000}\u{3000}\u{0020}Monica\u{0020}claims\u{0020}the\u{0020}captain\u{0020}is\u{0020}too\u{0020}soft,\u{0020}that\u{0020}she\u{0020}lets\u{0020}many\u{0020}Sins\u{0020}slip\u{0020}away\u{0020}when\u{0020}they\u{0020}should\u{0020}be\u{0020}eradicated.\u{0020}But\u{0020}everyone\u{0020}else\u{0020}thinks\u{0020}Monica's\u{0020}the\u{0020}problem.\u{0020}Since\u{0020}Blackthorn\u{0020}often\u{0020}works\u{0020}as\u{0020}a\u{0020}shield,\u{0020}the\u{0020}safety\u{0020}of\u{0020}the\u{0020}mission\u{0020}objective\u{0020}always\u{0020}comes\u{0020}first.\n\u{3000}\u{3000}\u{0020}She\u{0020}doesn't\u{0020}play\u{0020}well\u{0020}with\u{0020}others.\u{0020}Her\u{0020}Ironthorn\u{0020}Whip\u{0020}makes\u{0020}people\u{0020}hesitant\u{0020}to\u{0020}get\u{0020}too\u{0020}close,\u{0020}which\u{0020}suits\u{0020}her\u{0020}fine,\u{0020}since\u{0020}Monica\u{0020}doesn't\u{0020}want\u{0020}friends.\u{0020}She\u{0020}wants\u{0020}enemies.\n\u{3000}\u{3000}\u{0020}Good,\u{0020}honest,\u{0020}deserving\u{0020}enemies.\u{0020}The\u{0020}kind\u{0020}that\u{0020}harm\u{0020}people,\u{0020}threaten\u{0020}cities.\n\u{3000}\u{3000}\u{0020}So,\u{0020}in\u{0020}a\u{0020}way,\u{0020}Monica\u{0020}is\u{0020}a\u{0020}rather...\u{0020}evil\u{0020}kind\u{0020}of\u{0020}righteous\u{0020}ally.", "0", "0", "0", "0", 13022, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632202] = {632202, 500, "\u{3000}\u{3000}\nBefore\u{0020}Blackthorn,\u{0020}Monica\u{0020}worked\u{0020}in\u{0020}the\u{0020}police\u{0020}department\u{0020}as\u{0020}an\u{0020}interrogator.\u{3000}\u{3000}\u{0020}Not\u{0020}in\u{0020}Chesterton,\u{0020}but\u{0020}in\u{0020}another\u{0020}city.\u{0020}However,\u{0020}she\u{0020}was\u{0020}dismissed\u{0020}before\u{0020}the\u{0020}Maya\u{0020}Incident,\u{0020}which\u{0020}ironically\u{0020}involved\u{0020}her\u{0020}being\u{0020}caught\u{0020}in\u{0020}a\u{0020}life-threatening\u{0020}crisis.\n\u{3000}\u{3000}\u{0020}Her\u{0020}dismissal\u{0020}was\u{0020}directly\u{0020}related\u{0020}to\u{0020}her\u{0020}work\u{0020}habits.\u{0020}As\u{0020}an\u{0020}interrogator,\u{0020}Monica\u{0020}was\u{0020}a\u{0020}bit\u{0020}too\u{0020}violent.\n\u{3000}\u{3000}\u{0020}The\u{0020}city\u{0020}where\u{0020}she\u{0020}worked\u{0020}had\u{0020}one\u{0020}of\u{0020}the\u{0020}better\u{0020}public\u{0020}security\u{0020}records\u{0020}in\u{0020}Maya.\u{0020}After\u{0020}humanity\u{0020}fully\u{0020}committed\u{0020}to\u{0020}the\u{0020}war\u{0020}against\u{0020}the\u{0020}Sin,\u{0020}ruthless\u{0020}terrorists\u{0020}became\u{0020}increasingly\u{0020}rare.\n\u{3000}\u{3000}\u{0020}Monica's\u{0020}daily\u{0020}work\u{0020}wasn't\u{0020}involved\u{0020}in\u{0020}extracting\u{0020}critical\u{0020}intel\u{0020}from\u{0020}terrorists;\u{0020}instead,\u{0020}she\u{0020}dealt\u{0020}with\u{0020}petty\u{0020}thieves\u{0020}hiding\u{0020}stolen\u{0020}goods\u{0020}or\u{0020}drunkards\u{0020}causing\u{0020}trouble.\u{0020}The\u{0020}role\u{0020}of\u{0020}an\u{0020}interrogator\u{0020}had\u{0020}devolved\u{0020}into\u{0020}handling\u{0020}trivialities\u{0020}like\u{0020}getting\u{0020}a\u{0020}drunk\u{0020}to\u{0020}admit\u{0020}guilt.\n\u{3000}\u{3000}\u{0020}It's\u{0020}normal\u{0020}for\u{0020}people\u{0020}to\u{0020}struggle\u{0020}in\u{0020}times\u{0020}of\u{0020}change,\u{0020}but\u{0020}it\u{0020}was\u{0020}rare\u{0020}for\u{0020}someone\u{0020}of\u{0020}Monica's\u{0020}generation\u{0020}to\u{0020}have\u{0020}such\u{0020}issues.\u{0020}She\u{0020}preferred\u{0020}what\u{0020}she\u{0020}called\u{0020}the\u{0020}\"old\u{0020}ways\"\u{0020}with\u{0020}her\u{0020}subjects.\u{0020}Methods\u{0020}drilled\u{0020}into\u{0020}her\u{0020}at\u{0020}the\u{0020}police\u{0020}academy\u{0020}for\u{0020}breaking\u{0020}spies\u{0020}and\u{0020}terrorists.\n\u{3000}\u{3000}\u{0020}Her\u{0020}favorite\u{0020}tool\u{0020}was\u{0020}the\u{0020}whip.\u{0020}The\u{0020}sound\u{0020}of\u{0020}it\u{0020}cracking\u{0020}in\u{0020}the\u{0020}interrogation\u{0020}room\u{0020}became\u{0020}a\u{0020}grim\u{0020}refrain\u{0020}that\u{0020}everyone\u{0020}in\u{0020}the\u{0020}precinct\u{0020}learned\u{0020}to\u{0020}dread.\u{0020}Even\u{0020}after\u{0020}a\u{0020}suspect\u{0020}had\u{0020}fully\u{0020}confessed,\u{0020}Monica\u{0020}would\u{0020}often\u{0020}grant\u{0020}them\u{0020}a\u{0020}few\u{0020}more\u{0020}lashes.\u{0020}A\u{0020}\"lasting\u{0020}lesson,\"\u{0020}as\u{0020}she\u{0020}put\u{0020}it,\u{0020}like\u{0020}the\u{0020}brands\u{0020}they\u{0020}used\u{0020}to\u{0020}burn\u{0020}into\u{0020}criminals\u{0020}in\u{0020}ancient\u{0020}times.\n\u{3000}\u{3000}\u{0020}The\u{0020}station\u{0020}faced\u{0020}a\u{0020}steady\u{0020}stream\u{0020}of\u{0020}complaints\u{0020}over\u{0020}excessive\u{0020}force.\u{0020}The\u{0020}chief\u{0020}had\u{0020}several\u{0020}1-on-1\u{0020}conversations\u{0020}with\u{0020}her.\u{0020}But\u{0020}Monica\u{0020}was\u{0020}convinced\u{0020}the\u{0020}others\u{0020}were\u{0020}simply\u{0020}too\u{0020}soft\u{0020}on\u{0020}criminals.\n\u{3000}\u{3000}\u{0020}\"If\u{0020}they're\u{0020}guilty,\u{0020}they\u{0020}deserve\u{0020}harsher\u{0020}punishment.\u{0020}Showing\u{0020}sympathy\u{0020}to\u{0020}evil\u{0020}is\u{0020}a\u{0020}betrayal\u{0020}of\u{0020}the\u{0020}good.\"\n\u{3000}\u{3000}\u{0020}Not\u{0020}long\u{0020}after\u{0020}she\u{0020}shouted\u{0020}those\u{0020}words\u{0020}right\u{0020}at\u{0020}the\u{0020}police\u{0020}chief,\u{0020}she\u{0020}was\u{0020}dismissed.\u{0020}Soon\u{0020}after,\u{0020}clinging\u{0020}stubbornly\u{0020}to\u{0020}her\u{0020}principles,\u{0020}Monica\u{0020}left\u{0020}for\u{0020}Chesterton.", "0", "0", "0", "0", 13022, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[632203] = {632203, 1000, "\u{3000}\u{3000}Becoming\u{0020}a\u{0020}Driver\u{0020}was\u{0020}never\u{0020}Monica's\u{0020}first\u{0020}choice.\u{0020}Her\u{0020}original\u{0020}plan\u{0020}was\u{0020}to\u{0020}join\u{0020}the\u{0020}Chesterton\u{0020}Police,\u{0020}but\u{0020}when\u{0020}she\u{0020}arrived\u{0020}and\u{0020}found\u{0020}only\u{0020}ruins\u{0020}where\u{0020}the\u{0020}station\u{0020}should\u{0020}have\u{0020}been,\u{0020}she\u{0020}knew\u{0020}she\u{0020}had\u{0020}to\u{0020}find\u{0020}another\u{0020}path.\u{3000}\u{3000}\u{0020}It\u{0020}was\u{0020}then\u{0020}that\u{0020}she\u{0020}saw\u{0020}the\u{0020}recruitment\u{0020}ads\u{0020}from\u{0020}Odyssey\u{0020}Heavy\u{0020}Industries.\u{0020}In\u{0020}the\u{0020}aftermath\u{0020}of\u{0020}the\u{0020}war,\u{0020}Odyssey\u{0020}had\u{0020}taken\u{0020}control\u{0020}over\u{0020}Maya,\u{0020}and\u{0020}they\u{0020}were\u{0020}looking\u{0020}for\u{0020}capable\u{0020}Drivers.\u{0020}Monica\u{0020}knew\u{0020}it\u{0020}was\u{0020}an\u{0020}opportunity.\u{0020}She\u{0020}hadn't\u{0020}been\u{0020}trained\u{0020}at\u{0020}the\u{0020}Azure\u{0020}Academy\u{0020}like\u{0020}some\u{0020}candidates,\u{0020}but\u{0020}she'd\u{0020}heard\u{0020}that\u{0020}didn't\u{0020}matter.\u{0020}The\u{0020}only\u{0020}thing\u{0020}that\u{0020}truly\u{0020}counted\u{0020}was\u{0020}one's\u{0020}Compatibility\u{0020}Rate.\n\u{3000}\u{3000}\u{0020}Hers,\u{0020}however,\u{0020}tested\u{0020}at\u{0020}just\u{0020}around\u{0020}70%.\u{0020}Decent,\u{0020}but\u{0020}far\u{0020}from\u{0020}impressive\u{0020}among\u{0020}the\u{0020}applicants.\u{0020}It\u{0020}was\u{0020}during\u{0020}the\u{0020}simulated\u{0020}combat\u{0020}trial\u{0020}that\u{0020}everything\u{0020}changed.\u{0020}With\u{0020}a\u{0020}whip\u{0020}in\u{0020}hand,\u{0020}she\u{0020}moved\u{0020}like\u{0020}something\u{0020}out\u{0020}of\u{0020}a\u{0020}nightmare,\u{0020}and\u{0020}that\u{0020}was\u{0020}enough\u{0020}to\u{0020}land\u{0020}the\u{0020}last\u{0020}available\u{0020}spot\u{0020}for\u{0020}her.", "0", "0", "0", "0", 13022, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[632204] = {632204, 2000, "\u{3000}\u{3000}\"Criminals\u{0020}have\u{0020}rights\u{0020}too.\"\n\u{3000}\u{3000}\u{0020}What\u{0020}a\u{0020}joke.\n\u{3000}\u{3000}\u{0020}We\u{0020}created\u{0020}the\u{0020}laws,\n\u{3000}\u{3000}and\u{0020}now\u{0020}they\u{0020}shield\u{0020}the\u{0020}wicked.\n\u{3000}\u{3000}\u{0020}To\u{0020}me,\n\u{3000}\u{3000}there's\u{0020}no\u{0020}difference\u{0020}between\u{0020}a\u{0020}criminal\u{0020}and\u{0020}a\u{0020}Sin.\n\u{3000}\u{3000}\u{0020}Well,\u{0020}except\u{0020}for\u{0020}one\u{0020}thing.\n\u{3000}\u{3000}No\u{0020}one\u{0020}pleads\u{0020}for\u{0020}the\u{0020}Sin,\u{0020}\n\u{3000}\u{3000}and\u{0020}I\u{0020}hope\u{0020}they\u{0020}never\u{0020}do.", "0", "0", "0", "0", 13022, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[632300] = {632300, 0, "[Name]:\u{0020}Lilith\u{0020}\n[B-day]:\u{0020}August\u{0020}13\u{0020}\n[Core\u{0020}Compatibility]:\u{0020}98%\u{0020}\n[Height]:\u{0020}35m\u{0020}\n[Squad]:\u{0020}Romance\u{0020}Unconfirmed\u{0020}\n[Affiliation]:\u{0020}Danube\u{0020}Branch\u{0020}\n[Interest]:\u{0020}Spending\u{0020}time\u{0020}alone,\u{0020}wearing\u{0020}beautiful\u{0020}clothes,\u{0020}watching\u{0020}sitcoms", "0", "0", "0", "0", 13023, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[632301] = {632301, 100, "\u{3000}\u{3000}Valentine’s\u{0020}Day\u{0020}is\u{0020}a\u{0020}feast\u{0020}for\u{0020}girls.\u{0020}On\u{0020}this\u{0020}day,\u{0020}the\u{0020}Navigator,\u{0020}the\u{0020}story's\u{0020}protagonist,\u{0020}was\u{0020}meant\u{0020}to\u{0020}encounter\u{0020}Drivers\u{0020}of\u{0020}vastly\u{0020}different\u{0020}personalities,\u{0020}enjoy\u{0020}sweet\u{0020}dates\u{0020}within\u{0020}Aegis,\u{0020}stumble\u{0020}here\u{0020}and\u{0020}there\u{0020}along\u{0020}the\u{0020}way,\u{0020}and\u{0020}in\u{0020}the\u{0020}end\u{0020}share\u{0020}oath-binding\u{0020}chocolate\u{0020}together.\u{0020}That\u{0020}was\u{0020}how\u{0020}the\u{0020}story\u{0020}was\u{0020}supposed\u{0020}to\u{0020}unfold:\u{0020}a\u{0020}saccharine,\u{0020}love-soaked\u{0020}romantic\u{0020}comedy.\u{0020}\n\u{3000}\u{3000}But\u{0020}for\u{0020}Lilith,\u{0020}who\u{0020}can\u{0020}perceive\u{0020}everyone's\u{0020}emotions,\u{0020}this\u{0020}day\u{0020}would\u{0020}become\u{0020}a\u{0020}trial\u{0020}by\u{0020}fire.\u{0020}Her\u{0020}synesthetic\u{0020}ability,\u{0020}unchecked\u{0020}and\u{0020}out\u{0020}of\u{0020}control,\u{0020}captured\u{0020}those\u{0020}emotions\u{0020}without\u{0020}restraint,\u{0020}subtly\u{0020}influencing\u{0020}her\u{0020}judgment.\u{0020}At\u{0020}its\u{0020}worst,\u{0020}so\u{0020}it\u{0020}was\u{0020}said,\u{0020}it\u{0020}even\u{0020}affected\u{0020}her\u{0020}personality.\u{0020}\n\u{3000}\u{3000}No\u{0020}one\u{0020}told\u{0020}her\u{0020}what\u{0020}exactly\u{0020}had\u{0020}happened.\u{0020}Yet\u{0020}judging\u{0020}from\u{0020}the\u{0020}changes\u{0020}she\u{0020}noticed\u{0020}in\u{0020}herself,\u{0020}and\u{0020}from\u{0020}the\u{0020}strange\u{0020}reactions\u{0020}of\u{0020}those\u{0020}around\u{0020}her,\u{0020}people\u{0020}who\u{0020}looked\u{0020}like\u{0020}they\u{0020}wanted\u{0020}to\u{0020}laugh\u{0020}the\u{0020}moment\u{0020}they\u{0020}saw\u{0020}her\u{0020}but\u{0020}dared\u{0020}not\u{0020}(Skadi\u{0020}laughed\u{0020}outright),\u{0020}it\u{0020}was\u{0020}absolutely\u{0020}clear\u{0020}that\u{0020}something\u{0020}truly\u{0020}serious\u{0020}had\u{0020}occurred.", "0", "0", "0", "0", 13023, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632302] = {632302, 500, "\u{3000}\u{3000}Some\u{0020}very\u{0020}troubling\u{0020}rumors\u{0020}began\u{0020}to\u{0020}surface.\n\u{3000}\u{3000}\"It\u{0020}seems\u{0020}that\u{0020}Lilith\u{0020}has\u{0020}been\u{0020}acting\u{0020}completely\u{0020}out\u{0020}of\u{0020}character\u{0020}lately\u{0020}and\u{0020}has\u{0020}launched\u{0020}a\u{0020}romantic\u{0020}offensive\u{0020}toward\u{0020}the\u{0020}Navigator.\",\"Huh!?\u{0020}Does\u{0020}that\u{0020}mean\u{0020}the\u{0020}Navigator\u{0020}actually\u{0020}likes\u{0020}the\u{0020}cool\u{0020}beauty\u{0020}type\u{0020}of\u{0020}Driver?\",\"Lilith\u{0020}has\u{0020}been\u{0020}steadily\u{0020}advancing\u{0020}her\u{0020}relationship\u{0020}with\u{0020}the\u{0020}Navigator\u{0020}using\u{0020}her\u{0020}own\u{0020}strategies...\u{0020}damn\u{0020}it,\u{0020}if\u{0020}only\u{0020}I'd\u{0020}thought\u{0020}of\u{0020}that\u{0020}earlier.\",\"I\u{0020}wonder\u{0020}how\u{0020}far\u{0020}they've\u{0020}gone\u{0020}by\u{0020}now.\",\"So\u{0020}their\u{0020}relationship\u{0020}really\u{0020}changed\u{0020}because\u{0020}of\u{0020}Valentine's\u{0020}Day...\"\n\u{3000}\u{3000}While\u{0020}in\u{0020}recovery,\u{0020}Lilith\u{0020}has\u{0020}been\u{0020}hearing\u{0020}nearby\u{0020}Drivers\u{0020}discussing\u{0020}things\u{0020}like\u{0020}this\u{0020}more\u{0020}and\u{0020}more\u{0020}often,\u{0020}and\u{0020}some\u{0020}even\u{0020}went\u{0020}so\u{0020}far\u{0020}as\u{0020}to\u{0020}visit\u{0020}her\u{0020}directly\u{0020}to\u{0020}ask\u{0020}for\u{0020}her\u{0020}secret\u{0020}techniques,\u{0020}hoping\u{0020}to\u{0020}learn\u{0020}more\u{0020}advanced\u{0020}methods.\n\u{3000}\u{3000}She\u{0020}was\u{0020}unable\u{0020}to\u{0020}meet\u{0020}or\u{0020}explain\u{0020}things\u{0020}to\u{0020}the\u{0020}visiting\u{0020}Drivers,\u{0020}because\u{0020}the\u{0020}aftereffects\u{0020}of\u{0020}her\u{0020}synesthetic\u{0020}overload\u{0020}were\u{0020}still\u{0020}affecting\u{0020}her,\u{0020}causing\u{0020}her\u{0020}to\u{0020}