[632101] = {632101, 100, "\u{0020}\u{0020}Hoshii\u{0020}Bernard,\u{0020}one\u{0020}could\u{0020}tell\u{0020}from\u{0020}a\u{0020}glance\u{0020}she\u{0020}is\u{0020}not\u{0020}a\u{0020}100%\u{0020}Kyushu\u{0020}native.\u{0020}As\u{0020}the\u{0020}youngest\u{0020}miko\u{0020}in\u{0020}Shingyou\u{0020}House,\u{0020}she\u{0020}has\u{0020}been\u{0020}described\u{0020}as\u{0020}\"a\u{0020}cute\u{0020}miko\u{0020}who\u{0020}is\u{0020}on\u{0020}par\u{0020}with\u{0020}Kokorokami\".\n\nTo\u{0020}most\u{0020}people,\u{0020}Hoshii\u{0020}is\u{0020}just\u{0020}a\u{0020}cute\u{0020}little\u{0020}girl\u{0020}with\u{0020}nothing\u{0020}special,\u{0020}apart\u{0020}from\u{0020}the\u{0020}fact\u{0020}that\u{0020}she\u{0020}always\u{0020}carries\u{0020}a\u{0020}deep\u{0020}and\u{0020}translucent\u{0020}crystal\u{0020}ball\u{0020}the\u{0020}size\u{0020}of\u{0020}a\u{0020}soccer\u{0020}ball\u{0020}around\u{0020}with\u{0020}her.\u{0020}If\u{0020}you\u{0020}see\u{0020}her\u{0020}standing\u{0020}somewhere,\u{0020}that\u{0020}means\u{0020}she's\u{0020}using\u{0020}divination\u{0020}to\u{0020}decide\u{0020}where\u{0020}she's\u{0020}going\u{0020}to\u{0020}go\u{0020}next.\n\nYou\u{0020}see,\u{0020}in\u{0020}addition\u{0020}to\u{0020}being\u{0020}a\u{0020}miko,\u{0020}Hoshii\u{0020}has\u{0020}another\u{0020}special\u{0020}identity\u{0020}-\u{0020}that\u{0020}of\u{0020}a\u{0020}fortune\u{0020}teller.\n\nHoshii's\u{0020}divination\u{0020}skills\u{0020}were\u{0020}inherited\u{0020}from\u{0020}her\u{0020}family\u{0020}and\u{0020}the\u{0020}result\u{0020}of\u{0020}her\u{0020}divinations\u{0020}are\u{0020}often\u{0020}some\u{0020}obscure\u{0020}and\u{0020}strange\u{0020}vision.\u{0020}While\u{0020}she\u{0020}never\u{0020}gives\u{0020}explanations\u{0020}for\u{0020}her\u{0020}divinations,\u{0020}in\u{0020}Hoshii's\u{0020}words\u{0020}—\n\n\"This\u{0020}is\u{0020}your\u{0020}own\u{0020}destiny,\u{0020}and\u{0020}a\u{0020}fortune\u{0020}teller\u{0020}can\u{0020}only\u{0020}give\u{0020}guidance\u{0020}to\u{0020}the\u{0020}future,\u{0020}not\u{0020}interfere\u{0020}with\u{0020}it.\"\n\nHoshii's\u{0020}confidence\u{0020}and\u{0020}respect\u{0020}for\u{0020}divination\u{0020}is\u{0020}so\u{0020}great\u{0020}that\u{0020}she\u{0020}even\u{0020}uses\u{0020}it\u{0020}to\u{0020}decide\u{0020}what\u{0020}to\u{0020}eat\u{0020}for\u{0020}dinner.\n\nDivination\u{0020}has\u{0020}become\u{0020}Hoshii's\u{0020}creed\u{0020}of\u{0020}life,\u{0020}and\u{0020}perhaps\u{0020}Hoshii\u{0020}even\u{0020}uses\u{0020}divination\u{0020}to\u{0020}find\u{0020}the\u{0020}person\u{0020}to\u{0020}whom\u{0020}she\u{0020}will\u{0020}entrust\u{0020}her\u{0020}future\u{0020}to.", "0", "0", "0", "0", 13021, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632102] = {632102, 500, "\u{0020}\u{0020}Hoshii\u{0020}Bernardi's\u{0020}birthplace\u{0020}was\u{0020}not\u{0020}Kyushu,\u{0020}but\u{0020}Danube,\u{0020}a\u{0020}land\u{0020}far\u{0020}far\u{0020}away\u{0020}from\u{0020}Kyushu.\n\n\"Bernardi\"\u{0020}is\u{0020}a\u{0020}family\u{0020}name\u{0020}that\u{0020}comes\u{0020}from\u{0020}her\u{0020}mother's\u{0020}side\u{0020}of\u{0020}the\u{0020}family,\u{0020}while\u{0020}\"Hoshii\"\u{0020}is\u{0020}her\u{0020}father's\u{0020}family\u{0020}name.\u{0020}According\u{0020}to\u{0020}reports,\u{0020}Hoshii's\u{0020}father\u{0020}was\u{0020}a\u{0020}merchant\u{0020}in\u{0020}Kyushu\u{0020}who\u{0020}ran\u{0020}a\u{0020}jewelry\u{0020}business\u{0020}in\u{0020}his\u{0020}early\u{0020}years.\u{0020}He\u{0020}met\u{0020}Hoshii's\u{0020}mother\u{0020}at\u{0020}a\u{0020}jewelry\u{0020}show\u{0020}in\u{0020}Danube.\u{0020}They\u{0020}soon\u{0020}fell\u{0020}in\u{0020}love,\u{0020}with\u{0020}Hoshii's\u{0020}father\u{0020}selling\u{0020}off\u{0020}part\u{0020}of\u{0020}his\u{0020}Kyushu\u{0020}fortune\u{0020}to\u{0020}become\u{0020}a\u{0020}member\u{0020}of\u{0020}the\u{0020}Bernardi\u{0020}family.\n\nUpon\u{0020}further\u{0020}investigation,\u{0020}it\u{0020}turned\u{0020}out\u{0020}that\u{0020}the\u{0020}Bernardi\u{0020}family\u{0020}was\u{0020}not\u{0020}an\u{0020}ordinary\u{0020}family\u{0020}of\u{0020}nobility.\n\nIn\u{0020}ancient\u{0020}times,\u{0020}when\u{0020}Danube\u{0020}enjoyed\u{0020}a\u{0020}century-long\u{0020}period\u{0020}of\u{0020}prosperity,\u{0020}it\u{0020}is\u{0020}said\u{0020}that\u{0020}the\u{0020}king\u{0020}was\u{0020}advised\u{0020}by\u{0020}a\u{0020}legendary\u{0020}fortune\u{0020}teller\u{0020}in\u{0020}building\u{0020}a\u{0020}powerful\u{0020}empire\u{0020}that\u{0020}spanned\u{0020}the\u{0020}whole\u{0020}of\u{0020}Danube.\u{0020}However,\u{0020}at\u{0020}the\u{0020}height\u{0020}of\u{0020}the\u{0020}kingdom's\u{0020}prosperity,\u{0020}the\u{0020}legendary\u{0020}fortune\u{0020}teller\u{0020}suddenly\u{0020}disappeared,\u{0020}and\u{0020}the\u{0020}kingdom\u{0020}quickly\u{0020}fell\u{0020}into\u{0020}disarray\u{0020}within\u{0020}a\u{0020}few\u{0020}years\u{0020}after\u{0020}the\u{0020}disappearance.\n\nThe\u{0020}legendary\u{0020}fortune\u{0020}teller\u{0020}was\u{0020}an\u{0020}ancestor\u{0020}of\u{0020}the\u{0020}Bernardi\u{0020}family,\u{0020}from\u{0020}whom\u{0020}the\u{0020}art\u{0020}of\u{0020}fortune-telling\u{0020}has\u{0020}been\u{0020}passed\u{0020}down.\n\nHoshii's\u{0020}arrival\u{0020}at\u{0020}Shingyou\u{0020}House\u{0020}seems\u{0020}to\u{0020}be\u{0020}a\u{0020}coincidence,\u{0020}but\u{0020}as\u{0020}the\u{0020}number\u{0020}of\u{0020}coincidences\u{0020}increased,\u{0020}it\u{0020}became\u{0020}a\u{0020}matter\u{0020}of\u{0020}fate.\n\nFirst\u{0020}off\u{0020}was\u{0020}when\u{0020}the\u{0020}Bernardi\u{0020}family\u{0020}came\u{0020}to\u{0020}Kyushu\u{0020}because\u{0020}of\u{0020}the\u{0020}incident\u{0020}in\u{0020}Saar\u{0020}City,\u{0020}in\u{0020}which\u{0020}they\u{0020}felt\u{0020}that\u{0020}Danube\u{0020}was\u{0020}no\u{0020}longer\u{0020}a\u{0020}safe\u{0020}place\u{0020}to\u{0020}live.\u{0020}It\u{0020}was\u{0020}discovered\u{0020}that\u{0020}Hoshii,\u{0020}along\u{0020}with\u{0020}her\u{0020}mother\u{0020}and\u{0020}grandmother,\u{0020}carried\u{0020}out\u{0020}a\u{0020}family\u{0020}divination,\u{0020}the\u{0020}results\u{0020}of\u{0020}which\u{0020}directed\u{0020}them\u{0020}to\u{0020}Kyushu.\n\nThe\u{0020}second\u{0020}time\u{0020}was\u{0020}when\u{0020}Hoshii\u{0020}came\u{0020}across\u{0020}the\u{0020}Shingyou\u{0020}House\u{0020}after\u{0020}one\u{0020}of\u{0020}her\u{0020}frequent\u{0020}walks.\u{0020}While\u{0020}wandering\u{0020}about\u{0020}as\u{0020}she\u{0020}always\u{0020}does,\u{0020}guided\u{0020}by\u{0020}her\u{0020}fortune-telling,\u{0020}Hoshii\u{0020}came\u{0020}upon\u{0020}a\u{0020}shrine\u{0020}called\u{0020}\"Shingyou\u{0020}House\".\u{0020}Kokorokami\u{0020}of\u{0020}Shingyou\u{0020}House\u{0020}was\u{00