[632401] = {632401, 100, "Nei\u{0020}Okawamura,\u{0020}a\u{0020}rare\u{0020}clairvoyant\u{0020}among\u{0020}the\u{0020}warrioresses\u{0020}of\u{0020}the\u{0020}7th\u{0020}Squad.\n\nDespite\u{0020}joining\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Squad,\u{0020}the\u{0020}eleven-year-old\u{0020}elementary\u{0020}school\u{0020}student\u{0020}still\u{0020}attends\u{0020}school\u{0020}as\u{0020}usual\u{0020}and\u{0020}looks\u{0020}forward\u{0020}to\u{0020}seeing\u{0020}her\u{0020}friends\u{0020}like\u{0020}any\u{0020}other\u{0020}child.\n\n\u{0020}For\u{0020}Nei,\u{0020}joining\u{0020}the\u{0020}squad\u{0020}holds\u{0020}personal\u{0020}meaning.\u{0020}Her\u{0020}parents\u{0020}are\u{0020}believed\u{0020}to\u{0020}have\u{0020}gone\u{0020}missing\u{0020}during\u{0020}a\u{0020}Mato\u{0020}Mishap.\u{0020}She\u{0020}had\u{0020}heard\u{0020}whispers\u{0020}among\u{0020}the\u{0020}disaster\u{0020}survivors:\u{0020}stories\u{0020}of\u{0020}missing\u{0020}loved\u{0020}ones\u{0020}suddenly\u{0020}calling\u{0020}home,\u{0020}or\u{0020}being\u{0020}spotted\u{0020}by\u{0020}chance\u{0020}long\u{0020}after\u{0020}they\u{0020}were\u{0020}thought\u{0020}lost.\u{0020}Fueled\u{0020}by\u{0020}that\u{0020}fragile\u{0020}spark\u{0020}of\u{0020}hope,\u{0020}Nei\u{0020}enlisted\u{0020}in\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force,\u{0020}determined\u{0020}to\u{0020}find\u{0020}any\u{0020}trace\u{0020}of\u{0020}her\u{0020}parents.\n\nPerhaps\u{0020}it\u{0020}was\u{0020}that\u{0020}unwavering\u{0020}resolve\u{0020}that\u{0020}became\u{0020}her\u{0020}true\u{0020}driving\u{0020}force\u{0020}and\u{0020}eventually\u{0020}manifested\u{0020}as\u{0020}her\u{0020}Peach\u{0020}Blessing.\u{0020}After\u{0020}eating\u{0020}a\u{0020}Peach,\u{0020}Nei\u{0020}awakened\u{0020}the\u{0020}power\u{0020}known\u{0020}as\u{0020}Sure\u{0020}To\u{0020}Find:\u{0020}Promise,\u{0020}a\u{0020}clairvoyant\u{0020}ability\u{0020}that\u{0020}allows\u{0020}her\u{0020}to\u{0020}locate\u{0020}people\u{0020}miles\u{0020}away.", "0", "0", "0", "0", 13024, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632402] = {632402, 500, "Maybe\u{0020}it's\u{0020}because\u{0020}of\u{0020}the\u{0020}near-death\u{0020}experience\u{0020}in\u{0020}the\u{0020}Mishap.\u{0020}Nei\u{0020}carries\u{0020}herself\u{0020}with\u{0020}a\u{0020}maturity\u{0020}well\u{0020}beyond\u{0020}her\u{0020}years,\u{0020}steadier,\u{0020}even,\u{0020}than\u{0020}many\u{0020}of\u{0020}the\u{0020}seasoned\u{0020}Drivers.\n\nAs\u{0020}the\u{0020}haze\u{0020}disaster\u{0020}was\u{0020}resolved,\u{0020}the\u{0020}Social\u{0020}Rehabilitation\u{0020}Department\u{0020}moved\u{0020}in\u{0020}to\u{0020}stabilize\u{0020}civilians'\u{0020}livelihoods,\u{0020}including\u{0020}psychological\u{0020}care\u{0020}programs\u{0020}for\u{0020}children,\u{0020}such\u{0020}as\u{0020}kindergarten\u{0020}visits.\n\nDrivers\u{0020}were\u{0020}to\u{0020}participate\u{0020}as\u{0020}\"heroic\u{0020}guardians\"\u{0020}to\u{0020}inspire\u{0020}the\u{0020}kids...\u{0020}Well,\u{0020}let's\u{0020}be\u{0020}real—the\u{0020}ulterior\u{0020}motive\u{0020}was\u{0020}probably\u{0020}to\u{0020}plant\u{0020}early\u{0020}aspirations\u{0020}of\u{0020}\"I\u{0020}want\u{0020}to\u{0020}be\u{0020}a\u{0020}Driver!\"\u{0020}or\u{0020}\"I'll\u{0020}support\u{0020}them\u{0020}as\u{0020}an\u{0020}engineer!\"\u{0020}After\u{0020}all,\u{0020}in\u{0020}humanity's\u{0020}war\u{0020}for\u{0020}survival,\u{0020}Drivers\u{0020}are\u{0020}the\u{0020}linchpin\u{0020}of\u{0020}defense.\n\nDuring\u{0020}these\u{0020}events,\u{0020}Nei\u{0020}blended\u{0020}seamlessly\u{0020}with\u{0020}the\u{0020}children.\u{0020}No\u{0020}awkward\u{0020}incidents\u{0020}like\u{0020}with\u{0020}certain\u{0020}other\u{0020}Drivers\u{0020}(e.g.,\u{0020}suddenly\u{0020}organizing\u{0020}a\u{0020}field\u{0020}day,\u{0020}skipping\u{0020}events\u{0020}due\u{0020}to\u{0020}hangovers,\u{0020}or\u{0020}freezing\u{0020}up\u{0020}from\u{0020}crippling\u{0020}social\u{0020}anxiety).", "0", "0", "0", "0", 13024, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[632403] = {632403, 1000, "Nei's\u{0020}natural\u{0020}warmth\u{0020}really\u{0020}shines\u{0020}through\u{0020}whenever\u{0020}she\u{0020}interacts\u{0020}with\u{0020}the\u{0020}Drivers.\n\nMaybe\u{0020}it's\u{0020}simply\u{0020}that\u{0020}children\u{0020}have\u{0020}a\u{0020}way\u{0020}of\u{0020}disarming\u{0020}people.\u{0020}Or\u{0020}perhaps\u{0020}everyone\u{0020}can\u{0020}sense\u{0020}the\u{0020}strength\u{0020}and\u{0020}reliability\u{0020}behind\u{0020}her\u{0020}gentle\u{0020}demeanor.\n\nWhatever\u{0020}the\u{0020}reason,\u{0020}it's\u{0020}clear\u{0020}that\u{0020}Nei\u{0020}has\u{0020}earned\u{0020}everyone's\u{0020}trust\u{0020}and\u{0020}affection,\u{0020}except\u{0020}a\u{0020}certain\u{0020}\"chuunibyou\"\u{0020}girl,\u{0020}Skadi,\u{0020}who\u{0020}got\u{0020}drawn\u{0020}in\u{0020}more\u{0020}by\u{0020}the\u{0020}whole\u{0020}\"otherworlder\"\u{0020}thing.\u{0020}Ironically,\u{0020}Skadi\u{0020}chose\u{0020}Nei\u{0020}of\u{0020}all\u{0020}people\u{0020}as\u{0020}her\u{0020}go-to\u{0020}source\u{0020}for\u{0020}\"otherworldly\u{0020}knowledge.\"\u{0020}Maybe\u{0020}that's\u{0020}a\u{0020}testament\u{0020}to\u{0020}Nei's\u{0020}unnatural\u{0020}charisma?\u{0020}Hard\u{0020}to\u{0020}say\u{0020}for\u{0020}sure.\n\nAnyway,\u{0020}Nei\u{0020}seems\u{0020}to\u{0020}be\u{0020}enjoying\u{0020}herself...\u{0020}though\u{0020}let's\u{0020}hope\u{0020}she\u{0020}doesn't\u{0020}start\u{0020}taking\u{0020}Skadi's\u{0020}dramatic\u{0020}one-liners\u{0020}at\u{0020}face\u{0020}value.\n\nNow\u{0020}that\u{0020}I\u{0020}think\u{0020}about\u{0020}it,\u{0020}is\u{0020}it\u{0020}Nei's\u{0020}reliability,\u{0020}or\u{0020}Skadi's\u{0020}lack\u{0020}of\u{0020}maturity,\u{0020}that\u{0020}has\u{0020}an\u{0020}18-year-old\u{0020}girl\u{0020}constantly\u{0020}trailing\u{0020}after\u{0020}an\u{0020}11-year-old\u{0020}elementary\u{0020}schooler?\n\nHard\u{0020}to\u{0020}say\u{0020}that,\u{0020}too.", "0", "0", "0", "0", 13024, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
