[632501] = {632501, 100, "\u{3000}\u{3000}The\u{0020}id,\u{0020}the\u{0020}ego,\u{0020}and\u{0020}then\u{0020}the\u{0020}superego.\n\u{3000}\u{3000}A\u{0020}famous\u{0020}psychoanalyst\u{0020}used\u{0020}these\u{0020}theoretical\u{0020}concepts\u{0020}to\u{0020}explain\u{0020}the\u{0020}relationship\u{0020}between\u{0020}human\u{0020}consciousness\u{0020}and\u{0020}the\u{0020}subconscious.\n\u{3000}\u{3000}The\u{0020}incident\u{0020}that\u{0020}happened\u{0020}to\u{0020}Franca\u{0020}this\u{0020}time,\u{0020}namely\u{0020}the\u{0020}dream\u{0020}world\u{0020}seen\u{0020}during\u{0020}the\u{0020}\"mental\u{0020}assessment,\"\u{0020}seems\u{0020}like\u{0020}it\u{0020}can\u{0020}be\u{0020}explained\u{0020}with\u{0020}this\u{0020}theory.\n\u{3000}\u{3000}The\u{0020}Franca\u{0020}who\u{0020}openly\u{0020}displayed\u{0020}her\u{0020}own\u{0020}desires\u{0020}without\u{0020}restraint\u{0020}was\u{0020}the\u{0020}id.\n\u{3000}\u{3000}The\u{0020}agent\u{0020}used\u{0020}to\u{0020}face\u{0020}external\u{0020}objects\u{0020}was\u{0020}the\u{0020}ego.\n\u{3000}\u{3000}The\u{0020}steward\u{0020}who\u{0020}judged\u{0020}her\u{0020}own\u{0020}actions\u{0020}through\u{0020}conscience\u{0020}and\u{0020}morality\u{0020}was\u{0020}the\u{0020}superego.\n\u{3000}\u{3000}...Among\u{0020}the\u{0020}Francas\u{0020}I\u{0020}met,\u{0020}it\u{0020}was\u{0020}very\u{0020}easy\u{0020}to\u{0020}tell\u{0020}which\u{0020}one\u{0020}was\u{0020}the\u{0020}\"id.\"\u{0020}But\u{0020}as\u{0020}for\u{0020}the\u{0020}Franca\u{0020}who\u{0020}always\u{0020}viewed\u{0020}how\u{0020}things\u{0020}developed\u{0020}in\u{0020}a\u{0020}negative\u{0020}light,\u{0020}and\u{0020}the\u{0020}Franca\u{0020}who\u{0020}remained\u{0020}rational\u{0020}and\u{0020}could\u{0020}grasp\u{0020}the\u{0020}situation\u{0020}at\u{0020}the\u{0020}fastest\u{0020}speed,\u{0020}deciding\u{0020}which\u{0020}one\u{0020}was\u{0020}the\u{0020}\"ego\"\u{0020}and\u{0020}which\u{0020}one\u{0020}was\u{0020}the\u{0020}\"superego\"\u{0020}was\u{0020}not\u{0020}so\u{0020}simple.\n\u{3000}\u{3000}Either\u{0020}of\u{0020}them\u{0020}seemed\u{0020}like\u{0020}the\u{0020}\"ego,\"\u{0020}and\u{0020}either\u{0020}of\u{0020}them\u{0020}seemed\u{0020}like\u{0020}the\u{0020}\"superego.\"\u{0020}The\u{0020}Franca\u{0020}in\u{0020}my\u{0020}impression\u{0020}was\u{0020}more\u{0020}like\u{0020}a\u{0020}fusion\u{0020}of\u{0020}those\u{0020}latter\u{0020}two\u{0020}Francas.\n\u{3000}\u{3000}However,\u{0020}using\u{0020}psychoanalysis\u{0020}to\u{0020}explain\u{0020}the\u{0020}composition\u{0020}of\u{0020}a\u{0020}person's\u{0020}personality\u{0020}was\u{0020}never\u{0020}something\u{0020}I\u{0020}was\u{0020}good\u{0020}at.\u{0020}My\u{0020}understanding\u{0020}of\u{0020}the\u{0020}\"id,\u{0020}ego,\u{0020}and\u{0020}superego\"\u{0020}likely\u{0020}only\u{0020}stays\u{0020}on\u{0020}the\u{0020}surface,\u{0020}so\u{0020}there\u{0020}is\u{0020}no\u{0020}need\u{0020}for\u{0020}me\u{0020}to\u{0020}dwell\u{0020}too\u{0020}much\u{0020}on\u{0020}matching\u{0020}them\u{0020}one\u{0020}by\u{0020}one.\n\u{3000}\u{3000}\"So\u{0020}Franca\u{0020}is\u{0020}not\u{0020}only\u{0020}what\u{0020}I\u{0020}have\u{0020}seen\u{0020}her\u{0020}as.\"\u{0020}Just\u{0020}learning\u{0020}that\u{0020}was\u{0020}already\u{0020}the\u{0020}greatest\u{0020}gain\u{0020}from\u{0020}this\u{0020}incident.", "0", "0", "0", "0", 13025, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632502] = {632502, 500, "\u{3000}\u{3000}The\u{0020}rollout\u{0020}of\u{0020}the\u{0020}medical\u{0020}pod,\u{0020}which\u{0020}could\u{0020}be\u{0020}called\u{0020}the\u{0020}\"culprit\"\u{0020}behind\u{0020}this\u{0020}incident,\u{0020}was\u{0020}suspended\u{0020}immediately\u{0020}after\u{0020}the\u{0020}incident\u{0020}ended.\u{0020}After\u{0020}all,\u{0020}technology\u{0020}that\u{0020}can\u{0020}split\u{0020}a\u{0020}person's\u{0020}consciousness\u{0020}into\u{0020}three\u{0020}parts\u{0020}is\u{0020}still\u{0020}too\u{0020}advanced\u{0020}for\u{0020}humanity\u{0020}as\u{0020}it\u{0020}is\u{0020}now.\u{0020}Until\u{0020}it\u{0020}can\u{0020}be\u{0020}guaranteed\u{0020}that\u{0020}it\u{0020}will\u{0020}not\u{0020}leave\u{0020}any\u{0020}aftereffects\u{0020}on\u{0020}those\u{0020}who\u{0020}enter\u{0020}the\u{0020}medical\u{0020}pod,\u{0020}it\u{0020}would\u{0020}be\u{0020}better\u{0020}not\u{0020}to\u{0020}release\u{0020}this\u{0020}technology\u{0020}to\u{0020}the\u{0020}public.\n\u{3000}\u{3000}\"Although\u{0020}the\u{0020}results\u{0020}of\u{0020}the\u{0020}mental\u{0020}assessment\u{0020}showed\u{0020}that\u{0020}everything\u{0020}is\u{0020}normal,\u{0020}as\u{0020}her\u{0020}Navigator,\u{0020}you\u{0020}had\u{0020}better\u{0020}pay\u{0020}more\u{0020}attention\u{0020}to\u{0020}her\u{0020}condition\u{0020}for\u{0020}the\u{0020}time\u{0020}being.\"\n\u{3000}\u{3000}Dr.\u{0020}Stephanie\u{0020}expressed\u{0020}her\u{0020}concern\u{0020}for\u{0020}Franca's\u{0020}mental\u{0020}state\u{0020}in\u{0020}such\u{0020}a\u{0020}direct\u{0020}way.\u{0020}This\u{0020}unprecedented\u{0020}act\u{0020}left\u{0020}me\u{0020}on\u{0020}edge\u{0020}and\u{0020}restless\u{0020}for\u{0020}quite\u{0020}some\u{0020}time\u{0020}afterward.\n\u{3000}\u{3000}To\u{0020}make\u{0020}sure\u{0020}nothing\u{0020}unexpected\u{0020}happened\u{0020}to\u{0020}Franca\u{0020}without\u{0020}my\u{0020}knowledge,\u{0020}I\u{0020}assigned\u{0020}to\u{0020}her\u{0020}all\u{0020}the\u{0020}time\u{0020}on\u{0020}my\u{0020}schedule\u{0020}that\u{0020}had\u{0020}originally\u{0020}been\u{0020}set\u{0020}aside\u{0020}for\u{0020}accompanying\u{0020}others.\u{0020}In\u{0020}other\u{0020}words,\u{0020}aside\u{0020}from\u{0020}the\u{0020}private\u{0020}time\u{0020}I\u{0020}absolutely\u{0020}needed,\u{0020}my\u{0020}life\u{0020}was\u{0020}practically\u{0020}tied\u{0020}to\u{0020}Franca.\n\u{3000}\u{3000}Fortunately,\u{0020}the\u{0020}situation\u{0020}I\u{0020}was\u{0020}most\u{0020}worried\u{0020}about\u{0020}did\u{0020}not\u{0020}happen.\u{0020}At\u{0020}the\u{0020}very\u{0020}least,\u{0020}Franca's\u{0020}mental\u{0020}state\u{0020}did\u{0020}not\u{0020}become\u{0020}as\u{0020}bad\u{0020}as\u{0020}Lilith's\u{0020}once\u{0020}was.\u{0020}I\u{0020}really\u{0020}do\u{0020}not\u{0020}want\u{0020}to\u{0020}see\u{0020}anything\u{0020}like\u{0020}someone\u{0020}occasionally\u{0020}saying\u{0020}things\u{0020}that\u{0020}sound\u{0020}like\u{0020}they\u{0020}came\u{0020}from\u{0020}a\u{0020}Secondary\u{0020}Persona\u{0020}ever\u{0020}again.\n\u{3000}\u{3000}Of\u{0020}course,\u{0020}it\u{0020}would\u{0020}be\u{0020}overly\u{0020}optimistic\u{0020}to\u{0020}say\u{0020}that\u{0020}Franca\u{0020}has\u{0020}not\u{0020}changed\u{0020}at\u{0020}all\u{0020}compared\u{0020}to\u{0020}before.\n\u{3000}\u{3000}Perhaps\u{0020}because\u{0020}my\u{0020}relationship\u{0020}with\u{0020}her\u{0020}has\u{0020}become\u{0020}closer\u{0020}than\u{0020}it\u{0020}was\u{0020}in\u{0020}the\u{0020}past,\u{0020}she\u{0020}has\u{0020}been\u{0020}a\u{0020}little\u{0020}too\u{0020}eager\u{0020}lately,\u{0020}and\u{0020}she\u{0020}even\u{0020}says\u{0020}things\u{0020}that\u{0020}the\u{0020}old\u{0020}her\u{0020}never\u{0020}would\u{0020}have\u{0020}said,\u{0020}things\u{0020}that\u{0020}make\u{0020}my\u{0020}face\u{0020}turn\u{0020}red.\n\u{3000}\u{3000}Still,\u{0020}a\u{0020}change\u{0020}of\u{0020}this\u{0020}degree\u{0020}can\u{0020}only\u{0020}be\u{0020}said\u{0020}to\u{0020}mean\u{0020}that\u{0020}she\u{0020}has\u{0020}become\u{0020}a\u{0020}little\u{0020}more\u{0020}active\u{0020}and\u{0020}outgoing\u{0020}than\u{0020}before.\u{0020}Compared\u{0020}to\u{0020}how\u{0020}reserved\u{0020}she\u{0020}used\u{0020}to\u{0020}be,\u{0020}this\u{0020}change\u{0020}should\u{0020}be\u{0020}a\u{0020}good\u{0020}thing.\u{0020}As\u{0020}long\u{0020}as\u{0020}the\u{0020}contrast\u{0020}is\u{0020}not\u{0020}as\u{0020}drastic\u{0020}as\u{0020}it\u{0020}was\u{0020}with\u{0020}Lilith\u{0020}back\u{0020}then,\u{0020}I\u{0020}do\u{0020}not\u{0020}think\u{0020}it\u{0020}is\u{0020}something\u{0020}I\u{0020}need\u{0020}to\u{0020}worry\u{0020}too\u{0020}much\u{0020}about.\n\u{3000}\u{3000}\"Navigator!\u{0020}Navigator!\u{0020}Please\u{0020}go\u{0020}out\u{0020}and\u{0020}have\u{0020}fun\u{0020}with\u{0020}me\u{0020}today\u{0020}too,\u{0020}okay~?\"\n\u{3000}\u{3000}Franca's\u{0020}voice\u{0020}interrupted\u{0020}my\u{0020}worries.\u{0020}I\u{0020}glanced\u{0020}at\u{0020}the\u{0020}calendar.\u{0020}Sure\u{0020}enough,\u{0020}it\u{0020}was\u{0020}once\u{0020}again\u{0020}the\u{0020}day\u{0020}I\u{0020}had\u{0020}promised\u{0020}to\u{0020}go\u{0020}shopping\u{0020}with\u{0020}Franca.", "0", "0", "0", "0", 13025, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[632503] = {632503, 1000, "\u{3000}\u{3000}Something\u{0020}is\u{0020}off\u{0020}about\u{0020}Franca.\n\u{3000}\u{3000}Only\u{0020}noticing\u{0020}it\u{0020}now\u{0020}would\u{0020}probably\u{0020}be\u{0020}considered\u{0020}far\u{0020}too\u{0020}late.\n\u{3000}\u{3000}Even\u{0020}so,\u{0020}I\u{0020}have\u{0020}to\u{0020}take\u{0020}back\u{0020}what\u{0020}I\u{0020}said\u{0020}before,\u{0020}and\u{0020}repeat\u{0020}it\u{0020}once\u{0020}again--\n\u{3000}\u{3000}Something\u{0020}has\u{0020}been\u{0020}off\u{0020}about\u{0020}Franca\u{0020}lately.\n\u{3000}\u{3000}At\u{0020}first,\u{0020}I\u{0020}thought\u{0020}she\u{0020}had\u{0020}simply\u{0020}been\u{0020}influenced\u{0020}by\u{0020}the\u{0020}strange\u{0020}things\u{0020}said\u{0020}in\u{0020}the\u{0020}dream,\u{0020}and\u{0020}that\u{0020}she\u{0020}wanted\u{0020}to\u{0020}become\u{0020}more\u{0020}outgoing\u{0020}and\u{0020}proactive,\u{0020}which\u{0020}was\u{0020}why\u{0020}her\u{0020}personality\u{0020}had\u{0020}changed\u{0020}a\u{0020}little.\n\u{3000}\u{3000}However,\u{0020}that\u{0020}was\u{0020}not\u{0020}the\u{0020}case.\n\u{3000}\u{3000}Recently,\u{0020}she\u{0020}has\u{0020}been\u{0020}frequently\u{0020}appearing\u{0020}in\u{0020}my\u{0020}room\u{0020}in\u{0020}a\u{0020}wedding\u{0020}dress,\u{0020}and\u{0020}often\u{0020}throws\u{0020}herself\u{0020}at\u{0020}me\u{0020}under\u{0020}Gia's\u{0020}astonished\u{0020}gaze.\u{0020}This\u{0020}is\u{0020}no\u{0020}longer\u{0020}the\u{0020}Franca\u{0020}I\u{0020}know.\n\u{3000}\u{3000}She\u{0020}has\u{0020}already\u{0020}turned\u{0020}into\u{0020}some\u{0020}kind\u{0020}of\u{0020}weirdo\u{0020}possessed\u{0020}by\u{0020}a\u{0020}carnivorous\u{0020}animal.\n\u{3000}\u{3000}\"The\u{0020}results\u{0020}of\u{0020}the\u{0020}mental\u{0020}assessment\u{0020}showed\u{0020}that\u{0020}everything\u{0020}is\u{0020}normal\"?\u{0020}That\u{0020}must\u{0020}have\u{0020}been\u{0020}complete\u{0020}nonsense\u{0020}Dr.\u{0020}Stephanie\u{0020}made\u{0020}up\u{0020}to\u{0020}avoid\u{0020}responsibility.\u{0020}What\u{0020}part\u{0020}of\u{0020}this\u{0020}Franca\u{0020}is\u{0020}normal?\n\u{3000}\u{3000}\"Navigator~\u{0020}You\u{0020}are\u{0020}here,\u{0020}right?\u{0020}Right?\u{0020}Hurry\u{0020}and\u{0020}accompany\u{0020}me\u{0020}for\u{0020}bride\u{0020}training!\"\n\u{3000}\u{3000}What\u{0020}do\u{0020}you\u{0020}mean,\u{0020}bride\u{0020}training?\u{0020}That\u{0020}is\u{0020}something\u{0020}Uki\u{0020}would\u{0020}say,\u{0020}right?\u{0020}Do\u{0020}not\u{0020}steal\u{0020}her--\n\u{3000}\u{3000}(The\u{0020}written\u{0020}record\u{0020}cuts\u{0020}off\u{0020}abruptly)", "0", "0", "0", "0", 13025, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[632504] = {632504, 2000, "\u{3000}\u{3000}To\u{0020}him,\u{0020}she\u{0020}has\u{0020}always\u{0020}been\u{0020}a\u{0020}reassuring\u{0020}presence.\n\u{3000}\u{3000}A\u{0020}harbor\u{0020}that\u{0020}always\u{0020}remains\u{0020}calm\u{0020}upon\u{0020}his\u{0020}return.\n\u{3000}\u{3000}A\u{0020}starting\u{0020}point\u{0020}he\u{0020}will\u{0020}always\u{0020}come\u{0020}back\u{0020}to,\u{0020}no\u{0020}matter\u{0020}how\u{0020}far\u{0020}he\u{0020}goes.\n\u{3000}\u{3000}But\u{0020}being\u{0020}unchanging,\u{0020}and\u{0020}being\u{0020}the\u{0020}starting\u{0020}point,\u{0020}means\u{0020}staying\u{0020}where\u{0020}she\u{0020}is.\n\u{3000}\u{3000}Always\u{0020}falling\u{0020}behind\u{0020}everyone\u{0020}else.\n\u{3000}\u{3000}This\u{0020}will\u{0020}not\u{0020}do.\u{0020}This\u{0020}is\u{0020}not\u{0020}right.\u{0020}She\u{0020}finally\u{0020}realized\u{0020}that.\n\u{3000}\u{3000}The\u{0020}fruit\u{0020}of\u{0020}victory\u{0020}will\u{0020}not\u{0020}be\u{0020}delivered\u{0020}into\u{0020}her\u{0020}hands.\u{0020}She\u{0020}has\u{0020}to\u{0020}reach\u{0020}out\u{0020}and\u{0020}take\u{0020}it\u{0020}herself.\n\u{3000}\u{3000}The\u{0020}title\u{0020}of\u{0020}victor\u{0020}is\u{0020}something\u{0020}earned\u{0020}through\u{0020}striving.\n\u{3000}\u{3000}Miss\u{0020}Franca\u{0020}refuses\u{0020}to\u{0020}fall\u{0020}behind.", "0", "0", "0", "0", 13025, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[632600] = {632600, 0, "[Name]:\u{0020}Shiranui\n[Date\u{0020}of\u{0020}Birth]:\u{0020}November\u{0020}26\n[Compatibility\u{0020}Rate]:\u{0020}87%\n[Height\u{0020}after\u{0020}Gigantification]:\u{0020}40m\n[Squad]:\u{0020}Cosmic\u{0020}Problem\u{0020}Children\n[Affiliation]:\u{0020}Heroine\u{0020}Universe\n[Likes]:\u{0020}Cute\u{0020}stuff,\u{0020}taking\u{0020}care\u{0020}of\u{0020}others.", "0", "0", "0", "0", 13026, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[632601] = {632601, 100, "\u{3000}\u{3000}\"You\u{0020}have\u{0020}way\u{0020}too\u{0020}many\u{0020}moms.\"\n\u{3000}\u{3000}\u{0020}This\u{0020}was\u{0020}Shiranui's\u{0020}complaint.\u{0020}I\u{0020}felt\u{0020}like\u{0020}I'd\u{0020}heard\u{0020}something\u{0020}similar\u{0020}before,\u{0020}probably\u{0020}a\u{0020}version\u{0020}that\u{0020}went,\u{0020}\"You\u{0020}have\u{0020}way\u{0020}too\u{0020}many\u{0020}Heroines.\"\n\u{3000}\u{3000}\u{0020}\"Besides\u{0020}Mother\u{0020}Stephanie,\u{0020}there's\u{0020}me,\u{0020}right?\u{0020}And\u{0020}Suzuki\u{0020}Seifung,\u{0020}that\u{0020}girl\u{0020}who\u{0020}also\u{0020}wants\u{0020}to\u{0020}take\u{0020}care\u{0020}of\u{0020}you...\u{0020}and\u{0020}so\u{0020}many\u{0020}other\u{0020}Heroines\u{0020}fighting\u{0020}over\u{0020}this\u{0020}niche.\"\n\u{3000}\u{3000}\u{0020}\"What\u{0020}kind\u{0020}of\u{0020}weird\u{0020}term\u{0020}is\u{0020}'niche'...?\"\u{0020}It\u{0020}seemed\u{0020}I'd\u{0020}stumbled\u{0020}upon\u{0020}something\u{0020}unusual\u{0020}again.\n\u{3000}\u{3000}\u{0020}\"Simply\u{0020}put,\u{0020}we\u{0020}need\u{0020}a\u{0020}unique\u{0020}title\u{0020}to\u{0020}solidify\u{0020}our\u{0020}relationship\u{0020}with\u{0020}tyou...\u{0020}Heh,\u{0020}sounds\u{0020}ridiculous,\u{0020}doesn't\u{0020}it?\u{0020}They're\u{0020}fighting\u{0020}tooth\u{0020}and\u{0020}nail\u{0020}over\u{0020}it...\u{0020}But\u{0020}unfortunately!\u{0020}No\u{0020}matter\u{0020}how\u{0020}much\u{0020}they\u{0020}compete,\u{0020}it's\u{0020}pointless.\u{0020}Mother\u{0020}Shiranui\u{0020}has\u{0020}already\u{0020}taken\u{0020}the\u{0020}lead!\"", "0", "0", "0", "0", 13026, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632602] = {632602, 500, "\u{3000}\u{3000}As\u{0020}one\u{0020}of\u{0020}the\u{0020}Cosmic\u{0020}Problem\u{0020}Children,\u{0020}Shiranui\u{0020}seemed\u{0020}noticeably\u{0020}more\u{0020}mature\u{0020}and\u{0020}reliable\u{0020}than\u{0020}the\u{0020}others.\u{0020}From\u{0020}daily\u{0020}interactions,\u{0020}it\u{0020}was\u{0020}easy\u{0020}to\u{0020}see\u{0020}she\u{0020}took\u{0020}care\u{0020}of\u{0020}the\u{0020}other\u{0020}problem\u{0020}children,\u{0020}but\u{0020}that\u{0020}was\u{0020}a\u{0020}lie.\u{0020}A\u{0020}trap,\u{0020}like\u{0020}a\u{0020}Venus\u{0020}flytrap\u{0020}luring\u{0020}prey\u{0020}with\u{0020}sweet\u{0020}fragrance.\u{0020}She\u{0020}wasn't\u{0020}actually\u{0020}\"the\u{0020}leader\u{0020}who\u{0020}looks\u{0020}after\u{0020}everyone\";\u{0020}she\u{0020}was\u{0020}a\u{0020}genuine\u{0020}problem\u{0020}child\u{0020}herself.\n\u{3000}\u{3000}\u{0020}[Universal\u{0020}Calamity:\u{0020}Nursery],\u{0020}that\u{0020}was\u{0020}the\u{0020}codename\u{0020}Shiranui\u{0020}received\u{0020}after\u{0020}arriving\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe,\u{0020}before\u{0020}she\u{0020}became\u{0020}a\u{0020}Heroine.\u{0020}She\u{0020}set\u{0020}up\u{0020}a\u{0020}nursery\u{0020}in\u{0020}space,\u{0020}attracting\u{0020}others\u{0020}with\u{0020}the\u{0020}promise\u{0020}of\u{0020}letting\u{0020}them\u{0020}experience\u{0020}the\u{0020}happiness\u{0020}of\u{0020}childhood,\u{0020}all\u{0020}while\u{0020}gradually\u{0020}making\u{0020}everyone\u{0020}dependent\u{0020}on\u{0020}her\u{0020}care.\n\u{3000}\u{3000}\u{0020}Before\u{0020}the\u{0020}Heroine\u{0020}Association\u{0020}noticed,\u{0020}she\u{0020}had\u{0020}amassed\u{0020}a\u{0020}terrifying\u{0020}amount\u{0020}of\u{0020}influence\u{0020}in\u{0020}this\u{0020}universe,\u{0020}with\u{0020}spies\u{0020}in\u{0020}nearly\u{0020}every\u{0020}organization.\u{0020}She\u{0020}acted\u{0020}on\u{0020}her\u{0020}desires,\u{0020}wanting\u{0020}to\u{0020}turn\u{0020}everyone\u{0020}into\u{0020}babies\u{0020}and\u{0020}become\u{0020}their\u{0020}mother.\n\u{3000}\u{3000}\u{0020}And\u{0020}so,\u{0020}the\u{0020}Infant\u{0020}Revolution\u{0020}began.\n\u{3000}\u{3000}\u{0020}Heroines\u{0020}turned\u{0020}into\u{0020}infants\u{0020}fought\u{0020}for\u{0020}Shiranui's\u{0020}affection,\u{0020}and\u{0020}she\u{0020}reveled\u{0020}in\u{0020}this\u{0020}beautiful\u{0020}spectacle.\u{0020}Then,\u{0020}seven\u{0020}Heroines,\u{0020}later\u{0020}known\u{0020}as\u{0020}the\u{0020}Neglected\u{0020}Seven,\u{0020}had\u{0020}their\u{0020}memories\u{0020}awakened\u{0020}and\u{0020}began\u{0020}to\u{0020}take\u{0020}action.\n\u{3000}\u{3000}\u{0020}In\u{0020}the\u{0020}end,\u{0020}Shiranui\u{0020}was\u{0020}defeated\u{0020}by\u{0020}the\u{0020}Neglected\u{0020}Seven.\u{0020}A\u{0020}happy\u{0020}ending?\n\u{3000}\u{3000}\u{0020}\"So\u{0020}which\u{0020}seven\u{0020}Heroines\u{0020}were\u{0020}so\u{0020}unlucky...\u{0020}that\u{0020}they\u{0020}didn't\u{0020}get\u{0020}your\u{0020}care?\"\n\u{3000}\u{3000}\u{0020}\"Hmm...\u{0020}It's\u{0020}a\u{0020}secret.\"\u{0020}She\u{0020}didn't\u{0020}seem\u{0020}keen\u{0020}on\u{0020}sharing\u{0020}this\u{0020}embarrassing\u{0020}history.", "0", "0", "0", "0", 13026, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[632603] = {632603, 1000, "\u{3000}\u{3000}After\u{0020}her\u{0020}defeat,\u{0020}Shiranui\u{0020}grew\u{0020}completely\u{0020}quiet.\u{0020}She\u{0020}neither\u{0020}joined\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}nor\u{0020}continued\u{0020}disrupting\u{0020}cosmic\u{0020}peace.\n\u{3000}\u{3000}\u{0020}\"I'm\u{0020}very\u{0020}tired;\u{0020}let\u{0020}me\u{0020}rest\u{0020}for\u{0020}a\u{0020}while.\"\u{0020}she\u{0020}said,\u{0020}vanishing\u{0020}into\u{0020}the\u{0020}cosmos,\u{0020}only\u{0020}occasionally\u{0020}spotted\u{0020}at\u{0020}various\u{0020}pudding\u{0020}shops.\u{0020}To\u{0020}the\u{0020}Heroine\u{0020}Association,\u{0020}it\u{0020}seemed\u{0020}Shiranui\u{0020}had\u{0020}abandoned\u{0020}her\u{0020}inflated\u{0020}desires\u{0020}and\u{0020}redirected\u{0020}her\u{0020}focus\u{0020}to\u{0020}pudding.\u{0020}his\u{0020}aligned\u{0020}with\u{0020}the\u{0020}intelligence\u{0020}they\u{0020}received:\u{0020}\"Pudding\u{0020}is\u{0020}the\u{0020}key\u{0020}to\u{0020}defeating\u{0020}Shiranui.\"\u{0020}In\u{0020}short,\u{0020}she\u{0020}was\u{0020}now\u{0020}a\u{0020}good\u{0020}person\u{0020}(Association-certified).\n\u{3000}\u{3000}\u{0020}If\u{0020}left\u{0020}alone,\u{0020}the\u{0020}day\u{0020}might\u{0020}come\u{0020}when\u{0020}Shiranui's\u{0020}name\u{0020}once\u{0020}again\u{0020}echoed\u{0020}across\u{0020}the\u{0020}universe,\u{0020}but\u{0020}unfortunately,\u{0020}she\u{0020}caught\u{0020}the\u{0020}attention\u{0020}of\u{0020}Tsukumo\u{0020}Tamaki,\u{0020}a\u{0020}psychic\u{0020}who\u{0020}could\u{0020}see\u{0020}the\u{0020}future.\n\u{3000}\u{3000}\u{0020}After\u{0020}that,\u{0020}guided\u{0020}deliberately\u{0020}by\u{0020}Tsukumo\u{0020}Tamaki,\u{0020}Shiranui\u{0020}faced\u{0020}off\u{0020}against\u{0020}[Universal\u{0020}Calamity:\u{0020}Dark\u{0020}Throne]\u{0020}(Hikari)\u{0020}head-on,\u{0020}expending\u{0020}all\u{0020}the\u{0020}power\u{0020}she\u{0020}had\u{0020}accumulated...", "0", "0", "0", "0", 13026, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[632604] = {632604, 2000, "\u{3000}\u{3000}His\u{0020}figure\u{0020}was\u{0020}that\u{0020}of\u{0020}someone\u{0020}saving\u{0020}the\u{0020}world.\n\u{3000}\u{3000}\u{0020}And\u{0020}I\u{0020}was\u{0020}always\u{0020}following\u{0020}behind\u{0020}him.\n\u{3000}\u{3000}\u{0020}Watching\u{0020}him\u{0020}move\u{0020}forward,\u{0020}again\u{0020}and\u{0020}again.\n\u{3000}\u{3000}\u{0020}He\u{0020}walked\u{0020}ahead,\u{0020}and\u{0020}I\u{0020}followed\u{0020}closely.\n\u{3000}\u{3000}\u{0020}Then\u{0020}spring,\u{0020}summer,\u{0020}autumn,\u{0020}and\u{0020}winter\u{0020}passed\u{0020}in\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye.\n\u{3000}\u{3000}\u{0020}Oh\u{0020}Navigator,\u{0020}my\u{0020}Navigator,\u{0020}when\u{0020}will\u{0020}you\u{0020}finally\u{0020}rest?\n\u{3000}\u{3000}\u{0020}When\u{0020}will\u{0020}you\u{0020}stop\u{0020}moving\u{0020}forward?\n\u{3000}\u{3000}\u{0020}When...\u{0020}will\u{0020}you\u{0020}turn\u{0020}around\u{0020}and\u{0020}look\u{0020}at\u{0020}me?\n\u{3000}\u{3000}\u{0020}Come\u{0020}rest\u{0020}with\u{0020}me\u{0020}for\u{0020}a\u{0020}while.\n\u{3000}\u{3000}\u{0020}Tell\u{0020}me\u{0020}you're\u{0020}tired.\n\u{3000}\u{3000}\u{0020}When\u{0020}that\u{0020}time\u{0020}comes,\u{0020}I\u{0020}will\u{0020}surely\u{0020}be\u{0020}your\u{0020}support.", "0", "0", "0", "0", 13026, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[632800] = {632800, 0, "[Name]\u{0020}Choco\n\u{0020}[B-day]\u{0020}April\u{0020}22\n\u{0020}[Transformation\u{0020}Core\u{0020}Compatibility]\u{0020}87%\n\u{0020}[Height]\u{0020}29m\n\u{0020}[Squad]\u{0020}Choco\u{0020}House\n\u{0020}[Affiliation]\u{0020}Kyushu\u{0020}Headquarters\n\u{0020}[Hobbies]\u{0020}Seeing\u{0020}other\u{0020}people's\u{0020}happy\u{0020}faces", "0", "0", "0", "0", 13028, "0", "0", "0", "0", 1, 1, "0", "0", "0"},
[632801] = {632801, 100, "\u{3000}\u{3000}There\u{0020}is\u{0020}a\u{0020}Driver\u{0020}like\u{0020}this\u{0020}at\u{0020}Kyushu\u{0020}Headquarters.\n\u{3000}\u{3000}She\u{0020}always\u{0020}smiles\u{0020}at\u{0020}everyone,\u{0020}and\u{0020}no\u{0020}one\u{0020}has\u{0020}ever\u{0020}seen\u{0020}her\u{0020}look\u{0020}sad,\u{0020}as\u{0020}if\u{0020}she\u{0020}had\u{0020}been\u{0020}born\u{0020}without\u{0020}the\u{0020}gene\u{0020}for\u{0020}sorrow.\u{0020}She\u{0020}likes\u{0020}wearing\u{0020}her\u{0020}hair\u{0020}in\u{0020}twin\u{0020}tails,\u{0020}carrying\u{0020}a\u{0020}lollipop\u{0020}as\u{0020}tall\u{0020}as\u{0020}she\u{0020}is,\u{0020}and\u{0020}pushing\u{0020}a\u{0020}little\u{0020}cart\u{0020}around\u{0020}wherever\u{0020}she\u{0020}goes.\u{0020}The\u{0020}cart\u{0020}is\u{0020}filled\u{0020}with\u{0020}all\u{0020}kinds\u{0020}of\u{0020}candies.\u{0020}She\u{0020}offers\u{0020}her\u{0020}candies\u{0020}to\u{0020}everyone\u{0020}she\u{0020}meets,\u{0020}and\u{0020}at\u{0020}extremely\u{0020}low\u{0020}prices.\n\u{3000}\u{3000}If\u{0020}you\u{0020}happen\u{0020}to\u{0020}be\u{0020}in\u{0020}a\u{0020}bad\u{0020}mood,\u{0020}and\u{0020}she\u{0020}sees\u{0020}your\u{0020}gloomy\u{0020}face,\u{0020}you\u{0020}will\u{0020}most\u{0020}likely\u{0020}receive\u{0020}one\u{0020}candy,\u{0020}or\u{0020}even\u{0020}many\u{0020}candies,\u{0020}for\u{0020}free.\n\u{3000}\u{3000}Everyone\u{0020}who\u{0020}has\u{0020}tasted\u{0020}her\u{0020}candies\u{0020}says\u{0020}that\u{0020}although\u{0020}they\u{0020}look\u{0020}like\u{0020}perfectly\u{0020}ordinary\u{0020}sweets,\u{0020}they\u{0020}taste\u{0020}incredibly\u{0020}sweet,\u{0020}sweet\u{0020}from\u{0020}the\u{0020}teeth\u{0020}all\u{0020}the\u{0020}way\u{0020}to\u{0020}the\u{0020}heart,\u{0020}melting\u{0020}away\u{0020}the\u{0020}bitterness\u{0020}of\u{0020}life\u{0020}and\u{0020}giving\u{0020}worries\u{0020}an\u{0020}excuse\u{0020}to\u{0020}run\u{0020}away\u{0020}from\u{0020}home.\n\u{3000}\u{3000}She\u{0020}seems\u{0020}less\u{0020}like\u{0020}she\u{0020}is\u{0020}selling\u{0020}candy,\u{0020}and\u{0020}more\u{0020}like\u{0020}she\u{0020}is\u{0020}selling\u{0020}happiness.\n\u{3000}\u{3000}She\u{0020}is\u{0020}Choco.", "0", "0", "0", "0", 13028, "0", "0", "0", "0", 1, 2, "0", "0", "0"},
[632802] = {632802, 500, "\u{3000}\u{3000}There\u{0020}once\u{0020}was\u{0020}a\u{0020}candy\u{0020}shop.\n\u{3000}\u{3000}This\u{0020}shop\u{0020}stood\u{0020}in\u{0020}a\u{0020}seaside\u{0020}town\u{0020}in\u{0020}eastern\u{0020}Kyushu,\u{0020}and\u{0020}was\u{0020}widely\u{0020}known\u{0020}for\u{0020}its\u{0020}colorful\u{0020}candies\u{0020}and\u{0020}rich\u{0020}variety\u{0020}of\u{0020}flavors.\u{0020}Every\u{0020}traveler\u{0020}who\u{0020}came\u{0020}there\u{0020}would\u{0020}visit\u{0020}this\u{0020}candy\u{0020}shop.\u{0020}Even\u{0020}those\u{0020}merely\u{0020}passing\u{0020}through\u{0020}in\u{0020}a\u{0020}hurry\u{0020}would\u{0020}be\u{0020}sure\u{0020}to\u{0020}buy\u{0020}a\u{0020}few\u{0020}jars\u{0020}before\u{0020}leaving,\u{0020}or\u{0020}else\u{0020}they\u{0020}would\u{0020}feel\u{0020}that\u{0020}part\u{0020}of\u{0020}the\u{0020}meaning\u{0020}of\u{0020}their\u{0020}journey\u{0020}had\u{0020}been\u{0020}lost.\n\u{3000}\u{3000}There\u{0020}were\u{0020}two\u{0020}people\u{0020}in\u{0020}the\u{0020}shop.\u{0020}The\u{0020}shopkeeper\u{0020}was\u{0020}an\u{0020}elderly\u{0020}man\u{0020}nearing\u{0020}seventy,\u{0020}with\u{0020}gray\u{0020}at\u{0020}his\u{0020}temples.\u{0020}The\u{0020}other\u{0020}was\u{0020}the\u{0020}shopkeeper's\u{0020}daughter.\u{0020}Occasionally,\u{0020}the\u{0020}daughter's\u{0020}daughter--the\u{0020}shopkeeper's\u{0020}granddaughter--would\u{0020}also\u{0020}come\u{0020}to\u{0020}help\u{0020}at\u{0020}the\u{0020}shop,\u{0020}though\u{0020}most\u{0020}of\u{0020}the\u{0020}time,\u{0020}she\u{0020}only\u{0020}made\u{0020}things\u{0020}more\u{0020}troublesome,\u{0020}such\u{0020}as\u{0020}tasting\u{0020}every\u{0020}single\u{0020}candy\u{0020}one\u{0020}by\u{0020}one.\n\u{3000}\u{3000}There\u{0020}was\u{0020}a\u{0020}sign\u{0020}in\u{0020}the\u{0020}shop\u{0020}that\u{0020}read,\u{0020}\"Sweetness\u{0020}Brings\u{0020}Smiles.\"\u{0020}It\u{0020}was\u{0020}said\u{0020}to\u{0020}have\u{0020}a\u{0020}history\u{0020}of\u{0020}one\u{0020}hundred\u{0020}years,\u{0020}and\u{0020}it\u{0020}was\u{0020}the\u{0020}principle\u{0020}the\u{0020}candy\u{0020}shop\u{0020}had\u{0020}upheld\u{0020}ever\u{0020}since\u{0020}it\u{0020}first\u{0020}opened.\n\u{3000}\u{3000}To\u{0020}bring\u{0020}smiles\u{0020}to\u{0020}customers\u{0020}through\u{0020}sweetness--in\u{0020}other\u{0020}words,\u{0020}to\u{0020}bring\u{0020}happiness\u{0020}to\u{0020}customers\u{0020}through\u{0020}candy.\n\u{3000}\u{3000}This\u{0020}was\u{0020}a\u{0020}business\u{0020}passed\u{0020}down\u{0020}for\u{0020}a\u{0020}hundred\u{0020}years.\u{0020}Once\u{0020}upon\u{0020}a\u{0020}time,\u{0020}their\u{0020}candies\u{0020}could\u{0020}become\u{0020}a\u{0020}kind\u{0020}of\u{0020}comfort\u{0020}for\u{0020}customers\u{0020}during\u{0020}their\u{0020}most\u{0020}bitter\u{0020}and\u{0020}difficult\u{0020}moments,\u{0020}bringing\u{0020}them\u{0020}sweet\u{0020}happiness,\u{0020}as\u{0020}well\u{0020}as\u{0020}the\u{0020}courage\u{0020}to\u{0020}keep\u{0020}going.\n\u{3000}\u{3000}But\u{0020}as\u{0020}times\u{0020}changed,\u{0020}people\u{0020}no\u{0020}longer\u{0020}needed\u{0020}candy.\n\u{3000}\u{3000}It\u{0020}happened\u{0020}over\u{0020}the\u{0020}span\u{0020}of\u{0020}about\u{0020}a\u{0020}dozen\u{0020}years--the\u{0020}same\u{0020}amount\u{0020}of\u{0020}time\u{0020}it\u{0020}took\u{0020}for\u{0020}the\u{0020}shopkeeper's\u{0020}granddaughter\u{0020}to\u{0020}grow\u{0020}from\u{0020}a\u{0020}babbling\u{0020}infant\u{0020}into\u{0020}a\u{0020}graceful\u{0020}young\u{0020}girl.\u{0020}The\u{0020}development\u{0020}of\u{0020}all\u{0020}kinds\u{0020}of\u{0020}technology\u{0020}gave\u{0020}people\u{0020}more\u{0020}ways\u{0020}to\u{0020}obtain\u{0020}happiness.\u{0020}Candies,\u{0020}which\u{0020}had\u{0020}once\u{0020}brought\u{0020}joy\u{0020}through\u{0020}sweetness,\u{0020}gradually\u{0020}became\u{0020}a\u{0020}symbol\u{0020}of\u{0020}\"indulgence,\"\u{0020}and\u{0020}even\u{0020}a\u{0020}terrible\u{0020}threat\u{0020}to\u{0020}health.\n\u{3000}\u{3000}The\u{0020}candy\u{0020}shop's\u{0020}business\u{0020}plummeted,\u{0020}but\u{0020}the\u{0020}quality\u{0020}of\u{0020}its\u{0020}candies\u{0020}never\u{0020}changed.\n\u{3000}\u{3000}The\u{0020}shopkeeper\u{0020}and\u{0020}the\u{0020}shopkeeper's\u{0020}daughter\u{0020}believed\u{0020}that\u{0020}one\u{0020}day,\u{0020}people\u{0020}would\u{0020}need\u{0020}candy\u{0020}again.\n\u{3000}\u{3000}However,\u{0020}the\u{0020}shopkeeper's\u{0020}granddaughter\u{0020}did\u{0020}not\u{0020}think\u{0020}so.\u{0020}As\u{0020}part\u{0020}of\u{0020}the\u{0020}new\u{0020}generation,\u{0020}she\u{0020}believed\u{0020}that\u{0020}the\u{0020}candy\u{0020}shop\u{0020}needed\u{0020}to\u{0020}change.\u{0020}She\u{0020}had\u{0020}to\u{0020}take\u{0020}the\u{0020}initiative\u{0020}and\u{0020}deliver\u{0020}candy\u{0020}into\u{0020}the\u{0020}hands\u{0020}of\u{0020}those\u{0020}who\u{0020}needed\u{0020}it.\n\u{3000}\u{3000}And\u{0020}so,\u{0020}in\u{0020}order\u{0020}to\u{0020}save\u{0020}the\u{0020}candy\u{0020}shop\u{0020}on\u{0020}the\u{0020}verge\u{0020}of\u{0020}closing,\u{0020}and\u{0020}to\u{0020}bring\u{0020}sweet\u{0020}happiness\u{0020}to\u{0020}even\u{0020}more\u{0020}people,\n\u{3000}\u{3000}the\u{0020}shopkeeper's\u{0020}granddaughter--Choco--chose\u{0020}to\u{0020}take\u{0020}the\u{0020}candy\u{0020}shop's\u{0020}name\u{0020}as\u{0020}her\u{0020}banner\u{0020}and\u{0020}become\u{0020}a\u{0020}Driver\u{0020}of\u{0020}Kyushu.", "0", "0", "0", "0", 13028, "0", "0", "0", "0", 1, 3, "0", "0", "0"},
[632803] = {632803, 1000, "\u{3000}\u{3000}Become\u{0020}a\u{0020}Driver\u{0020}and\u{0020}save\u{0020}the\u{0020}candy\u{0020}shop--no\u{0020}one\u{0020}knows\u{0020}how\u{0020}Choco\u{0020}connected\u{0020}these\u{0020}two\u{0020}things.\n\u{3000}\u{3000}However,\u{0020}there\u{0020}is\u{0020}no\u{0020}denying\u{0020}that\u{0020}Choco\u{0020}succeeded.\u{0020}After\u{0020}she\u{0020}began\u{0020}taking\u{0020}on\u{0020}missions\u{0020}as\u{0020}part\u{0020}of\u{0020}the\u{0020}\"Choco\u{0020}House\"\u{0020}squad,\u{0020}the\u{0020}candy\u{0020}shop\u{0020}back\u{0020}home\u{0020}did\u{0020}indeed\u{0020}become\u{0020}a\u{0020}little\u{0020}more\u{0020}popular\u{0020}than\u{0020}before,\u{0020}though\u{0020}it\u{0020}still\u{0020}could\u{0020}not\u{0020}compare\u{0020}to\u{0020}its\u{0020}peak.\n\u{3000}\u{3000}It\u{0020}was\u{0020}like\u{0020}a\u{0020}sponsored\u{0020}ad\u{0020}on\u{0020}TV,\u{0020}letting\u{0020}more\u{0020}people\u{0020}know\u{0020}that\u{0020}the\u{0020}candy\u{0020}shop\u{0020}existed.\n\u{3000}\u{3000}\"Awoo\u{0020}Corner\u{0020}Store\"\u{0020}was\u{0020}another\u{0020}clever\u{0020}move\u{0020}by\u{0020}Choco.\u{0020}Choco\u{0020}knew\u{0020}that\u{0020}in\u{0020}this\u{0020}era,\u{0020}an\u{0020}overly\u{0020}limited\u{0020}product\u{0020}lineup\u{0020}would\u{0020}not\u{0020}be\u{0020}competitive.\u{0020}\"Awoo\u{0020}Corner\u{0020}Store\"\u{0020}sells\u{0020}not\u{0020}only\u{0020}candy,\u{0020}but\u{0020}also\u{0020}all\u{0020}kinds\u{0020}of\u{0020}desserts\u{0020}and\u{0020}snacks.\u{0020}Aside\u{0020}from\u{0020}the\u{0020}candy,\u{0020}which\u{0020}is\u{0020}made\u{0020}by\u{0020}her\u{0020}family,\u{0020}the\u{0020}other\u{0020}snacks\u{0020}are\u{0020}all\u{0020}products\u{0020}available\u{0020}on\u{0020}the\u{0020}market,\u{0020}but\u{0020}every\u{0020}one\u{0020}of\u{0020}them\u{0020}has\u{0020}been\u{0020}personally\u{0020}tested\u{0020}by\u{0020}Choco,\u{0020}bite\u{0020}by\u{0020}bite.\u{0020}To\u{0020}Choco,\u{0020}\"Awoo\u{0020}Corner\u{0020}Store\"\u{0020}is\u{0020}the\u{0020}shop\u{0020}that\u{0020}truly\u{0020}belongs\u{0020}to\u{0020}her.\n\u{3000}\u{3000}She\u{0020}will\u{0020}run\u{0020}it\u{0020}with\u{0020}100%\u{0020}care,\u{0020}and\u{0020}she\u{0020}also\u{0020}has\u{0020}100%\u{0020}confidence\u{0020}that\u{0020}she\u{0020}can\u{0020}use\u{0020}sweetness\u{0020}to\u{0020}deliver\u{0020}happiness\u{0020}to\u{0020}everyone.", "0", "0", "0", "0", 13028, "0", "0", "0", "0", 1, 4, "0", "0", "0"},
[632804] = {632804, 2000, "\u{3000}\u{3000}I\u{0020}simmer\u{0020}sadness\u{0020}into\u{0020}candy,\n\u{3000}\u{3000}and\u{0020}sell\u{0020}it\u{0020}to\u{0020}you.\n\u{3000}\u{3000}Affordable\u{0020}prices,\u{0020}honest\u{0020}to\u{0020}all.\n\u{3000}\u{3000}It\u{0020}is\u{0020}all\u{0020}right\u{0020}even\u{0020}if\u{0020}you\u{0020}have\u{0020}no\u{0020}money.\n\u{3000}\u{3000}Please\u{0020}accept\u{0020}this\u{0020}free\u{0020}dessert--\n\u{3000}\u{3000}because\u{0020}sweetness\u{0020}needs\u{0020}no\u{0020}price,\n\u{3000}\u{3000}because\u{0020}happiness\u{0020}needs\u{0020}no\u{0020}price.\n\u{3000}\u{3000}If\u{0020}I\u{0020}could,\n\u{3000}\u{3000}I\u{0020}would\u{0020}hope\u{0020}that\u{0020}in\u{0020}everyone's\u{0020}pocket,\n\u{3000}\u{3000}there\u{0020}is\u{0020}always\n\u{3000}\u{3000}a\u{0020}little\u{0020}piece\u{0020}of\u{0020}happiness\n\u{3000}\u{3000}ready\u{0020}to\u{0020}be\u{0020}unwrapped\u{0020}at\u{0020}any\u{0020}time.", "0", "0", "0", "0", 13028, "0", "0", "0", "0", 1, 5, "0", "0", "0"},
[640000] = {640000, 0, "[Name]\u{0020}Starry\n[B-Day]\u{0020}Jan\u{0020}14\n[Compatability\u{0020}Rate]\u{0020}77％\n[Height]\u{0020}36m\n[Squad]\u{0020}Frontier\n[Affiliation]\u{0020}Maya\u{0020}Branch\n[Interest]\u{0020}Baseball,\u{0020}Sudoku,\u{0020}being\u{0020}in\u{0020}a\u{0020}daze", "0", "0", "0", "0", 14000, "0", "0", "0", "0", 1, 1, "0", "0", "[Name]\u{1000}欧朵啦\n[B-Day]\u{1000}5月2日\n[幻化核心适格率]\u{1000}53％\n[Height]\u{1000}24m\n[部队]\u{1000}魂灭\n[隶属]\u{1000}九州总部\n[Interest]\u{1000}睡觉\u{1000}露露啦的背"},
[640001] = {640001, 100, "\u{0020}\u{0020}The\u{0020}essence\u{0020}of\u{0020}Starry\u{0020}is\u{0020}being\u{0020}stripped\u{0020}away\u{0020}little\u{0020}by\u{0020}little.\n\nThose\u{0020}who\u{0020}are\u{0020}bewitched\u{0020}by\u{0020}her\u{0020}smile\u{0020}may\u{0020}not\u{0020}be\u{0020}able\u{0020}to\u{0020}clearly\u{0020}realize\u{0020}what\u{0020}is\u{0020}going\u{0020}on\u{0020}with\u{0020}her.\n\n\"I'm\u{0020}so\u{0020}lucky.\"\u{0020}Starry\u{0020}is\u{0020}always\u{0020}praising\u{0020}her\u{0020}own\u{0020}luck.\n\nPraise\u{0020}the\u{0020}bestowed\u{0020}good\u{0020}fortune\u{0020}with\u{0020}a\u{0020}happy\u{0020}smile.\n\nBut\u{0020}for\u{0020}the\u{0020}world,\u{0020}the\u{0020}strong\u{0020}luck\u{0020}that\u{0020}happened\u{0020}to\u{0020}her\u{0020}was\u{0020}simply\u{0020}as\u{0020}terrifying\u{0020}as\u{0020}a\u{0020}curse.\n\nCursing\u{0020}herself\u{0020}and\u{0020}those\u{0020}around\u{0020}her.\n\nIf\u{0020}the\u{0020}essence\u{0020}of\u{0020}strong\u{0020}luck\u{0020}is\u{0020}a\u{0020}curse.\n\nThen\u{0020}what\u{0020}exactly\u{0020}is\u{0020}the\u{0020}essence\u{0020}of\u{0020}her\u{0020}heart\u{0020}who\u{0020}builds\u{0020}enthusiasm\u{0020}with\u{0020}a\u{0020}smile?", "0", "0", "0", "0", 14000, "0", "0", "0", "0", 1, 2, "0", "0", "\u{1000}\u{1000}\"魂灭\"的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{1000}\u{1000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{1000}\u{1000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着\"生活障碍症\"这一奇怪病症。\n\u{1000}\u{1000}\"不……无论怎么看，都只是纯粹的懒惰而已吧……\"尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[640002] = {640002, 500, "\u{0020}\u{0020}\"The\u{0020}birth\u{0020}of\u{0020}Starry\u{0020}was\u{0020}an\u{0020}accident.\"\n\nThis\u{0020}comment\u{0020}might\u{0020}always\u{0020}suit\u{0020}her.\n\nWhen\u{0020}initially\u{0020}deciding\u{0020}on\u{0020}an\u{0020}alias\u{0020}to\u{0020}replace\u{0020}her\u{0020}official\u{0020}name\u{0020}-\u{0020}that\u{0020}is,\u{0020}a\u{0020}code\u{0020}name,\u{0020}Starry\u{0020}once\u{0020}fell\u{0020}into\u{0020}a\u{0020}brief\u{0020}predicament.\u{0020}She\u{0020}wanted\u{0020}to\u{0020}express\u{0020}the\u{0020}meaning\u{0020}of\u{0020}\"twinkling\u{0020}stars\",\u{0020}so\u{0020}she\u{0020}intended\u{0020}to\u{0020}take\u{0020}\"Stella\"\u{0020}as\u{0020}her\u{0020}code\u{0020}name.\n\nUnfortunately,\u{0020}this\u{0020}name\u{0020}has\u{0020}already\u{0020}been\u{0020}taken\u{0020}by\u{0020}someone\u{0020}else.\n\nThen\u{0020}she\u{0020}just\u{0020}saw\u{0020}the\u{0020}single\u{0020}\"Starry\"\u{0020}released\u{0020}by\u{0020}a\u{0020}band\u{0020}to\u{0020}promote\u{0020}the\u{0020}album.\n\nIf\u{0020}it\u{0020}weren't\u{0020}for\u{0020}just\u{0020}seeing\u{0020}this\u{0020}song,\u{0020}perhaps\u{0020}Starry\u{0020}would\u{0020}have\u{0020}adopted\u{0020}the\u{0020}variant\u{0020}name\u{0020}\"Stella\"\u{0020}as\u{0020}her\u{0020}code\u{0020}name.\n\nIt\u{0020}was\u{0020}not\u{0020}until\u{0020}recently\u{0020}that\u{0020}she\u{0020}realized\u{0020}that\u{0020}this\u{0020}song\u{0020}seemed\u{0020}to\u{0020}belong\u{0020}to\u{0020}the\u{0020}band\u{0020}\"The\u{0020}Live\"\u{0020}like\u{0020}\"Anti\u{0020}Nova\".\n\nIt\u{0020}was\u{0020}a\u{0020}song\u{0020}composed\u{0020}by\u{0020}the\u{0020}lead\u{0020}singer\u{0020}of\u{0020}the\u{0020}band\u{0020}-\u{0020}the\u{0020}girl\u{0020}named\u{0020}Nozomi\u{0020}-\u{0020}herself.\n\nWhat\u{0020}a\u{0020}disgusting\u{0020}coincidence,\u{0020}she\u{0020}sighed.\n\nThe\u{0020}song\u{0020}title\u{0020}composed\u{0020}by\u{0020}the\u{0020}girl\u{0020}who\u{0020}could\u{0020}play\u{0020}with\u{0020}fate\u{0020}but\u{0020}ultimately\u{0020}died\u{0020}because\u{0020}of\u{0020}playing\u{0020}with\u{0020}fate\u{0020}eventually\u{0020}became\u{0020}the\u{0020}code\u{0020}name\u{0020}for\u{0020}the\u{0020}girl\u{0020}who\u{0020}manipulated\u{0020}luck\u{0020}but\u{0020}was\u{0020}cursed\u{0020}by\u{0020}luck.\n\nStarry\u{0020}might\u{0020}detest\u{0020}this\u{0020}kind\u{0020}of\u{0020}bad-taste\u{0020}coincidence\u{0020}from\u{0020}the\u{0020}bottom\u{0020}of\u{0020}her\u{0020}heart.\n\nBecause\u{0020}this\u{0020}would\u{0020}make\u{0020}her\u{0020}deeply\u{0020}aware\u{0020}that\u{0020}-\u{0020}perhaps\u{0020}there\u{0020}are\u{0020}really\u{0020}rules\u{0020}in\u{0020}this\u{0020}world\u{0020}that\u{0020}override\u{0020}logic.\u{0020}But\u{0020}if\u{0020}this\u{0020}is\u{0020}the\u{0020}case,\u{0020}then\u{0020}what\u{0020}is\u{0020}the\u{0020}meaning\u{0020}of\u{0020}her\u{0020}efforts\u{0020}so\u{0020}far?\n\nIf\u{0020}fate\u{0020}is\u{0020}destined\u{0020}to\u{0020}be\u{0020}unchangeable,\u{0020}or\u{0020}fate\u{0020}is\u{0020}destined\u{0020}to\u{0020}be\u{0020}changed,\u{0020}then\u{0020}led\u{0020}by\u{0020}her,\u{0020}what\u{0020}are\u{0020}the\u{0020}reasons\u{0020}for\u{0020}those\u{0020}who\u{0020}rush\u{0020}to\u{0020}all\u{0020}parts\u{0020}of\u{0020}the\u{0020}world\u{0020}one\u{0020}after\u{0020}another\u{0020}to\u{0020}fight?\n\nAzure\u{0020}Fortunate\u{0020}Daughter\u{0020}doesn't\u{0020}believe\u{0020}in\u{0020}fate.", "0", "0", "0", "0", 14000, "0", "0", "0", "0", 1, 3, "0", "0", "\u{1000}\u{1000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{1000}\u{1000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{1000}\u{1000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{1000}\u{1000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了\"明日之花\"的鼓励性质奖章。\n\u{1000}\u{1000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{1000}\u{1000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{1000}\u{1000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队\"魂灭\"的雏形，也是从那个时候开始的。\n\u{1000}\u{1000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队\"魂灭\"的一员。"},
[640003] = {640003, 1000, "\u{0020}\u{0020}Starry\u{0020}had\u{0020}arrived\u{0020}in\u{0020}the\u{0020}Mayan\u{0020}region\u{0020}of\u{0020}Chesterton\u{0020}a\u{0020}week\u{0020}before\u{0020}the\u{0020}Mayan\u{0020}Ark\u{0020}crashed.\n\nWhat\u{0020}happened\u{0020}before\u{0020}the\u{0020}Ark\u{0020}crashed\u{0020}is\u{0020}known\u{0020}to\u{0020}few\u{0020}people,\u{0020}and\u{0020}Starry\u{0020}is\u{0020}just\u{0020}one\u{0020}of\u{0020}them.\n\nPerhaps\u{0020}she\u{0020}did\u{0020}a\u{0020}lot\u{0020}to\u{0020}prevent\u{0020}the\u{0020}Ark\u{0020}from\u{0020}crashing,\u{0020}or\u{0020}perhaps\u{0020}she\u{0020}didn't\u{0020}have\u{0020}time\u{0020}to\u{0020}do\u{0020}anything\u{0020}and\u{0020}could\u{0020}only\u{0020}watch\u{0020}helplessly\u{0020}as\u{0020}the\u{0020}Ark\u{0020}crashed.\n\nBut\u{0020}in\u{0020}any\u{0020}case,\u{0020}this\u{0020}time\u{0020}she\u{0020}survived\u{0020}in\u{0020}a\u{0020}desperate\u{0020}situation\u{0020}as\u{0020}always.\n\nEven\u{0020}if\u{0020}the\u{0020}probability\u{0020}of\u{0020}survival\u{0020}this\u{0020}time\u{0020}may\u{0020}only\u{0020}be\u{0020}1/300M\u{0020}Exception.\n\nAfter\u{0020}crossing\u{0020}the\u{0020}threshold\u{0020}of\u{0020}a\u{0020}survival\u{0020}rate\u{0020}of\u{0020}one\u{0020}in\u{0020}300\u{0020}million,\u{0020}she\u{0020}still\u{0020}wouldn't\u{0020}stop.\n\nShe\u{0020}knew\u{0020}that\u{0020}the\u{0020}next\u{0020}battlefield\u{0020}was\u{0020}waiting\u{0020}for\u{0020}her,\u{0020}and\u{0020}after\u{0020}that\u{0020}battlefield,\u{0020}there\u{0020}would\u{0020}be\u{0020}a\u{0020}new\u{0020}battlefield.\n\nUntil\u{0020}she\u{0020}decides\u{0020}the\u{0020}outcome\u{0020}with\u{0020}the\u{0020}deity.", "0", "0", "0", "0", 14000, "0", "0", "0", "0", 1, 4, "0", "0", "\u{1000}\u{1000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{1000}\u{1000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{1000}\u{1000}\"魂灭小队中存在着一个幽灵队员——\"渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{1000}\u{1000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{1000}\u{1000}\"——我可以去睡觉了吗？呜……\"\n\u{1000}\u{1000}——是的，她只是懒而已。"},
[640004] = {640004, 2000, "\u{0020}\u{0020}Dance\u{0020}the\u{0020}body\u{0020}heartily\u{0020}in\u{0020}despair\n\nLet\u{0020}the\u{0020}turbulent\u{0020}world\u{0020}become\u{0020}the\u{0020}stage\u{0020}for\u{0020}one's\u{0020}wild\u{0020}and\u{0020}unrestrained\u{0020}movements.\n\nBe\u{0020}a\u{0020}little\u{0020}more\u{0020}wayward\u{0020}and\u{0020}a\u{0020}little\u{0020}more\u{0020}self-centered.\n\nWhat\u{0020}one\u{0020}does\u{0020}now\u{0020}is\u{0020}allowed.\n\nOne\u{0020}can\u{0020}achieve\u{0020}anything\u{0020}one\u{0020}does\u{0020}now.\n\nLet\u{0020}those\u{0020}noises\u{0020}be\u{0020}louder!\n\nLet\u{0020}those\u{0020}words\u{0020}fly\u{0020}beyond\u{0020}the\u{0020}universe.\n\nLet\u{0020}others\u{0020}see\u{0020}your\u{0020}true\u{0020}self.\n\nTo\u{0020}save\u{0020}the\u{0020}world.\n\nTo\u{0020}do\u{0020}wanton\u{0020}and\u{0020}unrestrained\u{0020}things\n\nGo\u{0020}meet\u{0020}your\u{0020}\"only\u{0020}one\".", "0", "0", "0", "0", 14000, "0", "0", "0", "0", 1, 5, "0", "0", "\u{1000}\u{1000}作战如她所推演的那样进行着，\n\u{1000}\u{1000}原罪的行动早在战争开始前就被她看穿，\n\u{1000}\u{1000}将破局的方法说出之后，\n\u{1000}\u{1000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{1000}\u{1000}\"呼……呼……呼……\"\n\u{1000}\u{1000}\"露露啦……\"\n\u{1000}\u{1000}\"领航……\"\n\u{1000}\u{1000}\"喜欢……\"\n\u{1000}\u{1000}\"最喜欢了……\""},
[640100] = {640100, 0, "【Name】Kosgaard\n\u{0020}【B-Day】March\u{0020}14\n\u{0020}【Transformation\u{0020}Core\u{0020}Proficiency】91％\n\u{0020}【Height】38m\n\u{0020}【Squad】Revelation\u{0020}Spring\n\u{0020}【Affiliation】Danube\u{0020}Branch\n\u{0020}【Interest】Swordsmanship,\u{0020}Mountaineering", "0", "0", "0", "0", 14001, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[640101] = {640101, 100, "\u{3000}\u{3000}Born\u{0020}in\u{0020}an\u{0020}old\u{0020}noble\u{0020}family,\u{0020}serving\u{0020}as\u{0020}the\u{0020}head\u{0020}of\u{0020}the\u{0020}Holy\u{0020}Church\u{0020}Knights,\u{0020}and\u{0020}able\u{0020}to\u{0020}swing\u{0020}a\u{0020}two-handed\u{0020}greatsword\u{0020}with\u{0020}one\u{0020}hand.\u{0020}Based\u{0020}on\u{0020}these\u{0020}three\u{0020}descriptions,\u{0020}people\u{0020}can\u{0020}easily\u{0020}form\u{0020}a\u{0020}first\u{0020}impression,\u{0020}and\u{0020}Kosgaard\u{0020}indeed\u{0020}fits\u{0020}this\u{0020}imagination\u{0020}-\u{0020}to\u{0020}summarize\u{0020}with\u{0020}a\u{0020}comment\u{0020}from\u{0020}a\u{0020}teammate:\u{0020}Just\u{0020}like\u{0020}every\u{0020}modern\u{0020}person's\u{0020}fantasy\u{0020}of\u{0020}a\u{0020}knight,\u{0020}she\u{0020}is\u{0020}someone\u{0020}who\u{0020}values\u{0020}honor\u{0020}as\u{0020}her\u{0020}life.\u{0020}\n\u{3000}\u{3000}Some\u{0020}people\u{0020}pursue\u{0020}the\u{0020}glory\u{0020}called\u{0020}\"Victory\",\u{0020}some\u{0020}pursue\u{0020}the\u{0020}glory\u{0020}called\u{0020}\"Loyalty\",\u{0020}while\u{0020}the\u{0020}glory\u{0020}pursued\u{0020}by\u{0020}Kosgaard\u{0020}is\u{0020}called\u{0020}\"Purity\".\u{0020}She\u{0020}cannot\u{0020}tolerate\u{0020}the\u{0020}relaxation\u{0020}and\u{0020}compromise\u{0020}in\u{0020}front\u{0020}of\u{0020}morality,\u{0020}the\u{0020}indecisive\u{0020}dedication\u{0020}after\u{0020}careful\u{0020}weighing,\u{0020}and\u{0020}the\u{0020}conspiracy\u{0020}lurking\u{0020}in\u{0020}the\u{0020}clouds.\u{0020}She\u{0020}always\u{0020}adheres\u{0020}to\u{0020}this\u{0020}to\u{0020}wash\u{0020}away\u{0020}the\u{0020}mire\u{0020}in\u{0020}her\u{0020}heart\u{0020}and\u{0020}requires\u{0020}herself\u{0020}to\u{0020}flow\u{0020}like\u{0020}a\u{0020}gushing\u{0020}spring.\u{0020}She\u{0020}has\u{0020}indeed\u{0020}fulfilled\u{0020}her\u{0020}requirements\u{0020}for\u{0020}herself,\u{0020}and\u{0020}therefore\u{0020}she\u{0020}has\u{0020}become\u{0020}the\u{0020}head\u{0020}of\u{0020}the\u{0020}knight\u{0020}regiment\u{0020}guarding\u{0020}one\u{0020}side,\u{0020}a\u{0020}driver.", "0", "0", "0", "0", 14001, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[640102] = {640102, 500, "\u{3000}\u{3000}Kosgaard\u{0020}received\u{0020}a\u{0020}good\u{0020}moral\u{0020}education\u{0020}since\u{0020}childhood\u{0020}and\u{0020}was\u{0020}also\u{0020}influenced\u{0020}by\u{0020}the\u{0020}Poynred\u{0020}West\u{0020}District\u{0020}Church.\u{0020}Although\u{0020}she\u{0020}lived\u{0020}in\u{0020}the\u{0020}dilapidated\u{0020}mansion\u{0020}of\u{0020}the\u{0020}old\u{0020}noble\u{0020}family\u{0020}and\u{0020}grew\u{0020}up\u{0020}in\u{0020}the\u{0020}almost\u{0020}isolated\u{0020}and\u{0020}perilous\u{0020}mountainous\u{0020}area,\u{0020}the\u{0020}lack\u{0020}of\u{0020}material\u{0020}life\u{0020}intensified\u{0020}her\u{0020}spiritual\u{0020}pursuit\u{0020}of\u{0020}the\u{0020}sublime.\u{0020}When\u{0020}she\u{0020}was\u{0020}still\u{0020}young,\u{0020}Kosgaard's\u{0020}spirit\u{0020}was\u{0020}as\u{0020}clear\u{0020}as\u{0020}flowing\u{0020}water\u{0020}and\u{0020}as\u{0020}lofty\u{0020}as\u{0020}mountain\u{0020}wind.\u{0020}However,\u{0020}this\u{0020}glass\u{0020}sword\u{0020}blade,\u{0020}forged\u{0020}only\u{0020}by\u{0020}imagination\u{0020}and\u{0020}lacking\u{0020}life\u{0020}experience,\u{0020}was\u{0020}naturally\u{0020}extremely\u{0020}fragile.\u{0020}\n\u{3000}\u{3000}When\u{0020}she\u{0020}was\u{0020}in\u{0020}her\u{0020}early\u{0020}teens,\u{0020}the\u{0020}incident\u{0020}she\u{0020}encountered\u{0020}became\u{0020}the\u{0020}first\u{0020}turning\u{0020}point\u{0020}in\u{0020}Kosgaard's\u{0020}life.\u{0020}A\u{0020}crack\u{0020}appeared\u{0020}in\u{0020}her\u{0020}transparent\u{0020}and\u{0020}flawless\u{0020}heart,\u{0020}and\u{0020}it\u{0020}was\u{0020}a\u{0020}crack\u{0020}that\u{0020}could\u{0020}spread\u{0020}over\u{0020}time.\u{0020}But\u{0020}precisely\u{0020}because\u{0020}of\u{0020}this,\u{0020}she\u{0020}was\u{0020}able\u{0020}to\u{0020}examine\u{0020}what\u{0020}was\u{0020}hidden\u{0020}in\u{0020}the\u{0020}crack\u{0020}of\u{0020}her\u{0020}heart,\u{0020}to\u{0020}confirm\u{0020}whether\u{0020}the\u{0020}knowledge\u{0020}she\u{0020}had\u{0020}received\u{0020}so\u{0020}far\u{0020}was\u{0020}correct,\u{0020}and\u{0020}for\u{0020}the\u{0020}first\u{0020}time,\u{0020}to\u{0020}swing\u{0020}the\u{0020}glass\u{0020}sword\u{0020}blade,\u{0020}which\u{0020}was\u{0020}originally\u{0020}only\u{0020}for\u{0020}ornamental\u{0020}purposes\u{0020}like\u{0020}a\u{0020}vase,\u{0020}as\u{0020}if\u{0020}it\u{0020}were\u{0020}a\u{0020}real\u{0020}weapon.\u{0020}\n\u{3000}\u{3000}What\u{0020}should\u{0020}this\u{0020}weapon\u{0020}be\u{0020}used\u{0020}to\u{0020}strike?\u{0020}The\u{0020}withered\u{0020}elegance\u{0020}of\u{0020}the\u{0020}elders\u{0020}who,\u{0020}although\u{0020}already\u{0020}reduced\u{0020}to\u{0020}a\u{0020}poor\u{0020}family,\u{0020}still\u{0020}stubbornly\u{0020}adhered\u{0020}to\u{0020}the\u{0020}noble\u{0020}spirit?\u{0020}The\u{0020}lofty\u{0020}illusion\u{0020}of\u{0020}the\u{0020}church,\u{0020}which\u{0020}was\u{0020}shaped\u{0020}only\u{0020}by\u{0020}words\u{0020}and\u{0020}beliefs\u{0020}without\u{0020}empirical\u{0020}evidence?\u{0020}Or...\u{0020}the\u{0020}empty\u{0020}and\u{0020}thin\u{0020}girl\u{0020}-\u{0020}Kosgaard\u{0020}herself\u{0020}-\u{0020}who\u{0020}merely\u{0020}repeated\u{0020}the\u{0020}words\u{0020}of\u{0020}adults\u{0020}and\u{0020}passively\u{0020}accepted\u{0020}the\u{0020}deeds\u{0020}and\u{0020}virtues\u{0020}that\u{0020}did\u{0020}not\u{0020}belong\u{0020}to\u{0020}her?\u{0020}\n\u{3000}\u{3000}The\u{0020}answer\u{0020}is\u{0020}undoubtedly.\u{0020}After\u{0020}struggling\u{0020}with\u{0020}various\u{0020}thoughts,\u{0020}Kosgaard\u{0020}finally\u{0020}decided\u{0020}to\u{0020}swing\u{0020}the\u{0020}sword\u{0020}at\u{0020}the\u{0020}ignorant\u{0020}and\u{0020}naive\u{0020}self\u{0020}in\u{0020}the\u{0020}past.\u{0020}The\u{0020}glass\u{0020}sword\u{0020}blade,\u{0020}which\u{0020}originally\u{0020}covered\u{0020}the\u{0020}heart\u{0020}like\u{0020}ice,\u{0020}completely\u{0020}cracked,\u{0020}revealing\u{0020}the\u{0020}true\u{0020}thing\u{0020}inside.\u{0020}It\u{0020}was\u{0020}Kosgaard's\u{0020}own\u{0020}belief,\u{0020}a\u{0020}steel\u{0020}sword\u{0020}blade\u{0020}that\u{0020}would\u{0020}never\u{0020}rust.", "0", "0", "0", "0", 14001, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[640103] = {640103, 1000, "\u{3000}\u{3000}For\u{0020}those\u{0020}who\u{0020}don't\u{0020}know,\u{0020}Kosgaard\u{0020}is\u{0020}simply\u{0020}a\u{0020}pretentious\u{0020}fellow.\u{0020}Despite\u{0020}being\u{0020}a\u{0020}modern\u{0020}person,\u{0020}her\u{0020}style\u{0020}is\u{0020}rather\u{0020}classical.\u{0020}Even\u{0020}among\u{0020}drivers\u{0020}from\u{0020}the\u{0020}old\u{0020}noble\u{0020}families\u{0020}of\u{0020}the\u{0020}Danube,\u{0020}such\u{0020}a\u{0020}degree\u{0020}is\u{0020}rare.\u{0020}She\u{0020}is\u{0020}very\u{0020}strict\u{0020}with\u{0020}herself\u{0020}and\u{0020}those\u{0020}around\u{0020}her\u{0020}and\u{0020}shows\u{0020}no\u{0020}tolerance\u{0020}for\u{0020}immoral\u{0020}matters.\u{0020}But\u{0020}over\u{0020}time,\u{0020}her\u{0020}outspokenness\u{0020}and\u{0020}sense\u{0020}of\u{0020}justice\u{0020}have\u{0020}indeed\u{0020}solved\u{0020}some\u{0020}tangled\u{0020}and\u{0020}difficult\u{0020}problems.\u{0020}She\u{0020}has\u{0020}pierced\u{0020}through\u{0020}many\u{0020}hypocritical\u{0020}facades,\u{0020}making\u{0020}the\u{0020}tacit\u{0020}mistakes\u{0020}public\u{0020}and\u{0020}ultimately\u{0020}resolving\u{0020}them.\u{0020}In\u{0020}the\u{0020}trendy\u{0020}parlance\u{0020}of\u{0020}young\u{0020}people,\u{0020}Kosgaard\u{0020}seems\u{0020}to\u{0020}have\u{0020}joined\u{0020}AEGIS\u{0020}to\u{0020}\"rectify\u{0020}the\u{0020}workplace\".\u{0020}Although\u{0020}she\u{0020}is\u{0020}still\u{0020}aloof,\u{0020}she\u{0020}has\u{0020}gradually\u{0020}gained\u{0020}some\u{0020}silent\u{0020}support\u{0020}and\u{0020}understanding.", "0", "0", "0", "0", 14001, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[640104] = {640104, 2000, "\u{3000}\u{3000}The\u{0020}mountain\u{0020}peak\u{0020}closest\u{0020}to\u{0020}the\u{0020}sky,\u{0020}\n\u{3000}\u{3000}The\u{0020}air\u{0020}becomes\u{0020}thinner.\u{0020}\n\u{3000}\u{3000}Since\u{0020}clear\u{0020}water\u{0020}has\u{0020}no\u{0020}life,\u{0020}\n\u{3000}\u{3000}Could\u{0020}it\u{0020}be\u{0020}that\u{0020}filth\u{0020}is\u{0020}the\u{0020}law\u{0020}of\u{0020}the\u{0020}world?\u{0020}\n\u{3000}\u{3000}The\u{0020}arm\u{0020}accumulating\u{0020}sins\u{0020}is\u{0020}raised\u{0020}again,\u{0020}\n\u{3000}\u{3000}Dispelling\u{0020}hesitation\u{0020}with\u{0020}the\u{0020}brilliance\u{0020}of\u{0020}the\u{0020}holy\u{0020}sword.\u{0020}\n\u{3000}\u{3000}\"Thank\u{0020}you\u{0020}for\u{0020}giving\u{0020}me\u{0020}courage\u{0020}and\u{0020}determination.\"\u{0020}\n\u{3000}\u{3000}Looking\u{0020}into\u{0020}the\u{0020}pupil\u{0020}of\u{0020}that\u{0020}navigator,\u{0020}\n\u{3000}\u{3000}The\u{0020}girl\u{0020}will\u{0020}no\u{0020}longer\u{0020}escape.", "0", "0", "0", "0", 14001, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[640200] = {640200, 0, "[Name]\u{0020}Ophelia\n[Date\u{0020}of\u{0020}Birth]\u{0020}October\u{0020}31\n[Compatibility\u{0020}Rate]\u{0020}70%\n[Height\u{0020}after\u{0020}Gigantification]\u{0020}36m\n[Squad]\u{0020}Seaside\u{0020}Paradise\n[Affiliation]\u{0020}Heroine\u{0020}Universe\n[Likes]\u{0020}Playing\u{0020}with\u{0020}animals,\u{0020}daydreaming", "0", "0", "0", "0", 14002, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】欧朵啦\n【生日】5月2日\n【幻化核心适格率】53％\n【巨大化身高】24m\n【部队】魂灭\n【隶属】九州总部\n【爱好】睡觉\u{3000}露露啦的背"},
[640201] = {640201, 100, "\u{3000}\u{3000}The\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}a\u{0020}realm\u{0020}where\u{0020}heroines\u{0020}gather\u{0020}and\u{0020}among\u{0020}them,\n\n\u{3000}\u{3000}Ophelia\u{0020}stands\u{0020}as\u{0020}one\u{0020}of\u{0020}the\u{0020}most\u{0020}docile.\n\n\u{3000}\u{3000}She\u{0020}accepted\u{0020}her\u{0020}defeat\u{0020}with\u{0020}grace,\u{0020}without\u{0020}protest,\u{0020}dutifully\u{0020}applied\u{0020}for\u{0020}her\u{0020}Universal\u{0020}Pass,\u{0020}and\u{0020}settled\u{0020}on\u{0020}her\u{0020}assigned\u{0020}planet\u{0020}for\u{0020}years.\n\n\u{3000}\u{3000}Through\u{0020}work\u{0020}with\u{0020}the\u{0020}Association,\u{0020}she\u{0020}accumulated\u{0020}enough\u{0020}cosmic\u{0020}points\u{0020}to\u{0020}buy\u{0020}a\u{0020}home,\u{0020}then\u{0020}invested\u{0020}heavily\u{0020}in\u{0020}terraforming.\u{0020}She\u{0020}recreated\u{0020}the\u{0020}Waterwheel\u{0020}Village,\u{0020}Holy\u{0020}Church,\u{0020}the\u{0020}Danube\u{0020}Ark,\u{0020}structures\u{0020}steeped\u{0020}in\u{0020}memory,\u{0020}now\u{0020}supporting\u{0020}her\u{0020}in\u{0020}this\u{0020}new\u{0020}world.\n\n\u{3000}\u{3000}And\u{0020}of\u{0020}course,\u{0020}she\u{0020}couldn't\u{0020}leave\u{0020}out\u{0020}merchandise\u{0020}of\u{0020}that\u{0020}certain\u{0020}Navigator.\n\n\u{3000}\u{3000}At\u{0020}the\u{0020}[Official\u{0020}Heroine\u{0020}Merchandise\u{0020}Store],\u{0020}she\u{0020}splurged\u{0020}on\u{0020}Navigator-themed\u{0020}goods,\u{0020}even\u{0020}commissioning\u{0020}three\u{0020}thousand\u{0020}statues\u{0020}of\u{0020}him\u{0020}to\u{0020}dot\u{0020}the\u{0020}landscape\u{0020}of\u{0020}Ophelia's\u{0020}Planet.\u{0020}This\u{0020}eccentric\u{0020}tribute\u{0020}later\u{0020}inspired\u{0020}many\u{0020}Heroines\u{0020}to\u{0020}follow\u{0020}suit.", "0", "0", "0", "0", 14002, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂灭”的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{3000}\u{3000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{3000}\u{3000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着“生活障碍症”这一奇怪病症。\n\u{3000}\u{3000}“不……无论怎么看，都只是纯粹的懒惰而已吧……”尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[640202] = {640202, 500, "\u{3000}\u{3000}In\u{0020}the\u{0020}Heroine\u{0020}Universe.\n\n\u{3000}\u{3000}Every\u{0020}Heroine\u{0020}in\u{0020}this\u{0020}universe\u{0020}once\u{0020}met\u{0020}a\u{0020}unique\u{0020}defeat,\u{0020}a\u{0020}memory\u{0020}of\u{0020}fighting\u{0020}by\u{0020}your\u{0020}side,\u{0020}a\u{0020}love\u{0020}carved\u{0020}into\u{0020}their\u{0020}bone.\u{0020}For\u{0020}some,\u{0020}the\u{0020}regret\u{0020}twists\u{0020}their\u{0020}nature,\u{0020}straining\u{0020}old\u{0020}bonds\u{0020}until\u{0020}they\u{0020}fray\u{0020}(not\u{0020}from\u{0020}conflict,\u{0020}but\u{0020}diverging\u{0020}convictions).\n\n\u{3000}\u{3000}But\u{0020}Ophelia?\u{0020}She's\u{0020}different.\u{0020}Even\u{0020}now,\u{0020}she\u{0020}clings\u{0020}to\u{0020}her\u{0020}promise\u{0020}to\u{0020}you.\u{0020}Even\u{0020}as\u{0020}you've\u{0020}forgotten\u{0020}her\u{0020}entirely,\u{0020}she\u{0020}who\u{0020}has\u{0020}been\u{0020}shaped\u{0020}by\u{0020}you\u{0020}is\u{0020}still\u{0020}the\u{0020}perfect\u{0020}knight.\u{0020}The\u{0020}blindly\u{0020}loyal\u{0020}knight.\u{0020}The\u{0020}knight\u{0020}who\u{0020}wields\u{0020}her\u{0020}sword\u{0020}just\u{0020}for\u{0020}you.\n\n\u{3000}\u{3000}\"So\u{0020}after\u{0020}all\u{0020}this,\u{0020}Ophelia\u{0020}hasn't\u{0020}changed\u{0020}at\u{0020}all?\u{0020}Not\u{0020}even\u{0020}a\u{0020}little?\u{0020}That's\u{0020}almost\u{0020}impressive.\"\u{0020}Meria,\u{0020}her\u{0020}former\u{0020}teammate\u{0020}from\u{0020}the\u{0020}Revelation\u{0020}Spring,\u{0020}was\u{0020}baffled\u{0020}after\u{0020}visiting.\n\n\u{3000}\u{3000}\"That's\u{0020}precisely\u{0020}what\u{0020}makes\u{0020}her\u{0020}so\u{0020}reliable.\"\u{0020}Mira,\u{0020}their\u{0020}ex-captain,\u{0020}smirked.\u{0020}\"Pay\u{0020}up,\u{0020}Meria.\u{0020}You're\u{0020}treating\u{0020}us\u{0020}to\u{0020}Ophelia's\u{0020}welcome\u{0020}feast.\"\n\n\u{3000}\u{3000}\"Ugh.\u{0020}Both\u{0020}of\u{0020}you\u{0020}are\u{0020}so\u{0020}rigid\u{0020}it's\u{0020}unbearable.\"\u{0020}Meria\u{0020}conceded\u{0020}defeat.\n\n\u{3000}\u{3000}\"Kosgaard's\u{0020}waiting.\u{0020}Let's\u{0020}go.\"\n\n\u{3000}\u{3000}\"A\u{0020}toast,\u{0020}to\u{0020}the\u{0020}[Revelation\u{0020}Spring]'s\u{0020}reunion\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe!\"\n\n\u{3000}\u{3000}As\u{0020}for\u{0020}the\u{0020}accusation\u{0020}of\u{0020}\"no\u{0020}change\"...\u{0020}Ophelia\u{0020}fumbled\u{0020}for\u{0020}words,\u{0020}too\u{0020}embarrassed\u{0020}to\u{0020}confess\u{0020}the\u{0020}tiny\u{0020}evolution\u{0020}in\u{0020}her\u{0020}heart:\u{0020}a\u{0020}budding\u{0020}romance,\u{0020}quietly\u{0020}flourishing.\n\n\u{3000}\u{3000}Thus,\u{0020}her\u{0020}social\u{0020}circle\u{0020}assimilated\u{0020}into\u{0020}this\u{0020}universe\u{0020}smoothly.", "0", "0", "0", "0", 14002, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{3000}\u{3000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{3000}\u{3000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{3000}\u{3000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了“明日之花”的鼓励性质奖章。\n\u{3000}\u{3000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{3000}\u{3000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{3000}\u{3000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队“魂灭”的雏形，也是从那个时候开始的。\n\u{3000}\u{3000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队“魂灭”的一员。"},
[640203] = {640203, 1000, "\u{3000}\u{3000}In\u{0020}the\u{0020}real\u{0020}world.\n\n\u{3000}\u{3000}There\u{0020}is\u{0020}something\u{0020}off\u{0020}about\u{0020}Ophelia.\u{0020}Lately,\u{0020}she's\u{0020}been...\u{0020}clingy.\u{0020}Out\u{0020}of\u{0020}curiosity,\u{0020}I\u{0020}asked\u{0020}her.\n\n\u{3000}\u{3000}\"I-I've\u{0020}received\u{0020}divine\u{0020}revelations\u{0020}in\u{0020}my\u{0020}dreams!\"\u{0020}Her\u{0020}eyes\u{0020}darted\u{0020}like\u{0020}a\u{0020}guilty\u{0020}criminal's,\u{0020}\"The\u{0020}gods\u{0020}said...\u{0020}staying\u{0020}close\u{0020}to\u{0020}Navigator\u{0020}brings\u{0020}good\u{0020}fortune!\"\n\n\u{3000}\u{3000}\"A-and\u{0020}another\u{0020}message\u{0020}said\u{0020}to...\u{0020}hold\u{0020}your\u{0020}hand\u{0020}and\u{0020}never\u{0020}let\u{0020}go.\"\u{0020}Even\u{0020}this\u{0020}simple\u{0020}contact\u{0020}seemed\u{0020}to\u{0020}require\u{0020}tremendous\u{0020}bravery;\u{0020}her\u{0020}cheeks\u{0020}burned\u{0020}scarlet.\n\n\u{3000}\u{3000}It\u{0020}seemed\u{0020}trivial,\u{0020}so\u{0020}I\u{0020}dismissed\u{0020}it,\u{0020}until\u{0020}her\u{0020}behavior\u{0020}escalated.\n\n\u{3000}\u{3000}Fortunately,\u{0020}Mira\u{0020}intervened\u{0020}before\u{0020}things\u{0020}got\u{0020}out\u{0020}of\u{0020}hand,\u{0020}saying,\u{0020}\"My\u{0020}divine\u{0020}revelation\u{0020}warned\u{0020}of\u{0020}someone\u{0020}cheating.\"\n\n\u{3000}\u{3000}As\u{0020}Ophelia\u{0020}was\u{0020}dragged\u{0020}away,\u{0020}flushed\u{0020}crimson,\u{0020}one\u{0020}thought\u{0020}lingered:\n\n\u{3000}\u{3000}[What\u{0020}exactly\u{0020}are\u{0020}these\u{0020}\"revelations\"\u{0020}they\u{0020}keep\u{0020}getting?]", "0", "0", "0", "0", 14002, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{3000}\u{3000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{3000}\u{3000}“魂灭小队中存在着一个幽灵队员——”渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{3000}\u{3000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{3000}\u{3000}“——我可以去睡觉了吗？呜……”\n\u{3000}\u{3000}——是的，她只是懒而已。"},
[640204] = {640204, 2000, "\u{3000}\u{3000}The\u{0020}knight\u{0020}met\u{0020}three\u{0020}deaths.\u{0020}The\u{0020}first\u{0020}came\u{0020}in\u{0020}battle,\n\n\u{3000}\u{3000}where\u{0020}she\u{0020}died\u{0020}as\u{0020}she\u{0020}shielded\u{0020}her\u{0020}lord\u{0020}from\u{0020}ten\u{0020}thousand\u{0020}swords.\n\n\u{3000}\u{3000}The\u{0020}second\u{0020}came\u{0020}with\u{0020}resurrection,\n\n\u{3000}\u{3000}when\u{0020}she\u{0020}learned\u{0020}her\u{0020}lord\u{0020}was\u{0020}lost\u{0020}to\u{0020}her\u{0020}forever.\n\n\u{3000}\u{3000}The\u{0020}third\u{0020}death\u{0020}came\u{0020}by\u{0020}choice,\n\n\u{3000}\u{3000}with\u{0020}her\u{0020}marching\u{0020}into\u{0020}death,\u{0020}armed\u{0020}only\u{0020}with\u{0020}courage\u{0020}and\u{0020}faith.\n\n\u{3000}\u{3000}And\u{0020}at\u{0020}the\u{0020}story's\u{0020}end,\n\n\u{3000}\u{3000}the\u{0020}knight,\u{0020}at\u{0020}last,\u{0020}took\u{0020}her\u{0020}lord's\u{0020}hand\u{0020}just\u{0020}as\u{0020}she'd\u{0020}always\u{0020}dreamed.", "0", "0", "0", "0", 14002, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作战如她所推演的那样进行着，\n\u{3000}\u{3000}原罪的行动早在战争开始前就被她看穿，\n\u{3000}\u{3000}将破局的方法说出之后，\n\u{3000}\u{3000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“领航……”\n\u{3000}\u{3000}“喜欢……”\n\u{3000}\u{3000}“最喜欢了……”"},
[640300] = {640300, 0, "[Name]\u{0020}Iliya\u{0020}K\u{0020}Bronchi\n[B-Day]\u{0020}Aug\u{0020}14\n[Compatibility\u{0020}Rate]\u{0020}97％\n[Height]\u{0020}36m\n[Squad]\u{0020}Ember\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Interest]\u{0020}Ice\u{0020}cream,\u{0020}Crushing\u{0020}Sin\u{0020}Cores.", "0", "0", "0", "0", 14003, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】欧朵啦\n【生日】5月2日\n【幻化核心适格率】53％\n【巨大化身高】24m\n【部队】魂灭\n【隶属】九州总部\n【爱好】睡觉\u{3000}露露啦的背"},
[640301] = {640301, 100, "Iliya\u{0020}K.\u{0020}Bronchi—a\u{0020}calm\u{0020}and\u{0020}deliberate\u{0020}avenger.\n\nFor\u{0020}Iliya,\u{0020}hatred\u{0020}was\u{0020}no\u{0020}longer\u{0020}a\u{0020}burden.\u{0020}While\u{0020}her\u{0020}hatred\u{0020}for\u{0020}the\u{0020}Sin\u{0020}remained\u{0020}as\u{0020}intense\u{0020}as\u{0020}ever,\u{0020}it\u{0020}no\u{0020}longer\u{0020}clouded\u{0020}her\u{0020}judgment\u{0020}or\u{0020}drove\u{0020}her\u{0020}to\u{0020}reckless,\u{0020}irreversible\u{0020}mistakes.\n\nOne\u{0020}of\u{0020}the\u{0020}most\u{0020}visible\u{0020}signs\u{0020}of\u{0020}her\u{0020}transformation\u{0020}was\u{0020}her\u{0020}left\u{0020}hand.\u{0020}Once\u{0020}entirely\u{0020}replaced\u{0020}with\u{0020}metal\u{0020}and\u{0020}polymers,\u{0020}it\u{0020}has\u{0020}since\u{0020}been\u{0020}restored\u{0020}to\u{0020}a\u{0020}smooth,\u{0020}natural\u{0020}form.\u{0020}Yet,\u{0020}it\u{0020}was\u{0020}the\u{0020}invisible\u{0020}changes\u{0020}within\u{0020}her\u{0020}that\u{0020}have\u{0020}truly\u{0020}redefined\u{0020}her.\n\nHer\u{0020}artificial\u{0020}organs,\u{0020}especially\u{0020}her\u{0020}heart,\u{0020}were\u{0020}once\u{0020}the\u{0020}root\u{0020}of\u{0020}her\u{0020}uncontrollable\u{0020}anger.\u{0020}The\u{0020}synthetic\u{0020}heart's\u{0020}accelerated\u{0020}pumping\u{0020}would\u{0020}flood\u{0020}her\u{0020}body\u{0020}with\u{0020}rage-driven\u{0020}emotions,\u{0020}leaving\u{0020}her\u{0020}powerless\u{0020}to\u{0020}resist\u{0020}the\u{0020}tide.\n\nOnly\u{0020}by\u{0020}freeing\u{0020}herself\u{0020}from\u{0020}the\u{0020}constraints\u{0020}of\u{0020}these\u{0020}artificial\u{0020}enhancements\u{0020}did\u{0020}she\u{0020}regain\u{0020}full\u{0020}autonomy\u{0020}over\u{0020}her\u{0020}body.\u{0020}Now,\u{0020}she\u{0020}is\u{0020}a\u{0020}tranquil\u{0020}storm\u{0020}of\u{0020}vengeance\u{0020}incarnate.", "0", "0", "0", "0", 14003, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂灭”的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{3000}\u{3000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{3000}\u{3000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着“生活障碍症”这一奇怪病症。\n\u{3000}\u{3000}“不……无论怎么看，都只是纯粹的懒惰而已吧……”尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[640302] = {640302, 500, "The\u{0020}fusion\u{0020}of\u{0020}human\u{0020}and\u{0020}Sin\u{0020}was\u{0020}rare\u{0020}but\u{0020}not\u{0020}unheard\u{0020}of.\u{0020}Typically,\u{0020}the\u{0020}process\u{0020}used\u{0020}the\u{0020}human\u{0020}body\u{0020}as\u{0020}a\u{0020}vessel\u{0020}to\u{0020}carry\u{0020}the\u{0020}Sin\u{0020}genes,\u{0020}enabling\u{0020}the\u{0020}subject\u{0020}to\u{0020}wield\u{0020}its\u{0020}power.\n\nIliya's\u{0020}case,\u{0020}however,\u{0020}was\u{0020}different.\n\nAfter\u{0020}sampling\u{0020}the\u{0020}remains\u{0020}of\u{0020}Icarus,\u{0020}researchers\u{0020}found\u{0020}significant\u{0020}amounts\u{0020}of\u{0020}human\u{0020}DNA\u{0020}within\u{0020}its\u{0020}tissue.\u{0020}Similarly,\u{0020}traces\u{0020}of\u{0020}Sin\u{0020}were\u{0020}detected\u{0020}in\u{0020}Iliya.\u{0020}Combined\u{0020}with\u{0020}the\u{0020}fragments\u{0020}of\u{0020}artificial\u{0020}limbs\u{0020}and\u{0020}organs\u{0020}recovered\u{0020}near\u{0020}the\u{0020}shattered\u{0020}Sin\u{0020}core,\u{0020}it\u{0020}became\u{0020}evident\u{0020}that\u{0020}the\u{0020}fusion\u{0020}had\u{0020}healed\u{0020}Iliya's\u{0020}once-battered\u{0020}body.\n\nSome\u{0020}theorize\u{0020}that\u{0020}Icarus\u{0020}was\u{0020}created\u{0020}specifically\u{0020}to\u{0020}save\u{0020}Iliya.\n\nThe\u{0020}idea\u{0020}of\u{0020}a\u{0020}Sin\u{0020}born\u{0020}to\u{0020}protect\u{0020}humanity\u{0020}is\u{0020}almost\u{0020}unimaginable,\u{0020}even\u{0020}to\u{0020}those\u{0020}who\u{0020}witnessed\u{0020}the\u{0020}event.\n\nFor\u{0020}many\u{0020}sleepless\u{0020}nights,\u{0020}Iliya\u{0020}grappled\u{0020}with\u{0020}a\u{0020}single\u{0020}question:\u{0020}Can\u{0020}she\u{0020}truly\u{0020}exact\u{0020}her\u{0020}vengeance\u{0020}in\u{0020}her\u{0020}current\u{0020}form?\n\nHer\u{0020}doubts\u{0020}stemmed\u{0020}from\u{0020}her\u{0020}lack\u{0020}of\u{0020}trust\u{0020}in\u{0020}herself.\u{0020}She\u{0020}had\u{0020}sacrificed\u{0020}so\u{0020}much\u{0020}for\u{0020}vengeance,\u{0020}yet\u{0020}found\u{0020}herself\u{0020}unable\u{0020}to\u{0020}fully\u{0020}control\u{0020}her\u{0020}body.\u{0020}How\u{0020}could\u{0020}she\u{0020}achieve\u{0020}her\u{0020}goals\u{0020}like\u{0020}this?\n\nNow,\u{0020}however,\u{0020}her\u{0020}question\u{0020}had\u{0020}shifted:\u{0020}Can\u{0020}what\u{0020}she's\u{0020}doing\u{0020}right\u{0020}now\u{0020}even\u{0020}be\u{0020}called\u{0020}vengeance?\n\nThe\u{0020}power\u{0020}of\u{0020}Icarus\u{0020}not\u{0020}only\u{0020}restored\u{0020}her\u{0020}body\u{0020}but\u{0020}also\u{0020}granted\u{0020}her\u{0020}incredible\u{0020}strength.\u{0020}Before,\u{0020}Iliya\u{0020}relied\u{0020}on\u{0020}artificial\u{0020}organs\u{0020}to\u{0020}reach\u{0020}an\u{0020}89%\u{0020}Compatibility\u{0020}Rate,\u{0020}peaking\u{0020}at\u{0020}92%\u{0020}in\u{0020}a\u{0020}state\u{0020}of\u{0020}rage.\u{0020}Now,\u{0020}with\u{0020}no\u{0020}external\u{0020}aids,\u{0020}she\u{0020}can\u{0020}reach\u{0020}an\u{0020}astonishing\u{0020}97%.\n\nInitially,\u{0020}Iliya\u{0020}was\u{0020}overwhelmed\u{0020}by\u{0020}this\u{0020}strength,\u{0020}which\u{0020}came\u{0020}from\u{0020}the\u{0020}very\u{0020}enemy\u{0020}she\u{0020}despised.\u{0020}But\u{0020}she\u{0020}soon\u{0020}realized\u{0020}a\u{0020}harsh\u{0020}truth:\u{0020}without\u{0020}strength,\u{0020}vengeance\u{0020}is\u{0020}but\u{0020}a\u{0020}pipe\u{0020}dream—even\u{0020}if\u{0020}that\u{0020}strength\u{0020}came\u{0020}from\u{0020}her\u{0020}foe.\n\nPerhaps\u{0020}she\u{0020}remembered\u{0020}that\u{0020}fateful\u{0020}Christmas\u{0020}Eve,\u{0020}the\u{0020}moment\u{0020}when\u{0020}she\u{0020}turned\u{0020}her\u{0020}gun\u{0020}on\u{0020}herself.\u{0020}At\u{0020}that\u{0020}moment,\u{0020}she\u{0020}suddenly\u{0020}realized\u{0020}that\u{0020}this\u{0020}newfound\u{0020}strength\u{0020}wasn't\u{0020}a\u{0020}chain\u{0020}holding\u{0020}her\u{0020}back.\u{0020}She,\u{0020}along\u{0020}with\u{0020}Ember\u{0020}Squad,\u{0020}had\u{0020}embarked\u{0020}on\u{0020}a\u{0020}new\u{0020}path—a\u{0020}path\u{0020}leading\u{0020}to\u{0020}light\u{0020}and\u{0020}vengeance.\n\nAll\u{0020}she\u{0020}needs\u{0020}to\u{0020}do\u{0020}now\u{0020}is\u{0020}move\u{0020}forward.", "0", "0", "0", "0", 14003, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{3000}\u{3000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{3000}\u{3000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{3000}\u{3000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了“明日之花”的鼓励性质奖章。\n\u{3000}\u{3000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{3000}\u{3000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{3000}\u{3000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队“魂灭”的雏形，也是从那个时候开始的。\n\u{3000}\u{3000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队“魂灭”的一员。"},
[640303] = {640303, 1000, "For\u{0020}Ember\u{0020}Squad,\u{0020}the\u{0020}events\u{0020}of\u{0020}Christmas\u{0020}Eve\u{0020}turned\u{0020}out\u{0020}to\u{0020}be\u{0020}a\u{0020}blessing\u{0020}in\u{0020}disguise.\n\nPreviously,\u{0020}Ember\u{0020}Squad\u{0020}had\u{0020}only\u{0020}been\u{0020}a\u{0020}minor,\u{0020}unremarkable\u{0020}unit\u{0020}within\u{0020}AEGIS.\u{0020}With\u{0020}no\u{0020}standout\u{0020}Drivers\u{0020}and\u{0020}a\u{0020}reputation\u{0020}for\u{0020}ignoring\u{0020}orders,\u{0020}they\u{0020}were\u{0020}often\u{0020}overlooked.\u{0020}But\u{0020}the\u{0020}power\u{0020}gained\u{0020}by\u{0020}Bolina\u{0020}and\u{0020}Iliya\u{0020}elevated\u{0020}Ember\u{0020}Squad\u{0020}overnight,\u{0020}making\u{0020}them\u{0020}rivals\u{0020}to\u{0020}even\u{0020}the\u{0020}elite\u{0020}Snow\u{0020}Owl\u{0020}Squad\u{0020}in\u{0020}performance\u{0020}tests.\n\nThis\u{0020}newfound\u{0020}power\u{0020}prompted\u{0020}the\u{0020}Katya\u{0020}Branch\u{0020}to\u{0020}significantly\u{0020}increase\u{0020}their\u{0020}investment\u{0020}in\u{0020}Ember\u{0020}Squad,\u{0020}particularly\u{0020}in\u{0020}resource\u{0020}allocations.\n\nFor\u{0020}the\u{0020}first\u{0020}time,\u{0020}Iliya,\u{0020}as\u{0020}squad\u{0020}leader,\u{0020}was\u{0020}freed\u{0020}from\u{0020}the\u{0020}burden\u{0020}of\u{0020}logistical\u{0020}struggles\u{0020}and\u{0020}could\u{0020}focus\u{0020}entirely\u{0020}on\u{0020}fighting\u{0020}the\u{0020}Sins\u{0020}and\u{0020}pursuing\u{0020}vengeance.\n\nYet\u{0020}one\u{0020}thing\u{0020}remained\u{0020}unchanged:\u{0020}Ember\u{0020}Squad\u{0020}will\u{0020}only\u{0020}ever\u{0020}take\u{0020}orders\u{0020}from\u{0020}their\u{0020}Navigator.\n\nIn\u{0020}Iliya's\u{0020}heart,\u{0020}she\u{0020}will\u{0020}never\u{0020}forget\u{0020}the\u{0020}sacrifices\u{0020}the\u{0020}Navigator\u{0020}made\u{0020}for\u{0020}her.", "0", "0", "0", "0", 14003, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{3000}\u{3000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{3000}\u{3000}“魂灭小队中存在着一个幽灵队员——”渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{3000}\u{3000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{3000}\u{3000}“——我可以去睡觉了吗？呜……”\n\u{3000}\u{3000}——是的，她只是懒而已。"},
[640304] = {640304, 2000, "A\u{0020}crimson\u{0020}spear\u{0020}descended\u{0020}from\u{0020}the\u{0020}sky,\n\nstriking\u{0020}the\u{0020}earth\u{0020}with\u{0020}a\u{0020}thunderous\u{0020}roar.\n\nThe\u{0020}deep,\u{0020}resonant\u{0020}hum\u{0020}of\u{0020}a\u{0020}whale\u{0020}filled\u{0020}the\u{0020}air,\n\nfollowed\u{0020}by\u{0020}a\u{0020}flash\u{0020}of\u{0020}crimson\u{0020}light.\n\nIn\u{0020}the\u{0020}blink\u{0020}of\u{0020}an\u{0020}eye,\u{0020}a\u{0020}girl\u{0020}stood\u{0020}before\u{0020}him,\n\nher\u{0020}gaze\u{0020}was\u{0020}steady\u{0020}and\u{0020}calm.\n\nShe\u{0020}extended\u{0020}her\u{0020}smooth,\n\nsilky\u{0020}hand\u{0020}and\u{0020}parted\u{0020}her\u{0020}lips.\n\n\"I\u{0020}am\u{0020}ready\u{0020}to\u{0020}begin\u{0020}a\u{0020}new\u{0020}life\u{0020}with\u{0020}you,\u{0020}Navigator.\"", "0", "0", "0", "0", 14003, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作战如她所推演的那样进行着，\n\u{3000}\u{3000}原罪的行动早在战争开始前就被她看穿，\n\u{3000}\u{3000}将破局的方法说出之后，\n\u{3000}\u{3000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“领航……”\n\u{3000}\u{3000}“喜欢……”\n\u{3000}\u{3000}“最喜欢了……”"},
[640400] = {640400, 0, "[Name]:\u{0020}Charlissa\u{0020}de\u{0020}Roland\n\u{0020}[B-day]:\u{0020}Apr.\u{0020}1\u{0020}\n[Transformation\u{0020}Core\u{0020}Compatibility\u{0020}Rate]:\u{0020}<color=#FF6100>100%</color>\u{0020}\n[Height]:\u{0020}37m\u{0020}\n[Squad]:\u{0020}Torch\u{0020}\n[Affiliation]:\u{0020}New\u{0020}Cheston\u{0020}\n[Hobbies]:\u{0020}Venting\u{0020}violence\u{0020}on\u{0020}sufficiently\u{0020}wide-open\u{0020}ground", "0", "0", "0", "0", 14004, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[640401] = {640401, 100, "\u{3000}\u{3000}Rude\u{0020}manners,\u{0020}a\u{0020}sharp\u{0020}tongue,\u{0020}a\u{0020}fierce\u{0020}competitive\u{0020}streak...\u{0020}The\u{0020}criticized\u{0020}personality\u{0020}traits\u{0020}Charlissa\u{0020}once\u{0020}possessed\u{0020}can\u{0020}no\u{0020}longer\u{0020}be\u{0020}seen\u{0020}in\u{0020}the\u{0020}Charlissa\u{0020}de\u{0020}Roland\u{0020}of\u{0020}today.\n\u{3000}\u{3000}The\u{0020}person\u{0020}who\u{0020}once\u{0020}sheltered\u{0020}her\u{0020}from\u{0020}the\u{0020}wind\u{0020}and\u{0020}rain,\u{0020}allowing\u{0020}her\u{0020}to\u{0020}show\u{0020}her\u{0020}sharp\u{0020}edges\u{0020}as\u{0020}much\u{0020}as\u{0020}she\u{0020}wanted,\u{0020}is\u{0020}no\u{0020}longer\u{0020}here.\u{0020}Whether\u{0020}you\u{0020}call\u{0020}it\u{0020}growth\u{0020}or\u{0020}a\u{0020}disguise,\u{0020}as\u{0020}the\u{0020}administrator\u{0020}of\u{0020}New\u{0020}Cheston,\u{0020}the\u{0020}city\u{0020}entrusted\u{0020}with\u{0020}humanity's\u{0020}last\u{0020}hope,\u{0020}Charlissa\u{0020}had\u{0020}to\u{0020}learn\u{0020}how\u{0020}to\u{0020}become\u{0020}a\u{0020}mature\u{0020}adult.\n\u{3000}\u{3000}Whether\u{0020}in\u{0020}formal\u{0020}settings\u{0020}or\u{0020}in\u{0020}private,\u{0020}there\u{0020}is\u{0020}no\u{0020}longer\u{0020}any\u{0020}trace\u{0020}of\u{0020}the\u{0020}Charlissa\u{0020}she\u{0020}once\u{0020}was,\u{0020}as\u{0020}if\u{0020}that\u{0020}girl\u{0020}had\u{0020}never\u{0020}existed\u{0020}at\u{0020}all.\u{0020}If\u{0020}you\u{0020}told\u{0020}the\u{0020}residents\u{0020}of\u{0020}New\u{0020}Cheston\u{0020}that\u{0020}Charlissa\u{0020}de\u{0020}Roland\u{0020}was\u{0020}once\u{0020}a\u{0020}willful,\u{0020}spoiled\u{0020}young\u{0020}lady,\u{0020}you\u{0020}might\u{0020}be\u{0020}treated\u{0020}as\u{0020}a\u{0020}social\u{0020}destabilizer\u{0020}spreading\u{0020}malicious\u{0020}rumors.\n\u{3000}\u{3000}But\u{0020}would\u{0020}Charlissa\u{0020}de\u{0020}Roland\u{0020}feel\u{0020}happy\u{0020}about\u{0020}her\u{0020}own\u{0020}growth?\n\u{3000}\u{3000}No.\u{0020}Probably\u{0020}not.\n\u{3000}\u{3000}The\u{0020}price\u{0020}was\u{0020}completely\u{0020}unequal.\n\u{3000}\u{3000}No\u{0020}one\u{0020}would\u{0020}want\u{0020}this\u{0020}kind\u{0020}of\u{0020}growth.\u{0020}She\u{0020}would\u{0020}rather\u{0020}have\u{0020}remained\u{0020}a\u{0020}blond\u{0020}idiot\u{0020}for\u{0020}the\u{0020}rest\u{0020}of\u{0020}her\u{0020}life.", "0", "0", "0", "0", 14004, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[640402] = {640402, 500, "\u{3000}\u{3000}She\u{0020}was\u{0020}relied\u{0020}upon\u{0020}as\u{0020}humanity's\u{0020}last\u{0020}hope,\u{0020}its\u{0020}final\u{0020}trump\u{0020}card.\n\u{3000}\u{3000}She\u{0020}was\u{0020}trusted\u{0020}by\u{0020}everyone,\u{0020}depended\u{0020}on\u{0020}by\u{0020}everyone,\u{0020}and\u{0020}every\u{0020}action\u{0020}she\u{0020}took\u{0020}carried\u{0020}enormous\u{0020}influence.\n\u{3000}\u{3000}Charlissa's\u{0020}original\u{0020}dream\u{0020}had\u{0020}now\u{0020}come\u{0020}true.\n\u{3000}\u{3000}But\u{0020}joy,\u{0020}or\u{0020}feelings\u{0020}of\u{0020}happiness,\u{0020}could\u{0020}never\u{0020}possibly\u{0020}appear.\n\u{3000}\u{3000}The\u{0020}price\u{0020}of\u{0020}realizing\u{0020}her\u{0020}dream\u{0020}was\u{0020}the\u{0020}extinction\u{0020}of\u{0020}humanity.\u{0020}Although\u{0020}she\u{0020}was\u{0020}not\u{0020}the\u{0020}one\u{0020}who\u{0020}caused\u{0020}it,\u{0020}in\u{0020}terms\u{0020}of\u{0020}the\u{0020}result,\u{0020}that\u{0020}was\u{0020}the\u{0020}price\u{0020}she\u{0020}paid\u{0020}to\u{0020}become\u{0020}the\u{0020}person\u{0020}she\u{0020}had\u{0020}once\u{0020}dreamed\u{0020}of\u{0020}being.\n\u{3000}\u{3000}In\u{0020}the\u{0020}dead\u{0020}of\u{0020}night,\u{0020}Charlissa's\u{0020}thoughts\u{0020}would\u{0020}return\u{0020}to\u{0020}twenty\u{0020}years\u{0020}ago.\n\u{3000}\u{3000}Back\u{0020}to\u{0020}that\u{0020}time\u{0020}she\u{0020}could\u{0020}never\u{0020}return\u{0020}to,\u{0020}an\u{0020}era\u{0020}that\u{0020}could\u{0020}be\u{0020}called\u{0020}\"beautiful\"\u{0020}for\u{0020}both\u{0020}humanity\u{0020}and\u{0020}herself.\n\u{3000}\u{3000}Back\u{0020}then,\u{0020}she\u{0020}was\u{0020}childish,\u{0020}foolish,\u{0020}and\u{0020}ignorant.\u{0020}She\u{0020}thought\u{0020}she\u{0020}could\u{0020}change\u{0020}the\u{0020}world\u{0020}by\u{0020}herself,\u{0020}and\u{0020}believed\u{0020}the\u{0020}world\u{0020}could\u{0020}be\u{0020}reshaped\u{0020}however\u{0020}she\u{0020}wished.\n\u{3000}\u{3000}But\u{0020}back\u{0020}then,\u{0020}she\u{0020}was\u{0020}also\u{0020}happy.\u{0020}She\u{0020}had\u{0020}teammates\u{0020}she\u{0020}could\u{0020}rely\u{0020}on,\u{0020}and\u{0020}a\u{0020}Navigator\u{0020}who\u{0020}understood\u{0020}and\u{0020}believed\u{0020}in\u{0020}her.\n\u{3000}\u{3000}All\u{0020}of\u{0020}those\u{0020}foolish\u{0020}yet\u{0020}beautiful\u{0020}things\u{0020}were\u{0020}destroyed\u{0020}on\u{0020}that\u{0020}day\u{0020}twenty\u{0020}years\u{0020}ago.\n\u{3000}\u{3000}And\u{0020}on\u{0020}that\u{0020}day,\u{0020}she\u{0020}was\u{0020}not\u{0020}there.\n\u{3000}\u{3000}She\u{0020}missed\u{0020}the\u{0020}fall\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force.\u{0020}As\u{0020}the\u{0020}ace\u{0020}of\u{0020}the\u{0020}squad,\u{0020}she\u{0020}did\u{0020}not\u{0020}take\u{0020}part\u{0020}in\u{0020}the\u{0020}war\u{0020}that\u{0020}shaped\u{0020}human\u{0020}history.\u{0020}For\u{0020}some\u{0020}ridiculous\u{0020}reason,\u{0020}she\u{0020}failed\u{0020}to\u{0020}stay\u{0020}with\u{0020}her\u{0020}Navigator\u{0020}and\u{0020}her\u{0020}teammates\u{0020}until\u{0020}the\u{0020}very\u{0020}end.\n\u{3000}\u{3000}She\u{0020}knew\u{0020}that\u{0020}even\u{0020}if\u{0020}she\u{0020}had\u{0020}been\u{0020}there,\u{0020}she\u{0020}might\u{0020}not\u{0020}have\u{0020}been\u{0020}able\u{0020}to\u{0020}change\u{0020}the\u{0020}outcome.\u{0020}She\u{0020}would\u{0020}only\u{0020}have\u{0020}died\u{0020}like\u{0020}the\u{0020}others\u{0020}beneath\u{0020}Gluttony's\u{0020}hands--\u{0020}or\u{0020}perhaps\u{0020}it\u{0020}would\u{0020}be\u{0020}more\u{0020}accurate\u{0020}to\u{0020}say\u{0020}beneath\u{0020}its\u{0020}feet.\n\u{3000}\u{3000}But--\u{0020}what\u{0020}if?\n\u{3000}\u{3000}If\u{0020}she\u{0020}had\u{0020}been\u{0020}there,\u{0020}the\u{0020}outcome\u{0020}might\u{0020}not\u{0020}have\u{0020}changed.\u{0020}Humanity\u{0020}might\u{0020}still\u{0020}have\u{0020}lost\u{0020}that\u{0020}war\u{0020}and\u{0020}headed\u{0020}toward\u{0020}its\u{0020}end,\u{0020}but\u{0020}perhaps\u{0020}Navigator\u{0020}could\u{0020}have\u{0020}survived,\u{0020}and\u{0020}Julius\u{0020}and\u{0020}Franca\u{0020}might\u{0020}have\u{0020}survived\u{0020}too.\n\u{3000}\u{3000}If\u{0020}that\u{0020}had\u{0020}happened,\u{0020}Charlissa\u{0020}would\u{0020}not\u{0020}have\u{0020}been\u{0020}left\u{0020}alone\u{0020}in\u{0020}this\u{0020}world\u{0020}filled\u{0020}with\u{0020}despair\u{0020}and\u{0020}emptiness.\n\u{3000}\u{3000}But,\n\u{3000}\u{3000}There\u{0020}was\u{0020}no\u{0020}longer\u{0020}any\u{0020}\"what\u{0020}if.\"", "0", "0", "0", "0", 14004, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[640403] = {640403, 1000, "\u{3000}\u{3000}Before\u{0020}his\u{0020}death,\u{0020}Odyssey\u{0020}Chronos\u{0020}entrusted\u{0020}New\u{0020}Cheston\u{0020}to\u{0020}Charlissa,\u{0020}who\u{0020}had\u{0020}lost\u{0020}all\u{0020}sense\u{0020}of\u{0020}herself.\n\u{3000}\u{3000}At\u{0020}the\u{0020}time,\u{0020}Charlissa\u{0020}was\u{0020}still\u{0020}immersed\u{0020}in\u{0020}the\u{0020}grief\u{0020}of\u{0020}Navigator's\u{0020}death\u{0020}and\u{0020}the\u{0020}fall\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force.\u{0020}If\u{0020}she\u{0020}had\u{0020}been\u{0020}left\u{0020}alone,\u{0020}she\u{0020}would\u{0020}surely\u{0020}have\u{0020}sealed\u{0020}off\u{0020}her\u{0020}heart\u{0020}completely\u{0020}and\u{0020}suffered\u{0020}a\u{0020}spiritual\u{0020}death.\n\u{3000}\u{3000}That\u{0020}is\u{0020}why\u{0020}the\u{0020}heavy\u{0020}responsibility\u{0020}of\u{0020}New\u{0020}Cheston\u{0020}was\u{0020}a\u{0020}rope,\u{0020}a\u{0020}rope\u{0020}that\u{0020}ensured\u{0020}her\u{0020}humanity\u{0020}and\u{0020}soul\u{0020}would\u{0020}not\u{0020}fall\u{0020}into\u{0020}the\u{0020}abyss.\n\u{3000}\u{3000}Odyssey's\u{0020}method\u{0020}succeeded.\u{0020}Perhaps\u{0020}Charlissa\u{0020}still\u{0020}had\u{0020}not\u{0020}escaped\u{0020}the\u{0020}shadow\u{0020}of\u{0020}Navigator's\u{0020}death,\u{0020}but\u{0020}at\u{0020}the\u{0020}very\u{0020}least,\u{0020}from\u{0020}the\u{0020}moment\u{0020}she\u{0020}took\u{0020}on\u{0020}that\u{0020}responsibility,\u{0020}she\u{0020}had\u{0020}grown\u{0020}into\u{0020}a\u{0020}hero\u{0020}who\u{0020}could\u{0020}live\u{0020}for\u{0020}others,\u{0020}an\u{0020}ideal\u{0020}hero--\u{0020}a\u{0020}hero\u{0020}she\u{0020}never\u{0020}wanted\u{0020}to\u{0020}become.", "0", "0", "0", "0", 14004, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[640404] = {640404, 2000, "\u{3000}\u{3000}A\u{0020}brilliant\u{0020}shooting\u{0020}star\u{0020}is\u{0020}dazzling,\u{0020}but\u{0020}fleeting.\n\u{3000}\u{3000}A\u{0020}shooting\u{0020}star\u{0020}cannot\u{0020}become\u{0020}a\u{0020}light\u{0020}that\u{0020}shines\u{0020}upon\u{0020}others.\n\u{3000}\u{3000}It\u{0020}can\u{0020}only\u{0020}become\u{0020}a\u{0020}momentary\u{0020}beauty\u{0020}that\u{0020}vanishes\u{0020}in\u{0020}an\u{0020}instant.\n\u{3000}\u{3000}Charlissa\u{0020}de\u{0020}Roland\u{0020}can\u{0020}no\u{0020}longer\u{0020}be\u{0020}a\u{0020}shooting\u{0020}star,\n\u{3000}\u{3000}because\u{0020}she\u{0020}has\u{0020}a\u{0020}greater\u{0020}responsibility\u{0020}to\u{0020}bear.\n\u{3000}\u{3000}To\u{0020}become\u{0020}the\u{0020}North\u{0020}Star,\u{0020}forever\u{0020}shining\u{0020}and\u{0020}guiding\u{0020}others\u{0020}forward,\n\u{3000}\u{3000}may\u{0020}be\u{0020}the\u{0020}role\u{0020}she\u{0020}must\u{0020}play\u{0020}now.\n\u{3000}\u{3000}\"I\u{0020}will\u{0020}keep\u{0020}shining...\u{0020}until\u{0020}the\u{0020}end\u{0020}arrives.\"", "0", "0", "0", "0", 14004, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[640500] = {640500, 0, "[Name]\u{0020}Kyouka\u{0020}Uzen\n[Compatibility\u{0020}Rate]\u{0020}???\n[Height\u{0020}after\u{0020}Gigantification]\u{0020}37m\n[Squad]\u{0020}Demon\u{0020}Defense\u{0020}Force\n[Affiliation]\u{0020}Others\n[Birthday]\u{0020}September\u{0020}4", "0", "0", "0", "0", 14005, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】欧朵啦\n【生日】5月2日\n【幻化核心适格率】53％\n【巨大化身高】24m\n【部队】魂灭\n【隶属】九州总部\n【爱好】睡觉\u{3000}露露啦的背"},
[640501] = {640501, 100, "Kyouka\u{0020}Uzen,\u{0020}a\u{0020}woman\u{0020}of\u{0020}unshakable\u{0020}virtue\u{0020}and\u{0020}icy\u{0020}beauty.\n\nKyouka\u{0020}Uzen\u{0020}emerged\u{0020}with\u{0020}the\u{0020}arrival\u{0020}of\u{0020}an\u{0020}eerie\u{0020}haze,\u{0020}believed\u{0020}to\u{0020}be\u{0020}someone\u{0020}displaced\u{0020}from\u{0020}a\u{0020}parallel\u{0020}dimension.\u{0020}And\u{0020}a\u{0020}wielder\u{0020}of\u{0020}a\u{0020}supernatural\u{0020}power\u{0020}known\u{0020}as\u{0020}Peach\u{0020}Blessing.\n\nAccording\u{0020}to\u{0020}her,\u{0020}her\u{0020}powers\u{0020}remained\u{0020}fully\u{0020}intact\u{0020}after\u{0020}crossing\u{0020}into\u{0020}this\u{0020}world.\u{0020}With\u{0020}all\u{0020}analysis\u{0020}efforts\u{0020}ending\u{0020}in\u{0020}failure,\u{0020}her\u{0020}abilities\u{0020}defy\u{0020}observation,\u{0020}remaining\u{0020}unfathomable\u{0020}by\u{0020}modern\u{0020}science,\u{0020}a\u{0020}clear\u{0020}sign\u{0020}that\u{0020}the\u{0020}fundamental\u{0020}structure\u{0020}of\u{0020}her\u{0020}world\u{0020}differs\u{0020}from\u{0020}ours.\n\nThe\u{0020}Science\u{0020}Department\u{0020}has\u{0020}yet\u{0020}to\u{0020}uncover\u{0020}the\u{0020}cause\u{0020}of\u{0020}her\u{0020}displacement.\u{0020}The\u{0020}leading\u{0020}hypothesis\u{0020}suggests\u{0020}it\u{0020}was\u{0020}triggered\u{0020}by\u{0020}the\u{0020}Haze\u{0020}and\u{0020}the\u{0020}Gate.", "0", "0", "0", "0", 14005, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂灭”的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{3000}\u{3000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{3000}\u{3000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着“生活障碍症”这一奇怪病症。\n\u{3000}\u{3000}“不……无论怎么看，都只是纯粹的懒惰而已吧……”尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[640502] = {640502, 500, "Kyouka's\u{0020}homeland,\u{0020}Yamagata\u{0020}Prefecture,\u{0020}once\u{0020}suffered\u{0020}the\u{0020}Gassan\u{0020}Oisawa\u{0020}disaster,\u{0020}where\u{0020}Shuuki,\u{0020}monsters\u{0020}that\u{0020}inhabit\u{0020}Mato,\u{0020}killed\u{0020}everyone\u{0020}there,\u{0020}leaving\u{0020}her\u{0020}as\u{0020}the\u{0020}sole\u{0020}survivor\u{0020}of\u{0020}her\u{0020}village,\u{0020}a\u{0020}tragedy\u{0020}that\u{0020}altered\u{0020}the\u{0020}course\u{0020}of\u{0020}her\u{0020}life\u{0020}ever\u{0020}since.\u{0020}Following\u{0020}her\u{0020}training\u{0020}on\u{0020}Mt.\u{0020}Ryouzen,\u{0020}Kyouka\u{0020}has\u{0020}developed\u{0020}masterful\u{0020}skill\u{0020}in\u{0020}swordsmanship\u{0020}to\u{0020}the\u{0020}point\u{0020}of\u{0020}easily\u{0020}slicing\u{0020}multiple\u{0020}Shuuki\u{0020}into\u{0020}pieces\u{0020}without\u{0020}the\u{0020}help\u{0020}of\u{0020}her\u{0020}Peach\u{0020}Blessing.\u{0020}Her\u{0020}all-consuming\u{0020}hatred\u{0020}for\u{0020}the\u{0020}Shuuki\u{0020}became\u{0020}the\u{0020}driving\u{0020}force\u{0020}of\u{0020}her\u{0020}existence.\u{0020}Her\u{0020}ultimate\u{0020}goal\u{0020}is\u{0020}to\u{0020}ascend\u{0020}to\u{0020}the\u{0020}position\u{0020}of\u{0020}Supreme\u{0020}Commander\u{0020}and\u{0020}eradicate\u{0020}every\u{0020}last\u{0020}Shuuki\u{0020}from\u{0020}the\u{0020}world.\n\nThis\u{0020}exceptional,\u{0020}unique\u{0020}prowess\u{0020}earned\u{0020}her\u{0020}the\u{0020}leadership\u{0020}of\u{0020}the\u{0020}7th\u{0020}Squad.\u{0020}It\u{0020}also\u{0020}fueled\u{0020}a\u{0020}complex\u{0020}blend\u{0020}of\u{0020}admiration\u{0020}and\u{0020}rivalry\u{0020}among\u{0020}other\u{0020}commanders\u{0020}and\u{0020}squad\u{0020}members\u{0020}within\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force.", "0", "0", "0", "0", 14005, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{3000}\u{3000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{3000}\u{3000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{3000}\u{3000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了“明日之花”的鼓励性质奖章。\n\u{3000}\u{3000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{3000}\u{3000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{3000}\u{3000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队“魂灭”的雏形，也是从那个时候开始的。\n\u{3000}\u{3000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队“魂灭”的一员。"},
[640503] = {640503, 1000, "Even\u{0020}after\u{0020}arriving\u{0020}in\u{0020}AEGIS,\u{0020}Kyouka\u{0020}remains\u{0020}deeply\u{0020}burdened\u{0020}by\u{0020}her\u{0020}sense\u{0020}of\u{0020}duty.\u{0020}A\u{0020}keen\u{0020}observer\u{0020}would\u{0020}notice\u{0020}the\u{0020}lingering\u{0020}unease\u{0020}in\u{0020}her\u{0020}expression.\n\nHer\u{0020}7th\u{0020}Squad\u{0020}was\u{0020}tasked\u{0020}with\u{0020}guarding\u{0020}an\u{0020}area\u{0020}prone\u{0020}to\u{0020}heavy\u{0020}Shuuki\u{0020}activity.\u{0020}Their\u{0020}absence\u{0020}gnawed\u{0020}at\u{0020}her,\u{0020}stirring\u{0020}up\u{0020}the\u{0020}fear\u{0020}of\u{0020}humanity\u{0020}once\u{0020}again\u{0020}falling\u{0020}victim\u{0020}to\u{0020}an\u{0020}invasion.\n\nYet,\u{0020}she\u{0020}fought\u{0020}with\u{0020}precision\u{0020}in\u{0020}the\u{0020}new\u{0020}world.\u{0020}Unlike\u{0020}seasoned\u{0020}Drivers,\u{0020}who\u{0020}have\u{0020}grown\u{0020}desensitized\u{0020}to\u{0020}the\u{0020}destruction\u{0020}wrought\u{0020}by\u{0020}their\u{0020}giant-scale\u{0020}fights,\u{0020}Kyouka\u{0020}prioritized\u{0020}protecting\u{0020}buildings,\u{0020}minimizing\u{0020}collateral\u{0020}damage\u{0020}wherever\u{0020}possible.\u{0020}To\u{0020}put\u{0020}it\u{0020}in\u{0020}another\u{0020}way,\u{0020}she\u{0020}fights\u{0020}to\u{0020}ensure\u{0020}people\u{0020}will\u{0020}still\u{0020}have\u{0020}homes\u{0020}to\u{0020}return\u{0020}to,\u{0020}lives\u{0020}to\u{0020}rebuild,\u{0020}and\u{0020}dreams\u{0020}to\u{0020}pursue.", "0", "0", "0", "0", 14005, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{3000}\u{3000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{3000}\u{3000}“魂灭小队中存在着一个幽灵队员——”渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{3000}\u{3000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{3000}\u{3000}“——我可以去睡觉了吗？呜……”\n\u{3000}\u{3000}——是的，她只是懒而已。"},
[640504] = {640504, 2000, "Dialogue\u{0020}after\u{0020}one\u{0020}particular\u{0020}battle:\n\n\"The\u{0020}people\u{0020}of\u{0020}this\u{0020}world...\"\n\n\"Even\u{0020}they\u{0020}were\u{0020}invaded\u{0020}by\u{0020}the\u{0020}Sins,\"\n\n\"Even\u{0020}before\u{0020}the\u{0020}City\u{0020}Reconstruction\u{0020}Department\u{0020}could\u{0020}arrive,\"\n\n\"At\u{0020}sunrise\u{0020}the\u{0020}next\u{0020}day,\"\n\n\"They\u{0020}held\u{0020}each\u{0020}other\u{0020}up,\u{0020}all\u{0020}with\u{0020}an\u{0020}encouraging\u{0020}smile.\"\n\n\"Clapped\u{0020}hands\u{0020}in\u{0020}celebration\u{0020}after\u{0020}the\u{0020}invaders\u{0020}were\u{0020}driven\u{0020}back.\"\n\n\"They're\u{0020}incredibly\u{0020}strong.\"\n\nBathed\u{0020}in\u{0020}the\u{0020}light\u{0020}of\u{0020}the\u{0020}rising\u{0020}sun,\n\nThe\u{0020}girl\u{0020}smiled\u{0020}as\u{0020}she\u{0020}spoke.", "0", "0", "0", "0", 14005, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作战如她所推演的那样进行着，\n\u{3000}\u{3000}原罪的行动早在战争开始前就被她看穿，\n\u{3000}\u{3000}将破局的方法说出之后，\n\u{3000}\u{3000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“领航……”\n\u{3000}\u{3000}“喜欢……”\n\u{3000}\u{3000}“最喜欢了……”"},
[640600] = {640600, 0, "[Name]:\u{0020}Red\n[Date\u{0020}of\u{0020}Birth]:\u{0020}February\u{0020}13\n[Compatibility\u{0020}Rate]:\u{0020}100%\n[Height\u{0020}after\u{0020}Gigantification]:\u{0020}33m\n[Squad]:\u{0020}Cosmic\u{0020}Problem\u{0020}Children\n[Affiliation]:\u{0020}Heroine\u{0020}Universe\n[Likes]:\u{0020}Absorbing\u{0020}human\u{0020}emotions.", "0", "0", "0", "0", 14006, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[640601] = {640601, 100, "\u{3000}\u{3000}Arrogance\u{0020}is\u{0020}Red's\u{0020}sin.\n\u{3000}\u{3000}\u{0020}Her\u{0020}creator\u{0020}told\u{0020}her:\u{0020}\"You\u{0020}are\u{0020}the\u{0020}silicon-based\u{0020}lifeform\u{0020}I\u{0020}created,\u{0020}the\u{0020}closest\u{0020}thing\u{0020}to\u{0020}perfection\u{0020}in\u{0020}this\u{0020}world.\u{0020}You\u{0020}are\u{0020}humanity's\u{0020}natural\u{0020}enemy,\u{0020}the\u{0020}Sin\u{0020}among\u{0020}humans,\u{0020}yet\u{0020}also\u{0020}the\u{0020}one\u{0020}that\u{0020}is\u{0020}most\u{0020}closely\u{0020}related\u{0020}to\u{0020}them.\"\n\u{3000}\u{3000}\u{0020}[As\u{0020}humanity's\u{0020}natural\u{0020}enemy,\u{0020}I\u{0020}am\u{0020}inherently\u{0020}superior\u{0020}to\u{0020}humans.\u{0020}I\u{0020}have\u{0020}nothing\u{0020}to\u{0020}say\u{0020}to\u{0020}ants.]\u{0020}That's\u{0020}what\u{0020}Red\u{0020}thought.\u{0020}[But,\u{0020}I\u{0020}still\u{0020}need\u{0020}them\u{0020}for\u{0020}now.\u{0020}It's\u{0020}a\u{0020}fact\u{0020}that\u{0020}I'm\u{0020}living\u{0020}among\u{0020}them.]\n\u{3000}\u{3000}\u{0020}[In\u{0020}the\u{0020}human\u{0020}world...\u{0020}biological\u{0020}superiority\u{0020}alone\u{0020}isn't\u{0020}enough.\u{0020}Until\u{0020}I\u{0020}accomplish\u{0020}something\u{0020}that\u{0020}proves\u{0020}how\u{0020}special\u{0020}I\u{0020}am...\u{0020}I'll\u{0020}bide\u{0020}my\u{0020}time.]\n\u{3000}\u{3000}\u{0020}And\u{0020}so,\u{0020}the\u{0020}arrogant\u{0020}Red\u{0020}blended\u{0020}into\u{0020}the\u{0020}crowd.\n\u{3000}\u{3000}\u{0020}[Imitating\u{0020}humans?\u{0020}Easy.]\n\u{3000}\u{3000}\u{0020}She\u{0020}thought\u{0020}she\u{0020}was\u{0020}doing\u{0020}a\u{0020}perfect\u{0020}job\u{0020}pretending\u{0020}to\u{0020}be\u{0020}one\u{0020}of\u{0020}them.", "0", "0", "0", "0", 14006, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之于眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[640602] = {640602, 500, "\u{3000}\u{3000}[And\u{0020}then...\u{0020}the\u{0020}world\u{0020}ended,\u{0020}just\u{0020}like\u{0020}that,\u{0020}without\u{0020}me\u{0020}doing\u{0020}anything.]\n\u{3000}\u{3000}\u{0020}While\u{0020}Red\u{0020}was\u{0020}busy\u{0020}acting\u{0020}human\u{0020}and\u{0020}trying\u{0020}to\u{0020}win\u{0020}over\u{0020}Stephanie's\u{0020}son,\u{0020}the\u{0020}Navigator,\u{0020}everything\u{0020}fell\u{0020}apart.\n\u{3000}\u{3000}\"Why\u{0020}are\u{0020}you\u{0020}trying\u{0020}so\u{0020}hard\u{0020}to\u{0020}please\u{0020}me?\"\u{0020}he\u{0020}asked.\n\u{3000}\u{3000}\u{0020}\"Winning\u{0020}you\u{0020}over\u{0020}equals\u{0020}to\u{0020}defeating\u{0020}all\u{0020}the\u{0020}Drivers.\u{0020}That\u{0020}would've\u{0020}been\u{0020}one\u{0020}of\u{0020}the\u{0020}greatest\u{0020}achievements\u{0020}in\u{0020}my\u{0020}perfect\u{0020}life,\"\u{0020}Red\u{0020}explained.\u{0020}\"Besides,\u{0020}becoming\u{0020}your\u{0020}woman\u{0020}would've\u{0020}granted\u{0020}me\u{0020}endless\u{0020}resources\u{0020}and\u{0020}supreme\u{0020}status.\u{0020}Or\u{0020}at\u{0020}least,\u{0020}that's\u{0020}how\u{0020}it\u{0020}should've\u{0020}been...\"\n\u{3000}\u{3000}But\u{0020}then\u{0020}the\u{0020}world\u{0020}ended,\u{0020}with\u{0020}the\u{0020}Earth\u{0020}split\u{0020}in\u{0020}two,\u{0020}and\u{0020}she\u{0020}was\u{0020}flung\u{0020}into\u{0020}space.\n\u{3000}\u{3000}\u{0020}Drifting\u{0020}through\u{0020}the\u{0020}cosmos\u{0020}was\u{0020}so\u{0020}unbearably\u{0020}dull\u{0020}that\u{0020}she\u{0020}shut\u{0020}down\u{0020}her\u{0020}activity\u{0020}and\u{0020}consciousness\u{0020}to\u{0020}conserve\u{0020}energy.\u{0020}When\u{0020}she\u{0020}woke\u{0020}up,\u{0020}she\u{0020}was\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe.\n\u{3000}\u{3000}\u{0020}\"The\u{0020}Earth\u{0020}split\u{0020}open!?\"\n\u{3000}\u{3000}\u{0020}\"Cut\u{0020}open\u{0020}by\u{0020}a\u{0020}massive\u{0020}beam,\u{0020}then\u{0020}broke\u{0020}apart.\u{0020}I'm\u{0020}probably\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}survived,\"\u{0020}Red\u{0020}recalled.\u{0020}\"But\u{0020}what's\u{0020}even\u{0020}stranger\u{0020}is\u{0020}that\u{0020}ever\u{0020}since\u{0020}I\u{0020}arrived\u{0020}in\u{0020}this\u{0020}universe,\u{0020}the\u{0020}timer\u{0020}in\u{0020}my\u{0020}head\u{0020}has\u{0020}been\u{0020}moving\u{0020}incredibly\u{0020}slowly...\"\n\u{3000}\u{3000}\"Broken?\"\n\u{3000}\u{3000}\u{0020}\"The\u{0020}timer\u{0020}isn't\u{0020}malfunctioning...\u{0020}It's\u{0020}just...\u{0020}slowed\u{0020}down...\u{0020}but\u{0020}is\u{0020}still\u{0020}working.\u{0020}I\u{0020}can't\u{0020}really\u{0020}explain\u{0020}why,\"\u{0020}Red\u{0020}said\u{0020}with\u{0020}a\u{0020}troubled\u{0020}expression.\u{0020}\"It's\u{0020}hard\u{0020}to\u{0020}describe...\u{0020}Basically,\u{0020}time\u{0020}flows\u{0020}differently\u{0020}in\u{0020}this\u{0020}world.\"\n\u{3000}\u{3000}\u{0020}\"Spending\u{0020}a\u{0020}year\u{0020}in\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}might\u{0020}only\u{0020}be\u{0020}a\u{0020}day\u{0020}in\u{0020}the\u{0020}real\u{0020}world...\u{0020}Hikari\u{0020}told\u{0020}me\u{0020}that.\"\n\u{3000}\u{3000}\"The\u{0020}ratio\u{0020}isn't\u{0020}fixed;\u{0020}it's\u{0020}always\u{0020}changing.\u{0020}There\u{0020}are\u{0020}also\u{0020}times\u{0020}when\u{0020}a\u{0020}year\u{0020}passes\u{0020}in\u{0020}the\u{0020}real\u{0020}world,\u{0020}but\u{0020}only\u{0020}a\u{0020}day\u{0020}goes\u{0020}by\u{0020}here.\u{0020}If\u{0020}the\u{0020}Navigator\u{0020}stays\u{0020}here\u{0020}for\u{0020}50\u{0020}days,\u{0020}he\u{0020}might\u{0020}return\u{0020}as\u{0020}an\u{0020}old\u{0020}man.\"\n\u{3000}\u{3000}\u{0020}\"Then\u{0020}I\u{0020}should\u{0020}hurry\u{0020}back\u{0020}to\u{0020}the\u{0020}reality!\"", "0", "0", "0", "0", 14006, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為原罪全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明瞭歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[640603] = {640603, 1000, "\u{3000}\u{3000}The\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}filled\u{0020}with\u{0020}endless\u{0020}emotions,\u{0020}and\u{0020}most\u{0020}of\u{0020}them\u{0020}taste\u{0020}awful.\n\u{3000}\u{3000}\u{0020}In\u{0020}Red's\u{0020}own\u{0020}words:\u{0020}\"Everyone\u{0020}acts\u{0020}like\u{0020}a\u{0020}resentful\u{0020}widow.\u{0020}Only\u{0020}a\u{0020}few\u{0020}people\u{0020}have\u{0020}pure,\u{0020}beautiful\u{0020}emotions.\"\n\u{3000}\u{3000}\u{0020}That's\u{0020}why\u{0020}she\u{0020}chose\u{0020}to\u{0020}stick\u{0020}with\u{0020}Shiranui\u{0020}and\u{0020}the\u{0020}others:\u{0020}she\u{0020}gets\u{0020}to\u{0020}enjoy\u{0020}good\u{0020}meals.\n\u{3000}\u{3000}\u{0020}\"Tsukumo\u{0020}Tamaki's\u{0020}emotions\u{0020}taste\u{0020}like\u{0020}oranges...\u{0020}The\u{0020}President's\u{0020}usually\u{0020}taste\u{0020}like\u{0020}curry...\u{0020}As\u{0020}for\u{0020}Shiranui...\u{0020}her\u{0020}pudding\u{0020}is\u{0020}delicious,\"\u{0020}Red\u{0020}remarked\u{0020}after\u{0020}stealing\u{0020}a\u{0020}bite\u{0020}of\u{0020}Shiranui's\u{0020}pudding.\u{0020}\"I\u{0020}think\u{0020}most\u{0020}of\u{0020}the\u{0020}Heroines\u{0020}are...\u{0020}well,\u{0020}not\u{0020}quite\u{0020}sane?\u{0020}When\u{0020}I\u{0020}fight\u{0020}them,\u{0020}I'm\u{0020}forced\u{0020}to\u{0020}absorb\u{0020}all\u{0020}these\u{0020}disgusting\u{0020}emotions,\u{0020}including\u{0020}extreme\u{0020}hatred,\u{0020}bitter\u{0020}jealousy,\u{0020}utter\u{0020}despair.\u{0020}It's\u{0020}given\u{0020}me\u{0020}diarrhea.\"", "0", "0", "0", "0", 14006, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[640604] = {640604, 2000, "\u{3000}\u{3000}\"I'm\u{0020}going\u{0020}all\u{0020}out\u{0020}with\u{0020}your\u{0020}soul,\"\n\u{3000}\u{3000}\u{0020}Red\u{0020}declared\u{0020}one\u{0020}day.\n\u{3000}\u{3000}\u{0020}\"So\u{0020}show\u{0020}me\u{0020}that\u{0020}powerful\u{0020}thing\u{0020}of\u{0020}yours.\"\n\u{3000}\u{3000}\u{0020}It\u{0020}was\u{0020}unmistakably\u{0020}harassment.\n\u{3000}\u{3000}\u{0020}Or\u{0020}maybe\u{0020}you\u{0020}misunderstood\u{0020}her.\n\u{3000}\u{3000}\u{0020}It\u{0020}could\u{0020}be\u{0020}just\u{0020}a\u{0020}complaint,\u{0020}an\u{0020}accusation\u{0020}against\u{0020}you.\n\u{3000}\u{3000}\u{0020}\"The\u{0020}thing\u{0020}that\u{0020}turned\u{0020}me\u{0020}into\u{0020}a\u{0020}woman.\"\n\u{3000}\u{3000}\u{0020}Now\u{0020}there\u{0020}was\u{0020}solid\u{0020}proof.\u{0020}She\u{0020}was\u{0020}definitely\u{0020}harassing\u{0020}you.\n\u{3000}\u{3000}\u{0020}So...\u{0020}what\u{0020}will\u{0020}you\u{0020}do?", "0", "0", "0", "0", 14006, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}原罪的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
[640800] = {640800, 0, "[Name]:\u{0020}Ren\u{0020}Yamashiro\u{0020}\n[B-day]:\u{0020}February\u{0020}11\u{0020}\n[Core\u{0020}Compatibility]:\u{0020}?\u{0020}?\u{0020}?\u{0020}\n[Height]:\u{0020}36m\u{0020}\n[Squad]:\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}\n[Affiliation]:\u{0020}Others", "0", "0", "0", "0", 14008, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】欧朵啦\n【生日】5月2日\n【幻化核心适格率】53％\n【巨大化身高】24m\n【部队】魂灭\n【隶属】九州总部\n【爱好】睡觉\u{3000}露露啦的背"},
[640801] = {640801, 100, "\u{3000}\u{3000}The\u{0020}Supreme\u{0020}Commander\u{0020}who\u{0020}stands\u{0020}at\u{0020}the\u{0020}very\u{0020}top\u{0020}of\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force,\u{0020}she\u{0020}also\u{0020}serves\u{0020}as\u{0020}the\u{0020}Commander\u{0020}of\u{0020}the\u{0020}Tenth\u{0020}Squad,\u{0020}and\u{0020}her\u{0020}abilities\u{0020}and\u{0020}methods\u{0020}are\u{0020}trusted\u{0020}by\u{0020}the\u{0020}Force\u{0020}as\u{0020}a\u{0020}whole.\u{0020}\n\u{3000}\u{3000}Since\u{0020}birth,\u{0020}she\u{0020}has\u{0020}lived\u{0020}the\u{0020}life\u{0020}of\u{0020}a\u{0020}literal\u{0020}\"winner\".\u{0020}Whether\u{0020}in\u{0020}her\u{0020}school\u{0020}days\u{0020}or\u{0020}after\u{0020}joining\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force,\u{0020}becoming\u{0020}\"the\u{0020}one\u{0020}above\u{0020}everyone\u{0020}else\"\u{0020}has\u{0020}been\u{0020}second\u{0020}nature\u{0020}to\u{0020}her.\u{0020}\n\u{3000}\u{3000}She\u{0020}possesses\u{0020}overwhelming\u{0020}power,\u{0020}enough\u{0020}to\u{0020}annihilate\u{0020}a\u{0020}Great\u{0020}Sin\u{0020}on\u{0020}her\u{0020}own,\u{0020}and\u{0020}she\u{0020}rules\u{0020}the\u{0020}entire\u{0020}Demon\u{0020}Defense\u{0020}Force\u{0020}with\u{0020}cold,\u{0020}efficient\u{0020}methods.\u{0020}To\u{0020}her,\u{0020}protecting\u{0020}the\u{0020}nation\u{0020}is\u{0020}the\u{0020}first\u{0020}and\u{0020}absolute\u{0020}rule.\u{0020}Anything\u{0020}that\u{0020}stands\u{0020}in\u{0020}the\u{0020}way\u{0020}of\u{0020}that\u{0020}goal\u{0020}will\u{0020}be\u{0020}crushed\u{0020}without\u{0020}mercy.\u{0020}Toward\u{0020}those\u{0020}she\u{0020}acknowledges,\u{0020}or\u{0020}rather,\u{0020}those\u{0020}she\u{0020}has\u{0020}set\u{0020}her\u{0020}sights\u{0020}on\u{0020}as\u{0020}\"prey\",\u{0020}she\u{0020}shows\u{0020}an\u{0020}intense\u{0020}possessiveness\u{0020}and\u{0020}desire\u{0020}to\u{0020}dominate.\u{0020}\n\u{3000}\u{3000}Her\u{0020}Peach\u{0020}Blessing\u{0020}is\u{0020}called\u{0020}All-Encompassing\u{0020}Lord\u{0020}of\u{0020}the\u{0020}Cosmos.\u{0020}True\u{0020}to\u{0020}its\u{0020}name,\u{0020}it\u{0020}is\u{0020}an\u{0020}absolute\u{0020}power\u{0020}that\u{0020}governs\u{0020}all\u{0020}things\u{0020}and\u{0020}transcends\u{0020}common\u{0020}sense.", "0", "0", "0", "0", 14008, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂灭”的成员之一，天才少女，传言她一天二十四小时中有二十个小时在睡觉。\n\u{3000}\u{3000}相传，她有着接近艾吉斯首席科学家史蒂芬妮博士的智力与学识。因为她大部分时间都在睡觉，这一传闻无法得到证实。\n\u{3000}\u{3000}她经常与魂灭小队的队长露露啦一同出现，人们见到她的时候，她的身边必然存在着露露啦的陪伴。根据知情人员的透漏，即便是从苍穹学院毕业的现在，她依然无法独立生活，存在着“生活障碍症”这一奇怪病症。\n\u{3000}\u{3000}“不……无论怎么看，都只是纯粹的懒惰而已吧……”尝试着将真相公之于众的人，被露露啦与金库啦联手人道毁灭（？）了。"},
[640802] = {640802, 500, "\u{3000}\u{3000}A\u{0020}world\u{0020}has\u{0020}a\u{0020}capacity.\u{0020}\n\u{3000}\u{3000}The\u{0020}stronger\u{0020}someone\u{0020}is,\u{0020}the\u{0020}less\u{0020}the\u{0020}world\u{0020}will\u{0020}allow\u{0020}them\u{0020}to\u{0020}exist.\u{0020}And\u{0020}for\u{0020}a\u{0020}world\u{0020}as\u{0020}fragile\u{0020}as\u{0020}a\u{0020}newborn,\u{0020}one\u{0020}that\u{0020}has\u{0020}not\u{0020}even\u{0020}fully\u{0020}taken\u{0020}shape\u{0020}yet,\u{0020}\"the\u{0020}strong\"\u{0020}are\u{0020}even\u{0020}more\u{0020}likely\u{0020}to\u{0020}be\u{0020}cast\u{0020}out.\u{0020}\n\u{3000}\u{3000}If\u{0020}a\u{0020}powerhouse\u{0020}who\u{0020}could\u{0020}easily\u{0020}overturn\u{0020}or\u{0020}destroy\u{0020}a\u{0020}world\u{0020}were\u{0020}dragged\u{0020}into\u{0020}this\u{0020}incident,\u{0020}then\u{0020}whether\u{0020}or\u{0020}not\u{0020}there\u{0020}was\u{0020}truly\u{0020}a\u{0020}mastermind\u{0020}behind\u{0020}it,\u{0020}that\u{0020}newborn\u{0020}world\u{0020}would\u{0020}surely\u{0020}collapse.\u{0020}\n\u{3000}\u{3000}That\u{0020}is\u{0020}why\u{0020}Ren\u{0020}Yamashiro\u{0020}was\u{0020}removed\u{0020}from\u{0020}the\u{0020}board\u{0020}from\u{0020}the\u{0020}very\u{0020}beginning.\u{0020}\n\u{3000}\u{3000}Put\u{0020}up\u{0020}on\u{0020}a\u{0020}shelf.\u{0020}\n\u{3000}\u{3000}Isolated.\u{0020}\n\u{3000}\u{3000}Ignored.\u{0020}\n\u{3000}\u{3000}And\u{0020}yet,\u{0020}if\u{0020}anyone\u{0020}could\u{0020}tear\u{0020}apart\u{0020}the\u{0020}world\u{0020}itself\u{0020}in\u{0020}the\u{0020}most\u{0020}unreasonable\u{0020}way\u{0020}possible,\u{0020}scrawling\u{0020}graffiti\u{0020}across\u{0020}the\u{0020}very\u{0020}structure\u{0020}of\u{0020}the\u{0020}story,\u{0020}then\u{0020}without\u{0020}question,\u{0020}only\u{0020}Ren\u{0020}Yamashiro\u{0020}could\u{0020}do\u{0020}it.\u{0020}\n\u{3000}\u{3000}When\u{0020}the\u{0020}Synesthete\u{0020}Navigator's\u{0020}world\u{0020}came\u{0020}into\u{0020}contact\u{0020}with\u{0020}the\u{0020}Demon\u{0020}Defense\u{0020}Force's\u{0020}world,\u{0020}Ren\u{0020}Yamashiro\u{0020}should\u{0020}have\u{0020}been\u{0020}pulled\u{0020}into\u{0020}the\u{0020}anomaly\u{0020}like\u{0020}the\u{0020}other\u{0020}commanders.\u{0020}Instead,\u{0020}the\u{0020}instigator\u{0020}deemed\u{0020}her\u{0020}an\u{0020}\"uncontrollable\"\u{0020}risk\u{0020}factor\u{0020}and\u{0020}singled\u{0020}her\u{0020}out.\u{0020}\n\u{3000}\u{3000}What\u{0020}the\u{0020}instigator\u{0020}failed\u{0020}to\u{0020}anticipate\u{0020}was\u{0020}that\u{0020}she\u{0020}was\u{0020}not\u{0020}the\u{0020}only\u{0020}being\u{0020}capable\u{0020}of\u{0020}interfering\u{0020}with\u{0020}\"the\u{0020}world\".\u{0020}\n\u{3000}\u{3000}Although\u{0020}the\u{0020}Great\u{0020}Sin\u{0020}who\u{0020}called\u{0020}herself\u{0020}\"Lust\"\u{0020}does\u{0020}not\u{0020}interfere\u{0020}with\u{0020}the\u{0020}world's\u{0020}operation\u{0020}in\u{0020}most\u{0020}cases,\u{0020}this\u{0020}time\u{0020}was\u{0020}an\u{0020}exception.\u{0020}\n\u{3000}\u{3000}Just\u{0020}as\u{0020}Ren\u{0020}Yamashiro\u{0020}was\u{0020}treated\u{0020}as\u{0020}an\u{0020}exception\u{0020}and\u{0020}handled\u{0020}separately,\u{0020}this\u{0020}incident\u{0020}was\u{0020}also\u{0020}deemed\u{0020}an\u{0020}anomaly\u{0020}that\u{0020}Lust\u{0020}had\u{0020}to\u{0020}treat\u{0020}as\u{0020}a\u{0020}special\u{0020}case.\u{0020}And\u{0020}so\u{0020}Ren\u{0020}Yamashiro\u{0020}returned\u{0020}to\u{0020}the\u{0020}story\u{0020}once\u{0020}more.\u{0020}\n\u{3000}\u{3000}And\u{0020}then,\u{0020}she\u{0020}shattered\u{0020}their\u{0020}sweet\u{0020}dream.", "0", "0", "0", "0", 14008, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作为原罪全面入侵后的诞生的新生代，欧朵啦在很小的时候就展露了自己的才华。那些即便对于成年人而言也称得上棘手的课题，欧朵啦依靠着书籍上的知识便能独自一人完成。\n\u{3000}\u{3000}天赋异禀的欧朵啦很快被艾吉斯首席科学家史蒂芬妮注意到。艾吉斯用测试证明了欧朵啦的才华并非媒体炒作的成果，而是货真价实的才能。\n\u{3000}\u{3000}为了不让这份才能被埋没，为了让这份才能得到更充分的发挥空间，艾吉斯让欧朵啦进入了培育人才的苍穹学院。\n\u{3000}\u{3000}艾吉斯的这一决断或许是正确的。欧朵啦对于学术知识与战术理论的吸收速度远超人们的想象，在她刚进入苍穹学院的三个月后，她对于战场的判断与战术的实际应用已经超出了学生范畴。在一次与毕业生的模拟战中，她取得了压倒性的优势，被授予了“明日之花”的鼓励性质奖章。\n\u{3000}\u{3000}遗憾的是，在对于驾驶员最重要的幻化核心适格率上，欧朵啦的数值并不理想，这使她注定无法成为一线的战士。\n\u{3000}\u{3000}另外，艾吉斯拔苗助长的行为也让欧朵啦暴露出了另一个弱点——她无法独立生活。她不懂得该如何独自进食，甚至连穿衣服也不会。她的日常起居皆是由她当时的室友——露露啦照顾的。\n\u{3000}\u{3000}然而正是因为她的这个弱点，使得她与露露啦结下了深厚的羁绊。未来的精英小队“魂灭”的雏形，也是从那个时候开始的。\n\u{3000}\u{3000}露露啦毕业后，考虑到欧朵啦的情况，艾吉斯破例让欧朵啦提前离开学院，成为露露啦所属小队“魂灭”的一员。"},
[640803] = {640803, 1000, "\u{3000}\u{3000}Supreme\u{0020}Commander\u{0020}Ren\u{0020}Yamashiro\u{0020}is\u{0020}someone\u{0020}you\u{0020}cannot\u{0020}get\u{0020}along\u{0020}with\u{0020}in\u{0020}any\u{0020}normal\u{0020}way,\u{0020}someone\u{0020}who\u{0020}makes\u{0020}you\u{0020}afraid.\u{0020}At\u{0020}least,\u{0020}that\u{0020}was\u{0020}the\u{0020}thought\u{0020}that\u{0020}rose\u{0020}in\u{0020}Angelica's\u{0020}mind\u{0020}the\u{0020}first\u{0020}time\u{0020}she\u{0020}met\u{0020}her.\u{0020}\n\u{3000}\u{3000}Overwhelming\u{0020}strength,\u{0020}the\u{0020}way\u{0020}she\u{0020}enforces\u{0020}her\u{0020}will\u{0020}through\u{0020}action,\u{0020}and\u{0020}the\u{0020}way\u{0020}she\u{0020}destroys\u{0020}anyone\u{0020}who\u{0020}stands\u{0020}in\u{0020}the\u{0020}way\u{0020}of\u{0020}that\u{0020}will\u{0020}as\u{0020}if\u{0020}they\u{0020}were\u{0020}nothing\u{0020}but\u{0020}obstacles.\u{0020}Any\u{0020}ordinary\u{0020}person\u{0020}would\u{0020}be\u{0020}intimidated\u{0020}by\u{0020}Ren\u{0020}Yamashiro's\u{0020}presence.\u{0020}\n\u{3000}\u{3000}But\u{0020}Angelica\u{0020}noticed\u{0020}something.\u{0020}\n\u{3000}\u{3000}As\u{0020}unbelievable\u{0020}as\u{0020}it\u{0020}sounds...\u{0020}Ren\u{0020}Yamashiro\u{0020}might\u{0020}actually\u{0020}be\u{0020}a\u{0020}very\u{0020}gentle\u{0020}person.\u{0020}\n\u{3000}\u{3000}It\u{0020}is\u{0020}just\u{0020}that\u{0020}her\u{0020}gentleness\u{0020}is\u{0020}too\u{0020}powerful.\u{0020}\n\u{3000}\u{3000}A\u{0020}powerful\u{0020}gentleness\u{0020}that\u{0020}takes\u{0020}on\u{0020}everyone's\u{0020}burdens,\u{0020}everyone's\u{0020}weakness,\u{0020}everyone's\u{0020}helplessness,\u{0020}as\u{0020}if\u{0020}she\u{0020}would\u{0020}carry\u{0020}it\u{0020}all\u{0020}alone.\u{0020}\n\u{3000}\u{3000}A\u{0020}gentleness\u{0020}that\u{0020}lives\u{0020}alongside\u{0020}the\u{0020}duty\u{0020}of\u{0020}a\u{0020}Supreme\u{0020}Commander.\u{0020}\n\u{3000}\u{3000}Angelica\u{0020}does\u{0020}not\u{0020}know\u{0020}whether\u{0020}that\u{0020}immense\u{0020}power\u{0020}shaped\u{0020}Ren\u{0020}Yamashiro's\u{0020}sense\u{0020}of\u{0020}responsibility\u{0020}and\u{0020}gentleness,\u{0020}or\u{0020}whether\u{0020}it\u{0020}was\u{0020}because\u{0020}she\u{0020}was\u{0020}that\u{0020}kind\u{0020}of\u{0020}person\u{0020}that\u{0020}she\u{0020}was\u{0020}granted\u{0020}such\u{0020}power.\u{0020}\n\u{3000}\u{3000}Perhaps\u{0020}it\u{0020}is\u{0020}also\u{0020}that\u{0020}strength\u{0020}that\u{0020}makes\u{0020}her\u{0020}look,\u{0020}somehow,\u{0020}lonely.\u{0020}\n\u{3000}\u{3000}But\u{0020}Angelica\u{0020}thinks...\u{0020}maybe\u{0020}the\u{0020}Supreme\u{0020}Commander\u{0020}is\u{0020}hoping\u{0020}for\u{0020}something\u{0020}too.\u{0020}\n\u{3000}\u{3000}Hoping\u{0020}that\u{0020}everyone\u{0020}will\u{0020}become\u{0020}strong\u{0020}enough\u{0020}to\u{0020}stand\u{0020}and\u{0020}fight\u{0020}at\u{0020}her\u{0020}side.\u{0020}\n\u{3000}\u{3000}Whether\u{0020}that\u{0020}is\u{0020}true\u{0020}or\u{0020}not,\u{0020}Angelica\u{0020}does\u{0020}not\u{0020}know.", "0", "0", "0", "0", 14008, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}欧朵啦深居简出的生活习性在她进入艾吉斯九州总部之后加重了。\n\u{3000}\u{3000}也许是环境的变化让她感到不安，在搬入九州总部后，她外出的次数变得更少了。因此尽管九州总部的人知道魂灭小队存在着露露啦、金库啦之外的第三人，但却鲜有人见过她的真身。\n\u{3000}\u{3000}“魂灭小队中存在着一个幽灵队员——”渐渐有这样的奇怪传说在九州总部间流传开来了。经过露露啦的说教，欧朵啦才增加了自己外出的次数。\n\u{3000}\u{3000}这下子真相终于大白，她深居简出的理由并不是怕生，而是更加纯粹的理由——\n\u{3000}\u{3000}“——我可以去睡觉了吗？呜……”\n\u{3000}\u{3000}——是的，她只是懒而已。"},
[640804] = {640804, 2000, "\u{3000}\u{3000}As\u{0020}Supreme\u{0020}Commander,\u{0020}she\u{0020}does\u{0020}not\u{0020}allow\u{0020}herself\u{0020}to\u{0020}fail.\u{0020}\n\u{3000}\u{3000}Whether\u{0020}it\u{0020}is\u{0020}a\u{0020}crisis\u{0020}of\u{0020}the\u{0020}world\u{0020}or\u{0020}a\u{0020}crisis\u{0020}of\u{0020}the\u{0020}nation,\u{0020}there\u{0020}may\u{0020}be\u{0020}a\u{0020}difference\u{0020}in\u{0020}scale\u{0020}for\u{0020}other\u{0020}people,\u{0020}\n\u{3000}\u{3000}but\u{0020}to\u{0020}her\u{0020}it\u{0020}is\u{0020}all\u{0020}the\u{0020}same.\u{0020}\n\u{3000}\u{3000}It\u{0020}must\u{0020}be\u{0020}resolved.\u{0020}It\u{0020}must\u{0020}end\u{0020}in\u{0020}victory.\u{0020}\n\u{3000}\u{3000}If\u{0020}even\u{0020}she,\u{0020}the\u{0020}\"strongest\",\u{0020}cannot\u{0020}deal\u{0020}with\u{0020}a\u{0020}crisis\u{0020}like\u{0020}this...\u{0020}\n\u{3000}\u{3000}...Then\u{0020}who\u{0020}else\u{0020}will\u{0020}step\u{0020}forward?\u{0020}\n\u{3000}\u{3000}Pray\u{0020}to\u{0020}a\u{0020}god?\u{0020}\n\u{3000}\u{3000}Ren\u{0020}Yamashiro\u{0020}would\u{0020}never\u{0020}do\u{0020}something\u{0020}that\u{0020}foolish.", "0", "0", "0", "0", 14008, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作战如她所推演的那样进行着，\n\u{3000}\u{3000}原罪的行动早在战争开始前就被她看穿，\n\u{3000}\u{3000}将破局的方法说出之后，\n\u{3000}\u{3000}她躺在山丘间，静静地睡着，说着孩童般的梦话，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“领航……”\n\u{3000}\u{3000}“喜欢……”\n\u{3000}\u{3000}“最喜欢了……”"},
[640900] = {640900, 0, "[Name]\u{0020}Tverda\n[B-day]\u{0020}December\u{0020}26\n[Core\u{0020}Compatibility\u{0020}Rate]\u{0020}88%\n[Height]\u{0020}38m\n[Squad]\u{0020}Cannonbore\n[Affiliation]\u{0020}Katya\u{0020}Branch\n[Hobbies]\u{0020}Watching\u{0020}movies,\u{0020}mechanical\u{0020}engineering", "0", "0", "0", "0", 14009, "0", "0", "0", "0", 1, 1, "0", "0", "【姓名】歐朵啦\n【生日】5月2日\n【幻化核心適格率】53％\n【巨大化身高】24m\n【部隊】魂滅\n【隸屬】九州總部\n【愛好】睡覺\u{3000}露露啦的背"},
[640901] = {640901, 100, "\u{3000}\u{3000}The\u{0020}Heroine\u{0020}Universe\u{0020}is\u{0020}a\u{0020}place\u{0020}where\u{0020}heroines\u{0020}gather.\n\u{3000}\u{3000}After\u{0020}falling\u{0020}from\u{0020}the\u{0020}sky\u{0020}in\u{0020}an\u{0020}utterly\u{0020}traditional\u{0020}fashion,\u{0020}Tverda\u{0020}took\u{0020}only\u{0020}about\u{0020}half\u{0020}an\u{0020}hour\u{0020}to\u{0020}accept\u{0020}this\u{0020}mind-boggling\u{0020}situation,\u{0020}then\u{0020}devoted\u{0020}the\u{0020}brainpower\u{0020}she\u{0020}had\u{0020}saved\u{0020}to\u{0020}figuring\u{0020}out\u{0020}how\u{0020}best\u{0020}to\u{0020}tease\u{0020}the\u{0020}Navigator\u{0020}about\u{0020}it.\n\u{3000}\u{3000}As\u{0020}described\u{0020}above,\u{0020}she\u{0020}simply\u{0020}discards\u{0020}anything\u{0020}she\u{0020}would\u{0020}rather\u{0020}not\u{0020}examine\u{0020}too\u{0020}closely\u{0020}and\u{0020}can\u{0020}never\u{0020}stay\u{0020}serious\u{0020}about\u{0020}matters\u{0020}unrelated\u{0020}to\u{0020}work.\u{0020}She\u{0020}is\u{0020}exactly\u{0020}the\u{0020}Tverda\u{0020}you\u{0020}know.\u{0020}At\u{0020}most,\u{0020}the\u{0020}unexpected\u{0020}seaside\u{0020}vacation\u{0020}has\u{0020}left\u{0020}her\u{0020}a\u{0020}little\u{0020}more\u{0020}enthusiastic\u{0020}than\u{0020}usual\u{0020}in\u{0020}certain\u{0020}respects.\n\u{3000}\u{3000}--Until\u{0020}the\u{0020}lucid\u{0020}dream\u{0020}that\u{0020}set\u{0020}every\u{0020}alarm\u{0020}bell\u{0020}in\u{0020}her\u{0020}intuition\u{0020}blaring\u{0020}arrived,\u{0020}she\u{0020}would\u{0020}rather\u{0020}have\u{0020}believed\u{0020}that\u{0020}this\u{0020}was\u{0020}merely\u{0020}a\u{0020}somewhat\u{0020}bizarre\u{0020}seaside\u{0020}holiday.", "0", "0", "0", "0", 14009, "0", "0", "0", "0", 1, 2, "0", "0", "\u{3000}\u{3000}“魂滅”的成員之一，天才少女，傳言她一天二十四小時中有二十個小時在睡覺。\n\u{3000}\u{3000}相傳，她有著接近艾吉斯首席科學家史蒂芬妮博士的智力與學識。因為她大部分時間都在睡覺，這一傳聞無法得到證實。\n\u{3000}\u{3000}她經常與魂滅小隊的隊長露露啦一同出現，人們見到她的時候，她的身邊必然存在著露露啦的陪伴。根據知情人員的透漏，即便是從蒼穹學院畢業的現在，她依然無法獨立生活，存在著“生活障礙症”這一奇怪病症。\n\u{3000}\u{3000}“不……無論怎麼看，都只是純粹的懶惰而已吧……”嘗試著將真相公之於眾的人，被露露啦與金庫啦聯手人道毀滅（？）了。"},
[640902] = {640902, 500, "\u{3000}\u{3000}Even\u{0020}within\u{0020}AEGIS\u{0020}as\u{0020}a\u{0020}whole,\u{0020}very\u{0020}few\u{0020}people\u{0020}truly\u{0020}know\u{0020}Tverda.\n\u{3000}\u{3000}After\u{0020}all,\u{0020}she\u{0020}is\u{0020}clearly\u{0020}not\u{0020}the\u{0020}sociable\u{0020}type.\u{0020}Even\u{0020}the\u{0020}small\u{0020}handful\u{0020}of\u{0020}people\u{0020}who\u{0020}interact\u{0020}with\u{0020}her\u{0020}as\u{0020}something\u{0020}other\u{0020}than\u{0020}mere\u{0020}\"colleagues\"\u{0020}rarely\u{0020}find\u{0020}an\u{0020}opportunity\u{0020}to\u{0020}broach\u{0020}such\u{0020}topics\u{0020}with\u{0020}her.\u{0020}The\u{0020}reason\u{0020}is\u{0020}obvious:\u{0020}although\u{0020}Tverda\u{0020}herself\u{0020}is\u{0020}hardly\u{0020}secretive\u{0020}about\u{0020}having\u{0020}once\u{0020}been\u{0020}a\u{0020}child\u{0020}soldier,\u{0020}when\u{0020}that\u{0020}background\u{0020}is\u{0020}considered\u{0020}alongside\u{0020}Katya's\u{0020}social\u{0020}history,\u{0020}the\u{0020}result\u{0020}is\u{0020}rarely\u{0020}the\u{0020}kind\u{0020}of\u{0020}lighthearted\u{0020}subject\u{0020}one\u{0020}would\u{0020}bring\u{0020}up\u{0020}with\u{0020}a\u{0020}friend.\n\u{3000}\u{3000}In\u{0020}the\u{0020}end,\u{0020}those\u{0020}who\u{0020}become\u{0020}interested\u{0020}in\u{0020}Tverda\u{0020}because\u{0020}of\u{0020}her\u{0020}mannerisms,\u{0020}yet\u{0020}have\u{0020}no\u{0020}idea\u{0020}how\u{0020}to\u{0020}learn\u{0020}more\u{0020}about\u{0020}her,\u{0020}often\u{0020}turn\u{0020}to\u{0020}Efgenia\u{0020}and\u{0020}the\u{0020}Navigator\u{0020}for\u{0020}help.\u{0020}The\u{0020}former\u{0020}is\u{0020}widely\u{0020}regarded\u{0020}as\u{0020}the\u{0020}most\u{0020}approachable\u{0020}person\u{0020}in\u{0020}the\u{0020}entire\u{0020}Katya\u{0020}Branch\u{0020}and\u{0020}is,\u{0020}in\u{0020}legal\u{0020}terms,\u{0020}something\u{0020}akin\u{0020}to\u{0020}the\u{0020}person\u{0020}in\u{0020}question's\u{0020}adoptive\u{0020}mother.\u{0020}As\u{0020}for\u{0020}the\u{0020}latter,\u{0020}while\u{0020}the\u{0020}exact\u{0020}circumstances\u{0020}remain\u{0020}shrouded\u{0020}in\u{0020}mystery,\u{0020}the\u{0020}Navigator\u{0020}is\u{0020}indeed\u{0020}the\u{0020}only\u{0020}person\u{0020}who\u{0020}has\u{0020}repeatedly\u{0020}caused\u{0020}Tverda's\u{0020}\"professional\u{0020}facade\"\u{0020}to\u{0020}crumble\u{0020}in\u{0020}public.\n\u{3000}\u{3000}However,\u{0020}when\u{0020}these\u{0020}people\u{0020}act\u{0020}on\u{0020}their\u{0020}curiosity,\u{0020}fully\u{0020}expecting\u{0020}to\u{0020}hear\u{0020}a\u{0020}tale\u{0020}as\u{0020}cold\u{0020}and\u{0020}biting\u{0020}as\u{0020}the\u{0020}winter\u{0020}north\u{0020}wind,\u{0020}the\u{0020}result\u{0020}usually\u{0020}defies\u{0020}their\u{0020}expectations.\u{0020}The\u{0020}Tverda\u{0020}described\u{0020}by\u{0020}the\u{0020}Navigator\u{0020}and\u{0020}Efgenia\u{0020}seems\u{0020}to\u{0020}be\u{0020}nothing\u{0020}more\u{0020}than\u{0020}a\u{0020}reliable\u{0020}young\u{0020}woman\u{0020}with\u{0020}a\u{0020}few\u{0020}rather\u{0020}obvious\u{0020}personality\u{0020}flaws,\u{0020}an\u{0020}otherwise\u{0020}perfectly\u{0020}ordinary\u{0020}peer\u{0020}whose\u{0020}strengths,\u{0020}weaknesses,\u{0020}and\u{0020}hobbies\u{0020}are\u{0020}all\u{0020}quite\u{0020}unremarkable.\n\u{3000}\u{3000}She\u{0020}is\u{0020}a\u{0020}little\u{0020}simpler\u{0020}than\u{0020}the\u{0020}background\u{0020}that\u{0020}could\u{0020}fill\u{0020}countless\u{0020}pages,\u{0020}yet\u{0020}a\u{0020}little\u{0020}more\u{0020}complicated\u{0020}than\u{0020}the\u{0020}rather\u{0020}obvious\u{0020}facade\u{0020}she\u{0020}wears\u{0020}at\u{0020}work.\u{0020}If\u{0020}there\u{0020}is\u{0020}one\u{0020}piece\u{0020}of\u{0020}advice\u{0020}worth\u{0020}giving,\u{0020}it\u{0020}is\u{0020}this:\u{0020}do\u{0020}not\u{0020}treat\u{0020}her\u{0020}like\u{0020}someone\u{0020}who\u{0020}may\u{0020}be\u{0020}standing\u{0020}in\u{0020}the\u{0020}same\u{0020}room\u{0020}as\u{0020}you,\u{0020}yet\u{0020}is\u{0020}actually\u{0020}a\u{0020}world\u{0020}away.\u{0020}That\u{0020}is\u{0020}the\u{0020}first\u{0020}step\u{0020}toward\u{0020}keeping\u{0020}her\u{0020}from\u{0020}deciding\u{0020}that\u{0020}dealing\u{0020}with\u{0020}you\u{0020}is\u{0020}too\u{0020}much\u{0020}trouble.\n\u{3000}\u{3000}Oh,\u{0020}and\u{0020}one\u{0020}more\u{0020}thing:\u{0020}never\u{0020}touch\u{0020}the\u{0020}dog\u{0020}tags\u{0020}she\u{0020}always\u{0020}keeps\u{0020}with\u{0020}her.", "0", "0", "0", "0", 14009, "0", "0", "0", "0", 1, 3, "0", "0", "\u{3000}\u{3000}作為異獸全面入侵後的誕生的新生代，歐朵啦在很小的時候就展露了自己的才華。那些即便對於成年人而言也稱得上棘手的課題，歐朵啦依靠著書籍上的知識便能獨自一人完成。\n\u{3000}\u{3000}天賦異稟的歐朵啦很快被艾吉斯首席科學家史蒂芬妮注意到。艾吉斯用測試證明了歐朵啦的才華並非媒體炒作的成果，而是貨真價實的才能。\n\u{3000}\u{3000}為了不讓這份才能被埋沒，為了讓這份才能得到更充分的發揮空間，艾吉斯讓歐朵啦進入了培育人才的蒼穹學院。\n\u{3000}\u{3000}艾吉斯的這一決斷或許是正確的。歐朵啦對於學術知識與戰術理論的吸收速度遠超人們的想像，在她剛進入蒼穹學院的三個月後，她對於戰場的判斷與戰術的實際應用已經超出了學生範疇。在一次與畢業生的模擬戰中，她取得了壓倒性的優勢，被授予了“明日之花”的鼓勵性質獎章。\n\u{3000}\u{3000}遺憾的是，在對於駕駛員最重要的幻化核心適格率上，歐朵啦的數值並不理想，這使她註定無法成為一線的戰士。\n\u{3000}\u{3000}另外，艾吉斯揠苗助長的行為也讓歐朵啦暴露出了另一個弱點——她無法獨立生活。她不懂得該如何獨自進食，甚至連穿衣服也不會。她的日常起居皆是由她當時的室友——露露啦照顧的。\n\u{3000}\u{3000}然而正是因為她的這個弱點，使得她與露露啦結下了深厚的羈絆。未來的精英小隊“魂滅”的雛形，也是從那個時候開始的。\n\u{3000}\u{3000}露露啦畢業後，考慮到歐朵啦的情況，艾吉斯破例讓歐朵啦提前離開學院，成為露露啦所屬小隊“魂滅”的一員。"},
[640903] = {640903, 1000, "\u{3000}\u{3000}Although\u{0020}she\u{0020}was\u{0020}always\u{0020}talking\u{0020}about\u{0020}\"vacation,\"\u{0020}Tverda\u{0020}showed\u{0020}no\u{0020}attachment\u{0020}to\u{0020}the\u{0020}Heroine\u{0020}Universe\u{0020}whatsoever.\u{0020}As\u{0020}soon\u{0020}as\u{0020}everything\u{0020}was\u{0020}ready\u{0020}on\u{0020}the\u{0020}Association's\u{0020}end,\u{0020}she\u{0020}promptly\u{0020}collected\u{0020}herself\u{0020}and\u{0020}prepared\u{0020}for\u{0020}the\u{0020}journey\u{0020}home.\n\u{3000}\u{3000}A\u{0020}vacation\u{0020}itself\u{0020}was\u{0020}naturally\u{0020}something\u{0020}she\u{0020}could\u{0020}never\u{0020}have\u{0020}too\u{0020}much\u{0020}of,\u{0020}but\u{0020}the\u{0020}reason\u{0020}behind\u{0020}receiving\u{0020}it\u{0020}also\u{0020}had\u{0020}a\u{0020}considerable\u{0020}impact\u{0020}on\u{0020}how\u{0020}she\u{0020}felt\u{0020}about\u{0020}it--that\u{0020}was\u{0020}more\u{0020}or\u{0020}less\u{0020}her\u{0020}view.\n\u{3000}\u{3000}From\u{0020}what\u{0020}I\u{0020}learned\u{0020}afterward,\u{0020}the\u{0020}specific\u{0020}reason\u{0020}she\u{0020}had\u{0020}crossed\u{0020}over\u{0020}seemed\u{0020}to\u{0020}be\u{0020}that\u{0020}the\u{0020}universe\u{0020}had\u{0020}forcibly\u{0020}recruited\u{0020}her\u{0020}as\u{0020}some\u{0020}kind\u{0020}of\u{0020}dumping\u{0020}ground\u{0020}for\u{0020}redundant\u{0020}information--certainly\u{0020}not\u{0020}a\u{0020}pleasant\u{0020}reason.\n\u{3000}\u{3000}\"Just\u{0020}thinking\u{0020}about\u{0020}it\u{0020}makes\u{0020}that\u{0020}stupid\u{0020}face\u{0020}of\u{0020}my\u{0020}other\u{0020}self\u{0020}pop\u{0020}into\u{0020}my\u{0020}head.\u{0020}It's\u{0020}the\u{0020}worst.\"\n\u{3000}\u{3000}\"Do\u{0020}you\u{0020}really\u{0020}hate\u{0020}your\u{0020}other\u{0020}self\u{0020}that\u{0020}much?\"\n\u{3000}\u{3000}\"Is\u{0020}there\u{0020}any\u{0020}reason\u{0020}I\u{0020}should\u{0020}like\u{0020}her?\"\n\u{3000}\u{3000}As\u{0020}she\u{0020}said\u{0020}this,\u{0020}Tverda\u{0020}let\u{0020}out\u{0020}a\u{0020}rather\u{0020}deliberate\u{0020}sigh--from\u{0020}what\u{0020}I\u{0020}understood\u{0020}of\u{0020}her,\u{0020}whenever\u{0020}she\u{0020}made\u{0020}a\u{0020}certain\u{0020}attitude\u{0020}especially\u{0020}obvious,\u{0020}it\u{0020}was\u{0020}usually\u{0020}because\u{0020}she\u{0020}\"wanted\u{0020}others\u{0020}to\u{0020}take\u{0020}her\u{0020}at\u{0020}face\u{0020}value.\"\n\u{3000}\u{3000}Besides,\u{0020}although\u{0020}we\u{0020}had\u{0020}always\u{0020}shared\u{0020}an\u{0020}unspoken\u{0020}agreement\u{0020}not\u{0020}to\u{0020}pry\u{0020}into\u{0020}unpleasant\u{0020}subjects,\u{0020}the\u{0020}tone\u{0020}she\u{0020}had\u{0020}used\u{0020}on\u{0020}that\u{0020}snowfield\u{0020}when\u{0020}treating\u{0020}me\u{0020}as\u{0020}an\u{0020}outlet\u{0020}for\u{0020}her\u{0020}emotions\u{0020}certainly\u{0020}did\u{0020}not\u{0020}sound\u{0020}like\u{0020}someone\u{0020}who\u{0020}had\u{0020}simply\u{0020}\"taken\u{0020}revenge\u{0020}on\u{0020}a\u{0020}person\u{0020}she\u{0020}could\u{0020}never\u{0020}forgive.\"\n\u{3000}\u{3000}\"...What\u{0020}is\u{0020}it?\u{0020}Why\u{0020}do\u{0020}you\u{0020}suddenly\u{0020}look\u{0020}so\u{0020}thoughtful?\"\n\u{3000}\u{3000}\"...\"\n\u{3000}\u{3000}\"There\u{0020}aren't\u{0020}any\u{0020}heroines\u{0020}here\u{0020}anymore\u{0020}who\u{0020}can\u{0020}spin\u{0020}an\u{0020}entire\u{0020}romance\u{0020}novel\u{0020}out\u{0020}of\u{0020}a\u{0020}glimpse\u{0020}of\u{0020}your\u{0020}profile,\u{0020}so\u{0020}could\u{0020}you\u{0020}just\u{0020}say\u{0020}what\u{0020}you\u{0020}mean?\"\n\u{3000}\u{3000}\"As\u{0020}I\u{0020}thought...\"\n\u{3000}\u{3000}\"?\"\n\u{3000}\u{3000}\"...As\u{0020}I\u{0020}thought,\u{0020}you\u{0020}don't\u{0020}hate\u{0020}her\u{0020}quite\u{0020}as\u{0020}much\u{0020}as\u{0020}you\u{0020}claim,\u{0020}do\u{0020}you?\"\n\u{3000}\u{3000}\"...I\u{0020}take\u{0020}back\u{0020}what\u{0020}I\u{0020}said.\u{0020}Shut\u{0020}up\u{0020}right\u{0020}now.\"", "0", "0", "0", "0", 14009, "0", "0", "0", "0", 1, 4, "0", "0", "\u{3000}\u{3000}歐朵啦深居簡出的生活習性在她進入艾吉斯九州總部之後加重了。\n\u{3000}\u{3000}也許是環境的變化讓她感到不安，在搬入九州總部後，她外出的次數變得更少了。因此儘管九州總部的人知道魂滅小隊存在著露露啦、金庫啦之外的第三人，但卻鮮有人見過她的真身。\n\u{3000}\u{3000}“魂滅小隊中存在著一個幽靈隊員——”漸漸有這樣的奇怪傳說在九州總部間流傳開來了。經過露露啦的說教，歐朵啦才增加了自己外出的次數。\n\u{3000}\u{3000}這下子真相終於大白，她深居簡出的理由並不是怕生，而是更加純粹的理由——\n\u{3000}\u{3000}“——我可以去睡覺了嗎？嗚……”\n\u{3000}\u{3000}——是的，她只是懶而已。"},
[640904] = {640904, 2000, "\u{3000}\u{3000}Noble\u{0020}character\u{0020}has\u{0020}nothing\u{0020}to\u{0020}do\u{0020}with\u{0020}me.\n\u{3000}\u{3000}From\u{0020}the\u{0020}moment\u{0020}I\u{0020}realized\u{0020}I\u{0020}might\u{0020}remain\u{0020}forever\u{0020}trapped\u{0020}behind\u{0020}the\u{0020}blizzards\u{0020}and\u{0020}high\u{0020}walls\u{0020}before\u{0020}me,\u{0020}that\u{0020}place\u{0020}was\u{0020}destined\u{0020}never\u{0020}to\u{0020}nurture\u{0020}anything\u{0020}worthy\u{0020}of\u{0020}praise.\u{0020}In\u{0020}a\u{0020}place\u{0020}where\u{0020}it\u{0020}took\u{0020}everything\u{0020}just\u{0020}to\u{0020}remain\u{0020}yourself,\u{0020}the\u{0020}most\u{0020}it\u{0020}could\u{0020}foster\u{0020}were\u{0020}thoughts\u{0020}like\u{0020}\"survive\"\u{0020}and\u{0020}\"escape,\"\u{0020}impulses\u{0020}even\u{0020}an\u{0020}animal\u{0020}could\u{0020}possess.\n\u{3000}\u{3000}I\u{0020}know\u{0020}that\u{0020}compared\u{0020}to\u{0020}those\u{0020}who\u{0020}were\u{0020}buried\u{0020}forever\u{0020}in\u{0020}the\u{0020}courtyard,\u{0020}I\u{0020}was\u{0020}one\u{0020}of\u{0020}the\u{0020}lucky\u{0020}ones.\u{0020}But\u{0020}recently,\u{0020}someone\u{0020}went\u{0020}and\u{0020}used\u{0020}their\u{0020}entire\u{0020}life\u{0020}to\u{0020}prove\u{0020}to\u{0020}me\u{0020}that\u{0020}even\u{0020}among\u{0020}those\u{0020}who\u{0020}escaped,\u{0020}I\u{0020}was\u{0020}truly\u{0020}fortunate.\n\u{3000}\u{3000}...\n\u{3000}\u{3000}Consider\u{0020}it\u{0020}my\u{0020}attempt\u{0020}to\u{0020}find\u{0020}even\u{0020}the\u{0020}slightest\u{0020}positive\u{0020}meaning\u{0020}in\u{0020}where\u{0020}I\u{0020}came\u{0020}from.\n\u{3000}\u{3000}If\u{0020}that\u{0020}seemingly\u{0020}meaningless\u{0020}thing,\u{0020}the\u{0020}one\u{0020}thing\u{0020}that\u{0020}sets\u{0020}me\u{0020}apart\u{0020}from\u{0020}a\u{0020}beast,\u{0020}has\u{0020}gradually\u{0020}crystallized\u{0020}into\u{0020}the\u{0020}good\u{0020}fortune\u{0020}that\u{0020}brought\u{0020}me\u{0020}this\u{0020}far,\u{0020}then\u{0020}I\u{0020}have\u{0020}a\u{0020}duty\u{0020}to\u{0020}preserve\u{0020}it.\n\u{3000}\u{3000}For\u{0020}those\u{0020}who\u{0020}were\u{0020}buried,\u{0020}and\u{0020}for\u{0020}all\u{0020}the\u{0020}less\u{0020}fortunate\u{0020}versions\u{0020}of\u{0020}me.\n\u{3000}\u{3000}Ask\u{0020}not\u{0020}what\u{0020}lies\u{0020}ahead.\u{0020}Never\u{0020}forget.", "0", "0", "0", "0", 14009, "0", "0", "0", "0", 1, 5, "0", "0", "\u{3000}\u{3000}作戰如她所推演的那樣進行著，\n\u{3000}\u{3000}異獸的行動早在戰爭開始前就被她看穿，\n\u{3000}\u{3000}將破局的方法說出之後，\n\u{3000}\u{3000}她躺在山丘間，靜靜地睡著，說著孩童般的夢話，\n\u{3000}\u{3000}“呼……呼……呼……”\n\u{3000}\u{3000}“露露啦……”\n\u{3000}\u{3000}“領航……”\n\u{3000}\u{3000}“喜歡……”\n\u{3000}\u{3000}“最喜歡了……”"},
